sh_m_difbbox:
    call shm_difbbox
    retf
sh_m_pfin:
    call shm_pfin
    clc                             ; CF=0 is "the module ran" - the stub
    retf                            ; reads CF=1 as "there is no module"
sh_m_ptext:                         ; 81.62, the same contract
    call shm_ptext
    clc
    retf
sh_m_ptrans:
    call shm_ptrans
    clc
    retf
sh_m_pinfo:
    call shm_pinfo
    clc
    retf
sh_m_idapply:                       ; 81.94: MACRO.OVL's ways in. The two
    call sh_idlg_apply              ; applies say nothing in CF, and CLC is
    clc                             ; the module-presence answer as above;
    retf                            ; shm_mname and sh_read_rc ANSWER in CF,
sh_m_bdapply:                       ; so theirs is passed through untouched
    call sh_bdlg_apply
    clc
    retf
sh_m_tor1c1:
    call sh_formula_to_r1c1
    clc
