    clc
    retf
sh_m_fclose:
    call sh_df_savefld                 ; a background click is not a cancel
    call sh_df_close                   ; here: the field being edited is
    clc                                ; committed, the way Close itself does
    retf
sh_m_mfind:                         ; macro plan wave 0: AX = the id or 0xFF
    call shm_mfind
    clc
    retf

; =============================================================================
; MACRO.OVL (81.94): the macro language's own module, a second segment after
; CHART.OVL in the same assembly. Its offset 0 is ITS dispatcher, the way
; .modc's is CHART.OVL's, and the eight bytes after the jump are the mark
; tools/os88ovl.py cuts the file at - so the boundary is IN the image and not
; in a second place to keep in step.
; =============================================================================
section .modm vstart=0 align=1 follows=.modc
sh_modm0:
    jmp short sh_modm_disp
    db 'SHMACRO2'                     ; os88ovl.py's cut mark: exactly once
sh_modm_stamp:                        ; ...and sh_m2need's build stamp, after
    dw shm_m2end, os88_image_end      ; the mark so the cut is unaffected
sh_modm_disp:
    cmp bp, SHM2_N
    jae .bad
    shl bp, 1
    jmp word [cs:bp+sh_m2verb]
.bad:
    stc
    retf
sh_m2verb:
    dw sh_m2_pmacro, sh_m2_mresume, sh_m2_dpaint, sh_m2_dkey, sh_m2_dclick
    dw sh_m2_dfire
sh_m2verb_end:
    times ((sh_m2verb_end - sh_m2verb) / 2 - SHM2_N) db 0   ; sh_mverb's own
    times (SHM2_N - (sh_m2verb_end - sh_m2verb) / 2) db 0   ; assertion, here
sh_m2_pmacro:
    call shm_pmacro
    clc
    retf
sh_m2_mresume:
    call shm_mresume
    clc
    retf
sh_m2_dpaint:
    call shm_dbpaint
    clc
    retf
sh_m2_dkey:
    call shm_dbkey
    clc
    retf
sh_m2_dclick:
    call shm_dbclick
    clc
    retf
sh_m2_dfire:
    call shm_dbfire
    clc
    retf
section SH_MODSEC
sh_m_justify:                       ; 81.81
    call sh_docmd_justify
    clc                             ; ...and CF=0 says the MODULE ran, which
    retf                            ; is not the same as the command having
                                    ; done anything - Justify's own refusals
                                    ; speak through [sh_msg]
sh_m_sortcol:                       ; 81.71.6
    call sh_docmd_sortcol
    clc
    retf
sh_m_lopen:
    call sh_ldlg_open
    clc
    retf
sh_m_lpaint:
    call sh_ldlg_paint
    clc
    retf
sh_m_lclick:
    call sh_ldlg_onclick
    clc
    retf
sh_m_series:                        ; 81.72
    call shm_series
    clc
    retf
sh_m_fdopen:                        ; 81.74.2
    call sh_fdlg_open
    clc
    retf
sh_m_fdpaint:
    call sh_fdlg_paint
    clc
    retf
sh_m_fdclick:
    call sh_fdlg_onclick
    clc
    retf
sh_m_fdclose:
    call sh_fdlg_close
    clc
    retf
sh_m_idopen:
    call sh_idlg_open
    clc
    retf
sh_m_idpaint:
    call sh_idlg_paint
    clc
    retf
sh_m_idkey:
    call sh_idlg_onkey
    clc
    retf
sh_m_idclick:
    call sh_idlg_onclick
    clc
    retf
sh_m_idclose:
    call sh_idlg_close
    clc
    retf
sh_m_find:
    call sh_docmd_find
    clc
    retf
; -----------------------------------------------------------------------------
; sh_docmd_find - Formula > Find... (in CHART.OVL since 81.111, reached
; from MACRO.OVL as SHM_FIND): move the selection to the next cell whose
; DISPLAYED TEXT contains what was typed.
;
; Displayed text, not stored value, and that is the useful definition rather
; than the easy one: it finds 3.5 in a cell holding 3.5, "Total" in a label,
; and - because a formula cell displays its result - 1003.5 in a cell holding
; =A2+A3. A search over stored bytes would have matched none of those the way
; a user expects, since a double's eight bytes look nothing like what is on
; screen.
;
; Case-insensitive, and it wraps: the walk starts at the cell AFTER the
; selection and comes back round to it, so Find repeated from the same box
; steps through every match rather than sticking on the first.
; -----------------------------------------------------------------------------
sh_docmd_find:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov si, sh_idlg_buf
    SHOUT sh_upcase_at
    cmp byte [sh_idlg_buf], 0
    je .none
    ; the scan order is the CELL ARRAY's, which is sorted by row then column -
    ; so "next" here means next in reading order, which is what it looks like
    mov cx, [sh_ncells]
    or cx, cx                         ; not jcxz: it is short-only and .none
    jz .none                          ; is past its reach from here
    xor bx, bx                        ; bx = index into the array
.each:
    push cx
    mov ax, bx
    mov cx, SH_C_SZ
    mul cx
    mov si, ax
    pop cx
    mov es, [sh_cellseg]
    mov ax, [es:si]
    push bx
    SHOUT sh_unpackrow                 ; ax = row, bx = sheet
    mov dx, bx
    pop bx
    cmp dx, [sh_cursheet]
    jne .next
    mov [sh_find_row], ax
    mov ax, [es:si+2]
    mov [sh_find_col], ax
    ; skip everything at or before the current selection on this pass
    mov ax, [sh_find_row]
    cmp ax, [sh_selrow]
    jb .next
    ja .test
    mov ax, [sh_find_col]
    cmp ax, [sh_selcol]
    jbe .next
.test:
    call sh_find_text                 ; builds the cell's displayed text
    call sh_find_match
    jc .found
.next:
    inc bx
    cmp bx, cx
    jb .each
    ; nothing after the selection: go round again from the top, so a repeated
    ; Find wraps rather than stopping
    xor bx, bx
.each2:
    push cx
    mov ax, bx
    mov cx, SH_C_SZ
    mul cx
    mov si, ax
    pop cx
    mov es, [sh_cellseg]
    mov ax, [es:si]
    push bx
    SHOUT sh_unpackrow
    mov dx, bx
    pop bx
    cmp dx, [sh_cursheet]
    jne .next2
    mov [sh_find_row], ax
    mov ax, [es:si+2]
    mov [sh_find_col], ax
    call sh_find_text
    call sh_find_match
    jc .found
.next2:
    inc bx
    cmp bx, cx
    jb .each2
.none:
    mov word [sh_msg], sh_s_id_nofnd
    jmp .out
.found:
    mov ax, [sh_find_col]
    mov bx, [sh_find_row]
    mov si, [sh_ownwin]
    SHOUT sh_select
    SHOUT sh_scrollto
    mov word [sh_msg], 0
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_find_text - the cell at (sh_find_col, sh_find_row) as UPPERCASE text in
; sh_find_buf. Goes through sh_getcell2 so a formula cell yields its RESULT,
; which is what the grid shows and therefore what a search should match.
sh_find_text:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov byte [sh_find_buf], 0
    mov ax, [sh_find_col]
    mov bx, [sh_find_row]
    SHOUT sh_getcell2
    jnc .out
    cmp byte [sh_curtype], SH_T_TEXT
    je .istext
    cmp byte [sh_curtype], SH_T_BOOL  ; a LOGICAL is found by the name it
    jne .fnum                         ; shows (81.51)
    mov ax, dx
    SHOUT sh_boolname
    mov si, sh_numbuf
    mov di, sh_find_buf
    SHOUT sh_strcpy
    jmp .up
.fnum:
    SHOUT sh_acc_load_a                ; a number: the same ten significant
    mov di, sh_find_buf               ; digits the cell itself shows
    mov ax, 10
    SHOUT fp_ftoa
    jmp .up
.istext:
    push es
    mov es, [sh_txtseg]
    mov si, [sh_curtoff]
    mov di, sh_find_buf
    mov cx, SH_EDITMAX
.tc:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .tcd
    inc si
    inc di
    dec cx
    jnz .tc
    mov byte [di], 0
.tcd:
    pop es
.up:
    mov si, sh_find_buf
    SHOUT sh_upcase_at
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_find_match - CF=1 if sh_idlg_buf occurs anywhere in sh_find_buf
sh_find_match:
    push ax
    push bx
    push si
    push di
    mov si, sh_find_buf
.at:
    cmp byte [si], 0
    je .no
    mov bx, si
    mov di, sh_idlg_buf
.cmp:
    mov al, [di]
    or al, al
    jz .yes
    cmp al, [bx]
    jne .adv
    inc bx
    inc di
    jmp .cmp
.adv:
    inc si
    jmp .at
.no:
    ; an empty needle would have matched at the first character above, so
    ; reaching here means it really is absent
    pop di
    pop si
    pop bx
    pop ax
    clc
    ret
.yes:
    pop di
    pop si
    pop bx
    pop ax
    stc
    ret

sh_m_dfbtn:
    dec al                             ; the record counts from 1, dobtn
    cbw                                ; from 0
    call sh_df_dobtn
    clc
    retf
sh_m_ndbtn:
    call sh_ndlg_onbtn
    clc
    retf
sh_m_ldbtn:
    call sh_ldlg_onbtn
    clc
    retf
sh_m_idbtn:
    call sh_idlg_onbtn
    clc
    retf
sh_m_bdbtn:
    call sh_bdlg_onbtn
    clc
    retf
sh_m_fdbtn:                         ; 81.111
    call sh_fdlg_onbtn
    clc
