    clc
    retf
sh_m_fdapply:
    call sh_fdlg_apply
    clc
    retf
section .text

; -----------------------------------------------------------------------------
; The three resident stubs. Every existing caller still says `call sh_doread`
; and never learns the reader moved - which is the point of doing it this way
; round rather than editing the call sites (82.16.9).
; -----------------------------------------------------------------------------
sh_doread:
    push bp
    mov bp, SHM_READ
    call ch_ovcall
    pop bp
    cmp word [sh_msg], sh_m_loaded     ; a document just read is CLEAN - every
    jne .kept                          ; cell it made marked it dirty on the
    mov byte [sh_modified], 0          ; way in (81.118)
.kept:
    jmp sh_undo_drop                   ; another document now (81.57). It reads
                                       ; no flag, so the compare above is free
sh_dowrite:
    call sh_recalc_all                  ; every formula CURRENT before any
    push bp                             ; writer reads one - see below
    mov bp, SHM_WRITE
    call ch_ovcall
    pop bp
    ret

; -----------------------------------------------------------------------------
; sh_tbl_run_all - 81.114.8's recalculation, resident side. A table's result
; cells hold STORED VALUES, so `inc word [sh_pass]` - this app's whole
; recalculation - does nothing for them; they have to be computed again.
;
; CF IS NOT READ, and must not be: a machine with no room for CHART.OVL is a
; machine that never opened the Data > Table dialog either, so there are no
; tables for this to miss (82.16.3 is the same argument for the chart).
; -----------------------------------------------------------------------------
sh_tbl_run_all:
    cmp word [sh_ntbl], 0               ; the overwhelmingly common case, and
    je .out                             ; it costs a compare rather than a
    push bp                             ; far call into the module
    mov bp, SHM_TBLRUN
    call ch_ovcall
    pop bp
.out:
    ret

; sh_tbl_rc_adj - 81.114.9's, and sh_tbl_run_all's shape exactly: a table's
; stored rectangle follows an Insert/Delete Row/Column. sh_rowcol_op is
; resident and this work is the module's, which is the right side of the line
; - it is a menu operation, not a hot path.
sh_tbl_rc_adj:
    cmp word [sh_ntbl], 0
    je .out
    push bp
    mov bp, SHM_TBLADJ
    call ch_ovcall
    pop bp
.out:
    ret

; -----------------------------------------------------------------------------
; sh_recalc_all - evaluate every formula cell on every sheet, as its own sheet
; (SPEC.md 81.48).
; Preserves all registers.
;
; EVALUATION IS LAZY: sh_eval_cell runs when a cell is READ, and a repaint only
; reads what is on the glass. The SYLK and BIFF writers read a cell's value
; with sh_cellval_to_acc_si, the STORED double, and never ask for a fresh one -
; so a formula scrolled out of sight since it was loaded, or since a cell it
; names changed, was written with whatever it last held. After a load that is
; the zero sh_setformula leaves, and BIFF's reader keeps the result and not the
; tokens, so a Save in Normal format turned an off-screen formula into a
; permanent 0. DIF and the text formats read through sh_getcell2, which
; evaluates, which is why it looked like a SYLK/BIFF quirk rather than a hole.
; Found by tests/sheetfin.py: the first four formulas - the ones on screen -
; came back right and all twenty-two below them came back 0.
;
; NOTHING HERE DECIDES WHAT IS STALE. sh_eval_cell's pass stamp already does,
; and does the right thing in both modes: automatic advances sh_pass on every
; repaint, so anything not recomputed since is stale and recomputes; manual
; does not, so only a cell never computed at all (stamped 0xFFFF) runs - which
; keeps manual mode meaning what it says.
;
; THE SHEET IS IMPERSONATED per record, sh_rowcol_op's idiom: sh_findcell packs
; [sh_cursheet] into every reference, so a Sheet 2 formula evaluated as Sheet 1
; would read Sheet 1's cells.
; -----------------------------------------------------------------------------
sh_recalc_all:
    push ax
    push cx
    push dx
    push di
    push es
    push word [sh_cursheet]
    xor di, di
    mov cx, [sh_ncells]
    jcxz .done
.l:
    mov es, [sh_cellseg]                ; re-read each time: the claim is
    test byte [es:di+SH_C_FLAGS], 1     ; movable (66.2) and a word is what
    jz .next                            ; sh_reloc keeps right, not ES
    mov ax, [es:di+SH_C_ROW]
    rol ax, 1                           ; the sheet is the row word's top two
    rol ax, 1                           ; bits
    and ax, 3
    mov [sh_cursheet], ax
    push cx                             ; the parser under sh_eval_cell is
    call sh_eval_cell                   ; free with CX and DX; DI and ES it
    pop cx                              ; keeps
.next:
    add di, SH_C_SZ
    loop .l
.done:
    pop word [sh_cursheet]
    pop es
    pop di
    pop dx
    pop cx
    pop ax
    ret
sh_difbbox:
    push bp
    mov bp, SHM_DIFBB
    call ch_ovcall
    pop bp
    ret

; sh_pfin - the financial family's door (82.16.10). The body is shm_pfin in
; CHART.OVL; its contract is unchanged - AX the id, SI just past '(', the answer
; in sh_acc, SI past ')', AX 0, BX CX DX DI kept.
;
; THE ONE STUB HERE THAT HAS TO ANSWER A REFUSAL ITSELF. The other three hand
; ch_ovcall's CF to callers that already test it; this one's caller is the
; formula parser, which expects the arguments consumed and a value in sh_acc,
; and would otherwise carry on parsing from inside the argument list. So no
; module answers exactly what the family's own refusals do: zero, #VALUE!
; (47), and the arguments stepped over.
; 81.62: THE TEXT, TRANSCENDENTAL AND INFORMATION FAMILIES came through the
; same door, each with its own verb: the functions a sheet uses least, 2.8 KB
; the package needed more than the module did. SUM and its folds, IF, the
; special forms, the lookups, the dates and NOW stay resident.
sh_pfin:
    push bp
    mov bp, SHM_FIN
    jmp short sh_pdoor
sh_ptext:
    push bp
    mov bp, SHM_TEXT
    jmp short sh_pdoor
sh_ptrans:
    push bp
    mov bp, SHM_TRANS
    jmp short sh_pdoor
sh_pinfo:
    push bp
    mov bp, SHM_INFO
    jmp short sh_pdoor
sh_pmacro:                          ; 81.63: the macro functions - MACRO.OVL's
    push bp                         ; since 81.94, through its own door
    mov bp, SHM2_PMACRO
    call sh_m2call
    pop bp
    jc sh_pdoor.nomod
    ret
sh_pdatabase:                       ; 81.65: DAVERAGE...DVARP
    push bp
    mov bp, SHM_DATABASE
    jmp short sh_pdoor
sh_pcell:                           ; 81.66: CELL
    push bp
    mov bp, SHM_CELL
    jmp short sh_pdoor
sh_pmatrix:                         ; 81.67: MDETERM...GROWTH
    push bp
    mov bp, SHM_MATRIX
sh_pdoor:
    call ch_ovcall
    pop bp
    jc .nomod
    ret
.nomod:
    push bx
    push cx
    push dx
    push di
    call fp_azero
    call sh_acc_store
    call sh_skipargs
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    pop di
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_m2call - far-call MACRO.OVL (81.94). in: BP = its verb (SHM2_*), the rest
; as the verb documents. out: as the verb; CF=1 the module is not there.
; sh_m2need - make sure it is: CHART.OVL first, because the macro module calls
; into it (CHOUT), then MACRO.OVL read into its own claim, from the folder
; SHEET was launched from - ch_ovneed's recipe, and its banked folder words.
; Taken at the entry proc with the other claims (SPEC.md 50.3); this lazy path
; runs only if that one failed, and a failure is remembered, not retried
; -----------------------------------------------------------------------------
sh_m2call:
    call sh_m2need
    jc .no
    call far [sh_m2far]
.no:
    ret
sh_m2need:
    cmp word [sh_m2far + 2], 0
    jne .ok
    cmp byte [sh_m2fail], 0
    jne .no
    call ch_ovneed
    jc .fail
    push ax
    push bx
    push cx
    push dx
    push si
    push es
    call OSAPI_FILE_HERE                ; where the USER is, to be put back
    mov [ch_ovwas], dx
    mov [ch_ovwdr], bl
    mov dx, [ch_ovdir]                  ; ...and off to where we were launched
    mov bl, [ch_ovdrv]
    call OSAPI_FILE_GOTO
    mov ax, SH_M2KB
    call OSAPI_MEM_CLAIM
    jc .nomem
    mov es, dx
    xor bx, bx
    mov cx, SH_M2KB * 1024
    push dx
    xor dx, dx
    mov si, sh_m2name
    call OSAPI_FILE_READ
    pop dx
    jc .noread
    mov ax, [es:SH_M2STAMP]             ; THIS build's module, or none: one
    cmp ax, shm_m2end - sh_modm0        ; from another build reads our bss at
    jne .noread                         ; stale offsets (sh_modm_stamp)
    mov ax, [es:SH_M2STAMP + 2]
    cmp ax, os88_image_end
    jne .noread
    mov word [sh_m2far], 0              ; the dispatcher is at the claim's 0
    mov [sh_m2far + 2], dx
    call ch_ovback
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
.ok:
    clc
    ret
.noread:
    call OSAPI_MEM_FREE                 ; DX is the claim: a half-loaded
.nomem:                                 ; module is worse than none
    call ch_ovback
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
.fail:
    mov byte [sh_m2fail], 1
.no:
    stc
    ret
sh_m2name: db 'MACRO.OVL', 0
SH_M2STAMP equ sh_modm_stamp - sh_modm0   ; the stamp's offset in the claim

; -----------------------------------------------------------------------------
; sh_ovbind - fill the vector table: this package's shim offsets and its own
; segment. The offsets are assembled in; only the segment is a runtime fact,
; and it is the same one for all of them. ch_ovbind's shape exactly (82.16).
; -----------------------------------------------------------------------------
sh_ovbind:
    push ax
    push bx
    push si
    push di
    mov si, sh_ovshims
    mov di, sh_v_first
    mov ax, cs
    mov bx, SH_NVEC
.l:
    push ax
    mov ax, [si]
    mov [di], ax
    pop ax
    mov [di+2], ax
    add si, 2
    add di, 4
    dec bx
    jnz .l
    pop di
    pop si
    pop bx
    pop ax
    ret

