    dw sh_x_fp_cmpab, sh_x_fp_unpack_b, sh_x_fp_atof, sh_x_fp_i2a
    dw sh_x_fp_a2i, sh_x_fp_ftoa, sh_x_fp_div, sh_x_fp_i2b
    dw sh_x_fp_norm, sh_x_sh_bios_ymd, sh_x_sh_bt_get, sh_x_sh_bt_addcell
    dw sh_x_fp_a_to_b, sh_x_fp_add, sh_x_fp_azero, sh_x_fp_iszero, sh_x_fp_ln   ; 82.16.10's
    dw sh_x_fp_mul, sh_x_fp_pack_a, sh_x_fp_pow, sh_x_fp_sub
    dw sh_x_sh_pargref, sh_x_sh_pcmp, sh_x_sh_skipargs, sh_x_sh_trcopy
    dw sh_x_sh_setbool, sh_x_sh_setlabel, sh_x_sh_boolname      ; 81.51
    dw sh_x_sh_bt_getw                                            ; 81.55
    dw sh_x_sh_colwidth, sh_x_sh_colw_set, sh_x_sh_colw_clear     ; 81.56
    dw sh_x_sh_rowh_set                                           ; 81.60
    dw sh_x_sh_seterr                                             ; 81.61
    dw sh_x_fp_atan, sh_x_fp_cos, sh_x_fp_exp, sh_x_fp_sin   ; 81.62
    dw sh_x_fp_sqrt, sh_x_fp_tan, sh_x_sh_acc_toint, sh_x_sh_binop_ld
    dw sh_x_sh_fmtcode, sh_x_sh_group3, sh_x_sh_ins_at, sh_x_sh_matchat
    dw sh_x_sh_numdp, sh_x_sh_parg, sh_x_sh_pcellref, sh_x_sh_pstrarg
    dw sh_x_sh_spop, sh_x_sh_spush, sh_x_sh_srestore, sh_x_sh_sslot
    dw sh_x_sh_str_cat, sh_x_sh_strcpy, sh_x_sh_strlen

    dw sh_x_sh_commit, sh_x_sh_drawstatus, sh_x_sh_macro_alertup, sh_x_sh_macro_beep   ; 81.63
    dw sh_x_sh_macro_clear, sh_x_sh_macro_cmd, sh_x_sh_macro_inputup, sh_x_sh_name_lookup
    dw sh_x_sh_recalc_all, sh_x_sh_repaint, sh_x_sh_scrollto, sh_x_sh_str_want
    dw sh_x_sh_undo_drop
    dw sh_x_sh_foldvalue, sh_x_sh_funcfinish                          ; 81.65
    dw sh_x_sh_cell_totext, sh_x_sh_clearcell, sh_x_sh_formula_copyshift ; 81.71
    dw sh_x_os88line_set, sh_x_os88line_draw, sh_x_os88line_key      ; 81.71.5
    dw sh_x_os88line_click, sh_x_os88ui_btn, sh_x_os88ui_ask
    dw sh_x_os88ui_glyph                                           ; 81.71.5.1
    dw sh_x_os88ui_sbar, sh_x_os88ui_sbhit, sh_x_sh_cell_nfid        ; 81.71.6
    dw sh_x_sh_editstart, sh_x_sh_flkey, sh_x_sh_name_list
    dw sh_x_sh_nf_apply
    dw sh_x_sh_acc_toudw, sh_x_sh_ser_to_ymd, sh_x_sh_ymd_to_ser     ; 81.72
    dw sh_x_sh_chart_paint, sh_x_sh_chart_render
    dw sh_x_sh_dlg, sh_x_sh_docmd_paste
    dw sh_x_sh_geom, sh_x_sh_new
    dw sh_x_sh_pnum_at, sh_x_sh_prot_blocked, sh_x_sh_ptwips
    dw sh_x_sh_rec_cmd, sh_x_sh_rec_start, sh_x_sh_rowcol_op
    dw sh_x_sh_rowtw, sh_x_sh_select, sh_x_sh_ser_setstep
    dw sh_x_sh_twpts, sh_x_sh_undo_begin
    dw sh_x_sh_upcase_at, sh_x_sh_docmd_dbrun, sh_x_sh_undo_end, sh_x_sh_idlg_after  ; 81.74.2
    dw sh_x_sh_acc_fromudw, sh_x_sh_monlen
    dw sh_x_sh_bt_findcell, sh_x_sh_bt_removecell
    dw sh_x_sh_pnow, sh_x_sh_macro_arm                               ; 81.86
    dw sh_x_sh_nt_get                                                ; 81.87
    dw sh_x_sh_macro_mfire                                           ; 81.88
    dw sh_x_sh_nt_set                                                ; 81.89
    dw sh_x_sh_mtab_calc                                             ; 81.95
    dw sh_x_sh_dbx_open                                              ; 81.96
    dw sh_x_sh_note_load                                             ; 81.102
    dw sh_x_sh_btfix                                                 ; 81.111
    dw sh_x_os88ui_sbwheel                                           ; 13.18
sh_entry:
    push ax
    push dx
    push si
    push di
    call OSAPI_FILE_HERE                ; where this package was LAUNCHED from,
    mov [ch_ovdir], dx                  ; banked before anything can navigate
    mov [ch_ovdrv], bl                  ; away - it is where CHART.OVL lives
                                        ; (82.16, the shape SPEC.md 68.10 sets)
    call fp_init                      ; before the first claim, because every
    call sh_ovbind                      ; ...and the file-format module's
                                        ; (82.16.9), the same shape
    call ch_ovbind                      ; the chart module's vectors out (82.16):
                                        ; our shims, our segment, before anything
                                        ; can draw
                                      ; other thing here can fail and be
                                      ; recovered from and this one decides
                                      ; which arithmetic the session gets
    mov ax, SH_CLAIM_CELLS_KB
    call OSAPI_MEM_CLAIM
    jc .fail
    mov [sh_cellseg], dx
    mov ax, sh_reloc                     ; ...and MOVABLE (SPEC.md 66.2). SHEET
                                      ; has NO WORKER, so mem_can_move
                                      ; passes these on I_TASK = 0xFF
                                      ; alone and no park is involved
    call OSAPI_MEM_MOVABLE
    mov ax, SH_CLAIM_TXT_KB
    call OSAPI_MEM_CLAIM
    jc .fail
    mov [sh_txtseg], dx
    mov ax, sh_reloc
    call OSAPI_MEM_MOVABLE
    mov ax, SH_CLAIM_STG_KB
    call OSAPI_MEM_CLAIM
    jc .fail
    mov [sh_stgseg], dx
    ; THE BORDER AND NOTE TABLES ARE ONE CLAIM, CARVED (81.94): MEM_OWNER_MAX
    ; is eight claims an owner and SHEET held eight, so MACRO.OVL's claim had
    ; nowhere to come from. The note table is the claim's second part, and
    ; sh_reloc derives its segment from the border table's after a move
    mov ax, SH_CLAIM_BORD_KB + SH_CLAIM_NOTE_KB + SH_CLAIM_TBL_KB
    call OSAPI_MEM_CLAIM
    jc .fail
    mov [sh_bordseg], dx
    mov ax, sh_reloc                   ; DX IS THE CLAIM HERE: MEM_MOVABLE
    call OSAPI_MEM_MOVABLE             ; takes the claim's base, and the first
    add dx, SH_CLAIM_BORD_KB * 64      ; build declared the NOTE table's - not
    mov [sh_noteseg], dx               ; a claim, refused, silently pinned
    add dx, SH_CLAIM_NOTE_KB * 64      ; ...and the table list past all five
    mov [sh_tblseg], dx                ; of the note claim's KB (81.114.7)
    mov word [sh_ntbl], 0
    mov word [sh_nbord], 0
    call sh_colw_clear                 ; every column the standard width (81.56)
    mov word [sh_nnote], 0
    mov ax, SH_CLAIM_CHART_KB
    call OSAPI_MEM_CLAIM
    jc .fail
    mov [sh_chartseg], dx
    mov ax, sh_reloc
    call OSAPI_MEM_MOVABLE
    mov ax, SH_CLAIM_UNDO_KB           ; Undo's, last and optional (81.57): a
    call OSAPI_MEM_CLAIM               ; heap that cannot spare it costs Undo,
    jc .noundo                         ; not the app
    mov [sh_undoseg], dx
    mov ax, sh_reloc
    call OSAPI_MEM_MOVABLE
.noundo:
    call sh_m2need                      ; 81.94: MACRO.OVL's, with CHART.OVL's
                                        ; before it (sh_m2need asks for that
                                        ; one first) - CF not read, as below
    call ch_ovneed                      ; CHART.OVL's CH_OVKB claim is taken
                                        ; HERE, with every other claim, because
                                        ; SPEC.md 50.3 is not advice. CF is not
                                        ; read - a machine too small for it
                                        ; still runs the spreadsheet, and the
                                        ; first chart is what says so (82.16.3)
    mov dx, [sh_chartseg]               ; ...AND DX IS RE-READ, NOT TRUSTED.
                                        ; ch_ovneed claims, a claim can compact,
                                        ; and the chart claim above is movable
                                        ; now: sh_reloc patches the WORD, never
                                        ; this register, and the BMP header copy
                                        ; below writes through DX as ES
    ; THE REGION ITSELF IS NOT DECLARED MOVABLE IN THIS TREE, and that is the
    ; one place this proc departs from upstream's (SPEC.md 66.6.1). Upstream's
    ; case for it is that SHEET "stores its own segment nowhere", which is
    ; true of a package with no overlay and false of this one twice over:
    ;
    ;  - ch_ovbind stamps CS into CHART.OVL's vector table, and every SHOUT
    ;    reaches back through a far pointer holding it. A moved image leaves
    ;    all of them naming the old one.
    ;  - the module makes ELEVEN file calls (every format's reader and
    ;    writer, 82.16.9), each while this package's far return address is on
    ;    the stack - and a file call claims, so it can compact. The module's
    ;    retf would pop a segment the kernel has no record of.
    ;
    ; The data claims above DO move: every file transfer stages through
    ; sh_stgseg, which is pinned, and every copy of a movable segment is
    ; either in sh_segw or dead across no compaction point. The image and
    ; CHART.OVL are what stay put.
    mov word [sh_chartwin], 0
    mov word [sh_chart_cnt], 0
    mov word [ch_type], CH_T_COLUMN
    push si
    push di
    push cx
    push es
    mov es, dx                          ; copy the constant 118-byte BMP
    mov si, ch_hdrtpl                   ; header+palette into the buffer once
    xor di, di                          ; here - ch_bmp_write only ever stages
    mov cx, CH_HDRSZ                    ; whatever is already sitting there,
    cld                                 ; it never rebuilds it (see
    rep movsb                           ; os88chart.inc's own header comment)
    pop es
    pop cx
    pop di
    pop si
    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0
    mov si, sh_defname                ; the document's NAME before the window:
    mov di, sh_name                   ; the template's title is sh_ttlbuf, so
    call sh_strcpy                    ; the first frame already says which
    call sh_note_arg                  ; document it is (81.103). A document
    call sh_title_sync                ; double-clicked in the Disk window is
                                       ; NOTED here and READ at the first paint
                                       ; - see sh_note_arg's header
    mov si, sh_tpl
    call OSAPI_WM_CREATE
    jc .fail
    push ax
    mov ax, sh_onclose                ; the close negotiator (81.118, SPEC.md
    call OSAPI_WM_ONCLOSE             ; 75.1): a changed workbook asks first
    pop ax
    push ax                           ; SIZABLE (SPEC.md 11.1, 81.112). The
    mov al, 1                         ; contract is that a resizable window's
    call OSAPI_WM_SIZABLE             ; paint lays out from the LIVE record
    pop ax                            ; every call, and sh_paint has always
                                       ; done exactly that: it calls sh_geom,
                                       ; which asks OSAPI_WM_CONTENT for the
                                       ; content box and WALKS columns and
                                       ; rows until the pixels run out. The
                                       ; grid was never fixed at the
                                       ; template's 560x380 - only the window
                                       ; was, because nothing ever asked for
                                       ; the flag. Notepad's np_paint carries
                                       ; the same comment for the same reason
    push cx                           ; ...and a FLOOR under it (SPEC.md
    push dx                           ; 11.100.2): see SH_MINW above. A window
    mov cx, SH_MINW                   ; that may be dragged can be dragged to
    mov dx, SH_MINH                   ; WMIN_W x WMIN_H, where this one's own
    call OSAPI_WM_MINSIZE             ; strips do not fit each other
    pop dx
    pop cx
    mov [sh_ownwin], bx               ; stage 2.0: os88ui_ask needs our own
                                       ; window ptr, and it's asked for from
                                       ; the macro engine, which has no window
                                       ; ptr of its own to hand it - Sheet
                                       ; only ever has the one window, so
                                       ; capturing it once here is safe
    mov byte [sh_mopen], SH_M_NONE    ; stage 2.x: Sheet's own menu bar -
    mov byte [sh_mhi], SH_M_NONE      ; see the SH_MBAR_H section comment
    mov byte [sh_gridlines], 1
    mov byte [sh_showformulas], 0
    mov word [sh_cellw], SH_CW_NORMAL        ; stage 2.x: runtime cell size
    mov word [sh_cellh], SH_RH_NORMAL        ; defaults - see the SH_CW_*/
    mov word [sh_cellch], SH_CW_NORMAL / 8   ; SH_RH_* section comment
    mov word [sh_defch], SH_CW_NORMAL / 8    ; 81.56: the STANDARD width - a
                                             ; column's own is in the table,
                                             ; and sh_cellch/sh_cellw are the
                                             ; column being drawn
    call sh_mkblank
    call sh_mtab_calc
    call sh_sheetmark
    call sh_recmark                    ; 81.74: both Macro items say what they

    ; stage 3.0a: drag-to-select. BX is still the window OSAPI_WM_CREATE just
    ; answered. CF=1 means kern_small, which carries the slot and not the body
    ; (os88api.inc: "TEST CF AND HAVE A SECOND PATH") - there is simply no
    ; tracking on that machine, and shift+click and shift+arrows, which need
    ; no kernel support at all, remain the way to build a range there.
    mov ax, sh_ondrag
    call OSAPI_WM_ONDRAG

    ; The RELEASE edge, which a thumb drag needs to let go on (13.10.5). Same
    ; kern_small caveat as the drag edge above: refused there, and a bar that
    ; cannot be dragged never needs dropping.
    mov ax, sh_onmouseup
    call OSAPI_WM_ONMOUSEUP

    ; The WHEEL (SPEC.md 13.18) scrolls the grid's rows. kern_small has no
    ; wheel and the cell does nothing there; flags preserved, BX still ours.
    mov ax, sh_onwheel
    call OSAPI_WM_ONWHEEL

    ; stage 3.0b: the formula bar's content box. Only the buffer binding is
    ; set once - the rect is refreshed per draw by sh_flrect, since the window
    ; moves and resizes and a stale rect would draw and hit-test in the wrong
    ; place.
    mov word [sh_fline + LN_BUF], sh_editbuf
    mov word [sh_fline + LN_MAX], SH_EDITMAX + 1

    ; Arm the key-state map now rather than on the user's first shift+click.
    ; kbd_down arms itself on the first ASK and its first answer is always
    ; "up" (kernel/mouse.inc's own note), so without this the very first
    ; shift+click of a session would read as an unshifted one.
    mov al, 0x2A
    call OSAPI_KEY_DOWN

    mov si, sh_menus
    call OSAPI_MENU_SET
    mov bx, [sh_ownwin]               ; ...and 'About Sheet' above its Close,
    mov si, sh_about                  ; which is the OS's own convention and
    call OSAPI_ABOUT_SET              ; not a Help menu of one's own devising
                                       ; (SPEC.md 12.2). Seventeen packages
                                       ; already did this; Sheet had a Help >
                                       ; About... item instead, which put the
                                       ; same text somewhere nobody looks for
                                       ; it on this system.
    clc
    jmp .out
.fail:
    stc
.out:
    pop di
    pop si
    pop dx
    pop ax
    ret

; =============================================================================
; Geometry
; =============================================================================

; -----------------------------------------------------------------------------
; sh_geom - in: BX = window ptr
; out: [sh_ox]/[sh_oy] content origin, [sh_cw]/[sh_ch] content size,
;      [sh_vcols]/[sh_vrows] grid cells that fit given the current scroll;
;      all registers preserved
; -----------------------------------------------------------------------------
sh_geom:
    push ax
    push cx
    push dx
    call OSAPI_WM_CONTENT
    mov [sh_ox], ax
    mov [sh_oy], dx
    add dx, SH_MBAR_H                  ; sh_goy: where the formula bar and
    mov [sh_goy], dx                   ; everything below it actually starts,
                                        ; now that the menu bar (SH_MBAR_H
                                        ; section comment) sits above them -
                                        ; sh_oy itself stays the RAW content
                                        ; origin, since sh_mbar_draw needs
                                        ; that one, not the shifted one
    call OSAPI_WM_GEOM
    mov [sh_cw], cx
    mov [sh_ch], dx

    mov ax, cx
    sub ax, SH_RH_W + SH_VSB_W         ; the vertical bar owns a strip at the
    jns .cw_ok                          ; right, so the grid is that much
    xor ax, ax                          ; narrower
.cw_ok:
    mov [sh_gridw], ax                  ; what sh_scrollto_t fits a column in
    ; EACH COLUMN ITS OWN WIDTH (81.56): walked from the scroll position until
    ; the next would not fit whole, and kept in sh_vcw for everything that
    ; places a column - sh_vcx is the only arithmetic that turns a visible
    ; column into pixels. It was one division by the one width.
    ;
    ; FROZEN PANES (81.70) walk FIRST, real columns 0..sh_freezecol-1 - DI
    ; keeps counting up through them rather than resetting, so the second
    ; loop's "real column = sh_scrollcol + (DI - sh_freezecol)" is exactly
    ; the old "sh_scrollcol + DI" once sh_freezecol is 0, and every visible
    ; index still names its own sh_vcw slot directly either way
    push bx
    push di
    mov dx, ax                          ; DX = the pixels left
    xor di, di                          ; DI = the SLOTS filled so far, which
    mov word [sh_geom_rc], 0            ; is no longer the same thing as the
                                         ; real columns walked (81.73): a
                                         ; HIDDEN column is walked and takes
                                         ; no slot, so the two cursors part
                                         ; company and sh_vrc records which
                                         ; real column each slot ended up with
.fcwalk:
    mov ax, [sh_geom_rc]
    cmp ax, [sh_freezecol]
    jae .cwinit
    cmp di, SH_MAXVC
    jae .cset
    call sh_geom_col
    jc .fcwalk
    jmp short .cset
.cwinit:
    mov ax, [sh_scrollcol]
    mov [sh_geom_rc], ax
.cwalk:
    cmp di, SH_MAXVC
    jae .cset
    mov ax, [sh_geom_rc]
    cmp ax, SH_COLS
    jae .cset
    call sh_geom_col
    jc .cwalk
.cset:
    mov [sh_vcols], di
    pop di
    pop bx

    mov ax, [sh_ch]
    sub ax, SH_MBAR_H + SH_FB_H + SH_CH_H + SH_SB_H + SH_HSB_H
    jns .chh_ok                         ; ...and the horizontal bar a strip
    xor ax, ax                          ; above the status bar
.chh_ok:
    mov [sh_gridh], ax
    ; EACH ROW ITS OWN HEIGHT (81.60), walked the way the columns are: from
    ; the scroll position until the next would not fit whole, kept in sh_vrh
    ; for sh_vry, the only arithmetic that turns a visible row into pixels
    ; The table is walked ONCE beside the rows, not searched for each: it is
    ; sorted, so from the first record at or past the scroll row the next
    ; record is either this row's or a later one's. sh_geom runs on every
    ; repaint, and a search per row is a table-full of compares per row
    ; FROZEN PANES (81.70): the frozen prefix, real rows 0..sh_freezerow-1,
    ; walked FIRST with its own sh_rh_find (the sparse table's position for
    ; row 0 and for sh_scrollrow are generally not the same place, so the
    ; walk restarts rather than continuing) - DI keeps counting up through
    ; it exactly as the column walk's does, so it still names its own
    ; sh_vrh slot directly in both phases
    push bx
    push si
    push di
    push es
    mov dx, ax                          ; DX = the pixels left
    xor di, di                          ; DI = the rows so far
    cmp di, [sh_freezerow]
    jae .rowsdone
    xor ax, ax
    call sh_rh_find                     ; BX = key, SI/CX = record, from 0
    mov word [sh_geom_rr], 0            ; 81.73: the real ROW cursor, beside DI
    mov word [sh_geom_rbase], 0         ; ...and where this phase's sh_rh_find
.frwalk:
    mov ax, [sh_geom_rr]
    cmp ax, [sh_freezerow]
    jae .rowsdone
    cmp di, SH_MAXVR
    jae .rset
    call sh_geom_row
    jc .frwalk
    jmp short .rset
.rowsdone:
    mov ax, [sh_scrollrow]
    mov [sh_geom_rr], ax
    mov [sh_geom_rbase], ax
    call sh_rh_find                     ; a fresh walk, from the scroll row
.rwalk:
    cmp di, SH_MAXVR
    jae .rset
    mov ax, [sh_geom_rr]
    cmp ax, SH_ROWS
    jae .rset
    call sh_geom_row
    jc .rwalk
.rset:
    mov [sh_vrows], di
    pop es
    pop di
    pop si
    pop bx

    pop dx
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_geom_col / sh_geom_row - ONE column (or row) of sh_geom's walk (81.73).
;
; in:  [sh_geom_rc]/[sh_geom_rr] = the real index to consider, DI = the next
;      free slot, DX = the pixels left; for rows, ES:SI/CX/BX are the row
;      height table's streaming cursor exactly as the walk left them.
; out: the cursor advanced, and CF=1 to carry on / CF=0 when this one did not
;      fit and the walk is finished. DI and DX updated in place.
;
; A HIDDEN index takes no slot and no pixels and does not end the walk, which
; is the whole of what hiding is here - every other reader sees a viewport
; that simply does not contain it.
; -----------------------------------------------------------------------------
sh_geom_col:
    push bx
    mov ax, [sh_geom_rc]
    inc word [sh_geom_rc]
    call sh_colwidth                   ; 0 = hidden
    or ax, ax
    jz .skip
    mov [sh_vcw + di], al
    mov cl, 3
    shl ax, cl
    cmp ax, dx
    ja .full
    sub dx, ax
    mov bx, di
    shl bx, 1
    mov ax, [sh_geom_rc]
    dec ax
    mov [sh_vrc + bx], ax              ; slot DI shows THIS real column
    inc di
.skip:
    pop bx
    stc
    ret
.full:
    pop bx
    clc
    ret

sh_geom_row:
    mov ax, [sh_geom_rr]
    mov [sh_geom_roff], ax             ; the real row this slot would show
    inc word [sh_geom_rr]
    sub ax, [sh_geom_rbase]            ; ...as an offset into the phase that
    add ax, bx                         ; sh_rh_find was last called for, which
    cmp cx, [es:SH_ROWH_N]             ; is the key the table is streaming in
    jae .std
    cmp [es:si], ax
    jne .std
    mov ax, [es:si+2]                  ; its own height, in twips...
    add si, SH_ROWH_REC
    inc cx
    cmp ax, SH_RH_HIDDEN
    je .skip                           ; ...or no height at all
    call sh_twpx
    jmp short .have
.std:
    mov ax, SH_RH_NORMAL               ; ...or the standard
.have:
    cmp ax, dx
    ja .full
    sub dx, ax
    mov [sh_vrh + di], al
    push bx
    mov bx, di
    shl bx, 1
    mov ax, [sh_geom_roff]
    mov [sh_vrr + bx], ax              ; slot DI shows THIS real row
    pop bx
    inc di
.skip:
    stc
    ret
.full:
    clc
    ret

; -----------------------------------------------------------------------------
; COLUMN WIDTHS (81.56). 256 bytes a sheet in the note claim's top kilobyte
; (SH_COLW_OFF), each a column's width in CHARACTERS, Excel's own unit - 0 for
; the standard width, sh_defch. sh_vcw is the visible columns' widths, which
; sh_geom walks out of here; sh_vcx and sh_vwidth turn one into pixels.
; -----------------------------------------------------------------------------
; 81.73: a HIDDEN column or row. The stored width byte already spends 0 on
; "the standard width" and a row's twips do too, so hiding needs a sentinel of
; its own rather than the zero Excel's dialog shows - SH_CW_MAXCH is 40, so
; 255 is free, and a row's height is a word.
SH_CW_HIDDEN equ 255
SH_RH_HIDDEN equ 0xFFFF
; NOTHING ASKS "is this hidden?" as a question of its own, and nothing should:
; sh_colwidth and sh_rowheight answer ZERO for a hidden one, which is what lets
; sh_geom skip it without a second lookup. Two predicates - sh_col_hidden and
; sh_row_hidden - were written beside these sentinels and never called by
; anything, which is worse than absent: they read like the mechanism.

; sh_colwidth - in: AX = a column; out: AX = its width in characters, and ZERO
; when it is hidden - which is what makes sh_geom skip it without a second
; question (81.73)
sh_colwidth:
    push bx
    push es
    mov bh, [sh_cursheet]
    xor bl, bl
    add bx, ax
    mov es, [sh_noteseg]
    mov al, [es:bx + SH_COLW_OFF]
    xor ah, ah
    cmp al, SH_CW_HIDDEN               ; 81.73: hidden is no width at all
    je .hidden
    or al, al
    jnz .out
    mov ax, [sh_defch]
    jmp short .out
.hidden:
    xor ax, ax
.out:
    pop es
    pop bx
    ret

; sh_colw_set - in: AX = a column, CL = its width in characters (0 standard)
sh_colw_set:
    push bx
    push es
    mov bh, [sh_cursheet]
    xor bl, bl
    add bx, ax
    mov es, [sh_noteseg]
    mov [es:bx + SH_COLW_OFF], cl
    pop es
    pop bx
    ret

; sh_colw_clear - every column of every sheet the standard width, and (81.60)
; every row the standard height: the two tables are the claim's last 2 KB
sh_colw_clear:
    push ax
    push cx
    push di
    push es
    mov es, [sh_noteseg]
    mov di, SH_COLW_OFF
    mov cx, 4 * 256 + 1024
    xor al, al
    cld
    rep stosb
    pop es
    pop di
    pop cx
    pop ax
    ret

; sh_colw_shift - AL = 2 inserts a column at BX, 3 deletes the one at BX: the
; widths after it move with their columns, as the cells do. An inserted
; column is the standard width. Anything else in AL: nothing.
sh_colw_shift:
    push ax
    push bx
    push cx
    push si
    push di
    push ds
    push es
    mov cx, 255
    sub cx, bx                        ; CX = the columns past the pivot
    jbe .out
    mov si, [sh_cursheet]             ; THE BASE FIRST, from our own bss:
    mov di, si                        ; DS is the note claim below
    mov cl, 8
    shl di, cl
    add di, SH_COLW_OFF               ; DI = this sheet's width table
    mov cx, 255
    sub cx, bx
    mov es, [sh_noteseg]
    push es
    pop ds
    cmp al, 3
    je .del
    cmp al, 2
    jne .out
    add di, bx                        ; insert: [c..254] -> [c+1..255]
    push di
    add di, cx
    mov si, di
    dec si
    std
    rep movsb
    cld
    pop di
    mov byte [es:di], 0
    jmp short .out
.del:
    add di, bx                        ; delete: [c+1..255] -> [c..254]
    mov si, di
    inc si
    push cx
    cld
    rep movsb
    pop cx
    mov byte [es:di], 0               ; DI is at 255 now
.out:
    pop es
    pop ds
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

;-----------------------------------------------------------------------------
; ROW HEIGHTS (81.60). A sorted sparse table in the note claim's fifth KB
; (SH_ROWH_OFF): a packed row/sheet word - the cell array's own key - and the
; height in TWIPS, for each row that is not the standard height; the count is
; the KB's last word. Excel's rows are 16,384 to a sheet, so a flat table like
; the widths' would be 32 KB a sheet. sh_vrh is the visible rows' heights in
; pixels, which sh_geom walks out of here; sh_vry turns one into pixels.
; -----------------------------------------------------------------------------
; sh_rh_find - AX = a row of the current sheet -> BX = its key, SI = the offset
; of the first record whose key is not below it, CX = that record's index, ES =
; the note claim; ZF=1 when that record IS this row's
sh_rh_find:
    push dx
    push ax
    mov bx, [sh_cursheet]
    mov cl, SH_ROW_BITS
    shl bx, cl
    or bx, ax
    mov es, [sh_noteseg]
    mov si, SH_ROWH_OFF
    xor cx, cx
.l:
    cmp cx, [es:SH_ROWH_N]
    jae .end
    cmp [es:si], bx
    jae .ge
    add si, SH_ROWH_REC
    inc cx
    jmp short .l
.ge:
    pop ax
    pop dx
    cmp [es:si], bx
    ret
.end:
    pop ax
    mov dx, 1
    or dx, dx                          ; ZF=0: past the last record
    pop dx
    ret

; sh_rowtw - AX = a row -> AX = its height in twips, 0 for the standard
sh_rowtw:
    push bx
    push cx
    push si
    push es
    call sh_rh_find
    mov ax, 0
    jne .out
    mov ax, [es:si+2]
.out:
    pop es
    pop si
    pop cx
    pop bx
    ret

; sh_rowheight - AX = a row -> AX = its height in pixels, and ZERO when it is
; hidden, sh_colwidth's own rule (81.73)
sh_rowheight:
    call sh_rowtw
    cmp ax, SH_RH_HIDDEN
    je .hidden
    or ax, ax
    jnz sh_twpx
    mov ax, SH_RH_NORMAL
    ret
.hidden:
    xor ax, ax
    ret
; sh_pxtw - AX = pixels -> AX = twips, sh_twpx's own inverse (81.73.2)
sh_pxtw:
    push cx
    push dx
    mov cx, SH_RH_STDTW
    mul cx
    add ax, SH_RH_NORMAL / 2
    adc dx, 0
    mov cx, SH_RH_NORMAL
    div cx
    pop dx
    pop cx
    ret

; sh_twpx - AX = twips -> AX = pixels, the standard 255 being SH_RH_NORMAL
sh_twpx:
    push cx
    push dx
    mov cx, SH_RH_NORMAL
    mul cx
    add ax, SH_RH_STDTW / 2
    adc dx, 0
    mov cx, SH_RH_STDTW
    div cx
    pop dx
    pop cx
    ret

; sh_rowh_set - AX = a row of the current sheet, CX = its height in twips (0
; or SH_RH_STDTW for the standard, which removes its record). CF=1 when the
; table is full, and nothing changed
sh_rowh_set:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov dx, cx                         ; DX = the twips
    cmp dx, SH_RH_STDTW
    jne .have
    xor dx, dx
.have:
    call sh_rh_find
    jne .new
    or dx, dx
    jz .del
    mov [es:si+2], dx                  ; already there: a new height
    jmp short .ok
.del:
    mov ax, [es:SH_ROWH_N]             ; the standard again: close it up
    dec ax
    mov [es:SH_ROWH_N], ax
    sub ax, cx                         ; AX = the records after it
.dl:
    or ax, ax
    jz .ok
    mov bx, [es:si+SH_ROWH_REC]
    mov [es:si], bx
    mov bx, [es:si+SH_ROWH_REC+2]
    mov [es:si+2], bx
    add si, SH_ROWH_REC
    dec ax
    jmp short .dl
.new:
    or dx, dx
    jz .ok                             ; the standard, and none: nothing to do
    mov di, [es:SH_ROWH_N]
    cmp di, SH_ROWH_CAP
    jae .full
    shl di, 1
    shl di, 1
    add di, SH_ROWH_OFF                ; DI = one past the last record
.ul:
    cmp di, si                         ; open a slot at SI, from the end
    jbe .ins
    mov ax, [es:di-SH_ROWH_REC]
    mov [es:di], ax
    mov ax, [es:di-SH_ROWH_REC+2]
    mov [es:di+2], ax
    sub di, SH_ROWH_REC
    jmp short .ul
.ins:
    mov [es:si], bx
    mov [es:si+2], dx
    inc word [es:SH_ROWH_N]
.ok:
    clc
    jmp short .out
.full:
    stc
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_rh_anyin - AX..DX = rows of the current sheet -> CF=1 when any of them is
; not the standard height. What sh_scrollrow_blit asks before it moves rows by
; one height
sh_rh_anyin:
    push ax
    push bx
    push cx
    push si
    push es
    cmp dx, SH_ROWS
    jb .dok
    mov dx, SH_ROWS - 1
.dok:
    call sh_rh_find                    ; the first record at or past AX...
    cmp cx, [es:SH_ROWH_N]
    jae .none
    mov bx, [sh_cursheet]              ; ...is it still at or before DX's
    mov cl, SH_ROW_BITS                ; key, built as sh_rh_find builds it?
    shl bx, cl
    or bx, dx
    cmp [es:si], bx
    ja .none
    stc
    jmp short .out
.none:
    clc
.out:
    pop es
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_vry - in: AX = a visible row (0..sh_vrows); out: AX = its top edge, in
; pixels from the grid's
sh_vry:
    push bx
    push cx
    mov cx, ax
    xor ax, ax
    xor bx, bx
.l:
    jcxz .d
    add al, [sh_vrh + bx]
    adc ah, 0
    inc bx
    dec cx
    jmp short .l
.d:
    pop cx
    pop bx
    ret

; sh_vheight - in: AX = a visible row; out: AX = its height in pixels
sh_vheight:
    push bx
    mov bx, ax
    mov al, [sh_vrh + bx]
    xor ah, ah
    pop bx
    ret

; sh_vtoff - in: AX = a visible row; out: AX = where its text starts below its
; top: a row taller than the standard keeps its text as far from its BOTTOM as
; a standard one does, so text sits low in a tall row as Excel's does
sh_vtoff:
    call sh_vheight
    sub ax, SH_RH_NORMAL
    jns .out
    xor ax, ax
.out:
    ret

; -----------------------------------------------------------------------------
; sh_rc_sides - Insert and Delete Row/Column move the BORDER and NOTE tables'
; records with their cells (81.58). They moved the cells alone, so a border or
; a note stayed on the row or column it had been drawn on while its cell went
; somewhere else - and a deleted row left its borders on the row that took
; its place. In: [sh_rc_op], [sh_rc_idx], the user's sheet in sh_cursheet.
; -----------------------------------------------------------------------------
sh_rc_sides:
    push bx
    push cx
    push dx
    mov dx, [sh_bordseg]
    mov cx, [sh_nbord]
    mov bx, SH_BT_SZ
    call sh_rc_table
    mov [sh_nbord], cx
    mov dx, [sh_noteseg]
    mov cx, [sh_nnote]
    mov bx, SH_NOTE_REC
    call sh_rc_table
    mov [sh_nnote], cx
    cmp byte [sh_rc_op], 2            ; ...and a ROW's height goes with it
    jae .out                          ; (81.60) - the table has no column
    push es                           ; word for a column op to read
    mov es, [sh_noteseg]
    mov cx, [es:SH_ROWH_N]
    mov dx, es
    add dx, SH_ROWH_OFF / 16
    mov bx, SH_ROWH_REC
    call sh_rc_table
    mov [es:SH_ROWH_N], cx
    pop es
.out:
    pop dx
    pop cx
    pop bx
    ret

; sh_rc_table - DX = a sparse table's segment, CX = its records, BX = its
; record size (packed row/sheet word, then the column word): every record on
; this sheet past the pivot moves one row or column, the pivot's own go on a
; delete, and one pushed off the grid goes too. out: CX = the records left.
; IN PLACE, and still sorted: the table is in (row, col) order, and a shift
; that moves every record past the pivot by the same one cannot reorder it.
sh_rc_table:
    push ax
    push dx
    push si
    push di
    push bp
    push es
    mov es, dx
    mov bp, cx                        ; BP = the records still to read
    xor cx, cx                        ; CX = the records kept
    xor si, si                        ; SI reads, DI writes
    xor di, di
.l:
    or bp, bp
    jz .done
    dec bp
    mov ax, [es:si]                   ; the packed row: its sheet...
    mov dx, ax
    push cx
    mov cl, SH_ROW_BITS
    shr dx, cl
    pop cx
    cmp dx, [sh_cursheet]
    jne .keep                         ; another sheet's: untouched
    and ax, SH_ROW_MASK               ; ...and its row
    mov dl, [sh_rc_op]
    cmp dl, 2
    jae .col
    cmp ax, [sh_rc_idx]
    jb .keep
    cmp dl, 1
    je .delrow
    inc ax                            ; insert: one row down
    cmp ax, SH_ROWS
    jae .drop
    jmp short .newrow
.delrow:
    cmp ax, [sh_rc_idx]               ; delete: the pivot's own go, the rest
    je .drop                          ; one row up
    dec ax
.newrow:
    mov dx, [es:si]
    and dx, ~SH_ROW_MASK & 0xFFFF     ; the sheet bits, as they were
    or ax, dx
    mov [es:si], ax
    jmp short .keep
.col:
    mov ax, [es:si+2]
    cmp ax, [sh_rc_idx]
    jb .keep
    cmp dl, 3
    je .delcol
    inc ax
    cmp ax, SH_COLS
    jae .drop
    mov [es:si+2], ax
    jmp short .keep
.delcol:
    cmp ax, [sh_rc_idx]
    je .drop
    dec ax
    mov [es:si+2], ax
.keep:
    cmp si, di
    je .same
    push cx                           ; a drop behind it: close the gap
    mov cx, bx
.cp:
    mov al, [es:si]
    mov [es:di], al
    inc si
    inc di
    loop .cp
    pop cx
    jmp short .kept
.same:
    add si, bx
    add di, bx
.kept:
    inc cx
    jmp .l
.drop:
    add si, bx
    jmp .l
.done:
    pop es
    pop bp
    pop di
    pop si
    pop dx
    pop ax
    ret

; sh_vcx - in: AX = a visible column (0..sh_vcols); out: AX = its left edge,
; in pixels from the grid's
sh_vcx:
    push bx
    push cx
    mov cx, ax
    xor ax, ax
    xor bx, bx
.l:
    jcxz .d
    add al, [sh_vcw + bx]
    adc ah, 0
    inc bx
    dec cx
    jmp short .l
.d:
    mov cl, 3
    shl ax, cl
    pop cx
    pop bx
    ret

; sh_vwidth - in: AX = a visible column; out: AX = its width in pixels
sh_vwidth:
    push bx
    mov bx, ax
    mov al, [sh_vcw + bx]
    xor ah, ah
    push cx
    mov cl, 3
    shl ax, cl
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; FREEZE PANES (81.70). A visible column/row index (0..sh_vcols/vrows-1) no
; longer means [sh_scrollcol/row + index] once sh_freezecol/row is nonzero:
; sh_geom lays sh_vcw/sh_vrh out as the frozen prefix (real columns/rows
; 0..freeze-1, always shown) followed by the scrolling suffix (real
; sh_scrollcol/row and up). sh_vreal_col/row is that mapping; sh_vclip_col/
; row is its inverse for clamping a REAL range (a selection, a damage rect)
; into visible-index space the way sh_updsel/sh_drawsel already needed to
; before freeze existed, just freeze-aware now.
; -----------------------------------------------------------------------------

; sh_vreal_col - in: AX = a visible column (0..sh_vcols-1); out: AX = the
; real column it shows.
;
; 81.73 made this a TABLE READ. It was arithmetic - the frozen prefix's index
; is its own real column, and past it the scrolling suffix picks up at
; sh_scrollcol - and a HIDDEN column ends that: the slots no longer march in
; step with the columns, so sh_geom records which real one each slot got and
; everything reads it back from here. It is the smaller routine of the two.
sh_vreal_col:
    push bx
    mov bx, ax
    shl bx, 1
    mov ax, [sh_vrc + bx]
    pop bx
    ret

; sh_vreal_row - the same, for rows
sh_vreal_row:
    push bx
    mov bx, ax
    shl bx, 1
    mov ax, [sh_vrr + bx]
    pop bx
    ret

; sh_vclip_col - in: AX = real c1, BX = real c2 (c1 <= c2). out: CF=1, AX =
; visible c1 (rounded UP into view), BX = visible c2 (rounded DOWN into
; view); CF=0 if the whole [c1,c2] is off-screen. A column short of
; sh_freezecol is always visible, at its own index; sh_updsel/sh_drawsel
; used to do this inline with a bare [sh_scrollcol] subtraction - this is
; that clamp, freeze-aware, factored out because now two axes' worth of
; caller need the identical shape
; -----------------------------------------------------------------------------
; sh_vclip - in: AX = lo, BX = hi (REAL indices, lo <= hi), SI = the slot
; table, CX = how many slots it holds. out: AX = the first slot whose real
; index lies in [lo,hi], BX = the last; CF=0 when no slot does.
;
; 81.73 made this a SCAN. Before hidden rows and columns it was arithmetic
; with each edge clamped, and it cannot be any more - the visible slots no
; longer march in step with the real indices. The scan is over at most
; SH_MAXVC = 80 entries and runs on a selection move, not per cell.
;
; A range that is ENTIRELY hidden answers CF=0, which is the right answer and
; the same one an off-screen range gives: there is nothing to draw either way.
; -----------------------------------------------------------------------------
sh_vclip:
    push dx
    push di
    mov [sh_vcl_lo], ax
    mov [sh_vcl_hi], bx
    mov word [sh_vcl_a], 0xFFFF
    xor di, di
.l:
    cmp di, cx
    jae .done
    mov bx, di
    shl bx, 1
    mov dx, [si + bx]
    cmp dx, [sh_vcl_lo]
    jb .next
    cmp dx, [sh_vcl_hi]
    ja .next
    cmp word [sh_vcl_a], 0xFFFF
    jne .setb
    mov [sh_vcl_a], di
.setb:
    mov [sh_vcl_b], di
.next:
    inc di
    jmp short .l
.done:
    cmp word [sh_vcl_a], 0xFFFF
    je .no
    mov ax, [sh_vcl_a]
    mov bx, [sh_vcl_b]
    pop di
    pop dx
    stc
    ret
.no:
    pop di
    pop dx
    clc
    ret

; sh_vclip_col / sh_vclip_row - in: AX = real c1/r1, BX = real c2/r2. out: the
; visible range, CF=0 when none of it shows
sh_vclip_col:
    push cx
    push si
    mov si, sh_vrc
    mov cx, [sh_vcols]
    call sh_vclip
    pop si
    pop cx
    ret

sh_vclip_row:
    push cx
    push si
    mov si, sh_vrr
    mov cx, [sh_vrows]
    call sh_vclip
    pop si
    pop cx
    ret

; sh_vreal_col - sh_vclip_col clamps a RANGE into view, this answers whether
; one already-real column (the border table's own stored key, in
; sh_drawborders' sparse walk) is showing at all
sh_vidx_col:
    push bx
    push cx
    xor bx, bx
    mov cx, [sh_vcols]
.l:
    jcxz .no
    cmp [sh_vrc + bx], ax
    je .yes
    add bx, 2
    dec cx
    jmp short .l
.yes:
    shr bx, 1
    mov ax, bx
    pop cx
    pop bx
    stc
    ret
.no:
    pop cx
    pop bx
    clc
    ret

; sh_vidx_row - the same, for rows
sh_vidx_row:
    push bx
    push cx
    xor bx, bx
    mov cx, [sh_vrows]
.l:
    jcxz .no
    cmp [sh_vrr + bx], ax
    je .yes
    add bx, 2
    dec cx
    jmp short .l
.yes:
    shr bx, 1
    mov ax, bx
    pop cx
    pop bx
    stc
    ret
.no:
    pop cx
    pop bx
    clc
    ret

; =============================================================================
; EDIT > UNDO (81.57). Excel 2.1's: ONE level, the last cell entry or the last
; command of the Edit menu or Data Sort, and Undo then offers Redo. What it
; cannot reverse - formats, names, notes, macros, a new document - ends it.
;
; A SNAPSHOT, not a log of changes: the cell array, the border table, the note
; table, the column widths and row heights, and the text arena's LENGTH - it is
; append-only, so cutting it back is all it takes to undo what was added to
; it. Taken into Undo's own claim (SH_CLAIM_UNDO_KB) before the command runs;
; a document too big for it cannot be undone ("Can't Undo"), the honest
; answer. Undo SWAPS the two, through the staging claim, so Redo is the same
; operation again.
;
; Layout in sh_undoseg, and in staging during a swap: SH_UD_HDR bytes of
; header - ncells, nbord, nnote, txtlen, ntbl - then the FOUR arrays and the
; 2048 bytes of widths and row heights (the height table carries its own
; count).
;
; 81.114.9 ADDED THE TABLE LIST, and it had to: without it, Undo of an Insert
; Row put the cells and the result-cell MARKS back where they were and left
; every table's stored RECTANGLE shifted - and Undo of an Edit > Clear that
; dropped a table restored the cells without the table. A half-restoring Undo
; is worse than none, because the user believes it.
; =============================================================================
SH_UD_HDR    equ 10
SH_UL_ENTRY  equ 0                     ; the labels, sh_ud_names' order
SH_UL_CUT    equ 1
SH_UL_PASTE  equ 2
SH_UL_CLEAR  equ 3
SH_UL_PSPEC  equ 4
SH_UL_PLINK  equ 5
SH_UL_DEL    equ 6
SH_UL_INS    equ 7
SH_UL_FILLR  equ 8
SH_UL_FILLD  equ 9
SH_UL_SORT   equ 10
SH_UL_PARSE  equ 12                    ; 81.82: Data > Parse, which overwrites
                                       ; the cells to the right and so is
                                       ; exactly what Undo is for
SH_UL_JUST   equ 11                    ; 81.81: Format > Justify, and the
                                       ; Reference Guide names Undo as the way
                                       ; back from an overwrite, so it is one
                                       ; of the reversible ones and not a DROP
SH_UL_KEEP   equ 0xFE                  ; sh_ud_kind: changes nothing Undo holds
SH_UL_DROP   equ 0xFF                  ; ...or changes what it cannot reverse
sh_ud_names:  dw sh_ud_n0, sh_ud_n1, sh_ud_n2, sh_ud_n3, sh_ud_n4, sh_ud_n5
              dw sh_ud_n6, sh_ud_n7, sh_ud_n8, sh_ud_n9, sh_ud_n10
              dw sh_ud_n11, sh_ud_n12
sh_ud_n0:     db 'Entry', 0
sh_ud_n1:     db 'Cut', 0
sh_ud_n2:     db 'Paste', 0
sh_ud_n3:     db 'Clear', 0
sh_ud_n4:     db 'Paste Special', 0
sh_ud_n5:     db 'Paste Link', 0
sh_ud_n6:     db 'Delete', 0
sh_ud_n7:     db 'Insert', 0
sh_ud_n8:     db 'Fill Right', 0
sh_ud_n9:     db 'Fill Down', 0
sh_ud_n10:    db 'Sort', 0
sh_ud_n11:    db 'Justify', 0
sh_ud_n12:    db 'Parse', 0
sh_ud_sundo:  db 'Undo ', 0
sh_ud_sredo:  db 'Redo ', 0
sh_ud_cant:   db MENU_DIS, "Can't Undo", 0
; sh_fdlg_apply's kinds: Number Align Font Insert Delete ColW RowH Clear New
; Calc Sort Gallery SaveFmt PasteSpecial Protection
sh_ud_kind:   db SH_UL_DROP, SH_UL_DROP, SH_UL_DROP, SH_UL_INS, SH_UL_DEL
              db SH_UL_DROP, SH_UL_DROP, SH_UL_CLEAR, SH_UL_DROP, SH_UL_KEEP
              db SH_UL_SORT, SH_UL_KEEP, SH_UL_KEEP, SH_UL_PSPEC, SH_UL_DROP
              db SH_UL_DROP, SH_UL_DROP    ; 81.71: Extract WRITES cells, and
                                             ; 81.72's Series does too
                                             ; the Reference Guide says Undo
                                             ; cannot reverse it - so DROP,
                                             ; which is Undo saying so
sh_ud_kind_end:                        ; one entry per sh_fdlg kind: asserted
                                       ; beside SH_FDK_N, which is defined later

; sh_undo_begin - AL = the label. Snapshot the document into Undo's claim and
; mark the command in progress, so sh_commit does not take one of its own
sh_undo_begin:
    push ax
    push dx
    mov byte [sh_ud_busy], 1
    mov [sh_ud_lab], al
    mov dx, [sh_undoseg]
    or dx, dx
    jz .no
    call sh_undo_save                  ; CF=1: too big for it
    jc .no
    mov byte [sh_ud_redo], 0
    call sh_undo_label
    jmp short .out
.no:
    call sh_undo_drop
.out:
    pop dx
    pop ax
    ret

sh_undo_end:
    mov byte [sh_ud_busy], 0
    ret

; sh_undo_drop - nothing to undo: "Can't Undo", greyed
sh_undo_drop:
    push si
    push di
    mov si, sh_ud_cant
    mov di, sh_it_undo
    call sh_strcpy
    pop di
    pop si
    ret

; sh_undo_label - "Undo <action>" or "Redo <action>", enabled
sh_undo_label:
    push ax
    push bx
    push si
    push di
    mov si, sh_ud_sundo
    cmp byte [sh_ud_redo], 0
    je .u
    mov si, sh_ud_sredo
.u:
    mov di, sh_it_undo
    call sh_strcpy
    mov di, sh_it_undo
.end:
    cmp byte [di], 0
    je .cat
    inc di
    jmp short .end
.cat:
    mov bl, [sh_ud_lab]
    xor bh, bh
    shl bx, 1
    mov si, [sh_ud_names + bx]
    call sh_strcpy
    pop di
    pop si
    pop bx
    pop ax
    ret

; sh_undo_size - out: AX = the bytes a snapshot of the document takes, CF=1
; when that is more than Undo's claim holds
sh_undo_size:
    push dx
    mov ax, [sh_ncells]
    mov dx, SH_C_SZ
    mul dx
    jc .big
    push ax
    mov ax, [sh_nbord]
    mov dx, SH_BT_SZ
    mul dx
    pop dx
    add ax, dx
    jc .big
    push ax
    mov ax, [sh_nnote]
    mov dx, SH_NOTE_REC
    mul dx
    pop dx
    add ax, dx
    jc .big
    push ax
    mov ax, [sh_ntbl]                  ; 81.114.9
    mov dx, SH_T_SZ
    mul dx
    pop dx
    add ax, dx
    jc .big
    add ax, SH_UD_HDR + 2048
    jc .big
    cmp ax, SH_CLAIM_UNDO_KB * 1024
    ja .big
    clc
    pop dx
    ret
.big:
    stc
    pop dx
    ret

; sh_fcopy - CX bytes from AX:SI to DX:DI, forward. SI and DI advance.
sh_fcopy:
    push ds
    push es
    mov es, dx
    mov ds, ax
    cld
    rep movsb
    pop es
    pop ds
    ret

; sh_undo_save - the live document into segment DX at offset 0.
; CF=1 when it does not fit Undo's claim, and nothing is written
sh_undo_save:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    call sh_undo_size
    jc .out
    mov es, dx
    mov ax, [sh_ncells]
    mov [es:0], ax
    mov ax, [sh_nbord]
    mov [es:2], ax
    mov ax, [sh_nnote]
    mov [es:4], ax
    mov ax, [sh_txtlen]
    mov [es:6], ax
    mov ax, [sh_ntbl]                  ; 81.114.9
    mov [es:8], ax
    mov di, SH_UD_HDR
    mov ax, [sh_ncells]                ; every length from OUR bss before any
    mov bx, SH_C_SZ                    ; segment register moves (the lesson of
    push dx                            ; the DS-switch hang)
    mul bx
    pop dx
    mov cx, ax
    mov ax, [sh_cellseg]
    xor si, si
    call sh_fcopy
    mov ax, [sh_nbord]
    mov bx, SH_BT_SZ
    push dx
    mul bx
    pop dx
    mov cx, ax
    mov ax, [sh_bordseg]
    xor si, si
    call sh_fcopy
    mov ax, [sh_nnote]
    mov bx, SH_NOTE_REC
    push dx
    mul bx
    pop dx
    mov cx, ax
    mov ax, [sh_noteseg]
    xor si, si
    call sh_fcopy
    mov ax, [sh_ntbl]                  ; 81.114.9: ...and the table list
    mov bx, SH_T_SZ
    push dx
    mul bx
    pop dx
    mov cx, ax
    mov ax, [sh_tblseg]
    xor si, si
    call sh_fcopy
    mov cx, 2048                       ; the widths and the row heights, from
    mov ax, [sh_noteseg]               ; the same claim's top (81.60)
    mov si, SH_COLW_OFF
    call sh_fcopy
    clc
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_undo_load - segment AX at offset 0 back into the live document
sh_undo_load:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov es, ax
    mov bx, [es:0]
    mov [sh_ncells], bx
    mov bx, [es:2]
    mov [sh_nbord], bx
    mov bx, [es:4]
    mov [sh_nnote], bx
    mov bx, [es:6]
    mov [sh_txtlen], bx
    mov bx, [es:8]                     ; 81.114.9
    mov [sh_ntbl], bx
    mov si, SH_UD_HDR
    push ax
    mov ax, [sh_ncells]
    mov bx, SH_C_SZ
    mul bx
    mov cx, ax
    pop ax
    mov dx, [sh_cellseg]
    xor di, di
    call sh_fcopy
    push ax
    mov ax, [sh_nbord]
    mov bx, SH_BT_SZ
    mul bx
    mov cx, ax
    pop ax
    mov dx, [sh_bordseg]
    xor di, di
    call sh_fcopy
    push ax
    mov ax, [sh_nnote]
    mov bx, SH_NOTE_REC
    mul bx
    mov cx, ax
    pop ax
    mov dx, [sh_noteseg]
    xor di, di
    call sh_fcopy
    push ax                            ; 81.114.9
    mov ax, [sh_ntbl]
    mov bx, SH_T_SZ
    mul bx
    mov cx, ax
    pop ax
    mov dx, [sh_tblseg]
    xor di, di
    call sh_fcopy
    mov cx, 2048
    mov dx, [sh_noteseg]
    mov di, SH_COLW_OFF
    call sh_fcopy
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_undo_do - Edit > Undo (or Redo): the live document and the snapshot
; change places, through the staging claim, so doing it again redoes it
sh_undo_do:
    push ax
    push cx
    push dx
    push si
    push di
    mov dx, [sh_undoseg]
    or dx, dx
    jz .out
    mov byte [sh_editing], 0           ; an edit in progress is abandoned, as
                                       ; Excel's Undo abandons one - committing
                                       ; it would snapshot over the snapshot
    mov dx, [sh_stgseg]                ; now -> staging
    call sh_undo_save
    jc .out                            ; it has outgrown Undo: leave both
    call sh_undo_size                  ; ...measured NOW, before the load
    push ax                            ; changes the counts it is made of
    push word [sh_txtlen]              ; the live arena's end, because the
    mov ax, [sh_undoseg]               ; the snapshot -> live
    call sh_undo_load
    pop ax                             ; arena is not in the snapshot: the
    cmp ax, [sh_txtlen]                ; end stays at the larger of the two,
    jbe .txtok                         ; so a slot claimed after this cannot
    mov [sh_txtlen], ax                ; land on bytes the other side holds
.txtok:
    pop cx                             ; staging -> the snapshot: what live was
    push ds
    push es
    mov es, [sh_undoseg]
    mov ds, [sh_stgseg]
    xor si, si
    xor di, di
    cld
    rep movsb
    pop es
    pop ds
    xor byte [sh_ud_redo], 1
    call sh_undo_label
    inc word [sh_pass]                 ; every formula recomputes against what
    mov byte [sh_commitdirty], 1       ; is there now
    mov byte [sh_chartdirty], 1
    call sh_geom
    mov si, [sh_ownwin]
    call sh_repaint
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop ax
    ret

; =============================================================================
; Callbacks
; =============================================================================

; -----------------------------------------------------------------------------
; sh_note_arg - take the document this instance was launched with, if any.
; OSAPI_ARG_FILE is READ-AND-CLEAR (SPEC.md 54.5), so asking once here spends
; it and a later instance can never inherit it.
;
; THIS COPIES A NAME AND TOUCHES NO DISK, and that is the whole point of
; splitting it from sh_deferred_ld. A floppy read inside the entry proc runs
; under the LOADER LOCK and freezes the desktop (SPEC.md 69.6) - texpad's own
; ARG_FILE note carries the same warning, having paid for it.
; -----------------------------------------------------------------------------
sh_note_arg:
    push ax
    push bx                           ; ARG_FILE answers in BL, and the entry
    push cx                           ; proc that calls this has not banked BX
    push dx
    push si
    push di
    push es
    call OSAPI_ARG_FILE
    jc .none                          ; CF=1 = launched empty, the usual case
    mov [sh_argdir], dx
    mov [sh_argdrv], bl
    mov ax, KERNEL_SEG                ; the name lives in the KERNEL's segment,
    mov es, ax                        ; not ours
    mov di, sh_name
    mov cx, SH_FNAME_MAX
.cp:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .named
    inc si
    inc di
    loop .cp
    mov byte [di], 0
.named:
    mov byte [sh_needld], 1
.none:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_deferred_ld - and NOW the disk read, from the first paint, which happens
; after the window is up and the loader lock is long gone. Clears the flag
; first, so a read that fails is not retried on every repaint for the rest of
; the session.
; -----------------------------------------------------------------------------
sh_deferred_ld:
    push ax
    push bx
    push cx
    push dx
    push si                           ; sh_paint takes SI as its window ptr
    push di                           ; the instruction after this returns -
    push es                           ; OSAPI_FILE_GOTO_QM answers in AX and,
    mov byte [sh_needld], 0           ; on a redirected volume, hands CX, SI
                                      ; and DI to the driver (SPEC.md 62.9.1)
    mov dx, [sh_argdir]               ; Stand in the document's folder QUIETLY
    mov bl, [sh_argdrv]               ; and move the instance with it: nothing
    call OSAPI_FILE_GOTO_QM           ; here lists the folder, so the remount's
                                      ; scan, sort and icon harvest were ~0.5 s
                                      ; of floppy bought for no reader
                                      ; (docs/plans/NAV-COST-PLAN.md, SPEC.md
                                      ; 19.9.1). sh_doread's by-name read then
                                      ; resolves in the instance's folder,
                                      ; which is now this one.
    jc .out                           ; could not stand there, and NOTHING
    call sh_doread                    ; moved: sh_name would resolve in the
.out:                                 ; package's own folder and could find a
    pop es                            ; same-named stranger - leave the sheet
                                      ; empty rather than read the wrong file
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

sh_paint:
    push bx
    cmp byte [sh_needld], 0           ; the associated document lands HERE, so
    je .nold                          ; it is on screen at the first paint
    call sh_deferred_ld               ; instead of waiting for a key or click
.nold:
    mov bx, si
    call sh_geom
    call sh_drawall
    cmp byte [sh_abon], 0             ; ...and the About card LAST, over the
    je .noab                          ; grid it is opaque about (SPEC.md 20.5.1)
    push si
    mov bx, si
    mov si, sh_ablines
    call os88ui_about_d               ; _d: this paint's region is already armed
    pop si
.noab:
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_repaint - SI = this window, the gfx lock held: the whole content again.
;
; IT ARMS ITS OWN CLIP REGION (81.105, upstream issue #152). Almost none of its
; fifty callers is a W_PAINT - they are menu commands, dialog applies and edit
; paths, which arrive with NO region armed (SPEC.md 11.3) - so the fill and
; every glyph went onto the glass wherever they landed, over any window
; stacked above SHEET. The Chart window is the one that shows it: shown, then
; painted, then SHEET repainted UNDER it and over it, and 11.96's raise cache
; banked the damage and carried it along on the next drag. One arm HERE, not
; one per call site, so the fifty-first caller cannot forget.
;
; ...AND CLEARS IT the moment SHEET's own content is down. A region lives to
; the next GFX_UNLOCK, and what these callers draw next is not SHEET's
; content: the Chart window below (on top of SHEET, and repainted only when
; wholly uncovered), a dialog, the pulldown hanging past the window. Clipped
; to SHEET's region they would vanish. So only SHEET's own drawing is
; clipped, and everything after runs exactly as it did. No caller is a
; W_PAINT (a paint's region is the kernel's; walked, 81.105), so the clear
; drops nothing it was handed. Wholly covered: nothing of SHEET is drawn, and
; the chart and the caption still get their turn
; -----------------------------------------------------------------------------
sh_repaint:
    push ax
    push bx
    push cx
    push dx
    mov bx, si
    call sh_geom
    call OSAPI_WM_CLIP_SET              ; BX = this window: CF = 1 not one
    jc .covered                         ; pixel of it is visible
    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov ax, [sh_ox]
    mov bx, [sh_oy]
    mov cx, [sh_ox]
    add cx, [sh_cw]
    dec cx
    mov dx, [sh_oy]
    add dx, [sh_ch]
    dec dx
    call OSAPI_GFX_FILL
    call sh_drawall
    call OSAPI_WM_CLIP_CLEAR
.covered:
    cmp word [sh_chartwin], 0           ; stage 2.x: keep the live Chart Column
    je .nochart                         ; window in sync with every data-
    cmp byte [sh_chartdirty], 0         ; changing command that already routes
    je .nochart                         ; through sh_repaint - and ONLY those:
    push bx                            ; sh_addcell/sh_removecell set the dirty
    mov bx, [sh_chartwin]              ; byte, so a selection move, an edit
    call OSAPI_WM_OBSCURED              ; keystroke or a scroll (which change no
    jc .chartobscured                   ; cell) skips the re-scan and the whole
    call sh_chart_scan                  ; 240x160 re-raster. Skipped too while
    call sh_chart_render                ; nobody can see it (also covers
    mov si, [sh_chartwin]               ; "hidden via its own close box", which
    call sh_chart_paint                 ; only hides it - see sh_docmd_chart's
    mov byte [sh_chartdirty], 0         ; window-lifecycle comment); the byte
                                         ; then STAYS set, so the first repaint
                                         ; with the chart visible resyncs it.
                                         ; sh_chart_scan is what re-reads the
                                         ; charted column's current values;
                                         ; sh_chart_render re-rasterizes them.
.chartobscured:
    pop bx
.nochart:
    call sh_title_sync                  ; 81.103: Open, Save As, New and the
    pop dx                              ; macro file commands all end here - an
    pop cx                              ; EVENT, as 11.92 asks, never a paint
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_title_sync - the window's caption says which document this is (81.103):
; "Sheet - <sh_name>", Word's "Microsoft Word - <NAME>" convention. Composes
; [sh_ttlbuf] only when it no longer matches [sh_name], and then tells the
; kernel (OSAPI_WM_TITLE, AX = 0: "the bytes W_TITLE names changed"), which
; redraws the 17-row strip and nothing else. Before the window exists
; ([sh_ownwin] 0, the entry proc) it composes and tells nobody. Needs the
; gfx lock when a window exists: sh_repaint's callers hold it. NOT FROM
; sh_paint - 11.92: a caption changes on an event and never on a paint, and
; wm_title_set's own clip handling would disarm a paint's armed region.
; Preserves all registers
; -----------------------------------------------------------------------------
SH_TTL_PRE  equ 8                       ; "Sheet - "
sh_title_sync:
    push ax
    push bx
    push si
    push di
    mov si, sh_name
    mov di, sh_ttlbuf + SH_TTL_PRE
    cmp byte [sh_ttlbuf], 0             ; never composed: the entry's call
    je .compose
.cmp:
    mov al, [si]
    cmp al, [di]
    jne .compose
    inc si
    inc di
    or al, al
    jnz .cmp
    jmp short .out                      ; unchanged: no strip redrawn
.compose:
    mov si, sh_ttl_pre
    mov di, sh_ttlbuf
    call sh_strcpy
    mov si, sh_name
    mov di, sh_ttlbuf + SH_TTL_PRE
    call sh_strcpy
    mov bx, [sh_ownwin]
    or bx, bx
    jz .out
    xor ax, ax
    call OSAPI_WM_TITLE
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret
sh_ttl_pre:    db 'Sheet - ', 0

; -----------------------------------------------------------------------------
; sh_onclick - W_ONCLICK: CX=x, DX=y (screen), SI=window; gfx lock held
; -----------------------------------------------------------------------------
sh_onclick:
    push ax
    push bx
    push cx
    push dx
    call sh_macro_gate                 ; 81.86
    jc .out
    call sh_abdismiss                  ; the credits are up: this click is
    jc .out                            ; spent taking them down
    cmp word [sh_fdlg_win], 0
    je .nofdlg
    call sh_fdlg_close_r                 ; stage 1.8: a Format dialog isn't
                                        ; kernel-modal (no fdlg_grab/fdlg_top
                                        ; machinery outside the kernel - see
                                        ; the section comment above
                                        ; sh_fdlg_open), so a click that
                                        ; reaches the main grid at all means
                                        ; the dialog visually lost focus;
                                        ; treat it as Cancel rather than
                                        ; leave sh_fdlg_win stuck non-zero,
                                        ; which would gate every future
                                        ; Format menu command shut for good
.nofdlg:
    cmp word [sh_bdlg_win], 0          ; same non-modal gate-lock risk, same
    je .nobdlg                         ; recovery, for the Border dialog
    call sh_bdlg_close_r
.nobdlg:
    cmp word [sh_df_win], 0            ; 81.71.5: and for Data ▸ Form, which
    je .nodf                           ; would otherwise gate that item shut
    call sh_df_close_r                 ; for the rest of the session
.nodf:
    mov word [sh_msg], 0
    mov bx, si                         ; the geometry first: a dragged window
    call sh_geom                       ; is put back with no W_PAINT
    mov byte [sh_rz_on], 0             ; 81.73.2: a press on a heading's own
    call sh_hdrhit                     ; trailing edge is a RESIZE and not a
    jnc .norz                          ; selection, so it is asked first and
    mov byte [sh_rz_on], 1             ; owns the whole gesture
    jmp .out
.norz:
    mov byte [sh_dragging], 0          ; stage 3.0a: a gesture is only a grid
                                        ; drag if it STARTS on the grid - the
                                        ; menu-bar path below never arms it
    call sh_mbar_hit                   ; stage 2.x: Sheet's own in-window
    cmp al, SH_M_NONE                  ; menu bar (see the SH_MBAR_H section
    je .notmenu                        ; comment) claims a click on its strip
    call sh_mtrack                     ; before anything below ever sees it -
    jmp .out                           ; AL=menu index (from sh_mbar_hit),
                                        ; SI=window (still this callback's own
                                        ; untouched SI)
.notmenu:
    call sh_sbclick                    ; stage 3.0a+: the two scroll bars get
    jc .out                            ; the click before the grid does
    call sh_gridhit                    ; CX=x, DX=y -> CF=1 + AX=col, BX=row
    jnc .out
    call sh_shiftdown                  ; stage 3.0a: shift+click extends the
    jc .extend                         ; range from the existing anchor
    call sh_select                     ; plain click: collapse and move
    mov byte [sh_dragging], 1          ; ...and arm the drag from here
    push ax
    mov ax, [sh_selcol]
    mov [sh_drag_col], ax
    mov ax, [sh_selrow]
    mov [sh_drag_row], ax
    pop ax
    jmp .out
.extend:
    call sh_select_to
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_select - commit any pending edit, move the selection, scroll to show
; it, and repaint. AX = new column, BX = new row. SI must be the window
; ptr; not touched here so it stays that way for sh_repaint.
; -----------------------------------------------------------------------------
sh_select:
    push ax
    push bx
    mov word [sh_tabanchor], 0       ; ANY other move ends a Tab run - only the
    call sh_selbank                  ; Tab arm puts the anchor back afterwards
    call sh_commit
    mov [sh_selcol], ax
    mov [sh_selrow], bx
    mov [sh_selcol2], ax               ; stage 3.0a: a plain select COLLAPSES
    mov [sh_selrow2], bx               ; the range - anchor and extent become
                                        ; the same cell, which is exactly the
                                        ; old single-cell behaviour every
                                        ; existing caller still expects
    call sh_scrollto
    call sh_selpaint                   ; only what the move dirtied - the full
                                        ; repaint costs ~1s on a 4.77MHz 8088
                                        ; and this path runs per arrow key
    call sh_rec_sel                    ; 81.74: ...and the recorder's SELECT,
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_select_to - stage 3.0a: move only the EXTENT of the range, leaving the
; anchor where it is. AX = column, BX = row. Used by shift+click, shift+arrows
; and the drag handler. SI must be the window ptr (sh_repaint's contract).
;
; Deliberately does NOT call sh_commit: extending a selection is not a
; different-cell move, and committing here would end an in-progress edit
; halfway through a drag.
; -----------------------------------------------------------------------------
sh_select_to:
    push ax
    push bx
    call sh_selbank
    cmp ax, SH_COLS
    jb .colok
    mov ax, SH_COLS - 1
.colok:
    cmp bx, SH_ROWS
    jb .rowok
    mov bx, SH_ROWS - 1
.rowok:
    mov [sh_selcol2], ax
    mov [sh_selrow2], bx
    call sh_scrollto2
    call sh_selpaint
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_selbank - bank the rect and the scroll origin a selection move starts
; from, so sh_selpaint can price the damage afterwards. Preserves everything.
; -----------------------------------------------------------------------------
sh_selbank:
    push ax
    call sh_selrect
    mov ax, [sh_selc1]
    mov [sh_oldc1], ax
    mov ax, [sh_selc2]
    mov [sh_oldc2], ax
    mov ax, [sh_selr1]
    mov [sh_oldr1], ax
    mov ax, [sh_selr2]
    mov [sh_oldr2], ax
    mov ax, [sh_scrollcol]
    mov [sh_oldscol], ax
    mov ax, [sh_scrollrow]
    mov [sh_oldsrow], ax
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_selpaint - repaint after a selection move: as little of the window as
; the move actually dirtied. SI = the window (sh_repaint's own contract).
;
; The full repaint is ~1s on the target (PERFORMANCE.md's own table: one
; OSAPI_FONT_RUN per visible cell, plus all the chrome, plus a recalc pass),
; and this path runs once per keystroke-repeat and per drag packet - so it
; pays that price only when it must:
;   * sh_commit stored something -> full, because a dependent formula
;     anywhere on screen may now show a new value and only sh_drawall's
;     pass advance re-evaluates them;
;   * the view scrolled by rows only -> blit the surviving rows
;     (sh_scrollrow_blit) and letter just the vacated ones;
;   * by columns only -> the grid and its column half, nothing else
;     (sh_scrollcol_part - OSAPI_GFX_SCROLL is vertical-only, SPEC.md 5.5);
;   * no scroll at all -> the old cells and the new ones (sh_updsel).
; -----------------------------------------------------------------------------
sh_selpaint:
    push ax
    push cx
    cmp byte [sh_commitdirty], 0
    jne .full
    mov ax, [sh_oldscol]
    cmp ax, [sh_scrollcol]
    jne .cols
    mov cx, [sh_oldsrow]
    cmp cx, [sh_scrollrow]
    jne .rows
    call sh_updsel
    jmp .out
.rows:
    call sh_scrollrow_blit             ; CX = the row the view is leaving
    jc .full                           ; refused: pay the full price
    call sh_updsel                     ; old cells + new cells + the bars
    jmp .out
.cols:
    mov cx, [sh_oldsrow]
    cmp cx, [sh_scrollrow]
    jne .full                          ; both axes moved: a Goto, not a walk
    call sh_scrollcol_part
    call sh_drawbar                    ; the reference box changed too
    call sh_drawstatus
    jmp .out
.full:
    mov byte [sh_commitdirty], 0
    call sh_repaint
.out:
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_updsel - the no-scroll damage path: redraw the union of the old and the
; new selection rects (which covers both frames), then the two bars whose
; text names the selection. SI = the window.
; -----------------------------------------------------------------------------
sh_updsel:
    push ax
    push bx
    push cx
    push dx
    mov bx, si
    call sh_geom
    cmp word [sh_vcols], 0
    je .chrome
    cmp word [sh_vrows], 0
    je .chrome
    call sh_selrect                    ; the NEW rect, ordered
    mov ax, [sh_selc1]                 ; the union's columns...
    cmp ax, [sh_oldc1]
    jbe .c1
    mov ax, [sh_oldc1]
.c1:
    mov bx, [sh_selc2]
    cmp bx, [sh_oldc2]
    jae .c2
    mov bx, [sh_oldc2]
.c2:
    call sh_vclip_col                  ; 81.70: real range -> visible-index
    jnc .chrome                        ; range, frozen-aware; CF=0 = wholly
    mov [sh_dmgc1], ax                 ; off-screen (what the old inline
    mov [sh_dmgc2], bx                 ; [sh_scrollcol] clamp used to do)
    mov ax, [sh_selr1]                 ; the union's rows, the same
    cmp ax, [sh_oldr1]
    jbe .r1
    mov ax, [sh_oldr1]
.r1:
    mov bx, [sh_selr2]
    cmp bx, [sh_oldr2]
    jae .r2
    mov bx, [sh_oldr2]
.r2:
    call sh_vclip_row
    jnc .chrome
    mov [sh_dmgr1], ax
    mov [sh_dmgr2], bx
    call sh_dmgdraw
    call sh_drawsel
.chrome:
    call sh_drawbar
    call sh_drawstatus
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_gridhit - stage 3.0a: which cell is this screen point on?
; in:  CX = x, DX = y (screen coords, W_ONCLICK/W_ONDRAG's own)
; out: CF=1 and AX = column, BX = row (both absolute, scroll-adjusted);
;      CF=0 if the point is not over a grid cell. CX/DX restored.
;
; Lifted verbatim out of sh_onclick so the drag handler hit-tests exactly the
; same way a click does - two copies of this arithmetic would drift the first
; time the header or menu-bar height changed.
; -----------------------------------------------------------------------------
sh_gridhit:
    push cx
    push dx
    mov ax, cx
    sub ax, [sh_ox]
    sub ax, SH_RH_W
    js .no
    mov bx, dx
    sub bx, [sh_goy]                   ; grid origin, NOT raw content origin -
    sub bx, SH_FB_H + SH_CH_H          ; the menu bar strip sits above it
    js .no
    mov dx, ax                         ; DX = pixels into the grid: walked
    xor cx, cx                         ; across the columns' own widths (81.56)
.hwalk:
    cmp cx, [sh_vcols]
    jae .no
    mov ax, cx
    call sh_vwidth
    cmp dx, ax
    jb .hcol
    sub dx, ax
    inc cx
    jmp short .hwalk
.hcol:
    mov ax, cx
    call sh_vreal_col                  ; 81.70: frozen or scrolling, the
    mov [sh_wcol], ax                  ; visible->real mapping is the same
    xor cx, cx                         ; ...and down the rows' own heights
.vwalk:                                ; (81.60), BX = pixels into the grid
    cmp cx, [sh_vrows]
    jae .no
    mov ax, cx
    call sh_vheight
    cmp bx, ax
    jb .vrow
    sub bx, ax
    inc cx
    jmp short .vwalk
.vrow:
    mov ax, cx
    call sh_vreal_row
    mov bx, ax
    mov ax, [sh_wcol]
    pop dx
    pop cx
    stc
    ret
.no:
    pop dx
    pop cx
    clc
    ret

; -----------------------------------------------------------------------------
; sh_flkey - stage 3.0b: hand one keystroke to the formula bar's field, then
; resync this app's own sh_editlen from the field's LN_LEN so sh_commit and
; every other existing reader keeps working unchanged.
; in: AL = ascii, AH = scan.
;
; REDRAWS ONLY THE FIELD. An editing keystroke changes no cell, so the full
; sh_repaint this used to end with - every visible cell re-lettered plus a
; recalc pass, ~1s per keystroke on a 4.77MHz 8088 - repainted identical
; pixels and dropped keys on the target. os88line_draw is one opaque run
; plus the strip past the text; sh_flmarg covers the one span it does not.
; -----------------------------------------------------------------------------
sh_flkey:
    push ax
    push si
    call sh_flrect                     ; the box may have moved since the last
                                        ; draw - os88line hit-tests and draws
                                        ; from the same four words
    mov si, sh_fline
    call os88line_key
    mov ax, [si + LN_LEN]
    mov [sh_editlen], al               ; LN_LEN is a word and SH_EDITMAX is
                                        ; 63, so the low byte is the whole of
                                        ; it - but keep them in step, because
                                        ; sh_commit still reads sh_editlen
    call sh_flmarg
    call os88line_draw
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_flmarg - white the strip between the content box's frame and os88line's
; 8-aligned pen. The field's own draw covers its run and the strip PAST the
; text (os88line_draw's header), so this margin is the one span neither
; touches - and on the first keystroke of an edit it still holds the leftmost
; pixels of the static text sh_drawbar drew there. SI = sh_fline, whose rect
; sh_flrect has already refreshed. Preserves everything.
; -----------------------------------------------------------------------------
sh_flmarg:
    push ax
    push bx
    push cx
    push dx
    call os88line_pen
    mov cx, ax
    dec cx                             ; the margin's right edge...
    mov ax, [si + LN_X1]
    inc ax                             ; ...and its left, inside the frame
    cmp ax, cx
    jg .none
    mov bx, [si + LN_Y1]
    inc bx
    mov dx, [si + LN_Y2]
    dec dx
    cmp bx, dx
    jg .none
    push ax
    mov al, CWHITE
    call OSAPI_SET_COLOR
    pop ax
    call OSAPI_GFX_FILL
.none:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_flsync - stage 3.0b: the buffer was filled by someone other than the
; field (F2's seed-from-cell, or a Paste). Recompute the field's own length
; from the NUL and park the caret at the end, which is where a just-loaded
; value should leave it. Preserves everything.
; -----------------------------------------------------------------------------
sh_flsync:
    push ax
    push cx
    push si
    xor cx, cx
    mov si, sh_editbuf
.cnt:
    cmp byte [si], 0
    je .done
    cmp cx, SH_EDITMAX                 ; never trust an unterminated buffer
    jae .done
    inc si
    inc cx
    jmp .cnt
.done:
    mov [sh_editlen], cl
    mov si, sh_fline
    mov [si + LN_LEN], cx
    mov [si + LN_CAR], cx              ; caret at the end
    mov word [si + LN_VIEW], 0
    mov byte [si + LN_FOCUS], 1
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_editstart - stage 3.0b: begin a fresh, EMPTY edit (the first character
; typed into a cell). Resets both this app's own edit state and the field's.
; -----------------------------------------------------------------------------
sh_editstart:
    push si
    mov byte [sh_editing], 1
    mov byte [sh_editlen], 0
    mov byte [sh_editbuf], 0
    mov si, sh_fline
    mov word [si + LN_LEN], 0
    mov word [si + LN_CAR], 0
    mov word [si + LN_VIEW], 0
    mov byte [si + LN_FOCUS], 1
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_arrowsrc - stage 3.0a: where does an arrow key start counting from?
; out: AX = column, BX = row - the ANCHOR normally, the EXTENT while shift is
; held, which is what makes shift+arrow grow the block from the end the user
; last moved rather than snapping it back to the anchor.
; -----------------------------------------------------------------------------
sh_arrowsrc:
    call sh_shiftdown
    jc .ext
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    ret
.ext:
    mov ax, [sh_selcol2]
    mov bx, [sh_selrow2]
    ret

; -----------------------------------------------------------------------------
; sh_shiftdown - out: CF=1 if either shift key is held. Preserves everything.
; 0x2A/0x36 are the set-1 make codes; kbd_down's map is 128 bits wide, one per
; make code, so it answers for any key and not just the named KSC_* few.
; -----------------------------------------------------------------------------
sh_shiftdown:
    push ax
    mov al, 0x2A                       ; left shift
    call OSAPI_KEY_DOWN
    jc .yes
    mov al, 0x36                       ; right shift
    call OSAPI_KEY_DOWN
    jc .yes
    pop ax                             ; pop leaves the flags alone
    clc
    ret
.yes:
    pop ax
    stc
    ret

; -----------------------------------------------------------------------------
; sh_ondrag - W_ONDRAG (SPEC.md 13.8.2): the pointer moved while our press was
; armed. CX = x, DX = y, SI = window; UI task, gfx lock held.
;
; REDRAWS ONLY ON A CHANGE, which the slot's own doc insists on: it fires per
; mouse packet, and a repaint per packet is tens of milliseconds each on a
; 4.77MHz machine. [sh_drag_col]/[sh_drag_row] hold the cell we last extended
; to, so sliding within one cell costs a hit-test and nothing else.
; -----------------------------------------------------------------------------
sh_ondrag:
    push ax
    push bx
    push cx
    push dx
    push si
    call sh_macro_gate                 ; 81.86
    jc .out
    ; 81.73.2: ...and a heading drag owns it before either of them, because
    ; it started on a press the selection never saw
    cmp byte [sh_rz_on], 0
    je .norz
    call sh_rz_track
    jmp .out
.norz:
    ; stage 3.0a+: a live scroll-thumb drag owns the gesture before the grid
    ; selection does.
    call sh_sbsync
    call os88ui_sbdragging
    jc .novthumb
    mov bx, sh_vsb
    call os88ui_sbtrack                ; DX = the pointer's y
    jc .out                            ; nothing owed (no move, or the rate)
    add ax, [sh_freezerow]             ; 81.70: the bar answers in its own
    call sh_setscrollrow               ; scrolling-region space (sh_sbsync
    jmp .out                           ; shifted pos/total/fit there); every
                                        ; sh_setscrollrow caller is absolute
.novthumb:
    cmp byte [sh_hsb_dragon], 0
    je .nohthumb
    mov bx, sh_hsb
    call sh_hsb_track                  ; CX = the pointer's x
    jc .out
    add ax, [sh_freezecol]             ; 81.70, the vertical bar's reason
    call sh_setscrollcol
    jmp .out
.nohthumb:
    cmp byte [sh_dragging], 0
    je .out                            ; this gesture did not start on the grid
    call sh_gridhit
    jnc .out                           ; slid off the grid: leave the range as
                                        ; it was rather than clamping wildly
    cmp ax, [sh_drag_col]
    jne .moved
    cmp bx, [sh_drag_row]
    je .out                            ; same cell as last packet - nothing
.moved:
    mov [sh_drag_col], ax
    mov [sh_drag_row], bx
    mov si, [sh_ownwin]                ; sh_repaint's SI contract
    call sh_select_to
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_selrect - stage 3.0a: normalize the anchor/extent pair into an ordered
; rect. Out: [sh_selc1] <= [sh_selc2], [sh_selr1] <= [sh_selr2]. Every range
; consumer reads these rather than comparing the raw pair itself, so "which
; corner did the user start from" is answered in exactly one place.
; -----------------------------------------------------------------------------
sh_selrect:
    push ax
    push bx
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .cols_ok
    xchg ax, bx
.cols_ok:
    mov [sh_selc1], ax
    mov [sh_selc2], bx
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .rows_ok
    xchg ax, bx
.rows_ok:
    mov [sh_selr1], ax
    mov [sh_selr2], bx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_selsingle - out: CF=1 if the selection is a single cell (anchor==extent).
; The gate every command that has no range semantics yet uses.
; -----------------------------------------------------------------------------
sh_selsingle:
    push ax
    mov ax, [sh_selcol]
    cmp ax, [sh_selcol2]
    jne .no
    mov ax, [sh_selrow]
    cmp ax, [sh_selrow2]
    jne .no
    stc
    jmp .out
.no:
    clc
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_scrollto - move the scroll origin the least amount that brings the
; current selection into the viewport described by [sh_vcols]/[sh_vrows]
; -----------------------------------------------------------------------------
sh_scrollto:
    push ax
    mov ax, [sh_selcol]
    mov [sh_sc_tcol], ax
    mov ax, [sh_selrow]
    mov [sh_sc_trow], ax
    pop ax
    jmp sh_scrollto_t

; stage 3.0a: the same scroll, aimed at the range's moving END instead of its
; anchor - what a drag or a shift+arrow needs, since it is the extent that
; walks off-screen, not the anchor.
sh_scrollto2:
    push ax
    mov ax, [sh_selcol2]
    mov [sh_sc_tcol], ax
    mov ax, [sh_selrow2]
    mov [sh_sc_trow], ax
    pop ax
    jmp sh_scrollto_t
; =============================================================================
; RESIZING A ROW OR COLUMN BY DRAGGING ITS HEADING (SPEC.md 81.73.2)
;
; A press within SH_RZ_GRAB pixels of a heading's trailing edge grabs it; the
; drag then sets the width or height LIVE and the release just lets go.
;
; LIVE, BUT ONLY IN WHOLE UNITS. A width is stored in CHARACTERS, so the grid
; is repainted once per 8 pixels of travel rather than once per mouse event -
; a full grid repaint is priced in primitive calls (PERFORMANCE.md), and one
; per pixel across a 56-pixel column is 56 of them where 7 is the same
; gesture. Excel 2.1 drew a guide line instead for exactly this reason; that
; needs an XOR line this app does not have, and stepping in whole units gets
; the feedback without one.
;
; DRAGGING IT SHUT HIDES IT, which is Excel's own behaviour and falls out of
; 81.73 rather than being built: no width IS the hidden sentinel's meaning.
; =============================================================================
SH_RZ_GRAB   equ 3                   ; pixels either side of the edge

; -----------------------------------------------------------------------------
; sh_hdrhit - in: CX,DX = a click. out: CF=1 when it grabbed a heading's
; trailing edge, with [sh_rz_axis] 0 = column / 1 = row, [sh_rz_idx] = the
; REAL row or column being resized, and [sh_rz_x0] the slot's LEADING edge.
; -----------------------------------------------------------------------------
sh_hdrhit:
    push ax
    push bx
    push dx
    mov ax, dx                         ; --- the COLUMN heading strip?
    sub ax, [sh_goy]
    sub ax, SH_FB_H
    js .rowstrip
    cmp ax, SH_CH_H
    jae .rowstrip
    mov ax, cx
    sub ax, [sh_ox]
    sub ax, SH_RH_W
    js .no
    mov [sh_rz_px], ax
    mov byte [sh_rz_axis], 0
    xor bx, bx
    xor dx, dx
.cw:
    cmp bx, [sh_vcols]
    jae .no
    mov ax, bx
    call sh_vwidth
    add dx, ax                         ; DX = this slot's TRAILING edge
    mov ax, [sh_rz_px]
    sub ax, dx
    jns .cpos
    neg ax
.cpos:
    cmp ax, SH_RZ_GRAB
    jbe .gotcol
    inc bx
    jmp short .cw
.gotcol:
    mov ax, bx
    call sh_vwidth
    sub dx, ax                         ; DX = this slot's LEADING edge
    mov ax, bx
    call sh_vreal_col
    mov [sh_rz_idx], ax
    jmp short .yes
.rowstrip:
    mov ax, cx                         ; --- or the ROW heading strip?
    sub ax, [sh_ox]
    js .no
    cmp ax, SH_RH_W
    jae .no
    mov ax, dx
    sub ax, [sh_goy]
    sub ax, SH_FB_H + SH_CH_H
    js .no
    mov [sh_rz_px], ax
    mov byte [sh_rz_axis], 1
    xor bx, bx
    xor dx, dx
.rw:
    cmp bx, [sh_vrows]
    jae .no
    mov ax, bx
    call sh_vheight
    add dx, ax
    mov ax, [sh_rz_px]
    sub ax, dx
    jns .rpos
    neg ax
.rpos:
    cmp ax, SH_RZ_GRAB
    jbe .gotrow
    inc bx
    jmp short .rw
.gotrow:
    mov ax, bx
    call sh_vheight
    sub dx, ax
    mov ax, bx
    call sh_vreal_row
    mov [sh_rz_idx], ax
.yes:
    mov [sh_rz_x0], dx                 ; the slot's leading edge, which the
    pop dx                             ; resize never moves: the size is the
    pop bx                             ; pointer less it, never added again
    pop ax
    stc
    ret
.no:
    pop dx
    pop bx
    pop ax
    clc
    ret

; -----------------------------------------------------------------------------
; sh_rz_track - CX,DX = the pointer. Sets the grabbed row or column to what
; the drag now says, in whole units, repainting only when it changed.
; -----------------------------------------------------------------------------
sh_rz_track:
    push ax
    push bx
    push cx
    push dx
    cmp byte [sh_rz_axis], 0
    jne .row
    mov ax, cx                         ; the pointer, in grid pixels...
    sub ax, [sh_ox]
    sub ax, SH_RH_W
    sub ax, [sh_rz_x0]                 ; ...less the leading edge: what the
    jle .cwzero                        ; pointer is asking for
    mov cl, 3
    shr ax, cl                         ; ...in whole characters
    or ax, ax
    jz .cwzero
    cmp ax, SH_CW_MAXCH
    jbe .cwhave
    mov ax, SH_CW_MAXCH
.cwhave:
    mov bx, ax
    mov ax, [sh_rz_idx]
    call sh_colwidth
    cmp ax, bx                         ; no WHOLE character changed: no paint
    je .out
    mov cl, bl
    cmp bx, [sh_defch]
    jne .cwstore
    xor cl, cl
.cwstore:
    mov ax, [sh_rz_idx]
    call sh_colw_set
    jmp short .redraw
.cwzero:
    mov ax, [sh_rz_idx]
    call sh_colwidth
    or ax, ax
    jz .out                            ; already shut
    mov cl, SH_CW_HIDDEN
    mov ax, [sh_rz_idx]
    call sh_colw_set
    jmp short .redraw
.row:
    mov ax, dx
    sub ax, [sh_goy]
    sub ax, SH_FB_H + SH_CH_H
    sub ax, [sh_rz_x0]
    jle .rzero
    cmp ax, SH_RH_MAX
    jbe .rhmin
    mov ax, SH_RH_MAX
.rhmin:
    cmp ax, SH_RH_MIN
    jae .rhhave
    mov ax, SH_RH_MIN                  ; a glyph still has to fit anything
.rhhave:                               ; that is not shut
    mov bx, ax
    mov ax, [sh_rz_idx]
    call sh_rowheight
    cmp ax, bx                         ; no whole PIXEL changed: no paint
    je .out
    mov ax, bx
    call sh_pxtw
    mov cx, ax
    mov ax, [sh_rz_idx]
    call sh_rowh_set
    jmp short .redraw
.rzero:
    mov ax, [sh_rz_idx]
    call sh_rowheight
    or ax, ax
    jz .out
    mov cx, SH_RH_HIDDEN
    mov ax, [sh_rz_idx]
    call sh_rowh_set
.redraw:
    push si
    mov si, [sh_ownwin]
    mov bx, si
    call sh_geom
    call sh_repaint
    pop si
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret



; the core: bring [sh_sc_tcol]/[sh_sc_trow] into the viewport, moving the
; scroll origin the least amount that does it
sh_scrollto_t:
    push ax
    push bx
    ; 81.73 made the "is it already on screen?" test ASK THE VIEWPORT rather
    ; than compute it. It used to be sh_scrollcol + the scrolling window's
    ; width, which is only the last visible column while the slots march in
    ; step with the columns - a hidden one anywhere between them breaks that,
    ; and sh_vidx_col is the routine that already knows.
    mov ax, [sh_sc_tcol]
    cmp ax, [sh_freezecol]             ; 81.70: the frozen prefix is always
    jb .rows                           ; visible - nothing to scroll for it,
                                        ; and sh_scrollcol may never go there
    call sh_vidx_col
    jc .rows                           ; already showing: leave the view alone
    mov ax, [sh_sc_tcol]
    cmp ax, [sh_scrollcol]
    jae .cfwd
    mov [sh_scrollcol], ax             ; it is to the LEFT: scroll onto it
    jmp short .rows
.cfwd:
    call sh_backcols                   ; to the RIGHT: walk back from it until
    mov [sh_scrollcol], ax             ; the window is full (81.56 - the
                                        ; columns are not one width, so this
                                        ; is walked and not subtracted)
.rows:
    mov ax, [sh_sc_trow]
    cmp ax, [sh_freezerow]
    jb .out
    call sh_vidx_row
    jc .out
    mov ax, [sh_sc_trow]
    cmp ax, [sh_scrollrow]
    jae .rfwd
    mov [sh_scrollrow], ax
    jmp short .out
.rfwd:
    call sh_backrows                   ; nor the rows one height (81.60)
    mov [sh_scrollrow], ax
.out:
    pop bx
    pop ax
    ret

; sh_frozencw - out: AX = the frozen columns' (0..sh_freezecol-1) total
; pixel width, summed fresh via sh_colwidth rather than read from sh_vcw -
; that cache can be one repaint stale for the very columns whose width just
; changed (Format > Column Width), and this runs off a selection move,
; which does not itself imply sh_geom has run since
sh_frozencw:
    push bx
    push cx
    push dx
    xor dx, dx
    xor bx, bx
.l:
    cmp bx, [sh_freezecol]
    jae .out
    mov ax, bx
    call sh_colwidth
    mov cl, 3
    shl ax, cl
    add dx, ax
    inc bx
    jmp short .l
.out:
    mov ax, dx
    pop dx
    pop cx
    pop bx
    ret

; sh_frozenrh - the same, for the frozen rows, via sh_rowheight (already in
; pixels, unlike sh_colwidth's characters)
sh_frozenrh:
    push bx
    push dx
    xor dx, dx
    xor bx, bx
.l:
    cmp bx, [sh_freezerow]
    jae .out
    mov ax, bx
    call sh_rowheight
    add dx, ax
    inc bx
    jmp short .l
.out:
    mov ax, dx
    pop dx
    pop bx
    ret

; sh_backcols - AX = a column past the view's right edge -> AX = the scroll
; column that shows it WHOLE at the right: the columns before it, each its own
; width, as many as still fit [sh_gridw]. It subtracted the column count the
; OLD view held, which put a column wider than the ones it scrolled past
; partly or wholly off the glass
sh_backcols:
    push bx
    push cx
    push dx
    mov bx, ax                         ; BX = the first column shown
    call sh_colwidth
    mov cl, 3
    shl ax, cl
    mov dx, ax                         ; DX = the pixels they take
    call sh_frozencw                   ; 81.70: the frozen prefix's own
    add dx, ax                         ; pixels are already spent, permanently
.l:
    cmp bx, [sh_freezecol]             ; 81.70: never walk INTO the frozen
    jbe .out                           ; prefix - it is not a scroll position
    mov ax, bx
    dec ax
    call sh_colwidth
    mov cl, 3
    shl ax, cl
    add ax, dx
    cmp ax, [sh_gridw]
    ja .out
    mov dx, ax
    dec bx
    jmp short .l
.out:
    mov ax, bx
    pop dx
    pop cx
    pop bx
    ret

; sh_backrows - AX = a row below the view -> AX = the scroll row that shows it
; whole at the bottom, the rows before it each their own height (81.60)
sh_backrows:
    push bx
    push dx
    mov bx, ax                         ; BX = the first row shown
    call sh_rowheight
    mov dx, ax                         ; DX = the pixels they take
    call sh_frozenrh                   ; 81.70
    add dx, ax
.l:
    cmp bx, [sh_freezerow]
    jbe .out
    mov ax, bx
    dec ax
    call sh_rowheight
    add ax, dx
    cmp ax, [sh_gridh]
    ja .out
    mov dx, ax
    dec bx
    jmp short .l
.out:
    mov ax, bx
    pop dx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_onkey - W_ONKEY: AL=ascii (0 for a navigation key), AH=scan, SI=window
; -----------------------------------------------------------------------------
sh_onkey:
    push ax
    push bx
    push cx
    push dx
    call sh_macro_gatek                ; 81.86: WAIT, Esc, DISABLE.INPUT
    jc .out
    call sh_macro_keyck                ; 81.92: ON.KEY
    jc .out
    call sh_abdismiss                  ; any key takes the credits down, and
    jc .out                            ; is spent doing it
    cmp word [sh_fdlg_win], 0
    je .nofdlg
    call sh_fdlg_close_r                 ; see sh_onclick's own copy of this
                                        ; guard for why
.nofdlg:
    cmp word [sh_bdlg_win], 0
    je .nobdlg
    call sh_bdlg_close_r
.nobdlg:
    cmp word [sh_df_win], 0            ; 81.71.5, sh_onclick's own reason
    je .nodf
    call sh_df_close_r
.nodf:
    mov word [sh_msg], 0
    mov bx, si
    call sh_geom
    call sh_kaccel                     ; 81.101: Ctrl+X, F9 and the rest
    jc .out                            ; fire their menu item
    or al, al
    jz .navkey
    ; stage 3.0a: a shift+arrow arrives WITH an ASCII byte. The arrow and the
    ; keypad digit share one scancode - 0x4D is both Right and KP-6, the E0
    ; prefix naming no key of its own (kernel/mouse.inc's own note) - so the
    ; kernel's shifted translation hands us '6'. Without this test, holding
    ; shift and pressing an arrow would TYPE A DIGIT into the cell instead of
    ; extending the selection, which is exactly what it did before this check.
    call sh_shiftdown
    jnc .typing
    cmp ah, 0x4B
    je .navkey
    cmp ah, 0x4D
    je .navkey
    cmp ah, 0x48
    je .navkey
    cmp ah, 0x50
    je .navkey
    jmp .typing
.navkey:
    ; stage 3.0b: while an edit is in progress, the keys that move a CARET
    ; belong to the field, not to the grid - Left/Right/Home/End and Delete.
    ; Up/Down deliberately still commit and move the selection, which is what
    ; Excel does during cell entry.
    cmp byte [sh_editing], 0
    je .navgrid
    cmp ah, 0x4B                     ; Left
    je .navfield
    cmp ah, 0x4D                     ; Right
    je .navfield
    cmp ah, 0x47                     ; Home
    je .navfield
    cmp ah, 0x4F                     ; End
    je .navfield
    cmp ah, 0x53                     ; Delete
    je .navfield
    jmp .navgrid
.navfield:
    call sh_flkey
    jmp .out
.navgrid:
    cmp ah, 0x4B                     ; Left
    je .left
    cmp ah, 0x4D                     ; Right
    je .right
    cmp ah, 0x48                     ; Up
    je .up
    cmp ah, 0x50                     ; Down
    je .down
    cmp ah, 0x49                     ; Page Up
    je .pgup
    cmp ah, 0x51                     ; Page Down
    je .pgdn
    cmp ah, 0x47                     ; Home: back to column A
    je .home
    cmp ah, 0x53                     ; Delete: clear the selected cell
    je .delcell
    cmp ah, 0x3C                     ; F2: edit the cell in place
    je .f2
    jmp .out
.typing:
    cmp al, 27                       ; Escape: cancel the edit
    jne .notesc
    cmp byte [sh_editing], 0
    je .out
    mov byte [sh_editing], 0
    call sh_repaint
    jmp .out
.notesc:
    cmp al, 13                       ; Enter: commit, move down - and back to
    jne .nottab                      ; the column this ROW's entry started in,
    call sh_commit                   ; which is what Excel does after a run of
    mov ax, [sh_tabanchor]           ; Tabs. sh_select clears the anchor, so
    or ax, ax                        ; Enter consuming it needs no extra step
    jz .noanchor
    dec ax                           ; stored as col+1, see the Tab arm below
    jmp .enterrow
.noanchor:
    mov ax, [sh_selcol]
.enterrow:
    mov bx, [sh_selrow]
    inc bx
    cmp bx, SH_ROWS
    jb .entergo
    mov bx, SH_ROWS - 1
.entergo:
    call sh_select
    jmp .out
.nottab:
    cmp al, 9                        ; Tab: commit, move right
    jne .notbs
    call sh_commit
    mov ax, [sh_tabanchor]           ; the first Tab of a run records where it
    or ax, ax                        ; started; later ones keep that. Stored as
    jnz .haveanchor                  ; col+1, so a ZEROED bss reads as "none"
    mov ax, [sh_selcol]              ; and no init pass is needed
    inc ax
.haveanchor:
    push ax                          ; sh_select clears it, so it is put back
    mov ax, [sh_selcol]              ; afterwards rather than before
    mov bx, [sh_selrow]
    inc ax
    cmp ax, SH_COLS
    jb .tabgo
    mov ax, SH_COLS - 1
.tabgo:
    call sh_select
    pop ax
    mov [sh_tabanchor], ax
    jmp .out
.notbs:
    cmp al, 8                        ; Backspace: the field owns it now, so it
    jne .notdigit                    ; deletes AT THE CARET rather than only
    cmp byte [sh_editing], 0         ; ever chopping the last character
    je .out
    call sh_flkey
    jmp .out
.notdigit:
    ; STAGE 4.5 REPLACED AN ALLOW-LIST WITH A RANGE, and the reason is that
    ; the list had stopped describing anything. It grew one character at a
    ; time as the formula language did - '=' then the operators, then <> for
    ; comparisons, then ! and " for cross-sheet refs and ALERT's string
    ; literal, then '.' for SET.VALUE, then '$' for absolute references, then
    ; '^' for the power operator - and each addition was found the same way:
    ; the parser handled the character perfectly and the character never
    ; reached it, because THIS gate dropped it first.
    ;
    ; A cell that can hold a LABEL ends the argument. A label is arbitrary
    ; text; there is no subset of printable ASCII a column heading is not
    ; allowed to contain, and an apostrophe or a percent sign being rejected
    ; is a bug with no upside. So the gate now asks the only question it can
    ; actually answer - is this a printable character - and leaves deciding
    ; what the characters MEAN to sh_commit, which is where that decision
    ; belongs and where it already lives.
    cmp al, ' '
    jb .out                            ; control characters are handled above
    cmp al, 0x7E                       ; (Enter, Escape, Backspace, arrows)
    ja .out                            ; and are not text
.accept:
    cmp byte [sh_editing], 0
    jnz .append
    call sh_editstart                ; first character into an empty cell
.append:
    call sh_flkey                    ; the field inserts AT THE CARET and
    jmp .out                         ; bounds itself against LN_MAX
; stage 3.0a: an arrow moves the ANCHOR (collapsing the range) normally, or
; walks the EXTENT when shift is held. Both halves share one source-load and
; one dispatch rather than four near-copies of each.
.left:
    call sh_arrowsrc
    or ax, ax
    jz .out
    dec ax
    jmp .arrowgo
.right:
    call sh_arrowsrc
    cmp ax, SH_COLS - 1
    jae .out
    inc ax
    jmp .arrowgo
.up:
    call sh_arrowsrc
    or bx, bx
    jz .out
    dec bx
    jmp .arrowgo
.down:
    call sh_arrowsrc
    cmp bx, SH_ROWS - 1
    jae .out
    inc bx
.arrowgo:
    call sh_shiftdown
    jc .arrowext
    call sh_select
    jmp .out
.arrowext:
    call sh_select_to
    jmp .out
.pgup:
    mov bx, [sh_selrow]
    mov ax, [sh_vrows]
    cmp bx, ax
    jae .pgup_sub
    xor bx, bx
    jmp .pgup_go
.pgup_sub:
    sub bx, ax
.pgup_go:
    mov ax, [sh_selcol]
    call sh_select
    jmp .out
.pgdn:
    mov bx, [sh_selrow]
    add bx, [sh_vrows]
    cmp bx, SH_ROWS - 1
    jbe .pgdn_go
    mov bx, SH_ROWS - 1
.pgdn_go:
    mov ax, [sh_selcol]
    call sh_select
    jmp .out
.home:
    xor ax, ax
    mov bx, [sh_selrow]
    call sh_select
    jmp .out
.f2:
    call sh_beginedit
    jmp .out
.delcell:
    mov byte [sh_editing], 0
    ; THE GUARD WAS MISSING HERE, and it was missing for 81.46 before this
    ; feature existed: Del is the one write path in this app that never asked
    ; sh_prot_blocked, so it cleared a locked cell on a protected document
    ; and would have cleared a table result cell. Every other write - typing,
    ; Paste, Fill, a sort's write-back - goes through sh_commit, which asks.
    ; It is asked STRICTLY, with [sh_prot_clr] left at 0: Del clears the one
    ; selected cell, and clearing one cell of a table is exactly the partial
    ; clear 81.114.7 refuses.
    call sh_prot_blocked
    jnc .delok
    call sh_repaint                    ; A REFUSAL STILL HAS TO REPAINT, or
    jmp .out                           ; the status bar never shows what it
.delok:                                ; just said (SI is the window here -
                                       ; .delcell's own sh_repaint below takes
                                       ; it from the same place)
    mov al, SH_UL_CLEAR                ; Del is Edit Clear's key, and undoable
    call sh_undo_begin                 ; as it is (81.57)
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_clearcell
    call sh_undo_end
    cmp byte [sh_calcmode], SH_CALC_AUTO  ; 81.114.8: Del does not go through
    jne .delnorec                      ; sh_commit, and the cell it just
    call sh_tbl_run_all                ; emptied may be an INPUT cell
.delnorec:
    call sh_repaint
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_beginedit - F2: seed the edit buffer from the selected cell's current
; value (blank if the cell is empty) and enter edit mode. SI must be the
; window ptr for sh_repaint.
; -----------------------------------------------------------------------------
sh_beginedit:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov dx, si                        ; DX = window ptr, stashed (SI is used
                                       ; as scratch throughout this function)
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_findcell
    jnc .blank
    push es
    mov es, [sh_cellseg]
    test byte [es:di+4], 1
    jz .plainval
    mov ax, [es:di+SH_C_FOFF]                 ; formula_off
    pop es
    mov byte [sh_editbuf], '='
    mov di, sh_editbuf + 1
    mov si, ax
    push es
    mov es, [sh_txtseg]
.copyf:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .copyf
    pop es
    jmp .havelen
.plainval:
    call sh_cellnum                   ; the value as decimal text
    pop es
    mov si, sh_numbuf
    mov di, sh_editbuf
    call sh_strcpy
.havelen:
    xor cx, cx
    mov si, sh_editbuf
.cnt:
    cmp byte [si], 0
    je .setlen
    inc si
    inc cx
    jmp .cnt
.setlen:
    mov [sh_editlen], cl
    jmp .go
.blank:
    mov byte [sh_editbuf], 0
    mov byte [sh_editlen], 0
.go:
    mov byte [sh_editing], 1
    call sh_flsync                    ; stage 3.0b: the field's own length,
                                       ; caret and scroll must match the
                                       ; buffer we just seeded, or the caret
                                       ; draws somewhere the text is not
    mov si, dx                        ; SI = window ptr, restored
    call sh_repaint
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_paren_ok - do the parentheses in [sh_editbuf] balance? out: CF=1 = no.
;
; Lexical only, and deliberately so: it runs at COMMIT, where re-running the
; evaluator would mean recursion, cycle marks and memoisation stamps as a side
; effect of typing. It catches the bracket a person actually drops; it does not
; claim to be a syntax check, and something like `=1+` still commits and reads
; as 0. A real answer needs an error VALUE - SH_T_ERR is reserved and nothing
; produces one yet - and that is a feature, not this.
;
; A quoted string is skipped whole, so a bracket inside a label literal does
; not count toward the balance.
; -----------------------------------------------------------------------------
sh_paren_ok:
    push ax
    push cx
    push si
    mov si, sh_editbuf
    xor cx, cx                        ; cx = how many are still open
.scan:
    mov al, [si]
    or al, al
    jz .done
    inc si
    cmp al, '"'
    je .instr
    cmp al, '('
    je .open
    cmp al, ')'
    jne .scan
    or cx, cx
    jz .bad                           ; a ')' with nothing open
    dec cx
    jmp .scan
.open:
    inc cx
    jmp .scan
.instr:
    mov al, [si]
    or al, al
    jz .done
    inc si
    cmp al, '"'
    jne .instr
    jmp .scan
.done:
    or cx, cx
    jnz .bad
    clc
    jmp .out
.bad:
    stc
.out:
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_commit - if a cell is being edited, parse the buffer and store it (an
; empty buffer, or one that doesn't parse as a single signed integer,
; clears the cell instead); either way stop editing. SI is not touched.
; Out: CF=1 when the store was REFUSED (text arena or cell table full) and
; the cell keeps what it had - sh_sort_permcol stops on it; every older
; caller ignores it, which is what the silence always was.
; -----------------------------------------------------------------------------
sh_commit:
    push ax
    push bx
    push cx
    push dx
    push si
    push es
    cmp byte [sh_editing], 0
    je .out
    call sh_prot_blocked              ; ONE funnel, so one guard: typing, Paste
    jnc .allowed                      ; in all six modes, Fill Right and Fill
    mov byte [sh_editing], 0          ; Down and a sort's write-back all end up
    jmp .out                          ; here, and none of them can change a
.allowed:                             ; locked cell on a protected document
    cmp byte [sh_ud_busy], 0          ; a TYPED entry is undoable on its own
    jne .inside                       ; (81.57); one made by Paste, Fill or
    mov al, SH_UL_ENTRY               ; Sort is part of theirs, which took
    call sh_undo_begin                ; the snapshot already
    call sh_undo_end
.inside:
    call sh_rec_stage                 ; 81.74: a TYPED entry is the recorder's
                                      ; FORMULA. Staged HERE, before the store
                                      ; reads sh_editbuf, and emitted at .out
                                      ; - the emit writes through sh_commit
                                      ; itself, so it has to happen once this
    mov byte [sh_editing], 0
    mov byte [sh_commitdirty], 1      ; cell data changes below (even an empty
                                      ; buffer clears the cell) - sh_selpaint
                                      ; reads this and pays the full repaint,
                                      ; whose pass advance is what re-shows
                                      ; every dependent formula
    cmp byte [sh_editlen], 0
    jne .have
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_clearcell
    clc                               ; clearing is never refused
    jmp .out
.have:
    cmp byte [sh_editbuf], '='
    jne .numeric
    call sh_paren_ok                  ; ...and a formula must be well formed,
    jc .badformula                    ; for the same reason "3.5kg" is not 3.5
    mov si, sh_editbuf
    inc si                            ; past the '='
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_setformula
    jmp .out
.badformula:
    ; `=SUM(E2:E5` - one missing bracket - used to be STORED AS A FORMULA and
    ; quietly evaluated to 0, which is the worst answer available: a plausible
    ; number, in the right place, that nobody has reason to doubt. It is kept
    ; as a LABEL instead, so the cell shows the text that was typed, and the
    ; status bar says why. That is this app's existing rule for input that
    ; cannot be what it looks like, applied to the one type that was exempt.
    mov word [sh_msg], sh_s_badparen
    jmp .astext
.numeric:
    mov si, sh_editbuf                ; stage 4.0: a full decimal, not a signed
    call fp_atof                      ; integer. "3.5", "-0.25" and "1e3" are
    jc .astext                        ; all values now; anything fp_atof does
    mov al, [si]                      ; not consume ENTIRELY is not a number,
    or al, al                         ; which is what keeps "3.5kg" from
    jnz .astext                       ; silently becoming 3.5
    call sh_acc_store
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_setvald
    jmp .out
.astext:
    ; stage 4.5: what used to happen here was sh_clearcell - anything that
    ; would not parse as a number was DISCARDED, and typing a column heading
    ; left the cell empty. Content decides the type, exactly as Excel does it:
    ; '=' is a formula, a complete number is a number, and everything else is
    ; a label. There is no forcing prefix because Excel 2.1 has none either
    ; (the leading ' " ^ \ are Lotus's, not Excel's) - a cell that must hold
    ; "1990" as text is a Format problem, not an entry one.
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    mov si, sh_editbuf
    push ax                           ; ...except an ERROR VALUE's name, which
    call sh_errword                   ; is the error constant, as a typed #N/A
    mov dx, ax                        ; is in Excel - and so what Paste and
    pop ax                            ; Sort's carry commit for one, both of
    jnc .label                        ; which go through here as text (81.61)
    call sh_seterr
    jmp short .out
.label:
    call sh_setlabel                  ; ...and TRUE and FALSE, which are
.out:                                 ; the logical constant (81.51)
    pushf                             ; 81.74: every caller reads this CF
    call sh_rec_flush
    ; 81.114.8: ONE FUNNEL, SO ONE RECALCULATION. Typing, Paste in all six
    ; modes, Fill Right and Fill Down and a sort's write-back all end up
    ; here, which is the same reason sh_prot_blocked sits at the other end of
    ; this routine - so hooking the table re-run here covers every one of
    ; them and no call site learns about tables.
    ;
    ; GATED ON sh_commitdirty, not on reaching .out: a REFUSED commit comes
    ; through here too, and typing into a result cell is refused by
    ; construction - so without the gate every rejected keystroke would
    ; re-run every table on the document.
    cmp byte [sh_calcmode], SH_CALC_AUTO
    jne .norecalc
    cmp byte [sh_commitdirty], 0
    je .norecalc
    call sh_tbl_run_all
.norecalc:
    popf
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; Drawing
; =============================================================================

sh_drawall:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    cmp byte [sh_calcmode], SH_CALC_MANUAL  ; stage 3.0c Options > Calculation.
    jae .nocalc                       ; NOT advancing the pass stamp is the whole
    inc word [sh_pass]                ; mechanism: sh_eval_cell's memoization
.nocalc:                              ; keys off it, so every formula reads as
                                       ; a cache hit and nothing re-evaluates.
                                       ; One recalculation pass per full
                                       ; repaint, when it is automatic.
    call sh_mbar_draw
    call sh_drawbar
    call sh_drawstatus
    call sh_sbsync                    ; stage 3.0a+: both scroll bars, from
    mov bx, sh_vsb                    ; the live geometry and scroll position
    call os88ui_sbar
    mov bx, sh_hsb
    call sh_hsb_draw
    call sh_drawcolhdrs
    call sh_drawrowhdrs
    call sh_drawhdrrules              ; 81.116.1: and the lines that box them
    call sh_dmgfull                   ; the three grid painters below are
    call sh_drawgrid                  ; RANGED now (sh_dmgc1..sh_dmgr2); a
    call sh_drawlines                 ; full draw is the whole viewport
    call sh_drawborders
    call sh_drawsel
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dmgfull - point the damage range at the whole viewport. The ranged grid
; painters guard [sh_vcols]/[sh_vrows] == 0 themselves, so the wrapped-around
; bounds an empty viewport produces here are never read. Preserves everything.
; -----------------------------------------------------------------------------
sh_dmgfull:
    push ax
    xor ax, ax
    mov [sh_dmgc1], ax
    mov [sh_dmgr1], ax
    mov ax, [sh_vcols]
    dec ax
    mov [sh_dmgc2], ax
    mov ax, [sh_vrows]
    dec ax
    mov [sh_dmgr2], ax
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dmgdraw - redraw ONLY the cells in [sh_dmgc1..c2] x [sh_dmgr1..r2]
; (window-relative, inclusive, already clamped to the viewport), plus the
; gridline segments and border edges over them. This is the partial-repaint
; core: OSAPI_FONT_RUN owns each cell's 8 glyph rows, so when a cell is
; taller the band below them is filled here - the full repaint's window-wide
; white fill does not run on this path, and the mover owns its stale pixels
; (the old selection frame's edges land in exactly that band).
; -----------------------------------------------------------------------------
sh_dmgdraw:
    push ax
    push bx
    push cx
    push dx
    cmp word [sh_vcols], 0
    je .out
    cmp word [sh_vrows], 0
    je .out
    mov ax, [sh_dmgc1]                 ; the damaged columns' pixel span
    call sh_vcx                        ; each column its own width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov [sh_blitx1], ax
    mov ax, [sh_dmgc2]
    inc ax
    call sh_vcx                        ; each column its own width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    dec ax
    mov [sh_blitx2], ax
    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov cx, [sh_dmgr1]
.band:
    ; EACH ROW ITS OWN HEIGHT (81.60): the band ABOVE the glyphs, where a
    ; tall row's text sits low (sh_vtoff), and the band below them
    cmp cx, [sh_dmgr2]
    ja .nobands
    mov ax, cx
    call sh_vry
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov bx, ax                         ; BX = the row's top
    mov ax, cx
    call sh_vtoff
    or ax, ax
    jz .below
    mov dx, bx
    add dx, ax
    dec dx                             ; down to the line above the glyphs
    mov ax, [sh_blitx1]
    push cx
    mov cx, [sh_blitx2]
    call OSAPI_GFX_FILL
    pop cx
.below:
    mov ax, cx
    call sh_vheight
    mov dx, bx
    add dx, ax
    dec dx                             ; DX = the row's last pixel line
    mov ax, cx
    call sh_vtoff
    add bx, ax
    add bx, 8                          ; below the glyphs
    cmp bx, dx
    ja .bandn                          ; an 8px row: the run covers it all
    mov ax, [sh_blitx1]
    push cx
    mov cx, [sh_blitx2]
    call OSAPI_GFX_FILL
    pop cx
.bandn:
    inc cx
    jmp .band
.nobands:
    call sh_drawgrid
    call sh_drawlines
    call sh_drawborders
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawbar - the formula bar (stage 2.x: real Excel's own two-box look -
; a fixed-width reference box on the left, a boxed content area on the
; right showing the selected cell's current value/formula, or the live
; edit buffer while typing). Status messages have their own bar now
; (sh_drawstatus) - this one only ever shows the reference and the
; content, matching real Excel's own division of labor between the two.
; -----------------------------------------------------------------------------
; =============================================================================
; The two scroll bars (stage 3.0a+)
;
; The VERTICAL one is os88ui.inc's shared element, used exactly as files.inc
; and fdlg.inc use it. The HORIZONTAL one is sh_hsb_* below - private to this
; app for now, but written to os88ui.inc's own conventions (same seven-word
; block, same OS88UI_SB* part codes, same "geometry not policy" split) so that
; promoting it into the shared file after Sheet 2.0 is a rename rather than a
; redesign. os88ui.inc has no horizontal bar today: its arrow cells are
; derived as y1+10/y2-10 and os88ui_sbtrack deliberately takes DX and not CX
; (SPEC.md 13.10.5.2, "x is never read"), so the axis is structural.
;
; SCROLL EXTENT. `total` is not SH_ROWS/SH_COLS - a bar over 16384 rows would
; have a one-pixel thumb that says nothing. It is the USED extent plus one
; screen, so the thumb is proportional to the sheet a person actually has, and
; it collapses to "no thumb" when everything already fits (os88ui_sbthumb
; answers CF=1 for that case on its own).
; =============================================================================

; -----------------------------------------------------------------------------
; sh_sbsync - refill both blocks from the live geometry and scroll position.
; Called before every draw and every hit-test, for sh_flrect's reason: the
; window moves and resizes, and a painter and a hit-tester reading different
; rects is the one bug this element is designed to make impossible.
; -----------------------------------------------------------------------------
sh_sbsync:
    push ax
    push bx
    push cx
    push dx
    call sh_difbbox                    ; -> [sh_bbcol]/[sh_bbrow], the used
                                        ; bounding box (walks only OCCUPIED
                                        ; cells, not the whole grid)

    ; --- vertical: the strip at the right of the grid area
    mov ax, [sh_ox]
    add ax, [sh_cw]
    sub ax, SH_VSB_W
    mov [sh_vsb + 0], ax               ; x1
    mov ax, [sh_ox]
    add ax, [sh_cw]
    dec ax
    mov [sh_vsb + 4], ax               ; x2
    mov ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov [sh_vsb + 2], ax               ; y1 - the top of the grid proper
    mov ax, [sh_oy]
    add ax, [sh_ch]
    sub ax, SH_SB_H + SH_HSB_H
    dec ax
    mov [sh_vsb + 6], ax               ; y2 - just above the horizontal bar
    mov ax, [sh_bbrow]
    inc ax                             ; the USED extent, not SH_ROWS - a bar
    cmp ax, [sh_vrows]                 ; over 16384 rows has a one-pixel thumb
    jae .vtot                          ; that says nothing. Floored at `fit`,
    mov ax, [sh_vrows]                 ; so an empty sheet has total == fit and
.vtot:                                 ; correctly shows no thumb at all.
    sub ax, [sh_freezerow]             ; 81.70: total/fit/pos all shift into
    mov [sh_vsb + 8], ax               ; the SCROLLING region's own space -
    mov ax, [sh_vrows]                 ; the frozen prefix is never part of
    sub ax, [sh_freezerow]             ; what the thumb represents at all
    mov [sh_vsb + 10], ax              ; fit
    mov ax, [sh_scrollrow]
    sub ax, [sh_freezerow]
    mov dx, [sh_vsb + 8]               ; pos, CLAMPED to total - fit: keyboard
    sub dx, [sh_vsb + 10]              ; navigation and Goto move the origin
    cmp ax, dx                         ; without consulting the bars, and both
    jbe .vpos                          ; thumb routines divide pos * track by
    mov ax, dx                         ; total - unclamped, the quotient can
.vpos:                                 ; overflow 16 bits and the DIV raises
    mov [sh_vsb + 12], ax              ; INT 0 (a crash on real hardware)

    ; --- horizontal: the strip below the grid, left of the vertical bar
    mov ax, [sh_ox]
    add ax, SH_RH_W
    mov [sh_hsb + 0], ax               ; x1
    mov ax, [sh_ox]
    add ax, [sh_cw]
    sub ax, SH_VSB_W
    dec ax
    mov [sh_hsb + 4], ax               ; x2 - stops at the vertical bar
    mov ax, [sh_oy]
    add ax, [sh_ch]
    sub ax, SH_SB_H + SH_HSB_H
    mov [sh_hsb + 2], ax               ; y1
    mov ax, [sh_oy]
    add ax, [sh_ch]
    sub ax, SH_SB_H
    dec ax
    mov [sh_hsb + 6], ax               ; y2
    mov ax, [sh_bbcol]
    inc ax
    cmp ax, [sh_vcols]
    jae .htot
    mov ax, [sh_vcols]
.htot:
    sub ax, [sh_freezecol]             ; 81.70: see the vertical bar's own
    mov [sh_hsb + 8], ax               ; comment above
    mov ax, [sh_vcols]
    sub ax, [sh_freezecol]
    mov [sh_hsb + 10], ax              ; fit
    mov ax, [sh_scrollcol]
    sub ax, [sh_freezecol]
    mov dx, [sh_hsb + 8]               ; pos, clamped to total - fit, for the
    sub dx, [sh_hsb + 10]              ; vertical bar's reason above
    cmp ax, dx
    jbe .hpos
    mov ax, dx
.hpos:
    mov [sh_hsb + 12], ax

    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; sh_hsb_* - A HORIZONTAL SCROLL BAR, staged for os88ui.inc
;
; os88ui.inc's bar is structurally vertical and says so: its arrow cells are
; y1+10 and y2-10, and os88ui_sbtrack takes DX and refuses CX on purpose
; (SPEC.md 13.10.5.2). This is that element transposed, and NOTHING about it
; is Sheet-specific:
;
;   * the same seven-word block (x1,y1,x2,y2,total,fit,pos), so a promoted
;     version needs no caller to change its .bss;
;   * the same part codes - SH_SB_UP/SBDOWN mean LEFT/RIGHT here, which is
;     what the vertical file would also do rather than inventing two more;
;   * the same split: this answers where the parts are and draws them, and
;     what an arrow DOES to a view stays the caller's (13.10.1);
;   * the same refusal: no thumb when everything fits or the track is too
;     short to hold one.
;
; When it moves into os88ui.inc after Sheet 2.0, the intended shape is one
; axis flag in the block (or a paired entry point) rather than two copies -
; the arithmetic below is deliberately written so that swapping x for y and
; width for height is the whole of the difference.
; =============================================================================

; =============================================================================
; sh_hsb_* - A HORIZONTAL SCROLL BAR, staged for os88ui.inc
;
; os88ui.inc's bar is structurally vertical and says so: its arrow cells are
; y1+10 and y2-10, and os88ui_sbtrack takes DX and refuses CX on purpose
; (SPEC.md 13.10.5.2, "x is never read"). This is that element transposed, and
; nothing about it is Sheet-specific:
;
;   * the same seven-word block (x1,y1,x2,y2,total,fit,pos), so a promoted
;     version needs no caller to change its .bss;
;   * the same part codes - SH_SB_UP/SBDOWN read as LEFT/RIGHT here, which
;     is what a shared two-axis file would do rather than invent two more;
;   * the same split - this answers where the parts are and draws them; what
;     an arrow DOES to a view stays the caller's (13.10.1);
;   * the same refusal - no thumb when everything fits, or when the track is
;     too short to hold one.
;
; When it moves into os88ui.inc after Sheet 2.0, the intended shape is one
; axis flag in the block rather than two copies: the arithmetic below is
; written so that swapping x for y, and width for height, is the whole of the
; difference.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_hsb_load - copy the block's rect into scratch. in: BX = the block.
; Preserves everything. Every drawing routine calls this FIRST and then never
; dereferences BX again, which is what keeps the block pointer and the gfx
; rect from fighting over the same register.
; -----------------------------------------------------------------------------
sh_hsb_load:
    push ax
    mov ax, [bx + 0]
    mov [sh_hsb_x1], ax
    mov ax, [bx + 2]
    mov [sh_hsb_y1], ax
    mov ax, [bx + 4]
    mov [sh_hsb_x2], ax
    mov ax, [bx + 6]
    mov [sh_hsb_y2], ax
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_hsb_thumb - the thumb's geometry (os88ui_sbthumb, transposed)
; in:  BX = the block
; out: CF=1 = there is no thumb; else CF=0 and [sh_hsb_tl]/[sh_hsb_tw] hold
;      its left and width, absolute. Every register preserved.
; -----------------------------------------------------------------------------
sh_hsb_thumb:
    push ax
    push cx
    push dx
    push si
    mov cx, [bx + 4]
    sub cx, [bx + 0]
    sub cx, (SH_SB_CELL + 1) * 2    ; cx = the track's width
    cmp cx, SH_SB_MINH
    jb .none
    mov ax, [bx + 10]                  ; fit
    or ax, ax
    jz .none
    cmp ax, [bx + 8]                   ; fit >= total: everything fits
    jae .none
    xor dx, dx
    mul cx                             ; dx:ax = fit * track
    div word [bx + 8]                  ; / total
    cmp ax, SH_SB_MINH
    jae .wok
    mov ax, SH_SB_MINH
.wok:
    mov si, ax                         ; si = the thumb's width
    mov ax, [bx + 12]                  ; pos
    xor dx, dx
    mul cx                             ; dx:ax = pos * track
    div word [bx + 8]                  ; / total
    add ax, [bx + 0]
    add ax, SH_SB_CELL + 1          ; ax = the thumb's left
    ; Clamp the tail inside the track: pos == total-fit can overshoot by a
    ; pixel once both divisions have truncated.
    mov dx, [bx + 4]
    sub dx, SH_SB_CELL + 1          ; dx = the track's last column
    push ax
    add ax, si
    dec ax                             ; ax = the thumb's right
    cmp ax, dx
    pop ax
    jbe .fits
    mov ax, dx
    sub ax, si
    inc ax
.fits:
    mov [sh_hsb_tl], ax
    mov [sh_hsb_tw], si
    pop si
    pop dx
    pop cx
    pop ax
    clc
    ret
.none:
    pop si
    pop dx
    pop cx
    pop ax
    stc
    ret

; -----------------------------------------------------------------------------
; sh_hsb_draw - the whole bar. in: BX = the block; gfx lock held.
; Preserves everything; leaves the pen BLACK, as os88ui_sbar does.
; -----------------------------------------------------------------------------
sh_hsb_draw:
    push ax
    push bx
    push cx
    push dx
    call sh_hsb_load

    mov al, CWHITE                     ; the arrow cells are plain white...
    call OSAPI_SET_COLOR
    mov ax, [sh_hsb_x1]
    mov bx, [sh_hsb_y1]
    mov cx, [sh_hsb_x2]
    mov dx, [sh_hsb_y2]
    call OSAPI_GFX_FILL
    mov ax, [sh_hsb_x1]                ; ...and the TRACK between them is the
    add ax, SH_SB_CELL + 1             ; grey dither, which is what the thumb
    mov cx, [sh_hsb_x2]                ; reads as a knob against
    sub cx, SH_SB_CELL + 1
    mov bx, [sh_hsb_y1]
    inc bx
    mov dx, [sh_hsb_y2]
    dec dx
    cmp ax, cx
    jg .notrack
    call OSAPI_GFX_FILL_GRAY
.notrack:

    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_hsb_x1]                ; the outline
    mov bx, [sh_hsb_y1]
    mov cx, [sh_hsb_x2]
    mov dx, [sh_hsb_y2]
    call OSAPI_GFX_FRAME

    mov ax, [sh_hsb_x1]                ; the two arrow-cell rules
    add ax, SH_SB_CELL
    mov bx, [sh_hsb_y1]
    mov dx, [sh_hsb_y2]
    call OSAPI_GFX_VLINE
    mov ax, [sh_hsb_x2]
    sub ax, SH_SB_CELL
    mov bx, [sh_hsb_y1]
    mov dx, [sh_hsb_y2]
    call OSAPI_GFX_VLINE

    pop dx
    pop cx
    pop bx
    pop ax
    call sh_hsb_arrows
    call sh_hsb_thdraw
    ret

; -----------------------------------------------------------------------------
; sh_hsb_arrows - the two triangles. os88ui.inc's vertical arrow is 5 rows of
; widths 1..9; this is that rotated, so 5 columns of growing height.
; in: BX = the block (already loaded into scratch by the caller).
; -----------------------------------------------------------------------------
sh_hsb_arrows:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov si, [sh_hsb_y1]
    add si, [sh_hsb_y2]
    shr si, 1                          ; si = the cells' vertical centre

    ; The tips point OUTWARD - `<` on the left cell and `>` on the right, not
    ; `>` and `<`. Each arrow starts one pixel in from its OUTER edge, where
    ; the tip belongs, and widens INWARD.
    mov di, [sh_hsb_x1]                ; LEFT arrow: tip at the outer edge...
    add di, 3
    mov cx, 5
    xor bx, bx
.la:
    mov ax, di
    push bx
    push cx
    mov cx, si
    sub cx, bx
    mov dx, si
    add dx, bx
    mov bx, cx
    call OSAPI_GFX_VLINE
    pop cx
    pop bx
    inc di                             ; ...widening inward
    inc bx
    loop .la

    mov di, [sh_hsb_x2]                ; RIGHT arrow: tip at ITS outer edge,
    sub di, 3                          ; widening inward the other way
    mov cx, 5
    xor bx, bx
.ra:
    mov ax, di
    push bx
    push cx
    mov cx, si
    sub cx, bx
    mov dx, si
    add dx, bx
    mov bx, cx
    call OSAPI_GFX_VLINE
    pop cx
    pop bx
    dec di
    inc bx
    loop .ra

    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_hsb_thdraw - just the thumb. in: BX = the block; gfx lock held.
; -----------------------------------------------------------------------------
sh_hsb_thdraw:
    push ax
    push bx
    push cx
    push dx
    call sh_hsb_thumb
    jc .out
    ; The same two-part thumb os88ui_sbthdraw draws, transposed: a BLACK
    ; frame with a WHITE interior inside it - not a solid block, which is what
    ; makes it read as a knob against the dithered track rather than as a bar.
    mov ax, [sh_hsb_tl]
    mov cx, ax
    add cx, [sh_hsb_tw]
    dec cx
    mov bx, [sh_hsb_y1]
    add bx, 2
    mov dx, [sh_hsb_y2]
    sub dx, 2
    push ax
    mov al, CBLACK
    call OSAPI_SET_COLOR
    pop ax
    call OSAPI_GFX_FRAME
    inc ax                             ; the interior, INSIDE the border
    dec cx
    inc bx
    dec dx
    cmp ax, cx
    jg .black
    cmp bx, dx
    jg .black
    push ax
    mov al, CWHITE
    call OSAPI_SET_COLOR
    pop ax
    call OSAPI_GFX_FILL
.black:
    mov al, CBLACK                     ; the header's promise: pen left BLACK
    call OSAPI_SET_COLOR
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_hsb_hit - which part is this point on? (os88ui_sbhit, transposed)
; in:  BX = the block, CX = x, DX = y (both ABSOLUTE)
; out: AL = OS88UI_SB*; AH clobbered, everything else preserved.
; -----------------------------------------------------------------------------
sh_hsb_hit:
    push cx
    push dx
    cmp dx, [bx + 2]
    jb .none
    cmp dx, [bx + 6]
    ja .none
    cmp cx, [bx + 0]
    jb .none
    cmp cx, [bx + 4]
    ja .none
    mov ax, [bx + 0]
    add ax, SH_SB_CELL
    cmp cx, ax
    jbe .up                            ; the LEFT arrow cell
    mov ax, [bx + 4]
    sub ax, SH_SB_CELL
    cmp cx, ax
    jae .down                          ; the RIGHT arrow cell
    call sh_hsb_thumb
    jc .pgdn                           ; no thumb: the track is all page-fwd
    mov ax, [sh_hsb_tl]
    cmp cx, ax
    jb .pgup
    add ax, [sh_hsb_tw]
    cmp cx, ax
    jae .pgdn
    mov al, SH_SB_THUMB
    jmp .out
.up:
    mov al, SH_SB_UP
    jmp .out
.down:
    mov al, SH_SB_DOWN
    jmp .out
.pgup:
    mov al, SH_SB_PGUP
    jmp .out
.pgdn:
    mov al, SH_SB_PGDN
    jmp .out
.none:
    mov al, SH_SB_NONE
.out:
    pop dx
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_hsb_grab / sh_hsb_track / sh_hsb_drop - the thumb drag, the same three
; edges os88ui.inc's own uses (13.10.5), with the anchor banked as
; press_x - thumb_left so the thumb does not jump under the hand.
; -----------------------------------------------------------------------------
sh_hsb_grab:
    push ax
    call sh_hsb_thumb
    jc .no
    mov ax, cx
    sub ax, [sh_hsb_tl]
    mov [sh_hsb_dragoff], ax
    mov byte [sh_hsb_dragon], 1
    pop ax
    clc
    ret
.no:
    pop ax
    stc
    ret

; in: BX = the block, CX = the pointer's x (ABSOLUTE). y is never read, which
; is 13.10.5.2's rule with the axes swapped.
; out: CF=0 and AX = the pos the view is owed; CF=1 = nothing is owed.
sh_hsb_track:
    cmp byte [sh_hsb_dragon], 0
    je .no
    push cx
    push dx
    push si
    mov ax, cx
    sub ax, [sh_hsb_dragoff]           ; ax = where the thumb's left wants to be
    mov si, [bx + 0]
    add si, SH_SB_CELL + 1          ; si = the track's left
    sub ax, si
    jns .pos
    xor ax, ax                         ; clamped at the near end
.pos:
    mov cx, [bx + 4]
    sub cx, [bx + 0]
    sub cx, (SH_SB_CELL + 1) * 2    ; cx = the track's width
    or cx, cx
    jz .nopop
    xor dx, dx
    mul word [bx + 8]                  ; offset * total
    div cx                             ; / track -> the pos it maps to
    mov cx, [bx + 8]
    sub cx, [bx + 10]                  ; the last legal pos = total - fit
    jbe .zero
    cmp ax, cx
    jbe .done
    mov ax, cx
    jmp .done
.zero:
    xor ax, ax
.done:
    cmp ax, [bx + 12]                  ; 13.10.5.3's quantisation: a move too
    je .nopop                          ; small to change a row owes nothing
    pop si
    pop dx
    pop cx
    clc
    ret
.nopop:
    pop si
    pop dx
    pop cx
.no:
    stc
    ret

sh_hsb_drop:
    mov byte [sh_hsb_dragon], 0
    ret

; -----------------------------------------------------------------------------
; sh_onmouseup - W_ONMOUSEUP: the press was released. Ends a thumb drag and,
; for the vertical bar's rate-0 grab, commits the pos the hand ended on -
; which is what "the view follows only on release" means (13.10.5.4).
; -----------------------------------------------------------------------------
sh_onmouseup:
    push ax
    push bx
    push si
    mov byte [sh_rz_on], 0             ; 81.73.2: the drag already applied
    call os88ui_sbdragging
    jc .noV
    call os88ui_sbdrop                 ; the view already followed during the
    jmp .out                           ; drag (the rate above), so releasing
.noV:                                  ; only has to let go
    cmp byte [sh_hsb_dragon], 0
    je .out
    call sh_hsb_drop
.out:
    mov byte [sh_dragging], 0
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sbclick - stage 3.0a+: a press landed somewhere. If it was on either
; scroll bar, act on it and answer CF=1 ("mine"); otherwise CF=0 and the grid
; gets it. in: CX = x, DX = y (absolute), SI = the window.
;
; This is the POLICY half that os88ui.inc deliberately leaves to the caller
; (13.10.1): the element says which part was hit, and what a part MEANS to a
; sheet - one row, one screen, or take the thumb - is decided here.
; -----------------------------------------------------------------------------
sh_sbclick:
    push ax
    push bx
    push di
    call sh_sbsync

    mov bx, sh_vsb                     ; --- the vertical bar
    call os88ui_sbhit
    cmp al, SH_SB_NONE
    je .tryh
    xor ah, ah                         ; stash the part in DI: the very next
    mov di, ax                         ; instruction writes the whole of AX,
    mov ax, [sh_scrollrow]             ; so stashing it in AH (as this did)
    mov [sh_sb_oldpos], ax             ; destroyed it and every compare below
    cmp di, SH_SB_UP                   ; fell through to the thumb branch
                                        ; - which is why an arrow click did
                                        ; nothing at all
    je .vup
    cmp di, SH_SB_DOWN
    je .vdn
    cmp di, SH_SB_PGUP
    je .vpgup
    cmp di, SH_SB_PGDN
    je .vpgdn
    mov ax, SH_SBRATE | (SH_SBRATE286 << 8)
    call os88ui_sbrate                 ; SB_THUMB. A rate of 2 ticks (~110ms)
    call os88ui_sbgrab                 ; rather than 0: the view FOLLOWS the
                                        ; thumb as it moves, throttled, which
                                        ; is 13.10.5.4's purpose - rate 0 means
                                        ; nothing moves until release, and then
                                        ; the final pos has to be recovered
                                        ; from os88ui_sbpos, an INTERNAL that
                                        ; answers in DI and wants the pointer's
                                        ; y that a release has but a drop does
                                        ; not naturally carry
    jmp .mine
.vup:
    mov ax, [sh_scrollrow]
    or ax, ax
    jz .mine
    dec ax
    jmp .vset
.vdn:
    mov ax, [sh_scrollrow]
    inc ax
    jmp .vset
.vpgup:
    mov ax, [sh_scrollrow]
    sub ax, [sh_vrows]
    jns .vset
    xor ax, ax
    jmp .vset
.vpgdn:
    mov ax, [sh_scrollrow]
    add ax, [sh_vrows]
.vset:
    call sh_setscrollrow
    jmp .mine

.tryh:
    mov bx, sh_hsb                     ; --- the horizontal bar
    call sh_hsb_hit
    cmp al, SH_SB_NONE
    je .notmine
    xor ah, ah                         ; same AX-clobber trap as the vertical
    mov di, ax                         ; branch above
    mov ax, [sh_scrollcol]
    mov [sh_sb_oldpos], ax
    cmp di, SH_SB_UP
    je .hlf
    cmp di, SH_SB_DOWN
    je .hrt
    cmp di, SH_SB_PGUP
    je .hpgup
    cmp di, SH_SB_PGDN
    je .hpgdn
    call sh_hsb_grab                   ; SB_THUMB
    jmp .mine
.hlf:
    mov ax, [sh_scrollcol]
    or ax, ax
    jz .mine
    dec ax
    jmp .hset
.hrt:
    mov ax, [sh_scrollcol]
    inc ax
    jmp .hset
.hpgup:
    mov ax, [sh_scrollcol]
    sub ax, [sh_vcols]
    jns .hset
    xor ax, ax
    jmp .hset
.hpgdn:
    mov ax, [sh_scrollcol]
    add ax, [sh_vcols]
.hset:
    call sh_setscrollcol
.mine:
    pop di
    pop bx
    pop ax
    stc
    ret
.notmine:
    pop di
    pop bx
    pop ax
    clc
    ret

; -----------------------------------------------------------------------------
; sh_onwheel - W_ONWH (SPEC.md 13.18): AX = signed notches, SI = window, gfx
; lock held, W_ONKEY's environment. WHEEL_STEPS ROWS a notch - a sheet row is
; the grid's line - through sh_setscrollrow, the vertical arrows' own path, so
; the view blits and letters only the vacated rows exactly as an arrow click
; does, and draws nothing when it did not move. The VIEW moves; the selection
; does not, as a scroll-bar click leaves it.
;
; The block's pos is CLAMPED to total - fit (sh_sbsync's own note) while the
; view itself may sit past it - keyboard navigation and Goto move the origin
; without consulting the bar - so os88ui_sbwheel's CF ("pos unchanged") is not
; read: going UP from past the end lands inside the extent, which is a move
; the CF would have refused, and going DOWN from there would answer the clamp,
; which is UP, so a down turn that would raise the view is dropped instead.
; -----------------------------------------------------------------------------
sh_onwheel:
    call sh_abdismiss                  ; the credits are up: the turn is spent
    jc .ret                            ; taking them down, as a key's is
    push ax
    push bx
    push cx
    push dx
    mov dx, ax                         ; the turn's direction, for the guard
    mov bx, si
    call sh_geom                       ; [sh_vrows], which sh_sbsync's fit is
    call sh_sbsync
    mov bx, sh_vsb
    mov cx, 1                          ; ONE LINE is one row in this bar
    call os88ui_sbwheel                ; -> AX = the row the view belongs at
    or dx, dx
    js .go
    cmp ax, [sh_scrollrow]
    jb .out                            ; down never moves the view up
.go:
    call sh_setscrollrow
.out:
    pop dx
    pop cx
    pop bx
    pop ax
.ret:
    ret

; -----------------------------------------------------------------------------
; sh_setscrollrow / sh_setscrollcol - move the view to AX, clamped to the
; scrollable extent, and paint the move if it actually happened - the
; surviving rows blitted and only the vacated ones lettered (vertical), or
; the grid's own strip repainted (horizontal; OSAPI_GFX_SCROLL is
; vertical-only, SPEC.md 5.5). SI = the window.
; -----------------------------------------------------------------------------
sh_setscrollrow:
    push ax
    push bx
    push cx
    mov cx, [sh_vsb + 8]               ; total
    sub cx, [sh_vsb + 10]              ; ...minus fit = the last legal pos,
    jns .rok                           ; relative to the scrolling region
    xor cx, cx
.rok:
    add cx, [sh_freezerow]             ; 81.70: back to an ABSOLUTE row -
    cmp ax, cx                         ; every caller passes AX absolute
    jbe .rset
    mov ax, cx
.rset:
    cmp ax, [sh_freezerow]             ; 81.70: the frozen prefix is the
    jae .rset2                         ; floor - scrolling can never uncover
    mov ax, [sh_freezerow]             ; less of it than that
.rset2:
    cmp ax, [sh_scrollrow]
    je .rout                           ; no movement: draw nothing
    mov cx, [sh_scrollrow]             ; the row the view is leaving
    mov [sh_scrollrow], ax
    call sh_scrollrow_blit
    jnc .rout
    call sh_repaint                    ; the blit refused: pay the full price
.rout:
    pop cx
    pop bx
    pop ax
    ret

sh_setscrollcol:
    push ax
    push bx
    push cx
    mov cx, [sh_hsb + 8]
    sub cx, [sh_hsb + 10]
    jns .cok
    xor cx, cx
.cok:
    add cx, [sh_freezecol]             ; 81.70: the vertical bar's own
    cmp ax, cx                         ; comment applies here too
    jbe .cset
    mov ax, cx
.cset:
    cmp ax, [sh_freezecol]
    jae .cset2
    mov ax, [sh_freezecol]
.cset2:
    cmp ax, [sh_scrollcol]
    je .cout
    mov [sh_scrollcol], ax
    call sh_scrollcol_part
.cout:
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_scrollrow_blit - move the grid by whole rows with OSAPI_GFX_SCROLL
; instead of repainting every visible cell: the surviving rows are one blit,
; and only the |delta| vacated ones are lettered (~7 runs for an arrow click
; instead of ~119).
; in:  CX = the scroll row the view is leaving, SI = the window;
;      [sh_scrollrow] already holds the new one.
; out: CF=0 the view is painted; CF=1 nothing was drawn and the caller owes
;      the full repaint - the blit refused (the clip does not wholly contain
;      the rect, SPEC.md 5.5), the byte-alignment round-up would reach the
;      vertical bar, or the delta leaves no surviving band worth keeping.
; -----------------------------------------------------------------------------
sh_scrollrow_blit:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si
    call sh_geom                       ; fresh geometry: the drag path arrives
                                        ; without sh_onclick's own sh_geom
    cmp word [sh_vcols], 0
    je .no
    cmp word [sh_vrows], 0
    je .no
    ; FROZEN ROWS REFUSE THE BLIT (81.70). OSAPI_GFX_SCROLL shifts a whole
    ; rect's pixels, and the frozen strip's must not move with the rest -
    ; cutting the rect below it is real work in the one routine whose
    ; rectangle arithmetic is hardest to get right, for a saving only a
    ; frozen sheet being scrolled would ever see. The caller already owns a
    ; refusal path (it repaints), so this takes it
    cmp word [sh_freezerow], 0
    jne .no
    mov ax, [sh_scrollrow]
    sub ax, cx                         ; ax = the delta, in rows (signed)
    mov [sh_blitdel], ax
    mov di, ax
    or di, di
    jns .abs
    neg di                             ; di = |delta|
.abs:
    cmp di, [sh_vrows]
    jae .no                            ; nothing survives: repaint instead
    ; ONE HEIGHT, OR NO BLIT (81.60): the band moves by delta rows of one
    ; height, which is only the picture when every row either view shows -
    ; and the one past each, which decides how many fit - is the standard
    mov ax, cx
    mov dx, [sh_scrollrow]
    cmp ax, dx
    jbe .span
    xchg ax, dx
.span:
    add dx, [sh_vrows]
    call sh_rh_anyin
    jc .no

    ; The rect. x1 and x2+1 must be multiples of 8 (the blit is byte-column
    ; granular, SPEC.md 5.5): x1 rounds DOWN into the row-header strip,
    ; which is redrawn whole below anyway; x2+1 rounds UP into the dead
    ; space right of the last gridline - refused if that would reach the
    ; vertical bar, whose pixels must not move.
    mov ax, [sh_ox]
    add ax, SH_RH_W
    and ax, 0xFFF8
    mov [sh_blitx1], ax
    mov ax, [sh_vcols]
    call sh_vcx                        ; each column its own width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W                    ; ax = one past the grid's right edge
    add ax, 7
    and ax, 0xFFF8                     ; ...rounded up to the byte column
    mov dx, [sh_ox]
    add dx, [sh_cw]
    sub dx, SH_VSB_W                   ; dx = the vertical bar's x1
    cmp ax, dx
    ja .no
    dec ax
    mov [sh_blitx2], ax
    mov ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov [sh_blity1], ax
    mov bx, ax
    mov ax, [sh_vrows]
    mov dx, SH_RH_NORMAL               ; every row the standard, checked above
    mul dx
    add ax, bx
    dec ax
    mov [sh_blity2], ax

    mov ax, [sh_blitdel]
    mov dx, SH_RH_NORMAL
    imul dx                            ; the delta is under vrows, so AX is
    mov si, ax                         ; the whole of it: SI = signed dy
    mov ax, [sh_blitx1]
    mov bx, [sh_blity1]
    mov cx, [sh_blitx2]
    mov dx, [sh_blity2]
    call OSAPI_GFX_SCROLL              ; positive dy = content UP = view DOWN
    jc .no                             ; refused: nothing moved, fall back

    xor ax, ax                         ; the vacated rows, and only them:
    cmp word [sh_blitdel], 0           ; scrolled up = new rows on top,
    jl .vac                            ; scrolled down = at the bottom
    mov ax, [sh_vrows]
    sub ax, di
.vac:
    mov [sh_dmgr1], ax
    add ax, di
    dec ax
    mov [sh_dmgr2], ax
    xor ax, ax
    mov [sh_dmgc1], ax
    mov ax, [sh_vcols]
    dec ax
    mov [sh_dmgc2], ax
    call sh_dmgdraw
    call sh_drawsel                    ; the frame's share of the vacated
                                        ; band - its surviving part moved
                                        ; WITH the blit, to exactly where the
                                        ; frame now belongs

    mov al, CWHITE                     ; the row headers: every number
    call OSAPI_SET_COLOR               ; changed places, and their text is
    mov ax, [sh_ox]                    ; transparent, so the strip is erased
    mov bx, [sh_blity1]                ; first
    mov cx, [sh_ox]
    add cx, SH_RH_W - 1
    mov dx, [sh_blity2]
    call OSAPI_GFX_FILL
    call sh_drawrowhdrs

    call sh_sbsync                     ; ...and the thumb moved
    mov bx, sh_vsb
    call os88ui_sbar
    clc
    jmp .out
.no:
    stc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_scrollcol_part - a horizontal scroll has no blit primitive to lean on,
; but it still owes nothing to the menu bar, the formula bar, the status bar
; or the vertical scroll bar: the grid, the column letters and the
; horizontal thumb are the whole of what moved - and no recalc pass, because
; no cell changed. SI = the window.
; -----------------------------------------------------------------------------
sh_scrollcol_part:
    push ax
    push bx
    push cx
    push dx
    mov bx, si
    call sh_geom                       ; sh_scrollrow_blit's reason
    ; THE STRIP PAST THE LAST WHOLE COLUMN (81.56): with one width it was
    ; always narrower than a column and the same each time; with each column
    ; its own, scrolling changes it, and the cells alone never cover it
    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov ax, [sh_vcols]
    call sh_vcx
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov cx, [sh_ox]
    add cx, [sh_cw]
    sub cx, SH_VSB_W + 1
    cmp ax, cx
    ja .nostrip
    mov bx, [sh_goy]
    add bx, SH_FB_H
    mov dx, [sh_oy]
    add dx, [sh_ch]
    sub dx, SH_SB_H + SH_HSB_H + 1
    call OSAPI_GFX_FILL
.nostrip:
    call sh_dmgfull
    call sh_dmgdraw
    call sh_drawsel
    cmp word [sh_vcols], 0
    je .nohdr
    mov al, CWHITE                     ; the column letters all changed
    call OSAPI_SET_COLOR               ; places; their text is transparent,
    mov ax, [sh_ox]                    ; so the strip is erased first
    add ax, SH_RH_W
    mov bx, [sh_goy]
    add bx, SH_FB_H
    push ax
    mov ax, [sh_vcols]
    call sh_vcx                        ; each column its own width (81.56)
    mov cx, ax
    pop ax
    add cx, ax
    dec cx
    mov dx, [sh_goy]
    add dx, SH_FB_H + SH_CH_H - 1
    call OSAPI_GFX_FILL
    call sh_drawcolhdrs
.nohdr:
    call sh_sbsync                     ; the horizontal thumb moved
    mov bx, sh_hsb
    call sh_hsb_draw
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_flrect - stage 3.0b: point the formula bar's line block at the content
; box's CURRENT screen rect. Called before every draw and every hit-test
; rather than once at startup, because the window moves and resizes and
; os88line reads the same four words for both drawing and clicking - a stale
; rect would put the caret somewhere the box no longer is. These are exactly
; the coordinates sh_drawbar frames the content box with, so the field's own
; frame lands on top of the same pixels.
; -----------------------------------------------------------------------------
sh_flrect:
    push ax
    mov ax, [sh_ox]
    add ax, SH_REF_W
    mov [sh_fline + LN_X1], ax
    mov ax, [sh_goy]
    mov [sh_fline + LN_Y1], ax
    mov ax, [sh_ox]
    add ax, [sh_cw]
    dec ax
    mov [sh_fline + LN_X2], ax
    mov ax, [sh_goy]
    add ax, SH_FB_H - 1
    mov [sh_fline + LN_Y2], ax
    pop ax
    ret

sh_drawbar:
    push ax
    push bx
    push cx
    push dx
    push si
    push di

    mov al, CBLACK
    call OSAPI_SET_COLOR

    ; --- reference box outline: (ox, goy) to (ox+SH_REF_W-1, goy+SH_FB_H-1) ---
    mov ax, [sh_ox]
    mov bx, ax
    add bx, SH_REF_W - 1
    mov dx, [sh_goy]
    call OSAPI_GFX_HLINE
    add dx, SH_FB_H - 1
    call OSAPI_GFX_HLINE
    mov ax, [sh_ox]
    mov bx, [sh_goy]
    mov dx, [sh_goy]
    add dx, SH_FB_H - 1
    call OSAPI_GFX_VLINE
    mov ax, [sh_ox]
    add ax, SH_REF_W - 1
    call OSAPI_GFX_VLINE               ; also the content box's own left edge

    ; --- content box outline: (ox+SH_REF_W, goy) to (ox+cw-1, goy+SH_FB_H-1) ---
    mov ax, [sh_ox]
    add ax, SH_REF_W
    mov bx, [sh_ox]
    add bx, [sh_cw]
    dec bx
    mov dx, [sh_goy]
    call OSAPI_GFX_HLINE
    add dx, SH_FB_H - 1
    call OSAPI_GFX_HLINE
    mov ax, [sh_ox]
    add ax, [sh_cw]
    dec ax
    mov bx, [sh_goy]
    mov dx, [sh_goy]
    add dx, SH_FB_H - 1
    call OSAPI_GFX_VLINE

    ; --- the reference box's interior, erased: its text is transparent and
    ; this bar repaints on every selection move WITHOUT the window-wide
    ; white fill behind it now (sh_selpaint), so it owns its own pixels ---
    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov ax, [sh_ox]
    inc ax
    mov bx, [sh_goy]
    inc bx
    mov cx, [sh_ox]
    add cx, SH_REF_W - 2
    mov dx, [sh_goy]
    add dx, SH_FB_H - 2
    call OSAPI_GFX_FILL
    mov al, CBLACK
    call OSAPI_SET_COLOR

    ; --- reference text, into sh_tbuf ---
    ; Formula > Reference switches this between A1 and R1C1, which is the only
    ; place in the app that had an answer to show: the A1<->R1C1 converters
    ; already existed for SYLK's own ;E field (81.7.1), and this is what makes
    ; the setting visible rather than a file-format detail.
    mov di, sh_tbuf
    cmp byte [sh_a1style], 0
    jne .refrc
    mov ax, [sh_selcol]
    call sh_colname
    mov si, sh_colbuf
    call sh_strcpy_to_di
    mov ax, [sh_selrow]
    inc ax
    call sh_itoa
    mov si, sh_numbuf
    call sh_strcpy_to_di
    jmp .refdone
.refrc:
    mov byte [di], 'R'
    inc di
    mov ax, [sh_selrow]
    inc ax
    call sh_itoa
    mov si, sh_numbuf
    call sh_strcpy_to_di
    mov byte [di], 'C'
    inc di
    mov ax, [sh_selcol]
    inc ax
    call sh_itoa
    mov si, sh_numbuf
    call sh_strcpy_to_di
.refdone:
    mov cx, [sh_ox]
    add cx, 4
    mov dx, [sh_goy]
    add dx, 4
    mov si, sh_tbuf
    call OSAPI_FONT_STR_XPARENT

    ; --- while EDITING, the content box is a real text field: os88line owns
    ; the box, the text, the caret and the horizontal scroll, so this path
    ; hands it over entirely rather than drawing a string itself.
    cmp byte [sh_editing], 0
    je .static
    call sh_flrect
    mov si, sh_fline
    call sh_flmarg                     ; the span between the frame and the
    call os88line_draw                 ; field's 8-aligned pen, which the
    jmp .done                          ; field's own one-pass draw never
                                        ; touches

.static:
    ; --- not editing: the cell's current value/formula, as static text, into
    ; sh_tbuf+16 (past the reference text's own small span, so the two never
    ; overlap in the same shared buffer) ---
    mov di, sh_tbuf + 16
    push di                            ; sh_findcell's own DI output would
                                        ; otherwise clobber our cursor
    cmp byte [sh_protected], 0         ; HIDDEN is the half of cell protection
    je .nothidden                      ; that is about LOOKING rather than
    mov ax, [sh_selcol]                ; changing, and this bar is the only
    mov bx, [sh_selrow]                ; place a formula is ever shown as
    call sh_bt_get                     ; itself - the grid shows its RESULT.
    test al, SH_PROT_HIDDEN            ; So the whole of hiding one is here
    jnz .empty2                        ; (81.46.2)
.nothidden:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_findcell
    jnc .empty2
    push es
    mov es, [sh_cellseg]
    test byte [es:di+4], 1
    jnz .isformula
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT     ; stage 4.5: a label shows its
    jne .plainval2                     ; own text here, unprefixed - the '='
    mov ax, [es:di+SH_C_FOFF]          ; below is what makes a formula look
    pop es                             ; like one, and a label is not one
    pop di
    mov si, ax
    push es
    mov es, [sh_txtseg]
    jmp .copyfm
.isformula:
    mov ax, [es:di+SH_C_FOFF]                 ; formula_off
    pop es
    pop di                             ; DI = content cursor, restored
    mov byte [di], '='
    inc di
    mov si, ax
    push es
    mov es, [sh_txtseg]
.copyfm:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .copyfm
    pop es
    jmp .draw
.plainval2:
    call sh_cellnum                    ; sh_numbuf already holds the decimal
    pop es                             ; text; sh_itoa would overwrite it with
    pop di                             ; the low word's worth
    mov si, sh_numbuf
    call sh_strcpy_to_di
    jmp .draw
.empty2:
    pop di                             ; DI = content cursor, restored
    mov byte [di], 0
.draw:
    mov al, CWHITE                     ; the content box's interior, erased:
    call OSAPI_SET_COLOR               ; the text below is transparent and of
    mov ax, [sh_ox]                    ; varying length (the ref box's reason
    add ax, SH_REF_W + 1               ; above)
    mov bx, [sh_goy]
    inc bx
    mov cx, [sh_ox]
    add cx, [sh_cw]
    sub cx, 2
    mov dx, [sh_goy]
    add dx, SH_FB_H - 2
    call OSAPI_GFX_FILL
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov cx, [sh_ox]
    add cx, SH_REF_W + 4
    mov dx, [sh_goy]
    add dx, 3                          ; the same row os88line's own run uses
                                        ; (LN_INSET), so the field covers this
                                        ; text exactly when an edit begins
    mov si, sh_tbuf + 16
    call OSAPI_FONT_STR_XPARENT
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawstatus - the status bar: a single divider line above a strip at
; the very bottom of the content area, showing [sh_msg] if a command just
; set one, else the idle "Ready" real Excel's own status bar shows.
; -----------------------------------------------------------------------------
sh_drawstatus:
    push ax
    push bx
    push cx
    push dx
    push si

    mov al, CWHITE                     ; the strip's interior, erased: the
    call OSAPI_SET_COLOR               ; message is transparent text of
    mov ax, [sh_ox]                    ; varying length, and this bar repaints
    mov bx, [sh_oy]                    ; on selection moves without the
    add bx, [sh_ch]                    ; window-wide white fill behind it
    sub bx, SH_SB_H                    ; (sh_selpaint)
    inc bx
    mov cx, [sh_ox]
    add cx, [sh_cw]
    dec cx
    mov dx, [sh_oy]
    add dx, [sh_ch]
    dec dx
    call OSAPI_GFX_FILL

    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_ox]
    mov bx, ax
    add bx, [sh_cw]
    dec bx
    mov dx, [sh_oy]
    add dx, [sh_ch]
    sub dx, SH_SB_H
    call OSAPI_GFX_HLINE

    mov si, [sh_msg]
    or si, si
    jnz .havemsg
    mov si, sh_s_ready
.havemsg:
    mov cx, [sh_ox]
    add cx, 4
    mov dx, [sh_oy]
    add dx, [sh_ch]
    sub dx, SH_SB_H
    add dx, 4
    call OSAPI_FONT_STR_XPARENT

    ; The right-hand indicator block, which real Excel uses for NUM/CAPS/SCRL
    ; and for the word CALCULATE when Manual mode has left the sheet stale.
    ; CALCULATE takes precedence, because it is the one that means something
    ; is WRONG on screen rather than something is set on the keyboard.
    ; 81.114.8: and CALCULATE means the same thing under the middle mode,
    ; but only when there is a table to be stale - "automatic except tables"
    ; on a sheet with no table recalculates everything, so nothing is owed.
    mov si, sh_s_num
    cmp byte [sh_calcmode], SH_CALC_MANUAL
    jae .stale
    cmp byte [sh_calcmode], SH_CALC_AUEX
    jne .indi
    cmp word [sh_ntbl], 0
    je .indi
.stale:
    mov si, sh_s_calcind
.indi:
    ; 81.104: Excel's two things here - a DIVIDER between the message and the
    ; indicators, and the indicator drawn INVERTED. The divider is one vline
    ; down the strip's interior; the pen is still the hline's black
    mov ax, [sh_ox]
    add ax, [sh_cw]
    sub ax, SH_SB_DIVX
    mov bx, [sh_oy]
    add bx, [sh_ch]
    sub bx, SH_SB_H
    inc bx
    mov dx, [sh_oy]
    add dx, [sh_ch]
    dec dx
    call OSAPI_GFX_VLINE
    mov cx, [sh_ox]
    add cx, [sh_cw]
    sub cx, 88
    mov dx, [sh_oy]
    add dx, [sh_ch]
    sub dx, SH_SB_H
    add dx, 4
    ; the inverted box: a 1px frame JUST OUTSIDE the run, then the run white
    ; on black, OPAQUE (SPEC.md 6.6) - no pixel of the box is written twice,
    ; and this was one of the file's transparent calls, so the registry
    ; goes 17 -> 16
    push cx
    push dx
    call OSAPI_FONT_WIDTH             ; AX = the indicator's width
    mov bx, dx
    dec bx                            ; y1 = the run's top - 1
    add dx, 8                         ; y2 = its bottom + 1
    xchg ax, cx                       ; CX = width, AX = x
    add cx, ax                        ; x2 = x + width
    dec ax                            ; x1 = x - 1
    call OSAPI_GFX_FRAME
    pop dx
    pop cx
    mov ax, (CBLACK << 8) | CWHITE    ; AL = ink, AH = ground
    call OSAPI_FONT_RUN

    ; ...AND THE GROW BOX BACK (SPEC.md 11.1/81.112). The white fill at the
    ; top of this routine runs to the content's right edge, and since 81.112
    ; made the window sizable the kernel's 13x13 box lives in that strip's
    ; bottom-right corner - so every selection move ate it, while wm_hit went
    ; on reporting AL=4 from geometry alone: an invisible corner that still
    ; resizes, which is the failure OSAPI_WM_GROW's own banner names. ONE call
    ; here covers all eight callers, sh_repaint's full repaint among them,
    ; because the fill that erases the box is this one. The indicator block
    ; above stops at sh_cw-16 and the box starts at sh_cw-13, so they do not
    ; overlap; the strip's top rule is at sh_ch-16, three rows above the box.
    mov bx, [sh_ownwin]               ; Word and Browser spell this `mov bx,
    call OSAPI_WM_GROW                ; si` - SI is the window in their paints
                                       ; and is the message string in this one

    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawhdrrules - 81.116.1: the CORNER BOX that encloses the headers (stage
; 1.8's item 10 - "lines through the header row and column, and a corner
; box"). SHEET's letters and numbers floated outside the grid with no lines.
;
; TWO SHORT RULES AND NOT TWO LONG ONES: row 1's own top gridline already
; rules the column headers off across the width of the grid, and column A's
; own left gridline does the same down its height. All that was missing is
; the L that closes the corner - so these two spans are the row-header
; column's width and the column-header band's height, and nothing else.
;
; SOLID, where the cell gridlines next door are dotted (81.116), which is
; Excel's own distinction rather than an oversight: a header rule is a real
; edge and a gridline is a guide.
;
; THE CORNER BOX IS WHERE THE TWO MEET and needs no third call - which is
; what keeps this inside SHEET's resident headroom. Per-header separators
; were written first and taken out: they are 27 more one-pixel fills on a
; ten-by-fifteen viewport, they are not what the look report asked for, and
; the routine did not FIT - 129 bytes is what the package has (81.115), and
; this engine cannot move to CHART.OVL the way the dialogs did, because a
; repaint may not depend on an on-demand overlay being loaded.
;
; TWO fills on a full repaint, at the 608.61 us Set 163 measured: ~1.2 ms
; against the ~3 ms a SINGLE cell's opaque text run costs. Not on the damage
; path - a cell edit repaints its own rect and never comes here.
; -----------------------------------------------------------------------------
sh_drawhdrrules:
    push ax
    push bx
    push cx
    push dx
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_ox]                   ; under the ROW-HEADER column only -
    mov cx, ax                        ; row 1's own top gridline already rules
    add cx, SH_RH_W - 1               ; the column headers off for the width of
                                      ; the grid, and a second line one pixel
                                      ; above it put a GAP OF 1 in the row list
                                      ; tests/glass.py's rgrid walks
    mov bx, [sh_goy]
    add bx, SH_FB_H + SH_CH_H - 1
    mov dx, bx
    call OSAPI_GFX_FILL
    mov ax, [sh_ox]                   ; ...and right of the row headers -
    add ax, SH_RH_W - 1               ; THROUGH THE HEADER BAND ONLY, which is
    mov cx, ax                        ; what makes the corner box. Column A's
    mov bx, [sh_goy]                  ; own left gridline already rules the
    add bx, SH_FB_H                   ; headers off for the whole grid height,
    mov dx, bx                        ; so a second line beside it is
    add dx, SH_CH_H - 1               ; redundant - and it broke
    call OSAPI_GFX_FILL               ; tests/glass.py's column walk, which
                                      ; reads the row-header column from the
                                      ; GAP between the first two lines and
                                      ; found 161 where it wanted 36..46
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawcolhdrs - the column letters, centred in each visible column's band
; -----------------------------------------------------------------------------
sh_drawcolhdrs:
    push ax
    push bx
    push cx
    push dx
    push si
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov word [sh_wcol], 0
.col:
    mov bx, [sh_wcol]
    cmp bx, [sh_vcols]
    jae .out
    mov ax, bx
    call sh_vreal_col                  ; 81.70
    call sh_colname
    mov ax, bx
    call sh_vcx                        ; each letter over its own column
    add ax, [sh_ox]                    ; (81.56)
    add ax, SH_RH_W
    mov cx, ax
    mov si, sh_colbuf
    call OSAPI_FONT_WIDTH
    push ax
    mov ax, [sh_wcol]
    call sh_vwidth
    mov dx, ax
    pop ax
    sub dx, ax
    shr dx, 1
    add cx, dx
    mov dx, [sh_goy]
    add dx, SH_FB_H
    mov si, sh_colbuf
    call OSAPI_FONT_STR_XPARENT
    mov bx, [sh_wcol]
    inc bx
    mov [sh_wcol], bx
    jmp .col
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawrowhdrs - the row numbers, right-aligned in SH_RH_W
; -----------------------------------------------------------------------------
sh_drawrowhdrs:
    push ax
    push bx
    push cx
    push dx
    push si
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov word [sh_wrow], 0
.row:
    mov bx, [sh_wrow]
    cmp bx, [sh_vrows]
    jae .out
    mov ax, bx
    call sh_vreal_row                  ; 81.70
    inc ax
    call sh_itoa
    mov si, sh_numbuf
    call OSAPI_FONT_WIDTH
    mov cx, SH_RH_W - 4
    sub cx, ax
    add cx, [sh_ox]
    mov ax, bx
    call sh_vry                        ; its own top (81.60)...
    mov dx, ax
    mov ax, bx
    call sh_vtoff                      ; ...and as low as its cells' text
    add dx, ax
    add dx, [sh_goy]
    add dx, SH_FB_H + SH_CH_H
    mov si, sh_numbuf
    call OSAPI_FONT_STR_XPARENT
    mov bx, [sh_wrow]
    inc bx
    mov [sh_wrow], bx
    jmp .row
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawgrid - every cell in the damage range (sh_dmgc1..sh_dmgr2, window-
; relative - sh_dmgfull for the whole viewport) as one fixed-width
; OSAPI_FONT_RUN, number-formatted and justified per its own SH_FMT_* bits
; (stage 1.6), all spaces for empty. Sparse lookup: no bitmap.
; -----------------------------------------------------------------------------
sh_drawgrid:
    push ax
    push bx
    push cx
    push dx
    push si
    cmp word [sh_vcols], 0
    je .out
    cmp word [sh_vrows], 0
    je .out
    mov ax, [sh_dmgr1]
    mov [sh_wrow], ax
.row:
    mov ax, [sh_wrow]
    cmp ax, [sh_dmgr2]
    ja .out
    call sh_vheight                    ; THIS ROW'S OWN HEIGHT (81.60), and
    mov [sh_cellh], ax                 ; how far down it the text sits
    mov ax, [sh_wrow]
    call sh_vtoff
    mov [sh_rtoff], ax
    mov ax, [sh_dmgc1]
    mov [sh_wcol], ax
.col:
    mov ax, [sh_wcol]
    cmp ax, [sh_dmgc2]
    ja .rownext
    call sh_vwidth                     ; THIS COLUMN'S OWN WIDTH (81.56): the
    mov [sh_cellw], ax                 ; justifiers, the number fit, the blank
    mov cl, 3                          ; and the spill all read these two, so
    shr ax, cl                         ; setting them per cell is all they
    mov [sh_cellch], ax                ; need to know about it
    call sh_mkblank
    mov ax, [sh_wcol]
    call sh_vreal_col                  ; 81.70
    push ax                            ; the real column, banked - sh_vreal_
    mov ax, [sh_wrow]                  ; row only touches AX and flags, but
    call sh_vreal_row                  ; the bank costs nothing to be sure
    mov bx, ax
    pop ax
    call sh_getcell2
    jc .have
    call sh_spill                      ; ...unless a label to its left runs
    mov si, sh_tbuf                    ; on into it (81.54) - MOV keeps CF
    jc .got
    mov si, sh_blank
    jmp .got
.have:
    cmp byte [sh_showformulas], 0      ; stage 2.x Options > Formulas: On -
    je .valpath                        ; show the formula TEXT, not its
                                        ; value, matching real Excel's
                                        ; Display dialog's "Formulas" box.
                                        ; AX/BX are still this cell's own
                                        ; col/row (sh_getcell2 preserves
                                        ; both), so re-finding it costs
                                        ; nothing extra to set up.
    call sh_findcell
    jnc .valpath                       ; can't happen (getcell2 said
                                        ; occupied) - stay safe regardless
    push es
    mov es, [sh_cellseg]
    test byte [es:di+4], 1             ; HASFORMULA
    jz .noformula3
    mov ax, [es:di+SH_C_FOFF]                  ; formula_off
    pop es
    mov byte [sh_tbuf], '='
    mov di, sh_tbuf + 1
    mov si, ax
    push es
    mov es, [sh_txtseg]
.fcopy:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .fcopy
    pop es
    mov cx, di
    sub cx, sh_tbuf
    dec cx                             ; cx = chars written, excluding NUL
    cmp cx, [sh_cellch]
    jbe .fpad
    mov bx, [sh_cellch]
    mov byte [sh_tbuf + bx], 0         ; longer than a cell: truncate
    jmp .fshow
.fpad:
    mov ax, [sh_cellch]
    sub ax, cx
    jz .fshow
    mov cx, ax
.fploop:
    mov byte [di], ' '
    inc di
    loop .fploop
    mov byte [di], 0
.fshow:
    mov si, sh_tbuf
    jmp .got
.noformula3:
    pop es
.valpath:
    cmp byte [sh_curtype], SH_T_ERR    ; an error draws its NAME - the number
    je .errpath                        ; underneath it is meaningless
    cmp byte [sh_curtype], SH_T_TEXT   ; stage 4.5: a label draws its own
    je .textpath                       ; characters, not its value
    cmp byte [sh_curtype], SH_T_BOOL   ; ...and a LOGICAL its name (81.51),
    je .boolpath                       ; which no number format touches
    call sh_bt_getw                    ; AH = its number format, beside its
    mov bh, ah                         ; border (81.55)
    mov bl, [sh_curfmt]
    mov ax, dx
    call sh_numfmt
    call sh_justify
    mov si, sh_tbuf
    jmp .got
.boolpath:
    mov ax, dx
    call sh_boolname                   ; -> sh_numbuf
    jmp short .centred
.errpath:
    call sh_errname                    ; -> sh_numbuf
.centred:
    mov bl, [sh_curfmt]
    call sh_justify_c                  ; General CENTRES a logical and an
    mov si, sh_tbuf                    ; error, Excel's third General rule
    jmp .got                           ; beside numbers right and labels left.
                                       ; An error sat right, "like the number
                                       ; it replaces", until 81.51
.textpath:
    call sh_text_to_numbuf             ; the arena string, clipped to the cell
    mov bl, [sh_curfmt]
    call sh_justify_t                  ; General means LEFT for a label
    mov si, sh_tbuf
.got:
    mov ax, [sh_wcol]
    call sh_vcx                        ; its own left edge (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov cx, ax
    mov ax, [sh_wrow]
    call sh_vry                        ; its own top (81.60)
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov dx, ax                         ; DX = the cell's top, for the shade;
                                       ; the text goes sh_rtoff below it
    ; stage 2.x: a Shaded cell (Format > Border..., real Excel's own Shade
    ; checkbox) needs the grey dither drawn FIRST and the text drawn
    ; TRANSPARENT over it - OSAPI_FONT_RUN's opaque erase-then-letter would
    ; otherwise wipe the dither right back out on every single repaint
    push cx
    push dx
    mov ax, [sh_wcol]
    call sh_vreal_col                  ; 81.70
    push ax
    mov ax, [sh_wrow]
    call sh_vreal_row
    mov bx, ax
    pop ax
    call sh_bt_get                     ; al = this cell's border byte
    pop dx
    pop cx
    test al, SH_BORD_SHADE
    jz .noshade
    push cx
    push dx
    mov ax, cx
    mov bx, dx
    add cx, [sh_cellw]
    dec cx
    add dx, [sh_cellh]
    dec dx
    call OSAPI_GFX_FILL_GRAY
    pop dx
    pop cx
    add dx, [sh_rtoff]
    mov al, CBLACK
    call OSAPI_SET_COLOR
    call OSAPI_FONT_STR_XPARENT
    jmp .aftertext
.noshade:
    add dx, [sh_rtoff]
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN
.aftertext:
    test byte [sh_curfmt], SH_FMT_BOLD
    jz .nobold
    push cx
    push dx
    inc cx
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_STR_XPARENT                ; a 1px-right overprint - the same
                                        ; double-strike trick texpad uses
                                        ; for bold on this same 8x8 font
    pop dx
    pop cx
.nobold:
    test byte [sh_curfmt], SH_FMT_UNDER
    jz .nounder
    call sh_drawunderline
.nounder:
    mov ax, [sh_wcol]
    inc ax
    mov [sh_wcol], ax
    jmp .col
.rownext:
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    jmp .row
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawlines - the cell-boundary lines over the damage range (sh_dmgc1..
; sh_dmgr2; sh_dmgfull for the whole viewport): c2-c1+2 vertical and r2-r1+2
; horizontal, each a degenerate (1px) rectangle spanning just the damaged
; cells. Drawn AFTER sh_drawgrid: OSAPI_FONT_RUN's opaque erase is exactly
; one cell wide and would otherwise paint back over a line drawn first.
;
; 81.116: THE RECTANGLE IS FILLED WITH THE 50% DITHER AND NOT WITH BLACK,
; because on a ONE-PIXEL line a dither IS a dotted line - which is what Excel
; draws (the 1.8 look measurement's item 9, the most visible difference in
; the grid). gfx_fill_gray's pattern is 0AAh on even rows and 55h on odd, so
; a horizontal line alternates along its length and a vertical one alternates
; down it, from the same primitive and with no pattern to stage.
;
; AND IT IS FREE - measured, because the look report said to price pattern
; lines before drawing them and expected them to cost more. On a 4.77MHz 8088
; GFX_FILL_GRAY 256x1 is 599.49 us against GFX_FILL 256x1's 608.61, so the
; dotted line is 9 us FASTER (PERFORMANCE.md Set 163). A one-row solid fill
; pays for arming Set/Reset and for two masked edge columns; the gray body
; writes a pattern byte a row and nothing else.
; -----------------------------------------------------------------------------
sh_drawlines:
    push ax
    push bx
    push cx
    push dx
    cmp byte [sh_gridlines], 0         ; stage 2.x Options > Gridlines: Off
    je .out                            ; skips this whole pass, same as real
                                        ; Excel's Display dialog
    cmp word [sh_vcols], 0
    je .out
    cmp word [sh_vrows], 0
    je .out
    mov al, CBLACK
    call OSAPI_SET_COLOR

    mov ax, [sh_dmgr1]                 ; the damaged rows' pixel span, each
    call sh_vry                        ; its own height (81.60)...
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov [sh_ly1], ax
    mov ax, [sh_dmgr2]
    inc ax
    call sh_vry
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    dec ax
    mov [sh_ly2], ax

    mov ax, [sh_dmgc1]                 ; ...and the damaged columns', each
    call sh_vcx                        ; its own width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov [sh_lx1], ax
    mov ax, [sh_dmgc2]
    inc ax
    call sh_vcx
    add ax, [sh_ox]
    add ax, SH_RH_W
    dec ax
    mov [sh_lx2], ax

    mov ax, [sh_dmgc1]
    mov [sh_wcol], ax
.vline:
    mov ax, [sh_wcol]
    mov dx, [sh_dmgc2]
    inc dx
    cmp ax, dx
    ja .vdone
    call sh_vcx
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov cx, ax
    mov bx, [sh_ly1]
    mov dx, [sh_ly2]
    call OSAPI_GFX_FILL                ; 81.116: solid for now - the dither
                                       ; is measured and deferred, see there
    mov ax, [sh_wcol]
    inc ax
    mov [sh_wcol], ax
    jmp .vline
.vdone:
    mov ax, [sh_dmgr1]
    mov [sh_wrow], ax
.hline:
    mov ax, [sh_wrow]
    mov dx, [sh_dmgr2]
    inc dx
    cmp ax, dx
    ja .hdone
    call sh_vry
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov bx, ax
    mov dx, ax
    mov ax, [sh_lx1]
    mov cx, [sh_lx2]
    call OSAPI_GFX_FILL                ; 81.116: ...and so is this one
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    jmp .hline
.hdone:
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawborders - the four directional edges (Left/Right/Top/Bottom) of
; every bordered cell (sh_bordseg) on the current sheet, within the visible
; scroll window AND the damage range (sh_dmgc1..sh_dmgr2; sh_dmgfull for the
; whole viewport). Shade is drawn from INSIDE sh_drawgrid instead, since it
; has to happen BEFORE that cell's own opaque text run, not after (see the
; comment there) - this routine only ever draws the four edge lines.
; Sparse walk of sh_bordseg (typically tiny - almost no cell has a border)
; rather than a per-cell probe, the same style sh_docmd_sortcol/
; sh_rowcol_op already walk-and-filter the main cell array with. Drawn
; AFTER sh_drawgrid for the same reason sh_drawlines already is:
; OSAPI_FONT_RUN's opaque erase is exactly one cell wide and would
; otherwise paint back over an edge drawn first.
; -----------------------------------------------------------------------------
sh_drawborders:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov word [sh_bti], 0               ; the scan index lives in bss, not
                                        ; CX - OSAPI_GFX_FILL below takes CX
                                        ; as one of its own four params, so
                                        ; a register loop counter would get
                                        ; clobbered by the very first edge
                                        ; it draws (caught in review)
.scan:
    mov cx, [sh_bti]
    cmp cx, [sh_nbord]
    jae .done
    mov ax, cx
    mov bx, SH_BT_SZ
    mul bx
    mov si, ax
    mov es, [sh_bordseg]
    mov ax, [es:si]                   ; packed row/sheet
    call sh_unpackrow                 ; ax=row, bx=sheet
    cmp bx, [sh_cursheet]
    jne .next
    push ax                           ; the real row, banked across the
                                       ; column's own lookup below (81.70) -
                                       ; sh_vidx_col/row are the real->
                                       ; visible inverse sh_vreal_col/row
    mov ax, [es:si+2]                 ; col
    call sh_vidx_col
    jnc .skiprow
    mov bx, ax
    cmp bx, [sh_dmgc1]                ; ...and inside the damage range, so a
    jb .skiprow                       ; partial redraw (sh_dmgdraw) does not
    cmp bx, [sh_dmgc2]                ; re-edge cells it never repainted
    ja .skiprow
    mov [sh_wcol], bx
    pop ax                            ; the real row, back
    call sh_vidx_row
    jnc .next
    mov bx, ax
    cmp bx, [sh_dmgr1]
    jb .next
    cmp bx, [sh_dmgr2]
    ja .next
    mov [sh_wrow], bx
    mov al, [es:si+4]
    mov [sh_bdrawflags], al
    mov ax, [sh_wcol]
    call sh_vcx                       ; its own left edge and width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov [sh_bx1], ax
    mov ax, [sh_wcol]
    call sh_vwidth
    add ax, [sh_bx1]
    dec ax
    mov [sh_bx2], ax
    mov ax, [sh_wrow]
    call sh_vheight                    ; its own top and height (81.60)
    mov bx, ax
    mov ax, [sh_wrow]
    call sh_vry
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov [sh_by1], ax
    add ax, bx
    dec ax
    mov [sh_by2], ax
    ; LEFT AND TOP SIT ONE PIXEL IN, mirroring right and bottom (81.17.2).
    ; A cell's gridlines are its OWN first column and row (sh_drawlines draws
    ; them at sh_vcx/sh_vry), so an edge drawn there landed on the gridline
    ; and vanished; one pixel in puts it beside this cell's own gridline, as
    ; right and bottom sit beside the next cell's.
    test byte [sh_bdrawflags], SH_BORD_LEFT
    jz .noleft
    mov ax, [sh_bx1]
    inc ax
    mov bx, [sh_by1]
    mov cx, ax
    mov dx, [sh_by2]
    call OSAPI_GFX_FILL
.noleft:
    test byte [sh_bdrawflags], SH_BORD_RIGHT
    jz .noright
    mov ax, [sh_bx2]
    mov bx, [sh_by1]
    mov cx, [sh_bx2]
    mov dx, [sh_by2]
    call OSAPI_GFX_FILL
.noright:
    test byte [sh_bdrawflags], SH_BORD_TOP
    jz .notop
    mov ax, [sh_bx1]
    mov bx, [sh_by1]
    inc bx
    mov cx, [sh_bx2]
    mov dx, bx
    call OSAPI_GFX_FILL
.notop:
    test byte [sh_bdrawflags], SH_BORD_BOTTOM
    jz .nobottom
    mov ax, [sh_bx1]
    mov bx, [sh_by2]
    mov cx, [sh_bx2]
    mov dx, [sh_by2]
    call OSAPI_GFX_FILL
.nobottom:
    jmp .next
.skiprow:
    pop ax                            ; the real row, banked above and never
                                       ; needed now the column already missed
.next:
    mov ax, [sh_bti]
    inc ax
    mov [sh_bti], ax
    jmp .scan
.done:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawsel - a black frame around the selected cell, if it is on screen
; -----------------------------------------------------------------------------
sh_drawsel:
    push ax
    push bx
    push cx
    push dx
    call sh_selrect                    ; stage 3.0a: -> sh_selc1..sh_selr2,
                                        ; already ordered

    ; --- clip the block's own cell rect to the visible viewport. Each edge is
    ; clamped rather than the whole block rejected, so a selection that runs
    ; off the screen still draws the part that shows (Excel's own behaviour,
    ; and what a drag past the edge needs). 81.70: sh_vclip_col/row do both
    ; edges at once, frozen-aware, the same clamp sh_updsel needs too
    mov ax, [sh_selc1]
    mov bx, [sh_selc2]
    call sh_vclip_col
    jnc .out
    mov [sh_wcol], ax
    mov [sh_selvc2], bx

    mov ax, [sh_selr1]
    mov bx, [sh_selr2]
    call sh_vclip_row
    jnc .out
    mov [sh_wrow], ax
    mov [sh_selvr2], bx

    ; --- cell coords -> pixels
    mov ax, [sh_wcol]
    call sh_vcx                        ; each column its own width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    mov [sh_selx1], ax

    mov ax, [sh_selvc2]
    inc ax                             ; one past the last column...
    call sh_vcx                        ; each column its own width (81.56)
    add ax, [sh_ox]
    add ax, SH_RH_W
    dec ax                             ; ...minus a pixel = its right edge
    mov [sh_selx2], ax

    mov ax, [sh_wrow]
    call sh_vry                        ; each row its own height (81.60)
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    mov [sh_sely1], ax

    mov ax, [sh_selvr2]
    inc ax
    call sh_vry
    add ax, [sh_goy]
    add ax, SH_FB_H + SH_CH_H
    dec ax
    mov [sh_sely2], ax

    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_selx1]
    mov bx, [sh_sely1]
    mov cx, [sh_selx2]
    mov dx, [sh_sely2]
    call OSAPI_GFX_FRAME
    call sh_selsingle                  ; a single cell keeps the plain 1px
    jc .out                            ; frame it has always had; a real
                                        ; RANGE gets a second, inset frame so
                                        ; it reads as a block rather than as
                                        ; one very large cell (this OS has no
                                        ; wide-pen primitive, and XOR fill
                                        ; over the text would be worse - see
                                        ; os88ui_btn's own note on XOR)
    mov ax, [sh_selx1]
    inc ax
    mov bx, [sh_sely1]
    inc bx
    mov cx, [sh_selx2]
    dec cx
    mov dx, [sh_sely2]
    dec dx
    cmp ax, cx                         ; degenerate after the inset?
    jae .out
    cmp bx, dx
    jae .out
    call OSAPI_GFX_FRAME
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; Sheet's own in-window menu bar (see the SH_MBAR_H section comment for why
; this exists instead of OS88_MENUSET): File > New / Open... / Save / Save
; As..., Edit > Cut/Copy/Paste/..., Format > dialogs, Data > Sort Column,
; Sheets > switch, Options > Display toggles, Macro > Run, Help > About.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_mtab_calc - measure each menu title's pixel width once (sh_mw), so
; sh_mboxof never has to call OSAPI_FONT_WIDTH itself on every click/paint.
; Called once from sh_entry - the titles are fixed strings, so this never
; needs to run again.
; -----------------------------------------------------------------------------
sh_mtab_calc:
    push ax
    push bx
    push cx
    push si
    push di
    cmp word [sh_mtabp], 0            ; 81.95: the first call sets up the
    jne .set                          ; built-in bar
    mov word [sh_mtabp], sh_mtab
    mov word [sh_mcount], SH_MENU_N
.set:
    xor cx, cx
.loop:
    cmp cx, [sh_mcount]
    jae .done
    mov ax, cx
    mov bx, 6
    mul bx
    mov bx, ax
    add bx, [sh_mtabp]
    mov si, [bx]
    call OSAPI_FONT_WIDTH
    mov di, cx
    shl di, 1
    mov [sh_mw + di], ax
    inc cx
    jmp .loop
.done:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mboxof - AL = menu index -> sh_mbx1/sh_mbx2 (screen-absolute box
; bounds, using the raw [sh_ox]/[sh_oy], not the grid-shifted [sh_goy]).
; preserves everything
; -----------------------------------------------------------------------------
sh_mboxof:
    push ax
    push bx
    push cx
    push dx
    push di
    mov cl, al
    xor ch, ch
    mov dx, [sh_ox]
    xor bx, bx
.loop:
    cmp bx, cx
    jae .found
    mov di, bx
    shl di, 1
    mov ax, [sh_mw + di]
    add ax, SH_MPAD*2
    add dx, ax
    inc bx
    jmp .loop
.found:
    mov [sh_mbx1], dx
    mov di, bx
    shl di, 1
    mov ax, [sh_mw + di]
    add ax, SH_MPAD*2
    add dx, ax
    dec dx
    mov [sh_mbx2], dx
    pop di
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mbar_draw - the whole menu bar strip: white ground, black rule under
; it, every title (inverted if it is [sh_mopen]). Monochrome-safe black/
; white/invert, matching every other Sheet dialog in this app, rather than
; real Excel 2.1's cyan bar
; (LIBRARY/documentation/screenshots/excel/excel_main.png) - this OS
; supports 1bpp Hercules/CGA-mono adapters Sheet's own chrome has stayed
; safe for since stage 1.8, and introducing a new color here would be the
; first thing in this app to depend on one existing at all.
; -----------------------------------------------------------------------------
sh_mbar_draw:
    push ax
    push bx
    push cx
    push dx
    push si
    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov ax, [sh_ox]
    mov bx, [sh_oy]
    mov cx, [sh_ox]
    add cx, [sh_cw]
    dec cx
    mov dx, [sh_oy]
    add dx, SH_MBAR_H - 1
    call OSAPI_GFX_FILL
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_ox]
    mov bx, [sh_ox]
    add bx, [sh_cw]
    dec bx
    mov dx, [sh_oy]
    add dx, SH_MBAR_H - 1
    call OSAPI_GFX_HLINE
    mov word [sh_mli], 0
    mov word [sh_mto], 0
.loop:
    mov ax, [sh_mli]
    cmp ax, [sh_mcount]
    jae .done
    mov al, [sh_mli]
    call sh_mboxof
    mov al, [sh_mli]
    cmp al, [sh_mopen]
    jne .normal
    mov ax, [sh_mbx1]
    mov bx, [sh_oy]
    mov cx, [sh_mbx2]
    mov dx, [sh_oy]
    add dx, SH_MBAR_H - 1
    call OSAPI_GFX_FILL
    mov al, CWHITE
    call OSAPI_SET_COLOR
    jmp .drawtitle
.normal:
    mov al, CBLACK
    call OSAPI_SET_COLOR
.drawtitle:
    mov bx, [sh_mto]
    add bx, [sh_mtabp]
    mov si, [bx]
    mov cx, [sh_mbx1]
    add cx, SH_MPAD
    mov dx, [sh_oy]
    add dx, 3
    call OSAPI_FONT_STR_XPARENT
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_mto]
    add ax, 6
    mov [sh_mto], ax
    mov ax, [sh_mli]
    inc ax
    mov [sh_mli], ax
    jmp .loop
.done:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mcrun - a custom menu's command (81.95): AH = the menu's place on the
; bar, AL = the command. Its table entry points at its record's items, so
; the record, and the cell the command runs, are a subtraction away. A run
; already going (paused) is not interrupted - the gate has the click anyway
; -----------------------------------------------------------------------------
sh_mcrun:
    push ax
    push bx
    push cx
    mov bl, ah
    xor bh, bh
    mov cx, bx
    shl bx, 1
    add bx, cx
    shl bx, 1                         ; x6: the entry
    add bx, [sh_mtabp]
    mov bx, [bx + 2]                  ; the items: the record + SH_MC_ITEMS
    or bx, bx                         ; ...and 0 is a menu deleted since the
    jz .out                           ; dropdown opened (81.95.3), not a
    sub bx, SH_MC_ITEMS               ; record near the top of the segment
    xor ah, ah
    shl ax, 1
    shl ax, 1
    add bx, ax
    mov ax, [bx + SH_MC_CELLS]        ; the command's cell
    cmp ax, 0xFFFF                    ; a command with no macro
    je .out
    mov [sh_macro_col], ax
    mov ax, [bx + SH_MC_CELLS + 2]
    mov [sh_macro_row], ax
    mov byte [sh_macro_wait], SH_MW_START
    call sh_macro_onalert
.out:
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mbar_hit - CX,DX (screen-absolute) -> AL = menu index or SH_M_NONE
; -----------------------------------------------------------------------------
sh_mbar_hit:
    push bx
    push cx
    push dx
    mov ax, [sh_oy]
    cmp dx, ax
    jb .no
    add ax, SH_MBAR_H - 1
    cmp dx, ax
    ja .no
    mov word [sh_mli], 0
.loop:
    mov ax, [sh_mli]
    cmp ax, [sh_mcount]
    jae .no
    mov al, [sh_mli]
    call sh_mboxof
    cmp cx, [sh_mbx1]
    jb .next
    cmp cx, [sh_mbx2]
    ja .next
    mov ax, [sh_mli]
    jmp .out
.next:
    mov ax, [sh_mli]
    inc ax
    mov [sh_mli], ax
    jmp .loop
.no:
    mov ax, SH_M_NONE
.out:
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_mdrop_geo - compute the open menu's ([sh_mopen]) dropdown rect into
; sh_mrx1/mry1/mrx2/mry2, and stash its items ptr/count into sh_mip/
; sh_mcnt for sh_mdrop_draw and sh_mitem_hit to share. Width is the widest
; item label (skipping a leading MENU_DIS byte when measuring); height is
; item_count*SH_MI_H plus a little top/bottom padding. No sliding-under-
; the-screen-edge case (unlike word.asm's wd_mgeo) - Sheet's own dropdowns
; are short enough that this has never yet needed one.
; -----------------------------------------------------------------------------
sh_mdrop_geo:
    push ax
    push bx
    push cx
    push si
    mov al, [sh_mopen]
    call sh_mboxof
    mov ax, [sh_mbx1]
    mov [sh_mrx1], ax
    mov ax, [sh_oy]
    add ax, SH_MBAR_H
    mov [sh_mry1], ax

    mov bl, [sh_mopen]
    xor bh, bh
    mov ax, bx
    mov cx, 6
    mul cx
    mov bx, ax
    add bx, [sh_mtabp]
    mov si, [bx + 2]
    mov [sh_mip], si
    mov ax, [bx + 4]
    mov [sh_mcnt], ax

    mov word [sh_mmaxw], 0
    mov word [sh_mli], 0
.wloop:
    mov ax, [sh_mli]
    cmp ax, [sh_mcnt]
    jae .wdone
    mov bx, [sh_mli]
    shl bx, 1
    mov si, [sh_mip]
    add si, bx
    mov si, [si]
    mov al, [si]
    cmp al, MENU_DIS                  ; either PREFIX byte, as sh_mdrop_draw
    je .prefix                        ; skips both - measuring the check byte
    cmp al, SH_MENU_CHK               ; as a glyph made a ticked item's
    jne .measure                      ; dropdown one cell too wide
.prefix:
    inc si
.measure:
    call OSAPI_FONT_WIDTH
    call sh_kcap                      ; 81.101: a shortcut's caption widens
    jc .nocap                         ; the row by a gap and itself
    push ax
    call OSAPI_FONT_WIDTH
    mov si, ax
    pop ax
    add ax, si
    add ax, SH_MKGAP
.nocap:
    cmp ax, [sh_mmaxw]
    jbe .wnext
    mov [sh_mmaxw], ax
.wnext:
    mov ax, [sh_mli]
    inc ax
    mov [sh_mli], ax
    jmp .wloop
.wdone:
    mov ax, [sh_mmaxw]
    add ax, SH_MPAD*2 + SH_MCHKW
    mov bx, [sh_mrx1]
    add bx, ax
    dec bx
    mov [sh_mrx2], bx
    mov ax, [sh_ox]                   ; 81.95: INSIDE THE WINDOW. A custom
    add ax, [sh_cw]                   ; menu after Help opens at the bar's
    dec ax                            ; right edge, and a panel past it was
    cmp bx, ax                        ; drawn outside the window and never
    jbe .fits                         ; erased - so it moves left instead
    sub bx, ax
    sub [sh_mrx1], bx
    sub [sh_mrx2], bx
.fits:

    mov ax, [sh_mcnt]
    mov cx, SH_MI_H
    mul cx
    add ax, 4
    add ax, [sh_mry1]
    dec ax
    mov [sh_mry2], ax
                                      ; 81.98: NOT slid up when it runs off
                                      ; the screen, though the kernel's popup
                                      ; slides: a bar menu slid up covers its
                                      ; own title and lands UNDER THE POINTER,
                                      ; and a plain click on the title then
                                      ; releases on an item and fires it. The
                                      ; shared element (os88ui_mngeo) refuses
                                      ; the same slide for the same reason
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mdrop_draw - paint the open dropdown from sh_mrx1/y1/x2/y2 + sh_mip/
; sh_mcnt (sh_mdrop_geo must already have run). White panel, black frame,
; one row per item at SH_MI_H apart: disabled items (MENU_DIS) drawn under
; OSAPI_GFX_PEN's disabled (grey) pen; the hot item ([sh_mhi]) drawn
; inverted. Redraws the WHOLE panel on every highlight change rather than
; word.asm's per-row XOR - Sheet's dropdowns are short lists, so this is
; cheap enough not to need that finer granularity.
; -----------------------------------------------------------------------------
sh_mdrop_draw:
    push ax
    push bx
    push cx
    push dx
    push si
    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov ax, [sh_mrx1]
    mov bx, [sh_mry1]
    mov cx, [sh_mrx2]
    mov dx, [sh_mry2]
    call OSAPI_GFX_FILL
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_mrx1]
    mov bx, [sh_mry1]
    mov cx, [sh_mrx2]
    mov dx, [sh_mry2]
    call OSAPI_GFX_FRAME
    mov word [sh_mli], 0
.loop:
    mov ax, [sh_mli]
    cmp ax, [sh_mcnt]
    jae .done
    mov cx, SH_MI_H
    mul cx
    add ax, [sh_mry1]
    add ax, 2
    mov [sh_mry_row], ax
    mov bx, [sh_mip]
    mov cx, [sh_mli]
    shl cx, 1
    add bx, cx
    mov si, [bx]
    mov byte [sh_mchk], 0
    mov al, [si]
    cmp al, SH_MENU_CHK               ; stage 3.0c: the same relabel-by-
    jne .notchk                       ; repointing trick MENU_DIS documents,
    inc si                            ; for a mark rather than for grey
    mov byte [sh_mchk], 1
    mov al, [si]
.notchk:
    cmp al, MENU_DIS
    jne .live
    inc si
    stc
    call OSAPI_GFX_PEN
    jmp .drawtext
.live:
    mov ax, [sh_mli]
    cmp al, [sh_mhi]
    jne .plain
    mov ax, [sh_mrx1]
    inc ax
    mov bx, [sh_mry_row]
    mov cx, [sh_mrx2]
    dec cx
    mov dx, [sh_mry_row]
    add dx, SH_MI_H - 1
    push ax
    mov al, CBLACK
    call OSAPI_SET_COLOR
    pop ax
    call OSAPI_GFX_FILL
    clc
    call OSAPI_GFX_PEN
    mov al, CWHITE
    call OSAPI_SET_COLOR
    jmp .drawtext
.plain:
    clc
    call OSAPI_GFX_PEN
.drawtext:
    cmp byte [sh_mchk], 0
    je .nochk
    push ax                           ; the check: A SOLID SQUARE and not a
    push bx                           ; tick (SPEC.md 81.64), because a thin
    push cx                           ; diagonal reads as scattered pixels on
    push dx                           ; the two 1bpp adapters (SPEC.md 39.4) -
    mov ax, [sh_mrx1]                 ; os88ui_chk's own mark and its own
    add ax, SH_MCHKX                  ; reason. The pen is already the right
    mov bx, [sh_mry_row]              ; colour, set by the highlight branch
    add bx, SH_MCHKY                  ; above, so the mark inverts with the row
    mov cx, ax                        ; exactly as the text does
    add cx, SH_MCHKS - 1
    mov dx, bx
    add dx, SH_MCHKS - 1
    call OSAPI_GFX_FILL
    pop dx
    pop cx
    pop bx
    pop ax
.nochk:
    mov cx, [sh_mrx1]
    add cx, SH_MPAD + SH_MCHKW
    mov dx, [sh_mry_row]
    call OSAPI_FONT_STR_XPARENT
    call sh_kcap                      ; 81.101: the shortcut, RIGHT-aligned.
    jc .nextrow                       ; OPAQUE (SPEC.md 6.6): the panel ground
    call OSAPI_FONT_WIDTH             ; was filled this same pass, which is
    mov cx, [sh_mrx2]                 ; the pair 6.6.2 does not allow, so the
    inc cx                            ; run redraws its own cells' ground in
    sub cx, SH_MPAD                   ; the row's colours. font_run honours
    sub cx, ax                        ; the greyed pen itself (6.6.2's retired
    mov dx, [sh_mry_row]              ; sixth), so a greyed item's key is
    mov ax, (CWHITE << 8) | CBLACK    ; grey, and the hot row - never a greyed
    mov bl, [sh_mli]                  ; one (sh_mitem_hit) - inverts
    cmp bl, [sh_mhi]
    jne .capgo
    mov ax, (CBLACK << 8) | CWHITE
.capgo:
    call OSAPI_FONT_RUN
.nextrow:
    mov ax, [sh_mli]
    inc ax
    mov [sh_mli], ax
    jmp .loop
.done:
    clc
    call OSAPI_GFX_PEN                 ; leave the pen live (its own "put it
                                        ; back" rule) for whatever draws next
    call sh_msepdraw                   ; 81.109: the group lines, last
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_msepdraw - the open pulldown's SEPARATORS (81.109): a 1px line in the gap
; after each row sh_msep marks, as Excel groups its menus. A HAIRLINE IN THE
; EXISTING PITCH and not Word's 5px band (the owner's choice): no row moves,
; so a row's y, the hit test, the save-under rect and every test that clicks
; by the 12px pitch are all exactly what they were. Row i's glyph is at
; row_top + 0..7; the line sits at row_top + 10, two clear rows below it and
; one above the next row's. Drawn AFTER the rows, so a highlight redraw never
; loses one (over the lit row it is black on black). A custom bar's menus and
; any past Help (81.95) have none. Preserves every register
; -----------------------------------------------------------------------------
sh_msepdraw:
    push ax
    push bx
    push cx
    push dx
    push si
    cmp word [sh_mtabp], sh_mtab
    jne .out
    mov bl, [sh_mopen]
    cmp bl, SH_MENU_N
    jae .out
    xor bh, bh
    shl bx, 1
    mov si, [sh_msep + bx]              ; bit i: a line after row i
    or si, si
    jz .out
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov dx, [sh_mry1]
    add dx, 2 + 10                      ; row 0's line
    mov cx, [sh_mcnt]
    dec cx                              ; never after the last row
    jle .out
.row:
    shr si, 1
    jnc .next
    push cx
    mov ax, [sh_mrx1]
    inc ax
    mov bx, [sh_mrx2]
    dec bx
    call OSAPI_GFX_HLINE                ; AX..BX at DX
    pop cx
.next:
    add dx, SH_MI_H
    loop .row
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; the lines, per built-in menu in sh_mtab's order: bit i = after row i.
; Excel 2.1d's own groups, read off its captures (menu_*.png); SHEET's rows
; that Excel lacks sit in the group they belong to, and Data's chart items -
; SHEET's own - get a group of their own after Parse
%define SH_SEP(r) (1 << (r))
sh_msep:
    dw SH_SEP(1)                                           ; File: New, Open |
    dw SH_SEP(SH_EI_UNDO) | SH_SEP(SH_EI_PASTELK) | SH_SEP(SH_EI_INSERT) ; Edit
    dw SH_SEP(SH_FI_REF) | SH_SEP(3) | SH_SEP(4)           ; Formula: | Define
                                                           ; Name | Note |
    dw SH_SEP(4) | SH_SEP(6)                               ; Format: | Row H,
                                                           ; Col W | Justify
    dw SH_SEP(0) | SH_SEP(5) | SH_SEP(6) | SH_SEP(9)       ; Data: Table...
                                                           ; went in at 8, so
                                                           ; the rule that
                                                           ; separated Excel's
                                                           ; list from this
                                                           ; app's charts
                                                           ; moved with Parse
    dw SH_SEP(SH_OI_FREEZE) | SH_SEP(SH_OI_PROT)           ; Options
    dw SH_SEP(SH_MAI_RUN)                                  ; Macro: | recorder
    dw 0, 0                                                ; Sheets, Help
sh_msep_end:
    times ((sh_msep_end - sh_msep) / 2 - SH_MENU_N) db 0   ; one word a menu,
    times (SH_MENU_N - (sh_msep_end - sh_msep) / 2) db 0   ; in sh_mtab's order

; -----------------------------------------------------------------------------
; sh_mitem_hit - CX,DX (screen-absolute) -> AL = item index, or SH_M_NONE
; if outside the panel, on a separator gap, or on a disabled (MENU_DIS)
; item - a disabled row cannot become the hot item at all, which is what
; lets sh_mdrop_draw assume a highlighted row is always live.
; -----------------------------------------------------------------------------
sh_mitem_hit:
    push bx
    push si
    cmp cx, [sh_mrx1]
    jb .no
    cmp cx, [sh_mrx2]
    ja .no
    cmp dx, [sh_mry1]
    jb .no
    cmp dx, [sh_mry2]
    ja .no
    mov ax, dx
    sub ax, [sh_mry1]
    sub ax, 2
    js .no
    push dx
    xor dx, dx
    mov bx, SH_MI_H
    div bx
    pop dx
    cmp ax, [sh_mcnt]
    jae .no
    mov bx, [sh_mip]
    push cx
    mov cx, ax
    shl cx, 1
    add bx, cx
    pop cx
    mov si, [bx]
    cmp byte [si], MENU_DIS
    je .no
    jmp .out
.no:
    mov ax, SH_M_NONE
.out:
    pop si
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_mclose - close the open dropdown and repaint what it covered. Always a
; full sh_repaint (menu bar included, since sh_drawall draws it first) -
; Sheet's own grid redraw is cheap, unlike word.asm's wd_mrepair, which
; repaints piecewise specifically to avoid a full-document reflow.
; -----------------------------------------------------------------------------
sh_mclose:
    push ax
    push si
    mov byte [sh_mopen], SH_M_NONE
    mov byte [sh_mhi], SH_M_NONE
    mov si, [sh_ownwin]
    cmp byte [sh_mbanked], 0            ; 81.98: the pixels the panel covered,
    je .repaint                       ; WHEREVER they were - the part past the
    mov byte [sh_mbanked], 0            ; window's bottom edge included, which
    push bx                           ; the repaint below cannot reach: it
    push cx                           ; draws this window, and the tail was on
    push dx                           ; the desktop or another window
    push es
    push si
    mov es, [sh_stgseg]
    xor si, si
    mov ax, [sh_mrx1]
    mov bx, [sh_mry1]
    mov cx, [sh_mrx2]
    mov dx, [sh_mbky2]
    call OSAPI_GFX_REST
    pop si
    pop es
    pop dx
    pop cx
    pop bx
    jc .repaint
    call sh_mbar_draw                 ; ...and the title back to plain
    call sh_drawstatus                ; ...and the STATUS BAR, which the old
    jmp short .out                    ; full repaint refreshed as a side
                                       ; effect: the click that opened this
                                       ; menu cleared [sh_msg] (sh_onclick),
                                       ; and the bank put back the old message.
                                       ; The VGA gate caught it by comparing
                                       ; this path with the repaint's
.repaint:
    call sh_repaint                   ; refused: what it always did
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mbank - 81.98: save what the dropdown is about to cover, in the staging
; claim - which holds nothing a command reads back without rebuilding it
; (Copy and Paste stage through it and the clipboard is the OS's; the
; chart's staged series are there too, so Chart Gallery rescans rather than
; re-rendering them), and no command runs while a menu is up.
; [sh_mbanked] = 1 with the rect's bottom, clamped to the display, in
; [sh_mbky2]; or 0 when anything refused, and sh_mclose repaints as before.
; The size is SPEC.md 13.16.4's: planes * rows * byte columns, the plane
; count from OSAPI_WM_DISPLAY (never OSAPI_VIDEO: 39.16.4)
; -----------------------------------------------------------------------------
sh_mbank:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov byte [sh_mbanked], 0
    mov bx, [sh_ownwin]
    call OSAPI_WM_DISPLAY             ; BX = height, DH = bits per pixel
    dec bx
    mov ax, [sh_mry2]
    cmp ax, bx
    jbe .y2
    mov ax, bx
.y2:
    mov [sh_mbky2], ax
    mov di, ax                        ; DI = the last row, kept across mul
    mov ax, [sh_mrx2]
    mov cl, 3
    shr ax, cl
    mov bx, [sh_mrx1]
    shr bx, cl
    sub ax, bx
    inc ax                            ; AX = byte columns
    mov bx, di
    sub bx, [sh_mry1]
    inc bx                            ; BX = rows
    push dx
    mul bx                            ; DX:AX = one plane
    pop bx                            ; BH = bits per pixel
    cmp bh, 4
    jb .one                           ; 4 planes - or 8 or 16 BYTES a column
    or dx, dx                         ; on a packed display (SPEC.md 120.5):
    jnz .out                          ; DH AS IT COMES, never == 4
    mov cl, bh
    xor ch, ch
    mul cx                            ; DX:AX = planes * one plane
.one:
    or dx, dx
    jnz .out
    cmp ax, SH_STAGE_MAX
    ja .out
    mov es, [sh_stgseg]
    xor di, di
    mov ax, [sh_mrx1]
    mov bx, [sh_mry1]
    mov cx, [sh_mrx2]
    mov dx, [sh_mbky2]
    call OSAPI_GFX_SAVE               ; CF=1: the rect straddles two displays
    jc .out
    mov byte [sh_mbanked], 1
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_mtrack - the press-drag-release gesture: a tick-paced OSAPI_MOUSE poll,
; never W_ONDRAG - see the SH_MBAR_H section comment for why. in: AL = menu
; index to open, SI = window ptr (this callback's own, untouched SI - see
; sh_onclick); called with the gfx lock already held, and it KEEPS it held
; until the panel is gone (81.98). It was word.asm's wd_mtrack pattern, an
; unlock/yield/relock between reads, and that is right for a panel inside
; its own window, where no other task can draw; SHEET's hangs past the
; window's bottom, so it takes the kernel menu's discipline instead.
; -----------------------------------------------------------------------------
sh_mtrack:
    push ax
    push bx
    push si
    call sh_refmark                    ; 81.108: live only mid-formula
    mov [sh_mopen], al
    mov byte [sh_mhi], SH_M_NONE
    call sh_mdrop_geo
    call sh_mbank                      ; 81.98: before anything is drawn
    call sh_mbar_draw
    call sh_mdrop_draw
.loop:
    call OSAPI_GET_TICKS               ; 81.98: THE LOCK STAYS HELD while the
    mov bx, ax                         ; panel is up - the kernel menu's own
.spin:                                 ; discipline (menu_drop: "nothing else
    call OSAPI_TASK_YIELD              ; draws while we hold the lock"). The
    call OSAPI_GET_TICKS               ; panel hangs past the window onto other
    cmp ax, bx                         ; windows and the desktop, and a task
    je .spin                           ; repainting under it would be put back
    call OSAPI_MOUSE                   ; STALE by the restore; cx=x, dx=y,
                                       ; al=buttons
    test al, 1
    jz .release
    call sh_mitem_hit
    cmp al, [sh_mhi]
    je .loop
    mov [sh_mhi], al
    call sh_mdrop_draw
    jmp .loop
.release:
    call sh_mitem_hit
    cmp al, SH_M_NONE
    je .closeonly
    mov ah, [sh_mopen]
    push ax
    call sh_mclose
    pop ax
    call sh_mfire
    jmp .out
.closeonly:
    call sh_mclose
.out:
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; 81.101: KEYBOARD SHORTCUTS, the modern set (the owner's choice over Excel
; 2.1d's Shift+Del / Ctrl+Ins / Shift+Ins). ONE TABLE drives both halves: the
; key that fires an item and the caption the pulldown draws beside it, so the
; two cannot disagree. A shortcut FIRES THE MENU ITEM through sh_mfire, the
; door a click and a macro's command equivalent already share - so the undo
; snapshot, the recorder and every refusal are the item's own, not a copy.
;
; An entry: the ASCII byte, the scan (0 = any: a Ctrl+letter is its control
; character whatever the scan), the menu, the row, the caption. The first
; entry naming an item is the one its caption shows (Goto has two keys).
; Ctrl+H/I/M are Backspace/Tab/Enter and cannot be shortcuts.
; -----------------------------------------------------------------------------
%macro SH_KA 5
    db %1, %2, %3, %4
    dw %5
%endmacro
SH_KA_SZ     equ 6
sh_katab:
    SH_KA 0x0E, 0,    SH_MI_FILE,    0,              sh_kc_n     ; New
    SH_KA 0x0F, 0,    SH_MI_FILE,    1,              sh_kc_o     ; Open
    SH_KA 0x13, 0,    SH_MI_FILE,    2,              sh_kc_s     ; Save
    SH_KA 0x1A, 0,    SH_MI_EDIT,    SH_EI_UNDO,     sh_kc_z
    SH_KA 0x18, 0,    SH_MI_EDIT,    SH_EI_CUT,      sh_kc_x
    SH_KA 0x03, 0,    SH_MI_EDIT,    SH_EI_COPY,     sh_kc_c
    SH_KA 0x16, 0,    SH_MI_EDIT,    SH_EI_PASTE,    sh_kc_v
    SH_KA 0x12, 0,    SH_MI_EDIT,    SH_EI_FILLR,    sh_kc_r
    SH_KA 0x04, 0,    SH_MI_EDIT,    SH_EI_FILLD,    sh_kc_d
    SH_KA 0,    0x3D, SH_MI_FORMULA, 0,              sh_kc_f3    ; Paste Name
    SH_KA 0,    0x3E, SH_MI_FORMULA, SH_FI_REF,      sh_kc_f4    ; Reference
    SH_KA 0,    0x56, SH_MI_FORMULA, 1,              sh_kc_sf3   ; Paste Fn
    SH_KA 0x07, 0,    SH_MI_FORMULA, 5,              sh_kc_g     ; Goto
    SH_KA 0,    0x3F, SH_MI_FORMULA, 5,              sh_kc_g     ; F5 too
    SH_KA 0x06, 0,    SH_MI_FORMULA, 6,              sh_kc_f     ; Find
    SH_KA 0,    0x43, SH_MI_OPTIONS, SH_OI_CALCNOW,  sh_kc_f9    ; Calc Now
sh_katab_end:
SH_KA_N      equ (sh_katab_end - sh_katab) / SH_KA_SZ
sh_kc_n:   db 'Ctrl+N', 0
sh_kc_o:   db 'Ctrl+O', 0
sh_kc_s:   db 'Ctrl+S', 0
sh_kc_z:   db 'Ctrl+Z', 0
sh_kc_x:   db 'Ctrl+X', 0
sh_kc_c:   db 'Ctrl+C', 0
sh_kc_v:   db 'Ctrl+V', 0
sh_kc_r:   db 'Ctrl+R', 0
sh_kc_d:   db 'Ctrl+D', 0
sh_kc_f3:  db 'F3', 0
sh_kc_f4:  db 'F4', 0
sh_kc_sf3: db 'Shift+F3', 0
sh_kc_g:   db 'Ctrl+G', 0
sh_kc_f:   db 'Ctrl+F', 0
sh_kc_f9:  db 'F9', 0

; sh_kaccel - W_ONKEY's AL/AH: a shortcut? CF=1 it was, and it is spent -
; fired, or swallowed because its item cannot run now. CF=0 not one.
; Swallowed, not passed on: while a cell is being EDITED (modern Excel greys
; the menus during entry, and the field has no clipboard for Ctrl+C to mean
; anything else), when the item is greyed, and when a macro's custom bar is
; up (81.95: the built-in commands are not on the screen to be named)
sh_kaccel:
    push bx
    push cx
    push si
    mov si, sh_katab
    mov cx, SH_KA_N
.find:
    mov bl, [si]
    or bl, bl
    jz .scan
    cmp bl, al                         ; a Ctrl+letter: its control byte
    je .hit
    jmp short .next
.scan:
    or al, al                          ; a function key: no ASCII, its scan
    jnz .next
    cmp [si + 1], ah
    je .hit
.next:
    add si, SH_KA_SZ
    loop .find
    clc
    jmp short .out
.hit:
    call sh_refmark                    ; 81.108: Reference's live state first
    cmp word [si + 2], (SH_FI_REF << 8) | SH_MI_FORMULA
    je .entry                          ; ...the ONE item that works DURING an
    cmp byte [sh_editing], 0           ; entry and nowhere else (F4, Excel's)
    jne .spent
.entry:
    cmp word [sh_mtabp], sh_mtab
    jne .spent
    push ax
    mov ah, [si + 2]
    mov al, [si + 3]
    call sh_mitemp                     ; SI = the item's string
    cmp byte [si], MENU_DIS            ; greyed in the menu: not runnable
    je .grey
    push ax
    call sh_drawstatus                 ; the order a click has: the status
    pop ax                             ; line first (sh_mclose's), then
    call sh_mfire                      ; the command
.grey:
    pop ax
.spent:
    stc
.out:
    pop si
    pop cx
    pop bx
    ret

; sh_mitemp - AH = menu, AL = row of the BUILT-IN bar -> SI = the item's
; string, as the table holds it now (relabels included)
sh_mitemp:
    push ax
    push bx
    mov bl, ah
    xor bh, bh
    mov si, bx
    shl bx, 1                          ; x 6: a sh_mtab row
    add bx, si
    shl bx, 1
    mov si, [sh_mtab + 2 + bx]
    xor ah, ah
    shl ax, 1
    add si, ax
    mov si, [si]
    pop bx
    pop ax
    ret

; sh_kcap - the caption for row [sh_mli] of the open pulldown: SI = it and
; CF=0, or CF=1 none. None on a custom bar: a macro's menus name no keys
sh_kcap:
    push ax
    push cx
    cmp word [sh_mtabp], sh_mtab
    jne .none
    cmp byte [sh_mopen], SH_MENU_N
    jae .none
    mov ah, [sh_mopen]
    mov al, [sh_mli]
    mov si, sh_katab
    mov cx, SH_KA_N
.find:
    cmp [si + 2], ah
    jne .next
    cmp [si + 3], al
    jne .next
    mov si, [si + 4]
    clc
    jmp short .out
.next:
    add si, SH_KA_SZ
    loop .find
.none:
    stc
.out:
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_refmark - Formula > Reference is live only while a FORMULA is being
; entered in A1 style (81.108), which is the only time Excel's cycles
; anything. Asked when a pulldown opens and on F4, rather than kept current
; on every keystroke. Preserves all registers and flags
; -----------------------------------------------------------------------------
sh_refmark:
    pushf
    push ax
    mov ax, sh_it_refdis
    cmp byte [sh_editing], 0
    je .set
    cmp byte [sh_editbuf], '='
    jne .set
    cmp byte [sh_a1style], 0
    jne .set
    mov ax, sh_it_ref
.set:
    mov [sh_i_formula + SH_FI_REF * 2], ax
    pop ax
    popf
    ret
sh_refcyc_r:                          ; its door into CHART.OVL
    push bp
    mov bp, SHM_REFCYC
    call ch_ovcall
    pop bp
    ret

; -----------------------------------------------------------------------------
; sh_mfire - AH = menu index, AL = item index -> dispatch. Sets SI to
; [sh_ownwin] unconditionally before calling anything: this runs from
; sh_mtrack's own polling loop, not a kernel AM_ONCMD callback, so nothing
; here can assume SI already IS the window the way sh_oncmd's old kernel-
; supplied SI always was.
; -----------------------------------------------------------------------------
sh_mfire:
    push ax
    push si
    mov si, [sh_ownwin]
    cmp word [sh_mtabp], sh_mtab      ; 81.95: the custom bar, or a custom
    jne .custom                       ; menu after Help, runs a macro
    cmp ah, SH_MENU_N
    jb .builtin
.custom:
    call sh_mcrun
    pop si
    pop ax
    ret
.builtin:
    ; WHAT UNDO CANNOT REVERSE ENDS IT (81.57): a snapshot older than a
    ; format, a name, a note or a macro would put them back too, silently.
    ; Excel 2.1 cannot undo any of these either
    cmp ah, SH_MI_FORMAT               ; Format, all of it
    je .udrop
    cmp ah, SH_MI_MACRO                ; Macro
    je .udrop
    cmp ah, SH_MI_FORMULA              ; Formula: Define Name and Note
    jne .ukept
    cmp al, 3
    je .udrop
    cmp al, 4
    jne .ukept
.udrop:
    call sh_undo_drop
.ukept:
    cmp ah, SH_MI_FILE
    je .file
    cmp ah, SH_MI_EDIT
    je .edit
    cmp ah, SH_MI_FORMULA
    je .formula
    cmp ah, SH_MI_FORMAT
    je .format
    cmp ah, SH_MI_DATA
    je .data
    cmp ah, SH_MI_OPTIONS
    je .options
    cmp ah, SH_MI_MACRO
    je .macro
    cmp ah, SH_MI_SHEET
    je .sheets
    cmp ah, SH_MI_HELP
    je .help
    jmp .out
.formula:
    or al, al
    jnz .fm1
    mov al, SH_LD_NAME
    call sh_ldlg_open_r
    jmp .out
.fm1:
    cmp al, 1
    jne .fm2
    mov al, SH_LD_FUNC
    call sh_ldlg_open_r
    jmp .out
.fm2:
    cmp al, 2                         ; Reference (81.108): the reference at
    jne .fm3                          ; the caret, one step round Excel's
    call sh_refcyc_r                  ; cycle. Refused inside, as the item is
    jmp .out                          ; greyed, unless a formula is being
.fm3:                                 ; entered
    cmp al, 3
    jne .fm4
    mov al, SH_ID_DEFN
    call sh_idlg_open_r
    jmp .out
.fm4:
    cmp al, 4
    jne .fm5
    call sh_ndlg_open_r
    jmp .out
.fm5:
    cmp al, 5
    jne .fm6
    mov al, SH_ID_GOTO
    call sh_idlg_open_r
    jmp .out
.fm6:
    mov al, SH_ID_FIND
    call sh_idlg_open_r
    jmp .out
.file:
    cmp al, 1                          ; New and Open both throw the current
    ja .fsave                          ; workbook away, so both ask first when
    inc ax                             ; it has changes (81.118) - AL = 1 New,
    call sh_ask_unsaved                ; 2 Open, the action owed once the
    jmp .out                           ; question is answered
.fsave:
    cmp al, 2
    jne .fsaveas
    call sh_dowrite
    mov si, [sh_ownwin]
    call sh_repaint
    jmp .out
.fsaveas:
    cmp al, 3
    jne .fdelete
    mov al, SH_FDK_SAVEFMT             ; 3. ASK for the
    call sh_fdlg_open_r                  ; format, then name it - the format used
    jmp .out                           ; to be whatever extension the typed
                                       ; name happened to end in
.fdelete:                              ; 4: File > Delete (81.79). The kernel
    mov byte [sh_dlg_del], 1           ; dialog has only OPEN and SAVE, so the
    mov al, FDLG_OPEN                  ; PICKER is an Open and this flag is what
    call sh_dlg                        ; tells sh_ondlg what was meant by it
    jmp .out
.edit:
    call sh_docmd_edit
    jmp .out
.format:
    call sh_docmd_format
    jmp .out
.data:
    or al, al                          ; AL was ignored here before Chart
    jnz .data1                         ; Column.../Export were added - Data
                                        ; had exactly one item (Sort Column)
                                        ; so every click ran it regardless.
                                        ; Now a real dispatch, matching the
                                        ; or al,al chains above.
    call sh_docmd_form_r               ; 0: Form... (81.71.5)
    jmp .out
.data1:
    cmp al, 1
    jne .data2
    call sh_docmd_dfind                ; 1: Find / Exit Find (81.71). NOT
    jmp .out                           ; sh_docmd_find, which is Formula's own
.data2:
    cmp al, 2
    jne .data3
    mov al, SH_FDK_EXTRACT             ; 2: Extract... (81.71)
    call sh_fdlg_open_r
    jmp .out
.data3:
    cmp al, 3
    jne .data4
    call sh_docmd_dbdelete             ; 3: Delete (81.71)
    jmp .out
.data4:
    cmp al, 4
    jne .data5
    mov si, sh_s_dbname                ; 4: Set Database
    call sh_docmd_setname
    jmp .out
.data5:
    cmp al, 5
    jne .data6
    mov si, sh_s_critname              ; 5: Set Criteria
    call sh_docmd_setname
    jmp .out
.data6:
    cmp al, 6
    jne .data7
    mov al, SH_ID_SORT                 ; 6: stage 4.5's Sort - the KEY first,
    call sh_idlg_open_r                  ; then the order (sh_idlg_apply's own
    jmp .out                           ; .sortkey)
.data7:
    cmp al, 7
    jne .data8
    mov al, SH_FDK_SERIES              ; 7: Series... (81.72), the TYPE first
    call sh_fdlg_open_r                  ; and then the step
    jmp .out
.data8:
    cmp al, 8
    jne .data9
    mov al, SH_ID_TBLROW               ; 8: Table... (81.114), Excel's own
    call sh_idlg_open_r                ; place - and Parse and the three
    jmp .out                           ; chart items each moved down one,
.data9:                                ; exactly as 81.82 moved them before
    cmp al, 9
                                       ; THE SELECTION IS NOT BANKED: nothing
                                       ; moves it while a modal dialog owns
                                       ; the input, so the engine reads
                                       ; sh_selrow/sh_selcol two dialogs later
    jne .data10
    mov al, SH_ID_PARSE                ; 9: Parse... (81.82)
    call sh_idlg_open_r
    jmp .out
.data10:
    cmp al, 10
    jne .data11
    call sh_docmd_chart                ; 10..12: this app's own charting,
    jmp .out                           ; which real Excel has no Data item
.data11:                               ; for, so it trails Excel's list
    cmp al, 11                         ; rather than sitting inside it
    jne .data12
    mov al, SH_FDK_GAL
    call sh_fdlg_open_r
    jmp .out
.data12:
    call sh_docmd_chartexport
    jmp .out
.sheets:
    xor ah, ah                        ; al = item index = target sheet 0..3
    call sh_switchsheet
    jmp .out
.options:
    call sh_docmd_options
    jmp .out
.macro:
    cmp al, SH_MAI_RECORD
    jne .macro1
    call sh_docmd_record               ; Record... / Stop Recorder (81.74)
    jmp .out
.macro1:
    cmp al, SH_MAI_RUN
    jne .macro2
    call sh_macro_run                  ; Run...
    jmp .out
.macro2:
    cmp al, SH_MAI_START
    jne .macro3
    call sh_docmd_startrec             ; Start Recorder (81.107)
    jmp .out
.macro3:
    cmp al, SH_MAI_SETREC
    jne .macro4
    call sh_docmd_setrec               ; Set Recorder
    jmp .out
.macro4:
    xor byte [sh_rec_rel], 1           ; Relative / Absolute Record - the
    call sh_recmark                    ; item names what choosing it WOULD do
    jmp .out
.help:
    call sh_docmd_help
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_calc_now - Calculate Now: force every formula to be worked out again.
;
; NOT sh_recalc_all. The stamp is what does it: sh_drawgrid re-evaluates a
; formula cell whose cached [sh_pass] is not the current one, so bumping the
; stamp invalidates every cache at once and the next repaint does the work -
; which is the same machinery Calculation: Manual suspends, rather than a
; second way of arriving at the same answer.
;
; THE RESIDENT COPY of what sh_fdlg_apply's own .calcnow does for the
; Calculation dialog's third choice. Two copies, knowingly: that arm is in the
; MODULE, and a module reaches resident code only through the sh_v_* vector
; table, which is filled POSITIONALLY from a parallel `dw sh_x_*` list with
; nothing gating that the two agree - so a slot appended to one and not the
; other is a silent far call to the wrong routine. Four lines twice is the
; cheaper risk than that. CHANGE ONE AND CHANGE THE OTHER.
;
; Writing the menu's own version from scratch was the first attempt and it was
; wrong three ways - it called sh_recalc_all, it set no message, and it
; recorded NOTHING, so a macro recorded over it played back missing the
; command entirely.
; -----------------------------------------------------------------------------
sh_calc_now:
    push si
    inc word [sh_pass]                ; a pass stamp nothing has cached, which
    call sh_tbl_run_all               ; 81.114.8: ...and a table's results are
                                      ; STORED, so the stamp does nothing for
                                      ; them. WHATEVER THE MODE: Calculate Now
                                      ; is the command that means "catch
                                      ; everything up", and under Automatic
                                      ; except Tables it is the only thing
                                      ; that ever will
    mov word [sh_msg], sh_s_calc_now  ; is exactly what forces the recompute
    mov si, sh_s_rec_calc             ; 81.74: and the recorder sees it
    call sh_rec_cmd
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_docmd_options - AL = the Options row (SH_OI_*). Display... and
; Workspace... are the check-box engine's kinds 1 and 2 (81.106); Protect
; Document and Freeze Panes relabel themselves (the relabel-by-repointing idea
; documented above MENU_DIS in apps/os88api.inc)
; -----------------------------------------------------------------------------
sh_docmd_options:
    push si
    cmp al, SH_OI_FREEZE
    je .freeze
    cmp al, SH_OI_CALCNOW
    je .calcnow
    cmp al, SH_OI_CALC
    je .calc
    cmp al, SH_OI_PROT
    je .protect
    cmp al, SH_OI_DISPLAY
    je .display
    cmp al, SH_OI_WORKSPACE
    jne .done
    mov al, SH_BK_WORKSPACE
    call sh_bdlg_open_r
    pop si
    ret
.display:
    mov al, SH_BK_DISPLAY
    call sh_bdlg_open_r
    pop si
    ret
.calcnow:                              ; 81.78: Excel's own menu item, doing
    call sh_calc_now                   ; exactly what the Calculation dialog's
    jmp .repaint                       ; third choice does - one body, so the
                                       ; two cannot drift. Never greyed: with
                                       ; Calculation on Automatic it is a
                                       ; refresh that changes nothing, which
                                       ; is Excel's behaviour too
.protect:                              ; NO PASSWORD, and no ellipsis on the
    xor byte [sh_protected], 1         ; item to promise one - see 81.46.3.
    cmp byte [sh_protected], 0         ; The label flips, the way Freeze
    je .poff                           ; Panes' does
    mov word [sh_i_options + SH_OI_PROT * 2], sh_it_prot_on
    jmp .repaint
.poff:
    mov word [sh_i_options + SH_OI_PROT * 2], sh_it_prot_off
    jmp .repaint
.calc:
    mov al, SH_FDK_CALC
    call sh_fdlg_open_r
.done:
    pop si
    ret
; FREEZE PANES (81.70). Excel's own: the split is AT the active cell, so
; everything ABOVE and LEFT of it stops scrolling, and choosing the item
; again unfreezes. The ANCHOR is the active cell, not the extent - a
; dragged range freezes at the corner it was dragged FROM.
.freeze:
    mov ax, [sh_freezecol]
    or ax, [sh_freezerow]
    jnz .unfreeze
    mov ax, [sh_selcol]
    or ax, [sh_selrow]
    jnz .dofreeze
    mov word [sh_msg], sh_s_frz_at_a1  ; A1 has nothing above or left of it
    jmp .repaint                       ; to freeze: REFUSED in its own words
                                        ; (47), not silently done as nothing
.dofreeze:
    mov ax, [sh_selcol]
    mov [sh_freezecol], ax
    mov ax, [sh_selrow]
    mov [sh_freezerow], ax
    mov ax, [sh_scrollcol]             ; the scrolling region can never start
    cmp ax, [sh_freezecol]             ; inside the frozen prefix - every
    jae .fcok                          ; other reader takes that invariant
    mov ax, [sh_freezecol]             ; for granted
    mov [sh_scrollcol], ax
.fcok:
    mov ax, [sh_scrollrow]
    cmp ax, [sh_freezerow]
    jae .frok
    mov ax, [sh_freezerow]
    mov [sh_scrollrow], ax
.frok:
    call sh_frzmark
    jmp .repaint
.unfreeze:
    mov word [sh_freezecol], 0
    mov word [sh_freezerow], 0
    call sh_frzmark
    jmp .repaint
.repaint:
    mov si, [sh_ownwin]
    call sh_repaint
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_docmd_help - the only Help item, About Sheet...
; -----------------------------------------------------------------------------
sh_docmd_help:
    call sh_about
    ret

; -----------------------------------------------------------------------------
; sh_about - the OSAPI_ABOUT_SET handler (slot 0x018A, SPEC.md 12.2).
; in: SI = our window ptr; the UI task, gfx lock HELD, far-called at our own
; segment - a window callback in every respect that matters.
;
; Help > About Sheet... calls the SAME routine, so the two cannot say different
; things. Keeping the menu item as well as the name pull-down is deliberate:
; Excel 2.1d has a Help menu and this app follows Excel, while the pull-down is
; what os8088 users reach for.
;
; IT WAS A ONE-LINE ALERT and is the standard card now (SPEC.md 20.5.1).
; os88ui_ask's line is OS88UI_AMAX = 34 characters and CLIPPED rather than
; refused, which is a box with no room for a credit in it - and that is how
; this package shipped with no attribution while seventeen others had one.
; -----------------------------------------------------------------------------
sh_about:
    push bx
    push si
    mov byte [sh_abon], 1
    mov bx, [sh_ownwin]
    mov si, sh_ablines
    call os88ui_about               ; arms the clip itself: both doors into
    pop si                          ; here are menu dispatches, and neither
    pop bx                          ; arrives with a region (SPEC.md 11.3)
    ret

; -----------------------------------------------------------------------------
; sh_abdismiss - take the card down if it is up
; in:  gfx lock held ([sh_ownwin] names the window)
; out: CF = 1 the click or key was spent doing it; preserves every register
; -----------------------------------------------------------------------------
sh_abdismiss:
    cmp byte [sh_abon], 0
    je .none
    push bx
    push si
    mov byte [sh_abon], 0
    mov bx, [sh_ownwin]
    mov si, bx
    call OSAPI_WM_CLIP_SET          ; nothing has armed a region for a click
    jc .gone                        ; or a key (SPEC.md 11.3)
    call sh_repaint                 ; ...which white-fills and draws it all
.gone:
    pop si
    pop bx
    stc
    ret
.none:
    clc
    ret

; -----------------------------------------------------------------------------
; sh_docmd_format - Format menu item AL opens the matching dialog (stage
; 1.8: real Excel's own Format menu is dialog-per-verb - Number.../
; Alignment.../Font... - not a flat immediate-apply list, per the reference
; screenshots at
; LIBRARY/documentation/screenshots/excel/dialog_{number,alignment,font}.png;
; Sheet's menu now matches that shape, see the item table below). AL is 0
; Number, 1 Alignment, 2 Font - the same order sh_fdlg_open expects.
; -----------------------------------------------------------------------------
; sh_docmd_format - Format menu item AL: 0 Number/1 Alignment/2 Font map
; straight onto sh_fdlg_open's own kind numbers. 3 Border opens the
; separate sh_bdlg_* checkbox dialog, 4 Cell Protection is kind
; SH_FDK_PROT, and 5 Row Height/6 Column Width are sh_idlg_open's typed
; fields - sh_fdlg_open's own kinds 5/6, the presets they replaced, are
; retired (81.59).
sh_docmd_format:
    or al, al                          ; Number: Excel's list of codes (81.55),
    jnz .notnum                        ; not the four-way radio it was
    mov al, SH_LD_NUMFMT
    call sh_ldlg_open_r
    ret
.notnum:
    cmp al, 3
    jne .notborder
    mov al, SH_BK_BORDER
    call sh_bdlg_open_r
    ret
.notborder:
    cmp al, 4
    jne .notprot
    mov al, SH_FDK_PROT
    call sh_fdlg_open_r
    ret
.notprot:
    cmp al, 5
    jne .notrowh
    mov al, SH_ID_ROWH                 ; stage 3.0c: a typed number now, not
    call sh_idlg_open_r                  ; the 3-preset radio pick this had to
    ret                                ; be while no text field existed
.notrowh:
    cmp al, 6
    jne .notcolw
    mov al, SH_ID_COLW
    call sh_idlg_open_r
    ret
.notcolw:
    cmp al, 7                          ; 81.81: Justify, and it has to be
    jne .notjust                       ; caught HERE - the fallthrough below
    call sh_justify_r                  ; opens an sh_fdlg of kind AL, so an
    ret                                ; unintercepted 7 would open kind 7
.notjust:
    call sh_fdlg_open_r
    ret

; -----------------------------------------------------------------------------
; sh_docmd_edit - Edit menu item AL, NAMED by the SH_EI_ constants (81.99).
; This header used to list the rows by number, and the numbers had gone stale
; twice over - it still said 1 Cut, 2 Copy while Repeat sat at 1 - which is
; the whole case for the names. Undo is Undo or Redo when there is a snapshot
; and MENU_DIS when there is not (81.57). Cut, Copy and Paste use the real
; system clipboard (OSAPI_CLIP_*). Delete... and Insert... both open the
; Row/Column picker (sh_fdlg_* kinds 4 and 3 - see the dialog engine's own
; comment for why one engine serves several kinds). Fill Right and Fill Down
; are deliberately scoped down from real Excel: fill acts on just the one
; adjacent cell.
;
; THIS USED TO SAY "no range selection exists in this app (W_ONDRAG is
; missing... so a real rectangular selection was ruled out)". Stage 3.0a
; built one - drag, shift+click and shift+arrows - and the note stayed, in
; three places (here, sh_rowcol_op and sh_docmd_sortcol) all pointing at
; this one as the source. The BEHAVIOUR those two describe is still true;
; the REASON is not, and a reason that has expired is worse than none,
; because it says the thing cannot be done.
; -----------------------------------------------------------------------------
sh_docmd_edit:
    cmp al, SH_EI_UNDO                 ; Undo or Redo when there is a
    jne .notundo                       ; snapshot, and MENU_DIS - so it never
    call sh_undo_do                    ; arrives - when there is not (81.57)
    ret
.notundo:
    push ax                            ; the commands that act at once take
    mov ah, al                         ; their snapshot here; the dialogs'
    mov al, SH_UL_CUT                  ; take it at OK, in sh_fdlg_apply
    cmp ah, SH_EI_CUT
    je .snap
    mov al, SH_UL_PASTE
    cmp ah, SH_EI_PASTE
    je .snap
    mov al, SH_UL_PLINK
    cmp ah, SH_EI_PASTELK
    je .snap
    mov al, SH_UL_FILLR
    cmp ah, SH_EI_FILLR
    je .snap
    mov al, SH_UL_FILLD
    cmp ah, SH_EI_FILLD
    jne .nosnap
.snap:
    call sh_undo_begin
    pop ax
    call .cmd
    call sh_undo_end
    ret
.nosnap:
    pop ax
.cmd:
    cmp al, SH_EI_CUT
    je .cut
    cmp al, SH_EI_COPY
    je .copy
    cmp al, SH_EI_PASTE
    je .paste
    cmp al, SH_EI_CLEAR
    je .clear
    cmp al, SH_EI_PASTESP
    je .pastesp
    cmp al, SH_EI_PASTELK
    je .pastelk
    cmp al, SH_EI_DELETE
    je .delete
    cmp al, SH_EI_INSERT
    je .insert
    cmp al, SH_EI_FILLR
    je .fillright
    cmp al, SH_EI_FILLD
    je .filldown
    ret                                ; THERE WAS A `cmp al, 9 / je .sort`
                                       ; HERE, left behind when Sort moved to
                                       ; the Data menu - unreachable from a
                                       ; nine-item menu and therefore invisible.
                                       ; Adding three items made index 9 into
                                       ; Insert..., so the orphan would have
                                       ; turned Insert into Sort, silently, on
                                       ; a menu nobody had changed
.cut:
    call sh_docmd_cut
    ret
.copy:
    call sh_docmd_copy
    ret
.paste:
    mov byte [sh_ps_mode], SH_PS_ALL
    call sh_docmd_paste
    ret
.pastesp:
    cmp byte [sh_clip_valid], 0        ; Excel greys Paste Special when there
    je .noclip                         ; is no copy area; this app has no
    mov al, SH_FDK_PSPEC               ; dynamic enable, so it says so instead
    call sh_fdlg_open_r
    ret
.pastelk:
    cmp byte [sh_clip_valid], 0
    je .noclip
    mov byte [sh_ps_mode], SH_PS_LINK
    call sh_docmd_paste
    ret
.noclip:
    mov word [sh_msg], sh_s_nocopyarea
    mov si, [sh_ownwin]
    call sh_repaint
    ret
.clear:
    mov al, SH_FDK_CLEAR
    call sh_fdlg_open_r
    ret
.delete:
    mov al, 4
    call sh_fdlg_open_r
    ret
.insert:
    mov al, 3
    call sh_fdlg_open_r
    ret
.fillright:
    call sh_docmd_fillright
    ret
.filldown:
    call sh_docmd_filldown
    ret

; -----------------------------------------------------------------------------
; sh_prot_blocked - may the selected cell be changed? (81.46)
; out: CF=1 no, and the status line already says why; CF=0 go ahead.
;
; Two conditions, and BOTH are needed: the document has to be protected AND
; the cell has to be locked. That is Excel's model and it is the reason the
; per-cell bit alone does nothing visible - a Locked cell on an unprotected
; document is an ordinary cell, which is why every cell starts locked and
; nobody notices.
;
; Preserves every register. It sits in front of sh_commit, whose arguments
; are in them.
; -----------------------------------------------------------------------------
sh_prot_blocked:
    push ax
    push bx
    push cx
    push dx
    push si
    mov byte [sh_prot_hit], 0
    cmp byte [sh_protected], 0
    jne .scan
    cmp word [sh_ntbl], 0             ; 81.114.7: an unprotected document with
    je .done                          ; no table on it is every document this
.scan:                                ; app had before Data > Table, and the
                                      ; scan below costs it nothing at all
    ; THE WHOLE SELECTION, not the anchor. Cut and Clear act on the block,
    ; and a guard that asked about one corner would have let a Cut take
    ; every locked cell beside it. sh_commit's selection is 1x1 by the time
    ; it runs, so it costs one lookup there.
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .rr
    xchg ax, bx
.rr:
    mov cx, [sh_selcol]
    mov dx, [sh_selcol2]
    cmp cx, dx
    jbe .cc
    xchg cx, dx
.cc:
    mov si, ax                        ; SI walks the rows, CX the columns
.rowloop:
    push cx
.colloop:
    push ax
    push bx
    push cx
    push dx
    mov ax, cx
    mov bx, si
    call sh_bt_get                    ; 0 when there is no record, and no
    mov [sh_prot_bt], al              ; record is the LOCKED default. THE BYTE
    pop dx                            ; GOES TO BSS, not to AH: every register
    pop cx                            ; here is the caller's and the pops are
    pop bx                            ; what put them back, so a half-register
    pop ax                            ; would not survive them
    test byte [sh_prot_bt], SH_TBL_RESULT
    jz .notres                        ; 81.114.7: a Data > Table result cell
    cmp byte [sh_prot_clr], 0         ; cannot be edited, protected document
    je .hittbl                        ; or not - except by Edit > Clear, which
.notres:                              ; asks the WIDER question in
                                      ; sh_tbl_clearguard: a clear that covers
                                      ; a whole table is how a table is
                                      ; dropped, and must reach it to be
                                      ; judged
    cmp byte [sh_protected], 0
    je .next
    test byte [sh_prot_bt], SH_PROT_UNLOCK
    jnz .next
    mov byte [sh_prot_hit], 1
    pop cx
    jmp .done
.hittbl:
    mov byte [sh_prot_hit], 2
    pop cx
    jmp .done
.next:
    inc cx
    cmp cx, dx
    jbe .colloop
    pop cx
    inc si
    cmp si, bx
    jbe .rowloop
.done:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    mov byte [sh_prot_clr], 0         ; one call's worth, never a mode
    cmp byte [sh_prot_hit], 0
    je .ok
    mov word [sh_msg], sh_s_locked
    cmp byte [sh_prot_hit], 2
    jne .say
    mov word [sh_msg], sh_s_tblpart
.say:
    stc
    ret
.ok:
    clc
    ret

; -----------------------------------------------------------------------------
; sh_ps_src - the SOURCE cell for the block position being pasted into.
; out: AX = column, BX = row. The block walker keeps (sh_pb_x, sh_pb_y) as the
; offset within the block, and sh_clip_col/sh_clip_row is where the block was
; copied FROM, so the source is just the two added - the same arithmetic the
; reference shift does in the other direction.
;
; Only meaningful when sh_clip_valid: an external clipboard has text and no
; cells behind it. Every caller here is reached only after that test.
; -----------------------------------------------------------------------------
sh_ps_src:
    mov ax, [sh_clip_col]
    add ax, [sh_pb_x]
    mov bx, [sh_clip_row]
    add bx, [sh_pb_y]
    ret

; -----------------------------------------------------------------------------
; sh_ps_srcsheet / sh_ps_mysheet - step into the sheet the block was COPIED
; from, and back out again. (81.45.4)
;
; An address is not a cell here: sh_findcell, sh_bt_get and sh_nt_get all pack
; sh_cursheet into the row word, so reading the source cell's format, border or
; note while standing on the DESTINATION sheet reads whatever happens to live
; at that address on the wrong grid. Copy on Sheet1, switch to Sheet2, Paste
; Special > Formats, and the formats came from Sheet2's own cell.
;
; The pair is symmetric and nests nowhere - one caller enters, does its reads
; and leaves before writing anything, because the WRITES go to the current
; sheet and only the READS belong to the other one.
;
; TWO RULES, AND BREAKING EITHER IS SILENT. The banked sheet lives in ONE bss
; word, so (1) every path that enters must leave - a leave without a matching
; enter restores whatever the slot held last and moves the USER's sheet under
; them, which is how an experiment here left the grid showing Sheet1 after a
; paste onto Sheet2; and (2) the two callers must never nest, or the inner
; enter overwrites the outer's bank. They do not: sh_paste_cell reaches
; sh_ps_valtext for SH_PS_VAL and sh_ps_props for ALL/FORMATS/NOTES, and no
; mode reaches both.
; -----------------------------------------------------------------------------
sh_ps_srcsheet:
    push ax
    mov ax, [sh_cursheet]
    mov [sh_ps_ownsheet], ax
    mov ax, [sh_clip_sheet]
    mov [sh_cursheet], ax
    pop ax
    ret
sh_ps_mysheet:
    push ax
    mov ax, [sh_ps_ownsheet]
    mov [sh_cursheet], ax
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ps_props - copy the source cell's PROPERTIES onto the destination, which
; parts depending on [sh_ps_mode]: the format byte and the border for All and
; Formats, the note for All and Notes.
;
; The destination is wherever sh_selcol/sh_selrow point, which sh_paste_cell
; has just set. A source cell with no record contributes nothing rather than
; writing a default over what is already there - "paste formats" from an empty
; cell is not "clear the formats".
; -----------------------------------------------------------------------------
sh_ps_props:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    ; --- EVERY SOURCE READ FIRST, standing on the sheet the block came from.
    ; CL says the source had a cell record, CH that it had a note; DL is its
    ; format byte and DH its border/protection byte. The writes below all go
    ; to the CURRENT sheet, so the two must not interleave (81.45.4).
    xor cx, cx
    xor dx, dx
    call sh_ps_srcsheet
    mov al, [sh_ps_mode]
    cmp al, SH_PS_NOTE
    je .srcnote
    call sh_ps_src
    call sh_findcell
    jnc .srcborder                    ; no source record: nothing to copy
    mov es, [sh_cellseg]
    mov dl, [es:di+SH_C_FMT]
    mov cl, 1
.srcborder:
    call sh_ps_src
    call sh_bt_getw                   ; AL = the source's border byte, 0 none,
    mov dh, al                        ; AH its number format (81.55)
    mov [sh_ps_nf], ah
    cmp byte [sh_ps_mode], SH_PS_ALL  ; All carries the note as well
    jne .srcdone
.srcnote:
    call sh_ps_src
    call sh_nt_get
    jnc .srcdone                      ; no note on the source: leave the
    mov si, ax                        ; destination's own alone. Excel's All
    call sh_note_load                 ; does not erase a note either
    mov ch, 1
.srcdone:
    call sh_ps_mysheet                ; ...and back, before anything is written
    mov al, [sh_ps_mode]
    cmp al, SH_PS_NOTE
    je .putnote
    or cl, cl
    jz .noborder                      ; the source had no record at all
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_findcell
    jnc .noborder                     ; no DESTINATION record either - the
    mov es, [sh_cellseg]              ; same scope limit sh_fdlg_apply
    mov [es:di+SH_C_FMT], dl          ; documents for the Format dialogs
.noborder:
    mov al, [sh_ps_nf]
    or al, dh
    jz .clrborder
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_bt_addcell
    jc .fmtdone                       ; table full: silent, as sh_bdlg_apply is
    mov es, [sh_bordseg]
    mov [es:di+4], dh
    mov al, [sh_ps_nf]
    mov [es:di+5], al
    jmp .fmtdone
.clrborder:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call sh_bt_removecell
.fmtdone:
    cmp byte [sh_ps_mode], SH_PS_ALL
    jne .out
.putnote:
    or ch, ch
    jz .out
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    mov si, sh_notetext
    call sh_nt_set                    ; CF=1 = arena or table full, silent
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ps_valtext - the SOURCE cell's value, as text, into sh_editbuf: what
; "Values" means. A formula cell yields the number it produced, not the
; formula; a label yields its characters.
;
; This is sh_cell_totext's .notformula branch, reached UNCONDITIONALLY - which
; is the whole difference between the two routines and the reason this is not
; a flag on that one. sh_cell_totext exists to reproduce what the user typed;
; this exists to discard it.
; -----------------------------------------------------------------------------
sh_ps_valtext:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    mov byte [sh_editbuf], 0
    call sh_ps_srcsheet               ; the source cell is on the sheet the
    call sh_ps_src                    ; block was COPIED from (81.45.4)
    call sh_findcell
    jnc .valdone                      ; an empty source pastes an empty cell
    mov es, [sh_cellseg]
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    je .label
    call sh_cellnum                   ; the eight value bytes, as decimal
    mov si, sh_numbuf
    mov di, sh_editbuf
    call sh_strcpy
    jmp .valdone
.label:
    mov ax, [es:di+SH_C_FOFF]         ; a label shares the formula arena
    mov si, ax
    mov di, sh_editbuf
    mov es, [sh_txtseg]
.acopy:
    cmp di, sh_editbuf + SH_EDITMAX   ; sh_editbuf's 63 and the NUL: a label
    jae .acut                         ; another reader stored can be longer
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .acopy
    jmp short .valdone
.acut:
    mov byte [di], 0
.valdone:
    call sh_ps_mysheet                ; EVERY path leaves it, not just the
.count:                               ; empty one - the caller commits to the
                                      ; CURRENT sheet immediately after
    xor cx, cx
    mov si, sh_editbuf
.len:
    cmp byte [si], 0
    je .haslen
    inc si
    inc cx
    jmp .len
.haslen:
    mov [sh_editlen], cl
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ps_linktext - "=<the source cell>" into sh_editbuf: what Paste Link
; means. Written as A1-style text and handed to sh_commit like anything else,
; so the result is an ordinary formula that happens to name one cell - which
; is exactly what Excel produces, and means every later Insert/Delete/Sort
; rewrites it through the machinery that already exists (81.28).
;
; RELATIVE, not absolute. Excel 2.1's Paste Link writes a relative reference,
; so a linked block dragged elsewhere follows the same rule as any other
; copied formula.
; -----------------------------------------------------------------------------
sh_ps_linktext:
    push ax
    push bx
    push cx
    push si
    push di
    mov byte [sh_editbuf], '='
    mov di, sh_editbuf + 1
    ; --- a link to ANOTHER sheet has to say which one (81.45.4) -----------
    mov ax, [sh_clip_sheet]
    cmp ax, [sh_cursheet]
    je .samesheet                     ; the ordinary case writes no prefix, so
    push ax                           ; a same-sheet link is byte-for-byte
    mov si, sh_s_sheetpfx             ; what it always was
    call sh_strcpy_to_di
    pop ax
    add al, '1'                       ; "Sheet1".."Sheet4" are the only names
    mov [di], al                      ; there are (sh_psheetpfx), so the index
    inc di                            ; IS the digit
    mov byte [di], '!'
    inc di
.samesheet:
    call sh_ps_src
    push bx                           ; sh_colname and sh_itoa both go through
    call sh_colname                   ; scratch buffers, so the row is banked
    mov si, sh_colbuf                 ; rather than recomputed
    call sh_strcpy_to_di
    pop ax
    inc ax                            ; rows are 1-based on screen
    call sh_itoa
    mov si, sh_numbuf
    call sh_strcpy_to_di
    mov byte [di], 0                  ; A1 STYLE UNCONDITIONALLY, even with
                                      ; the reference box set to R1C1: that is
                                      ; a DISPLAY setting (81.31), and this
                                      ; text goes to sh_commit, whose parser
                                      ; reads A1 and nothing else
    xor cx, cx
    mov si, sh_editbuf
.len:
    cmp byte [si], 0
    je .haslen
    inc si
    inc cx
    jmp .len
.haslen:
    mov [sh_editlen], cl
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_cell_totext - the text of the cell at (AX,BX) into sh_clipbuf: a formula's
; own source with its '=' restored, a label's characters, or a number as
; decimal. An empty cell gives an empty string. out: CX = the length.
;
; Copy used to do this inline and got two of the three wrong. It read a WORD at
; SH_C_VAL and ran sh_itoa over it - which is what everything did before stage
; 4.0, and is meaningless now that the value is an eight-byte double whose low
; word is mantissa bits (sh_cellnum exists to say exactly that). And it had no
; case for a label at all, so copying a column heading ran the numeric path
; over its text offset. One routine now, so the next thing that needs a cell as
; text cannot get a third answer.
; -----------------------------------------------------------------------------
sh_cell_totext:
    push ax
    push bx
    push dx                           ; callers loop on DX; sh_cellnum and the
    push si                           ; arena copy below both go through it
    push di
    push es
    mov byte [sh_clipbuf], 0
    call sh_findcell
    jnc .count
    mov es, [sh_cellseg]
    test byte [es:di+4], 1            ; HASFORMULA
    jz .notformula
    mov ax, [es:di+SH_C_FOFF]
    mov byte [sh_clipbuf], '='
    mov di, sh_clipbuf + 1
    jmp .arena
.notformula:
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    je .label
    call sh_cellnum                   ; the eight value bytes, as decimal
    mov si, sh_numbuf
    mov di, sh_clipbuf
    call sh_strcpy
    jmp .count
.label:
    mov ax, [es:di+SH_C_FOFF]         ; a label shares the formula arena
    mov di, sh_clipbuf
.arena:
    mov si, ax
    mov es, [sh_txtseg]
.acopy:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .acopy
.count:
    xor cx, cx
    mov si, sh_clipbuf
.cnt:
    cmp byte [si], 0
    je .out
    inc si
    inc cx
    jmp .cnt
.out:
    pop es
    pop di
    pop si
    pop dx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_copy - builds the selected cell's text (a formula's own source
; text with its '=' restored, or a plain value's decimal text - the same
; two cases sh_beginedit already knows how to build, just targeting
; sh_clipbuf instead of sh_editbuf) and hands it to the real clipboard. An
; empty cell empties the clipboard instead (CX=0 is documented as not an
; error).
; -----------------------------------------------------------------------------
sh_docmd_copy:
    push si
    mov si, sh_s_rec_copy              ; 81.74
    call sh_rec_cmd
    pop si
    push ax
    push bx
    push cx
    push si
    push di
    push es
    ; THE TOP-LEFT of the selection, not the anchor: a drag can start at any
    ; corner, and Paste's reference shift is measured from where the block
    ; began rather than from where the mouse went down.
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .cpc
    xchg ax, bx
.cpc:
    mov [sh_clip_col], ax
    mov cx, bx                         ; cx = last column
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .cpr
    xchg ax, bx
.cpr:
    mov [sh_clip_row], ax
    mov ax, [sh_cursheet]              ; WHICH SHEET the block came from, which
    mov [sh_clip_sheet], ax            ; matters the moment Paste Special reads
    mov byte [sh_clip_valid], 1        ; the SOURCE CELLS again (81.45.4)
    ; --- build the block as TAB-SEPARATED TEXT in the staging segment ------
    ; Tabs between columns, CR/LF between rows, and nothing after the last
    ; one - which is exactly what Excel puts on the clipboard, makes a 1x1
    ; block byte-identical to what this used to write, and means a copied
    ; block pastes into Word as text that lines up.
    push bp
    mov es, [sh_stgseg]
    xor di, di                         ; di = the write cursor
    mov dx, ax                         ; dx = the current row
.rowloop:
    mov bp, [sh_clip_col]              ; bp = the current column
.colloop:
    push ax
    push bx
    push cx
    push dx
    mov ax, bp
    mov bx, dx
    call sh_cell_totext                ; -> sh_clipbuf, CX = length
    mov si, sh_clipbuf
.emit:
    or cx, cx
    jz .emitted
    cmp di, SH_STAGE_MAX - 4           ; the staging area is the bound here
    jae .emitted
    mov al, [si]
    mov [es:di], al
    inc si
    inc di
    dec cx
    jmp .emit
.emitted:
    pop dx
    pop cx
    pop bx
    pop ax
    cmp bp, cx
    jae .rowend
    cmp di, SH_STAGE_MAX - 4
    jae .rowend
    mov byte [es:di], 9                ; TAB between columns
    inc di
    inc bp
    jmp .colloop
.rowend:
    cmp dx, bx                         ; bx is still the last row
    jae .blockdone
    cmp di, SH_STAGE_MAX - 4
    jae .blockdone
    mov byte [es:di], 13               ; CR/LF between rows, none after the
    inc di                             ; last - so a single cell is exactly
    mov byte [es:di], 10               ; its own text, as before
    inc di
    inc dx
    jmp .rowloop
.blockdone:
    pop bp
    mov cx, di
    xor si, si
    call OSAPI_CLIP_PUT                ; ES is already the staging segment
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_docmd_cut - Copy, then Clear
sh_docmd_cut:
    push si
    mov si, sh_s_rec_cut               ; 81.74
    call sh_rec_cmd
    pop si
    push ax
    push bx
    push cx
    push si
    push di
    call sh_prot_blocked              ; Cut CLEARS through sh_clearcell, not
    jc .refused                       ; sh_commit, so the funnel guard misses
    call sh_docmd_copy                 ; the whole block goes to the clipboard,
    mov ax, [sh_selrow]                ; so the whole block has to leave the
    mov bx, [sh_selrow2]               ; sheet - it cleared the anchor alone
    cmp ax, bx                         ; and left the rest of what it had just
    jbe .cutrows                       ; copied sitting there
    xchg ax, bx
.cutrows:
    mov cx, [sh_selcol]
    mov si, [sh_selcol2]
    cmp cx, si
    jbe .cutcols
    xchg cx, si
.cutcols:
.cutcolloop:
    mov di, ax
.cutrowloop:
    push ax
    push bx
    mov ax, cx
    mov bx, di
    call sh_clearcell
    pop bx
    pop ax
    inc di
    cmp di, bx
    jbe .cutrowloop
    inc cx
    cmp cx, si
    jbe .cutcolloop
    mov si, [sh_ownwin]
    call sh_repaint
    jmp .out
.refused:                             ; A REFUSAL STILL HAS TO REPAINT. Jumping
    mov si, [sh_ownwin]               ; straight to the exit skipped the redraw
    call sh_repaint                   ; and the message sh_prot_blocked had just
.out:                                 ; set was never painted - the command did
    pop di                            ; nothing and said nothing
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_paste - reads the system clipboard straight into sh_editbuf
; (capped to SH_EDITMAX, same as anything a keyboard could ever produce
; there); if this instance's own last Copy captured a formula AND a
; source cell (sh_clip_valid), and the destination differs from it,
; shifts every reference in the pasted formula by the (col, row) delta
; between them (sh_formula_copyshift) - real Excel's own default
; relative-reference behavior - before calling sh_commit to reuse its
; existing value/formula parsing exactly as if this (possibly rewritten)
; text had been typed. An empty clipboard is a no-op.
; -----------------------------------------------------------------------------
sh_docmd_paste:
    push si
    mov si, sh_s_rec_paste             ; 81.74
    call sh_rec_cmd
    pop si
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    call OSAPI_CLIP_SIZE
    jc .out
    or ax, ax
    jz .out
    cmp ax, SH_STAGE_MAX - 2           ; the staging segment holds the block
    jbe .fits                          ; while it is taken apart
    mov ax, SH_STAGE_MAX - 2
.fits:
    mov cx, ax
    mov es, [sh_stgseg]
    xor di, di
    call OSAPI_CLIP_GET
    mov [sh_pb_len], cx
    mov ax, [sh_selcol]                ; where the block lands
    mov [sh_pb_c0], ax
    mov ax, [sh_selrow]
    mov [sh_pb_r0], ax
    mov word [sh_pb_x], 0
    mov word [sh_pb_y], 0
    mov word [sh_pb_cur], 0
.cell:
    mov ax, [sh_pb_cur]
    cmp ax, [sh_pb_len]
    jae .done
    ; --- one cell's text out of the block, up to TAB, CR, LF or the end ----
    mov es, [sh_stgseg]
    mov si, ax
    mov di, sh_editbuf
    xor cx, cx
.take:
    cmp si, [sh_pb_len]
    jae .took
    mov al, [es:si]
    cmp al, 9
    je .took
    cmp al, 13
    je .took
    cmp al, 10
    je .took
    cmp cx, SH_EDITMAX
    jae .skiptail
    mov [di], al
    inc di
    inc si
    inc cx
    jmp .take
.skiptail:
    inc si                             ; over-long cell: drop the rest, so the
    jmp .take                          ; dispatch below sees the cell's real
                                       ; terminator - its 64th character read
                                       ; as "new row" and smeared each further
                                       ; 63-byte chunk one row down
.took:
    mov byte [di], 0
    mov [sh_editlen], cl
    mov [sh_pb_cur], si                ; the terminator is consumed below
    call sh_paste_cell
    ; --- what ended it decides where the next one goes --------------------
    mov es, [sh_stgseg]
    mov si, [sh_pb_cur]
    cmp si, [sh_pb_len]
    jae .done
    mov al, [es:si]
    inc si
    mov [sh_pb_cur], si
    cmp al, 9                          ; TAB: the next column
    jne .newrow
    inc word [sh_pb_x]
    jmp .cell
.newrow:
    cmp al, 13                         ; CR, and swallow an LF behind it
    jne .lfonly
    cmp si, [sh_pb_len]
    jae .rowdone
    cmp byte [es:si], 10
    jne .rowdone
    inc si
    mov [sh_pb_cur], si
.rowdone:
.lfonly:
    mov word [sh_pb_x], 0
    inc word [sh_pb_y]
    jmp .cell
.done:
    mov ax, [sh_pb_c0]                 ; put the selection back where it was
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov ax, [sh_pb_r0]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
    mov si, [sh_ownwin]                ; ONE repaint for the whole block
    call sh_repaint
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_paste_cell - commit sh_editbuf into the block cell at (sh_pb_x, sh_pb_y),
; shifting a formula's relative references by the SAME delta for every cell in
; the block: where the block landed, less where it was copied from. That is
; Excel's rule, and it is what makes a copied column of =A1*B1 still line up a
; column over.
;
; It moves sh_selcol/sh_selrow and calls sh_commit rather than reimplementing
; the decision, because sh_commit is the ONE place that decides whether text
; is a formula, a number or a label - a second copy of that would be a second
; answer. The selection is restored by the caller when the block is done.
; -----------------------------------------------------------------------------
sh_paste_cell:
    push ax
    push bx
    push cx
    push si
    push di
    mov ax, [sh_pb_c0]
    add ax, [sh_pb_x]
    cmp ax, SH_COLS
    jae .out                           ; a block that runs off the edge stops
    mov [sh_selcol], ax                ; at it rather than wrapping
    mov [sh_selcol2], ax
    mov bx, [sh_pb_r0]
    add bx, [sh_pb_y]
    cmp bx, SH_ROWS
    jae .out
    mov [sh_selrow], bx
    mov [sh_selrow2], bx
    call sh_prot_blocked              ; Formats and Notes write the tables
    jc .out                           ; DIRECTLY and never reach sh_commit, so
                                      ; the funnel guard does not cover them
    ; --- WHICH PARTS OF THE SOURCE CELL THIS PASTE IS FOR (81.45) ----------
    mov al, [sh_ps_mode]
    cmp al, SH_PS_LINK
    je .dolink
    cmp al, SH_PS_FMT                 ; Formats and Notes leave the CONTENTS
    jb .contents                      ; alone entirely - they are the two
    call sh_ps_props                  ; modes with nothing to commit
    jmp .out
.dolink:
    call sh_ps_linktext               ; "=<the source cell>" - no shifting,
    jmp .commit                       ; the whole point is that it points back
.contents:
    cmp al, SH_PS_VAL
    jne .astyped
    call sh_ps_valtext                ; the source's VALUE, so a formula lands
    jmp .commit                       ; as the number it produced. Never
                                      ; reference-shifted: there is no
                                      ; reference left in it to shift
.astyped:
    cmp byte [sh_clip_valid], 0
    je .commit
    cmp byte [sh_editbuf], '='
    jne .commit
    mov ax, [sh_pb_c0]
    sub ax, [sh_clip_col]
    mov [sh_cp_coldelta], ax
    mov bx, [sh_pb_r0]
    sub bx, [sh_clip_row]
    mov [sh_cp_rowdelta], bx
    or ax, bx
    jz .commit                         ; pasted onto the cell it came from
    mov si, sh_editbuf
    inc si
    mov di, sh_rwsrc
.copyin:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .copyin
    mov si, sh_rwsrc
    call sh_formula_copyshift
    mov byte [sh_editbuf], '='
    mov si, sh_rwdst
    mov di, sh_editbuf + 1
    mov cx, SH_EDITMAX - 1             ; a shifted reference can grow a digit
.copyout:                              ; or two, so clip rather than overrun
    mov al, [si]
    or al, al
    jz .copyoutdone
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .copyout
.copyoutdone:
    mov byte [di], 0
    xor cx, cx
    mov si, sh_editbuf
.relen:
    cmp byte [si], 0
    je .haverelen
    inc si
    inc cx
    jmp .relen
.haverelen:
    mov [sh_editlen], cl
.commit:
    mov byte [sh_editing], 1
    call sh_commit
    cmp byte [sh_ps_mode], SH_PS_ALL  ; All is contents AND properties, which
    jne .out                          ; is what Excel's plain Paste does too
    call sh_ps_props
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_fillright / sh_docmd_filldown - fill the SELECTED RANGE from its
; own first column/row, the way Excel does: Fill Down copies the selection's
; top row into every row under it, for every column in the selection, and
; Fill Right copies its left column across.
;
; These two used to copy exactly one cell into exactly one neighbour, because
; they were written before range selection existed (stage 3.0a) and were never
; taught about sh_selcol2/sh_selrow2. Selecting a block and choosing Fill Down
; changed a single cell and reported nothing - the selection stayed drawn over
; cells that had not been touched. A SINGLE-CELL selection still fills the one
; neighbour, which is what the old behaviour was and what collapsing the
; anchor and extent already means here.
;
; A formula source has its text copied through sh_formula_copyshift (the same
; relative-reference shift Copy/Paste uses), and the delta is the FULL offset
; from the source rather than always one - filling five rows down has to shift
; the fifth by five. A plain value is copied as its current value.
; -----------------------------------------------------------------------------
; sh_fill_copy - one cell to another. in: sh_fl_scol/srow = source,
; sh_fl_dcol/drow = destination. An empty source copies nothing. Preserves
; every register, so the loops below can keep their bounds in theirs.
; -----------------------------------------------------------------------------
sh_fill_copy:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov ax, [sh_fl_scol]
    mov bx, [sh_fl_srow]
    call sh_findcell
    jnc .out                           ; empty source: nothing to fill
    mov es, [sh_cellseg]
    test byte [es:di+4], 1             ; HASFORMULA
    jz .plain
    mov ax, [es:di+SH_C_FOFF]
    mov si, ax
    mov es, [sh_txtseg]
    mov di, sh_rwsrc
.copyin:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .copyin
    mov ax, [sh_fl_dcol]
    sub ax, [sh_fl_scol]
    mov [sh_cp_coldelta], ax
    mov ax, [sh_fl_drow]
    sub ax, [sh_fl_srow]
    mov [sh_cp_rowdelta], ax
    mov si, sh_rwsrc
    call sh_formula_copyshift
    mov ax, [sh_fl_dcol]
    mov bx, [sh_fl_drow]
    mov si, sh_rwdst
    call sh_setformula
    jmp .out
.plain:
    mov ax, [sh_fl_scol]
    mov bx, [sh_fl_srow]
    call sh_getcell2                   ; the full double lands in sh_acc, and
    cmp byte [sh_curtype], SH_T_TEXT   ; the tag says label or number (81.13 -
    je .text                           ; 81.18's Copy defect, closed here too)
    mov ax, [sh_fl_dcol]
    mov bx, [sh_fl_drow]
    cmp byte [sh_curtype], SH_T_ERR    ; ...or an ERROR CONSTANT, which the
    jne .fbool                         ; number store turned into 0 (81.61)
    mov dl, [sh_curaux]
    call sh_seterr
    jmp .out
.fbool:
    cmp byte [sh_curtype], SH_T_BOOL   ; ...or LOGICAL, which a number store
    jne .fnum                          ; would flatten to 1 (81.51)
    call sh_setbool                    ; DL: sh_getcell2's truncated value
    jmp .out
.fnum:
    call sh_setvald                    ; an integer store would truncate 3.5
    jmp .out
.text:
    mov si, [sh_curtoff]               ; a LABEL: copy its text out of
    mov es, [sh_txtseg]                ; sh_txtseg into DS scratch, because
    mov di, sh_rwsrc                   ; sh_settext reads DS:SI
.tcopy:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .tcopy
    mov ax, [sh_fl_dcol]
    mov bx, [sh_fl_drow]
    mov si, sh_rwsrc
    call sh_settext
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret
; -----------------------------------------------------------------------------
sh_docmd_fillright:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov ax, [sh_selcol]                ; normalise: a drag can run either way
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .colsok
    xchg ax, bx
.colsok:
    mov [sh_fl_scol], ax               ; the source is the LEFTMOST column
    cmp ax, bx
    jne .haverange
    inc bx                             ; a one-column selection fills the one
    cmp bx, SH_COLS                    ; column over, as this always did
    jae .out
.haverange:
    mov cx, [sh_selrow]                ; ...for every row of the selection
    mov si, [sh_selrow2]
    cmp cx, si
    jbe .rowsok
    xchg cx, si
.rowsok:
.rowloop:
    mov [sh_fl_srow], cx
    mov [sh_fl_drow], cx
    mov dx, [sh_fl_scol]
.colloop:
    inc dx
    cmp dx, bx
    ja .nextrow
    mov [sh_fl_dcol], dx
    call sh_fill_copy
    jmp .colloop
.nextrow:
    inc cx
    cmp cx, si
    jbe .rowloop
    mov si, [sh_ownwin]                ; ONE repaint for the whole fill, not
    call sh_repaint                    ; one per cell
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

sh_docmd_filldown:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .rowsok
    xchg ax, bx
.rowsok:
    mov [sh_fl_srow], ax               ; the source is the TOP row
    cmp ax, bx
    jne .haverange
    inc bx                             ; a one-row selection fills the one
    cmp bx, SH_ROWS                    ; row below, as this always did
    jae .out
.haverange:
    mov cx, [sh_selcol]                ; ...for every column of the selection
    mov si, [sh_selcol2]
    cmp cx, si
    jbe .colsok
    xchg cx, si
.colsok:
.colloop:
    mov [sh_fl_scol], cx
    mov [sh_fl_dcol], cx
    mov dx, [sh_fl_srow]
.rowloop:
    inc dx
    cmp dx, bx
    ja .nextcol
    mov [sh_fl_drow], dx
    call sh_fill_copy
    jmp .rowloop
.nextcol:
    inc cx
    cmp cx, si
    jbe .colloop
    mov si, [sh_ownwin]
    call sh_repaint
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret
section SH_MODSEC                      ; 81.71.6: ...and the carry half of it

; -----------------------------------------------------------------------------
; sh_sort_carry - apply the key column's permutation to every OTHER column in
; the selection, so a table sorts as ROWS rather than as one column sliding
; past its neighbours.
;
; This is what "why can't we sort multiple columns" wanted. Sorting one column
; of a table and leaving the others put does not sort anything - it breaks the
; correspondence between them, silently, and the sheet looks ordinary
; afterwards. Excel sorts whole rows by a key column; so does this now.
;
; The permutation is already computed: rows[] are the target rows and
; origidx[i] says which original entry belongs at position i. Each column is
; SNAPSHOT AS TEXT first, because writing a column in place would overwrite
; cells the permutation still has to read. Text is the intermediate because it
; covers values, labels and formulas with one representation - sh_cell_totext
; on the way out and sh_commit on the way back, which is the same pair the
; block clipboard uses (81.18) and the same single decision about what a
; string means.
; -----------------------------------------------------------------------------
sh_sort_carry:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    cmp word [sh_sort_cnt], 2
    jb .out
    cmp word [sh_sort_cnt], SH_SORT_SNAPCAP
    ja .out                           ; more rows than the snapshot holds: the
                                      ; key column is still sorted, the others
                                      ; are left alone rather than half moved
    mov ax, [sh_sort_keycol]             ; THE KEY COLUMN, banked before anything
    mov [sh_cry_key], ax              ; else runs: sh_sort_permcol moves
    mov bx, [sh_selrow]               ; sh_selcol to commit into each carried
    mov [sh_cry_keyrow], bx           ; column, so reading it later names
                                      ; whichever column was carried last and
                                      ; the key gets carried too - permuted a
                                      ; second time, on top of its own sort
    ; THE SPAN IS THE SELECTION'S, NOT THE KEY'S. These two used to be the
    ; same register because the key WAS the anchor; now that the dialog picks
    ; the key (81.27), deriving the span from it carried only the columns to
    ; the key's right - sorting A:C by B left column A exactly where it was,
    ; which is the correspondence-breaking this whole routine exists to
    ; prevent.
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .cols
    xchg ax, bx
.cols:
    mov [sh_cry_c1], ax
    mov [sh_cry_c2], bx
    cmp ax, bx
    je .out                           ; one column: the write-back did it all
    mov cx, ax
.colloop:
    cmp cx, [sh_cry_c2]
    ja .done
    cmp cx, [sh_cry_key]
    je .nextcol                       ; the key column is already written
    mov [sh_cry_col], cx
    call sh_sort_snapcol
    call sh_sort_permcol
    jc .done                          ; the arena refused (message already
                                      ; set): stop carrying, restore the
                                      ; selection and let the repaint say so
.nextcol:
    inc cx
    jmp .colloop
.done:
    mov ax, [sh_cry_key]              ; put the selection back where it was
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov ax, [sh_cry_keyrow]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_sort_snapcol - column [sh_cry_col]'s cells, for the sorted rows, as text
; in the snapshot slots. An empty cell snapshots as an empty string, which is
; what makes the permutation able to move emptiness around like anything else.
sh_sort_snapcol:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov word [sh_cry_i], 0            ; THE COUNTER LIVES IN BSS, not in a
.snap:                                ; register: this loop calls out to
    mov dx, [sh_cry_i]                ; sh_cell_totext and multiplies, and an
    cmp dx, [sh_sort_cnt]             ; index in DX did not survive either -
    jae .out                          ; the loop simply never ended and the
                                      ; machine stopped
    mov es, [sh_stgseg]
    mov si, dx
    shl si, 1
    mov bx, [es:si]                   ; rows[i]
    mov ax, [sh_cry_col]
    SHOUT sh_cell_totext               ; -> sh_clipbuf, CX = length
    cmp cx, 63
    jbe .fits
    mov cx, 63
.fits:
    mov ax, [sh_cry_i]                ; slot = SNAP + i*64
    mov di, 64
    mul di
    add ax, SH_SORT_SNAP_OFF
    mov di, ax
    mov es, [sh_stgseg]
    mov si, sh_clipbuf
    jcxz .term
.scopy:
    mov al, [si]
    mov [es:di], al
    inc si
    inc di
    dec cx
    jnz .scopy
.term:
    mov byte [es:di], 0
    inc word [sh_cry_i]
    jmp .snap
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_sort_permcol - write column [sh_cry_col] back in the sorted order, each
; cell shifted by its own row delta the way the key column's own write-back
; shifts formulas. Out: CF=1 = the text arena refused a commit mid-permutation:
; [sh_msg] says so and the caller must stop carrying further columns - going
; on would keep burning the arena and keep half-applying.
sh_sort_permcol:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov word [sh_cry_i], 0            ; in bss for sh_sort_snapcol's reason
.perm:
    mov dx, [sh_cry_i]
    cmp dx, [sh_sort_cnt]
    jae .out
    mov es, [sh_stgseg]
    mov si, dx
    shl si, 1
    add si, SH_SORT_ORIG_OFF
    mov bx, [es:si]                   ; src = origidx[dx]
    cmp bx, dx
    je .nextperm                      ; already in place: nothing to rewrite
    mov [sh_cry_src], bx
    mov si, dx                        ; target row = rows[dx]
    shl si, 1
    mov ax, [es:si]
    mov [sh_cry_trow], ax
    mov si, bx                        ; source row = rows[src]
    shl si, 1
    mov ax, [es:si]
    mov [sh_cry_srow], ax
    ; the snapshot slot for src, into sh_editbuf
    mov ax, [sh_cry_src]
    mov di, 64
    mul di
    add ax, SH_SORT_SNAP_OFF
    mov si, ax
    mov di, sh_editbuf
    xor cx, cx
.load:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .loaded
    inc si
    inc di
    inc cx
    jmp .load
.loaded:
    mov [sh_editlen], cl
    mov ax, [sh_cry_col]               ; where it is going
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov ax, [sh_cry_trow]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
    cmp byte [sh_editbuf], '='
    jne .commit
    mov ax, [sh_cry_trow]              ; a formula follows its own row
    sub ax, [sh_cry_srow]
    mov [sh_cp_rowdelta], ax
    mov word [sh_cp_coldelta], 0
    or ax, ax
    jz .commit
    mov si, sh_editbuf
    inc si
    mov di, sh_rwsrc
.fcopy:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .fcopy
    mov si, sh_rwsrc
    SHOUT sh_formula_copyshift
    mov byte [sh_editbuf], '='
    mov si, sh_rwdst
    mov di, sh_editbuf + 1
    mov cx, SH_EDITMAX - 1
.fout:
    mov al, [si]
    or al, al
    jz .fdone
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .fout
.fdone:
    mov byte [di], 0
    xor cx, cx
    mov si, sh_editbuf
.flen:
    cmp byte [si], 0
    je .fhave
    inc si
    inc cx
    jmp .flen
.fhave:
    mov [sh_editlen], cl
.commit:
    mov byte [sh_editing], 1
    SHOUT sh_commit
    jc .arenafull                     ; the text arena refused: entries already
.nextperm:                            ; written hold the new order, the rest
    inc word [sh_cry_i]               ; the old - stop and SAY SO rather than
    jmp .perm                         ; keep half-applying in silence
.out:
    clc
    jmp .ret
.arenafull:
    mov word [sh_msg], sh_s_sortfull
    stc
.ret:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

section .text

sh_s_sortfull: db 'Sort incomplete - text area full.', 0
sh_s_sorttbl:  db 'Sorted - a table in the range is no longer one.', 0

; -----------------------------------------------------------------------------
; sh_docmd_sortcol - sorts the selected column's occupied cells (on the
; current sheet) ascending by value; empty rows are left exactly where
; they are, so occupied cells are compacted toward the top the same way
; the original plain-values-only sort already did. Stage 2.x: a formula
; cell now sorts right alongside plain values (by its CURRENT evaluated
; value, via sh_getcell2, so staleness is never an issue) and, if the
; sort actually moves it to a different row, its own text is rewritten
; with sh_formula_copyshift (a (0, row-delta) shift, the same machinery
; Copy/Paste and Fill Down use) so its references still mean what they
; looked like they meant - matching real Excel's own behavior, where
; sorting a range that contains formulas carries their relative
; references along with them. Previously formula cells were excluded
; from the sort entirely (skipped, left in their original row) purely
; because this reference-adjustment capability did not exist yet.
;
; Method: one linear pass over the cell array collects this column's
; occupied cells into sh_stgseg - rows[] at offset 0, values[] at
; SH_SORT_VALS_OFF (both well under its 32KB claim: SH_CELL_CAP=1365
; entries needs at most 2730 bytes each), plus origidx[]/isformula[]/
; fidx[]/staged-formula-text (SH_SORT_ORIG_OFF/SH_SORT_ISF_OFF/
; SH_SORT_FIDX_OFF/SH_SORT_FTXT_OFF - see their own equ comments). Because
; the cell array is sorted by row within a sheet (the stage 2.0 comment
; above sh_findcell), rows[] comes out already ascending for free -
; sorting is really just "which ORIGINAL entry's data ends up at which
; ascending row", so values[] and origidx[] are insertion-sorted together
; (a parallel permutation, not just a value sort) and then written back:
; a plain value straight via sh_setvald as before; a formula, only if it
; actually changed row, via sh_formula_copyshift + sh_setformula using
; that specific cell's own (target row - its original row) delta - each
; moved formula can have a DIFFERENT delta, since a sort is an arbitrary
; reordering, not a uniform shift like Insert/Delete Row or Copy/Paste.
; A sort key is a whole column by definition, so this acts on all of the
; selected column rather than on the selected part of it.
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_chart_scan - (re)collect [sh_chart_sheet]/[sh_chart_col]'s plain-value
; cells into sh_stgseg/sh_chart_cnt, capped at CH_MAXBARS (same shape as
; sh_docmd_sortcol's own scan). Does NOT touch sh_chart_sheet/sh_chart_col
; themselves - sh_docmd_chart freezes those from the current selection
; before calling this; the live-update hook in sh_repaint calls this
; against whatever was already frozen, so every edit to the charted column
; is reflected without retargeting the chart to wherever the selection
; happens to be at the time.
; -----------------------------------------------------------------------------
; sh_chart_scan - series ONE from [sh_chart_col], then series TWO from the
; column to its right if that column holds anything. Two passes rather than one
; because the cell array is sorted by row and then column, so a single walk
; would interleave them and both series must come out in row order.
sh_chart_scan:
    push ax
    mov ax, [sh_chart_col]
    mov [sh_scan_col], ax
    mov word [sh_scan_off], SH_CHART_D1
    call sh_chart_scan1
    mov ax, [sh_chart_cnt2]           ; sh_chart_scan1 leaves its count here
    mov [sh_chart_cnt], ax
    mov ax, [sh_chart_col]
    inc ax
    cmp ax, SH_COLS
    jae .nosecond
    mov [sh_scan_col], ax
    mov word [sh_scan_off], SH_CHART_D2
    call sh_chart_scan1
    jmp .done
.nosecond:
    mov word [sh_chart_cnt2], 0
.done:
    mov word [ch_arr2], SH_CHART_S2
    mov ax, [sh_chart_cnt2]
    mov [ch_cnt2], ax
    mov ax, [sh_stgseg]
    mov [ch_srcseg2], ax
    ; --- the doubles become the words the drawing runs on (82.13) ----------
    ; SERIES TWO FIRST, so [ch_e10] is left holding SERIES ONE's exponent:
    ; that is the series the value axis is labelled from.
    push bx
    push cx
    push dx
    push si
    push di
    mov dx, [sh_stgseg]
    mov si, SH_CHART_D2
    mov di, SH_CHART_S2
    mov cx, [sh_chart_cnt2]
    CHMOD scale
    mov dx, [sh_stgseg]
    mov si, SH_CHART_D1
    xor di, di
    mov cx, [sh_chart_cnt]
    CHMOD scale
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

sh_chart_scan1:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov word [sh_chart_cnt2], 0
    xor cx, cx
.scan:
    mov ax, [sh_chart_cnt2]
    cmp ax, CH_MAXBARS
    jae .scandone
    cmp cx, [sh_ncells]
    jae .scandone
    mov ax, cx
    mov bx, SH_C_SZ
    mul bx
    mov si, ax
    mov es, [sh_cellseg]
    mov ax, [es:si]
    call sh_unpackrow                  ; ax=row, bx=sheet
    cmp bx, [sh_chart_sheet]
    jne .next
    mov dx, [es:si+2]                  ; col
    cmp dx, [sh_scan_col]
    jne .next
    cmp ax, [sh_chart_r1]              ; ...and inside the rows the selection
    jb .next                           ; covered (81.30). AX is still the row
    cmp ax, [sh_chart_r2]              ; sh_unpackrow left there
    ja .next
    ; A LABEL AND AN ERROR ARE NOT DATA POINTS, and this scan was the last
    ; reader that did not know it. chart.o88's SYLK reader skips them (82.4),
    ; its DIF reader skips type 1, and the sort scan skips both (81.19) - but
    ; the LIVE chart, the one inside Sheet, fed them straight through. A plain
    ; label leaves SH_C_VAL zero (sh_commit writes the value before the tag),
    ; so a column with a heading charted a 0 bar at the top of it, and a
    ; #DIV/0! charted the zero underneath the error.
    ;
    ; A formula is judged AFTER it runs, not from the stored tag: the tag may
    ; predate the fix that unbroke it, which is the same reason sh_getcell2
    ; raises from the freshly published one (81.20).
    cmp byte [es:si+SH_C_TYPE], SH_T_TEXT
    je .next
    cmp byte [es:si+SH_C_TYPE], SH_T_ERR
    jne .typeok
    test byte [es:si+4], 1             ; a stored error with no formula behind
    jz .next                           ; it has nothing to re-evaluate
.typeok:
    test byte [es:si+4], 1             ; HASFORMULA: chart its CURRENT value
    jz .plainval                       ; (sh_getcell2 evaluates transparently
    mov bx, ax                         ; and is never stale) rather than
                                        ; skipping it - a column of formulas
                                        ; used to chart as completely empty.
                                        ; AX still holds this record's row
                                        ; from sh_unpackrow above.
    mov ax, [sh_scan_col]
    push cx                            ; CX is this scan's own index and
    push si                            ; sh_getcell2 does not preserve it -
    call sh_getcell2                   ; see the matching note in
    pop si                             ; sh_docmd_sortcol.
    pop cx
    cmp byte [sh_curtype], SH_T_TEXT   ; ...and what it ANSWERED decides it
    je .next
    cmp byte [sh_curtype], SH_T_ERR
    je .next
    jmp .havevalue
.plainval:
    call sh_cellval_to_acc_si          ; the WHOLE double, not the truncation
                                        ; of it: the chart plots 43.6 as 43.6
                                        ; now (82.13), and ch_scale is what
                                        ; turns the series into the words the
                                        ; drawing runs on
.havevalue:                            ; the value is in sh_acc either way
    mov ax, [sh_chart_cnt2]
    mov dx, 8
    mul dx
    add ax, [sh_scan_off]
    mov di, ax
    mov es, [sh_stgseg]
    push cx                            ; CX IS THIS SCAN'S OWN RECORD INDEX -
    push si                            ; the copy below needs a counter, and
    mov si, sh_acc                     ; borrowing it would restart the walk
    mov cx, 4
.vcopy:
    mov ax, [si]
    mov [es:di], ax
    add si, 2
    add di, 2
    dec cx
    jnz .vcopy
    pop si
    pop cx
    inc word [sh_chart_cnt2]
.next:
    inc cx
    jmp .scan
.scandone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_chart - Data > Chart Column...: freeze the current sheet/column,
; scan its plain values via sh_chart_scan, then create-or-show the chart
; window and draw it.
;
; The window, once created, is NEVER destroyed by this app again - only
; shown/hidden. Traced directly against the kernel (kernel/instance.inc's
; app_close_win): clicking a non-primary window's own close box only calls
; wm_hide, not a real destroy - the record stays valid, just invisible,
; until the whole instance tears down (wm_destroy_seg cleans it up then,
; automatically). Re-creating a fresh window on every "Chart Column..."
; click would leak one of the system's MAX_WIN=12 window slots per click;
; treating a second click as "just show it again" does not.
; -----------------------------------------------------------------------------
sh_docmd_chart:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov ax, [sh_cursheet]
    mov [sh_chart_sheet], ax
    ; THE SELECTION IS WHAT A CHART IS OF, and Sheet is the half of this pair
    ; that HAS one. chart.o88 needed named ranges (82.15) because a file does
    ; not carry what was selected; here the answer was always sitting in
    ; sh_selrow/sh_selrow2 and this command was throwing it away and charting
    ; the whole column instead. Select A1:A4 and Chart Column... now charts
    ; four rows; select a name with Goto and it charts that name.
    ;
    ; A SINGLE CELL STILL MEANS THE WHOLE COLUMN - the same rule Sort states
    ; (81.19) and for the same reason: one cell is not a range, and the menu
    ; item still says Column.
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .chcol
    mov ax, bx                        ; the LEFTMOST column of the selection is
.chcol:                               ; series one, whichever way it was dragged
    mov [sh_chart_col], ax
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .chrows
    xchg ax, bx
.chrows:
    cmp ax, bx
    jne .chhave
    xor ax, ax                        ; one cell: the whole column, as before
    mov bx, SH_ROWS - 1
.chhave:
    mov [sh_chart_r1], ax
    mov [sh_chart_r2], bx
    call sh_chart_scan
    cmp word [sh_chartwin], 0
    jne .haswin
    mov si, sh_chart_tpl
    call OSAPI_WM_CREATE
    jc .out                            ; refused: silently give up, same
                                        ; scope limit sh_fdlg_open's own
                                        ; "already open, stay safe" has
    mov [sh_chartwin], bx
.haswin:
    mov bx, [sh_chartwin]
    call OSAPI_WM_SHOW
    call sh_chart_render
    mov si, [sh_chartwin]
    call sh_chart_paint
                                        ; sh_chart_render owns [sh_msg] now:
                                        ; setting "Charted." here overwrote its
                                        ; CHART.OVL refusal, so a chart that
                                        ; never drew still reported success
    mov si, [sh_ownwin]                ; repaint OUR OWN window too - this
    call sh_repaint                    ; only ever painted the chart window
                                        ; above, so the status bar's own
                                        ; "Charted." message was set but
                                        ; never actually shown until now
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_chart_render - rasterize the currently-staged values (sh_stgseg
; offset 0, count sh_chart_cnt) into the chart's own offscreen buffer
; (sh_chartseg), via apps/os88chart.inc's ch_bars_draw. DS is never
; touched - ch_bars_draw takes the array's segment as an explicit
; parameter (DX) and swaps ES internally instead of borrowing DS, so this
; caller's own bss stays reachable via the normal, unchanged DS throughout
; (see ch_bars_draw's own header comment for why that matters).
sh_chart_render:
    push ax
    push cx
    push dx
    push si
    push es
    push bx                             ; the title: "Column A", built here
    push di                             ; because only Sheet knows which column
    mov di, sh_chart_title              ; the series came from
    mov si, sh_s_coltitle
    call sh_strcpy_to_di
    mov ax, [sh_chart_col]
    call sh_colname
    mov si, sh_colbuf
    call sh_strcpy_to_di
    mov word [ch_title], sh_chart_title
    pop di
    pop bx
    mov cx, [sh_chart_cnt]
    mov es, [sh_chartseg]
    mov dx, [sh_stgseg]
    xor si, si
    CHMOD draw                          ; stage 3.0f: the gallery, which Data >
                                        ; Chart Gallery... now sets. Going
    mov word [sh_msg], sh_s_charted     ; through the dispatcher rather than
    jnc .drawn                          ; calling one drawing routine is what
    mov word [sh_msg], sh_s_noovl       ; keeps this app and CHART.O88 from
.drawn:                                 ; drifting into drawing the same data
    pop es                              ; drifting into drawing the same data
    pop si
    pop dx
    pop cx
    pop ax
    ret

; sh_chart_paint - the chart window's own W_PAINT callback (SI=window);
; the two bands the picture does not cover, then one OSAPI_GFX_BLIT4 of the
; already-rasterized buffer
sh_chart_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push bp
    push es
    cmp byte [sh_chartdirty], 0         ; sh_repaint's hook leaves the byte SET
    je .clean                           ; while this window is obscured, so a
    call sh_chart_scan                  ; raise is the first paint that can
    call sh_chart_render                ; show the change - Chart Gallery's
    mov byte [sh_chartdirty], 0         ; type, or a cell edited meanwhile -
.clean:                                 ; and it re-reads before it blits
    mov bx, si
    call OSAPI_WM_CONTENT               ; ax=content x, dx=content y
    mov [ch_bx1], ax                    ; borrow this scratch - safe here,
    mov [ch_by1], dx                    ; ch_bars_draw already finished by
                                         ; the time sh_chart_paint ever runs
    call ch_margin                      ; THE INTERIOR THE PICTURE DOES NOT
                                         ; COVER (SPEC.md 82.1.1, issue #142):
                                         ; the window is a little larger than
                                         ; the CH_W x CH_H canvas, and the two
                                         ; bands that leaves were never written
                                         ; by anything - so a move redrew the
                                         ; frame, re-blitted the picture, and
                                         ; left whatever had been on the glass
                                         ; in between. BX is still the window
                                         ; and AX/DX still WM_CONTENT's answer,
                                         ; which is exactly what it wants.
                                         ; SHARED with CHART.O88's ct_paint,
                                         ; because the two windows have the
                                         ; same margin for the same reason -
                                         ; and resident under CH_OVERLAY for
                                         ; this call (os88chart.inc)
    mov es, [sh_chartseg]
    mov si, CH_PXOFF
    mov bp, CH_STRIDE
    mov ax, [ch_bx1]
    mov bx, [ch_by1]
    mov cx, CH_W
    mov dx, CH_H
    call OSAPI_GFX_BLIT4
    pop es
    pop bp
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

sh_chart_tpl:
    dw 0, 0, SH_CHARTWIN_W, SH_CHARTWIN_H
    dw sh_s_chart_title, sh_chart_paint, 0, 0
sh_s_chart_title: db 'Chart', 0
sh_s_charted:      db 'Charted.', 0
sh_s_coltitle:     db 'Column ', 0
sh_s_onesheet:     db 'Saved - THIS SHEET ONLY; use .BIF to keep them all.', 0
sh_s_sheetnm:      db 'Sheet', 0

; sh_docmd_chartexport - Data > Export Chart as BMP...: a no-op
; informational message if there's nothing charted yet (same "still runs,
; OK is just a no-op" idiom used throughout this file), else the standard
; Save dialog, writing the chart's own offscreen buffer via
; apps/os88chart.inc's ch_bmp_write once a name is chosen.
sh_docmd_chartexport:
    push ax
    push bx
    push si
    push di
    cmp word [sh_chartwin], 0
    je .nothing
    cmp word [sh_chart_cnt], 0
    je .nothing
    mov al, FDLG_SAVE
    mov bx, [sh_ownwin]
    mov di, sh_chartexp_ondlg
    mov si, sh_s_chartbmp
    call OSAPI_FILE_DLG
    jmp .out
.nothing:
    mov word [sh_msg], sh_s_nochart
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret
; =============================================================================
; THE MACRO RECORDER (SPEC.md 81.74)
;
; 81.68 was built for this and says so in its own title: a macro's references
; are written in R1C1 "the way the recorder writes them". This is the
; recorder, and it emits exactly the language 81.63 already runs - a recording
; is an ordinary macro sheet afterwards, readable and editable, not a second
; representation.
;
; WHAT IS RECORDABLE is what those 20 functions can say: the selection moving
; (SELECT), a cell entered (FORMULA), and the five menu commands the language
; already has (COPY, CUT, PASTE, CLEAR, CALCULATE.NOW). Anything else is
; simply not recorded - it is not refused, and the recording stays valid,
; which is the same bargain Excel's own recorder makes with the commands its
; language cannot express.
;
; THE EMITTER GOES THROUGH sh_commit, which is itself a recording site, so
; sh_rec_busy is the guard that stops a recorded FORMULA recording itself.
; It is a refusal and not a queue: nothing a recorded write does is worth
; recording.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_recmark - derive both relabelled Macro items from the state, the
; relabel-by-repointing 81.70's Freeze Panes and the Options toggles use
; -----------------------------------------------------------------------------
sh_recmark:
    push ax
    mov ax, sh_it_recon
    cmp byte [sh_rec_on], 0
    je .set0
    mov ax, sh_it_recoff
.set0:
    mov [sh_i_macro + SH_MAI_RECORD * 2], ax
    mov ax, sh_it_relrec               ; the item names what choosing it WOULD
    cmp byte [sh_rec_rel], 0           ; do, which is Excel's own wording and
    je .set1                           ; the opposite of the state it is in
    mov ax, sh_it_absrec
.set1:
    mov [sh_i_macro + SH_MAI_REL * 2], ax
    mov ax, sh_it_startdis             ; 81.107: "You cannot choose Macro
    cmp byte [sh_rec_on], 0            ; Start Recorder until you set the
    jne .set2                          ; recorder range" - and not while one
    cmp byte [sh_rec_set], 0           ; is running, when Stop Recorder is
    je .set2                           ; the item that means something
    mov ax, sh_it_startrec
.set2:
    mov [sh_i_macro + SH_MAI_START * 2], ax
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_setrec - Macro ▸ Set Recorder. "Defines the selection on your macro
; sheet as the recorder range... Recording starts in the upper-left corner of
; the range and proceeds down the left column."
;
; So only the corner is kept, and the SHEET with it: a recording made while
; the user works on sheet 1 has to land on the macro sheet they pointed at.
; -----------------------------------------------------------------------------
sh_docmd_setrec:
    push ax
    mov ax, [sh_selcol]
    mov [sh_rec_col], ax
    mov ax, [sh_selrow]
    mov [sh_rec_row], ax
    mov al, [sh_cursheet]
    mov [sh_rec_sheet], al
    mov byte [sh_rec_set], 1
    mov byte [sh_rec_ret], 0           ; 81.107: a NEW range has no RETURN of
    call sh_recmark                    ; ours at its end; Start is live now
    mov word [sh_msg], sh_s_rec_set
    call sh_recrepaint
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_record - Macro ▸ Record... / Stop Recorder.
;
; Stopping writes a RETURN() of its own, so the recording is a macro that ends
; rather than one that runs on into whatever was below it - which is what
; 81.63's engine would otherwise do.
; -----------------------------------------------------------------------------
sh_docmd_record:
    push ax
    push si
    cmp byte [sh_rec_on], 0
    jne .stop
    cmp byte [sh_rec_set], 0           ; Excel opens a macro sheet here; this
    jne .start                         ; has four sheets and no idea which one
    mov word [sh_msg], sh_s_rec_norange ; the user meant, so it asks rather
    call sh_recrepaint                  ; than guessing
    jmp .out
.start:
    mov al, SH_ID_RECNAME              ; ask what to call it first; the start
    call sh_idlg_open_r                  ; is that dialog's own OK
    jmp .out
.stop:
    mov si, sh_s_rec_return
    call sh_rec_emit
    mov byte [sh_rec_on], 0
    mov byte [sh_rec_ret], 1           ; 81.107: the row above the recorder
    mov word [sh_msg], sh_s_rec_off    ; cell is OUR RETURN()
    call sh_recmark
    call sh_recrepaint
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_startrec - Macro ▸ Start Recorder (81.107). "Records subsequent
; actions and commands until you choose Macro Stop Recorder ... You can use
; Macro Start Recorder and Macro Stop Recorder to temporarily pause while
; recording a macro. You can also use them to add to an existing macro."
;
; So it CONTINUES the macro rather than beginning another: "If the end of the
; recorder range contains a RETURN function, RETURN is overwritten." The one
; RETURN this knows is at that end is its own - Stop Recorder writes it and
; sets [sh_rec_ret] - so that is the one stepped back over. No name is asked
; for (Record... names a NEW macro; this adds to one). The item is greyed
; with no range or with a recording live (sh_recmark), and a macro's fire of
; it is refused the same way here.
; -----------------------------------------------------------------------------
sh_docmd_startrec:
    cmp byte [sh_rec_on], 0
    jne .out
    cmp byte [sh_rec_set], 0
    je .out
    cmp byte [sh_rec_ret], 0
    je .go
    mov byte [sh_rec_ret], 0
    cmp word [sh_rec_row], 0
    je .go
    dec word [sh_rec_row]              ; back over our RETURN(): the next
.go:                                   ; write lands on it
    call sh_rec_start
    call sh_recrepaint
.out:
    ret

; sh_rec_start - what SH_ID_RECNAME's OK does
sh_rec_start:
    mov byte [sh_rec_on], 1
    mov word [sh_rec_lastc], 0xFFFF    ; no selection recorded yet, so the
    mov word [sh_rec_lastr], 0xFFFF    ; first SELECT is always written
    mov word [sh_msg], sh_s_rec_on
    call sh_recmark
    ret

sh_recrepaint:
    push si
    mov si, [sh_ownwin]
    call sh_repaint
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_rec_emit - SI = a macro formula's text, WITHOUT the leading '='. Puts it
; in the recorder cell and steps down a row.
;
; The write is driven the way sh_sort_permcol drives sh_commit - the SELECTION
; is its argument - so the real selection AND the current sheet are banked
; across it and put back. The sheet matters: the recording lands on whichever
; sheet Set Recorder was pointed at, while the user goes on working on theirs.
; -----------------------------------------------------------------------------
sh_rec_emit:
    cmp byte [sh_rec_on], 0
    je .ret
    cmp byte [sh_rec_busy], 0
    jne .ret                           ; a recorded write is not itself news
    cmp byte [sh_editing], 0           ; the user's own edit is committed
    je .noedit                         ; first: the buffer is about to hold
    call sh_commit                     ; this line, and the entry is then
.noedit:                               ; recorded ahead of it, in order
    push ax
    push bx
    push cx
    push si
    push di
    mov byte [sh_rec_busy], 1
    mov byte [sh_editbuf], '='
    mov di, sh_editbuf + 1
    mov cx, SH_EDITMAX - 1
.copy:
    mov al, [si]
    or al, al
    jz .copied
    jcxz .copied
    mov [di], al
    inc si
    inc di
    dec cx
    jmp short .copy
.copied:
    mov byte [di], 0
    mov si, sh_editbuf
    xor cx, cx
.len:
    cmp byte [si], 0
    je .have
    inc si
    inc cx
    jmp short .len
.have:
    mov [sh_editlen], cl
    mov ax, [sh_selcol]                ; bank the user's own place...
    mov [sh_rec_svc], ax
    mov ax, [sh_selrow]
    mov [sh_rec_svr], ax
    mov ax, [sh_selcol2]
    mov [sh_rec_svc2], ax
    mov ax, [sh_selrow2]
    mov [sh_rec_svr2], ax
    mov al, [sh_cursheet]
    mov [sh_rec_svsh], al
    mov al, [sh_rec_sheet]             ; ...go to the recorder's...
    mov [sh_cursheet], al
    mov ax, [sh_rec_col]
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov ax, [sh_rec_row]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
    mov byte [sh_editing], 1
    mov al, [sh_ud_busy]
    mov ah, [sh_commitdirty]
    push ax
    mov byte [sh_ud_busy], 1           ; a recorded line is not an Undo step:
    call sh_commit                     ; no snapshot of its own over the user's
    pop bx
    mov [sh_ud_busy], bl
    mov al, [sh_rec_svsh]              ; ...and back
    mov [sh_cursheet], al
    cmp al, [sh_rec_sheet]             ; recorded onto ANOTHER sheet: nothing
    je .shown                          ; on screen changed, so the next arrow
    mov [sh_commitdirty], bh           ; key keeps sh_selpaint's cheap path
.shown:
    mov ax, [sh_rec_svc]
    mov [sh_selcol], ax
    mov ax, [sh_rec_svr]
    mov [sh_selrow], ax
    mov ax, [sh_rec_svc2]
    mov [sh_selcol2], ax
    mov ax, [sh_rec_svr2]
    mov [sh_selrow2], ax
    inc word [sh_rec_row]
    mov byte [sh_rec_busy], 0
    pop di
    pop si
    pop cx
    pop bx
    pop ax
.ret:
    ret

; -----------------------------------------------------------------------------
; sh_rec_sel - the selection moved: record it. ABSOLUTE by default, which is
; Excel's own initial state ("Initially, cell references in macros are
; recorded as absolute references"), RELATIVE to the cell the last recorded
; SELECT left the macro standing on when Relative Record is chosen.
; -----------------------------------------------------------------------------
sh_rec_sel:
    cmp byte [sh_rec_on], 0
    je .ret
    cmp byte [sh_rec_busy], 0
    jne .ret
    push ax
    push bx
    push si                            ; sh_select's own contract is that SI
    push di                            ; is the window, and this is called
    mov ax, [sh_selcol]                ; from inside it
    cmp ax, [sh_rec_lastc]
    jne .go
    mov ax, [sh_selrow]
    cmp ax, [sh_rec_lastr]
    je .done                           ; it did not actually move
.go:
    mov di, sh_recbuf
    mov si, sh_s_rec_select
    call sh_reccpy
    cmp byte [sh_rec_rel], 0
    je .abs
    mov ax, [sh_selrow]                ; R[dr]C[dc], the offsets 81.68's own
    sub ax, [sh_rec_lastr]             ; converter already speaks
    mov bx, [sh_selcol]
    sub bx, [sh_rec_lastc]
    cmp word [sh_rec_lastr], 0xFFFF    ; ...unless nothing is recorded yet, in
    je .abs                            ; which case there is no origin to be
    call sh_rec_rc                     ; relative TO
    jmp short .emit
.abs:
    mov ax, [sh_selrow]
    inc ax
    mov bx, [sh_selcol]
    inc bx
    call sh_rec_rcabs
.emit:
    mov si, sh_s_rec_qp
    call sh_reccpy
    mov byte [di], 0
    mov si, sh_recbuf
    call sh_rec_emit
    mov ax, [sh_selcol]
    mov [sh_rec_lastc], ax
    mov ax, [sh_selrow]
    mov [sh_rec_lastr], ax
.done:
    pop di
    pop si
    pop bx
    pop ax
.ret:
    ret

; sh_reccpy - SI -> DI, NUL not copied, DI left past the last byte
sh_reccpy:
    push ax
.l:
    mov al, [si]
    or al, al
    jz .d
    mov [di], al
    inc si
    inc di
    jmp short .l
.d:
    pop ax
    ret

; sh_rec_rcabs - AX = a 1-based row, BX = a 1-based column -> "R<n>C<n>" at DI
sh_rec_rcabs:
    push ax
    mov byte [di], 'R'
    inc di
    call sh_itoa
    push si
    mov si, sh_numbuf
    call sh_reccpy
    pop si
    mov byte [di], 'C'
    inc di
    mov ax, bx
    call sh_itoa
    push si
    mov si, sh_numbuf
    call sh_reccpy
    pop si
    pop ax
    ret

; sh_rec_rc - AX = a row DELTA, BX = a column delta -> "R[d]C[d]" at DI, with
; a zero offset written as the bare letter, which is what 81.68's converter
; and Excel both mean by "this row"
sh_rec_rc:
    push ax
    mov byte [di], 'R'
    inc di
    call sh_rec_off
    mov byte [di], 'C'
    inc di
    mov ax, bx
    call sh_rec_off
    pop ax
    ret

; sh_rec_off - AX = an offset -> "[n]" at DI, or nothing at all when it is 0
sh_rec_off:
    or ax, ax
    jz .out
    push si
    mov byte [di], '['
    inc di
    or ax, ax
    jns .pos
    mov byte [di], '-'
    inc di
    neg ax
.pos:
    call sh_itoa
    mov si, sh_numbuf
    call sh_reccpy
    mov byte [di], ']'
    inc di
    pop si
.out:
    ret

; -----------------------------------------------------------------------------
; sh_rec_stage / sh_rec_flush - a TYPED entry, recorded as FORMULA("...").
;
; TWO HALVES because the emit writes THROUGH sh_commit, and this is called
; from inside one: staging copies sh_editbuf out before the store reads it,
; and the flush at sh_commit's own exit does the writing once the outer call
; has finished with the buffer. sh_rec_busy then stops the inner commit
; staging anything of its own.
;
; A double quote in the typed text is DOUBLED, which is how this app's own
; parser reads a quote inside a string (81.18's `"a""b"`), so a label with one
; in it records as a macro that re-enters the same label.
; -----------------------------------------------------------------------------
sh_rec_stage:
    cmp byte [sh_rec_on], 0
    je .ret
    cmp byte [sh_rec_busy], 0
    jne .ret
    cmp byte [sh_ud_busy], 0           ; a Paste, Fill or Sort write is part of
    jne .ret                           ; a command, not an entry someone typed
    push ax
    push cx
    push si
    push di
    mov si, sh_editbuf
    mov di, sh_recbuf
    mov cx, SH_EDITMAX - 14            ; room for FORMULA("") and the NUL
    push si
    mov si, sh_s_rec_formula
    call sh_reccpy
    pop si
.c:
    mov al, [si]
    or al, al
    jz .done
    jcxz .done
    cmp al, '"'
    jne .one
    mov [di], al
    inc di
    dec cx
    jcxz .done
.one:
    mov [di], al
    inc di
    inc si
    dec cx
    jmp short .c
.done:
    push si
    mov si, sh_s_rec_qp
    call sh_reccpy
    pop si
    mov byte [di], 0
    mov byte [sh_rec_pend], 1
    pop di
    pop si
    pop cx
    pop ax
.ret:
    ret

sh_rec_flush:
    cmp byte [sh_rec_pend], 0
    je .ret
    push si
    mov byte [sh_rec_pend], 0
    mov si, sh_recbuf
    call sh_rec_emit
    pop si
.ret:
    ret

; -----------------------------------------------------------------------------
; sh_rec_cmd - SI = a bare command's text (COPY(), PASTE()...). One call site
; per Edit menu command the language has a function for.
; -----------------------------------------------------------------------------
sh_rec_cmd:
    call sh_rec_emit
    ret

sh_s_rec_formula: db 'FORMULA("', 0
sh_s_rec_select:  db 'SELECT("', 0
sh_s_rec_qp:      db '")', 0
sh_s_rec_return:  db 'RETURN()', 0
sh_s_rec_copy:    db 'COPY()', 0
sh_s_rec_cut:     db 'CUT()', 0
sh_s_rec_paste:   db 'PASTE()', 0
sh_s_rec_clear:   db 'CLEAR()', 0
sh_s_rec_calc:    db 'CALCULATE.NOW()', 0
sh_s_rec_set:     db 'Recorder set.', 0
sh_s_rec_on:      db 'Recording.', 0
sh_s_rec_off:     db 'Recording stopped.', 0
sh_s_rec_norange: db 'Set Recorder first.', 0



; -----------------------------------------------------------------------------
; sh_docmd_setname - Data > Set Database.../Set Criteria... (SPEC.md 81.69).
; in: SI = the reserved name ('DATABASE' or 'CRITERIA'). Binds it to the
; CURRENT SELECTION through the identical sh_name_def every defined name
; already goes through (Formula > Define Name..., sh_idlg_apply's own
; .defname). NO DIALOG: real Excel's own Set Database/Set Criteria take
; effect on the selection immediately, and §81.65's database functions
; already resolve a bare NAME as a reference wherever one is expected, so
; DSUM(Database,"Amount",Criteria) works the moment both are bound - this
; command's entire job is sparing a user from retyping the same range on
; every call, not a second engine.
; -----------------------------------------------------------------------------
sh_docmd_setname:
    push ax
    push bx
    push cx
    push dx
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    mov cx, [sh_selcol2]
    mov dx, [sh_selrow2]
    call sh_name_def
    mov word [sh_msg], sh_s_id_nofit
    jc .out
    mov word [sh_msg], sh_s_id_named
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ser_setstep - in: SI = the typed step. out: CF=1 and [sh_ser_step] set;
; CF=0 the text is not a number at all. RESIDENT because sh_idlg_apply is.
;
; fp_atof, not sh_pnum_at: a growth factor of 1.5 and a linear step of 0.25
; are both ordinary, and sh_pnum_at answers integers only.
; -----------------------------------------------------------------------------
sh_ser_setstep:
    push ax
    push si
    push di
    call fp_atof                       ; CF=1 from fp_atof means NO number
    jc .bad
    mov di, sh_ser_step
    call fp_pack_a
    stc
    jmp .out
.bad:
    clc
.out:
    pop di
    pop si
    pop ax
    ret

sh_s_dbname:   db 'DATABASE', 0
sh_s_critname: db 'CRITERIA', 0

; =============================================================================
; DATA ▸ FIND / EXTRACT / DELETE / FORM (SPEC.md 81.71)
;
; §81.65 built the criteria engine and §81.69 the two names it reads its
; rectangles from; these four commands are that engine driven from the MENU
; instead of from a formula, and they add no matching logic of their own -
; every one of them is `sh_dbrowmatch` in a loop.
;
; THE WHOLE FAMILY RUNS IN CHART.OVL, behind one new verb (SHM_DBCMD), for
; the reason §81.65 put the engine there: sh_dbrowmatch, sh_dbrowok,
; sh_dbtest and sh_dbcmp are all .modc and none of them is exported, so a
; resident command would have to duplicate the matcher rather than call it.
; What stays resident is what a menu needs: the dispatch, the alert, the
; item's own relabel, and this door.
;
; sh_dbc_kind picks the command and sh_dbc_res carries its answer back,
; because CF on that door already means "is there a module at all".
; =============================================================================
SH_DBC_FIND    equ 0                 ; the next matching record, forwards
SH_DBC_EXTRACT equ 1                 ; ...copied into the extract range
SH_DBC_DELETE  equ 2                 ; ...or removed from the database
SH_DBC_FORM    equ 3                 ; ...or shown one record at a time

SH_DBR_OK      equ 0                 ; sh_dbc_res: what the command decided
SH_DBR_NODB    equ 1                 ; no DATABASE name is bound
SH_DBR_NOCRIT  equ 2                 ; ...or no CRITERIA name
SH_DBR_NOMATCH equ 3                 ; nothing in the database matches
SH_DBR_LAST    equ 4                 ; Find: already on the last match
SH_DBR_NOROOM  equ 5                 ; Extract: the range could not hold them
SH_DBR_NOFIELD equ 6                 ; Extract: the range names no real field
SH_DBR_BUSY    equ 7                 ; a database function is already running

; Excel clears "all cells below the field names to the bottom of the
; worksheet" when the extract range is its header row alone. This clears the
; rows it wrote plus this many past them, which is the same thing for any
; sheet this machine holds and is bounded work rather than a walk to row 16383
SH_DBC_EXTAIL  equ 64

; -----------------------------------------------------------------------------
; sh_docmd_dbrun - in: AL = one of SH_DBC_*. Runs it in the module and turns
; [sh_dbc_res] into a status line. out: CF=1 if the command actually did
; something (the caller repaints); every register preserved.
; -----------------------------------------------------------------------------
sh_docmd_dbrun:
    push ax
    push bx
    push bp
    mov [sh_dbc_kind], al
    mov byte [sh_dbc_res], SH_DBR_OK
    mov bp, SHM_DBCMD
    call ch_ovcall
    jc .nomod
    mov bl, [sh_dbc_res]
    xor bh, bh
    shl bx, 1
    mov ax, [sh_dbc_msg + bx]
    mov [sh_msg], ax
    cmp byte [sh_dbc_res], SH_DBR_OK   ; only a clean run changed anything
    je .did
    clc
    jmp .out
.did:
    stc
    jmp .out
.nomod:
    mov word [sh_msg], sh_s_noovl
    clc
.out:
    pop bp
    pop bx
    pop ax
    ret

sh_dbc_msg:
    dw sh_s_db_done, sh_s_db_nodb, sh_s_db_nocrit, sh_s_db_nomatch
    dw sh_s_db_last, sh_s_db_noroom, sh_s_db_nofield, sh_s_db_busy
sh_s_db_done:   db 'Ready', 0
sh_s_db_nodb:   db 'Set Database first.', 0
sh_s_db_nocrit: db 'Set Criteria first.', 0
sh_s_db_nomatch: db 'No records match the criteria.', 0
sh_s_db_last:   db 'Last matching record.', 0
sh_s_db_noroom: db 'The extract range is too small.', 0
sh_s_db_nofield: db 'The extract range names no field.', 0
sh_s_db_busy:   db 'A database function is running.', 0
sh_s_db_delq:   db 'Delete every matching record?', 0

; -----------------------------------------------------------------------------
; sh_docmd_dfind - Data ▸ Find, and Data ▸ Exit Find, which are the SAME item
; relabelled (Excel's own: "Exit Find appears on the Data menu only when you
; are in Data Find"). Choosing Find again selects the NEXT matching record,
; which is how Excel's find-and-replace-one-at-a-time works.
; -----------------------------------------------------------------------------
sh_docmd_dfind:
    push ax
    cmp byte [sh_dfindmode], 0
    je .start
    call sh_dfind_exit                   ; Exit Find
    jmp .repaint
.start:
    mov al, SH_DBC_FIND
    call sh_docmd_dbrun
    jnc .out                           ; refused: the message is already up
    mov byte [sh_dfindmode], 1          ; ...and the item becomes Exit Find
    call sh_dfind_mark
.repaint:
    push si
    mov si, [sh_ownwin]
    call sh_repaint
    pop si
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dfind_exit - leave find mode. Excel leaves the record it last found
; SELECTED, which is what makes find-then-edit-then-find-again work, so this
; touches nothing but the mode and the item's label.
; -----------------------------------------------------------------------------
sh_dfind_exit:
    mov byte [sh_dfindmode], 0
    ; fall through

; sh_dfind_mark - derive the Data menu's SECOND item from [sh_dfindmode], the
; relabel-by-repointing the Options toggles and Freeze Panes (81.70) use
sh_dfind_mark:
    push ax
    mov ax, sh_it_dfind
    cmp byte [sh_dfindmode], 0
    je .set
    mov ax, sh_it_exitfnd
.set:
    mov [sh_i_data + 2], ax            ; item 1: Form... is index 0 now
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_docmd_dbdelete - Data ▸ Delete. The Reference Guide is explicit that
; this one WARNS first ("A message warns that records will be permanently
; deleted from the database") and that Edit ▸ Undo cannot reverse it, so the
; alert is the feature and not a courtesy.
; -----------------------------------------------------------------------------
sh_docmd_dbdelete:
    push ax
    push bx
    push si
    push di
    mov al, OS88UI_AYESNO
    mov bx, [sh_ownwin]
    mov si, sh_s_db_delq
    mov di, sh_ondbdelete
    call os88ui_ask
    pop di
    pop si
    pop bx
    pop ax
    ret

; os88ui_ask's completion (SPEC.md 75.3): AL = the button index, or
; OS88UI_ACANCEL when it was dismissed. SI is OUR window, the gfx lock is
; held and the alert is already gone.
sh_ondbdelete:
    push ax
    cmp al, 0                          ; Yes, and nothing else - a dismissed
    jne .out                           ; alert must not delete records
    mov al, SH_DBC_DELETE
    call sh_docmd_dbrun
    jnc .out
    call sh_recalc_all                 ; records moved: every formula that
    call sh_repaint                    ; named one has to be re-folded
.out:
    call sh_drawstatus
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_chartexp_ondlg - the Export Chart dialog's completion proc (SPEC.md
; 38.6, same shape as sh_ondlg but writing the chart buffer, not the sheet,
; and never reading back - Export is always a Save). In: AL=mode
; (unused), SI=our window ptr, DI=chosen name (ES=KERNEL_SEG); UI task,
; gfx lock HELD, dialog already destroyed - we owe the repaint.
; -----------------------------------------------------------------------------
sh_chartexp_ondlg:
    push ax
    push bx
    push cx
    push si
    push di
    mov si, di
    mov di, sh_chart_name
    mov cx, SH_FNAME_MAX               ; the count lives in CX - the loop
.copy:                               ; body writes AL, so AX cannot hold it
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .copied
    inc si
    inc di
    dec cx
    jnz .copy
    mov byte [di], 0
.copied:
    mov es, [sh_chartseg]
    mov bx, [sh_stgseg]
    mov si, sh_chart_name
    CHMOD bmp_write                     ; a module that will not load returns
                                        ; CF=1 too, so the export's own error
    jnc .ok                             ; path already covers it
    mov word [sh_msg], sh_s_experr
    jmp .draw
.ok:
    mov word [sh_msg], sh_s_exported
.draw:
    mov si, [sh_ownwin]
    call sh_repaint
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

sh_s_chartbmp: db 'CHART.BMP', 0
sh_s_nochart:  db 'No chart to export.', 0
sh_s_experr:   db 'Chart export failed.', 0
sh_s_noovl:    db 'CHART.OVL not found.', 0
sh_s_exported: db 'Chart exported.', 0

; -----------------------------------------------------------------------------
; sh_sort_vof / sh_sort_ldds / sh_sort_cmp - the three places the sort's value
; array is touched, so its EIGHT-BYTE stride lives in exactly one of them.
; It was a word per entry and the multiply was written inline six times; a
; widening done that way is how a missed site returns a plausible wrong number
; with no crash (the risk this file's own record-layout comment names).
;
; sh_sort_vof - in: BX = entry index, out: DI = its offset in sh_stgseg
; -----------------------------------------------------------------------------
section SH_MODSEC                      ; 81.71.6: Data > Sort's worker, CHART.OVL
sh_sort_vof:
    push ax
    push cx
    mov ax, bx
    mov cx, 8
    mul cx
    add ax, SH_SORT_VALS_OFF
    mov di, ax
    pop cx
    pop ax
    ret

; sh_sort_ldds - copy 8 bytes from ES:DI (the staging array) to DS:SI
sh_sort_ldds:
    push ax
    mov ax, [es:di]
    mov [si], ax
    mov ax, [es:di+2]
    mov [si+2], ax
    mov ax, [es:di+4]
    mov [si+4], ax
    mov ax, [es:di+6]
    mov [si+6], ax
    pop ax
    ret

; sh_sort_cmp - compare sh_sort_cmpv against sh_sort_keyval, leaving the flags
; a signed JL/JE/JG can read. ES is preserved because the caller is mid-walk
; through the staging segment and fp_unpack_* work in DS.
sh_sort_cmp:
    push ax
    push si
    mov al, [sh_sort_cmpc]            ; the CLASS first (81.61): number, text,
    cmp al, [sh_sort_keyc]            ; logical, error. Small and unsigned, so
    jne .out                          ; the signed flags read the same
    cmp al, 1
    je .text
    cmp al, 3
    je .out                           ; two errors: equal (ZF from the cmp)
    mov si, sh_sort_cmpv
    SHOUT fp_unpack_a
    mov si, sh_sort_keyval
    SHOUT fp_unpack_b
    SHOUT fp_cmpab                     ; AX = -1/0/1 and the flags to match
.out:
    pop si
    pop ax
    ret
.text:
    push bx                           ; two labels, in any case: ES is the
    push di                           ; staging segment, where the slots are
    mov si, [sh_sort_cmpv]
    mov di, [sh_sort_keyval]
.tl:
    mov al, [es:si]
    mov bl, [es:di]
    cmp al, 'a'
    jb .t1
    cmp al, 'z'
    ja .t1
    sub al, 32
.t1:
    cmp bl, 'a'
    jb .t2
    cmp bl, 'z'
    ja .t2
    sub bl, 32
.t2:
    xor ah, ah                        ; as words, so a byte past 7FH still
    xor bh, bh                        ; orders by the signed flags
    cmp ax, bx
    jne .td
    or al, al
    jz .td                            ; both ended: equal, ZF set
    inc si
    inc di
    jmp short .tl
.td:
    pop di
    pop bx
    jmp short .out

; sh_sort_tslot - SI = a string in the text arena -> copied into the next SNAP
; slot, [sh_sort_ctoff] = where. CF=1 when the slots are all used (81.61)
sh_sort_tslot:
    push ax
    push cx
    push di
    push es
    mov ax, [sh_sort_tcnt]
    cmp ax, SH_SORT_SNAPCAP
    jae .full
    mov cx, 64
    mul cx
    add ax, SH_SORT_SNAP_OFF
    mov [sh_sort_ctoff], ax
    mov di, ax
    mov cx, 63
.c:
    mov es, [sh_txtseg]
    mov al, [es:si]
    mov es, [sh_stgseg]
    mov [es:di], al
    or al, al
    jz .done
    inc si
    inc di
    loop .c
    mov byte [es:di], 0
.done:
    inc word [sh_sort_tcnt]
    clc
    jmp short .out
.full:
    stc
.out:
    pop es
    pop di
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sort_flushblank - the row in [sh_sort_currow] is finished. If it never
; showed a cell in the KEY column it takes part as a BLANK (81.80), class 4,
; which sorts last whichever way the sort runs. Preserves everything.
;
; A row is only in play at all if it has a cell somewhere in the block, so
; this stages nothing for the empty rows between two entries - and for a
; ONE-COLUMN sort it stages nothing ever, every cell in the block being a key
; cell. That is what keeps "sort a single cell" - which means the whole
; column, rows 0..SH_ROWS-1 - from trying to collect sixteen thousand blanks.
; -----------------------------------------------------------------------------
sh_sort_flushblank:
    push ax
    push bx
    push dx
    push di
    push es
    cmp word [sh_sort_currow], 0xFFFF  ; nothing being grouped yet
    je .out
    cmp byte [sh_sort_haskey], 0
    jne .out                           ; it had a key cell and staged already
    mov bx, [sh_sort_cnt]
    cmp bx, SH_SORT_CAP
    jae .out                           ; full: it sits the sort out, the same
    mov es, [sh_stgseg]                ; "clip, don't crash" policy as above
    mov ax, [sh_sort_currow]
    mov di, bx
    shl di, 1
    mov [es:di], ax                    ; rows[cnt] = the row
    push bx
    call sh_sort_vof                   ; DI = &values[cnt] - zeroed, because
    xor ax, ax                         ; a blank compares by CLASS alone and
    mov [es:di], ax                    ; never by these bytes
    mov [es:di+2], ax
    mov [es:di+4], ax
    mov [es:di+6], ax
    pop bx
    mov di, bx
    shl di, 1
    add di, SH_SORT_ORIG_OFF
    mov [es:di], bx                    ; origidx[cnt] = cnt
    mov di, bx
    add di, SH_SORT_ISF_OFF
    mov byte [es:di], 0                ; not a formula
    mov di, bx
    add di, SH_SORT_CLS_OFF
    mov byte [es:di], 4                ; ...and the class that sorts LAST
    inc word [sh_sort_cnt]
.out:
    pop es
    pop di
    pop dx
    pop bx
    pop ax
    ret

; sh_sort_class - after sh_getcell2 on a FORMULA key cell: [sh_sort_ccls] =
; its result's class, a text result's characters (sh_sacc) staged in a slot.
; CF=1 when a text result finds no slot
sh_sort_class:
    push ax
    push cx
    push si
    push di
    push es
    mov byte [sh_sort_ccls], 0
    mov al, [sh_curtype]
    cmp al, SH_T_BOOL
    jne .nb
    mov byte [sh_sort_ccls], 2
.nb:
    cmp al, SH_T_ERR
    jne .ne
    mov byte [sh_sort_ccls], 3
.ne:
    cmp al, SH_T_TEXT
    je .txt
    clc                               ; AFTER the compare, which sets CF
    jmp short .out
.txt:
    mov ax, [sh_sort_tcnt]
    cmp ax, SH_SORT_SNAPCAP
    jae .full
    mov cx, 64
    mul cx
    add ax, SH_SORT_SNAP_OFF
    mov [sh_sort_ctoff], ax
    mov di, ax
    mov es, [sh_stgseg]
    mov si, sh_sacc
    mov cx, 63
.c:
    mov al, [si]
    mov [es:di], al
    or al, al
    jz .done
    inc si
    inc di
    loop .c
    mov byte [es:di], 0
.done:
    inc word [sh_sort_tcnt]
    mov byte [sh_sort_ccls], 1
    clc
    jmp short .out
.full:
    stc
.out:
    pop es
    pop di
    pop si
    pop cx
    pop ax
    ret

sh_docmd_sortcol:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    ; Sort the ROWS THE SELECTION COVERS, not the whole column. A single cell
    ; still means the whole column, which is what this always did and what the
    ; Data menu's one-item Sort implies.
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .sortrows
    xchg ax, bx
.sortrows:
    cmp ax, bx
    jne .haverows
    xor ax, ax
    mov bx, SH_ROWS - 1
.haverows:
    mov [sh_sort_r1], ax
    mov [sh_sort_r2], bx
    ; THE BLOCK'S COLUMNS, and they are needed HERE now rather than only in
    ; the carry below (81.80). A row whose KEY cell is empty still takes part
    ; if it has a cell anywhere else in the block - that is the row Excel
    ; sorts last - so the scan has to see the whole block, not the key column.
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .scols
    xchg ax, bx
.scols:
    mov [sh_sort_c1], ax
    mov [sh_sort_c2], bx
    mov word [sh_sort_currow], 0xFFFF ; no row is being grouped yet
    mov byte [sh_sort_haskey], 0
    mov word [sh_sort_cnt], 0
    mov word [sh_sort_fcnt], 0
    mov word [sh_sort_tcnt], 0
    xor cx, cx
.scan:
    cmp cx, [sh_ncells]
    jae .scandone
    mov ax, cx
    mov bx, SH_C_SZ
    mul bx
    mov si, ax
    mov es, [sh_cellseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow                 ; ax=row, bx=sheet
    cmp bx, [sh_cursheet]
    jne .next
    mov dx, [es:si+2]                 ; col
    cmp ax, [sh_sort_r1]              ; outside the rows asked for
    jb .next
    cmp ax, [sh_sort_r2]
    ja .next
    cmp dx, [sh_sort_c1]              ; ...or outside the block's columns, in
    jb .next                          ; which case this row is not in play at
    cmp dx, [sh_sort_c2]              ; all on account of THIS cell
    ja .next
    ; --- a new row? then the one before it is finished (81.80) --------------
    cmp ax, [sh_sort_currow]
    je .samerow
    push ax
    call sh_sort_flushblank           ; ...and if it never showed a key cell,
    pop ax                            ; it stages as a BLANK
    mov [sh_sort_currow], ax
    mov byte [sh_sort_haskey], 0
.samerow:
    cmp dx, [sh_sort_keycol]             ; stage 4.5: the KEY, which the dialog
    jne .next                         ; picks and which need not be the anchor
    mov byte [sh_sort_haskey], 1
    mov [sh_sort_row], ax             ; ax = row, stashed (0-based)
    test byte [es:si+4], 1            ; HASFORMULA
    jz .isplainval
    cmp word [sh_sort_fcnt], SH_SORT_FCAP
    jae .next                         ; too many formulas to carry through
                                       ; this sort: exclude this one
                                       ; entirely (see SH_SORT_FCAP's own
                                       ; comment)
    mov ax, dx                        ; col (== sh_sort_keycol, just compared)
    mov bx, [sh_sort_row]
    push cx                           ; CX is this scan's own cell index and
                                       ; sh_getcell2 does NOT preserve it: for
                                       ; a formula cell it reaches sh_eval_cell
                                       ; -> sh_pcmp -> sh_pterm's own `.div`,
                                       ; which does `mov cx, ax` to hold the
                                       ; divisor. Without this save, sorting a
                                       ; column containing any formula that
                                       ; uses '/' restarts or skips the scan
                                       ; from an arbitrary index, silently
                                       ; duplicating or dropping cells.
    push si
    SHOUT sh_getcell2                  ; -> dx = its CURRENT value (never
    pop si                            ; stale - see this proc's own header)
    pop cx
    mov [sh_sort_val], dx
    call sh_sort_class                ; ...and its RESULT's class (81.61): a
    jc .next                          ; text result needs a slot, and if none
                                      ; is left the cell sits the sort out,
                                      ; before its formula text takes one
    mov es, [sh_cellseg]
    mov ax, [es:si+SH_C_FOFF]         ; formula_off
    mov si, ax
    mov es, [sh_txtseg]
    mov di, sh_rwsrc
.copyin:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .copyin
    mov ax, [sh_sort_fcnt]
    mov [sh_sort_fslot], ax
    mov bx, 64
    mul bx
    add ax, SH_SORT_FTXT_OFF
    mov di, ax
    mov es, [sh_stgseg]
    mov si, sh_rwsrc
.copyout:
    mov al, [si]
    mov [es:di], al
    inc si
    inc di
    or al, al
    jnz .copyout
    inc word [sh_sort_fcnt]
    push ax                           ; a formula sorts on its RESULT, which
    push si                           ; sh_getcell2 already left in sh_acc
    push di                           ; above - re-reading it here would use
    mov si, sh_acc                    ; the SI and ES the text copy just left,
                                      ; which point into the staging segment
    mov di, sh_sort_val
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    pop si
    pop ax
    cmp byte [sh_sort_ccls], 1        ; a text result sorts on its TEXT: the
    jne .fkey                         ; value bytes name its slot instead
    mov ax, [sh_sort_ctoff]
    mov [sh_sort_val], ax
.fkey:
    mov al, 1                         ; isformula flag
    jmp .stage
.isplainval:
    ; EVERY CONSTANT SORTS, as in Excel (81.61): numbers, then labels (in
    ; any case), then logicals, then errors. A label, an error and a logical
    ; used to sit the sort out, their rows never entering rows[] - so sorting
    ; a column of names moved nothing. The class says how each compares and
    ; how the write-back restores it
    mov al, [es:si+SH_C_TYPE]
    mov byte [sh_sort_ccls], 0
    cmp al, SH_T_TEXT
    je .stext
    cmp al, SH_T_ERR
    je .serr
    cmp al, SH_T_BOOL
    jne .snum
    mov byte [sh_sort_ccls], 2        ; a logical: its 0 or 1 below
.snum:
    SHOUT sh_cellval_to_acc_si         ; the WHOLE value into sh_acc, not the
    push si                           ; word at SH_S_VAL - sorting on the
    push di                           ; truncated integer made every decimal
    mov si, sh_acc                    ; in a column compare equal
    mov di, sh_sort_val
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    pop si
    jmp short .splain
.serr:
    mov byte [sh_sort_ccls], 3        ; an error: all compare equal, and the
    mov al, [es:si+SH_C_AUX]          ; code rides in the value bytes for the
    xor ah, ah                        ; write-back
    mov [sh_sort_val], ax
    jmp short .splain
.stext:
    push si                           ; a label: its characters into a slot
    mov si, [es:si+SH_C_FOFF]
    call sh_sort_tslot                ; CF=1 no slot left: it sits out
    pop si
    jc .next
    mov byte [sh_sort_ccls], 1
    mov ax, [sh_sort_ctoff]
    mov [sh_sort_val], ax
.splain:
    xor al, al                        ; isformula flag
.stage:
    mov bx, [sh_sort_cnt]
    cmp bx, SH_SORT_CAP
    jae .next                         ; the array is full: this cell sits the
                                       ; sort out, the same "clip, don't
                                       ; crash" policy SH_SORT_FCAP uses
    mov es, [sh_stgseg]
    mov di, bx
    shl di, 1
    mov dx, [sh_sort_row]
    mov [es:di], dx                   ; rows[cnt] = row
    call sh_sort_vof                  ; DI = &values[cnt]
    push ax                           ; AL IS THE ISFORMULA FLAG and the copy
    push si                           ; below moves eight bytes through AX. It
    mov si, sh_sort_val               ; was two bytes when this was a word
    mov ax, [si]                      ; array, and the flag survived by luck;
    mov [es:di], ax                   ; now the value's top word lands in AL
    mov ax, [si+2]                    ; and every ordinary number stages as a
    mov [es:di+2], ax                 ; FORMULA, whose write-back then reads a
    mov ax, [si+4]                    ; text slot that was never written
    mov [es:di+4], ax
    mov ax, [si+6]
    mov [es:di+6], ax
    pop si
    pop ax
    mov di, bx
    shl di, 1
    add di, SH_SORT_ORIG_OFF
    mov [es:di], bx                   ; origidx[cnt] = cnt (pre-sort)
    mov di, bx
    add di, SH_SORT_ISF_OFF
    mov [es:di], al                   ; isformula[cnt]
    mov di, bx
    add di, SH_SORT_CLS_OFF
    mov ah, [sh_sort_ccls]
    mov [es:di], ah                   ; class[cnt], by original index
    or al, al
    jz .noformidx
    mov di, bx
    shl di, 1
    add di, SH_SORT_FIDX_OFF
    mov dx, [sh_sort_fslot]
    mov [es:di], dx                   ; fidx[cnt] = its own text slot
.noformidx:
    inc word [sh_sort_cnt]
.next:
    inc cx
    jmp .scan
.scandone:
    call sh_sort_flushblank           ; the LAST row has no cell after it to
                                       ; notice that it ended (81.80)
    mov cx, [sh_sort_cnt]
    cmp cx, 2
    jb .sortdone
    mov es, [sh_stgseg]
    mov bx, 1
.outer:
    cmp bx, cx
    jae .sortdone
    push bx
    call sh_sort_vof                  ; DI = &values[bx]
    mov si, sh_sort_keyval
    call sh_sort_ldds                 ; key = values[bx], all eight bytes
    pop bx
    mov si, bx
    shl si, 1
    add si, SH_SORT_ORIG_OFF
    mov ax, [es:si]                   ; ax = key's own origidx
    mov [sh_sort_keyorig], ax
    mov si, ax
    mov al, [es:si+SH_SORT_CLS_OFF]
    mov [sh_sort_keyc], al            ; ...and its class, which stays put
    mov di, bx
.inner:
    or di, di
    jz .insert
    push bx
    mov bx, di
    dec bx
    push di
    call sh_sort_vof                  ; DI = &values[j-1]
    mov si, sh_sort_cmpv
    call sh_sort_ldds
    pop di
    mov si, di                        ; values[j-1]'s class, through its
    dec si                            ; origidx
    shl si, 1
    mov si, [es:si+SH_SORT_ORIG_OFF]
    mov al, [es:si+SH_SORT_CLS_OFF]
    mov [sh_sort_cmpc], al
    pop bx
    ; A BLANK GOES LAST WHICHEVER WAY THE SORT RUNS (81.80), which is Excel's
    ; rule and the reason this cannot live in sh_sort_cmp: the direction is
    ; applied BELOW, to the comparison's answer, so a blank that merely
    ; compared "greater" would come FIRST when sorting descending.
    cmp byte [sh_sort_cmpc], 4
    je .vblank
    cmp byte [sh_sort_keyc], 4        ; a blank KEY settles where it is: every
    je .insert                        ; real value is already ahead of it
    call sh_sort_cmp                  ; CF/ZF as a signed compare of
    je .insert                        ; values[j-1] against the key
    jl .isless
    cmp byte [sh_sort_desc], 0        ; values[j-1] > key: ascending shifts,
    jne .insert                       ; descending is already in order
    jmp .shift
.isless:
    cmp byte [sh_sort_desc], 0        ; values[j-1] < key: the other way round
    je .insert
    jmp short .shift
.vblank:
    cmp byte [sh_sort_keyc], 4
    je .insert                        ; both blank: equal, and stable
.shift:
    ; DI IS THE LOOP INDEX j and sh_sort_vof RETURNS IN DI, so every use of it
    ; as a pointer here is bracketed - the origidx block below needs j back,
    ; and getting a byte offset instead is a sort that silently does nothing.
    push bx
    push di                           ; j, banked for the whole value copy
    mov bx, di
    dec bx
    call sh_sort_vof
    mov si, di                        ; SI = &values[j-1]
    pop bx                            ; BX = j (from the push di above)
    push bx
    push si
    call sh_sort_vof                  ; DI = &values[j]
    pop si
    mov ax, [es:si]
    mov [es:di], ax
    mov ax, [es:si+2]
    mov [es:di+2], ax
    mov ax, [es:si+4]
    mov [es:di+4], ax
    mov ax, [es:si+6]
    mov [es:di+6], ax
    pop di                            ; j, restored
    pop bx
    mov si, di
    dec si
    shl si, 1
    add si, SH_SORT_ORIG_OFF
    mov ax, [es:si]
    mov si, di
    shl si, 1
    add si, SH_SORT_ORIG_OFF
    mov [es:si], ax                   ; origidx[j] = origidx[j-1]
    dec di
    jmp .inner
.insert:
    push bx
    push di                           ; j, banked - same trap as .shift
    mov bx, di
    call sh_sort_vof
    mov si, sh_sort_keyval
    mov ax, [si]
    mov [es:di], ax
    mov ax, [si+2]
    mov [es:di+2], ax
    mov ax, [si+4]
    mov [es:di+4], ax
    mov ax, [si+6]
    mov [es:di+6], ax
    pop di                            ; j, restored
    pop bx
    mov si, di
    shl si, 1
    add si, SH_SORT_ORIG_OFF
    mov ax, [sh_sort_keyorig]
    mov [es:si], ax
    inc bx
    jmp .outer
.sortdone:
    cmp byte [sh_protected], 0         ; 81.46: a LOCKED cell refuses the
    je .wbgo                           ; whole sort before anything is
    mov cx, [sh_sort_cnt]              ; written - the carry's own guard would
    jcxz .wbgo                         ; stop it half-way and shear the rows
    mov es, [sh_stgseg]
    mov si, cx                         ; the rows it writes are the occupied
    dec si                             ; ones, rows[0] to rows[cnt-1], across
    shl si, 1                          ; the block's columns
    push word [sh_selcol]
    push word [sh_selrow]
    push word [sh_selcol2]
    push word [sh_selrow2]
    mov ax, [es:0]
    mov [sh_selrow], ax
    mov ax, [es:si]
    mov [sh_selrow2], ax
    mov ax, [sh_sort_c1]
    mov [sh_selcol], ax
    mov ax, [sh_sort_c2]
    mov [sh_selcol2], ax
    mov byte [sh_prot_clr], 1          ; the LOCK is the question: a table a
    SHOUT sh_prot_blocked              ; sort touches is dropped (81.114.9)
    pop word [sh_selrow2]
    pop word [sh_selcol2]
    pop word [sh_selrow]
    pop word [sh_selcol]
    jc .wbpaint                        ; refused, and [sh_msg] says why
.wbgo:
    xor cx, cx
.wb:
    cmp cx, [sh_sort_cnt]
    jae .wbdone
    mov es, [sh_stgseg]
    mov si, cx
    shl si, 1
    mov ax, [es:si]                   ; target_row = rows[cx] (unchanged -
    mov [sh_sort_trow], ax            ; the occupied rows themselves never
                                       ; move, only which VALUE/FORMULA
                                       ; sits in each one does)
    mov si, cx
    shl si, 1
    add si, SH_SORT_ORIG_OFF
    mov ax, [es:si]                   ; src = origidx[cx]
    mov [sh_sort_src], ax
    mov si, ax
    add si, SH_SORT_ISF_OFF
    mov al, [es:si]
    or al, al
    jz .wbplain
    mov si, [sh_sort_src]
    shl si, 1
    mov ax, [es:si]                   ; src_row = rows[src]
    mov bx, [sh_sort_trow]
    sub bx, ax                        ; row delta = target - src
    jz .wbnext                        ; unchanged position: already
                                       ; correct, nothing to rewrite
    mov [sh_cp_rowdelta], bx
    mov word [sh_cp_coldelta], 0
    mov si, [sh_sort_src]
    shl si, 1
    add si, SH_SORT_FIDX_OFF
    mov ax, [es:si]                   ; this formula's own text-slot index
    mov bx, 64
    mul bx
    add ax, SH_SORT_FTXT_OFF
    mov si, ax
    mov di, sh_rwsrc
.wbcopyin:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .wbcopyin
    push cx
    mov si, sh_rwsrc
    SHOUT sh_formula_copyshift
    mov ax, [sh_sort_keycol]             ; the KEY column, the same one .wbplain
    mov bx, [sh_sort_trow]            ; writes to - this said sh_selcol, which
    mov si, sh_rwdst                  ; was the anchor and is no longer the key
    SHOUT sh_setformula
    pop cx
    jc .wbfull                        ; the arena refused: stop the write-back
    jmp .wbnext
.wbplain:
    mov si, [sh_sort_src]             ; its class decides the store (81.61)
    mov al, [es:si+SH_SORT_CLS_OFF]
    cmp al, 4
    je .wbblank                       ; 81.80: it takes its EMPTINESS with it
    cmp al, 1
    je .wbtext
    cmp al, 3
    je .wberr
    cmp al, 2
    je .wbbool
    push cx
    push bx
    mov bx, cx
    call sh_sort_vof                  ; DI = &values[cx]
    mov si, sh_acc                    ; straight into the accumulator
    mov ax, [es:di]
    mov [si], ax
    mov ax, [es:di+2]
    mov [si+2], ax
    mov ax, [es:di+4]
    mov [si+4], ax
    mov ax, [es:di+6]
    mov [si+6], ax
    pop bx
    mov ax, [sh_sort_keycol]
    mov bx, [sh_sort_trow]
    SHOUT sh_setvald                   ; an integer store would truncate it
    pop cx
    jmp .wbnext
.wbblank:                              ; 81.80: the row that had no key cell
    push cx                            ; carries its blank to wherever it
    mov ax, [sh_sort_keycol]           ; landed - which is the end - so the
    mov bx, [sh_sort_trow]             ; cell that used to hold a value and
    SHOUT sh_clearcell                 ; now holds a sorted-away one is
    pop cx                             ; EMPTIED rather than left behind
    jmp .wbnext
.wbbool:
    push cx
    mov bx, cx
    call sh_sort_vof
    xor dl, dl
    cmp word [es:di+6], 0             ; 1.0 has a top word, 0.0 none
    je .wbb
    inc dl
.wbb:
    mov ax, [sh_sort_keycol]
    mov bx, [sh_sort_trow]
    SHOUT sh_setbool
    pop cx
    jmp .wbnext
.wberr:
    push cx
    mov bx, cx
    call sh_sort_vof
    mov dl, [es:di]                   ; the code it was staged with
    mov ax, [sh_sort_keycol]
    mov bx, [sh_sort_trow]
    SHOUT sh_seterr
    pop cx
    jmp .wbnext
.wbtext:
    mov si, [sh_sort_src]             ; its own row already: nothing to do,
    shl si, 1                         ; and no arena spent saying so
    mov ax, [es:si]
    cmp ax, [sh_sort_trow]
    je .wbnext
    push cx
    mov bx, cx
    call sh_sort_vof
    mov si, [es:di]                   ; the slot, out of staging into DS
    mov di, sh_rwsrc                  ; where sh_settext reads
.wbtc:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .wbtc
    mov ax, [sh_sort_keycol]
    mov bx, [sh_sort_trow]
    mov si, sh_rwsrc
    SHOUT sh_settext
    pop cx
    jc .wbfull
    mov es, [sh_stgseg]               ; the loop reads staging through ES
.wbnext:
    inc cx
    jmp .wb
.wbfull:
    mov word [sh_msg], sh_s_sortfull  ; ...and SKIP the carry: permuting the
    jmp .wbpaint                      ; other columns under a half-moved key
                                       ; would shear the table row from row
.wbdone:
    call sh_sort_carry                ; ...and bring the other columns with it
    ; 81.114.9: A SORT IS AN ARBITRARY PERMUTATION, so a table whose range it
    ; touched stops being a table - its results are still the right numbers,
    ; in an order nothing can reconstruct. The record goes and the marks with
    ; it; the VALUES stay where the sort put them, which is the same shape of
    ; answer SYLK gives a table it cannot describe. It is SAID, because a
    ; table silently ceasing to be one is the kind of thing a user finds out
    ; about much later.
    call sh_tbl_sortdrop
    or al, al
    jz .wbpaint
    mov word [sh_msg], sh_s_sorttbl
.wbpaint:
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret


; =============================================================================
; 81.81: Format > Justify - re-wrap a paragraph down the LEFT column of the
; selection, to the width of the WHOLE selection.
;
; The contract is Excel 2.1d's Reference Guide, "Format Justify command", and
; it is more specific than "wrap a long label":
;
;   - the text comes from the LEFT COLUMN of the range and nowhere else. The
;     other columns only lend their WIDTH; what is in them is untouched, and
;     the Guide's own note is that they "should be blank or they will
;     interfere with the display of the text"
;   - every cell in that left column must be TEXT or BLANK. A value refuses
;     the whole command rather than being skipped
;   - a BLANK cell is a PARAGRAPH SEPARATOR. It divides the range into
;     sections that are each justified INDIVIDUALLY, inside their own rows -
;     the Guide's five-row example with the third cell blank
;   - the lines go back down the left column, and rows a section does not
;     need are left blank
;
; WHAT IS SCOPED OUT, and said rather than hidden: Excel ASKS when the text
; does not fit and, on OK, writes past the bottom of the selection. This
; refuses instead, naming the rows it would have needed. The ask is not the
; expensive part - os88ui_ask is one call - the WRITE is: the alert is
; asynchronous (81.79's shape), so the wrapped text has to survive in staging
; across a window the user can click anywhere in, and staging is the scratch
; that Undo, the clipboard and every file write also use. Refusing costs the
; user one Column Width away from the same result and costs no data.
; =============================================================================
section SH_MODSEC                      ; 81.81: Format > Justify, CHART.OVL

SH_JU_LMAX equ SH_EDITMAX              ; a line is a label, and this is a label

sh_docmd_justify:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    call sh_ju_block                   ; the ordered block and the width
    call sh_ju_check                   ; ...and every left-column cell is text
    jc .notext
    push word [sh_selcol]              ; 81.46: the LEFT column is all it
    push word [sh_selcol2]             ; writes, so that is what is asked
    mov ax, [sh_ju_c1]
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    SHOUT sh_prot_blocked
    pop word [sh_selcol2]
    pop word [sh_selcol]
    jc .out                            ; refused, and [sh_msg] says why
    ; --- PASS 1: every section, counted and NOTHING written ------------------
    mov ax, [sh_ju_r1]
    mov [sh_ju_a], ax
.p1:
    call sh_ju_section                 ; CF=1 when there are no more
    jc .p1done
    call sh_ju_stage                   ; the section merged into staging
    call sh_ju_count                   ; CX = the lines it wraps to
    mov ax, [sh_ju_b]
    sub ax, [sh_ju_a]
    inc ax                             ; the rows the section HAS
    cmp cx, ax
    ja .toobig
    mov ax, [sh_ju_b]
    inc ax
    mov [sh_ju_a], ax
    jmp .p1
.p1done:
    ; --- PASS 2: the same walk, writing. Nothing has been touched yet, so a
    ;     section that would not fit has already refused above -------------
    mov al, SH_UL_JUST
    SHOUT sh_undo_begin
    mov ax, [sh_ju_r1]
    mov [sh_ju_a], ax
.p2:
    call sh_ju_section
    jc .p2done
    call sh_ju_stage
    call sh_ju_write
    mov ax, [sh_ju_b]
    inc ax
    mov [sh_ju_a], ax
    jmp .p2
.p2done:
    SHOUT sh_undo_end
    mov word [sh_msg], sh_s_ju_done
    ; DELIBERATELY NOT RECORDED. 81.74's recorder emits only what 81.63's 20
    ; functions can say, so that a recording is an ordinary macro sheet
    ; afterwards; there is no JUSTIFY() to emit, and inventing one here would
    ; write a recording that no longer replays. Not recorded is the bargain
    ; that section already makes, and is not the same as refused.
    jmp short .out
.notext:
    mov word [sh_msg], sh_s_ju_notext
    jmp short .out
.toobig:
    mov word [sh_msg], sh_s_ju_toobig
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ju_block - the selection, ordered, and the line width.
;
; The width is the sum of the SELECTED columns' widths, which is what "fill to
; the edge of that row of the selection" means. A hidden column answers zero
; (81.73) and so contributes nothing, which is right: it shows no characters.
; Clamped to SH_JU_LMAX because the result is a LABEL.
; -----------------------------------------------------------------------------
sh_ju_block:
    push ax
    push bx
    push cx
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .c
    xchg ax, bx
.c:
    mov [sh_ju_c1], ax
    mov [sh_ju_c2], bx
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .r
    xchg ax, bx
.r:
    mov [sh_ju_r1], ax
    mov [sh_ju_r2], bx
    xor cx, cx
    mov ax, [sh_ju_c1]
.wsum:
    cmp ax, [sh_ju_c2]
    ja .wdone
    push ax
    SHOUT sh_colwidth                  ; AX = its width, 0 when hidden
    add cx, ax
    pop ax
    inc ax
    cmp cx, SH_JU_LMAX                 ; no point summing 256 of them
    jb .wsum
.wdone:
    cmp cx, SH_JU_LMAX
    jbe .wok
    mov cx, SH_JU_LMAX
.wok:
    or cx, cx                          ; every column hidden: one character,
    jnz .wset                          ; so it wraps rather than dividing by
    mov cx, 1                          ; zero further down
.wset:
    mov [sh_ju_w], cx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ju_check - CF=1 when any cell of the left column, within the rows, is
; something other than a label. A FORMULA refuses too, whatever it evaluates
; to: the Guide says the cells "must either contain text or be blank", and a
; formula is neither - justifying it would replace it with its own text.
; -----------------------------------------------------------------------------
sh_ju_check:
    push ax
    push bx
    push di
    push es
    mov bx, [sh_ju_r1]
.row:
    cmp bx, [sh_ju_r2]
    ja .ok
    mov ax, [sh_ju_c1]
    SHOUT sh_findcell                  ; DI = the record, CF=0 when empty
    jnc .next
    mov es, [sh_cellseg]
    test byte [es:di+4], 1             ; HASFORMULA
    jnz .bad
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    jne .bad
.next:
    inc bx
    jmp .row
.ok:
    clc
    jmp short .out
.bad:
    stc
.out:
    pop es
    pop di
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ju_section - from [sh_ju_a], find the next run of non-blank left-column
; cells and leave it in [sh_ju_a]..[sh_ju_b]. CF=1 when there is none left.
; The blank rows BETWEEN sections are skipped and stay blank, which is the
; Guide's paragraph separator.
; -----------------------------------------------------------------------------
sh_ju_section:
    push ax
    push bx
    mov bx, [sh_ju_a]
.skip:
    cmp bx, [sh_ju_r2]
    ja .none
    call sh_ju_isblank
    jnc .found                         ; occupied: the section starts here
    inc bx
    jmp .skip
.found:
    mov [sh_ju_a], bx
.run:
    inc bx
    cmp bx, [sh_ju_r2]
    ja .end
    call sh_ju_isblank
    jnc .run
.end:
    dec bx
    mov [sh_ju_b], bx
    clc
    jmp short .out
.none:
    stc
.out:
    pop bx
    pop ax
    ret

; sh_ju_isblank - in: BX = row; CF=1 when the LEFT column's cell there is
; empty. sh_ju_check has already refused anything that is not a label, so
; "occupied" and "has text" are the same question by the time this runs.
sh_ju_isblank:
    push ax
    push di
    mov ax, [sh_ju_c1]
    SHOUT sh_findcell
    jc .full
    stc
    jmp short .out
.full:
    clc
.out:
    pop di
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ju_stage - merge rows [sh_ju_a]..[sh_ju_b] of the left column into one
; NUL-terminated string at sh_stgseg:0, a single space between rows. The text
; goes through sh_editbuf rather than being copied arena-to-staging directly,
; because those are two different segments and DS is the package's own
; (81.18.2's hang: switch DS to read someone else's memory and your own bss
; reads back as theirs).
; -----------------------------------------------------------------------------
sh_ju_stage:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    xor di, di
    mov bx, [sh_ju_a]
.row:
    cmp bx, [sh_ju_b]
    ja .done
    call sh_ju_gettext                 ; the row's label -> sh_editbuf
    or di, di
    jz .copy                           ; the first one needs no separator
    mov es, [sh_stgseg]
    mov byte [es:di], ' '
    inc di
.copy:
    mov si, sh_editbuf
    mov es, [sh_stgseg]
.byte:
    mov al, [si]
    or al, al
    jz .rownext
    cmp di, SH_STAGE_MAX - 2           ; staging is 32KB and the text arena is
    jae .done                          ; 8, so this cannot fire today - it is
    mov [es:di], al                    ; here because "cannot" is a property of
    inc di                             ; two constants that have both moved
    inc si
    jmp .byte
.rownext:
    inc bx
    jmp .row
.done:
    mov es, [sh_stgseg]
    mov byte [es:di], 0
    mov [sh_ju_len], di
    mov word [sh_ju_si], 0
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_ju_gettext - in: BX = row; copies the LEFT column's label into
; sh_editbuf, empty when there is none.
sh_ju_gettext:
    push ax
    push cx
    push si
    push di
    push es
    mov byte [sh_editbuf], 0
    mov ax, [sh_ju_c1]
    SHOUT sh_findcell
    jnc .out
    mov es, [sh_cellseg]
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    jne .out
    mov si, [es:di+SH_C_FOFF]          ; a label shares the formula arena
    mov es, [sh_txtseg]
    mov di, sh_editbuf
    mov cx, SH_EDITMAX
.cp:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .out
    inc si
    inc di
    dec cx
    jnz .cp
    mov byte [di], 0
.out:
    pop es
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ju_nextline - the greedy wrap, one line a call, out of staging and into
; sh_ju_line. CF=1 when the staged string is spent.
;
; Break at the last space that fits; a word longer than the whole width is cut
; where it runs out, because the alternative is a line this app cannot store.
; -----------------------------------------------------------------------------
sh_ju_nextline:
    push ax
    push bx
    push cx
    push dx
    push si
    push es
    mov es, [sh_stgseg]
    mov si, [sh_ju_si]
.lead:
    cmp byte [es:si], ' '              ; leading spaces belong to the break,
    jne .start                         ; not to the line
    inc si
    jmp .lead
.start:
    cmp byte [es:si], 0
    je .spent
    xor cx, cx                         ; characters taken
    mov dx, 0xFFFF                     ; the last space's index, none yet
.take:
    mov al, [es:si]
    or al, al
    jz .emit                           ; the rest fits whole
    cmp cx, [sh_ju_w]
    jae .full
    cmp al, ' '
    jne .put
    mov dx, cx
.put:
    mov bx, cx
    mov [sh_ju_line + bx], al
    inc cx
    inc si
    jmp .take
.full:
    cmp byte [es:si], ' '              ; it broke exactly on a space: clean
    je .emit
    cmp dx, 0xFFFF
    je .emit                           ; one word wider than the line: cut it
    sub si, cx                         ; back up to the last space
    add si, dx
    mov cx, dx
.emit:
    ; ...and no line ENDS in a space. `.lead` takes the leading ones off the
    ; next line, but a break that lands on the SECOND of two consecutive
    ; spaces leaves the first one stored: 'aa  bb' at width 4 emitted 'aa '.
    ; A justified line is written back as a label, so that space is a
    ; character the cell really holds.
.rtrim:
    or cx, cx
    jz .emit0
    mov bx, cx
    dec bx
    cmp byte [sh_ju_line + bx], ' '
    jne .emit0
    mov cx, bx
    jmp short .rtrim
.emit0:
    mov bx, cx
    mov byte [sh_ju_line + bx], 0
    mov [sh_ju_si], si
    clc
    jmp short .out
.spent:
    mov [sh_ju_si], si
    stc
.out:
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_ju_count - out: CX = the lines the staged section wraps to. Leaves the
; cursor rewound, so the same staging can be wrapped again to write.
sh_ju_count:
    xor cx, cx
    mov word [sh_ju_si], 0
.l:
    call sh_ju_nextline
    jc .done
    inc cx
    jmp .l
.done:
    mov word [sh_ju_si], 0
    ret

; -----------------------------------------------------------------------------
; sh_ju_write - wrap the staged section and write it down the left column from
; [sh_ju_a]. Rows the section does not need are CLEARED: the Guide's "unused
; cells are left blank", and without it the tail of a paragraph that shrank
; would stay on the sheet underneath the new text.
; -----------------------------------------------------------------------------
sh_ju_write:
    push ax
    push bx
    push si
    mov word [sh_ju_si], 0
    mov bx, [sh_ju_a]
.l:
    cmp bx, [sh_ju_b]
    ja .done
    call sh_ju_nextline
    jc .blank
    mov ax, [sh_ju_c1]
    mov si, sh_ju_line
    SHOUT sh_settext                   ; CF=1: the arena is full, and the cell
    jc .done                           ; keeps what it had - so STOP rather
    inc bx                             ; than write half a paragraph
    jmp .l
.blank:
    mov ax, [sh_ju_c1]
    SHOUT sh_clearcell
    inc bx
    jmp .l
.done:
    pop si
    pop bx
    pop ax
    ret

section .text

section .text


; =============================================================================
; Format dialogs (stage 1.8). Real Excel's Number/Alignment/Font dialogs
; each boil down to "pick one of a short list, then OK/Cancel" for what
; this app actually supports (Number's real dialog is a much longer
; scrollable list of format-code strings,
; LIBRARY/documentation/screenshots/excel/dialog_number.png - Sheet only ever
; has 4 number formats, so a plain 4-item radio list stands
; in for it, same shape as the real Alignment and Font dialogs). All three
; are really the SAME dialog (a title, 4 radio rows, OK/Cancel) with
; different labels and a different 2-bit field of the format byte to read
; and write - see sh_fdlg_kind - which is why one implementation serves
; all three rather than three near-copies.
;
; Built directly on apps/os88ui.inc's primitives (os88ui_glyph for the
; radio dots, os88ui_btn for OK/Cancel) rather than os88ui_ask, which only
; ever offers a message and a button row - there is no generic
; "N controls" dialog builder in this codebase (apps/word/word.asm rolled
; its own, ~900 lines, for a dozen much bigger dialogs; three small
; identical-shaped ones don't need that). Only one can be open at a time
; (sh_fdlg_win is the gate, same single-instance idea as os88ui_awin, just
; simpler: this dialog doesn't need "refuse and raise" since the menu
; command that opens it can't fire again while it's up).
;
; Radio index 0-3 in each dialog is deliberately identical to that
; category's own SH_FMT_* encoding (SH_FMT_ALIGN_LEFT=1, SH_FMT_NUM_COMMA=2,
; etc, and Font's 0=Normal/1=Bold/2=Underline/3=Bold+Underline is just
; SH_FMT_BOLD|SH_FMT_UNDER's own bit pattern) - so applying a choice is a
; plain mask-and-OR, no translation table needed anywhere.
; =============================================================================
; 81.115: EXCEL'S SHAPE, and it is the CHECK-BOX engine's shape too - a
; titled group box around the choices with OK and Cancel STACKED at the top
; right (dialog_alignment.png in the reference captures). sh_bdlg already had
; it; this engine drew its buttons side by side along the bottom, which is the
; one place the two engines disagreed with each other and with Excel.
SH_FDLG_GX1    equ 10                ; the group box, inset from the content
SH_FDLG_GY1    equ 12                ; origin - sh_bdlg's own two numbers
SH_FDLG_GX2    equ 200               ; ...but WIDER than sh_bdlg's 104: the
                                     ; longest label here is 'All Matching
                                     ; Records' at 20 cells, which starts at
                                     ; GX1 + 24 and so ends at 194
SH_FDLG_BTW    equ 54                ; the button column, to the RIGHT of the
SH_FDLG_BTH    equ 16                ; box and measured from the SAME origin
SH_FDLG_BTGAP  equ 6                 ; as its top edge, which is what "stacked
SH_FDLG_BTX    equ SH_FDLG_GX2 + 10  ; top right" means
SH_FDLG_BTBOT  equ SH_FDLG_GY1 + 2 * SH_FDLG_BTH + SH_FDLG_BTGAP
SH_FDLG_W      equ SH_FDLG_BTX + SH_FDLG_BTW + 10
SH_FDLG_ROWTOP equ SH_FDLG_GY1 + 14  ; the first radio row, inside the box and
                                     ; clear of the label on its top edge -
                                     ; sh_bdlg's 26, reached by derivation so
                                     ; moving GY1 moves both
SH_FDLG_ROWH   equ 16
SH_FDLG_NITEMS equ 4
; THE BUTTON ROW AND THE WINDOW HEIGHT ARE ONE NUMBER, not two that have to be
; kept in agreement by hand. They were two, and they disagreed: the height was
; a flat 116 while the buttons were drawn at content-relative 86..102, and a
; window's content is only W_H - TITLE_H - 1 tall (wm_content: the origin is
; W_X+1, W_Y+TITLE_H). 116 - 18 - 1 = 97, so the bottom HALF of OK and Cancel
; was outside the window in every one of this engine's kinds - Number,
; Alignment, Font, Insert, Delete, Column Width and Row Height since stage 1.8,
; and the four stage 3.0c added. Deriving it means the next kind that needs a
; taller body cannot reintroduce this by changing one of the two.
SH_FDLG_MAXROWS equ 7                ; the tallest kind's row count, and the
                                     ; reason the button row is derived from
                                     ; it rather than fixed: the Gallery kind
                                     ; has five rows and the row at index 4
                                     ; landed ON the buttons, because 86 was
                                     ; chosen when four was the most any kind
                                     ; had. A new kind with more rows changes
                                     ; this one number.
SH_DLG_BMARG   equ 8                 ; the gap every dialog leaves below its
                                     ; lowest element, and the reason all four
                                     ; heights below are DERIVED: a window's
                                     ; content is W_H - TITLE_H - 1 tall, so a
                                     ; hand-written height is a second number
                                     ; that has to agree with the first and
                                     ; silently did not
; THE HEIGHT IS PER KIND NOW (81.115) and this is only the TEMPLATE's, the
; tallest one: sh_fdlg_open patches WT_H from [sh_fdlg_count] before it
; creates the window, exactly as it already patches WT_X and WT_Y. Every kind
; used to be sized for the tallest, so Insert's two choices got Gallery's
; seven-row dialog - which was invisible while the body was bare rows and is
; plainly wrong inside a group box.
;
; It is also what RELIEVES the CGA problem recorded at the OSAPI_WM_KEEPH call
; below rather than working around it: the buttons no longer sit under the
; rows, so even the tallest kind is shorter than the fixed 171 this was.
SH_FDLG_BOXH   equ SH_FDLG_ROWTOP - SH_FDLG_GY1 + SH_FDLG_MAXROWS * SH_FDLG_ROWH + 4
SH_FDLG_H      equ SH_FDLG_GY1 + SH_FDLG_BOXH + SH_DLG_BMARG + TITLE_H + 1

sh_fdlg_tpl:
    dw 0, 0, SH_FDLG_W, SH_FDLG_H
    dw 0, sh_fdlg_paint_r, 0, sh_fdlg_click_r

; Stage 2.x's Edit menu Insert.../Delete... reuse this same engine as kinds
; 3 and 4 - just a 2-item Row/Column pick instead of a 4-item format
; radio, and a different [sh_fdlg_count] (see sh_fdlg_open) since these
; two kinds don't have 4 rows to show. sh_fdlg_apply branches to
; sh_rowcol_op for these two kinds instead of writing a format bit.
; Kinds 5/6 are RETIRED: they were the Narrow/Normal/Wide and Short/Normal/
; Tall presets Column Width.../Row Height... used before stage 3.0c gave
; them sh_idlg_open's typed field, and nothing has opened them since. Their
; code went in 81.59; the two slots stay, as zeros, so every later kind keeps
; its number - sh_ud_kind and the SH_FDK_* equates are indexed by it.
; Kinds 7-10 (stage 3.0c) are the last four radio dialogs Excel 2.1d has and
; this app was doing as immediate menu commands: Clear, New, Calculation and
; Sort. Each was a one-line "just do it" item, which is wrong twice - Excel
; asks, and asking is what lets Clear mean something other than "everything"
; and Sort mean something other than "ascending".
; 81.75: kinds 15 and 16 are Extract and Series. They go the way 5 and 6 did
; when they were retired - the SLOT stays, because a kind is an index into
; these three tables and into sh_ud_kind, and the entry becomes 0.
sh_fdlg_titles: dw sh_s_fd_num, sh_s_fd_align, sh_s_fd_font, sh_s_fd_insert, sh_s_fd_delete, 0, 0, sh_s_fd_clear, sh_s_fd_new, sh_s_fd_calc, sh_s_fd_sort, sh_s_fd_gal, sh_s_fd_savefmt, sh_s_fd_pspec, sh_s_fd_prot
                dw sh_s_fd_extract, sh_s_fd_series
sh_s_fd_pspec:  db 'Paste Special', 0
sh_s_fd_prot:   db 'Cell Protection', 0
sh_s_fd_extract: db 'Extract', 0
sh_s_fd_series: db 'Series', 0
sh_s_fd_savefmt: db 'File Format', 0
sh_s_fd_gal:    db 'Gallery', 0
sh_s_fd_clear:  db 'Clear', 0
sh_s_fd_new:    db 'New', 0
sh_s_fd_calc:   db 'Calculation', 0
sh_s_fd_sort:   db 'Sort', 0
sh_s_fd_num:    db 'Format Number', 0
sh_s_fd_align:  db 'Alignment', 0
sh_s_fd_font:   db 'Font', 0
sh_s_fd_insert: db 'Insert', 0
sh_s_fd_delete: db 'Delete', 0

sh_fdlg_items:  dw sh_fd_i_num, sh_fd_i_align, sh_fd_i_font, sh_fd_i_rowcol, sh_fd_i_rowcol, 0, 0, sh_fd_i_clear, sh_fd_i_new, sh_fd_i_calc, sh_fd_i_sort, sh_fd_i_gal, sh_fd_i_savefmt, sh_fd_i_pspec, sh_fd_i_prot
                dw sh_fd_i_extract, sh_fd_i_series
; Excel's Cell Protection dialog is two INDEPENDENT CHECK BOXES, Locked and
; Hidden. This is the four combinations as a radio, which is exactly what the
; Font dialog above already does with Bold and Underline - the same engine and
; the same compression, so it is at least consistent with itself. The order
; mirrors Font's: the default first, then each one alone, then both.
sh_fd_i_prot:   dw sh_fd_prlock, sh_fd_prunlock, sh_fd_prlockh, sh_fd_prunlockh
sh_fd_prlock:   db 'Locked', 0
sh_fd_prunlock: db 'Unlocked', 0
sh_fd_prlockh:  db 'Locked, Hidden', 0
sh_fd_prunlockh: db 'Unlocked, Hidden', 0
; 81.71: Excel's own Extract dialog carries ONE control, a `Unique Records
; Only` CHECK BOX. This engine paints a radio column, so the same single bit
; is asked as a two-way pick instead - identical meaning, no sixth dialog
; engine, and the divergence is the one §81.31 already took for Gridlines and
; Formulas. Index 1 IS the flag, so sh_fdlg_apply0 stores it with no mapping.
sh_fd_i_extract: dw sh_fd_exall, sh_fd_exuniq
sh_fd_exall:    db 'All Matching Records', 0
sh_fd_exuniq:   db 'Unique Records Only', 0
; 81.72: Excel's Series dialog carries FIVE controls - Series In, Type, Date
; Unit, Step Value and Stop Value. Type and Date Unit fold into one radio
; column here (a date unit is only ever read when the type IS Date, so the
; two questions are really one), Step Value is the second dialog, and the
; other two are 81.72's own documented shortfalls
sh_fd_i_series: dw sh_fd_serlin, sh_fd_sergro, sh_fd_serday, sh_fd_serwd
                dw sh_fd_sermon, sh_fd_seryr
sh_fd_serlin:   db 'Linear', 0
sh_fd_sergro:   db 'Growth', 0
sh_fd_serday:   db 'Date: Day', 0
sh_fd_serwd:    db 'Date: Weekday', 0
sh_fd_sermon:   db 'Date: Month', 0
sh_fd_seryr:    db 'Date: Year', 0
; Excel's own five, in Excel's own order (Reference Guide p.236). The dialog
; there ALSO carries an Operation group (None/Add/Subtract/Multiply/Divide)
; and two check boxes (Skip Blanks, Transpose); this engine paints ONE radio
; column and an OK/Cancel, so those are absent rather than faked - see 81.45.
sh_fd_i_pspec:  dw sh_fd_psall, sh_fd_psform, sh_fd_psval, sh_fd_psfmt, sh_fd_psnote
sh_fd_psall:    db 'All', 0
sh_fd_psform:   db 'Formulas', 0
sh_fd_psval:    db 'Values', 0
sh_fd_psfmt:    db 'Formats', 0
sh_fd_psnote:   db 'Notes', 0
; Excel's own words: the app's OWN format is "Normal", and the interchange
; formats are named after themselves. The order is Excel's too.
sh_fd_i_savefmt: dw sh_fd_sfnormal, sh_fd_sfsylk, sh_fd_sfdif, sh_fd_sfcsv, sh_fd_sftxt, sh_fd_sfdbf
sh_fd_sfnormal: db 'Normal', 0
sh_fd_sfsylk:   db 'SYLK', 0
sh_fd_sfdif:    db 'DIF', 0
sh_fd_sfcsv:    db 'CSV', 0         ; 81.40: two of the nine formats Excel 2.0
sh_fd_sftxt:    db 'Text', 0
sh_fd_sfdbf:    db 'DBF 3', 0     ; Excel's own label for it        ; listed and this app did not have. Excel's
                                    ; own words for them in its Save As list
; Excel's own Gallery order, which is alphabetical and is NOT the order CH_T_*
; happens to be in - sh_gal_map translates, the same way chart.asm's own
; ct_gal_map does, rather than either side renumbering to suit the other.
sh_fd_i_gal:    dw sh_fd_garea, sh_fd_gbar, sh_fd_gcol, sh_fd_gline, sh_fd_gpie, sh_fd_gsca, sh_fd_gcmb
sh_fd_garea:    db 'Area', 0
sh_fd_gbar:     db 'Bar', 0
sh_fd_gcol:     db 'Column', 0
sh_fd_gline:    db 'Line', 0
sh_fd_gpie:     db 'Pie', 0
sh_fd_gsca:     db 'Scatter', 0
sh_fd_gcmb:     db 'Combination', 0
sh_gal_map:     dw CH_T_AREA, CH_T_BAR, CH_T_COLUMN, CH_T_LINE, CH_T_PIE, CH_T_SCATTER, CH_T_COMBO
sh_fd_i_clear:  dw sh_fd_clall, sh_fd_clform, sh_fd_clfmt
sh_fd_clall:    db 'All', 0
sh_fd_clform:   db 'Formulas', 0       ; Excel's own order and its own words:
sh_fd_clfmt:    db 'Formats', 0        ; "Formulas" means the CONTENTS
sh_fd_i_new:    dw sh_fd_nwsheet, sh_fd_nwchart, sh_fd_nwmacro
sh_fd_nwsheet:  db 'Worksheet', 0
sh_fd_nwchart:  db 'Chart', 0
sh_fd_nwmacro:  db 'Macro Sheet', 0
; 81.114.8: Excel 2.1's Calculation dialog is Automatic / Automatic except
; Tables / Manual, and the middle one is there for exactly the reason it is
; needed here - a table is a full formula evaluation PER RESULT CELL, where
; an ordinary formula is a memoized one. The capture is
; LIBRARY/documentation/screenshots/excel/dialog_calculation.png. Calculate
; Now is this app's own fourth row rather than Excel's separate menu item
; (81.78), and it stays where it was, after the three modes.
sh_fd_i_calc:   dw sh_fd_cauto, sh_fd_cauex, sh_fd_cmanual, sh_fd_cnow
sh_fd_cauto:    db 'Automatic', 0
sh_fd_cauex:    db 'Automatic except Tables', 0
sh_fd_cmanual:  db 'Manual', 0
sh_fd_cnow:     db 'Calculate Now', 0
sh_fd_i_sort:   dw sh_fd_sasc, sh_fd_sdesc
sh_fd_sasc:     db 'Ascending', 0
sh_fd_sdesc:    db 'Descending', 0
sh_fd_i_num:    dw sh_fd_numgen, sh_fd_numcur, sh_fd_numcomma, sh_fd_numpct
sh_fd_numgen:   db 'General', 0
sh_fd_numcur:   db 'Currency', 0
sh_fd_numcomma: db 'Comma', 0
sh_fd_numpct:   db 'Percent', 0
sh_fd_i_align:  dw sh_fd_agen, sh_fd_aleft, sh_fd_acenter, sh_fd_aright
sh_fd_agen:     db 'General', 0
sh_fd_aleft:    db 'Left', 0
sh_fd_acenter:  db 'Center', 0
sh_fd_aright:   db 'Right', 0
sh_fd_i_font:   dw sh_fd_fnorm, sh_fd_fbold, sh_fd_funder, sh_fd_fboth
sh_fd_fnorm:    db 'Normal', 0
sh_fd_fbold:    db 'Bold', 0
sh_fd_funder:   db 'Underline', 0
sh_fd_fboth:    db 'Bold, Underline', 0
sh_fd_i_rowcol: dw sh_fd_rcrow, sh_fd_rccol
sh_fd_rcrow:    db 'Row', 0
sh_fd_rccol:    db 'Column', 0

sh_s_fd_ok:     db 'OK', 0
sh_s_fd_cancel: db 'Cancel', 0

; per-kind row count (0 Number/1 Align/2 Font = 4 rows, 3 Insert/4 Delete
; = 2 rows, 5/6 retired) - sh_fdlg_open copies the
; matching entry into [sh_fdlg_count], which sh_fdlg_paint/sh_fdlg_onclick
; loop and hit-test against instead of the fixed SH_FDLG_NITEMS.
sh_fdlg_counts: dw 4, 4, 4, 2, 2, 0, 0, 3, 4, 3, 2, 7, 6, 5, 4, 2, 6

; 81.114.8: Options > Calculation's three MODES, in Excel's own order, and
; the dialog row after them that is this app's folded-in Calculate Now.
; The order matters twice over: it IS the radio row number, and it is
; GET.DOCUMENT(14)'s own numbering less one (1 Automatic, 2 Automatic except
; tables, 3 Manual), which is why shm_gd_calc is now `mode + 1` instead of a
; two-way pick that could not say the middle one.
SH_CALC_AUTO   equ 0
SH_CALC_AUEX   equ 1                ; automatic, except tables
SH_CALC_MANUAL equ 2
SH_CALC_NOWROW equ 3                ; not a mode: the dialog's fourth row

SH_FDK_CLEAR equ 7
SH_PEND_NEW  equ 1                  ; sh_ask_unsaved's owed action (81.118)
SH_PEND_OPEN equ 2
SH_PEND_CLOSE equ 3
SH_FDK_NEW   equ 8
SH_FDK_CALC  equ 9
SH_FDK_SORT  equ 10
SH_FDK_GAL   equ 11
SH_FDK_SAVEFMT equ 12                 ; stage 4.6: Save As asks for the format
SH_FDK_PSPEC equ 13                   ; instead of deriving it silently
SH_FDK_PROT  equ 14
SH_FDK_EXTRACT equ 15                 ; 81.71: Data ▸ Extract...
SH_FDK_SERIES equ 16                  ; 81.72: Data ▸ Series..., part one of
SH_FDK_N     equ 17                   ; two (the step value follows)
    times (sh_ud_kind_end - sh_ud_kind - SH_FDK_N) db 0  ; sh_ud_kind (81.57)
    times (SH_FDK_N - (sh_ud_kind_end - sh_ud_kind)) db 0 ; has a kind each
section SH_MODSEC                      ; 81.74.2: the radio dialog engine, CHART.OVL

; -----------------------------------------------------------------------------
; sh_fdlg_open - in: AL = 0 Number / 1 Alignment / 2 Font. Preselects the
; radio matching the selected cell's current format (0/General if the cell
; has no record yet - the dialog still opens; OK on a still-empty cell is a
; no-op, same scope limit the old flat menu already had).
; -----------------------------------------------------------------------------
sh_fdlg_open:
    push ax
    push bx
    push cx
    push si
    push di
    cmp word [sh_fdlg_win], 0
    jne .out                          ; already open (can't happen via the
                                       ; menu, which is inert while a dialog
                                       ; owns input focus, but stay safe)
    mov [sh_fdlg_kind], al
    mov word [sh_fdlg_sel], 0
    mov bl, al
    xor bh, bh
    shl bx, 1
    mov cx, [sh_fdlg_counts + bx]
    mov [sh_fdlg_count], cx
    cmp al, SH_FDK_SERIES             ; 81.72: Series pins its range for the
    je .prefillseries                 ; same reason, and needs it across TWO
                                       ; dialogs rather than one
    cmp al, SH_FDK_EXTRACT            ; 81.71: Extract PINS the selection it
    je .prefillextract                ; was opened on - these windows are not
                                       ; modal (81.6), so the selection can
                                       ; move while one is up, and the extract
                                       ; range is the whole point of the
                                       ; command. sh_ndlg's pattern, not
                                       ; sh_fdlg's own live read
    cmp al, SH_FDK_SAVEFMT
    je .prefillfmt                    ; File Format opens on the format the
    cmp al, SH_FDK_GAL                ; current NAME already implies
    je .prefillgal                    ; Gallery opens on the type in use, so
    cmp al, SH_FDK_CALC               ; OK alone cannot silently change it
    je .prefillcalc                   ; Calculation opens SHOWING the mode it
    cmp al, SH_FDK_PROT               ; is in, so OK alone cannot change it
    je .prefillprot                   ; ...and Cell Protection opens showing
    cmp al, SH_FDK_CLEAR              ; what the cell already IS, for exactly
    jae .noprefill                    ; that reason. Clear/New/Sort have
                                       ; nothing current
    cmp al, 3
    jae .noprefill                    ; Insert/Delete (kinds 3/4): no
                                       ; "current" selection to preselect,
                                       ; just default to row 0 ("Row")
    jmp .cellpre
.prefillseries:                       ; 81.72: the range to fill, and the
    mov cx, [sh_selcol]               ; DIRECTION derived from its shape -
    mov [sh_ser_c1], cx               ; see sh_docmd_series on why that is
    mov cx, [sh_selrow]               ; not a third question
    mov [sh_ser_r1], cx
    mov cx, [sh_selcol2]
    mov [sh_ser_c2], cx
    mov cx, [sh_selrow2]
    mov [sh_ser_r2], cx
    jmp .noprefill
.prefillextract:                      ; 81.71: bank the extract range, both
    mov cx, [sh_selcol]               ; corners as selected - normalising is
    mov [sh_ex_c1], cx                ; the module's job, the same way
    mov cx, [sh_selrow]               ; sh_name_def leaves it to sh_foldrange
    mov [sh_ex_r1], cx
    mov cx, [sh_selcol2]
    mov [sh_ex_c2], cx
    mov cx, [sh_selrow2]
    mov [sh_ex_r2], cx
    jmp .noprefill
.prefillprot:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    SHOUT sh_bt_get                    ; AL = the byte, and 0 when the cell has
    xor cx, cx                        ; no record at all - which IS the
    test al, SH_PROT_UNLOCK           ; default, Locked and not Hidden
    jz .pp1
    inc cx
.pp1:
    test al, SH_PROT_HIDDEN
    jz .pp2
    add cx, 2
.pp2:
    mov [sh_fdlg_sel], cx             ; CX is banked at entry, so using it
    jmp .noprefill                    ; here costs the caller nothing
.prefillfmt:
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_dif
    SHOUT sh_nameends
    pop di
    pop si
    jc .fmtdif
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_biff
    SHOUT sh_nameends
    pop di
    pop si
    jc .fmtbiff
    push si                           ; ...and .XLS is Normal too, as the
    push di                           ; reader and the writer both take it
    mov si, sh_name                   ; (81.15.1)
    mov di, sh_s_ext_xls
    SHOUT sh_nameends
    pop di
    pop si
    jc .fmtbiff
    mov word [sh_fdlg_sel], 1         ; anything else is SYLK, which is what
    jmp .noprefill                    ; sh_dowrite itself falls through to
.fmtdif:
    mov word [sh_fdlg_sel], 2
    jmp .noprefill
.fmtbiff:
    mov word [sh_fdlg_sel], 0
    jmp .noprefill
.prefillgal:
    xor bx, bx                        ; find [ch_type] in the map rather than
    mov cx, 7                         ; inverting it - seven entries, and an
.galpre:                              ; inverse table is one more thing to
    mov ax, [sh_gal_map + bx]         ; keep in step
    cmp ax, [ch_type]
    je .galprefound
    add bx, 2
    loop .galpre
    xor bx, bx
.galprefound:
    shr bx, 1
    mov [sh_fdlg_sel], bx
    jmp .noprefill
.prefillcalc:
    xor ah, ah
    mov al, [sh_calcmode]
    mov [sh_fdlg_sel], ax
    jmp .noprefill
.cellpre:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    SHOUT sh_findcell
    jnc .noprefill
    push es
    mov es, [sh_cellseg]
    mov al, [es:di+5]
    pop es
    mov ah, 0
    cmp byte [sh_fdlg_kind], 0
    je .pfnum
    cmp byte [sh_fdlg_kind], 1
    je .pfalign
    and al, 0x03                      ; Font: bits0-1 directly
    jmp .havesel
.pfnum:
    and al, SH_FMT_NUM_MASK
    mov cl, SH_FMT_NUM_SHIFT
    shr al, cl
    jmp .havesel
.pfalign:
    and al, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr al, cl
.havesel:
    mov [sh_fdlg_sel], ax
    jmp .noprefill
.noprefill:
    mov bl, [sh_fdlg_kind]
    xor bh, bh
    shl bx, 1
    mov ax, [sh_fdlg_titles + bx]
    mov [sh_fdlg_tpl + WT_TITLE], ax
    ; 81.115: THIS KIND'S OWN HEIGHT, patched the way WT_X and WT_Y below
    ; already are - the box is as tall as the rows it holds, unless the two
    ; stacked buttons beside it need more.
    mov ax, [sh_fdlg_count]
    mov cl, 4                         ; * SH_FDLG_ROWH; CX is this routine's
    shl ax, cl                        ; own (pushed above), DX is not
    add ax, SH_FDLG_ROWTOP + 4
    cmp ax, SH_FDLG_BTBOT
    jae .tallenough
    mov ax, SH_FDLG_BTBOT
.tallenough:
    add ax, SH_DLG_BMARG + TITLE_H + 1
    mov [sh_fdlg_tpl + WT_H], ax
    call OSAPI_VIDEO                  ; centre on the LIVE screen, the same
    sub ax, SH_FDLG_W                 ; way os88ui_ask does (apps/os88ui.inc)
    sar ax, 1
    mov [sh_fdlg_tpl + WT_X], ax
    sub bx, [sh_fdlg_tpl + WT_H]
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .placed
    mov bx, MBAR_H + 8                ; never under the menu bar
.placed:
    mov [sh_fdlg_tpl + WT_Y], bx
    mov si, sh_fdlg_tpl
    call OSAPI_WM_CREATE
    jc .out
    mov [sh_fdlg_win], bx
    push ax                           ; a FIXED layout, taller than a CGA's
    mov al, 1                         ; 155-row desktop band: wm_fit cut it
    call OSAPI_WM_KEEPH               ; and the buttons drew through the frame,
    pop ax                            ; below the window and past its clicks.
                                      ; Hang over the dock instead (SPEC.md
                                      ; 11.93, 81.100) - 28 + 171 still fits
                                      ; the 200 rows the display has
    call OSAPI_WM_SHOW
    SHOUT sh_btfix                     ; the gesture (81.111), from here
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_fdlg_paint - SI = the dialog window. Uses bss scratch (sh_fdlg_ox/oy/
; itemsptr/rowidx/rowy) rather than stack juggling to hold state across the
; os88ui_glyph/OSAPI_FONT_RUN calls, since both take CX/DX as their own
; position input - a register-only approach would need constant reshuffling
; for no real benefit here (this paints at most once per click).
; -----------------------------------------------------------------------------
sh_fdlg_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si                         ; OSAPI_WM_CONTENT wants BX=window
    call OSAPI_WM_CONTENT              ; -> ax=content x, dx=content y
    mov [sh_fdlg_ox], ax
    mov [sh_fdlg_oy], dx
    mov bl, [sh_fdlg_kind]
    xor bh, bh
    shl bx, 1
    mov si, [sh_fdlg_items + bx]
    mov [sh_fdlg_itemsptr], si

    ; --- 81.115: the group box, and its label BREAKING the top edge.
    ; The title is on the window's title bar as well, and Excel repeats it
    ; here - that repetition is the group box's whole grammar, naming what the
    ; choices inside it are about.
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_fdlg_ox]
    add ax, SH_FDLG_GX1
    mov cx, [sh_fdlg_ox]
    add cx, SH_FDLG_GX2
    mov bx, [sh_fdlg_oy]
    add bx, SH_FDLG_GY1
    mov dx, [sh_fdlg_count]           ; as tall as THIS kind's rows
    push cx
    mov cl, 4                         ; * SH_FDLG_ROWH, without touching DX's
    shl dx, cl                        ; neighbour: `mul` would spend AX, which
    pop cx                            ; is the box's left edge
    add dx, bx
    add dx, SH_FDLG_ROWTOP - SH_FDLG_GY1 + 4
    call OSAPI_GFX_FRAME

    ; ONE OPAQUE font_run, not sh_bdlg's FONT_WIDTH + GFX_FILL + transparent
    ; string (SPEC.md 6.1, 6.6): the run paints its own cells' ground, which
    ; is exactly the erase that breaks the line - the frame passes through the
    ; middle of an 8-tall cell placed at GY1 - 4. Three calls become one, and
    ; no new site joins tests/textsites.txt's ratchet.
    mov bl, [sh_fdlg_kind]
    xor bh, bh
    shl bx, 1
    mov si, [sh_fdlg_titles + bx]
    mov cx, [sh_fdlg_ox]
    add cx, SH_FDLG_GX1 + 8
    mov dx, [sh_fdlg_oy]
    add dx, SH_FDLG_GY1 - 4
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN

    mov word [sh_fdlg_rowidx], 0
.rowloop:
    mov cx, [sh_fdlg_rowidx]
    cmp cx, [sh_fdlg_count]
    jae .rowsdone
    mov ax, cx
    mov bx, SH_FDLG_ROWH
    mul bx
    add ax, SH_FDLG_ROWTOP
    add ax, [sh_fdlg_oy]
    mov [sh_fdlg_rowy], ax
    mov ax, [sh_fdlg_sel]
    cmp ax, [sh_fdlg_rowidx]
    mov al, OS88UI_GRADIO
    jne .goff
    or al, OS88UI_GON
.goff:
    mov ah, 0
    mov cx, [sh_fdlg_ox]
    add cx, SH_FDLG_GX1 + 8             ; 81.115: inside the group box now
    mov dx, [sh_fdlg_rowy]
    SHOUT os88ui_glyph                  ; preserves all registers (its own doc)
    mov si, [sh_fdlg_itemsptr]
    mov bx, [sh_fdlg_rowidx]
    shl bx, 1
    add si, bx
    mov si, [si]                       ; si = this row's label string
    mov cx, [sh_fdlg_ox]
    add cx, SH_FDLG_GX1 + 24            ; 81.115: ...and so is its label
    mov dx, [sh_fdlg_rowy]
    add dx, 2
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN
    mov ax, [sh_fdlg_rowidx]
    inc ax
    mov [sh_fdlg_rowidx], ax
    jmp .rowloop
.rowsdone:
    ; 81.111: OK then Cancel, CONTIGUOUS in the record's own array and drawn
    ; by index - the library owns the pressed look. 81.115 moved them from a
    ; row along the bottom to a STACKED COLUMN at the top right, which is both
    ; Excel's shape and sh_bdlg's. The rects are what the click half and
    ; tests/sheetfmt.py's fdlg_ok both read, so neither needs telling.
    mov ax, [sh_fdlg_ox]
    add ax, SH_FDLG_BTX
    mov [sh_fdlg_btrects], ax          ; OK x1
    mov [sh_fdlg_btrects+8], ax        ; ...and Cancel's, the same column
    add ax, SH_FDLG_BTW
    mov [sh_fdlg_btrects+4], ax        ; OK x2
    mov [sh_fdlg_btrects+12], ax
    mov ax, [sh_fdlg_oy]
    add ax, SH_FDLG_GY1                ; level with the box's top edge
    mov [sh_fdlg_btrects+2], ax
    add ax, SH_FDLG_BTH
    mov [sh_fdlg_btrects+6], ax
    add ax, SH_FDLG_BTGAP
    mov [sh_fdlg_btrects+10], ax
    add ax, SH_FDLG_BTH
    mov [sh_fdlg_btrects+14], ax
    mov bx, sh_fdlg_btrec
    mov al, 1
    SHOUT os88ui_btn
    mov al, 2
    SHOUT os88ui_btn
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_fdlg_onclick - in: CX=x, DX=y (screen-absolute, same convention as
; sh_onclick), SI=the dialog window
; -----------------------------------------------------------------------------
sh_fdlg_onclick:
    push ax
    push bx
    push si
    push di
    push cx
    push dx
    mov bx, si
    call OSAPI_WM_CONTENT              ; -> ax=content x, dx=content y
    pop bx
    sub bx, dx                         ; bx = click y, content-relative
    pop cx
    sub cx, ax                         ; cx = click x, content-relative
                                       ; (81.111: a press on OK or Cancel
                                       ; never reaches here - the library's
                                       ; gesture takes it, sh_fdlg_onbtn acts)
.checkrows:
    cmp cx, SH_FDLG_GX1 + 8            ; 81.115: the rows moved INSIDE the
    jb .out                            ; group box, so its left edge moved too
    cmp cx, SH_FDLG_GX2                ; ...and a click to the RIGHT of the box
    ja .out                            ; is the button column's, not a row's
    cmp bx, SH_FDLG_ROWTOP
    jb .out
    mov ax, bx
    sub ax, SH_FDLG_ROWTOP
    xor dx, dx
    mov si, SH_FDLG_ROWH
    div si                             ; ax = row index
    cmp ax, [sh_fdlg_count]
    jae .out
    mov [sh_fdlg_sel], ax
    mov si, [sh_fdlg_win]
    call sh_fdlg_paint
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret

; sh_fdlg_onbtn - AL = the button that FIRED on the release (81.111): 1 OK,
; 2 Cancel. What sh_fdlg_onclick used to do on the PRESS
sh_fdlg_onbtn:
    push ax
    push si
    cmp al, 1
    jne .cancel
    call sh_fdlg_apply
    call sh_fdlg_close
    cmp byte [sh_savepend], 0         ; File Format's OK owes a Save As, and it
    je .out                           ; runs only now that the format dialog's
    mov byte [sh_savepend], 0         ; window is DESTROYED. Opening the file
    mov si, [sh_ownwin]               ; dialog from inside apply would stack a
    mov al, FDLG_SAVE                 ; second dialog on a window slot that is
    SHOUT sh_dlg                       ; still in use, which is how one gets
    jmp short .out                    ; orphaned behind the other
.cancel:
    call sh_fdlg_close
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_setext - in: SI -> a 4-byte ".XXX". Replaces [sh_name]'s extension, or
; appends one if it has none, so picking a format in the Save As dialog
; renames BUDGET.SLK to BUDGET.BIF rather than leaving the name disagreeing
; with the bytes. sh_dowrite still decides by extension - this makes the
; extension follow the CHOICE instead of the other way round.
;
; sh_name is 13 bytes and holds an 8.3 name, so the worst case (an 8-char
; stem with no dot) writes 8+4+1 = 13. Nothing longer can arrive: the file
; dialog is what fills this buffer and it enforces 8.3.
; -----------------------------------------------------------------------------
sh_setext:
    push ax
    push cx
    push si
    push di
    mov di, sh_name
    xor cx, cx                        ; cx = where the '.' is, 0 = none yet
.scan:
    mov al, [di]
    or al, al
    jz .atend
    cmp al, '.'
    jne .next
    mov cx, di
.next:
    inc di
    jmp .scan
.atend:
    or cx, cx
    jz .append                        ; no extension: write one on the end
    mov di, cx                        ; there is one: overwrite from the '.'
.append:
    mov cx, 4
.cp:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    loop .cp
    mov byte [di], 0
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_clear_one - Clear's work for ONE cell, by [sh_fdlg_sel]: 0 All /
; 1 Formulas / 2 Formats. "Formulas" is Excel's word for the CONTENTS - a cell
; cleared that way keeps its border, its number format and its font, which is
; the whole reason the dialog exists - and a cell with nothing of that kind
; to keep goes altogether. in: AX = col, BX = row. Preserves all.
; -----------------------------------------------------------------------------
sh_clear_one:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push di
    push es
    cmp word [sh_fdlg_sel], 2
    je .fmt
    cmp word [sh_fdlg_sel], 1
    je .contents
    SHOUT sh_clearcell                 ; All: the record goes, border and all
    SHOUT sh_bt_removecell             ; (sh_clearcell preserves AX/BX)
    jmp .out
.contents:
    push ax                           ; NOTHING TO KEEP - no border, no number
    SHOUT sh_bt_getw                   ; format beyond the four, no format byte:
    or ax, ax                         ; then the contents going leave no cell
    pop ax                            ; at all, as All's do, rather than a
    jnz .keep                         ; zero where Excel shows nothing (81.63)
    SHOUT sh_findcell
    jnc .out
    mov es, [sh_cellseg]
    cmp byte [es:di+5], 0
    jne .keep2
    SHOUT sh_clearcell
    jmp .out
.keep:
    SHOUT sh_findcell
    jnc .out
    mov es, [sh_cellseg]
.keep2:
    mov byte [es:di+4], 0             ; not a formula any more...
    mov byte [es:di+SH_C_TYPE], SH_T_NUM
    mov word [es:di+SH_C_VAL], 0      ; ...and zero, but the format byte at
    mov word [es:di+SH_C_VAL+2], 0    ; +5 is deliberately untouched
    mov word [es:di+SH_C_VAL+4], 0
    mov word [es:di+SH_C_VAL+6], 0
    mov word [es:di+SH_C_PASS], 0
    jmp .out
.fmt:
    SHOUT sh_findcell
    jnc .fmtbord                      ; no CELL record is no reason to leave
    mov es, [sh_cellseg]              ; the border table alone
    mov byte [es:di+5], 0             ; Formats: the format byte...
.fmtbord:
    ; ...AND THE BORDER RECORD'S FORMAT HALF, BUT NOT THE WHOLE RECORD. This
    ; was a plain sh_bt_removecell, which takes everything stored for the
    ; cell - so Clear > Formats reset Locked/Hidden to the default, which is
    ; an 81.46 defect older than this feature, and once 81.114.7 put the
    ; table mark in the same byte it UN-PROTECTED a table's result cells
    ; while leaving the table itself recorded. The edges, the shade and the
    ; number format are what Formats means; SH_BT_KEEP's three bits are not,
    ; and the record goes only when nothing is left in it - which is
    ; sh_bdlg_apbord's own .clearit, exactly.
    push ax
    push bx
    SHOUT sh_bt_findcell
    jnc .fmtdone
    push es
    mov es, [sh_bordseg]
    and byte [es:di+4], SH_BT_KEEP
    mov byte [es:di+5], 0             ; the number format too (81.55)
    mov al, [es:di+4]
    pop es
    or al, al
    jnz .fmtdone
    pop bx
    pop ax
    SHOUT sh_bt_removecell            ; nothing left: the record goes after all
    jmp .out
.fmtdone:
    pop bx
    pop ax
.out:
    pop es
    pop di
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_fmt_one - apply the format dialog's current choice to ONE cell.
; in: AX = col, BX = row. An empty cell has no record to carry a format and is
; skipped, which is what the single-cell version did too. Preserves all.
; -----------------------------------------------------------------------------
sh_fmt_one:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push di
    push es
    SHOUT sh_findcell
    jnc .out
    mov es, [sh_cellseg]
    mov bl, [es:di+5]
    mov al, [sh_fdlg_sel]
    cmp byte [sh_fdlg_kind], 0
    je .num
    cmp byte [sh_fdlg_kind], 1
    je .align
    and bl, SH_FMT_BU_CLR              ; Font: bits0-1 directly
    or bl, al
    jmp .put
.num:
    and bl, SH_FMT_NUM_CLR
    mov cl, SH_FMT_NUM_SHIFT
    shl al, cl
    or bl, al
    jmp .put
.align:
    and bl, SH_FMT_ALIGN_CLR
    mov cl, SH_FMT_ALIGN_SHIFT
    shl al, cl
    or bl, al
.put:
    mov [es:di+5], bl
.out:
    pop es
    pop di
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_fdlg_apply - kinds 0-2 (Number/Alignment/Font): write [sh_fdlg_sel]
; into the selected cell's format byte, in the field [sh_fdlg_kind] names -
; a no-op if the cell has no record (see sh_fdlg_open's own comment on
; that scope limit). Kinds 3-4 (Insert/Delete): [sh_fdlg_sel] is 0 Row / 1
; Column, so hand off to sh_rowcol_op with the selected cell's own row or
; column as the pivot index - these have no "cell must have a record"
; limit, since they act on the grid's structure, not a cell's content.
; -----------------------------------------------------------------------------
sh_fdlg_apply:
    ; UNDO AT OK, NOT AT THE MENU (81.57): a dialog the user cancels changes
    ; nothing, so nothing is snapshot for it. sh_ud_kind says, per kind, the
    ; action's label, or that it ends Undo (a format, New), or neither
    push ax
    push bx
    mov bl, [sh_fdlg_kind]
    xor bh, bh
    cmp bx, SH_FDK_N
    jae .ukeep
    mov al, [sh_ud_kind + bx]
    cmp al, SH_UL_KEEP
    je .ukeep
    cmp al, SH_UL_DROP
    jne .usnap
    SHOUT sh_undo_drop
    jmp short .ukeep
.usnap:
    SHOUT sh_undo_begin
.ukeep:
    pop bx
    pop ax
    call sh_fdlg_apply0
    SHOUT sh_undo_end                  ; 81.74.2: a tail JUMP would enter a
    ret                                ; resident body with no far frame

sh_fdlg_apply0:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    cmp byte [sh_fdlg_kind], SH_FDK_CLEAR
    je .doclear
    cmp byte [sh_fdlg_kind], SH_FDK_NEW
    je .donew
    cmp byte [sh_fdlg_kind], SH_FDK_CALC
    je .docalc
    cmp byte [sh_fdlg_kind], SH_FDK_SORT
    je .dosort
    cmp byte [sh_fdlg_kind], SH_FDK_GAL
    je .dogallery
    cmp byte [sh_fdlg_kind], SH_FDK_SAVEFMT
    je .dosavefmt
    cmp byte [sh_fdlg_kind], SH_FDK_PSPEC
    je .dopspec
    cmp byte [sh_fdlg_kind], SH_FDK_PROT
    je .doprot
    cmp byte [sh_fdlg_kind], SH_FDK_EXTRACT
    je .doextract
    cmp byte [sh_fdlg_kind], SH_FDK_SERIES
    je .doseries
    cmp byte [sh_fdlg_kind], 3
    je .insertrc
    cmp byte [sh_fdlg_kind], 4
    je .deleterc
    ; Number/Alignment/Font apply to the WHOLE SELECTION. They used to read
    ; sh_selcol/sh_selrow and format the anchor alone, so selecting a column
    ; of figures and choosing Currency changed exactly one cell - the same
    ; thing Fill Right/Down did before 81.13, and for the same reason: written
    ; before range selection existed and never taught about sh_selcol2/
    ; sh_selrow2. A single-cell selection is a 1x1 range, so it still works.
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .fmtrows
    xchg ax, bx
.fmtrows:                              ; ax = top row, bx = bottom row
    mov cx, [sh_selcol]
    mov si, [sh_selcol2]
    cmp cx, si
    jbe .fmtcols
    xchg cx, si
.fmtcols:                              ; cx = first col, si = last col
.fmtcolloop:
    mov di, ax                         ; di = the current row, from the top
.fmtrowloop:
    push ax
    push bx
    mov ax, cx
    mov bx, di
    call sh_fmt_one
    pop bx
    pop ax
    inc di
    cmp di, bx
    jbe .fmtrowloop
    inc cx
    cmp cx, si
    jbe .fmtcolloop
    mov si, [sh_ownwin]                ; SI WAS THE LAST COLUMN: sh_repaint
    SHOUT sh_repaint                    ; takes the window there, and got a
    jmp .out                           ; column index - a ghost of the sheet
                                       ; drawn at a garbage origin, which a
                                       ; dialog's own close repaint covered
                                       ; and a macro's FORMAT.* did not (81.88)
.insertrc:
    cmp byte [sh_protected], 0        ; a structure change is refused for the
    jne .protdoc                      ; WHOLE document, not per cell: inserting

    cmp word [sh_fdlg_sel], 0
    jne .inscol
    mov al, 0                          ; op 0 = insert row
    mov bx, [sh_selrow]
    jmp .rcgo
.inscol:
    mov al, 2                          ; op 2 = insert column
    mov bx, [sh_selcol]
    jmp .rcgo
.deleterc:
    cmp byte [sh_protected], 0        ; a row moves locked cells it does not
    jne .protdoc                      ; name, so there is no cell to ask about

    cmp word [sh_fdlg_sel], 0
    jne .delcol
    mov al, 1                          ; op 1 = delete row
    mov bx, [sh_selrow]
    jmp .rcgo
.delcol:
    mov al, 3                          ; op 3 = delete column
    mov bx, [sh_selcol]
.rcgo:
    SHOUT sh_rowcol_op
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    jmp .out

; --- stage 3.0c: the four that used to be immediate menu commands -----------
.doclear:
    mov byte [sh_prot_clr], 1         ; 81.114.7: a result cell reaches the
    SHOUT sh_prot_blocked             ; guard below instead of being refused
    jc .refused                       ; ...and the same here: this engine's
    push si                           ; 81.74: CLEAR() takes no argument here,
    mov si, sh_s_rec_clear            ; so the three radio modes all record as
    SHOUT sh_rec_cmd                   ; the one the language has
    pop si
                                      ; .out does not repaint either
    call sh_tbl_clearguard            ; 81.114.7: all of a table or none of
    jc .refused                       ; it - Excel's "You must clear all the
                                      ; resulting values", and a cover that
                                      ; is whole DROPS the table in here
    ; Over the WHOLE SELECTION, like Excel's Clear and like the block the user
    ; has highlighted. It used to clear the anchor alone (81.17's third case,
    ; after Fill and the format dialogs).
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .clrows
    xchg ax, bx
.clrows:                              ; ax = top row, bx = bottom row
    mov cx, [sh_selcol]
    mov si, [sh_selcol2]
    cmp cx, si
    jbe .clcols
    xchg cx, si
.clcols:                              ; cx = first col, si = last col
.clcolloop:
    mov di, ax
.clrowloop:
    push ax
    push bx
    mov ax, cx
    mov bx, di
    call sh_clear_one
    pop bx
    pop ax
    inc di
    cmp di, bx
    jbe .clrowloop
    inc cx
    cmp cx, si
    jbe .clcolloop
.cldone:
    cmp byte [sh_calcmode], SH_CALC_AUTO  ; 81.114.8: a clear does not go
    jne .clnorec                       ; through sh_commit either, and what
    call sh_tbl_runall                 ; it emptied may be another table's
.clnorec:                              ; INPUT cell. The tables this clear
                                       ; COVERED are already gone, so this
                                       ; re-runs the ones that merely read
                                       ; what it took away
    mov si, [sh_ownwin]               ; ONE repaint for the block
    SHOUT sh_repaint
    jmp .out

.donew:
    ; Excel asks which KIND of new document. This app has one grid type, so
    ; Chart and Macro Sheet do the honest thing rather than the flattering
    ; one: a new sheet, and a status line saying what was actually made.
    SHOUT sh_new
    mov word [sh_msg], sh_s_nw_sheet
    cmp word [sh_fdlg_sel], 1
    jne .nwnotchart
    mov word [sh_msg], sh_s_nw_chart
.nwnotchart:
    cmp word [sh_fdlg_sel], 2
    jne .nwdone
    mov word [sh_msg], sh_s_nw_macro
    call sh_macsheet                  ; 81.97: a macro sheet is a KIND now
.nwdone:
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    jmp .out

.docalc:
    ; 0 Automatic / 1 Automatic except Tables / 2 Manual / 3 Calculate Now.
    ; Manual is not a no-op with a label on it: sh_drawgrid re-evaluates every
    ; formula cell on every repaint, so switching it off is what a big sheet
    ; on a 4.77MHz 8088 actually needs, and Calculate Now is then the only
    ; way to catch up. The MIDDLE one is 81.114.8's, and it is the mode a
    ; machine this slow wants the moment a table exists.
    cmp word [sh_fdlg_sel], SH_CALC_NOWROW
    je .calcnow
    mov ax, [sh_fdlg_sel]
    mov [sh_calcmode], al
    mov word [sh_msg], sh_s_calc_auto
    or al, al
    jz .calcrepaint
    mov word [sh_msg], sh_s_calc_auex
    cmp al, SH_CALC_MANUAL
    jb .calcrepaint
    mov word [sh_msg], sh_s_calc_man
    jmp .calcrepaint
.calcnow:
    ; THE SAME COMMAND AS Options > Calculate Now (81.78), and deliberately
    ; NOT sh_calc_now, which is where the resident copy of these four lines
    ; lives. This arm is in the MODULE, and a module reaches resident code
    ; only through the sh_v_* vector table - which is filled POSITIONALLY
    ; from a parallel `dw sh_x_*` list with nothing gating that the two agree.
    ; A slot appended to one and not the other is a far call to the wrong
    ; routine, silently; four duplicated lines are the cheaper risk. Change
    ; one and change the other.
    inc word [sh_pass]                ; a pass stamp nothing has cached, which
    call sh_tbl_runall                ; 81.114.8 - and THIS copy calls the
                                      ; module's own routine directly, being
                                      ; already inside it
    mov word [sh_msg], sh_s_calc_now  ; is exactly what forces the recompute
    push si                           ; 81.74
    mov si, sh_s_rec_calc
    SHOUT sh_rec_cmd
    pop si
.calcrepaint:
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    jmp .out

.dosort:
    mov ax, [sh_fdlg_sel]
    mov [sh_sort_desc], al
    call sh_docmd_sortcol
    jmp .out
.dogallery:
    mov bx, [sh_fdlg_sel]
    shl bx, 1
    mov ax, [sh_gal_map + bx]
    mov [ch_type], ax
    cmp word [sh_chartwin], 0         ; no chart window yet: the type is still
    je .galdone                       ; remembered, and the next Chart Column
    mov byte [sh_chartdirty], 1       ; uses it. A RESCAN, not a re-render:
.galdone:                             ; the pulldown that opened this dialog
                                      ; banked its pixels over the staged
                                      ; values (sh_mbank), so sh_repaint's
                                      ; hook re-reads them, renders, paints
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    jmp .out
.doprot:
    xor dl, dl                         ; 0 Locked is the default and stores no
    mov ax, [sh_fdlg_sel]              ; bits at all, so a sheet nobody has
    test al, 1                         ; touched is entirely locked
    jz .prot1
    mov dl, SH_PROT_UNLOCK
.prot1:
    test al, 2
    jz .prot2
    or dl, SH_PROT_HIDDEN
.prot2:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    or dl, dl
    jz .protclear
    SHOUT sh_bt_addcell
    jc .out                            ; table full: silent, as everywhere
    push es                            ; else that writes this table
    mov es, [sh_bordseg]
    mov al, [es:di+4]
    and al, ~SH_PROT_MASK & 0xFF       ; the BORDER bits are not this dialog's
    or al, dl                          ; to write, the mirror of sh_bdlg_apply
    mov [es:di+4], al
    pop es
    jmp .protdone
.protclear:
    SHOUT sh_bt_findcell
    jnc .protdone
    push es
    mov es, [sh_bordseg]
    and byte [es:di+4], ~SH_PROT_MASK & 0xFF
    mov ax, [es:di+4]                  ; ...and the number format beside it
    pop es                             ; (81.55): the record stays while
    or ax, ax                          ; either byte holds anything
    jnz .protdone                      ; a border is still stored here
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    SHOUT sh_bt_removecell
.protdone:
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    jmp .out
.protdoc:
    mov word [sh_msg], sh_s_protdoc
.refused:
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    jmp .out
.doseries:                            ; 81.72: the radio IS the type, and
    mov al, [sh_fdlg_sel]             ; part TWO of the question follows it -
    mov [sh_ser_type], al             ; Sort's own two-dialog shape (81.15),
    mov al, SH_ID_SERSTEP             ; because no engine here has a radio
    call sh_idlg_open                 ; column AND a text field
    jmp .out
.doextract:                           ; 81.71: the radio IS the flag
    mov al, [sh_fdlg_sel]
    mov [sh_dbc_uniq], al
    mov al, SH_DBC_EXTRACT
    SHOUT sh_docmd_dbrun
    jnc .out                          ; refused: the status line says why
    SHOUT sh_recalc_all                ; the extract range holds new values
    jmp .out
.dopspec:
    mov al, [sh_fdlg_sel]             ; the radio IS the mode: All/Formulas/
    mov [sh_ps_mode], al              ; Values/Formats/Notes are SH_PS_ALL..
    SHOUT sh_docmd_paste               ; SH_PS_NOTE in that order, on purpose
    jmp .out
.dosavefmt:
    mov si, sh_s_ext_biff             ; 0 Normal is this app's OWN format,
    mov ax, [sh_fdlg_sel]             ; which is BIFF - the same thing
    or ax, ax                         ; Excel means by "Normal"
    jz .fmtset
    mov si, sh_s_ext_sylk
    cmp ax, 1
    je .fmtset
    mov si, sh_s_ext_dif
    cmp ax, 2
    je .fmtset
    mov si, sh_s_ext_csv
    cmp ax, 3
    je .fmtset
    mov si, sh_s_ext_txt
    cmp ax, 4
    je .fmtset
    mov si, sh_s_ext_dbf
.fmtset:
    call sh_setext
    mov byte [sh_savepend], 1         ; the file dialog cannot open until
    jmp .out                          ; THIS one is destroyed - see .doOK

.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_fdlg_close
; -----------------------------------------------------------------------------
sh_fdlg_close:
    push ax
    push bx
    mov bx, [sh_fdlg_win]
    or bx, bx
    jz .out
    mov word [sh_fdlg_win], 0
    call OSAPI_WM_DESTROY               ; NOT OSAPI_WM_CLOSE. Close means
                                        ; "quit the instance owning this
                                        ; window" (app_close_win); a dialog
                                        ; has no owning instance, so that path
                                        ; falls through to a plain wm_hide -
                                        ; the pixels go but THE SLOT STAYS
                                        ; USED. MAX_WIN is 12, so ten dialogs
                                        ; into a session no dialog would open
                                        ; again, in this app or any other.
                                        ; os88api.inc names this exact case:
                                        ; the unowned species is "a driver's
                                        ; windows, and a package's second one".
                                        ; The gfx lock is already held - every
                                        ; callback holds it - which is what
                                        ; DESTROY wants (os88ui_adone does the
                                        ; same, gate first then destroy).
.out:
    pop bx
    pop ax
    ret

; =============================================================================
; Border dialog (stage 2.x). Real Excel 2.1's Format > Border... is a
; "Border" GROUP BOX holding six independent CHECKBOXES (Outline/Left/
; Right/Top/Bottom/Shade) with OK/Cancel standing beside it, not below it
; (LIBRARY/documentation/screenshots/excel/dialog_border.png) - a
; materially different shape from
; Number/Alignment/Font's single-choice radio lists, so it gets its own
; small engine rather than being forced into sh_fdlg_*'s. "Outline" is
; UI-only: checking it sets all four edges at once and unchecking it clears
; all four, matching real Excel's own behavior - there is no stored
; "outline" bit separate from the four edges themselves, so re-opening the
; dialog on a cell that has all four set shows Outline checked too, purely
; because sh_bdlg_open recomputes it from them.
; =============================================================================
SH_BDLG_W      equ 190
SH_BDLG_GX1    equ 10                ; the "Border" group box, inset from
SH_BDLG_GY1    equ 12                ; the dialog's own content origin
SH_BDLG_GX2    equ 104
SH_BDLG_GY2    equ 132                ; the LOWEST element here, so the height
SH_BDLG_H      equ SH_BDLG_GY2 + SH_DLG_BMARG + TITLE_H + 1
                                     ; comes from it. At a flat 150 the content
                                     ; was 131 tall and this line sat at 132 -
                                     ; the group box's bottom edge was one
                                     ; pixel outside the window
SH_BDLG_BTNBOT equ 70                ; 81.106: Cancel's bottom edge - the
                                     ; floor of a short kind's height
SH_BDLG_ROWTOP equ 26                ; first checkbox row, and OK/Cancel
SH_BDLG_ROWH   equ 18                ; both measured from the SAME origin
SH_BDLG_NITEMS equ 6

SH_BK_BORDER    equ 0                ; 81.106: the check-box engine's KINDS -
SH_BK_DISPLAY   equ 1                ; Excel's three dialogs of this shape:
SH_BK_WORKSPACE equ 2                ; a titled group of independent boxes,
SH_BK_N         equ 3                ; OK/Cancel stacked beside it
SH_BDLG_B_OUTLINE equ 0x01           ; the dialog's own 6-bit UI state -
SH_BDLG_B_LEFT    equ 0x02           ; bits 1-4 line up with SH_BORD_LEFT..
SH_BDLG_B_RIGHT   equ 0x04           ; SH_BORD_BOTTOM shifted up by one (to
SH_BDLG_B_TOP     equ 0x08           ; make room for Outline at bit 0) and
SH_BDLG_B_BOTTOM  equ 0x10           ; bit 5 lines up with SH_BORD_SHADE the
SH_BDLG_B_SHADE   equ 0x20           ; same way - see sh_bdlg_open/_apply

section .text


sh_bdlg_tpl:
    dw 0, 0, SH_BDLG_W, SH_BDLG_H
    dw sh_s_bdlg_title, sh_bdlg_paint_r, 0, sh_bdlg_click_r

sh_s_bdlg_title: db 'Border', 0
sh_bdlg_items: dw sh_bdlg_i0, sh_bdlg_i1, sh_bdlg_i2, sh_bdlg_i3, sh_bdlg_i4, sh_bdlg_i5
; 81.106: per KIND - the title (which is the group box's label too, as in
; Excel's Display dialog), the item list and its length. Resident, because
; the module reads them through DS and the kernel reads the title
sh_bdlg_ktitle: dw sh_s_bdlg_title, sh_s_disp_title, sh_s_ws_title
sh_bdlg_kitems: dw sh_bdlg_items, sh_disp_items, sh_ws_items
sh_bdlg_kn:     db SH_BDLG_NITEMS, 2, 1
sh_s_disp_title: db 'Display', 0
sh_disp_items:  dw sh_disp_i0, sh_disp_i1
sh_disp_i0:     db 'Formulas', 0           ; Excel's order: Formulas first
sh_disp_i1:     db 'Gridlines', 0
sh_s_ws_title:  db 'Workspace', 0
sh_ws_items:    dw sh_ws_i0
sh_ws_i0:       db 'R1C1', 0
sh_bdlg_i0:    db 'Outline', 0
sh_bdlg_i1:    db 'Left', 0
sh_bdlg_i2:    db 'Right', 0
sh_bdlg_i3:    db 'Top', 0
sh_bdlg_i4:    db 'Bottom', 0
sh_bdlg_i5:    db 'Shade', 0

; the resident thunks (81.71.5.1) - sh_bdlg_open_r is the menu's, and it is
; what forces CHART.OVL in before any window exists, so neither callback can
; be the call that has to read a disk
    SH_BTREC bdlg, 2, sh_dlg_blfd           ; 81.111
    SH_BTDOORS bdlg, SHM_BDBTN
sh_bdlg_open_r:
    push bp
    mov bp, SHM_BOPEN
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_noovl
    push si
    mov si, [sh_ownwin]
    call sh_repaint
    pop si
.out:
    ret
sh_bdlg_paint_r:
    push bp
    mov bp, SHM_BPAINT
    call ch_ovcall
    pop bp
    ret
sh_bdlg_click_r:
    push bp
    mov bp, SHM_BCLICK
    call ch_ovcall
    pop bp
    ret
sh_bdlg_close_r:                       ; the gate-lock recovery's own door
    push bp
    mov bp, SHM_BCLOSE
    call ch_ovcall
    pop bp
    ret
; --- in CHART.OVL (81.71.5.1), Data ▸ Form's own reason: a dialog nobody
; opens twice a session was 900 bytes of a package with 46 to spare. Its
; data stays resident because the kernel and os88ui both read it through
; DS, and sh_bdlg_open_r forces the module in before the window exists.
section SH_MODSEC                      ; 81.71.5.1: the Border dialog

; -----------------------------------------------------------------------------
; sh_bdlg_open - preselect from what the SELECTION already has (sh_bdlg_walk's
; GATHER, 81.17.2: a single cell is its stored byte); a cell with no border
; record at all reads back as 0, same "dialog still opens, OK on it is just a
; no-op" scope as sh_fdlg_open's.
; -----------------------------------------------------------------------------
sh_bdlg_open:                          ; AL = SH_BK_* (81.106)
    push ax
    push bx
    push si
    cmp word [sh_bdlg_win], 0
    jne .out
    cmp al, SH_BK_N
    jae .out
    mov [sh_bdlg_kind], al
    xor ah, ah
    mov si, ax
    shl si, 1
    mov bx, [sh_bdlg_ktitle + si]
    mov [sh_bdlg_tpl + WT_TITLE], bx
    call sh_bdlg_gy2                   ; the window's height follows the
    cmp ax, SH_BDLG_BTNBOT             ; group box, or the buttons if they
    jae .tall                          ; reach lower
    mov ax, SH_BDLG_BTNBOT
.tall:
    add ax, SH_DLG_BMARG + TITLE_H + 1
    mov [sh_bdlg_tpl + WT_H], ax
    cmp byte [sh_bdlg_kind], SH_BK_DISPLAY
    je .display
    cmp byte [sh_bdlg_kind], SH_BK_WORKSPACE
    je .workspace
    xor al, al                          ; GATHER over the selection: AL =
    call sh_bdlg_walk                   ; the bits every cell's mask holds
    mov ah, al
    and ah, 0x1F
    mov bl, ah
    shl bl, 1                          ; bl = sel bits 1-5 (L,R,T,Bot,Shade)
    and ah, SH_BORD_EDGES
    cmp ah, SH_BORD_EDGES
    jne .noout
    or bl, SH_BDLG_B_OUTLINE
.noout:
    mov [sh_bdlg_sel], bl
    jmp short .place
.display:                             ; bit 0 Formulas, bit 1 Gridlines
    mov bl, [sh_gridlines]
    shl bl, 1
    or bl, [sh_showformulas]
    mov [sh_bdlg_sel], bl
    jmp short .place
.workspace:                           ; bit 0 R1C1
    mov bl, [sh_a1style]
    mov [sh_bdlg_sel], bl
.place:
    call OSAPI_VIDEO
    sub ax, SH_BDLG_W
    sar ax, 1
    mov [sh_bdlg_tpl + WT_X], ax
    sub bx, SH_BDLG_H
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .placed
    mov bx, MBAR_H + 8
.placed:
    mov [sh_bdlg_tpl + WT_Y], bx
    mov si, sh_bdlg_tpl
    call OSAPI_WM_CREATE
    jc .out
    mov [sh_bdlg_win], bx
    push ax                           ; over the dock rather than cut on a
    mov al, 1                         ; CGA - sh_fdlg_open's reason (81.100)
    call OSAPI_WM_KEEPH
    pop ax
    call OSAPI_WM_SHOW
    SHOUT sh_btfix                     ; the gesture (81.111), from here
.out:
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_bdlg_paint - SI = the dialog window
; -----------------------------------------------------------------------------
sh_bdlg_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si
    call OSAPI_WM_CONTENT
    mov [sh_bdlg_ox], ax
    mov [sh_bdlg_oy], dx
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_bdlg_ox]
    add ax, SH_BDLG_GX1
    mov bx, [sh_bdlg_oy]
    add bx, SH_BDLG_GY1
    mov cx, [sh_bdlg_ox]
    add cx, SH_BDLG_GX2
    push ax
    call sh_bdlg_gy2                    ; 81.106: as tall as this kind's rows
    mov dx, ax
    pop ax
    add dx, [sh_bdlg_oy]
    call OSAPI_GFX_FRAME                ; the group box itself
    mov al, CWHITE
    call OSAPI_SET_COLOR
    call sh_bdlg_label                  ; 81.106: SI = this kind's title
    call OSAPI_FONT_WIDTH
    mov cx, ax                          ; the gap is the label's width + 4
    mov ax, [sh_bdlg_ox]
    add ax, SH_BDLG_GX1 + 6
    mov bx, [sh_bdlg_oy]
    add bx, SH_BDLG_GY1 - 3
    add cx, ax
    add cx, 3
    mov dx, bx
    add dx, 7
    call OSAPI_GFX_FILL                 ; erase the frame line behind the
                                         ; label, so it "breaks" the box top
                                         ; the way a real GUI group box does
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov cx, [sh_bdlg_ox]
    add cx, SH_BDLG_GX1 + 8
    mov dx, [sh_bdlg_oy]
    add dx, SH_BDLG_GY1 - 4
    call sh_bdlg_label
    call OSAPI_FONT_STR_XPARENT
    mov word [sh_bdlg_ri], 0
.rowloop:
    call sh_bdlg_count                  ; 81.106: AX = this kind's rows
    cmp [sh_bdlg_ri], ax
    jae .rowsdone
    mov ax, [sh_bdlg_ri]
    mov bx, SH_BDLG_ROWH
    mul bx
    add ax, SH_BDLG_ROWTOP
    add ax, [sh_bdlg_oy]
    mov [sh_bdlg_ry], ax
    mov al, OS88UI_GCHECK
    mov bh, 1
    mov cl, byte [sh_bdlg_ri]
    shl bh, cl
    test bh, [sh_bdlg_sel]
    jz .off
    or al, OS88UI_GON
.off:
    mov ah, 0
    mov cx, [sh_bdlg_ox]
    add cx, SH_BDLG_GX1 + 8
    mov dx, [sh_bdlg_ry]
    SHOUT os88ui_glyph
    mov bl, [sh_bdlg_kind]
    xor bh, bh
    shl bx, 1
    mov si, [sh_bdlg_kitems + bx]
    mov bx, [sh_bdlg_ri]
    shl bx, 1
    mov si, [si + bx]
    mov cx, [sh_bdlg_ox]
    add cx, SH_BDLG_GX1 + 24
    mov dx, [sh_bdlg_ry]
    add dx, 2
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN
    mov ax, [sh_bdlg_ri]
    inc ax
    mov [sh_bdlg_ri], ax
    jmp .rowloop
.rowsdone:
    mov ax, [sh_bdlg_ox]               ; 81.111: OK over Cancel, contiguous in
    add ax, SH_BDLG_GX2 + 10           ; the record's array, drawn by index
    mov [sh_bdlg_btrects], ax
    mov [sh_bdlg_btrects+8], ax
    add ax, SH_BDLG_W - 10 - (SH_BDLG_GX2 + 10)
    mov [sh_bdlg_btrects+4], ax
    mov [sh_bdlg_btrects+12], ax
    mov ax, [sh_bdlg_oy]
    add ax, 20
    mov [sh_bdlg_btrects+2], ax
    add ax, 20
    mov [sh_bdlg_btrects+6], ax
    add ax, 10
    mov [sh_bdlg_btrects+10], ax
    add ax, 20
    mov [sh_bdlg_btrects+14], ax
    mov bx, sh_bdlg_btrec
    mov al, 1
    SHOUT os88ui_btn
    mov al, 2
    SHOUT os88ui_btn
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_bdlg_onclick - in: CX=x, DX=y (screen-absolute), SI=the dialog window
; -----------------------------------------------------------------------------
sh_bdlg_onclick:
    push ax
    push bx
    push si
    push di
    push cx
    push dx
    mov bx, si
    call OSAPI_WM_CONTENT
    pop bx
    sub bx, dx                          ; bx = click y, content-relative
    pop cx
    sub cx, ax                          ; cx = click x, content-relative
                                        ; (81.111: OK/Cancel are the
                                        ; library's gesture, sh_bdlg_onbtn)
.checkrows:
    cmp cx, SH_BDLG_GX1 + 8
    jb .out
    cmp bx, SH_BDLG_ROWTOP
    jb .out
    mov ax, bx
    sub ax, SH_BDLG_ROWTOP
    xor dx, dx
    mov si, SH_BDLG_ROWH
    div si
    push ax
    call sh_bdlg_count
    mov dx, ax
    pop ax
    cmp ax, dx
    jae .out
    mov cl, al
    mov bh, 1
    shl bh, cl
    xor [sh_bdlg_sel], bh
    cmp byte [sh_bdlg_kind], SH_BK_BORDER
    jne .redraw                         ; 81.106: Outline's coupling is the
    cmp al, 0                           ; Border's alone
    je .wasoutline
    mov al, [sh_bdlg_sel]
    and al, 0x1E
    cmp al, 0x1E
    jne .clroutline
    or byte [sh_bdlg_sel], SH_BDLG_B_OUTLINE
    jmp .redraw
.clroutline:
    and byte [sh_bdlg_sel], ~SH_BDLG_B_OUTLINE & 0xFF
    jmp .redraw
.wasoutline:
    test byte [sh_bdlg_sel], SH_BDLG_B_OUTLINE
    jz .outoff
    or byte [sh_bdlg_sel], 0x1E
    jmp .redraw
.outoff:
    and byte [sh_bdlg_sel], ~0x1E & 0xFF
.redraw:
    mov si, [sh_bdlg_win]
    call sh_bdlg_paint
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret

; sh_bdlg_onbtn - AL = the button FIRED on the release (81.111): 1 OK, 2 Cancel
sh_bdlg_onbtn:
    cmp al, 1
    jne .cancel
    call sh_bdlg_apply
.cancel:
    jmp sh_bdlg_close

; -----------------------------------------------------------------------------
; sh_bdlg_apply - write sh_bdlg_sel's edges/shade (bits 1-5) into the
; border table: a record if any bit is set, no record (removed if one
; existed) if the cell ends up with no border at all.
; -----------------------------------------------------------------------------
sh_bdlg_apply:
    cmp byte [sh_bdlg_kind], SH_BK_BORDER
    je sh_bdlg_apbord
    push ax                             ; 81.106: Display and Workspace set
    mov al, [sh_bdlg_sel]               ; the flags their boxes stand for
    cmp byte [sh_bdlg_kind], SH_BK_DISPLAY
    jne .ws
    mov ah, al
    and al, 1
    mov [sh_showformulas], al
    shr ah, 1
    and ah, 1
    mov [sh_gridlines], ah
    jmp short .shown
.ws:
    and al, 1
    mov [sh_a1style], al
.shown:
    push si
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop si
    pop ax
    ret
; sh_bdlg_count - AX = the open kind's number of boxes
sh_bdlg_count:
    push bx
    mov bl, [sh_bdlg_kind]
    xor bh, bh
    mov al, [sh_bdlg_kn + bx]
    xor ah, ah
    pop bx
    ret
; sh_bdlg_gy2 - AX = the group box's bottom edge, content-relative: the last
; row's box and a margin. SH_BDLG_GY2 is what it comes to for the Border's six
sh_bdlg_gy2:
    push dx
    call sh_bdlg_count
    mov dx, SH_BDLG_ROWH
    mul dx
    add ax, SH_BDLG_ROWTOP - 2
    pop dx
    ret
; sh_bdlg_label - SI = the open kind's title, which is its group's label too
sh_bdlg_label:
    push bx
    mov bl, [sh_bdlg_kind]
    xor bh, bh
    shl bx, 1
    mov si, [sh_bdlg_ktitle + bx]
    pop bx
    ret
sh_bdlg_apbord:
    push ax
    mov ah, [sh_bdlg_sel]
    shr ah, 1
    and ah, 0x1F                        ; AH = the edges and Shade wanted
    mov al, 1                           ; APPLY, over the whole selection
    call sh_bdlg_walk                   ; (81.17.2)
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_bdlg_walk - Format > Border over the SELECTION (SPEC.md 81.17.2), main's
; walk in this table's shape. Each edge box means that side of the BLOCK:
; Left is the left edge of the cells in its first column, Top the top edge of
; its first row, and so on, so Outline - all four - frames the block. Shade
; means every cell. A single cell is a 1x1 block whose four sides are its own.
;
; A cell's MASK is the bits the dialog governs there (Shade, plus each block
; side it lies on); bits outside it - an inner edge set earlier, and
; SH_BT_KEEP's protection and table bits, which no mask holds - are kept.
; in: AL = 0 GATHER: out AL = the bits set on EVERY cell whose mask holds
;          them (what the dialog should open showing)
;     AL = 1 APPLY: AH = the bits to write through every cell's mask, adding
;          or removing border records; a record goes only when nothing at
;          all is left in it (81.55's number format included), and a full
;          table stops adding, silently, as the single-cell version did
; The bounds live in a frame on the stack, so the walk costs no bss.
; Preserves every register but AL.
; -----------------------------------------------------------------------------
sh_bdlg_walk:
    push bx
    push cx
    push dx
    push si
    push di
    push bp
    push es
    or al, al
    jnz .ap
    mov ah, 0x1F                        ; GATHER's accumulator starts full
.ap:
    mov cx, [sh_selcol]
    mov dx, [sh_selcol2]
    cmp cx, dx
    jbe .cok
    xchg cx, dx
.cok:
    mov si, [sh_selrow]
    mov di, [sh_selrow2]
    cmp si, di
    jbe .rok
    xchg si, di
.rok:
    mov bp, sp                          ; [bp-2] c1 [bp-4] c2 [bp-6] r1
    push cx                             ; [bp-8] r2, then [bp-10] the mode
    push dx                             ; and [bp-9] the bits - SS, which is
    push si                             ; where a [bp] operand points
    push di
    push ax
.row:
    mov cx, [bp-2]
.col:
    mov ax, cx
    mov bx, si
    mov dl, SH_BORD_SHADE               ; DL = this cell's mask
    cmp cx, [bp-2]
    jne .m1
    or dl, SH_BORD_LEFT
.m1:
    cmp cx, [bp-4]
    jne .m2
    or dl, SH_BORD_RIGHT
.m2:
    cmp si, [bp-6]
    jne .m3
    or dl, SH_BORD_TOP
.m3:
    cmp si, [bp-8]
    jne .m4
    or dl, SH_BORD_BOTTOM
.m4:
    SHOUT sh_bt_get                     ; AL = what the cell has now
    mov dh, al
    cmp byte [bp-10], 0
    jne .apply
    mov al, dl                          ; a bit outside the mask cannot veto,
    not al                              ; so it reads as set
    or al, dh
    and [bp-9], al
    jmp short .next
.apply:
    mov al, [bp-9]
    xor al, dh
    and al, dl                          ; AL = the governed bits that change
    jz .next
    xor dh, al                          ; DH = the cell's new byte
    mov ax, cx
    SHOUT sh_bt_addcell                 ; finds the record, or makes one
    jc .next                            ; table full
    mov es, [sh_bordseg]
    mov [es:di+4], dh
    cmp word [es:di+4], 0               ; no border, no protection, no number
    jne .next                           ; format: the record is the default
    SHOUT sh_bt_removecell
.next:
    inc cx
    cmp cx, [bp-4]
    jbe .col
    inc si
    cmp si, [bp-8]
    jbe .row
    mov al, [bp-9]                      ; GATHER's answer
    add sp, 10                          ; the frame's five words
    pop es
    pop bp
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_bdlg_close
; -----------------------------------------------------------------------------
sh_bdlg_close:
    push ax
    push bx
    mov bx, [sh_bdlg_win]
    or bx, bx
    jz .out
    mov word [sh_bdlg_win], 0
    call OSAPI_WM_DESTROY               ; see sh_fdlg_close on why not CLOSE
.out:
    pop bx
    pop ax
    ret

section .text

; =============================================================================
; The ONE-LINE INPUT DIALOG (stage 3.0c) - a prompt, an os88line field, OK and
; Cancel. Four menu items want exactly this and differ only in their prompt and
; in what OK does with the string, so it is written once with a KIND byte and
; a dispatch on it, the same way sh_fdlg_* already serves five radio-list
; kinds rather than being copied five times.
;
; This is what the text widget was for. Row Height... and Column Width... have
; been a THREE-PRESET RADIO PICK since stage 1.8 purely because no free-text
; entry existed at the app level - sh_m_format's own comment says so. They are
; now real numeric entry, which is what Excel 2.1d has.
; =============================================================================
SH_ID_GOTO   equ 0                   ; Formula > Goto...
SH_ID_ROWH   equ 1                   ; Format > Row Height...
SH_ID_COLW   equ 2                   ; Format > Column Width...
SH_ID_DEFN   equ 3                   ; Formula > Define Name...
SH_ID_FIND   equ 4                   ; Formula > Find...
SH_ID_SORT   equ 5                   ; Data > Sort... (stage 4.5): the KEY.
                                     ; Excel 2.1's Sort dialog takes its keys
                                     ; as cell references typed into fields,
                                     ; which is exactly what this engine is,
                                     ; and it is the only way to name a key
                                     ; that is not an edge of the selection
                                     ; (81.19 recorded that as a known limit;
                                     ; 81.27 is this)
SH_ID_RUN    equ 6                   ; Macro > Run... (81.63): where to start
SH_ID_INPUT  equ 7                   ; ...and INPUT(), a macro's own question
SH_ID_SERSTEP equ 8                  ; 81.72: Data ▸ Series...' step value,
SH_ID_RECNAME equ 9                  ; part two of two; 81.74: what to call
SH_ID_PARSE  equ 10                  ; 81.82: Data > Parse...' bracket line
SH_ID_TBLROW equ 11                  ; 81.114: Data > Table...' two fields.
SH_ID_TBLCOL equ 12                  ; EXCEL ASKS FOR BOTH IN ONE DIALOG and
                                     ; no engine here has two fields, so they
                                     ; are asked one after the other - the
                                     ; same shape 81.72's Series uses for its
                                     ; type and step, and 81.74's recorder
                                     ; for its name. Either may be left
                                     ; EMPTY, which is how a one-input table
                                     ; says which kind it is: Excel spells
                                     ; that as the comma's side in
                                     ; {=TABLE($D$9,)} and {=TABLE(,$E$8)}
SH_ID_NKIND  equ 13                  ; the recording about to be made
; 81.114: "no input cell of this kind". NOT zero - row 0 column 0 is cell A1,
; a perfectly ordinary input cell - and not -1 either, since every other
; row/col here is an unsigned word and a compare against 0FFFFh reads the
; same whichever it is. SH_ROWS is 16384 and SH_COLS 256, so this is past
; both and can never collide with a real reference.
SH_TBL_NONE  equ 0xFFFF

SH_IDLG_W    equ 268
SH_IDLG_FX1  equ 8                   ; the field, content-relative
SH_IDLG_FY1  equ 28
SH_IDLG_FX2  equ 176
SH_IDLG_FY2  equ 46
SH_IDLG_BTX1 equ 186                 ; OK / Cancel, 64 wide - 'Cancel' needs
SH_IDLG_BTX2 equ 250                 ; 6 glyphs at the fixed 8px cell
SH_IDLG_OKY1 equ 26
SH_IDLG_OKY2 equ 46
SH_IDLG_CAY1 equ 54
SH_IDLG_CAY2 equ 74
; 81.82: Guess and Clear, which Parse alone has. They go on the CANCEL ROW,
; in the space to the left of it - the field above ends at FY2 and Cancel
; starts at BTX1, so this rectangle is empty on all eleven kinds today. That
; is what keeps SH_IDLG_H below unchanged: two more buttons and not one pixel
; of extra dialog, where a row of their own would have made every Goto and
; Column Width taller for a feature they do not have.
SH_IDLG_G1X1 equ SH_IDLG_FX1
SH_IDLG_G1X2 equ SH_IDLG_FX1 + 64
SH_IDLG_G2X1 equ SH_IDLG_FX1 + 72
SH_IDLG_G2X2 equ SH_IDLG_FX1 + 136
SH_IDLG_H    equ SH_IDLG_CAY2 + SH_DLG_BMARG + TITLE_H + 1

sh_idlg_tpl:
    dw 0, 0, SH_IDLG_W, SH_IDLG_H
    dw sh_s_id_tgoto, sh_idlg_paint_r, sh_idlg_key_r, sh_idlg_click_r
; The title above is only a PLACEHOLDER: sh_idlg_open overwrites
; [sh_idlg_tpl + WT_TITLE] with whichever of sh_s_id_t* the kind names, before
; OSAPI_WM_CREATE. WT_TITLE is a pointer TO the text, so the pointer has to go
; into the template itself - putting it in a cell and pointing the template at
; that cell makes the kernel letter the pointer's own two bytes and then run on
; into whatever follows, which is exactly what it did.
sh_id_titles:  dw sh_s_id_tgoto, sh_s_id_trowh, sh_s_id_tcolw, sh_s_id_tdefn, sh_s_id_tfind
               dw sh_s_id_tsort, sh_s_id_trun, sh_s_id_tinput, sh_s_id_tser
               dw sh_s_id_trec, sh_s_id_tparse, sh_s_id_ttbl, sh_s_id_ttbl
sh_id_prompts: dw sh_s_id_pgoto, sh_s_id_prowh, sh_s_id_pcolw, sh_s_id_pdefn, sh_s_id_pfind
               dw sh_s_id_psort, sh_s_id_pgoto, sh_macro_msg, sh_s_id_pser
               dw sh_s_id_prec, sh_s_id_pparse, sh_s_id_ptblr, sh_s_id_ptblc
sh_s_id_ttbl:  db 'Table', 0            ; 81.114, and both halves wear it:
sh_s_id_ptblr: db 'Row Input Cell:', 0  ; Excel's one dialog has one title
sh_s_id_ptblc: db 'Column Input Cell:', 0
sh_s_id_tblbad: db 'Select the formulas and the input values.', 0
sh_s_id_tbldone: db 'Table filled.', 0
sh_s_id_tparse: db 'Parse', 0
sh_s_id_pparse: db 'Parse line:', 0     ; the Reference Guide's own words
sh_s_id_trec:  db 'Record Macro', 0
sh_s_id_prec:  db 'Name:', 0
sh_s_id_tser:  db 'Series', 0
sh_s_id_pser:  db 'Step value:', 0
sh_s_id_tgoto: db 'Goto', 0
sh_s_id_trowh: db 'Row Height', 0
sh_s_id_tcolw: db 'Column Width', 0
sh_s_id_tdefn: db 'Define Name', 0
sh_s_id_tfind: db 'Find', 0
sh_s_id_tsort: db 'Sort', 0
sh_s_id_trun:  db 'Run', 0
sh_s_id_tinput: db 'Input', 0
sh_s_id_badkey: db 'Sort key must be inside the selection', 0
sh_s_id_pgoto: db 'Reference:', 0
sh_s_id_prowh: db 'Row height:', 0
sh_s_id_pcolw: db 'Column width:', 0
sh_s_id_pdefn: db 'Name:', 0
sh_s_id_pfind: db 'Find what:', 0
sh_s_id_psort: db '1st Key:', 0     ; Excel 2.1's own label for the field
sh_s_id_nofit: db 'Name table full.', 0
sh_s_id_named: db 'Name defined.', 0
sh_s_id_nofnd: db 'Not found.', 0
sh_s_idlg_ok:  db 'OK', 0
sh_s_idlg_can: db 'Cancel', 0
section SH_MODSEC                      ; 81.74.2: the one-line input dialog, CHART.OVL

; =============================================================================
; sh_table_run - Data > Table (SPEC.md 81.114). CHART.OVL's, near-called from
; sh_idlg_apply's second half.
; in:  [sh_tbl_ir]/[sh_tbl_ic]   the ROW input cell, or SH_TBL_NONE
;      [sh_tbl_ir2]/[sh_tbl_ic2] the COLUMN input cell, or SH_TBL_NONE
;      the selection is the whole rectangle, formulas and input values and all
; out: CF=1 = the selection is not a table shape; nothing was written
;
; THE SELECTION INCLUDES THE EDGES. Excel's own words are "select the range of
; cells containing the row and column of values and the formula", so the
; rectangle handed in here is one row and one column LARGER than the cells
; that get filled: the top row and the left column are the inputs and the
; formulas, and the interior is the result.
;
; WHICH OF THE THREE SHAPES (4.9's numbering, and the Reference Guide's two
; sections) is decided by which input cells were given, not by guessing from
; the data:
;
;   both given     a two-input table. One formula, in the top-left corner;
;                  the column of values below it feeds the COLUMN input cell
;                  and the row of values right of it feeds the ROW input cell
;   column only    one-input, formulas across the top row, values down the
;                  left column
;   row only       one-input, formulas down the left column, values across
;                  the top row
;
; and neither is a refusal, because then nothing says what to substitute.
; =============================================================================
sh_table_run:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    ; --- the rectangle, normalised ------------------------------------------
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .c_ok
    xchg ax, bx
.c_ok:
    mov [sh_tbl_c1], ax
    mov [sh_tbl_c2], bx
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .r_ok
    xchg ax, bx
.r_ok:
    mov [sh_tbl_r1], ax
    mov [sh_tbl_r2], bx
    ; A TABLE NEEDS AN INTERIOR. One row or one column of selection has an
    ; edge and nothing to fill, which is a mis-selection and not an empty
    ; table - Excel refuses it too.
    mov ax, [sh_tbl_r1]
    cmp ax, [sh_tbl_r2]
    jae .bad
    mov ax, [sh_tbl_c1]
    cmp ax, [sh_tbl_c2]
    jae .bad
    ; --- which shape? --------------------------------------------------------
    mov word [sh_tbl_flags], 0
    mov ax, [sh_tbl_ir]
    cmp ax, SH_TBL_NONE
    jne .haverow
    mov ax, [sh_tbl_ir2]
    cmp ax, SH_TBL_NONE
    je .bad                            ; neither: nothing to substitute
    jmp short .shaped                  ; COLUMN input only: the values are
                                       ; down the left column, so the input
                                       ; data is in the column and bit 2 is 0
.haverow:
    ; 81.114.7: the flags BIFF3's DATATABLE carries, settled here where the
    ; shape is decided rather than guessed again by the writer. Bit 3 is
    ; two-dimensional; bit 2 says the input data is in the ROW above and the
    ; formulas down the column left, which is the row-input-only shape.
    mov ax, [sh_tbl_ir2]
    cmp ax, SH_TBL_NONE
    je .rowdata
    mov word [sh_tbl_flags], SH_TF_TWOD
    jmp short .shaped
.rowdata:
    mov word [sh_tbl_flags], SH_TF_ROWDATA
.shaped:
    call sh_table_fill                 ; the interior, cell by cell
    call sh_tbl_add                    ; ...and the table OUTLIVES the run
    clc                                ; (81.114.7). CF is not read: a full
    jmp short .out                     ; list costs protection, not numbers
.bad:
    stc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_table_fill - the interior of the rectangle now in [sh_tbl_r1..c2], with
; the input cells in [sh_tbl_ir/ic/ir2/ic2]. No validation and no record: the
; caller has already decided this is a table.
;
; SPLIT OUT FOR 81.114.8. sh_table_run reads the SELECTION, which is right
; once - when the dialog is answered - and wrong every time after, because a
; recalculation re-runs a table that is not selected and may be on another
; sheet entirely. The loop itself is unchanged.
; -----------------------------------------------------------------------------
sh_table_fill:
    push ax
    push bx
    mov bx, [sh_tbl_r1]
    inc bx                             ; the first result row
.rowloop:
    cmp bx, [sh_tbl_r2]
    ja .done
    mov ax, [sh_tbl_c1]
    inc ax                             ; ...and the first result column
.colloop:
    cmp ax, [sh_tbl_c2]
    ja .nextrow
    push ax
    push bx
    call sh_table_cell                 ; AX=col, BX=row of the result cell
    pop bx
    pop ax
    inc ax
    jmp short .colloop
.nextrow:
    inc bx
    jmp short .rowloop
.done:
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_tbl_runall - re-run EVERY table on the document (81.114.8). The resident
; half reaches this through SHM_TBLRUN.
;
; A table's result cells hold STORED VALUES, not formulas, so this app's
; ordinary recalculation - `inc word [sh_pass]`, and sh_eval_cell re-evaluates
; lazily as the grid draws - does nothing for them at all. They have to be
; computed again, which is one full formula evaluation PER RESULT CELL. That
; cost is the whole reason Excel's own Calculation dialog offers "Automatic
; except Tables", and 81.114.8 offers it for the same reason.
;
; THE SHEET IS SET FROM THE RECORD. sh_getcell2 and sh_setvald work on
; [sh_cursheet], and a table on Sheet 3 re-run while Sheet 1 is showing would
; otherwise read and write the wrong grid - sh_recalc_all's own push/pop of
; that word, for the same reason.
; -----------------------------------------------------------------------------
sh_tbl_runall:
    cmp byte [sh_tbl_busy], 0          ; a table's formula cannot reach here,
    jne .out                           ; but a guard is two bytes and the
    cmp word [sh_ntbl], 0              ; failure it prevents is unbounded
    je .out
    push ax
    push cx
    push dx
    push si
    push es
    push word [sh_cursheet]
    mov byte [sh_tbl_busy], 1
    mov es, [sh_tblseg]
    xor si, si
    mov cx, [sh_ntbl]
.l:
    xor ax, ax
    mov al, [es:si+SH_T_SHEET]
    mov [sh_cursheet], ax
    mov ax, [es:si+SH_T_R1]
    mov [sh_tbl_r1], ax
    mov ax, [es:si+SH_T_R2]
    mov [sh_tbl_r2], ax
    xor ax, ax
    mov al, [es:si+SH_T_C1]
    mov [sh_tbl_c1], ax
    xor ax, ax
    mov al, [es:si+SH_T_C2]
    mov [sh_tbl_c2], ax
    mov ax, [es:si+SH_T_IR]
    mov [sh_tbl_ir], ax
    mov ax, [es:si+SH_T_IC]
    mov [sh_tbl_ic], ax
    mov ax, [es:si+SH_T_IR2]
    mov [sh_tbl_ir2], ax
    mov ax, [es:si+SH_T_IC2]
    mov [sh_tbl_ic2], ax
    push cx
    push si
    call sh_table_fill
    pop si
    pop cx
    mov es, [sh_tblseg]                ; re-read: sh_table_fill writes cells,
    add si, SH_T_SZ                    ; and a write can compact the heap
    loop .l
    mov byte [sh_tbl_busy], 0
    pop word [sh_cursheet]
    pop es
    pop si
    pop dx
    pop cx
    pop ax
.out:
    ret

; -----------------------------------------------------------------------------
; sh_table_cell - one result cell. in: AX = col, BX = row (inside the table).
;
; Substitute this cell's governing input value(s) into the input cell(s),
; evaluate the governing formula, store the answer here, and PUT THE INPUT
; CELLS BACK. The restore is not tidiness: the input cell is an ordinary cell
; of the user's sheet and every later result reads it, so leaving the last
; substitution in it would make the table depend on the order it was filled.
; -----------------------------------------------------------------------------
sh_table_cell:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov [sh_tbl_cc], ax
    mov [sh_tbl_cr], bx
    ; --- 1. bank both input cells, WHOLE RECORDS ----------------------------
    ; Not just their values: an input cell is an ordinary cell of the user's
    ; sheet and may hold a formula or a label, and sh_setvald over one would
    ; leave a value where a formula was. Twenty bytes each, put back below
    ; whatever happens in between.
    mov ax, [sh_tbl_ic]
    mov bx, [sh_tbl_ir]
    mov di, sh_tbl_sav1
    call sh_table_bank
    mov ax, [sh_tbl_ic2]
    mov bx, [sh_tbl_ir2]
    mov di, sh_tbl_sav2
    call sh_table_bank
    ; --- 2. substitute, and remember where the formula is -------------------
    mov ax, [sh_tbl_ir]
    cmp ax, SH_TBL_NONE
    je .colonly
    mov ax, [sh_tbl_ir2]
    cmp ax, SH_TBL_NONE
    je .rowonly
    ; BOTH: a two-input table. One formula, in the corner; this cell's row
    ; value feeds the COLUMN input cell and its column value the ROW one.
    mov ax, [sh_tbl_c1]                ; the left column, at this row
    mov bx, [sh_tbl_cr]
    mov cx, [sh_tbl_ic2]
    mov dx, [sh_tbl_ir2]
    call sh_table_subst
    mov ax, [sh_tbl_cc]                ; the top row, at this column
    mov bx, [sh_tbl_r1]
    mov cx, [sh_tbl_ic]
    mov dx, [sh_tbl_ir]
    call sh_table_subst
    mov ax, [sh_tbl_c1]                ; ...and the formula is the corner
    mov bx, [sh_tbl_r1]
    jmp short .evaluate
.colonly:
    ; A COLUMN input cell only: the values are down the left column and the
    ; formulas are across the top row, so this cell's formula is the one
    ; above it and its value the one to its left.
    mov ax, [sh_tbl_c1]
    mov bx, [sh_tbl_cr]
    mov cx, [sh_tbl_ic2]
    mov dx, [sh_tbl_ir2]
    call sh_table_subst
    mov ax, [sh_tbl_cc]
    mov bx, [sh_tbl_r1]
    jmp short .evaluate
.rowonly:
    ; A ROW input cell only: the values are across the top row and the
    ; formulas down the left column - the mirror of the above.
    mov ax, [sh_tbl_cc]
    mov bx, [sh_tbl_r1]
    mov cx, [sh_tbl_ic]
    mov dx, [sh_tbl_ir]
    call sh_table_subst
    mov ax, [sh_tbl_c1]
    mov bx, [sh_tbl_cr]
.evaluate:
    ; --- 3. evaluate the governing formula ----------------------------------
    ; THE PASS STAMP MUST MOVE. sh_eval_cell memoizes per repaint pass, so
    ; without this every cell of the table would answer with the value the
    ; formula had the first time and the whole interior would be one number
    ; repeated. The same `inc` is what Calculate Now spends (81.78).
    inc word [sh_pass]
    SHOUT sh_getcell2                  ; AX=col, BX=row -> the value in sh_acc
    ; --- 4. store it, and only then put the inputs back ---------------------
    mov ax, [sh_tbl_cc]
    mov bx, [sh_tbl_cr]
    SHOUT sh_setvald
    call sh_table_mark                 ; 81.114.7: ...and it is a RESULT cell
                                       ; now, which no edit may touch. AFTER
                                       ; the store, never before: sh_setvald
                                       ; writes the cell record and this
                                       ; writes the border table beside it
    mov di, sh_tbl_sav1
    call sh_table_unbank
    mov di, sh_tbl_sav2
    call sh_table_unbank
    inc word [sh_pass]                 ; ...and nothing may keep a value that
    pop di                             ; was computed against a substitution
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; 81.114.7 - THE TABLE LIST. A table outlives the run that made it: a result
; cell cannot be edited, a clear is all-or-nothing, and stage 4 has to write
; one DATATABLE record per table. None of that is answerable from the cell
; records, so the rectangle and the input cells are kept in a list of their
; own - SH_T_SZ a table, carved out of the border claim (SHEET holds all
; eight of MEM_OWNER_MAX's claims, so a ninth is refused).
;
; WHICH CELLS ARE RESULTS is NOT read from this list on the hot path. Every
; result cell carries SH_TBL_RESULT in the border byte, which sh_prot_blocked
; already fetches for each cell of the selection - so the guard that refuses
; an edit is one `test` and the list is only walked by Clear, which is a menu
; command and may spend a scan.
; =============================================================================

; sh_tbl_selnorm - the selection into [sh_tbl_sr1..sc2], top-left first.
sh_tbl_selnorm:
    push ax
    push bx
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .r
    xchg ax, bx
.r:
    mov [sh_tbl_sr1], ax
    mov [sh_tbl_sr2], bx
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .c
    xchg ax, bx
.c:
    mov [sh_tbl_sc1], ax
    mov [sh_tbl_sc2], bx
    pop bx
    pop ax
    ret

; sh_tbl_findrec - the record for the rectangle now in [sh_tbl_r1]/[sh_tbl_c1]
; on the current sheet. in: ES = [sh_tblseg]. out: CF=1 and DI = its offset.
; The top-left corner and the sheet are the identity: re-running Data > Table
; over the same rectangle REPLACES its record rather than adding a second.
sh_tbl_findrec:
    push ax
    push cx
    xor di, di
    mov cx, [sh_ntbl]
    jcxz .no
.l:
    mov ax, [sh_tbl_r1]
    cmp ax, [es:di+SH_T_R1]
    jne .next
    mov al, byte [sh_tbl_c1]
    cmp al, [es:di+SH_T_C1]
    jne .next
    mov al, byte [sh_cursheet]
    cmp al, [es:di+SH_T_SHEET]
    je .yes
.next:
    add di, SH_T_SZ
    loop .l
.no:
    clc
    jmp short .out
.yes:
    stc
.out:
    pop cx
    pop ax
    ret

; sh_tbl_add - record the table sh_table_run has just filled, from the same
; [sh_tbl_*] words it ran off. out: CF=1 the list is full and nothing was
; stored - the numbers are still right, the table is simply not protected,
; which is the same scope limit every other table in this file takes when it
; fills (the border table's own writers say so).
sh_tbl_add:
    push ax
    push cx
    push dx
    push di
    push es
    mov es, [sh_tblseg]
    call sh_tbl_findrec
    jc .fill
    cmp word [sh_ntbl], SH_TBL_CAP
    jae .full
    mov ax, [sh_ntbl]
    mov cx, SH_T_SZ
    mul cx
    mov di, ax
    inc word [sh_ntbl]
.fill:
    mov ax, [sh_tbl_r1]
    mov [es:di+SH_T_R1], ax
    mov ax, [sh_tbl_r2]
    mov [es:di+SH_T_R2], ax
    mov al, byte [sh_tbl_c1]
    mov [es:di+SH_T_C1], al
    mov al, byte [sh_tbl_c2]
    mov [es:di+SH_T_C2], al
    mov ax, [sh_tbl_flags]
    mov [es:di+SH_T_FLAGS], ax
    mov ax, [sh_tbl_ir]
    mov [es:di+SH_T_IR], ax
    mov ax, [sh_tbl_ic]
    mov [es:di+SH_T_IC], ax
    mov ax, [sh_tbl_ir2]
    mov [es:di+SH_T_IR2], ax
    mov ax, [sh_tbl_ic2]
    mov [es:di+SH_T_IC2], ax
    mov al, byte [sh_cursheet]
    mov [es:di+SH_T_SHEET], al
    clc
    jmp short .out
.full:
    stc
.out:
    pop es
    pop di
    pop dx
    pop cx
    pop ax
    ret

; sh_tbl_overlap - how the record at ES:DI sits against the selection in
; [sh_tbl_sr1..sc2]. out: AL = 0 apart, 1 PARTLY covered, 2 wholly covered.
; THE RESULT AREA, not the range: the top row and the left column of a
; table's rectangle are the user's own formulas and input values, and
; clearing those is not clearing the table.
sh_tbl_overlap:
    mov al, byte [sh_cursheet]
    cmp al, [es:di+SH_T_SHEET]
    jne .none                          ; another sheet's table
    push ax
    mov ax, [es:di+SH_T_R1]
    inc ax
    mov [sh_tbl_tr1], ax
    mov ax, [es:di+SH_T_R2]
    mov [sh_tbl_tr2], ax
    xor ax, ax
    mov al, [es:di+SH_T_C1]
    inc ax
    mov [sh_tbl_tc1], ax
    xor ax, ax
    mov al, [es:di+SH_T_C2]
    mov [sh_tbl_tc2], ax
    ; apart?
    mov ax, [sh_tbl_tr2]
    cmp ax, [sh_tbl_sr1]
    jb .nonep
    mov ax, [sh_tbl_tr1]
    cmp ax, [sh_tbl_sr2]
    ja .nonep
    mov ax, [sh_tbl_tc2]
    cmp ax, [sh_tbl_sc1]
    jb .nonep
    mov ax, [sh_tbl_tc1]
    cmp ax, [sh_tbl_sc2]
    ja .nonep
    ; wholly inside?
    mov ax, [sh_tbl_tr1]
    cmp ax, [sh_tbl_sr1]
    jb .partp
    mov ax, [sh_tbl_tr2]
    cmp ax, [sh_tbl_sr2]
    ja .partp
    mov ax, [sh_tbl_tc1]
    cmp ax, [sh_tbl_sc1]
    jb .partp
    mov ax, [sh_tbl_tc2]
    cmp ax, [sh_tbl_sc2]
    ja .partp
    pop ax
    mov al, 2
    ret
.partp:
    pop ax
    mov al, 1
    ret
.nonep:
    pop ax
.none:
    xor al, al
    ret

; sh_tbl_dropsel - forget every table the selection covers WHOLLY. Called
; only after sh_tbl_clearguard has agreed, so a partial cover never reaches
; it. The result cells' SH_TBL_RESULT marks go with the border records
; sh_clear_one removes; this takes the table itself away.
sh_tbl_dropsel:
    push ax
    push cx
    push dx
    push si
    push di
    push es
    mov es, [sh_tblseg]
    xor di, di
.l:
    mov ax, [sh_ntbl]
    mov cx, SH_T_SZ
    mul cx                             ; AX = the list's length, in bytes
    cmp di, ax
    jae .out
    call sh_tbl_overlap
    cmp al, 2
    jne .keep
    call sh_tbl_unmark                 ; THE MARKS GO WITH THE TABLE, here and
                                       ; not in sh_clear_one: All removes the
                                       ; whole border record anyway, but
                                       ; FORMULAS keeps it (81.63 - a cell
                                       ; with a border is kept), so a clear
                                       ; that way dropped the table and left
                                       ; every result cell marked. An orphan
                                       ; mark refuses edits for ever, and only
                                       ; while another table keeps
                                       ; sh_prot_blocked's scan armed - which
                                       ; is as hard to see as it sounds
    mov ax, [sh_ntbl]                  ; THE LENGTH IS RE-TAKEN, not the one
    mov cx, SH_T_SZ                    ; computed four instructions ago:
    mul cx                             ; sh_tbl_overlap answers in AL, so AX
                                       ; came back as (old AH):(0|1|2) and
                                       ; `mov cx, ax` made a byte count out of
                                       ; whatever AH happened to be. The
                                       ; rep movsb below then ran off the end
                                       ; of a 10KB claim and the machine said
                                       ; STACK OVERFLOW, three structures
                                       ; away from the mistake
    mov cx, ax                         ; close the gap: everything past this
    sub cx, di                         ; record moves down over it
    sub cx, SH_T_SZ
    jcxz .last
    mov si, di
    add si, SH_T_SZ
    push di
    push ds                            ; DS GOES BACK BEFORE THE LOOP TURNS:
    push es                            ; [sh_ntbl] and the rectangles below
    pop ds                             ; are in OUR segment, not the claim's
    cld
    rep movsb
    pop ds
    pop di
.last:
    dec word [sh_ntbl]
    jmp short .l                       ; ...and judge THIS index again
.keep:
    add di, SH_T_SZ
    jmp short .l
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop ax
    ret

; sh_tbl_unmark - clear SH_TBL_RESULT over the result rectangle now in
; [sh_tbl_tr1..tc2] on the current sheet, which sh_tbl_overlap has just
; filled. ONE WALK of the border table rather than a lookup per cell: the
; rectangle can be large and the table is SH_BORD_CAP records at most.
;
; A record left holding nothing is NOT removed here - every reader of this
; table treats a zero record exactly as it treats no record, and removing one
; mid-walk would shift the array under the cursor. Clear > All takes the
; record away in sh_clear_one anyway; what can be left behind is a zero
; record per result cell of a table cleared through FORMULAS, bounded by the
; number of distinct result cells the document has ever had.
sh_tbl_unmark:
    push ax
    push bx
    push cx
    push si
    push es
    mov es, [sh_bordseg]
    xor si, si
    mov cx, [sh_nbord]
    jcxz .out
.l:
    test byte [es:si+4], SH_TBL_RESULT
    jz .next
    mov ax, [es:si]                    ; row, packed with the sheet
    mov bx, ax
    and bx, 0xC000
    push cx                            ; 8086: a shift is by 1 or by CL
    mov cl, 6
    shr bh, cl
    pop cx
    cmp bh, byte [sh_cursheet]
    jne .next
    and ax, 0x3FFF
    cmp ax, [sh_tbl_tr1]
    jb .next
    cmp ax, [sh_tbl_tr2]
    ja .next
    mov ax, [es:si+2]
    cmp ax, [sh_tbl_tc1]
    jb .next
    cmp ax, [sh_tbl_tc2]
    ja .next
    and byte [es:si+4], ~SH_TBL_RESULT & 0xFF
.next:
    add si, SH_BT_SZ
    loop .l
.out:
    pop es
    pop si
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; 81.114.9 - THE STORED RECTANGLE FOLLOWS THE GRID.
;
; Insert/Delete Row/Column move the cells, and they move a result cell's MARK
; with them for free - the mark lives in the border byte, and sh_rc_sides
; already shifts that table. The 16-byte table record does NOT move, so
; without this a table whose sheet gained a row above it is guarded against a
; rectangle one row too high: a clear refused when it should be allowed, or
; allowed when it should be refused.
;
; sh_rc_table is the GENERIC shifter for a sparse table whose record begins
; (packed row/sheet, column), and it does not fit, because a table record is
; not a point:
;
;   a row inserted ABOVE it     moves the whole rectangle down
;   a row inserted INSIDE it    GROWS it - r2 moves, r1 does not
;   a row deleted INSIDE it     shrinks it, and the table goes when no
;                               interior is left
;   the TOP row deleted         takes the formulas (or the input values)
;                               with it, so the table goes
;   an INPUT CELL deleted       leaves nothing to substitute, so the table
;                               goes
;
; A dropped table is UNMARKED first, over where its marks now are - the
; border table was shifted before this ran, so the rectangle to unmark is the
; SHIFTED one and not the one the record still holds.
; =============================================================================

; sh_tbl_shiftv - AX = a row or column index that is not SH_TBL_NONE;
; DX = the grid's bound in that direction. [sh_rc_op]/[sh_rc_idx] say what
; happened. out: AX shifted, CF=1 = this index is GONE - it was the deleted
; one, or an insert pushed it off the end of the grid.
sh_tbl_shiftv:
    push bx
    mov bx, [sh_rc_idx]
    cmp ax, bx
    jb .same                           ; before the pivot: untouched
    test byte [sh_rc_op], 1            ; ops 1 and 3 are the deletes
    jnz .del
    inc ax
    cmp ax, dx
    jae .gone                          ; pushed off the grid
.same:
    pop bx
    clc
    ret
.del:
    cmp ax, bx                         ; RE-COMPARED ON PURPOSE: the `test`
    je .gone                           ; above ate the flags from the compare
    dec ax                             ; at the top, so a `je` resting on
    pop bx                             ; them would never have fired - and a
    clc                                ; stale flag has no name (81.17's
    ret                                ; family)
.gone:
    pop bx
    stc
    ret

; sh_tbl_rcone - one record, at ES:SI and known to be on this sheet.
; out: CF=1 drop it, and either way [sh_tbl_tr1..tc2] is the RESULT
; rectangle where this table's marks now are.
sh_tbl_rcone:
    push ax
    push bx
    push dx
    mov ax, [es:si+SH_T_R1]
    mov [sh_tbl_r1], ax
    mov ax, [es:si+SH_T_R2]
    mov [sh_tbl_r2], ax
    xor ax, ax
    mov al, [es:si+SH_T_C1]
    mov [sh_tbl_c1], ax
    xor ax, ax
    mov al, [es:si+SH_T_C2]
    mov [sh_tbl_c2], ax
    mov ax, [es:si+SH_T_IR]
    mov [sh_tbl_ir], ax
    mov ax, [es:si+SH_T_IC]
    mov [sh_tbl_ic], ax
    mov ax, [es:si+SH_T_IR2]
    mov [sh_tbl_ir2], ax
    mov ax, [es:si+SH_T_IC2]
    mov [sh_tbl_ic2], ax

    mov bx, [sh_rc_idx]
    cmp byte [sh_rc_op], 2
    jae .col

    ; --- ROWS: the rectangle ------------------------------------------------
    mov dx, SH_ROWS
    mov ax, [sh_tbl_r1]
    cmp ax, bx
    jb .r2                             ; the pivot is below r1: r1 stays
    cmp byte [sh_rc_op], 1
    jne .rins1
    cmp ax, bx                         ; DELETING THE TOP ROW takes the
    je .drop                           ; formulas, or the input values, with
                                       ; it - there is no table left
    dec ax
    mov [sh_tbl_r1], ax
    jmp short .r2
.rins1:
    inc ax
    cmp ax, SH_ROWS
    jae .drop
    mov [sh_tbl_r1], ax
.r2:
    mov ax, [sh_tbl_r2]
    cmp ax, bx
    jb .rinputs                        ; wholly above the pivot: nothing moves
    cmp byte [sh_rc_op], 1
    jne .rins2
    dec ax                             ; a delete at or inside the rectangle
    mov [sh_tbl_r2], ax                ; SHRINKS it
    mov bx, [sh_tbl_r1]
    cmp ax, bx
    jbe .drop                          ; ...and no interior is left
    mov bx, [sh_rc_idx]
    jmp short .rinputs
.rins2:
    inc ax
    cmp ax, SH_ROWS
    jae .drop
    mov [sh_tbl_r2], ax
.rinputs:
    mov ax, [sh_tbl_ir]
    cmp ax, SH_TBL_NONE
    je .rin2
    call sh_tbl_shiftv
    jc .drop                           ; the input cell is gone
    mov [sh_tbl_ir], ax
.rin2:
    mov ax, [sh_tbl_ir2]
    cmp ax, SH_TBL_NONE
    je .ok
    call sh_tbl_shiftv
    jc .drop
    mov [sh_tbl_ir2], ax
    jmp short .ok

    ; --- COLUMNS: the mirror, and SH_COLS is 256 so c1/c2 stay bytes --------
.col:
    mov dx, SH_COLS
    mov ax, [sh_tbl_c1]
    cmp ax, bx
    jb .c2
    cmp byte [sh_rc_op], 3
    jne .cins1
    cmp ax, bx
    je .drop
    dec ax
    mov [sh_tbl_c1], ax
    jmp short .c2
.cins1:
    inc ax
    cmp ax, SH_COLS
    jae .drop
    mov [sh_tbl_c1], ax
.c2:
    mov ax, [sh_tbl_c2]
    cmp ax, bx
    jb .cinputs
    cmp byte [sh_rc_op], 3
    jne .cins2
    dec ax
    mov [sh_tbl_c2], ax
    mov bx, [sh_tbl_c1]
    cmp ax, bx
    jbe .drop
    mov bx, [sh_rc_idx]
    jmp short .cinputs
.cins2:
    inc ax
    cmp ax, SH_COLS
    jae .drop
    mov [sh_tbl_c2], ax
.cinputs:
    mov ax, [sh_tbl_ic]
    cmp ax, SH_TBL_NONE
    je .cin2
    call sh_tbl_shiftv
    jc .drop
    mov [sh_tbl_ic], ax
.cin2:
    mov ax, [sh_tbl_ic2]
    cmp ax, SH_TBL_NONE
    je .ok
    call sh_tbl_shiftv
    jc .drop
    mov [sh_tbl_ic2], ax
.ok:
    call sh_tbl_resultrect
    ; write the shifted rectangle back
    mov ax, [sh_tbl_r1]
    mov [es:si+SH_T_R1], ax
    mov ax, [sh_tbl_r2]
    mov [es:si+SH_T_R2], ax
    mov al, byte [sh_tbl_c1]
    mov [es:si+SH_T_C1], al
    mov al, byte [sh_tbl_c2]
    mov [es:si+SH_T_C2], al
    mov ax, [sh_tbl_ir]
    mov [es:si+SH_T_IR], ax
    mov ax, [sh_tbl_ic]
    mov [es:si+SH_T_IC], ax
    mov ax, [sh_tbl_ir2]
    mov [es:si+SH_T_IR2], ax
    mov ax, [sh_tbl_ic2]
    mov [es:si+SH_T_IC2], ax
    pop dx
    pop bx
    pop ax
    clc
    ret
.drop:
    call sh_tbl_resultrect             ; where the marks are NOW, which is
    pop dx                             ; what sh_tbl_unmark needs
    pop bx
    pop ax
    stc
    ret

; sh_tbl_resultrect - [sh_tbl_tr1..tc2] from the working rectangle: the range
; less its top row and left column, which is sh_tbl_overlap's own convention.
sh_tbl_resultrect:
    push ax
    mov ax, [sh_tbl_r1]
    inc ax
    mov [sh_tbl_tr1], ax
    mov ax, [sh_tbl_r2]
    mov [sh_tbl_tr2], ax
    mov ax, [sh_tbl_c1]
    inc ax
    mov [sh_tbl_tc1], ax
    mov ax, [sh_tbl_c2]
    mov [sh_tbl_tc2], ax
    pop ax
    ret

; sh_tbl_drop1 - unmark and remove the record at ES:SI. [sh_tbl_tr1..tc2] is
; already the rectangle whose marks are to go.
sh_tbl_drop1:
    push ax
    push cx
    push dx
    push di
    call sh_tbl_unmark
    mov ax, [sh_ntbl]
    mov cx, SH_T_SZ
    mul cx
    mov cx, ax                         ; the list's length, in bytes
    sub cx, si
    sub cx, SH_T_SZ                    ; ...past this record
    jcxz .last
    mov di, si
    push si
    add si, SH_T_SZ
    push ds
    push es
    pop ds
    cld
    rep movsb
    pop ds
    pop si
.last:
    dec word [sh_ntbl]
    pop di
    pop dx
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_tbl_rcshift - SHM_TBLADJ's work: every table on this sheet follows an
; Insert/Delete Row/Column. Called from sh_rowcol_op AFTER sh_rc_sides, so
; the marks have already moved and a drop unmarks where they now are.
; -----------------------------------------------------------------------------
sh_tbl_rcshift:
    cmp word [sh_ntbl], 0
    je .out
    push ax
    push bx
    push cx
    push dx                            ; `mul` below writes it, and this
    push si                            ; routine's contract is "preserves
    push es                            ; everything"

    mov es, [sh_tblseg]
    xor si, si
.l:
    mov ax, [sh_ntbl]
    mov cx, SH_T_SZ
    mul cx
    cmp si, ax
    jae .done
    xor ax, ax
    mov al, [es:si+SH_T_SHEET]
    cmp ax, [sh_cursheet]
    jne .next                          ; another sheet's grid did not move
    call sh_tbl_rcone
    jnc .next
    call sh_tbl_drop1
    jmp short .l                       ; ...and judge THIS index again
.next:
    add si, SH_T_SZ
    jmp short .l
.done:
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
.out:
    ret

; -----------------------------------------------------------------------------
; sh_tbl_sortdrop - a SORT is an arbitrary permutation of rows, so a table
; whose rectangle it touches stops being a table: its results are still the
; right numbers, in an order nothing can reconstruct. The record goes and the
; marks with it, which leaves the VALUES where the sort put them - the same
; shape of answer SYLK gives a table it cannot describe (81.114.7).
;
; in: [sh_sort_r1/r2/c1/c2], the block as sh_docmd_sortcol normalised it.
; out: AL = how many tables were dropped, for the status line.
; -----------------------------------------------------------------------------
sh_tbl_sortdrop:
    push bx
    push cx
    push dx
    push si
    push es
    xor dl, dl                         ; DL counts them
    cmp word [sh_ntbl], 0
    je .done
    mov es, [sh_tblseg]
    xor si, si
.l:
    push dx                            ; `mul` WRITES DX, and DL is the
    mov ax, [sh_ntbl]                  ; counter: without this the count came
    mov cx, SH_T_SZ                    ; back as the multiply's high word,
    mul cx                             ; which is 0 for any list that fits -
    mov bx, ax                         ; so the tables were dropped correctly
    pop dx                             ; and the status line never said so.
    cmp si, bx                         ; Third of its family in this feature
    jae .done
    xor ax, ax
    mov al, [es:si+SH_T_SHEET]
    cmp ax, [sh_cursheet]
    jne .next
    ; THE WHOLE RANGE, not the result area: a sort that reorders only the
    ; formula row or the input values has broken the table just as surely.
    mov ax, [es:si+SH_T_R2]
    cmp ax, [sh_sort_r1]
    jb .next
    mov ax, [es:si+SH_T_R1]
    cmp ax, [sh_sort_r2]
    ja .next
    xor ax, ax
    mov al, [es:si+SH_T_C2]
    cmp ax, [sh_sort_c1]
    jb .next
    xor ax, ax
    mov al, [es:si+SH_T_C1]
    cmp ax, [sh_sort_c2]
    ja .next
    mov ax, [es:si+SH_T_R1]
    mov [sh_tbl_r1], ax
    mov ax, [es:si+SH_T_R2]
    mov [sh_tbl_r2], ax
    xor ax, ax
    mov al, [es:si+SH_T_C1]
    mov [sh_tbl_c1], ax
    xor ax, ax
    mov al, [es:si+SH_T_C2]
    mov [sh_tbl_c2], ax
    call sh_tbl_resultrect
    call sh_tbl_drop1
    inc dl
    jmp short .l
.next:
    add si, SH_T_SZ
    jmp short .l
.done:
    mov al, dl
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    ret

; =============================================================================
; 81.114.10 - DATA > TABLE IN BIFF, the writer's half.
;
; Excel writes a table as a FORMULA record per RESULT cell whose token array
; is a single tTbl, plus ONE DATATABLE record immediately after the FIRST
; FORMULA record of the table's range. A reader that knows neither still sees
; the right numbers - the FORMULA's cached result - which is why this is the
; faithful shape rather than a private one.
; =============================================================================

; sh_tbl_atcell - AX = col, BX = row, on the sheet being written. out: CF=1
; and SI = the record offset of the table whose RANGE contains the cell, with
; [sh_tbl_isres] = 1 when it is in the RESULT interior as well.
;
; THE LIST DECIDES, NOT THE MARK. A border table that filled leaves a result
; cell unmarked (81.114.7 takes that scope limit deliberately), and a file
; that then wrote it as a plain number would lose the table on the way out
; for a reason the user could not see.
sh_tbl_atcell:
    push ax
    push bx
    push cx
    push dx
    push es
    mov byte [sh_tbl_isres], 0
    mov byte [sh_tbl_idx], 0
    mov cx, [sh_ntbl]
    jcxz .no
    xor si, si
    mov es, [sh_tblseg]
.l:
    mov dl, [es:si+SH_T_SHEET]
    xor dh, dh
    cmp dx, [sh_wsheet]
    jne .next
    cmp bx, [es:si+SH_T_R1]
    jb .next
    cmp bx, [es:si+SH_T_R2]
    ja .next
    xor dx, dx
    mov dl, [es:si+SH_T_C1]
    cmp ax, dx
    jb .next
    xor dx, dx
    mov dl, [es:si+SH_T_C2]
    cmp ax, dx
    ja .next
    ; inside the RANGE. The result interior is that less the top row and the
    ; left column, which is sh_tbl_overlap's convention throughout.
    cmp bx, [es:si+SH_T_R1]
    je .yes
    xor dx, dx
    mov dl, [es:si+SH_T_C1]
    cmp ax, dx
    je .yes
    mov byte [sh_tbl_isres], 1
.yes:
    pop es
    pop dx
    pop cx
    pop bx
    pop ax
    stc
    ret
.next:
    add si, SH_T_SZ
    inc byte [sh_tbl_idx]
    loop .l
.no:
    pop es
    pop dx
    pop cx
    pop bx
    pop ax
    clc
    ret

; sh_biff_ttbl - a FORMULA record whose whole token array is one tTbl, for
; the result cell in sh_wrec_*. SI = its table's record offset.
; out: CF=0 written, CF=1 no room (the caller falls back to RK/NUMBER).
sh_biff_ttbl:
    push ax
    push bx
    push cx
    mov ax, di
    add ax, 4 + 18 + 5
    cmp ax, SH_STAGE_MAX
    ja .no
    mov ax, 0x0206                    ; FORMULA. A BIFF4 workbook needs 0406H,
    cmp byte [sh_wb_xf4], 0           ; exactly as sh_biff_formula does
    je .op3
    mov ax, 0x0406
.op3:
    call sh_biffw
    mov ax, 18 + 5                    ; row+col+xf+result(8)+grbit+cce, then
    call sh_biffw                     ; the five bytes of the token
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]
    call sh_biffw
    mov bx, sh_wrec_dval              ; the CACHED RESULT, which is the whole
    mov cx, 4                         ; point of the record: a reader that
.val:                                 ; does not know tTbl still shows the
    mov ax, [bx]                      ; right number. sh_wrec_DVAL and not
                                      ; sh_wrec_val - that one is the WORD the
                                      ; RK path packs an exact integer from,
                                      ; and reading the double out of it gave
                                      ; four cells of denormal noise
    call sh_biffw
    add bx, 2
    loop .val
    xor ax, ax                        ; grbit: nothing set
    call sh_biffw
    mov ax, 5                         ; cce - the token array's length
    call sh_biffw
    mov al, 0x02                      ; tTbl, and it is ALWAYS the only token
    call sh_stgputb                   ; in the array
    push es
    mov es, [sh_tblseg]
    mov ax, [es:si+SH_T_R1]
    mov bx, ax
    xor ax, ax
    mov al, [es:si+SH_T_C1]
    mov cx, ax
    pop es
    mov ax, bx
    call sh_biffw                     ; the table's first ROW...
    mov ax, cx
    call sh_biffw                     ; ...and its first COLUMN, two bytes in
    pop cx                            ; BIFF3 where BIFF2 had one
    pop bx
    pop ax
    clc
    ret
.no:
    pop cx
    pop bx
    pop ax
    stc
    ret

; sh_biff_dtafter - a FORMULA record has just been written for a cell in the
; table at SI. If this is that table's FIRST, the DATATABLE goes here.
;
; "Immediately after the first FORMULA record of the range" is the format's
; own rule, and the first such record is usually the USER'S OWN formula in
; the top row rather than a result cell - so this is called after every
; FORMULA this writer emits inside a table, not only after a tTbl one.
sh_biff_dtafter:
    push ax
    push bx
    push cx
    push dx
    push si
    push es
    mov al, [sh_tbl_idx]              ; sh_tbl_atcell left it, so there is no
    mov ah, al                        ; divide by SH_T_SZ here at all
    shr al, 1
    shr al, 1
    shr al, 1                         ; AL = the byte of the bitmap
    and ah, 7                         ; AH = the bit within it
    mov bl, al
    xor bh, bh
    add bx, sh_tbl_wdone              ; BX AND NOT BP: [bp] addresses SS by
    mov al, 1                         ; default and SS is not DS in a package
    mov cl, ah                        ; (SPEC.md 1), so a bitmap read through
    shl al, cl                        ; BP would have been another segment's
    test [bx], al
    jnz .done
    or [bx], al
    mov ax, di                        ; room for the record?
    add ax, 4 + 16
    cmp ax, SH_STAGE_MAX
    ja .done
    mov ax, 0x0236                    ; DATATABLE (BIFF3/BIFF4)
    call sh_biffw
    mov ax, 16
    call sh_biffw
    ; The RANGE and the FLAGS are the record's own, word for word.
    push es
    mov es, [sh_tblseg]
    mov ax, [es:si+SH_T_R1]
    mov bx, [es:si+SH_T_R2]
    mov cx, [es:si+SH_T_C1]           ; c1 and c2 are adjacent BYTES, which
    mov dx, [es:si+SH_T_FLAGS]        ; is one word
    pop es
    call sh_biffw
    mov ax, bx
    call sh_biffw
    mov ax, cx
    call sh_biffw
    mov ax, dx
    call sh_biffw
    ; ...AND THE INPUT CELLS ARE TRANSLATED, which is where "the body is the
    ; record" stops being true. The format names ONE input cell for a
    ; one-input table - in the FIRST pair, whichever kind it is - and leaves
    ; the second pair to the two-dimensional case, with option bit 2 saying
    ; which orientation the single one has. This app keeps the ROW input in
    ; the first pair and the COLUMN input in the second ALWAYS, with
    ; SH_TBL_NONE in the unused one, because that is what its engine reads.
    ; Copying the sixteen bytes verbatim would therefore write 0FFFFh as the
    ; input cell of every column-input table - the common shape.
    test dx, SH_TF_TWOD
    jnz .twod
    push es
    mov es, [sh_tblseg]
    mov ax, [es:si+SH_T_IR]           ; the live pair, whichever it is
    mov bx, [es:si+SH_T_IC]
    cmp ax, SH_TBL_NONE
    jne .have1
    mov ax, [es:si+SH_T_IR2]
    mov bx, [es:si+SH_T_IC2]
.have1:
    pop es
    call sh_biffw
    mov ax, bx
    call sh_biffw
    xor ax, ax                        ; the second pair is 2-D's alone
    call sh_biffw
    call sh_biffw
    jmp short .done
.twod:
    push es
    mov es, [sh_tblseg]
    mov ax, [es:si+SH_T_IR]
    mov bx, [es:si+SH_T_IC]
    mov cx, [es:si+SH_T_IR2]
    mov dx, [es:si+SH_T_IC2]
    pop es
    call sh_biffw
    mov ax, bx
    call sh_biffw
    mov ax, cx
    call sh_biffw
    mov ax, dx
    call sh_biffw
.done:
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_tbl_markall - every table's result cells carry SH_TBL_RESULT (81.114.10).
;
; Run ONCE, after a whole BIFF stream is in, and not as each DATATABLE
; arrives: the record follows the FIRST FORMULA of its range, so most of the
; cells it describes are still ahead of it in the file and marking then would
; mark cells that do not exist yet.
;
; THE SHEET IS IMPERSONATED per table, sh_tbl_runall's reason exactly:
; sh_bt_addcell keys on [sh_cursheet], so a workbook's second sheet would
; otherwise have its marks written into the first.
; -----------------------------------------------------------------------------
sh_tbl_markall:
    cmp word [sh_ntbl], 0
    je .out
    push ax
    push bx
    push cx
    push dx
    push si
    push es
    push word [sh_cursheet]
    xor si, si
    mov cx, [sh_ntbl]
.t:
    mov es, [sh_tblseg]
    xor ax, ax
    mov al, [es:si+SH_T_SHEET]
    mov [sh_cursheet], ax
    mov ax, [es:si+SH_T_R1]
    mov [sh_tbl_r1], ax
    mov ax, [es:si+SH_T_R2]
    mov [sh_tbl_r2], ax
    xor ax, ax
    mov al, [es:si+SH_T_C1]
    mov [sh_tbl_c1], ax
    xor ax, ax
    mov al, [es:si+SH_T_C2]
    mov [sh_tbl_c2], ax
    call sh_tbl_resultrect
    push cx
    push si
    mov bx, [sh_tbl_tr1]
.row:
    cmp bx, [sh_tbl_tr2]
    ja .rowsdone
    mov ax, [sh_tbl_tc1]
.col:
    cmp ax, [sh_tbl_tc2]
    ja .nextrow
    push ax
    push bx
    call sh_table_mark                 ; AX = col, BX = row
    pop bx
    pop ax
    inc ax
    jmp short .col
.nextrow:
    inc bx
    jmp short .row
.rowsdone:
    pop si
    pop cx
    add si, SH_T_SZ
    loop .t
    pop word [sh_cursheet]
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
.out:
    ret

; -----------------------------------------------------------------------------
; sh_tbl_clearguard - Edit > Clear over a selection that touches a table.
; in: the selection, and [sh_fdlg_sel] = 0 All / 1 Formulas / 2 Formats
; out: CF=1 REFUSED and [sh_msg] says why; CF=0 go ahead, and every table
;      the selection covered wholly has been dropped
;
; Excel's rule in its own words: "You must clear all the resulting values."
; A clear that covers every result cell of every table it touches is allowed
; and takes those tables with it; one that covers part of a table is refused.
;
; FORMATS IS EXEMPT, and that is Excel too rather than a shortcut: a table's
; cells can be formatted - that is why the guide tells you to - so clearing a
; number format off them is a format change and not an edit of the values.
; -----------------------------------------------------------------------------
sh_tbl_clearguard:
    cmp word [sh_fdlg_sel], 2
    je .ok
    cmp word [sh_ntbl], 0
    je .ok
    push ax
    push cx
    push di
    push es
    call sh_tbl_selnorm
    mov es, [sh_tblseg]
    xor di, di
    mov cx, [sh_ntbl]
.l:
    call sh_tbl_overlap
    cmp al, 1
    je .part
    add di, SH_T_SZ
    loop .l
    call sh_tbl_dropsel
    pop es
    pop di
    pop cx
    pop ax
.ok:
    clc
    ret
.part:
    mov word [sh_msg], sh_s_tblpart
    pop es
    pop di
    pop cx
    pop ax
    stc
    ret

; sh_table_mark - (AX=col, BX=row) is a result cell. 81.114.7's bit 7 of the
; border byte, which is where sh_prot_blocked already looks - so this costs a
; border record per result cell and nothing per edit. A border table that
; fills is a silent no-op, as it is at every other writer: the cell keeps the
; right NUMBER and loses only its protection.
sh_table_mark:
    push ax
    push bx
    push di
    push es
    SHOUT sh_bt_addcell
    jc .out
    mov es, [sh_bordseg]
    or byte [es:di+4], SH_TBL_RESULT
.out:
    pop es
    pop di
    pop bx
    pop ax
    ret

; sh_table_subst - read the value at AX,BX and write it into the cell at
; CX,DX. The one step the whole feature is: "on calculation, this cell
; reference is replaced by the respective value from the input value range".
sh_table_subst:
    push ax
    push bx
    push cx
    push dx
    cmp cx, SH_TBL_NONE
    je .out
    ; THE DESTINATION IS BANKED ACROSS THE READ. sh_getcell2's contract is
    ; "out: CF=1 occupied + DX = value" - DX is an OUTPUT - so holding the
    ; destination row there across the call hands sh_setvald the VALUE as a
    ; row. Every substitution went to row 4 for an input of 4, the input
    ; cell itself was never written, and the table filled with the formula's
    ; original answer repeated. Same family as sh_findcell not preserving DI
    ; (81.17): a documented output register eating a caller's live input.
    push cx                            ; the destination column...
    push dx                            ; ...and row
    SHOUT sh_getcell2                  ; the input VALUE, into sh_acc
    pop bx
    pop ax
    SHOUT sh_setvald                   ; ...and into the input cell
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_table_bank / sh_table_unbank - AX,BX = a cell; DI = a 22-byte slot.
; The first word of the slot says whether the cell existed at all; the
; twenty after it are its record. An absent input cell banks as absent and
; is deleted again on the way out, so a table does not leave a zero behind
; in a cell the user never filled.
sh_table_bank:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    push ds
    mov word [di+SH_TBS_HAVE], 0
    mov [di+SH_TBS_COL], ax            ; WHICH CELL, written before the
    mov [di+SH_TBS_ROW], bx            ; lookup: unbank needs it whether or
    cmp ax, SH_TBL_NONE                ; not there turns out to be a record,
    je .out                            ; and must not read it back out of one
    add di, SH_TBS_REC
    push di
    SHOUT sh_findcell                  ; CF=1 = DI is the record
    mov si, di
    pop di
    jnc .out
    mov word [di-SH_TBS_REC+SH_TBS_HAVE], 1
    ; DS:SI = the record, in the CELL segment; ES:DI = the slot, in ours.
    ; SI and DI are already that way round - `mov si, di` took the record and
    ; `pop di` the slot - and an `xchg si, di` left here from an earlier
    ; arrangement reversed them, so `rep movsb` wrote twenty bytes of the
    ; cell segment OVER THE PACKAGE'S OWN DATA at a record offset. The window
    ; came back blank, which is what a package scribbling on itself looks
    ; like. [sh_cellseg] is read in the same instruction that loads DS, so
    ; nothing reads this segment's own bss with DS already pointing away.
    push ds
    pop es
    mov ds, [sh_cellseg]
    mov cx, SH_C_SZ
    cld
    rep movsb
.out:
    pop ds
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

sh_table_unbank:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    mov ax, [di+SH_TBS_COL]
    mov bx, [di+SH_TBS_ROW]
    cmp ax, SH_TBL_NONE                ; no input cell of this kind at all
    je .out
    cmp word [di+SH_TBS_HAVE], 0
    je .gone
    mov si, di
    add si, SH_TBS_REC
    push si
    SHOUT sh_findcell
    pop si
    jnc .out
    mov es, [sh_cellseg]
    mov cx, SH_C_SZ
    cld
    rep movsb                          ; DS:SI the slot -> ES:DI the record
    jmp short .out
.gone:
    ; THE CELL DID NOT EXIST, so putting it back means taking it away again.
    ; sh_table_subst created it to substitute into, and leaving it would put
    ; a number in a cell the user never filled - the last value of the input
    ; range, sitting in the sheet looking like data.
    SHOUT sh_clearcell
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_idlg_open - in: AL = SH_ID_*. Preloads the field with the CURRENT value
; (the selection's reference, or the live row height / column width) so the
; dialog opens showing what it is about to change, and Enter alone is a no-op
; rather than a surprise.
; -----------------------------------------------------------------------------
sh_idlg_open:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    cmp word [sh_idlg_win], 0
    jne .out
    cmp al, SH_ID_NKIND
    jae .out
    mov [sh_idlg_kind], al
    xor ah, ah
    mov bx, ax
    shl bx, 1                          ; word index into the two tables
    mov ax, [sh_id_titles + bx]
    mov [sh_idlg_tpl + WT_TITLE], ax
    mov byte [sh_idlg_buf], 0
    cmp byte [sh_idlg_kind], SH_ID_RUN  ; ...and Run with the selection, where
    je .pregoto                        ; a macro used to start (81.63)
    cmp byte [sh_idlg_kind], SH_ID_SORT ; Sort prefills with the anchor, the
    je .pregoto                        ; same reference Goto shows - it is the
    cmp byte [sh_idlg_kind], SH_ID_SERSTEP  ; 81.72: a step of 1 is what
    je .preone                              ; almost every series wants, so
    cmp byte [sh_idlg_kind], SH_ID_PARSE ; 81.82: the parse line shows the
    je .preparse                       ; FIRST NON-BLANK cell of the column,
                                       ; and must be tested before the .jae
                                       ; below, which would open it empty
    cmp byte [sh_idlg_kind], SH_ID_DEFN ; key you get by pressing Enter
    jae .prenone                       ; Define Name and Find open EMPTY: there
    cmp byte [sh_idlg_kind], SH_ID_GOTO ; is no current value for either, and
    je .pregoto                        ; prefilling one would be a wrong guess
    cmp byte [sh_idlg_kind], SH_ID_ROWH
    je .prerowh
    mov ax, [sh_selcol]                ; the SELECTED column's own width, in
    SHOUT sh_colwidth                   ; characters, matching what OK reads
    jmp .prenum
.prerowh:
    mov ax, [sh_selrow]                ; the SELECTED row's own height, in
    SHOUT sh_rowtw                      ; POINTS as Excel's dialog shows it -
    or ax, ax                          ; 12.75 for the standard (81.60)
    jnz .prerh
    mov ax, SH_RH_STDTW
.prerh:
    SHOUT sh_twpts
    jmp short .precopy
.prenum:
    SHOUT sh_itoa
.precopy:
    mov di, sh_idlg_buf
    mov si, sh_numbuf
    SHOUT sh_strcpy_to_di
    jmp .haveinit
.preone:
    mov ax, 1                          ; Enter alone gives 1, 2, 3...
    jmp short .prenum
.pregoto:
    mov di, sh_idlg_buf                ; the selection, as 'A1'
    mov ax, [sh_selcol]
    SHOUT sh_colname
    mov si, sh_colbuf
    SHOUT sh_strcpy_to_di
    mov ax, [sh_selrow]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    SHOUT sh_strcpy_to_di
    jmp short .prenone                 ; ...AND OUT. This used to fall through
                                       ; into whatever came next, which was
                                       ; .prenone and harmless until 81.82 put
                                       ; a body there: sh_parse_pre then ran
                                       ; on every Goto, Sort and Run, throwing
                                       ; away the 'A1' just built and leaving
                                       ; the column's first label in its place.
                                       ; Sort's key came out as 'pear', was
                                       ; refused, and the command did nothing
.preparse:
    call sh_parse_pre                  ; ...and NO brackets yet: the Guide's
                                       ; own procedure makes Guess a step the
                                       ; user takes, and a line that opened
                                       ; pre-bracketed would make the button
                                       ; look like it had already been pressed
.prenone:
.haveinit:
    mov si, sh_idlg_line
    mov word [si + LN_BUF], sh_idlg_buf
    mov word [si + LN_MAX], SH_EDITMAX
    mov byte [si + LN_FOCUS], 1
    mov di, sh_idlg_buf
    SHOUT os88line_set                  ; sets LEN/CAR/VIEW from the content
    call OSAPI_VIDEO
    sub ax, SH_IDLG_W
    sar ax, 1
    mov [sh_idlg_tpl + WT_X], ax
    sub bx, SH_IDLG_H
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .placed
    mov bx, MBAR_H + 8
.placed:
    mov [sh_idlg_tpl + WT_Y], bx
    mov si, sh_idlg_tpl
    call OSAPI_WM_CREATE
    jc .out
    mov [sh_idlg_win], bx
    call OSAPI_WM_SHOW
    SHOUT sh_btfix                     ; the gesture (81.111), from here
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_idlg_paint - SI = the dialog window
; -----------------------------------------------------------------------------
sh_idlg_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si
    call OSAPI_WM_CONTENT
    mov [sh_idlg_ox], ax
    mov [sh_idlg_oy], dx
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov bl, [sh_idlg_kind]             ; the prompt for this kind
    xor bh, bh
    shl bx, 1
    mov si, [sh_id_prompts + bx]
    mov cx, [sh_idlg_ox]
    add cx, SH_IDLG_FX1
    mov dx, [sh_idlg_oy]
    add dx, 8
    call OSAPI_FONT_STR_XPARENT

    mov si, sh_idlg_line               ; the field's rect from the LIVE origin
    mov ax, [sh_idlg_ox]               ; every paint - the window moves
    add ax, SH_IDLG_FX1
    mov [si + LN_X1], ax
    mov ax, [sh_idlg_ox]
    add ax, SH_IDLG_FX2
    mov [si + LN_X2], ax
    mov ax, [sh_idlg_oy]
    add ax, SH_IDLG_FY1
    mov [si + LN_Y1], ax
    mov ax, [sh_idlg_oy]
    add ax, SH_IDLG_FY2
    mov [si + LN_Y2], ax
    SHOUT os88line_draw

    mov ax, [sh_idlg_ox]               ; 81.111: OK, Cancel (same x), and
    add ax, SH_IDLG_BTX1               ; for Parse Guess and Clear on
    mov [sh_idlg_btrects], ax          ; Cancel's row - the record's array,
    mov [sh_idlg_btrects+8], ax        ; drawn by index
    mov ax, [sh_idlg_ox]
    add ax, SH_IDLG_BTX2
    mov [sh_idlg_btrects+4], ax
    mov [sh_idlg_btrects+12], ax
    mov ax, [sh_idlg_ox]
    add ax, SH_IDLG_G1X1
    mov [sh_idlg_btrects+16], ax
    mov ax, [sh_idlg_ox]
    add ax, SH_IDLG_G1X2
    mov [sh_idlg_btrects+20], ax
    mov ax, [sh_idlg_ox]
    add ax, SH_IDLG_G2X1
    mov [sh_idlg_btrects+24], ax
    mov ax, [sh_idlg_ox]
    add ax, SH_IDLG_G2X2
    mov [sh_idlg_btrects+28], ax
    mov ax, [sh_idlg_oy]
    add ax, SH_IDLG_OKY1
    mov [sh_idlg_btrects+2], ax
    mov ax, [sh_idlg_oy]
    add ax, SH_IDLG_OKY2
    mov [sh_idlg_btrects+6], ax
    mov ax, [sh_idlg_oy]
    add ax, SH_IDLG_CAY1
    mov [sh_idlg_btrects+10], ax
    mov [sh_idlg_btrects+18], ax
    mov [sh_idlg_btrects+26], ax
    mov ax, [sh_idlg_oy]
    add ax, SH_IDLG_CAY2
    mov [sh_idlg_btrects+14], ax
    mov [sh_idlg_btrects+22], ax
    mov [sh_idlg_btrects+30], ax
    mov bx, sh_idlg_btrec
    mov word [bx + OS88UI_BT_N], 2     ; how many are LIVE: Parse's two only
    cmp byte [sh_idlg_kind], SH_ID_PARSE   ; for its own kind (81.82)
    jne .nb4
    mov word [bx + OS88UI_BT_N], 4
.nb4:
    mov al, 1
    SHOUT os88ui_btn
    mov al, 2
    SHOUT os88ui_btn

    cmp byte [sh_idlg_kind], SH_ID_PARSE   ; 81.82's two, and ONLY this kind's
    jne .nobrk
    mov al, 3
    SHOUT os88ui_btn
    mov al, 4
    SHOUT os88ui_btn
.nobrk:

    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_idlg_onkey - Enter is OK and Escape is Cancel, which is what a one-field
; dialog should do; os88line_key deliberately does NOT consume Enter (its own
; header says so) precisely so the caller can use it for this.
; -----------------------------------------------------------------------------
sh_idlg_onkey:
    push ax
    push si
    cmp al, 27
    je .cancel
    cmp al, 0x0D
    je .accept
    cmp byte [sh_idlg_kind], SH_ID_PARSE
    jne .toline
    cmp al, 0x20                       ; 81.82: "the only editing allowed in
    jb .toline                         ; the parse line is adding and deleting
    cmp al, 0x7E                       ; brackets" - so every PRINTABLE key but
    ja .toline                         ; the two brackets is dropped here, and
    cmp al, '['                        ; the control keys fall through to the
    je .toline                         ; field, which is what gives LEFT/RIGHT/
    cmp al, ']'                        ; BACKSPACE/DELETE the Guide names
    je .toline
    jmp .out
.toline:
    mov si, sh_idlg_line
    SHOUT os88line_key
    jc .out
    mov si, [sh_idlg_win]
    call sh_idlg_paint
    jmp .out
.accept:
    call sh_idlg_apply
    call sh_idlg_close
    SHOUT sh_idlg_after                 ; a Run or an INPUT goes on (81.63)
    jmp .out
.cancel:
    call sh_idlg_close
    SHOUT sh_idlg_after
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_idlg_onclick - CX,DX = the click, screen-absolute
; -----------------------------------------------------------------------------
sh_idlg_onclick:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov si, sh_idlg_line               ; the field's rect is already
    SHOUT os88line_click                ; screen-absolute from the last paint
    jnc .redraw
    jmp .out                           ; 81.111: the buttons are the
.redraw:                               ; library's gesture (sh_idlg_onbtn)
    mov si, [sh_idlg_win]
    call sh_idlg_paint
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_idlg_onbtn - AL = the button FIRED on the release (81.111): 1 OK,
; 2 Cancel, and Parse's 3 Guess and 4 Clear. What the press used to do
sh_idlg_onbtn:
    push si
    push di
    cmp al, 3
    je .doGuess
    cmp al, 4
    je .doClear
    cmp al, 1
    jne .doCancel
    call sh_idlg_apply
.doCancel:
    call sh_idlg_close
    SHOUT sh_idlg_after                ; a Run or an INPUT goes on (81.63)
    jmp short .out
.doGuess:
    call sh_parse_guess                ; both rewrite the LINE and leave the
    jmp short .reline                  ; dialog up - they are edits, not
.doClear:                              ; answers
    call sh_parse_clear
.reline:
    mov si, sh_idlg_line               ; the caret and view follow the new
    mov di, sh_idlg_buf                ; length, which os88line_set is what
    SHOUT os88line_set                 ; recomputes
    mov si, [sh_idlg_win]
    call sh_idlg_paint
.out:
    pop di
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_idlg_apply - dispatch on the kind. A value this cannot make sense of is
; REFUSED SILENTLY and the old one kept, rather than being coerced to zero:
; a column of width 0 is invisible and a Goto to a reference that does not
; parse has nowhere to go, so doing nothing is the honest answer.
; -----------------------------------------------------------------------------
sh_idlg_apply:
    push ax
    push bx
    push cx
    push dx
    push si
    cmp byte [sh_idlg_kind], SH_ID_PARSE
    je .parse
    cmp byte [sh_idlg_kind], SH_ID_DEFN
    je .defname
    cmp byte [sh_idlg_kind], SH_ID_FIND
    je .find
    cmp byte [sh_idlg_kind], SH_ID_GOTO
    je .goto
    cmp byte [sh_idlg_kind], SH_ID_SORT
    je .sortkey
    cmp byte [sh_idlg_kind], SH_ID_RUN
    je .run
    cmp byte [sh_idlg_kind], SH_ID_INPUT
    je .input
    cmp byte [sh_idlg_kind], SH_ID_SERSTEP
    je .serstep
    cmp byte [sh_idlg_kind], SH_ID_RECNAME
    je .recname
    cmp byte [sh_idlg_kind], SH_ID_TBLROW
    je .tblrow
    cmp byte [sh_idlg_kind], SH_ID_TBLCOL
    je .tblcol
    cmp byte [sh_idlg_kind], SH_ID_ROWH
    je .rowh
    mov si, sh_idlg_buf                ; the column width
    SHOUT sh_pnum_at
    jc .out                            ; not a number at all
    or ax, ax                          ; 81.73: ZERO HIDES IT, which is how
    jz .cwhide                         ; Excel hides a column and why this
    cmp ax, SH_CW_MINCH                ; COLUMN WIDTH IS IN CHARACTERS, which
    jb .out                            ; is Excel's own unit for it - the
    cmp ax, SH_CW_MAXCH                ; pixel width is a consequence, not the
    ja .out                            ; thing the user types
    ; THE SELECTED COLUMNS, each - Excel's Column Width (81.56). It set the
    ; one width the whole sheet had. The standard width is stored as 0, so a
    ; column set back to it costs a file nothing.
    mov cl, al
    cmp ax, [sh_defch]
    jne .cwset
    xor cl, cl
    jmp short .cwset
.cwhide:
    mov cl, SH_CW_HIDDEN               ; ...and a nonzero width typed over a
.cwset:                                ; selection that SPANS a hidden column
                                        ; unhides it, which is Excel's own way
                                        ; back and needs no second command:
                                        ; the loop below walks real columns
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .cwl
    xchg ax, bx
.cwl:
    SHOUT sh_colw_set
    inc ax
    cmp ax, bx
    jbe .cwl
    jmp .redraw
; 81.114: Data > Table, part one of two. An EMPTY field is not a refusal -
; it is how a one-input table says it has no row input cell - so the parse
; failing stores SH_TBL_NONE and the second half decides whether the pair
; makes sense. Deciding here would refuse a legal one-input table.
.tblrow:
    mov word [sh_tbl_ir], SH_TBL_NONE
    mov word [sh_tbl_ic], SH_TBL_NONE
    mov si, sh_idlg_buf
    SHOUT sh_upcase_at
    mov si, sh_idlg_buf
    cmp byte [si], 0
    je .tblrnext
    SHOUT sh_pcellref                  ; CF=1 = AX col, BX row
    jnc .tblrnext
    cmp ax, SH_COLS                    ; ON the sheet, as .gotoref asks: 'A0'
    jae .tblbad                        ; parses as row FFFFh, SH_TBL_NONE
    cmp bx, SH_ROWS                    ; itself, and a row past SH_ROWS packs
    jae .tblbad                        ; into the NEXT sheet's key
    mov [sh_tbl_ic], ax
    mov [sh_tbl_ir], bx
.tblrnext:
    mov byte [sh_tbl_pend], 1          ; ...and ask the other one AFTER this
                                       ; dialog has closed, not here:
                                       ; sh_idlg_open refuses while
                                       ; [sh_idlg_win] is set, and the apply
                                       ; runs BEFORE sh_idlg_close. The hook
                                       ; for it is sh_idlg_after, whose own
                                       ; comment says why it exists - "after
                                       ; and not inside the apply, because
                                       ; the run may open this same dialog
                                       ; again". 81.72's Series could call
                                       ; straight through only because its
                                       ; first half is the RADIO engine and
                                       ; this one is not.
                                       ; A CANCEL NEVER REACHES HERE, so the
                                       ; flag also makes cancelling the first
                                       ; half cancel the whole command
    jmp .out
.tblcol:
    mov word [sh_tbl_ir2], SH_TBL_NONE
    mov word [sh_tbl_ic2], SH_TBL_NONE
    mov si, sh_idlg_buf
    SHOUT sh_upcase_at
    mov si, sh_idlg_buf
    cmp byte [si], 0
    je .tblgo
    SHOUT sh_pcellref
    jnc .tblgo
    cmp ax, SH_COLS                    ; ...and the same for this one
    jae .tblbad
    cmp bx, SH_ROWS
    jae .tblbad
    mov [sh_tbl_ic2], ax
    mov [sh_tbl_ir2], bx
.tblgo:
    call sh_table_run                  ; CHART.OVL's own, so a near call
    jc .tblbad
    mov word [sh_msg], sh_s_id_tbldone
    jmp .redraw
.tblbad:
    mov word [sh_msg], sh_s_id_tblbad
    jmp .redraw
.rowh:
    ; ROW HEIGHT IS IN POINTS, Excel's unit, fractions allowed, and applies
    ; to THE SELECTED ROWS, each (81.60). It set the one height the whole
    ; sheet had, in pixels. The standard 12.75 is stored as no record at all
    mov si, sh_idlg_buf
    SHOUT sh_ptwips
    jc .out
    or ax, ax                          ; 81.73: ZERO HIDES IT. This used to
    jz .rhhide                         ; refuse, and said so - "Excel's 0
    cmp ax, SH_RH_TWMIN                ; (hidden) and its 409 points are both
    jb .out                            ; refused" - which is the line 81.73
    cmp ax, SH_RH_TWMAX                ; opens; a glyph still has to fit any
    ja .out                            ; height that is not zero
    mov cx, ax
    jmp short .rhhave
.rhhide:
    mov cx, SH_RH_HIDDEN
.rhhave:
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .rhl
    xchg ax, bx
.rhl:
    SHOUT sh_rowh_set
    jc .redraw                         ; the table is full: what fitted stays
    inc ax
    cmp ax, bx
    jbe .rhl
    jmp .redraw
.run:
    mov si, sh_idlg_buf                ; a macro is run by NAME, Excel's way -
    SHOUT sh_upcase_at                  ; or by the cell it starts in
    mov si, sh_idlg_buf
    SHOUT sh_name_lookup
    jc .runat
    mov si, sh_idlg_buf
    SHOUT sh_pcellref
    jnc .out
    cmp ax, SH_COLS
    jae .out
    cmp bx, SH_ROWS
    jae .out
.runat:
    mov [sh_macro_col], ax
    mov [sh_macro_row], bx
    mov byte [sh_macro_wait], SH_MW_START ; sh_idlg_after starts it
    jmp .out
.input:
    push di                            ; the answer, as typed; the run takes
    mov si, sh_idlg_buf                ; it up again once this has closed
    mov di, sh_macro_ans
    SHOUT sh_strcpy
    pop di
    mov byte [sh_macro_ansok], 1
    jmp .out
.goto:
    mov si, sh_idlg_buf
    SHOUT sh_upcase_at                  ; 'a1' and 'A1' both work, as in Excel
    mov si, sh_idlg_buf
    SHOUT sh_name_lookup                ; A NAME GOES TO ITS WHOLE RECTANGLE
    jnc .gotoref                       ; (81.30): sh_select collapses the
    push cx                            ; selection to one cell, so the far
    push dx                            ; corner is put back afterwards - and
    mov si, [sh_ownwin]                ; that is what makes Goto SALES then
    SHOUT sh_select                     ; Chart Column... chart SALES
    pop dx
    pop cx
    mov [sh_selcol2], cx
    mov [sh_selrow2], dx
    mov si, [sh_ownwin]
    SHOUT sh_repaint                    ; the band is wider than sh_select drew
    jmp .out
.gotoref:
    mov si, sh_idlg_buf
    SHOUT sh_pcellref                   ; CF=1 = AX col, BX row
    jnc .out
    cmp ax, SH_COLS
    jae .out
    cmp bx, SH_ROWS
    jae .out
    mov si, [sh_ownwin]                ; sh_select's own contract: SI must be
    SHOUT sh_select                     ; the window; it scrolls and repaints
    jmp .out                           ; itself - and a Goto DEFINES NO NAME,
                                       ; so it must not fall into .defname
.defname:
    mov si, sh_idlg_buf                ; the name binds THE SELECTION, which is
    mov ax, [sh_selcol]                ; where it was when the dialog opened -
    mov bx, [sh_selrow]                ; nothing can move it while a modal
    mov cx, [sh_selcol2]               ; dialog owns the input. BOTH corners
    mov dx, [sh_selrow2]               ; since 81.29: a dragged block names a
    SHOUT sh_name_def                   ; range, a single cell names itself
    mov word [sh_msg], sh_s_id_named
    jnc .redraw
    mov word [sh_msg], sh_s_id_nofit
    jmp .redraw
.find:
    call sh_docmd_find                 ; a neighbour here since 81.111
    jmp .redraw
; Data > Sort..., part one of two. The KEY is a reference, so it needs a field;
; the ORDER is a two-way pick, so it needs radios; and no dialog engine here
; has both. Asking in sequence is what File > Save As... already does - the
; format radio first, then the file dialog - so this follows the app's own
; idiom rather than growing a third engine.
; 81.74: the recording's own name, bound to the cell it is about to start in
; so Macro ▸ Run can list it. An EMPTY name is not a refusal - the Run dialog
; takes a reference too, and Excel's own Name field may be left alone.
.recname:
    mov si, sh_idlg_buf
    SHOUT sh_upcase_at
    cmp byte [sh_idlg_buf], 0
    je .recgo
    mov ax, [sh_rec_col]
    mov bx, [sh_rec_row]
    mov cx, ax
    mov dx, bx
    mov si, sh_idlg_buf
    SHOUT sh_name_def                   ; CF=1 = the table is full, which
    jnc .recgo                         ; 81.69's own pair of messages already
    mov word [sh_msg], sh_s_id_nofit   ; says
.recgo:
    SHOUT sh_rec_start
    jmp .redraw

; 81.72: the step value, and the whole of Data ▸ Series' second question.
; The TEXT is read rather than an integer parsed: Growth by 1.5 and a linear
; step of 0.25 are both ordinary, and sh_pnum_at answers integers only -
; which is what the three numeric kinds above it want and this one does not.
.parse:
    call sh_parse_do                   ; 81.82
    jmp .redraw
.serstep:
    mov si, sh_idlg_buf
    SHOUT sh_ser_setstep                ; CF=0 = not a number at all: refused
    jnc .out                           ; in silence, the same way a bad row
    call shm_series             ; height is (this engine's own header)
    jmp .redraw
.sortkey:
    mov si, sh_idlg_buf
    SHOUT sh_upcase_at                  ; 'b3' names the same column as 'B3'
    mov si, sh_idlg_buf
    SHOUT sh_pcellref                   ; AX = col, and only the COLUMN matters:
    jnc .badkey                        ; a key is a column, and the row the
    cmp ax, SH_COLS                    ; user happened to point at is not part
    jae .badkey                        ; of the question
    mov bx, [sh_selcol]                ; IT HAS TO BE INSIDE THE SELECTION.
    mov cx, [sh_selcol2]               ; Outside it, the sort would reorder a
    cmp bx, cx                         ; column the carry does not move, which
    jbe .keyspan                       ; breaks exactly the correspondence
    xchg bx, cx                        ; 81.19 exists to keep. REFUSED rather
.keyspan:                              ; than clamped - a clamp answers a
    cmp bx, cx                         ; different question, silently
    je .keyself                        ; a single-column selection sorts by
    cmp ax, bx                         ; ITSELF whatever was typed
    jb .badkey
    cmp ax, cx
    ja .badkey
    jmp short .keyok
.keyself:
    mov ax, bx                         ; 81.80 MAKES THAT LITERAL. The comment
                                       ; above was true of the intent and not
                                       ; of the code, which stored the TYPED
                                       ; column - so column A selected and C
                                       ; typed sorted A by C's order, the very
                                       ; thing the multi-column arm refuses.
                                       ; And it cannot survive 81.80 either
                                       ; way: the scan sees the BLOCK now, so
                                       ; a key outside it matches no cell and
                                       ; every row would stage blank
.keyok:
    mov [sh_sort_keycol], ax
    mov al, SH_FDK_SORT                ; ...and now ask for the order
    call sh_fdlg_open
    jmp .out
.badkey:
    mov word [sh_msg], sh_s_id_badkey
    jmp .redraw
.redraw:
    SHOUT sh_geom                       ; the cell size may have changed, so the
    mov si, [sh_ownwin]                ; visible row/column counts must be
    SHOUT sh_repaint                    ; recomputed before anything is drawn
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_idlg_close
; -----------------------------------------------------------------------------
sh_idlg_close:
    push ax
    push bx
    mov bx, [sh_idlg_win]
    or bx, bx
    jz .out
    mov word [sh_idlg_win], 0
    call OSAPI_WM_DESTROY               ; see sh_fdlg_close on why not CLOSE
.out:
    pop bx
    pop ax
    ret

section .text


; =============================================================================
; DEFINED NAMES (stage 3.0c) - Formula > Define Name... binds a name to the
; cell the selection is on, and a formula may then use that name anywhere a
; reference would go.
;
; A FIXED TABLE IN BSS rather than a claim: SH_NAME_CAP names at SH_NAME_REC
; bytes is under 400, which is small enough that a whole segment claim for it
; would be the wrong shape - and unlike the cell array it never grows during
; a repaint, so nothing here needs the shuffling that made the cells' claim
; worth having.
;
; Each record is a name, uppercased on entry, then its column and row. Names
; are compared uppercase because sh_pident already uppercases what it reads,
; and a spreadsheet where Total and TOTAL are different cells would be a trap
; rather than a feature.
;
; A NAME BINDS A RECTANGLE (stage 4.6). It used to bind one cell, and the
; reason written here was that "a range needs the reference-typed argument the
; value model still does not have (the same thing blocking VLOOKUP and the
; array functions)". That argument landed in 81.23, so the reason expired and
; the record grew the second corner it had been waiting for.
;
; A one-cell name is the same thing with both corners equal, so nothing that
; worked before behaves differently - `=Total` still reads one cell, and the
; dialog still binds whatever the selection is, which for a single cell is a
; 1x1 rectangle.
;
; STILL INSTANCE-WIDE, not per sheet: that needs a sheet field here plus a
; rule for what an unqualified name means from another sheet, and it would be
; worse guessed at.
; =============================================================================
SH_NAME_CAP  equ 16
SH_NAME_MAX  equ 12                  ; characters, not counting the NUL
; 81.83: THE GATHER BUFFER IS NOT THE NAME RECORD. Every identifier lexer in
; this file capped at SH_NAME_MAX, on the reasoning that a defined name is the
; longest thing collected and "a function name is shorter than either". That
; stopped being true when 81.63 added CALCULATE.NOW, which is THIRTEEN
; characters: it collected as CALCULATE.NO, matched nothing, and evaluated to
; #NAME? - in sh_functab, listed among the twenty, and unreachable since the
; day it was added. Raising SH_NAME_MAX instead would widen all SH_NAME_CAP
; defined-NAME RECORDS for a reason that has nothing to do with them.
SH_IDENT_MAX equ 20                  ; the longest name any lexer COLLECTS:
                                     ; CALCULATE.DOCUMENT is 18 (81.89)
SH_NAME_REC  equ SH_NAME_MAX + 1 + 8 ; text + NUL + col + row + col2 + row2

; -----------------------------------------------------------------------------
; sh_name_find - in: SI = an uppercase NUL name
; out: CF=1 and BX = its record offset in sh_names; CF=0 = no such name
; -----------------------------------------------------------------------------
sh_name_find:
    push ax
    push cx
    push si
    push di
    xor bx, bx
    mov cx, [sh_nnames]
    jcxz .no
.each:
    push cx
    push si
    mov di, sh_names
    add di, bx
.cmp:
    mov al, [si]
    cmp al, [di]
    jne .next
    or al, al
    jz .hit
    inc si
    inc di
    jmp .cmp
.next:
    pop si
    pop cx
    add bx, SH_NAME_REC
    loop .each
.no:
    pop di
    pop si
    pop cx
    pop ax
    clc
    ret
.hit:
    pop si
    pop cx
    pop di
    pop si
    pop cx
    pop ax
    stc
    ret

; -----------------------------------------------------------------------------
; sh_name_def - in: SI = a NUL name (uppercased here), AX/BX = the near
; corner, CX/DX = the far one. Both corners are stored as given; sh_foldrange
; normalises when it walks, so the dialog does not have to.
; out: CF=1 the table is full. Redefining an existing name REBINDS it, which
; is what Excel does and what makes the dialog usable twice.
; -----------------------------------------------------------------------------
sh_name_def:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov [sh_nm_col], ax
    mov [sh_nm_row], bx
    mov [sh_nm_col2], cx
    mov [sh_nm_row2], dx
    push si
    call sh_upcase_at
    mov di, sh_nm_buf                 ; clipped to SH_NAME_MAX, so a long name
    mov cx, SH_NAME_MAX               ; cannot run past its record
.copy:
    mov al, [si]
    or al, al
    jz .copied
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .copy
.copied:
    mov byte [di], 0
    pop si
    cmp byte [sh_nm_buf], 0
    je .full                          ; an empty name is not a name
    mov si, sh_nm_buf
    call sh_name_find
    jc .bind
    mov ax, [sh_nnames]
    cmp ax, SH_NAME_CAP
    jae .full
    mov cx, SH_NAME_REC
    mul cx
    mov bx, ax
    inc word [sh_nnames]
.bind:
    mov di, sh_names
    add di, bx
    mov si, sh_nm_buf
.wr:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .wr
    mov di, sh_names
    add di, bx
    add di, SH_NAME_MAX + 1
    mov ax, [sh_nm_col]
    mov [di], ax
    mov ax, [sh_nm_row]
    mov [di+2], ax
    mov ax, [sh_nm_col2]
    mov [di+4], ax
    mov ax, [sh_nm_row2]
    mov [di+6], ax
    clc
    jmp .out
.full:
    stc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_name_lookup - in: SI = an uppercase NUL name
; out: CF=1 and AX = col, BX = row (the NEAR corner, which is what a caller
; wanting one cell reads), with the far corner in CX/DX; CF=0 = not a name.
;
; The near corner stays in AX/BX because that is the shape sh_pcellref hands
; on and sh_pident's name path already speaks it - a one-cell name goes on
; behaving exactly as it did.
; -----------------------------------------------------------------------------
sh_name_lookup:
    push di
    call sh_name_find
    jnc .no
    mov di, sh_names
    add di, bx
    add di, SH_NAME_MAX + 1
    mov ax, [di]
    mov cx, [di+4]
    mov dx, [di+6]
    mov bx, [di+2]
    stc
    pop di
    ret
.no:
    pop di
    clc
    ret

; -----------------------------------------------------------------------------
; sh_name_list - build the pointer array sh_ldlg wants. out: CX = count.
; The pointers are into sh_names itself, which is fine because the list dialog
; only ever READS them and nothing can redefine a name while it is open.
; -----------------------------------------------------------------------------
sh_name_list:
    push ax
    push bx
    push di
    xor bx, bx
    xor di, di
    mov cx, [sh_nnames]
    jcxz .done
    push cx
.each:
    mov ax, sh_names
    add ax, bx
    mov [sh_nameptr + di], ax
    add di, 2
    add bx, SH_NAME_REC
    loop .each
    pop cx
.done:
    pop di
    pop bx
    pop ax
    ret

; =============================================================================
; The SCROLLING LIST dialog (stage 3.0c) - a framed list with a real scroll
; bar, OK and Cancel. Formula > Paste Function... and Formula > Paste Name...
; are both "pick one of a list too long to show at once", which is the one
; shape sh_fdlg_* cannot take: its radio rows are a fixed short array chosen
; by kind, and 25 function names is neither fixed nor short.
;
; The item source is a POINTER ARRAY plus a count, filled at open time, so the
; two kinds differ only in where that array comes from - sh_functab as it
; stands for the functions, and the name table built at run time for the names.
; That is also what makes a third kind free later.
;
; The bar is os88ui.inc's (SPEC.md 13.10), already opted into by this file for
; the grid's own two, so the dialog gets arrow cells, page regions and a
; proportional thumb without a line of its own.
; =============================================================================
SH_LD_FUNC   equ 0                   ; Formula > Paste Function...
SH_LD_NAME   equ 1                   ; Formula > Paste Name...
SH_LD_NUMFMT equ 2                   ; Format > Number... (81.55)
SH_LD_NKIND  equ 3

SH_LDLG_W    equ 332                 ; wide enough for Excel's longest built-in
SH_LDLG_LX1  equ 8                   ; code, $#,##0.00 ;[Red]($#,##0.00) - the
SH_LDLG_LY1  equ 22                  ; rows are not clipped. It was 222
SH_LDLG_LX2  equ 240
SH_LDLG_ROWH equ 12
SH_LDLG_ROWS equ 8                   ; visible at once
SH_LDLG_LY2  equ SH_LDLG_LY1 + SH_LDLG_ROWS * SH_LDLG_ROWH + 2
SH_LDLG_SBW  equ 14                  ; the bar sits just right of the list
SH_LDLG_BTX1 equ 262                 ; clear of the bar, which ends at
SH_LDLG_BTX2 equ 322                 ; SH_LDLG_LX2 + 2 + SH_LDLG_SBW
SH_LDLG_OKY1 equ 22
SH_LDLG_OKY2 equ 42
SH_LDLG_CAY1 equ 50
SH_LDLG_CAY2 equ 70
SH_LDLG_H    equ SH_LDLG_LY2 + SH_DLG_BMARG + TITLE_H + 1

sh_ldlg_tpl:
    dw 0, 0, SH_LDLG_W, SH_LDLG_H
    dw sh_s_ld_tfunc, sh_ldlg_paint_r, 0, sh_ldlg_click_r
; the resident doors (81.71.6) - sh_ldlg_open_r forces the module in before
; the window exists, 81.71.5.1's invariant
; 81.74.2: the resident doors for the last two engines. Same shape and same
; invariant as 81.71.5.1's: the OPEN forces the module in, and refuses to
; create a window at all if it cannot, so no paint holding the gfx lock is
; ever the call that has to read a disk.
; macro plan wave 0: sh_ident is not a resident function - is it one of the
; EXTENSION macro functions, whose names live in CHART.OVL? AX = the id
; (SH_FID_MX..) or 0xFF, and 0xFF too when there is no module to ask, which
; leaves the word #NAME? exactly as it was.
sh_mfind_r:
    push bp
    mov bp, SHM_MFIND
    call ch_ovcall
    pop bp
    jnc .out
    mov ax, 0xFF
.out:
    ret
; 81.81: Format > Justify, SHM_SORT's shape - one verb, no callback.
sh_justify_r:                       ; NOT sh_justify, which is 81.13's
    push bp                         ; align-a-value-INSIDE-a-cell helper and
    mov bp, SHM_JUSTIFY             ; has nothing to do with this command
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_noovl
.out:
    ret
; =============================================================================
; THE BUTTON GESTURE (SPEC.md 20.5.1.3, 81.111) - upstream's os88ui_btn takes a
; RECORD now and fires on the RELEASE, and a package's dialogs attach to it
; with os88ui_btninit. In this tree the dialog ENGINES run from CHART.OVL, so
; everything the kernel calls is RESIDENT: the record (initialised data, so the
; overlay's first paint already finds it whole), the release and drag doors
; (SH_BTDOORS) and the attach (sh_btattach, from each open door once the
; overlay has made the window). The overlay's painters fill the rects and draw
; through os88ui_btn; its click handlers no longer see a button's press.
; =============================================================================
sh_dlg_bflags: dw OS88UI_DEF, 0                ; OK is button 1, Cancel 2, in
sh_dlg_blfd:   dw sh_s_fd_ok, sh_s_fd_cancel   ; every dialog here: the flags
                                               ; are shared outright

; sh_btattach - BX = the record, AX = the window, SI/DI = its release/drag
; doors, DX = its own click door: UNLINK the record from os88ui's list, then
; os88ui_btninit. The unlink is not tidiness: btninit PREPENDS, so re-opening
; a dialog made its record's NEXT point at ITSELF, and a click whose walk had
; to pass it never returned. Preserves all registers
; sh_btfix - attach the record of EVERY dialog engine whose window is up.
; The engines' open routines run in CHART.OVL and are reached two ways - the
; resident door, and each other (Sort's key dialog opens its order dialog,
; Series and Extract likewise, File Format's OK the Save As), so the attach
; is the open routine's own last act rather than the door's. Attaching a
; window that already is only re-installs the same three procs
sh_bttab:  dw sh_fdlg_btrec, sh_fdlg_win, sh_fdlg_onup_r, sh_fdlg_ondrag_r, sh_fdlg_click_r
           dw sh_bdlg_btrec, sh_bdlg_win, sh_bdlg_onup_r, sh_bdlg_ondrag_r, sh_bdlg_click_r
           dw sh_idlg_btrec, sh_idlg_win, sh_idlg_onup_r, sh_idlg_ondrag_r, sh_idlg_click_r
           dw sh_ldlg_btrec, sh_ldlg_win, sh_ldlg_onup_r, sh_ldlg_ondrag_r, sh_ldlg_click_r
           dw sh_ndlg_btrec, sh_ndlg_win, sh_ndlg_onup_r, sh_ndlg_ondrag_r, sh_ndlg_onclick_r
           dw sh_df_btrec, sh_df_win, sh_df_onup_r, sh_df_ondrag_r, sh_df_onclick_r
sh_bttab_end:
sh_btfix:
    push ax
    push bx
    push dx
    push si
    push di
    push bp
    mov bp, sh_bttab
.l:
    mov bx, [ds:bp+2]
    mov ax, [bx]
    or ax, ax
    jz .n
    mov bx, [ds:bp]
    mov si, [ds:bp+4]
    mov di, [ds:bp+6]
    mov dx, [ds:bp+8]
    call sh_btattach
.n:
    add bp, 10
    cmp bp, sh_bttab_end
    jb .l
    pop bp
    pop di
    pop si
    pop dx
    pop bx
    pop ax
    clc                               ; the open's own CF=0, kept
    ret

sh_btattach:
    push cx
    push si
    mov si, os88ui_btlist - OS88UI_BT_NEXT   ; the head, as if it were a NEXT
.walk:
    mov cx, [si + OS88UI_BT_NEXT]
    jcxz .gone
    cmp cx, bx
    je .unlink
    mov si, cx
    jmp short .walk
.unlink:
    mov cx, [bx + OS88UI_BT_NEXT]
    mov [si + OS88UI_BT_NEXT], cx
.gone:
    pop si
    pop cx
    call os88ui_btninit
    ret


    SH_BTREC fdlg, 2, sh_dlg_blfd
    SH_BTDOORS fdlg, SHM_FDBTN
sh_fdlg_open_r:
    push bp
    mov bp, SHM_FDOPEN
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_noovl
.out:
    ret
sh_fdlg_paint_r:
    push bp
    mov bp, SHM_FDPAINT
    call ch_ovcall
    pop bp
    ret
sh_fdlg_click_r:
    push bp
    mov bp, SHM_FDCLICK
    call ch_ovcall
    pop bp
    ret
sh_fdlg_close_r:
    push bp
    mov bp, SHM_FDCLOSE
    call ch_ovcall
    pop bp
    ret
sh_fdlg_apply_r:
    push bp
    mov bp, SHM_FDAPPLY
    call ch_ovcall
    pop bp
    ret
; SH_ONCLOSE win_word - install AX, a resident negotiator, on the dialog the
; open just made, if it made one. HERE and not in the module's open: the proc
; is a near pointer in the WINDOW's segment (SPEC.md 75.1), and CHART.OVL runs
; banked (81.71.5.1). pushf: an open door's caller may read CF
%macro SH_ONCLOSE 1
    pushf
    push bx
    mov bx, [%1]
    or bx, bx
    jz %%none
    call OSAPI_WM_ONCLOSE
%%none:
    pop bx
    popf
%endmacro
sh_idlg_blab:  dw sh_s_idlg_ok, sh_s_idlg_can, sh_s_idlg_guess, sh_s_idlg_clear
sh_idlg_bflag: dw OS88UI_DEF, 0, 0, 0     ; 81.111: OK Cancel, and Parse's two
    SH_BTRECF idlg, 4, sh_idlg_blab, sh_idlg_bflag
    SH_BTDOORS idlg, SHM_IDBTN
sh_idlg_open_r:
    push bp
    mov bp, SHM_IDOPEN
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_noovl
.out:
    push ax
    mov ax, sh_idlg_cls_r
    SH_ONCLOSE sh_idlg_win
    pop ax
    ret
; sh_idlg_cls_r / sh_ldlg_cls_r - the two dialogs' CLOSE BOXES. A package's
; secondary window has no owner record, so the kernel's own close only HIDES
; it (SPEC.md 75.1, 81.96.2): the slot leaked, [sh_?dlg_win] stayed set, and
; every later open refused in silence - Format > Number closed by its box left
; Paste Function and Paste Name dead for the session (found photographing
; 1.8 on four adapters, 81.100). sh_onclick's gate-lock recovery covers the
; radio, Border and Form dialogs and never covered these two. Each negotiator
; takes the close ITSELF and answers CF = 1 (sc_close's shape): the input
; dialog as Esc, so an INPUT or a Run resumes exactly as Cancel resumes it;
; the list dialog has no Cancel beyond the close
sh_idlg_cls_r:
    mov ax, 27
    call sh_idlg_key_r
    stc
    ret
sh_ldlg_cls_r:
    push bx
    mov bx, [sh_ldlg_win]
    mov word [sh_ldlg_win], 0
    or bx, bx
    jz .gone
    call OSAPI_WM_DESTROY               ; see sh_fdlg_close on why not CLOSE
.gone:
    pop bx
    stc
    ret
sh_idlg_paint_r:
    push bp
    mov bp, SHM_IDPAINT
    call ch_ovcall
    pop bp
    ret
sh_idlg_key_r:
    push bp
    mov bp, SHM_IDKEY
    call ch_ovcall
    pop bp
    ret
sh_idlg_click_r:
    push bp
    mov bp, SHM_IDCLICK
    call ch_ovcall
    pop bp
    ret
    SH_BTREC ldlg, 2, sh_dlg_blfd
    SH_BTDOORS ldlg, SHM_LDBTN
sh_ldlg_open_r:
    push bp
    mov bp, SHM_LOPEN
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_noovl
.out:
    push ax
    mov ax, sh_ldlg_cls_r
    SH_ONCLOSE sh_ldlg_win
    pop ax
    ret
sh_ldlg_paint_r:
    push bp
    mov bp, SHM_LPAINT
    call ch_ovcall
    pop bp
    ret
sh_ldlg_click_r:
    push bp
    mov bp, SHM_LCLICK
    call ch_ovcall
    pop bp
    ret
sh_ldlg_wheel_r:                       ; W_ONWH: the kernel near-calls it in
    push bp                            ; THIS segment, so it is a thunk like
    mov bp, SHM_LWHEEL                 ; the paint's (81.71.5.1)
    call ch_ovcall
    pop bp
    ret
sh_ld_titles:  dw sh_s_ld_tfunc, sh_s_ld_tname, sh_s_ld_tnum
sh_ld_prompts: dw sh_s_ld_pfunc, sh_s_ld_pname, sh_s_ld_pnum
sh_s_ld_tnum:  db 'Format Number', 0
sh_s_ld_pnum:  db 'Format:', 0
sh_s_ld_tfunc: db 'Paste Function', 0
sh_s_ld_tname: db 'Paste Name', 0
sh_s_ld_pfunc: db 'Paste function:', 0
sh_s_ld_pname: db 'Paste name:', 0
sh_s_ld_none:  db '(none defined)', 0
; --- in CHART.OVL (81.71.6): the scrolling LIST dialog - Paste Function,
; Paste Name and Format Number's code list. Its data stays resident for
; 81.71.5.1's reason, and sh_ldlg_open_r forces the module in first.
section SH_MODSEC                      ; 81.71.6: the list dialog

; -----------------------------------------------------------------------------
; sh_ldlg_open - in: AL = SH_LD_*
; -----------------------------------------------------------------------------
sh_ldlg_open:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    cmp word [sh_ldlg_win], 0
    jne .out
    cmp al, SH_LD_NKIND
    jae .out
    mov [sh_ldlg_kind], al
    xor ah, ah
    mov bx, ax
    shl bx, 1
    mov ax, [sh_ld_titles + bx]
    mov [sh_ldlg_tpl + WT_TITLE], ax
    mov word [sh_ldlg_sel], 0
    mov word [sh_ldlg_top], 0
    cmp byte [sh_ldlg_kind], SH_LD_NAME
    je .names
    mov si, sh_functab
    cmp byte [sh_ldlg_kind], SH_LD_NUMFMT
    jne .isfunc
    mov ax, [sh_selcol]                    ; Excel's 21 codes, the selected
    mov bx, [sh_selrow]                    ; cell's own already chosen and in
    SHOUT sh_cell_nfid                      ; view (81.55)
    xor ah, ah
    mov [sh_ldlg_sel], ax
    sub ax, SH_LDLG_ROWS - 1
    jnc .nftop
    xor ax, ax
.nftop:
    mov [sh_ldlg_top], ax
    mov si, sh_nf_codes
.isfunc:
    mov [sh_ldlg_items], si                ; the function table IS the list -
    xor cx, cx                             ; it is already a NUL-terminated
                                           ; pointer array, which is what this
.fcount:                                   ; dialog wants
    cmp word [si], 0
    je .fdone
    inc cx
    add si, 2
    jmp .fcount
.fdone:
    mov [sh_ldlg_count], cx
    jmp .have
.names:
    SHOUT sh_name_list                      ; -> sh_nameptr[] and CX
    mov word [sh_ldlg_items], sh_nameptr
    mov [sh_ldlg_count], cx
.have:
    call OSAPI_VIDEO                  ; centred the same way every other
    sub ax, SH_LDLG_W                 ; dialog here is
    sar ax, 1
    mov [sh_ldlg_tpl + WT_X], ax
    sub bx, SH_LDLG_H
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .placed
    mov bx, MBAR_H + 8
.placed:
    mov [sh_ldlg_tpl + WT_Y], bx
    mov si, sh_ldlg_tpl
    call OSAPI_WM_CREATE               ; the window comes back in BX, NOT SI -
    jc .out                            ; SI is still the template - and it is
    mov [sh_ldlg_win], bx
    push ax
    mov ax, sh_ldlg_wheel_r            ; the wheel scrolls the list (13.18)
    call OSAPI_WM_ONWHEEL
    pop ax
    call OSAPI_WM_SHOW                 ; created HIDDEN, so the show is not
    SHOUT sh_btfix                     ; the gesture (81.111), from here
                                       ; optional. No WF_KEEPH: 147 rows from
                                       ; y 28 ends at 175, inside a CGA's
                                       ; band (81.100 measured it).
                                       ; sh_btfix is this fork's own form of
                                       ; main's inline os88ui_btninit: ONE
                                       ; table walked for whichever dialog is
                                       ; open, rather than the call repeated
                                       ; at every open (81.111)
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_sbset - fill the scroll block from the live list state. One place,
; because the painter and the hit-tester must not disagree about the geometry
; (which is the whole reason os88ui_sbhit derives everything from the block).
; -----------------------------------------------------------------------------
sh_ldlg_sbset:
    push ax
    mov ax, [sh_ldlg_ox]
    add ax, SH_LDLG_LX2 + 2
    mov [sh_ldsb + 0], ax
    add ax, SH_LDLG_SBW - 1
    mov [sh_ldsb + 4], ax
    mov ax, [sh_ldlg_oy]
    add ax, SH_LDLG_LY1
    mov [sh_ldsb + 2], ax
    mov ax, [sh_ldlg_oy]
    add ax, SH_LDLG_LY2
    mov [sh_ldsb + 6], ax
    mov ax, [sh_ldlg_count]
    cmp ax, SH_LDLG_ROWS
    jae .tot
    mov ax, SH_LDLG_ROWS
.tot:
    mov [sh_ldsb + 8], ax
    mov word [sh_ldsb + 10], SH_LDLG_ROWS
    mov ax, [sh_ldlg_top]
    mov [sh_ldsb + 12], ax
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_paint
; -----------------------------------------------------------------------------
sh_ldlg_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si
    call OSAPI_WM_CONTENT
    mov [sh_ldlg_ox], ax
    mov [sh_ldlg_oy], dx

    mov al, CWHITE
    call OSAPI_SET_COLOR
    mov ax, [sh_ldlg_ox]
    mov bx, [sh_ldlg_oy]
    mov cx, ax
    add cx, SH_LDLG_W - 3
    mov dx, bx
    add dx, SH_LDLG_H - TITLE_H - 3
    call OSAPI_GFX_FILL
    mov al, CBLACK
    call OSAPI_SET_COLOR

    mov cx, [sh_ldlg_ox]              ; the prompt
    add cx, SH_LDLG_LX1
    mov dx, [sh_ldlg_oy]
    add dx, 6
    mov bl, [sh_ldlg_kind]
    xor bh, bh
    shl bx, 1
    mov si, [sh_ld_prompts + bx]
    call OSAPI_FONT_STR_XPARENT

    mov ax, [sh_ldlg_ox]              ; the list box's own frame
    add ax, SH_LDLG_LX1
    mov bx, [sh_ldlg_oy]
    add bx, SH_LDLG_LY1
    mov cx, [sh_ldlg_ox]
    add cx, SH_LDLG_LX2
    mov dx, [sh_ldlg_oy]
    add dx, SH_LDLG_LY2
    call OSAPI_GFX_FRAME

    cmp word [sh_ldlg_count], 0
    jne .rows
    mov cx, [sh_ldlg_ox]              ; an empty list says so rather than
    add cx, SH_LDLG_LX1 + 6           ; showing a blank box
    mov dx, [sh_ldlg_oy]
    add dx, SH_LDLG_LY1 + 4
    mov si, sh_s_ld_none
    call OSAPI_FONT_STR_XPARENT
    jmp .buttons
.rows:
    mov word [sh_ldlg_i], 0
.rloop:
    mov ax, [sh_ldlg_i]
    cmp ax, SH_LDLG_ROWS
    jae .rdone
    add ax, [sh_ldlg_top]
    cmp ax, [sh_ldlg_count]
    jae .rdone
    mov [sh_ldlg_idx], ax
    mov ax, [sh_ldlg_i]
    mov cx, SH_LDLG_ROWH
    mul cx
    add ax, [sh_ldlg_oy]
    add ax, SH_LDLG_LY1 + 2
    mov [sh_ldlg_rowy], ax
    mov ax, [sh_ldlg_idx]
    cmp ax, [sh_ldlg_sel]
    jne .plain
    mov ax, [sh_ldlg_ox]              ; the selected row is inverted, the same
    add ax, SH_LDLG_LX1 + 1           ; way the menu's hot item is
    mov bx, [sh_ldlg_rowy]
    mov cx, [sh_ldlg_ox]
    add cx, SH_LDLG_LX2 - 1
    mov dx, bx
    add dx, SH_LDLG_ROWH - 1
    call OSAPI_GFX_FILL
    clc
    call OSAPI_GFX_PEN
    mov al, CWHITE
    call OSAPI_SET_COLOR
    jmp .rtext
.plain:
    clc
    call OSAPI_GFX_PEN
    mov al, CBLACK
    call OSAPI_SET_COLOR
.rtext:
    mov bx, [sh_ldlg_items]
    mov ax, [sh_ldlg_idx]
    shl ax, 1
    add bx, ax
    mov si, [bx]
    mov cx, [sh_ldlg_ox]
    add cx, SH_LDLG_LX1 + 4
    mov dx, [sh_ldlg_rowy]
    add dx, 2
    call OSAPI_FONT_STR_XPARENT
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov ax, [sh_ldlg_i]
    inc ax
    mov [sh_ldlg_i], ax
    jmp .rloop
.rdone:
    call sh_ldlg_sbset
    mov bx, sh_ldsb
    SHOUT os88ui_sbar
.buttons:
    mov ax, [sh_ldlg_ox]               ; 81.111: the record's array, OK over
    add ax, SH_LDLG_BTX1               ; Cancel at one x
    mov [sh_ldlg_btrects+0], ax
    mov [sh_ldlg_btrects+8], ax
    mov ax, [sh_ldlg_ox]
    add ax, SH_LDLG_BTX2
    mov [sh_ldlg_btrects+4], ax
    mov [sh_ldlg_btrects+12], ax
    mov ax, [sh_ldlg_oy]
    add ax, SH_LDLG_OKY1
    mov [sh_ldlg_btrects+2], ax
    mov ax, [sh_ldlg_oy]
    add ax, SH_LDLG_OKY2
    mov [sh_ldlg_btrects+6], ax
    mov ax, [sh_ldlg_oy]
    add ax, SH_LDLG_CAY1
    mov [sh_ldlg_btrects+10], ax
    mov ax, [sh_ldlg_oy]
    add ax, SH_LDLG_CAY2
    mov [sh_ldlg_btrects+14], ax
    mov bx, sh_ldlg_btrec
    mov al, 1
    SHOUT os88ui_btn
    mov al, 2
    SHOUT os88ui_btn
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_onclick - in: CX/DX = absolute click point
; -----------------------------------------------------------------------------
sh_ldlg_onclick:
    push ax
    push bx
    push cx
    push dx
    mov bx, [sh_ldlg_win]
    or bx, bx
    jz .out
    push cx
    push dx
    call OSAPI_WM_CONTENT
    mov [sh_ldlg_ox], ax
    mov [sh_ldlg_oy], dx
    pop dx
    pop cx

    call sh_ldlg_sbset                ; the bar first: it owns a strip of its
    mov ax, cx                        ; own and a click there is never a row
    mov bx, dx
    mov cx, ax
    mov dx, bx
    mov bx, sh_ldsb
    SHOUT os88ui_sbhit
    or al, al
    jz .notbar
    cmp al, OS88UI_SBUP
    je .up
    cmp al, OS88UI_SBDOWN
    je .down
    cmp al, OS88UI_SBPGUP
    je .pgup
    cmp al, OS88UI_SBPGDN
    je .pgdn
    jmp .out
.up:
    cmp word [sh_ldlg_top], 0
    je .out
    dec word [sh_ldlg_top]
    jmp .redraw
.down:
    call sh_ldlg_maxtop
    cmp [sh_ldlg_top], ax
    jae .out
    inc word [sh_ldlg_top]
    jmp .redraw
.pgup:
    mov ax, [sh_ldlg_top]
    cmp ax, SH_LDLG_ROWS
    jae .pgu2
    xor ax, ax
    jmp .pgset
.pgu2:
    sub ax, SH_LDLG_ROWS
    jmp .pgset
.pgdn:
    mov ax, [sh_ldlg_top]
    add ax, SH_LDLG_ROWS
    push ax
    call sh_ldlg_maxtop
    mov bx, ax
    pop ax
    cmp ax, bx
    jbe .pgset
    mov ax, bx
.pgset:
    mov [sh_ldlg_top], ax
    jmp .redraw
.notbar:
    mov ax, cx                        ; the buttons are the library's gesture
    sub ax, [sh_ldlg_ox]              ; (81.111, sh_ldlg_onbtn): only the
    mov bx, dx                        ; list is left to this handler
    sub bx, [sh_ldlg_oy]
    cmp ax, SH_LDLG_LX1
    jb .out
    cmp ax, SH_LDLG_LX2
    ja .out
    sub bx, SH_LDLG_LY1 + 2
    jb .out
    mov ax, bx
    xor dx, dx
    mov bx, SH_LDLG_ROWH
    div bx
    cmp ax, SH_LDLG_ROWS
    jae .out
    add ax, [sh_ldlg_top]
    cmp ax, [sh_ldlg_count]
    jae .out
    mov [sh_ldlg_sel], ax
.redraw:
    mov si, [sh_ldlg_win]             ; sh_ldlg_paint, NOT sh_repaint: that one
    call sh_ldlg_paint                ; repaints THE SHEET into whatever window
                                       ; SI names, so calling it here drew the
                                       ; grid, the menu bar and the status line
                                       ; inside this dialog's own rect. Every
                                       ; other dialog here calls its own
                                       ; painter for exactly this reason.
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_onwheel - W_ONWH for the Paste list (SPEC.md 13.18): AX = signed
; notches. WHEEL_STEPS items a notch - an item is the list's line - set the
; way the bar's page arms set [sh_ldlg_top], and repainted by the same
; sh_ldlg_paint they end in. A list already at that end draws nothing.
; -----------------------------------------------------------------------------
sh_ldlg_onwheel:
    push ax
    push bx
    push cx
    call sh_ldlg_sbset                ; total, fit and pos (the rect is not
    mov bx, sh_ldsb                   ; read)
    mov cx, 1
    SHOUT os88ui_sbwheel              ; resident: this body is in CHART.OVL
    jc .out
    mov [sh_ldlg_top], ax
    call sh_ldlg_paint                ; SI: W_ONWH names this window
.out:
    pop cx
    pop bx
    pop ax
    ret

; sh_ldlg_onbtn - AL = the button fired on the release (81.111): 1 OK, 2 Cancel
; main calls os88ui_btnup inline here; 81.111 made that ONE shared release
; handler, so this is only what to do with the answer.
sh_ldlg_onbtn:
    cmp al, 1
    jne .cancel
    call sh_ldlg_apply
.cancel:
    jmp sh_ldlg_close

; sh_ldlg_maxtop - AX = the largest legal sh_ldlg_top
sh_ldlg_maxtop:
    mov ax, [sh_ldlg_count]
    cmp ax, SH_LDLG_ROWS
    ja .some
    xor ax, ax
    ret
.some:
    sub ax, SH_LDLG_ROWS
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_apply - paste the chosen item into the cell being edited.
;
; A FUNCTION arrives with its opening parenthesis, because that is what the
; user would type next and Excel's own Paste Function does the same; a NAME
; arrives bare. Both go through sh_editstart/sh_flkey so the field's caret and
; bounds behave exactly as they do for typing - there is no second path into
; the edit buffer to keep in step.
; -----------------------------------------------------------------------------
sh_ldlg_apply:
    push ax
    push bx
    push si
    cmp word [sh_ldlg_count], 0
    je .out
    cmp byte [sh_ldlg_kind], SH_LD_NUMFMT
    jne .paste
    mov al, [sh_ldlg_sel]              ; a FORMAT, to the whole selection -
    SHOUT sh_nf_apply                   ; empty cells too, as Excel's is
    jmp .done
.paste:
    mov bx, [sh_ldlg_items]
    mov ax, [sh_ldlg_sel]
    shl ax, 1
    add bx, ax
    mov ax, [bx]
    mov [sh_ldlg_src], ax             ; the chosen string, in BSS rather than
                                       ; in SI - see sh_ldlg_putc
    cmp byte [sh_editing], 0
    jne .append
    SHOUT sh_editstart                 ; nothing being edited: start a formula,
    mov al, '='                       ; since a bare function name is not one
    call sh_ldlg_putc
.append:
    call sh_ldlg_puts
    cmp byte [sh_ldlg_kind], SH_LD_FUNC
    jne .done
    mov al, '('                       ; a function arrives with its opening
    call sh_ldlg_putc                 ; parenthesis, as Excel's own does
.done:
    mov si, [sh_ownwin]
    SHOUT sh_repaint
.out:
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_putc - one character into the edit field, in: AL.
;
; TWO REGISTER CONTRACTS MEET HERE and they want different things in the same
; register. os88line_key reads AH as a SCAN CODE, so AH must be cleared or a
; leftover one makes the field do something else with a perfectly good
; character. And SI must not be the string being copied out, as it was:
; sh_flkey points SI at the field's own block. Both are set here, once,
; instead of at each call site.
; -----------------------------------------------------------------------------
sh_ldlg_putc:
    push ax
    push si
    xor ah, ah
    mov si, [sh_ownwin]
    SHOUT sh_flkey
    pop si
    pop ax
    ret

; sh_ldlg_puts - every character of the string at sh_ldlg_src
sh_ldlg_puts:
    push ax
    push si
    mov si, [sh_ldlg_src]
.lp:
    mov al, [si]
    or al, al
    jz .done
    inc si
    push si
    call sh_ldlg_putc
    pop si
    jmp .lp
.done:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ldlg_close
; -----------------------------------------------------------------------------
sh_ldlg_close:
    push ax
    push bx
    mov bx, [sh_ldlg_win]
    or bx, bx
    jz .out
    mov word [sh_ldlg_win], 0
    call OSAPI_WM_DESTROY               ; see sh_fdlg_close on why not CLOSE
.out:
    pop bx
    pop ax
    ret


; =============================================================================
; 81.82: Data > Parse - distribute ONE column of text across several, cutting
; at FIXED CHARACTER POSITIONS.
;
; Not at delimiters: that is what the CSV reader is for, and the two solve
; different problems. Parse is for a report PRINTED by another program, where
; every record arrived in one cell and the fields line up by column because
; they were laid out for a printer.
;
; The contract is Excel 2.0's Reference Guide, "Data Parse command":
;
;   - the range is any number of rows and ONE COLUMN wide
;   - the PARSE LINE shows the first non-blank cell, and the only editing
;     allowed in it is adding and deleting BRACKETS
;   - the settings made on that first cell apply to every cell in the range
;   - GUESS places a set of brackets; CLEAR removes them all
;   - it fills cells TO THE RIGHT, and what is there is overwritten
;
; A bracket PAIR is one field. The positions are counted in the underlying
; text, so the brackets themselves do not shift the columns they mark - which
; is why sh_parse_fields counts non-bracket characters as it walks.
; =============================================================================
section SH_MODSEC                      ; 81.82: Data > Parse, CHART.OVL

SH_PA_MAXF equ 8                       ; fields, and so columns written. Eight
                                       ; is what fits SH_EDITMAX at a useful
                                       ; width; a ninth bracket pair is
                                       ; ignored rather than refused, since
                                       ; the line is the user's own editing

; -----------------------------------------------------------------------------
; sh_parse_pre - the parse line's initial contents: the FIRST NON-BLANK cell
; of the selected column, as the Guide says. Not the first cell: a range
; selected from a heading row down would otherwise open on an empty line and
; Guess would have nothing to work with.
; -----------------------------------------------------------------------------
sh_parse_pre:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    mov byte [sh_idlg_buf], 0
    call sh_parse_span
    mov bx, [sh_pa_r1]
.row:
    cmp bx, [sh_pa_r2]
    ja .out
    mov ax, [sh_pa_col]
    SHOUT sh_findcell
    jnc .next
    mov es, [sh_cellseg]
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    jne .next                          ; a VALUE is nothing to parse, so it is
    mov si, [es:di+SH_C_FOFF]          ; skipped rather than refused - only a
    mov es, [sh_txtseg]                ; TEXT cell can be the sample
    mov di, sh_idlg_buf
    mov cx, SH_EDITMAX
.cp:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .out
    inc si
    inc di
    dec cx
    jnz .cp
    mov byte [di], 0
    jmp short .out
.next:
    inc bx
    jmp .row
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_parse_span - the selection's rows, ordered, and its LEFT column. The
; Guide's "no more than one column wide" is not enforced: a wider selection
; parses its left column, which is the same answer and needs no refusal.
sh_parse_span:
    push ax
    push bx
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .r
    xchg ax, bx
.r:
    mov [sh_pa_r1], ax
    mov [sh_pa_r2], bx
    mov ax, [sh_selcol]
    mov bx, [sh_selcol2]
    cmp ax, bx
    jbe .c
    mov ax, bx
.c:
    mov [sh_pa_col], ax
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_parse_clear - every bracket out of the line, in place.
; -----------------------------------------------------------------------------
sh_parse_clear:
    push ax
    push si
    push di
    mov si, sh_idlg_buf
    mov di, sh_idlg_buf
.l:
    mov al, [si]
    inc si
    cmp al, '['
    je .l
    cmp al, ']'
    je .l
    mov [di], al
    inc di
    or al, al
    jnz .l
    pop di
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_parse_guess - bracket the fields the way the data lays them out.
;
; THE RULE IS TWO SPACES. A printed report separates its columns by a RUN of
; spaces and puts single spaces inside a field, so `Jones  1234  45.60` is
; three fields and `New York  10001` is two - which a split on every space
; would get wrong in the one case that matters most.
;
; It clears first, so pressing Guess twice is the same as pressing it once.
; -----------------------------------------------------------------------------
; NO `movsb` IN HERE, and that is not a style note. It moves DS:SI to ES:DI,
; and ES in a package is whatever was last loaded; every other string move in
; this file sets ES first and on purpose. The first draft used it, so the
; brackets - written DS-relative with `mov [di]` - landed in sh_pa_tmp while
; every character between them went through ES to somewhere else, and the
; parse line came back as a single '['.
sh_parse_guess:
    push ax
    push bx
    push cx
    push si
    push di
    call sh_parse_clear
    mov si, sh_idlg_buf                ; SI walks the cleared text
    mov di, sh_pa_tmp                  ; DI builds the bracketed line
    xor cx, cx                         ; fields so far
.field:
    cmp byte [si], ' '                 ; skip the run between fields, and it
    jne .start                         ; goes into the output as it stands
    mov al, [si]
    mov [di], al
    inc si
    inc di
    jmp .field
.start:
    cmp byte [si], 0
    je .done
    cmp cx, SH_PA_MAXF
    jae .rest                          ; out of fields: the tail goes through
    mov byte [di], '['                 ; unbracketed rather than being cut
    inc di
    inc cx
.body:
    mov al, [si]
    or al, al
    jz .close
    cmp al, ' '
    jne .take
    cmp byte [si+1], ' '               ; ONE space is inside the field; TWO
    je .close                          ; end it
    cmp byte [si+1], 0
    je .close
.take:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    jmp .body
.close:
    mov byte [di], ']'
    inc di
    jmp .field
.rest:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .rest
    jmp short .copy
.done:
    mov byte [di], 0
.copy:
    mov si, sh_pa_tmp                  ; back over the line, clipped to what
    mov di, sh_idlg_buf                ; the field can hold
    mov cx, SH_EDITMAX
.cp:
    mov al, [si]
    mov [di], al
    or al, al
    jz .out
    inc si
    inc di
    dec cx
    jnz .cp
    mov byte [di], 0
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_parse_fields - the bracket pairs in the line, as offsets into the text
; WITHOUT the brackets. [sh_pa_n] pairs, starts in sh_pa_st and ends in
; sh_pa_en. CF=1 when there are none.
;
; The count that matters is of NON-BRACKET characters: a bracket marks a
; position in the cell's text and occupies none of it, so a line with three
; pairs in it still describes the same columns of the original.
; -----------------------------------------------------------------------------
sh_parse_fields:
    push ax
    push bx
    push cx
    push si
    mov word [sh_pa_n], 0
    xor cx, cx                         ; the text column
    xor bx, bx                         ; open field? 0 no
    mov si, sh_idlg_buf
.l:
    mov al, [si]
    inc si
    or al, al
    jz .done
    cmp al, '['
    je .open
    cmp al, ']'
    je .close
    inc cx                             ; an ordinary character: one column on
    jmp .l
.open:
    or bx, bx
    jnz .l                             ; '[[' - the second is noise
    mov bx, [sh_pa_n]
    cmp bx, SH_PA_MAXF
    jae .l
    shl bx, 1
    mov [sh_pa_st + bx], cx
    mov bx, 1
    jmp .l
.close:
    or bx, bx
    jz .l                              ; ']' with no '[' - noise
    mov bx, [sh_pa_n]
    cmp bx, SH_PA_MAXF
    jae .noroom
    shl bx, 1
    mov [sh_pa_en + bx], cx
    inc word [sh_pa_n]
.noroom:
    xor bx, bx
    jmp .l
.done:
    or bx, bx                          ; a '[' never closed runs to the end,
    jz .fin                            ; which is what an unfinished edit
    mov bx, [sh_pa_n]                  ; looks like and is the useful reading
    cmp bx, SH_PA_MAXF
    jae .fin
    shl bx, 1
    mov [sh_pa_en + bx], cx
    inc word [sh_pa_n]
.fin:
    cmp word [sh_pa_n], 0
    je .none
    clc
    jmp short .out
.none:
    stc
.out:
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_parse_do - OK. Split every row of the column at those offsets and write
; the pieces across, starting in the parsed column itself.
; -----------------------------------------------------------------------------
sh_parse_do:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    call sh_parse_span
    call sh_parse_fields
    jc .nofields
    push word [sh_selcol]              ; 81.46: every cell it can write - the
    push word [sh_selcol2]             ; column and the fields to its right,
    mov ax, [sh_pa_col]                ; across the rows - is asked first
    mov [sh_selcol], ax
    add ax, [sh_pa_n]
    dec ax
    cmp ax, SH_COLS
    jb .pacols
    mov ax, SH_COLS - 1                ; ...as far as the edge sh_parse_row
.pacols:                               ; stops at
    mov [sh_selcol2], ax
    SHOUT sh_prot_blocked
    pop word [sh_selcol2]
    pop word [sh_selcol]
    jc .out                            ; refused, and [sh_msg] says why
    mov al, SH_UL_PARSE
    SHOUT sh_undo_begin
    mov bx, [sh_pa_r1]
.row:
    cmp bx, [sh_pa_r2]
    ja .done
    call sh_parse_row
    inc bx
    jmp .row
.done:
    SHOUT sh_undo_end
    mov word [sh_msg], sh_s_pa_done
    jmp short .out
.nofields:
    mov word [sh_msg], sh_s_pa_nobrk
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_parse_row - in: BX = row. The cell's text is taken FIRST, whole, into
; sh_pa_src, because the very first field written lands on the cell it came
; from and would otherwise be read after it was overwritten.
sh_parse_row:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov byte [sh_pa_src], 0
    mov ax, [sh_pa_col]
    SHOUT sh_findcell
    jnc .out                           ; an empty row stays empty: there is
    mov es, [sh_cellseg]               ; nothing to distribute and clearing
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT   ; the row to its right would
    jne .out                           ; destroy data on the strength of a
    mov si, [es:di+SH_C_FOFF]          ; blank
    mov es, [sh_txtseg]
    mov di, sh_pa_src
    mov cx, SH_EDITMAX
.cp:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .have
    inc si
    inc di
    dec cx
    jnz .cp
    mov byte [di], 0
.have:
    xor cx, cx                         ; the field index
.f:
    cmp cx, [sh_pa_n]
    jae .out
    call sh_parse_cut                  ; sh_pa_fld = this field, trimmed
    mov ax, [sh_pa_col]
    add ax, cx
    cmp ax, SH_COLS
    jae .out                           ; off the right edge: stop, silently -
    mov si, sh_pa_fld                  ; there is nowhere to put it
    call sh_parse_put
    inc cx
    jmp .f
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_parse_cut - in: CX = field index; out: sh_pa_fld = sh_pa_src's characters
; [st..en), leading and trailing spaces removed. A field that starts past the
; end of a short row is empty, which is right: the record simply had nothing
; in that column.
sh_parse_cut:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, cx
    shl bx, 1
    mov dx, [sh_pa_en + bx]            ; DX = end column
    mov bx, [sh_pa_st + bx]            ; BX = start column
    mov si, sh_pa_src
    mov di, sh_pa_fld
    xor cx, cx                         ; the column SI is looking at
.find:
    cmp cx, bx
    jae .take
    cmp byte [si], 0
    je .fin
    inc si
    inc cx
    jmp .find
.take:
    cmp cx, dx
    jae .fin
    mov al, [si]
    or al, al
    jz .fin
    mov [di], al
    inc di
    inc si
    inc cx
    jmp .take
.fin:
    mov byte [di], 0
    mov si, sh_pa_fld                  ; trim: leading first, then trailing
    mov di, sh_pa_fld
.lead:
    cmp byte [si], ' '
    jne .shift
    inc si
    jmp .lead
.shift:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .shift
.trail:
    cmp di, sh_pa_fld + 1
    jbe .done
    dec di
    cmp byte [di-1], ' '
    jne .done
    mov byte [di-1], 0
    jmp .trail
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_parse_put - in: AX = col, BX = row, SI = the field. THE FIELD'S SPELLING
; DECIDES, exactly as a CSV field's does (81.40): a complete number is a
; number, TRUE/FALSE is the logical, everything else is a label, and an error
; SPELLING comes back as text - which is CSV's answer too, because neither
; format has a type to say otherwise.
sh_parse_put:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    cmp byte [si], 0
    je .empty
    push ax
    push si
    SHOUT fp_atof                      ; CF=1: no number there at all. SHOUT
                                       ; and not `call`: this body is in the
                                       ; module and fp_atof is resident, which
                                       ; os88ovlchk catches as a near call
                                       ; across a segment boundary (68.10)
    jc .notnum
    mov al, [si]                       ; ...and anything it did not consume
    or al, al                          ; ENTIRELY is not one either, which is
    jnz .notnum                        ; what keeps '3.5kg' a label
    pop si
    pop ax
    SHOUT sh_acc_store
    SHOUT sh_setvald
    jmp short .out
.notnum:
    pop si
    pop ax
    SHOUT sh_setlabel                  ; TRUE/FALSE inside it, label otherwise
    jmp short .out
.empty:
    SHOUT sh_clearcell
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

section .text

section .text


; -----------------------------------------------------------------------------
; sh_upcase_at - uppercase the NUL string at SI in place. Preserves all.
; -----------------------------------------------------------------------------
sh_upcase_at:
    push ax
    push si
.loop:
    mov al, [si]
    or al, al
    jz .done
    cmp al, 'a'
    jb .next
    cmp al, 'z'
    ja .next
    sub al, 32
    mov [si], al
.next:
    inc si
    jmp .loop
.done:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_pnum_at - read an unsigned decimal from the NUL string at SI.
; out: CF=0 and AX = the value; CF=1 if there was no digit at all or it ran
; past 65535. Leading blanks are skipped; anything after the digits is
; ignored, so '12 wide' reads as 12.
; -----------------------------------------------------------------------------
sh_pnum_at:
    push bx
    push cx
    push dx
    push si
    xor ax, ax
    xor cx, cx                         ; cx = how many digits were seen
.skip:
    cmp byte [si], ' '
    jne .loop
    inc si
    jmp .skip
.loop:
    mov bl, [si]
    cmp bl, '0'
    jb .done
    cmp bl, '9'
    ja .done
    cmp ax, 6553                       ; 6553*10 is the last product that fits,
    ja .over                           ; checked BEFORE the shifts rather than
    mov dx, ax                         ; from the carry of one of them - the
    shl ax, 1                          ; first two can overflow silently
    shl ax, 1
    add ax, dx
    shl ax, 1                          ; ax = ax*10 (8086: shift by 1 or CL)
    sub bl, '0'
    xor bh, bh
    add ax, bx
    jc .over
    inc cx
    inc si
    jmp .loop
.done:
    or cx, cx
    jz .none
    clc
    jmp .out
.over:
.none:
    stc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    ret

; sh_ptwips - SI = a height typed in points, "15" or "12.75" -> AX = twips,
; CF=1 when it is not one. Digits past the hundredths are read and dropped
; (81.60)
sh_ptwips:
    push bx
    push cx
    push dx
    push si
    push di
    xor ax, ax                         ; AX = whole points
    xor cx, cx                         ; CX = the digits seen
.sp:
    cmp byte [si], ' '
    jne .int
    inc si
    jmp short .sp
.int:
    mov bl, [si]
    sub bl, '0'
    cmp bl, 9
    ja .frac
    cmp ax, 100                        ; 999 points at most, so the twips
    jae .bad                           ; below cannot overflow
    mov dx, 10
    mul dx
    xor bh, bh
    add ax, bx
    inc cx
    inc si
    jmp short .int
.frac:
    mov dx, 20
    mul dx
    mov di, ax                         ; DI = the whole points, in twips
    xor dx, dx                         ; DX = hundredths
    cmp byte [si], '.'
    jne .tail
    inc si
    mov bl, [si]
    sub bl, '0'
    cmp bl, 9
    ja .tail
    mov al, 10
    mul bl
    mov dx, ax                         ; the tenths
    inc cx
    inc si
    mov bl, [si]
    sub bl, '0'
    cmp bl, 9
    ja .tail
    xor bh, bh
    add dx, bx                         ; ...and the hundredths
    inc si
.more:
    mov bl, [si]
    sub bl, '0'
    cmp bl, 9
    ja .tail
    inc si
    jmp short .more
.tail:
    cmp byte [si], ' '
    jne .end
    inc si
    jmp short .tail
.end:
    cmp byte [si], 0
    jne .bad
    jcxz .bad
    mov ax, dx                         ; a hundredth of a point is a fifth of
    add ax, 2                          ; a twip: rounded
    mov bl, 5
    div bl
    xor ah, ah
    add ax, di
    clc
    jmp short .out
.bad:
    stc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; sh_twpts - AX = twips -> sh_numbuf = points, "15" or "12.75" (81.60)
sh_twpts:
    push ax
    push bx
    push dx
    push si
    xor dx, dx
    mov bx, 20
    div bx                             ; AX = whole points, DX = twips over
    call sh_itoa
    mov ax, dx
    or ax, ax
    jz .out
    mov si, sh_numbuf
.end:
    cmp byte [si], 0
    je .at
    inc si
    jmp short .end
.at:
    mov byte [si], '.'
    mov bl, 5
    mul bl                             ; AX = hundredths, 5..95
    mov bl, 10
    div bl                             ; AL = tenths, AH = hundredths
    add al, '0'
    mov [si+1], al
    mov byte [si+2], 0
    or ah, ah
    jz .out
    add ah, '0'
    mov [si+2], ah
    mov byte [si+3], 0
.out:
    pop si
    pop dx
    pop bx
    pop ax
    ret

; =============================================================================
; Formula > Note... (stage 3.0b) - Excel 2.1's cell notes, and the FIRST
; consumer of apps/os88text.inc. Everything above this point that takes typed
; input takes it one character at a time into a fixed field; this is the first
; place in Sheet where a user can type a paragraph.
;
; It edits sh_notetext, a bss COPY, and only writes through to the note table
; on OK - so Cancel is free and a commit refused for want of arena space leaves
; the old note exactly as it was, rather than half-replacing it.
;
; It also remembers the cell it was opened on (sh_notecol/sh_noterow) instead
; of reading the live selection at OK time. This dialog is NON-MODAL like every
; other one here, so the user can move the selection while it is open; writing
; to whatever happens to be selected on OK would attach the note to the wrong
; cell, which is exactly the kind of quiet wrongness that is hard to notice.
; =============================================================================
SH_NDLG_W    equ 300
SH_NDLG_BX1  equ 8                   ; the text box, content-relative
SH_NDLG_BY1  equ 24
SH_NDLG_BX2  equ 214
SH_NDLG_BY2  equ 112                 ; -> 24 columns x 10 rows = 240 cells,
                                     ; which is what SH_NOTEMAX is sized from
SH_NDLG_BTX1 equ 222                 ; OK / Cancel, both 64 wide -
                                     ; 'Cancel' is 6 glyphs at the fixed 8px
                                     ; cell, so a narrower button clips its
                                     ; own label (it did, at 34)
SH_NDLG_BTX2 equ 286
SH_NDLG_OKY1 equ 24
SH_NDLG_OKY2 equ 44
SH_NDLG_CAY1 equ 52
SH_NDLG_CAY2 equ 72
SH_NDLG_H    equ SH_NDLG_BY2 + SH_DLG_BMARG + TITLE_H + 1   ; the text box is
                                     ; the lowest element, not the buttons

sh_ndlg_tpl:
    dw 0, 0, SH_NDLG_W, SH_NDLG_H
    dw sh_s_ndlg_title, sh_ndlg_paint_r, sh_ndlg_onkey_r, sh_ndlg_onclick_r

sh_s_ndlg_title: db 'Note', 0
sh_s_ndlg_cell:  db 'Cell:', 0

; 81.102: THE ENGINE IS IN CHART.OVL, with os88text.inc - the box's only
; consumer - and these are its resident doors. The template, its strings
; (the kernel and FONT_STR read them through DS) and sh_note_load (Paste
; uses it too) stay here. The open door forces the module in before the
; window exists, 81.71.5.1's invariant, and installs the close negotiator:
; the kernel's close box only HID this window (75.1), so [sh_noteopen]
; stayed set and Formula > Note refused for the session - 81.100.1's
; defect, in the one dialog that pass did not look at
    SH_BTREC ndlg, 2, sh_dlg_blfd
    SH_BTDOORS ndlg, SHM_NDBTN
sh_ndlg_open_r:
    push bp
    mov bp, SHM_NOPEN
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_noovl
.out:
    push ax
    mov ax, sh_ndlg_cls_r
    SH_ONCLOSE sh_ndlg_win
    pop ax
    ret
sh_ndlg_paint_r:
    push bp
    mov bp, SHM_NPAINT
    call ch_ovcall
    pop bp
    ret
sh_ndlg_onkey_r:
    push bp
    mov bp, SHM_NKEY
    call ch_ovcall
    pop bp
    ret
sh_ndlg_onclick_r:
    push bp
    mov bp, SHM_NCLICK
    call ch_ovcall
    pop bp
    ret
; the close box is Cancel: the edit copy is dropped, the table untouched
sh_ndlg_cls_r:
    push bx
    mov bx, [sh_ndlg_win]
    mov word [sh_ndlg_win], 0
    mov byte [sh_noteopen], 0
    or bx, bx
    jz .gone
    call OSAPI_WM_DESTROY
.gone:
    pop bx
    stc
    ret

section SH_MODSEC                      ; 81.102: the Note dialog, CHART.OVL

; -----------------------------------------------------------------------------
; sh_ndlg_open - load the selected cell's note into the edit buffer and put
; the dialog up. Same single-instance gate as sh_bdlg_open.
; -----------------------------------------------------------------------------
sh_ndlg_open:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    cmp byte [sh_noteopen], 0
    jne .out
    mov ax, [sh_selcol]                ; pin the cell NOW - see this section's
    mov [sh_notecol], ax               ; header on why not at OK time
    mov bx, [sh_selrow]
    mov [sh_noterow], bx
    mov byte [sh_notetext], 0          ; no note = an empty box, not stale text
    SHOUT sh_nt_get
    jnc .nonote
    mov si, ax                         ; ax = the text's offset in the arena
    SHOUT sh_note_load
.nonote:
    mov si, sh_notebox                 ; the field, over the buffer
    mov word [si + TX_BUF], sh_notetext
    mov word [si + TX_MAX], SH_NOTEMAX
    mov word [si + TX_TOP], 0
    mov byte [si + TX_FOCUS], 1
    mov di, sh_notetext
    call os88text_set                  ; sets LEN/CAR from the buffer's content
    call OSAPI_VIDEO
    sub ax, SH_NDLG_W
    sar ax, 1
    mov [sh_ndlg_tpl + WT_X], ax
    sub bx, SH_NDLG_H
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .placed
    mov bx, MBAR_H + 8
.placed:
    mov [sh_ndlg_tpl + WT_Y], bx
    mov si, sh_ndlg_tpl
    call OSAPI_WM_CREATE
    jc .out
    mov [sh_ndlg_win], bx
    mov byte [sh_noteopen], 1
    call OSAPI_WM_SHOW
    SHOUT sh_btfix                     ; the gesture (81.111), from here
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_note_load - copy the NUL string at [sh_txtseg]:SI into sh_notetext,
; clipped to SH_NOTEMAX-1. in: SI = the arena offset. Preserves everything.
;
; A byte-at-a-time copy through ES rather than a rep movsb, so DS is never
; changed at all - the alternative wants DS pointing at the claim, and every
; sh_* symbol in this file is DS-relative.
section .text                          ; sh_note_load stays: Paste uses it too

; -----------------------------------------------------------------------------
sh_note_load:
    push ax
    push cx
    push si
    push di
    push es
    mov es, [sh_txtseg]
    mov di, sh_notetext
    mov cx, SH_NOTEMAX - 1
.copy:
    jcxz .done
    mov al, [es:si]
    or al, al
    jz .done
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .copy
.done:
    mov byte [di], 0
    pop es
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ndlg_paint - SI = the dialog window
section SH_MODSEC

; -----------------------------------------------------------------------------
sh_ndlg_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si
    call OSAPI_WM_CONTENT               ; ax,dx = the content origin
    mov [sh_ndlg_ox], ax
    mov [sh_ndlg_oy], dx

    mov cx, ax                          ; the 'Cell:' label and the reference
    add cx, SH_NDLG_BX1
    mov dx, [sh_ndlg_oy]
    add dx, 6
    mov al, CBLACK
    call OSAPI_SET_COLOR
    mov si, sh_s_ndlg_cell
    call OSAPI_FONT_STR_XPARENT
    mov di, sh_tbuf                     ; the reference, built the same way the
    mov ax, [sh_notecol]                ; formula bar's own name box builds it
    SHOUT sh_colname
    mov si, sh_colbuf
    SHOUT sh_strcpy_to_di
    mov ax, [sh_noterow]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    SHOUT sh_strcpy_to_di
    mov cx, [sh_ndlg_ox]
    add cx, SH_NDLG_BX1 + 48
    mov dx, [sh_ndlg_oy]
    add dx, 6
    mov si, sh_tbuf
    call OSAPI_FONT_STR_XPARENT

    mov si, sh_notebox                  ; the field's rect is refreshed from
    mov ax, [sh_ndlg_ox]                ; the LIVE content origin every paint,
    add ax, SH_NDLG_BX1                 ; because the window moves - the same
    mov [si + TX_X1], ax                ; painter/hit-tester drift the scroll
    mov ax, [sh_ndlg_ox]                ; bars already had to solve
    add ax, SH_NDLG_BX2
    mov [si + TX_X2], ax
    mov ax, [sh_ndlg_oy]
    add ax, SH_NDLG_BY1
    mov [si + TX_Y1], ax
    mov ax, [sh_ndlg_oy]
    add ax, SH_NDLG_BY2
    mov [si + TX_Y2], ax
    call os88text_draw

    mov ax, [sh_ndlg_ox]                ; OK over Cancel at one x, into the
    add ax, SH_NDLG_BTX1                ; record's array (81.111)
    mov [sh_ndlg_btrects], ax
    mov [sh_ndlg_btrects+8], ax
    mov ax, [sh_ndlg_ox]
    add ax, SH_NDLG_BTX2
    mov [sh_ndlg_btrects+4], ax
    mov [sh_ndlg_btrects+12], ax
    mov ax, [sh_ndlg_oy]
    add ax, SH_NDLG_OKY1
    mov [sh_ndlg_btrects+2], ax
    mov ax, [sh_ndlg_oy]
    add ax, SH_NDLG_OKY2
    mov [sh_ndlg_btrects+6], ax
    mov ax, [sh_ndlg_oy]
    add ax, SH_NDLG_CAY1
    mov [sh_ndlg_btrects+10], ax
    mov ax, [sh_ndlg_oy]
    add ax, SH_NDLG_CAY2
    mov [sh_ndlg_btrects+14], ax
    mov bx, sh_ndlg_btrec
    mov al, 1
    SHOUT os88ui_btn
    mov al, 2
    SHOUT os88ui_btn

    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ndlg_onkey - AL = ascii, AH = scan code. The field gets first refusal;
; Escape is the only key this dialog claims for itself.
; -----------------------------------------------------------------------------
sh_ndlg_onkey:
    push ax
    push si
    cmp al, 27
    je .cancel
    mov si, sh_notebox
    call os88text_key
    jc .out                             ; the field did not want it
    call os88text_draw                  ; the BOX, not the whole dialog: the
    jmp .out                            ; labels and both buttons did not
                                        ; change, and os88ui_btn's own erase
                                        ; would flash them on every keystroke.
                                        ; The block's rect is refreshed by
                                        ; every real paint and the window
                                        ; cannot move mid-callback (the gfx
                                        ; lock is held) - the same trust the
                                        ; onclick hit-test below already
                                        ; places in it
.cancel:
    call sh_ndlg_close
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ndlg_onclick - CX,DX = the click, screen-absolute
; -----------------------------------------------------------------------------
sh_ndlg_onclick:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov si, sh_notebox                  ; the field first: its own rect is
    call os88text_click                 ; already screen-absolute from the
    jc .out                             ; last paint, so no conversion here;
                                        ; the buttons are the library's
                                        ; gesture (81.111, sh_ndlg_onbtn)
    mov si, sh_notebox                  ; only the caret moved: redraw the
    call os88text_draw                  ; box, not the dialog's chrome
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_ndlg_onbtn - AL = the button fired on the release (81.111): 1 OK, 2 Cancel
sh_ndlg_onbtn:
    cmp al, 1
    jne .cancel
    call sh_ndlg_apply
.cancel:
    jmp sh_ndlg_close

; -----------------------------------------------------------------------------
; sh_ndlg_apply - commit the edit buffer to the cell the dialog was opened on.
; An empty buffer removes the note (sh_nt_set's own rule), which is how this
; dialog clears one - Excel 2.1's Note dialog has no separate Delete either.
; -----------------------------------------------------------------------------
sh_ndlg_apply:
    push ax
    push bx
    push si
    mov ax, [sh_notecol]
    mov bx, [sh_noterow]
    mov si, sh_notetext
    SHOUT sh_nt_set                      ; CF=1 = table or arena full. Silent,
                                        ; the same scope limit sh_bdlg_apply
                                        ; documents for a full border table.
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ndlg_close
; -----------------------------------------------------------------------------
sh_ndlg_close:
    push ax
    push bx
    mov bx, [sh_ndlg_win]
    or bx, bx
    jz .out
    mov word [sh_ndlg_win], 0
    mov byte [sh_noteopen], 0
    call OSAPI_WM_DESTROY               ; see sh_fdlg_close on why not CLOSE
.out:
    pop bx
    pop ax
    ret

section .text

; =============================================================================
; FORMULA ▸ REFERENCE (SPEC.md 81.108), Excel's own: "Converts the selected
; references in the formula bar from relative to absolute, from absolute to
; mixed, and from mixed back to relative ... if the insertion point is within
; or next to the reference. Shortcut key: F4."  A1 > $A$1 > A$1 > $A1 > A1.
;
; THE REFERENCE is the run of '$', letters and digits the caret is in or
; touching, and it has to READ as one - $?, one or two letters, $?, digits,
; and nothing after - so a function name (SUM), a defined name (RATE1) or a
; sheet-qualified cell's sheet part (Sheet2!, which '!' ends) is left alone.
;
; THE EDIT goes through the field's own keys (sh_flkey), as Paste Function's
; does: Right to the reference's end, Backspace over it, the new form typed -
; so the field's text, length, caret, view and SHEET's sh_editlen stay one
; story, and the caret ends after the reference, where a second F4 finds it.
; A1 style only: in R1C1 a reference reads R[1]C[2], and the item is greyed
; there (sh_refmark), which this checks again for a macro's fire of it
; =============================================================================
section SH_MODSEC
sh_refcyc:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    cmp byte [sh_editing], 0
    je .out
    cmp byte [sh_editbuf], '='
    jne .out
    cmp byte [sh_a1style], 0
    jne .out
    mov bx, [sh_fline + LN_CAR]        ; the caret
    mov dx, [sh_fline + LN_LEN]
    mov si, bx
.left:                                 ; start: back over reference chars,
    cmp si, 1                          ; never over the leading '='
    jbe .ldone
    mov al, [sh_editbuf + si - 1]
    call sh_refch
    jnc .ldone
    dec si
    jmp short .left
.ldone:
    mov di, bx
.right:
    cmp di, dx
    jae .rdone
    mov al, [sh_editbuf + di]
    call sh_refch
    jnc .rdone
    inc di
    jmp short .right
.rdone:
    cmp si, di
    jae .out                           ; nothing at the caret
    mov [sh_rf_s], si
    mov [sh_rf_e], di
    mov [sh_rf_c], bx
    ; --- parse [si, di): $? L{1,2} $? D+ ---
    xor ah, ah                         ; bit 1 column absolute, bit 0 row
    cmp byte [sh_editbuf + si], '$'
    jne .let
    or ah, 2
    inc si
.let:
    mov cx, si                         ; the letters start here
.letl:
    cmp si, di
    jae .bad
    mov al, [sh_editbuf + si]
    or al, 0x20                        ; fold to lower case
    cmp al, 'a'
    jb .letd
    cmp al, 'z'
    ja .letd
    inc si
    jmp short .letl
.letd:
    mov [sh_rf_l0], cx
    sub cx, si
    neg cx                             ; CX = letters counted
    jz .bad
    cmp cx, 2
    ja .bad
    mov [sh_rf_ln], cx
    cmp byte [sh_editbuf + si], '$'
    jne .dig
    or ah, 1
    inc si
.dig:
    mov [sh_rf_d0], si
.digl:
    cmp si, di
    jae .digd
    mov al, [sh_editbuf + si]
    cmp al, '0'
    jb .bad
    cmp al, '9'
    ja .bad
    inc si
    jmp short .digl
.digd:
    mov cx, si
    sub cx, [sh_rf_d0]
    jz .bad                            ; no row digits
    cmp cx, 5                          ; ...or more than a row can have
    ja .bad                            ; (16,384 is five), which also bounds
                                       ; sh_rf_buf: $ + 2 + $ + 5 + NUL
    ; --- the next form: 00 > 11 > 01 > 10 > 00 (column bit, row bit) ---
    mov bl, ah
    xor bh, bh
    mov ah, [cs:sh_rf_next + bx]       ; CS: the table is the module's own
    mov di, sh_rf_buf
    test ah, 2
    jz .nc
    mov byte [di], '$'
    inc di
.nc:
    mov si, [sh_rf_l0]
    mov cx, [sh_rf_ln]
.cl:
    mov al, [sh_editbuf + si]
    mov [di], al
    inc si
    inc di
    loop .cl
    test ah, 1
    jz .nr
    mov byte [di], '$'
    inc di
.nr:
    mov si, [sh_rf_d0]
.cd:
    cmp si, [sh_rf_e]
    jae .built
    mov al, [sh_editbuf + si]
    mov [di], al
    inc si
    inc di
    jmp short .cd
.built:
    mov byte [di], 0
    ; --- through the field's own keys ---
    mov cx, [sh_rf_e]
    sub cx, [sh_rf_c]
    jz .atend
.rk:
    mov ax, 0x4D00                     ; Right
    call sh_rf_key
    loop .rk
.atend:
    mov cx, [sh_rf_e]
    sub cx, [sh_rf_s]
.bk:
    mov ax, 8                          ; Backspace
    call sh_rf_key
    loop .bk
    mov si, sh_rf_buf
.ty:
    mov al, [si]
    or al, al
    jz .out
    xor ah, ah
    call sh_rf_key
    inc si
    jmp short .ty
.bad:
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret
sh_rf_next: db 3, 2, 0, 1              ; indexed by (col << 1) | row

; sh_refch - CF=1 when AL can be part of a reference: '$', a letter, a digit
sh_refch:
    cmp al, '$'
    je .yes
    cmp al, '0'
    jb .no
    cmp al, '9'
    jbe .yes
    push ax
    or al, 0x20
    cmp al, 'a'
    jb .nop
    cmp al, 'z'
    ja .nop
    pop ax
.yes:
    stc
    ret
.nop:
    pop ax
.no:
    clc
    ret

; sh_rf_key - AX to the entry field, as a keystroke (sh_ldlg_putc's shape)
sh_rf_key:
    push si
    mov si, [sh_ownwin]
    SHOUT sh_flkey
    pop si
    ret
section .text

; =============================================================================
; DATA ▸ FORM (SPEC.md 81.71.5) - one record at a time, in a dialog.
;
; THE SIXTH DIALOG ENGINE, and the first that needed to be: sh_fdlg is a radio
; column, sh_idlg one text field, sh_bdlg check boxes, sh_ldlg a list and
; sh_ndlg one multi-line box. A form is N labelled fields over a record, with
; a button row and a position counter, and none of the five could be bent to
; it without becoming a sixth anyway.
;
; IT NEEDS NO OVERLAY. Unlike Find/Extract/Delete this never touches the
; criteria engine - the Reference Guide is explicit that "Data Form works
; independently of the other database commands ... and if you use criteria
; within the form to find specific database records, those criteria do not
; affect the criteria specified in the criteria range". So the whole of it is
; the DATABASE name, sh_cell_totext and sh_commit, all three resident.
;
; ONE LINE EDITOR, NOT N. Every field is drawn in a box, but only the focused
; one is live; Tab and Shift+Tab move the focus, and the field is written back
; to its cell as the focus LEAVES it. Excel saves a record's changes when you
; move off the record, which is observably the same thing here because
; `Restore` - the one command that can tell the two apart - is not implemented
; (see 81.71.5's own list of what is missing and why).
; =============================================================================
SH_DF_W      equ 360
SH_DF_MAXF   equ 5                   ; field rows on screen at once. A wider
                                     ; database scrolls this window of them
                                     ; with the focus rather than refusing:
                                     ; sh_df_top is the first one shown
SH_DF_ROWTOP equ 20                  ; ...below the `n of m` counter
SH_DF_ROWH   equ 16
SH_DF_LBLX   equ 8
SH_DF_BOXX1  equ 104
SH_DF_BOXX2  equ SH_DF_W - 12
SH_DF_BTW    equ 64
SH_DF_BTGAP  equ 8
SH_DF_BTY1   equ SH_DF_ROWTOP + SH_DF_MAXF * SH_DF_ROWH + 8
SH_DF_BTY2   equ SH_DF_BTY1 + 18
SH_DF_H      equ SH_DF_BTY2 + SH_DLG_BMARG + TITLE_H + 1
SH_DF_NBT    equ 5
SH_DF_LW     equ 11                  ; the label and value columns, in CELLS.
SH_DF_VW     equ 29                  ; OSAPI_FONT_RUN erases exactly its own
                                     ; cells (6.1), so a SHORTER string drawn
                                     ; over a longer one leaves the tail of it
                                     ; behind - `Veg` over `Fruit` read `Vegit`
                                     ; on the first run of tests/sheetform.py.
                                     ; Padding to a fixed width is the fix that
                                     ; stays ONE PASS; filling the box first
                                     ; and then lettering it would be the
                                     ; double-draw 6.1 exists to refuse

sh_df_tpl:                             ; the RESIDENT thunks, not the module's
    dw 0, 0, SH_DF_W, SH_DF_H          ; own labels: a template holds near
    dw sh_s_df_title, sh_df_paint_r, sh_df_onkey_r, sh_df_onclick_r

sh_s_df_title: db 'Form', 0
sh_s_df_of:    db ' of ', 0
sh_df_btns:    dw sh_s_df_prev, sh_s_df_next, sh_s_df_new, sh_s_df_del
               dw sh_s_df_close
sh_df_bflag:   dw 0, 0, 0, 0, OS88UI_DEF    ; Close carries the ring (81.111)
    SH_BTRECF df, SH_DF_NBT, sh_df_btns, sh_df_bflag
    SH_BTDOORS df, SHM_DFBTN
sh_s_df_prev:  db 'Prev', 0
sh_s_df_next:  db 'Next', 0
sh_s_df_new:   db 'New', 0
sh_s_df_del:   db 'Delete', 0
sh_s_df_close: db 'Close', 0
sh_s_df_nodb:  db 'Set Database first.', 0
sh_s_df_noroom: db 'The row below the database is not empty.', 0
sh_s_df_delq:  db 'Delete the displayed record?', 0
sh_s_df_noovl: db 'CHART.OVL is not beside SHEET.O88.', 0

; -----------------------------------------------------------------------------
; The four resident entry points. sh_docmd_form_r is the menu's, and it is
; also what FORCES THE MODULE IN: if ch_ovcall cannot read CHART.OVL it says
; so and no window is ever created, so the three callbacks below can never be
; the call that has to touch a disk - which, holding the gfx lock inside a
; paint, is the one thing this arrangement must not do. Once read, ch_ovneed
; returns on its first compare and every later callback is a plain far call.
; -----------------------------------------------------------------------------
sh_docmd_form_r:
    push bp
    mov bp, SHM_FORM
    call ch_ovcall
    pop bp
    jnc .out
    mov word [sh_msg], sh_s_df_noovl
    push si
    mov si, [sh_ownwin]
    call sh_repaint
    pop si
.out:
    ret

sh_df_paint_r:                         ; SI = the window, the gfx lock held
    push bp
    mov bp, SHM_FPAINT
    call ch_ovcall
    pop bp
    ret

sh_df_onkey_r:                         ; AL = ascii, AH = scan
    push bp
    mov bp, SHM_FKEY
    call ch_ovcall
    pop bp
    ret

sh_df_onclick_r:                       ; CX,DX = the click
    push bp
    mov bp, SHM_FCLICK
    call ch_ovcall
    pop bp
    ret
sh_df_close_r:                         ; ...and the recovery's
    push bp
    mov bp, SHM_FCLOSE
    call ch_ovcall
    pop bp
    ret
sh_df_ondel_r:                         ; Delete's alert completion: os88ui_adone
    push bp                            ; near-calls it in THIS segment, so a
    mov bp, SHM_DFDEL                  ; module label would land mid-resident
    call ch_ovcall
    pop bp
    ret

; -----------------------------------------------------------------------------
; sh_docmd_form - Data ▸ Form.... Pins the database rectangle the way
; Extract pins its own selection, and for the same reason (81.6).
; -----------------------------------------------------------------------------
; --- the engine itself lives in CHART.OVL (81.71.5.1): it is ~2.2KB of
; code that runs only while the form is open, and SHEET had 1,806 bytes
; less resident room than it needed. What stays behind is the DATA the
; kernel reads (the template and its title) and four thunks - the module
; is forced in by sh_docmd_form_r BEFORE the window exists, so no paint
; can ever be the call that has to read the file.
section SH_MODSEC                      ; 81.71.5: Data ▸ Form, CHART.OVL
sh_docmd_form:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    cmp word [sh_df_win], 0
    jne .out
    mov si, sh_s_dbname
    SHOUT sh_name_lookup
    jnc .nodb
    mov [sh_df_c1], ax
    mov [sh_df_r1], bx
    mov [sh_df_c2], cx
    mov [sh_df_r2], dx
    call sh_df_norm
    mov ax, [sh_df_c2]                 ; how many fields the record has
    sub ax, [sh_df_c1]
    inc ax
    mov [sh_df_nf], ax
    mov ax, [sh_df_r1]                 ; ...and which record is shown. A
    inc ax                             ; database that is only its header row
    mov [sh_df_rec], ax                ; opens on `0 of 0` with nothing to
    mov word [sh_df_fld], 0            ; edit, which is what New is for
    mov word [sh_df_top], 0
    mov si, sh_df_line
    mov word [si + LN_BUF], sh_df_buf
    mov word [si + LN_MAX], SH_EDITMAX
    mov byte [si + LN_FOCUS], 1
    call sh_df_loadfld
    call OSAPI_VIDEO
    sub ax, SH_DF_W
    sar ax, 1
    mov [sh_df_tpl + WT_X], ax
    sub bx, SH_DF_H
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .placed
    mov bx, MBAR_H + 8
.placed:
    mov [sh_df_tpl + WT_Y], bx
    mov si, sh_df_tpl
    call OSAPI_WM_CREATE
    jc .out
    mov [sh_df_win], bx
    call OSAPI_WM_SHOW
    SHOUT sh_btfix                     ; the gesture (81.111), from here
    jmp .out
.nodb:
    mov word [sh_msg], sh_s_df_nodb
    mov si, [sh_ownwin]
    SHOUT sh_repaint
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_df_norm - the pinned rectangle the right way round, sh_dbcmd_norm's own
; reason: a name keeps the corners the selection gave it
sh_df_norm:
    push ax
    mov ax, [sh_df_c1]
    cmp ax, [sh_df_c2]
    jle .r
    xchg ax, [sh_df_c2]
    mov [sh_df_c1], ax
.r:
    mov ax, [sh_df_r1]
    cmp ax, [sh_df_r2]
    jle .out
    xchg ax, [sh_df_r2]
    mov [sh_df_r1], ax
.out:
    pop ax
    ret

; sh_df_nrec - out: AX = how many records the database holds (its rows past
; the header). Zero is legal and means a header row on its own
sh_df_nrec:
    mov ax, [sh_df_r2]
    sub ax, [sh_df_r1]
    jns .out
    xor ax, ax
.out:
    ret

; sh_df_fcol - in: AX = a field index. out: AX = the sheet column it names
sh_df_fcol:
    add ax, [sh_df_c1]
    ret

; -----------------------------------------------------------------------------
; sh_df_editable - in: AX = a field index. out: CF=1 the field may be typed
; into. The Reference Guide: "Fields that are computed or protected cannot be
; edited, and so do not appear in a text box. A protected field is a field in
; a cell that is locked while the worksheet is protected."
; -----------------------------------------------------------------------------
sh_df_editable:
    push ax
    push bx
    push di
    push es
    call sh_df_nrec
    or ax, ax
    pop es
    pop di
    pop bx
    pop ax
    jz .no                             ; no records: nothing to type into
    push ax
    push bx
    push di
    push es
    call sh_df_fcol
    mov bx, [sh_df_rec]
    SHOUT sh_findcell
    jnc .free                          ; an empty cell takes anything
    mov es, [sh_cellseg]
    test byte [es:di+SH_C_FLAGS], 1    ; HASFORMULA: a computed field
    jnz .locked
.free:
    cmp byte [sh_protected], 0
    je .yes
    call sh_df_fcol
    mov bx, [sh_df_rec]
    SHOUT sh_bt_get                     ; 0 when the cell has no record, which
    test al, SH_PROT_UNLOCK            ; IS the default - locked
    jnz .yes
.locked:
    pop es
    pop di
    pop bx
    pop ax
.no:
    clc
    ret
.yes:
    pop es
    pop di
    pop bx
    pop ax
    stc
    ret

; -----------------------------------------------------------------------------
; sh_df_loadfld - the focused field's own text into the editor, and the
; visible window of fields moved to show it
; -----------------------------------------------------------------------------
sh_df_loadfld:
    push ax
    push bx
    push cx
    push si
    push di
    mov ax, [sh_df_fld]                ; keep the focus on screen
    cmp ax, [sh_df_top]
    jae .notabove
    mov [sh_df_top], ax
.notabove:
    mov ax, [sh_df_top]
    add ax, SH_DF_MAXF
    cmp [sh_df_fld], ax
    jb .onscreen
    mov ax, [sh_df_fld]
    sub ax, SH_DF_MAXF - 1
    mov [sh_df_top], ax
.onscreen:
    mov byte [sh_df_buf], 0
    mov byte [sh_df_dirty], 0          ; the cell's own text: nothing typed
    call sh_df_nrec
    or ax, ax
    jz .set
    mov ax, [sh_df_fld]
    call sh_df_fcol
    mov bx, [sh_df_rec]
    SHOUT sh_cell_totext                ; -> sh_clipbuf
    mov si, sh_clipbuf
    mov di, sh_df_buf
    mov cx, SH_EDITMAX
.copy:
    jcxz .term
    mov al, [si]
    mov [di], al
    or al, al
    jz .set
    inc si
    inc di
    dec cx
    jmp .copy
.term:
    mov byte [di], 0
.set:
    mov si, sh_df_line
    mov di, sh_df_buf
    SHOUT os88line_set
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_df_savefld - write the editor back to the focused field's cell, if that
; field is one that may be typed into at all.
;
; sh_commit is driven the way sh_sort_permcol drives it - the SELECTION is its
; argument - so the real selection is banked across the call and put back.
; Without that, closing the form would leave the user's cursor on whichever
; field was last edited.
; -----------------------------------------------------------------------------
sh_df_savefld:
    push ax
    push bx
    push cx
    push si
    push di
    mov ax, [sh_df_fld]
    call sh_df_editable
    jnc .out
    cmp byte [sh_df_dirty], 0          ; nothing typed: the text is the cell's
    je .out                            ; own, and re-typing it would re-parse
    mov byte [sh_df_dirty], 0          ; a label '02134' into a number
    mov ax, [sh_selcol]                ; bank the real selection
    mov [sh_df_svc1], ax
    mov ax, [sh_selrow]
    mov [sh_df_svr1], ax
    mov ax, [sh_selcol2]
    mov [sh_df_svc2], ax
    mov ax, [sh_selrow2]
    mov [sh_df_svr2], ax
    mov si, sh_df_buf                  ; the editor's text is what gets typed
    mov di, sh_editbuf
    xor cx, cx
.copy:
    mov al, [si]
    mov [di], al
    or al, al
    jz .copied
    inc si
    inc di
    inc cx
    jmp .copy
.copied:
    mov [sh_editlen], cl
    mov ax, [sh_df_fld]
    call sh_df_fcol
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov ax, [sh_df_rec]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
    mov byte [sh_editing], 1
    SHOUT sh_commit
    mov ax, [sh_df_svc1]               ; ...and put it back
    mov [sh_selcol], ax
    mov ax, [sh_df_svr1]
    mov [sh_selrow], ax
    mov ax, [sh_df_svc2]
    mov [sh_selcol2], ax
    mov ax, [sh_df_svr2]
    mov [sh_selrow2], ax
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_df_movefld - in: AX = the field to move the focus to. Saves the one being
; left, clamps, loads the new one
sh_df_movefld:
    push ax
    push cx
    mov cx, ax
    or cx, cx
    jl .out
    cmp cx, [sh_df_nf]
    jae .out
    call sh_df_savefld
    mov [sh_df_fld], cx
    call sh_df_loadfld
.out:
    pop cx
    pop ax
    ret

; sh_df_moverec - in: AX = the record row to show. Saves the field being left
sh_df_moverec:
    push ax
    push bx
    push cx
    mov cx, ax
    mov ax, [sh_df_r1]
    inc ax
    cmp cx, ax
    jl .out
    cmp cx, [sh_df_r2]
    jg .out
    call sh_df_savefld
    mov [sh_df_rec], cx
    call sh_df_loadfld
.out:
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_df_paint - SI = the dialog window
; -----------------------------------------------------------------------------
sh_df_paint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, si
    call OSAPI_WM_CONTENT
    mov [sh_df_ox], ax
    mov [sh_df_oy], dx
    mov al, CBLACK
    call OSAPI_SET_COLOR

    ; --- `n of m`, the position counter Excel's own form carries -----------
    mov di, sh_tbuf
    call sh_df_nrec
    push ax
    or ax, ax
    jz .zero
    mov ax, [sh_df_rec]
    sub ax, [sh_df_r1]
.zero:
    SHOUT sh_itoa
    mov si, sh_numbuf
    SHOUT sh_strcpy_to_di
    mov si, sh_s_df_of
    SHOUT sh_strcpy_to_di
    pop ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    SHOUT sh_strcpy_to_di
    mov di, sh_tbuf
    mov cx, SH_DF_LW
    call sh_df_pad
    mov cx, [sh_df_ox]
    add cx, SH_DF_LBLX
    mov dx, [sh_df_oy]
    add dx, 4
    mov si, sh_tbuf
    mov al, CBLACK                     ; OPAQUE (6.1): the counter changes on
    mov ah, CWHITE                     ; every record, and one pass is what
    call OSAPI_FONT_RUN                ; stops it flashing as it does

    ; --- one row per visible field -----------------------------------------
    mov word [sh_df_i], 0
.row:
    mov ax, [sh_df_i]
    cmp ax, SH_DF_MAXF
    jae .buttons
    add ax, [sh_df_top]
    cmp ax, [sh_df_nf]
    jae .buttons
    call sh_df_rowpaint
    inc word [sh_df_i]
    jmp .row

.buttons:
    mov word [sh_df_i], 0
.btn:
    mov ax, [sh_df_i]
    cmp ax, SH_DF_NBT
    jae .done
    call sh_df_btnpaint
    inc word [sh_df_i]
    jmp .btn
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_df_rowpaint - draw visible row [sh_df_i]: the field's NAME from the
; database's header row, then its value - in a live editor if this is the
; focused field, in a plain frame if it is another editable one, and as bare
; text with no frame at all if it is computed or protected, which is exactly
; how Excel's own form says a field cannot be typed into
sh_df_rowpaint:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov ax, [sh_df_i]
    mov bx, SH_DF_ROWH
    mul bx
    add ax, SH_DF_ROWTOP
    add ax, [sh_df_oy]
    mov [sh_df_rowy], ax
    mov ax, [sh_df_i]
    add ax, [sh_df_top]
    mov [sh_df_f], ax
    call sh_df_fcol                    ; the header cell above this field
    mov bx, [sh_df_r1]
    SHOUT sh_cell_totext
    mov di, sh_clipbuf                 ; a scrolled field window changes the
    mov cx, SH_DF_LW                   ; labels too, so this column pads as
    call sh_df_pad                     ; well as the value one
    mov cx, [sh_df_ox]
    add cx, SH_DF_LBLX
    mov dx, [sh_df_rowy]
    add dx, 4
    mov si, sh_clipbuf
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN

    mov ax, [sh_df_f]                  ; ...and the value beside it
    mov bx, [sh_df_fld]
    cmp ax, bx
    jne .other
    mov si, sh_df_line                 ; THE focused field: the live editor,
    mov ax, [sh_df_ox]                 ; its rect refreshed from the live
    add ax, SH_DF_BOXX1                ; content origin every paint
    mov [si + LN_X1], ax
    mov ax, [sh_df_ox]
    add ax, SH_DF_BOXX2
    mov [si + LN_X2], ax
    mov ax, [sh_df_rowy]
    mov [si + LN_Y1], ax
    add ax, SH_DF_ROWH - 3
    mov [si + LN_Y2], ax
    SHOUT os88line_draw
    jmp .out
.other:
    mov ax, [sh_df_f]
    push ax
    mov ax, [sh_df_fld]                ; sh_df_editable asks about the FOCUSED
    push ax                            ; field, so borrow the focus to ask
    mov ax, [sh_df_f]                  ; about this one
    mov [sh_df_fld], ax
    call sh_df_editable
    pop ax
    mov [sh_df_fld], ax
    pop ax
    pushf
    call sh_df_valtext                 ; -> sh_clipbuf
    mov di, sh_clipbuf
    mov cx, SH_DF_VW
    call sh_df_pad
    popf
    jnc .bare
    mov ax, [sh_df_ox]                 ; an editable field keeps its frame
    add ax, SH_DF_BOXX1
    mov bx, [sh_df_rowy]
    mov cx, [sh_df_ox]
    add cx, SH_DF_BOXX2
    mov dx, [sh_df_rowy]
    add dx, SH_DF_ROWH - 3
    mov al, CBLACK
    call OSAPI_SET_COLOR
    call OSAPI_GFX_FRAME
.bare:
    mov cx, [sh_df_ox]
    add cx, SH_DF_BOXX1 + 4
    mov dx, [sh_df_rowy]
    add dx, 3
    mov si, sh_clipbuf
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_df_pad - in: DI = a NUL string, CX = the width in cells. Pads it with
; spaces to exactly that, or cuts it to it. See SH_DF_VW for why.
sh_df_pad:
    push ax
    push cx
    push di
.find:
    cmp byte [di], 0
    je .fill
    inc di
    dec cx
    jns .find
    jmp .cut
.fill:
    or cx, cx
    jle .term
    mov byte [di], ' '
    inc di
    dec cx
    jmp .fill
.cut:
.term:
    mov byte [di], 0
    pop di
    pop cx
    pop ax
    ret

; sh_df_valtext - field [sh_df_f]'s own text into sh_clipbuf, empty when the
; database holds no records at all
sh_df_valtext:
    push ax
    push bx
    mov byte [sh_clipbuf], 0
    call sh_df_nrec
    or ax, ax
    jz .out
    mov ax, [sh_df_f]
    call sh_df_fcol
    mov bx, [sh_df_rec]
    SHOUT sh_cell_totext
.out:
    pop bx
    pop ax
    ret

; sh_df_btnpaint - button [sh_df_i]: its rect into the record's array from
; the live content origin, then drawn by index (81.111). Close carries the
; ring (sh_df_bflag): it is the one button Enter should never fire by
; accident, and the one a user always wants within reach
sh_df_btnpaint:
    push ax
    push bx
    push cx
    push dx
    push di
    mov di, [sh_df_i]
    mov cl, 3
    shl di, cl
    add di, sh_df_btrects
    mov ax, [sh_df_i]
    mov bx, SH_DF_BTW + SH_DF_BTGAP
    mul bx
    add ax, 4
    add ax, [sh_df_ox]
    mov [di], ax
    add ax, SH_DF_BTW
    mov [di+4], ax
    mov ax, [sh_df_oy]
    add ax, SH_DF_BTY1
    mov [di+2], ax
    mov ax, [sh_df_oy]
    add ax, SH_DF_BTY2
    mov [di+6], ax
    mov al, [sh_df_i]
    inc al
    mov bx, sh_df_btrec
    SHOUT os88ui_btn
    pop di
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_df_onkey - AL = ascii, AH = scan code. The Reference Guide's own table:
; TAB the next field, SHIFT+TAB the previous, ENTER the next record. Escape
; closes, which is this OS's rule for every dialog.
; -----------------------------------------------------------------------------
sh_df_onkey:
    push ax
    push si
    cmp al, 27
    je .close
    cmp al, 9
    je .tab
    cmp al, 13
    je .nextrec
    mov si, sh_df_line
    SHOUT os88line_key
    jc .out                            ; the field did not want it
    or al, al                          ; a character or a backspace edits;
    jnz .edited                        ; of the extended keys, only Delete
    cmp ah, 0x53
    jne .moved
.edited:
    mov byte [sh_df_dirty], 1
.moved:
    call sh_df_repaint
    jmp .out
.tab:
    mov ax, [sh_df_fld]
    inc ax
    cmp ax, [sh_df_nf]
    jb .setfld
    xor ax, ax                         ; past the last field: round to the
.setfld:                               ; first, which is what a form does
    call sh_df_movefld
    call sh_df_repaint
    jmp .out
.nextrec:
    mov ax, [sh_df_rec]
    inc ax
    call sh_df_moverec
    mov ax, 0
    call sh_df_movefld                 ; ENTER = the FIRST field of the next
    call sh_df_repaint                 ; record, the Guide's own wording
    jmp .out
.close:
    call sh_df_savefld
    call sh_df_close
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_df_onclick - CX,DX = the click, screen-absolute
; -----------------------------------------------------------------------------
sh_df_onclick:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov si, sh_df_line                 ; the live field first: its rect is
    SHOUT os88line_click                ; already screen-absolute
    jnc .redraw
    mov bx, [sh_df_win]
    push cx
    push dx
    call OSAPI_WM_CONTENT
    pop dx
    pop cx
    sub cx, ax
    sub dx, [sh_df_oy]
    cmp dx, SH_DF_BTY1                 ; the button row is the library's
    jae .out                           ; gesture (81.111, sh_m_dfbtn)
                                       ; a click on another field focuses it
    sub dx, SH_DF_ROWTOP
    jl .out
    mov ax, dx
    xor dx, dx
    mov bx, SH_DF_ROWH
    div bx
    cmp ax, SH_DF_MAXF
    jae .out
    add ax, [sh_df_top]
    cmp ax, [sh_df_nf]
    jae .out
    call sh_df_movefld
    call sh_df_repaint
    jmp .out
.redraw:
    mov si, sh_df_line
    SHOUT os88line_draw
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_df_dobtn - in: AX = the button index
sh_df_dobtn:
    push ax
    push bx
    or ax, ax
    jnz .b1
    mov ax, [sh_df_rec]                ; Prev
    dec ax
    call sh_df_moverec
    jmp .repaint
.b1:
    cmp ax, 1
    jne .b2
    mov ax, [sh_df_rec]                ; Next
    inc ax
    call sh_df_moverec
    jmp .repaint
.b2:
    cmp ax, 2
    jne .b3
    call sh_df_new                     ; New
    jmp .repaint
.b3:
    cmp ax, 3
    jne .b4
    call sh_df_askdel                  ; Delete, behind its own alert
    jmp .out
.b4:
    call sh_df_savefld                 ; Close
    call sh_df_close
    jmp .out
.repaint:
    call sh_df_repaint
.out:
    pop bx
    pop ax
    ret

; sh_df_repaint - the dialog only, by calling its own painter with SI = the
; window, which is what sh_fdlg_onclick does after a radio moves. The grid
; behind it repaints when the form CLOSES, not on every keystroke
sh_df_repaint:
    push si
    mov si, [sh_df_win]
    or si, si
    jz .out
    call sh_df_paint
.out:
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_df_new - a blank record at the end of the database, which the DATABASE
; name then covers. REFUSED when the row below the database already holds
; something in any of its columns: extending over a user's own data is not a
; thing to do quietly, and Excel's own form refuses the same case.
; -----------------------------------------------------------------------------
sh_df_new:
    push ax
    push bx
    push cx
    call sh_df_savefld
    mov cx, [sh_df_c1]
.scan:
    cmp cx, [sh_df_c2]
    jg .room
    mov ax, cx
    mov bx, [sh_df_r2]
    inc bx
    SHOUT sh_findcell
    jc .noroom
    inc cx
    jmp .scan
.room:
    inc word [sh_df_r2]
    call sh_df_bind
    mov ax, [sh_df_r2]
    mov [sh_df_rec], ax
    mov word [sh_df_fld], 0
    mov word [sh_df_top], 0
    call sh_df_loadfld
    jmp .out
.noroom:
    mov word [sh_msg], sh_s_df_noroom
    mov bx, [sh_ownwin]
    push si
    mov si, bx
    SHOUT sh_repaint
    pop si
.out:
    pop cx
    pop bx
    pop ax
    ret

; sh_df_bind - DATABASE covers what sh_df_r1/r2 now say it does
sh_df_bind:
    push ax
    push bx
    push cx
    push dx
    push si
    mov si, sh_s_dbname
    mov ax, [sh_df_c1]
    mov bx, [sh_df_r1]
    mov cx, [sh_df_c2]
    mov dx, [sh_df_r2]
    SHOUT sh_name_def
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_df_askdel - Delete warns first, Data ▸ Delete's own reason: Edit ▸ Undo
; cannot reverse it
sh_df_askdel:
    push ax
    push bx
    push si
    push di
    call sh_df_nrec
    or ax, ax
    jz .out
    mov al, OS88UI_AYESNO
    mov bx, [sh_ownwin]
    mov si, sh_s_df_delq
    mov di, sh_df_ondel_r              ; resident: adone's `call di` is near
    SHOUT os88ui_ask
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret

; sh_df_ondel - the alert's completion. AL = the button, or OS88UI_ACANCEL
sh_df_ondel:
    push ax
    cmp al, 0
    jne .out
    call sh_df_delrec
    call sh_df_repaint
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_df_delrec - drop the displayed record and close the gap, across the
; database's own columns only. Data ▸ Delete's rule (81.71.3) for one record,
; through the same sh_cell_totext/sh_commit pair
; -----------------------------------------------------------------------------
sh_df_delrec:
    push ax
    push bx
    push cx
    mov ax, [sh_df_rec]
    mov [sh_df_dst], ax
.row:
    mov ax, [sh_df_dst]
    inc ax
    cmp ax, [sh_df_r2]
    ja .tail
    mov [sh_df_src], ax
    call sh_df_carry
    inc word [sh_df_dst]
    jmp .row
.tail:
    mov cx, [sh_df_c1]                 ; the last row is a duplicate now
.clr:
    cmp cx, [sh_df_c2]
    jg .shrink
    mov ax, cx
    mov bx, [sh_df_r2]
    SHOUT sh_clearcell
    inc cx
    jmp .clr
.shrink:
    dec word [sh_df_r2]
    call sh_df_bind
    mov ax, [sh_df_rec]                ; ...and the form lands on whatever is
    cmp ax, [sh_df_r2]                 ; in the deleted record's place, or on
    jbe .loaded                        ; the new last record
    mov ax, [sh_df_r2]
    mov [sh_df_rec], ax
.loaded:
    call sh_df_loadfld
    push si
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_df_carry - move the record at [sh_df_src] to [sh_df_dst], field by field
sh_df_carry:
    push ax
    push bx
    push cx
    push si
    push di
    mov cx, [sh_df_c1]
.col:
    cmp cx, [sh_df_c2]
    jg .out
    mov ax, cx
    mov bx, [sh_df_src]
    SHOUT sh_cell_totext                ; -> sh_clipbuf
    mov si, sh_clipbuf
    mov di, sh_editbuf
    push cx
    xor cx, cx
.copy:
    mov al, [si]
    mov [di], al
    or al, al
    jz .copied
    inc si
    inc di
    inc cx
    jmp .copy
.copied:
    mov [sh_editlen], cl
    pop cx
    mov ax, [sh_selcol]                ; bank the real selection, sh_df_savefld's
    mov [sh_df_svc1], ax               ; own reason
    mov ax, [sh_selrow]
    mov [sh_df_svr1], ax
    mov ax, [sh_selcol2]
    mov [sh_df_svc2], ax
    mov ax, [sh_selrow2]
    mov [sh_df_svr2], ax
    mov [sh_selcol], cx
    mov [sh_selcol2], cx
    mov ax, [sh_df_dst]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
    mov byte [sh_editing], 1
    SHOUT sh_commit
    mov ax, [sh_df_svc1]
    mov [sh_selcol], ax
    mov ax, [sh_df_svr1]
    mov [sh_selrow], ax
    mov ax, [sh_df_svc2]
    mov [sh_selcol2], ax
    mov ax, [sh_df_svr2]
    mov [sh_selrow2], ax
    inc cx
    jmp .col
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_df_close - the gate cleared BEFORE the destroy, every other engine's
; shape, and OSAPI_WM_DESTROY and not CLOSE (81.6: CLOSE leaks the slot)
; -----------------------------------------------------------------------------
sh_df_close:
    push ax
    push bx
    push si
    mov bx, [sh_df_win]
    or bx, bx
    jz .out
    mov word [sh_df_win], 0
    call OSAPI_WM_DESTROY
    SHOUT sh_recalc_all                 ; a form can have rewritten any cell
    mov si, [sh_ownwin]
    SHOUT sh_repaint
.out:
    pop si
    pop bx
    pop ax
    ret

section .text

sh_dlg:
    push bx
    push si
    push di
    mov bx, si
    mov di, sh_ondlg
    mov si, sh_name
    call OSAPI_FILE_DLG
    pop di
    pop si
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_ondlg - the file dialog's completion proc (SPEC.md 38.6)
; in:  AL=mode, SI=our window ptr, DI=chosen name (ES=KERNEL_SEG); UI task,
;      gfx lock HELD, dialog already destroyed - we owe the repaint
; -----------------------------------------------------------------------------
sh_ondlg:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bl, al
    mov cx, si                       ; CX = our window ptr (SI about to move)
    mov si, di
    mov di, sh_name
    cmp byte [sh_dlg_del], 0         ; 81.79: a DELETE picks a file that is
    je .dest                         ; not this document, so its name must
    mov di, sh_delname               ; not land in sh_name - that is the open
.dest:                               ; document's own name, and Save would
                                     ; then have written over the file the
                                     ; user had just chosen to delete
    mov dx, SH_FNAME_MAX               ; the count lives in DX - the loop body
.copy:                               ; writes AL, so AX cannot hold it, and
    mov al, [es:si]                  ; CX holds the window
    mov [di], al
    or al, al
    jz .copied
    inc si
    inc di
    dec dx
    jnz .copy
    mov byte [di], 0
.copied:
    mov si, cx                       ; SI = our window again
    cmp byte [sh_dlg_del], 0
    je .notdel
    mov byte [sh_dlg_del], 0         ; cleared FIRST: every path below leaves
    mov al, OS88UI_AYESNO            ; the flag down, so a dismissed alert or
    mov bx, [sh_ownwin]              ; a refused one cannot leave the NEXT
    mov si, sh_s_delq                ; Open behaving like a Delete
    mov di, sh_ondelete
    call os88ui_ask                  ; the gfx lock is held here, which is
    jmp short .drawn                 ; what os88ui_ask's contract wants
.notdel:
    or bl, bl
    jz .load
    call sh_dowrite
    jmp short .draw
.load:
    call sh_doread
.draw:
    call sh_repaint
.drawn:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ondelete - os88ui_ask's completion for File > Delete (81.79). AL = the
; button index, or OS88UI_ACANCEL when it was dismissed; SI is OUR window and
; the gfx lock is held. sh_docmd_dbdelete's own shape, for its reason: a
; DISMISSED alert must not delete anything.
; -----------------------------------------------------------------------------
sh_ondelete:
    push ax
    push si
    cmp al, 0                          ; Yes, and nothing else
    jne .out
    push si
    mov si, sh_delname
    call OSAPI_FILE_DELETE
    pop si
    mov word [sh_msg], sh_s_deleted
    jnc .out
    mov word [sh_msg], sh_s_delfail    ; FERR_* in AX: the sheet says it could
.out:                                  ; not rather than saying nothing
    call sh_repaint
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_new - File > New: clear the sheet and the name, reselect A1
; -----------------------------------------------------------------------------
sh_new:
    push ax
    push cx
    push dx
    push si
    push di
    mov dx, si                       ; DX = window ptr, stashed
    mov si, sh_defname
    mov di, sh_name
    call sh_strcpy
    mov si, dx                       ; SI = window ptr, restored
    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0
    mov word [sh_nbord], 0           ; the discarded document's borders and
    mov word [sh_ntbl], 0            ; 81.114.7: ...and its TABLES
    mov word [sh_nnote], 0           ; notes go with it - a note record holds
    SHOUT sh_colw_clear                ; ...and every column's width (81.56)
    mov word [sh_nnames], 0          ; ...and its NAMES, which used to survive
                                     ; into the next document and go on
                                     ; pointing at cells no longer there
                                     ; an OFFSET into the arena reset above,
                                     ; and would read new text through it
    cmp byte [sh_dockind], 0           ; 81.97: a macro sheet showed its
    je .wsheet                         ; formulas; a new document is a
    cmp byte [sh_dockind], 2           ; worksheet, which shows values -
    mov byte [sh_dockind], 0           ; unless they were the user's own
    jne .wsheet                        ; (sh_kindreset's rule, inline: this
    mov byte [sh_showformulas], 0      ; is resident and that is CHART.OVL's)
.wsheet:
    mov word [sh_cursheet], 0
    mov cx, SH_SHEETS * 6            ; 6 words per sheet: sel/row/scl/scr,
                                      ; and 81.70's own fcl/frw
    mov di, sh_selsave
    xor ax, ax
.clrsave:
    mov [di], ax
    add di, 2
    loop .clrsave
    mov word [sh_selcol], 0
    mov word [sh_selrow], 0
    mov word [sh_selcol2], 0           ; the EXTENT too, or the new sheet
    mov word [sh_selrow2], 0           ; opens with the old block framed
    mov word [sh_scrollcol], 0
    mov word [sh_scrollrow], 0
    mov word [sh_freezecol], 0         ; 81.70: a new document is unfrozen,
    mov word [sh_freezerow], 0         ; like every other view setting here
    call sh_frzmark                    ; ...and the item says so again
    mov byte [sh_editing], 0
    mov word [sh_msg], 0
    mov byte [sh_modified], 0          ; A NEW DOCUMENT IS CLEAN (81.118), and
                                       ; this is one place the port diverges
                                       ; from main: 81.23's own comment says
                                       ; the flag is "cleared by New" and its
                                       ; sh_new does not clear it, so closing
                                       ; straight after New asks about an
                                       ; empty sheet nobody has touched
    pop di                             ; NO repaint here: the caller repaints
    pop si                             ; once, through [sh_ownwin], and SI is
    pop dx                             ; the New dialog's or a macro's own
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_switchsheet - in: AX = target sheet index (0..SH_SHEETS-1); saves the
; outgoing sheet's selection/scroll into its slot and restores the
; incoming sheet's own (all-zero the first time it's ever visited)
; -----------------------------------------------------------------------------
; =============================================================================
; Unsaved work (SPEC.md 81.118). [sh_modified] is set by every routine that
; changes the document - a cell, a border, a note, a format - and cleared by
; New, by a successful read and by a save that kept EVERYTHING. New, Open and
; closing the window all throw the workbook away, so each asks first when it is
; set, with SPEC.md 75.3's standard Save / Discard / Cancel alert: the same
; question, in the same words, that Note Pad and Word ask.
;
; THIS IS MAIN'S 81.23, ported at the 2026-10-20 merge rather than written
; again - the arrangement, the words and the refusal cases are its, and what
; changed is where the pieces live: sh_fdlg_open is CHART.OVL's here, so
; sh_proceed takes the resident thunk, and the whole family is `.text` because
; a close negotiator must answer with the module unmounted.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_ask_unsaved - in: AL = what to do once the workbook may go: SH_PEND_NEW,
; SH_PEND_OPEN or SH_PEND_CLOSE. Does it at once when nothing would be lost;
; otherwise raises the alert and leaves it to sh_onask.
; out: CF = 0 done (or asked), CF = 1 the alert could not be raised - one is
;      already up and has been brought to the front, or the window table is
;      full - and NOTHING was done. Gfx lock held. Preserves every register.
; -----------------------------------------------------------------------------
sh_ask_unsaved:
    push ax
    push bx
    push si
    push di
    push dx
    cmp byte [sh_modified], 0
    jne .ask
    mov [sh_pend], al
    call sh_proceed
    clc
    jmp short .out
.ask:
    mov dl, al                        ; NOT [sh_pend] yet: an alert already up
                                      ; is still owed ITS action, and a refused
                                      ; ask must not change what that is
    mov si, sh_s_askpre               ; 'Save changes to NAME?' - the name
    mov di, sh_askmsg                 ; is at most SH_FNAME_MAX characters, so
    call sh_strcpy                    ; the line fits OS88UI_AMAX
    dec di
    mov si, sh_name
    call sh_strcpy_to_di
    mov word [di], '?'                ; '?' and the NUL in one store
    mov al, OS88UI_ASAVE
    mov bx, [sh_ownwin]
    mov si, sh_askmsg
    mov di, sh_onask
    call os88ui_ask                   ; CF = 1 refused: nothing happens
    jc .out
    mov [sh_pend], dl
.out:
    pop dx
    pop di
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_onask - the alert's completion (SPEC.md 75.3). AL = 0 Save, 1 Discard,
; 2 Cancel or OS88UI_ACANCEL; SI = our window; gfx lock held, alert gone.
; A Save that did not keep EVERYTHING - a failed write, a truncated file, one
; sheet of several - does NOT go on: the status line says what happened and
; the workbook is still here, so the user can choose Discard knowingly.
; -----------------------------------------------------------------------------
sh_onask:
    or al, al
    jz .save
    cmp al, 1
    je .go
    ret                               ; Cancel, or dismissed: stay as we are
.save:
    call sh_dowrite
    cmp byte [sh_modified], 0         ; sh_dowrite clears it only for a save
    je .go                            ; that kept the whole workbook
    mov si, [sh_ownwin]
    call sh_repaint                   ; ...and the status line says why not
    ret
.go:
    jmp sh_proceed

; -----------------------------------------------------------------------------
; sh_proceed - do [sh_pend]'s action now. Gfx lock held.
; -----------------------------------------------------------------------------
sh_proceed:
    push ax
    push bx
    push si
    mov al, [sh_pend]
    mov si, [sh_ownwin]
    cmp al, SH_PEND_OPEN
    je .open
    cmp al, SH_PEND_CLOSE
    je .close
    mov al, SH_FDK_NEW                ; New asks which KIND first (.donew).
    call sh_fdlg_open_r               ; the dialog engine is CHART.OVL's here
    jmp short .out
.open:
    mov al, FDLG_OPEN
    call sh_dlg
    jmp short .out
.close:
    mov byte [sh_modified], 0         ; this IS the answer: not again
    mov bx, si
    call OSAPI_WM_CLOSE               ; DEFERRED (SPEC.md 75.2) - draw nothing
.out:                                 ; after it
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_onclose - the CLOSE NEGOTIATOR (SPEC.md 75.1). SI = our window, gfx lock
; held. CF = 0 close now (nothing to lose), CF = 1 not yet: the question is up
; and sh_proceed closes once it is answered - or an alert is already up and
; has been raised, and the window waits for it.
; -----------------------------------------------------------------------------
sh_onclose:
    cmp byte [sh_modified], 0
    je .go
    push ax
    mov al, SH_PEND_CLOSE
    call sh_ask_unsaved
    pop ax
    stc
    ret
.go:
    clc
    ret

; -----------------------------------------------------------------------------
; sh_sheetmark - point every Sheets item at its plain string, then the CURRENT
; one at its marked twin. Called at startup and after every switch, so the mark
; is derived from sh_cursheet rather than tracked alongside it.
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_frzmark - point Options' Freeze Panes item at whichever of its two
; labels the CURRENT state wants (81.70), derived rather than tracked - the
; same shape sh_sheetmark below uses for the Sheets menu's own tick, and the
; reason a sheet switch or a new document cannot leave "Unfreeze Panes"
; standing over a sheet that is not frozen.
; -----------------------------------------------------------------------------
sh_frzmark:
    push ax
    mov ax, [sh_freezecol]
    or ax, [sh_freezerow]
    jnz .on
    mov word [sh_i_options + SH_OI_FREEZE * 2], sh_it_frz_off
    pop ax
    ret
.on:
    mov word [sh_i_options + SH_OI_FREEZE * 2], sh_it_frz_on
    pop ax
    ret

sh_sheetmark:
    push ax
    push bx
    push cx
    xor bx, bx
    mov cx, SH_SHEETS
.lp:
    mov ax, [sh_sheet_plain + bx]
    mov [sh_i_sheet + bx], ax
    add bx, 2
    loop .lp
    mov bx, [sh_cursheet]
    shl bx, 1
    mov ax, [sh_sheet_chk + bx]
    mov [sh_i_sheet + bx], ax
    pop cx
    pop bx
    pop ax
    ret

sh_switchsheet:
    push ax
    push bx
    push cx
    mov cx, ax                       ; cx = target sheet, preserved across
                                      ; the save step below
    cmp cx, [sh_cursheet]
    je .out
    mov bx, [sh_cursheet]
    shl bx, 1
    mov ax, [sh_selcol]
    mov [sh_selsave+bx], ax
    mov ax, [sh_selrow]
    mov [sh_rowsave+bx], ax
    mov ax, [sh_scrollcol]
    mov [sh_sclsave+bx], ax
    mov ax, [sh_scrollrow]
    mov [sh_scrsave+bx], ax
    mov ax, [sh_freezecol]             ; 81.70
    mov [sh_fclsave+bx], ax
    mov ax, [sh_freezerow]
    mov [sh_frwsave+bx], ax
    mov [sh_cursheet], cx
    call sh_sheetmark
    mov bx, cx
    shl bx, 1
    mov ax, [sh_selsave+bx]
    mov [sh_selcol], ax
    mov ax, [sh_rowsave+bx]
    mov [sh_selrow], ax
    mov ax, [sh_sclsave+bx]
    mov [sh_scrollcol], ax
    mov ax, [sh_scrsave+bx]
    mov [sh_scrollrow], ax
    mov ax, [sh_fclsave+bx]            ; 81.70
    mov [sh_freezecol], ax
    mov ax, [sh_frwsave+bx]
    mov [sh_freezerow], ax
    call sh_frzmark                    ; the item follows the incoming sheet
    call sh_repaint
.out:
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; File I/O: SYLK write and read, over the sparse array directly
; =============================================================================

; -----------------------------------------------------------------------------
; sh_dowrite - write the sheet to [sh_name], format chosen by its extension
; (SPEC-free scope decision, this project's own: ".DIF" writes DIF,
; everything else writes SYLK, matching stage 1.0's default).
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_sheets_used - out: AX = how many of the SH_SHEETS grids hold at least one
; cell, and BX = a bitmap of which. One walk of the array, not four.
; -----------------------------------------------------------------------------
section SH_MODSEC                      ; 82.16.9
sh_sheets_used:
    push cx
    push dx
    push si
    push es
    xor bx, bx
    xor cx, cx
    mov es, [sh_cellseg]
.each:
    cmp cx, [sh_ncells]
    jae .counted
    mov ax, cx
    push bx
    mov bx, SH_C_SZ
    mul bx
    pop bx
    mov si, ax
    mov ax, [es:si]
    push bx
    SHOUT sh_unpackrow                 ; BX = this record's sheet
    mov dx, bx
    pop bx
    mov ax, 1
    push cx
    mov cx, dx
    jcxz .noshift
.shift:
    shl ax, 1
    loop .shift
.noshift:
    pop cx
    or bx, ax
    inc cx
    jmp .each
.counted:
    mov ax, bx                        ; popcount of the bitmap
    xor dx, dx
    mov cx, SH_SHEETS
.pop1:
    shr ax, 1
    jnc .pop2
    inc dx
.pop2:
    loop .pop1
    mov ax, dx
    pop es
    pop si
    pop dx
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_dowrite - pick the writer from the file name's extension.
;
; AND SAY SO WHEN A SAVE CANNOT CARRY EVERYTHING. SYLK and DIF have no
; multi-sheet concept at all - SYLK has no notion of a sheet and DIF is one
; table - so a workbook with data on more than one of them loses the rest, and
; used to lose it in silence. It says so in the status bar now. BIFF is the one
; format here that CAN carry them, and does (81.10.5).
; -----------------------------------------------------------------------------
shm_dowrite:
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_dif
    SHOUT sh_nameends
    pop di
    pop si
    jc .dif
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_biff
    SHOUT sh_nameends
    pop di
    pop si
    jc .biff
    push si                            ; .XLS is Normal under Excel's own
    push di                            ; name: the reader takes it as BIFF,
    mov si, sh_name                    ; so the writer must write it as BIFF
    mov di, sh_s_ext_xls               ; (81.15.1), not fall through to SYLK
    SHOUT sh_nameends
    pop di
    pop si
    jc .biff
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_csv
    SHOUT sh_nameends
    pop di
    pop si
    jc .csv
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_txt
    SHOUT sh_nameends
    pop di
    pop si
    jc .txt
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_dbf
    SHOUT sh_nameends
    pop di
    pop si
    jc .dbf
    call sh_dowrite_sylk
    jmp .warn
.csv:
    call sh_dowrite_csv
    jmp .warn
.txt:
    call sh_dowrite_txt
    jmp .warn
.dbf:
    call sh_dowrite_dbf
    jmp .warn
.dif:
    call sh_dowrite_dif
    jmp .warn
.biff:
    jmp sh_dowrite_biff
.warn:
    push ax
    push bx
    cmp word [sh_msg], sh_m_saved     ; only upgrade a plain success: a failed
    jne .warned                       ; write's "Err N" (or a truncated save's
                                      ; message) must not be replaced by a
                                      ; string that begins with "Saved"
    mov byte [sh_modified], 0         ; ...and only a plain success makes the
                                      ; document CLEAN: a truncated file, or
                                      ; one that kept one sheet of several,
                                      ; did not save everything (81.118)
    call sh_sheets_used
    cmp ax, 2
    jb .warned
    mov byte [sh_modified], 1
    mov word [sh_msg], sh_s_onesheet
.warned:
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_wr_colw - SYLK's F;W<first> <last> <width> for every column of the
; current sheet that is not the standard width, at ES:DI (81.56)
; -----------------------------------------------------------------------------
sh_wr_colw:
    push ax
    push bx
    push si
    xor bx, bx
.l:
    mov ax, bx
    SHOUT sh_colwidth
    cmp ax, [sh_defch]
    je .n
    push ax
    mov si, sh_s_sylk_fw
    call sh_stgput
    mov ax, bx
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov al, ' '
    call sh_stgputb
    mov si, sh_numbuf
    call sh_stgput
    mov al, ' '
    call sh_stgputb
    pop ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_crlf
    call sh_stgput
.n:
    inc bx
    cmp bx, 256
    jb .l
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_wr_names - one NN record per defined name, straight after the ID line.
;
; NN;N<name>;E<ref> is SYLK's own defined-name record, and the reference goes
; out in R1C1 because that is the notation every ;E field in this file already
; uses - one convention, not two. Absolute R1C1 (no brackets): a name is a
; fixed place, not an offset from wherever it is read.
;
; THIS IS WHAT LETS ANOTHER PROGRAM FIND THE RANGE. Chart charts a named range
; by reading these (82.15); without them a name is a fact only this app knows,
; and a saved sheet would carry the data but not what any of it was called.
; -----------------------------------------------------------------------------
sh_wr_names:
    push ax
    push bx
    push cx
    push si
    mov cx, [sh_nnames]
    jcxz .out
    xor bx, bx
.each:
    mov ax, di
    add ax, 64                        ; the longest NN line: name, two R1C1
    cmp ax, SH_STAGE_MAX              ; refs and the punctuation
    ja .out
    push cx
    push bx
    mov si, sh_names
    add si, bx
    add si, SH_NAME_MAX + 1
    mov ax, [si]
    mov [sh_nm_col], ax
    mov ax, [si+2]
    mov [sh_nm_row], ax
    mov ax, [si+4]
    mov [sh_nm_col2], ax
    mov ax, [si+6]
    mov [sh_nm_row2], ax
    mov si, sh_s_nn
    call sh_stgput
    mov si, sh_names
    add si, bx
    call sh_stgput                    ; the name itself
    mov si, sh_s_nne
    call sh_stgput
    mov ax, [sh_nm_row]
    mov bx, [sh_nm_col]
    call sh_wr_r1c1
    mov si, sh_s_colon
    call sh_stgput
    mov ax, [sh_nm_row2]
    mov bx, [sh_nm_col2]
    call sh_wr_r1c1
    mov si, sh_s_crlf
    call sh_stgput
    pop bx
    pop cx
    add bx, SH_NAME_REC
    loop .each
.out:
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_wr_r1c1 - in: AX = 0-based row, BX = 0-based col; emits "R<n>C<n>" at DI,
; 1-based as the notation is. sh_itoa lands in sh_numbuf, so each half is
; converted immediately before it is put and never both at once.
sh_wr_r1c1:
    push ax
    push bx
    push si
    mov [sh_nm_tmp], bx
    mov si, sh_s_r
    call sh_stgput
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_cu
    call sh_stgput
    mov ax, [sh_nm_tmp]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dowrite_sylk - write the sheet to [sh_name] as SYLK. Walks the sorted
; cell array directly (already row-major), so no grid loop is needed at
; all. A formatted cell's C (value) record is followed by a real SYLK F
; (formatting) record - "F;X<col>;Y<row>;F<c1><n><c2>[;K]" - using
; MultiPlan-era SYLK's actual format codes (stage 1.6): c1 is '$' for
; Currency, '%' for Percent - SYLK's own percent code (81.119.2) - or 'G'
; for everything else (General and Comma share 'G': real SYLK has no comma
; code of its own, so Comma instead sets the separate ;K "commas are set"
; flag), c2 is the real alignment code (G/L/C/R) matching this app's own
; alignment 1:1. Borders and notes follow the sheet's cells, from
; sh_sylk_extras (81.119.2). Real
; SYLK, per the era's own documentation, has no bold/underline concept
; whatsoever - MultiPlan predates that - so neither persists here; this is
; the same "only persist what the real format actually has" rule DIF
; follows below, not an oversight.
; -----------------------------------------------------------------------------
sh_dowrite_sylk:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    mov es, [sh_stgseg]
    xor di, di
    mov si, sh_s_id
    call sh_stgput
    call sh_wr_colw                   ; 81.56: F;W for each column's width
    call sh_wr_names                  ; stage 4.6: the defined names, so a
                                       ; reader that is not this app can find
                                       ; the ranges too (81.29.1)

    mov byte [sh_trunc], 0
    mov word [sh_wrow], 0            ; reused here as the record index
.rec:
    mov bx, [sh_wrow]
    cmp bx, [sh_ncells]
    jae .footer
    cmp byte [sh_trunc], 0
    jne .footer
    mov ax, di
    add ax, 200                      ; worst case a LABEL's C line: the head
                                      ; ("C;X256;Y16384;K"), the quoted text
                                      ; with every embedded quote DOUBLED
                                      ; (2 + 2*SH_EDITMAX), CRLF, plus its
                                      ; F line ("F;X256;Y16384;F$0R;K\r\n");
                                      ; the ;E formula case is smaller
    cmp ax, SH_STAGE_MAX
    jbe .room
    mov byte [sh_trunc], 1
    jmp .footer
.room:
    mov ax, bx
    mov cx, SH_C_SZ
    mul cx
    mov si, ax                        ; SI = this record's offset in cellseg
    push es
    mov es, [sh_cellseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow                 ; -> ax=real row, bx=this record's
                                       ; sheet (see the stage 2.0 comment
                                       ; above the cell record layout)
    cmp bx, [sh_cursheet]
    jne .recskip                      ; a save only ever writes the CURRENT
                                       ; sheet - the array may hold other
                                       ; sheets' records too, interleaved
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]
    mov [sh_wrec_col], ax
    mov word [sh_wrec_foff], 0xFFFF   ; ...and this cell's formula, if it has
    test byte [es:si+4], 1            ; one: SYLK carries the EXPRESSION in a
    jz .noformula_w                   ; ;E field beside the cached ;K value,
    mov ax, [es:si+SH_C_FOFF]         ; which is what makes a saved sheet a
    mov [sh_wrec_foff], ax            ; spreadsheet rather than a table of
.noformula_w:                         ; numbers
    SHOUT sh_cellval_to_acc_si         ; bank the whole value: the row and
    push si                           ; column are formatted through sh_numbuf
    push di                           ; before it is wanted, so it cannot be
    mov si, sh_acc                    ; turned into text here
    mov di, sh_wrec_dval
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    pop si
    mov ax, [es:si+SH_C_VAL]
    mov [sh_wrec_val], ax
    mov al, [es:si+5]
    mov [sh_wrec_fmt], al
    mov al, [es:si+SH_C_AUX]
    mov [sh_wrec_aux], al
    mov al, [es:si+SH_C_TYPE]         ; stage 4.5: and the tag, because a LABEL
    mov [sh_wrec_type], al            ; goes out as a QUOTED K field rather
    mov ax, [es:si+SH_C_FOFF]         ; than as a number, and its characters
    mov [sh_wrec_toff], ax            ; come from the same arena a formula's do
    test byte [es:si+4], 1            ; A FORMULA THAT RETURNED TEXT keeps its
    jz .toffok1                          ; result in SH_C_VAL, because FOFF is
    cmp byte [es:si+SH_C_TYPE], SH_T_TEXT  ; already holding the formula's own
    jne .toffok1                         ; text (81.22.1) - so the label this
    mov ax, [es:si+SH_C_VAL]          ; writer emits is the RESULT, not the
    mov [sh_wrec_toff], ax            ; expression that produced it
.toffok1:
    pop es                            ; ES = stgseg again

    mov si, sh_s_c
    call sh_stgput
    mov ax, [sh_wrec_col]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_y
    call sh_stgput
    mov ax, [sh_wrec_row]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    cmp word [sh_wrec_foff], 0xFFFF   ; ";E<expr>" comes BEFORE ";K", the
    je .noexpr                        ; order a real file from the period uses
    push si
    push di
    mov ax, [sh_wrec_col]             ; every relative offset is measured from
    mov [sh_rc_ccol], ax              ; the cell being written
    mov ax, [sh_wrec_row]
    mov [sh_rc_crow], ax
    push es
    mov es, [sh_txtseg]               ; copy the formula text out of the arena
    mov si, [sh_wrec_foff]            ; into DS, where the converter reads
    mov di, sh_rwsrc
    mov cx, SH_EDITMAX
.ecopy:
    mov al, [es:si]
    mov [di], al
    or al, al
    jz .ecopied
    inc si
    inc di
    dec cx
    jnz .ecopy
    mov byte [di], 0
.ecopied:
    pop es
    mov si, sh_rwsrc
    call sh_formula_to_r1c1
    pop di
    pop si
    mov si, sh_s_e
    call sh_stgput
    mov si, sh_rwdst                  ; ...with every ';' DOUBLED, as the K
.edbl:                                ; field's are: a string constant can
    mov al, [si]                      ; hold one, and a single one ends the
    or al, al                         ; field there, in a file that parses
    jz .noexpr
    inc si
    cmp al, ';'
    jne .edbl1
    call sh_stgputb
.edbl1:
    call sh_stgputb
    jmp short .edbl
.noexpr:
    mov si, sh_s_k
    call sh_stgput
    cmp byte [sh_wrec_type], SH_T_TEXT
    je .ktext
    cmp byte [sh_wrec_type], SH_T_BOOL ; a LOGICAL is QUOTED, Walden's rule:
    je .kbool                          ; "Logical values TRUE and FALSE must
                                       ; also be quoted" (81.51)
    cmp byte [sh_wrec_type], SH_T_ERR ; ...and an ERROR is its NAME, bare. The
    je .kerr                          ; leading '#' is what tells it from a
    push si                           ; SYLK's K field IS a decimal literal,
    push di                           ; so the full value goes out, not a
    mov si, sh_wrec_dval              ; truncation of it
    SHOUT fp_unpack_a
    mov di, sh_numbuf
    mov ax, 10
    SHOUT fp_ftoa
    pop di
    pop si
    mov si, sh_numbuf
    call sh_stgput
    jmp .kdone
.kerr:
    ; number, on both sides - no number starts with one, and SYLK has no type
    ; field to consult. Writing the value UNDERNEATH an error instead (a zero)
    ; is what this did, and it turned #DIV/0! into a perfectly ordinary 0 on
    ; the next load.
    push ax
    mov al, [sh_curaux]               ; sh_errname names the CURRENT cell, and
    push ax                           ; a save is not a paint - bank what the
    mov al, [sh_wrec_aux]             ; painter left there
    mov [sh_curaux], al
    SHOUT sh_errname                   ; -> sh_numbuf
    pop ax
    mov [sh_curaux], al
    pop ax
    mov si, sh_numbuf
    call sh_stgput
    jmp .kdone
.kbool:
    mov al, 34
    call sh_stgputb
    mov ax, [sh_wrec_dval+6]
    SHOUT sh_boolname
    mov si, sh_numbuf
    call sh_stgput
    mov al, 34
    call sh_stgputb
    jmp .kdone
.ktext:
    ; A LABEL'S K FIELD IS QUOTED, and that is the whole of how SYLK tells text
    ; from a number - there is no type field to consult, on either side.
    ; SYLK HAS TWO RESERVED CHARACTERS AND BOTH ARE ESCAPED BY DOUBLING.
    ; The quote was always doubled here, because the charset gate admits one
    ; and a bare one would end the field early. The SEMICOLON was not, and it
    ; is the worse of the two: it is the FIELD SEPARATOR, so a label
    ; containing one was written as `K"a;b"` and any conforming reader splits
    ; that into a `K"a` field and a stray `b"` - the text silently truncated
    ; at the semicolon, in a file that still parses. Walden: "Any field
    ; containing the reserved semicolon character must have two of them."
    ;
    ; This was invisible for as long as SHEET was the only thing that ever
    ; read the file, because 81.38's reader did not double it either and the
    ; two errors cancelled exactly.
    mov al, 34
    call sh_stgputb
    mov si, [sh_wrec_toff]
.kt:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    or al, al
    jz .ktend
    inc si
    cmp al, 34
    je .kdup
    cmp al, ';'
    jne .kt1
.kdup:
    call sh_stgputb                   ; doubled: a quote or a semicolon
.kt1:
    call sh_stgputb
    jmp .kt
.ktend:
    mov al, 34
    call sh_stgputb
.kdone:
    mov si, sh_s_crlf
    call sh_stgput

    mov al, [sh_wrec_fmt]
    and al, (SH_FMT_ALIGN_MASK | SH_FMT_NUM_MASK)
    jz .noformat                      ; bold/underline alone don't get an F
                                       ; record - real SYLK has no code for
                                       ; either, see sh_parsefrec's comment
    mov si, sh_s_sylk_fx               ; "F;X"
    call sh_stgput
    mov ax, [sh_wrec_col]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_y
    call sh_stgput
    mov ax, [sh_wrec_row]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_sylk_ff                ; ";F"
    call sh_stgput
    mov bl, [sh_wrec_fmt]
    and bl, SH_FMT_NUM_MASK
    mov cl, SH_FMT_NUM_SHIFT
    shr bl, cl
    mov al, '$'
    cmp bl, SH_FMT_NUM_CURRENCY
    je .c1ok
    mov al, '%'                          ; SYLK's own percent code (81.119.2)
    cmp bl, SH_FMT_NUM_PERCENT
    je .c1ok
    mov al, 'G'
.c1ok:
    call sh_stgputb                      ; c1
    mov al, '0'
    call sh_stgputb                      ; n (digit count - always 0, this
                                         ; app's values are whole numbers)
    mov al, [sh_wrec_fmt]
    and al, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr al, cl
    cmp al, SH_FMT_ALIGN_LEFT
    je .c2l
    cmp al, SH_FMT_ALIGN_CENTER
    je .c2c
    cmp al, SH_FMT_ALIGN_RIGHT
    je .c2r
    mov al, 'G'
    jmp .c2ok
.c2l:
    mov al, 'L'
    jmp .c2ok
.c2c:
    mov al, 'C'
    jmp .c2ok
.c2r:
    mov al, 'R'
.c2ok:
    call sh_stgputb                      ; c2
    cmp bl, SH_FMT_NUM_COMMA
    jne .nok
    mov si, sh_s_k
    call sh_stgput                      ; ";K"
.nok:
    mov si, sh_s_crlf
    call sh_stgput
.noformat:
    jmp .recnext
.recskip:
    pop es
.recnext:
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    jmp .rec
.footer:
    cmp byte [sh_trunc], 0
    jne .nomore
    call sh_sylk_extras               ; borders and notes (81.119.2)
.nomore:
    mov si, sh_s_end
    call sh_stgput
    mov [sh_stagelen], di

    mov ax, [sh_stgseg]
    mov es, ax
    xor bx, bx
    mov cx, [sh_stagelen]
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_WRITE
    jc .werr
    mov word [sh_msg], sh_m_saved
    cmp byte [sh_trunc], 0            ; cells dropped for room must not be
    je .wdone                         ; reported as a plain success
    mov word [sh_msg], sh_m_trunc
    jmp .wdone
.werr:
    call sh_setferr
.wdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sylk_xy - "X<col+1>;Y<row+1>" for [sh_wrec_col]/[sh_wrec_row] at ES:DI.
; -----------------------------------------------------------------------------
sh_sylk_xy:
    push ax
    push si
    mov ax, [sh_wrec_col]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_y
    call sh_stgput
    mov ax, [sh_wrec_row]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sylk_extras - the current sheet's borders and notes, after its cells, at
; ES:DI (81.119.2), main's writer in this file's tables. A border is an F
; record of its own with SYLK's style field, ";S" and a letter an edge -
; L R T B - and S for shaded:
;     F;X3;Y4;SLT
; A border-table record holding only protection or a number format (81.46,
; 81.55) has no style to write and is passed over. A note is a C record
; carrying only SYLK's comment field, ";A", so it neither needs a value nor
; disturbs one: a ';' in the text is doubled, as every SYLK field's is, and a
; line break is ESC " :", which is what Excel writes.
; Sets [sh_trunc] if the buffer fills. Preserves everything but DI.
; -----------------------------------------------------------------------------
sh_sylk_extras:
    push ax
    push bx
    push cx
    push dx
    push si
    xor si, si
    mov cx, [sh_nbord]
    jcxz .notes
.b:
    push cx
    push es
    mov es, [sh_bordseg]
    mov ax, [es:si]
    mov cx, [es:si+2]
    mov dl, [es:si+4]
    pop es
    and dl, 0x1F                       ; the edges and Shade alone
    jz .bnext
    SHOUT sh_unpackrow                 ; -> AX = row, BX = its sheet
    cmp bx, [sh_cursheet]
    jne .bnext
    mov [sh_wrec_row], ax
    mov [sh_wrec_col], cx
    mov ax, di
    add ax, 40
    cmp ax, SH_STAGE_MAX
    ja .full
    push si
    mov si, sh_s_sylk_fx               ; "F;X"
    call sh_stgput
    call sh_sylk_xy
    mov si, sh_s_sylk_fs               ; ";S"
    call sh_stgput
    mov si, sh_sylk_bordch             ; one letter per bit, in bit order
    mov ah, dl
.bl:
    mov al, [si]
    inc si
    or al, al
    jz .bldone
    shr ah, 1
    jnc .bl
    call sh_stgputb
    jmp short .bl
.bldone:
    mov si, sh_s_crlf
    call sh_stgput
    pop si
.bnext:
    pop cx
    add si, SH_BT_SZ
    loop .b
.notes:
    xor si, si
    mov cx, [sh_nnote]
    or cx, cx
    jnz .n
    jmp .out
.n:
    push cx
    push es
    mov es, [sh_noteseg]
    mov ax, [es:si]
    mov cx, [es:si+2]
    mov dx, [es:si+4]                  ; the text's arena offset
    pop es
    SHOUT sh_unpackrow
    cmp bx, [sh_cursheet]
    jne .nnext
    mov [sh_wrec_row], ax
    mov [sh_wrec_col], cx
    mov ax, di
    add ax, 3 * SH_NOTEMAX + 30        ; every character could be a break
    cmp ax, SH_STAGE_MAX
    ja .full
    push si
    mov si, sh_s_c                     ; "C;X"
    call sh_stgput
    call sh_sylk_xy
    mov si, sh_s_sylk_fa               ; ";A"
    call sh_stgput
    mov si, dx
    mov cx, SH_NOTEMAX
.nt:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    or al, al
    jz .ntdone
    inc si
    cmp al, 10
    jne .ntsemi
    mov al, 27                         ; ESC " :" - a line break
    call sh_stgputb
    mov al, ' '
    call sh_stgputb
    mov al, ':'
    jmp short .ntput
.ntsemi:
    cmp al, ';'
    jne .ntput
    call sh_stgputb                    ; doubled
.ntput:
    call sh_stgputb
    loop .nt
.ntdone:
    mov si, sh_s_crlf
    call sh_stgput
    pop si
.nnext:
    pop cx
    add si, SH_NOTE_REC
    dec cx
    jz .out
    jmp .n
.full:
    mov byte [sh_trunc], 1
    pop cx
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_stgput - append DS:SI (NUL-terminated) to ES:DI, advancing DI. ES must
; already be the staging segment (the caller's job); no NUL is written to
; the destination, since the staging buffer is a raw byte stream whose
; total length is tracked separately, not a re-readable C string.
; -----------------------------------------------------------------------------
sh_stgput:
    push ax
.loop:
    mov al, [si]
    or al, al
    jz .done
    mov [es:di], al
    inc si
    inc di
    jmp .loop
.done:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_doread - read [sh_name], format chosen by its extension (see sh_dowrite)
; -----------------------------------------------------------------------------
shm_doread:
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_dif
    SHOUT sh_nameends
    pop di
    pop si
    jc .dif
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_biff
    SHOUT sh_nameends
    pop di
    pop si
    jc .biff
    push si                            ; .XLS is Excel's own name for the same
    push di                            ; thing, and Excel 2.1's are BIFF2,
    mov si, sh_name                    ; which the BIFF reader takes (81.52)
    mov di, sh_s_ext_xls
    SHOUT sh_nameends
    pop di
    pop si
    jc .biff
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_csv
    SHOUT sh_nameends
    pop di
    pop si
    jc .csv
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_txt
    SHOUT sh_nameends
    pop di
    pop si
    jc .txt
    push si
    push di
    mov si, sh_name
    mov di, sh_s_ext_dbf
    SHOUT sh_nameends
    pop di
    pop si
    jc .dbf
    jmp sh_doread_sylk
.dif:
    jmp sh_doread_dif
.biff:
    jmp sh_doread_biff
.csv:
    jmp sh_doread_csv
.txt:
    jmp sh_doread_txt
.dbf:
    jmp sh_doread_dbf

; -----------------------------------------------------------------------------
; sh_doread_sylk - read [sh_name] as SYLK, replacing the sheet
; -----------------------------------------------------------------------------
sh_doread_sylk:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    mov es, [sh_stgseg]
    xor bx, bx
    mov cx, SH_STAGE_MAX
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_READ              ; out: DX:AX = bytes read, or CF=1
    jc .rerr

    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0           ; "replacing the sheet" means the old
    mov word [sh_nbord], 0            ; document's arena text, borders and
    mov word [sh_ntbl], 0            ; 81.114.7: ...and its TABLES
    mov word [sh_nnote], 0            ; notes too, not just its cells
    SHOUT sh_colw_clear                ; ...and every column's width (81.56)
    mov word [sh_nnames], 0           ; ...and its defined names (81.10.8)
    call sh_kindreset                  ; 81.97: a worksheet until a BOF says
    mov cx, ax                        ; a file this small never exceeds 64KB
    xor si, si
    call sh_parseslk
    mov word [sh_msg], sh_m_loaded
    jmp .out
.rerr:
    call sh_setferr
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; File I/O: DIF write and read - the "expanded file format" alongside SYLK
; (SPEC-free, this project's own subset - round-trips against itself, like
; the SYLK subset already does, not certified interchange with a specific
; external product, but DOES follow the real per-cell data-line grammar so
; a genuine DIF-reading program can open it). DIF is fundamentally DENSE -
; it declares a column and row count up front and must then supply a value
; for every cell in that rectangle - so unlike SYLK's sparse C-records, the
; write walks the sheet's USED BOUNDING BOX (sh_difbbox), not the full
; 256x16384 grid: a handful of cells clustered near the origin, which is
; what this stage's sheets actually look like, stays a small file; the
; roadmap's full grid size is a ceiling on what a cell address can BE, not
; a promise that every format scales to a dense encoding of all of it.
;
; Each occupied cell is written as real DIF's numeric data item: type 0
; (NUMERIC), the value, then the literal value-indicator keyword V (valid)
; on its own line - NOT a comment string. An earlier version of this
; writer got this wrong (it emitted an empty quoted comment string, "",
; where V belongs, since a type-0 item has no comment-string line at all
; in the real format) and marked a gap in the bounding box as type 1
; (STRING) with the bare word NA where a quoted string was required; both
; are fixed now - a gap is type 0 with the NA indicator instead, per the
; real spec's own "0 - numeric type ... indicator: V/NA/ERROR/TRUE/FALSE"
; rule. On read, TRUE and FALSE are the logical (81.51) and ERROR is #N/A;
; any other indicator (a foreign file's NA) means "leave this cell blank",
; the same as this app's own concept of empty. Like SYLK, only the cached VALUE is carried -
; a formula's source text is not, and per the user's explicit direction
; this stage does NOT extend DIF with any per-cell formatting: real DIF
; has no such concept (unlike real SYLK, which has actual P/font records -
; see the SYLK section below), so this format only ever carries values.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_nameends - in: SI=name (NUL-terminated), DI=suffix (NUL-terminated);
; out: CF=1 if name ends with suffix (case-sensitive: 8.3 names arrive
; already uppercase from the kernel, and so do the suffixes this file
; compares against)
; -----------------------------------------------------------------------------
section .text
sh_nameends:
    push ax
    push bx
    push cx
    push si
    push di
    xor cx, cx
    mov bx, si
.namelen:
    cmp byte [bx], 0
    je .havenamelen
    inc bx
    inc cx
    jmp .namelen
.havenamelen:
    push cx                          ; CX = strlen(name)
    xor cx, cx
    mov bx, di
.suflen:
    cmp byte [bx], 0
    je .havesuflen
    inc bx
    inc cx
    jmp .suflen
.havesuflen:
    pop bx                           ; BX = strlen(name), CX = strlen(suffix)
    cmp cx, bx
    ja .no                           ; suffix longer than the whole name
    mov ax, si
    add ax, bx
    sub ax, cx                       ; AX = name + (namelen - suflen)
    mov si, ax
.cmp:
    or cx, cx
    jz .yes
    mov al, [si]
    cmp al, [di]
    jne .no
    inc si
    inc di
    dec cx
    jmp .cmp
.yes:
    stc
    jmp .out
.no:
    clc
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_difbbox - the sheet's used bounding box (0,0)-(sh_bbcol,sh_bbrow),
; both 0 for an empty sheet. sh_bbrow is free (the array is row-sorted, so
; it is just the last record's row); sh_bbcol needs a scan.
; -----------------------------------------------------------------------------
section SH_MODSEC                      ; 82.16.9
shm_difbbox:
    push ax
    push bx
    push cx
    push si
    push es
    mov word [sh_bbrow], 0
    mov word [sh_bbcol], 0
    cmp word [sh_ncells], 0
    je .out
    mov es, [sh_cellseg]
    xor cx, cx
.scan:
    cmp cx, [sh_ncells]
    jae .out
    mov ax, cx
    mov bx, SH_C_SZ
    mul bx
    mov si, ax                        ; si = this record's byte offset
    mov ax, [es:si]                   ; packed row/sheet (stage 2.0)
    SHOUT sh_unpackrow                 ; -> ax=real row, bx=sheet
    cmp bx, [sh_cursheet]
    jne .next                         ; a sheet's records aren't
                                       ; necessarily contiguous from index 0,
                                       ; so this scans every record rather
                                       ; than assuming the last one is ours
    cmp ax, [sh_bbrow]
    jbe .rowok
    mov [sh_bbrow], ax
.rowok:
    mov ax, [es:si+2]                 ; this record's col
    cmp ax, [sh_bbcol]
    jbe .next
    mov [sh_bbcol], ax
.next:
    inc cx
    jmp .scan
.out:
    pop es
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dowrite_dif - write the sheet to [sh_name] as DIF
; -----------------------------------------------------------------------------
sh_dowrite_dif:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    call shm_difbbox                  ; THE MODULE'S OWN COPY, not the resident
                                      ; stub of the same name. A near `call
                                      ; sh_difbbox` from here targets that
                                      ; offset in the MODULE's segment, which
                                      ; is whatever code happens to sit there -
                                      ; and the DIF writer simply stopped
                                      ; producing a file (82.16.9)
    mov byte [sh_trunc], 0
    mov es, [sh_stgseg]
    xor di, di
    mov si, sh_s_dif_hdr1
    call sh_stgput
    mov ax, [sh_bbcol]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_dif_hdr2
    call sh_stgput
    mov ax, [sh_bbrow]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_dif_hdr3
    call sh_stgput

    mov word [sh_wrow], 0
.rloop:
    mov ax, [sh_wrow]
    cmp ax, [sh_bbrow]
    ja .footer
    mov ax, di
    add ax, 16
    cmp ax, SH_STAGE_MAX
    ja .truncf                        ; truncate - documented, same spirit
                                       ; as the SYLK writer's own room check
    mov si, sh_s_dif_bot
    call sh_stgput
    mov word [sh_wcol], 0
.cloop:
    mov ax, [sh_wcol]
    cmp ax, [sh_bbcol]
    ja .rnext
    mov ax, di
    add ax, SH_EDITMAX + 24           ; worst case is now a LABEL and its
    cmp ax, SH_STAGE_MAX              ; quotes, not "0,-32768\r\nV\r\n"
    ja .truncf
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_getcell2
    jnc .na
    cmp byte [sh_curtype], SH_T_TEXT   ; stage 4.5: DIF's type 1 is STRING -
    je .dtext                          ; "1,0" then the quoted text on the
    cmp byte [sh_curtype], SH_T_BOOL   ; a LOGICAL takes DIF's own TRUE or
    je .dbool                          ; FALSE indicator (81.51)
    cmp byte [sh_curtype], SH_T_ERR    ; ...and an ERROR takes DIF's own ERROR
    je .derr                           ; indicator. DIF cannot say WHICH error,
    mov si, sh_s_dif_zc                ; following line, which is the real
    call sh_stgput                     ; format's own grammar
    push si                            ; ...and the value goes out as a FULL
    push di                            ; DECIMAL. This wrote `mov ax, dx` -
    mov si, sh_acc                     ; the TRUNCATED integer - so a sheet
    SHOUT fp_unpack_a                   ; holding 3.5 saved to DIF as 3, in
    mov di, sh_numbuf                  ; silence, and reloaded as 3. Stage 4.0
    mov ax, 10                         ; converted SYLK's K field and left this
    SHOUT fp_ftoa                       ; one behind; DIF's numeric item has
    pop di                             ; never been restricted to integers.
    pop si
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_crlf
    call sh_stgput
    mov si, sh_s_dif_v
    call sh_stgput
    jmp .cnext
.dbool:
    mov si, sh_s_dif_zc                ; "0,1" CRLF "TRUE", or 0 and FALSE -
    call sh_stgput                     ; the value and the indicator agree
    mov ax, [sh_acc+6]
    and ax, 0x7FFF
    mov al, '0'
    jz .db0
    inc ax
.db0:
    call sh_stgputb
    mov si, sh_s_crlf
    call sh_stgput
    mov ax, [sh_acc+6]
    SHOUT sh_boolname
    mov si, sh_numbuf
    call sh_stgput
    mov si, sh_s_crlf
    call sh_stgput
    jmp .cnext
.dtext:
    mov si, sh_s_dif_1c
    call sh_stgput                     ; "1,0" CRLF, then the quoted string
    mov al, 34
    call sh_stgputb
    mov si, [sh_curtoff]
.dt:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    or al, al
    jz .dtend
    inc si
    cmp al, 34                         ; DIF has no escape for an embedded
    je .dt                             ; quote, so one is DROPPED rather than
    cmp al, 13                         ; written out to break the line - the
    je .dt                             ; label loses a character, the file
    cmp al, 10                         ; stays parseable
    je .dt
    call sh_stgputb
    jmp .dt
.dtend:
    mov al, 34
    call sh_stgputb
    mov si, sh_s_crlf
    call sh_stgput
    jmp .cnext
.derr:
    mov si, sh_s_dif_err0              ; but a file that says ERROR is honest,
    call sh_stgput                     ; where the 0 underneath one is a lie
    jmp .cnext
.na:
    mov si, sh_s_dif_na0
    call sh_stgput
.cnext:
    mov ax, [sh_wcol]
    inc ax
    mov [sh_wcol], ax
    jmp .cloop
.rnext:
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    jmp .rloop
.truncf:
    mov byte [sh_trunc], 1            ; the buffer filled before the bounding
                                       ; box was covered - the header already
                                       ; promised the full box, so say so
.footer:
    mov si, sh_s_dif_eod
    call sh_stgput
    mov [sh_stagelen], di

    mov ax, [sh_stgseg]
    mov es, ax
    xor bx, bx
    mov cx, [sh_stagelen]
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_WRITE
    jc .werr
    mov word [sh_msg], sh_m_saved
    cmp byte [sh_trunc], 0            ; cells dropped for room must not be
    je .wdone                         ; reported as a plain success
    mov word [sh_msg], sh_m_trunc
    jmp .wdone
.werr:
    call sh_setferr
.wdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_difskipline - in: ES:SI, DI=end (exclusive); out: SI advanced past the
; next CR/LF run (any mix of the two, so both conventions read correctly)
; -----------------------------------------------------------------------------
sh_difskipline:
    push ax
.scan:
    cmp si, di
    jae .out
    mov al, [es:si]
    inc si
    cmp al, 13
    je .eat
    cmp al, 10
    je .eat
    jmp .scan
.eat:
    cmp si, di
    jae .out
    mov al, [es:si]
    cmp al, 13
    je .eat2
    cmp al, 10
    je .eat2
    jmp .out
.eat2:
    inc si
    jmp .eat
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_doread_dif - read [sh_name] as DIF, replacing the sheet. Skips the
; fixed 12-line header (this project's own writer always emits exactly
; that many), then reads row markers ("-1,0"/"BOT" or the closing "EOD")
; and, within a row, cell records ("0,<value>" or "1,0"/"NA").
; -----------------------------------------------------------------------------
sh_doread_dif:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    mov es, [sh_stgseg]
    xor bx, bx
    mov cx, SH_STAGE_MAX
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_READ               ; out: DX:AX = bytes read, or CF=1
    jc .rerr

    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0            ; "replacing the sheet" - see
    mov word [sh_nbord], 0             ; sh_doread_sylk's same three
    mov word [sh_ntbl], 0            ; 81.114.7: ...and its TABLES
    mov word [sh_nnote], 0
    SHOUT sh_colw_clear                ; ...and every column's width (81.56)
    mov word [sh_nnames], 0            ; DIF carries no names, so a DIF load
                                       ; leaves none - still a REPLACEMENT,
                                       ; not an inheritance
    call sh_kindreset                  ; 81.97: a worksheet until a BOF says
    mov es, [sh_stgseg]
    mov di, ax                         ; DI = end (bytes read)
    xor si, si
    mov cx, 12                         ; the header is always 12 lines
.skiphdr:
    call sh_difskipline
    loop .skiphdr
    mov word [sh_wrow], 0xFFFF         ; becomes 0 at the first BOT
.rowloop:
    cmp si, di
    jae .done
    call sh_difskipline                ; the "-1,0" line
    cmp si, di
    jae .done
    mov al, [es:si]
    cmp al, 'E'
    je .done                           ; EOD
    call sh_difskipline                ; the "BOT" line
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    mov word [sh_wcol], 0
.cellloop:
    cmp si, di
    jae .done
    mov al, [es:si]
    cmp al, '-'
    je .rowloop                        ; the next row's "-1,0"
    cmp al, '1'
    je .dstring                        ; stage 4.5: type 1 IS a string item,
    cmp al, '0'                        ; and this app writes them now - the
    jne .skipunknown                   ; comment that used to sit here said it
                                        ; never would, and skipping them was
                                        ; the right defence at the time
    add si, 2                          ; past "0,"
    mov bx, di
    call sh_esatof                     ; a full decimal into sh_acc, not
    call sh_difskipline                ; sh_pint's integer: the writer emits
    cmp si, di                         ; 3.5 and this read it back as 3
    jae .cellnext
    cmp word [sh_wcol], SH_COLS        ; a file with more data items per row
    jae .notvalid                      ; than the grid has columns walks
                                       ; sh_wcol off it - drop the surplus,
                                       ; but still consume its indicator line
    cmp byte [es:si], 'V'              ; the real DIF value-indicator: V
    je .isvalid                        ; (valid) is the ordinary one; ERROR is
    cmp byte [es:si], 'T'              ; TRUE and FALSE are the LOGICAL, and
    je .istrue                         ; this app writes those now too (81.51)
    cmp byte [es:si], 'F'
    je .isfalse
    cmp byte [es:si], 'E'              ; the other one this app writes, and
    jne .notvalid                      ; NA from a foreign file still just
    mov dl, SH_ERR_NA                  ; means "leave this cell blank"
    mov ax, [sh_wcol]                  ; here.
    mov bx, [sh_wrow]                  ; #N/A is what an ERROR comes back as:
    SHOUT sh_seterr                    ; the file said a value was not
    jmp .notvalid                      ; available and could not say more, and
.isvalid:                              ; #N/A is the one error that means
    mov ax, [sh_wcol]                  ; exactly that. Guessing a specific one
    mov bx, [sh_wrow]                  ; would be inventing what the file does
    SHOUT sh_setvald                    ; not contain
    jmp short .notvalid
.istrue:
    mov dl, 1
    jmp short .dlog
.isfalse:
    mov dl, 0
.dlog:
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_setbool
.notvalid:
    call sh_difskipline                ; the indicator line
    jmp .cellnext
.dstring:
    call sh_difskipline                ; past the "1,0" line; the quoted text
    cmp si, di                         ; is the line after it
    jae .cellnext
    cmp word [sh_wcol], SH_COLS        ; off-grid column: skip the text line
    jae .notvalid                      ; too (see the numeric item above)
    cmp byte [es:si], 34
    jne .notvalid                      ; not quoted: not a string item this
    inc si                             ; app can use - skip the line
    push di                            ; DI is the buffer END and is needed
    push di                            ; again below, so it is banked twice:
    mov di, SH_TEXPR                   ; once for the loop bound in CX terms
    mov cx, SH_EDITMAX                 ; and once as the cursor here
    pop bx                             ; BX = the end offset
.ds:
    jcxz .dsend
    cmp si, bx
    jae .dsend
    mov al, [es:si]
    cmp al, 34
    je .dsend
    cmp al, 13
    je .dsend
    cmp al, 10
    je .dsend
    mov [di], al
    inc di
    inc si
    dec cx
    jmp .ds
.dsend:
    mov byte [di], 0
    pop di
    push si
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    mov si, SH_TEXPR
    SHOUT sh_settext
    pop si
    call sh_difskipline
    jmp .cellnext
.skipunknown:
    call sh_difskipline
.cellnext:
    mov ax, [sh_wcol]
    inc ax
    mov [sh_wcol], ax
    jmp .cellloop
.done:
    mov word [sh_msg], sh_m_loaded
    jmp .out
.rerr:
    call sh_setferr
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; File I/O: BIFF write and read. docs/BIFF-NOTES.md is the record-by-record
; table of what goes out and what is accepted; SPEC.md 81.7, 81.10.2,
; 81.10.5 and 81.20.1 are the design decisions. In short:
;
; One sheet is a BIFF3 stream (BOF 0209H); more than one is a BIFF4 workbook
; (sh_biff_workbook). An exact in-range integer is an RK record (027EH,
; signed-30-bit subtype - the older INTEGER record's value is UNSIGNED and
; cannot carry a negative cell), anything else a NUMBER (0203H) carrying the
; IEEE-754 double verbatim; a label is a LABEL (0204H), a formula a FORMULA
; (0206H) with its RPN tokens and cached result, and an error whose formula
; could not be tokenised a BOOLERR (0205H). On read all four RK subtypes are
; decoded (sh_rkdec_d), NUMBER/LABEL/BOOLERR are taken, and a FORMULA's cached
; RESULT is used with its tokens skipped - so a formula written by this app
; comes back as a value, unlike SYLK's ;E.
; Like SYLK, this is sparse (one record per occupied cell, walking the
; sorted array directly), not dense like DIF, since a binary record already
; carries its own row/col and needs no bounding box.
;
; Bold/underline/alignment/number-format persist through real BIFF3/4
; structure: 4 FONT records (0231H) for the 4 bold/underline combinations,
; 64 XF records (0243H, or 0443H in the workbook) - one per possible
; SH_FMT_* byte value - and each cell record points at its XF by index. That
; 1:1 pairing between our format byte and the BIFF ixfe is deliberate: it
; means neither side needs a lookup table to go from "this cell's 6
; format bits" to "this cell's XF index" or back, at the cost of always
; writing all 64 XFs whether or not the sheet uses every combination (at
; most 64*16 + 4*15 bytes - a fixed, small overhead). No FORMAT records are
; written at all: General/Currency/Comma/Percent all land on real BIFF
; built-in number-format ids (0/5/3/9), the 0-decimal-place forms.
; =============================================================================

; 81.97: THE DOCUMENT'S KIND. Excel has worksheets and macro sheets, and the
; BOF record's dt word says which a stream is (0010H, 0040H). A macro sheet
; here is a worksheet that SAYS so - every cell, function and command works
; the same on both, because SHEET's macros have always run from ordinary
; cells - and that shows its formulas, as Excel's does.
; sh_macsheet - make this document a macro sheet, formulas shown
sh_macsheet:
    mov byte [sh_dockind], 1
    cmp byte [sh_showformulas], 0     ; 2 = and the formulas on show are
    jne .out                          ; THIS document's doing, so closing it
    mov byte [sh_dockind], 2          ; takes them away again; 1 = the user
    mov byte [sh_showformulas], 1     ; already had them on and keeps them
.out:
    ret

; sh_kindreset - a worksheet again: the formulas a macro sheet showed go, and
; a Formulas the user turned on for a worksheet stays
sh_kindreset:
    cmp byte [sh_dockind], 0
    je .out
    cmp byte [sh_dockind], 2          ; 1: the user's own Formulas, untouched
    mov byte [sh_dockind], 0
    jne .out
    mov byte [sh_showformulas], 0
.out:
    ret

; sh_biff_dt - AX = the BOF's dt for this document
sh_biff_dt:
    mov ax, 0x0010
    cmp byte [sh_dockind], 0
    je .out
    mov ax, 0x0040
.out:
    ret

; sh_rd_bofkind - a BOF at ES:SI, DX long: dt 0040H makes this a macro sheet.
; A workbook's globals BOF (0100H) and a worksheet's say nothing, so a
; workbook with one macro sheet in it is a macro sheet document - SHEET's
; kind is the document's, not a sheet's
sh_rd_bofkind:
    cmp dx, 4
    jb .out
    cmp word [es:si+2], 0x0040
    jne .out
    call sh_macsheet
.out:
    ret


; -----------------------------------------------------------------------------
; sh_biffw - append raw word AX to ES:DI (little-endian, matching BIFF and
; this CPU), advancing DI by 2. ES must already be the staging segment.
; -----------------------------------------------------------------------------
sh_biffw:
    mov [es:di], ax
    add di, 2
    ret

; -----------------------------------------------------------------------------
; sh_stgputb - append raw byte AL to ES:DI, advancing DI by 1. ES must
; already be the staging segment (the caller's job, as with sh_stgput).
; Used for a BIFF length-prefix byte (sh_biffw only writes whole words) and
; for a SYLK F record's single-character format codes.
; -----------------------------------------------------------------------------
sh_stgputb:
    mov [es:di], al
    inc di
    ret

; -----------------------------------------------------------------------------
; sh_rkenc - in: AX = signed 16-bit cell value; out: DX:AX = that value
; packed as an RK "signed 30-bit integer, not multiplied by 100" (bit1=1,
; bit0=0 of the low word) - AX is the low word of the 4-byte RK value, DX
; the high word, matching write order (low word first, then high).
; -----------------------------------------------------------------------------
sh_rkenc:
    push cx
    cwd                    ; DX:AX = AX sign-extended to 32 bits
    mov cx, 2
.shl:
    shl ax, 1
    rcl dx, 1
    loop .shl
    or ax, 0x0002
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_rkdec_d - in: DX:AX = a packed RK value; out: sh_acc = it, as a double.
;
; ALL FOUR SUBTYPES, where its integer-only predecessor handled only the one an integer
; could represent. The other three - divided by 100, and the float form that
; is the TOP 32 BITS of an IEEE-754 double with the low 32 zero - are exactly
; the ones a 16-bit integer had to refuse, and refusing them meant silently
; dropping cells from any file Excel itself had written.
;
;   bit0 = 1: the value is 100x what was meant
;   bit1 = 1: integer form, a signed 30-bit value in the top 30 bits
;   bit1 = 0: float form, the top 32 bits of a double
; -----------------------------------------------------------------------------
sh_rkdec_d:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, ax                        ; bl bit0/bit1 = the subtype flags
    test al, 0x02
    jz .float
    mov cx, 2                         ; integer form: an arithmetic shift, so
.shr:                                 ; a negative value stays negative
    sar dx, 1
    rcr ax, 1
    loop .shr
    push bx
    call fp_i32_to_a                  ; DX:AX (signed 32) -> A
    pop bx
    jmp .div100
.float:
    and ax, 0xFFFC                    ; the two flag bits are not mantissa
    mov word [sh_acc], 0              ; the low 32 bits of the double are zero
    mov word [sh_acc+2], 0            ; by construction in this form
    mov [sh_acc+4], ax
    mov [sh_acc+6], dx
    push bx
    SHOUT sh_acc_load_a
    pop bx
.div100:
    test bl, 0x01
    jz .out
    mov ax, 100                       ; bit0: it was scaled up by a hundred
    SHOUT fp_i2b
    SHOUT fp_div
.out:
    SHOUT sh_acc_store
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_i32_to_a - DX:AX, a SIGNED 32-bit integer, becomes A.
fp_i32_to_a:
    push ax
    push bx
    push cx
    push di
    mov byte [fp_as], 0
    or dx, dx
    jns .abs
    mov byte [fp_as], 1
    neg dx                            ; the 32-bit negate idiom
    neg ax
    sbb dx, 0
.abs:
    mov [fp_am0], ax
    mov [fp_am1], dx
    mov word [fp_am2], 0
    mov word [fp_am3], 0
    mov word [fp_ae], 0
    mov bx, fp_am0
    mov di, fp_ae
    SHOUT fp_norm
    pop di
    pop cx
    pop bx
    pop ax
    ret

section .text

; -----------------------------------------------------------------------------
; sh_biff_numfmt_from_id - in: AL = a real BIFF built-in number-format id;
; out: AL = this app's SH_FMT_NUM_* code (General for anything that isn't
; one of the four ids sh_biff_numfmt_tab itself ever writes - a custom
; FORMAT record's id, or a built-in this app doesn't have an equivalent
; for, both just degrade to General rather than guessed at)
; -----------------------------------------------------------------------------
section SH_MODSEC                      ; 82.16.9
; sh_cwbyte - AX = a width in characters from a file -> CL = what the width
; table keeps: clamped to what the Column Width dialog allows, and 0 for the
; standard width, so a file that states it costs the table nothing (81.56)
sh_cwbyte:
    cmp ax, SH_CW_MINCH
    jae .a
    mov ax, SH_CW_MINCH
.a:
    cmp ax, SH_CW_MAXCH
    jbe .b
    mov ax, SH_CW_MAXCH
.b:
    mov cl, al
    cmp ax, [sh_defch]
    jne .c
    xor cl, cl
.c:
    ret

; sh_biff_nfside - AL = a file's built-in format id -> AL = what the border
; table keeps for it: 0 for the four the format byte holds (and for any id
; past Excel's 21, a custom FORMAT this app draws as General), else id + 1
sh_biff_nfside:
    cmp al, SH_NF_N
    jae .zero
    or al, al
    jz .out
    cmp al, 3
    je .zero
    cmp al, 5
    je .zero
    cmp al, 9
    je .zero
    inc al
    ret
.zero:
    xor al, al
.out:
    ret

sh_biff_numfmt_from_id:
    cmp al, 0x05
    je .cur
    cmp al, 0x03
    je .comma
    cmp al, 0x09
    je .pct
    xor al, al
    ret
.cur:
    mov al, SH_FMT_NUM_CURRENCY
    ret
.comma:
    mov al, SH_FMT_NUM_COMMA
    ret
.pct:
    mov al, SH_FMT_NUM_PERCENT
    ret

; -----------------------------------------------------------------------------
; sh_b2_attr - a BIFF2 cell's three attribute bytes (ES:SI+4..6, 2.5.13) into
; XF slot SH_B2_XF, the three bytes .isxf decodes a BIFF3 XF into: font and
; number format from byte 1, alignment, borders and shade from byte 2,
; protection from byte 0. Excel 2.1 writes the built-in FORMAT list in the
; built-in order, so the format index IS the built-in id. (81.52)
; -----------------------------------------------------------------------------
sh_b2_attr:
    push ax
    push bx
    push cx
    mov bx, SH_B2_XF
    mov al, [es:si+5]                  ; bits 7-6 FONT, 5-0 FORMAT
    mov ah, al
    mov cl, 6
    shr ah, cl
    mov [bx+sh_xf_font], ah
    and al, 0x3F
    push ax
    call sh_biff_nfside                ; any but the format byte's four waits
    mov [bx+sh_xf_nf], al              ; beside the border (81.55)
    pop ax
    mov ah, [es:si+6]                  ; bits 2-0 XF_HOR_ALIGN
    and ah, 7
    cmp ah, 3
    jbe .al
    xor ah, ah                         ; Fill: General, as .isxf does
.al:
    mov cl, SH_FMT_ALIGN_SHIFT
    shl ah, cl
    call sh_biff_numfmt_from_id        ; AL -> this app's code, AH kept
    mov cl, SH_FMT_NUM_SHIFT
    shl al, cl
    or al, ah
    mov [bx+sh_xf_fmt], al
    xor ah, ah
    mov al, [es:si+6]                  ; bit 3 left, 4 right, 5 top, 6 bottom,
    test al, 0x08                      ; 7 shaded
    jz .nl
    or ah, SH_BORD_LEFT
.nl:
    test al, 0x10
    jz .nr
    or ah, SH_BORD_RIGHT
.nr:
    test al, 0x20
    jz .nt
    or ah, SH_BORD_TOP
.nt:
    test al, 0x40
    jz .nb
    or ah, SH_BORD_BOTTOM
.nb:
    test al, 0x80
    jz .ns
    or ah, SH_BORD_SHADE
.ns:
    mov al, [es:si+4]                  ; bit 6 locked, bit 7 hidden - and this
    test al, 0x40                      ; app stores the EXCEPTION (81.46.1)
    jnz .lk
    or ah, SH_PROT_UNLOCK
.lk:
    test al, 0x80
    jz .nh
    or ah, SH_PROT_HIDDEN
.nh:
    mov [bx+sh_xf_bord], ah
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_biff_applyfmt - in: sh_wrec_col/sh_wrec_row (the cell just written by
; sh_setvald), sh_wrec_xf (its BIFF ixfe); combines sh_xf_fmt/sh_xf_font (if
; the xf index is one this reader tracked) with sh_font_tab (if that xf's
; font index is one it tracked) into this app's own format byte, and
; writes it to the cell. A cell whose xf or font fell outside the tracked
; caps is left at format 0 (General, unformatted) rather than guessed at.
; -----------------------------------------------------------------------------
sh_biff_applyfmt:
    push ax
    push bx
    push cx
    push di
    push es
    mov bx, [sh_wrec_xf]
    cmp bx, SH_BIFF_XF_CAP
    jae .out
    cmp bx, [sh_biff_nxf]              ; ...AND one this file actually carried.
    jae .out                           ; These tables are not cleared between
                                       ; loads, only the counts are, so a file
                                       ; with fewer XFs than the last one would
                                       ; otherwise read the previous file's
                                       ; bytes - harmless-looking for a format
                                       ; byte and not at all harmless for a
                                       ; border, which would appear on cells
                                       ; that never had one
    mov di, sh_xf_fmt
    add di, bx
    mov al, [di]                       ; al = align|numfmt packed byte
    mov di, sh_xf_font
    add di, bx
    mov cl, [di]                       ; cl = this xf's font index
    xor ch, ch
    cmp cx, SH_BIFF_FONT_CAP
    jae .noboldunder
    mov di, sh_font_tab
    add di, cx
    or al, [di]                        ; fold in bold/underline
.noboldunder:
    mov cl, al                         ; stash the finished byte in cl
    mov di, sh_xf_bord                 ; ...and this XF's border/protection
    add di, bx                         ; bits in CH, across the same lookup
    mov ch, [di]
    mov al, [bx+sh_xf_nf]              ; ...and its number format (81.55)
    mov [sh_xfw_nf], al
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_findcell
    jnc .nocell                        ; 81.77: a cell with NO RECORD still
    mov es, [sh_cellseg]               ; takes its border and number format,
    mov [es:di+5], cl                  ; which live in the side table anyway -
.nocell:                               ; it is only the FORMAT BYTE that has
                                       ; nowhere to go. This used to return
                                       ; here, so a BLANK record read back as
                                       ; nothing at all
    mov al, ch
    or al, [sh_xfw_nf]                 ; a border table record only for the
    jz .out                            ; cells that need one, which is the
    mov ax, [sh_wrec_col]              ; table's whole convention (81.46.1)
    mov bx, [sh_wrec_row]
    SHOUT sh_bt_addcell
    jc .out                            ; full: silent, as everywhere else that
    push es                            ; writes this table
    mov es, [sh_bordseg]
    mov [es:di+4], ch
    mov al, [sh_xfw_nf]
    mov [es:di+5], al
    pop es
.out:
    pop es
    pop di
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dowrite_biff - write the sheet to [sh_name] as BIFF. Walks the sorted
; cell array directly, same shape as sh_dowrite_sylk.
; -----------------------------------------------------------------------------
sh_dowrite_biff:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    push di                           ; 81.114.10: no table has had its
    push es                           ; DATATABLE written into THIS file yet.
    push ds                           ; Once per file and not per sheet: a
    pop es                            ; workbook's tables are one list, and
    mov di, sh_tbl_wdone              ; the bitmap is indexed by the list
    mov cx, (SH_TBL_CAP + 7) / 8
    xor al, al
    cld
    rep stosb
    pop es
    pop di
    call sh_sheets_used               ; ONE sheet keeps the BIFF3 stream this
    cmp ax, 2                         ; writer has always produced, byte for
    jb .single                        ; byte. More than one needs a WORKBOOK,
    call sh_biff_workbook             ; and BIFF3 has no such thing (81.10.5)
    jmp .wdone
.single:
    mov es, [sh_stgseg]
    xor di, di

    mov ax, 0x0209                   ; BOF (BIFF3). NOT BIFF4, deliberately:
                                      ; a reader is BACKWARD compatible and
                                      ; not forward compatible, so Excel 4 and
                                      ; everything after it read a BIFF3 file
                                      ; happily, while a program that knows
                                      ; only BIFF3 cannot read a BIFF4 one -
                                      ; it does not even recognise the BOF.
                                      ; Emitting the older stream is therefore
                                      ; strictly the wider audience, and costs
                                      ; nothing: every record this writer uses
                                      ; exists in BIFF3.
    call sh_biffw
    mov ax, 6
    call sh_biffw
    mov ax, 0x0300                   ; vers = BIFF3, matching the BOF above
    call sh_biffw
    call sh_biff_dt                  ; dt = worksheet, or macro sheet
    call sh_biffw
    xor ax, ax                       ; BIFF3's BOF carries two more bytes,
    call sh_biffw                    ; documented as "not used" - BIFF2's
                                      ; record is the four-byte one, and a
                                      ; reader that trusts the length would
                                      ; desynchronise on the short form

    call sh_xfp_scan                  ; the pairs FIRST: the XF records are
    call sh_biff_fontsxfs             ; part of the globals and every cell
    call sh_biff_names                ; record after them names one by index
                                      ; records - excelfileformat's own 4.2.3
                                      ; and 4.10.1 are both "2do" for BIFF3/4,
                                      ; so this follows the BIFF5 worksheet
                                      ; stream it does document

    mov byte [sh_trunc], 0
    mov ax, [sh_cursheet]            ; the BIFF3 stream is ONE sheet, and says
    mov [sh_wsheet], ax              ; so in the status bar when there are more
    call sh_biff_cells
.footer:
    mov ax, 0x000A                    ; EOF
    call sh_biffw
    xor ax, ax
    call sh_biffw
    mov [sh_stagelen], di

    mov ax, [sh_stgseg]
    mov es, ax
    xor bx, bx
    mov cx, [sh_stagelen]
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_WRITE
    jc .werr
    mov word [sh_msg], sh_m_saved
    mov byte [sh_modified], 0         ; BIFF writes the WORKBOOK, so a plain
                                      ; success here is clean whatever
                                      ; sh_sheets_used would say (81.118)
    cmp byte [sh_trunc], 0            ; cells dropped for room must not be
    je .wdone                         ; reported as a plain success
    mov word [sh_msg], sh_m_trunc
    mov byte [sh_modified], 1         ; ...and a truncated file is not saved
    jmp .wdone
.werr:
    call sh_setferr
.wdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_doread_biff - read [sh_name] as BIFF, replacing the sheet. Skips the
; BOF record (and every other record type this subset doesn't know, by its
; length - so a real file's extra records, e.g. a workbook-globals BOF,
; FONT, or FORMAT record, are tolerated rather than misparsed), then
; applies every RK cell record found whose value is this subset's
; understood subtype, until EOF or the buffer end (a truncated/foreign
; file).
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_biff_formula - a FORMULA record (0206H in BIFF3) for the cell being
; written. out: CF=0 it was written; CF=1 = not expressible, and the caller
; falls through to RK/NUMBER exactly as before.
;
; The result field carries the CACHED VALUE as an IEEE double, which is what
; the record is for: a reader that does not recalculate still shows the right
; number, and one that does gets the same answer from the tokens.
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_biff_names - one DEFINEDNAME record per defined name, at ES:DI.
;
; THE OPCODE IS 0218H, NOT 0018H, and that is the whole reason to read the
; reference before writing this. 0018H is the BIFF2 number, and BIFF5 and
; BIFF8 took it back; BIFF3 and BIFF4 - the two versions this app writes -
; use 0218H (excelfileformat 5.33). Writing 0018H into a BIFF3 stream is not
; an error any reader reports: it is an unknown record, skipped by its length,
; and the names simply are not there.
;
; The body, BIFF3-4:
;
;   0  2  option flags: 0 = visible, user-defined, standard, simple formula
;   2  1  keyboard shortcut (command macros only, so 0)
;   3  1  ln = the name's length in characters
;   4  2  sz = the size of the formula data
;   6  ln the name, counted rather than NUL-terminated
;   6+ln  sz  the RPN token array, with no size field of its own
;
; The token array is one tAreaR (25H) and a six-byte cell-range address, so
; sz is always 7 here. tAreaR and not tAreaN: 3.9.11 says a defined name in
; BIFF2-BIFF4 uses tAreaN, the RELATIVE form, "if all components of the cell
; range address are absolute, a tArea token is used instead" - and a name in
; this app is always absolute, which is the same rule sh_wr_names states for
; SYLK. Reference class (25H), not the value class 45H the cell formulas use:
; the name IS the range, it is not a value read out of one.
;
; The corners are NORMALISED here. The table stores them as the dialog gave
; them, because sh_foldrange normalises when it walks; a file has no walker,
; and BIFF's first/last are not "wherever you dragged from".
; -----------------------------------------------------------------------------
sh_biff_names:
    push ax
    push bx
    push cx
    push dx
    push si
    mov cx, [sh_nnames]
    or cx, cx                         ; not JCXZ, for the same reach reason as
    jnz .some                         ; the LOOP at the bottom of this routine
    jmp .out
.some:
    xor bx, bx
.each:
    mov ax, di
    add ax, 4 + 6 + SH_NAME_MAX + 7   ; the longest record this can emit; the
    cmp ax, SH_STAGE_MAX              ; cells matter more than the names, so
    ja .out                           ; a full staging area drops these first
    push cx
    push bx
    mov si, sh_names
    add si, bx
    xor cx, cx
.len:
    cmp byte [si], 0
    je .havelen
    inc si
    inc cx
    cmp cx, SH_NAME_MAX
    jb .len
.havelen:
    or cx, cx
    jnz .named
    jmp .nextname                     ; an empty name has nothing to define
.named:
    mov ax, 0x0218                    ; DEFINEDNAME (BIFF3/BIFF4)
    call sh_biffw
    mov ax, cx
    add ax, 6 + 7                     ; header + tAreaR + its address
    call sh_biffw
    xor ax, ax
    call sh_biffw                     ; option flags
    xor al, al
    call sh_stgputb                   ; keyboard shortcut
    mov al, cl
    call sh_stgputb                   ; ln
    mov ax, 7
    call sh_biffw                     ; sz
    mov si, sh_names
    add si, bx
.nm:
    mov al, [si]
    call sh_stgputb
    inc si
    dec cx
    jnz .nm
    mov si, sh_names                  ; the corners, normalised into
    add si, bx                        ; first/last
    add si, SH_NAME_MAX + 1
    mov ax, [si]                      ; col1, col2
    mov dx, [si+4]
    cmp ax, dx
    jbe .colok
    xchg ax, dx
.colok:
    mov [sh_nm_col], ax
    mov [sh_nm_col2], dx
    mov ax, [si+2]                    ; row1, row2
    mov dx, [si+6]
    cmp ax, dx
    jbe .rowok
    xchg ax, dx
.rowok:
    mov [sh_nm_row], ax
    mov [sh_nm_row2], dx
    mov al, 0x25                      ; tAreaR
    call sh_stgputb
    mov ax, [sh_nm_row]               ; the two relative-flag bits stay CLEAR:
    call sh_biffw                     ; set means relative (81.10.2), and a
    mov ax, [sh_nm_row2]              ; name does not move
    call sh_biffw
    mov al, [sh_nm_col]
    call sh_stgputb
    mov al, [sh_nm_col2]
    call sh_stgputb
.nextname:
    pop bx
    pop cx
    add bx, SH_NAME_REC
    dec cx                            ; not LOOP: the body above is well past
    jz .out                           ; the 127 bytes a short jump reaches
    jmp .each
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_biff_fontsxfs - the four FONT records and the sixty-four XF records, at
; ES:DI. [sh_wb_xf4] picks BIFF4's XF opcode and body layout over BIFF3's.
;
; Extracted so the BIFF4 workbook's globals section and the BIFF3 stream share
; one copy: they differ in two version-dependent details and in nothing else,
; and two copies would have drifted on the first change to a font.
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_xfp_scan - collect the distinct (format byte, border byte) pairs in the
; whole document into sh_xfp_fmt/sh_xfp_bord. (81.47)
;
; Runs BEFORE sh_biff_fontsxfs, because the XF records are part of a BIFF
; stream's globals and every cell record after them refers to one by index.
;
; ALL SHEETS, not just the one being written. A BIFF4 workbook writes one
; globals section and several sheet substreams, so the pair table has to cover
; every cell that will be emitted; for the single-sheet BIFF3 stream that
; means at worst a few XF records nothing points at, which costs 16 bytes each
; and is not worth a second code path to avoid.
; -----------------------------------------------------------------------------
sh_xfp_scan:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov ax, [sh_cursheet]            ; BANKED: the border table is keyed by
    push ax                          ; sh_cursheet (sh_bt_findcell packs it
                                     ; into the row word), and this walk
                                     ; crosses every sheet - so each record
                                     ; has to be looked up as ITS OWN sheet,
                                     ; the way sh_rowcol_op already does
    mov word [sh_nxfp], 0
    mov cx, [sh_ncells]
    jcxz .done
    xor si, si                       ; SI = the cell record's offset
.each:
    push cx
    mov es, [sh_cellseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow               ; -> AX = row, BX = sheet
    push si
    mov [sh_cursheet], bx            ; ...impersonate it before the lookup
    mov dl, [es:si+5]                ; DL = the cell's format byte
    mov bx, ax                       ; BX = row, AX = col, which is the order
    mov ax, [es:si+2]                ; sh_bt_getw wants
    SHOUT sh_bt_getw                 ; AL = its border+protection byte, AH its
    or ax, ax                        ; number format (81.55), 0 when the cell
    jz .next                         ; has no record - almost every cell
    call sh_xfp_add                  ; DL fmt, AL border, AH number format
.next:
    pop si
    pop cx
    add si, SH_C_SZ
    dec cx
    jnz .each
    ; --- AND THE ENTRIES WITH NO CELL RECORD (81.77) -----------------------
    ; A formatted or bordered EMPTY cell lives ONLY in the border table - its
    ; format is that table's sixth byte (81.55) and it has no cell record at
    ; all. The walk above cannot see it, because it walks the CELL ARRAY: so
    ; no XF pair was ever registered for it, and the BLANK record written for
    ; it would fall back to the plain format byte and carry neither the
    ; format nor the border.
    mov cx, [sh_nbord]
    jcxz .done
    xor si, si
.bteach:
    push cx
    push si
    mov es, [sh_bordseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow               ; -> AX = row, BX = its sheet
    mov [sh_cursheet], bx            ; ...impersonated, as above
    mov bx, ax
    mov es, [sh_bordseg]
    mov ax, [es:si+2]                ; AX = col, BX = row
    SHOUT sh_findcell
    jc .btnext                       ; the cell EXISTS: the walk above had it
    pop si
    push si
    mov es, [sh_bordseg]
    mov ax, [es:si+4]                ; AL border, AH number format
    or ax, ax
    jz .btnext
    xor dl, dl                       ; no cell record, so no format byte
    call sh_xfp_add
.btnext:
    pop si
    pop cx
    add si, SH_BT_SZ
    dec cx
    jnz .bteach
.done:
    pop ax
    mov [sh_cursheet], ax            ; ...and put the user's sheet back
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_xfp_add - register the (format byte, border byte, number format) triple
; in DL / AL / AH if it is new and there is room. Preserves everything.
;
; TWO WALKS SHARE IT (81.77): the cell array, and the border table's own
; entries for cells that have no record there. The second is why this is a
; routine rather than an inline block - the two have to agree exactly about
; what "already registered" means, or an XF is written twice or not at all.
; -----------------------------------------------------------------------------
sh_xfp_add:
    push cx
    push di
    mov cx, [sh_nxfp]
    xor di, di
    jcxz .add
.find:
    cmp dl, [sh_xfp_fmt + di]
    jne .fnext
    cmp al, [sh_xfp_bord + di]
    jne .fnext
    cmp ah, [sh_xfp_nf + di]
    je .out                          ; this triple already has an XF
.fnext:
    inc di
    dec cx
    jnz .find
.add:
    mov di, [sh_nxfp]
    cmp di, SH_XFP_CAP
    jae .out                         ; full: this cell keeps its plain XF
    mov [sh_xfp_fmt + di], dl
    mov [sh_xfp_bord + di], al
    mov [sh_xfp_nf + di], ah
    inc word [sh_nxfp]
.out:
    pop di
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_biff_ixfe - which XF this cell's record should name.
; in: sh_wrec_col/sh_wrec_row/sh_wrec_fmt. out: [sh_wrec_ixfe].
;
; The format byte IS the XF index for the 64 base records - that pairing is
; the whole reason there are exactly 64 - and a cell with a border instead
; names the extra XF sh_xfp_scan registered for its (format, border) pair.
; -----------------------------------------------------------------------------
sh_biff_ixfe:
    push ax
    push bx
    push cx
    push di
    mov ax, [sh_cursheet]             ; same reason as sh_xfp_scan: a WORKBOOK
    push ax                           ; write walks every sheet but the border
    mov ax, [sh_wsheet]               ; table answers for sh_cursheet alone,
    mov [sh_cursheet], ax             ; so a bordered cell on any sheet but
                                      ; the active one read back the WRONG
                                      ; cell's border - usually none, so the
                                      ; border was silently dropped (81.47.6)
    mov al, [sh_wrec_fmt]
    xor ah, ah
    mov [sh_wrec_ixfe], ax
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_bt_getw                 ; AL border, AH number format (81.55)
    or ax, ax
    jz .out
    mov bl, [sh_wrec_fmt]
    mov cx, [sh_nxfp]
    jcxz .out
    xor di, di
.find:
    cmp bl, [sh_xfp_fmt + di]
    jne .fnext
    cmp al, [sh_xfp_bord + di]
    jne .fnext
    cmp ah, [sh_xfp_nf + di]
    je .found
.fnext:
    inc di
    dec cx
    jnz .find
    jmp .out                         ; the table was full when this pair came
                                      ; up: keep the plain XF and lose the
                                      ; border, rather than name a stranger's
.found:
    add di, 64
    mov [sh_wrec_ixfe], di
.out:
    pop ax
    mov [sh_cursheet], ax
    pop di
    pop cx
    pop bx
    pop ax
    ret

sh_biff_fontsxfs:
    ; 4 FONT records (indices 0-3: normal, bold, underline, bold+underline)
    ; and 64 XF records (indices 0-63) - one per possible SH_FMT_* byte
    ; value, so a cell's own format byte IS its BIFF ixfe with no lookup
    ; table needed on either side. See the section comment above for why
    ; this pairing is safe and the honesty scope around it.
    mov word [sh_wrow], 0            ; reused as the font index, 0..3
.ffontloop:
    mov ax, [sh_wrow]
    cmp ax, 4
    jae .ffontsdone
    mov ax, 0x0231                   ; FONT (BIFF3/4)
    call sh_biffw
    mov ax, 11                       ; height+options+palette(6) + len(1) +
    call sh_biffw                    ; "Helv"(4)
    mov ax, 200                      ; height: 10pt in twips
    call sh_biffw
    mov bx, [sh_wrow]
    xor ax, ax
    test bl, 1
    jz .fnobold
    or ax, 0x0001                    ; bit0: bold
.fnobold:
    test bl, 2
    jz .fnounder
    or ax, 0x0004                    ; bit2: underlined
.fnounder:
    call sh_biffw
    xor ax, ax                       ; palette index (default)
    call sh_biffw
    mov al, 4
    call sh_stgputb                   ; name length prefix
    mov si, sh_s_biff_fontname
    call sh_stgput                   ; the raw bytes, no NUL (BIFF strings
                                      ; are length-prefixed, not C strings)
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    jmp .ffontloop
.ffontsdone:
    ; THE 21 FORMAT RECORDS, in Excel's own order (81.55). An XF names its
    ; number format by POSITION in this list, and none was written: a reader
    ; had to assume Excel's built-in list, which is what Excel's own files
    ; carry in full, so they are written in full now.
    xor bx, bx
.ffmt:
    cmp bx, SH_NF_N
    jae .ffmtdone
    push bx
    shl bx, 1
    mov si, [sh_nf_codes + bx]       ; the package's data: DS reads it
    pop bx
    xor cx, cx
.fflen:
    push si
    add si, cx
    cmp byte [si], 0
    pop si
    je .ffhave
    inc cx
    jmp short .fflen
.ffhave:
    mov ax, 0x001E                   ; FORMAT, BIFF3: a length byte and the
    cmp byte [sh_wb_xf4], 0          ; code - BIFF4's 041EH puts its own
    je .ffop3                        ; index word first
    mov ax, 0x041E
.ffop3:
    call sh_biffw
    mov ax, cx
    inc ax
    cmp byte [sh_wb_xf4], 0
    je .ffl3
    add ax, 2
.ffl3:
    call sh_biffw
    cmp byte [sh_wb_xf4], 0
    je .ffbody
    mov ax, bx
    call sh_biffw
.ffbody:
    mov al, cl
    call sh_stgputb
    call sh_stgput                   ; the code, without its NUL
    inc bx
    jmp .ffmt
.ffmtdone:
    mov word [sh_wrow], 0            ; reused as the XF index
.fxfloop:
    mov si, [sh_wrow]
    mov ax, 64
    add ax, [sh_nxfp]                ; the 64 base records, then one per
    cmp si, ax                       ; (format, border) pair sh_xfp_scan found
    jae .fxfsdone
    ; --- which format byte and which border byte this XF stands for --------
    mov byte [sh_xfw_bord], 0
    mov byte [sh_xfw_nf], 0
    mov ax, si
    cmp si, 64
    jb .xfbase                       ; 0..63 ARE the format byte, which is the
    sub ax, 64                       ; whole reason there are exactly 64
    push bx
    mov bx, ax
    mov al, [sh_xfp_nf + bx]
    mov [sh_xfw_nf], al
    mov al, [sh_xfp_bord + bx]
    mov [sh_xfw_bord], al
    mov al, [sh_xfp_fmt + bx]
    xor ah, ah
    pop bx
.xfbase:
    mov [sh_xfw_fmt], ax
    mov al, 1                        ; XF_TYPE_PROT bit 0 = LOCKED, which is
    test byte [sh_xfw_bord], SH_PROT_UNLOCK  ; Excel's default and now this
    jz .xflocked                     ; app's. Every XF this writer emitted
    xor al, al                       ; before 81.47 left these bits clear, so
.xflocked:                           ; a file it wrote claimed every cell was
    test byte [sh_xfw_bord], SH_PROT_HIDDEN  ; UNLOCKED - the opposite of what
    jz .xfnothid                     ; a new sheet means
    or al, 2
.xfnothid:
    mov [sh_xfw_prot], al            ; banked, because sh_biffw sits between
    mov ax, 0x0243                   ; XF - or BIFF4's own number and body
    cmp byte [sh_wb_xf4], 0          ; layout, which differ (docs/BIFF-NOTES.md
    je .xfop3                        ; tabulates the two side by side)
    mov ax, 0x0443
.xfop3:                              ; XF (BIFF3). Same twelve bytes as the
                                      ; BIFF4 record in the fields this uses -
                                      ; font index, format index, attributes,
                                      ; alignment, area, border - which is why
                                      ; the body below did not have to change
                                      ; with the opcode. BIFF4's additions to
                                      ; that record (orientation, notably) sit
                                      ; in bits this never sets.
    call sh_biffw
    mov ax, 12
    call sh_biffw
    mov ax, [sh_xfw_fmt]
    and ax, 3                        ; al = font index (bits0-1 of the
                                      ; format byte: bold, underline)
    mov bx, [sh_xfw_fmt]
    mov cl, 4
    shr bx, cl
    and bx, 3                        ; bx = our number-format code
    mov ah, [sh_biff_numfmt_tab + bx] ; ah = real BIFF built-in format id
    cmp byte [sh_xfw_nf], 0          ; ...or the border table's (81.55)
    je .xfnf
    mov ah, [sh_xfw_nf]
    dec ah
.xfnf:
    call sh_biffw                    ; offset0-1: font idx, format idx
    ; THE TWO MIDDLE WORDS ARE SWAPPED BETWEEN THE VERSIONS, and that is the
    ; whole of the layout difference this record's used fields feel:
    ;
    ;   BIFF3 (0243H)                    BIFF4 (0443H)
    ;     +2  XF_TYPE_PROT      (1)        +2  type/prot + parent   (2)
    ;     +3  XF_USED_ATTRIB    (1)        +4  align/vert/orient    (1)
    ;     +4  align + parent    (2)        +5  XF_USED_ATTRIB       (1)
    ;
    ; So BIFF3 writes FC00H then align|FFF0H, and BIFF4 writes FFF0H then
    ; align|FC00H. FCH means "override every inherited attribute", which is the
    ; honest value when no style XF is written, and FFFH is the documented
    ; "no parent" for the same reason.
    mov ax, [sh_xfw_fmt]             ; the alignment code, bits 2-3 of the
    mov cl, 2                        ; format byte - it matches XF_HOR_ALIGN
    shr ax, cl                       ; 0-3 (General/Left/Center/Right)
    and ax, 3                        ; directly, with no translation
    mov [sh_wb_align], ax
    cmp byte [sh_wb_xf4], 0
    jne .xf4body
    mov ax, 0xFC00                   ; BIFF3: type/prot, then used-attrib
    or al, [sh_xfw_prot]             ; ...with XF_TYPE_PROT's low bits (81.47)
    call sh_biffw
    mov ax, [sh_wb_align]
    or ax, 0xFFF0
    call sh_biffw
    jmp .xfmid
.xf4body:
    mov ax, 0xFFF0                   ; BIFF4: type/prot + parent, then the
    or al, [sh_xfw_prot]             ; align byte with used-attrib above it -
    call sh_biffw                    ; XF_TYPE_PROT is the low 3 bits of this
    mov ax, [sh_wb_align]            ; word too, and 0xFFF0 leaves them clear
    or ax, 0xFC00
    call sh_biffw
.xfmid:
    ; --- XF_AREA_34: the Shade bit, as a background pattern ---------------
    ; Pattern 02H with pattern colour 0 (black) and background 1 (white).
    ; 2.5.12's own table of pattern samples is a set of IMAGES in the PDF and
    ; could not be read, so "02H is 50% grey" is convention rather than
    ; something checked here - what IS checked is the bit layout (5-0 pattern,
    ; 10-6 pattern colour, 15-11 background), and the round trip depends only
    ; on the pattern being non-zero. 01H is avoided deliberately: that one IS
    ; documented, as SOLID, and solid black is a black box where this app
    ; draws a dither.
    xor ax, ax
    test byte [sh_xfw_bord], SH_BORD_SHADE
    jz .noarea
    mov ax, 0x0802 | 0x00            ; pattern 2, black on white
.noarea:
    call sh_biffw
    ; --- XF_BORDER_34, four line styles at bits 2-0 / 10-8 / 18-16 / 26-24 -
    ; Style 1 is "thin" (2.5.11), which is what this app draws; the five-bit
    ; colour fields above each style stay 0, and 0 in the default palette is
    ; black.
    xor ax, ax
    test byte [sh_xfw_bord], SH_BORD_TOP
    jz .nbtop
    or ax, 0x0001
.nbtop:
    test byte [sh_xfw_bord], SH_BORD_LEFT
    jz .nbleft
    or ax, 0x0100
.nbleft:
    call sh_biffw                    ; low word: top, then left
    xor ax, ax
    test byte [sh_xfw_bord], SH_BORD_BOTTOM
    jz .nbbot
    or ax, 0x0001
.nbbot:
    test byte [sh_xfw_bord], SH_BORD_RIGHT
    jz .nbright
    or ax, 0x0100
.nbright:
    call sh_biffw                    ; high word: bottom, then right
    mov ax, si
    inc ax
    mov [sh_wrow], ax
    jmp .fxfloop
.fxfsdone:

    ret

; =============================================================================
; THE BIFF4 WORKBOOK - the only way this app can save more than one sheet.
;
; SYLK has no notion of a sheet and DIF is a single table, so for those two the
; loss is the format's and all this app can do is say so. BIFF3 is single-sheet
; too: its stream is one BOF...EOF pair. BIFF4 is the first version with a
; workbook, and its shape is (excelfileformat 4.1.2):
;
;     BOF          dt = 0100H, workbook globals
;     FONT x4, XF x64
;     SHEETSOFFSET stream position of the first SHEETHDR
;     SHEETHDR     byte length of the substream, and the sheet's name
;       BOF        dt = 0010H, worksheet
;       cells
;       EOF
;     SHEETHDR ... BOF ... EOF        (once per sheet)
;     EOF          the outer one
;
; WRITTEN ONLY WHEN IT IS NEEDED. A reader is backward compatible and not
; forward compatible, so a BIFF3 file reaches strictly more programs - which is
; why the single-sheet case still emits one and this path exists beside it
; rather than replacing it. A workbook that will not open in a BIFF3-only
; reader is still better than three sheets that were never written at all.
;
; THE SUBSTREAM LENGTH IS BACKPATCHED. SHEETHDR carries the byte length of the
; substream that FOLLOWS it, which is not known until that substream is built.
; The whole file is assembled in the staging segment before a single byte
; reaches the disk, so the header's offset is remembered and the length written
; into it afterwards - which is why this is easy here and would not be if the
; writer streamed.
;
; XF IS 0443H HERE, NOT 0243H, AND ITS BODY IS LAID OUT DIFFERENTLY - see
; docs/BIFF-NOTES.md, which tabulates both. FONT keeps 0231H in both versions.
; =============================================================================
sh_biff_workbook:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov es, [sh_stgseg]
    xor di, di
    mov byte [sh_trunc], 0
    call sh_sheets_used
    mov [sh_wb_map], bx               ; which sheets to write

    mov ax, 0x0409                    ; BOF, BIFF4
    call sh_biffw
    mov ax, 6
    call sh_biffw
    mov ax, 0x0400                    ; vers = BIFF4
    call sh_biffw
    mov ax, 0x0100                    ; dt = workbook globals
    call sh_biffw
    xor ax, ax
    call sh_biffw

    mov byte [sh_wb_xf4], 1           ; the globals' FONT/XF block, in BIFF4
    call sh_xfp_scan                  ; opcodes and layout - and the pairs
    call sh_biff_fontsxfs             ; first, as in the BIFF3 path (81.47)
    call sh_biff_names                ; ...and the names, which are instance-
                                      ; wide and so belong to the GLOBALS
                                      ; substream, not to any one sheet

    mov ax, 0x008E                    ; SHEETSOFFSET
    call sh_biffw
    mov ax, 4
    call sh_biffw
    mov ax, di                        ; the first SHEETHDR begins right after
    add ax, 4                         ; this record's own four bytes
    call sh_biffw
    xor ax, ax
    call sh_biffw

    mov word [sh_wb_i], 0
.sheet:
    mov ax, [sh_wb_i]
    cmp ax, SH_SHEETS
    jae .alldone
    mov cx, ax                        ; is this one used?
    mov ax, 1
    jcxz .nosh
.shl1:
    shl ax, 1
    loop .shl1
.nosh:
    test [sh_wb_map], ax
    jz .next
    cmp byte [sh_trunc], 0
    jne .next
    mov ax, di                        ; SHEETHDR 15, BOF 10, this sheet's
    add ax, 15 + 10 + 4 + 4           ; EOF and the workbook's: none of them
    cmp ax, SH_STAGE_MAX              ; is checked as it goes out
    jbe .shroom
    mov byte [sh_trunc], 1            ; no room for this sheet: say so
    jmp .next
.shroom:

    mov ax, 0x008F                    ; SHEETHDR
    call sh_biffw
    mov ax, 11                        ; 4 length + 1 count + "SheetN"(6)
    call sh_biffw
    mov [sh_wb_lenat], di             ; ...backpatched once the substream is
    xor ax, ax                        ; built, because SHEETHDR carries the
    call sh_biffw                     ; size of what FOLLOWS it
    call sh_biffw
    mov al, 6
    call sh_stgputb
    mov si, sh_s_sheetnm              ; "Sheet"
.nm:
    mov al, [si]
    or al, al
    jz .nmdone
    call sh_stgputb
    inc si
    jmp .nm
.nmdone:
    mov ax, [sh_wb_i]
    add al, '1'
    call sh_stgputb

    mov [sh_wb_subat], di             ; the substream starts here
    mov ax, 0x0409                    ; BOF, worksheet
    call sh_biffw
    mov ax, 6
    call sh_biffw
    mov ax, 0x0400
    call sh_biffw
    call sh_biff_dt                   ; dt = worksheet, or macro sheet
    call sh_biffw
    xor ax, ax
    call sh_biffw

    mov ax, [sh_wb_i]                 ; ...its cells...
    mov [sh_wsheet], ax
    call sh_biff_cells

    mov ax, 0x000A                    ; ...and its EOF
    call sh_biffw
    xor ax, ax
    call sh_biffw

    mov ax, di                        ; backpatch the substream length
    sub ax, [sh_wb_subat]
    mov bx, [sh_wb_lenat]
    mov [es:bx], ax
    mov word [es:bx+2], 0
.next:
    inc word [sh_wb_i]
    jmp .sheet
.alldone:
    mov ax, 0x000A                    ; the workbook's own EOF
    call sh_biffw
    xor ax, ax
    call sh_biffw
    mov [sh_stagelen], di

    mov ax, [sh_stgseg]
    mov es, ax
    xor bx, bx
    mov cx, [sh_stagelen]
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_WRITE
    jc .err
    mov word [sh_msg], sh_m_saved
    mov byte [sh_modified], 0         ; the whole workbook went out: clean,
                                      ; as .single's success is (81.118)
    cmp byte [sh_trunc], 0            ; cells dropped for room must not be
    je .out                           ; reported as a plain success
    mov word [sh_msg], sh_m_trunc
    mov byte [sh_modified], 1         ; ...and a truncated file is not saved
    jmp .out
.err:
    call sh_setferr
.out:
    mov byte [sh_wb_xf4], 0
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_biff_cells - every cell record for ONE sheet, appended at ES:DI.
; in: [sh_wsheet] = which of the SH_SHEETS grids; ES = staging, DI = cursor
; out: DI advanced past what was written; [sh_trunc] set if the buffer filled
;
; Extracted from sh_dowrite_biff so a BIFF4 WORKBOOK can call it once per
; sheet (81.10.5). The BIFF3 path calls it exactly once, with sh_wsheet set to
; sh_cursheet, and emits the same bytes it always did.
; -----------------------------------------------------------------------------
sh_biff_cells:
    ; COLWIDTH FOR EVERY COLUMN NOT THE STANDARD WIDTH (81.56), before the
    ; cells, in 1/256ths of a character. The sheet is sh_wsheet's, which
    ; sh_colwidth reads through sh_cursheet - impersonated, as sh_biff_ixfe
    ; does for the border table
    mov byte [sh_trunc], 0           ; here, not after the ROWs: a COLWIDTH
    push word [sh_cursheet]          ; refused for room must survive to the
    mov ax, [sh_wsheet]              ; caller's message
    mov [sh_cursheet], ax
    xor bx, bx
.cw:
    mov ax, bx
    SHOUT sh_colwidth
    cmp ax, [sh_defch]
    je .cwn
    push ax
    mov ax, di                       ; 8 of COLWIDTH and 4 of this sheet's
    add ax, 8 + 4                    ; EOF: up to 256 of them is 2 KB, and
    cmp ax, SH_STAGE_MAX             ; staging is the whole 32 KB claim
    pop ax
    ja .cwfull
    push ax
    mov ax, 0x0024                   ; COLWIDTH: first, last, width
    call sh_biffw
    mov ax, 4
    call sh_biffw
    mov al, bl
    mov ah, bl
    call sh_biffw
    pop ax
    mov ah, al
    xor al, al
    call sh_biffw
.cwn:
    inc bx
    cmp bx, 256
    jb .cw
    jmp short .cwdone
.cwfull:
    mov byte [sh_trunc], 1
.cwdone:
    pop word [sh_cursheet]
    ; ...and a ROW for every row of it not the standard height (81.60): the
    ; row, its first and one-past-last cell column (none are claimed), the
    ; height in twips with bit 15 clear, and the flags word Excel 3 sets for
    ; a height given by hand - bit 8 always, bit 6 "not the font's height"
    push es
    mov es, [sh_noteseg]
    mov cx, [es:SH_ROWH_N]
    pop es
    mov si, SH_ROWH_OFF
.rh:
    jcxz .rhd
    mov ax, di
    add ax, 20
    cmp ax, SH_STAGE_MAX
    ja .rhd
    push es
    mov es, [sh_noteseg]
    mov ax, [es:si]
    mov bx, [es:si+2]
    pop es
    mov dx, ax
    push cx
    mov cl, SH_ROW_BITS
    shr dx, cl
    pop cx
    cmp dx, [sh_wsheet]
    jne .rhn
    and ax, SH_ROW_MASK
    push ax
    mov ax, 0x0208                   ; ROW (BIFF3/4)
    call sh_biffw
    mov ax, 16
    call sh_biffw
    pop ax
    call sh_biffw                    ; the row
    xor ax, ax
    call sh_biffw                    ; no cell columns claimed
    call sh_biffw
    mov ax, bx
    call sh_biffw                    ; the height, custom
    xor ax, ax
    call sh_biffw                    ; not used
    call sh_biffw                    ; BIFF3/4's offset to its first cell
    mov ax, 0x0140
    call sh_biffw
    mov ax, 0x000F                   ; the XF, unused with bit 7 clear
    call sh_biffw
.rhn:
    add si, SH_ROWH_REC
    dec cx
    jmp short .rh
.rhd:
    mov word [sh_wrow], 0            ; reused here as the record index
.rec:
    mov bx, [sh_wrow]
    cmp bx, [sh_ncells]
    jae .cdone
    cmp byte [sh_trunc], 0
    jne .cdone
    mov ax, di
    add ax, 18                       ; the NUMBER record - opcode+len(4) +
                                      ; row+col+xf(6) + double(8), the largest
                                      ; fixed-size cell record (RK is 14,
                                      ; BOOLERR 12; LABEL and FORMULA re-check
                                      ; with their own exact sizes)
    cmp ax, SH_STAGE_MAX
    jbe .room
    mov byte [sh_trunc], 1
    jmp .cdone
.room:
    mov ax, bx
    mov cx, SH_C_SZ
    mul cx
    mov si, ax                        ; SI = this record's offset in cellseg
    push es
    mov es, [sh_cellseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow                 ; -> ax=real row, bx=this record's
                                       ; sheet (stage 2.0)
    cmp bx, [sh_wsheet]
    jne .recskip                      ; one pass writes ONE sheet: the
                                       ; current one for BIFF3, each used
                                       ; one in turn for the workbook
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]
    mov [sh_wrec_col], ax
    SHOUT sh_cellval_to_acc_si         ; the whole value, banked - the choice
    push si                           ; of record below needs all eight bytes
    push di
    mov si, sh_acc
    mov di, sh_wrec_dval
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    pop si
    mov al, [es:si+5]
    mov [sh_wrec_fmt], al
    mov al, [es:si+SH_C_TYPE]
    mov [sh_wrec_type], al            ; stage 4.5: a LABEL takes neither RK nor
    mov al, [es:si+SH_C_AUX]          ; NUMBER, and an ERROR takes neither
    mov [sh_wrec_aux], al             ; either - see .aserr
    mov ax, [es:si+SH_C_FOFF]
    mov [sh_wrec_toff], ax            ; what sh_biff_formula tokenises...
    mov [sh_wrec_roff], ax            ; ...and the TEXT a LABEL or a STRING
    test byte [es:si+4], 1            ; record carries. A FORMULA THAT RETURNED
    jz .toffok2                          ; TEXT keeps its result in SH_C_VAL,
    cmp byte [es:si+SH_C_TYPE], SH_T_TEXT  ; because FOFF is already holding
    jne .toffok2                         ; the formula's own text (81.22.1).
    mov ax, [es:si+SH_C_VAL]          ; This used to REPLACE toff, which was
    mov [sh_wrec_roff], ax            ; right while such a cell could only
.toffok2:                             ; become a LABEL (81.10.11)
    mov al, [es:si+4]                 ; ...and a FORMULA cell may take a real
    and al, 1                         ; FORMULA record, if its text is one this
    mov [sh_wrec_hasf], al            ; writer can tokenise
    pop es                            ; ES = stgseg again
    call sh_biff_ixfe                 ; which XF this cell names (81.47)

    ; 81.114.10: A RESULT CELL GOES OUT AS A FORMULA, whose whole token
    ; array is one tTbl, with its stored number as the cached result. That is
    ; Excel's own shape, and it is why a reader that knows nothing about
    ; tables still shows the right figures.
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    call sh_tbl_atcell
    jnc .nottbl
    cmp byte [sh_tbl_isres], 0
    je .nottbl                        ; inside the RANGE but not a result:
                                      ; the user's own formula or input
                                      ; value, written normally below - and
                                      ; the DATATABLE may follow it there
    call sh_biff_ttbl
    jc .nottbl                        ; no room: out as a plain number, the
    call sh_biff_dtafter              ; same scope limit every writer here
    jmp .recnext                      ; takes when staging fills
.nottbl:
    cmp byte [sh_wrec_hasf], 0
    je .notformula
    cmp byte [sh_wrec_type], SH_T_TEXT ; A TEXT RESULT IS A FORMULA TOO now
    jne .fnottext                      ; (81.10.11): the FORMULA record says
    call sh_biff_rlen                  ; "string" and a STRING record carries
    mov ax, di                         ; it - so there must be room for both,
    add ax, cx                         ; or it goes out as the value alone
    add ax, 6 + 22 + SH_RPN_MAX
    cmp ax, SH_STAGE_MAX
    jbe .fnottext
    jmp .aslabel
.fnottext:
    call sh_biff_formula              ; CF=0 = it wrote the record
    jc .notformula
    cmp byte [sh_wrec_type], SH_T_TEXT
    jne .fdone
    call sh_biff_wstring              ; ...and the string it promised
.fdone:
    ; 81.114.10: and the FIRST formula record of a table's range is usually
    ; THIS one - the user's own formula in the top row - not a result cell,
    ; which is where the format says the DATATABLE goes
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    call sh_tbl_atcell
    jnc .recnext
    call sh_biff_dtafter
    jmp .recnext
.notformula:
    cmp byte [sh_wrec_type], SH_T_TEXT
    jne .notlabel
    jmp .aslabel
.notlabel:
    cmp byte [sh_wrec_type], SH_T_BOOL ; a LOGICAL is a BOOLERR too, with the
    je .aserr                          ; flag clear (81.51)
    cmp byte [sh_wrec_type], SH_T_ERR  ; an error whose formula this writer
    je .aserr                          ; could not tokenise still has to go out
                                        ; AS AN ERROR: the number underneath one
                                        ; is zero, and a file saying 0 where the
                                        ; sheet said #DIV/0! is worse than a
                                        ; file that lost the formula

    ; --- which record? -------------------------------------------------------
    ; AN EXACT IN-RANGE INTEGER STILL GOES OUT AS RK, byte for byte as before,
    ; so every file this app has already written is unchanged and a reader that
    ; only knows the old subtype still reads those cells. Anything else - a
    ; fraction, or a magnitude past a signed word - needs the NUMBER record,
    ; which carries the IEEE-754 double verbatim.
    push si
    mov si, sh_wrec_dval
    SHOUT fp_unpack_a
    pop si
    SHOUT fp_a2i                       ; CF=1: no signed word can hold it
    jc .asnumber
    mov [sh_wrec_val], ax
    SHOUT fp_i2a                       ; round-trip it and see if anything was
    push si                           ; lost - 3.5 truncates to 3, and 3 is
    mov si, sh_wrec_dval              ; not the value we were asked to write
    SHOUT fp_unpack_b
    pop si
    SHOUT fp_cmpab
    jne .asnumber

    mov ax, 0x027E                    ; RK cell record
    call sh_biffw
    mov ax, 10
    call sh_biffw
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]            ; 81.47: the format byte UNLESS this
                                      ; cell also has a border
    call sh_biffw
    mov ax, [sh_wrec_val]
    call sh_rkenc                     ; -> DX:AX = packed RK value
    call sh_biffw                     ; low word
    mov ax, dx
    call sh_biffw                     ; high word
    jmp .recnext
.asnumber:
    mov ax, 0x0203                    ; NUMBER: row, col, xf, then an 8-byte
    call sh_biffw                     ; IEEE-754 double, little-endian - the
    mov ax, 14                        ; same layout the working form packs to,
    call sh_biffw                     ; so it goes out with no conversion
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]            ; 81.47: the format byte UNLESS this
                                      ; cell also has a border
    call sh_biffw
    mov ax, [sh_wrec_dval]
    call sh_biffw
    mov ax, [sh_wrec_dval+2]
    call sh_biffw
    mov ax, [sh_wrec_dval+4]
    call sh_biffw
    mov ax, [sh_wrec_dval+6]
    call sh_biffw
    jmp .recnext
.aserr:
    ; BOOLERR, 0205H: the row/col/xf head every cell record shares, then the
    ; value byte and a flag saying whether it is a BOOLEAN or an ERROR. The
    ; code is TRANSLATED - see sh_biff_e2b. This comment used to say it
    ; travelled with no translation because SH_C_AUX already held "Excel's own
    ; ERROR.TYPE number", and that is true of the number and false of the
    ; record: BIFF has a second numbering for the same seven errors.
    mov ax, 0x0205
    call sh_biffw
    mov ax, 8
    call sh_biffw
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]            ; 81.47: the format byte UNLESS this
                                      ; cell also has a border
    call sh_biffw
    cmp byte [sh_wrec_type], SH_T_BOOL
    je .bebool
    mov al, [sh_wrec_aux]
    call sh_biff_e2b
    mov ah, 1                          ; fError
    jmp short .beput
.bebool:
    xor ax, ax                         ; the value 0 or 1, fError clear
    test word [sh_wrec_dval+6], 0x7FFF
    jz .beput
    inc ax
.beput:
    call sh_biffw                      ; AL then AH: the two bytes in order
    jmp .recnext
.aslabel:
    ; LABEL, 0204H in BIFF3 - and NOT 0004H, which is BIFF2's. The body is the
    ; same row/col/xf head RK and NUMBER use, then a SIXTEEN-BIT length and the
    ; bytes. BIFF2's LABEL has a one-byte length and a three-byte cell
    ; attribute where the xf index goes, so a file mixing the two conventions
    ; desynchronises the moment a reader trusts the length field.
    call sh_biff_rlen                  ; measure it first: the length goes in
    mov [sh_wrec_len], cx              ; the record BEFORE the bytes do
    mov ax, di                         ; and only now check for room, because
    add ax, cx                         ; the length is what decides how much
    add ax, 12
    cmp ax, SH_STAGE_MAX
    jbe .lroom
    mov byte [sh_trunc], 1
    jmp .recnext
.lroom:
    mov ax, 0x0204                     ; LABEL
    call sh_biffw
    mov ax, [sh_wrec_len]
    add ax, 8                          ; row+col+xf+cch = 8, then the bytes
    call sh_biffw
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]            ; 81.47: the format byte UNLESS this
                                      ; cell also has a border
    call sh_biffw
    mov ax, [sh_wrec_len]
    call sh_biffw
    mov si, [sh_wrec_roff]
    mov cx, [sh_wrec_len]
    jcxz .recnext
.lput:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    inc si
    call sh_stgputb
    dec cx
    jnz .lput
    jmp .recnext
.recskip:
    pop es
.recnext:
    mov ax, [sh_wrow]
    inc ax
    mov [sh_wrow], ax
    jmp .rec
.cdone:
    ; --- THE FORMATTED OR BORDERED EMPTY CELLS (81.77) ---------------------
    ; They have NO CELL RECORD, so the walk above never reached them: their
    ; format is the border table's own sixth byte (81.55) and that table is
    ; the only place they exist. BIFF says such a cell with a BLANK record -
    ; row, column, XF and nothing else - and without one, applying a format
    ; to an empty cell and saving lost it with no message.
    push word [sh_cursheet]           ; sh_findcell answers for sh_cursheet,
    mov ax, [sh_wsheet]               ; and this pass is writing sh_wsheet
    mov [sh_cursheet], ax
    mov cx, [sh_nbord]
    jcxz .btdone
    xor si, si
.bt:
    mov ax, di
    add ax, 10                        ; BLANK is 4 of header and 6 of body
    cmp ax, SH_STAGE_MAX
    jbe .btroom                       ; out of staging: stop, as the cells do,
    mov byte [sh_trunc], 1            ; and SAY so, as they do - a dropped
    jmp .btdone                       ; formatted cell is not a plain Saved
.btroom:
    push cx
    push si
    mov es, [sh_bordseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow                ; -> AX = row, BX = its sheet
    cmp bx, [sh_wsheet]
    jne .btnext                       ; one pass writes ONE sheet
    mov [sh_wrec_row], ax
    mov bx, ax
    mov es, [sh_bordseg]
    mov ax, [es:si+2]
    mov [sh_wrec_col], ax
    push di                           ; DI IS THE STAGING WRITE POINTER, and
    SHOUT sh_findcell                 ; sh_findcell does not preserve DI -
    pop di                            ; a pop leaves CF alone, so the test
    jc .btnext                        ; below still reads the search's answer
    mov es, [sh_bordseg]
    mov ax, [es:si+4]                 ; AL border, AH number format
    or ax, ax
    jz .btnext                        ; an empty entry: nothing to carry
    mov byte [sh_wrec_fmt], 0         ; no cell record, so no format byte
    call sh_biff_ixfe
    mov es, [sh_stgseg]
    mov ax, 0x0201                    ; BLANK (BIFF3)
    call sh_biffw
    mov ax, 6
    call sh_biffw
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]
    call sh_biffw
.btnext:
    pop si
    pop cx
    add si, SH_BT_SZ
    dec cx
    jnz .bt
.btdone:
    ; --- AND THE NOTES (81.119) --------------------------------------------
    ; A note lives only in the note table - packed row/sheet, col, and the
    ; text's offset in the SHARED formula arena - and BIFF's NOTE (001CH) is
    ; row, col, length, the bytes. Without this a note made here was lost on
    ; every save in every format, while main's Sheet kept it; this is main's
    ; sh_biff_extras' second half, with our six-byte table and SHOUT'd
    ; sh_unpackrow.
    mov cx, [sh_nnote]
    or cx, cx                         ; NOT jcxz: it is short-only on an 8086
    jnz .ntgo                         ; and .ntdone is past the note loop
    jmp .ntdone
.ntgo:
    xor si, si
.nt:
    push cx
    push si
    mov es, [sh_noteseg]
    mov ax, [es:si]
    SHOUT sh_unpackrow                ; -> AX = row, BX = its sheet
    cmp bx, [sh_wsheet]
    jne .ntnext                       ; one pass writes ONE sheet
    mov [sh_wrec_row], ax
    mov es, [sh_noteseg]
    mov ax, [es:si+2]
    mov [sh_wrec_col], ax
    mov dx, [es:si+4]                 ; DX = the text's arena offset, kept
                                      ; across the length walk below
    mov es, [sh_txtseg]               ; ...and its length, capped the way the
    mov si, dx                        ; dialog caps what it will take
    xor cx, cx
.ntlen:
    cmp byte [es:si], 0
    je .nthave
    inc si
    inc cx
    cmp cx, SH_NOTEMAX
    jb .ntlen
.nthave:
    mov ax, di
    add ax, cx
    add ax, 10                        ; 4 of header and 6 of body, then text
    cmp ax, SH_STAGE_MAX
    jbe .ntroom
    mov byte [sh_trunc], 1            ; out of staging: say so, as the cells
    pop si                            ; and the borders do
    pop cx
    jmp short .ntdone
.ntroom:
    mov es, [sh_stgseg]
    mov ax, 0x001C                    ; NOTE (BIFF3)
    call sh_biffw
    mov ax, cx
    add ax, 6
    call sh_biffw
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, cx
    call sh_biffw
    jcxz .ntnext
    mov si, dx
.ntput:
    push es
    mov es, [sh_txtseg]               ; the arena holds the text and the
    mov al, [es:si]                   ; STAGE is where it goes: two segments,
    pop es                            ; one byte at a time
    inc si
    call sh_stgputb
    loop .ntput
.ntnext:
    pop si
    pop cx
    add si, SH_NOTE_REC
    dec cx
    jnz .nt
.ntdone:
    pop word [sh_cursheet]
    mov es, [sh_stgseg]               ; ES BACK TO THE STAGING SEGMENT. This
                                      ; routine's contract is "appended at
                                      ; ES:DI", and the walk above leaves ES
                                      ; on the BORDER TABLE on every path that
                                      ; writes nothing. Without this the
                                      ; caller's next records - the sheet's
                                      ; own EOF among them - went into
                                      ; sh_bordseg: a two-sheet save came back
                                      ; as one sheet, and the border table was
                                      ; being overwritten as well
    ret

; sh_biff_rlen - CX = the length of the text at [sh_wrec_roff] in the arena,
; at most 255: BIFF3's own ceiling, and the arena cannot hold longer anyway.
; Preserves everything else.
sh_biff_rlen:
    push si
    push es
    mov es, [sh_txtseg]
    mov si, [sh_wrec_roff]
    xor cx, cx
.l:
    cmp byte [es:si], 0
    je .out
    inc si
    inc cx
    cmp cx, 255
    jb .l
.out:
    pop es
    pop si
    ret

; sh_biff_wstring - the STRING record (0207H, BIFF3-5: a 16-bit length and
; the bytes) that follows a FORMULA whose result is text (81.10.11).
; sh_biff_cells has already checked there is room for it.
sh_biff_wstring:
    push ax
    push cx
    push si
    call sh_biff_rlen
    mov ax, 0x0207
    call sh_biffw
    mov ax, cx
    add ax, 2
    call sh_biffw
    mov ax, cx
    call sh_biffw
    mov si, [sh_wrec_roff]
    jcxz .out
.put:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    inc si
    call sh_stgputb
    dec cx
    jnz .put
.out:
    pop si
    pop cx
    pop ax
    ret

sh_biff_formula:
    push ax
    push bx
    push cx
    push dx
    push si
    push es
    ; DI IS NOT SAVED, AND MUST NOT BE. It is the staging write cursor this
    ; whole writer advances through the file, and sh_biffw both reads and
    ; advances it - so a record emitted here has to leave it moved on, exactly
    ; as the RK and NUMBER paths do. The first version pushed it and then used
    ; it as the text-copy destination, which put every FORMULA record into the
    ; staging segment at sh_rwsrc's offset - written, past the cursor, and
    ; invisible to the file the writer then saved. BX carries the copy instead.
    mov es, [sh_txtseg]               ; the formula text out of the arena into
    mov si, [sh_wrec_toff]            ; DS, where the emitter reads
    mov bx, sh_rwsrc
    mov cx, SH_EDITMAX
.copy:
    mov al, [es:si]
    mov [bx], al
    or al, al
    jz .copied
    inc si
    inc bx
    dec cx
    jnz .copy
    mov byte [bx], 0
.copied:
    mov es, [sh_stgseg]               ; AND BACK TO THE STAGING SEGMENT, which
                                      ; is where sh_biffw writes. The first
                                      ; version left ES pointing at DS through
                                      ; the whole record emit, so every word of
                                      ; every FORMULA record went into Sheet's
                                      ; own data segment instead of the file -
                                      ; no crash, no record, and a corrupted
                                      ; variable wherever DI happened to be.
    mov si, sh_rwsrc
    call sh_rpn_emit                  ; CX = token bytes, or CF=1
    jc .no
    mov [sh_wrec_len], cx
    mov ax, di                        ; room? header + body + the tokens
    add ax, cx
    add ax, 22
    cmp ax, SH_STAGE_MAX
    ja .no
    mov ax, 0x0206                    ; FORMULA - 0206H in BIFF3 and 0406H in
    cmp byte [sh_wb_xf4], 0           ; BIFF4, and a BIFF4 workbook must carry
    je .op3                           ; the BIFF4 number or its own reader
    mov ax, 0x0406                    ; skips the record by length and loses
.op3:                                 ; the cell
    call sh_biffw
    mov ax, [sh_wrec_len]
    add ax, 18                        ; row+col+xf+result(8)+flags+cce = 18
    call sh_biffw
    mov ax, [sh_wrec_row]
    call sh_biffw
    mov ax, [sh_wrec_col]
    call sh_biffw
    mov ax, [sh_wrec_ixfe]            ; 81.47: the format byte UNLESS this
                                      ; cell also has a border
    call sh_biffw
    cmp byte [sh_wrec_type], SH_T_TEXT ; a string: byte 0 = 0, top word all
    je .strresult                      ; ones, the text in a STRING record next
    cmp byte [sh_wrec_type], SH_T_BOOL ; a LOGICAL: byte 0 = 1, byte 2 the
    je .boolresult                     ; value (81.51)
    cmp byte [sh_wrec_type], SH_T_ERR ; BIFF's own encoding for a cached result
    je .errresult                     ; that is not a number: the top word all
    mov ax, [sh_wrec_dval]            ; ones, byte 0 naming the kind and byte 2
    call sh_biffw                     ; carrying the value. Without this the
    mov ax, [sh_wrec_dval+2]          ; result field says 0.0, and a reader
    call sh_biffw                     ; that trusts it - including this app's,
    mov ax, [sh_wrec_dval+4]          ; which reads the result and skips the
    call sh_biffw                     ; tokens - turns #DIV/0! back into a
    mov ax, [sh_wrec_dval+6]          ; perfectly ordinary zero
    call sh_biffw
    jmp .resdone
.strresult:
    xor ax, ax
    call sh_biffw
    call sh_biffw
    call sh_biffw
    mov ax, 0xFFFF
    call sh_biffw
    jmp .resdone
.boolresult:
    mov ax, 1                         ; byte 0 = 1: a boolean
    call sh_biffw
    xor ax, ax
    test word [sh_wrec_dval+6], 0x7FFF
    jz .brv
    inc ax
.brv:
    call sh_biffw
    jmp short .restail
.errresult:
    mov ax, 2                         ; byte 0 = 2: an error code
    call sh_biffw
    mov al, [sh_wrec_aux]             ; byte 2 = which one, IN THE FILE'S
    call sh_biff_e2b                  ; NUMBERING. This wrote ERROR.TYPE's -
    xor ah, ah                        ; #DIV/0! as 02H, not 07H - and the reader
    call sh_biffw                     ; read it back the same way, so SHEET's
                                      ; own files never showed it (81.10.11)
.restail:
    xor ax, ax
    call sh_biffw
    mov ax, 0xFFFF
    call sh_biffw
.resdone:
    mov ax, [sh_rpn_vol]              ; option flags: bit 0 "Recalculate
    call sh_biffw                     ; always", raised by sh_rpn_func for a
                                      ; volatile function anywhere in the array
    mov ax, [sh_wrec_len]             ; cce, the token array's own length
    call sh_biffw
    mov si, sh_rpn_buf
    mov cx, [sh_wrec_len]
    jcxz .done
.put:
    mov al, [si]
    call sh_stgputb
    inc si
    dec cx
    jnz .put
.done:
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    clc
    ret
.no:
    pop es
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    stc
    ret


; =============================================================================
; sh_biff_dcrpn - a FORMULA record's tokens back into formula TEXT
; (SPEC.md 81.10.10).
; in:  ES:SI = the record's body, DX = its length, [sh_dc_ver] = 2 for BIFF3
;      and 4 for BIFF4 (the high byte of the record's own opcode)
; out: CF=0 and sh_rwsrc = the text, NUL-terminated, without its '='.
;      CF=1 when any token is outside what this reads - and the caller keeps
;      the cached value, which is what this reader did with EVERY formula
;      before: an unreadable token costs a formula its liveness, never its
;      number. Preserves every register.
;
; tools/os88sheetfmt.py's decode_rpn is the reference and this follows it
; token for token, down to what it refuses: tPercent (SHEET's parser has no
; %), names, missing arguments, CHOOSE's jump table (two sources disagree on
; its length), array and shared formulas. What it reads is everything
; sh_rpn_emit writes, plus what Excel adds around the same expressions -
; strings, TRUE/FALSE, error constants, and the tAttr family of IF/SUM
; control tokens, which carry no text of their own.
;
; THE TEXT IS BUILT IN PLACE, not on a stack of strings. RPN pushes operands
; in order, so the fragments on the stack are ADJACENT in the buffer and an
; operator only has to INSERT its characters between or around them: a
; binary op at its right operand's start, a unary minus or '(' at the top
; fragment's start, a call's commas at each argument's start and its name at
; the first. Every insert lands at or after the start of the lowest fragment
; being merged, and all of those merge into one at once, so no start this
; keeps is ever made stale by one. The stack holds starts and nothing else.
;
; RPN with explicit tParen needs no precedence of its own: a parenthesis the
; author wrote is a token, and one they did not write the grammar that made
; the tokens did not need.
;
; The buffer and the stack are the WRITER's scratch - sh_rwsrc and
; sh_rpn_buf. Other readers borrow them too; none runs between this and the
; sh_setformula that copies the text out, which is the one window that
; matters.
; =============================================================================
SH_DC_DEPTH  equ 16
sh_dc_stk    equ sh_rpn_buf                  ; SH_DC_DEPTH starts, a byte each
sh_dc_dbl    equ sh_rpn_buf + SH_DC_DEPTH    ; a tNum's double, copied to DS

sh_biff_dcrpn:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov bx, 18                        ; row col xf result(8) flags cce
    cmp byte [sh_dc_ver], 0           ; ...BIFF2's, once .b2cell has moved it
    jne .b34                          ; up a byte, with ONE byte of flags and
    mov bx, 16                        ; one of cce (5.50) - 81.52
    cmp dx, bx
    jb .bail
    mov cl, [es:si+15]
    xor ch, ch
    jmp short .havecce
.b34:
    cmp dx, bx
    jb .bail
    mov cx, [es:si+16]                ; cce: the token array's length
.havecce:
    mov ax, cx
    add ax, bx
    jc .bail
    cmp ax, dx
    ja .bail
    lea di, [si+bx]
    add cx, di
    mov [sh_dc_tend], cx
    xor ax, ax
    mov [sh_dc_end], ax
    mov [sh_dc_sp], ax
    mov byte [cs:sh_dc_cept], 0       ; 81.97.4: never from a formula before
.tok:
    cmp di, [sh_dc_tend]
    jae .done
    mov al, [es:di]
    cmp al, 0x20
    jb .find0
    and al, 0x1F                      ; R, V and A classes are one token to a
    or al, 0x20                       ; reader that only wants the text
.find0:
    mov bx, sh_dc_tab
.find:
    cmp byte [cs:bx], 0               ; [cs:] - the table is the module's own
    je .bail                          ; data, and DS is the package (68.10)
    cmp al, [cs:bx]
    je .hit
    add bx, 3
    jmp short .find
.hit:
    call word [cs:bx+1]
    jnc .tok
.bail:
    stc
    jmp short .out
.done:
    cmp word [sh_dc_sp], 1            ; exactly one expression, or the array
    jne .bail                         ; was not one
    mov bx, [sh_dc_end]
    mov byte [bx+sh_rwsrc], 0
    clc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; token -> handler. Each: in AL = the token (class folded), ES:DI = it;
; out DI past it, CF=1 to refuse. 0 ends the table.
sh_dc_tab:
    db 0x03
    dw sh_dc_bin
    db 0x04
    dw sh_dc_bin
    db 0x05
    dw sh_dc_bin
    db 0x06
    dw sh_dc_bin
    db 0x07
    dw sh_dc_bin
    db 0x08
    dw sh_dc_bin
    db 0x09
    dw sh_dc_bin
    db 0x0A
    dw sh_dc_bin
    db 0x0B
    dw sh_dc_bin
    db 0x0C
    dw sh_dc_bin
    db 0x0D
    dw sh_dc_bin
    db 0x0E
    dw sh_dc_bin
    db 0x12
    dw sh_dc_uplus
    db 0x13
    dw sh_dc_neg
    db 0x15
    dw sh_dc_par
    db 0x17
    dw sh_dc_str
    db 0x19
    dw sh_dc_attr
    db 0x1C
    dw sh_dc_err
    db 0x1D
    dw sh_dc_bool
    db 0x1E
    dw sh_dc_int
    db 0x1F
    dw sh_dc_num
    db 0x21
    dw sh_dc_fn
    db 0x22
    dw sh_dc_fnv
    db 0x38                           ; 58H folded: tFuncVarCE, a command
    dw sh_dc_fnce
    db 0x24
    dw sh_dc_ref
    db 0x25
    dw sh_dc_area
    db 0

; tAdd..tNE (03H-0EH): each operator's one or two characters
sh_dc_ops:
    db '+', 0, '-', 0, '*', 0, '/', 0, '^', 0, '&', 0
    db '<', 0, '<', '=', '=', 0, '>', '=', '>', 0, '<', '>'

; --- the handlers ------------------------------------------------------------
sh_dc_bin:
    push ax
    push bx
    sub al, 3
    xor ah, ah
    shl ax, 1
    mov bx, ax
    mov ax, [cs:bx+sh_dc_ops]         ; AL the first character, AH any second
    call sh_dc_pop                    ; BX = the right operand's start
    jc .x
    cmp word [sh_dc_sp], 1            ; ...and a left one under it
    jb .bad
    or ah, ah
    jz .one
    xchg al, ah                       ; the SECOND character goes in first, so
    call sh_dc_insc                   ; the first lands in front of it
    jc .x
    xchg al, ah
.one:
    call sh_dc_insc
    jc .x
    inc di
    clc
    jmp short .x
.bad:
    stc
.x:
    pop bx
    pop ax
    ret

sh_dc_uplus:                          ; the identity: nothing to write
    inc di
    clc
    ret

sh_dc_neg:
    push ax
    push bx
    call sh_dc_top
    jc .x
    mov al, '-'
    call sh_dc_insc
    jc .x
    inc di
.x:
    pop bx
    pop ax
    ret

sh_dc_par:
    push ax
    push bx
    call sh_dc_top
    jc .x
    mov al, '('
    call sh_dc_insc
    jc .x
    mov al, ')'
    call sh_dc_app
    jc .x
    inc di
.x:
    pop bx
    pop ax
    ret

sh_dc_str:                            ; 17H len chars - quoted, '"' doubled
    push ax
    push cx
    mov cx, 2
    call sh_dc_need
    jc .x
    mov cl, [es:di+1]
    xor ch, ch
    add cx, 2
    call sh_dc_need
    jc .x
    call sh_dc_push
    jc .x
    mov al, '"'
    call sh_dc_app
    jc .x
    add di, 2
    sub cx, 2
    jz .close
.ch:
    mov al, [es:di]
    call sh_dc_app
    jc .x
    cmp al, '"'
    jne .next
    call sh_dc_app                    ; a quote in the text is two in a formula
    jc .x
.next:
    inc di
    loop .ch
.close:
    mov al, '"'
    call sh_dc_app
.x:
    pop cx
    pop ax
    ret

sh_dc_attr:                           ; 19H flags data - a WORD of data from
    push ax                           ; BIFF3, a BYTE in BIFF2 (3.10, 81.52)
    push cx
    push si
    mov cx, 4
    cmp byte [sh_dc_ver], 0
    jne .sz
    dec cx
.sz:
    call sh_dc_need
    jc .x
    mov al, [es:di+1]
    test al, 0x04                     ; CHOOSE: a jump table whose length the
    jnz .bad                          ; references do not agree on
    test al, 0x10                     ; SUM with one argument: a call with no
    jz .skip                          ; token of its own
    mov si, sh_f_sum
    mov cx, 1
    call sh_dc_call
    jc .x
.skip:                                ; volatile, IF, skip, space: no text
    add di, 4
    cmp byte [sh_dc_ver], 0
    jne .s4
    dec di
.s4:
    clc
    jmp short .x
.bad:
    stc
.x:
    pop si
    pop cx
    pop ax
    ret

sh_dc_err:                            ; 1CH code - by its name
    push ax
    push cx
    push si
    mov cx, 2
    call sh_dc_need
    jc .x
    mov al, [es:di+1]
    call sh_biff_b2e                  ; the file's code -> ERROR.TYPE
    mov [sh_curaux], al               ; ...which is what sh_errname reads
    push es
    push di
    SHOUT sh_errname
    pop di
    pop es
    call sh_dc_push
    jc .x
    mov si, sh_numbuf
    call sh_dc_apps
    jc .x
    add di, 2
.x:
    pop si
    pop cx
    pop ax
    ret

sh_dc_bool:                           ; 1DH 0/1 - the bare constant, the way
    push ax                           ; Excel shows it. It was TRUE() while
    push cx                           ; the evaluator knew no other (81.51)
    push si
    mov cx, 2
    call sh_dc_need
    jc .x
    call sh_dc_push
    jc .x
    mov si, sh_f_false
    cmp byte [es:di+1], 0
    je .f
    mov si, sh_f_true
.f:
    call sh_dc_apps
    jc .x
    add di, 2
.x:
    pop si
    pop cx
    pop ax
    ret

sh_dc_int:                            ; 1EH word, UNSIGNED
    push ax
    push cx
    push si
    mov cx, 3
    call sh_dc_need
    jc .x
    mov ax, [es:di+1]
    test ax, 0x8000                   ; sh_itoa is signed; a tInt this large
    jnz .bad                          ; is rarer than the code to print it
    push es
    push di
    SHOUT sh_itoa
    pop di
    pop es
    call sh_dc_push
    jc .x
    mov si, sh_numbuf
    call sh_dc_apps
    jc .x
    add di, 3
    jmp short .x
.bad:
    stc
.x:
    pop si
    pop cx
    pop ax
    ret

sh_dc_num:                            ; 1FH double - fifteen digits, which
    push ax                           ; is what Excel shows and enough to
    push cx                           ; give back any constant a person typed
    push si
    mov cx, 9
    call sh_dc_need
    jc .x
    push bx
    xor bx, bx
.cp:
    mov al, [es:di+bx+1]              ; the eight bytes into DS, where the
    mov [bx+sh_dc_dbl], al            ; float layer reads its operands
    inc bx
    cmp bx, 8
    jb .cp
    pop bx
    push es
    push di
    mov si, sh_dc_dbl
    SHOUT fp_unpack_a
    mov di, sh_numbuf
    mov ax, 15
    SHOUT fp_ftoa
    pop di
    pop es
    call sh_dc_push
    jc .x
    mov si, sh_numbuf
    call sh_dc_apps
    jc .x
    add di, 9
.x:
    pop si
    pop cx
    pop ax
    ret

sh_dc_fn:                             ; 21H index - a FIXED count, from the
    push ax                           ; table, because the token has none
    push bx
    push cx
    push si
    mov cx, 2
    cmp byte [sh_dc_ver], 4
    jb .n
    inc cx                            ; BIFF4's index is a word
.n:
    call sh_dc_need
    jc .x
    push cx
    mov bx, 1
    call sh_dc_index                  ; AL = the index, CF if not a function
    pop cx
    jc .x
    call sh_dc_name                   ; SI = its name, AL = its count
    jc .x
    push cx
    mov cl, al
    xor ch, ch
    call sh_dc_call
    pop cx
    jc .x
    add di, cx
.x:
    pop si
    pop cx
    pop bx
    pop ax
    ret

sh_dc_fnce:                           ; 58H argc index - a macro COMMAND,
    mov byte [cs:sh_dc_cept], 1       ; BIFF2/3's way of saying so (81.97),
                                       ; and otherwise tFuncVar exactly
sh_dc_fnv:                            ; 22H argc index
    push ax
    push bx
    push cx
    push si
    mov cx, 3
    cmp byte [sh_dc_ver], 4
    jb .n
    inc cx
.n:
    call sh_dc_need
    jc .xce                           ; 81.97.4: a TRUNCATED 58H token never
    push cx                           ; reaches sh_dc_index, and the flag it
    mov bx, 2                         ; set would then be read by the NEXT
    call sh_dc_index                  ; token - in the next formula, or the
                                       ; next document
    pop cx
    jc .x
    call sh_dc_name
    jc .x
    mov al, [es:di+1]
    and al, 0x7F                      ; bit 7: a macro command's prompt
    push cx
    mov cl, al
    xor ch, ch
    call sh_dc_call
    pop cx
    jc .x
    add di, cx
    jmp short .x
.xce:
    mov byte [cs:sh_dc_cept], 0
    stc
.x:
    pop si
    pop cx
    pop bx
    pop ax
    ret

sh_dc_ref:                            ; 24H roww col
    push ax
    push bx
    push cx
    mov cx, 4
    call sh_dc_need
    jc .x
    call sh_dc_push
    jc .x
    mov ax, [es:di+1]
    mov bl, [es:di+3]
    call sh_dc_cref
    jc .x
    add di, 4
.x:
    pop cx
    pop bx
    pop ax
    ret

sh_dc_area:                           ; 25H row1 row2 col1 col2
    push ax
    push bx
    push cx
    mov cx, 7
    call sh_dc_need
    jc .x
    call sh_dc_push
    jc .x
    mov ax, [es:di+1]
    mov bl, [es:di+5]
    call sh_dc_cref
    jc .x
    mov al, ':'
    call sh_dc_app
    jc .x
    mov ax, [es:di+3]
    mov bl, [es:di+6]
    call sh_dc_cref
    jc .x
    add di, 7
.x:
    pop cx
    pop bx
    pop ax
    ret

; --- the primitives ----------------------------------------------------------
; sh_dc_index - in BX = the index's offset in the token; out AL = it, and
; [cs:sh_dc_ce] which table it numbers - 1 for a macro COMMAND, when the ptg
; said so (58H, sh_dc_fnce) or BIFF4's bit 15 does (fCeFunc, 81.83.2). CF=1
; past one byte, or POWER's 0FFH "unwritable". Clobbers AH
sh_dc_index:
    mov al, [es:di+bx]
    mov ah, [cs:sh_dc_cept]
    mov byte [cs:sh_dc_cept], 0
    cmp byte [sh_dc_ver], 4
    jb .one
    cmp byte [es:di+bx+1], 0          ; BIFF4's high byte: 0 a function,
    je .one                           ; 80H a command, and SHEET has no
    cmp byte [es:di+bx+1], 0x80       ; function past 255
    jne .bad
    mov ah, 1
.one:
    mov [cs:sh_dc_ce], ah
    cmp al, 0xFF
    je .bad
    clc
    ret
.bad:
    stc
    ret
sh_dc_ce:   db 0                      ; the index just read is a command...
sh_dc_cept: db 0                      ; ...because its ptg is 58H (81.97)

; sh_dc_name - AL = a BIFF index, numbered in the table [cs:sh_dc_ce] names
; -> SI = the function's name (DS) and AL = its argument count when it is
; FIXED; CF=1 SHEET has no such function. sh_rpn_fid first, the table the
; writer uses, and then the extension functions' shm_mxrpn - so a mismatch
; with the writer is one table wrong, which --selfcheck checks. The TABLE
; matters as much as the number: every Cetab index collides with a function's
; (81.83.2), and a command read as a function is a different formula
sh_dc_name:
    push bx
    push cx
    push dx
    push di
    mov dl, [cs:sh_dc_ce]
    xor bx, bx
    mov cx, sh_rpn_fid_end - sh_rpn_fid
.l:
    cmp [bx+sh_rpn_fid], al
    jne .n
    xor dh, dh                        ; this one's table: the Ftab, unless
    mov di, bx                        ; it is one of sh_rpn_fce's commands
    sub di, SH_FN_MAC0
    jb .t
    cmp di, sh_rpn_fce_end - sh_rpn_fce
    jae .t
    mov dh, [di+sh_rpn_fce]
.t:
    cmp dh, dl
    je .hit
.n:
    inc bx
    loop .l
    xor bx, bx                        ; ...and the extension functions
    mov di, shm_mxrpn
    mov cx, SHM_MX_N
.x:
    cmp [cs:di], al
    jne .xn
    cmp [cs:di+2], dl
    je .xhit
.xn:
    add di, 3
    inc bx
    loop .x
    stc
    jmp short .out
.hit:
    mov al, [bx+sh_rpn_fargc]
    shl bx, 1
    mov si, [bx+sh_functab]
    clc
    jmp short .out
.xhit:
    mov al, [cs:bx+shm_mxargc]
    mov di, shm_mxnames               ; the BX'th name, copied into DS -
.w:                                   ; sh_ident, which the decode does not
    or bx, bx                         ; use, holds the longest of them
    jz .cp
.s:
    inc di
    cmp byte [cs:di-1], 0
    jne .s
    dec bx
    jmp short .w
.cp:
    mov si, sh_ident
    push ax
.c:
    mov al, [cs:di]
    mov [si], al
    inc di
    inc si
    or al, al
    jnz .c
    pop ax
    mov si, sh_ident
    clc
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; sh_dc_call - SI = a function's name (DS), CX = its argument count: the top
; CX fragments become NAME(a,b,...), or a new NAME() when CX is 0.
sh_dc_call:
    push ax
    push bx
    push cx
    push dx
    push si
    jcxz .none
    cmp [sh_dc_sp], cx
    jb .bad
    mov dx, [sh_dc_sp]
    sub dx, cx                        ; DX = the first argument's slot
    mov bx, [sh_dc_sp]
    dec bx                            ; commas from the LAST argument down,
.comma:                               ; so each insert shifts only what has
    cmp bx, dx                        ; already been placed
    jbe .name
    push bx
    mov bl, [bx+sh_dc_stk]
    xor bh, bh
    mov al, ','
    call sh_dc_insc
    pop bx
    jc .x
    dec bx
    jmp short .comma
.name:
    mov bx, dx
    mov bl, [bx+sh_dc_stk]
    xor bh, bh
    call .insname
    jc .x
    mov al, ')'
    call sh_dc_app
    jc .x
    dec cx
    sub [sh_dc_sp], cx                ; the arguments are one fragment now
    clc
    jmp short .x
.none:
    call sh_dc_push
    jc .x
    mov bx, [sh_dc_end]
    call .insname
    jc .x
    mov al, ')'
    call sh_dc_app
    jmp short .x
.bad:
    stc
.x:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret
.insname:                             ; SI's letters and a '(' at BX
    lodsb
    or al, al
    jz .open
    call sh_dc_insc
    jc .ret
    inc bx
    jmp short .insname
.open:
    mov al, '('
    call sh_dc_insc
.ret:
    ret

; sh_dc_cref - AX = an encoded row word, BL = the column (3.3.3): bit 15 SET
; means the row is RELATIVE and bit 14 the column, so '$' goes where a bit is
; CLEAR. Appends it.
sh_dc_cref:
    push ax
    push si
    test ah, 0x40
    jnz .col
    push ax
    mov al, '$'
    call sh_dc_app
    pop ax
    jc .x
.col:
    push ax
    push es
    push di
    mov al, bl
    xor ah, ah
    SHOUT sh_colname
    pop di
    pop es
    mov si, sh_colbuf
    call sh_dc_apps
    pop ax
    jc .x
    test ah, 0x80
    jnz .row
    push ax
    mov al, '$'
    call sh_dc_app
    pop ax
    jc .x
.row:
    and ax, 0x3FFF
    inc ax
    push es
    push di
    SHOUT sh_itoa
    pop di
    pop es
    mov si, sh_numbuf
    call sh_dc_apps
.x:
    pop si
    pop ax
    ret

; sh_dc_insc - AL into the text at BX, the rest moved up one. CF=1 when the
; text is already SH_EDITMAX long: SHEET cannot hold a longer formula, so the
; cell keeps its value instead. Preserves everything.
sh_dc_insc:
    push cx
    push si
    mov si, [sh_dc_end]
    cmp si, SH_EDITMAX
    jae .full
.mv:
    cmp si, bx
    jbe .put
    mov cl, [si+sh_rwsrc-1]
    mov [si+sh_rwsrc], cl
    dec si
    jmp short .mv
.put:
    mov [bx+sh_rwsrc], al
    inc word [sh_dc_end]
    clc
    pop si
    pop cx
    ret
.full:
    stc
    pop si
    pop cx
    ret

sh_dc_app:                            ; AL at the end
    push bx
    mov bx, [sh_dc_end]
    call sh_dc_insc
    pop bx
    ret

sh_dc_apps:                           ; DS:SI's NUL-terminated string at the end
    push ax
    push si
.l:
    lodsb
    or al, al
    jz .ok
    call sh_dc_app
    jnc .l
    jmp short .x
.ok:
    clc
.x:
    pop si
    pop ax
    ret

sh_dc_push:                           ; a new fragment, starting at the end
    push ax
    push bx
    mov bx, [sh_dc_sp]
    cmp bx, SH_DC_DEPTH
    jae .full
    mov al, [sh_dc_end]
    mov [bx+sh_dc_stk], al
    inc word [sh_dc_sp]
    clc
    jmp short .x
.full:
    stc
.x:
    pop bx
    pop ax
    ret

sh_dc_pop:                            ; BX = the top fragment's start, dropped
    cmp word [sh_dc_sp], 0
    je .empty
    dec word [sh_dc_sp]
    mov bx, [sh_dc_sp]
    mov bl, [bx+sh_dc_stk]
    xor bh, bh
    clc
    ret
.empty:
    stc
    ret

sh_dc_top:                            ; BX = the top fragment's start, kept
    cmp word [sh_dc_sp], 0
    je .empty
    mov bx, [sh_dc_sp]
    mov bl, [bx+sh_dc_stk-1]
    xor bh, bh
    clc
    ret
.empty:
    stc
    ret

sh_dc_need:                           ; CF=1 if CX bytes from DI pass the end
    push ax
    mov ax, di
    add ax, cx
    cmp [sh_dc_tend], ax
    pop ax
    ret


sh_doread_biff:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es

    mov es, [sh_stgseg]
    xor bx, bx
    mov cx, SH_STAGE_MAX
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_READ               ; out: AX = bytes read, or CF=1
    jc .rerr

    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0            ; "replacing the sheet" - see
    mov word [sh_nbord], 0             ; sh_doread_sylk's same three
    mov word [sh_ntbl], 0            ; 81.114.7: ...and its TABLES
    mov word [sh_nnote], 0
    SHOUT sh_colw_clear                ; ...and every column's width (81.56)
    mov word [sh_nnames], 0            ; the DEFINEDNAME records below refill
                                       ; this; they precede the cell records
    call sh_kindreset                  ; 81.97: a worksheet until a BOF says
    mov word [sh_biff_nfont], 0
    mov word [sh_biff_nxf], 0
    mov word [sh_b2], 0                ; sh_b2 and sh_b2_int: BIFF3 until a
                                       ; BIFF2 BOF says otherwise (81.52)
    mov cx, ax                         ; CX = end offset (bytes read)
    mov [sh_biff_end], ax              ; ...and banked, because .islabel needs
    xor si, si                         ; a counter and CX is the only one free
    ; AX STILL HELD THE BYTE COUNT two lines ago, which is why this bank sits
    ; below and not above: reading sh_cursheet into AX before those two lines
    ; made the file end ZERO, and the record walk finished before its first
    ; record while still reporting "Loaded".
    mov ax, [sh_cursheet]              ; a workbook read MOVES sh_cursheet as
    mov [sh_rd_home], ax               ; it walks the substreams, so where the
    mov word [sh_rd_sheet], -1         ; user actually was is banked and put
    mov byte [sh_rd_wb], 0             ; back at the end
.rechdr:
    mov ax, si
    add ax, 4                          ; a record header is 4 bytes; EOF's
    cmp ax, cx                         ; is the shortest whole record, so
    ja .done                           ; anything less can't be one
    mov ax, [es:si]                    ; opcode
    mov dx, [es:si+2]                  ; length
    add si, 4                          ; SI = this record's data start
    mov bx, si                         ; the record must END inside the file:
    add bx, dx                         ; a crafted length near 0xFFFF wraps
    jc .done                           ; the 16-bit add and walks the stream
    cmp bx, cx                         ; BACKWARD - onto this same header,
    ja .done                           ; forever - so the wrap (CF) and the
                                       ; file end are both refused here, which
                                       ; also bounds every unknown-opcode
                                       ; .skip (every byte off a disk is
                                       ; hostile)
    cmp ax, 0x0009                     ; 81.97: every BOF says what KIND
    je .bofk                           ; of sheet follows - BIFF2's, 3's and
    cmp ax, 0x0209                     ; 4's alike, dt at +2
    je .bofk
    cmp ax, 0x0409
    jne .nbofk
.bofk:
    call sh_rd_bofkind
.nbofk:
    cmp ax, 0x000A                     ; EOF - but a WORKBOOK has one per sheet
    je .iseof                          ; substream plus its own, so the first
                                       ; is not the end of anything (81.10.5)
    cmp ax, 0x0009                     ; BIFF2's BOF: EXCEL 2.1's OWN FILES
    je .isbof2                         ; (81.52). Its cell ids are 0002H-0007H,
    cmp byte [sh_b2], 0                ; which BIFF5 reuses for other shapes,
    je .notb2                          ; so they are BIFF2's only after one
    cmp ax, 0x0031                     ; BIFF2's FONT: the options word at the
    je .isfont                         ; same offset as 0231H's
    cmp ax, 0x0008                     ; BIFF2's ROW (81.60), 0208H's first
    je .isrow                          ; four words exactly
    cmp ax, 0x0002
    jb .notb2
    cmp ax, 0x0007
    ja .notb2
    jmp .b2cell
.notb2:
    cmp ax, 0x0231                     ; FONT
    je .isfont
    cmp ax, 0x0243                     ; XF (BIFF3) - what this app writes
    je .isxf                           ; now, and what a real Excel 3 file
    cmp ax, 0x0443                     ; carries. BIFF4's is accepted too, so
    je .isxf                           ; files written before the switch still
                                        ; read back with their formats, as do
                                        ; real Excel 4 files. BIFF5-8's XF
                                        ; (0x00E0) has a different layout and
                                        ; is skipped generically below, so
                                        ; those cells read back unformatted
                                        ; rather than misformatted.
    cmp ax, 0x0201                     ; BLANK: a cell with a FORMAT and no
    je .isblank                        ; value at all (81.77). SHEET writes
                                        ; one; before this it could not read
                                        ; one back, so its own file lost the
                                        ; format on the way in instead of on
                                        ; the way out
    cmp ax, 0x001C                     ; NOTE (81.119): the text of a cell
    je .isnote                         ; note, which SHEET writes now
    cmp ax, 0x027E                     ; RK cell record
    je .isrk
    cmp ax, 0x0203                     ; NUMBER: a whole IEEE-754 double, and
    je .isnum                          ; the only way a fraction can travel
    cmp ax, 0x0204                     ; LABEL (BIFF3/4). 0004H is BIFF2's,
    je .islabel                        ; with a one-byte length, and is NOT
    cmp ax, 0x0205                     ; BOOLERR: a boolean or an ERROR VALUE
    je .isboolerr
    cmp ax, 0x0207                     ; STRING: the text a string formula
    jne .notstr                        ; answered, directly after it
    jmp .isstring
.notstr:
    mov byte [sh_dc_pend], 0           ; anything else ends a wait for one
    cmp ax, 0x0206                     ; accepted here for that reason
    je .isformula                      ; FORMULA: decoded back to its text when
    cmp ax, 0x0406                     ; it can be, its cached result when not
    je .isformula                      ; (81.10.10). 0406H is BIFF4's number
    cmp ax, 0x008F                     ; SHEETHDR: the substream that follows
    je .issheethdr                     ; belongs to the NEXT sheet
    cmp ax, 0x0024                     ; COLWIDTH (BIFF2-4) and COLINFO (BIFF3
    je .iscolw                         ; on): a run of columns and their width
    cmp ax, 0x007D                     ; (81.56)
    je .iscolw
    cmp ax, 0x0208                     ; ROW (BIFF3 on): a row's height, in
    je .isrow                          ; twips (81.60)
    cmp ax, 0x0236                     ; DATATABLE (BIFF3/4). 0036H is BIFF2's
    je .isdatatable                    ; and splits the two-input case into a
                                       ; second record; 81.114.10 reads this
                                       ; one only, which is what this app
                                       ; writes
    cmp ax, 0x0218                     ; DEFINEDNAME (BIFF3/4) - 0018H is the
    je .isname                         ; BIFF2/5/8 number and is NOT accepted
    jmp .skip                          ; here, because its body is a different
                                       ; shape (81.10.8)
.iscolw:
    ; first and last column - BYTES in COLWIDTH, WORDS in COLINFO - then the
    ; width in 1/256ths of a character, rounded to a whole one here
    push dx
    cmp dx, 4
    jb .cwskip
    push ax
    mov al, [es:si]
    xor ah, ah
    mov dx, [es:si+1]
    xor dh, dh
    mov cx, [es:si+2]                  ; COLWIDTH's width
    pop bx
    cmp bx, 0x0024
    je .cwhave
    mov ax, [es:si]                    ; COLINFO's three words
    mov dx, [es:si+2]
    mov cx, [es:si+4]
.cwhave:
    push ax
    mov ax, cx
    add ax, 128
    mov al, ah
    xor ah, ah                         ; AX = whole characters
    call sh_cwbyte                     ; CL = what the table keeps
    pop ax
.cwl:
    cmp ax, dx
    ja .cwskip
    cmp ax, 256
    jae .cwskip
    SHOUT sh_colw_set
    inc ax
    jmp short .cwl
.cwskip:
    mov cx, [sh_biff_end]              ; the file's end, which CX carries here
    pop dx
    jmp .skip
.isrow:
    ; the row, then at +6 its height in twips with bit 15 set for "the
    ; default height", which costs the table nothing. Excel's 0 hides a row,
    ; which this grid cannot, so it stays the standard; the rest are clamped
    ; to what the Row Height dialog allows
    push dx
    cmp dx, 8
    jb .rowskip
    mov ax, [es:si]
    cmp ax, SH_ROWS
    jae .rowskip
    mov cx, [es:si+6]
    test ch, 0x80
    jnz .rowskip
    jcxz .rowskip
    cmp cx, SH_RH_TWMIN
    jae .rowlo
    mov cx, SH_RH_TWMIN
.rowlo:
    cmp cx, SH_RH_TWMAX
    jbe .rowhi
    mov cx, SH_RH_TWMAX
.rowhi:
    SHOUT sh_rowh_set
.rowskip:
    mov cx, [sh_biff_end]
    pop dx
    jmp .skip
.isbof2:
    mov byte [sh_b2], 1
    mov word [sh_biff_nxf], SH_BIFF_XF_CAP  ; so .applyfmt takes SH_B2_XF
    jmp .skip
.b2cell:
    ; ------------------------------------------------------------------
    ; A BIFF2 CELL is a BIFF3 one with three attribute bytes where the XF
    ; index goes (2.5.13), and it is REWRITTEN IN PLACE into BIFF3's shape so
    ; the handlers below read it unchanged: the attributes go to XF slot
    ; SH_B2_XF, and row/col/xf move up one byte, which puts the value where
    ; BIFF3 keeps it. SI+1 and DX-1 leave .skip's SI+DX where it was. LABEL
    ; is the exception - its one-byte length becomes BIFF3's word without the
    ; move - and so is STRING, which has no cell header at all.
    ; ------------------------------------------------------------------
    cmp ax, 0x0007
    je .b2str
    cmp dx, 8
    jb .skip
    call sh_b2_attr
    cmp al, 4
    je .b2label
    push ax
    push bx
    mov bx, [es:si]                    ; row
    mov ax, [es:si+2]                  ; col
    mov [es:si+3], ax
    mov [es:si+1], bx
    mov word [es:si+5], SH_B2_XF
    pop bx
    inc si
    dec dx
    pop ax
    mov byte [sh_b2_int], 0
    cmp al, 3
    jne .b2n3
    jmp .isnum
.b2n3:
    cmp al, 5
    jne .b2n5
    jmp .isboolerr
.b2n5:
    cmp al, 6
    jne .b2int
    jmp .isformula                     ; AH = 0: sh_dc_ver 0 is BIFF2
.b2int:
    mov byte [sh_b2_int], 1            ; 2, INTEGER: an unsigned word
    jmp .isrk
.b2label:
    mov al, [es:si+7]
    mov [es:si+6], al
    mov byte [es:si+7], 0
    mov word [es:si+4], SH_B2_XF
    jmp .islabel
.b2str:
    or dx, dx
    jz .b2sskip
    dec si                             ; one byte BACK onto the record header's
    inc dx                             ; length, already consumed, for the
    mov al, [es:si+1]                  ; second byte of the word
    mov [es:si], al
    mov byte [es:si+1], 0
    jmp .isstring
.b2sskip:
    jmp .skip
.isname:
    ; ------------------------------------------------------------------
    ; DEFINEDNAME. Every field is bounds-checked against CX, the file's
    ; own end, before it is read: a name length and a formula size are
    ; two more numbers off a disk, and either can be a lie.
    ; ------------------------------------------------------------------
    mov ax, si
    add ax, 6                          ; the six-byte header must be there
    jc .skip
    cmp ax, cx
    ja .skip
    mov bl, [es:si+3]                  ; ln
    xor bh, bh
    or bx, bx
    jz .skip
    cmp bx, SH_NAME_MAX                ; a longer name than this app can hold
    ja .skip                           ; is dropped, not clipped: a clipped
                                       ; name silently binds the wrong thing
                                       ; the next time it is looked up
    mov ax, [es:si+4]                  ; sz - the token array's size. Seven is
    cmp ax, 7                          ; one tAreaR, which is the only shape
    jne .skip                          ; this app defines and the only one it
                                       ; can turn back into a rectangle
    mov ax, si
    add ax, 6
    add ax, bx
    add ax, 7                          ; ...and all of it must be inside
    jc .skip
    cmp ax, cx
    ja .skip
    push si
    push cx
    push dx
    add si, 6
    mov di, sh_nm_in
    mov cx, bx
.nmcopy:
    mov al, [es:si]                    ; the name is COUNTED in the file and
    mov [di], al                       ; NUL-terminated in the table
    inc si
    inc di
    dec cx
    jnz .nmcopy
    mov byte [di], 0
    cmp byte [es:si], 0x25             ; tAreaR, the absolute reference form.
    jne .nmdone                        ; tAreaN (2DH) is the relative one and
                                       ; means something this app has no way
                                       ; to resolve - a name relative to WHAT
    mov ax, [es:si+1]                  ; first row; bits 14-15 are the two
    and ax, 0x3FFF                     ; relative flags, not part of the index
    mov [sh_nm_row], ax
    mov ax, [es:si+3]                  ; last row
    and ax, 0x3FFF
    mov [sh_nm_row2], ax
    mov al, [es:si+5]                  ; first and last column, a byte each
    xor ah, ah
    mov [sh_nm_col], ax
    mov al, [es:si+6]
    xor ah, ah
    mov [sh_nm_col2], ax
    cmp word [sh_nm_row2], SH_ROWS     ; a range this grid cannot hold is
    jae .nmdone                        ; refused whole rather than clamped
    cmp word [sh_nm_col2], SH_COLS
    jae .nmdone
    mov si, sh_nm_in
    mov ax, [sh_nm_col]
    mov bx, [sh_nm_row]
    mov cx, [sh_nm_col2]
    mov dx, [sh_nm_row2]
    SHOUT sh_name_def                   ; CF=1 = the table is full, and the
.nmdone:                               ; rest of the file still loads
    pop dx
    pop cx
    pop si
    jmp .skip
.isfont:
    mov bx, [sh_biff_nfont]
    cmp bx, SH_BIFF_FONT_CAP
    jae .fontcounted                   ; too many fonts to track: this one
                                        ; (and any cell using it) just
                                        ; reads back as not bold/underlined
    mov ax, si
    add ax, 4                          ; need at least height+options here
    cmp ax, cx
    ja .fontcounted
    mov al, [es:si+2]                  ; BIFF options byte: bit0 bold,
    mov ah, 0                          ; bit2 underline (BIFF3/4 layout)
    test al, 0x01
    jz .fnb
    or ah, SH_FMT_BOLD
.fnb:
    test al, 0x04
    jz .fnu
    or ah, SH_FMT_UNDER
.fnu:
    mov di, sh_font_tab
    add di, bx
    mov [di], ah
.fontcounted:
    inc word [sh_biff_nfont]
    jmp .skip
.isxf:
    mov bx, [sh_biff_nxf]
    cmp bx, SH_BIFF_XF_CAP
    jae .xfcounted                     ; too many XFs to track: a cell
                                        ; using one just reads back General
    mov ax, si
    add ax, 12                         ; need the full BIFF4 XF body
    cmp ax, cx
    ja .xfcounted
    mov al, [es:si]                    ; font index (offset0, low byte of
    mov di, sh_xf_font                 ; the font/format word)
    add di, bx
    mov [di], al
    mov al, [es:si+1]                  ; the XF's number format: any but the
    call sh_biff_nfside                ; format byte's four waits beside the
    mov [bx+sh_xf_nf], al              ; border (81.55)
    mov al, [es:si+4]                  ; align/wrap/vertalign/orient byte
    and al, 0x07                       ; the full 3-bit XF_HOR_ALIGN field
    cmp al, 3
    jbe .alignok
    xor al, al                         ; Filled/Justified/CenterAcrossSel:
                                        ; out of this subset's scope
.alignok:
    push cx                            ; CX IS THE FILE'S END OFFSET here, and
    mov cl, SH_FMT_ALIGN_SHIFT         ; `mov cl` destroys its low byte. With
    shl al, cl                         ; 64 XF records to read, the walk then
    pop cx                             ; ran off a length of ~1028 instead of
    mov ah, al                         ; 1160 and stopped BEFORE the first cell
    mov al, [es:si+1]                  ; record - so every BIFF file this app
    call sh_biff_numfmt_from_id        ; wrote read back as "Loaded" and empty.
    push cx
    mov cl, SH_FMT_NUM_SHIFT
    shl al, cl
    pop cx
    or al, ah                          ; al = align|numfmt packed byte
    mov di, sh_xf_fmt
    add di, bx
    mov [di], al
    ; --- borders, shade and protection out of the SAME record (81.47) -----
    ; AH is the accumulator, because DX is the record length the walk needs
    ; and CX is the file's end - the two registers this loop cannot spare.
    xor ah, ah
    mov al, [es:si+8]                  ; XF_BORDER_34, bits 2-0: top line
    and al, 7                          ; style. ANY non-zero style reads back
    jz .nrtop                          ; as this app's one kind of line - it
    or ah, SH_BORD_TOP                 ; draws thin and has no other
.nrtop:
    mov al, [es:si+9]                  ; bits 10-8: left
    and al, 7
    jz .nrleft
    or ah, SH_BORD_LEFT
.nrleft:
    mov al, [es:si+10]                 ; bits 18-16: bottom
    and al, 7
    jz .nrbot
    or ah, SH_BORD_BOTTOM
.nrbot:
    mov al, [es:si+11]                 ; bits 26-24: right
    and al, 7
    jz .nrright
    or ah, SH_BORD_RIGHT
.nrright:
    mov al, [es:si+6]                  ; XF_AREA_34, bits 5-0: any pattern at
    and al, 0x3F                       ; all is this app's Shade
    jz .nrshade
    or ah, SH_BORD_SHADE
.nrshade:
    mov al, [es:si+2]                  ; XF_TYPE_PROT: bit 0 locked, bit 1
    test al, 1                         ; hidden. This app stores the EXCEPTION
    jnz .nrlocked                      ; (81.46.1), so an absent locked bit is
    or ah, SH_PROT_UNLOCK              ; what gets recorded
.nrlocked:
    test al, 2
    jz .nrhid
    or ah, SH_PROT_HIDDEN
.nrhid:
    mov di, sh_xf_bord
    add di, bx
    mov [di], ah
.xfcounted:
    inc word [sh_biff_nxf]
    jmp .skip
.isnote:
    ; 81.119: row, col, cch, the bytes - into the note table through the same
    ; sh_nt_set a typed note takes, so a refusal (table or arena full) drops
    ; it exactly as typing one would. sh_notetext is the dialog's own buffer
    ; and no dialog can be open during a read.
    cmp dx, 6                          ; row, col, cch, then the text
    jb .skip
    mov ax, [es:si]
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]
    mov [sh_wrec_col], ax
    call sh_biff_rcok                  ; a continuation record's row is FFFFH
    jc .skip                           ; and lands here too
    push dx
    push si
    push di
    mov cx, [es:si+4]                  ; the text's length, bounded by the
    sub dx, 6                          ; record's and by the dialog's buffer
    cmp cx, dx
    jbe .nlok
    mov cx, dx
.nlok:
    cmp cx, SH_NOTEMAX - 1
    jbe .nlok2
    mov cx, SH_NOTEMAX - 1
.nlok2:
    add si, 6
    mov di, sh_notetext
    jcxz .nrend
.nrd:
    mov al, [es:si]
    or al, al                          ; a NUL inside would end it early
    jz .nrend                          ; anyway; end it here instead
    mov [di], al
    inc si
    inc di
    loop .nrd
.nrend:
    mov byte [di], 0
    pop di
    pop si
    push es
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    push si
    mov si, sh_notetext
    SHOUT sh_nt_set                    ; CF = 1 table or arena full: dropped,
    pop si                             ; as a typed one would be
    pop es
    pop dx
    mov cx, [sh_biff_end]              ; CX was the counter: the file end back
    jmp .skip

.isblank:
    ; A CELL WITH A FORMAT AND NO VALUE (81.77). There is nothing to store as
    ; a value - sh_setvald is not called at all - and the whole record is its
    ; XF, which sh_biff_applyfmt puts in the border table's own bytes. A cell
    ; record is deliberately NOT created: "no record" is what empty means
    ; here, and inventing one would put a 0 on the sheet.
    push dx
    mov ax, si
    add ax, dx
    cmp ax, cx
    ja .toolong                        ; truncated record: stop, don't read
    mov ax, [es:si]                    ; row
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]                  ; col
    mov [sh_wrec_col], ax
    mov ax, [es:si+4]                  ; xf index
    mov [sh_wrec_xf], ax
    call sh_biff_rcok                  ; off-grid: skip, as every cell record
    jc .bldone                         ; here does
    call sh_biff_applyfmt
.bldone:
    pop dx
    jmp .skip


.isrk:
    push dx                            ; length, saved across sh_setvald
                                        ; (which itself preserves DX, but
                                        ; only around the value it was
                                        ; passed - not a second use)
    mov ax, si
    add ax, dx
    cmp ax, cx
    ja .toolong                        ; truncated record: stop, don't read
    mov ax, [es:si]                    ; row
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]                  ; col
    mov [sh_wrec_col], ax
    mov ax, [es:si+4]                  ; xf index
    mov [sh_wrec_xf], ax
    call sh_biff_rcok                  ; off-grid row/col: skip the record
    jc .rkdone                         ; rather than cross onto another sheet
    mov ax, [es:si+6]                  ; rk value low word
    cmp byte [sh_b2_int], 0            ; ...or BIFF2's INTEGER, an unsigned
    je .rkhi                           ; word, made the RK integer it would
    xor dx, dx                         ; have been: (v << 2) | 2 (81.52)
    shl ax, 1
    rcl dx, 1
    shl ax, 1
    rcl dx, 1
    or al, 2
    jmp short .rkgo
.rkhi:
    mov dx, [es:si+8]                  ; rk value high word
.rkgo:
    push es                            ; sh_rkdec_d works in sh_acc, which is
    call sh_rkdec_d                    ; ours, not the staging segment's
    pop es
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_setvald
    call sh_biff_applyfmt              ; uses sh_wrec_col/row/xf; looks up
                                        ; the format and writes it to the
                                        ; cell record sh_setvald just made
.rkdone:
    pop dx
    jmp .skip
.isnum:
    push dx
    mov ax, si
    add ax, dx
    cmp ax, cx
    ja .toolong
    mov ax, [es:si]                    ; row
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]                  ; col
    mov [sh_wrec_col], ax
    mov ax, [es:si+4]                  ; xf index
    mov [sh_wrec_xf], ax
    call sh_biff_rcok                  ; off-grid row/col: skip the record
    jc .rkdone
    mov ax, [es:si+6]                  ; the eight value bytes, verbatim
    mov [sh_acc], ax
    mov ax, [es:si+8]
    mov [sh_acc+2], ax
    mov ax, [es:si+10]
    mov [sh_acc+4], ax
    mov ax, [es:si+12]
    mov [sh_acc+6], ax
    push es
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_setvald
    call sh_biff_applyfmt
    pop es
    pop dx
    jmp .skip
.iseof:
    cmp byte [sh_rd_wb], 0             ; a plain single-sheet stream ends here,
    je .done                           ; as it always did. In a workbook this
    jmp .skip                          ; only closes one substream, and the
                                       ; walk stops when the bytes run out
.issheethdr:
    mov byte [sh_rd_wb], 1             ; from here on, an EOF closes a sheet
    ; A BIFF4 WORKBOOK (81.10.5). Every SHEETHDR starts another sheet's
    ; substream, so the reader simply counts them: the first is sheet 0, the
    ; next sheet 1, and the cell records in between land on whichever is
    ; current. The name in the record is IGNORED - this app's four sheets are
    ; positional and named by position (81.2), so honouring a name would mean
    ; inventing a mapping the rest of the app has no way to express.
    inc word [sh_rd_sheet]
    mov ax, [sh_rd_sheet]
    cmp ax, SH_SHEETS
    jb .rdsheetok
    mov ax, SH_SHEETS - 1              ; a workbook with more sheets than this
.rdsheetok:                            ; app has: the surplus piles onto the
    mov [sh_cursheet], ax              ; last one rather than being dropped
    jmp .skip
.isformula:
    ; THE FORMULA IS READ BACK, and its cached result only when it cannot be
    ; (81.10.10). Until then this said the tokens were stepped over because a
    ; decompiler would have to guess at function numbers from a section marked
    ; *2do* - true of the document it was written against, and not of revision
    ; 1.42, which the writer has used since 81.10.2. Stepping over them made a
    ; Save in Normal format and a reopen turn every formula into a number.
    mov [sh_dc_ver], ah                ; 02H or 04H: BIFF3 or BIFF4, which is
    push dx                            ; how wide a function index is
    mov ax, si
    add ax, dx
    cmp ax, cx
    ja .toolong
    mov ax, [es:si]                    ; row
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]                  ; col
    mov [sh_wrec_col], ax
    mov ax, [es:si+4]                  ; xf index
    mov [sh_wrec_xf], ax
    call sh_biff_rcok                  ; off-grid row/col: skip the record
    jc .rkdone
    call sh_biff_dcrpn                 ; THE FORMULA ITSELF when its tokens
    jc .fcached                        ; can be read back, and the cached
    push es                            ; value below, as before, when they
    push si                            ; cannot
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    mov si, sh_rwsrc
    SHOUT sh_setformula                ; CF=1: the formula arena is full,
    pop si                             ; which costs this cell its liveness
    pop es                             ; and not its number
    jc .fcached
    push es
    call sh_biff_applyfmt
    pop es
    pop dx
    jmp .skip
.fcached:
    mov ax, [es:si+6]                  ; the eight result bytes
    mov [sh_acc], ax
    mov ax, [es:si+8]
    mov [sh_acc+2], ax
    mov ax, [es:si+10]
    mov [sh_acc+4], ax
    mov ax, [es:si+12]
    mov [sh_acc+6], ax
    cmp word [sh_acc+6], 0xFFFF        ; not a number at all: see .errresult in
    jne .fresnum                       ; the writer for the encoding
    mov al, [sh_acc]                   ; byte 0 says which kind (5.50)
    cmp al, 2
    je .fcerr
    cmp al, 1
    je .fcbool
    or al, al
    jnz .fcnone                        ; 3 is BIFF8's "empty": no value
    mov ax, [sh_wrec_row]              ; 0: TEXT, and it is not here - it is
    mov [sh_dc_prow], ax               ; in the STRING record that follows, so
    mov ax, [sh_wrec_col]              ; the cell waits for it (.isstring).
    mov [sh_dc_pcol], ax               ; These eight bytes used to be stored
    mov ax, [sh_wrec_xf]               ; as a double, which is a NaN
    mov [sh_dc_pxf], ax
    mov byte [sh_dc_pend], 1
.fcnone:
    pop dx
    jmp .skip
.fcbool:
    push es                            ; the logical, as a BOOLERR reads
    mov dl, [sh_acc+2]                 ; (.isbool)
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_setbool
    call sh_biff_applyfmt
    pop es
    pop dx
    jmp .skip
.fcerr:
    push es
    mov al, [sh_acc+2]                 ; the FILE's code, into ERROR.TYPE's:
    call sh_biff_b2e                   ; raw, an Excel #DIV/0! (07H) arrived
    mov dl, al                         ; as #N/A (81.10.11)
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_seterr
    call sh_biff_applyfmt
    pop es
    pop dx
    jmp .skip
.fresnum:
    push es
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_setvald
    call sh_biff_applyfmt
    pop es
    pop dx
    jmp .skip
.isboolerr:
    push dx
    mov ax, si
    add ax, dx
    cmp ax, cx
    ja .toolong
    mov ax, [es:si]                    ; row
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]                  ; col
    mov [sh_wrec_col], ax
    mov ax, [es:si+4]                  ; xf index
    mov [sh_wrec_xf], ax
    call sh_biff_rcok                  ; off-grid row/col: skip the record
    jc .rkdone
    mov al, [es:si+6]                  ; the value...
    mov dl, al
    mov al, [es:si+7]                  ; ...and what kind of value it is
    push es
    or al, al
    jz .isbool
    mov al, dl                         ; an ERROR: the file's code is the
    call sh_biff_b2e                   ; FORMAT's numbering, not ERROR.TYPE's
    mov dl, al
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    SHOUT sh_seterr
    jmp .bedone
.isbool:
    mov ax, [sh_wrec_col]              ; TRUE/FALSE is the LOGICAL now, and no
    mov bx, [sh_wrec_row]              ; longer reads back as 1/0 (81.51). DL
    SHOUT sh_setbool                    ; is the value byte
.bedone:
    call sh_biff_applyfmt
    pop es
    pop dx
    jmp .skip
.islabel:
    push dx
    mov ax, si
    add ax, dx
    cmp ax, cx
    ja .toolong
    mov ax, [es:si]                    ; row
    mov [sh_wrec_row], ax
    mov ax, [es:si+2]                  ; col
    mov [sh_wrec_col], ax
    mov ax, [es:si+4]                  ; xf index
    mov [sh_wrec_xf], ax
    call sh_biff_rcok                  ; off-grid row/col: skip the record
    jc .rkdone
    mov ax, [es:si+6]                  ; cch, sixteen bits in BIFF3
    cmp ax, SH_EDITMAX                 ; a longer label is TRUNCATED, not
    jbe .lcap                          ; refused: the record's own length
    mov ax, SH_EDITMAX                 ; field still governs the skip below,
.lcap:                                 ; so the stream stays in step
    mov [sh_wrec_len], ax
    push si
    push di
    add si, 8                          ; past row/col/xf/cch
    mov di, SH_TEXPR
    mov cx, [sh_wrec_len]              ; CX HOLDS THE FILE END for this whole
    jcxz .lrdend                       ; routine and is the only register free
.lrd:                                  ; to count with, so it is reloaded from
    mov al, [es:si]                    ; sh_biff_end after the copy - every
    mov [di], al                       ; record after this one is bounded by it
    inc si
    inc di
    dec cx
    jnz .lrd
.lrdend:
    mov byte [di], 0
    pop di
    pop si
    push es
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    push si
    mov si, SH_TEXPR
    SHOUT sh_settext
    pop si
    call sh_biff_applyfmt
    pop es
    mov cx, [sh_biff_end]              ; CX restored: the loop bound, banked at
    pop dx                             ; the top of this routine, because the
    jmp .skip                          ; copy above used CX as its counter
.isstring:                             ; (81.10.11)
    cmp byte [sh_dc_pend], 0           ; a STRING with no formula waiting is
    je .skip                           ; the result of one this app decoded,
    mov byte [sh_dc_pend], 0           ; which recomputes its own
    cmp dx, 2
    jb .skip
    push dx
    mov ax, [sh_dc_prow]
    mov [sh_wrec_row], ax
    mov ax, [sh_dc_pcol]
    mov [sh_wrec_col], ax
    mov ax, [sh_dc_pxf]
    mov [sh_wrec_xf], ax
    mov ax, [es:si]                    ; a 16-bit length in BIFF3-5 (5.102)
    cmp ax, SH_EDITMAX                 ; truncated, as .islabel truncates
    jbe .scap
    mov ax, SH_EDITMAX
.scap:
    mov [sh_wrec_len], ax
    push si
    push di
    add si, 2
    mov di, SH_TEXPR
    mov cx, [sh_wrec_len]
    jcxz .srdend
.srd:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .srd
.srdend:
    mov byte [di], 0
    pop di
    pop si
    push es
    mov ax, [sh_wrec_col]
    mov bx, [sh_wrec_row]
    push si
    mov si, SH_TEXPR
    SHOUT sh_settext
    pop si
    call sh_biff_applyfmt
    pop es
    mov cx, [sh_biff_end]              ; the loop bound again, as .islabel
    pop dx
    jmp .skip
.isdatatable:
    ; 81.114.10: THE BODY IS THE RECORD. sh_tblseg's entry was laid out as
    ; BIFF3's DATATABLE field for field (81.114.7) precisely so that reading
    ; one is a COPY - range, option flags, both input cells, sixteen bytes -
    ; and the seventeenth, the sheet, is ours and not the format's.
    cmp dx, 16
    jb .skip
    cmp word [sh_ntbl], SH_TBL_CAP
    jae .skip
    mov ax, [es:si+SH_T_R2]            ; ...BUT THE FIELDS ARE THE FILE'S, so
    cmp ax, SH_ROWS                    ; they are checked before the copy:
    jae .dtbad                         ; R1 <= R2 on the grid, C1 <= C2, and
    cmp [es:si+SH_T_R1], ax            ; every input cell on it or
    ja .dtbad                          ; SH_TBL_NONE. An R2 of FFFFH never
    mov al, [es:si+SH_T_C1]            ; ends sh_tbl_markall's row walk, and a
    cmp al, [es:si+SH_T_C2]            ; row past the grid packs into another
    ja .dtbad                          ; sheet's key - sh_biff_rcok's refusal
    mov bx, SH_T_IR
.dtin:
    mov ax, [es:si+bx]                 ; an input cell's row...
    cmp ax, SH_TBL_NONE
    je .dtin1
    cmp ax, SH_ROWS
    jae .dtbad
.dtin1:
    mov ax, [es:si+bx+2]               ; ...and its column
    cmp ax, SH_TBL_NONE
    je .dtin2
    cmp ax, SH_COLS
    jae .dtbad
.dtin2:
    test word [es:si+SH_T_FLAGS], SH_TF_TWOD
    jz .dtinok                         ; one input: the second pair is the
    add bx, 4                          ; format's unused one, and is set to
    cmp bx, SH_T_IR2                   ; SH_TBL_NONE below whatever it held
    jbe .dtin
    jmp short .dtinok
.dtbad:
    jmp .skip
.dtinok:
    push ax
    push bx
    push cx
    push dx                            ; `mul` BELOW WRITES DX, and DX is this
                                       ; loop's record LENGTH - `.skip` adds
                                       ; it to SI. Clobbering it does not
                                       ; corrupt one table, it misparses
                                       ; every record after this one. Fourth
                                       ; of its family in this feature
    push si
    push di
    push es
    push ds
    mov ax, [sh_ntbl]                  ; the destination offset, and the
    mov cx, SH_T_SZ                    ; SEGMENT, both read while DS is still
    mul cx                             ; ours - the lesson of the DS-switch
    mov di, ax                         ; hang, which is one `mov ds` too early
    mov bx, [sh_tblseg]
    push es
    pop ds                             ; DS:SI = the record's body
    mov es, bx
    mov cx, 16
    cld
    rep movsb
    sub di, 16                         ; REP ADVANCES DI, and everything below
                                       ; addresses the record through it - so
                                       ; without this the sheet byte and the
                                       ; input-cell translation land sixteen
                                       ; bytes on, in the NEXT record's space
    pop ds
    pop es
    mov bx, [sh_tblseg]
    push es
    mov es, bx
    mov ax, [sh_rd_sheet]              ; which sheet this substream is
    or ax, ax
    jns .dtsheet
    mov ax, [sh_cursheet]              ; a plain stream lands on the user's
.dtsheet:
    mov [es:di+SH_T_SHEET], al
    ; ...AND THE INPUT CELLS COME BACK THE OTHER WAY (81.114.10). The format
    ; names a one-input table's single cell in the FIRST pair whichever kind
    ; it is, with option bit 2 giving the orientation; this app's engine
    ; wants the ROW input in the first pair and the COLUMN input in the
    ; second, with SH_TBL_NONE in the unused one. Read verbatim, every
    ; column-input table would come back claiming a ROW input cell and
    ; substitute along the wrong axis.
    test word [es:di+SH_T_FLAGS], SH_TF_TWOD
    jnz .dtdone
    mov word [es:di+SH_T_IR2], SH_TBL_NONE
    mov word [es:di+SH_T_IC2], SH_TBL_NONE
    test word [es:di+SH_T_FLAGS], SH_TF_ROWDATA
    jnz .dtdone                        ; bit 2 set: it IS the row input cell,
                                       ; and the first pair is where it goes
    mov ax, [es:di+SH_T_IR]            ; clear: a COLUMN input cell, so it
    mov [es:di+SH_T_IR2], ax           ; belongs in the second pair here
    mov ax, [es:di+SH_T_IC]
    mov [es:di+SH_T_IC2], ax
    mov word [es:di+SH_T_IR], SH_TBL_NONE
    mov word [es:di+SH_T_IC], SH_TBL_NONE
.dtdone:
    pop es
    inc word [sh_ntbl]
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    jmp .skip
.toolong:
    pop dx
    jmp .done
.skip:
    add si, dx
    jmp .rechdr
.done:
    call sh_tbl_markall                ; 81.114.10: the result cells carry
                                       ; SH_TBL_RESULT, and only now - the
                                       ; DATATABLE can arrive before the
                                       ; cells it describes, and marking as
                                       ; it arrived would mark nothing
    mov ax, [sh_rd_home]               ; a plain single-sheet stream never
    cmp word [sh_rd_sheet], 0          ; touched sh_cursheet, so its cells
    jl .nowb                           ; landed on the user's own sheet and
    xor ax, ax                         ; that stays current; a workbook's
.nowb:                                 ; first sheet is 0, so end there
    mov [sh_cursheet], ax
    mov word [sh_msg], sh_m_loaded
    jmp .out
.rerr:
    call sh_setferr
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_biff_e2b / sh_biff_b2e - THE ERROR CODE, TRANSLATED. AL in, AL out; every
; other register preserved.
;
; SH_C_AUX holds Excel's ERROR.TYPE numbers, 1..7. A BIFF BOOLERR record does
; NOT hold those - it holds the codes of the format's own table, 00H #NULL!,
; 07H #DIV/0!, 0FH #VALUE!, 17H #REF!, 1DH #NAME?, 24H #NUM!, 2AH #N/A.
;
; TWO NUMBERINGS FOR THE SAME SEVEN ERRORS, and this file used to say - at the
; SH_ERR_* definitions and again above the writer - that "the BIFF BOOLERR
; record can carry them without a translation step". It cannot, and it never
; could. A #DIV/0! went out as 02H, which is not a code the format defines,
; and came back in as 02H and was read as ERROR.TYPE 2, which is #DIV/0!
; again. Perfectly symmetric, perfectly wrong, and invisible until 81.38 read
; one of the files from outside.
;
; The plausible-sounding claim is the whole of why it survived review: both
; numberings really are "Excel's own", they really do describe the same seven
; errors, and one of them really is what SH_C_AUX holds.
; -----------------------------------------------------------------------------
section .text
sh_biff_errtab: db 0x00, 0x07, 0x0F, 0x17, 0x1D, 0x24, 0x2A

section SH_MODSEC                      ; 82.16.9
sh_biff_e2b:                          ; ERROR.TYPE 1..7 -> the BIFF code
    push bx
    xor bh, bh
    mov bl, al
    dec bl
    cmp bl, 6
    ja .bad
    mov al, [bx+sh_biff_errtab]
    pop bx
    ret
.bad:
    mov al, 0x0F                      ; an out-of-range code travels as
    pop bx                            ; #VALUE!, which is what a reader that
    ret                               ; cannot place it will show anyway

sh_biff_b2e:                          ; the BIFF code -> ERROR.TYPE 1..7
    push bx
    push cx
    mov cl, al
    xor bx, bx
.l:
    cmp cl, [bx+sh_biff_errtab]
    je .hit
    inc bx
    cmp bx, 7
    jb .l
    mov al, SH_ERR_VALUE              ; an unknown code is still an error, and
    jmp .out                          ; #VALUE! is the honest one to show
.hit:
    mov al, bl
    inc al
.out:
    pop cx
    pop bx
    ret

; sh_biff_rcok - out: CF=0 if [sh_wrec_row] < SH_ROWS and [sh_wrec_col] <
; SH_COLS, CF=1 otherwise. A file's row with bit 14 set would OR into the
; SHEET bits of the packed key (see sh_findcell) and land the cell on a
; DIFFERENT sheet - the same clamp the SYLK reader's .apply performs on X/Y.
; Preserves all registers.
; -----------------------------------------------------------------------------
sh_biff_rcok:
    cmp word [sh_wrec_row], SH_ROWS
    jae .bad
    cmp word [sh_wrec_col], SH_COLS
    jae .bad
    clc
    ret
.bad:
    stc
    ret

; -----------------------------------------------------------------------------
; sh_parseslk - walk every line of a buffer, applying each 'C' record found
; in: SI = buffer start (offset in ES), CX = length; ES = the buffer's
; segment (the caller's job, e.g. sh_doread sets it to sh_stgseg)
; -----------------------------------------------------------------------------
sh_parseslk:
    push ax
    push bx
    push dx
    push si
    push di
    mov di, si
    add di, cx
.lineloop:
    cmp si, di
    jae .donelines
    mov bx, si
.findeol:
    cmp bx, di
    jae .goteol
    mov al, [es:bx]
    cmp al, 13
    je .goteol
    cmp al, 10
    je .goteol
    inc bx
    jmp .findeol
.goteol:
    mov ax, bx
    sub ax, si
    cmp ax, 3                        ; NN is the one record here whose type is
    jb .not2                         ; TWO letters, so its ';' is at +2 and it
    cmp byte [es:si], 'N'            ; has to be tested before the one-letter
    jne .not2                        ; shape below - which is why sh_wr_names
    cmp byte [es:si+1], 'N'          ; wrote these for a release and nothing
    jne .not2                        ; ever read one back (81.10.8)
    cmp byte [es:si+2], ';'
    jne .not2
    push si
    add si, 3
    call sh_parsenrec                ; in: SI=tokens start, BX=line end
    pop si
    jmp .advance
.not2:
    cmp ax, 2
    jb .advance
    cmp byte [es:si+1], ';'
    jne .advance
    cmp byte [es:si], 'C'
    jne .notc
    push si
    add si, 2
    call sh_parsecrec                ; in: SI=tokens start, BX=line end
    pop si
    jmp .advance
.notc:
    cmp byte [es:si], 'F'
    jne .advance
    push si
    add si, 2
    call sh_parsefrec                ; in: SI=tokens start, BX=line end
    pop si
.advance:
    mov si, bx
.skipterm:
    cmp si, di
    jae .lineloop
    mov al, [es:si]
    cmp al, 13
    je .isterm
    cmp al, 10
    je .isterm
    jmp .lineloop
.isterm:
    inc si
    jmp .skipterm
.donelines:
    pop di
    pop si
    pop dx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_parsenrec - one 'NN' record: NN;N<name>;E<R1C1>[:<R1C1>]
; in: SI = start of tokens (right after "NN;"), BX = line end (exclusive);
; ES = the buffer's segment, same as sh_parseslk's caller set
;
; This is the other half of sh_wr_names, and it was missing. Sheet wrote these
; records so CHART could find a named range (82.15) and never read one itself,
; so a name survived being saved and did not survive being loaded - the file
; was right and the app forgot. Fields are taken in any order, like the 'C'
; record's, because a SYLK writer is not obliged to emit them in ours.
; -----------------------------------------------------------------------------
sh_parsenrec:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov byte [sh_nm_in], 0
    mov word [sh_nm_row], 0xFFFF      ; "no ;E field seen yet"
.tok:
    cmp si, bx
    jae .done
    mov al, [es:si]
    inc si
    cmp al, 'N'
    je .isn
    cmp al, 'E'
    je .ise
.scan:                                ; a field this reader has no use for
    cmp si, bx
    jae .done
    cmp byte [es:si], ';'
    je .fieldend
    inc si
    jmp .scan
.isn:
    mov di, sh_nm_in
    mov cx, SH_NAME_MAX
.ncp:
    cmp si, bx
    jae .nend
    mov al, [es:si]
    cmp al, ';'
    je .nend
    cmp al, 13
    je .nend
    cmp al, 10
    je .nend
    jcxz .nskip                       ; past what the table holds: keep the
    mov [di], al                      ; first SH_NAME_MAX and go on reading
    inc di                            ; the field, so the ';' after it is
    dec cx                            ; still found
.nskip:
    inc si
    jmp .ncp
.nend:
    mov byte [di], 0
    jmp .fieldend
.ise:
    call sh_slk_r1c1
    jc .done
    mov [sh_nm_row], ax
    mov [sh_nm_col], dx
    mov [sh_nm_row2], ax              ; a one-cell name is the same rectangle
    mov [sh_nm_col2], dx              ; with both corners equal
    cmp si, bx
    jae .fieldend
    cmp byte [es:si], ':'
    jne .fieldend
    inc si
    call sh_slk_r1c1
    jc .fieldend                      ; a broken far corner still leaves a
    mov [sh_nm_row2], ax              ; usable one-cell name rather than
    mov [sh_nm_col2], dx              ; discarding the record
.fieldend:
    cmp si, bx
    jae .done
    cmp byte [es:si], ';'
    jne .done
    inc si
    jmp .tok
.done:
    cmp byte [sh_nm_in], 0            ; a record with no ;N or no ;E defines
    je .out                           ; nothing
    cmp word [sh_nm_row], 0xFFFF
    je .out
    mov ax, [sh_nm_row2]
    cmp ax, SH_ROWS
    jae .out
    mov ax, [sh_nm_col2]
    cmp ax, SH_COLS
    jae .out
    cmp word [sh_nm_row], SH_ROWS     ; ...and the NEAR corner, which is just
    jae .out                          ; as much the file's: a row past the
    cmp word [sh_nm_col], SH_COLS     ; grid carries into the sheet bits of
    jae .out                          ; the packed key
    mov si, sh_nm_in
    mov ax, [sh_nm_col]
    mov bx, [sh_nm_row]
    mov cx, [sh_nm_col2]
    mov dx, [sh_nm_row2]
    SHOUT sh_name_def                  ; CF=1 = the table is full; the rest of
.out:                                 ; the file still loads
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_slk_r1c1 - one absolute R1C1 reference at ES:SI, the notation sh_wr_r1c1
; emits. in: BX = limit. out: AX = 0-based row, DX = 0-based column, SI past
; it; CF=1 = not one, and SI is wherever it gave up.
;
; R1C1 is ONE-BASED, so R0 or C0 is refused rather than wrapped to 65535 by
; the decrement.
; -----------------------------------------------------------------------------
sh_slk_r1c1:
    push cx
    push di
    cmp si, bx
    jae .bad
    cmp byte [es:si], 'R'
    jne .bad
    inc si
    mov di, si
    SHOUT sh_pint                      ; no CF of its own: SI not moving is
    cmp si, di                        ; what "no digits" looks like
    je .bad
    or ax, ax
    jle .bad
    dec ax
    mov cx, ax                        ; bank the row - sh_pint returns in AX
    cmp si, bx
    jae .bad
    cmp byte [es:si], 'C'
    jne .bad
    inc si
    mov di, si
    SHOUT sh_pint
    cmp si, di
    je .bad
    or ax, ax
    jle .bad
    dec ax
    mov dx, ax
    mov ax, cx
    clc
    jmp .out
.bad:
    stc
.out:
    pop di
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_parsecrec - the fields of one 'C' record, order-independent
; in: SI = start of tokens (right after "C;"), BX = line end (exclusive);
; ES = the buffer's segment, same as sh_parseslk's caller set
; -----------------------------------------------------------------------------
sh_parsecrec:
    push ax
    push bx
    push si
    mov word [SH_TCOL], 0
    mov word [SH_TROW], 0
    mov word [SH_TVAL], 0
    mov byte [SH_THASE], 0
    mov byte [SH_TISTXT], 0
    mov byte [SH_TISERR], 0
    mov word [SH_TDVAL], 0
    mov word [SH_TDVAL+2], 0
    mov word [SH_TDVAL+4], 0
    mov word [SH_TDVAL+6], 0
    mov byte [SH_THAVE], 0
    mov byte [sh_notetext], 0          ; no ;A field yet (81.119.2): the note
                                       ; dialog's own buffer, as the BIFF
                                       ; reader's .isnote uses it - no dialog
                                       ; is open during a read
.tok:
    cmp si, bx
    jae .apply
    mov al, [es:si]
    cmp al, ';'
    je .skipsemi
    cmp al, 'X'
    je .isx
    cmp al, 'Y'
    je .isy
    cmp al, 'K'
    je .isk
    cmp al, 'E'
    je .ise
    cmp al, 'A'
    je .isa
.scan:
    cmp si, bx
    jae .apply
    mov al, [es:si]
    inc si
    cmp al, ';'
    jne .scan
    jmp .tok
.skipsemi:
    inc si
    jmp .tok
.isx:
    inc si
    SHOUT sh_pint
    mov [SH_TCOL], ax
    jmp .tok
.isy:
    inc si
    SHOUT sh_pint
    mov [SH_TROW], ax
    jmp .tok
.isk:
    inc si
    cmp si, bx                        ; stage 4.5: a QUOTED K field is a label.
    jae .knum                         ; SYLK has no type field - the quotes are
    cmp byte [es:si], '#'             ; the entire signal, on both sides, and
    je .kerr                          ; a leading '#' is an ERROR VALUE for
    cmp byte [es:si], 34              ; the same reason
    jne .knum
    inc si                            ; past the opening quote
    push di
    mov di, sh_rwsrc                  ; sh_rwsrc, NOT SH_TEXPR - the same
    mov cx, SH_EDITMAX                ; correction .kerr below already carries,
                                      ; and for the same reason. This used to
                                      ; say "the same buffer ;E uses, and never
                                      ; at the same time: a label has no
                                      ; formula", which is true of a LABEL and
                                      ; false of A FORMULA WHOSE RESULT IS
                                      ; TEXT. That cell writes both fields -
                                      ; `;EVLOOKUP("SU",...);K"Mulcahy"` - with
                                      ; ;E first, so the cached text landed on
                                      ; top of the formula and the cell loaded
                                      ; as `=Mulcahy`, which is #NAME?.
                                      ;
                                      ; Every text-returning function was
                                      ; affected - UPPER, LEFT, TEXT, the
                                      ; lookups when they find a label - and
                                      ; only on the RELOAD, so the sheet that
                                      ; wrote the file was still right on
                                      ; screen. 81.22 made a formula able to
                                      ; answer with text long after this loop
                                      ; was written, and nothing came back to
                                      ; re-read the premise.
.kt:
    jcxz .ktend
    cmp si, bx
    jae .ktend
    mov al, [es:si]
    cmp al, 13
    je .ktend
    cmp al, 10
    je .ktend
    cmp al, 34
    jne .ktsemi
    inc si                            ; a quote: doubled means one literal
    cmp si, bx                        ; quote, single means end of field
    jae .ktend
    cmp byte [es:si], 34
    jne .ktend
    jmp .ktkeep
.ktsemi:
    cmp al, ';'                       ; ...and the SEMICOLON is the same rule,
    jne .ktkeep                       ; which this loop did not know: it is
    inc si                            ; the field separator, so a doubled one
    cmp si, bx                        ; is one literal ';' and a single one
    jae .ktend                        ; ends the field even inside the quotes
    cmp byte [es:si], ';'
    jne .ktend
.ktkeep:
    mov [di], al
    inc di
    inc si
    dec cx
    jmp .kt
.ktend:
    mov byte [di], 0
    pop di
    mov byte [SH_TISTXT], 1
    mov byte [SH_THAVE], 1
    jmp .tok
.kerr:
    push di                           ; the name goes into sh_rwsrc, NOT into
    mov di, sh_rwsrc                  ; SH_TEXPR: a FORMULA cell writes both
    mov cx, SH_EDITMAX                ; ;E and ;K, ;E comes first, and parsing
                                       ; the ;K into ;E's buffer overwrote the
                                       ; formula with the error's name - which
                                       ; then went in as the cell's formula,
                                       ; `=#DIV/0!`, and evaluated to #VALUE!
.ke:
    jcxz .keend
    cmp si, bx
    jae .keend
    mov al, [es:si]
    cmp al, ';'
    je .keend
    cmp al, 13
    je .keend
    cmp al, 10
    je .keend
    mov [di], al
    inc di
    inc si
    dec cx
    jmp .ke
.keend:
    mov byte [di], 0
    pop di
    push si
    mov si, sh_rwsrc
    call sh_errcode                   ; -> AL, 0 for a spelling we do not know
    pop si
    mov [SH_TISERR], al
    mov byte [SH_THAVE], 1
    jmp .tok
.knum:
    call sh_esatof                    ; a full decimal, not an integer
    push ax
    push si
    push di
    mov si, sh_acc
    mov di, SH_TDVAL
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    pop si
    pop ax
    mov byte [SH_THAVE], 1
    jmp .tok
.ise:
    inc si
    push di                           ; the expression, copied out of the
    mov di, SH_TEXPR                  ; staging segment into DS so the R1C1
    mov cx, SH_EDITMAX                ; converter can read it
.ecpy:
    jcxz .ecpyd
    cmp si, bx
    jae .ecpyd
    mov al, [es:si]
    cmp al, ';'                       ; the field separator ends it - unless
    jne .ecnl                         ; DOUBLED, Walden's escape, which is one
    inc si                            ; literal ';' - in a string constant, the
    cmp si, bx                        ; one place a formula can hold one. This
    jae .ecpyd                        ; loop took the first of the pair as the
    cmp byte [es:si], ';'             ; field's end, as .kt did for labels
    jne .ecpyd                        ; until 81.38.1
    jmp short .eckeep
.ecnl:
    cmp al, 13
    je .ecpyd
    cmp al, 10
    je .ecpyd
.eckeep:
    mov [di], al
    inc di
    inc si
    dec cx
    jmp .ecpy
.ecpyd:
    mov byte [di], 0
    pop di
    mov byte [SH_THASE], 1
    jmp .tok
.isa:                                 ; ;A<text> - the cell's comment, which is
    inc si                            ; its NOTE (81.119.2). It runs to a single
    push di                           ; ';' or the line's end; ';;' is one ';'
    push cx                           ; and ESC " :" a line break. The whole
    mov di, sh_notetext               ; field is consumed and the first
    mov cx, SH_NOTEMAX - 1            ; SH_NOTEMAX - 1 bytes kept, so a long
.ac:                                  ; one cannot leave its tail to be read
    cmp si, bx                        ; as fields
    jae .acend
    mov al, [es:si]
    inc si
    cmp al, ';'
    jne .anotsemi
    cmp si, bx
    jae .acend
    cmp byte [es:si], ';'
    jne .acback                       ; a single ';' ends the field
    inc si
    jmp short .akeep
.anotsemi:
    cmp al, 27
    jne .akeep
    mov ax, si
    add ax, 2
    cmp ax, bx
    ja .akeep27
    cmp word [es:si], ' ' | (':' << 8)
    jne .akeep27
    add si, 2
    mov al, 10
    jmp short .akeep
.akeep27:
    mov al, 27
.akeep:
    jcxz .ac
    mov [di], al
    inc di
    dec cx
    jmp short .ac
.acback:
    dec si                            ; leave the ';' for the field scan
.acend:
    mov byte [di], 0
    pop cx
    pop di
    jmp .tok
.apply:
    cmp byte [SH_THAVE], 0
    jne .applyok
    cmp byte [sh_notetext], 0         ; a note alone is still worth the
    je .out                           ; coordinates
.applyok:
    mov ax, [SH_TCOL]
    cmp ax, 1
    jb .out
    cmp ax, SH_COLS
    ja .out
    mov cx, [SH_TROW]
    cmp cx, 1
    jb .out
    cmp cx, SH_ROWS
    ja .out
    dec ax
    dec cx
    mov bx, cx
    cmp byte [sh_notetext], 0         ; the note first: it stands whether or
    je .nonote                        ; not the record also carries a value
    push si
    mov si, sh_notetext
    SHOUT sh_nt_set                    ; CF = 1 table or arena full: dropped,
    pop si                            ; as a typed one would be
.nonote:
    cmp byte [SH_THAVE], 0
    je .out
    cmp byte [SH_THASE], 0            ; a ;E field wins over ;K: the value is
    je .notformula_c                  ; only the cached result of it, and
    push ax                           ; storing that instead would flatten the
    push bx                           ; formula exactly as this used to
    push si
    push di
    mov [sh_rc_ccol], ax
    mov [sh_rc_crow], bx
    mov si, SH_TEXPR
    call sh_formula_from_r1c1
    pop di
    pop si
    pop bx
    pop ax
    mov si, sh_rwdst                  ; AFTER the pops: setting SI before them
    SHOUT sh_setformula                ; put the saved value straight back over
                                      ; it, and sh_setformula stored whatever
                                      ; the staging pointer happened to be
    jmp .out
.notformula_c:
    cmp byte [SH_TISERR], 0
    je .noterr_c
    mov dl, [SH_TISERR]
    SHOUT sh_seterr
    jmp .out
.noterr_c:
    cmp byte [SH_TISTXT], 0
    je .plainval_c
    push si
    mov si, sh_rwsrc                  ; where .isk's quoted ;K now lands
    SHOUT sh_setlabel                 ; "TRUE" quoted is the LOGICAL: Walden
    pop si                            ; quotes both, so the spelling decides,
    jmp .out                          ; as it does when one is typed (81.51)
.plainval_c:
    push si
    push di
    mov si, SH_TDVAL
    mov di, sh_acc
    push ax
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop ax
    pop di
    pop si
    SHOUT sh_setvald
.out:
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_parsefrec - the fields of an "F" (formatting) record, stage 1.6's real
; SYLK support. In: SI = start of tokens (right after "F;"), BX = line end
; (exclusive); ES = the buffer's segment. Real SYLK's F record predates
; MultiPlan-era bold/underline entirely (this book's own field list never
; mentions either), so only alignment (;F's c2 code) and number format
; (;F's c1 code, plus the separate ;K comma flag) round-trip through SYLK -
; matching the same "only what the real format actually has" principle
; DIF's fix above just established. The cell itself must already exist
; (from an earlier C record) for this to do anything, per SYLK's own
; documented convention that referenced things are defined before use -
; this app's own writer always emits a formatted cell's C record first for
; exactly that reason.
; -----------------------------------------------------------------------------
sh_parsefrec:
    push ax
    push bx
    push cx
    push dx
    push si
    push di                           ; sh_findcell below is called for its
                                       ; side effect on DI, but sh_parseslk's
                                       ; caller keeps its own buffer-end in
                                       ; DI live across this whole call - it
                                       ; must come back unchanged
    mov word [SH_TCOL], 0
    mov word [SH_TROW], 0
    mov byte [SH_TALIGN], 0
    mov byte [SH_TNUMFMT], 0
    mov byte [SH_TCOMMA], 0
    xor dx, dx                        ; DL = ;S's border bits, DH = 1 once a
                                       ; ;F or ;K says something about the
                                       ; format (81.119.2) - registers, as
                                       ; nothing this calls touches DX
.tok:
    cmp si, bx
    jae .apply
    mov al, [es:si]
    cmp al, ';'
    je .skipsemi
    cmp al, 'X'
    je .isx
    cmp al, 'Y'
    je .isy
    cmp al, 'F'
    je .isf
    cmp al, 'K'
    je .isk
    cmp al, 'W'
    je .isw
    cmp al, 'S'
    je .iss
.scan:
    cmp si, bx
    jae .apply
    mov al, [es:si]
    inc si
    cmp al, ';'
    jne .scan
    jmp .tok
.skipsemi:
    inc si
    jmp .tok
.isx:
    inc si
    SHOUT sh_pint
    mov [SH_TCOL], ax
    jmp .tok
.isy:
    inc si
    SHOUT sh_pint
    mov [SH_TROW], ax
    jmp .tok
.isk:
    inc si
    mov byte [SH_TCOMMA], 1
    mov dh, 1
    jmp .tok
.iss:                                  ; ;S<letters> - the style field. L R T
    inc si                             ; B are the edges and S is shaded
.sl:                                   ; (81.119.2); D, I, M and any digits
    cmp si, bx                         ; are Excel's bold, italic and font,
    jae .tok                           ; and are passed over
    mov al, [es:si]
    cmp al, ';'
    je .tok
    inc si
    push si
    mov si, sh_sylk_bordch
    mov ah, 1
.sfind:
    cmp byte [si], 0
    je .snone
    cmp al, [si]
    je .shit
    inc si
    shl ah, 1
    jmp short .sfind
.shit:
    or dl, ah
.snone:
    pop si
    jmp short .sl
.isw:                                  ; ;W<first> <last> <width>: column
    inc si                             ; widths, Walden's F-record field (7)
    SHOUT sh_pint                      ; (81.56). 1-based, spaces between
    push ax
    inc si
    SHOUT sh_pint
    push ax
    inc si
    SHOUT sh_pint
    call sh_cwbyte                     ; CL = what the table keeps
    pop di                             ; DI = the last
    pop ax                             ; AX = the first
.wl:
    cmp ax, di
    ja .tok
    or ax, ax
    jz .wn
    cmp ax, 256
    ja .tok
    dec ax
    SHOUT sh_colw_set
    inc ax
.wn:
    inc ax
    jmp short .wl
.isf:                                  ; ;F<c1>[space]<digits>[space]<c2> -
                                        ; one field, not semicolon-delimited
                                        ; internally, so it's parsed as its
                                        ; own little grammar before control
                                        ; returns to the outer ;-scan loop
    mov dh, 1
    inc si
    cmp si, bx
    jae .tok
    mov al, [es:si]
    call sh_sylk_numfmt_from_c1
    mov [SH_TNUMFMT], al
    inc si
    cmp si, bx
    jae .tok
    cmp byte [es:si], ' '
    jne .fdigits
    inc si
.fdigits:
    cmp si, bx
    jae .tok
    mov al, [es:si]
    cmp al, '0'
    jb .fspace2
    cmp al, '9'
    ja .fspace2
    inc si
    jmp .fdigits
.fspace2:
    cmp si, bx
    jae .tok
    cmp byte [es:si], ' '
    jne .fc2
    inc si
.fc2:
    cmp si, bx
    jae .tok
    mov al, [es:si]
    call sh_sylk_align_from_c2
    mov [SH_TALIGN], al
    inc si
    jmp .tok
.apply:
    mov ax, [SH_TCOL]
    cmp ax, 1
    jb .out
    cmp ax, SH_COLS
    ja .out
    mov cx, [SH_TROW]
    cmp cx, 1
    jb .out
    cmp cx, SH_ROWS
    ja .out
    dec ax
    dec cx
    mov bx, cx
    or dl, dl                         ; a border needs no cell (81.119.2), and
    jz .nobord                        ; it is ORed into the border bits, so
    SHOUT sh_bt_addcell                ; SH_BT_KEEP's protection and table bits
    jc .nobord                        ; are never written; table full:
    push es                           ; dropped, as a typed one would be
    mov es, [sh_bordseg]
    or [es:di+4], dl
    pop es
.nobord:
    or dh, dh                         ; a style-only record says nothing
    jz .out                           ; about the format: leave it alone
    SHOUT sh_findcell
    jnc .out                          ; no prior C record for this cell:
                                       ; nothing to attach the format to
    mov al, [SH_TNUMFMT]
    cmp byte [SH_TCOMMA], 0
    je .noupgrade
    or al, al
    jnz .noupgrade                    ; ;K only promotes a still-General
                                       ; code to Comma - an explicit c1 of
                                       ; '$' (Currency) wins if both appear
    mov al, SH_FMT_NUM_COMMA
.noupgrade:
    mov cl, SH_FMT_NUM_SHIFT
    shl al, cl
    mov ah, [SH_TALIGN]
    mov cl, SH_FMT_ALIGN_SHIFT
    shl ah, cl
    or al, ah
    push es
    mov es, [sh_cellseg]
    mov [es:di+5], al
    pop es
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sylk_numfmt_from_c1 - in: AL = an F record's c1 formatting-code char;
; out: AL = this app's SH_FMT_NUM_* code. Real SYLK's c1 codes are
; 0/C/E/F/G/$/*/% (default/continuous/scientific/fixed/general/currency/
; bargraph/percent) - '$' and '%' have equivalents here; everything else
; (including the codes this app never writes, like scientific or bargraph)
; falls back to General, which is the honest answer since this app has no
; comparable format for them either.
; -----------------------------------------------------------------------------
sh_sylk_numfmt_from_c1:
    cmp al, '$'
    je .cur
    cmp al, '%'                       ; percent, which SYLK does have (81.119.2)
    je .pct
    xor al, al
    ret
.cur:
    mov al, SH_FMT_NUM_CURRENCY
    ret
.pct:
    mov al, SH_FMT_NUM_PERCENT
    ret

; -----------------------------------------------------------------------------
; sh_sylk_align_from_c2 - in: AL = an F record's c2 alignment-code char
; ('0' default, 'C' center, 'G' general, 'L' left, 'R' right); out: AL =
; this app's SH_FMT_ALIGN_* code
; -----------------------------------------------------------------------------
sh_sylk_align_from_c2:
    cmp al, 'L'
    je .left
    cmp al, 'C'
    je .center
    cmp al, 'R'
    je .right
    xor al, al
    ret
.left:
    mov al, SH_FMT_ALIGN_LEFT
    ret
.center:
    mov al, SH_FMT_ALIGN_CENTER
    ret
.right:
    mov al, SH_FMT_ALIGN_RIGHT
    ret

; -----------------------------------------------------------------------------
; sh_pint - parse a signed decimal integer
; in: ES:SI=ptr, BX=limit (exclusive, an offset); also stops at NUL
; out: AX=value, SI=advanced; BX preserved; ES must be set by the caller
; -----------------------------------------------------------------------------
section .text
sh_pint:
    push bx
    push cx
    push dx
    xor cx, cx
    xor ax, ax
    cmp si, bx
    jae .fin
    cmp byte [es:si], '-'
    jne .digits
    mov cx, 1
    inc si
.digits:
    cmp si, bx
    jae .fin
    mov dl, [es:si]
    or dl, dl
    jz .fin
    cmp dl, '0'
    jb .fin
    cmp dl, '9'
    ja .fin
    sub dl, '0'
    xor dh, dh
    push dx
    push bx
    mov bx, 10
    mul bx
    pop bx
    pop dx
    add ax, dx
    inc si
    jmp .digits
.fin:
    or cx, cx
    jz .nosign
    neg ax
.nosign:
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_setferr - build "Err N" from a FERR_* code and point sh_msg at it
; in: AX = FERR_* (CF was set on the API call that produced it)
; -----------------------------------------------------------------------------
section SH_MODSEC                      ; 82.16.9
sh_setferr:
    push di
    push si
    mov di, sh_errbuf
    mov si, sh_s_errpfx
    SHOUT sh_strcpy_to_di              ; DI advances past "Err " to the new NUL
    SHOUT sh_itoa                      ; AX (the FERR_* code) -> sh_numbuf;
                                       ; preserves DI
    mov si, sh_numbuf
    SHOUT sh_strcpy_to_di
    mov word [sh_msg], sh_errbuf
    pop si
    pop di
    ret

; =============================================================================
; Cell storage - a sorted array of (row, col, flags, format, value,
; formula_off, pass) records in the claimed sh_cellseg, searched with a
; binary search and kept sorted by shifting on insert/remove. 12 bytes/rec:
;   +0 row (word) - stage 2.0: PACKED, not a plain row. Bits 0-13 are the
;   real row (0..16383, SH_ROW_MASK); bits 14-15 are the sheet index
;   (0..SH_SHEETS-1). Sorting and searching a plain 16-bit compare on this
;   word therefore sorts every sheet's records into one contiguous run,
;   ordered first by sheet and then by row within it, with NO change to the
;   comparison logic itself - only the few places that construct or take
;   apart the word (sh_findcell packing it from [sh_cursheet], sh_unpackrow
;   splitting it back out for the SYLK/DIF/BIFF writers, which must skip
;   every sheet but the one being saved) know this isn't just a row.
;   +2 col (word)  +4 flags (byte)  +5 format (byte, the
;   SH_FMT_* bits, stage 1.6 - this byte was unused padding before)
;   +6 value (word)  +8 formula_off (word, 0xFFFF=none)  +10 pass (word)
; Only three routines (sh_findcell/sh_addcell/sh_removecell) know this
; layout and the shifting; everything else goes through sh_getcell2/
; sh_setvald/sh_clearcell.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_unpackrow - in: AX = a cell record's packed row/sheet word; out: AX =
; the real row (0..16383), BX = the sheet index it belongs to
; -----------------------------------------------------------------------------
section .text
sh_unpackrow:
    push cx
    mov bx, ax
    mov cl, SH_ROW_BITS
    shr bx, cl
    and ax, SH_ROW_MASK
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_findcell - binary search for (col, row)
; in: AX=col, BX=row
; out: CF=1 found, DI=byte offset of the record
;      CF=0 not found, DI=byte offset where it would be inserted
; -----------------------------------------------------------------------------
sh_findcell:
    push ax
    push bx
    push cx
    push dx
    push si
    mov [sh_fcol], ax
    mov ax, [sh_cursheet]              ; the stored "row" word is really a
    mov cl, SH_ROW_BITS                ; packed (sheet<<SH_ROW_BITS | row) -
    shl ax, cl                         ; see the stage 2.0 comment above the
    or ax, bx                          ; cell record layout - so every
    mov [sh_frow], ax                  ; existing caller of this proc (all
                                        ; of them pass a plain 0..16383 row)
                                        ; keeps working unchanged, searching
                                        ; only the CURRENT sheet's records
    xor cx, cx                        ; CX = lo
    mov dx, [sh_ncells]                ; DX = hi
.loop:
    cmp cx, dx
    jae .notfound
    mov si, dx
    sub si, cx
    shr si, 1
    add si, cx                        ; SI = mid
    mov ax, si
    mov bx, SH_C_SZ
    push dx                           ; MUL clobbers DX (the high word of
    mul bx                            ; the product) - DX is also this
    pop dx                            ; loop's search bound, so it must
    mov di, ax                        ; survive every iteration, not just
                                       ; the one that happens to find a match
                                       ; on its first probe
    push es
    mov es, [sh_cellseg]
    mov ax, [es:di]                   ; candidate row
    mov bx, [es:di+2]                 ; candidate col
    pop es
    cmp ax, [sh_frow]
    jl .lower
    jg .higher
    cmp bx, [sh_fcol]
    jl .lower
    jg .higher
    stc
    jmp .out
.lower:
    mov cx, si
    inc cx
    jmp .loop
.higher:
    mov dx, si
    jmp .loop
.notfound:
    mov ax, cx
    mov bx, SH_C_SZ
    mul bx
    mov di, ax
    clc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_addcell - find or create the record for (col, row)
; in: AX=col, BX=row
; out: CF=0, DI=byte offset of the record (existing or new, zeroed if new)
;      CF=1 the table is full - no new record could be created
; -----------------------------------------------------------------------------
sh_addcell:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push dx
    push si
    mov byte [sh_chartdirty], 1        ; whoever asked is about to write this
                                        ; record - sh_repaint's chart tail
                                        ; reads the byte instead of rescanning
                                        ; the column on every repaint
    call sh_findcell
    jc .found
    cmp word [sh_ncells], SH_CELL_CAP
    jae .full
    push di                            ; insertion offset, kept across the
                                        ; shift below
    mov ax, [sh_ncells]
    mov bx, SH_C_SZ
    mul bx                             ; AX = current end-of-array offset
    mov cx, ax
    sub cx, di                         ; CX = bytes to shift up (may be 0)
    push ds
    push es
    mov dx, [sh_cellseg]
    mov ds, dx
    mov es, dx
    jcxz .noshift
    mov si, ax
    dec si
    mov di, si
    add di, SH_C_SZ
    std
    rep movsb
    cld
.noshift:
    pop es
    pop ds
    pop di                             ; DI = insertion offset, restored
    inc word [sh_ncells]
    push es
    mov es, [sh_cellseg]
    mov ax, [sh_frow]
    mov [es:di], ax
    mov ax, [sh_fcol]
    mov [es:di+2], ax
    mov byte [es:di+4], 0
    mov byte [es:di+5], 0
    mov byte [es:di+SH_C_TYPE], SH_T_NUM
    mov byte [es:di+SH_C_AUX], 0
    mov word [es:di+SH_C_VAL], 0      ; ALL EIGHT value bytes, not just the low
    mov word [es:di+SH_C_VAL+2], 0    ; word the integer model uses today. The
    mov word [es:di+SH_C_VAL+4], 0    ; array is shuffled with a byte move, so
    mov word [es:di+SH_C_VAL+6], 0    ; a "new" record inherits whatever the
                                      ; record above it left here - harmless
                                      ; while only the low word is read, and a
                                      ; genuinely nasty surprise the moment the
                                      ; full double goes live
    mov word [es:di+SH_C_FOFF], 0xFFFF
    mov word [es:di+SH_C_PASS], 0
    pop es
    clc
    jmp .out
.found:
    clc
    jmp .out
.full:
    stc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_removecell - in: AX=col, BX=row; removes the record if present
; -----------------------------------------------------------------------------
sh_removecell:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov byte [sh_chartdirty], 1        ; sh_addcell's reason
    call sh_findcell
    jnc .out
    mov ax, [sh_ncells]
    mov bx, SH_C_SZ
    mul bx                             ; AX = end offset (before shrink)
    mov cx, ax
    sub cx, di
    sub cx, SH_C_SZ                    ; CX = bytes after this record
    push ds
    push es
    mov dx, [sh_cellseg]
    mov ds, dx
    mov es, dx
    jcxz .noshift
    mov si, di
    add si, SH_C_SZ
    cld
    rep movsb
.noshift:
    pop es
    pop ds
    dec word [sh_ncells]
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; Border table (stage 2.x, sh_bordseg claim) - a SEPARATE sparse sorted
; array, same shape and packing convention as the main cell array above
; (sh_findcell's own stage 2.0 comment on the packed row/sheet word applies
; here unchanged) but only SH_BT_SZ bytes/record: +0 packed row/sheet (word)
; +2 col (word) +4 border byte (SH_BORD_* bits) +5 number format (81.55: 0,
; or one of Excel's built-in format ids PLUS ONE). Almost no cell ever has a
; border, so a cell simply has NO record here at all until Format >
; Border... sets one of its bits, and loses its record again the moment
; every bit clears (sh_bt_removecell) - the same "no record = default"
; philosophy the main array already uses for value 0 vs formatted-and-0.
; =============================================================================

; sh_bt_findcell - binary search for (col,row); in AX=col,BX=row;
; out CF=1 found DI=offset, CF=0 not found DI=insertion offset
sh_bt_findcell:
    push ax
    push bx
    push cx
    push dx
    push si
    mov [sh_fcol], ax
    mov ax, [sh_cursheet]
    mov cl, SH_ROW_BITS
    shl ax, cl
    or ax, bx
    mov [sh_frow], ax
    xor cx, cx
    mov dx, [sh_nbord]
.loop:
    cmp cx, dx
    jae .notfound
    mov si, dx
    sub si, cx
    shr si, 1
    add si, cx
    mov ax, si
    mov bx, SH_BT_SZ
    push dx
    mul bx
    pop dx
    mov di, ax
    push es
    mov es, [sh_bordseg]
    mov ax, [es:di]
    mov bx, [es:di+2]
    pop es
    cmp ax, [sh_frow]
    jl .lower
    jg .higher
    cmp bx, [sh_fcol]
    jl .lower
    jg .higher
    stc
    jmp .out
.lower:
    mov cx, si
    inc cx
    jmp .loop
.higher:
    mov dx, si
    jmp .loop
.notfound:
    mov ax, cx
    mov bx, SH_BT_SZ
    mul bx
    mov di, ax
    clc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_bt_addcell - find or create (col,row); in AX=col,BX=row;
; out CF=0 DI=offset (zeroed border byte if new), CF=1 table full
sh_bt_addcell:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push dx
    push si
    call sh_bt_findcell
    jc .found
    cmp word [sh_nbord], SH_BORD_CAP
    jae .full
    push di
    mov ax, [sh_nbord]
    mov bx, SH_BT_SZ
    mul bx
    mov cx, ax
    sub cx, di
    push ds
    push es
    mov dx, [sh_bordseg]
    mov ds, dx
    mov es, dx
    jcxz .noshift
    mov si, ax
    dec si
    mov di, si
    add di, SH_BT_SZ
    std
    rep movsb
    cld
.noshift:
    pop es
    pop ds
    pop di
    inc word [sh_nbord]
    push es
    mov es, [sh_bordseg]
    mov ax, [sh_frow]
    mov [es:di], ax
    mov ax, [sh_fcol]
    mov [es:di+2], ax
    mov word [es:di+4], 0              ; no border, no number format
    pop es
    clc
    jmp .out
.found:
    clc
    jmp .out
.full:
    stc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_bt_removecell - in: AX=col, BX=row
sh_bt_removecell:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    call sh_bt_findcell
    jnc .out
    mov ax, [sh_nbord]
    mov bx, SH_BT_SZ
    mul bx
    mov cx, ax
    sub cx, di
    sub cx, SH_BT_SZ
    push ds
    push es
    mov dx, [sh_bordseg]
    mov ds, dx
    mov es, dx
    jcxz .noshift
    mov si, di
    add si, SH_BT_SZ
    cld
    rep movsb
.noshift:
    pop es
    pop ds
    dec word [sh_nbord]
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_bt_getw - in: AX=col, BX=row; out: AX = the record's word at +4: AL the
; border+protection byte, AH the number format (81.55); 0 when no record
sh_bt_getw:
    push bx
    push di
    push es
    call sh_bt_findcell
    mov ax, 0
    jnc .out
    mov es, [sh_bordseg]
    mov ax, [es:di+4]
.out:
    pop es
    pop di
    pop bx
    ret

; sh_bt_get - in: AX=col, BX=row; out: AL = border byte (0 if no record)
sh_bt_get:
    push bx
    push di
    push es
    call sh_bt_findcell
    jnc .none
    mov es, [sh_bordseg]
    mov al, [es:di+4]
    jmp .out
.none:
    xor al, al
.out:
    pop es
    pop di
    pop bx
    ret

; =============================================================================
; Note table (stage 3.0b, sh_noteseg claim) - Excel 2.1's cell notes, reached
; from Formula > Note... A THIRD sparse sorted array, the same shape as the
; border table above and searched the same way, but 6 bytes/record: +0 packed
; row/sheet (word) +2 col (word) +4 the note text's offset in sh_txtseg
; (word).
;
; THE TEXT LIVES IN THE EXISTING FORMULA ARENA, not in this claim. A note is
; text of unknown length and sh_txt_append already appends exactly that, so this
; table stores an offset into it just as a cell record stores formula_off.
; That arena is APPEND-ONLY and never compacted, so re-editing a note leaks
; its old copy - which is precisely what re-editing a formula has always done,
; so the behaviour is at least consistent, and 8KB is a lot of notes. When the
; arena fills, sh_txt_append returns CF=1 and the edit is refused rather than
; half-applied.
;
; SHEET HOLDS 8 OF MEM_OWNER_MAX's 8, and the kernel refuses a ninth. The
; eight: cellseg, txtseg, stgseg, bordseg (the border table with this note
; table carved into it, 81.94), chartseg, undoseg, CHART.OVL's and, on the
; first macro, MACRO.OVL's. THE REGION IS NOT ONE OF THEM, which this comment
; and three others said it was until 81.102: its record's owner is the
; INSTANCE SLOT, while every data claim's owner word is the region's SEGMENT
; (kernel/memory.inc's mem_own), and the cap counts owner words that match.
; =============================================================================

; sh_nt_findcell - binary search for (col,row); in AX=col,BX=row;
; out CF=1 found DI=offset, CF=0 not found DI=insertion offset
sh_nt_findcell:
    push ax
    push bx
    push cx
    push dx
    push si
    mov [sh_fcol], ax
    mov ax, [sh_cursheet]
    mov cl, SH_ROW_BITS
    shl ax, cl
    or ax, bx
    mov [sh_frow], ax
    xor cx, cx
    mov dx, [sh_nnote]
.loop:
    cmp cx, dx
    jae .notfound
    mov si, dx
    sub si, cx
    shr si, 1
    add si, cx
    mov ax, si
    mov bx, SH_NOTE_REC
    push dx
    mul bx
    pop dx
    mov di, ax
    push es
    mov es, [sh_noteseg]
    mov ax, [es:di]
    mov bx, [es:di+2]
    pop es
    cmp ax, [sh_frow]
    jl .lower
    jg .higher
    cmp bx, [sh_fcol]
    jl .lower
    jg .higher
    stc
    jmp .out
.lower:
    mov cx, si
    inc cx
    jmp .loop
.higher:
    mov dx, si
    jmp .loop
.notfound:
    mov ax, cx
    mov bx, SH_NOTE_REC
    mul bx
    mov di, ax
    clc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_nt_addcell - find or create (col,row); in AX=col,BX=row;
; out CF=0 DI=offset (zeroed text offset if new), CF=1 table full
sh_nt_addcell:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push dx
    push si
    call sh_nt_findcell
    jc .found
    cmp word [sh_nnote], SH_NOTE_CAP
    jae .full
    push di
    mov ax, [sh_nnote]
    mov bx, SH_NOTE_REC
    mul bx
    mov cx, ax
    sub cx, di
    push ds
    push es
    mov dx, [sh_noteseg]
    mov ds, dx
    mov es, dx
    jcxz .noshift
    mov si, ax
    dec si
    mov di, si
    add di, SH_NOTE_REC
    std
    rep movsb
    cld
.noshift:
    pop es
    pop ds
    pop di
    inc word [sh_nnote]
    push es
    mov es, [sh_noteseg]
    mov ax, [sh_frow]
    mov [es:di], ax
    mov ax, [sh_fcol]
    mov [es:di+2], ax
    mov word [es:di+4], 0
    pop es
    clc
    jmp .out
.found:
    clc
    jmp .out
.full:
    stc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_nt_removecell - in: AX=col, BX=row. Deleting a note orphans its text in
; the arena; see this table's header on why that is the existing behaviour.
sh_nt_removecell:
    mov byte [sh_modified], 1          ; the document changed (81.118)
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    call sh_nt_findcell
    jnc .out
    mov ax, [sh_nnote]
    mov bx, SH_NOTE_REC
    mul bx
    mov cx, ax
    sub cx, di
    sub cx, SH_NOTE_REC
    push ds
    push es
    mov dx, [sh_noteseg]
    mov ds, dx
    mov es, dx
    jcxz .noshift
    mov si, di
    add si, SH_NOTE_REC
    cld
    rep movsb
.noshift:
    pop es
    pop ds
    dec word [sh_nnote]
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_nt_get - in: AX=col, BX=row; out: CF=1 and AX = the note text's offset
; in sh_txtseg; CF=0 and AX undefined if this cell has no note.
sh_nt_get:
    push bx
    push di
    push es
    call sh_nt_findcell
    jnc .none
    mov es, [sh_noteseg]
    mov ax, [es:di+4]
    pop es
    pop di
    pop bx
    stc
    ret
.none:
    pop es
    pop di
    pop bx
    clc
    ret

; sh_nt_set - attach the NUL string at DS:SI to (col,row).
; in: AX=col, BX=row, SI=the text. out: CF=1 = refused (table or arena full).
; An EMPTY string removes the note instead, which is how the dialog's OK
; button clears one - Excel's own Note dialog has no separate Delete.
sh_nt_set:
    push ax
    push bx
    push dx
    push di
    cmp byte [si], 0
    je .clear
    push ax
    push bx
    call sh_txt_append                  ; arena first: if IT has no room the
    jc .fail2                           ; table must not gain a record
    mov dx, ax                          ; dx = the text's arena offset
    pop bx
    pop ax
    call sh_nt_addcell
    jc .fail
    push es
    mov es, [sh_noteseg]
    mov [es:di+4], dx
    pop es
    clc
    jmp .out
.clear:
    call sh_nt_removecell
    clc
    jmp .out
.fail2:
    pop bx
    pop ax
.fail:
    stc
.out:
    pop di
    pop dx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rowcol_op - Insert or delete a whole row or column on the CURRENT
; sheet only. in: AL = 0 insert row / 1 delete row / 2 insert column /
; 3 delete column; BX = the row or column index the operation pivots on
; (the selected cell's own row/col - Edit menu Insert.../Delete... has no
; other way to name one: a pivot is a single index, and a selection that
; spans several rows does not name one).
;
; The cell array is sorted by (sheet, row) then col (see the stage 2.0
; comment above sh_findcell) - shifting a COLUMN can reorder cells WITHIN
; a row relative to their row-mates, which the sorted array's own binary
; search depends on getting right. Rather than hand-roll an in-place
; resort, this stages every record's (sheet, row, col, flags, format,
; value, formula_off) into sh_stgseg with the shift already applied (or
; marked dropped, if inserting pushes a row/col past the edge of the
; grid, or if it sits exactly on a deleted row/col), empties the whole
; array, then re-inserts every staged record through sh_addcell (which
; already keeps the array sorted on every insert, so re-insertion order
; doesn't matter). Formula TEXT is untouched - only the cell record's own
; formula_off is carried over as-is, so an existing formula's cell
; references are NOT relatively adjusted by this operation (same scope
; reasoning as sh_docmd_fillright/sh_docmd_sortcol); its cached value is
; simply left to go stale, since sh_addcell's own default pass=0 on the
; fresh record forces a re-evaluation on the next paint regardless.
; -----------------------------------------------------------------------------
sh_rowcol_op:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov [sh_rc_op], al
    mov [sh_rc_idx], bx
    call sh_colw_shift                ; a column's WIDTH goes with it (81.56)
    call sh_rc_sides                  ; ...and its borders and notes (81.58)
    call sh_tbl_rc_adj                ; ...and 81.114.9's table RECTANGLES.
                                      ; AFTER sh_rc_sides and not before: a
                                      ; table this drops has to unmark its
                                      ; result cells, and those marks are in
                                      ; the border table that the line above
                                      ; has just moved
    mov word [sh_rc_stgcnt], 0
    mov ax, [sh_cursheet]
    mov [sh_rc_savedsheet], ax
    xor cx, cx
.scan:
    cmp cx, [sh_ncells]
    jae .scandone
    mov ax, cx
    mov bx, SH_C_SZ
    mul bx
    mov si, ax
    mov es, [sh_cellseg]
    mov ax, [es:si]
    call sh_unpackrow                 ; ax=row, bx=sheet
    mov [sh_rc_trow], ax
    mov [sh_rc_tsheet], bx
    mov ax, [es:si+2]
    mov [sh_rc_tcol], ax
    mov al, [es:si+4]
    mov [sh_rc_tflags], al
    mov al, [es:si+5]
    mov [sh_rc_tfmt], al
    mov al, [es:si+SH_C_TYPE]
    mov [sh_rc_ttype], al
    mov al, [es:si+SH_C_AUX]
    mov [sh_rc_taux], al
    push di
    push cx
    mov di, sh_rc_tval
    mov cx, 4
.rcget:
    mov ax, [es:si+SH_C_VAL]
    mov [di], ax
    add si, 2
    add di, 2
    dec cx
    jnz .rcget
    sub si, 8
    pop cx
    pop di
    mov ax, [es:si+SH_C_FOFF]
    mov [sh_rc_tfml], ax
    mov ax, [sh_rc_tsheet]
    cmp ax, [sh_rc_savedsheet]
    jne .stage                        ; a different sheet: carried unchanged
    mov al, [sh_rc_op]
    cmp al, 0
    je .insrow
    cmp al, 1
    je .delrow
    cmp al, 2
    je .inscol
    jmp .delcol
.insrow:
    mov ax, [sh_rc_trow]
    cmp ax, [sh_rc_idx]
    jb .stage
    inc ax
    cmp ax, SH_ROWS
    jae .next                         ; pushed off the bottom: dropped
    mov [sh_rc_trow], ax
    jmp .stage
.delrow:
    mov ax, [sh_rc_trow]
    cmp ax, [sh_rc_idx]
    jb .stage
    je .next                          ; exactly the deleted row: dropped
    dec ax
    mov [sh_rc_trow], ax
    jmp .stage
.inscol:
    mov ax, [sh_rc_tcol]
    cmp ax, [sh_rc_idx]
    jb .stage
    inc ax
    cmp ax, SH_COLS
    jae .next
    mov [sh_rc_tcol], ax
    jmp .stage
.delcol:
    mov ax, [sh_rc_tcol]
    cmp ax, [sh_rc_idx]
    jb .stage
    je .next
    dec ax
    mov [sh_rc_tcol], ax
.stage:
    mov ax, [sh_rc_stgcnt]
    mov bx, SH_S_SZ                   ; the STAGING record's own size. It is
    mul bx                            ; 20 like SH_C_SZ and this changes no
    mov di, ax                        ; byte - but saying SH_C_SZ here made
    mov es, [sh_stgseg]               ; the two layouts one constant apart
                                       ; from being independent, which is the
                                       ; whole reason they have two names
    mov ax, [sh_rc_tsheet]
    mov [es:di], ax
    mov ax, [sh_rc_trow]
    mov [es:di+2], ax
    mov ax, [sh_rc_tcol]
    mov [es:di+4], ax
    mov al, [sh_rc_tflags]
    mov [es:di+SH_S_FLAGS], al        ; THE STAGING RECORD IS NOT THE CELL
    mov al, [sh_rc_tfmt]              ; RECORD. It is its own SH_S_* layout in
    mov [es:di+SH_S_FMT], al          ; sh_stgseg - which is precisely why
    push si                           ; both are named now: converting this
    push cx                           ; block to the cell offsets by mistake
    mov si, sh_rc_tval                ; was silent, and staged garbage
    mov cx, 4
.stval:
    mov ax, [si]                      ; ALL FOUR value words: .rstval reads
    mov [es:di+SH_S_VAL], ax          ; four back, so staging only one left
    add si, 2                         ; six bytes of whatever sh_stgseg last
    add di, 2                         ; held (file text, a sort) inside every
    dec cx                            ; plain number, on every Insert/Delete
    jnz .stval
    sub di, 8
    pop cx
    pop si
    mov ax, [sh_rc_tfml]
    mov [es:di+SH_S_FML], ax
    mov al, [sh_rc_ttype]             ; the tag and the error code ride too -
    mov [es:di+SH_S_TYPE], al         ; see the SH_S_TYPE comment in the
    mov al, [sh_rc_taux]              ; layout block above
    mov [es:di+SH_S_AUX], al
    inc word [sh_rc_stgcnt]
.next:
    inc cx
    jmp .scan
.scandone:
    mov word [sh_ncells], 0
    xor cx, cx
.reins:
    cmp cx, [sh_rc_stgcnt]
    jae .reinsdone
    mov ax, cx
    mov bx, SH_S_SZ                   ; ...and its other half, for the same
    mul bx                            ; reason
    mov si, ax
    mov es, [sh_stgseg]
    mov ax, [es:si]
    mov [sh_cursheet], ax             ; impersonate this record's own sheet
                                       ; so sh_addcell's sh_findcell packs
                                       ; it correctly (stage 2.0 comment
                                       ; above sh_findcell)
    mov ax, [es:si+2]
    mov [sh_rc_trow], ax
    mov ax, [es:si+4]
    mov [sh_rc_tcol], ax
    mov al, [es:si+SH_S_FLAGS]
    mov [sh_rc_tflags], al
    mov al, [es:si+SH_S_FMT]
    mov [sh_rc_tfmt], al
    push di
    push cx
    mov di, sh_rc_tval
    mov cx, 4
.rstval:
    mov ax, [es:si+SH_S_VAL]
    mov [di], ax
    add si, 2
    add di, 2
    dec cx
    jnz .rstval
    sub si, 8
    pop cx
    pop di
    mov ax, [es:si+SH_S_FML]
    mov [sh_rc_tfml], ax
    mov al, [es:si+SH_S_TYPE]
    mov [sh_rc_ttype], al
    mov al, [es:si+SH_S_AUX]
    mov [sh_rc_taux], al
    mov ax, [sh_rc_tcol]
    mov bx, [sh_rc_trow]
    call sh_addcell
    jc .reinsnext                     ; array full - can't happen (we only
                                       ; ever re-insert as many records as
                                       ; we removed minus drops), stay safe
    mov es, [sh_cellseg]
    mov al, [sh_rc_tflags]
    mov [es:di+4], al
    mov al, [sh_rc_tfmt]
    mov [es:di+5], al
    mov al, [sh_rc_ttype]             ; over sh_addcell's SH_T_NUM default -
    mov [es:di+SH_C_TYPE], al         ; a label keeps being a label, an error
    mov al, [sh_rc_taux]              ; keeps its code
    mov [es:di+SH_C_AUX], al
    push si
    push cx
    mov si, sh_rc_tval
    mov cx, 4
.rcput:
    mov ax, [si]
    mov [es:di+SH_C_VAL], ax
    add si, 2
    add di, 2
    dec cx
    jnz .rcput
    sub di, 8
    pop cx
    pop si
    mov ax, [sh_rc_tfml]
    mov [es:di+SH_C_FOFF], ax
.reinsnext:
    inc cx
    jmp .reins
.reinsdone:
    mov ax, [sh_rc_savedsheet]
    mov [sh_cursheet], ax
    call sh_rowcol_reidx               ; stage 2.x: fix up every formula's
                                        ; own cell references for this same
                                        ; shift - see its own header comment
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; sh_rowcol_reidx and its helpers - stage 2.x: after sh_rowcol_op has
; shifted every cell record's own position, this second pass fixes up the
; TEXT of every formula whose cell references point at or past the pivot,
; so a formula still means what it looked like it meant before the
; insert/delete. Previously (and still true of Fill Right/Down and Sort
; Column, a deliberate scope cut documented at their own call sites)
; formula TEXT was left completely untouched by a row/col shift - only
; the referenced CELLS moved, silently breaking any formula that pointed
; at or past the pivot (a formula "=A1" one row below an inserted row
; kept saying A1 even though the data it meant is now at A2). This pass
; closes that gap for Insert/Delete Row/Column specifically, per direct
; user report.
;
; Method: walk the cell array once (this is now in its POST-shift,
; correct positions), and for every formula cell, copy its text out,
; run it through sh_formula_reidx (a character scanner - not a full
; parse/reserialize - that recognizes exactly the same token shapes the
; real formula grammar does: an optional "SheetN!" prefix, then 1-7
; letters immediately followed by digits is a cell reference; anything
; inside a double-quoted string, per ALERT's own argument, is copied
; byte-for-byte and never scanned), and if the text actually changed,
; appends the new text to the pool (formula text is append-only - see
; sh_setformula's own header comment - so an edit here is "append new,
; abandon old" exactly like every other formula edit already is) and
; repoints the cell record's formula_off at it.
;
; A reference is only ever touched if it is KNOWN to name the sheet this
; whole operation is acting on: either a bare, unprefixed reference
; inside a formula that itself lives on that sheet (the overwhelmingly
; common case - editing your own sheet's own formulas), or an explicit
; "SheetN!" reference naming that sheet from ANYWHERE else. A bare
; reference inside a formula that lives on a DIFFERENT sheet is left
; alone - it means that OTHER sheet's own same cell, never the one being
; shifted.
;
; A reference at exactly the pivot on a DELETE is clamped to stay at the
; pivot (the row/col that used to be one further along now occupies that
; slot) rather than invented as some error value - this project has no
; error-value concept anywhere else either (RK's unsupported subtype and
; a division by zero both degrade the same "closest sane fallback, never
; crash" way).
; =============================================================================

; sh_isletter_at - in: SI; out: CF=1 if [SI] is A-Z or a-z (SI untouched)
sh_isletter_at:
    push ax
    mov al, [si]
    cmp al, '$'                       ; stage 3.0e: '$A$1' starts a reference
    je .yes                           ; just as 'A1' does - the rewriters'
    cmp al, 'A'                       ; scanners enter on this test, so an
    jb .no                            ; absolute ref is invisible to them
                                      ; without it
    cmp al, 'Z'
    jbe .yes
    cmp al, 'a'
    jb .no
    cmp al, 'z'
    ja .no
.yes:
    stc
    jmp .out
.no:
    clc
.out:
    pop ax
    ret

; sh_rw_emit - in: AL = one byte; appends it to sh_rwdst at [sh_rw_di],
; clipping (silently dropping the byte) rather than overrunning the
; buffer - same "clip, don't refuse" policy ALERT's own message copy uses.
;
; The clip is at SH_EDITMAX, NOT at sh_rwdst's own SH_RW_CAP size: every
; consumer of a rewritten formula assumes formula text fits the same
; SH_EDITMAX+1 = 64 bytes a typed formula does - sh_eval_cell's own
; per-recursion-level sh_fbuf slot, sh_beginedit's sh_editbuf,
; sh_docmd_copy's sh_clipbuf, and sh_drawbar's sh_tbuf+16 span are all
; exactly that size. A shift CAN legitimately grow text (row 9 -> 10,
; column Z -> AA), so the extra SH_RW_CAP slack is real working room; but
; letting the RESULT exceed SH_EDITMAX would overrun all four of those
; downstream buffers (sh_setformula/sh_txt_append only bound against the
; whole pool, not against 64), so growth past the cap is dropped here at
; the single choke point every rewriter shares rather than re-checked at
; each of the five call sites.
sh_rw_emit:
    push bx
    push di
    mov bx, [sh_rw_di]
    cmp bx, SH_EDITMAX
    jae .full
    mov di, sh_rwdst
    add di, bx
    mov [di], al
    inc bx
    mov [sh_rw_di], bx
.full:
    pop di
    pop bx
    ret

; sh_txt_append - in: DS:SI = NUL-terminated text (no leading '=');
; out: CF=0 and AX = its new offset in the text pool, or CF=1 if there is
; no room (the pool is left unchanged either way)
sh_txt_append:
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov bx, si
    xor cx, cx
.len:
    cmp byte [bx], 0
    je .havelen
    inc bx
    inc cx
    jmp .len
.havelen:
    mov ax, [sh_txtlen]
    add ax, cx
    inc ax
    cmp ax, SH_TXT_CAP
    ja .noroom
    mov es, [sh_txtseg]
    mov di, [sh_txtlen]
    mov ax, di
    push ax
.copy:
    mov al, [si]
    mov [es:di], al
    inc si
    inc di
    or al, al
    jnz .copy
    mov [sh_txtlen], di
    pop ax
    clc
    jmp .out
.noroom:
    stc
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; sh_reidx_shift - in: AX = a reference's original 0-based row or col,
; BX = the pivot, [sh_rw_op] = sh_rowcol_op's own AL (0 ins-row/1 del-row/
; 2 ins-col/3 del-col); out: AX = the adjusted index
sh_reidx_shift:
    push cx
    push dx
    mov dl, [sh_rw_op]
    test dl, 1
    jnz .delete
    cmp ax, bx
    jb .out
    inc ax
    mov cx, SH_ROWS                    ; an insert that pushes a reference
    cmp dl, 2                          ; PAST the last row or column has moved
    jb .havecap                        ; the cell it names off the sheet, so
    mov cx, SH_COLS                    ; the reference is dead. It used to
.havecap:                              ; clamp to the last real index, which
    cmp ax, cx                         ; silently named different data
    jb .out
    jmp .dead
.delete:
    cmp ax, bx
    jb .out                            ; before the pivot: untouched
    je .dead                           ; ON THE PIVOT: THE CELL IS GONE. This
    dec ax                             ; used to leave the index alone, so the
.out:                                  ; reference quietly started naming
    clc                                ; whatever slid into the vacated slot -
    jmp .ret                           ; a wrong number with nothing to show
.dead:                                 ; for it. #REF! is Excel's answer and
    stc                                ; the whole point of it is that it
.ret:                                  ; cannot be mistaken for a live one
    pop dx
    pop cx
    ret

; sh_reidx_apply - in: [sh_rw_refcol]/[sh_rw_refrow] = the reference as
; parsed, [sh_rw_ostart]/[sh_rw_lettersend]/[sh_rw_refend] = its own text
; spans, [sh_rw_op]/[sh_rw_pivot] = the shift; emits the adjusted
; reference (only the axis [sh_rw_op] actually operates on is
; recomputed - the other axis's ORIGINAL text is copied verbatim, so a
; row-only shift never touches a column's own case/spelling)
sh_reidx_apply:
    push ax
    push bx
    mov al, [sh_rw_op]
    cmp al, 2
    jae .colop
    mov ax, [sh_rw_refrow]             ; INSERT/DELETE SHIFTS AN ABSOLUTE
    mov bx, [sh_rw_pivot]              ; REFERENCE TOO, and that is not an
    call sh_reidx_shift                ; oversight. '$' means "do not adjust
    jc .dead
    mov [sh_rw_refrow], ax             ; when this formula is COPIED"; it does
.rowletcopy:                           ; not mean "keep pointing at row 1 no
                                       ; matter what". Inserting a row above
                                       ; physically moves the referenced cell
                                       ; down, so every reference to it must
                                       ; follow or it silently starts naming
                                       ; different data - '$A$1' becomes
                                       ; '$A$2', exactly as Excel does. The
                                       ; markers are preserved below; only the
                                       ; index moves.
    mov bx, [sh_rw_ostart]             ; ostart is before any '$', so this
.rowletloop:                           ; copy carries the column's marker
    cmp bx, [sh_rw_lettersend]
    jae .rowdigits
    mov al, [bx]
    call sh_rw_emit
    inc bx
    jmp .rowletloop
.rowdigits:
    cmp byte [sh_rw_absr], 0           ; put the row's own '$' back
    je .rownodollar
    mov al, '$'
    call sh_rw_emit
.rownodollar:
    mov ax, [sh_rw_refrow]
    inc ax                             ; back to 1-based display text
    call sh_itoa
    mov bx, sh_numbuf
.rowdigemit:
    mov al, [bx]
    or al, al
    jz .out
    call sh_rw_emit
    inc bx
    jmp .rowdigemit
.colop:
    mov ax, [sh_rw_refcol]             ; same rule for a column insert/delete
    mov bx, [sh_rw_pivot]              ; as for a row - see .rowletcopy above
    call sh_reidx_shift
    jc .dead
    mov [sh_rw_refcol], ax
.colemitstart:
    cmp byte [sh_rw_absc], 0           ; the letters are REGENERATED here, so
    je .colnodollar                    ; the marker has to be re-emitted
    mov al, '$'
    call sh_rw_emit
.colnodollar:
    mov ax, [sh_rw_refcol]
    call sh_colname
    mov bx, sh_colbuf
.colemit:
    mov al, [bx]
    or al, al
    jz .coldigits
    call sh_rw_emit
    inc bx
    jmp .colemit
.coldigits:
    mov bx, [sh_rw_lettersend]
.coldigcopy:
    cmp bx, [sh_rw_refend]
    jae .out
    mov al, [bx]
    call sh_rw_emit
    inc bx
    jmp .coldigcopy
.dead:
    call sh_rw_emitref                 ; the cell this named no longer exists
.out:
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rw_emitref - put the literal "#REF!" in a rewritten formula, in place of
; a reference whose cell is gone. It reads the SAME string sh_errname prints,
; so the text a Delete writes is exactly the text sh_perrlit reads back.
; -----------------------------------------------------------------------------
sh_rw_emitref:
    push ax
    push bx
    mov bx, sh_s_err_ref
.l:
    mov al, [bx]
    or al, al
    jz .out
    call sh_rw_emit
    inc bx
    jmp .l
.out:
    pop bx
    pop ax
    ret

; sh_reidx_cellpart - in: SI at a cell reference's first letter (the
; caller has already confirmed one is there via sh_isletter_at), DL = 1
; adjust this reference (it is known to name the sheet being shifted) or
; 0 leave it exactly as written; out: SI advanced past the whole
; reference (letters and, if any followed, digits) and the reference (or
; the bare word, if a letter run here turns out NOT to be followed by a
; digit - a function name, not a cell reference) emitted to sh_rwdst
; either verbatim or adjusted
sh_reidx_cellpart:
    push ax
    push bx
    push cx
    push dx
    push di
    mov [sh_rw_adj], dl
    mov [sh_rw_ostart], si
    mov byte [sh_rw_absc], 0           ; stage 3.0e: '$' before the letters
    mov byte [sh_rw_absr], 0           ; pins the COLUMN, '$' before the
    cmp byte [si], '$'                 ; digits pins the ROW
    jne .nocoldollar
    mov byte [sh_rw_absc], 1
    inc si
.nocoldollar:
    mov di, sh_ident
    xor cx, cx
.letters:
    mov al, [si]
    cmp al, 'A'
    jb .doneletters
    cmp al, 'Z'
    jbe .isletter
    cmp al, 'a'
    jb .doneletters
    cmp al, 'z'
    ja .doneletters
.isletter:
    cmp cx, 7
    jae .doneletters
    mov ah, al
    and ah, 0xDF
    mov [di], ah
    inc di
    inc cx
    inc si
    jmp .letters
.doneletters:
    mov byte [di], 0
    mov [sh_rw_lettersend], si
    cmp byte [si], '$'
    jne .norowdollar
    mov byte [sh_rw_absr], 1
    inc si
.norowdollar:
    mov al, [si]
    cmp al, '0'
    jb .notref
    cmp al, '9'
    ja .notref
    mov bx, si                         ; 81.35: letters, digits, then '(' is
.fndig:                                ; a FUNCTION (LOG10, ATAN2), not a
    inc bx                             ; reference - the parser's own rule,
    mov al, [bx]                       ; so a shift never rewrites the name
    cmp al, '0'
    jb .fnend
    cmp al, '9'
    jbe .fndig
.fnend:
    cmp al, '('
    jne .isref
    mov si, bx                         ; the whole name goes out verbatim
    jmp .notref
.isref:
    call sh_identcol                   ; ax = 0-based col (from sh_ident)
    mov [sh_rw_refcol], ax
    mov bx, si
    add bx, SH_EDITMAX + 1
    push es
    mov ax, ds
    mov es, ax
    call sh_pint                       ; ax = 1-based row text; si advances
    pop es
    dec ax                             ; ax = 0-based row
    mov [sh_rw_refrow], ax
    mov [sh_rw_refend], si
    cmp byte [sh_rw_adj], 0
    je .verbatim
    call sh_reidx_apply
    jmp .out
.verbatim:
    mov bx, [sh_rw_ostart]
.vcopy:
    cmp bx, si
    jae .out
    mov al, [bx]
    call sh_rw_emit
    inc bx
    jmp .vcopy
.notref:
    mov bx, [sh_rw_ostart]
.wcopy:
    cmp bx, si
    jae .out
    mov al, [bx]
    call sh_rw_emit
    inc bx
    jmp .wcopy
.out:
    pop di
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; A1 <-> R1C1, for SYLK's ;E field (stage 4.x)
;
; SYLK CARRIES FORMULAS IN R1C1 RELATIVE FORM, not in the A1 form this app
; stores and shows. That is not a preference - it is what the format is, and a
; real file from the period reads
;
;     C;X3;E+R[-6]C[-1]-RC[-1];K100.73
;
; where R[-6]C[-1] is "six rows up, one column left" of the cell being defined.
; An ABSOLUTE reference has no brackets: R6C3 means row 6, column 3 outright,
; which is exactly what '$' means in A1 form - so the two notations carry the
; same distinction and it survives the trip.
;
; Both directions reuse sh_formula_reidx's scanner shape: walk the text, copy
; everything that is not a reference verbatim, and transform the references.
; A quoted string is passed through untouched, as it is there.
;
; THE CROSS-SHEET PREFIX IS AN EXTENSION. SYLK has no notion of a second sheet
; - it is a single-grid format - so "Sheet2!" is written through verbatim. It
; round-trips within this app and means nothing to anything else, which is the
; honest position: the alternative is silently dropping the reference.
; =============================================================================

; sh_emit_num - AX as signed decimal, into sh_rwdst via sh_rw_emit
section SH_MODSEC                      ; 82.16.9
sh_emit_num:
    push ax
    push bx
    SHOUT sh_itoa
    mov bx, sh_numbuf
.e:
    mov al, [bx]
    or al, al
    jz .o
    SHOUT sh_rw_emit
    inc bx
    jmp .e
.o:
    pop bx
    pop ax
    ret

; sh_emit_rc - one R or C part. in: AL = 'R' or 'C', BX = the value,
; CL = 0 relative (bracketed offset, omitted entirely when zero) or 1 absolute
; (a bare 1-based index).
sh_emit_rc:
    push ax
    push bx
    SHOUT sh_rw_emit                   ; the letter itself
    or cl, cl
    jnz .abs
    or bx, bx
    jz .out                           ; a zero offset is written as nothing:
    mov al, '['                       ; "RC" means "this row, this column"
    SHOUT sh_rw_emit
    mov ax, bx
    call sh_emit_num
    mov al, ']'
    SHOUT sh_rw_emit
    jmp .out
.abs:
    mov ax, bx
    inc ax                            ; absolute parts are 1-based
    call sh_emit_num
.out:
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_formula_to_r1c1 - in: SI = A1-form formula text (no leading '='),
; [sh_rc_ccol]/[sh_rc_crow] = the cell that owns it.
; out: sh_rwdst holds the R1C1 form, [sh_rw_di] its length.
; -----------------------------------------------------------------------------
sh_formula_to_r1c1:
    push ax
    push bx
    push cx
    push dx
    push si
    mov word [sh_rw_di], 0
.loop:
    mov al, [si]
    or al, al
    jz .done
    cmp al, '"'
    jne .tryref
    SHOUT sh_rw_emit
    inc si
.instr:
    mov al, [si]
    or al, al
    jz .done
    SHOUT sh_rw_emit
    inc si
    cmp al, '"'
    jne .instr
    jmp .loop
.tryref:
    SHOUT sh_isletter_at
    jnc .literal
    mov [sh_rw_ostart], si
    SHOUT sh_psheetpfx
    jnc .noxsheet
    mov si, [sh_rw_ostart]            ; the prefix goes through verbatim
    mov bx, 7
.pfx:
    mov al, [si]
    SHOUT sh_rw_emit
    inc si
    dec bx
    jnz .pfx
    mov [sh_rw_ostart], si
.noxsheet:
    call sh_reidx_cellpart_probe      ; is this really a reference?
    jc .isref
    mov si, [sh_rw_ostart]            ; no: a function name or a bare word
.word:
    SHOUT sh_isletter_at
    jnc .loop
    mov al, [si]
    SHOUT sh_rw_emit
    inc si
    jmp .word
.isref:
    mov al, 'R'                       ; ...the row part
    mov bx, [sh_rw_refrow]
    mov cl, [sh_rw_absr]
    or cl, cl
    jnz .rowabs
    sub bx, [sh_rc_crow]              ; relative: an offset from this cell
.rowabs:
    call sh_emit_rc
    mov al, 'C'                       ; ...and the column part
    mov bx, [sh_rw_refcol]
    mov cl, [sh_rw_absc]
    or cl, cl
    jnz .colabs
    sub bx, [sh_rc_ccol]
.colabs:
    call sh_emit_rc
    jmp .loop
.literal:
    mov al, [si]
    SHOUT sh_rw_emit
    inc si
    jmp .loop
.done:
    mov bx, [sh_rw_di]
    mov byte [sh_rwdst + bx], 0
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_reidx_cellpart_probe - SI at a possible reference. Fills sh_rw_refcol/
; refrow/absc/absr and returns CF=1 with SI past it. CF=0 means the letters
; were NOT followed by a row number (a function name, say) - SI is left where
; the scan stopped, and the caller rewinds it from sh_rw_ostart, which is the
; same contract sh_reidx_cellpart works to.
sh_reidx_cellpart_probe:
    push ax
    push cx
    push di
    mov di, sh_ident
    xor cx, cx
    mov byte [sh_rw_absc], 0
    mov byte [sh_rw_absr], 0
    cmp byte [si], '$'
    jne .nc
    mov byte [sh_rw_absc], 1
    inc si
.nc:
.letters:
    mov al, [si]
    cmp al, 'A'
    jb .doneletters
    cmp al, 'Z'
    jbe .isl
    cmp al, 'a'
    jb .doneletters
    cmp al, 'z'
    ja .doneletters
.isl:
    cmp cx, 2
    jae .doneletters
    and al, 0xDF
    mov [di], al
    inc di
    inc cx
    inc si
    jmp .letters
.doneletters:
    mov byte [di], 0
    or cx, cx
    jz .no
    cmp byte [si], '$'
    jne .nr
    mov byte [sh_rw_absr], 1
    inc si
.nr:
    mov al, [si]
    cmp al, '0'
    jb .no
    cmp al, '9'
    ja .no
    SHOUT sh_identcol
    mov [sh_rw_refcol], ax
    push bx
    mov bx, si
    add bx, SH_EDITMAX + 1
    push es
    mov ax, ds
    mov es, ax
    SHOUT sh_pint
    pop es
    pop bx
    dec ax
    mov [sh_rw_refrow], ax
    pop di
    pop cx
    pop ax
    stc
    ret
.no:
    pop di
    pop cx
    pop ax
    clc
    ret

; -----------------------------------------------------------------------------
; sh_formula_from_r1c1 - in: SI = R1C1-form text, [sh_rc_ccol]/[sh_rc_crow] =
; the cell that owns it. out: sh_rwdst holds the A1 form, NUL-terminated.
;
; The inverse of the above. A reference starts at an 'R' that is followed by
; '[', a digit, '-' or 'C' - which is what tells "R[-1]C" apart from a function
; name beginning with R, and the reason this looks one character further ahead
; than the A1 scanner needs to.
;
; AND IT IS A WHOLE WORD (81.62): the 'R' must not follow a letter, digit, '.'
; or '_', and what the reference ends at must not be one either, or '('. The
; RC inside SEARCH was read as "this cell" and the function came in as
; SEAC16H - #NAME? on every SYLK load, SHEET's own files included, and a
; defined name like SOURCE the same way.
; -----------------------------------------------------------------------------
sh_formula_from_r1c1:
    push ax
    push bx
    push cx
    push dx
    push si
    mov dx, si                        ; DX = the text's start, for the check
    mov word [sh_rw_di], 0
.loop:
    mov al, [si]
    or al, al
    jz .done
    cmp al, '"'
    jne .tryref
    SHOUT sh_rw_emit
    inc si
.instr:
    mov al, [si]
    or al, al
    jz .done
    SHOUT sh_rw_emit
    inc si
    cmp al, '"'
    jne .instr
    jmp .loop
.tryref:
    mov al, [si]
    and al, 0xDF
    cmp al, 'R'
    jne .literal
    cmp si, dx                        ; ...at the start of a WORD
    je .rstart
    mov al, [si-1]
    call sh_rcident
    jc .literal
.rstart:
    mov [sh_rw_ostart], si
    inc si
    call sh_read_rc                   ; -> BX = value, CL = 1 if absolute
    jc .notref
    mov [sh_rw_refrow], bx
    mov [sh_rw_absr], cl
    mov al, [si]
    and al, 0xDF
    cmp al, 'C'
    jne .notref
    inc si
    call sh_read_rc
    jc .notref
    mov al, [si]                      ; ...and ending one: RCOST is a name,
    cmp al, '('                       ; RC( a function
    je .notref
    call sh_rcident
    jc .notref
    mov [sh_rw_refcol], bx
    mov [sh_rw_absc], cl
    ; --- emit it as A1 ---
    cmp byte [sh_rw_absc], 0
    je .colrel
    mov al, '$'
    SHOUT sh_rw_emit
    jmp .colemit
.colrel:
    mov ax, [sh_rw_refcol]
    add ax, [sh_rc_ccol]
    mov [sh_rw_refcol], ax
.colemit:
    mov ax, [sh_rw_refcol]
    SHOUT sh_colname
    mov bx, sh_colbuf
.cl:
    mov al, [bx]
    or al, al
    jz .rowpart
    SHOUT sh_rw_emit
    inc bx
    jmp .cl
.rowpart:
    cmp byte [sh_rw_absr], 0
    je .rowrel
    mov al, '$'
    SHOUT sh_rw_emit
    jmp .rowemit
.rowrel:
    mov ax, [sh_rw_refrow]
    add ax, [sh_rc_crow]
    mov [sh_rw_refrow], ax
.rowemit:
    mov ax, [sh_rw_refrow]
    inc ax                            ; back to the 1-based display row
    call sh_emit_num
    jmp .loop
.notref:
    mov si, [sh_rw_ostart]            ; not a reference after all: the 'R' and
    mov al, [si]                      ; whatever follows go through as text
    SHOUT sh_rw_emit
    inc si
    jmp .loop
.literal:
    mov al, [si]
    SHOUT sh_rw_emit
    inc si
    jmp .loop
.done:
    mov bx, [sh_rw_di]
    mov byte [sh_rwdst + bx], 0
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_rcident - CF=1 when AL can be part of a word: a letter, a digit, '.' or
; '_' (81.62)
sh_rcident:
    push ax
    cmp al, '.'
    je .yes
    cmp al, '_'
    je .yes
    cmp al, '0'
    jb .no
    cmp al, '9'
    jbe .yes
    and al, 0xDF
    cmp al, 'A'
    jb .no
    cmp al, 'Z'
    jbe .yes
.no:
    pop ax
    clc
    ret
.yes:
    pop ax
    stc
    ret

; sh_read_rc - SI just past an 'R' or 'C'. out: BX = the value (a signed offset
; when relative, a 0-based index when absolute), CL = 1 if absolute, SI
; advanced. CF=1 if what follows is neither a bracket nor a digit.
sh_read_rc:
    push ax
    push dx
    xor bx, bx
    xor cl, cl
    cmp byte [si], '['
    je .rel
    mov al, [si]                      ; a bare digit means absolute
    cmp al, '0'
    jb .zero                          ; neither: "RC" - a zero offset
    cmp al, '9'
    ja .zero
    mov cl, 1
    call sh_read_int
    dec bx                            ; absolute parts are 1-based on the wire
    jmp .ok
.rel:
    inc si
    call sh_read_int                  ; the bracketed offset, sign and all
    cmp byte [si], ']'
    jne .bad
    inc si
    jmp .ok
.zero:
    cmp byte [si], 'C'                ; "RC..." - this part is simply zero
    je .ok
    cmp byte [si], 'c'
    je .ok
    or bx, bx                         ; end of the reference is fine too
    jmp .ok
.ok:
    pop dx
    pop ax
    clc
    ret
.bad:
    pop dx
    pop ax
    stc
    ret

; sh_read_int - a signed decimal at SI into BX; SI advanced. Used only by the
; R1C1 reader, where the number is known to be short.
sh_read_int:
    push ax
    push cx
    push dx
    xor bx, bx
    xor cx, cx                        ; cx = 1 when negative
    cmp byte [si], '-'
    jne .d
    mov cx, 1
    inc si
.d:
    mov al, [si]
    cmp al, '0'
    jb .fin
    cmp al, '9'
    ja .fin
    sub al, '0'
    xor ah, ah
    push ax
    mov ax, bx
    mov dx, 10
    imul dx
    mov bx, ax
    pop ax
    add bx, ax
    inc si
    jmp .d
.fin:
    or cx, cx
    jz .o
    neg bx
.o:
    pop dx
    pop cx
    pop ax
    ret

; sh_formula_reidx - in: SI = source formula text (DS-resident, NUL-
; terminated, no leading '='); [sh_rw_op]/[sh_rw_pivot]/[sh_rw_tsheet]/
; [sh_rw_home] already set by the caller (sh_rowcol_reidx). Out:
; sh_rwdst holds the rewritten, NUL-terminated text, [sh_rw_di] = its
; length. See the section header comment above for the token rules.
section .text
sh_formula_reidx:
    push ax
    push bx
    push cx
    push dx
    push si
    mov word [sh_rw_di], 0
.loop:
    mov al, [si]
    or al, al
    jz .done
    cmp al, '"'
    jne .tryref
    call sh_rw_emit
    inc si
.instr:
    mov al, [si]
    or al, al
    jz .done
    call sh_rw_emit
    inc si
    cmp al, '"'
    jne .instr
    jmp .loop
.tryref:
    call sh_isletter_at
    jnc .literal
    mov [sh_rw_ostart], si
    call sh_psheetpfx
    jnc .noxsheet
    mov cx, ax                         ; cx = the sheet the prefix names
    call sh_isletter_at
    jc .pfxisref
    mov si, [sh_rw_ostart]             ; "SheetN!" not actually followed by
    mov bx, 7                          ; a reference: emit the 7 prefix
.pfxverb:                              ; bytes VERBATIM and carry on.
    mov al, [si]                       ; sh_psheetpfx has already advanced
    call sh_rw_emit                    ; SI past them, so just jumping back
    inc si                             ; to .loop (as this did before) threw
    dec bx                             ; them away - silently deleting the
    jnz .pfxverb                       ; "SHEET2!" from the rewritten text
    jmp .loop
.pfxisref:
    mov si, [sh_rw_ostart]
    mov bx, 7                          ; "SHEET" + one digit + "!" always
.copypfx:
    mov al, [si]
    call sh_rw_emit
    inc si
    dec bx
    jnz .copypfx
    cmp cx, [sh_rw_tsheet]
    jne .pfxnoadj
    mov dl, 1
    jmp .pfxgo
.pfxnoadj:
    mov dl, 0
.pfxgo:
    call sh_reidx_cellpart
    jmp .loop
.noxsheet:
    mov dl, [sh_rw_home]
    call sh_reidx_cellpart
    jmp .loop
.literal:
    mov al, [si]
    call sh_rw_emit
    inc si
    jmp .loop
.done:
    mov bx, [sh_rw_di]
    mov byte [sh_rwdst + bx], 0
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_rowcol_reidx - the driver: walk every cell, and for each formula
; cell, run its text through sh_formula_reidx and repoint its
; formula_off if the text actually changed. [sh_rc_op]/[sh_rc_idx] are
; still exactly what sh_rowcol_op's caller passed (untouched since
; entry); [sh_cursheet] has just been restored to the sheet this whole
; operation acted on.
sh_rowcol_reidx:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov ax, [sh_cursheet]
    mov [sh_rw_tsheet], ax
    mov al, [sh_rc_op]
    mov [sh_rw_op], al
    mov ax, [sh_rc_idx]
    mov [sh_rw_pivot], ax
    xor cx, cx
.scan:
    cmp cx, [sh_ncells]
    jae .done
    mov ax, cx
    mov bx, SH_C_SZ
    mul bx
    mov [sh_rw_recdi], ax
    mov si, ax
    mov es, [sh_cellseg]
    test byte [es:si+4], 1             ; HASFORMULA
    jz .next
    mov ax, [es:si]
    call sh_unpackrow                  ; bx = this record's own sheet
    mov byte [sh_rw_home], 0
    cmp bx, [sh_rw_tsheet]
    jne .gothome
    mov byte [sh_rw_home], 1
.gothome:
    mov si, [sh_rw_recdi]
    mov ax, [es:si+SH_C_FOFF]          ; formula_off
    mov si, ax
    mov es, [sh_txtseg]
    mov di, sh_rwsrc
.copyin:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .copyin
    mov si, sh_rwsrc
    call sh_formula_reidx
    mov si, sh_rwsrc
    mov di, sh_rwdst
    call sh_streq                      ; CF=1 if identical
    jc .next                           ; unchanged: nothing to do
    mov si, sh_rwdst
    call sh_txt_append
    jc .next                           ; no room left: leave the stale
                                        ; (still valid, just unshifted)
                                        ; text in place rather than losing
                                        ; the formula entirely
    mov es, [sh_cellseg]
    mov di, [sh_rw_recdi]
    mov [es:di+SH_C_FOFF], ax
    mov word [es:di+SH_C_PASS], 0xFFFF        ; force re-evaluation
.next:
    inc cx
    jmp .scan
.done:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; Copy/Paste relative-reference adjustment (stage 2.x, per direct user
; report). sh_docmd_copy already remembers WHERE it copied from
; (sh_clip_col/sh_clip_row/sh_clip_valid, set below); sh_docmd_paste uses
; that plus its own destination (sh_selcol/sh_selrow) to compute a
; constant (col, row) delta and runs the copied formula's text through
; sh_formula_copyshift before handing it to sh_commit - the same "copy a
; formula, keep the cell it landed in" behavior every other spreadsheet's
; own default (non-absolute) reference already has.
;
; This reuses sh_rowcol_reidx's own low-level pieces (sh_isletter_at,
; sh_rw_emit, sh_rwsrc/sh_rwdst/sh_rw_di, sh_psheetpfx/sh_identcol/
; sh_colname/sh_pint/sh_itoa) but is otherwise a SEPARATE top-level scan,
; not a generalization of sh_formula_reidx: an Insert/Delete Row/Column
; shift only ever touches ONE axis (row XOR column) and only for
; references at or past a pivot; a copy/paste shift touches BOTH axes
; unconditionally by a fixed delta (pasting diagonally moves a reference
; diagonally too) and has no pivot or target-sheet concept at all - every
; reference in the formula, bare or "SheetN!"-prefixed alike, shifts by
; the exact same delta, matching real Excel's own relative-reference
; behavor when copying between sheets (the sheet name itself never
; changes, only the cell part does).
;
; sh_clip_valid is this instance's own memory of "the last thing *I*
; copied, and from where" - the real clipboard (OSAPI_CLIP_PUT/GET) is
; plain bytes with no provenance, so if something else overwrites it
; between the Copy and the Paste (a different app, or a different Sheet
; instance), a resulting paste here would only misfire if that unrelated
; text ALSO happens to start with '=' - accepted as a known, low-
; probability edge case rather than something worth adding real
; clipboard versioning for.
; =============================================================================

; sh_copy_shift - in: AX = a reference's original 0-based index, BX =
; the signed delta (sh_cp_coldelta or sh_cp_rowdelta), CX = that axis's
; cap (SH_COLS or SH_ROWS); out: AX = adjusted index, clamped to
; [0, CX-1] rather than allowed to go negative or off the grid - this
; project has no error-value concept anywhere (RK's unsupported subtype
; and division by zero both degrade the same "closest sane fallback,
; never crash" way)
sh_copy_shift:
    add ax, bx
    jns .nonneg
    jmp .dead                         ; off the top or the left edge: Excel
.nonneg:                              ; writes #REF! rather than clamping to
    cmp ax, cx                        ; A1, and clamping is what made
    jb .out                           ; `=A1` pasted one column left read as
    jmp .dead                         ; `=A1` again
.out:
    clc
    ret
.dead:
    stc
    ret

; sh_copy_cellpart - in: SI at a cell reference's first letter (the
; caller has already confirmed one is there via sh_isletter_at); out: SI
; advanced past the whole reference (letters and, if any followed,
; digits), and the reference emitted to sh_rwdst with BOTH its column
; and row shifted by [sh_cp_coldelta]/[sh_cp_rowdelta] - or, if this
; letter run turns out not to be followed by a digit (a function name,
; not a cell reference), the bare word emitted verbatim instead
sh_copy_cellpart:
    push ax
    push bx
    push cx
    push di
    mov [sh_cp_ostart], si
    mov byte [sh_cp_absc], 0           ; stage 3.0e: see sh_rw_absc
    mov byte [sh_cp_absr], 0
    mov byte [sh_cp_dead], 0           ; ...and stage 4.5: whether the shift
    cmp byte [si], '$'                 ; took this reference off the sheet.
    jne .nocoldollar                   ; The DECISION is deferred to the emit
    mov byte [sh_cp_absc], 1           ; below, because SI still has to be
    inc si                             ; advanced past the whole reference
                                       ; either way
.nocoldollar:
    mov di, sh_ident
    xor cx, cx
.letters:
    mov al, [si]
    cmp al, 'A'
    jb .doneletters
    cmp al, 'Z'
    jbe .isletter
    cmp al, 'a'
    jb .doneletters
    cmp al, 'z'
    ja .doneletters
.isletter:
    cmp cx, 7
    jae .doneletters
    mov ah, al
    and ah, 0xDF
    mov [di], ah
    inc di
    inc cx
    inc si
    jmp .letters
.doneletters:
    mov byte [di], 0
    mov [sh_cp_lettersend], si
    cmp byte [si], '$'
    jne .norowdollar
    mov byte [sh_cp_absr], 1
    inc si
.norowdollar:
    mov al, [si]
    cmp al, '0'
    jb .notref
    cmp al, '9'
    ja .notref
    mov bx, si                         ; 81.35: letters, digits, then '(' is
.fndig:                                ; a function - see sh_reidx_cellpart
    inc bx
    mov al, [bx]
    cmp al, '0'
    jb .fnend
    cmp al, '9'
    jbe .fndig
.fnend:
    cmp al, '('
    jne .isref
    mov si, bx
    jmp .notref
.isref:
    call sh_identcol                   ; ax = 0-based col (from sh_ident)
    cmp byte [sh_cp_absc], 0           ; a pinned column does not follow the
    jne .colpinned                     ; paste's own displacement
    mov bx, [sh_cp_coldelta]
    mov cx, SH_COLS
    call sh_copy_shift
    jnc .colpinned
    mov byte [sh_cp_dead], 1
.colpinned:
    mov [sh_cp_refcol], ax
    mov bx, si
    add bx, SH_EDITMAX + 1
    push es
    mov ax, ds
    mov es, ax
    call sh_pint                       ; ax = 1-based row text; si advances
    pop es
    dec ax                             ; ax = 0-based row
    cmp byte [sh_cp_absr], 0
    jne .rowpinned
    mov bx, [sh_cp_rowdelta]
    mov cx, SH_ROWS
    call sh_copy_shift
    jnc .rowpinned
    mov byte [sh_cp_dead], 1
.rowpinned:
    mov [sh_cp_refrow], ax
    mov [sh_cp_refend], si
    cmp byte [sh_cp_dead], 0
    je .cpalive
    call sh_rw_emitref
    jmp .out
.cpalive:
    cmp byte [sh_cp_absc], 0           ; both halves are REGENERATED below, so
    je .cpnocoldollar                  ; both markers have to be re-emitted
    mov al, '$'
    call sh_rw_emit
.cpnocoldollar:
    mov ax, [sh_cp_refcol]
    call sh_colname
    mov bx, sh_colbuf
.colemit:
    mov al, [bx]
    or al, al
    jz .rowdigits
    call sh_rw_emit
    inc bx
    jmp .colemit
.rowdigits:
    cmp byte [sh_cp_absr], 0
    je .cpnorowdollar
    mov al, '$'
    call sh_rw_emit
.cpnorowdollar:
    mov ax, [sh_cp_refrow]
    inc ax                             ; back to 1-based display text
    call sh_itoa
    mov bx, sh_numbuf
.rowdigemit:
    mov al, [bx]
    or al, al
    jz .out
    call sh_rw_emit
    inc bx
    jmp .rowdigemit
.notref:
    mov bx, [sh_cp_ostart]
.wcopy:
    cmp bx, si
    jae .out
    mov al, [bx]
    call sh_rw_emit
    inc bx
    jmp .wcopy
.out:
    pop di
    pop cx
    pop bx
    pop ax
    ret

; sh_formula_copyshift - in: SI = source formula text (DS-resident, NUL-
; terminated, no leading '='); [sh_cp_coldelta]/[sh_cp_rowdelta] already
; set by the caller (sh_docmd_paste). Out: sh_rwdst holds the shifted,
; NUL-terminated text, [sh_rw_di] = its length. Same token-recognition
; and quoted-string-is-verbatim rules as sh_formula_reidx (see that
; proc's own header comment for why a character scan, not a re-parse, is
; both sufficient and safe here).
sh_formula_copyshift:
    push ax
    push bx
    push si
    mov word [sh_rw_di], 0
.loop:
    mov al, [si]
    or al, al
    jz .done
    cmp al, '"'
    jne .tryref
    call sh_rw_emit
    inc si
.instr:
    mov al, [si]
    or al, al
    jz .done
    call sh_rw_emit
    inc si
    cmp al, '"'
    jne .instr
    jmp .loop
.tryref:
    call sh_isletter_at
    jnc .literal
    mov [sh_cp_ostart], si
    call sh_psheetpfx
    jnc .noxsheet
    call sh_isletter_at
    jc .pfxisref
    mov si, [sh_cp_ostart]             ; "SheetN!" not actually followed by
    mov bx, 7                          ; a reference: emit the 7 prefix
.pfxverb:                              ; bytes VERBATIM rather than letting
    mov al, [si]                       ; them be silently deleted (see the
    call sh_rw_emit                    ; matching fix in sh_formula_reidx)
    inc si
    dec bx
    jnz .pfxverb
    jmp .loop
.pfxisref:
    mov si, [sh_cp_ostart]
    mov bx, 7                          ; "SHEET" + one digit + "!" always
.copypfx:
    mov al, [si]
    call sh_rw_emit
    inc si
    dec bx
    jnz .copypfx
    call sh_copy_cellpart              ; the sheet name itself never
    jmp .loop                          ; shifts - only the cell part does
.noxsheet:
    call sh_copy_cellpart
    jmp .loop
.literal:
    mov al, [si]
    call sh_rw_emit
    inc si
    jmp .loop
.done:
    mov bx, [sh_rw_di]
    mov byte [sh_rwdst + bx], 0
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_getcell2 - in: AX=col, BX=row; out: CF=1 occupied + DX=value, CF=0 empty.
; Also always sets [sh_curfmt] to the cell's format byte (0 if empty) -
; a side channel the drawing code reads, since none of this proc's other
; callers (SYLK/DIF/BIFF export, range folding) care about it.
; -----------------------------------------------------------------------------
sh_getcell2:
    push ax
    push bx
    push di
    call sh_findcell
    jnc .empty
    push es
    mov es, [sh_cellseg]
    mov al, [es:di+5]
    mov [sh_curfmt], al
    mov al, [es:di+SH_C_TYPE]         ; stage 4.5: and the tag, so a caller can
    mov [sh_curtype], al              ; tell a label from the zero it would
    mov al, [es:di+SH_C_AUX]          ; the error code travels with the tag,
    mov [sh_curaux], al               ; so the painter can name it
    cmp byte [sh_curtype], SH_T_TEXT   ; ...and a LABEL loads its characters
    jne .nottext                       ; into sh_sacc, so a formula that names
    push ax                            ; one has something to work WITH rather
    call sh_txtslot                    ; than the zero underneath it (81.22)
    call sh_str_load
    pop ax
.nottext:
    mov ax, [es:di+SH_C_FOFF]         ; otherwise read as this cell's value
    mov [sh_curtoff], ax
    test byte [es:di+4], 1            ; HASFORMULA. An ERROR tag raises
    jz .plain                         ; sh_evalerr only AFTER this split
                                      ; (81.20): a formula cell's stored tag
                                      ; may predate the fix that unbreaks it,
                                      ; and raising from it here survived the
                                      ; clean re-evaluation below and wrote
                                      ; the old error back for the whole pass
    pop es
    ; BANK THIS CELL'S OWN IDENTITY ACROSS THE EVALUATION. sh_eval_cell
    ; recurses back through sh_getcell2 for every cell the formula names, and
    ; each of those overwrites every one of these - so a formula rendered with
    ; the FORMAT of the last cell it referenced, and, worse, with that cell's
    ; TYPE and text offset: `=A2+0` where A2 holds a label drew the label.
    ; The cell showed something that was not its value, and said nothing.
    ; Only the FORMAT is banked here - the one thing an evaluation cannot
    ; change. The type, the error code and the text offset all come back from
    ; sh_eval_cell's own writeback, because a text result's offset is its
    ; RESULT slot and not the formula text the banked copy would restore
    ; (81.22.1).
    mov al, [sh_curfmt]
    mov bx, [sh_curtoff]
    push ax
    push bx
    call sh_eval_cell                 ; leaves the full result in sh_acc, and
    pop bx                            ; DX as its truncated form
    pop ax
    mov [sh_curfmt], al
    cmp byte [sh_curtype], SH_T_TEXT   ; A TEXT RESULT KEEPS THE OFFSET THE
    je .offkept                        ; WRITEBACK PUBLISHED: it is the RESULT
    mov [sh_curtoff], bx               ; slot, and the banked one is the
.offkept:                              ; formula's own source text, which the
                                       ; cell would then draw instead (81.22.1).
                                       ; sh_curtype/sh_curaux are not banked at
                                       ; all: the evaluation decides them and
                                       ; publishes them at its writeback
    cmp byte [sh_curtype], SH_T_ERR   ; ...and an ERROR spreads: anything built
    jne .fresh                        ; on a broken cell is broken too - raised
    mov al, [sh_curaux]               ; from what the writeback (or a cache
    mov [sh_evalerr], al              ; hit's current tag) JUST published,
.fresh:                               ; never from the pre-evaluation one
    stc
    jmp .out
.plain:
    cmp byte [sh_curtype], SH_T_ERR   ; a formula-less error cell (sh_seterr,
    jne .pnum                         ; the BIFF reader) has no evaluation to
    mov al, [sh_curaux]               ; republish its tag, so the stored one
    mov [sh_evalerr], al              ; is current and spreads as before
.pnum:
    push si                           ; stage 4.0: the stored value is a full
    push cx                           ; double, so it comes out into sh_acc.
    mov si, sh_acc                    ; DX stays the truncated integer for the
    mov cx, 4                         ; callers that still want one.
.pcopy:
    mov ax, [es:di+SH_C_VAL]
    mov [si], ax
    add di, 2
    add si, 2
    dec cx
    jnz .pcopy
    pop cx
    pop si
    pop es
    call sh_acc_toint
    mov dx, ax
    stc
    jmp .out
.empty:
    mov byte [sh_curfmt], 0
    mov byte [sh_curtype], SH_T_BLANK
    push ax                           ; an empty cell is a zero value, and
    xor ax, ax                        ; sh_acc must say so rather than keeping
    call sh_acc_int                   ; whatever the last cell left there
    pop ax
    clc
.out:
    pop di
    pop bx
    pop ax
    ret

; =============================================================================
; The value accumulator (stage 4.0). The evaluator's working value is a double
; in sh_acc, not an integer in AX - a double does not fit a register, so it
; lives in memory and the machine stack carries a binary operator's left
; operand across the parse of its right.
;
; The INTEGER entry points below are kept as converting wrappers rather than
; being deleted. Roughly forty callers pass values as words - file readers,
; the chart scan, sort, fill, the macro engine - and converting them all in
; one change would have made a fault impossible to localise. They convert at
; the boundary and are correct for any value an integer can hold.
; =============================================================================

; sh_acc_store - pack the fp A accumulator into sh_acc
sh_acc_store:
    push di
    mov di, sh_acc
    call fp_pack_a
    pop di
    ret

; sh_acc_load_a - unpack sh_acc into fp A
sh_acc_load_a:
    push si
    mov si, sh_acc
    call fp_unpack_a
    pop si
    ret

; sh_acc_load_b - unpack sh_acc into fp B
sh_acc_load_b:
    push si
    mov si, sh_acc
    call fp_unpack_b
    pop si
    ret

; sh_acc_int - AX (signed) -> sh_acc
sh_acc_int:
    call fp_i2a
    call sh_acc_store
    ret

; sh_acc_toint - sh_acc -> AX (signed, truncated); CF=1 if it did not fit
sh_acc_toint:
    call sh_acc_load_a
    call fp_a2i
    ret

; sh_vpush - bank sh_acc on the machine stack. CLOBBERS AX (the return address
; goes through it), which is safe because the evaluator's value now lives in
; sh_acc rather than in a register.
sh_vpush:
    ; STKBALANCE-NET: +4 - banks sh_acc on the CALLER's stack for a binary operator; sh_binop_pre takes it off
    pop ax
    push word [sh_acc+6]
    push word [sh_acc+4]
    push word [sh_acc+2]
    push word [sh_acc]
    push ax
    ret

; sh_binop_pre - recover a banked left operand into fp A and load sh_acc, the
; right operand, into fp B. Pairs with exactly one sh_vpush.
sh_binop_pre:
    ; STKBALANCE-NET: -4 - the other half of sh_vpush - one call each, always paired
    pop ax
    pop word [sh_lhs]
    pop word [sh_lhs+2]
    pop word [sh_lhs+4]
    pop word [sh_lhs+6]
    push ax
; sh_binop_ld - fp A = the banked left operand, fp B = sh_acc: sh_binop_pre's
; half that touches no stack, which CHART.OVL's copy calls back to (81.62)
sh_binop_ld:
    push si
    mov si, sh_lhs
    call fp_unpack_a
    pop si
    call sh_acc_load_b
    ret

; -----------------------------------------------------------------------------
; sh_setvald - in: AX=col, BX=row; the value is sh_acc. Out: CF=1 when
; refused (cell table full) - the cell keeps what it had.
; -----------------------------------------------------------------------------
sh_setvald:
    push ax
    push bx
    push cx
    push dx
    push di
    push si
    call sh_addcell
    jc .dfull
    push es
    mov es, [sh_cellseg]
    mov byte [es:di+4], 0             ; a plain value has no formula
    mov byte [es:di+SH_C_TYPE], SH_T_NUM
    mov si, sh_acc                    ; all EIGHT bytes of it
    mov cx, 4
.dcopy:
    mov ax, [si]
    mov [es:di+SH_C_VAL], ax
    add si, 2
    add di, 2
    dec cx
    jnz .dcopy
    pop es
    clc                               ; stored
    jmp .ddone
.dfull:
    stc                               ; refused - see the header
.ddone:
    pop si
    pop di
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_seterr - in: AX=col, BX=row, DL=an SH_ERR_* code (1..7). The cell
; becomes an ERROR VALUE with a zero underneath it, which is exactly what a
; file carrying one means. Used by the file readers, and (81.61) by Fill
; Right/Down, which is why it is RESIDENT: Fill turned an error constant into
; 0, and the readers reach it through a vector now.
; -----------------------------------------------------------------------------
section .text
sh_seterr:
    push ax
    push bx
    push cx
    push dx
    push di
    push si
    mov cl, dl                        ; the code, across sh_setvald
    push cx
    push ax                           ; the column, across sh_acc_int
    xor ax, ax
    call sh_acc_int
    pop ax
    call sh_setvald                    ; creates the record, tagged SH_T_NUM
    pop cx
    jc .out                            ; refused: CF=1 says so (81.61)
    call sh_findcell                   ; ...and now say what it really is
    jnc .out
    push es
    mov es, [sh_cellseg]
    mov byte [es:di+SH_C_TYPE], SH_T_ERR
    mov [es:di+SH_C_AUX], cl
    pop es
    clc
.out:
    pop si
    pop di
    pop dx
    pop cx
    pop bx
    pop ax
    ret

section .text

; -----------------------------------------------------------------------------
; sh_fsep - CF=1 when AL is a byte a space beside it can never matter to: an
; operator, a parenthesis, the argument comma, the range colon, or 0 (the
; start or the end of the text). For sh_setformula's space squeeze.
; -----------------------------------------------------------------------------
sh_fsep:
    push bx
    mov bx, sh_fseps
.lp:
    cmp al, [bx]
    je .yes
    inc bx
    cmp bx, sh_fseps_end
    jb .lp
    pop bx
    clc
    ret
.yes:
    pop bx
    stc
    ret

sh_fseps:     db 0, '+-*/^&=<>(),:'
sh_fseps_end:

; -----------------------------------------------------------------------------
; THE LOGICAL VALUE (81.51). A logical is the double 1.0 or 0.0 tagged
; SH_T_BOOL, so everything that only wants a number - arithmetic, IF's test,
; a chart - reads it unchanged, and only what SHOWS a value, STORES one or
; FOLDS a reference has to know it is there.
;
; sh_boolname - AX nonzero -> "TRUE", else "FALSE", into sh_numbuf. Bit 15 is
; ignored, so the top word of either double does as well as an integer.
; -----------------------------------------------------------------------------
sh_boolname:
    push ax
    push si
    push di
    mov si, sh_f_true
    and ax, 0x7FFF
    jnz .t
    mov si, sh_f_false
.t:
    mov di, sh_numbuf
    call sh_strcpy
    pop di
    pop si
    pop ax
    ret

; sh_boolword - CF=1 when the text at DS:SI is TRUE or FALSE, in any case and
; with nothing either side of it, and AX = 1 or 0 then.
sh_boolword:
    push di
    mov di, sh_f_true
    call sh_wordeq
    mov ax, 1                         ; MOV leaves CF as sh_wordeq set it
    jc .out
    mov di, sh_f_false
    call sh_wordeq
    mov ax, 0
.out:
    pop di
    ret

; sh_errword - CF=1 when the text at DS:SI is one of the seven error values,
; in any case and with nothing either side, and AX = its ERROR.TYPE then
sh_errword:
    push bx
    push di
    xor bx, bx
.l:
    cmp bx, 14
    jae .no
    mov di, [sh_errtab + bx]
    call sh_wordeq
    jc .yes
    add bx, 2
    jmp short .l
.yes:
    mov ax, bx
    shr ax, 1
    inc ax
    stc
    jmp short .out
.no:
    clc
.out:
    pop di
    pop bx
    ret

sh_wordeq:                            ; DS:SI in any case against DS:DI, upper
    push ax
    push si
    push di
.l:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    cmp al, [di]
    jne .ne
    or al, al
    jz .eq
    inc si
    inc di
    jmp short .l
.eq:
    stc
    jmp short .out
.ne:
    clc
.out:
    pop di
    pop si
    pop ax
    ret

; sh_setbool - in: AX=col, BX=row, DL = the value (nonzero is TRUE). A logical
; CONSTANT: sh_setvald's record, retagged - sh_seterr's shape. Out: CF=1 when
; refused (the cell table is full) and the cell keeps what it had.
sh_setbool:
    push ax
    push di
    push es
    push ax
    xor ax, ax
    or dl, dl
    jz .v
    inc ax
.v:
    call sh_acc_int
    pop ax
    call sh_setvald
    jc .out
    call sh_findcell
    mov es, [sh_cellseg]
    mov byte [es:di+SH_C_TYPE], SH_T_BOOL
    clc
.out:
    pop es
    pop di
    pop ax
    ret

; sh_setlabel - sh_settext for text as a PERSON would have typed it: TRUE and
; FALSE are the logical, the way Excel reads that entry, and anything else is
; a label. Typing, SYLK's quoted K and a CSV field come through here; BIFF
; and DIF have a type of their own to say which it is, and do not.
sh_setlabel:
    push dx
    push ax
    call sh_boolword
    mov dx, ax
    pop ax
    jnc .text
    call sh_setbool
    pop dx
    ret
.text:
    call sh_settext
    pop dx
    ret

; sh_fnlogical - CF=1 when the function [sh_pfid] answers TRUE or FALSE:
; NOT, AND, OR, TRUE, FALSE, the IS family and EXACT
sh_fnlogical:
    push ax
    push bx
    mov ax, [sh_pfid]
    or ah, ah
    jnz .no
    mov bx, sh_fnlog
.l:
    cmp al, [bx]
    je .yes
    inc bx
    cmp bx, sh_fnlog_end
    jb .l
.no:
    pop bx
    pop ax
    clc
    ret
.yes:
    pop bx
    pop ax
    stc
    ret

sh_fnlog:     db 6, 8, 9, 20, 21, 25, 26, 27, 28, 29, 30, 31, 32, 48, 107
sh_fnlog_end:

; -----------------------------------------------------------------------------
; sh_setformula - in: AX=col, BX=row, SI=formula text (DS-resident,
; NUL-terminated, NOT including the leading '='). Out: CF=1 when refused
; (arena or cell table full) - the cell keeps what it had (sh_settext's
; contract, which this is a near-twin of).
; -----------------------------------------------------------------------------
sh_setformula:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov [sh_fcol], ax
    mov [sh_frow], bx
    mov dx, si                        ; DX = start of the text, for the
                                       ; length count below
    xor cx, cx
.len:
    cmp byte [si], 0
    je .havelen
    inc si
    inc cx
    jmp .len
.havelen:
    mov si, dx                        ; SI = start of the text again
    mov ax, [sh_txtlen]
    add ax, cx
    inc ax                            ; +1 for the NUL this stores too
    cmp ax, SH_TXT_CAP
    ja .noroom
    mov es, [sh_txtseg]
    mov di, [sh_txtlen]
    mov [sh_newoff], di               ; where THIS formula starts
    ; SPACES ARE DROPPED ON THE WAY IN (81.50), as Excel 2.1 drops them: its
    ; BIFF2 has no token to keep one in (tAttrSpace is BIFF3 on), so =1 + 2
    ; comes back =1+2. The evaluator does not step over a space between
    ; tokens, and never did - =1 + 2 used to answer 1. One space survives,
    ; where it stands between two OPERANDS (=1+2 3), because that is not a
    ; spacing but a mistake, and sh_eval_cell makes it #VALUE! rather than
    ; this closing it up into =1+23. A quoted string keeps every space.
    ; The count above is of the raw text, which this can only shorten.
    xor dx, dx                        ; DL = inside "...", DH = the last byte
.copy:                                ; stored (0 = none yet, a separator)
    lodsb
    cmp al, '"'
    jne .notq
    xor dl, 1
.notq:
    test dl, dl
    jnz .put
    cmp al, ' '
    jne .put
.sp:
    cmp byte [si], ' '                ; the whole run of spaces is one gap
    jne .spend
    inc si
    jmp short .sp
.spend:
    mov al, dh
    call sh_fsep
    jc .copy                          ; after an operator or '(': dropped
    mov al, [si]
    call sh_fsep
    jc .copy                          ; before one, or at the end: dropped
    mov al, ' '                       ; between two operands: ONE kept
.put:
    stosb
    mov dh, al
    or al, al
    jnz .copy
    mov [sh_txtlen], di
    mov ax, [sh_fcol]
    mov bx, [sh_frow]
    call sh_addcell
    jc .noroom
    push es
    mov es, [sh_cellseg]
    mov byte [es:di+4], 1             ; HASFORMULA
    mov byte [es:di+SH_C_TYPE], SH_T_NUM   ; stage 4.5: and RETAG it. Typing a
                                      ; formula over a label reuses that
                                      ; label's record, and without this the
                                      ; TEXT tag survived and the cell drew
                                      ; its old text forever while quietly
                                      ; computing the right answer underneath
    mov ax, [sh_newoff]
    mov [es:di+SH_C_FOFF], ax
    mov word [es:di+SH_C_PASS], 0xFFFF       ; a pass stamp sh_pass can never equal,
                                       ; forcing at least one real evaluation
    pop es
    clc                               ; stored
    jmp .done
.noroom:
    stc                               ; refused - see the header
.done:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; =============================================================================
; RPN TOKENS - a formula that reaches BIFF as a FORMULA record instead of a
; flattened number.
;
; WHAT THIS DELIBERATELY DOES NOT DO, first, because the boundary is the whole
; design. It refuses any formula containing a FUNCTION CALL, and falls back to
; writing the cached value as NUMBER or RK exactly as before. The reason is not
; effort: docs/excelfileformat.pdf's section 3.12, "Built-in Sheet Functions",
; is marked *2do* - the index table is not written in that revision. A guessed
; index does not produce a broken file, it produces a file Excel opens happily
; and computes SOMETHING ELSE from, silently. That is strictly worse than
; carrying the value, which is at least right.
;
; BIFF3's tFunc and tFuncVar also take a ONE-BYTE index, so several of Sheet's
; own functions could not be expressed even with the table - POWER is 337.
;
; So: numbers, cell references, ranges, the six comparisons, + - * / ^, unary
; minus and parentheses. That is most of what a sheet actually holds, and every
; one of them is verifiable against a spec section that IS written.
;
; THE PARSER HERE IS A SECOND ONE, not the evaluator with a mode bolted on.
; sh_pexpr and friends compute; this walks the same grammar and emits. Two
; parsers can drift - but this one only ever has to answer "can I express
; this", and when it cannot the writer falls back to a path that was already
; correct. A shared parser with an emit flag would have put a second set of
; states inside the routine every cell value already depends on.
; =============================================================================
SH_PTG_ADD     equ 0x03                 ; the operator tokens (excelfileformat 3.5.7)
SH_PTG_SUB     equ 0x04
SH_PTG_MUL     equ 0x05
SH_PTG_DIV     equ 0x06
SH_PTG_POWER   equ 0x07
SH_PTG_LT      equ 0x09
SH_PTG_LE      equ 0x0A
SH_PTG_EQ      equ 0x0B
SH_PTG_GE      equ 0x0C
SH_PTG_GT      equ 0x0D
SH_PTG_NE      equ 0x0E
SH_PTG_UMINUS  equ 0x13
SH_PTG_PAREN   equ 0x15
SH_PTG_CONCAT  equ 0x08               ; 81.61: '&', a string constant and an
SH_PTG_STR     equ 0x17               ; error constant - cch byte, then bytes
SH_PTG_ERR     equ 0x1C               ; one byte, BIFF's own error code
SH_PTG_INT     equ 0x1E                 ; + a 16-bit unsigned
SH_PTG_NUM     equ 0x1F                 ; + an IEEE double
SH_PTG_FUNCCE  equ 0x58                 ; 81.83: tFuncVar for a COMMAND
                                         ; EQUIVALENT. BIFF8 carries fCeFunc
                                         ; as bit 15 of a two-byte index and
                                         ; BIFF2/3 have only one byte, so what
                                         ; Excel 2.1d actually writes is a
                                         ; DIFFERENT PTG. That is in no
                                         ; document here; it came off its own
                                         ; file (81.68)
SH_PTG_FUNCV   equ 0x41                 ; tFuncV / tFuncVarV (3.7.1, 3.7.2).
SH_PTG_FUNCVARV equ 0x42                ; VALUE class throughout, like the refs
                                         ; below: a cell formula's result is a
                                         ; value, whatever the function's own
                                         ; default return class is
SH_PTG_REFV    equ 0x44                 ; value class: 3.3.4's transformation
SH_PTG_AREAV   equ 0x45                 ; turns the default R class into V inside
                                      ; an ordinary cell formula
SH_RPN_MAX   equ 96                   ; a token array longer than this is
                                      ; refused rather than truncated

; THE CONSTANTS ABOVE STAY IN BOTH ARMS and the code below does not. They are
; `equ`s and emit nothing, and SH_RPN_MAX still SIZES a bss slot further down
; (sh_rpn_buf, which sh_rwsrc is chained off) - so gating it out makes the
; whole bss chain non-constant and the two OS88_BSS assertions fail with
; "non-constant argument supplied to TIMES", which names neither the flag nor
; the symbol. PLAN's own bss ladder is 81.75's later stage; until it lands,
; PLAN reserves this buffer and never fills it.

; The BIFF function index for each of Sheet's own functions, INDEXED BY
; sh_functab's order - so the id sh_funcid already returns indexes straight
; into these, and adding a function to one table without the other is a
; visible hole rather than a silent mismatch.
;
; The numbers are OpenOffice.org's Documentation of the Microsoft Excel File
; Format, revision 1.42, section 3.11 (Built-In Sheet Functions). SPEC.md
; 81.10.2 was written against an EARLIER revision of the same document, in
; which that section reads only "2do" - which is why every function used to
; fall back to a cached value.
;
; SIX OF THESE WERE WRONG until 2026-09-10, and every one silently: UPPER and
; LOWER were each other's (113/112), INDEX was DATE's 65 (it is 29), PMT was
; DMIN's 43 (59), and RATE and MIRR had slid one place onto PMT's 59 and
; RATE's 60 (60, 61). A wrong index is the failure this table's own header
; warns about - a file Excel opens and computes SOMETHING ELSE from - and it
; was invisible here, because SHEET never read a function back. Found by
; checking the table against revision 1.42's 3.11 mechanically, which
; tools/os88sheetfmt.py --selfcheck now does on every build (BIFF_FUNCS).
;
; 0xFF = cannot be written at the BIFF version this app emits. POWER is the
; only one: it is index 337, new in BIFF5, and past the byte BIFF3 allows.
sh_rpn_fid:
    db 4, 5, 6, 7, 0                  ; SUM AVERAGE MIN MAX COUNT
    db 1, 38, 24, 36, 37              ; IF NOT ABS AND OR
    db 183, 169, 39, 25, 197          ; PRODUCT COUNTA MOD INT TRUNC
    db 26, 184, 20, 0xFF, 27          ; SIGN FACT SQRT POWER(no) ROUND
    db 34, 35, 8, 9, 100              ; TRUE FALSE ROW COLUMN CHOOSE
    db 129, 128, 127, 198, 3          ; ISBLANK ISNUMBER ISTEXT ISLOGICAL
                                       ;   ISERROR
    db 126, 2, 105, 10, 86            ; ISERR ISNA ISREF NA TYPE
    db 131, 0xFF                      ; N; ERROR.TYPE is ftab index 261, which
                                       ; does not fit a byte - and sh_rpn_func
                                       ; cannot lex the '.' either, so it
                                       ; declines twice over and the cell goes
                                       ; out as its cached value
    db 32, 115, 116, 31, 113          ; LEN LEFT RIGHT MID UPPER
    db 112, 114, 118, 30, 111         ; LOWER PROPER TRIM REPT CHAR
    db 121, 117, 130, 33              ; CODE EXACT T VALUE
    db 124, 82, 120, 119, 48          ; FIND SEARCH SUBSTITUTE REPLACE TEXT
    db 13, 14                         ; DOLLAR FIXED
    db 65, 67, 68, 69, 70             ; DATE DAY MONTH YEAR WEEKDAY
    db 66, 71, 72, 73, 140            ; TIME HOUR MINUTE SECOND DATEVALUE
    db 141                            ; TIMEVALUE
    db 76, 77, 75, 29                 ; ROWS COLUMNS AREAS INDEX - Excel's own
                                       ; ftab, the same table CHOOSE(100),
                                       ; ROW(8) and COLUMN(9) above came from
    db 64, 102, 101, 28               ; MATCH VLOOKUP HLOOKUP LOOKUP - and
                                       ; THIS ORDER
                                       ; IS THE CONTRACT: these three tables
                                       ; are indexed by position in sh_functab,
                                       ; so a row inserted anywhere but the
                                       ; matching place writes another
                                       ; function's ftab index into the file
    db 46, 194, 12, 193               ; VAR VARP STDEV STDEVP
    db 22, 23, 21, 19, 109            ; LN LOG10 EXP PI LOG - Excel's ftab
                                       ; again, and LOG is 109 because 2.1's
                                       ; LOG takes a BASE where 1.x's did not
    db 15, 16, 17, 98, 99             ; SIN COS TAN ASIN ACOS
    db 18, 97                         ; ATAN ATAN2
    db 142, 143, 59, 56, 57           ; SLN SYD PMT PV FV
    db 11                             ; NPV
    db 58, 144                        ; NPER DDB
    db 167, 168                       ; IPMT PPMT
    db 60                             ; RATE
    db 62, 61                         ; IRR MIRR
    db 74                             ; NOW - BIFF's own ftab index for it
    db 190, 162, 63                   ; ISNONTEXT CLEAN RAND
    db 148                            ; INDIRECT. All four of these were
                                       ; CHECKED against 3.11.1's own table
                                       ; (Built-In Sheet Functions in BIFF2)
                                       ; in revision 1.42, not recalled -
                                       ; the copy in docs/ is the 2002
                                       ; revision whose 3.11 reads "2do"
; 81.83: THE MACRO FUNCTIONS, and they come from TWO tables. Excel numbers
; macro COMMANDS through the Command Equivalents Table (Cetab) and macro
; FUNCTIONS through the ordinary function table (Ftab), and nothing about a
; name says which - SELECT and FORMULA are commands, GOTO and RETURN are
; functions. sh_rpn_fce below is which. Sourced from docs/ms-xls.pdf's
; sections 2.5.198.4 and 2.5.198.17 and VERIFIED against a macro sheet real
; Excel 2.1d wrote (81.68): ten and ten.
sh_rpn_fid_mac0:
    db 0x35, 0x37, 0x36, 0x6C         ; GOTO RETURN HALT SET.VALUE   - Ftab
    db 0x6D, 0x60, 0x76, 0x7A, 0x00   ; SELECT FORMULA ALERT MESSAGE BEEP - Ce
    db 0x68                           ; INPUT                        - Ftab
    db 0xAB, 0xAC, 0xAE, 0xAD         ; FOR WHILE NEXT BREAK         - Ftab
    db 0x5E                           ; ACTIVE.CELL                  - Ftab
    db 0x32, 0x31, 0x33, 0x34, 0x1F   ; COPY CUT PASTE CLEAR CALCULATE.NOW - Ce
    db 42, 40, 199, 44, 43             ; DAVERAGE DCOUNT DCOUNTA DMAX DMIN -
    db 189, 45, 195, 41, 47            ; DPRODUCT DSTDEV DSTDEVP DSUM DVAR -
    db 196                             ; DVARP (81.65). Revision 1.42's 3.11
                                       ; again, checked the same way the four
                                       ; rows above it were
    db 125                             ; CELL (81.66), 3.11.1's own index
    db 163, 164, 165, 83               ; MDETERM MINVERSE MMULT TRANSPOSE -
    db 49, 51, 50, 52                  ; LINEST LOGEST TREND GROWTH (81.67),
                                       ; revision 1.42's 3.11 once more
sh_rpn_fid_end:

; 1 = the function takes a variable number of arguments and so is written as
; tFuncVar (which carries a count byte); 0 = fixed, written as tFunc. This is
; "min par != max par" in that same table, NOT a guess about how it is used -
; TRUNC is 1..2 in BIFF3 even though this app only ever passes it one.
; 81.83: 1 = this macro function is a COMMAND and goes out through the Cetab
; (ptg 0x58 / fCeFunc), 0 = it is a function and goes through the Ftab. Twenty
; entries, sh_rpn_fid_mac0's order, and the split is the thing a guess gets
; wrong - it is not "commands are the ones that look like menu items", since
; GOTO and RETURN look exactly like that and are Ftab.
sh_rpn_fce:
    db 0, 0, 0, 0                     ; GOTO RETURN HALT SET.VALUE
    db 1, 1, 1, 1, 1                  ; SELECT FORMULA ALERT MESSAGE BEEP
    db 0                              ; INPUT
    db 0, 0, 0, 0                     ; FOR WHILE NEXT BREAK
    db 0                              ; ACTIVE.CELL
    db 1, 1, 1, 1, 1                  ; COPY CUT PASTE CLEAR CALCULATE.NOW
sh_rpn_fce_end:
SH_FN_MAC0 equ (sh_functab_mac0 - sh_functab) / 2
; TIMES AND NOT %if, and that distinction cost a vacuous assertion. `%if` is a
; PREPROCESSOR test and label arithmetic is not reliably available to it -
; NASM evaluates it against pass-1 values - so `%if (end - start) != 20` sat
; here testing NOTHING, and a mutation that made the table twenty-one entries
; long built cleanly. `times` is assembled, emits nothing when the count is
; zero, and drives NEGATIVE when it is not, which -w+error turns into a build
; failure naming the line. It is the same idiom OS88_BSS uses below and for
; the same reason. Proven by mutation, both ways, not by reading.
    times ((sh_rpn_fce_end - sh_rpn_fce) - 20) db 0
    times (20 - (sh_rpn_fce_end - sh_rpn_fce)) db 0
    times ((sh_rpn_fid_mac0 - sh_rpn_fid) - SH_FN_MAC0) db 0
    times (SH_FN_MAC0 - (sh_rpn_fid_mac0 - sh_rpn_fid)) db 0

sh_rpn_fvar:
    db 1, 1, 1, 1, 1                  ; SUM AVERAGE MIN MAX COUNT
    db 1, 0, 0, 1, 1                  ; IF NOT ABS AND OR
    db 1, 1, 0, 0, 1                  ; PRODUCT COUNTA MOD INT TRUNC
    db 0, 0, 0, 0, 0                  ; SIGN FACT SQRT POWER ROUND
    db 0, 0, 1, 1, 1                  ; TRUE FALSE ROW COLUMN CHOOSE
    db 0, 0, 0, 0, 0                  ; the twelve information functions are
    db 0, 0, 0, 0, 0                  ; every one of them fixed-arity, NA()
    db 0, 0                           ; included (0 parameters, min = max)
    db 0, 1, 1, 0, 0                  ; LEN LEFT(1..2) RIGHT(1..2) MID UPPER
    db 0, 0, 0, 0, 0                  ; LOWER PROPER TRIM REPT CHAR
    db 0, 0, 0, 0                     ; CODE EXACT T VALUE
    db 1, 1, 1, 0, 0                  ; FIND(2..3) SEARCH(2..3)
                                       ;   SUBSTITUTE(3..4) REPLACE TEXT
    db 1, 1                           ; DOLLAR(1..2) FIXED(1..3)
    db 0, 0, 0, 0, 0                  ; DATE DAY MONTH YEAR WEEKDAY
    db 0, 0, 0, 0, 0                  ; TIME HOUR MINUTE SECOND DATEVALUE
    db 0                              ; TIMEVALUE - all fixed-arity in 2.1
    db 0, 0, 0, 1                     ; ROWS COLUMNS AREAS INDEX(2..3)
    db 1, 0, 0, 1                     ; MATCH(2..3) VLOOKUP HLOOKUP
                                       ; LOOKUP(2..3)
    db 1, 1, 1, 1                     ; VAR VARP STDEV STDEVP - every one
                                       ; of them 1..14 arguments
    db 0, 0, 0, 0, 1                  ; LN LOG10 EXP PI, and LOG(1..2)
    db 0, 0, 0, 0, 0                  ; SIN COS TAN ASIN ACOS
    db 0, 0                           ; ATAN ATAN2 - all fixed-arity
    db 0, 0, 1, 1, 1                  ; SLN SYD, and PMT/PV/FV(3..5)
    db 1                              ; NPV(2..15)
    db 1, 1                           ; NPER(3..5) DDB(4..5)
    db 1, 1                           ; IPMT(4..6) PPMT(4..6)
    db 1                              ; RATE(3..6)
    db 1, 0                           ; IRR(1..2) MIRR
    db 0                              ; NOW()
    db 0, 0, 0                        ; ISNONTEXT(1) CLEAN(1) RAND()
    db 1                              ; INDIRECT is 1..2 in that table -
                                       ; tFuncVar, even though the second
                                       ; argument (A1 vs R1C1) is one this
                                       ; app never passes, exactly as the
                                       ; TRUNC note above says
; 81.83: the macro functions. VARIABLE where the table says so, fixed where
; it does not - the same rule as every row above, and os88sheetfmt.py's
; --selfcheck holds it. The first draft made all twenty variable on the
; strength of "Excel writes them in the three-byte form", which was an
; over-reading: the file that was looked at contains SELECT, FORMULA and
; RETURN, and all three ARE variable. It says nothing about NEXT or BREAK.
    db 0, 1, 1, 0                     ; GOTO(1) RETURN(0-1) HALT(0-1) SET.VALUE(2)
    db 1, 1, 1, 1, 1                  ; SELECT FORMULA ALERT MESSAGE BEEP - the
                                       ; Cetab five, and a COMMAND always
                                       ; carries its count (the Cetab's own
                                       ; *n(val) forms), which is what the
                                       ; observed 0x58 tokens show
    db 1                              ; INPUT(1-7)
    db 1, 0, 0, 0                     ; FOR(3-4) WHILE(1) NEXT(0) BREAK(0)
    db 0                              ; ACTIVE.CELL(0)
    db 1, 1, 1, 1, 1                  ; COPY CUT PASTE CLEAR CALCULATE.NOW - Ce
    times 11 db 0                     ; the DATABASE functions (81.65) - all
                                       ; eleven fixed at exactly 3 arguments
    db 1                               ; CELL is 1..2 in that table (81.66)
    db 0, 0, 0, 0                      ; MDETERM MINVERSE MMULT TRANSPOSE -
                                       ; every one fixed-arity
    db 1, 1, 1, 1                      ; LINEST LOGEST TREND GROWTH are all
                                       ; 1..4 in that table (81.67)
sh_rpn_fvar_end:

; How many arguments a FIXED-count function takes, in sh_functab's order -
; the decoder's (81.10.10), because a tFunc token carries only an index and
; the count is a property of the function. GENERATED from revision 1.42's
; 3.11 through tools/os88sheetfmt.py's BIFF_FUNCS, not typed: the minimum of
; whichever version has the function fixed, and 0 for one that is variable
; everywhere, which only ever arrives as tFuncVar with its own count.
; --selfcheck holds it to the document on every build.
sh_rpn_fargc:
    db 0, 0, 0, 0, 0               ; SUM AVERAGE MIN MAX COUNT
    db 0, 1, 1, 0, 0               ; IF NOT ABS AND OR
    db 0, 0, 2, 1, 0               ; PRODUCT COUNTA MOD INT TRUNC
    db 1, 1, 1, 0, 2               ; SIGN FACT SQRT POWER ROUND
    db 0, 0, 0, 0, 0               ; TRUE FALSE ROW COLUMN CHOOSE
    db 1, 1, 1, 1, 1               ; ISBLANK ISNUMBER ISTEXT ISLOGICAL ISERROR
    db 1, 1, 1, 0, 1               ; ISERR ISNA ISREF NA TYPE
    db 1, 0, 1, 0, 0               ; N ERROR.TYPE LEN LEFT RIGHT
    db 3, 1, 1, 1, 1               ; MID UPPER LOWER PROPER TRIM
    db 2, 1, 1, 2, 1               ; REPT CHAR CODE EXACT T
    db 1, 0, 0, 0, 4               ; VALUE FIND SEARCH SUBSTITUTE REPLACE
    db 2, 0, 2, 3, 1               ; TEXT DOLLAR FIXED DATE DAY
    db 1, 1, 1, 3, 1               ; MONTH YEAR WEEKDAY TIME HOUR
    db 1, 1, 1, 1, 1               ; MINUTE SECOND DATEVALUE TIMEVALUE ROWS
    db 1, 1, 0, 0, 3               ; COLUMNS AREAS INDEX MATCH VLOOKUP
    db 3, 0, 0, 0, 0               ; HLOOKUP LOOKUP VAR VARP STDEV
    db 0, 1, 1, 1, 0               ; STDEVP LN LOG10 EXP PI
    db 0, 1, 1, 1, 1               ; LOG SIN COS TAN ASIN
    db 1, 1, 2, 3, 4               ; ACOS ATAN ATAN2 SLN SYD
    db 0, 0, 0, 0, 0               ; PMT PV FV NPV NPER
    db 0, 0, 0, 0, 0               ; DDB IPMT PPMT RATE IRR
    db 3, 0, 1, 1, 0               ; MIRR NOW ISNONTEXT CLEAN RAND
    db 0                           ; INDIRECT
    db 1, 0, 0, 2                  ; 81.83: GOTO RETURN HALT SET.VALUE - the
    db 0, 0, 0, 0, 0               ; fixed ones carry their count here, the
    db 0                           ; variable ones carry 0 and bring their
    db 0, 1, 0, 0                  ; own. SELECT..BEEP and COPY..CALCULATE.NOW
    db 0                           ; are Cetab and the check skips them
    db 0, 0, 0, 0, 0               ; ...and the run above is, in order: GOTO(1)
                                    ; RETURN HALT SET.VALUE(2) / SELECT
                                    ; FORMULA ALERT MESSAGE BEEP / INPUT /
                                    ; FOR WHILE(1) NEXT BREAK / ACTIVE.CELL /
                                    ; COPY CUT PASTE CLEAR CALCULATE.NOW
    db 3, 3, 3, 3, 3               ; DAVERAGE DCOUNT DCOUNTA DMAX DMIN - the
    db 3, 3, 3, 3, 3               ; DATABASE functions (81.65), every one
    db 3                           ; DFUNC(database, field, criteria)
    db 0                           ; CELL - variable everywhere (81.66)
    db 1, 1, 2, 1                  ; MDETERM MINVERSE MMULT(2) TRANSPOSE
    db 0, 0, 0, 0                  ; LINEST LOGEST TREND GROWTH - variable
                                   ; everywhere (81.67)
sh_rpn_fargc_end:

; sh_rpn_isfunc - is the name at sh_rpn_p followed by a '('? out: CF=0 yes.
; Looks ahead and RESTORES nothing because it consumes nothing: sh_rpn_p is
; untouched either way, so whichever path runs next reads the name itself.
section SH_MODSEC                      ; 82.16.9
sh_rpn_isfunc:
    push ax
    push si
    mov si, [sh_rpn_p]
.skipname:
    mov al, [si]
    cmp al, 'A'
    jb .past
    cmp al, 'Z'
    jbe .next
    cmp al, 'a'
    jb .past
    cmp al, 'z'
    ja .past
.next:
    inc si
    jmp .skipname
.past:
    cmp al, '.'                       ; 81.83: ...and "CALCULATE.NOW (" is one
    jne .nodot                        ; too. THIS IS THE LOOKAHEAD, and it has
    inc si                            ; to agree with sh_rpn_func's gather or
    jmp .skipname                     ; a dotted name is read this far, found
.nodot:                               ; not to be followed by '(' , and handed
    cmp al, ' '                       ; to the REFERENCE parser instead - which
    jne .test                         ; declines, and the whole formula with it
.spaces:
    inc si
    mov al, [si]
    cmp al, ' '
    je .spaces
.test:
    cmp al, '('
    je .yes
    stc
    jmp .out
.yes:
    clc
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rpn_func - a built-in function call at sh_rpn_p: NAME ( arg , arg ... )
; Emits the arguments in order, then the function token. Re-entrant, because
; an argument can be another call - the function's own id and its argument
; count are kept in registers banked across the recursion rather than in bss,
; which a nested call would overwrite.
; -----------------------------------------------------------------------------
; sh_rpn_meta - in: BX = a function id, resident or EXTENSION; out: AL = its
; BIFF index (0xFF: none at this version), AH = 1 if variable-arity, and
; [sh_rpn_isce] = 1 if it is a Cetab COMMAND. A MODULE-local helper, which is
; the point: 81.83.5's hang was a module body near-calling a RESIDENT one.
sh_rpn_meta:
    push bx
    cmp bx, SH_FID_MX
    jae .ext
    mov byte [sh_rpn_isce], 0
    push bx
    sub bx, SH_FN_MAC0                ; below the macro run this wraps far
    cmp bx, sh_rpn_fce_end - sh_rpn_fce  ; above the count, so one unsigned
    jae .noce                         ; compare answers both ends
    mov al, [sh_rpn_fce + bx]
    mov [sh_rpn_isce], al
.noce:
    pop bx
    mov al, [sh_rpn_fid + bx]
    mov ah, [sh_rpn_fvar + bx]
    jmp short .out
.ext:
    sub bx, SH_FID_MX
    mov ax, bx
    add bx, bx
    add bx, ax                        ; three bytes a row
    mov al, [cs:bx + shm_mxrpn + 2]
    mov [sh_rpn_isce], al
    mov al, [cs:bx + shm_mxrpn]
    mov ah, [cs:bx + shm_mxrpn + 1]
.out:
    pop bx
    ret

sh_rpn_func:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov si, [sh_rpn_p]
    mov di, sh_ident
    xor cx, cx
.gather:
    mov al, [si]
    cmp al, 'a'
    jb .nolower
    cmp al, 'z'
    ja .nolower
    sub al, 32                        ; sh_funcid matches uppercase
.nolower:
    cmp al, '.'                       ; 81.83: a DOT is part of the name, not
    jne .notdot                       ; the end of it. Excel's macro commands
    or cx, cx                         ; are CALCULATE.NOW and SET.VALUE and
    jz .gathered                      ; ACTIVE.CELL, and this lexer stopped at
    jmp short .take                   ; the dot - so three of 81.63's twenty
.notdot:                              ; could not be written to a file even
    cmp al, 'A'                       ; once their numbers were known. A
    jb .gathered                      ; LEADING dot still ends it, so nothing
    cmp al, 'Z'                       ; that was not already a name becomes one
    ja .gathered
.take:
    cmp cx, SH_IDENT_MAX
    jae .bad
    mov [di], al
    inc di
    inc si
    inc cx
    jmp .gather
.gathered:
    mov byte [di], 0
    or cx, cx
    jz .bad
    mov [sh_rpn_p], si
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], '('
    jne .bad
    inc si
    mov [sh_rpn_p], si
    SHOUT sh_funcid                    ; AL = this app's own id, 0xFF unknown
    xor ah, ah
    cmp ax, 0xFF
    jne .resfn
    call shm_mfind                    ; macro plan wave 0: an EXTENSION one -
    cmp ax, 0xFF                      ; a near call, both are in the module
    je .bad
.resfn:
    mov bx, ax                        ; BX = that id, kept across the arguments
    call sh_rpn_meta                  ; AL = its BIFF index, AH = variable
    cmp al, 0xFF
    je .bad                           ; no index at this BIFF version
    cmp al, 63                        ; RAND, NOW and INDIRECT are the three
    je .vol                           ; functions this app can emit that
    cmp al, 74                        ; 3.11.1 marks VOLATILE, and the legend
    je .vol                           ; there says a volatile function sets
    cmp al, 148                       ; "Recalculate always" in the FORMULA
    jne .notvol                       ; record (5.50 bit 0). Written with that
.vol:                                 ; bit clear - as every record was - a
    mov word [sh_rpn_vol], 1          ; =NOW() opened in Excel shows the value
.notvol:                              ; SHEET cached and never refreshes it.
                                      ; Compared inline rather than through a
                                      ; fourth parallel table: three entries do
                                      ; not earn 110 bytes, and a near call to
                                      ; a resident helper is what 82.16 rule 1
                                      ; forbids from in here
    xor cx, cx                        ; CX = how many arguments were seen
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], ')'
    je .closed                        ; NAME() - legal for TRUE, ROW, COUNT...
.arg:
    push bx                           ; sh_rpn_cmp banks only AX and SI
    push cx
    call sh_rpn_cmp
    pop cx
    pop bx
    cmp byte [sh_rpn_bad], 0
    jne .out
    inc cx
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], ','
    jne .closed
    inc si
    mov [sh_rpn_p], si
    jmp .arg
.closed:
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], ')'
    jne .bad
    inc si
    mov [sh_rpn_p], si
    call sh_rpn_meta                  ; again, from BX: the arguments above
    or ah, ah                         ; recursed and any bss they touched is
    jne .variable                     ; theirs now, so nothing is carried over
    mov al, SH_PTG_FUNCV
    call sh_rpn_put
    jmp .index
.variable:
    mov al, SH_PTG_FUNCVARV
    cmp byte [sh_rpn_isce], 0         ; a COMMAND is its own ptg in the
    je .putptg                        ; one-byte world (81.83)
    mov al, SH_PTG_FUNCCE
.putptg:
    call sh_rpn_put
    mov al, cl                        ; the count comes before the index
    call sh_rpn_put
.index:
    call sh_rpn_meta
    call sh_rpn_put
    cmp byte [sh_wb_xf4], 0           ; BIFF2-3 carry a ONE-byte index and
    je .out                           ; BIFF4-8 a word (3.7.1/3.7.2) - the
    xor al, al                        ; workbook writer emits BIFF4, so the
    cmp byte [sh_rpn_isce], 0         ; high byte goes out there and not here
    je .puthi                         ; ...AND IT IS WHERE fCeFunc LIVES in
    mov al, 0x80                      ; that form: bit 15 of the word, which
.puthi:                               ; is the same distinction the 0x58 ptg
    call sh_rpn_put                   ; makes one byte down
    jmp .out
.bad:
    mov byte [sh_rpn_bad], 1
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rpn_emit - in: SI = the formula text (no leading '=')
; out: CF=0 and CX = bytes in sh_rpn_buf; CF=1 = cannot be expressed
; -----------------------------------------------------------------------------
sh_rpn_emit:
    push ax
    push bx
    push dx
    push si
    push di
    mov [sh_rpn_p], si
    mov word [sh_rpn_len], 0
    mov byte [sh_rpn_bad], 0
    mov word [sh_rpn_vol], 0          ; per formula, not per file
    call sh_rpn_cmp
    cmp byte [sh_rpn_bad], 0
    jne .no
    call sh_rpn_skip
    mov si, [sh_rpn_p]                ; anything left over means the grammar
    cmp byte [si], 0                  ; above did not account for all of it
    jne .no
    cmp word [sh_rpn_len], 0
    je .no
    mov cx, [sh_rpn_len]
    pop di
    pop si
    pop dx
    pop bx
    pop ax
    clc
    ret
.no:
    pop di
    pop si
    pop dx
    pop bx
    pop ax
    stc
    ret

; sh_rpn_put - AL into the buffer; sets sh_rpn_bad if it would overflow
sh_rpn_put:
    push bx
    mov bx, [sh_rpn_len]
    cmp bx, SH_RPN_MAX
    jae .full
    mov [sh_rpn_buf + bx], al
    inc word [sh_rpn_len]
    pop bx
    ret
.full:
    mov byte [sh_rpn_bad], 1
    pop bx
    ret

sh_rpn_putw:                          ; AX, little-endian
    push ax
    call sh_rpn_put
    pop ax
    push ax
    mov al, ah
    call sh_rpn_put
    pop ax
    ret

sh_rpn_skip:                          ; past spaces
    push si
    mov si, [sh_rpn_p]
.lp:
    cmp byte [si], ' '
    jne .done
    inc si
    jmp .lp
.done:
    mov [sh_rpn_p], si
    pop si
    ret

; --- the grammar, one level per routine, mirroring sh_pcmp/sh_pexpr/... ------
; sh_rpn_cmp - the comparison level, lowest precedence
sh_rpn_cmp:
    push ax
    push si
    call sh_rpn_concat
    cmp byte [sh_rpn_bad], 0
    jne .out
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    mov al, [si]
    cmp al, '='
    je .eq
    cmp al, '<'
    je .lt
    cmp al, '>'
    je .gt
    jmp .out
.eq:
    inc si
    mov [sh_rpn_p], si
    mov ah, SH_PTG_EQ
    jmp .rhs
.lt:
    inc si
    mov ah, SH_PTG_LT
    cmp byte [si], '='
    jne .lt2
    inc si
    mov ah, SH_PTG_LE
    jmp .ltdone
.lt2:
    cmp byte [si], '>'
    jne .ltdone
    inc si
    mov ah, SH_PTG_NE
.ltdone:
    mov [sh_rpn_p], si
    jmp .rhs
.gt:
    inc si
    mov ah, SH_PTG_GT
    cmp byte [si], '='
    jne .gtdone
    inc si
    mov ah, SH_PTG_GE
.gtdone:
    mov [sh_rpn_p], si
.rhs:
    push ax
    call sh_rpn_concat                ; ONE comparison only, which is what the
    pop ax                            ; evaluator does too - a<b<c is not a
    cmp byte [sh_rpn_bad], 0          ; thing either of them accepts
    jne .out
    mov al, ah
    call sh_rpn_put
.out:
    pop si
    pop ax
    ret

; sh_rpn_concat - '&' (81.61), between the comparison and the additive level
; exactly as sh_pconcat is: looser than '+', tighter than '='. Left-associative
sh_rpn_concat:
    push ax
    push si
    call sh_rpn_add
.more:
    cmp byte [sh_rpn_bad], 0
    jne .out
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], '&'
    jne .out
    inc si
    mov [sh_rpn_p], si
    call sh_rpn_add
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov al, SH_PTG_CONCAT
    call sh_rpn_put
    jmp short .more
.out:
    pop si
    pop ax
    ret

; sh_rpn_add - additive level, left-associative
sh_rpn_add:
    push ax
    push si
    call sh_rpn_term
.more:
    cmp byte [sh_rpn_bad], 0
    jne .out
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    mov al, [si]
    cmp al, '+'
    je .add
    cmp al, '-'
    je .sub
    jmp .out
.add:
    mov ah, SH_PTG_ADD
    jmp .go
.sub:
    mov ah, SH_PTG_SUB
.go:
    inc si
    mov [sh_rpn_p], si
    push ax
    call sh_rpn_term
    pop ax
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov al, ah
    call sh_rpn_put
    jmp .more
.out:
    pop si
    pop ax
    ret

; sh_rpn_term - multiplicative level
sh_rpn_term:
    push ax
    push si
    call sh_rpn_pow
.more:
    cmp byte [sh_rpn_bad], 0
    jne .out
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    mov al, [si]
    cmp al, '*'
    je .mul
    cmp al, '/'
    je .div
    jmp .out
.mul:
    mov ah, SH_PTG_MUL
    jmp .go
.div:
    mov ah, SH_PTG_DIV
.go:
    inc si
    mov [sh_rpn_p], si
    push ax
    call sh_rpn_pow
    pop ax
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov al, ah
    call sh_rpn_put
    jmp .more
.out:
    pop si
    pop ax
    ret

; sh_rpn_pow - '^', RIGHT-associative, exactly as sh_ppow is
sh_rpn_pow:
    push ax
    push si
    call sh_rpn_unary
    cmp byte [sh_rpn_bad], 0
    jne .out
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], '^'
    jne .out
    inc si
    mov [sh_rpn_p], si
    call sh_rpn_pow                   ; recursion is what makes it right-assoc
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov al, SH_PTG_POWER
    call sh_rpn_put
.out:
    pop si
    pop ax
    ret

; sh_rpn_unary - a leading minus becomes tUminus AFTER its operand
sh_rpn_unary:
    push ax
    push si
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], '-'
    jne .plain
    inc si
    mov [sh_rpn_p], si
    call sh_rpn_unary
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov al, SH_PTG_UMINUS
    call sh_rpn_put
    jmp .out
.plain:
    cmp byte [si], '+'                ; a leading plus is a no-op, and tUplus
    jne .factor                       ; would only add a byte
    inc si
    mov [sh_rpn_p], si
.factor:
    call sh_rpn_factor
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rpn_factor - a number, a cell reference, a range, or a parenthesised
; expression. ANYTHING ELSE REFUSES, which is where a function call lands and
; is the whole safety property of this emitter.
; -----------------------------------------------------------------------------
sh_rpn_factor:
    push ax
    push bx
    push cx
    push dx
    push si
    push di                           ; the error constant's table walk
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    mov al, [si]
    cmp al, '('
    je .paren
    cmp al, '$'
    je .ref
    cmp al, 34                        ; a STRING CONSTANT and an ERROR
    je .str                           ; CONSTANT are tokens too (81.61): they
    cmp al, '#'                       ; refused, and the formula went out as
    je .err                           ; its value alone
    cmp al, '0'
    jb .notdigit
    cmp al, '9'
    jbe .num
.notdigit:
    cmp al, '.'                       ; a leading decimal point is a number
    je .num
    cmp al, 'A'                       ; A letter starts either a reference or a
    jb .bad                           ; FUNCTION CALL, and only the character
    cmp al, 'Z'                       ; after the name tells them apart: a '('
    jbe .word                         ; means a call, anything else a reference
    cmp al, 'a'
    jb .bad
    cmp al, 'z'
    jbe .word
    jmp .bad
.word:
    call sh_rpn_isfunc                ; LOOKS AHEAD without consuming, because
    jc .notcall                       ; sh_rpn_ref must re-read from the name
    call sh_rpn_func
    jmp .out
.notcall:
    call sh_rpn_bool                  ; a bare TRUE or FALSE is tBool (81.51)
    jc .out
    jmp .ref
.paren:
    inc si
    mov [sh_rpn_p], si
    call sh_rpn_cmp
    cmp byte [sh_rpn_bad], 0
    jne .out
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], ')'
    jne .bad
    inc si
    mov [sh_rpn_p], si
    mov al, SH_PTG_PAREN                ; kept, because Excel round-trips it into
    call sh_rpn_put                   ; the formula it shows the user
    jmp .out
.num:
    call sh_rpn_number
    jmp .out
.ref:
    call sh_rpn_ref
    jmp .out
.str:
    ; tStr, then a count byte and the characters: a doubled quote is one
    ; literal quote, as the evaluator reads it. An unterminated constant is
    ; refused - Excel has no such thing, so no token says it
    inc si
    mov al, SH_PTG_STR
    call sh_rpn_put
    mov bx, [sh_rpn_len]              ; BX = where the count goes
    xor al, al
    call sh_rpn_put
    xor cx, cx
.sl:
    mov al, [si]
    or al, al
    jz .bad
    cmp al, 34
    jne .slkeep
    cmp byte [si+1], 34
    jne .slclose
    inc si
.slkeep:
    call sh_rpn_put
    inc si
    inc cx
    jmp short .sl
.slclose:
    inc si
    mov [sh_rpn_p], si
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov [sh_rpn_buf + bx], cl
    jmp .out
.err:
    ; tErr and BIFF's code for it, the name matched against sh_errtab - the
    ; table the evaluator matches and sh_errname prints - exactly, as
    ; sh_perrlit does. Not a name there: refused, as the evaluator's #NAME? is
    xor cx, cx
.et:
    cmp cx, 7
    jae .bad
    mov bx, cx
    shl bx, 1
    mov di, [sh_errtab + bx]
    push si
.em:
    mov al, [di]
    or al, al
    jz .ehit
    cmp al, [si]
    jne .emiss
    inc si
    inc di
    jmp short .em
.emiss:
    pop si
    inc cx
    jmp short .et
.ehit:
    pop dx                            ; the name's start, no longer needed
    mov [sh_rpn_p], si
    mov al, SH_PTG_ERR
    call sh_rpn_put
    mov al, cl
    inc al                            ; ERROR.TYPE, 1-based
    call sh_biff_e2b                  ; -> the file's code
    call sh_rpn_put
    jmp .out
.bad:
    mov byte [sh_rpn_bad], 1
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rpn_bool - CF=1 when sh_rpn_p is at a bare TRUE or FALSE, which it steps
; over, having emitted tBool (1DH, then the value byte) - Excel's own token for
; the constant. CF=0 leaves sh_rpn_p where it was, for sh_rpn_ref.
; -----------------------------------------------------------------------------
sh_rpn_bool:
    push ax
    push cx
    push si
    push di
    mov si, [sh_rpn_p]
    mov di, sh_ident
    xor cx, cx
.g:
    mov al, [si]
    cmp al, 'a'
    jb .nl
    cmp al, 'z'
    ja .nl
    sub al, 32
.nl:
    cmp al, 'A'
    jb .gd
    cmp al, 'Z'
    ja .gd
    cmp cx, 5
    jae .no
    mov [di], al
    inc di
    inc si
    inc cx
    jmp short .g
.gd:
    cmp al, '0'                       ; TRUE1 would be a column, not this
    jb .end
    cmp al, '9'
    jbe .no
.end:
    mov byte [di], 0
    SHOUT sh_funcid                    ; AL = this app's id: TRUE 20, FALSE 21
    cmp al, 20
    je .yes
    cmp al, 21
    jne .no
.yes:
    mov ah, 21
    sub ah, al                        ; AH = 1 for TRUE, 0 for FALSE
    mov [sh_rpn_p], si
    mov al, 0x1D
    call sh_rpn_put
    mov al, ah
    call sh_rpn_put
    stc
    jmp short .out
.no:
    clc
.out:
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rpn_number - tInt for a whole number that fits 0..65535, tNum otherwise.
; The value comes from fp_atof, so what BIFF carries and what the cell computes
; are parsed by ONE routine rather than two that could disagree about "1e3".
; -----------------------------------------------------------------------------
sh_rpn_number:
    push ax
    push bx
    push cx
    push si
    push di
    mov si, [sh_rpn_p]
    SHOUT fp_atof                      ; SI advances past what it consumed
    jc .bad
    mov [sh_rpn_p], si
    SHOUT sh_acc_store                 ; the packed double, in sh_acc
    SHOUT sh_acc_load_a
    SHOUT fp_a2i                       ; CF=1: no signed word holds it
    jc .asnum
    or ax, ax
    js .asnum                         ; tInt is UNSIGNED; a negative literal
    mov bx, ax                        ; arrives as tUminus over a positive one
    SHOUT fp_i2a                       ; and only an exact integer may use it
    push si
    mov si, sh_acc
    SHOUT fp_unpack_b
    pop si
    SHOUT fp_cmpab
    jne .asnum
    mov al, SH_PTG_INT
    call sh_rpn_put
    mov ax, bx
    call sh_rpn_putw
    jmp .out
.asnum:
    mov al, SH_PTG_NUM
    call sh_rpn_put
    mov si, sh_acc                    ; the eight bytes, verbatim - BIFF wants
    mov cx, 8                         ; exactly the IEEE double this file
.nbyte:                               ; already stores
    mov al, [si]
    call sh_rpn_put
    inc si
    dec cx
    jnz .nbyte
    jmp .out
.bad:
    mov byte [sh_rpn_bad], 1
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_rpn_ref - a cell reference, or a range if a ':' follows.
;
; The row word carries BOTH relative flags (excelfileformat 3.4.1): bit 15 is
; the ROW's, bit 14 the COLUMN's, and set means RELATIVE. So $A$1 is 0x0000 and
; A1 is 0xC000 - the opposite polarity from how the '$' reads, which is the one
; thing here worth checking twice.
;
; A "SheetN!" prefix refuses: a cross-sheet reference is tRef3d and needs an
; EXTERNSHEET table this writer does not build.
; -----------------------------------------------------------------------------
sh_rpn_ref:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    call sh_rpn_one                   ; -> BX = row word, DL = col
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov [sh_rpn_r1], bx
    mov [sh_rpn_c1], dl
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    cmp byte [si], ':'
    je .range
    mov al, SH_PTG_REFV
    call sh_rpn_put
    mov ax, [sh_rpn_r1]
    call sh_rpn_putw
    mov al, [sh_rpn_c1]
    call sh_rpn_put
    jmp .out
.range:
    inc si
    mov [sh_rpn_p], si
    call sh_rpn_one
    cmp byte [sh_rpn_bad], 0
    jne .out
    mov al, SH_PTG_AREAV
    call sh_rpn_put
    mov ax, [sh_rpn_r1]               ; first row, last row, first col, last col
    call sh_rpn_putw
    mov ax, bx
    call sh_rpn_putw
    mov al, [sh_rpn_c1]
    call sh_rpn_put
    mov al, dl
    call sh_rpn_put
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_rpn_one - one [$]COL[$]ROW at sh_rpn_p. out: BX = the row word with its
; two relative flags, DL = the column. Sets sh_rpn_bad and nothing else on a
; token that is not a reference.
sh_rpn_one:
    push ax
    push cx
    push si
    push di
    call sh_rpn_skip
    mov si, [sh_rpn_p]
    mov word [sh_rpn_rel], 0xC000     ; relative until a '$' says otherwise
    cmp byte [si], '$'
    jne .colletters
    inc si
    and word [sh_rpn_rel], 0x8000     ; absolute COLUMN clears bit 14
.colletters:
    mov di, sh_ident
    xor cx, cx
.gather:
    mov al, [si]
    cmp al, 'A'
    jb .gathered
    cmp al, 'Z'
    jbe .keep
    cmp al, 'a'
    jb .gathered
    cmp al, 'z'
    ja .gathered
.keep:
    cmp cx, 2                         ; two letters is the whole of 256 columns
    jae .bad
    and al, 0xDF
    mov [di], al
    inc di
    inc si
    inc cx
    jmp .gather
.gathered:
    jcxz .bad
    mov byte [di], 0
    cmp byte [si], '$'
    jne .rowdigits
    inc si
    and word [sh_rpn_rel], 0x4000     ; absolute ROW clears bit 15
.rowdigits:
    mov al, [si]
    cmp al, '0'
    jb .bad
    cmp al, '9'
    ja .bad
    xor bx, bx
.digit:
    mov al, [si]
    cmp al, '0'
    jb .haverow
    cmp al, '9'
    ja .haverow
    sub al, '0'
    xor ah, ah
    push ax
    mov ax, bx
    mov cx, 10
    mul cx
    mov bx, ax
    pop ax
    add bx, ax
    cmp bx, SH_ROWS
    ja .bad
    inc si
    jmp .digit
.haverow:
    or bx, bx
    jz .bad                           ; row 0 does not exist; A0 is not a cell
    dec bx                            ; BIFF rows are zero-based
    SHOUT sh_identcol                  ; AX = the 0-based column
    cmp ax, SH_COLS
    jae .bad
    mov dl, al
    or bx, [sh_rpn_rel]
    mov [sh_rpn_p], si
    pop di
    pop si
    pop cx
    pop ax
    ret
.bad:
    mov byte [sh_rpn_bad], 1
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_settext - stage 4.5: store TEXT in a cell.
; in: AX = col, BX = row, SI = the NUL-terminated text
;
; Deliberately a near-twin of sh_setformula above rather than a shared routine
; the two both call. They agree on the arena copy and disagree on every flag
; that follows it, and a merged version would have been a copy of the first
; half wrapped in a parameter deciding the second - which is the same amount
; of code with a branch through the middle of it.
;
; THE TEXT LIVES IN THE FORMULA ARENA, at SH_C_FOFF, and the two never collide
; because a cell is one thing or the other: HASFORMULA clear plus a TEXT tag
; is the whole discrimination. Notes share this arena too (stage 3.0b) and are
; keyed separately, in their own table.
;
; Like a formula, retyping a label APPENDS and abandons the old bytes - the
; arena has no free list and never compacts. 8 KB is a lot of labels and this
; matches what formulas have always done, but it is a real ceiling rather than
; an oversight, and it is why .noroom below is a no-op rather than a wrong
; value written. Out: CF=1 when refused (arena or cell table full) - the cell
; keeps what it had, and a caller mid-permutation must STOP (see
; sh_sort_permcol).
; -----------------------------------------------------------------------------
section .text
sh_settext:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov [sh_fcol], ax
    mov [sh_frow], bx
    mov dx, si
    xor cx, cx
.len:
    cmp byte [si], 0
    je .havelen
    inc si
    inc cx
    jmp .len
.havelen:
    mov si, dx
    mov ax, [sh_txtlen]
    add ax, cx
    inc ax                            ; +1 for the NUL
    cmp ax, SH_TXT_CAP
    ja .noroom
    mov es, [sh_txtseg]
    mov di, [sh_txtlen]
    mov [sh_newoff], di
.copy:
    lodsb
    stosb
    or al, al
    jnz .copy
    mov [sh_txtlen], di
    mov ax, [sh_fcol]
    mov bx, [sh_frow]
    call sh_addcell
    jc .noroom
    push es
    mov es, [sh_cellseg]
    mov byte [es:di+4], 0             ; NOT a formula: the tag is what says
    mov byte [es:di+SH_C_TYPE], SH_T_TEXT
    mov byte [es:di+SH_C_AUX], 0
    mov ax, [sh_newoff]
    mov [es:di+SH_C_FOFF], ax
    mov word [es:di+SH_C_PASS], 0
    xor ax, ax                        ; and a numeric value of zero, so every
    mov [es:di+SH_C_VAL], ax          ; reader that has never heard of text
    mov [es:di+SH_C_VAL+2], ax        ; still gets a defined number out of it
    mov [es:di+SH_C_VAL+4], ax
    mov [es:di+SH_C_VAL+6], ax
    pop es
    clc                               ; stored
    jmp .done
.noroom:
    stc                               ; refused - see the header
.done:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_eval_cell - evaluate a formula cell, with cycle detection and
; per-repaint memoization
; in: DI = record offset (a HASFORMULA record); ES = sh_cellseg
; out: DX = value; the record's cached value and pass stamp are updated
; -----------------------------------------------------------------------------
sh_eval_cell:
    push ax
    push bx
    push si
    push di
    push es
    mov es, [sh_cellseg]
    mov ax, [es:di+SH_C_PASS]                ; this cell's last-computed pass
    cmp ax, [sh_pass]
    jne .stale
    test byte [es:di+4], 2            ; EVALUATING - already mid-computation
    jnz .cycle                        ; means a cycle, not a cache hit
    call sh_cellval_to_acc            ; a cache hit is a full double now, not
    call sh_acc_toint                 ; a word; DX stays the truncated form
    mov dx, ax                        ; for the callers that still want one
    jmp .out
.stale:
    test byte [es:di+4], 2
    jnz .cycle
    or byte [es:di+4], 2              ; EVALUATING = 1
    push di                           ; this cell's record offset, kept on
                                       ; the stack (NOT a global) because
                                       ; evaluating this formula may recurse
                                       ; into sh_eval_cell again for a cell
                                       ; it references, and call/ret through
                                       ; sh_pexpr is stack-neutral either way
    push word [sh_evrow]              ; stage 3.0d: ROW()/COLUMN()'s context,
    push word [sh_evcol]              ; banked for the SAME reason and popped
    mov ax, [es:di]                   ; at .writeback. A referenced cell's own
    and ax, SH_ROW_MASK               ; formula must answer for ITSELF, so this
    mov [sh_evrow], ax                ; is per-frame, not set once
    mov ax, [es:di+2]
    mov [sh_evcol], ax
    mov ax, [es:di+SH_C_FOFF]                 ; formula_off
    mov si, ax
    mov es, [sh_txtseg]
    cmp word [sh_evaldepth], SH_EVAL_MAXDEPTH
    jae .toodeep
    cmp word [sh_evaldepth], 0        ; a FRESH evaluation starts clean; a
    jne .nested                       ; nested one must not, or a referenced
    mov byte [sh_evalerr], 0          ; cell's error would be wiped on the way
    mov word [sh_sstk_sp], 0          ; back up. The string bank is reset with
    cmp sp, [sh_pstk0]                ; it, so an error path that returned
    jbe .depthok                      ; early cannot leak a level into the
    mov [sh_pstk0], sp                ; next formula. The SHALLOWEST fresh
    jmp short .depthok                ; evaluation is the stack's anchor
.nested:
    mov ax, [sh_pstk0]                ; 81.3: and a nested one is tested in
    sub ax, sp                        ; BYTES - a cold cell is 51 to 90 of
    jb .depthok                       ; them, and five SUMs deep ran task 0
    cmp ax, SH_PSTK_MAX               ; into its canary inside SH_PNEST_MAX
    ja .toodeep
.depthok:
    mov bx, [sh_evaldepth]
    inc word [sh_evaldepth]
    push bx                           ; this recursion level's buffer slot
    mov ax, SH_EDITMAX + 1
    mul bx
    add ax, sh_fbuf
    mov di, ax                        ; DI = this level's OWN copy of the
                                       ; formula text - a nested evaluation
                                       ; (of a cell THIS formula references)
                                       ; gets a DIFFERENT slot, so it cannot
                                       ; overwrite the text we are still
                                       ; parsing
    mov bx, di
.copyin:
    mov al, [es:si]
    mov [di], al                      ; DS-relative: our own scratch buffer
    inc si
    inc di
    or al, al
    jnz .copyin
    mov si, bx
    call sh_pcmp                      ; the result lands in sh_acc, and may
                                       ; have recursed to get there
    cmp byte [si], 0                  ; THE WHOLE FORMULA, OR IT IS NOT ONE
    je .whole                         ; (81.50). The parse used to stop quietly
    cmp byte [sh_evalerr], 0          ; at the first character it could not
    jne .whole                        ; use, so =1+2 3 answered 3 and =(1+2)3
    mov byte [sh_evalerr], SH_ERR_VALUE ; answered 3 - the "3.5kg" rule sh_commit
.whole:                               ; keeps for a number, and =1+'s rule
    pop bx                            ; for a formula that stops too soon
    dec word [sh_evaldepth]
    jmp .writeback
.toodeep:
    xor dx, dx
    push ax
    xor ax, ax
    call sh_acc_int                   ; too deep is a zero, in both forms
    pop ax
.writeback:
    pop word [sh_evcol]               ; stage 3.0d: ROW()/COLUMN() context,
    pop word [sh_evrow]               ; restored in the order it was pushed
    pop di                            ; this cell's record offset, restored
    mov es, [sh_cellseg]
    and byte [es:di+4], 0xFD          ; EVALUATING = 0 (HASFORMULA untouched)
    call sh_acc_toint                 ; DX = the truncated form, for callers
    mov dx, ax
    ; CACHING THE DOUBLE IS NOT THE FIRST THING ANY MORE, and it cannot be:
    ; sh_acc_to_cellval writes eight bytes over SH_C_VAL, and a TEXT result's
    ; slot offset lives in that same union (81.22.1). Doing it up front wiped
    ; the slot on every pass, so sh_str_store found VAL zero, allocated a fresh
    ; 65 bytes, and the arena was empty inside a hundred repaints - after which
    ; every text formula quietly fell back to the number underneath it, which
    ; is 0. Each branch below caches for itself, and the text one does not.
    mov al, [sh_evalerr]              ; the cell is stored by what it IS: an
    or al, al                         ; error, or a number again once whatever
    jz .notanerr                      ; broke it has been fixed
    call sh_acc_to_cellval
    mov byte [es:di+SH_C_TYPE], SH_T_ERR
    mov [es:di+SH_C_AUX], al
    mov byte [sh_curtype], SH_T_ERR   ; and PUBLISH it: the caller banked these
    mov [sh_curaux], al               ; two before the evaluation ran, so its
    jmp .errdone                      ; copy names the cell as it USED to be -
.notanerr:                            ; which paints #DIV/0! on a cell whose
    cmp byte [sh_curtype], SH_T_TEXT  ; stage 4.5: ...or the answer is a
    jne .notatext                     ; STRING, which SH_C_FOFF cannot hold
    call sh_str_store                 ; because the formula's own text is
    jc .notatext                      ; already there (81.22.1)
    mov byte [es:di+SH_C_TYPE], SH_T_TEXT
    mov byte [es:di+SH_C_AUX], 0
    mov ax, [es:di+SH_C_VAL]          ; the painter reads the RESULT, not the
    mov [sh_curtoff], ax              ; formula, so publish where it went
    jmp .errdone
.notatext:
    call sh_acc_to_cellval            ; cache the whole double
    mov ax, [es:di+SH_C_FOFF]         ; and a NUMERIC result publishes the
    mov [sh_curtoff], ax              ; formula's own text, which is what every
                                       ; reader of it has always expected
    mov al, SH_T_NUM                  ; ...or a LOGICAL one, the same double
    cmp byte [sh_curtype], SH_T_BOOL  ; with its own tag (81.51)
    jne .tagnum
    mov al, SH_T_BOOL
.tagnum:
    mov byte [es:di+SH_C_TYPE], al    ; divisor has since been fixed, and
    mov byte [es:di+SH_C_AUX], 0      ; #ERR on the one that is still broken
    mov [sh_curtype], al              ; (its code having been overwritten by
    mov byte [sh_curaux], 0           ; the last cell the formula referenced)
.errdone:
    mov ax, [sh_pass]
    mov [es:di+SH_C_PASS], ax
    jmp .out
.cycle:
    xor dx, dx
    push ax
    xor ax, ax
    call sh_acc_int                   ; a cycle is a zero, in both forms
    pop ax
.out:
    pop es
    pop di
    pop si
    pop bx
    pop ax
    ret

; =============================================================================
; Formula parser/evaluator - recursive descent over sh_fbuf (a DS-resident
; copy of the formula text; see sh_eval_cell). Grammar:
;   expr   := term (('+'|'-') term)*
;   term   := pow (('*'|'/') pow)*
;   pow    := factor ('^' pow)?            ; right-associative (stage 3.0d)
;   factor := '-' factor | '(' expr ')' | NUMBER | CELLREF | NAME '(' args ')'
;   args   := arg (',' arg)*
;   arg    := CELLREF ':' CELLREF | expr
; No whitespace skipping: sh_setformula drops every space on the way in
; except one between two operands, which is a mistake, and sh_eval_cell makes
; whatever the parse leaves over #VALUE! (81.50). This used to say the editor
; never let a space through, which no file reader ever promised.
; Every value is a 16-bit signed integer; division truncates toward zero
; (IDIV) and division by zero yields 0 rather than faulting - a stated
; simplification, not an oversight, matching this project's "no formulas,
; no formatting" -> "formulas, still no formatting" progression: nothing
; here produces or accepts a fraction. SUM/AVERAGE/MIN/MAX/COUNT are "the
; most common formulas" the roadmap asks for first; comparisons, IF() and
; the rest are later-stage work.
; =============================================================================

; sh_pcmp / sh_pcmpcont - comparison level, the actual top of the grammar
; (sh_eval_cell enters here, not at sh_pexpr): '=' '<' '>' '<=' '>=' '<>'
; between two '&'-level operands, answering a LOGICAL (81.51) by Excel's
; ordering of types (81.53). LEFT-ASSOCIATIVE, as Excel's are: =1<2<3 is
; (1<2)<3, TRUE against 3, and a logical is above every number - FALSE. It
; stopped after one comparison, which since 81.50 left "<3" over, #VALUE!.
sh_pcmp:
    call sh_pconcat
sh_pcmpcont:
    mov al, [si]
    cmp al, '='
    je .eq
    cmp al, '<'
    je .lt
    cmp al, '>'
    je .gt
    ret
.eq:                                  ; AH = the outcomes that answer TRUE:
    inc si                            ; 1 left below, 2 equal, 4 left above
    mov ah, 2
    jmp short .have
.lt:
    inc si
    mov ah, 1
    cmp byte [si], '='
    jne .lt2
    inc si
    mov ah, 3
    jmp short .have
.lt2:
    cmp byte [si], '>'
    jne .have
    inc si
    mov ah, 5
    jmp short .have
.gt:
    inc si
    mov ah, 4
    cmp byte [si], '='
    jne .have
    inc si
    mov ah, 6
    ; COMPARED BY TYPE (81.53). This compared the two NUMBERS and nothing
    ; else, so two texts compared as the zeros underneath them: ="a"="b" was
    ; TRUE and every IF(A1="yes",...) took its first branch. Excel's rule:
    ; text against text, case-insensitively (sh_lkstrcmp, the lookups' own);
    ; across types every number is below every text, below FALSE, below TRUE;
    ; a blank is 0 to a number, "" to a text and FALSE to a logical. BX, CX
    ; and DX are kept - CHOOSE counts in two of them across a whole argument.
.have:
    push bx
    push cx
    push dx
    mov al, [sh_curtype]              ; the LEFT operand's type, and its text
    cmp al, SH_T_TEXT                 ; banked where the right one's parse
    jne .nobank                       ; cannot reach it
    call sh_spush
    jnc .nobank
    mov al, SH_T_ERR                  ; the bank is full: #VALUE! is raised,
.nobank:                              ; and there is nothing to drop later
    push ax
    call sh_vpush
    call sh_pconcat                   ; the RIGHT at the '&' level: this was
    call sh_binop_pre                 ; sh_pexpr, so ="ab"="a"&"b" left the
    pop dx                            ; &"b" over. DH = outcomes, DL = left
    mov cl, [sh_curtype]              ; CL = the right's type
    mov bl, dl                        ; BL, CH: the types as COMPARED - a blank
    mov ch, cl                        ; takes the other side's
    cmp bl, SH_T_BLANK
    jne .lset
    mov bl, ch
.lset:
    cmp ch, SH_T_BLANK
    jne .rset
    mov ch, bl
.rset:
    mov al, bl
    call sh_cmprank
    mov ah, al
    mov al, ch
    call sh_cmprank                   ; AH = the left's rank, AL = the right's
    cmp ah, al
    je .same
    mov ax, -1                        ; MOV keeps CMP's flags
    jb .outcome
    mov ax, 1
    jmp short .outcome
.same:
    cmp al, 1
    je .text
    call fp_cmpab                     ; numbers and logicals: AX = -1/0/1
    jmp short .outcome
.text:
    push si
    push di
    mov si, sh_snull                  ; a blank side is ""
    cmp dl, SH_T_TEXT
    jne .ltext
    xor ax, ax
    call sh_sslot                     ; SI = the banked left text
.ltext:
    mov di, sh_snull
    cmp cl, SH_T_TEXT
    jne .rtext
    mov di, sh_sacc
.rtext:
    call sh_lkstrcmp
    pop di
    pop si
.outcome:
    cmp dl, SH_T_TEXT
    jne .nodrop
    call sh_spop                      ; the left text's bank
.nodrop:
    mov cl, 2
    or ax, ax
    jz .bit
    mov cl, 1
    js .bit
    mov cl, 4
.bit:
    xor ax, ax
    test dh, cl
    jz .res
    inc ax
.res:
    call sh_acc_int
    mov byte [sh_curtype], SH_T_BOOL  ; a COMPARISON answers a LOGICAL (81.51)
    pop dx
    pop cx
    pop bx
    jmp sh_pcmpcont                   ; ...and may be the left of another

; sh_cmprank - AL = a type -> AL = its rank for a comparison: 0 a number (or
; a blank that met one), 1 text, 2 a logical
sh_cmprank:
    cmp al, SH_T_TEXT
    je .t
    cmp al, SH_T_BOOL
    je .b
    xor al, al
    ret
.t:
    mov al, 1
    ret
.b:
    mov al, 2
    ret

; sh_pexpr / sh_pexprcont - additive level. sh_pexprcont is a real entry
; point of its own: sh_prange calls it to resume the +/- loop after folding
; a lone cell reference that turned out not to start a range.
sh_pexpr:
    call sh_pterm
sh_pexprcont:
    cmp byte [si], '+'
    je .add
    cmp byte [si], '-'
    je .sub
    ret
.add:
    call sh_chktext                   ; the LEFT operand, which sh_curtype
    inc si                            ; still describes
    call sh_vpush                     ; the left operand goes on the machine
    call sh_pterm                     ; stack: a double does not fit a register
    call sh_chktext                   ; ...and now the right
    call sh_binop_pre                 ; and the parse of the right may recurse
    call fp_add
    call sh_acc_store
    mov byte [sh_curtype], SH_T_NUM   ; stage 4.5: the RESULT of arithmetic is
    jmp sh_pexprcont                  ; a NUMBER whatever its operands were
                                       ; tagged. Nothing used to say so, so the
                                       ; tag left by the last cell an operand
                                       ; touched still stood - unobservable
                                       ; until sh_pargclass below made a
                                       ; mid-expression tag answerable
.sub:
    call sh_chktext
    inc si
    call sh_vpush
    call sh_pterm
    call sh_chktext
    call sh_binop_pre
    call fp_sub
    call sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    jmp sh_pexprcont

; -----------------------------------------------------------------------------
; sh_pconcat (stage 4.5) - the '&' level. Excel binds it LOOSER than '+' and
; TIGHTER than a comparison, so `="a"&"b"="ab"` compares two concatenations
; rather than concatenating a comparison (81.22.2).
;
; Either side may be a number - `=A1&"x"` with A1 holding 12 gives "12x", which
; is what every spreadsheet does - so a numeric operand is formatted into
; sh_sacc first. The left operand is banked in sh_sacc2 across the right one's
; parse, because parsing the right may recurse all the way back through here.
; -----------------------------------------------------------------------------
sh_pconcat:
    call sh_pexpr
sh_pconcatcont:
    cmp byte [si], '&'
    je .cat
    ret
.cat:
    inc si
    call sh_str_want                  ; the LEFT operand, as text, BANKED ON
    call sh_spush                     ; THE STRING STACK: the right one's parse
    sbb ax, ax                        ; can reach this routine again, and the
    push ax                           ; one global it was banked in was
    call sh_pexpr                     ; overwritten - ="a"&("b"&"c") was "bbc"
    call sh_str_want                  ; (81.53). AX = -1: the bank was full
    push si                           ; the RIGHT operand, as text, out of
    push di                           ; the way...
    mov si, sh_sacc
    mov di, sh_sacc2
    call sh_strcpy
    pop di
    pop si
    pop ax
    or ax, ax
    jnz .nobank                       ; #VALUE! is raised already
    call sh_srestore                  ; ...the left back into sh_sacc...
.nobank:
    push si
    push di
    mov si, sh_sacc2                  ; ...and the right appended
    call sh_str_cat
    pop di
    pop si
    mov byte [sh_curtype], SH_T_TEXT
    xor ax, ax
    call sh_acc_int
    jmp sh_pconcatcont

; -----------------------------------------------------------------------------
; sh_str_want - make sh_sacc hold the current result AS TEXT, whatever it is.
; A number is formatted the way the General format shows it, so `=1.5&"x"` is
; "1.5x" and not "1.500000x".
; -----------------------------------------------------------------------------
sh_str_want:
    cmp byte [sh_curtype], SH_T_TEXT
    je .done
    push ax
    push si
    push di
    cmp byte [sh_curtype], SH_T_BOOL  ; a LOGICAL is its name: ="x"&TRUE is
    jne .num                          ; "xTRUE", LEN(TRUE) is 4 (81.51)
    mov ax, [sh_acc+6]
    call sh_boolname
    jmp short .copy
.num:
    call sh_acc_load_a
    mov di, sh_numbuf
    mov ax, 10
    call fp_ftoa
.copy:
    mov si, sh_numbuf
    mov di, sh_sacc
    call sh_strcpy
    pop di
    pop si
    pop ax
.done:
    ret

; sh_pterm / sh_ptermcont - multiplicative level, same reasoning as above.
sh_pterm:
    call sh_ppow
sh_ptermcont:
    cmp byte [si], '*'
    je .mul
    cmp byte [si], '/'
    je .div
    ret
.mul:
    call sh_chktext
    inc si
    call sh_vpush
    call sh_ppow
    call sh_chktext
    call sh_binop_pre
    call fp_mul
    call sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    jmp sh_ptermcont
.div:
    call sh_chktext
    inc si
    call sh_vpush
    call sh_ppow
    call sh_chktext
    call sh_binop_pre
    call fp_div                       ; CF=1 means the divisor was zero
    jnc .divok
    mov byte [sh_evalerr], SH_ERR_DIV0
    xor ax, ax                        ; the value is still zero underneath -
    call sh_acc_int                   ; the flag is what the cell is stored by
    mov byte [sh_curtype], SH_T_NUM
    jmp sh_ptermcont
.divok:
    call sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    jmp sh_ptermcont

; sh_ppow (stage 3.0d) - the '^' level, between multiplication and the
; factors. RIGHT-associative, so 2^3^2 is 2^(3^2) = 512, which is what every
; spreadsheet does; the recursion below is what makes it so, where a loop like
; sh_ptermcont's would have made it left-associative.
;
; It binds TIGHTER than '*' and looser than unary minus, so -2^2 is -(2^2).
; That is Excel's own precedence and it surprises people, but matching it is
; the point.
;
; A negative exponent is a fraction and there is no fraction here, so it
; yields 0 - the same answer this evaluator already gives for division by
; zero, and for the same stated reason.
; sh_ppowcont is a real entry point of its own, like sh_ptermcont's: sh_prange
; calls it FIRST to resume a lone cell reference that turned out not to start
; a range - without it, `=SUM(A1^2)` left the '^' for sh_pfunc's argument loop,
; which can only stop at it.
sh_ppow:
    call sh_pfactor
sh_ppowcont:
    cmp byte [si], '^'
    jne .out
    call sh_chktext
    inc si
    call sh_pnest_enter               ; '^' recurses too (81.3)
    jc .nestfull
    call sh_vpush                     ; the BASE, banked
    call sh_ppow                      ; recurse: right-associative
    call sh_pnest_leave
    call sh_chktext
    mov byte [sh_curtype], SH_T_NUM
    call sh_acc_load_a                ; THE EXPONENT MAY BE FRACTIONAL NOW.
    call fp_a_to_b                    ; This banked it through sh_acc_toint
    pop word [sh_lhs]                 ; and multiplied the base by itself that
    pop word [sh_lhs+2]               ; many times, with a comment saying "a
    pop word [sh_lhs+4]               ; fractional power needs logarithms,
    pop word [sh_lhs+6]               ; which this file does not have" - which
    push si                           ; stopped being true at 84.10. 2^0.5 is
    mov si, sh_lhs                    ; 1.414 and not 1
    call fp_unpack_a
    pop si
    call fp_pow
    jnc .powok
    mov byte [sh_evalerr], SH_ERR_NUM ; a negative base to a fractional power
    call fp_azero                     ; has no real value
.powok:
    call sh_acc_store
.out:
    ret
.nestfull:
    push ax                           ; over the budget: the base is dropped,
    xor ax, ax                        ; and the #VALUE! sh_pnest_enter raised
    call sh_acc_int                   ; stands
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_pnest_enter / sh_pnest_leave - the parser's shared nesting budget (81.3).
; SH_EVAL_MAXDEPTH bounds cell-to-cell recursion, but nothing bounded a
; formula's OWN nesting: every '(', unary '-', '^' and nested call recurses
; the parser and banks bytes on task 0's 512-byte stack, and six
; memoization-cold cells chained that way could run SP off the stack's floor
; into .lowbss - silent corruption that fails later, somewhere unrelated.
; One counter charges every recursion point, with the cell depth folded in;
; over SH_PNEST_MAX the parse refuses with #VALUE! - the same refusal shape
; sh_eval_cell's .toodeep already has. A LEVEL IS NOT A SIZE, though: a '('
; is 12 bytes and a CHART.OVL door call 72, and a pending operator charges
; nothing, so the stack itself is the first test - SP against [sh_pstk0],
; SH_PSTK_MAX bytes down, as the kernel's LNK_SPMIN reads it (26.10).
; out: CF=1 refused (sh_evalerr raised, NOTHING charged - do not leave),
;      CF=0 charged - pair with exactly one sh_pnest_leave
; -----------------------------------------------------------------------------
sh_pnest_enter:
    push ax
    mov ax, [sh_pstk0]                ; the BYTES first: below the anchor
    sub ax, sp                        ; sh_eval_cell keeps, past SH_PSTK_MAX
    jb .room                          ; is past task 0's stack, whatever the
    cmp ax, SH_PSTK_MAX               ; levels say (a door call alone is 72)
    ja .full
.room:
    mov ax, [sh_pnest]
    inc ax
    add ax, [sh_evaldepth]
    cmp ax, SH_PNEST_MAX
    ja .full
    inc word [sh_pnest]
    pop ax
    clc
    ret
.full:
    pop ax
    mov byte [sh_evalerr], SH_ERR_VALUE
    stc
    ret

sh_pnest_leave:
    dec word [sh_pnest]
    ret

; sh_pfactor - unary minus, parens, a number, or an identifier (cell
; reference or function call, sh_pident tells them apart)
sh_pfactor:
    cmp byte [si], '-'
    jne .notneg
    inc si
    call sh_pnest_enter               ; unary minus recurses (81.3)
    jc .nestfull
    call sh_pfactor
    call sh_pnest_leave
    call sh_chktext                   ; -"text" is arithmetic too
    xor byte [sh_acc+7], 0x80         ; negate by flipping the sign BIT of the
    mov byte [sh_curtype], SH_T_NUM   ; packed double - cheaper than unpacking.
    ret                               ; A NUMBER, as every operator's result
                                      ; is: -TRUE is -1, not a logical (81.51)
                                      ; and, unlike `neg`, exact for every
                                      ; value including zero
.notneg:
    cmp byte [si], '('
    jne .notparen
    inc si
    call sh_pnest_enter               ; ...and so does a parenthesis
    jc .nestfull
    call sh_pcmp
    call sh_pnest_leave
    cmp byte [si], ')'
    jne .out                          ; malformed; return whatever we have
    inc si
    ret
.nestfull:
    push ax                           ; over the budget: sh_pnest_enter has
    xor ax, ax                        ; raised #VALUE!, and the refusal
    call sh_acc_int                   ; answers zero underneath it
    pop ax
    ret
.notparen:
    mov al, [si]
    cmp al, 34                        ; stage 4.5: a QUOTED LITERAL is a text
    je .strlit                        ; value (81.22)
    cmp al, '#'                       ; ...and an ERROR VALUE spelled out is a
    je .errlit                        ; literal too (81.26.2)
    cmp al, '$'                       ; stage 3.0e: '$A$1' is an IDENTIFIER,
    je .ident                         ; and this router decides that on the
    cmp al, 'A'                       ; FIRST character - without this line a
    jb .maybenum                      ; leading '$' falls through to the
    cmp al, 'Z'                       ; number path and the whole reference
    jbe .ident                        ; evaluates to 0. sh_pident tolerating
    cmp al, 'a'                       ; '$' is necessary but not sufficient.
    jb .maybenum
    cmp al, 'z'
    ja .maybenum
.ident:
    call sh_pident
    ret
.maybenum:
    jmp .maybenum2
.strlit:
    inc si                            ; past the opening quote
    push cx
    push di
    mov di, sh_sacc
    mov cx, SH_STR_MAX
.slc:
    jcxz .slend
    mov al, [si]
    or al, al
    jz .slend
    cmp al, 34                        ; a DOUBLED quote is one literal quote,
    jne .slkeep                       ; the same rule SYLK's K field uses
    cmp byte [si+1], 34
    jne .slend
    inc si
.slkeep:
    mov [di], al
    inc di
    inc si
    dec cx
    jmp .slc
.slend:
    mov byte [di], 0
    cmp byte [si], 34                 ; step over the closing quote if it is
    jne .slnoq                        ; there; an unterminated literal ends at
    inc si                            ; the end of the formula rather than
.slnoq:                               ; running off it
    pop di
    pop cx
    mov byte [sh_curtype], SH_T_TEXT
    xor ax, ax                        ; the number underneath a string is zero,
    call sh_acc_int                   ; so a reader that wants one gets a
    ret                               ; defined answer
.errlit:
    call sh_perrlit
    ret
.maybenum2:
    mov byte [sh_curtype], SH_T_NUM   ; a LITERAL is a number - say so, or the
    call fp_atof                      ; tag left by the last cell referenced
    jnc .numok                        ; still stands and `=B4+1` is judged by
    mov byte [sh_evalerr], SH_ERR_VALUE ; B4's type twice over
    xor ax, ax                        ; nothing parseable at all: `=1+` used to
    call sh_acc_int                   ; read as 1, an answer to a formula the
    ret                               ; user never finished writing
.numok:
    call sh_acc_store
.out:
    ret

; -----------------------------------------------------------------------------
; sh_perrlit (stage 4.5) - SI is at a '#'. An error value written out in full
; is a LITERAL, as it is in Excel, and this file needs to read one for a
; reason of its own: Delete Row and Delete Column now write `#REF!` into every
; formula that named a deleted cell (81.26.1), so the parser has to be able to
; read back what the rewriter wrote. Typing `=#N/A` works for the same reason,
; which is also what Excel does.
;
; The names come from sh_errtab - the same table sh_errname prints and
; sh_errcode reads - so the spelling written and the spelling recognised
; cannot drift apart. No name is a prefix of another, so first match wins.
;
; out: the error raised in sh_evalerr, sh_acc zero, SI past the name. A '#'
; followed by something else is #NAME?, which is what an unknown word already
; gets, and SI steps over the '#' so the parse can still make progress.
; -----------------------------------------------------------------------------
sh_perrlit:
    push bx
    push cx
    push di
    xor cx, cx
.try:
    cmp cx, 7
    jae .unknown
    mov bx, cx
    shl bx, 1
    mov di, [sh_errtab + bx]
    call sh_matchat                   ; is that name a prefix of SI?
    jc .found
    inc cx
    jmp .try
.found:
    mov bx, cx
    shl bx, 1
    mov di, [sh_errtab + bx]
.skip:
    cmp byte [di], 0
    je .done
    inc di
    inc si
    jmp .skip
.done:
    inc cx                            ; the table is 0-based, the ERROR.TYPE
    mov [sh_evalerr], cl              ; codes are 1-based
    jmp .out
.unknown:
    mov byte [sh_evalerr], SH_ERR_NAME
    inc si
.out:
    mov byte [sh_curtype], SH_T_NUM
    xor ax, ax
    call sh_acc_int
    pop di
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_psheetpfx - stage 2.0: does SI start a "SheetN!" cross-sheet prefix?
; Sheet names are the fixed "Sheet1".."SheetN" strings (see the Sheets menu
; comment), so this is a literal, case-insensitive match against "SHEET"
; plus a digit '1'..SH_SHEETS - not a general name lookup.
; in: SI; out: CF=1 and AX=0-based sheet index, SI advanced past the '!';
; CF=0 and SI unchanged otherwise
; -----------------------------------------------------------------------------
sh_psheetpfx:
    push bx
    push cx
    mov bx, si
    mov al, [bx]
    and al, 0xDF
    cmp al, 'S'
    jne .no
    inc bx
    mov al, [bx]
    and al, 0xDF
    cmp al, 'H'
    jne .no
    inc bx
    mov al, [bx]
    and al, 0xDF
    cmp al, 'E'
    jne .no
    inc bx
    mov al, [bx]
    and al, 0xDF
    cmp al, 'E'
    jne .no
    inc bx
    mov al, [bx]
    and al, 0xDF
    cmp al, 'T'
    jne .no
    inc bx
    mov al, [bx]
    cmp al, '1'
    jb .no
    cmp al, '0' + SH_SHEETS
    ja .no
    sub al, '1'
    xor ah, ah
    mov cx, ax                        ; cx = sheet index 0..SH_SHEETS-1
    inc bx
    cmp byte [bx], '!'
    jne .no
    inc bx
    mov si, bx
    mov ax, cx
    stc
    jmp .out
.no:
    clc
.out:
    pop cx
    pop bx
    ret

; sh_pident - in: SI at an identifier's first letter
; out: AX = value (a cell's value, or a function call's result), SI advanced
sh_pident:
    push bx
    push cx
    push dx
    push di
    mov byte [sh_pxsheet], 0xFF
    call sh_psheetpfx
    jnc .noxsheet
    mov [sh_pxsheet], al
.noxsheet:
    cmp byte [si], '$'                ; stage 3.0e: skip an absolute marker
    jne .nocoldollar                  ; before the column letters
    inc si
.nocoldollar:
    mov di, sh_ident
    xor cx, cx
.collect:
    mov al, [si]
    cmp al, 'A'
    jb .trydot
    cmp al, 'Z'
    jbe .isletter
    cmp al, 'a'
    jb .trydot
    cmp al, 'z'
    ja .trydot
    jmp .isletter
.trydot:
    cmp al, '.'                       ; stage 4.5: a '.' INSIDE a name, which
    jne .doneletters                  ; is how ERROR.TYPE is spelled. Only
    or cx, cx                         ; after a letter, so a LEADING '.' is
    jz .doneletters                   ; still the start of a number (`.5`) and
    cmp cx, SH_IDENT_MAX              ; a cell reference still cannot hold one
    jae .doneletters
    jmp .store                        ; ...and it does NOT go through the
                                       ; uppercase fold below: '.' AND 0xDF is
                                       ; 0x0E, which would have put a control
                                       ; character in the middle of the name
.isletter:
    cmp cx, SH_IDENT_MAX              ; 81.83: the COLLECTED length, which is
    jae .doneletters                  ; no longer a defined name's - a macro
                                       ; function name is LONGER than either
                                       ; (CALCULATE.NOW is 13). What a defined
                                       ; name may be is still SH_NAME_MAX and
                                       ; is checked where one is STORED
    and al, 0xDF                      ; normalize to uppercase
.store:
    mov [di], al
    inc di
    inc cx
    inc si
    jmp .collect
.doneletters:
    ; A NAME MAY END IN DIGITS - LOG10 is the first one that does, and it lexed
    ; as the column LOG followed by the row 10 (81.35). Excel's own rule is
    ; what settles it: letters then digits then '(' is a FUNCTION, and letters
    ; then digits then anything else is a CELL. So the digits are looked past
    ; without being consumed, and only a '(' beyond them pulls them into the
    ; name - a lookahead, so A1 and $A$1 reach the reference path untouched.
    push si
    push cx
.lkdig:
    mov al, [si]
    cmp al, '0'
    jb .lkend
    cmp al, '9'
    ja .lkend
    inc si
    inc cx
    jmp short .lkdig
.lkend:
    cmp byte [si], '('
    jne .nodigname
    cmp cx, SH_NAME_MAX
    ja .nodigname
    pop cx
    pop si
.digname:                             ; take them after all
    mov al, [si]
    cmp al, '0'
    jb .digdone
    cmp al, '9'
    ja .digdone
    mov [di], al
    inc di
    inc si
    inc cx
    jmp short .digname
.digdone:
    mov byte [di], 0
    jmp .isfunc
.nodigname:
    pop cx
    pop si
    mov byte [di], 0
    cmp byte [si], '$'                ; ...and before the row digits
    jne .norowdollar
    inc si
.norowdollar:
    mov al, [si]
    cmp al, '0'
    jb .isfunc
    cmp al, '9'
    ja .isfunc
    call sh_identcol                  ; sh_ident -> AX = 0-based column
    mov [sh_pcol], ax
    mov bx, si
    add bx, SH_EDITMAX + 1
    push es
    mov ax, ds
    mov es, ax
    call sh_pint                      ; SI advances past the digits
    pop es
    dec ax                            ; AX = 0-based row
    mov bx, ax
    mov ax, [sh_pcol]
    cmp byte [sh_pxsheet], 0xFF
    je .samesheet
    mov cx, [sh_cursheet]              ; stage 2.0: a "SheetN!" prefix -
    push cx                            ; temporarily point sh_findcell (via
    mov cl, [sh_pxsheet]               ; sh_cursheet) at the target sheet
    xor ch, ch                         ; for this one lookup, then put it
    mov [sh_cursheet], cx              ; back - every OTHER caller of
    call sh_getcell2                   ; sh_getcell2/sh_findcell is none the
    pop cx                             ; wiser
    mov [sh_cursheet], cx
    jmp .havecell
.samesheet:
    call sh_getcell2
.havecell:
    jmp .out                          ; nothing to do: sh_getcell2 leaves the
                                      ; value in sh_acc, and leaves a ZERO
                                      ; there for a cell that does not exist -
                                      ; which is what both branches here used
                                      ; to arrange by hand
.isfunc:
    cmp byte [si], '('                ; stage 3.0c: a DEFINED NAME is an
    je .reallyfunc                    ; identifier that is not a call. Excel
    push si                           ; resolves it the same way, and the
    mov si, sh_ident                  ; parenthesis is the only thing that
    call sh_name_lookup               ; separates SUM from a cell called SUM
    pop si
    jnc .reallyfunc
    ; AX = col, BX = row: the same shape sh_pcellref hands on, so the name
    ; reaches the evaluator as an ordinary reference and everything that
    ; already works for one - the cycle check, the memoization - works for it
    call sh_getcell2                  ; which leaves the value in sh_acc, and
    jmp .out                          ; a zero there for a cell that does not
                                       ; exist yet - exactly as a reference to
                                       ; an empty cell already behaves
.reallyfunc:
    call sh_pfunc
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; sh_identcol - in: sh_ident = NUL-terminated uppercase letters (1-2 chars)
; out: AX = 0-based column index (the bijective base-26 sh_colname inverts)
sh_identcol:
    push bx
    push cx
    push si
    mov si, sh_ident
    xor ax, ax
.loop:
    mov cl, [si]
    or cl, cl
    jz .done
    sub cl, 'A'
    inc cl
    xor ch, ch
    mov bx, 26
    mul bx
    add ax, cx
    inc si
    jmp .loop
.done:
    dec ax
    pop si
    pop cx
    pop bx
    ret

; sh_pcellref - a backtracking probe: does SI start a bare cell reference?
; in: SI; out: CF=1 yes (AX=col, BX=row, SI advanced past it),
;             CF=0 no (SI UNCHANGED - the caller falls back to sh_pexpr)
; Used only to tell a range's "A1:B5" apart from a plain expression that
; merely starts with a cell reference, like "A1+5".
sh_pcellref:
    push cx
    push di
    push si                           ; the only way back out on failure
    cmp byte [si], '$'                ; stage 3.0e: '$' is PURELY TEXTUAL -
    jne .nocoldollar                  ; it changes what the rewriters do, not
    inc si                            ; what this evaluates to, so the parser
.nocoldollar:                         ; only has to skip it
    mov al, [si]
    cmp al, 'A'
    jb .fail
    cmp al, 'Z'
    jbe .ok
    cmp al, 'a'
    jb .fail
    cmp al, 'z'
    ja .fail
.ok:
    mov di, sh_ident
    xor cx, cx
.collect:
    mov al, [si]
    cmp al, 'A'
    jb .doneletters
    cmp al, 'Z'
    jbe .isletter
    cmp al, 'a'
    jb .doneletters
    cmp al, 'z'
    ja .doneletters
.isletter:
    cmp cx, 2
    jae .doneletters                  ; 3+ letters: a NAME, not a column
    and al, 0xDF
    mov [di], al
    inc di
    inc cx
    inc si
    jmp .collect
.doneletters:
    mov byte [di], 0
    or cx, cx
    jz .fail
    cmp byte [si], '$'                ; ...and again before the row digits
    jne .norowdollar
    inc si
.norowdollar:
    mov al, [si]
    cmp al, '0'
    jb .fail
    cmp al, '9'
    ja .fail
    call sh_identcol
    mov cx, ax                        ; CX = col, held across sh_pint
    mov bx, si
    add bx, SH_EDITMAX + 1
    push es
    mov ax, ds
    mov es, ax
    call sh_pint
    pop es
    dec ax                            ; AX = 0-based row
    mov bx, ax
    mov ax, cx                        ; AX = col
    add sp, 2                         ; discard the saved SI - keep advancing
    stc
    jmp .out
.fail:
    pop si                            ; restore SI - this was not a cellref
    clc
.out:
    pop di
    pop cx
    ret

; sh_prange - one comma-separated function argument: a range, or a single
; expression (which may itself start with, but not be, a cell reference -
; "A1" alone IS the range-shorthand for a single cell; "A1+5" is not a
; range at all). Folds into sh_pacc/sh_pcnt/sh_phave per sh_pfid.
sh_prange:
    push ax
    push bx
    call sh_pnamerange                ; stage 4.6: `=SUM(Sales)` where Sales
    jc .fold                          ; names a block folds the block (81.29)
    call sh_pcellref
    jnc .plainexpr
    cmp byte [si], ':'
    jne .singlecell
    inc si
    mov [sh_r1col], ax
    mov [sh_r1row], bx
    call sh_pcellref
    jnc .out                          ; malformed range; contributes nothing
    mov [sh_r2col], ax
    mov [sh_r2row], bx
    call sh_normrange
.isect:
    cmp byte [si], ' '                ; stage 4.5: Excel's INTERSECTION
    jne .fold                         ; operator is a space, and an empty
    mov ax, si                        ; intersection is the one and only
    call sh_pintersect                ; thing that produces #NULL! (81.26.3)
    jc .out                           ; empty: there is nothing to fold
    cmp ax, si
    je .fold                          ; nothing consumed - the space was not
    jmp .isect                        ; an operator after all
.fold:
    call sh_foldrange
    jmp .out
.singlecell:
    call sh_getcell2                  ; the value lands in sh_acc either way -
.havev:                               ; getcell2 puts a zero there for a cell
    call sh_ppowcont                  ; that does not exist. Tightest binding
    call sh_ptermcont                 ; first: '^', then '*', then '+', then
    call sh_pexprcont                 ; '&', then the comparison (81.22.2)
    call sh_pconcatcont
    call sh_pcmpcont
    call sh_foldvalue
    jmp .out
.plainexpr:
    call sh_pcmp
    cmp byte [sh_curtype], SH_T_BOOL  ; SUM(TRUE,1) is 2: a logical TYPED as
    jne .pefold                       ; an argument is its number, and only
    mov byte [sh_curtype], SH_T_NUM   ; one read from a cell is stepped over
.pefold:                              ; (81.51)
    call sh_foldvalue
.out:
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_pnamerange - is the argument at SI a DEFINED NAME and nothing else?
;
; in:  SI at the start of an argument
; out: CF=1 - sh_r1col/row..sh_r2col/row hold the rectangle it names and SI is
;             past it; CF=0 - not a name, SI UNCHANGED.
;
; Strict about "nothing else" for the same reason sh_pargref is (81.23): a ','
; or the ')' has to follow, so `=SUM(Sales+1)` is an expression about Sales
; and not a fold over it. A name followed by '(' is a FUNCTION CALL - that is
; the only thing separating SUM from a cell called SUM - and is declined here
; so sh_pfunc still gets it.
;
; A one-cell name resolves to a 1x1 rectangle and folds to the same single
; value the expression path already gave it, so nothing that worked before
; takes a different route to a different answer.
; -----------------------------------------------------------------------------
sh_pnamerange:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov di, sh_ident
    xor cx, cx
.collect:
    mov al, [si]
    cmp al, 'A'
    jb .done
    cmp al, 'Z'
    jbe .keep
    cmp al, 'a'
    jb .done
    cmp al, 'z'
    ja .done
.keep:
    cmp cx, SH_NAME_MAX
    jae .fail
    and al, 0xDF
    mov [di], al
    inc di
    inc cx
    inc si
    jmp .collect
.done:
    mov byte [di], 0
    or cx, cx
    jz .fail                          ; nothing here at all
    mov al, [si]
    cmp al, ','
    je .look
    cmp al, ')'
    jne .fail                         ; '(' lands here too: a call, not a name
.look:
    push si
    mov si, sh_ident
    call sh_name_lookup
    pop si
    jnc .fail
    mov [sh_r1col], ax
    mov [sh_r1row], bx
    mov [sh_r2col], cx
    mov [sh_r2row], dx
    call sh_normrange
    pop di                            ; DI was pushed LAST, so it comes off
    add sp, 2                         ; first - then discard the saved SI and
    pop dx                            ; keep advancing
    pop cx
    pop bx
    pop ax
    stc
    ret
.fail:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    clc
    ret

; -----------------------------------------------------------------------------
; sh_normrange - put sh_r1col/row..sh_r2col/row in top-left/bottom-right
; order. Split out of sh_foldrange so sh_pintersect can rely on both
; rectangles being normalised before it compares their edges.
sh_normrange:
    push ax
    push bx
    mov ax, [sh_r1col]
    mov bx, [sh_r2col]
    cmp ax, bx
    jle .colok
    xchg ax, bx
.colok:
    mov [sh_r1col], ax
    mov [sh_r2col], bx
    mov ax, [sh_r1row]
    mov bx, [sh_r2row]
    cmp ax, bx
    jle .rowok
    xchg ax, bx
.rowok:
    mov [sh_r1row], ax
    mov [sh_r2row], bx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
sh_pintersect:
    push ax
    push bx
    push si
.spaces:
    cmp byte [si], ' '
    jne .second
    inc si
    jmp .spaces
.second:
    call sh_pcellref
    jnc .nope
    mov [sh_ix1col], ax
    mov [sh_ix1row], bx
    mov [sh_ix2col], ax
    mov [sh_ix2row], bx
    cmp byte [si], ':'
    jne .haveit
    inc si
    call sh_pcellref
    jnc .nope
    mov [sh_ix2col], ax
    mov [sh_ix2row], bx
.haveit:
    mov ax, [sh_ix1col]               ; normalise the second rectangle too -
    mov bx, [sh_ix2col]               ; `B5:A1` names the same block as
    cmp ax, bx                        ; `A1:B5` and must intersect the same
    jle .c2ok
    xchg ax, bx
.c2ok:
    mov [sh_ix1col], ax
    mov [sh_ix2col], bx
    mov ax, [sh_ix1row]
    mov bx, [sh_ix2row]
    cmp ax, bx
    jle .r2ok
    xchg ax, bx
.r2ok:
    mov [sh_ix1row], ax
    mov [sh_ix2row], bx
    mov ax, [sh_ix1col]               ; the intersection is the later start
    cmp ax, [sh_r1col]                ; and the earlier end, on each axis
    jbe .e1
    mov [sh_r1col], ax
.e1:
    mov ax, [sh_ix2col]
    cmp ax, [sh_r2col]
    jae .e2
    mov [sh_r2col], ax
.e2:
    mov ax, [sh_ix1row]
    cmp ax, [sh_r1row]
    jbe .e3
    mov [sh_r1row], ax
.e3:
    mov ax, [sh_ix2row]
    cmp ax, [sh_r2row]
    jae .e4
    mov [sh_r2row], ax
.e4:
    mov ax, [sh_r1col]
    cmp ax, [sh_r2col]
    ja .empty
    mov ax, [sh_r1row]
    cmp ax, [sh_r2row]
    ja .empty
    add sp, 2                         ; discard the saved SI - keep advancing
    pop bx
    pop ax
    clc
    ret
.empty:
    mov byte [sh_evalerr], SH_ERR_NULL
    add sp, 2
    pop bx
    pop ax
    stc
    ret
.nope:
    pop si                            ; not a range after the space: put SI
    pop bx                            ; back, and the caller folds the first
    pop ax                            ; range alone
    clc
    ret

; -----------------------------------------------------------------------------
; sh_foldrange - in: sh_r1col/row, sh_r2col/row (either corner order);
; folds every OCCUPIED cell in the rectangle via sh_foldvalue.
;
; It walks the RECORD ARRAY, not the rectangle (81.3): records are sorted by
; (packed row, col) - the stage 2.0 comment above sh_findcell - so ONE binary
; search finds the first corner and a forward scan visits exactly the records
; in the row span. Walking every coordinate was O(area x log n): the ordinary
; =SUM(A1:A16384) idiom was 16,384 searches inside the paint callback, seconds
; per repaint on the 8088 and invisible in an emulator (PERFORMANCE.md rule 6).
; The bound rides in SI and the cursor in DI because sh_getcell2 preserves
; both across the evaluation a formula cell runs; the end offset is a
; function of [sh_ncells] alone, the same for a nested fold, so sh_rrow can
; hold it.
; -----------------------------------------------------------------------------
sh_foldrange:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    call sh_normrange                  ; split out for sh_pintersect's sake
    mov ax, [sh_ncells]
    mov bx, SH_C_SZ
    mul bx
    mov [sh_rrow], ax                  ; end-of-array offset
    mov ax, [sh_cursheet]              ; the far corner, PACKED the way the
    mov cl, SH_ROW_BITS                ; records store a row (sh_findcell)
    shl ax, cl
    or ax, [sh_r2row]
    mov si, ax                         ; SI = the packed bound
    mov ax, [sh_r1col]
    mov bx, [sh_r1row]
    call sh_findcell                   ; found or not, DI = the first record
                                        ; at or after the near corner
.scan:
    cmp di, [sh_rrow]
    jae .done                          ; past the last record
    mov es, [sh_cellseg]               ; reloaded every pass: an evaluation
    mov ax, [es:di]                    ; below moves ES. AX = packed row
    cmp ax, si
    jg .done                           ; sorted (signed, as sh_findcell
    mov bx, [es:di+2]                  ; compares): past the last row is done
    cmp bx, [sh_r1col]
    jb .next
    cmp bx, [sh_r2col]
    ja .next
    and ax, SH_ROW_MASK                ; a hit: unpack the row and fold it
    xchg ax, bx                        ; AX = col, BX = row
    push word [sh_r1col]               ; A FORMULA CELL IN THE RANGE MAY FOLD A
    push word [sh_r2col]               ; RANGE OF ITS OWN, through these same
    call sh_getcell2                   ; two words: =SUM(D55:I55) over six
    pop word [sh_r2col]                ; column SUMs scanned D alone after the
    pop word [sh_r1col]                ; first one ran, and answered its total.
                                       ; Excel 2.1d's own EXPENSES.XLS found it
                                       ; (81.52). The row bound is in SI and
                                       ; sh_rrow cannot change; the lookups
                                       ; refuse the same shape instead (47)
    jnc .next                          ; tag, format and sh_acc, exactly as
                                       ; an operand's read loads them
    call sh_foldvalue                  ; sh_acc is the value; see sh_foldvalue
.next:
    add di, SH_C_SZ
    jmp .scan
.done:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_foldvalue - fold the value in sh_acc into the running sh_pacc, per the
; function being parsed (sh_pfid).
;
; sh_pacc is EIGHT BYTES now, not a word: SUM over a column of decimals has to
; keep them. The incoming value arrives in sh_acc rather than in AX for the
; same reason, and both are packed doubles - fp A and B are scratch here and
; are reloaded on every fold, because the range walker between calls uses them
; itself.
; -----------------------------------------------------------------------------
sh_foldvalue:
    push ax
    push bx
    cmp byte [sh_curtype], SH_T_BOOL   ; A LOGICAL IN A REFERENCE is stepped
    jne .notbool                       ; over like a label - Excel's rule for
    cmp word [sh_pfid], 8              ; SUM and every numeric fold - except
    je .counted                        ; by AND and OR, which are about
    cmp word [sh_pfid], 9              ; nothing else. One typed as an argument
    je .counted                        ; counts: sh_prange makes it a number
    jmp short .astext                  ; before it gets here (81.51)
.notbool:
    cmp byte [sh_curtype], SH_T_TEXT   ; stage 4.5: a LABEL is not a number and
    jne .counted                       ; every numeric fold steps over it -
.astext:
    cmp word [sh_pfid], 11             ; SUM, MIN, MAX and PRODUCT because a
    jne .out                           ; label has no value, and AVERAGE for a
    inc word [sh_pcnt]                 ; second reason on top of that: it
    jmp .out                           ; divides by sh_pcnt, so counting a
                                       ; label would drag the mean toward zero
                                       ; without ever adding to the total.
                                       ; COUNTA (11) is the one that WANTS it,
                                       ; and this is the first release in
                                       ; which COUNT and COUNTA can disagree
                                       ; about anything at all.
.counted:
    inc word [sh_pcnt]
    mov bx, [sh_pfid]
    cmp bx, 0
    je .sum
    cmp bx, 1
    je .sum                           ; AVERAGE sums here; sh_funcfinish
                                       ; divides once the count is final
    cmp bx, 2
    je .min
    cmp bx, 3
    je .max
    cmp bx, 8
    je .and
    cmp bx, 9
    je .or
    cmp bx, 10
    je .product
    cmp bx, 77
    jae .stat
    jmp .out                          ; COUNT (4), COUNTA (11) or unknown:
                                       ; pcnt alone is enough
.stat:
    call sh_pacc_to_a                 ; the running sum, as SUM does...
    call sh_acc_load_b
    call fp_add
    call sh_pacc_from_a
    call sh_acc_load_a                ; ...and the sum of SQUARES beside it
    call sh_acc_load_b
    call fp_mul                       ; A = x * x
    call fp_a_to_b                    ; ...to B, so the running total can
    push si                           ; come into A
    mov si, sh_pacc2
    call fp_unpack_a
    pop si
    call fp_add
    push di
    mov di, sh_pacc2
    call fp_pack_a
    pop di
    jmp .out
.sum:
    call sh_pacc_to_a
    call sh_acc_load_b
    call fp_add
    call sh_pacc_from_a
    jmp .out
.product:
    call sh_pacc_to_a
    call sh_acc_load_b
    call fp_mul
    call sh_pacc_from_a
    jmp .out
.min:
    cmp word [sh_phave], 0
    jnz .mincmp
    call sh_acc_to_pacc
    mov word [sh_phave], 1
    jmp .out
.mincmp:
    call sh_acc_load_a                ; is the new value below the running one?
    call sh_pacc_to_b
    call fp_cmpab
    jge .out
    call sh_acc_to_pacc
    jmp .out
.max:
    cmp word [sh_phave], 0
    jnz .maxcmp
    call sh_acc_to_pacc
    mov word [sh_phave], 1
    jmp .out
.maxcmp:
    call sh_acc_load_a
    call sh_pacc_to_b
    call fp_cmpab
    jle .out
    call sh_acc_to_pacc
    jmp .out
.and:
    call sh_acc_iszero
    jnc .out                          ; nonzero folds in as true: no-op
    xor ax, ax                        ; any false value forces AND to false
    call sh_int_to_pacc
    jmp .out
.or:
    call sh_acc_iszero
    jc .out                           ; zero folds in as false: no-op
    mov ax, 1                         ; any true value forces OR to true
    call sh_int_to_pacc
.out:
    pop bx
    pop ax
    ret

; --- the small movers the fold above is written in terms of ------------------
sh_pacc_to_a:
    push si
    mov si, sh_pacc
    call fp_unpack_a
    pop si
    ret

sh_pacc_to_b:
    push si
    mov si, sh_pacc
    call fp_unpack_b
    pop si
    ret

sh_pacc_from_a:
    push di
    mov di, sh_pacc
    call fp_pack_a
    pop di
    ret

sh_acc_to_pacc:
    push ax
    push si
    push di
    mov si, sh_acc
    mov di, sh_pacc
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    pop si
    pop ax
    ret

; sh_int_to_pacc - AX (signed) -> sh_pacc
sh_int_to_pacc:
    call fp_i2a
    call sh_pacc_from_a
    ret

; sh_esatof - parse a decimal number from ES:SI into sh_acc, advancing SI past
; it. fp_atof reads DS:SI and the file staging buffer is in ES, so the token is
; copied across first - up to a ';' or the record's end. Without this, a SYLK
; K field would still be read by the integer parser and "3.5" would come back
; as 3, which is what the round trip actually did before this existed.
section SH_MODSEC                      ; 82.16.9
sh_esatof:
    push ax
    push cx
    push di
    mov di, sh_numbuf
    mov cx, 24
.copy:
    jcxz .done
    cmp si, bx
    jae .done
    mov al, [es:si]
    cmp al, ';'
    je .done
    cmp al, 13
    je .done
    cmp al, 10
    je .done
    mov [di], al
    inc di
    inc si
    dec cx
    jmp .copy
.done:
    mov byte [di], 0
    push si
    mov si, sh_numbuf
    SHOUT fp_atof
    pop si
    SHOUT sh_acc_store
    pop di
    pop cx
    pop ax
    ret

; The same three, for a record addressed through SI - the file writers, the
; chart scan and sort all walk the array with SI rather than DI.
section .text
sh_cellval_to_acc_si:
    push ax
    push cx
    push si
    push di
    mov di, sh_acc
    mov cx, 4
.s2a:
    mov ax, [es:si+SH_C_VAL]
    mov [di], ax
    add si, 2
    add di, 2
    dec cx
    jnz .s2a
    pop di
    pop si
    pop cx
    pop ax
    ret



; sh_cellnum - the value of the record at ES:DI, formatted into sh_numbuf as
; a decimal. What "read the word and sh_itoa it" used to do, except that the
; value is eight bytes now and its low word on its own is meaningless.
sh_cellnum:
    cmp byte [es:di+SH_C_TYPE], SH_T_ERR   ; ...and an ERROR its name (81.61):
    jne .noterr                           ; this wrote the zero underneath, so
    push ax                               ; a copied #N/A pasted as 0
    mov al, [sh_curaux]
    push ax
    mov al, [es:di+SH_C_AUX]
    mov [sh_curaux], al
    call sh_errname
    pop ax
    mov [sh_curaux], al
    pop ax
    ret
.noterr:
    cmp byte [es:di+SH_C_TYPE], SH_T_BOOL  ; a LOGICAL is its name here too -
    jne .num                              ; the formula bar, Copy and Paste
    push ax                               ; all read it through this (81.51)
    mov ax, [es:di+SH_C_VAL+6]
    call sh_boolname
    pop ax
    ret
.num:
    push ax
    push di
    call sh_cellval_to_acc
    call sh_acc_load_a
    mov di, sh_numbuf
    mov ax, 10
    call fp_ftoa
    pop di
    pop ax
    ret

; sh_cellval_to_acc / sh_acc_to_cellval - the eight value bytes of the record
; at ES:DI. DI is left where it started, which matters: every caller is still
; using it as the record's offset.
sh_cellval_to_acc:
    push ax
    push cx
    push si
    push di
    mov si, sh_acc
    mov cx, 4
.c2a:
    mov ax, [es:di+SH_C_VAL]
    mov [si], ax
    add di, 2
    add si, 2
    dec cx
    jnz .c2a
    pop di
    pop si
    pop cx
    pop ax
    ret

sh_acc_to_cellval:
    push ax
    push cx
    push si
    push di
    mov si, sh_acc
    mov cx, 4
.a2c:
    mov ax, [si]
    mov [es:di+SH_C_VAL], ax
    add di, 2
    add si, 2
    dec cx
    jnz .a2c
    pop di
    pop si
    pop cx
    pop ax
    ret

; sh_acc_iszero - CF=1 if sh_acc is zero. The exponent and mantissa are all
; that matter; a negative zero is still zero, so the sign byte is masked off.
sh_acc_iszero:
    push ax
    push bx
    mov ax, [sh_acc]
    or ax, [sh_acc+2]
    or ax, [sh_acc+4]
    mov bx, [sh_acc+6]
    and bx, 0x7FFF
    or ax, bx
    pop bx
    pop ax
    jnz .no
    stc
    ret
.no:
    clc
    ret

; sh_funcfinish - the accumulated sh_pacc/sh_pcnt -> the function's result
sh_funcfinish:
    push bx
    mov bx, [sh_pfid]
    cmp bx, 1
    je .average
    cmp bx, 4
    je .count
    cmp bx, 11
    je .count                         ; COUNTA answers from the COUNT of things
                                       ; folded, not from the accumulator - it
                                       ; is identical to COUNT while every
                                       ; value in this model is a number, and
                                       ; separating them is Stage 4.0's job,
                                       ; when text and blanks become tellable
                                       ; apart. Without this it returned
                                       ; sh_pacc, which for a non-summing fold
                                       ; is always 0.
    cmp bx, 77
    jae .stat
    call sh_pacc_to_a                 ; SUM/MIN/MAX/PRODUCT (and unknown):
    call sh_acc_store                 ; whatever was folded, zero if nothing
    jmp .fout
; --- VAR / VARP / STDEV / STDEVP (SPEC.md 81.34) -----------------------------
; variance = (sum of squares - sum*sum/n) / d, where d is n for the POPULATION
; forms and n-1 for the SAMPLE ones; the standard deviations are its square
; root. ONE PASS, which is what the fold machinery gives - Excel 2.1's own
; arithmetic, and its accuracy: subtracting two large nearly-equal numbers
; loses digits when the mean is far from zero. A spreadsheet of this era did
; the same, and the two-pass form would need the range walked twice, which
; this parser cannot do - it folds as it PARSES.
.stat:
    mov cx, [sh_pcnt]
    cmp bx, 78                        ; VARP and STDEVP divide by n...
    je .popn
    cmp bx, 80
    je .popn
    dec cx                            ; ...VAR and STDEV by n-1, and a single
.popn:                                ; value therefore has no sample variance
    or cx, cx
    jg .statok
    mov byte [sh_evalerr], SH_ERR_DIV0  ; #DIV/0! is Excel's own answer to
    xor ax, ax                        ; VAR of one number
    call sh_acc_int
    jmp .fout
.statok:
    push cx                           ; CX = the divisor, banked across the
    call sh_pacc_to_a                 ; arithmetic below
    call sh_pacc_to_b                 ; A = B = the sum
    call fp_mul                       ; A = sum * sum
    mov ax, [sh_pcnt]
    call fp_i2b
    call fp_div                       ; A = sum*sum/n
    call fp_a_to_b                    ; ...to B
    push si
    mov si, sh_pacc2                  ; A = the sum of squares
    call fp_unpack_a
    pop si
    call fp_sub                       ; A = sumsq - sum*sum/n
    pop cx
    mov ax, cx
    call fp_i2b
    call fp_div                       ; A = that / d
    cmp bx, 79                        ; STDEV and STDEVP are its square root
    jb .statdone
    call fp_sqrt
.statdone:
    call sh_acc_store                 ; sh_stbusy is not cleared here: sh_pfunc
    jmp .fout                         ; banks and restores it, so every exit
                                       ; path is covered and not just this one
.average:
    cmp word [sh_pcnt], 0
    jne .avgok
    xor ax, ax
    call sh_acc_int
    jmp .fout
.avgok:
    call sh_pacc_to_a                 ; A REAL MEAN NOW, not a truncated one:
    mov ax, [sh_pcnt]                 ; AVERAGE(1,2) is 1.5 where the integer
    call fp_i2b                       ; evaluator gave 1
    call fp_div
    call sh_acc_store
    jmp .fout
.count:
    mov ax, [sh_pcnt]
    call sh_acc_int
    jmp .fout
.fout:
.out:
    pop bx
    ret

; sh_pfunc - in: SI right after a function NAME (sh_ident holds it),
; expecting '(' next; out: AX=value, SI advanced past the closing ')'.
; Saves/restores sh_pfid/sh_pacc/sh_pcnt/sh_phave around itself, so a
; function call nested inside another's argument list (SUM(A1,MAX(B1:B9)))
; cannot corrupt the outer accumulator.
sh_pfunc:
    push bx
    push cx
    push dx
    push word [sh_pfid]
    push word [sh_pacc+6]             ; ALL EIGHT bytes: sh_pacc is a packed
    push word [sh_pacc+4]             ; double (stage 4.0), and banking only
    push word [sh_pacc+2]             ; its low word handed the outer fold the
    push word [sh_pacc]               ; inner call's accumulator back
    push word [sh_pcnt]
    push word [sh_phave]
    push word [sh_stbusy]             ; BANKED, not cleared on the way out: an
                                       ; error path that never reached
                                       ; sh_funcfinish would otherwise leave a
                                       ; variance fold marked live for the
                                       ; rest of the session, and every VAR
                                       ; after it would refuse (81.34.1)
    xor dx, dx                        ; DX = result; 0 covers every bad exit
    mov word [sh_pfid], 0xFFFF        ; THIS call's id, for .done's logical
                                      ; test (81.51); banked above, so a nested
                                      ; call's cannot outlive it
    call sh_pnest_enter               ; a nested call is a recursion point too
    jc .popout                        ; (81.3); too deep answers 0 + #VALUE!
    cmp byte [si], '('
    je .paren
    call sh_funcid                    ; =TRUE WITHOUT BRACKETS is Excel's
    cmp al, 20                        ; logical constant, and was #NAME? here
    je .bare                          ; (81.51). sh_ident still holds the word
    cmp al, 21
    jne .noparen
.bare:
    xor ah, ah
    mov [sh_pfid], ax
    neg al
    add al, 21                        ; TRUE (20) is 1, FALSE (21) is 0
    mov dx, ax
    call sh_acc_int
    jmp .typed
.paren:                               ; a bare word that resolved to no defined
    inc si                            ; name is #NAME?, exactly as in Excel -
    call sh_funcid                    ; sh_pident only routes one here once
    xor ah, ah                        ; sh_name_lookup has already declined it
    cmp ax, 0xFF                      ; macro plan wave 0: not resident - then
    jne .knownfn                      ; ask CHART.OVL, where every macro
    call sh_mfind_r                   ; function after the first twenty lives
    cmp ax, 0xFF
    jne .knownfn
    push bx                           ; ...and a DEFINED NAME called like a
    push cx                           ; function is a SUBROUTINE (Excel's
    push dx                           ; `ref(arg1, ...)`, macro plan wave 1).
    push si                           ; DX is this routine's result and must
    mov si, sh_ident                  ; still be 0 on the #NAME? path, which
    call sh_name_lookup               ; is why all three are banked
    pop si
    pop dx
    pop cx
    pop bx
    mov ax, 0xFF
    jnc .knownfn
    mov ax, SH_FID_MCALL              ; a macro COMMAND like any other: inert,
.knownfn:                             ; and FALSE, outside the step engine
    mov [sh_pfid], ax
    cmp ax, 0xFF                      ; ...and so is a CALL to a function this
    je .noname                        ; app does not have. Reading either as a
    cmp ax, SH_FID_MX                 ; an EXTENSION id is a macro function,
    jae .domacro                      ; and it is above every other range
    cmp ax, 5
    je .doif
    cmp ax, 24                        ; CHOOSE answers a VALUE, not an integer
    je .dochoose                      ; (81.49) - IF's route, not sh_pspecial's
    cmp ax, 6
    je .donot
    cmp ax, 7
    je .doabs
    cmp ax, 109                        ; RAND() is nullary like NOW()
    je .dorand
    cmp ax, 110                        ; INDIRECT is a TEXT function that
    je .dotext                         ; answers with a VALUE - it takes the
                                       ; string apart and reads what it names
    cmp ax, 108                        ; CLEAN joins the TEXT functions, whose
    je .dotext                         ; result is a string
    cmp ax, 107                        ; ISNONTEXT joins the INFORMATION ones,
    je .doinfo                         ; whose argument stays a reference
    cmp ax, 106                        ; NOW() is nullary and reads the BIOS
    je .donow                          ; clock - nothing else here does either
    cmp ax, SH_FID_MDETERM              ; 143+ are the ARRAY/MATRIX functions
    jae .domatrix                      ; (81.67) - ABOVE SH_FID_CELL's own id,
                                        ; so this test runs first
    cmp ax, SH_FID_CELL                ; 142 is CELL (81.66)
    je .docell
    cmp ax, SH_FID_DATABASE            ; 131+ are the DATABASE functions
    jae .dodatabase                    ; (81.65) - ABOVE SH_FID_MACRO's own
                                        ; range, so this test runs FIRST or
                                        ; the macro check below would catch
                                        ; them too
    cmp ax, SH_FID_MACRO               ; 111+ are the MACRO functions (81.63),
    jae .domacro                       ; which act only for the step engine
    cmp ax, 93                         ; 93+ are the FINANCIAL functions, on
    jae .dofin                         ; the same layer one level up
    cmp ax, 81                         ; 81+ are the LOGARITHMS and their
    jae .dotrans                       ; friends, on the transcendental layer
    cmp ax, 77                         ; 77+ are the VARIANCE folds. They walk
    jb .notstat                        ; their arguments exactly as SUM does,
    cmp byte [sh_stbusy], 0            ; so they rejoin the fold path below
    jne .statbusy                      ; rather than getting one of their own
    mov byte [sh_stbusy], 1
    jmp .fold
.statbusy:
    call sh_skipargs                   ; one variance fold inside another's
    mov byte [sh_evalerr], SH_ERR_VALUE  ; arguments would share sh_pacc2 -
    jmp .typed                         ; refused rather than answered (81.34.1)
.notstat:
    cmp ax, 69                         ; 69+ are the LOOKUP functions, whose
    jae .dolookup2                     ; answer may be a REFERENCE's contents
                                       ; and so may be TEXT (81.31). This test
                                       ; comes FIRST because the chain below
                                       ; is descending and 69 is also >= 58
    cmp ax, 58                         ; stage 4.5: 58+ are the DATE functions,
    jae .dodate                        ; which are numbers all the way down
    cmp ax, 37                         ; stage 4.5: 37+ are the TEXT functions,
    jae .dotext                        ; whose RESULT may be a string
    cmp ax, 25                         ; stage 4.5: 25+ are the INFORMATION
    jae .doinfo                        ; functions, whose argument stays a
                                       ; REFERENCE instead of folding (81.23)
    cmp ax, 12                         ; 12+ are stage 3.0d's special forms:
    jae .dospecial                     ; fixed arity, parsed by sh_pspecial,
                                       ; not folded over ranges
.fold:
    mov [sh_pfid], ax
    push ax
    xor ax, ax
    cmp word [sh_pfid], 8              ; AND folds by ANDing in each value, so
    je .accone                         ; it must start true (1), not the false
    cmp word [sh_pfid], 10             ; (0) every other fold starts at.
    jne .accset                        ; PRODUCT starts at 1 for the same
.accone:                               ; reason - a running product seeded with
    mov ax, 1                          ; 0 can only ever be 0
.accset:
    call sh_int_to_pacc
    pop ax
    mov word [sh_pcnt], 0
    mov word [sh_phave], 0
    mov word [sh_pacc2], 0             ; the sum of squares starts at zero for
    mov word [sh_pacc2+2], 0           ; every fold; only the variance ones
    mov word [sh_pacc2+4], 0           ; ever add to it
    mov word [sh_pacc2+6], 0
.args:
    call sh_prange
    cmp byte [si], ','
    jne .argsdone
    inc si
    jmp .args
.argsdone:
    cmp byte [si], ')'
    jne .badtail
    inc si
    call sh_funcfinish
    mov dx, ax
    jmp .typed                        ; a fold's answer is a NUMBER: this went
                                      ; to .done, which left the type of the
                                      ; LAST CELL FOLDED standing, so a SUM
                                      ; whose range ended on a label stored
                                      ; the label's text as its result (81.51)
.badtail:
    mov byte [sh_evalerr], SH_ERR_VALUE ; an argument tail this grammar cannot
    jmp .done                          ; parse (=SUM(A1:A9^2)) must ERR, not
                                       ; answer with a partial fold (81.20)
.doif:
    call sh_pif
    mov dx, ax
    jmp .done
.dochoose:
    call sh_pchoose
    mov dx, ax
    jmp .done                         ; NOT .typed: a chosen TEXT stays text
.donot:
    call sh_pnot
    mov dx, ax
    jmp .done
.doabs:
    call sh_pabs
    mov dx, ax
    jmp .done
.dodate:
    call sh_pdate
    mov dx, ax
    jmp .typed
.dotext:
    call sh_ptext
    mov dx, ax
    jmp .done                          ; NOT .typed: a text function's answer
                                       ; is TEXT, and .typed exists to stamp
                                       ; SH_T_NUM on a fold's result
.doinfo:
    call sh_pinfo
    mov dx, ax
    jmp .typed
.dorand:
    call sh_prand
    jmp .nullary
.donow:
    call sh_pnow
.nullary:                              ; A NULLARY CALL PARSES NO ARGUMENTS, so
    mov dx, ax                         ; nothing has stepped over its ')': .fold
    cmp byte [si], ')'                 ; does that at .argsdone and these two
    jne .badtail                       ; never reach it. This used to jump
    inc si                             ; straight to .typed under a comment
    jmp .typed                         ; saying "the ')' is skipped by the
                                       ; common tail" - .typed touches SI at
                                       ; all. SI was left ON the ')', the
                                       ; expression parser read that as the end
                                       ; of the formula, and =RAND()*1000
                                       ; SILENTLY ANSWERED RAND(). No error,
                                       ; a plausible number, and the same for
                                       ; =NOW()+1 ever since NOW landed
.dofin:
    call sh_pfin
    mov dx, ax
    jmp .typed
.dodatabase:
    call sh_pdatabase
    mov dx, ax
    jmp .typed
.docell:
    call sh_pcell
    mov dx, ax
    jmp .done                          ; NOT .typed, for sh_ptext's reason:
                                       ; CELL("type",...) answers with TEXT
.domatrix:
    call sh_pmatrix
    mov dx, ax
    jmp .done                          ; NOT .typed: TRANSPOSE's published
                                       ; element may be text, whatever its
                                       ; source cell held (81.67)
.domacro:
    call sh_pmacro
    mov dx, ax
    jmp .done                          ; NOT .typed: ACTIVE.CELL may be text
.dotrans:
    call sh_ptrans
    mov dx, ax
    jmp .typed
.dolookup2:
    call sh_plookup
    mov dx, ax
    jmp .done                          ; NOT .typed, for sh_ptext's reason: an
                                       ; INDEX onto a label answers with the
                                       ; label, and .typed would stamp
                                       ; SH_T_NUM over it
.dospecial:
    call sh_pspecial
    mov dx, ax
    jmp .typed
.noname:                              ; zero is how a typo silently becomes an
    call sh_skipargs                  ; answer, and the whole point of an error
.noparen:                             ; value is that it cannot be mistaken for
    mov byte [sh_evalerr], SH_ERR_NAME  ; one. Only the CALL form has arguments
.typed:                               ; to step over - `=FOO+1` has none, and
                                       ; skipping there would eat the `+1`
    mov byte [sh_curtype], SH_T_NUM   ; a call's RESULT is a number whatever it
                                       ; folded over: without this the TEXT tag
                                       ; left by the last cell a range touched
                                       ; would make `=SUM(A1:A9)*2` a #VALUE!
.done:
    cmp byte [sh_curtype], SH_T_ERR   ; A FUNCTION THAT ANSWERS TRUE OR FALSE
    je .notlog                        ; says so in the type (81.51), whatever
    call sh_fnlogical                 ; its own routine left there - NOT
    jnc .notlog                       ; sets none at all
    mov byte [sh_curtype], SH_T_BOOL
.notlog:
    call sh_pnest_leave
.popout:
    pop word [sh_stbusy]
    pop word [sh_phave]
    pop word [sh_pcnt]
    pop word [sh_pacc]
    pop word [sh_pacc+2]
    pop word [sh_pacc+4]
    pop word [sh_pacc+6]
    pop word [sh_pfid]
    mov ax, dx
    pop dx
    pop cx
    pop bx
    ret

; =============================================================================
; sh_pspecial (stage 3.0d) - the fixed-arity functions, ids 12 and up. These
; do not fold over a range the way SUM does; each parses exactly the arguments
; it takes and computes a value.
;
; THIS BLOCK USED TO LIST ISBLANK, ISNUMBER, ISNA AND NA AS "DELIBERATELY
; ABSENT". ALL FOUR SHIP - ids 25, 26, 31 and 33, dispatched by sh_pinfo a
; thousand lines down, which reads its argument through sh_pargclass and so
; has the reference the comment said had already been folded away.
;
; The reasons given were true when they were written and expired twice over:
; the first version said "all of these need the value model Stage 4.0 brings",
; which 4.0 delivered; the rewrite said the argument is folded before the
; function sees it, which sh_pargclass fixed. Neither edit removed the entry.
; The cost is not a wrong result - it is that a reader looking for somewhere
; to put a new INFORMATION function reads this and concludes the category is
; blocked, which is exactly what happened on the way to 81.44.
;
; A COMMENT THAT NAMES WHAT IS MISSING HAS TO BE DELETED WHEN THE THING
; ARRIVES, and nothing enforces that. What is genuinely absent now is listed
; in SPEC.md 81, which is at least read as a whole often enough to notice.
;
; in: AX = the id, SI just past '('. out: AX = the value, SI past ')'.
; =============================================================================
; sh_parg - one argument, as an integer. The special forms below are integer
; functions by nature; a fractional MOD or FACT is not a thing they mean.
; Truncation is the same rule TRUNC itself uses, so INT(3.7) is 3.
sh_parg:
    call sh_pcmp
    call sh_acc_toint
    ret

sh_pspecial:
    push bx
    push cx
    push dx
    push di
    mov di, ax                        ; DI holds the id: every sh_pcmp below
                                      ; clobbers AX/BX/CX/DX
    cmp di, 13                        ; the four that are REAL functions of a
    je .dfloor                        ; real number now that cells hold one -
    cmp di, 14                        ; everything else here is a function of
    je .dtrunc                        ; whole numbers by nature and stays
    cmp di, 17                        ; integer (see .close)
    je .dsqrt
    cmp di, 19
    je .dround
    cmp di, 18
    je .dpower                        ; POWER is a REAL power now (81.37.7)
    cmp di, 20
    jb .arg1                          ; 12..18 take one or two arguments
    cmp di, 23
    jbe .noargs                       ; 20..23 take none
    jmp .zeroout                      ; 24 CHOOSE is sh_pchoose's (81.49) and
                                      ; the dispatcher never sends it here

; ---- POWER(x, y), on doubles ------------------------------------------------
; It parsed both arguments as 16-BIT INTEGERS and multiplied with `imul` - a
; stage 3.0d routine that nothing upgraded when the value model became a
; double, so POWER(1.12, 6) truncated its base to 1 and answered 1. It went
; unnoticed because the only thing that exercised it was `^` on whole numbers,
; which agreed; MIRR asking for (1.12)^6 is what finally showed it.
.dpower:
    call sh_pcmp
    call sh_acc_load_a
    cmp byte [si], ','
    jne .powbad
    inc si
    push si
    mov si, sh_acc
    mov bx, sh_tr0
    call sh_trcopy                    ; the base, across the second parse
    pop si
    call sh_pcmp
    call sh_acc_load_b
    push si
    mov si, sh_tr0
    call fp_unpack_a
    pop si
    call fp_pow
    jnc .dstore
    mov byte [sh_evalerr], SH_ERR_NUM
    call fp_azero
    jmp .dstore
.powbad:
    mov byte [sh_evalerr], SH_ERR_VALUE
    call fp_azero
    jmp .dstore

; ---- INT / TRUNC / SQRT / ROUND, on doubles ---------------------------------
; INT FLOORS and TRUNC cuts toward zero, which differ for negatives: Excel's
; INT(-3.7) is -4 and TRUNC(-3.7) is -3. While every value was an integer the
; two were indistinguishable and both were the identity; they are not any more.
.dfloor:
    call sh_pcmp
    call sh_acc_load_a
    call fp_floor
    jmp .dstore
.dtrunc:
    call sh_pcmp
    call sh_acc_load_a
    call fp_trunc
    jmp .dstore
.dsqrt:
    call sh_pcmp
    test byte [sh_acc+7], 0x80        ; the sign bit of the packed double: a
    jz .sqrtok                        ; negative has no real square root, and
    mov byte [sh_evalerr], SH_ERR_NUM ; Excel says #NUM! rather than 0
.sqrtok:
    call sh_acc_load_a
    call fp_sqrt                      ; a REAL root: SQRT(2) is 1.414213562,
    jmp .dstore                       ; where the integer version gave 1
.dround:
    call sh_pcmp                      ; the value, banked across the second
    call sh_vpush                     ; argument's parse
    xor cx, cx
    cmp byte [si], ','
    jne .dround1                      ; ROUND(x) with no count means 0 places
    inc si
    call sh_parg                      ; the digit count IS a whole number
    mov cx, ax
.dround1:
    call sh_binop_pre                 ; A = the value again
    call fp_round
.dstore:
    call sh_acc_store
    cmp byte [si], ')'
    jne .dout
    inc si
.dout:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; ---- TRUE() FALSE() ROW() COLUMN() ------------------------------------------
.noargs:
    xor ax, ax
    cmp di, 20                        ; TRUE
    jne .nf
    mov ax, 1
    jmp .close
.nf:
    cmp di, 21                        ; FALSE - AX is already 0
    je .close
    mov ax, [sh_evrow]                ; ROW / COLUMN answer for the cell being
    cmp di, 22                        ; EVALUATED, not the one selected - a
    je .ctx1                          ; formula's own position is what Excel
    mov ax, [sh_evcol]                ; means by these
.ctx1:
    inc ax                            ; 1-based, as displayed
    jmp .close

; ---- the one- and two-argument forms ----------------------------------------
.arg1:
    call sh_parg                      ; every id from here takes a first value
    mov bx, ax                        ; BX = first argument
    cmp di, 12
    je .two
    cmp di, 18
    je .two
    cmp di, 19
    je .two
    ; --- single argument: INT TRUNC SIGN FACT SQRT ---
    mov ax, bx
    cmp di, 13                        ; INT - truncation toward zero on a whole
    je .close                         ; number is the identity. Present for
    cmp di, 14                        ; formula compatibility, not effect; it
    je .close                         ; becomes real work in Stage 4.0. TRUNC
                                      ; likewise.
    cmp di, 15
    je .sign
    cmp di, 16
    je .fact
    call sh_isqrt                     ; 17 SQRT
    jmp .close
.sign:
    or ax, ax
    jz .close
    jns .signpos
    mov ax, -1
    jmp .close
.signpos:
    mov ax, 1
    jmp .close
.fact:
    or ax, ax
    js .factnum                       ; negative has no factorial here
    cmp ax, 7
    ja .factnum                       ; 8! = 40320 does not fit a signed word,
    mov cx, ax                        ; so refuse rather than hand back a
    mov ax, 1                         ; wrapped number that looks like an answer
    or cx, cx
    jz .close                         ; 0! = 1
.factloop:
    imul cx
    dec cx
    jnz .factloop
    jmp .close
.factnum:                             ; out of FACT's domain, or out of the
    mov byte [sh_evalerr], SH_ERR_NUM ; range a word can hold: #NUM! either
    jmp .zeroout                      ; way, which is what Excel reports

.two:
    cmp byte [si], ','
    jne .zeroout
    inc si
    push bx                           ; first argument, across the second parse
    call sh_parg
    mov cx, ax                        ; CX = second argument
    pop bx
    cmp di, 12
    je .mod
    cmp di, 18
    je .power
    ; --- 19 ROUND(x, digits) ---
    mov ax, bx
    or cx, cx
    jns .close                        ; digits >= 0 leaves a whole number
    neg cx                            ; alone; only rounding to tens and up
    cmp cx, 4                         ; can do anything here
    ja .zeroout                       ; 10^5 exceeds the value range entirely
    mov bx, 1
.p10:
    or cx, cx
    jz .havep10
    push ax
    mov ax, bx
    mov dx, 10
    imul dx
    mov bx, ax
    pop ax
    dec cx
    jmp .p10
.havep10:                             ; BX = the power of ten
    cwd
    idiv bx                           ; AX = quotient, DX = remainder
    push ax
    mov ax, dx
    or ax, ax                         ; |remainder| * 2 vs the divisor decides
    jns .roundabs                     ; the direction; away from zero on a tie,
    neg ax                            ; which is Excel's own rule
.roundabs:
    shl ax, 1
    cmp ax, bx
    pop ax
    jb .scaleback
    or dx, dx                         ; step away from zero, following the
    js .rounddown                     ; remainder's own sign
    inc ax
    jmp .scaleback
.rounddown:
    dec ax
.scaleback:
    imul bx
    jmp .close
.mod:
    mov ax, bx
    or cx, cx
    jz .zeroout                       ; MOD by zero -> 0, this evaluator's
    cwd                               ; standing divide-by-zero policy
    idiv cx
    mov ax, dx                        ; IDIV's remainder takes the DIVIDEND's
    or ax, ax                         ; sign; Excel's MOD takes the DIVISOR's,
    jz .close                         ; so a mismatch needs one correction
    mov bx, ax
    xor bx, cx
    jns .close                        ; signs already agree
    add ax, cx
    jmp .close
.power:
    mov ax, 1
    or cx, cx
    js .zeroout                       ; a negative exponent is a fraction
    jz .close                         ; anything^0 = 1, including 0^0 here
.powloop:
    imul bx
    dec cx
    jnz .powloop
    jmp .close

.zeroout:
    xor ax, ax
.close:
    call sh_acc_int                   ; these thirteen are integer functions by
                                      ; nature - MOD, FACT, ROW, CHOOSE - so
                                      ; they take integers and give one back,
                                      ; converting only at this boundary
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; sh_isqrt - in: AX = n; out: AX = floor(sqrt(n)), 0 for n < 0.
; Successive odd numbers: 1+3+5+... = k^2, so subtracting them until AX runs
; out counts the root. At most 181 iterations for a signed word, and it needs
; no division at all.
sh_isqrt:
    push bx
    push cx
    or ax, ax
    js .zero
    xor cx, cx
    mov bx, 1
.loop:
    cmp ax, bx
    jb .done
    sub ax, bx
    add bx, 2
    inc cx
    jmp .loop
.zero:
    xor cx, cx
.done:
    mov ax, cx
    pop cx
    pop bx
    ret

; =============================================================================
; REFERENCE-TYPED ARGUMENTS (stage 4.5)
;
; Every argument in this evaluator has always been FOLDED TO A VALUE before
; the function saw it, so by the time ISBLANK was called there was no
; reference left to ask about: an empty cell and a cell holding 0 both arrived
; as 0, and a label arrived as the zero underneath it. That is why the comment
; above sh_pspecial listed ISBLANK, ISNUMBER and ISNA as deliberately absent -
; a version of any of them that returned a plausible constant would have been
; worse than its absence. These two routines are what ends that (81.23).
;
; sh_pargref - is the argument at SI a reference AND NOTHING ELSE? It is
; deliberately strict about "nothing else": ISNUMBER(A1+1) is a question about
; the sum, not about A1, so a reference only counts when the ',' or the ')'
; follows it immediately.
;
; in:  SI at the start of an argument
; out: CF=1 - sh_arg1col/sh_arg1row/sh_arg2col/sh_arg2row hold it (a single
;             cell puts the same cell in both corners), sh_refarea = 1 for an
;             A1:B9 form, and SI is past it
;
; THESE ARE NOT sh_r1col/sh_r2col, AND THE DISTINCTION IS NOT COSMETIC. Those
; four are sh_foldrange's loop bounds, read on EVERY iteration of its walk -
; so a cell inside the range that itself calls an information function used to
; overwrite the bounds mid-walk. `=SUM(A5:A9)` over a column of ISBLANK()
; formulas answered 1: A5's own argument reset the corners to A3, and the
; second iteration compared row 4 against row 2 and stopped. The right answer
; on the first cell and then nothing, with no error anywhere.
;
; The caller must still CONSUME these before evaluating anything, because a
; nested reference argument overwrites them in turn. sh_pargclass reads them
; into AX/BX on the line before its sh_getcell2 call for exactly that reason.
;      CF=0 - not a reference; SI is UNCHANGED, exactly as sh_pcellref leaves
;             it, and the caller parses an ordinary expression instead
; =============================================================================
sh_pargref:
    push ax
    push bx
    push si                           ; the only way back out on failure
    mov byte [sh_refarea], 0
    call sh_pcellref
    jnc .fail
    mov [sh_arg1col], ax
    mov [sh_arg1row], bx
    mov [sh_arg2col], ax
    mov [sh_arg2row], bx
    cmp byte [si], ':'
    jne .whole
    inc si
    call sh_pcellref
    jnc .fail
    mov [sh_arg2col], ax
    mov [sh_arg2row], bx
    mov byte [sh_refarea], 1
.whole:
    mov al, [si]
    cmp al, ','
    je .ok
    cmp al, ')'
    jne .fail
.ok:
    add sp, 2                         ; discard the saved SI - keep advancing
    pop bx
    pop ax
    stc
    ret
.fail:
    pop si
    pop bx
    pop ax
    clc
    ret

section SH_MODSEC                      ; 81.62: sh_pargclass, ISxxx's classifier
; =============================================================================
; sh_pargclass - one argument, CLASSIFIED rather than folded.
;
; out: sh_argtype  = the SH_T_* the argument IS. SH_T_BLANK for a cell that
;                    does not exist, which is the distinction this whole
;                    routine exists to make
;      sh_argaux   = its error code, 0 when it is not an error
;      sh_argisref = 1 when the argument was a bare reference
;      sh_acc      = its value, for the callers that want the number too
;      SI past the argument
;
; THE ARGUMENT'S ERROR IS THIS FUNCTION'S ANSWER, NOT THE SHEET'S. sh_evalerr
; is banked across the argument and put back afterwards, so ISERROR(1/0) is
; TRUE rather than being a #DIV/0! itself - trapping the error is the entire
; point of asking. Every other caller in this file WANTS an argument's error
; to spread (that is what puts one #DIV/0! at the bottom of a column), which
; is why the banking lives here and not in sh_getcell2.
; =============================================================================
sh_pargclass:
    push bx
    push cx
    push dx
    push di
    mov al, [sh_evalerr]
    push ax
    mov byte [sh_evalerr], 0
    mov byte [sh_argisref], 0
    mov byte [sh_argaux], 0
    SHOUT sh_pargref
    jnc .expr
    mov byte [sh_argisref], 1
    mov ax, [sh_arg1col]              ; an AREA is classified by its top-left
    mov bx, [sh_arg1row]              ; corner - what a 1x1 use of one would
    SHOUT sh_getcell2                 ; intersect to anyway
    jc .occupied
    mov byte [sh_argtype], SH_T_BLANK ; the cell does not exist. Not zero: the
    xor ax, ax                        ; whole point
    SHOUT sh_acc_int                  ; ...though its value is still a defined
    jmp .fin                          ; zero for anyone who asks for one
.occupied:
    mov al, [sh_curtype]
    mov [sh_argtype], al
    mov al, [sh_curaux]
    mov [sh_argaux], al
    jmp .fin
.expr:
    SHOUT sh_pcmp
    mov al, [sh_curtype]
    mov [sh_argtype], al
.fin:
    mov al, [sh_evalerr]              ; an error RAISED by the argument outranks
    or al, al                         ; whatever tag it left behind: 1/0 is an
    jz .noerr                         ; error value, not the zero underneath it
    mov byte [sh_argtype], SH_T_ERR
    mov [sh_argaux], al
.noerr:
    pop ax
    mov [sh_evalerr], al
    pop di
    pop dx
    pop cx
    pop bx
    ret

; =============================================================================
; THE FINANCIAL FAMILY IS CHART.OVL'S THIRD TENANT (SPEC.md 82.16.10): from
; here to sh_trcopy it is module code, bracketed where it stands the way the
; file formats were (82.16.9) - and since 81.62 sh_pargclass above and
; sh_ptrans below are in the same block. Every call out is SHOUT; the one way in is the
; resident stub sh_pfin, beside the other three. The three constants below
; stay in .text, because what reads them is resident fp_* code through DS.
; =============================================================================
section SH_MODSEC
                          ; closed-form in `^`, and fp_pow does whole-number
                          ; exponents by repeated squaring - including
                          ; NEGATIVE ones, as one-over-it - so (1+i)^-n is
                          ; exact. A sample budget carries the formulas.
; =============================================================================
; sh_pfin - the FINANCIAL functions, ids 93 and up (SPEC.md 81.37).
; in: AX = the id, SI just past '('. out: the answer in sh_acc, SI past ')'.
;
; They differ from everything above in TAKING SEVERAL ARGUMENTS WITH TRAILING
; ONES OPTIONAL, so they share one parser: sh_pfargs fills sh_fnarg[] and says
; how many arrived, and each function then reads the slots it wants. A missing
; argument is ZERO, which is Excel's rule for every one of them.
; =============================================================================
shm_pfin:
    push bx
    push cx
    push dx
    push di
    mov [sh_fnid], ax                 ; THE ID, IN MEMORY. DI is fp_pack_a's
    cmp byte [sh_fnbusy], 0           ; destination all through .annuity, so
                                       ; it stops being the id long before the
                                       ; dispatch at .havef - PV answered FV's
                                       ; number because `cmp word [sh_fnid], 96` compared
                                       ; a pointer to sh_fnt (81.37)           ; sh_fnarg[] is forty bytes and a task
    je .free                          ; stack is 384 (20.6 rule 6), so it is
    mov byte [sh_evalerr], SH_ERR_VALUE  ; not banked per nesting level and a
    jmp .refused                      ; financial function inside another's
.free:                                ; arguments refuses instead (47)
    mov byte [sh_fnbusy], 1
    cmp word [sh_fnid], 104           ; IRR and MIRR open with a RANGE, so
    jae .fnrange                      ; they cannot use the scalar parser
    mov cx, 6
    call sh_pfargs
    mov [sh_trsi], si
.dispatch:
    cmp word [sh_fnid], 93
    je .sln
    cmp word [sh_fnid], 94
    je .syd
    cmp word [sh_fnid], 98
    je .npv
    cmp word [sh_fnid], 99
    je .nper
    cmp word [sh_fnid], 100
    je .ddb
    cmp word [sh_fnid], 104
    je .irr
    cmp word [sh_fnid], 105
    je .mirr
    cmp word [sh_fnid], 103
    je .rate
    cmp word [sh_fnid], 101
    jae .ipmt
    jmp .annuity
; --- SLN(cost, salvage, life) = (cost - salvage) / life ---------------------
.sln:
    cmp word [sh_fnn], 3
    jb .badargs
    mov si, sh_fnarg
    SHOUT fp_unpack_a
    mov si, sh_fnarg + 8
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov si, sh_fnarg + 16
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    jmp .store
; --- SYD(cost, salvage, life, per) ------------------------------------------
; (cost - salvage) * (life - per + 1) * 2 / (life * (life + 1))
.syd:
    cmp word [sh_fnn], 4
    jb .badargs
    mov si, sh_fnarg
    SHOUT fp_unpack_a
    mov si, sh_fnarg + 8
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov di, sh_fnt
    SHOUT fp_pack_a                    ; t = cost - salvage
    mov si, sh_fnarg + 16             ; u = life - per + 1
    SHOUT fp_unpack_a
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    SHOUT fp_a_to_b
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_mul
    inc word [fp_ae]                  ; * 2, on the exponent
    mov di, sh_fnt
    SHOUT fp_pack_a
    mov si, sh_fnarg + 16             ; life * (life + 1)
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    SHOUT fp_a_to_b
    mov si, sh_fnarg + 16
    SHOUT fp_unpack_a
    SHOUT fp_mul
    SHOUT fp_a_to_b
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_div
    jc .divzero
    jmp .store
; --- NPV(rate, v1, v2, ...) = sum of vi / (1+rate)^i -------------------------
.npv:
    cmp word [sh_fnn], 2
    jb .badargs
    mov si, sh_fnarg                  ; u = 1 + rate, the running divisor base
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    mov di, sh_fnu
    SHOUT fp_pack_a
    mov si, sh_fnu                    ; t = the running (1+rate)^i, from i=1
    SHOUT fp_unpack_a
    mov di, sh_fnt
    SHOUT fp_pack_a
    SHOUT fp_azero                     ; the sum
    mov di, sh_tr0
    SHOUT fp_pack_a
    mov cx, 1
.npvl:
    cmp cx, [sh_fnn]
    jae .npvdone
    mov ax, cx                        ; sh_fnarg[cx] / t
    mov bx, 8
    mul bx
    add ax, sh_fnarg
    mov si, ax
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    SHOUT fp_a_to_b
    mov si, sh_tr0
    SHOUT fp_unpack_a
    SHOUT fp_add
    mov di, sh_tr0
    SHOUT fp_pack_a
    mov si, sh_fnt                    ; t *= (1+rate)
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_fnt
    SHOUT fp_pack_a
    inc cx
    jmp .npvl
.npvdone:
    mov si, sh_tr0
    SHOUT fp_unpack_a
    jmp .store
; --- PMT / PV / FV, the annuity three ---------------------------------------
; With r the rate, n the periods and t the type (0 = paid at the end of a
; period, 1 = at the beginning), all three come out of one identity:
;
;   pv*(1+r)^n + pmt*(1+t*r)*((1+r)^n - 1)/r + fv = 0
;
; sh_fnt holds (1+r)^n and sh_fnu the factor (1+t*r)*((1+r)^n-1)/r, and each
; function then rearranges for the one it wants. r = 0 is its own case, where
; that factor is simply n - the limit, and the formula divides by zero.
.annuity:
    cmp word [sh_fnn], 3
    jb .badargs
    mov si, sh_fnarg                  ; the rate is argument 0 here...
    mov bx, sh_fnr
    SHOUT sh_trcopy
    mov si, sh_fnarg + 8              ; ...n argument 1 and the type argument 4
    mov bx, sh_fnnp
    SHOUT sh_trcopy
    mov cx, 4
    call sh_fnsetty
    call sh_fnfac
    jc .badnum
.havef:
    cmp word [sh_fnid], 95
    je .pmt
    cmp word [sh_fnid], 96
    je .pvf
; --- FV(rate, nper, pmt, pv, type) = -(pv*(1+r)^n + pmt*factor) -------------
    mov si, sh_fnarg + 16             ; pmt * factor
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_tr0
    SHOUT fp_pack_a
    SHOUT fp_azero                     ; pv, if one came
    mov di, sh_tr1
    SHOUT fp_pack_a
    cmp word [sh_fnn], 4
    jb .fvsum
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_tr1
    SHOUT fp_pack_a
.fvsum:
    mov si, sh_tr0
    SHOUT fp_unpack_a
    mov si, sh_tr1
    SHOUT fp_unpack_b
    SHOUT fp_add
    xor byte [fp_as], 1
    jmp .store
; --- PV(rate, nper, pmt, fv, type) = -(fv + pmt*factor) / (1+r)^n -----------
.pvf:
    mov si, sh_fnarg + 16
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_tr0
    SHOUT fp_pack_a
    cmp word [sh_fnn], 4
    jb .pvnofv
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_b
    mov si, sh_tr0
    SHOUT fp_unpack_a
    SHOUT fp_add
    mov di, sh_tr0
    SHOUT fp_pack_a
.pvnofv:
    mov si, sh_tr0
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    xor byte [fp_as], 1
    jmp .store
; --- PMT(rate, nper, pv, fv, type) = -(pv*(1+r)^n + fv) / factor ------------
.pmt:
    mov si, sh_fnarg + 16
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_tr0
    SHOUT fp_pack_a
    cmp word [sh_fnn], 4
    jb .pmtnofv
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_b
    mov si, sh_tr0
    SHOUT fp_unpack_a
    SHOUT fp_add
    mov di, sh_tr0
    SHOUT fp_pack_a
.pmtnofv:
    mov si, sh_tr0
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    xor byte [fp_as], 1
    jmp .store
; --- IRR(values, guess) and MIRR(values, financerate, reinvestrate) ---------
; THE CASH FLOWS ARE A RANGE, not an argument list, so these two parse a
; reference first and then whatever scalars follow. The corners are banked in
; sh_ir*, because sh_getcell2 runs a whole evaluation for any formula cell the
; walk lands on - 81.32.1's reason, one category later.
;
; THE VALUES ARE NEVER COLLECTED. A range can be any size, so instead of
; copying it into an array the walk simply re-reads the cells each time it is
; needed. IRR's secant loop therefore reads the range up to forty times, which
; on a 4.77MHz 8088 is worth knowing about before putting IRR over a long
; column; the alternative is a fixed capacity, and a spreadsheet function with
; a silent capacity is worse than a slow one.
.fnrange:
    SHOUT sh_pargref
    jnc .badargs
    mov ax, [sh_arg1col]
    mov [sh_irc1], ax
    mov ax, [sh_arg1row]
    mov [sh_irr1], ax
    mov ax, [sh_arg2col]
    mov [sh_irc2], ax
    mov ax, [sh_arg2row]
    mov [sh_irr2], ax
    mov word [sh_fnn], 0              ; then the scalars, into sh_fnarg[0..]
.fnrs:
    cmp byte [si], ','
    jne .fnrdone
    inc si
    cmp word [sh_fnn], 6
    jae .fnrdone
    SHOUT sh_pcmp
    mov ax, [sh_fnn]
    mov bx, 8
    mul bx
    add ax, sh_fnarg
    mov bx, ax
    push si
    mov si, sh_acc
    SHOUT sh_trcopy
    pop si
    inc word [sh_fnn]
    jmp short .fnrs
.fnrdone:
    mov [sh_trsi], si
    jmp .dispatch
.irr:
    mov word [sh_irmode], 0
    cmp word [sh_fnn], 1              ; the guess, or Excel's own 0.1
    jb .irdefg
    mov si, sh_fnarg
    mov bx, sh_fnr0
    SHOUT sh_trcopy
    jmp short .irhaveg
.irdefg:
    mov si, sh_c_r10
    SHOUT fp_unpack_a
    mov di, sh_fnr0
    SHOUT fp_pack_a
.irhaveg:
    mov si, sh_fnr0
    SHOUT fp_unpack_a
    mov si, sh_c_r01
    SHOUT fp_unpack_b
    SHOUT fp_add
    mov di, sh_fnr1
    SHOUT fp_pack_a
    mov si, sh_fnr0
    mov bx, sh_fnr
    SHOUT sh_trcopy
    call sh_irwalk
    mov di, sh_fnf0
    SHOUT fp_pack_a
    cmp word [sh_ircnt], 2            ; one cash flow has no rate of return
    jb .badnum
    mov cx, 40
.irloop:
    push cx
    mov si, sh_fnr1
    mov bx, sh_fnr
    SHOUT sh_trcopy
    call sh_irwalk
    mov di, sh_fnf1
    SHOUT fp_pack_a
    mov byte [fp_as], 0
    mov si, sh_c_eps
    SHOUT fp_unpack_b
    SHOUT fp_cmpab
    jle .irdone
    mov si, sh_fnf1
    SHOUT fp_unpack_a
    mov si, sh_fnf0
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov di, sh_tr0
    SHOUT fp_pack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jc .irfail
    mov si, sh_fnr1
    SHOUT fp_unpack_a
    mov si, sh_fnr0
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov si, sh_fnf1
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov si, sh_tr0
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .irfail
    SHOUT fp_a_to_b
    mov si, sh_fnr1
    SHOUT fp_unpack_a
    SHOUT fp_sub
    mov di, sh_tr1
    SHOUT fp_pack_a
    mov si, sh_fnr1
    mov bx, sh_fnr0
    SHOUT sh_trcopy
    mov si, sh_fnf1
    mov bx, sh_fnf0
    SHOUT sh_trcopy
    mov si, sh_tr1
    mov bx, sh_fnr1
    SHOUT sh_trcopy
    pop cx
    dec cx
    jnz .irloop
    mov byte [sh_evalerr], SH_ERR_NUM
    jmp .zero
.irfail:
    pop cx
    mov byte [sh_evalerr], SH_ERR_NUM
    jmp .zero
.irdone:
    pop cx
    mov si, sh_fnr1
    SHOUT fp_unpack_a
    jmp .store
; MIRR is CLOSED FORM despite its reputation - two discounted sums and a root.
; Excel states it with NPV, which discounts from period ONE:
;   ( -npv_pos*(1+rrate)^n / (npv_neg*(1+frate)) ) ^ (1/(n-1)) - 1
; but sh_irwalk discounts from period ZERO - IRR's convention, and right for
; IRR - so each walk is (1+r)*npv and that formula, applied to it, carries one
; factor of (1+rrate)/(1+frate) too many. In the walk's own terms it is
;   ( -walk_pos*(1+rrate)^(n-1) / walk_neg ) ^ (1/(n-1)) - 1
; which is also what MIRR MEANS: the positives carried forward to the last
; period, over the negatives brought back to the first. It answered 0.10264
; for Excel's worked flows at 10%/12% where Excel says 0.09867, and SPEC.md
; 81.37.8's own "reference" had been computed with the same mistake, so the two
; agreed perfectly (tests/sheetfin.py; Excel's documented 12.61% is its anchor).
.mirr:
    cmp word [sh_fnn], 2
    jb .badargs
    mov word [sh_irmode], 1           ; the negatives, at the finance rate
    mov si, sh_fnarg
    mov bx, sh_fnr
    SHOUT sh_trcopy
    call sh_irwalk
    mov di, sh_tr0
    SHOUT fp_pack_a
    cmp word [sh_ircnt], 2
    jb .badnum
    mov word [sh_irmode], 2           ; the positives, at the reinvestment one
    mov si, sh_fnarg + 8
    mov bx, sh_fnr
    SHOUT sh_trcopy
    call sh_irwalk
    mov di, sh_tr1
    SHOUT fp_pack_a
    mov si, sh_fnarg + 8              ; (1+rrate)^(n-1): the positives
    SHOUT fp_unpack_a                  ; carried forward to the LAST period
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    mov ax, [sh_ircnt]
    dec ax                            ; n >= 2, checked after the first walk
    SHOUT fp_i2b
    SHOUT fp_pow
    jc .badnum
    mov si, sh_tr1
    SHOUT fp_unpack_b
    SHOUT fp_mul
    xor byte [fp_as], 1               ; -walk_pos*(1+rrate)^(n-1)
    mov di, sh_fnt
    SHOUT fp_pack_a
    mov si, sh_tr0                    ; ...over walk_neg, which is already the
    SHOUT fp_unpack_b                  ; negatives at period zero - no (1+frate)
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_div
    jc .divzero
    test byte [fp_as], 1              ; a negative has no real (n-1)th root
    jnz .badnum
    mov di, sh_fnt
    SHOUT fp_pack_a
    mov ax, [sh_ircnt]                ; ^ (1/(n-1))
    dec ax
    or ax, ax
    jle .badnum
    SHOUT fp_i2a
    SHOUT fp_a_to_b
    mov si, fp_c_one
    SHOUT fp_unpack_a
    SHOUT fp_div
    SHOUT fp_a_to_b
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_pow
    jc .badnum
    mov ax, 1                         ; ...less one
    SHOUT fp_i2b
    SHOUT fp_sub
    jmp .store

; --- RATE(nper, pmt, pv, fv, type, guess) -----------------------------------
; THE FIRST FUNCTION HERE THAT ITERATES TOWARD AN ANSWER. There is no closed
; form for the rate in
;
;   pv*(1+r)^n + pmt*(1+t*r)*((1+r)^n - 1)/r + fv = 0
;
; so it is solved by the SECANT method: two points, a straight line through
; them, and its root as the next point. Secant and not Newton because Newton
; wants the derivative, and that derivative is a page of algebra which would
; then have to agree with sh_fnfac about every one of its own edge cases.
;
; It can FAIL, which nothing before it could. Forty iterations, and either a
; residual small enough or a step small enough ends it; running out answers
; #NUM!, which is Excel's own reply and the reason `guess` is an argument at
; all - a caller who knows roughly where the root is can put the search there.
.rate:
    cmp word [sh_fnn], 3
    jb .badargs
    mov si, sh_fnarg                  ; n is argument 0 here, not 1
    mov bx, sh_fnnp
    SHOUT sh_trcopy
    mov cx, 4
    call sh_fnsetty
    cmp word [sh_fnn], 6              ; the guess, or Excel's own 0.1
    jb .rdefg
    mov si, sh_fnarg + 40
    mov bx, sh_fnr0
    SHOUT sh_trcopy
    jmp short .rhaveg
.rdefg:
    mov si, sh_c_r10
    SHOUT fp_unpack_a
    mov di, sh_fnr0
    SHOUT fp_pack_a
.rhaveg:
    mov si, sh_fnr0                   ; the second point, a little along
    SHOUT fp_unpack_a
    mov si, sh_c_r01
    SHOUT fp_unpack_b
    SHOUT fp_add
    mov di, sh_fnr1
    SHOUT fp_pack_a
    mov si, sh_fnr0                   ; f at the first
    mov bx, sh_fnr
    SHOUT sh_trcopy
    call sh_fnres
    jc .badnum
    mov di, sh_fnf0
    SHOUT fp_pack_a
    mov cx, 40
.rloop:
    push cx
    mov si, sh_fnr1
    mov bx, sh_fnr
    SHOUT sh_trcopy
    call sh_fnres
    jc .rfail
    mov di, sh_fnf1
    SHOUT fp_pack_a
    mov byte [fp_as], 0               ; |f1| small enough?
    mov si, sh_c_eps
    SHOUT fp_unpack_b
    SHOUT fp_cmpab
    jle .rdone
    mov si, sh_fnf1                   ; the secant step needs f1 - f0
    SHOUT fp_unpack_a
    mov si, sh_fnf0
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov di, sh_tr0
    SHOUT fp_pack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jc .rfail                         ; a flat line has no root to aim at
    mov si, sh_fnr1                   ; r1 - r0
    SHOUT fp_unpack_a
    mov si, sh_fnr0
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov si, sh_fnf1
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; f1 * (r1 - r0)
    mov si, sh_tr0
    SHOUT fp_unpack_b
    SHOUT fp_div                       ; ...over (f1 - f0)
    jc .rfail
    SHOUT fp_a_to_b
    mov si, sh_fnr1
    SHOUT fp_unpack_a
    SHOUT fp_sub                       ; the next point
    mov di, sh_tr1
    SHOUT fp_pack_a
    mov si, sh_fnr1                   ; r1 -> r0, f1 -> f0
    mov bx, sh_fnr0
    SHOUT sh_trcopy
    mov si, sh_fnf1
    mov bx, sh_fnf0
    SHOUT sh_trcopy
    mov si, sh_tr1
    mov bx, sh_fnr1
    SHOUT sh_trcopy
    pop cx
    dec cx
    jnz .rloop
    mov byte [sh_evalerr], SH_ERR_NUM ; forty steps and still moving
    jmp .zero
.rfail:
    pop cx
    mov byte [sh_evalerr], SH_ERR_NUM
    jmp .zero
.rdone:
    pop cx
    mov si, sh_fnr1
    SHOUT fp_unpack_a
    jmp .store

; --- IPMT / PPMT(rate, per, nper, pv, fv, type) -----------------------------
; The interest in one period is the BALANCE STILL OWED BEFORE IT, times the
; rate - and that balance is the same annuity evaluated at a smaller period
; count, which is the whole reason sh_fnfac takes its `n` in a slot rather
; than reading argument 1. PPMT is then simply PMT - IPMT: every payment is
; one or the other.
;
; Its type sits at argument FIVE where PMT's is at four, and with a type of 1
; the first period has no interest at all - the payment is made before any
; has accrued.
.ipmt:
    cmp word [sh_fnn], 4
    jb .badargs
    mov si, sh_fnarg
    mov bx, sh_fnr
    SHOUT sh_trcopy
    mov cx, 5
    call sh_fnsetty
    mov si, sh_fnarg + 16             ; --- the payment, over nper ---
    mov bx, sh_fnnp
    SHOUT sh_trcopy
    call sh_fnfac
    jc .badnum
    mov si, sh_fnarg + 24             ; pv * (1+r)^nper
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_mul
    cmp word [sh_fnn], 5              ; ...+ fv
    jb .ipnofv
    mov si, sh_fnarg + 32
    SHOUT fp_unpack_b
    SHOUT fp_add
.ipnofv:
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    xor byte [fp_as], 1
    mov di, sh_fnp
    SHOUT fp_pack_a                    ; sh_fnp = pmt
    mov si, sh_fnty                   ; --- which period to value at ---
    SHOUT fp_unpack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    mov ax, 1                         ; type 0: k = per - 1
    jc .iphavek
    mov si, sh_fnarg + 8              ; type 1 and per = 1: no interest yet
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_cmpab
    jle .ipzero
    mov ax, 2                         ; type 1 otherwise: k = per - 2
.iphavek:
    push ax
    mov si, sh_fnarg + 8
    SHOUT fp_unpack_a
    pop ax
    SHOUT fp_i2b
    SHOUT fp_sub
    mov di, sh_fnnp
    SHOUT fp_pack_a
    call sh_fnfac                     ; --- the balance before that period ---
    jc .badnum
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_tr0
    SHOUT fp_pack_a
    mov si, sh_fnp
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov si, sh_tr0
    SHOUT fp_unpack_b
    SHOUT fp_add
    xor byte [fp_as], 1               ; A = the balance
    mov si, sh_fnarg                  ; ...times the rate
    SHOUT fp_unpack_b
    SHOUT fp_mul
.ipdone:
    cmp word [sh_fnid], 102
    jne .store
    SHOUT fp_a_to_b                    ; PPMT = PMT - IPMT
    mov si, sh_fnp
    SHOUT fp_unpack_a
    SHOUT fp_sub
    jmp .store
.ipzero:
    SHOUT fp_azero
    jmp short .ipdone

; --- NPER(rate, pmt, pv, fv, type) -----------------------------------------
; r = 0 is -(pv + fv)/pmt, and otherwise
;   nper = ln((A - fv) / (A + pv)) / ln(1+r)   with A = pmt*(1+t*r)/r
; A LOGARITHM OF A NEGATIVE means the payments never retire the balance - the
; loan grows - and #NUM! is what Excel answers for it.
.nper:
    cmp word [sh_fnn], 3
    jb .badargs
    mov si, sh_fnarg
    SHOUT fp_unpack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jnc .nperr
    mov si, sh_fnarg + 16             ; r = 0: -(pv + fv)/pmt
    SHOUT fp_unpack_a
    cmp word [sh_fnn], 4
    jb .npr0
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_b
    SHOUT fp_add
.npr0:
    mov si, sh_fnarg + 8
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    xor byte [fp_as], 1
    jmp .store
.nperr:
    mov si, sh_fnarg + 8              ; A = pmt * (1 + t*r) / r
    SHOUT fp_unpack_a
    mov di, sh_fnt
    SHOUT fp_pack_a
    mov si, sh_fnarg                  ; A = (1 + t*r)
    mov bx, sh_fnr
    SHOUT sh_trcopy
    mov cx, 4
    call sh_fnsetty
    call sh_fntyv
    SHOUT fp_a_to_b
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_mul
    mov si, sh_fnarg
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    mov di, sh_fnu
    SHOUT fp_pack_a                    ; u = A
    SHOUT fp_azero                     ; A - fv
    mov di, sh_fnt
    SHOUT fp_pack_a
    cmp word [sh_fnn], 4
    jb .nprnf
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_a
    mov di, sh_fnt
    SHOUT fp_pack_a
.nprnf:
    mov si, sh_fnt
    SHOUT fp_unpack_b
    mov si, sh_fnu
    SHOUT fp_unpack_a
    SHOUT fp_sub
    mov di, sh_fnt
    SHOUT fp_pack_a                    ; t = A - fv
    mov si, sh_fnarg + 16             ; u = A + pv
    SHOUT fp_unpack_b
    mov si, sh_fnu
    SHOUT fp_unpack_a
    SHOUT fp_add
    SHOUT fp_a_to_b
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_div
    jc .divzero
    test byte [fp_as], 1              ; the ratio must be positive to have a
    jnz .badnum                       ; logarithm, and a negative one means the
    SHOUT fp_ln                        ; balance never comes down
    jc .badnum
    mov di, sh_fnt
    SHOUT fp_pack_a
    mov si, sh_fnarg                  ; / ln(1+r)
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    SHOUT fp_ln
    jc .badnum
    SHOUT fp_a_to_b
    mov si, sh_fnt
    SHOUT fp_unpack_a
    SHOUT fp_div
    jc .divzero
    jmp .store
; --- DDB(cost, salvage, life, period) ---------------------------------------
; Double-declining balance, walked one period at a time because that is what
; it IS: each period takes twice the straight-line fraction of what is LEFT,
; and the walk stops taking anything once the book value reaches salvage. The
; answer is the amount taken in `period` alone, not the total.
;
; Excel 2.1's DDB has no factor argument - that arrived later - so the factor
; is 2, applied as `book * 2 / life`.
.ddb:
    cmp word [sh_fnn], 4
    jb .badargs
    mov si, sh_fnarg                  ; t = the running book value
    SHOUT fp_unpack_a
    mov di, sh_fnt
    SHOUT fp_pack_a
    SHOUT fp_azero                     ; u = this period's depreciation
    mov di, sh_fnu
    SHOUT fp_pack_a
    mov si, sh_fnarg + 24             ; how many periods to walk
    SHOUT fp_unpack_a
    SHOUT fp_a2i
    jc .badnum
    mov cx, ax
    or cx, cx
    jle .badnum
.ddbl:
    mov si, sh_fnt                    ; book * 2 / life
    SHOUT fp_unpack_a
    inc word [fp_ae]
    mov si, sh_fnarg + 16
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .divzero
    mov di, sh_fnu
    SHOUT fp_pack_a
    mov si, sh_fnt                    ; ...but never below salvage
    SHOUT fp_unpack_a
    mov si, sh_fnarg + 8
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov di, sh_tr0
    SHOUT fp_pack_a                    ; tr0 = book - salvage
    mov si, sh_fnu
    SHOUT fp_unpack_a
    mov si, sh_tr0
    SHOUT fp_unpack_b
    SHOUT fp_cmpab
    jle .ddbok
    mov si, sh_tr0                    ; clipped
    SHOUT fp_unpack_a
    mov di, sh_fnu
    SHOUT fp_pack_a
.ddbok:
    test byte [sh_fnu+7], 0x80        ; and never negative: once the book value
    jz .ddbpos                        ; is at salvage there is nothing left to
    SHOUT fp_azero                     ; take
    mov di, sh_fnu
    SHOUT fp_pack_a
.ddbpos:
    mov si, sh_fnt                    ; book -= this period's amount
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_sub
    mov di, sh_fnt
    SHOUT fp_pack_a
    dec cx
    jnz .ddbl
    mov si, sh_fnu
    SHOUT fp_unpack_a
    jmp .store
.divzero:
    mov byte [sh_evalerr], SH_ERR_DIV0
    jmp short .zero
.badnum:
    mov byte [sh_evalerr], SH_ERR_NUM
    jmp short .zero
.badargs:
    mov byte [sh_evalerr], SH_ERR_VALUE
.zero:
    SHOUT fp_azero
.store:
    mov si, [sh_trsi]
    SHOUT sh_acc_store
    SHOUT sh_skipargs
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    mov byte [sh_fnbusy], 0
.rout:
    xor ax, ax
    pop di
    pop dx
    pop cx
    pop bx
    ret
.refused:                             ; the NESTED call's own exit. SI is its
    SHOUT fp_azero                    ; position, just past its '(', while
    SHOUT sh_acc_store                ; sh_trsi and sh_fnbusy are the OUTER
    SHOUT sh_skipargs                 ; call's: .zero resumed the parse at a
    cmp byte [si], ')'                ; stale sh_trsi and cleared the flag,
    jne .rout                         ; so the next nested call ran and wiped
    inc si                            ; sh_fnarg[] under the outer one
    jmp short .rout

; -----------------------------------------------------------------------------
; sh_irwalk - walk the banked range in row-major order, summing each value
; discounted at the rate in sh_fnr: A = sum of v_i / (1+r)^i, i from ZERO.
; [sh_ircnt] comes back as how many numbers were seen.
;
; [sh_irmode] selects which contribute - 0 every one, 1 only the negatives,
; 2 only the positives - and MIRR uses the last two. THE POSITION STILL
; ADVANCES FOR EVERY NUMBER whichever mode is running: i is where a flow sits
; in the series, not where it sits among the ones being added, and a walk that
; skipped the exponent would discount the fourth year as if it were the second.
;
; Blank cells, labels and error values are ignored and do NOT advance i, which
; is Excel's own rule for a cash-flow range.
; -----------------------------------------------------------------------------
sh_irwalk:
    push bx
    push cx
    push dx
    push si
    push di
    mov word [sh_ircnt], 0
    SHOUT fp_azero
    mov di, sh_iracc
    SHOUT fp_pack_a
    mov si, fp_c_one
    SHOUT fp_unpack_a
    mov di, sh_irpow
    SHOUT fp_pack_a
    mov dx, [sh_irr1]                 ; DX = the row being read
.row:
    cmp dx, [sh_irr2]
    ja .done
    mov cx, [sh_irc1]                 ; CX = the column
.col:
    cmp cx, [sh_irc2]
    ja .nextrow
    mov ax, cx
    mov bx, dx
    push cx
    push dx
    SHOUT sh_getcell2                  ; recurses for a formula cell, which is
    pop dx                            ; why every loop variable is banked
    pop cx
    jnc .nextcol                      ; empty
    cmp byte [sh_curtype], SH_T_NUM
    jne .nextcol                      ; a label or an error sits it out
    push cx
    push dx
    mov si, sh_acc                    ; v / (1+r)^i
    SHOUT fp_unpack_a
    mov cx, [sh_irmode]
    jcxz .take
    test byte [sh_acc+7], 0x80        ; mode 1 wants the negatives...
    jz .ispos
    cmp cx, 1
    je .take
    jmp short .skip
.ispos:
    cmp cx, 2                         ; ...and mode 2 the positives
    jne .skip
.take:
    mov si, sh_irpow
    SHOUT fp_unpack_b
    SHOUT fp_div
    jc .skip
    mov si, sh_iracc
    SHOUT fp_unpack_b
    SHOUT fp_add
    mov di, sh_iracc
    SHOUT fp_pack_a
.skip:
    mov ax, 1                         ; i advances for EVERY number, taken or
    SHOUT fp_i2a                       ; not - see the note above
    mov si, sh_fnr
    SHOUT fp_unpack_b
    SHOUT fp_add
    SHOUT fp_a_to_b
    mov si, sh_irpow
    SHOUT fp_unpack_a
    SHOUT fp_mul
    mov di, sh_irpow
    SHOUT fp_pack_a
    inc word [sh_ircnt]
    pop dx
    pop cx
.nextcol:
    inc cx
    jmp .col
.nextrow:
    inc dx
    jmp .row
.done:
    mov si, sh_iracc
    SHOUT fp_unpack_a
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; sh_fnres - A = the annuity residual at the rate in sh_fnr, for RATE's own
; argument order (0 = nper, 1 = pmt, 2 = pv, 3 = fv). CF=1 = the power refused.
; A root of this IS the rate, which is what makes the secant loop above short.
sh_fnres:
    push bx
    push si
    push di
    call sh_fnfac
    jc .no
    mov si, sh_fnarg + 16             ; pv * (1+r)^n
    SHOUT fp_unpack_a
    mov si, sh_fnt
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov di, sh_tr0
    SHOUT fp_pack_a
    mov si, sh_fnarg + 8              ; + pmt * factor
    SHOUT fp_unpack_a
    mov si, sh_fnu
    SHOUT fp_unpack_b
    SHOUT fp_mul
    mov si, sh_tr0
    SHOUT fp_unpack_b
    SHOUT fp_add
    cmp word [sh_fnn], 4              ; + fv
    jb .ok
    mov si, sh_fnarg + 24
    SHOUT fp_unpack_b
    SHOUT fp_add
.ok:
    clc
    jmp short .out
.no:
    stc
.out:
    pop di
    pop si
    pop bx
    ret

section .text                       ; ...DATA, and the resident fp_* routines
                                    ; read it through DS (68.10 rule 2)
sh_c_r10: dq 0.1
sh_c_r01: dq 0.01
sh_c_eps: dq 0.0000000001
section SH_MODSEC

; sh_fntyv - A = (1 + type*rate) from sh_fnty, or 1 when that is zero.
sh_fntyv:
    push bx
    push si
    mov si, sh_fnty
    SHOUT fp_unpack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jnc .scaled
    mov si, fp_c_one
    SHOUT fp_unpack_a
    jmp short .out
.scaled:
    mov si, sh_fnr
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
.out:
    pop si
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_fnsetty - copy argument CX into sh_fnty, or zero it if fewer arrived.
; THE TYPE IS NOT ALWAYS ARGUMENT 4: PMT, PV and FV put it there, and IPMT and
; PPMT at 5, so the caller names its index rather than the helper assuming one.
sh_fnsetty:
    push ax
    push bx
    push si
    mov bx, sh_fnty
    mov word [bx], 0
    mov word [bx+2], 0
    mov word [bx+4], 0
    mov word [bx+6], 0
    cmp [sh_fnn], cx
    jbe .out
    mov ax, cx
    push dx
    mov dx, 8
    mul dx
    pop dx
    add ax, sh_fnarg
    mov si, ax
    SHOUT sh_trcopy
.out:
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_fnfac - the two quantities every annuity function is built from, for the
; rate in sh_fnarg[0], the period count in sh_fnnp and the type in sh_fnty:
;
;   sh_fnt = (1+r)^n
;   sh_fnu = (1 + t*r) * ((1+r)^n - 1) / r
;
; out: CF=1 = the power refused. r = 0 is its own case, where that factor is
; simply n - the limit - and the general form divides by zero.
sh_fnfac:
    push bx
    push si
    push di
    mov si, sh_fnr
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    mov si, sh_fnnp
    SHOUT fp_unpack_b
    SHOUT fp_pow
    jc .no
    mov di, sh_fnt
    SHOUT fp_pack_a
    mov si, sh_fnr
    SHOUT fp_unpack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jnc .nz
    mov si, sh_fnnp
    SHOUT fp_unpack_a
    mov di, sh_fnu
    SHOUT fp_pack_a
    jmp short .ok
.nz:
    mov si, sh_fnt
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_sub
    mov si, sh_fnr
    SHOUT fp_unpack_b
    SHOUT fp_div
    mov di, sh_fnu
    SHOUT fp_pack_a
    mov si, sh_fnty                   ; (1 + t*r), when the type is non-zero
    SHOUT fp_unpack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jc .ok
    mov si, sh_fnr
    SHOUT fp_unpack_a
    mov ax, 1
    SHOUT fp_i2b
    SHOUT fp_add
    SHOUT fp_a_to_b
    mov si, sh_fnu
    SHOUT fp_unpack_a
    SHOUT fp_mul
    mov di, sh_fnu
    SHOUT fp_pack_a
.ok:
    clc
    jmp short .out
.no:
    stc
.out:
    pop di
    pop si
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_pfargs - parse up to CX comma-separated numeric arguments into sh_fnarg[],
; [sh_fnn] = how many were there. Every slot is ZEROED first, so a function
; reading past the end gets Excel's own default of nothing.
; out: SI at the ')'; preserves nothing but SI.
; -----------------------------------------------------------------------------
sh_pfargs:
    push ax
    push bx
    push cx
    push dx
    push di
    mov word [sh_fnn], 0
    push cx
    mov di, sh_fnarg                  ; wipe all six slots
    mov cx, 24
.wipe:
    mov word [di], 0
    add di, 2
    loop .wipe
    pop cx
.arg:
    cmp byte [si], ')'
    je .done
    cmp word [sh_fnn], 6
    jae .done
    push cx
    SHOUT sh_pcmp
    pop cx
    mov ax, [sh_fnn]
    mov bx, 8
    mul bx
    add ax, sh_fnarg
    mov bx, ax
    push si
    mov si, sh_acc
    SHOUT sh_trcopy
    pop si
    inc word [sh_fnn]
    cmp byte [si], ','
    jne .done
    inc si
    jmp short .arg
.done:
    pop di
    pop dx
    pop cx
    pop bx
    pop ax
    ret

                                    ; (sh_ptrans follows in the module too, 81.62)

                          ; here - fp_sqrt is its own Newton-Raphson in the
                          ; float library, which is assembled whole either
                          ; way, so exposing it costs a table entry and
                          ; saves the user a six-cell iteration chain
; =============================================================================
; sh_ptrans - LN, LOG10, EXP, PI and LOG, ids 81 and up (SPEC.md 81.35).
; in: AX = the id, SI just past '('. out: the answer in sh_acc, SI past ')'.
;
; Every one of these was blocked on apps/os88fp.inc having no logarithm, and
; on nothing else - the value model has been IEEE-754 double since stage 4.0.
; =============================================================================
shm_ptrans:
    push bx
    push cx
    push dx
    push di
    mov di, ax
    mov [sh_trsi], si                 ; PI() parses nothing: already final
    cmp di, 92
    je .atan2                         ; ATAN2 is the only one taking two
    cmp di, 84
    je .pi                            ; PI() takes no argument at all
    SHOUT sh_pcmp                     ; ...every other one takes a number
    mov [sh_trsi], si                 ; parsing over - bank it
    SHOUT sh_acc_load_a
    cmp di, 86
    jae .trig                         ; SIN COS TAN ASIN ACOS ATAN
    cmp di, 83
    je .exp
    test byte [sh_acc+7], 0x80        ; A LOGARITHM OF A NEGATIVE, or of zero,
    jnz .domain                       ; is #NUM! - the same answer SQRT gives
    cmp di, 81
    jne .ratio                        ; LOG10 and LOG bank the RAW number and
    SHOUT fp_ln                       ; take BOTH logarithms at the end; only
    jc .domain                        ; LN takes one here
    jmp .store
.ratio:
; --- LOG10 and LOG(number, base): a RATIO of two logarithms ------------------
; THE RAW VALUES ARE BANKED, NOT THEIR LOGARITHMS. fp_ln owns fp_e0..fp_e3 as
; its own scratch, so an intermediate parked there does not survive the second
; call - LOG10(1000) came back 0 and LOG(100) came back 0.04825, both from
; dividing by a ln(10) computed over the wreckage of ln(1000). sh_tr0/sh_tr1
; are Sheet's own and outlive it; parking the raw arguments there also means
; nothing of value crosses the sh_pcmp that parses the base.
    SHOUT sh_acc_store
    push si
    mov si, sh_acc
    mov bx, sh_tr0
    SHOUT sh_trcopy                   ; sh_tr0 = the number
    pop si
    mov ax, 10                        ; the base, defaulting to ten
    SHOUT sh_acc_int
    push si
    mov si, sh_acc
    mov bx, sh_tr1
    SHOUT sh_trcopy
    pop si
    cmp di, 85
    jne .lognum                       ; LOG10 keeps the ten
    cmp byte [si], ','
    jne .lognum
    inc si
    SHOUT sh_pcmp
    mov [sh_trsi], si                 ; parsing over - bank it
    test byte [sh_acc+7], 0x80
    jnz .domain
    push si
    mov si, sh_acc
    mov bx, sh_tr1
    SHOUT sh_trcopy                   ; sh_tr1 = the base the user named
    pop si
.lognum:
    push si
    mov si, sh_tr0                    ; ln(number)
    SHOUT fp_unpack_a
    SHOUT fp_ln
    push di
    mov di, sh_tr0
    SHOUT fp_pack_a
    pop di
    mov si, sh_tr1                    ; ln(base) - fp_ln may do what it likes
    SHOUT fp_unpack_a                 ; to fp_e0..3 between the two, and does
    SHOUT fp_ln
    pop si
    jc .domain
    SHOUT fp_a_to_b
    push si
    mov si, sh_tr0
    SHOUT fp_unpack_a
    pop si
    SHOUT fp_div
    jmp .store
.exp:
    SHOUT fp_exp
    jmp .store
; --- the trigonometric seven (SPEC.md 81.36) --------------------------------
.trig:
    cmp di, 86
    jne .t1
    SHOUT fp_sin                      ; CF: an argument past a word of
    jc .domain                        ; quadrants is #NUM!, not a stored 0
    jmp .store
.t1:
    cmp di, 87
    jne .t2
    SHOUT fp_cos
    jc .domain
    jmp .store
.t2:
    cmp di, 88
    jne .t3
    SHOUT fp_tan                      ; the cosine reaching zero is #DIV/0!,
    jc .divzero                       ; which is what a tangent's pole IS
    jmp .store
.t3:
    cmp di, 91
    jne .asin
    SHOUT fp_atan
    jmp .store
; ASIN(x) = atan(x / sqrt(1 - x*x)), and ACOS(x) = pi/2 - ASIN(x). The domain
; is [-1, 1]; at either end the square root is zero and the quotient has no
; value, so +-pi/2 is written directly rather than divided for.
.asin:
    SHOUT sh_acc_store
    push si
    mov si, sh_acc
    mov bx, sh_tr0
    SHOUT sh_trcopy
    pop si
    mov si, sh_tr0
    SHOUT fp_unpack_a
    mov byte [fp_as], 0               ; |x|
    mov si, fp_c_one
    SHOUT fp_unpack_b
    SHOUT fp_cmpab
    jg .domain
    je .atend
    mov si, sh_tr0                    ; 1 - x*x
    SHOUT fp_unpack_a
    mov si, sh_tr0
    SHOUT fp_unpack_b
    SHOUT fp_mul
    SHOUT fp_a_to_b
    mov si, fp_c_one
    SHOUT fp_unpack_a
    SHOUT fp_sub
    SHOUT fp_sqrt
    SHOUT fp_a_to_b
    mov si, sh_tr0
    SHOUT fp_unpack_a
    SHOUT fp_div
    SHOUT fp_atan
    jmp .acostoo
.atend:
    mov si, sh_c_pi2                  ; asin(+-1) = +-pi/2
    SHOUT fp_unpack_a
    mov al, [sh_acc+7]
    and al, 0x80
    mov [fp_as], al
    cmp byte [fp_as], 0
    je .acostoo
    mov byte [fp_as], 1
.acostoo:
    cmp di, 90
    jne .store
    SHOUT fp_a_to_b                   ; ACOS = pi/2 - ASIN
    mov si, sh_c_pi2
    SHOUT fp_unpack_a
    SHOUT fp_sub
    jmp .store
; ATAN2(x_number, y_number) - Excel's argument order, which is the REVERSE of
; C's atan2(y, x) and the one thing about this function everybody gets wrong.
.atan2:
    SHOUT sh_pcmp
    mov [sh_trsi], si                 ; parsing over - bank it
    push si                           ; NO sh_acc_store HERE: sh_pcmp leaves
    mov si, sh_acc                    ; its answer in sh_acc, and storing A
    mov bx, sh_tr0                    ; over it wrote whatever the last
    SHOUT sh_trcopy                   ; arithmetic had left in the accumulator
    pop si                            ; - which is why ATAN2(-1,1) came back
                                       ; 0.78539 instead of 2.35619
    cmp byte [si], ','
    jne .badargs2
    inc si
    SHOUT sh_pcmp
    mov [sh_trsi], si                 ; parsing over - bank it
    push si                           ; ...and the same for y
    mov si, sh_acc
    mov bx, sh_tr1
    SHOUT sh_trcopy
    pop si
    mov si, sh_tr0
    SHOUT fp_unpack_a
    mov bx, fp_am0
    SHOUT fp_iszero
    jnc .a2div
    mov si, sh_tr1                    ; x is zero: straight up, straight down,
    SHOUT fp_unpack_a                 ; or nowhere at all
    mov bx, fp_am0
    SHOUT fp_iszero
    jc .divzero
    mov cl, [fp_as]
    mov si, sh_c_pi2
    SHOUT fp_unpack_a
    mov [fp_as], cl
    jmp .store
.a2div:
    mov cl, [sh_tr1+7]                ; THE SIGN OF y, TAKEN NOW. The quadrant
    and cl, 0x80                      ; rule below turns on it, and the atan
    mov si, sh_tr0                    ; result is parked in sh_tr1 a moment
    SHOUT fp_unpack_b                 ; from now - testing it there gave the
    mov si, sh_tr1                    ; sign of the ANSWER instead, and
    SHOUT fp_unpack_a                 ; ATAN2(-1,1) came back -3.9269 where
    SHOUT fp_div                      ; 2.35619 was wanted
    SHOUT fp_atan                     ; atan(y/x)
    cmp byte [sh_tr0+7], 0            ; ...and the half-plane x < 0 needs pi
    jns .store                        ; added or subtracted to place it
    mov di, sh_tr1
    SHOUT fp_pack_a                   ; y is finished with; park the atan
    mov si, sh_c_pi
    SHOUT fp_unpack_b
    mov si, sh_tr1
    SHOUT fp_unpack_a
    or cl, cl
    jnz .a2sub                        ; y < 0 takes pi away, y >= 0 adds it
    SHOUT fp_add
    jmp .store
.a2sub:
    SHOUT fp_sub
    jmp .store
.divzero:
    mov byte [sh_evalerr], SH_ERR_DIV0
    SHOUT fp_azero
    jmp .store
.badargs2:
    mov byte [sh_evalerr], SH_ERR_VALUE
    SHOUT fp_azero
    jmp .store
.pi:
    mov si, sh_c_pi
    SHOUT fp_unpack_a
    jmp .store
.domain:
    mov byte [sh_evalerr], SH_ERR_NUM
    SHOUT fp_azero
.store:
    mov si, [sh_trsi]                 ; THE FORMULA AGAIN. Every constant here
                                      ; is loaded with `mov si, <addr>` for
                                      ; fp_unpack_*, so SI stops being the
                                      ; formula the moment any of them runs -
                                      ; PI()/6 answered 3.14159 because this
                                      ; hunted the closing paren inside the
                                      ; CONSTANT TABLE and never saw the '/'
    SHOUT sh_acc_store
    SHOUT sh_skipargs
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    xor ax, ax
    pop di
    pop dx
    pop cx
    pop bx
    ret

section .text                       ; sh_trcopy and the two constants stay:
                                    ; resident code reads them (81.62)
; sh_trcopy - eight bytes from DS:SI to DS:BX. BX and not DI, because DI holds
; the FUNCTION ID all the way through sh_ptrans and using it here quietly
; destroyed it. NOT `rep movsw` either: ES in this app is a claim far more
; often than the package (81.32.2).
sh_trcopy:
    push ax
    push bx
    push cx
    push si
    mov cx, 4
.c:
    mov ax, [si]
    mov [bx], ax
    add si, 2
    add bx, 2
    loop .c
    pop si
    pop cx
    pop bx
    pop ax
    ret

sh_c_pi:  dq 3.14159265358979323846
sh_c_pi2: dq 1.57079632679489661923

; =============================================================================
; sh_plookup - the LOOKUP functions, ids 69 and up (SPEC.md 81.31).
;
; in:  AX = the id, SI just past '('
; out: SI past ')', the answer in sh_acc and [sh_curtype] set. AX is 0 and
;      means nothing - the value has lived in sh_acc since stage 4.0.
;
; EVERY ONE OF THESE OPENS WITH A REFERENCE, and sh_pargref is strict about
; that on purpose (81.23): `ROWS(A1:B9)` is a question about the rectangle, and
; `ROWS(A1+1)` is not a question at all. An argument that is anything else is
; #VALUE!, not a fold of it.
;
; THE ANSWER MAY BE TEXT, which is why the router sends these to `.done` and
; not `.typed`. INDEX onto a label has to come back as the label; a number
; stamped over it would be the zero underneath, which is exactly the bug 81.23
; was written to end.
; =============================================================================
sh_plookup:
    push bx
    push cx
    push dx
    push di
    mov di, ax                        ; DI = the id; everything else is scratch
    cmp di, 73
    jae sh_plksearch                  ; MATCH/VLOOKUP/HLOOKUP open with a VALUE
    call sh_pargref                   ; the other four open with a reference
    jnc .notref
    cmp di, 72
    je .index
    cmp di, 71
    je .areas
    mov ax, [sh_arg2row]              ; ROWS - the rectangle's height...
    sub ax, [sh_arg1row]
    inc ax
    cmp di, 69
    je .num
    mov ax, [sh_arg2col]              ; ...and COLUMNS its width. sh_pargref
    sub ax, [sh_arg1col]              ; puts a single cell in BOTH corners, so
    inc ax                            ; ROWS(A1) is 1 with no special case
    jmp short .num
.areas:
    mov ax, 1                         ; AREAS is 1 for every reference this
                                       ; grammar can express. Excel answers >1
                                       ; only for a UNION - `(A1:A9,C1:C9)` -
                                       ; and there is no union operator here,
                                       ; so 1 is the truth rather than a stub
.num:
    call sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .close
; --- INDEX(ref, n) / INDEX(ref, row, col) ------------------------------------
; The two-argument form indexes along whichever way the reference runs, which
; is what makes INDEX(A1:A9, 3) and INDEX(A1:I1, 3) both mean "the third one".
; A rectangle given one subscript takes it as the ROW, as Excel does.
.index:
    cmp byte [si], ','
    jne .badargs
    inc si
    call sh_pcmp                      ; the first subscript
    call sh_acc_toint
    jc .badnum
    mov cx, ax                        ; CX = it
    mov dx, 1                         ; DX = the second, defaulting to 1
    cmp byte [si], ','
    jne .oneidx
    inc si
    call sh_pcmp
    call sh_acc_toint
    jc .badnum
    mov dx, ax
    jmp short .haveidx
.oneidx:
    mov ax, [sh_arg2row]              ; one subscript: if the reference is a
    cmp ax, [sh_arg1row]              ; single ROW then it counts columns
    jne .haveidx
    mov ax, [sh_arg2col]
    cmp ax, [sh_arg1col]
    je .haveidx                       ; ...a 1x1 reference is row 1, column 1
    mov dx, cx
    mov cx, 1
.haveidx:
    or cx, cx                         ; 0 or negative is #VALUE!, as it is for
    jle .badnum                       ; every subscript in this app
    or dx, dx
    jle .badnum
    mov ax, [sh_arg1row]              ; the cell: the corner plus (n-1)
    add ax, cx
    dec ax
    mov bx, ax
    cmp ax, [sh_arg2row]
    ja .outofref
    mov ax, [sh_arg1col]
    add ax, dx
    dec ax
    cmp ax, [sh_arg2col]
    ja .outofref
    mov byte [sh_curtype], SH_T_NUM   ; an EMPTY cell answers 0, as Excel does,
    push si                           ; and sh_getcell2 leaves sh_acc alone for
    xor ax, ax                        ; one - so the zero is written first and
    call sh_acc_int                   ; the read overwrites it when there is
    pop si                            ; something to read
    mov ax, [sh_arg1col]
    add ax, dx
    dec ax
    call sh_getcell2                  ; BX is already the row; the value, the
    jmp .close                        ; tag and any error land where the
                                       ; caller reads them
.outofref:
    mov byte [sh_evalerr], SH_ERR_REF ; a subscript past the rectangle names no
    jmp short .zero                   ; cell, and #REF! is what that is
.badnum:
    mov byte [sh_evalerr], SH_ERR_VALUE
    jmp short .zero
.notref:
    call sh_skipargs                  ; step over whatever it was, so the
    mov byte [sh_evalerr], SH_ERR_VALUE  ; caller still finds the ')'
    jmp short .zero
.badargs:
    mov byte [sh_evalerr], SH_ERR_VALUE
.zero:
    xor ax, ax
    call sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
.close:
    call sh_skipargs                  ; anything left before the ')' - a fourth
    cmp byte [si], ')'                ; subscript, a stray comma - is stepped
    jne .done                         ; over rather than re-parsed
    inc si
.done:
    xor ax, ax
    pop di
    pop dx
    pop cx
    pop bx
    ret

; =============================================================================
; sh_plksearch - MATCH, VLOOKUP and HLOOKUP: the lookup functions that SEARCH
; (SPEC.md 81.32). Entered from sh_plookup with DI = the id and the caller's
; four registers already banked, so it shares that routine's exits.
;
; The shape is one comparison engine and three ways of asking it: every one of
; these walks a single row or column comparing a key against each cell, and
; they differ only in what they do with the position they find.
; =============================================================================
sh_plksearch:
    cmp byte [sh_lk_busy], 0          ; SEE THE NOTE ON sh_lk_busy: a search
    je .free                          ; reached from inside a searched range
    mov byte [sh_evalerr], SH_ERR_VALUE  ; would overwrite the outer one's key
    jmp sh_plookup.zero               ; and answer both wrongly
.free:
    mov byte [sh_lk_busy], 1
    call sh_pcmp                      ; --- the key -------------------------
    mov al, [sh_curtype]
    mov [sh_lk_kt], al
    cmp al, SH_T_TEXT
    je .keytext
    push si                           ; a number: bank all eight bytes. NOT
    push di                           ; `rep movsw` - that writes ES:DI, and
    mov si, sh_acc                    ; ES in this app is a cell or text claim
    mov di, sh_lk_kv                  ; far more often than it is the package.
    mov cx, 4                         ; The key landed in another segment and
.kv:                                  ; every numeric compare then missed,
    mov ax, [si]                      ; while the TEXT path - a plain DS byte
    mov [di], ax                      ; loop - worked: MATCH("CCC",..) found
    add si, 2                         ; its row and MATCH(30,..) said #N/A
    add di, 2
    loop .kv
    pop di
    pop si
    jmp short .keyed
.keytext:
    push si                           ; a label: bank the string
    push di
    mov si, sh_sacc
    mov di, sh_lk_ks
    mov cx, SH_STR_MAX + 1
.kc:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    loopnz .kc
    mov byte [di-1], 0
    pop di
    pop si
.keyed:
    cmp byte [si], ','
    jne .bad
    inc si
    call sh_pargref                   ; --- the range -----------------------
    jnc .bad
    mov ax, [sh_arg1col]              ; banked at once: sh_getcell2 recurses
    mov [sh_lk_c1], ax                ; and the scan cannot trust sh_arg* to
    mov ax, [sh_arg1row]              ; survive it (81.23)
    mov [sh_lk_r1], ax
    mov ax, [sh_arg2col]
    mov [sh_lk_c2], ax
    mov ax, [sh_arg2row]
    mov [sh_lk_r2], ax
    mov word [sh_lk_idx], 1           ; a VLOOKUP with no third argument would
    mov word [sh_lk_mt], 1            ; want column 1; MATCH with none wants
    mov word [sh_lk_has2], 0          ; type 1. TWO fields - see sh_lkone
    cmp byte [si], ','
    jne .noidx
    inc si
    cmp di, 76                        ; LOOKUP's third argument is a RESULT
    je .arg2ref                       ; VECTOR, not a number at all
    call sh_pcmp
    call sh_acc_toint
    jc .bad
    cmp di, 73                        ; MATCH's third argument is the TYPE,
    jne .isidx                        ; the other two's is a column or row
    mov [sh_lk_mt], ax
    jmp short .noidx
.isidx:
    mov [sh_lk_idx], ax
    jmp short .noidx
.arg2ref:
    call sh_pargref
    jnc .bad
    mov word [sh_lk_has2], 1
    mov ax, [sh_arg1col]
    mov [sh_lk_2c1], ax
    mov ax, [sh_arg1row]
    mov [sh_lk_2r1], ax
    mov ax, [sh_arg2col]
    mov [sh_lk_2c2], ax
    mov ax, [sh_arg2row]
    mov [sh_lk_2r2], ax
.noidx:
    cmp di, 73                        ; --- the walk ------------------------
    je .match
    cmp di, 74
    je .vlook
    cmp di, 75
    je .hlook
    jmp sh_plklookup
.match:
    mov ax, [sh_lk_r2]                ; MATCH takes a vector: a single column
    cmp ax, [sh_lk_r1]                ; walks down, anything else walks across
    je .macross                       ; - which makes a 1x1 reference a row of
    call sh_lkdown                    ; one, and both spellings work
    jmp short .mpos
.macross:
    call sh_lkacross
.mpos:
    cmp word [sh_lk_got], 0
    je .nomatch
    mov ax, [sh_lk_pos]               ; the POSITION, 1-based, is the answer
    call sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .fin
.vlook:
    call sh_lkdown                    ; down the first column...
    cmp word [sh_lk_got], 0
    je .nomatch
    mov ax, [sh_lk_idx]               ; ...then across to the wanted column
    or ax, ax
    jle .badidx
    dec ax
    add ax, [sh_lk_c1]
    cmp ax, [sh_lk_c2]
    ja .badidx
    mov bx, [sh_lk_hit]
    jmp short .fetch
.hlook:
    call sh_lkacross                  ; across the first row, then down
    cmp word [sh_lk_got], 0
    je .nomatch
    mov ax, [sh_lk_idx]
    or ax, ax
    jle .badidx
    dec ax
    add ax, [sh_lk_r1]
    cmp ax, [sh_lk_r2]
    ja .badidx
    mov bx, ax
    mov ax, [sh_lk_hit]
.fetch:
    push ax                           ; an empty cell in the answer column is
    push bx                           ; 0, the same rule INDEX follows
    xor ax, ax
    call sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    pop bx
    pop ax
    call sh_getcell2
    jmp short .fin
.nomatch:
    mov byte [sh_evalerr], SH_ERR_NA  ; #N/A is what "no match" IS - #VALUE!
    jmp short .zero                   ; would say the arguments were wrong
.badidx:
    mov byte [sh_evalerr], SH_ERR_REF ; a column outside the range names no
    jmp short .zero                   ; cell, exactly as INDEX's does
.bad:
    mov byte [sh_evalerr], SH_ERR_VALUE
.zero:
    xor ax, ax
    call sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
.fin:
    mov byte [sh_lk_busy], 0
    jmp sh_plookup.close

; -----------------------------------------------------------------------------
; sh_lkdown / sh_lkacross - walk the reference's first column (row) comparing
; each cell against the banked key. Preserves all registers.
;
; out: [sh_lk_got] = something matched, [sh_lk_hit] = the row (column) it is
;      in, [sh_lk_pos] = its 1-based position along the vector.
;
; MATCH TYPE 0 IS EXACT AND ANYTHING ELSE IS APPROXIMATE: type 1 (the default,
; and what VLOOKUP and HLOOKUP always do) keeps the LAST cell that is still
; <= the key, which is the largest one not over it when the vector ascends;
; type -1 keeps the last that is still >=. Excel says the vector must be
; sorted, and an unsorted one gives an answer this makes no promise about
; rather than an error - which is Excel's behaviour too.
; -----------------------------------------------------------------------------
; =============================================================================
; sh_plklookup - LOOKUP, in both of the forms Excel gives it (SPEC.md 81.33).
; Entered from sh_plksearch with the key and the first reference already
; banked, so it shares that routine's exits.
;
;   LOOKUP(key, vector, result)  the VECTOR form: match along `vector`, answer
;                                with the element of `result` at the same
;                                POSITION - the two need not be the same shape
;                                or even the same length
;   LOOKUP(key, array)           the ARRAY form: search the array's first row
;                                or column, whichever is longer, and answer
;                                from its LAST one
;
; It is always approximate - there is no match-type argument - so the key
; finds the largest entry not over it, and a key below every entry is #N/A.
; =============================================================================
sh_plklookup:
    mov word [sh_lk_mt], 1            ; LOOKUP has no exact form
    mov ax, [sh_lk_c2]                ; which way does the first reference
    sub ax, [sh_lk_c1]                ; run? WIDER THAN TALL searches its row,
    mov bx, [sh_lk_r2]                ; anything else its column - which makes
    sub bx, [sh_lk_r1]                ; a single cell a column of one, and a
    cmp ax, bx                        ; square array a set of columns, both as
    ja .across                        ; Excel has them
    call sh_lkdown
    mov cx, 0                         ; CX = 0, the walk went DOWN
    jmp short .found
.across:
    call sh_lkacross
    mov cx, 1
.found:
    cmp word [sh_lk_got], 0
    jne .fetch
    jmp sh_plksearch.nomatch
.fetch:
    mov dx, [sh_lk_pos]               ; DX = the 1-based position
    cmp word [sh_lk_has2], 0
    jne .vector
; --- the ARRAY form: the same array's last row or column ---------------------
    or cx, cx
    jz .arrdown
    mov ax, [sh_lk_c1]                ; searched across: answer from the LAST
    add ax, dx                        ; ROW, in the column that matched
    dec ax
    mov bx, [sh_lk_r2]
    jmp short .read
.arrdown:
    mov ax, [sh_lk_c2]                ; searched down: the LAST COLUMN, in the
    mov bx, [sh_lk_r1]                ; row that matched
    add bx, dx
    dec bx
    jmp short .read
; --- the VECTOR form: the result vector's Nth element ------------------------
.vector:
    mov ax, [sh_lk_2r2]
    cmp ax, [sh_lk_2r1]
    jne .vcol
    mov ax, [sh_lk_2c1]               ; a result vector that is one ROW
    add ax, dx
    dec ax
    cmp ax, [sh_lk_2c2]
    ja .short
    mov bx, [sh_lk_2r1]
    jmp short .read
.vcol:
    mov bx, [sh_lk_2r1]               ; ...or one COLUMN
    add bx, dx
    dec bx
    cmp bx, [sh_lk_2r2]
    ja .short
    mov ax, [sh_lk_2c1]
.read:
    push ax                           ; an empty cell answers 0, the rule
    push bx                           ; INDEX and VLOOKUP both follow
    xor ax, ax
    call sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    pop bx
    pop ax
    call sh_getcell2
    jmp sh_plksearch.fin
.short:
    jmp sh_plksearch.nomatch          ; a result vector shorter than the
                                       ; position found is #N/A: there is no
                                       ; element to answer with, and a
                                       ; silently clamped one would be a
                                       ; different row's value

sh_lkdown:
    push ax
    push bx
    push cx
    mov word [sh_lk_got], 0
    mov word [sh_lk_pos], 0
    xor cx, cx                        ; CX = the position, counted up
    mov bx, [sh_lk_r1]
.row:
    cmp bx, [sh_lk_r2]
    ja .out
    inc cx
    mov ax, [sh_lk_c1]
    push ax
    push bx
    push cx
    call sh_lkone
    pop cx
    pop bx
    pop ax
    jc .next
    mov word [sh_lk_got], 1           ; THE WALKER RECORDS THE HIT, because it
    mov [sh_lk_pos], cx               ; is the one that knows which axis it is
    mov [sh_lk_hit], bx               ; on. A down-walk's hit is its ROW
.next:
    inc bx
    jmp short .row
.out:
    pop cx
    pop bx
    pop ax
    ret

sh_lkacross:
    push ax
    push bx
    push cx
    mov word [sh_lk_got], 0
    mov word [sh_lk_pos], 0
    xor cx, cx
    mov ax, [sh_lk_c1]
.col:
    cmp ax, [sh_lk_c2]
    ja .out
    inc cx
    mov bx, [sh_lk_r1]
    push ax
    push bx
    push cx
    call sh_lkone
    pop cx
    pop bx
    pop ax
    jc .next
    mov word [sh_lk_got], 1
    mov [sh_lk_pos], cx
    mov [sh_lk_hit], ax               ; ...and an across-walk's is its COLUMN
.next:
    inc ax
    jmp short .col
.out:
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_lkone - should the cell at AX,BX be kept? out: CF=0 keep, CF=1 pass over.
; Preserves every register: the walkers bank theirs anyway, because
; sh_getcell2 recurses into a whole evaluation for a formula cell.
;
; [sh_lk_mt] IS THE MATCH TYPE AND [sh_lk_idx] IS NOT. They were one field for
; one build, and VLOOKUP - whose third argument is a COLUMN NUMBER - then read
; that column number as a match type: VLOOKUP(x, r, 2) did an exact match and
; VLOOKUP(x, r, 0) an approximate one, both silently.
; -----------------------------------------------------------------------------
sh_lkone:
    push ax
    push bx
    push cx
    push dx
    call sh_getcell2                  ; the value lands in sh_acc/sh_sacc and
    call sh_lkcmp                     ; the tag in sh_curtype
    jc .no                            ; blank, an error, or the other type
    cmp word [sh_lk_mt], 0
    je .exact
    jg .asc
    or ax, ax                         ; type -1: keep while the key is still
    jle .yes                          ; at or above this cell
    jmp short .no
.asc:
    or ax, ax                         ; type 1: keep while the key is still at
    jge .yes                          ; or above this cell, so the LAST one
    jmp short .no                     ; kept is the largest not over it
.exact:
    or ax, ax
    jnz .no
.yes:
    pop dx
    pop cx
    pop bx
    pop ax
    clc
    ret
.no:
    pop dx
    pop cx
    pop bx
    pop ax
    stc
    ret

; -----------------------------------------------------------------------------
; sh_lkcmp - compare the banked key against the value sh_getcell2 just left.
; out: AX = -1 key below the cell, 0 equal, 1 key above it; CF=1 = the two are
;      not comparable and the cell sits the search out.
;
; A BLANK OR AN ERROR IS NEVER A CANDIDATE, and neither is a cell of the other
; type: Excel ignores text while looking for a number and the reverse, which
; is what lets a lookup table carry a header row without the search finding it.
; -----------------------------------------------------------------------------
sh_lkcmp:
    push bx
    push cx
    push si
    push di
    mov al, [sh_curtype]
    cmp al, SH_T_BLANK
    je .no
    cmp al, SH_T_ERR
    je .no
    mov bl, [sh_lk_kt]
    cmp bl, SH_T_TEXT
    je .text
    cmp al, SH_T_TEXT                 ; a number key against a text cell
    je .no
    cmp bl, SH_T_BOOL                 ; ...and a LOGICAL matches only a
    je .kbool                         ; logical, a number never one (81.51)
    cmp al, SH_T_BOOL
    je .no
    jmp short .knum
.kbool:
    cmp al, SH_T_BOOL
    jne .no
.knum:
    push si                           ; both numbers: the key into A, the
    mov si, sh_lk_kv                  ; cell's value into B
    call fp_unpack_a
    mov si, sh_acc
    call fp_unpack_b
    pop si
    call fp_cmpab
    clc
    jmp short .out
.text:
    cmp al, SH_T_TEXT                 ; a text key against a number cell
    jne .no
    mov si, sh_lk_ks
    mov di, sh_sacc
    call sh_lkstrcmp
    clc
    jmp short .out
.no:
    stc
.out:
    pop di
    pop si
    pop cx
    pop bx
    ret

; sh_lkstrcmp - SI against DI, case-insensitive; AX = -1/0/1. Preserves the
; rest. Case-insensitive because Excel's lookups are: MATCH("abc",...) finds
; "ABC", and EXACT is the function that does not.
sh_lkstrcmp:
    push bx
    push cx
    push si
    push di
.c:
    mov al, [si]
    mov bl, [di]
    call sh_lkup
    xchg al, bl
    call sh_lkup
    xchg al, bl
    cmp al, bl
    jb .lo
    ja .hi
    or al, al
    jz .eq
    inc si
    inc di
    jmp short .c
.eq:
    xor ax, ax
    jmp short .out
.lo:
    mov ax, -1
    jmp short .out
.hi:
    mov ax, 1
.out:
    pop di
    pop si
    pop cx
    pop bx
    ret

; sh_lkup - AL to upper case. Preserves everything else.
sh_lkup:
    cmp al, 'a'
    jb .out
    cmp al, 'z'
    ja .out
    sub al, 32
.out:
    ret

section SH_MODSEC                      ; 81.62: a less-used function, CHART.OVL
; =============================================================================
; sh_pinfo - the INFORMATION functions, ids 25 and up. Every one of these is a
; question about what an argument IS rather than what it is worth, so each is
; one sh_pargclass call and a comparison.
;
; in: AX = the id, SI just past '('. out: AX = the value, SI past ')'.
; =============================================================================
shm_pinfo:
    push bx
    push cx
    push dx
    push di
    mov di, ax                        ; DI = the id; sh_pargclass clobbers
    cmp di, 33                        ; everything else. NA() is the one that
    je .na                            ; takes no argument at all
    call sh_pargclass
    mov bl, [sh_argtype]
    mov bh, [sh_argaux]
    cmp di, 34
    je .type
    cmp di, 35
    je .n
    cmp di, 36
    je .errtype
    xor ax, ax                        ; every remaining id answers TRUE or
    cmp di, 25                        ; FALSE, and FALSE is the default
    je .isblank
    cmp di, 26
    je .isnumber
    cmp di, 27
    je .istext
    cmp di, 107
    je .isnontext
    cmp di, 28
    je .islogical
    cmp di, 29
    je .iserror
    cmp di, 30
    je .iserr
    cmp di, 31
    je .isna
    cmp byte [sh_argisref], 0         ; 32 ISREF - the one question only
    je .close                         ; sh_pargref can answer
    jmp .yes
.isblank:
    cmp bl, SH_T_BLANK
    je .yes
    jmp .close
.isnumber:
    cmp bl, SH_T_NUM
    je .yes
    jmp .close
.istext:
    cmp bl, SH_T_TEXT
    je .yes
    jmp .close
.isnontext:
    cmp bl, SH_T_TEXT                 ; ISNONTEXT is TRUE for everything that
    je .close                         ; is not text - a BLANK included, which
    jmp .yes                          ; is where it differs from NOT(ISTEXT())
                                      ; in Excel too
.islogical:
    cmp bl, SH_T_BOOL                 ; a comparison, a logical function or
    je .yes                           ; a logical constant (81.51). Nothing
    jmp .close                        ; produced one before, and this was
                                      ; FALSE for everything
.iserror:
    cmp bl, SH_T_ERR
    je .yes
    jmp .close
.iserr:
    cmp bl, SH_T_ERR                  ; ISERR is ISERROR MINUS #N/A, and that
    jne .close                        ; distinction is the only reason both
    cmp bh, SH_ERR_NA                 ; exist
    je .close
    jmp .yes
.isna:
    cmp bl, SH_T_ERR
    jne .close
    cmp bh, SH_ERR_NA
    jne .close
.yes:
    mov ax, 1
    jmp .close
.type:
    mov ax, 1                         ; Excel's own numbering: 1 number,
    cmp bl, SH_T_TEXT                 ; 2 text, 4 logical, 16 error. A BLANK
    jne .ty1                          ; cell is a 1 there too
    mov ax, 2
    jmp .close
.ty1:
    cmp bl, SH_T_BOOL
    jne .ty2
    mov ax, 4
    jmp .close
.ty2:
    cmp bl, SH_T_ERR
    jne .close
    mov ax, 16
    jmp .close
.errtype:
    cmp bl, SH_T_ERR                  ; THE SH_ERR_* CODES ARE Excel's OWN
    jne .errna                        ; ERROR.TYPE NUMBERS - they were numbered
    xor ah, ah                        ; that way when error values landed,
    mov al, bh                        ; precisely so this could be a copy
    jmp .close
.errna:
    mov byte [sh_evalerr], SH_ERR_NA  ; ERROR.TYPE of something that is not an
    xor ax, ax                        ; error is #N/A, not zero
    jmp .close
.na:
    mov byte [sh_evalerr], SH_ERR_NA
    xor ax, ax
    jmp .close
.n:
    cmp bl, SH_T_NUM                  ; N() passes a NUMBER through unchanged,
    je .nnum                          ; fraction and all, so it cannot leave by
    cmp bl, SH_T_ERR                  ; the integer path the rest of these use
    jne .nzero
    mov [sh_evalerr], bh              ; N of an error IS that error
.nzero:
    xor ax, ax
    SHOUT sh_acc_int
.nnum:
    SHOUT sh_acc_toint
    jmp .step
.close:
    SHOUT sh_acc_int
.step:
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

section .text
; -----------------------------------------------------------------------------
; sh_ins_at - in: DI = where in sh_numbuf to insert, AL = the byte. Everything
; from DI to the NUL moves right one, the NUL included. The building block
; both the thousands grouping and TEXT's leading zeros are made of. A string
; already SH_NUMBUF_MAX long takes nothing: the byte is dropped.
; -----------------------------------------------------------------------------
sh_ins_at:
    push ax
    push bx
    push cx
    push si
    push di
    mov bl, al
    mov cx, di                        ; CX = where to stop shifting
    mov si, di
.flen:
    cmp byte [si], 0
    je .found
    inc si
    jmp .flen
.found:
    cmp si, sh_numbuf + SH_NUMBUF_MAX ; full: the NUL is at the last byte,
    jae .out                          ; and past it are the claims' segment
    mov di, si                        ; words. Every caller inserts into
    inc di                            ; sh_numbuf, so this one test bounds
.shift:                               ; them all - TEXT's leading zeros cut
    mov al, [si]                      ; at its 40, as sh_nf_putc's do
    mov [di], al
    cmp si, cx
    je .place
    dec si
    dec di
    jmp .shift
.place:
    mov di, cx
    mov [di], bl
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_group3 - thousands separators through sh_numbuf's INTEGER part, however
; many it takes.
;
; IT REPLACES sh_comma_ins, WHICH HAD SILENTLY BECOME WRONG. That routine's
; own comment said "a 16-bit value never needs more than one - max 5 digits",
; and that was true right up until stage 4.0 made every value a double. It
; counted digits to the NUL, so the fraction counted as part of the run:
; 1234.5 in the Comma format drew as "123,4.5", and 1234567 as "1234,567".
; Nothing in the app could show a number that large or that precise when the
; routine was written.
;
; Separators go in RIGHT TO LEFT, which is why each insertion can ignore the
; ones already placed - they are all to its right.
; -----------------------------------------------------------------------------
sh_group3:
    push ax
    push bx
    push cx
    push si
    push di
    mov si, sh_numbuf
    cmp byte [si], '-'
    jne .nosign
    inc si
.nosign:
    cmp byte [si], '$'
    jne .nodollar
    inc si
.nodollar:
    mov bx, si                        ; BX = the first integer digit
.ilen:
    mov al, [si]
    cmp al, '0'
    jb .iend
    cmp al, '9'
    ja .iend
    inc si
    jmp .ilen
.iend:
    mov cx, si
    sub cx, bx                        ; CX = how many integer digits
.loop:
    cmp cx, 4
    jb .out                           ; three or fewer need no separator
    sub cx, 3
    mov di, bx
    add di, cx
    mov al, ','
    call sh_ins_at
    jmp .loop
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_numdp - fp A -> sh_numbuf with EXACTLY CX decimal places, rounded.
;
; fp_ftoa counts SIGNIFICANT digits and trims trailing zeros, which is right
; for General and wrong for money: 1.5 to two places has to be "1.50". So the
; value is rounded first (fp_round, the same one ROUND() uses) and the places
; are then padded back on.
;
; A value big or small enough that fp_ftoa reaches for scientific notation is
; left exactly as it came - padding a mantissa and grouping an exponent would
; both be nonsense, and passing it through is the one honest answer.
; -----------------------------------------------------------------------------
sh_numdp:
    push ax
    push cx
    push si
    push di
    or cx, cx
    jns .cap
    xor cx, cx                        ; a negative place count rounds left of
.cap:                                 ; the point, and shows none to the right
    cmp cx, 9
    jbe .round
    mov cx, 9
.round:
    push cx
    call fp_round
    call sh_acc_store
    call sh_acc_load_a
    mov di, sh_numbuf
    mov ax, 15
    call fp_ftoa
    pop cx
    mov si, sh_numbuf
.scan:
    mov al, [si]
    or al, al
    jz .nopoint
    cmp al, 'e'
    je .asis                          ; scientific: leave it exactly as it came
    cmp al, 'E'
    je .asis
    cmp al, '.'
    je .haspoint
    inc si
    jmp .scan
.nopoint:
    jcxz .out                         ; SI is at the NUL
    mov byte [si], '.'
    inc si
    jmp .pad
.haspoint:
    inc si
.count:
    cmp byte [si], 0
    je .padded
    inc si
    or cx, cx
    jz .count                         ; more digits than asked for: leave them
    dec cx                            ; rather than cut a rounded value short
    jmp .count
.padded:
.pad:
    jcxz .out
    mov byte [si], '0'
    inc si
    dec cx
    jmp .pad
.out:
    mov byte [si], 0
.asis:
    pop di
    pop si
    pop cx
    pop ax
    ret

section SH_MODSEC                      ; 81.62: a less-used function, CHART.OVL
; -----------------------------------------------------------------------------
; sh_dollar_ins - '$' in front of sh_numbuf's digits but AFTER a leading '-',
; so -123 in a currency format is "-$123" and not "$-123".
; -----------------------------------------------------------------------------
sh_dollar_ins:
    push ax
    push di
    mov di, sh_numbuf
    cmp byte [di], '-'
    jne .here
    inc di
.here:
    mov al, '$'
    SHOUT sh_ins_at
    pop di
    pop ax
    ret

section .text
; -----------------------------------------------------------------------------
; sh_padzero - pad sh_numbuf's integer part with leading zeros to CL digits,
; which is what the '0' placeholders in a TEXT format ask for ("00000").
; -----------------------------------------------------------------------------
sh_padzero:
    push ax
    push bx
    push cx
    push si
    push di
    xor ch, ch
    mov si, sh_numbuf
    cmp byte [si], '-'
    jne .ns
    inc si
.ns:
    mov bx, si
.ilen:
    mov al, [si]
    cmp al, '0'
    jb .iend
    cmp al, '9'
    ja .iend
    inc si
    jmp .ilen
.iend:
    mov ax, si
    sub ax, bx                        ; AX = integer digits present
.pad:
    cmp ax, cx
    jae .out
    mov di, bx
    push ax
    mov al, '0'
    call sh_ins_at
    pop ax
    inc ax
    jmp .pad
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

section SH_MODSEC                      ; 81.62: a less-used function, CHART.OVL
; -----------------------------------------------------------------------------
; sh_upcase - AL and AH both to upper case, for SEARCH's folded compare
; -----------------------------------------------------------------------------
sh_upcase:
    cmp al, 'a'
    jb .a1
    cmp al, 'z'
    ja .a1
    sub al, 32
.a1:
    cmp ah, 'a'
    jb .a2
    cmp ah, 'z'
    ja .a2
    sub ah, 32
.a2:
    ret

section .text
; -----------------------------------------------------------------------------
; sh_matchat - in: SI, DI; out: CF=1 if the string at DI is a prefix of the
; one at SI. Both preserved.
;
; AN EMPTY NEEDLE NEVER MATCHES, deliberately: SUBSTITUTE walks the text one
; character at a time and advances by the needle's length on a hit, so an
; empty one that matched would advance by nothing and never terminate.
; -----------------------------------------------------------------------------
sh_matchat:
    push ax
    push si
    push di
    cmp byte [di], 0
    je .no
.l:
    mov al, [di]
    or al, al
    jz .yes
    mov ah, [si]
    cmp al, ah
    jne .no
    inc si
    inc di
    jmp .l
.yes:
    stc
    jmp .out
.no:
    clc
.out:
    pop di
    pop si
    pop ax
    ret

section SH_MODSEC                      ; 81.62: a less-used function, CHART.OVL
; -----------------------------------------------------------------------------
; sh_strfind - in: SI = haystack, DI = needle, AX = 0-based start,
;              DL = 0 exact / 1 case-folded (which is FIND vs SEARCH, and the
;              only difference between them)
; out: AX = the 0-based position, or 0xFFFF for no match.
;
; The two bases live in bss rather than on the stack because the inner compare
; needs SI and DI, the outer scan needs a third pointer, and the 8086 will
; only address memory through BX, BP, SI and DI - with BP belonging to SS.
; -----------------------------------------------------------------------------
sh_strfind:
    push bx
    push cx
    push dx
    push si
    push di
    mov [sh_fnd_hb], si
    mov [sh_fnd_nd], di
    mov bx, si
    or ax, ax
    js .none                          ; a start before the string has no answer
.adv:
    or ax, ax
    jz .outer
    cmp byte [bx], 0
    je .none                          ; a start past the end likewise
    inc bx
    dec ax
    jmp .adv
.outer:
    mov si, bx
    mov di, [sh_fnd_nd]
.inner:
    mov al, [di]
    or al, al
    jz .hit                           ; the needle ran out: a match
    mov ah, [si]
    or ah, ah
    jz .nohit                         ; the haystack ran out first
    or dl, dl
    jz .same
    call sh_upcase
.same:
    cmp al, ah
    jne .nohit
    inc si
    inc di
    jmp .inner
.nohit:
    cmp byte [bx], 0
    je .none
    inc bx
    jmp .outer
.hit:
    mov ax, bx
    sub ax, [sh_fnd_hb]
    jmp .out
.none:
    mov ax, 0xFFFF
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_sacc_putc - append AL to sh_sacc, dropping it once SH_STR_MAX is reached.
; It finds the end each time, which is O(n^2) over 64 bytes and costs less
; than the cursor a caller would otherwise have to thread through two loops.
; -----------------------------------------------------------------------------
sh_sacc_putc:
    push ax
    push cx
    push si
    mov si, sh_sacc
    mov cx, SH_STR_MAX
.f:
    cmp byte [si], 0
    je .at
    inc si
    dec cx
    jnz .f
    jmp .out
.at:
    mov [si], al
    mov byte [si+1], 0
.out:
    pop si
    pop cx
    pop ax
    ret

section .text
; =============================================================================
; THE STRING STACK (stage 4.5)
;
; A text function with more than one string argument has to hold the first one
; while the second is parsed - and parsing the second can reach any text
; function again, which writes sh_sacc. sh_sacc alone is therefore not enough,
; and neither is a second fixed buffer: `=FIND(A1, LEFT(A2,3))` would have the
; inner LEFT overwrite the outer FIND's banked needle.
;
; This is NOT the machine stack. SPEC.md 20.6 rule 6 gives a task 384 bytes
; and says in as many words: no deep recursion, no big stack buffers. Banking
; 65 bytes per argument per frame there, under six levels of sh_eval_cell
; recursion, is exactly the buffer that rule forbids. So the bank is bss, it
; is bounded at SH_SSTK_N levels, and running out is a #VALUE! rather than a
; silent overwrite.
; =============================================================================
; sh_smove - copy SH_STR_MAX+1 bytes SI -> DI, both DS-relative. Not `rep
; movsb`, because ES belongs to the cell segment through most of this file.
sh_smove:
    push ax
    push cx
    push si
    push di
    mov cx, SH_STR_MAX + 1
.l:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .l
    pop di
    pop si
    pop cx
    pop ax
    ret

; sh_sslot - in: AX = depth from the TOP (0 = the string banked last)
; out: SI = its address. Reading past the bottom gives the EMPTY string, not
; whatever bss lies below it.
sh_sslot:
    push ax
    push dx
    mov si, sh_snull
    mov dx, [sh_sstk_sp]
    inc ax
    cmp ax, dx
    ja .out
    sub dx, ax
    mov ax, dx
    mov dx, SH_STR_MAX + 1
    mul dx
    add ax, sh_sstk
    mov si, ax
.out:
    pop dx
    pop ax
    ret

; sh_spush - bank sh_sacc. out: CF=1 the stack is full, and #VALUE! is raised
sh_spush:
    push ax
    push dx
    push si
    push di
    mov ax, [sh_sstk_sp]
    cmp ax, SH_SSTK_N
    jae .full
    inc word [sh_sstk_sp]
    mov dx, SH_STR_MAX + 1
    mul dx                            ; DX:AX, and SH_SSTK_N * 65 is far
    add ax, sh_sstk                   ; inside a segment, so DX is zero
    mov di, ax
    mov si, sh_sacc
    call sh_smove
    clc
    jmp .out
.full:
    mov byte [sh_evalerr], SH_ERR_VALUE
    stc
.out:
    pop di
    pop si
    pop dx
    pop ax
    ret

; sh_spop - drop the top bank
sh_spop:
    cmp word [sh_sstk_sp], 0
    je .out
    dec word [sh_sstk_sp]
.out:
    ret

; sh_srestore - put the top bank back in sh_sacc and drop it
sh_srestore:
    push ax
    push si
    push di
    xor ax, ax
    call sh_sslot
    mov di, sh_sacc
    call sh_smove
    call sh_spop
    pop di
    pop si
    pop ax
    ret

; sh_pstrarg - one argument, AS TEXT in sh_sacc, whatever it was worth
sh_pstrarg:
    call sh_pcmp
    call sh_str_want
    ret

section SH_MODSEC                      ; 81.62: a less-used function, CHART.OVL

; shm_vpush / shm_binop_pre - sh_vpush and sh_binop_pre for the module (81.62).
; Those two move sh_acc on and off their CALLER's stack past their own return
; address, so behind a far call and a shim they would bank it on the shim's
; frame and retf into the value. The stack work has to happen here; the fp
; loading, which touches no stack, calls back as sh_binop_ld
shm_vpush:
    ; STKBALANCE-NET: +4 - banks sh_acc on the CALLER's stack for a binary operator; shm_binop_pre takes it off
    pop ax
    push word [sh_acc+6]
    push word [sh_acc+4]
    push word [sh_acc+2]
    push word [sh_acc]
    push ax
    ret
shm_binop_pre:
    ; STKBALANCE-NET: -4 - the other half of shm_vpush - one call each, always paired
    pop ax
    pop word [sh_lhs]
    pop word [sh_lhs+2]
    pop word [sh_lhs+4]
    pop word [sh_lhs+6]
    push ax
    SHOUT sh_binop_ld
    ret

; =============================================================================
; sh_ptext (stage 4.5) - the TEXT functions, ids 37 and up. The whole category
; was blocked on two things and both have now landed: a formula could not
; return a string at all until 81.22, and a function could not keep an
; argument as a string across the next one until the bank above.
;
; in: AX = the id, SI just past '('.
; out: AX = the integer form of the result, SI past ')', and sh_curtype says
; which half of the result pair is live - these are the FIRST functions in
; this file whose answer may be either.
;
; EVERY ONE THAT TAKES A SECOND ARGUMENT BANKS ITS STRING FIRST. Parsing the
; second argument can reach any text function, and every one of those writes
; sh_sacc; `=LEFT(A1, LEN("abc"))` destroyed A1's text between reading it and
; cutting it.
; =============================================================================
shm_ptext:
    push bx
    push cx
    push dx
    push di
    mov di, ax
    cmp di, 46
    je .char                          ; CHAR takes a NUMBER, not a string
    cmp di, 49
    je .t                             ; T asks the TYPE, so it must see the
    cmp di, 55                        ; argument before sh_str_want converts it
    jb .strarg                        ; TEXT/DOLLAR/FIXED open with a NUMBER
    cmp di, 57                        ; ...AND THEY ARE 55..57 ALONE. This was
    jbe .numfmt3                      ; a bare `jae .numfmt3`, which reads as
.strarg:                              ; "every id from 55 up" - true while 54
    SHOUT sh_pstrarg                  ; was the last text function, false the
                                      ; moment CLEAN took 108. CLEAN went down
                                      ; the number-formatting path and gave
                                      ; "0.00" for every string it was handed.
                                      ; A ONE-SIDED COMPARE IS A CLAIM ABOUT
                                      ; IDS NOT YET ASSIGNED - bound it
    cmp di, 37
    je .len
    cmp di, 38
    je .left
    cmp di, 39
    je .right
    cmp di, 40
    je .mid
    cmp di, 41
    je .upper
    cmp di, 42
    je .lower
    cmp di, 43
    je .proper
    cmp di, 44
    je .trim
    cmp di, 108
    je .clean
    cmp di, 110
    je .indirect
    cmp di, 45
    je .rept
    cmp di, 47
    je .code
    cmp di, 48
    je .exact
    cmp di, 51
    je .find
    cmp di, 52
    je .find                          ; SEARCH is FIND with the compare folded
    cmp di, 53
    je .subst
    cmp di, 54
    je .replace
    push si                           ; 50 VALUE
    mov si, sh_sacc
    SHOUT fp_atof                     ; CF=1 = nothing parseable in there
    pop si
    jc .valbad
    SHOUT sh_acc_store
    SHOUT sh_acc_toint
    mov byte [sh_curtype], SH_T_NUM
    jmp .close2
.valbad:
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    jmp .num

.indirect:                            ; the argument is a REFERENCE SPELLED AS
    push si                           ; TEXT, so it is parsed out of sh_sacc by
    mov si, sh_sacc                   ; the same routine that reads one out of
    SHOUT sh_pcellref                 ; a formula. SI is banked because that
    jnc .indbad                       ; routine advances it and the formula's
    cmp byte [si], 0                  ; own cursor is live. "A1:B2" and "A1 "
    jne .indbad                       ; are not single references and are
    pop si                            ; refused rather than half-read
    SHOUT sh_getcell2                 ; -> sh_acc, sh_curtype, and sh_sacc too
    SHOUT sh_acc_toint                ; if the target holds a LABEL, which is
    jmp .close2                       ; why sh_curtype is left as it set it
.indbad:
    pop si
    mov byte [sh_evalerr], SH_ERR_REF ; #REF!, which is what Excel gives for
    xor ax, ax                        ; INDIRECT("not a reference")
    jmp .num

.len:
    push si
    mov si, sh_sacc
    SHOUT sh_strlen                   ; LEN of a NUMBER is the length of the
    pop si                            ; text it displays as, which is what
    jmp .num                          ; sh_str_want already produced

.code:
    mov al, [sh_sacc]
    or al, al
    jnz .code1
    mov byte [sh_evalerr], SH_ERR_VALUE  ; CODE("") has no answer to give
.code1:
    xor ah, ah
    jmp .num

.char:
    SHOUT sh_parg
    cmp ax, 1
    jl .charbad
    cmp ax, 255
    jle .charok
.charbad:
    mov byte [sh_evalerr], SH_ERR_VALUE
    mov byte [sh_sacc], 0
    jmp .text
.charok:
    mov [sh_sacc], al
    mov byte [sh_sacc+1], 0
    jmp .text

.t:
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT  ; T passes TEXT through and answers the
    je .text                          ; empty string for everything else -
    mov byte [sh_sacc], 0             ; which is the whole of what it is for
    jmp .text

.left:
    SHOUT sh_spush
    jc .text
    mov cx, 1                         ; LEFT(t) with no count means one
    cmp byte [si], ','
    jne .left1
    inc si
    SHOUT sh_parg
    mov cx, ax
.left1:
    SHOUT sh_srestore
    or cx, cx
    jns .left2
    mov byte [sh_evalerr], SH_ERR_VALUE  ; a negative count is Excel's #VALUE!
    xor cx, cx
.left2:
    push si
    mov si, sh_sacc
.leftl:
    jcxz .leftcut
    cmp byte [si], 0
    je .leftd
    inc si
    dec cx
    jmp .leftl
.leftcut:
    mov byte [si], 0
.leftd:
    pop si
    jmp .text

.right:
    SHOUT sh_spush
    jc .text
    mov cx, 1
    cmp byte [si], ','
    jne .right1
    inc si
    SHOUT sh_parg
    mov cx, ax
.right1:
    SHOUT sh_srestore
    or cx, cx
    jns .right2
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor cx, cx
.right2:
    push si
    mov si, sh_sacc
    SHOUT sh_strlen
    sub ax, cx                        ; AX = where the tail starts
    jns .right3
    xor ax, ax                        ; asking for more than there is gives
.right3:                              ; all of it, not an error
    mov si, sh_sacc
    add si, ax
    push di
    mov di, sh_sacc
    SHOUT sh_strcpy                   ; destination BELOW source, so a forward
    pop di                            ; copy of an overlap is safe
    pop si
    jmp .text

.mid:
    SHOUT sh_spush
    jc .text
    xor bx, bx
    xor cx, cx
    cmp byte [si], ','
    jne .midrest
    inc si
    SHOUT sh_parg
    mov bx, ax                        ; BX = the 1-based start
    cmp byte [si], ','
    jne .midrest
    inc si
    SHOUT sh_parg
    mov cx, ax
.midrest:
    SHOUT sh_srestore
    or bx, bx
    jg .mid1
    mov byte [sh_evalerr], SH_ERR_VALUE  ; MID's start is 1-based and a start
    mov byte [sh_sacc], 0             ; below 1 is #VALUE!, not a clamp
    jmp .text
.mid1:
    or cx, cx
    jns .mid2
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor cx, cx
.mid2:
    dec bx
    push si
    mov si, sh_sacc
    SHOUT sh_strlen
    cmp bx, ax
    jb .mid3
    mov byte [sh_sacc], 0             ; a start past the end is the empty
    pop si                            ; string, which is not an error
    jmp .text
.mid3:
    mov si, sh_sacc
    add si, bx
    push di
    mov di, sh_sacc
.midcopy:
    jcxz .midterm
    mov al, [si]
    or al, al
    jz .midterm
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .midcopy
.midterm:
    mov byte [di], 0
    pop di
    pop si
    jmp .text

.upper:
    push si
    mov si, sh_sacc
.ul:
    mov al, [si]
    or al, al
    jz .uld
    cmp al, 'a'
    jb .uln
    cmp al, 'z'
    ja .uln
    sub al, 32
    mov [si], al
.uln:
    inc si
    jmp .ul
.uld:
    pop si
    jmp .text

.lower:
    push si
    mov si, sh_sacc
.ll:
    mov al, [si]
    or al, al
    jz .lld
    cmp al, 'A'
    jb .lln
    cmp al, 'Z'
    ja .lln
    add al, 32
    mov [si], al
.lln:
    inc si
    jmp .ll
.lld:
    pop si
    jmp .text

.proper:
    push si
    mov si, sh_sacc
    xor bl, bl                        ; BL = the previous character was a letter
.pl:
    mov al, [si]
    or al, al
    jz .pld
    call sh_isalpha                   ; CF=1 = a letter
    jnc .pnotal
    or bl, bl
    jnz .plow                         ; inside a word: lower case
    cmp al, 'a'                       ; starting one: upper
    jb .pset
    cmp al, 'z'
    ja .pset
    sub al, 32
    jmp .pset
.plow:
    cmp al, 'A'
    jb .pset
    cmp al, 'Z'
    ja .pset
    add al, 32
.pset:
    mov [si], al
    mov bl, 1
    jmp .pnext
.pnotal:
    xor bl, bl                        ; anything that is not a letter starts a
.pnext:                               ; new word, digits and punctuation alike
    inc si
    jmp .pl
.pld:
    pop si
    jmp .text

; TRIM removes the leading and trailing spaces AND collapses every internal
; run to one. That last part is the half people forget, and it is the half
; that makes TRIM worth having on data pasted out of a report.
.clean:
    push si                           ; every control character out, the rest
    push di                           ; kept in place - what CLEAN is for is
    mov si, sh_sacc                   ; text that arrived from another machine
    mov di, sh_sacc                   ; with line breaks still in it
.cl:
    mov al, [si]
    inc si
    or al, al
    jz .cldone
    cmp al, ' '
    jb .cl                            ; below space: drop it
    mov [di], al
    inc di
    jmp .cl
.cldone:
    mov byte [di], 0
    pop di
    pop si
    jmp .text
.trim:
    push si
    push di
    mov si, sh_sacc
    mov di, sh_sacc
.tskip:
    cmp byte [si], ' '
    jne .tloop
    inc si
    jmp .tskip
.tloop:
    mov al, [si]
    or al, al
    jz .tend
    cmp al, ' '
    jne .tkeep
    inc si
    cmp byte [si], 0                  ; a run at the very END leaves nothing
    je .tend
    cmp byte [si], ' '
    je .tloop
    mov byte [di], ' '
    inc di
    jmp .tloop
.tkeep:
    mov [di], al
    inc di
    inc si
    jmp .tloop
.tend:
    mov byte [di], 0
    pop di
    pop si
    jmp .text

.rept:
    SHOUT sh_spush                    ; the pattern stays banked for the whole
    jc .text                          ; build, because sh_sacc becomes the
    xor cx, cx                        ; RESULT
    cmp byte [si], ','
    jne .rept0
    inc si
    SHOUT sh_parg
    mov cx, ax
.rept0:
    or cx, cx
    jns .rept1
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor cx, cx
.rept1:
    cmp cx, SH_STR_MAX                ; the result clips at SH_STR_MAX and each
    jbe .rept2                        ; round adds at least one character, so
    mov cx, SH_STR_MAX                ; REPT("x",30000) is 64 rounds, not 30000
.rept2:
    mov byte [sh_sacc], 0
.reptl:
    jcxz .reptd
    push cx
    push si
    xor ax, ax
    SHOUT sh_sslot
    SHOUT sh_str_cat
    pop si
    pop cx
    dec cx
    jmp .reptl
.reptd:
    SHOUT sh_spop
    jmp .text

.exact:
    SHOUT sh_spush
    jc .exzero
    cmp byte [si], ','
    jne .exdrop
    inc si
    SHOUT sh_pstrarg
    push si
    push di
    xor ax, ax
    SHOUT sh_sslot
    mov di, sh_sacc
    SHOUT sh_streq                    ; CASE-SENSITIVE, which is the whole
    pop di                            ; difference between EXACT and '='
    pop si
    mov ax, 0
    jnc .ex1
    mov ax, 1
.ex1:
    SHOUT sh_spop
    jmp .num
.exdrop:
    SHOUT sh_spop
.exzero:
    xor ax, ax
    jmp .num

; ---- FIND (51) and SEARCH (52) ----------------------------------------------
; The same scan; SEARCH folds case. Neither takes wildcards - Excel's SEARCH
; does, and saying so is better than a '?' that silently matches itself.
.find:
    SHOUT sh_spush                    ; the needle
    jc .textzero
    cmp byte [si], ','
    jne .find1drop
    inc si
    SHOUT sh_pstrarg                  ; the haystack
    SHOUT sh_spush
    jc .find1drop
    mov bx, 1                         ; the start defaults to the first
    cmp byte [si], ','                ; character
    jne .findgo
    inc si
    SHOUT sh_parg
    mov bx, ax
.findgo:
    dec bx                            ; 0-based
    push si
    push di
    xor dl, dl
    cmp di, 52
    jne .findcs
    mov dl, 1
.findcs:
    xor ax, ax
    SHOUT sh_sslot                    ; SI = the haystack
    push si
    mov ax, 1
    SHOUT sh_sslot                    ; SI = the needle
    mov di, si
    pop si
    mov ax, bx
    call sh_strfind
    pop di
    pop si
    SHOUT sh_spop
    SHOUT sh_spop
    cmp ax, 0xFFFF
    je .findnone
    inc ax                            ; FIND answers 1-based, as Excel does
    jmp .num
.findnone:
    mov byte [sh_evalerr], SH_ERR_VALUE  ; not found is #VALUE!, which is what
    xor ax, ax                        ; makes ISERROR the standard way to ask
    jmp .num                          ; whether it was there at all
.find1drop:
    SHOUT sh_spop
    xor ax, ax
    jmp .num

; ---- SUBSTITUTE(text, old, new, [instance]) (53) -----------------------------
.subst:
    SHOUT sh_spush                    ; the text
    jc .textzero
    cmp byte [si], ','
    jne .sub1drop
    inc si
    SHOUT sh_pstrarg
    SHOUT sh_spush                    ; old
    jc .sub1drop
    cmp byte [si], ','
    jne .sub2drop
    inc si
    SHOUT sh_pstrarg
    SHOUT sh_spush                    ; new
    jc .sub2drop
    xor bx, bx                        ; 0 = every occurrence, which is what no
    cmp byte [si], ','                ; fourth argument means
    jne .subgo
    inc si
    SHOUT sh_parg
    mov bx, ax
    or bx, bx
    jg .subgo
    mov byte [sh_evalerr], SH_ERR_VALUE  ; instance 0 or negative
    xor bx, bx
.subgo:
    push si
    push di
    xor cx, cx                        ; CX = occurrences seen so far
    mov ax, 2
    SHOUT sh_sslot
    mov di, si                        ; DI = the cursor through the text
    mov byte [sh_sacc], 0
.subl:
    cmp byte [di], 0
    je .subend
    mov ax, 1
    SHOUT sh_sslot                    ; SI = old
    xchg si, di
    SHOUT sh_matchat                  ; does old start here?
    xchg si, di
    jnc .subcopy
    inc cx
    or bx, bx
    jz .subrepl
    cmp cx, bx
    jne .subkeep                      ; a numbered instance, and not this one
.subrepl:
    xor ax, ax
    SHOUT sh_sslot                    ; SI = new
    SHOUT sh_str_cat
    mov ax, 1
    SHOUT sh_sslot                    ; SI = old, to measure the skip
.subskip:
    cmp byte [si], 0
    je .subl
    inc si
    inc di
    jmp .subskip
.subkeep:
    mov ax, 1
    SHOUT sh_sslot
.subkeepl:
    cmp byte [si], 0
    je .subl
    mov al, [di]
    call sh_sacc_putc
    inc si
    inc di
    jmp .subkeepl
.subcopy:
    mov al, [di]
    call sh_sacc_putc
    inc di
    jmp .subl
.subend:
    pop di
    pop si
    SHOUT sh_spop
    SHOUT sh_spop
    SHOUT sh_spop
    jmp .text
.sub2drop:
    SHOUT sh_spop
.sub1drop:
    SHOUT sh_spop
    jmp .textzero

; ---- REPLACE(old_text, start, num_chars, new_text) (54) ----------------------
.replace:
    SHOUT sh_spush                    ; old_text
    jc .textzero
    xor bx, bx
    xor cx, cx
    cmp byte [si], ','
    jne .rep1drop
    inc si
    SHOUT sh_parg
    mov bx, ax                        ; BX = the 1-based start
    cmp byte [si], ','
    jne .rep1drop
    inc si
    SHOUT sh_parg
    mov cx, ax                        ; CX = how many characters go
    cmp byte [si], ','
    jne .rep1drop
    inc si
    SHOUT sh_pstrarg                  ; new_text
    SHOUT sh_spush
    jc .rep1drop
    or bx, bx
    jg .repgo
    mov byte [sh_evalerr], SH_ERR_VALUE  ; REPLACE's start is 1-based too
    mov bx, 1
.repgo:
    dec bx
    or cx, cx
    jns .rep2
    xor cx, cx
.rep2:
    push si
    push di
    mov ax, 1
    SHOUT sh_sslot                    ; SI = old_text
    mov di, sh_sacc
    mov dx, bx                        ; DX = how many head characters to keep
.rephead:
    or dx, dx
    jz .repheadend
    mov al, [si]
    or al, al
    jz .repheadend
    mov [di], al
    inc si
    inc di
    dec dx
    jmp .rephead
.repheadend:
    mov byte [di], 0
.repskip:
    jcxz .reptail
    cmp byte [si], 0
    je .reptail
    inc si
    dec cx
    jmp .repskip
.reptail:
    push si                           ; where the tail starts
    xor ax, ax
    SHOUT sh_sslot                    ; SI = new_text
    SHOUT sh_str_cat
    pop si
    SHOUT sh_str_cat
    pop di
    pop si
    SHOUT sh_spop
    SHOUT sh_spop
    jmp .text
.rep1drop:
    SHOUT sh_spop
    jmp .textzero

; ---- TEXT / DOLLAR / FIXED (55, 56, 57) --------------------------------------
; The three that turn a number into text. All open with a VALUE rather than a
; string, so they are dispatched before the shared sh_pstrarg above.
.numfmt3:
    SHOUT sh_pcmp                     ; the value
    cmp di, 55
    je .dotext55
    call shm_vpush                    ; banked across the count's own parse
    mov cx, 2                         ; DOLLAR and FIXED both default to two
    cmp byte [si], ','
    jne .nfnone
    inc si
    SHOUT sh_parg
    mov cx, ax
    xor bl, bl                        ; BL = FIXED's "no commas" flag, zeroed
    cmp di, 57                        ; AFTER sh_parg rather than before it -
    jne .nf1                          ; sh_pcmp underneath it clobbers BL
    cmp byte [si], ','                ; FIXED's third argument suppresses the
    jne .nf1                          ; separators
    inc si
    push cx
    SHOUT sh_parg
    or ax, ax
    jz .nf0
    mov bl, 1
.nf0:
    pop cx
    jmp .nf1
.nfnone:
    xor bl, bl
.nf1:
    ; NOTHING MAY SIT ON THE STACK ACROSS sh_vpush -> sh_binop_pre: the pair
    ; banks the value in the CALLER's frame, below the return address, so a
    ; push in between is what sh_binop_pre would pop as the value. BL and CX
    ; go to bss for the one instruction it takes.
    mov [sh_fmt_fl], bl
    mov [sh_fmt_cx], cx
    call shm_binop_pre                ; A = the value again
    mov bl, [sh_fmt_fl]
    mov cx, [sh_fmt_cx]
    cmp di, 56
    je .dollar
    SHOUT sh_numdp
    or bl, bl
    jnz .nfdone
    SHOUT sh_group3
.nfdone:
    jmp .numtext

; DOLLAR wraps a NEGATIVE in parentheses - "($1,234.57)" - which is Excel's
; own rendering and not the same as a minus sign.
.dollar:
    push cx
    SHOUT sh_acc_store
    mov cl, [sh_acc+7]
    mov [sh_dol_neg], cl              ; the packed double's sign bit
    and byte [sh_acc+7], 0x7F         ; format the magnitude
    SHOUT sh_acc_load_a
    pop cx
    SHOUT sh_numdp
    SHOUT sh_group3
    call sh_dollar_ins
    test byte [sh_dol_neg], 0x80
    jz .numtext
    push di
    mov di, sh_numbuf
    mov al, '('
    SHOUT sh_ins_at
    pop di
    push si
    mov si, sh_numbuf
    SHOUT sh_strlen
    mov si, sh_numbuf
    add si, ax
    mov byte [si], ')'
    mov byte [si+1], 0
    pop si
    jmp .numtext

; TEXT(value, format) - by sh_fmtcode, the engine the grid draws with (81.55):
; Excel's whole code, sections, dates and times included. This read '$', ',',
; the placeholders around '.' and a trailing '%', and fell back to General on
; anything else - so TEXT(DATE(1990,1,15),"m/d/yy") answered 32888.
.dotext55:
    call shm_vpush                    ; the value, banked across the code's parse
    cmp byte [si], ','
    jne .t55none
    inc si
    SHOUT sh_pstrarg                  ; the code, in sh_sacc - which sh_fmtcode
    call shm_binop_pre                ; never touches, so it needs no bank
    SHOUT sh_acc_store
    push si
    mov si, sh_sacc
    SHOUT sh_fmtcode                  ; -> sh_numbuf
    pop si
    jmp .numtext
.t55none:
    call shm_binop_pre                ; unwind the bank, whatever went wrong
.textzero:
    mov byte [sh_sacc], 0
    jmp .text

; sh_numbuf now holds the formatted text: hand it over as the result
.numtext:
    push si
    push di
    mov si, sh_numbuf
    mov di, sh_sacc
    SHOUT sh_strcpy
    pop di
    pop si
    jmp .text

.num:
    mov byte [sh_curtype], SH_T_NUM
    SHOUT sh_acc_int
    jmp .close2
.text:
    mov byte [sh_curtype], SH_T_TEXT
    xor ax, ax
    SHOUT sh_acc_int                  ; the number underneath a string is zero
    xor ax, ax                        ; ...and so is the integer form sh_pfunc
                                       ; hands its own caller
.close2:
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; sh_isalpha - in: AL; out: CF=1 if it is a letter (AL untouched)
sh_isalpha:
    cmp al, 'A'
    jb .no
    cmp al, 'Z'
    jbe .yes
    cmp al, 'a'
    jb .no
    cmp al, 'z'
    ja .no
.yes:
    stc
    ret
.no:
    clc
    ret

section .text
; =============================================================================
; DATE SERIALS (stage 4.5)
;
; A date is a NUMBER: the count of days since the epoch, with the time of day
; in the fraction. That is Excel's model and it is why dates arithmetic at all
; - tomorrow is +1, an interval is a subtraction, and a date sorts because it
; is a number that happens to be shown as a date.
;
; THE EPOCH IS SERIAL 1 = 1 JANUARY 1900, AND SERIAL 60 IS 29 FEBRUARY 1900 -
; A DAY THAT NEVER EXISTED. 1900 was not a leap year; Lotus 1-2-3 thought it
; was, Excel copied the mistake so the two could exchange files, and every
; version since has kept it for the same reason. Getting it "right" here would
; put every date in a shared file one day out from what Excel shows, which is
; a worse bug than the one being reproduced. So serial 60 is the phantom day,
; and 61 is 1 March 1900.
;
; The range is what an UNSIGNED word holds, which is almost exactly Excel
; 2.1's own: serial 65535 is 5 June 2079, and 2.1 stops at 31 December 2078.
; -----------------------------------------------------------------------------
; sh_fp_32768_b - B = 32768.0. Clobbers A, so build it BEFORE loading the
; value. fp_i2b cannot: 32768 is not a signed 16-bit integer.
; -----------------------------------------------------------------------------
sh_fp_32768_b:
    push ax
    mov word [fp_t0], 0x8000
    mov word [fp_t1], 0
    mov word [fp_t2], 0
    mov word [fp_t3], 0
    call fp_u64_to_a
    call fp_a_to_b
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_acc_toudw - sh_acc, truncated toward zero, as an UNSIGNED word in AX.
;
; fp_a2i is signed and clamps at 32767 - as a date serial that is 24 September
; 1989, so every date this app will ever be asked about is past it and the
; signed conversion is not usable for serials at all. The top bit is taken off
; by hand and put back with an unsigned add.
;
; out: AX = the word; CF=1 if the value was negative or 65536 or more, with
; AX = 0. Every other register preserved.
; -----------------------------------------------------------------------------
sh_acc_toudw:
    push bx
    call sh_acc_load_a
    call fp_trunc
    call sh_acc_store
    test byte [sh_acc+7], 0x80        ; a negative serial has no unsigned form
    jnz .bad
    call sh_fp_32768_b
    call sh_acc_load_a
    call fp_cmpab                     ; SIGNED flags: fp_cmpab answers -1/0/1
    jl .small                         ; in AX and sets them from that, so `jb`
                                       ; is never taken and every serial past
                                       ; 32767 fell down the clamping path
    call sh_fp_32768_b
    call sh_acc_load_a
    call fp_sub                       ; A = value - 32768, now 0..32767
    call fp_a2i
    jc .bad
    add ax, 32768                     ; ...and back on, unsigned
    clc
    jmp .out
.small:
    call sh_acc_load_a
    call fp_a2i
    jc .bad
.out:
    pop bx
    ret
.bad:
    xor ax, ax
    stc
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_acc_fromudw - AX, an unsigned word, becomes sh_acc. fp_i2a is signed and
; would make 46265 negative.
; -----------------------------------------------------------------------------
sh_acc_fromudw:
    push ax
    mov [fp_t0], ax
    mov word [fp_t1], 0
    mov word [fp_t2], 0
    mov word [fp_t3], 0
    call fp_u64_to_a
    call sh_acc_store
    pop ax
    ret

; sh_isleap - in: sh_dt_ly = the year; out: CF=1 if it is a leap year.
; The full rule, not "divisible by four": 1900 is not a leap year and 2000 is,
; and both are inside the range this app covers.
sh_isleap:
    push ax
    push bx
    push dx
    mov ax, [sh_dt_ly]
    mov bx, 400
    xor dx, dx
    div bx
    or dx, dx
    jz .yes                           ; a multiple of 400 always is
    mov ax, [sh_dt_ly]
    mov bx, 100
    xor dx, dx
    div bx
    or dx, dx
    jz .no                            ; a multiple of 100 (but not 400) is not
    mov ax, [sh_dt_ly]
    mov bx, 4
    xor dx, dx
    div bx
    or dx, dx
    jz .yes
.no:
    clc
    jmp .out
.yes:
    stc
.out:
    pop dx
    pop bx
    pop ax
    ret

; sh_yearlen - in: AX = year; out: AX = 365 or 366
sh_yearlen:
    mov [sh_dt_ly], ax
    call sh_isleap
    mov ax, 365
    jnc .out
    inc ax
.out:
    ret

; sh_monlen - in: AX = month 1..12, BX = year; out: AX = days in it
sh_monlen:
    push bx
    push si
    cmp ax, 1
    jb .bad
    cmp ax, 12
    ja .bad
    mov si, ax
    dec si
    mov [sh_dt_ly], bx
    xor bh, bh
    mov bl, [sh_dt_mlen + si]
    mov ax, bx
    cmp si, 1                         ; February
    jne .out
    call sh_isleap
    jnc .out
    inc ax
    jmp .out
.bad:
    xor ax, ax
.out:
    pop si
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_ser_to_ymd - in: AX = an unsigned date serial; out: sh_dt_y/m/d.
; A serial of 0 or one past the range answers 1900/1/0, which is what Excel
; shows for serial 0 and is not an error.
; -----------------------------------------------------------------------------
sh_ser_to_ymd:
    push ax
    push bx
    push cx
    push dx
    mov word [sh_dt_y], 1900
    mov word [sh_dt_m], 1
    mov word [sh_dt_d], 0
    or ax, ax
    jz .out                           ; serial 0 is Excel's own 0-January-1900
    cmp ax, 60
    jne .notphantom
    mov word [sh_dt_m], 2             ; THE PHANTOM DAY. It is not reachable by
    mov word [sh_dt_d], 29            ; walking a real calendar, because it is
    jmp .out                          ; not in one
.notphantom:
    cmp ax, 61
    jb .haven
    dec ax                            ; past it: the real calendar is one day
.haven:                               ; behind the serial
    mov cx, ax                        ; CX = days, 1 = 1900-01-01
.yloop:
    mov ax, [sh_dt_y]
    call sh_yearlen
    cmp cx, ax
    jbe .haveyear
    sub cx, ax
    inc word [sh_dt_y]
    jmp .yloop
.haveyear:
.mloop:
    mov ax, [sh_dt_m]
    mov bx, [sh_dt_y]
    call sh_monlen
    cmp cx, ax
    jbe .havemonth
    sub cx, ax
    inc word [sh_dt_m]
    jmp .mloop
.havemonth:
    mov [sh_dt_d], cx
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ymd_to_ser - in: sh_dt_y/m/d; out: AX = the serial, CF=1 if the date is
; outside 1900-01-01 .. 2079-06-06 (what an unsigned word holds).
;
; The month is allowed to run outside 1..12 and the day outside a month's
; length, exactly as Excel's DATE() does: DATE(1990,13,1) is January 1991 and
; DATE(1990,1,32) is 1 February. Rolling the month first and then simply
; ADDING the days is what makes both fall out for free.
; -----------------------------------------------------------------------------
sh_ymd_to_ser:
    push bx
    push cx
    push dx
.mroll:
    mov ax, [sh_dt_m]
    cmp ax, 1
    jge .mrollhi
    add word [sh_dt_m], 12            ; month 0 is December of the year before
    dec word [sh_dt_y]
    jmp .mroll
.mrollhi:
    cmp ax, 12
    jle .mdone
    sub word [sh_dt_m], 12
    inc word [sh_dt_y]
    jmp .mroll
.mdone:
    mov ax, [sh_dt_y]
    cmp ax, 1900
    jb .bad
    cmp ax, 2080
    ja .bad
    xor cx, cx                        ; CX = whole days before this year
    mov word [sh_dt_ys], 1900
.yloop:
    mov ax, [sh_dt_ys]
    cmp ax, [sh_dt_y]
    jae .ydone
    call sh_yearlen
    add cx, ax
    inc word [sh_dt_ys]
    jmp .yloop
.ydone:
    mov word [sh_dt_ms], 1
.mloop:
    mov ax, [sh_dt_ms]
    cmp ax, [sh_dt_m]
    jae .mdone2
    mov bx, [sh_dt_y]
    call sh_monlen
    add cx, ax
    inc word [sh_dt_ms]
    jmp .mloop
.mdone2:
    add cx, [sh_dt_d]                 ; the day, which may itself overflow the
    mov ax, cx                        ; month - Excel lets it, and adding is
    cmp ax, 60                        ; what makes that work
    jb .noskip
    inc ax                            ; step over the phantom 29 February 1900
.noskip:
    clc
    jmp .out
.bad:
    xor ax, ax
    stc
.out:
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_pnow - NOW(), id 106. The serial date plus the fraction of the day, which
; is what Excel's NOW() is: the same number DATE() gives plus the same fraction
; TIME() gives.
;
; THE BIOS IS READ THE WAY THE KERNEL READS IT, poison and all: CX/DX are set
; to 0xFFFF before the call and checked after, because a BIOS that does not
; implement the service can return with CF clear having touched nothing, and
; the sentinel is the only thing that catches it. Every BCD field is validated
; before it is believed - a clock reporting hour 0x99 is not an hour.
;
; A machine with no usable RTC gets #N/A, which is the honest answer and the
; one a spreadsheet can test with ISNA. It does NOT get the uptime dressed up
; as a date, which is what the old comment here rightly refused to fake.
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_prand - RAND(), id 109. A number in [0,1).
;
; A 32-BIT LINEAR CONGRUENTIAL GENERATOR, seed = seed*25173 + 13849, which has
; the full 2^32 period because the multiplier is 1 mod 4 and the increment is
; odd. The multiplier fits a word, so the 32x16 product is two `mul`s and an
; add rather than a long-multiply routine.
;
; SEEDED FROM THE BIOS TICK COUNT, int 1Ah AH=00h - CX:DX is ticks since
; midnight, and unlike AH=02h/04h it works on a PC with no RTC at all, which
; is exactly the machine 81.42 found here. A tick count is a poor source of
; entropy and a fine source of a seed: it only has to differ between sessions.
;
; The value is the HIGH word over 65536. The low bits of an LCG are the weak
; ones - taking the top half is the standard remedy and costs nothing.
; -----------------------------------------------------------------------------
sh_prand:
    push bx
    push cx
    push dx
    cmp word [sh_rndhi], 0            ; unseeded? the very first RAND() of a
    jne .step                         ; session pays for the BIOS call
    cmp word [sh_rndlo], 0
    jne .step
    xor ah, ah
    int 0x1a                          ; CX:DX = ticks since midnight
    mov [sh_rndhi], cx
    mov [sh_rndlo], dx
    or dx, cx
    jnz .step
    mov word [sh_rndlo], 1            ; a clock reading exactly zero would
.step:                                ; leave the generator stuck at zero
    mov ax, [sh_rndlo]
    mov cx, 25173
    mul cx                            ; DX:AX = lo * 25173
    mov bx, dx                        ; BX = the carry into the high word
    push ax
    mov ax, [sh_rndhi]
    mul cx                            ; only the low half of this matters
    add ax, bx
    mov bx, ax                        ; BX = the new high word, pre-increment
    pop ax
    add ax, 13849
    adc bx, 0
    mov [sh_rndlo], ax
    mov [sh_rndhi], bx
    mov ax, 256                       ; /256 TWICE = /65536, which is what a
    call sh_acc_int                   ; 16-bit word cannot hold in one go.
    call sh_acc_load_b                ; THE DIVISOR IS BUILT FIRST, because
    mov ax, bx                        ; sh_acc_int goes through fp_i2a and
    call sh_acc_fromudw               ; sh_acc_fromudw through fp_u64_to_a -
    call sh_acc_load_a                ; BOTH WRITE A. Loading the value into A
    call fp_div                       ; and then building 256 overwrote it, and
    call fp_div                       ; RAND() answered a constant 256/256 = 1
    call sh_acc_store                 ; (81.42.1 again, verbatim). B is loaded
                                      ; once for both divides: fpx_div and
                                      ; fps_div stage from memory and write
                                      ; back A alone, so B survives one
    xor ax, ax                        ; SH_T_NUM
    inc ax
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_bios_ymd - the calendar date from the BIOS into sh_dt_y/m/d.
; out: CF=1 if there is no usable clock. Every other register preserved.
;
; AH=04h answers CH/CL = century and year and DH/DL = month and day, all packed
; BCD. CX and DX are POISONED with 0xFFFF first and checked after, because a
; BIOS without the service can return CF clear having touched nothing - the
; sentinel is the only thing that catches that, and it is the check the kernel's
; own clk_rtc_read makes for the same reason.
; -----------------------------------------------------------------------------
sh_bios_ymd:
    push ax
    push bx
    push cx
    push dx
    mov cx, 0xFFFF
    mov dx, 0xFFFF
    mov ah, 0x04
    stc
    int 0x1a
    jc .bad
    cmp cx, 0xFFFF
    je .bad
    mov al, ch
    call sh_bcd2bin
    jc .bad
    mov bl, al                        ; the century
    mov al, cl
    call sh_bcd2bin
    jc .bad
    mov bh, al                        ; ...and the year within it
    push dx                           ; MUL WRITES DX, and DX is holding the
    mov al, bl                        ; month and day. Reading dh afterwards
    xor ah, ah                        ; got the high word of century*100 - a
    mov cx, 100                       ; month of zero, and NOW() answered #N/A
    mul cx                            ; on a machine whose clock was fine
    xor ch, ch
    mov cl, bh
    add ax, cx
    pop dx
    cmp ax, 1900
    jb .bad
    cmp ax, 2080
    ja .bad
    mov [sh_dt_y], ax
    mov al, dh
    call sh_bcd2bin
    jc .bad
    xor ah, ah
    or ax, ax
    jz .bad
    cmp ax, 12
    ja .bad
    mov [sh_dt_m], ax
    mov al, dl
    call sh_bcd2bin
    jc .bad
    xor ah, ah
    or ax, ax
    jz .bad
    cmp ax, 31
    ja .bad
    mov [sh_dt_d], ax
    pop dx
    pop cx
    pop bx
    pop ax
    clc
    ret
.bad:
    pop dx
    pop cx
    pop bx
    pop ax
    stc
    ret

sh_pnow:
    push bx
    push cx
    push dx
    push si
    call sh_bios_ymd                  ; -> sh_dt_y/m/d, CF=1 if no clock
    jc .na
    call sh_ymd_to_ser                ; -> AX = the whole days
    jc .na
    push ax
    mov cx, 0xFFFF                    ; the time: AH=02h -> CH/CL/DH = hour,
    mov dx, 0xFFFF                    ; minute and second, BCD
    mov ah, 0x02
    stc
    int 0x1a
    jc .napop
    cmp cx, 0xFFFF
    je .napop
    mov al, ch
    call sh_bcd2bin
    jc .napop
    cmp al, 23
    ja .napop
    xor bh, bh
    mov bl, al                        ; BX = hours
    mov al, cl
    call sh_bcd2bin
    jc .napop
    cmp al, 59
    ja .napop
    push bx
    xor ah, ah
    mov cx, ax                        ; CX = minutes
    mov al, dh
    call sh_bcd2bin
    pop bx
    jc .napop
    cmp al, 59
    ja .napop
    xor ah, ah
    mov dx, ax                        ; DX = seconds
    call sh_hms_to_acc                ; sh_acc = the fraction of the day
    call sh_acc_load_b                ; ...into B, WHICH MUST COME FIRST:
    pop ax                            ; sh_acc_fromudw goes through fp_u64_to_a
    call sh_acc_fromudw               ; and CLOBBERS A, so a fraction parked
    call sh_acc_load_a                ; there is gone by the add. It answered
    call fp_add                       ; twice the serial, both operands being
                                      ; the day count (81.42.1)
    call sh_acc_store
    clc
    jmp .out
.napop:
    pop ax
.na:
    mov byte [sh_evalerr], SH_ERR_NA  ; no usable clock: #N/A, and ISNA can
    stc                               ; see it
.out:
    pop si
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_bcd2bin - AL packed BCD -> AL binary. CF=1 if either nibble is not a
; decimal digit, which is how a clock that is not running is caught: it answers
; 0xFF or 0x99 rather than failing the call.
; -----------------------------------------------------------------------------
sh_bcd2bin:
    push cx
    mov cl, al
    and cl, 0x0F
    cmp cl, 9
    ja .bad
    shr al, 1
    shr al, 1
    shr al, 1
    shr al, 1
    cmp al, 9
    ja .bad
    mov ch, al
    add al, al
    add al, al
    add al, ch                        ; al = high*5
    add al, al                        ; ...*2 = high*10
    add al, cl
    pop cx
    clc
    ret
.bad:
    pop cx
    stc
    ret

; -----------------------------------------------------------------------------
; sh_pdate - the DATE and TIME functions, ids 58 and up.
;
; NOW() IS HERE NOW, and the paragraph that used to stand in this place was
; wrong in a way worth keeping a record of. It said NOW() "cannot be written:
; no kernel call publishes the calendar date... the only clocks a package can
; read are OSAPI_GET_TICKS and OSAPI_BOOT_TICKS, both of which count since
; boot... It needs one new API slot, and that is a kernel change with its own
; review".
;
; EVERY SENTENCE ABOUT THE OSAPI TABLE IS TRUE. The conclusion does not follow,
; because the OSAPI table is not the only way out of a package. The kernel does
; not read the clock through its own API either - clk_rtc_read calls the BIOS,
; `int 0x1a` with AH=04h for the date and AH=02h for the time - and a package
; may make that identical call. MISSILE, CYCLONE and PAINT already use
; `int 0x16`; TASKMGR uses `int 0x12`. There is no rule against it and there is
; precedent for it four files away.
;
; A MISSING API IS NOT A MISSING CAPABILITY. The claim came from grepping the
; SDK for a date slot, finding none, and stopping there - and it then travelled
; into SPEC.md twice as a reason NOW() was blocked on a kernel decision. It was
; blocked on nobody having looked past os88api.inc (81.42).
;
; in: AX = the id, SI just past '('. out: AX = the value, SI past ')'.
; -----------------------------------------------------------------------------
sh_pdate:
    push bx
    push cx
    push dx
    push di
    mov di, ax
    cmp di, 58
    je .fdate
    cmp di, 63
    je .ftime
    cmp di, 67
    je .fdatevalue
    cmp di, 68
    je .ftimevalue
    ; 59..62, 64..66 all take one serial
    call sh_pcmp
    cmp di, 64
    jae .timepart
    call sh_acc_toudw                 ; the whole days
    jc .zeroout
    mov bx, ax
    cmp di, 62
    je .fweekday
    call sh_ser_to_ymd
    mov ax, [sh_dt_d]
    cmp di, 59
    je .close
    mov ax, [sh_dt_m]
    cmp di, 60
    je .close
    mov ax, [sh_dt_y]                 ; 61 YEAR
    jmp .close
.fweekday:
    mov ax, bx                        ; 1 = Sunday, which is Excel's numbering
    add ax, 6                         ; and its own serial 1 (a Sunday there)
    xor dx, dx
    mov bx, 7
    div bx
    mov ax, dx
    inc ax
    jmp .close

; ---- HOUR / MINUTE / SECOND, off the same split ----------------------------
.timepart:
    call sh_dt_hms                    ; sh_dt_min = minutes, AX = seconds
    cmp di, 66
    je .close                         ; 66 SECOND is already in AX
    mov ax, [sh_dt_min]
    xor dx, dx
    mov bx, 60
    div bx                            ; AX = hours, DX = minutes within it
    cmp di, 64
    je .close                         ; 64 HOUR
    mov ax, dx                        ; 65 MINUTE
    jmp .close

; ---- DATE(year, month, day) ------------------------------------------------
.fdate:
    call sh_parg
    mov [sh_dt_y], ax
    cmp ax, 1900                      ; a two-digit year is 19xx, as it is in
    jae .dy4                          ; Excel 2.1 - the app predates the
    cmp ax, 0                         ; question of what 00 means
    jl .zeroout
    add word [sh_dt_y], 1900
.dy4:
    cmp byte [si], ','
    jne .zeroout
    inc si
    call sh_parg
    mov [sh_dt_m], ax
    cmp byte [si], ','
    jne .zeroout
    inc si
    call sh_parg
    mov [sh_dt_d], ax
    call sh_ymd_to_ser
    jc .numerr
    call sh_acc_fromudw
    jmp .closed

; ---- TIME(hour, minute, second) --------------------------------------------
.ftime:
    call sh_parg
    mov bx, ax                        ; hours
    cmp byte [si], ','
    jne .zeroout
    inc si
    call sh_parg
    mov cx, ax                        ; minutes
    cmp byte [si], ','
    jne .zeroout
    inc si
    call sh_parg
    mov dx, ax                        ; seconds
    call sh_hms_to_acc
    jmp .closed

; ---- DATEVALUE / TIMEVALUE -------------------------------------------------
.fdatevalue:
    call sh_pstrarg
    call sh_dt_parse3                 ; BX/CX/DX = the three fields
    jc .numerr
    mov [sh_dt_y], dx
    mov ax, dx
    cmp ax, 1900
    jae .dv4
    add word [sh_dt_y], 1900
.dv4:
    mov [sh_dt_m], bx
    mov [sh_dt_d], cx
    call sh_ymd_to_ser
    jc .numerr
    call sh_acc_fromudw
    jmp .closed
.ftimevalue:
    call sh_pstrarg
    call sh_dt_parse3
    jc .numerr
    call sh_hms_to_acc                ; BX/CX/DX are already h/m/s
    jmp .closed

.numerr:
    mov byte [sh_evalerr], SH_ERR_VALUE  ; Excel's own answer for a date it
.zeroout:                                ; cannot make sense of
    xor ax, ax
.close:
    call sh_acc_int
.closed:
    mov byte [sh_curtype], SH_T_NUM
    call sh_acc_toint
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_hms_to_acc - BX/CX/DX = hours/minutes/seconds -> sh_acc as a fraction of
; a day. The three are summed as SECONDS first, in 32 bits, because
; 24 hours is 86,400 and a word stops at 65,535 - and Excel allows more than
; 24 hours in, rolling it into the day count.
; -----------------------------------------------------------------------------
sh_hms_to_acc:
    push ax
    push bx
    push cx
    push dx
    mov ax, bx                        ; hours -> seconds, in DX:AX
    mov bx, 3600
    mul bx                            ; unsigned: 24*3600 already needs 17 bits
    push dx
    push ax
    mov ax, cx
    mov bx, 60
    mul bx
    pop bx
    pop cx                            ; CX:BX = the hours' seconds
    add ax, bx
    adc dx, cx
    pop cx                            ; the ORIGINAL DX (seconds argument)
    push cx
    add ax, cx
    adc dx, 0
    mov [fp_t0], ax                   ; the whole thing as an unsigned 32-bit
    mov [fp_t1], dx
    mov word [fp_t2], 0
    mov word [fp_t3], 0
    call fp_u64_to_a
    call sh_acc_store
    call sh_dt_86400_b
    call sh_acc_load_a
    call fp_div                       ; a fraction of one day
    call sh_acc_store
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_dt_86400_b - B = 86400.0, the seconds in a day. Clobbers A.
sh_dt_86400_b:
    push ax
    mov word [fp_t0], 86400 & 0xFFFF
    mov word [fp_t1], 86400 >> 16
    mov word [fp_t2], 0
    mov word [fp_t3], 0
    call fp_u64_to_a
    call fp_a_to_b
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dt_hms - sh_acc holds a serial; out: sh_dt_min = whole minutes since
; midnight (0..1439) and AX = the seconds within that minute (0..59).
;
; NOT SECONDS-OF-DAY: 86,399 does not fit an unsigned word, so there is no
; single number to hand back. The rounding still happens in the seconds
; domain, in floating point where it fits - a time built as h/m/s is not exact
; in binary, and truncating a 10:30:00 that came back as 10:29:59.9999 would
; show 10:29:59. Minutes and seconds are then split off the rounded value, so
; the two can never disagree about which second it is.
; -----------------------------------------------------------------------------
sh_dt_hms:
    call sh_acc_load_a
    call fp_floor
    call sh_dt_tmp_store              ; the whole days
    call sh_acc_load_a
    call sh_dt_tmp_load_b
    call fp_sub                       ; A = the fraction
    call sh_acc_store
    call sh_dt_86400_b                ; clobbers A, so it goes first
    call sh_acc_load_a
    call fp_mul                       ; A = seconds, as a real
    xor cx, cx
    call fp_round                     ; ...to the nearest whole one
    call sh_acc_store                 ; sh_acc = s, a whole 0..86400
    mov ax, 60
    call fp_i2b
    call sh_acc_load_a
    call fp_div
    call fp_floor                     ; A = whole minutes, at most 1439
    call sh_dt_tmp_store
    call fp_a2i
    mov [sh_dt_min], ax
    mov ax, 60
    call fp_i2b
    call sh_dt_tmp_load_a             ; A = the minutes again
    call fp_mul                       ; A = 60 * minutes
    call sh_dt_tmp_store
    call sh_acc_load_a                ; A = s
    call sh_dt_tmp_load_b
    call fp_sub                       ; A = the leftover seconds
    call fp_a2i
    ret

; sh_dt_tmp_store / sh_dt_tmp_load_b - park fp A in bss and bring it back as
; B. sh_vpush cannot be used here: it banks on the CALLER's stack and pairs
; with exactly one sh_binop_pre (81.25.3).
sh_dt_tmp_store:
    push di
    mov di, sh_dt_tmp                 ; fp_pack_a writes at DI; fp_unpack_b
    call fp_pack_a                    ; reads at SI, and leaves A alone
    pop di
    ret
sh_dt_tmp_load_b:
    push si
    mov si, sh_dt_tmp
    call fp_unpack_b
    pop si
    ret
sh_dt_tmp_load_a:
    push si
    mov si, sh_dt_tmp
    call fp_unpack_a
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_dt_parse3 - three unsigned numbers out of sh_sacc, separated by anything
; that is not a digit. out: BX, CX, DX in the order they appear; CF=1 if
; fewer than two were found.
;
; "8/28/2026" and "10:30:00" go through the same routine because the shape is
; the same and the separator carries no meaning this needs - which is also why
; DATEVALUE here takes only the numeric forms, and not "28-Aug-2026": a month
; NAME is a different parse, and a half-supported one that quietly returned
; #VALUE! for the spelled form would be worse than a documented limit.
; -----------------------------------------------------------------------------
sh_dt_parse3:
    push si
    push di
    mov si, sh_sacc
    xor bx, bx
    xor cx, cx
    xor dx, dx
    xor di, di                        ; DI = how many fields have been read
.field:
    mov al, [si]
    or al, al
    je .done
    cmp al, '0'
    jb .skip
    cmp al, '9'
    ja .skip
    mov word [sh_dt_acc], 0           ; THE ACCUMULATOR IS IN BSS, not AX: the
.digits:                              ; digit under test needs a register half
    mov al, [si]                      ; of its own, and AH is where the running
    cmp al, '0'                       ; total's high byte lives
    jb .store
    cmp al, '9'
    ja .store
    sub al, '0'
    xor ah, ah
    push ax
    push dx
    mov ax, [sh_dt_acc]
    mov dx, 10
    mul dx                            ; unsigned: a year is four digits
    mov [sh_dt_acc], ax
    pop dx
    pop ax
    add [sh_dt_acc], ax
    inc si
    jmp .digits
.store:
    mov ax, [sh_dt_acc]
    or di, di
    jnz .st1
    mov bx, ax
    jmp .stnext
.st1:
    cmp di, 1
    jne .st2
    mov cx, ax
    jmp .stnext
.st2:
    cmp di, 2
    jne .stnext
    mov dx, ax
.stnext:
    inc di
    cmp di, 3
    jae .done
    jmp .field
.skip:
    inc si
    jmp .field
.done:
    cmp di, 2
    jb .bad
    clc
    jmp .out
.bad:
    stc
.out:
    pop di
    pop si
    ret

; sh_pif - IF(cond,then,else): the one function that does not fold - its
; branches are not even both evaluated the way a real spreadsheet expects
; only ONE side effect-free path to matter, but here both sides just get
; parsed unconditionally (the parse is what advances SI) and the condition
; alone picks which value survives. Parsing IS evaluation here, and it has
; one side effect since errors landed: a raise of the sticky sh_evalerr - so
; the raise of the branch the condition did NOT pick is banked and unraised
; (81.20), or =IF(B1=0,0,A1/B1) answered #DIV/0! for the case it guards.
; in: SI right after "IF("; out: AX=result, SI advanced past ')' if found
sh_pif:
    push bx
    push cx
    call sh_pcmp                      ; the condition, kept as a truth value
    call sh_acc_iszero                ; rather than as a number
    mov bx, 0
    jc .condfalse
    mov bx, 1
.condfalse:
    cmp byte [si], ','
    jne .bad
    inc si
    mov al, [sh_evalerr]              ; banked across the then-parse, and
    mov ah, [sh_macro_exec]           ; restored if then was NOT chosen - and
    push ax                           ; the branch the condition did NOT pick
    or bx, bx                         ; runs no MACRO command (81.63): parsed,
    jnz .thenrun                      ; as it has to be, but inert - or
    mov byte [sh_macro_exec], 0       ; IF(H7=3,BREAK()) broke at 1
.thenrun:
    call sh_pcmp                      ; the then-value, banked whole
    pop ax
    mov [sh_macro_exec], ah
    or bx, bx
    jnz .thenkept
    mov [sh_evalerr], al
.thenkept:
    call sh_vpush                     ; the then-VALUE...
    mov al, [sh_curtype]              ; ...AND WHAT KIND OF VALUE IT IS, which
    mov ah, [sh_curaux]               ; sh_vpush does not carry. Without this
    push ax                           ; the else-parse left ITS type behind, and
    cmp al, SH_T_TEXT                 ; a TEXT then-value's characters are not
    jne .nottext                      ; in sh_acc at all but in sh_sacc, which
    call sh_spush                     ; the else-parse overwrites: so
.nottext:                             ; =IF(A1>1,"big","small") answered
    cmp byte [si], ','                ; "small" for every A1 (81.10.10 found
    jne .badpop                       ; it). Banked on the string stack, the
    inc si                            ; way & banks its left operand
    mov al, [sh_evalerr]              ; ...and the same for the else-parse
    mov ah, [sh_macro_exec]
    push ax
    or bx, bx
    jz .elserun
    mov byte [sh_macro_exec], 0
.elserun:
    call sh_pcmp                      ; the else-value, left in sh_acc
    pop ax
    mov [sh_macro_exec], ah
    or bx, bx
    jz .elsekept
    mov [sh_evalerr], al
.elsekept:
    pop cx                            ; CL/CH: the then-value's type and aux
    or bx, bx
    jz .dropthen                      ; false: sh_acc already holds the else
    mov [sh_curtype], cl              ; true: the then-value back WHOLE - its
    mov [sh_curaux], ch               ; kind, and its eight bytes restored as
    pop word [sh_acc]                 ; they were banked rather than through
    pop word [sh_acc+2]               ; the float layer, which a TEXT result's
    pop word [sh_acc+4]               ; slot reference (81.22.1) is not a
    pop word [sh_acc+6]               ; double to survive
    cmp cl, SH_T_TEXT
    jne .out
    call sh_srestore                  ; ...and its characters
    jmp .out
.dropthen:
    add sp, 8                         ; the banked then-value is not wanted,
    cmp cl, SH_T_TEXT                 ; and nor are its characters: a bank
    jne .out                          ; left on the string stack would shift
    call sh_spop                      ; every string after it by one
    jmp .out
.badpop:
    add sp, 10                        ; the banked value, and its type...
    cmp al, SH_T_TEXT                 ; (AL still is: nothing since has
    jne .bad                          ; touched it)
    call sh_spop                      ; ...and any characters
.bad:
    xor ax, ax
    call sh_acc_int
.out:
    cmp byte [si], ')'
    jne .noclose
    inc si
.noclose:
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_pchoose - CHOOSE(index, v1, v2, ...) (SPEC.md 81.49)
; in: SI right after "CHOOSE("; out: the chosen value WHOLE - sh_acc,
; sh_curtype, and sh_sacc when it is text - and SI past ')'. AX is its
; truncation, for the callers that still want a word.
;
; IT WAS AN INTEGER FUNCTION: parsed in sh_pspecial beside MOD and FACT, every
; value taken through sh_parg as a word and the answer handed back through
; sh_acc_int. So =CHOOSE(2,1.5,2.5) answered 2, any fractional cell it picked
; lost its fraction, and a text value came back 0. Excel's CHOOSE returns the
; value it picked, whatever it is.
;
; THE CHOSEN VALUE IS NOT BANKED, because nothing is parsed after it: the
; values before it are parsed and dropped (their raise of the sticky error
; does not stand - 81.20), the chosen one is parsed and left where the parser
; put it, and the rest are STEPPED OVER by sh_skipargs, never evaluated -
; which is also Excel's behaviour, and why a #DIV/0! in an unchosen argument
; after the chosen one never mattered. An index outside 1..n is #VALUE!.
; -----------------------------------------------------------------------------
sh_pchoose:
    push bx
    push cx
    call sh_parg                      ; the 1-based index, truncated as Excel
    mov bx, ax                        ; truncates it
    xor cx, cx
.next:
    cmp byte [si], ','
    jne .short                        ; the list ran out first
    inc si
    inc cx
    cmp cx, bx
    je .chosen
    mov al, [sh_evalerr]              ; banked across an unchosen value, and
    mov ah, [sh_macro_exec]           ; put back after it - which runs no
    push ax                           ; macro command, as IF's does not (81.63)
    mov byte [sh_macro_exec], 0
    call sh_pcmp
    pop ax
    mov [sh_evalerr], al
    mov [sh_macro_exec], ah
    jmp .next
.chosen:
    call sh_pcmp                      ; its value, its type, its text - and its
    call sh_skipargs                  ; raise stands. The rest are stepped over
    xor ax, ax                        ; to the matching ')', and SI past it
    cmp byte [sh_curtype], SH_T_NUM
    jne .out
    call sh_acc_toint
    jmp .out
.short:
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    call sh_acc_int
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    pop cx
    pop bx
    ret

; sh_pnot - NOT(x): logical negation
; in: SI right after "NOT("; out: AX=1 or 0, SI advanced past ')' if found
sh_pnot:
    call sh_pcmp
    call sh_acc_iszero
    jc .true
    xor ax, ax
    call sh_acc_int
    jmp .close
.true:
    mov ax, 1
    call sh_acc_int
.close:
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    ret

; sh_pabs - ABS(x): absolute value
; in: SI right after "ABS("; out: AX=|x|, SI advanced past ')' if found
sh_pabs:
    call sh_pcmp
    and byte [sh_acc+7], 0x7F         ; clear the sign bit: |x| for a packed
.close:                               ; double is one AND, and it is exact
    cmp byte [si], ')'
    jne .out
    inc si
.out:
    ret

; =============================================================================
; MACROS, the package's half (SPEC.md 81.63): the Run dialog, the door, and
; the two ways a paused run comes back. The engine and every macro function
; are CHART.OVL's - the module's own header, at shm_pmacro, is the design.
; =============================================================================
SH_MACRO_MAXSTEPS equ 10000          ; a runaway loop ENDS rather than hangs:
                                     ; the system is cooperative and the step
                                     ; loop yields to nothing (81.8). It was
                                     ; 5000, before a macro could loop
SH_FID_MACRO   equ 111               ; the first macro function's id...
SH_FID_DATABASE equ 131              ; the first DATABASE function's id
                                     ; (81.65) - one past the last macro
                                     ; command (111 + 20)
SH_FID_CELL     equ 142              ; CELL's id (81.66) - one past the last
                                     ; DATABASE function (131 + 11)
SH_FID_MDETERM  equ 143              ; the first ARRAY/MATRIX function's id
                                     ; (81.67) - one past CELL
SH_FID_MINVERSE equ 144
SH_FID_MMULT    equ 145
SH_FID_TRANSPOSE equ 146
SH_FID_LINEST   equ 147
SH_FID_LOGEST   equ 148
SH_FID_TREND    equ 149
SH_FID_GROWTH   equ 150
SH_MF_ACTCELL  equ 14                ; ...and ACTIVE.CELL's, counted from it
; SHEET-MACRO-PLAN wave 0: EXTENSION macro functions. The twenty above stay in
; the resident sh_functab at SH_FID_MACRO.. - moving them would renumber the
; twenty database/CELL/matrix ids after them for ~300 bytes - and every new
; one lives in CHART.OVL instead, NAME AND ALL, with a WORD id from 0x100.
; The evaluator's ids were always words (sh_pfid); only sh_funcid's AL return
; is a byte, which is why an extension name is found by a second lookup and
; never by sh_funcid itself - its byte callers (bare TRUE/FALSE) cannot see
; one and so cannot misread one. APP_MAX_SIZE left 2,475 resident bytes, and
; 117 names at the twenty's price would have spent all of them.
SH_FID_MX      equ 0x100              ; the first extension id
SH_MF_N        equ 20                 ; the resident twenty, counted in shm_mtab
SH_FID_MCALL   equ SH_FID_MX + 0      ; the subroutine CALL - extension 0, with
                                     ; a name no formula can spell (below)
SH_MSUBS       equ 4                  ; subroutine frames, nested
SH_MARGS       equ 14                 ; arguments to one call - Excel's limit
SH_MSLOTS      equ 24                 ; argument values, all frames at once
SH_MPOOL       equ 384                ; ...and their text
SH_MBINDS      equ 16                 ; ARGUMENT's names, all frames at once
SH_MVAL        equ 12                 ; a banked value: type, err, aux, acc
SH_MFRAME      equ 12                 ; a frame (shm_cpush has the layout)
SH_MBREC       equ 14                 ; a binding: the name (13), its slot
SH_MC_NONE     equ 0                 ; what a step asked for (sh_macro_ctl):
SH_MC_GOTO     equ 1                 ; the next cell is [sh_macro_ncol/nrow]
SH_MC_STOP     equ 2                 ; RETURN, HALT, or a macro error
SH_MC_PAUSEN   equ 3                 ; ALERT: wait, then the next cell
SH_MC_PAUSEH   equ 4                 ; INPUT: wait, then THIS cell again
SH_MC_SKIP     equ 5                 ; on past the NEXT of the loop at ncol/nrow
SH_MC_RET      equ 7                 ; ...RETURN from one: pop it, and evaluate
                                     ; the CALLING cell again for its answer
SH_MW_START    equ 1                 ; what a resume means (sh_macro_wait)
SH_MW_ALERT    equ 2
SH_MW_INPUT    equ 3
SH_MW_WAIT     equ 4                 ; 81.86: WAIT's timer
SH_MW_STEP     equ 5                 ; ...and the Single Step dialog
SH_MW_ONTIME   equ 6                 ; 81.92: ON.TIME's look at the clock
SH_MW_DBOX     equ 7                 ; 81.96: DIALOG.BOX's own window
SH_MKEYS       equ 4                 ; ON.KEY's bindings (81.92)...
SH_MKREC       equ 6                 ; ...each the key word, then the col and
                                      ; row to run (col 0xFFFF: swallow it)
SH_MC_WAITT    equ 8                 ; WAIT: arm nothing more, return, and let
                                      ; the timer bring the run back
SH_MLOOPS      equ 4                 ; FOR/WHILE frames, nested
SH_LF_KIND     equ 0                 ; a frame: 1 FOR / 2 WHILE,
SH_LF_COL      equ 1                 ; its own cell,
SH_LF_ROW      equ 3
SH_LF_CCOL     equ 5                 ; FOR's counter cell,
SH_LF_CROW     equ 7
SH_LF_END      equ 9                 ; its end and step, doubles
SH_LF_STEP     equ 17
SH_LF_SZ       equ 25
SH_MPROMPT     equ 30                ; INPUT's prompt, as the dialog shows it
SH_MSTMSG      equ 40                ; MESSAGE's text on the status bar
sh_s_macrolimit: db 'Err: macro step limit', 0
sh_s_macrodone:  db 'Macro done', 0
sh_s_macroerr:   db 'Err: macro', 0
sh_s_macronext:  db 'Err: FOR or WHILE with no NEXT', 0
sh_s_macrobusy:  db 'A macro is running', 0
sh_s_mdeep:      db 'Err: subroutines nested too deep', 0
sh_s_mtwice:     db 'Err: one subroutine call to a cell', 0
sh_s_mfull:      db 'Err: too many subroutine arguments', 0
sh_s_marg:       db 'Err: ARGUMENT outside a subroutine', 0

; sh_macro_run - Macro > Run...: WHERE to start, a reference or a defined
; name, as Excel's Run dialog asks. It started at the selected cell because
; there was no text field to ask with (81.8); stage 3.0c made one
sh_macro_run:
    cmp byte [sh_macro_running], 0
    jne .busy
    push ax
    mov al, SH_ID_RUN
    call sh_idlg_open_r
    pop ax
    ret
.busy:
    mov word [sh_msg], sh_s_macrobusy
    jmp sh_drawstatus

; sh_macro_onalert - os88ui_ask's completion proc (SPEC.md 75.3), and the
; way every paused run carries on: the module, verb SHM_MRESUME
sh_macro_onalert:
    push bp
    mov bp, SHM2_MRESUME
    call sh_m2call
    pop bp
    jnc .out
    mov byte [sh_macro_running], 0    ; no module: no macro
    mov word [sh_msg], sh_s_noovl
    call sh_drawstatus
.out:
    ret

; sh_idlg_after - the one-line dialog has CLOSED: a Run's OK starts the run,
; an INPUT - answered or cancelled - lets it carry on. After and not inside
; the apply, because the run may open this same dialog again
sh_idlg_after:
    cmp byte [sh_tbl_pend], 0          ; 81.114: Data > Table's second field
    je .notbl
    mov byte [sh_tbl_pend], 0
    mov al, SH_ID_TBLCOL
    jmp sh_idlg_open_r
.notbl:
    cmp byte [sh_idlg_kind], SH_ID_RUN
    jb .out
    cmp byte [sh_macro_wait], 0
    je .out
    jmp sh_macro_onalert
.out:
    ret

; The module's hands on the package (each through a vector)
sh_macro_alertup:
    push ax
    push bx
    push si
    push di
    mov al, [sh_macro_aset]           ; 81.86: the module picks the buttons
    mov bx, [sh_ownwin]
    mov si, sh_macro_msg
    mov di, sh_macro_onbtn
    call os88ui_ask
    pop di
    pop si
    pop bx
    pop ax
    ret
sh_macro_mfire:                      ; 81.88: AH = menu, AL = item - the
    call sh_mfire                    ; command equivalents' own door, the
    mov byte [sh_macro_dirty], 1     ; one a click goes through
    ret
sh_macro_onbtn:                      ; ...and hears which one: AL, 0-based,
    mov [sh_macro_btn], al           ; or OS88UI_ACANCEL
    jmp sh_macro_onalert

; sh_macro_arm - arm WAIT's timer: AX = ticks. CF=1 there is no timer on
; this kernel (kern_small). RESIDENT, and it has to be: OSAPI_WM_ONTIMER takes
; a near proc in the CALLER's segment, and a call from CHART.OVL names the
; module's - the timer then fires into the module at a package offset
sh_macro_arm:
    push ax
    push bx
    mov bx, [sh_ownwin]
    push ax
    mov ax, sh_macro_ontimer
    call OSAPI_WM_ONTIMER
    pop ax
    jc .out
    call OSAPI_WM_TIMER
.out:
    pop bx
    pop ax
    ret

; sh_macro_ontimer - WAIT's timer (81.86): a paused run looks at the clock
; again. W_ONCLICK's environment, so it resumes exactly as an alert does
sh_macro_ontimer:
    cmp byte [sh_macro_wait], SH_MW_WAIT
    je .go
    cmp byte [sh_macro_wait], SH_MW_DBOX ; 81.96: DIALOG.BOX's window, and
    jne .notdbox                      ; its close box asked (sh_dbx_close_r):
    cmp byte [sh_dbx_cls], 0          ; destroy it HERE, where no kernel
    je .notdbox                       ; close is half done, and answer Cancel
    mov byte [sh_dbx_cls], 0
    push bx
    mov bx, [sh_dbx_win]
    mov word [sh_dbx_win], 0
    or bx, bx
    jz .nodbw
    call OSAPI_WM_DESTROY
.nodbw:
    pop bx
    jmp .go
.notdbox:
    cmp byte [sh_macro_ontp], 0       ; 81.92: ON.TIME has a request - and a
    je .out                           ; run that is going, paused on a
    cmp byte [sh_macro_running], 0    ; dialog, makes it wait its turn
    jne .later
    cmp byte [sh_mopen], SH_M_NONE    ; ...and so does an OPEN MENU (81.95.3):
    jne .later                        ; sh_mtrack yields, and a run started
                                       ; here could delete the very menu whose
                                       ; dropdown is on the glass
    mov byte [sh_macro_wait], SH_MW_ONTIME
.go:
    jmp sh_macro_onalert
.later:
    push ax
    mov ax, 18
    call sh_macro_arm
    pop ax
.out:
    ret

;
; DIALOG.BOX's window (81.96). The module draws it, reads its keys and its
; clicks; what stays here is what the kernel calls or names - the template,
; the three thunks, the close negotiator - and the CREATE, because
; OSAPI_WM_ONCLOSE takes a near proc in the CALLER's segment
sh_dbx_tpl:
    dw 0, 0, 0, 0
    dw sh_macro_msg, sh_dbx_paint_r, sh_dbx_key_r, sh_dbx_click_r

; 81.111: its buttons are ITEMS among other controls rather than a group, so
; they take two one-button records. The PAINT record is staged per item by
; shm_dbdraw straight out of sh_tbuf; the GESTURE record is staged only by a
; press (shm_dbgrab) and no repaint touches it, so the release is judged
; against the button the press armed. Its label is a copy of its own, since
; the library redraws it on the drag and the release
    OS88UI_BTNREC sh_dbx_prec, sh_tbuf, sh_dbx_plab, sh_dbx_pflg, 1
sh_dbx_plab:  dw sh_tbuf + 8
sh_dbx_pflg:  dw 0
    OS88UI_BTNREC sh_dbx_btrec, sh_dbx_btrects, sh_dbx_glab, sh_dbx_gflg, 1
sh_dbx_btrects: times 4 dw 0
sh_dbx_glab:  dw sh_dbx_gtxt
sh_dbx_gflg:  dw 0
sh_dbx_gitem: db 0xFF                 ; the item staged there, 0xFF = none
sh_dbx_grab:  db 0                    ; the module staged one: arm it
sh_dbx_gtxt:  times 24 db 0           ; SHM_DBTXT, asserted beside it

sh_dbx_onup_r:
    push ax
    push bx
    mov bx, sh_dbx_btrec
    call os88ui_btnup                 ; AX = what FIRED, 0 = cancelled
    or ax, ax
    pop bx
    pop ax
    jz .out
    push bp
    mov bp, SHM2_DFIRE
    jmp sh_dbx_ev
.out:
    ret
sh_dbx_ondrag_r:
    push bx
    mov bx, sh_dbx_btrec
    call os88ui_btndrag
    pop bx
    ret

; sh_dbx_open - in: CX = width, DX = height; out: CF=1 not made
sh_dbx_open:
    push ax
    push bx
    push si
    mov [sh_dbx_tpl + WT_W], cx
    mov [sh_dbx_tpl + WT_H], dx
    mov byte [sh_dbx_done], 0
    mov byte [sh_dbx_cls], 0          ; nothing owed from the LAST dialog
    call OSAPI_VIDEO                  ; centred, below the menu bar - and it
    sub ax, [sh_dbx_tpl + WT_W]       ; answers the size in AX/BX while
    sar ax, 1                         ; CLOBBERING CX and DX (the dock row,
    jns .x                            ; the adapter), so the size is read
    xor ax, ax                        ; back from the template and not from
.x:                                   ; the registers it came in
    mov [sh_dbx_tpl + WT_X], ax
    sub bx, [sh_dbx_tpl + WT_H]
    sar bx, 1
    cmp bx, MBAR_H + 8
    jge .y
    mov bx, MBAR_H + 8
.y:
    mov [sh_dbx_tpl + WT_Y], bx
    mov si, sh_dbx_tpl
    call OSAPI_WM_CREATE
    jc .out
    mov [sh_dbx_win], bx
    mov ax, sh_dbx_close_r
    call OSAPI_WM_ONCLOSE
    call OSAPI_WM_SHOW
    push dx
    push di
    mov ax, bx
    mov bx, sh_dbx_btrec
    mov si, sh_dbx_onup_r
    mov di, sh_dbx_ondrag_r
    mov dx, sh_dbx_click_r
    call sh_btattach
    mov byte [sh_dbx_gitem], 0xFF     ; nothing staged from the LAST dialog
    mov word [sh_dbx_btrects + 4], -1 ; ...and a rect no point is inside
    pop di
    pop dx
    clc
.out:
    pop si
    pop bx
    pop ax
    ret

sh_dbx_paint_r:                       ; SI = the window, the gfx lock held
    push bp
    mov bp, SHM2_DPAINT
    call sh_m2call
    pop bp
    ret
sh_dbx_key_r:                         ; AL = ascii, AH = scan
    push bp
    mov bp, SHM2_DKEY
    jmp short sh_dbx_ev
sh_dbx_click_r:                       ; CX,DX = the click
    push bp
    mov bp, SHM2_DCLICK
sh_dbx_ev:
    call sh_m2call
    pop bp
    cmp byte [sh_dbx_grab], 0         ; a button the gesture record was not
    je .nograb                        ; staged at: the module has staged it,
    mov byte [sh_dbx_grab], 0         ; so the press is armed on it now
    push ax
    push bx
    mov bx, sh_dbx_btrec
    call os88ui_btnpress
    pop bx
    pop ax
.nograb:
    cmp byte [sh_dbx_done], 0         ; a button: the window goes, and the
    je .out                           ; run carries on - INPUT's order
    mov byte [sh_dbx_done], 0
    push bx
    mov bx, [sh_dbx_win]
    mov word [sh_dbx_win], 0
    call OSAPI_WM_DESTROY
    pop bx
    jmp sh_macro_onalert
.out:
    ret

; sh_dbx_close_r - the close box (SPEC.md 75.1). It REFUSES the close and
; takes it on the next tick instead, which is the only way to end up calling
; OSAPI_WM_DESTROY: a package's secondary window has no owner record, so the
; kernel's own close merely HIDES it and the slot is never free again (81.6,
; and 81.96.2 is this one). Refusing owes the user a way out, and the tick is
; it - a run resumed from in here could open the next DIALOG.BOX while this
; window is still half closed
sh_dbx_close_r:
    cmp byte [sh_macro_wait], SH_MW_DBOX
    jne .let                          ; not a paused run's: not ours to keep
    push ax
    mov byte [sh_dbx_cls], 1
    mov ax, 1
    call sh_macro_arm                 ; CF=1: no timer on this kernel, and
    pop ax                            ; then a refusal would strand the run
    jc .let
    stc
    ret
.let:
    mov word [sh_dbx_win], 0
    clc
    ret

; sh_macro_keyck - ON.KEY (81.92): AX (AL the character, AH the scan) bound?
; CF=1 it was - a run started, or the key swallowed - and nothing else of
; the sheet's sees it. Only while no run is going: sh_macro_gatek has taken
; every key before this during one
sh_macro_keyck:
    push bx
    push cx
    mov bx, sh_macro_keys
    mov cx, SH_MKEYS
.l:
    cmp word [bx], 0
    je .next
    cmp byte [bx+1], 0                ; a character: AL
    jne .scan
    cmp al, [bx]
    je .hit
    jmp short .next
.scan:                                ; a function key: AH, and no character
    or al, al
    jnz .next
    cmp ah, [bx+1]
    je .hit
.next:
    add bx, SH_MKREC
    loop .l
    pop cx
    pop bx
    clc
    ret
.hit:
    mov cx, [bx+2]
    cmp cx, 0xFFFF                    ; "": the key does nothing
    je .eat
    mov [sh_macro_col], cx
    mov cx, [bx+4]
    mov [sh_macro_row], cx
    mov byte [sh_macro_wait], SH_MW_START
    call sh_macro_onalert
.eat:
    pop cx
    pop bx
    stc
    ret

; sh_macro_gatek / sh_macro_gate - CF=1: a paused macro swallows this key
; (AH = its scancode) or click. A run's dialogs are MODAL to the sheet, as
; Excel's are: the key or click is not the sheet's, and the dialog comes back
; to the front - a run left waiting on a dialog nobody can see is a run
; nobody can finish. ONE CLICK LATE, and not by choice: a click on the sheet
; while the dialog is in front only RAISES the sheet - the kernel calls no
; W_ONCLICK for a background window (ui.inc's content path) - so that click
; buries the dialog and the NEXT one, on the now-front sheet, arrives here
; (81.86.4). While WAIT is waiting, Esc is CANCEL.KEY's key and cuts the
; wait short, and nothing else reaches the sheet
sh_macro_gatek:
    cmp byte [sh_macro_running], 0
    je sh_macro_gate.pass
    cmp byte [sh_macro_wait], SH_MW_WAIT
    jne sh_macro_gate.front
    cmp ah, KSC_ESC
    jne sh_macro_gate.eat
    push ax
    push bx
    mov byte [sh_macro_esc], 1
    mov bx, [sh_ownwin]
    xor ax, ax                        ; the timer is cancelled...
    call OSAPI_WM_TIMER
    pop bx
    pop ax
    call sh_macro_onalert             ; ...and the run looks now
    stc
    ret
sh_macro_gate:
    cmp byte [sh_macro_running], 0
    je .pass
    cmp byte [sh_macro_wait], SH_MW_WAIT
    je .eat
.front:
    push bx
    mov bx, [os88ui_awin]             ; ALERT's or the Single Step dialog
    or bx, bx
    jnz .raise
    mov bx, [sh_idlg_win]             ; ...or INPUT's
    or bx, bx
    jnz .raise
    mov bx, [sh_dbx_win]              ; ...or DIALOG.BOX's (81.96)
    or bx, bx
    jz .none
.raise:
    call OSAPI_WM_FRONT
    pop bx
.eat:
    stc
    ret
.none:
    pop bx
.pass:
    clc
    ret
sh_macro_inputup:                    ; CF=1: no dialog came up, because
    cmp word [sh_idlg_win], 0        ; sh_idlg_open refuses in silence - one
    jne .none                        ; of its own is up, or the create failed
    push ax
    mov al, SH_ID_INPUT
    call sh_idlg_open_r
    pop ax
    jc .none
    cmp word [sh_idlg_win], 0
    je .none
    clc
    ret
.none:
    stc
    ret
sh_macro_beep:                       ; BEEP: 880 Hz for three ticks
    push ax
    push cx
    push dx
    mov ax, 880
    mov cx, 3
    mov dl, 0x40
    call OSAPI_SND_TONE
    pop dx
    pop cx
    pop ax
    ret
sh_macro_cmd:                        ; AX = sh_docmd_copy/cut/paste, SI =
    mov byte [sh_ps_mode], SH_PS_ALL ; the window: PASTE is the plain one
    call ax
    ret
sh_macro_clear:                      ; AX = Edit > Clear's row, SI = the
    mov byte [sh_fdlg_kind], SH_FDK_CLEAR ; window
    mov [sh_fdlg_sel], ax
    call sh_fdlg_apply_r               ; 81.74.2: that engine is the module's
    ret                                ; now, so this is a door and not a jump

; =============================================================================
; THE MACRO LANGUAGE (SPEC.md 81.63). A macro is a column of formulas on the
; sheet, run from a start cell - a reference or a defined name - that Macro >
; Run... asks for, as Excel's Run dialog does. Each cell is evaluated with the
; whole formula grammar, top to bottom, until RETURN or HALT, an empty cell,
; or SH_MACRO_MAXSTEPS.
;
; EXCEL'S MODEL, AND THE ONE THING IT NEEDS HERE: macro functions are
; FUNCTIONS, and they act when evaluated - so =IF(A5>10,GOTO(B20)) branches
; and =SET.VALUE(B1,B1+1) counts - but ONLY when the step engine is evaluating
; the current macro cell, at its own evaluation depth (sh_macro_exec,
; sh_macro_exdep). A repaint evaluates every visible formula, macro cells
; included, and must not run them; neither may a worksheet formula that names
; one. There a command does nothing and answers FALSE. ACTIVE.CELL, the one
; value function, answers anywhere.
;
; It was five keywords, each recognised only as the WHOLE of a cell (81.8),
; so no macro could decide anything, loop, or ask the user a question.
;
;   GOTO(ref)  RETURN()  HALT()           control
;   FOR(counter,start,end[,step])  WHILE(test)  NEXT()  BREAK()
;   SELECT(ref)  FORMULA(x[,ref])  SET.VALUE(ref,x)   the sheet
;   ALERT(text)  INPUT(prompt)  MESSAGE(show[,text])  BEEP()   the user
;   COPY()  CUT()  PASTE()  CLEAR([1..4])  CALCULATE.NOW()   the commands
;   ACTIVE.CELL()                         the selected cell's value
;
; A REFERENCE argument is a reference, a defined name, or TEXT: "B5", or
; "R[1]C" relative to the active cell - the form Excel's recorder writes, and
; the way a macro walks down a column without OFFSET. A FOR counter is a cell
; (or a name for one), where Excel's is a name that holds a value: this sheet's
; names are places, so the counter lives in the cell the name points at.
;
; SELECT repaints; SET.VALUE and FORMULA do not, and the grid catches up at
; the next SELECT, ALERT, INPUT or the end - every change repainted at once is
; seconds a step on the target. ALERT and INPUT PAUSE the run: the engine
; raises the dialog after the step and returns, and the dialog's completion
; resumes it (sh_macro_onalert, sh_idlg_after) - the next cell for ALERT, the
; SAME cell for INPUT, whose second evaluation answers what was typed.
;
; The engine and every macro function are CHART.OVL's (82.16): the package
; keeps the names, the door (sh_pmacro), the Run dialog and the resumptions.
; =============================================================================
section SH_MODSEC2                     ; 81.63 - MACRO.OVL since 81.94

; shm_pmacro - the macro functions, ids SH_FID_MACRO and up. in: AX = the id,
; SI just past '('. out: SI past ')', the answer in sh_acc/sh_curtype, AX 0
shm_pmacro:
    push bx
    push cx
    push dx
    push di
    cmp ax, SH_FID_MX                 ; wave 0: an EXTENSION id indexes the
    jb .res                           ; same tables, after the resident twenty
    sub ax, SH_FID_MX - SH_MF_N
    jmp short .idx
.res:
    sub ax, SH_FID_MACRO
.idx:
    mov di, ax
    cmp byte [cs:di + shm_mkind], 0   ; a VALUE function answers anywhere -
    jne .act                          ; ACTIVE.CELL was the only one, and a
                                       ; single `cmp di, SH_MF_ACTCELL` stood
                                       ; for the whole rule. REFTEXT, OFFSET and
                                       ; the GET family are the same kind
    cmp byte [sh_macro_exec], 0       ; ...a command only for the step engine,
    je .inert                         ; at its own depth: not for a repaint,
    mov ax, [sh_evaldepth]            ; not for a worksheet formula
    cmp ax, [sh_macro_exdep]
    jne .inert
.act:
    shl di, 1
    push si                           ; wave 1b: where its arguments start
    mov byte [cs:shm_rrnew], 0
    call word [cs:di + shm_mtab]      ; CS: the table is the module's own
    pop dx
    cmp byte [cs:shm_rrnew], 0        ; it answered a REFERENCE: say which
    je .out                           ; call it was, by where its text is
    mov byte [cs:shm_rrnew], 0        ; (shm_refarg)
    mov [cs:shm_rrin], dx
    mov [cs:shm_rrout], si
    mov byte [cs:shm_rrok], 1
    jmp short .out
.inert:
    SHOUT sh_skipargs
    call shm_mfalse
.out:
    xor ax, ax
    pop di
    pop dx
    pop cx
    pop bx
    ret

shm_mtab:
    dw shm_mgoto, shm_mreturn, shm_mhalt, shm_msetval, shm_mselect
    dw shm_mformula, shm_malert, shm_mmessage, shm_mbeep, shm_minput
    dw shm_mfor, shm_mwhile, shm_mnext, shm_mbreak, shm_mactcell
    dw shm_mcopy, shm_mcut, shm_mpaste, shm_mclear, shm_mcalc
    dw shm_mcall, shm_margument, shm_mresult          ; wave 1a
    dw shm_moffset, shm_mabsref, shm_mrelref, shm_mreftext ; wave 1b
    dw shm_mtextref, shm_mderef, shm_mselection, shm_mcaller
    dw shm_mecho, shm_merror, shm_mrestart, shm_mstepfn       ; wave 2
    dw shm_mcancelkey, shm_mdisinput, shm_mwait
    dw shm_mgetcell, shm_mgetformula, shm_mgetname, shm_mgetdef ; wave 2:
    dw shm_mgetnote, shm_mnames, shm_mgetdoc, shm_mgetwin       ; information
    dw shm_mgetws, shm_mdirectory
; wave 3a (81.88): command equivalents - Format, Edit, Options
    dw shm_x_fillr
    dw shm_x_filld
    dw shm_x_plink
    dw shm_x_undo
    dw shm_x_just
    dw shm_x_save
