    db 0

; Per extension function: its BIFF index, 1 if variable-arity, 1 if it is a
; Cetab COMMAND (ptg 0x58) rather than an Ftab function (81.83.2).
shm_mxrpn:
    db 0xFF, 1, 0                     ; the CALL: no BIFF form yet (wave 5)
    db 0x51, 1, 0                     ; ARGUMENT(name[,type[,ref]]) - Ftab
    db 0x60, 1, 0                     ; RESULT([type]) - Ftab
    db 0x4E, 1, 0                     ; OFFSET(ref,rows,cols[,h[,w]])
    db 0x4F, 0, 0                     ; ABSREF(ref_text,ref)
    db 0x50, 0, 0                     ; RELREF(ref,rel_to_ref)
    db 0x92, 1, 0                     ; REFTEXT(ref[,a1])
    db 0x93, 1, 0                     ; TEXTREF(text[,a1])
    db 0x5A, 0, 0                     ; DEREF(ref)
    db 0x5F, 0, 0                     ; SELECTION()
    db 0x59, 0, 0                     ; CALLER()
    db 0x57, 1, 0                     ; ECHO([logical])
    db 0x54, 1, 0                     ; ERROR([enable[,ref]])
    db 0xB4, 1, 0                     ; RESTART([level])
    db 0x55, 0, 0                     ; STEP()
    db 0xAA, 1, 0                     ; CANCEL.KEY([enable[,ref]])
    db 0x8C, 0, 1                     ; DISABLE.INPUT(logical) - Cetab
    db 0x95, 0, 1                     ; WAIT(serial) - Cetab
    db 0xB9, 1, 0                     ; GET.CELL(type[,ref])
    db 0x6A, 0, 0                     ; GET.FORMULA(ref)
    db 0x6B, 1, 0                     ; GET.NAME(name_text[,info])
    db 0x91, 1, 0                     ; GET.DEF(def_text[,doc])
    db 0xBF, 1, 0                     ; GET.NOTE(ref[,start[,count]])
    db 0x7A, 1, 0                     ; NAMES([doc])
    db 0xBC, 1, 0                     ; GET.DOCUMENT(type[,name])
    db 0xBB, 1, 0                     ; GET.WINDOW(type[,name])
    db 0xBA, 0, 0                     ; GET.WORKSPACE(type)
    db 0x7B, 1, 0                     ; DIRECTORY([path])
    db 0x38, 0, 1                     ; FILL.RIGHT - Cetab
    db 0x39, 0, 1                     ; FILL.DOWN - Cetab
    db 0x7C, 0, 1                     ; PASTE.LINK - Cetab
    db 0x30, 0, 1                     ; UNDO - Cetab
    db 0x5C, 0, 1                     ; JUSTIFY - Cetab
    db 0x04, 0, 1                     ; SAVE - Cetab
    db 0x25, 0, 1                     ; SET.DATABASE - Cetab
    db 0x26, 0, 1                     ; SET.CRITERIA - Cetab
    db 0xA7, 0, 1                     ; CALCULATE.DOCUMENT - Cetab
    db 0x92, 0, 1                     ; DATA.FORM - Cetab
    db 0x2B, 1, 1                     ; ALIGNMENT - Cetab
    db 0x96, 1, 1                     ; FORMAT.FONT - Cetab
    db 0x2A, 0, 1                     ; FORMAT.NUMBER - Cetab
    db 0x2D, 1, 1                     ; BORDER - Cetab
    db 0x2E, 1, 1                     ; CELL.PROTECTION - Cetab
    db 0x2F, 1, 1                     ; COLUMN.WIDTH - Cetab
    db 0x7F, 1, 1                     ; ROW.HEIGHT - Cetab
    db 0x37, 1, 1                     ; INSERT - Cetab
    db 0x36, 1, 1                     ; EDIT.DELETE - Cetab
    db 0x35, 1, 1                     ; PASTE.SPECIAL - Cetab
    db 0x78, 0, 1                     ; CANCEL.COPY - Cetab
    db 0x20, 1, 1                     ; CALCULATION - Cetab
    db 0x1B, 1, 1                     ; DISPLAY - Cetab
    db 0x87, 1, 1                     ; FREEZE.PANES - Cetab
    db 0x1C, 1, 1                     ; PROTECT.DOCUMENT - Cetab
    db 0x1D, 1, 1                     ; PRECISION - Cetab
    db 0x3F, 1, 1                     ; FORMULA.GOTO
    db 0x40, 1, 1                     ; FORMULA.FIND
    db 0x65, 0, 1                     ; FORMULA.FIND.NEXT
    db 0x66, 0, 1                     ; FORMULA.FIND.PREV
    db 0x3D, 1, 1                     ; DEFINE.NAME
    db 0x58, 1, 0                     ; SET.NAME
    db 0x6E, 0, 1                     ; DELETE.NAME
    db 0xC0, 1, 0                     ; NOTE
    db 0x22, 1, 1                     ; DATA.FIND
    db 0x63, 0, 1                     ; DATA.FIND.NEXT
    db 0x64, 0, 1                     ; DATA.FIND.PREV
    db 0x24, 0, 1                     ; DATA.DELETE
    db 0x23, 1, 1                     ; EXTRACT
    db 0x5B, 1, 1                     ; PARSE
    db 0x27, 1, 1                     ; SORT
    db 0x11, 1, 1                     ; RUN
    db 0x70, 0, 1                     ; VLINE
    db 0x71, 0, 1                     ; HLINE
    db 0x72, 0, 1                     ; VPAGE
    db 0x73, 0, 1                     ; HPAGE
    db 0x74, 1, 1                     ; VSCROLL
    db 0x75, 1, 1                     ; HSCROLL
    db 0x42, 0, 1                     ; SHOW.ACTIVE.CELL
    db 0x41, 0, 1                     ; SELECT.LAST.CELL
    db 0xBB, 0, 1                     ; SELECT.END
    db 0x6A, 0, 1                     ; UNLOCKED.NEXT
    db 0x6B, 0, 1                     ; UNLOCKED.PREV
    db 0x43, 1, 1                     ; GALLERY.AREA
    db 0x44, 1, 1                     ; GALLERY.BAR
    db 0x45, 1, 1                     ; GALLERY.COLUMN
    db 0x46, 1, 1                     ; GALLERY.LINE
    db 0x47, 1, 1                     ; GALLERY.PIE
    db 0x48, 1, 1                     ; GALLERY.SCATTER
    db 0x06, 0, 1                     ; FILE.DELETE
    db 0x77, 1, 1                     ; NEW
    db 0x01, 1, 1                     ; OPEN
    db 0x05, 1, 1                     ; SAVE.AS
    db 0x61, 1, 1                     ; FORMULA.FILL
    db 0x28, 1, 1                     ; DATA.SERIES
    db 0x84, 1, 0                     ; FOPEN
    db 0x85, 0, 0                     ; FCLOSE
    db 0x88, 0, 0                     ; FREAD
    db 0x87, 0, 0                     ; FREADLN
    db 0x8A, 0, 0                     ; FWRITE
    db 0x89, 0, 0                     ; FWRITELN
    db 0x8B, 1, 0                     ; FPOS
    db 0x86, 0, 0                     ; FSIZE
    db 0xA8, 1, 1                     ; ON.KEY - Cetab
    db 0x94, 1, 1                     ; ON.TIME - Cetab
    db 0x97, 1, 0                     ; ADD.BAR
    db 0x9D, 1, 0                     ; SHOW.BAR
    db 0xC8, 0, 0                     ; DELETE.BAR
    db 0x98, 1, 0                     ; ADD.MENU
    db 0x99, 1, 0                     ; ADD.COMMAND
    db 0x9E, 1, 0                     ; DELETE.MENU
    db 0x9F, 1, 0                     ; DELETE.COMMAND
    db 0x9A, 1, 0                     ; ENABLE.COMMAND
    db 0x9B, 1, 0                     ; CHECK.COMMAND
    db 0x9C, 1, 0                     ; RENAME.COMMAND
    db 0xA1, 0, 0                     ; DIALOG.BOX
    db 0x29, 1, 1                     ; TABLE([row_in][,col_in]) - Cetab 0029H
                                       ; and `table-params = *2(ref / val)`,
                                       ; read out of [MS-XLS] 2.5.198.4 and
                                       ; cross-checked against its neighbour
                                       ; DATA.SERIES at 0028H, which this
                                       ; table already carries. NOT GUESSED:
                                       ; a wrong number is a file Excel runs
                                       ; differently, which is why the CALL
                                       ; above still says 0FFh. VARIABLE
                                       ; (the second 1), because *2 means
                                       ; nought to two - and the third 1 is
                                       ; what says Cetab rather than Ftab,
                                       ; where 0029H is DSUM
shm_mxrpn_end:

; All four tables, one count - assembled, not preprocessed (81.83.3.3)
    times ((shm_mkind_end - shm_mkind) - (SH_MF_N + SHM_MX_N)) db 0
    times ((SH_MF_N + SHM_MX_N) - (shm_mkind_end - shm_mkind)) db 0
    times ((shm_mxrpn_end - shm_mxrpn) - 3 * SHM_MX_N) db 0
    times (3 * SHM_MX_N - (shm_mxrpn_end - shm_mxrpn)) db 0

; 81.97: how many arguments each extension function takes when it is FIXED
; (shm_mxrpn's second byte 0) - the decoder's, because a tFunc token carries
; only an index. 0 for a variable one and for every command: Excel writes
; those with a count of their own. From the document's arity, and
; tools/os88sheetfmt.py --selfcheck holds it there.
shm_mxargc:
    db 0, 0, 0, 0, 2, 2, 0, 0    ; the CALL ARGUMENT RESULT OFFSET ABSREF RELREF REFTEXT TEXTREF
    db 1, 0, 0, 0, 0, 0, 0, 0    ; DEREF SELECTION CALLER ECHO ERROR RESTART STEP CANCEL.KEY
    db 0, 0, 0, 1, 0, 0, 0, 0    ; DISABLE.INPUT WAIT GET.CELL GET.FORMULA GET.NAME GET.DEF GET.NOTE NAMES
    db 0, 0, 1, 0, 0, 0, 0, 0    ; GET.DOCUMENT GET.WINDOW GET.WORKSPACE DIRECTORY FILL.RIGHT FILL.DOWN PASTE.LINK UNDO
    db 0, 0, 0, 0, 0, 0, 0, 0    ; JUSTIFY SAVE SET.DATABASE SET.CRITERIA CALCULATE.DOCUMENT DATA.FORM ALIGNMENT FORMAT.FONT
    db 0, 0, 0, 0, 0, 0, 0, 0    ; FORMAT.NUMBER BORDER CELL.PROTECTION COLUMN.WIDTH ROW.HEIGHT INSERT EDIT.DELETE PASTE.SPECIAL
    db 0, 0, 0, 0, 0, 0, 0, 0    ; CANCEL.COPY CALCULATION DISPLAY FREEZE.PANES PROTECT.DOCUMENT PRECISION FORMULA.GOTO FORMULA.FIND
    db 0, 0, 0, 0, 0, 0, 0, 0    ; FORMULA.FIND.NEXT FORMULA.FIND.PREV DEFINE.NAME SET.NAME DELETE.NAME NOTE DATA.FIND DATA.FIND.NEXT
    db 0, 0, 0, 0, 0, 0, 0, 0    ; DATA.FIND.PREV DATA.DELETE EXTRACT PARSE SORT RUN VLINE HLINE
    db 0, 0, 0, 0, 0, 0, 0, 0    ; VPAGE HPAGE VSCROLL HSCROLL SHOW.ACTIVE.CELL SELECT.LAST.CELL SELECT.END UNLOCKED.NEXT
    db 0, 0, 0, 0, 0, 0, 0, 0    ; UNLOCKED.PREV GALLERY.AREA GALLERY.BAR GALLERY.COLUMN GALLERY.LINE GALLERY.PIE GALLERY.SCATTER FILE.DELETE
    db 0, 0, 0, 0, 0, 0, 1, 2    ; NEW OPEN SAVE.AS FORMULA.FILL DATA.SERIES FOPEN FCLOSE FREAD
    db 1, 2, 2, 0, 1, 0, 0, 0    ; FREADLN FWRITE FWRITELN FPOS FSIZE ON.KEY ON.TIME ADD.BAR
    db 0, 1, 0, 0, 0, 0, 0, 0    ; SHOW.BAR DELETE.BAR ADD.MENU ADD.COMMAND DELETE.MENU DELETE.COMMAND ENABLE.COMMAND CHECK.COMMAND
    db 0, 1, 0                   ; RENAME.COMMAND DIALOG.BOX TABLE
shm_mxargc_end:
    times ((shm_mxargc_end - shm_mxargc) - SHM_MX_N) db 0
    times (SHM_MX_N - (shm_mxargc_end - shm_mxargc)) db 0
section SH_MODSEC2

; =============================================================================
; SUBROUTINES (macro plan wave 1). Excel's `ref(arg1, ...)`: a defined name
; called like a function branches to that cell and runs from there, and its
; RETURN(value) is the call's answer.
;
; THE ANSWER COMES BACK BY EVALUATING THE CALLING CELL AGAIN - which is INPUT's
; mechanism, and for INPUT's reason. The engine runs a step, returns to the
; kernel, and resumes; a subroutine that asks the user something PAUSES in the
; middle of the caller's formula, and there is no way to suspend an 8086 call
; stack halfway through an evaluation. So the call site answers FALSE, the
; engine pushes a frame and runs the subroutine as ordinary steps - loops,
; ALERT and INPUT included - and RETURN pops it and sends the engine back to
; the caller, whose call site now answers RETURN's value. The cost is INPUT's
; too: what the calling formula does BEFORE the call happens twice, and so ONE
; call to a cell. `=IF(c, A(), B())` is one: IF parses the branch it does not
; take without running what is in it (81.63).
;
; ALL OF THIS STATE IS THE MODULE'S OWN, addressed through CS. APP_MAX_SIZE
; left 2,475 resident bytes and this is ~1 KB; CHART.OVL is loaded once and
; kept (ch_ovneed), so it lives as long as a run does. Every access names CS
; (os88ovlchk's rule for module data).
; =============================================================================
shm_csp:    db 0                      ; frames in use
shm_ccount: db 0                      ; calls started by THIS step (one)
shm_cpend:  db 0                      ; ...and one is waiting for a frame.
                                       ; A FLAG, not a value of sh_macro_ctl:
                                       ; `RETURN(SQ(v)+1)` sets the call and
                                       ; then RETURN's own control over it, and
                                       ; the call was lost
shm_cans:   db 0                      ; the caller's second pass has an answer
shm_cnargs: db 0                      ; the pending call's argument count
shm_sused:  db 0                      ; argument slots committed to frames
shm_bused:  db 0                      ; bindings committed to frames
shm_ctcol:  dw 0                      ; the pending call's target
shm_ctrow:  dw 0
shm_pused:  dw 0                      ; pool bytes committed to frames
shm_ptent:  dw 0                      ; ...and the pending call's end of them
shm_arcol:  dw 0                      ; ARGUMENT's ref, when it has one
shm_arrow:  dw 0
shm_ahref:  db 0
shm_amask:  db 0                      ; ARGUMENT's type, 0 = any
shm_aname:  times SH_NAME_MAX + 1 db 0
; A FRAME: +0 the caller's col, +2 row, +4 its loop depth, +5 its first
; argument slot, +6 how many, +7 how many ARGUMENTs have bound, +8 its first
; pool byte, +10 its first binding, +11 RESULT's type (0 = any)
shm_cstk:   times SH_MSUBS * SH_MFRAME db 0
; A VALUE: +0 SH_T_*, +1 its evaluation error, +2 sh_curaux, +4 sh_acc's eight
; bytes - or, for TEXT, the CS offset of its characters in the pool
shm_slots:  times SH_MSLOTS * SH_MVAL db 0
shm_pool:   times SH_MPOOL db 0
shm_binds:  times SH_MBINDS * SH_MBREC db 0
shm_ans:    times SH_MVAL db 0        ; RETURN's value, for the second pass
shm_anstxt: times SH_STR_MAX + 1 db 0

; shm_x12 / shm_x14 - AX = AX * 12 / * 14
shm_x12:
    push bx
    mov bx, ax
    shl ax, 1
    add ax, bx
    shl ax, 1
    shl ax, 1
    pop bx
    ret
shm_x14:
    push bx
    mov bx, ax
    shl ax, 1
    shl ax, 1
    shl ax, 1
    shl ax, 1
    sub ax, bx
    sub ax, bx
    pop bx
    ret

; shm_ctop - DI = the top frame. Only when [shm_csp] is not 0.
shm_ctop:
    push ax
    mov al, [cs:shm_csp]
    dec al
    xor ah, ah
    call shm_x12
    add ax, shm_cstk
    mov di, ax
    pop ax
    ret

; shm_vput - bank the value the evaluator just produced into the slot at
; [cs:di]; a TEXT value's characters go to [cs:bx]. out: CX = text bytes used
; (with the NUL), 0 for any other value. Preserves the rest.
shm_vput:
    push ax
    push si
    push di
    mov al, [sh_curtype]
    mov [cs:di], al
    mov al, [sh_evalerr]
    mov [cs:di+1], al
    mov ax, [sh_curaux]
    mov [cs:di+2], ax
    mov si, sh_acc
    add di, 4
    mov cx, 8
.acc:
    mov al, [si]
    mov [cs:di], al
    inc si
    inc di
    loop .acc
    sub di, 12
    cmp byte [cs:di], SH_T_TEXT
    jne .out
    mov [cs:di+4], bx
    mov si, sh_sacc
.text:
    mov al, [si]
    mov [cs:bx], al
    inc si
    inc bx
    inc cx
    or al, al
    jnz .text
.out:
    pop di
    pop si
    pop ax
    ret

; shm_vget - the value in the slot at [cs:di] back into the evaluator, as the
; answer of whatever is being evaluated. An error is RAISED, never cleared:
; sh_evalerr is sticky for the whole evaluation and a clean argument must not
; wipe out an error something else in the formula already hit.
shm_vget:
    push ax
    push cx
    push si
    push di
    cmp byte [cs:di], SH_T_TEXT
    je .text
    mov si, di
    add si, 4
    push di
    mov di, sh_acc
    mov cx, 8
.acc:
    mov al, [cs:si]
    mov [di], al
    inc si
    inc di
    loop .acc
    pop di
    jmp short .tag
.text:
    mov si, [cs:di+4]
    push di
    mov di, sh_sacc
.tc:
    mov al, [cs:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .tc
    xor ax, ax                        ; a text value's number is 0, as INPUT's
    SHOUT sh_acc_int
    pop di
.tag:                                 ; the tag LAST: sh_acc_int sets its own
    mov al, [cs:di]
    mov [sh_curtype], al
    mov ax, [cs:di+2]
    mov [sh_curaux], ax
    mov al, [cs:di+1]
    or al, al
    jz .out
    mov [sh_evalerr], al
.out:
    pop di
    pop si
    pop cx
    pop ax
    ret

; shm_mcall - the call site: a defined name followed by '(' (sh_pfunc routes
; it here as SH_FID_MCALL). The FIRST pass banks the arguments and asks the
; engine for a frame; the SECOND, after RETURN, answers what came back.
shm_mcall:
    cmp byte [cs:shm_cans], 0
    je .call
    mov byte [cs:shm_cans], 0
    SHOUT sh_skipargs                 ; they were evaluated on the first pass
    mov di, shm_ans
    jmp shm_vget
.call:
    inc byte [cs:shm_ccount]
    cmp byte [cs:shm_ccount], 1
    jne .twice
    push si                           ; the TARGET before any argument: an
    mov si, sh_ident                  ; argument's own evaluation overwrites
    SHOUT sh_name_lookup              ; sh_ident
    pop si
    jnc .bad
    mov [cs:shm_ctcol], ax
    mov [cs:shm_ctrow], bx
    mov byte [cs:shm_cnargs], 0
    mov ax, [cs:shm_pused]
    mov [cs:shm_ptent], ax
    cmp byte [si], ')'
    je .args
.arg:
    mov al, [cs:shm_cnargs]
    cmp al, SH_MARGS
    jae .full
    add al, [cs:shm_sused]
    cmp al, SH_MSLOTS
    jae .full
    mov bx, [cs:shm_ptent]
    add bx, SH_STR_MAX + 1            ; room for the longest text there is
    cmp bx, SH_MPOOL
    ja .full
    SHOUT sh_pcmp
    mov al, [cs:shm_sused]
    add al, [cs:shm_cnargs]
    xor ah, ah
    call shm_x12
    add ax, shm_slots
    mov di, ax
    mov bx, [cs:shm_ptent]
    add bx, shm_pool
    call shm_vput
    add [cs:shm_ptent], cx
    mov byte [sh_evalerr], 0          ; an argument's error is ITS value, and
    inc byte [cs:shm_cnargs]          ; does not make the calling cell one
    cmp byte [si], ','
    jne .args
    inc si
    jmp .arg
.args:
    SHOUT sh_skipargs
    mov byte [cs:shm_cpend], 1
    jmp shm_mfalse
.twice:
    mov word [sh_msg], sh_s_mtwice
    jmp short .stop
.full:
    mov word [sh_msg], sh_s_mfull
.stop:
    mov byte [sh_macro_ctl], SH_MC_STOP
    SHOUT sh_skipargs
    jmp shm_mfalse
.bad:
    jmp shm_merr

; shm_cpush - the engine, after a step asked for SH_MC_CALL: a frame for the
; caller, and the pending call's arguments committed to it. CF=1 too deep.
shm_cpush:
    push ax
    push di
    cmp byte [cs:shm_csp], SH_MSUBS
    jae .deep
    inc byte [cs:shm_csp]
    call shm_ctop
    mov ax, [sh_macro_col]
    mov [cs:di], ax
    mov ax, [sh_macro_row]
    mov [cs:di+2], ax
    mov al, [sh_macro_lsp]
    mov [cs:di+4], al
    mov al, [cs:shm_sused]
    mov [cs:di+5], al
    mov al, [cs:shm_cnargs]
    mov [cs:di+6], al
    add [cs:shm_sused], al
    mov byte [cs:di+7], 0
    mov ax, [cs:shm_pused]
    mov [cs:di+8], ax
    mov ax, [cs:shm_ptent]
    mov [cs:shm_pused], ax
    mov al, [cs:shm_bused]
    mov [cs:di+10], al
    mov byte [cs:di+11], 0
    clc
    jmp short .out
.deep:
    stc
.out:
    pop di
    pop ax
    ret

; shm_cpop - RETURN: back to the calling cell, with the subroutine's loops,
; arguments, text and bindings all given back
shm_cpop:
    push ax
    push di
    call shm_ctop
    mov ax, [cs:di]
    mov [sh_macro_col], ax
    mov ax, [cs:di+2]
    mov [sh_macro_row], ax
    mov al, [cs:di+4]
    mov [sh_macro_lsp], al
    mov al, [cs:di+5]
    mov [cs:shm_sused], al
    mov ax, [cs:di+8]
    mov [cs:shm_pused], ax
    mov al, [cs:di+10]
    mov [cs:shm_bused], al
    dec byte [cs:shm_csp]
    inc word [sh_pass]                ; ...and so does its bindings going
    pop di
    pop ax
    ret

; shm_tbit - AL = the SH_T_* just evaluated (an evaluation error counts as
; the error it is) -> AL = Excel's type bit: 1 number, 2 text, 4 logical,
; 16 error. A blank is the number 0 it evaluates as.
shm_tbit:
    cmp byte [sh_evalerr], 0
    jne .e
    cmp al, SH_T_TEXT
    je .t
    cmp al, SH_T_BOOL
    je .b
    cmp al, SH_T_ERR
    je .e
    mov al, 1
    ret
.t:
    mov al, 2
    ret
.b:
    mov al, 4
    ret
.e:
    mov al, 16
    ret

; shm_rtype - the value RETURN is about to hand back, against the type the
; subroutine declared with RESULT: #VALUE! if it is not one of them
shm_rtype:
    push ax
    push di
    call shm_ctop
    mov ah, [cs:di+11]
    or ah, ah
    jz .ok
    mov al, [sh_curtype]
    call shm_tbit
    test al, ah
    jnz .ok
    mov byte [sh_evalerr], SH_ERR_VALUE
.ok:
    pop di
    pop ax
    ret

; RESULT([type]) - the types this subroutine may RETURN, Excel's sum of 1
; number, 2 text, 4 logical, 8 reference, 16 error, 64 array. Omitted, 7.
shm_mresult:
    mov ax, 7
    cmp byte [si], ')'
    je .have
    SHOUT sh_pcmp
    SHOUT sh_acc_toint
    jnc .have
    mov ax, 7
.have:
    push ax                           ; sh_skipargs walks the text in AL
    SHOUT sh_skipargs
    pop ax
    cmp byte [cs:shm_csp], 0
    je .out                           ; not in a subroutine: nothing to type
    call shm_ctop
    or al, 8 + 64                     ; a reference or an array is a VALUE by
    mov [cs:di+11], al                ; the time this app returns one
.out:
    jmp shm_mtrue

; shm_bfind - is shm_aname bound in the TOP frame? CF=1 AL = its slot (0xFF:
; declared, but the caller passed fewer). in DI = the frame.
shm_bfind:
    push bx
    push si
    push di
    mov bl, [cs:di+10]
.rec:
    cmp bl, [cs:shm_bused]
    jae .no
    mov al, bl
    xor ah, ah
    call shm_x14
    add ax, shm_binds
    mov si, ax
    mov di, shm_aname
.cmp:
    mov al, [cs:si]
    cmp al, [cs:di]
    jne .next
    or al, al
    jz .yes
    inc si
    inc di
    jmp short .cmp
.next:
    inc bl
    jmp short .rec
.yes:
    mov al, bl
    xor ah, ah
    call shm_x14
    add ax, shm_binds
    mov si, ax
    mov al, [cs:si + SH_NAME_MAX + 1]
    stc
    jmp short .out
.no:
    clc
.out:
    pop di
    pop si
    pop bx
    ret

; shm_aslot - AL = a slot index, 0xFF for #N/A -> that value as the answer
shm_aslot:
    cmp al, 0xFF
    je .na
    xor ah, ah
    call shm_x12
    add ax, shm_slots
    mov di, ax
    jmp shm_vget
.na:
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_ERR
    mov word [sh_curaux], SH_ERR_NA
    mov byte [sh_evalerr], SH_ERR_NA
    ret

; ARGUMENT(name_text[, type[, ref]]) - names the NEXT argument the caller
; passed, in the order ARGUMENTs execute, as Excel binds them.
;
; A NAME HERE IS A PLACE, NOT A VALUE (81.29), which is the whole design
; problem. With a `ref`, the value is written there and the name bound to it,
; exactly as Excel does. Without one, the name is bound to THIS CELL, and this
; function is a VALUE function (shm_mkind): reading `x` anywhere evaluates
; this cell, which answers what `x` was bound to in the running subroutine.
; Only the STEP ENGINE binds - an evaluation at any other depth, a repaint or
; a reference to `x`, answers the binding and consumes nothing.
shm_margument:
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT
    jne .bad
    push si                           ; the name, uppercased into the module
    mov si, sh_sacc
    mov di, shm_aname
    xor cx, cx
.nc:
    mov al, [si]
    or al, al
    jz .nd
    cmp al, 'a'
    jb .up
    cmp al, 'z'
    ja .up
    sub al, 32
.up:
    mov [cs:di], al
    inc si
    inc di
    inc cx
    cmp cx, SH_NAME_MAX
    jb .nc
.nd:
    mov byte [cs:di], 0
    pop si
    mov byte [sh_evalerr], 0
    mov byte [cs:shm_ahref], 0
    mov byte [cs:shm_amask], 0
    cmp byte [si], ','
    jne .parsed
    inc si
    cmp byte [si], ','                ; ARGUMENT("x",,C5): no type given
    je .ref
    cmp byte [si], ')'
    je .parsed
    SHOUT sh_pcmp
    SHOUT sh_acc_toint
    jc .ref
    mov [cs:shm_amask], al
.ref:
    cmp byte [si], ','
    jne .parsed
    inc si
    call shm_mref
    jnc .bad
    mov [cs:shm_arcol], ax
    mov [cs:shm_arrow], bx
    mov byte [cs:shm_ahref], 1
.parsed:
    SHOUT sh_skipargs
    cmp byte [cs:shm_csp], 0
    je .outside
    call shm_ctop
    call shm_bfind                    ; bound already: answer it, consume none
    jc .answer
    cmp byte [sh_macro_exec], 0       ; not bound, and not the step engine
    je .unbound                       ; running THIS cell: nothing to answer
    mov ax, [sh_evaldepth]
    cmp ax, [sh_macro_exdep]
    jne .unbound
    mov al, [cs:di+7]                 ; the next argument, in order
    inc byte [cs:di+7]
    cmp al, [cs:di+6]
    jb .passed
    mov al, 0xFF                      ; declared, not passed: #N/A, as Excel
    jmp short .bind
.passed:
    add al, [cs:di+5]
.bind:
    mov ah, [cs:shm_bused]            ; record it: name, slot
    cmp ah, SH_MBINDS
    jae .full
    push ax
    mov al, ah
    xor ah, ah
    call shm_x14
    add ax, shm_binds
    mov di, ax
    push si                           ; SI IS THE EVALUATOR'S TEXT POINTER, past
    mov si, shm_aname                 ; ')' - borrowed for the copy and given
    mov cx, SH_NAME_MAX + 1           ; back, or the formula resumes parsing
.bn:                                  ; from inside the module
    mov al, [cs:si]
    mov [cs:di], al
    inc si
    inc di
    loop .bn
    pop si
    pop ax
    mov [cs:di], al
    inc byte [cs:shm_bused]
    inc word [sh_pass]                ; A BINDING CHANGES WHAT A CELL MEANS.
                                       ; sh_eval_cell answers a cell computed
                                       ; in this pass from its cache, and this
                                       ; one was computed - by a repaint, with
                                       ; nothing bound - so reading `num` got
                                       ; the fixture's 0 until the pass moved.
                                       ; Calculate Now's own invalidation
    push ax
    call shm_aslot                    ; the value, into the evaluator
    pop ax
    mov bx, [sh_macro_row]            ; the name: onto the ref, or this cell
    mov ax, [sh_macro_col]
    cmp byte [cs:shm_ahref], 0
    je .define
    mov ax, [cs:shm_arcol]
    mov bx, [cs:shm_arrow]
    push ax
    push bx
    call shm_mstore                   ; ...and with a ref, the value goes there
    pop bx
    pop ax
.define:
    call shm_mdefname
    ret                               ; answering the value shm_aslot loaded
.answer:
    call shm_aslot
    ret
.unbound:
    jmp shm_mfalse
.outside:
    mov word [sh_msg], sh_s_marg
    mov byte [sh_macro_ctl], SH_MC_STOP
    jmp shm_mfalse
.full:
    mov word [sh_msg], sh_s_mfull
    mov byte [sh_macro_ctl], SH_MC_STOP
    jmp shm_mfalse
.bad:
    jmp shm_merr

; shm_mdefname - bind shm_aname to the one cell AX,BX. sh_name_def takes a
; DS name, so it goes through sh_ident, which nothing evaluates in between.
; Preserves everything but the flags.
shm_mdefname:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov si, shm_aname
    mov di, sh_ident
.cp:
    mov cl, [cs:si]
    mov [di], cl
    inc si
    inc di
    or cl, cl
    jnz .cp
    mov cx, ax
    mov dx, bx
    mov si, sh_ident
    SHOUT sh_name_def
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

section SH_MODSEC                      ; 81.94: CHART.OVL's too - a lookup
; shm_mfind - is the name in sh_ident (DS, uppercase) an EXTENSION macro
; function? out: AX = its id, SH_FID_MX.., or 0xFF. Preserves the rest.
shm_mfind:
    push bx
    push cx
    push si
    push di
    mov di, shm_mxnames
    xor cx, cx
.name:
    cmp byte [cs:di], 0               ; an empty name: the end of the table
    je .none
    mov si, sh_ident
.cmp:
    mov al, [cs:di]
    cmp al, [si]
    jne .skip
    or al, al
    jz .hit                           ; both ended together
    inc si
    inc di
    jmp short .cmp
.skip:                                ; on to this name's NUL, then past it
    cmp byte [cs:di], 0
    je .next
    inc di
    jmp short .skip
.next:
    inc di
    inc cx
    jmp short .name
.hit:
    mov ax, cx
    add ax, SH_FID_MX
    jmp short .out
.none:
    mov ax, 0xFF
.out:
    pop di
    pop si
    pop cx
    pop bx
    ret

section SH_MODSEC2
; shm_mtrue / shm_mfalse - the answer, a logical
shm_mtrue:
    push ax
    mov ax, 1
    jmp short shm_mbool
shm_mfalse:
    push ax
    xor ax, ax
shm_mbool:
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_BOOL
    pop ax
    ret

; shm_merr - a macro that cannot go on: stop it and say so
shm_merr:
    SHOUT sh_skipargs
; shm_merr0 - the same, once the arguments are consumed already
shm_merr0:
    cmp byte [cs:shm_errmode], 1      ; 81.86: ERROR() decides - 1 is the
    jne .notnormal                    ; default, and stops the run
    mov byte [sh_macro_ctl], SH_MC_STOP
    mov word [sh_msg], sh_s_macroerr
.f:
    jmp short shm_mfalse
.notnormal:
    jb .f                             ; ERROR(FALSE): ignore it, carry on
    push ax                           ; ERROR(TRUE, ref): run from ref
    mov ax, [cs:shm_errcol]
    mov [sh_macro_ncol], ax
    mov ax, [cs:shm_errrow]
    mov [sh_macro_nrow], ax
    pop ax
    mov byte [sh_macro_ctl], SH_MC_GOTO
    jmp short .f

; shm_mref - a REFERENCE argument at SI: a reference, a name, or text - "B5",
; or "R[1]C" relative to the active cell. out: CF=1 AX = col, BX = row, SI
; past it; CF=0 when it is none of those
shm_mref:
    SHOUT sh_pargref                  ; a reference, as written
    jnc .name
    mov ax, [sh_arg1col]
    mov bx, [sh_arg1row]
    stc
    ret
.name:
    CHOUT SHM_MNAME                    ; ...a defined name standing alone
    jc .out
    push cx
    push dx
    push si
    mov byte [cs:shm_rrok], 0
    SHOUT sh_pcmp                     ; ...or anything that ANSWERS with one:
    pop dx                            ; a reference function, called as the
    call shm_refarg                   ; whole argument (wave 1b)...
    pop dx
    pop cx
    jc .out
    cmp byte [sh_curtype], SH_T_TEXT  ; ...or text
    jne .no
    push si
    mov si, sh_sacc
    SHOUT sh_pcellref                 ; "B5", all of it
    jnc .r1c1
    cmp byte [si], 0
    je .a1
.r1c1:
    mov si, sh_sacc                   ; "R[1]C": relative to the ACTIVE cell,
    call shm_r1c1one                  ; which is what the recorder means - and
    jnc .r1c1fail                     ; "R1C1", which A1 reads as R1 and more
    cmp byte [si], 0                  ; than one cell (a range) is SELECT's own
    jne .r1c1fail                     ; job (shm_mrangeref), not this one's
    pop si
    stc
    ret
.r1c1fail:
    pop si
    clc
    ret
.a1:
    pop si
    stc
    ret
.no:
    clc
.out:
    ret

section SH_MODSEC                      ; 81.94: CHART.OVL's - the database
                                       ; functions gather names with it too
; shm_mname - SI at a word that is a DEFINED NAME and nothing else, before a
; ',' or ')': CF=1, AX/BX its near corner, CX/DX its far corner (equal to
; AX/BX for a single cell), SI past it. CF=0 with SI where it was otherwise.
; CX/DX are OUTPUTS now, not preserved - shm_rangeref is why (this routine
; had exactly one caller before it, shm_mref, which never read them back)
shm_mname:
    push di
    mov [sh_macro_mnsi], si           ; where to put SI back on a miss
    mov di, sh_ident
    xor cx, cx
.g:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    cmp al, '.'
    je .k
    cmp al, '_'
    je .k
    cmp al, '0'
    jb .e
    cmp al, '9'
    jbe .k
    cmp al, 'A'
    jb .e
    cmp al, 'Z'
    ja .e
.k:
    cmp cx, SH_NAME_MAX               ; a DEFINED name, which is what this
    jae .no                           ; routine's own header says it gathers -
                                       ; it used to read SH_NAMEMAX, the 8.3
                                       ; FILE name bound, and was right only
                                       ; because the two constants were both 12
    mov [di], al
    inc di
    inc si
    inc cx
    jmp short .g
.e:
    jcxz .no
    cmp al, ','
    je .end
    cmp al, ')'
    jne .no
.end:
    mov byte [di], 0
    push si
    mov si, sh_ident
    SHOUT sh_name_lookup              ; AX/BX the near corner, CX/DX the far
    pop si
    jnc .no
    pop di
    stc
    ret
.no:
    mov si, [sh_macro_mnsi]
    pop di
    clc
    ret

section SH_MODSEC2
; shm_r1c1one - SI = an R1C1 reference; unlike the old shm_r1c1 this does NOT
; require the string to end there - shm_rangetext checks for ':' itself, so
; a lone reference and the first half of a range share one parser. out: CF=1
; AX col, BX row, SI past it; CF=0 otherwise, SI unchanged
shm_r1c1one:
    push cx
    push dx
    push si
    mov al, [si]
    and al, 0xDF
    cmp al, 'R'
    jne .no
    inc si
    CHOUT SHM_READRC                   ; BX = the value, CL = 1 absolute
    jc .no
    mov dx, bx
    or cl, cl
    jnz .rabs
    add dx, [sh_selrow]
.rabs:
    mov al, [si]
    and al, 0xDF
    cmp al, 'C'
    jne .no
    inc si
    CHOUT SHM_READRC
    jc .no
    or cl, cl
    jnz .cabs
    add bx, [sh_selcol]
.cabs:
    cmp bx, SH_COLS                   ; unsigned: a negative offset past the
    jae .no                           ; edge wraps high and is refused too
    cmp dx, SH_ROWS
    jae .no
    mov ax, bx
    mov bx, dx
    add sp, 2                         ; discard the banked SI - keep advancing
    pop dx
    pop cx
    stc
    ret
.no:
    pop si
    pop dx
    pop cx
    clc
    ret

; shm_rangetext - SI = a NUL-terminated string value: an A1 or R1C1
; reference, ONE cell or a colon-separated RANGE of them ("H1:I2",
; "R23C8:R24C9") - SELECT's own need, the one macro command that can select
; more than the active cell. out: CF=1 AX/BX near corner, CX/DX far corner
; (equal to near for one cell); CF=0 otherwise
;
; WHICH ONE FIRST IS NOT A COIN FLIP: "R23C8" is also a legal (if unintended)
; A1 reference - column R, row 23 - and sh_pcellref matches it and stops,
; leaving "C8:R24C9" behind, unconsumed but never rejected outright since
; nothing here required the whole string yet. Trying A1 unconditionally
; first would take that read every time. So this peeks the way
; sh_formula_from_r1c1's own header already does: a word-start 'R' followed
; by '[', a digit, '-' or 'C' is R1C1, anything else is A1 - the same
; disambiguation, not a second one
shm_rangetext:
    mov al, [si]
    and al, 0xDF
    cmp al, 'R'
    jne .doa1
    mov al, [si+1]
    cmp al, '['
    je .dorc
    cmp al, '-'
    je .dorc
    cmp al, '0'
    jb .doa1
    cmp al, '9'
    jbe .dorc
    and al, 0xDF
    cmp al, 'C'
    je .dorc
.doa1:
    SHOUT sh_pcellref
    jnc .fail
    push ax
    push bx
    cmp byte [si], ':'
    jne .a1one
    inc si
    SHOUT sh_pcellref
    jnc .failpop
    mov cx, ax
    mov dx, bx
    cmp byte [si], 0
    jne .failpop
    pop bx
    pop ax
    jmp .have
.a1one:
    cmp byte [si], 0
    jne .failpop
    pop bx
    pop ax
    mov cx, ax
    mov dx, bx
    jmp .have
.dorc:
    call shm_r1c1one
    jnc .fail
    push ax
    push bx
    cmp byte [si], ':'
    jne .rc1one
    inc si
    call shm_r1c1one
    jnc .failpop
    mov cx, ax
    mov dx, bx
    cmp byte [si], 0
    jne .failpop
    pop bx
    pop ax
    jmp .have
.rc1one:
    cmp byte [si], 0
    jne .failpop
    pop bx
    pop ax
    mov cx, ax
    mov dx, bx
.have:
    stc
    ret
.failpop:
    pop bx
    pop ax
.fail:
    clc
    ret

; shm_mrangeref - like shm_mref, but keeps the far corner too: SELECT's own
; need (GOTO/FOR/SET.VALUE/FORMULA's ref argument only ever wants one cell,
; so shm_mref is untouched for them). out: CF=1 AX/BX near corner, CX/DX far
; corner (equal to near for one cell), SI past it; CF=0 when the argument is
; none of a reference, a name, or a reference/range as text
shm_mrangeref:
    SHOUT sh_pargref                  ; a literal reference, as written -
    jnc .name                         ; sh_pargref already keeps both corners
    mov ax, [sh_arg1col]
    mov bx, [sh_arg1row]
    mov cx, [sh_arg2col]
    mov dx, [sh_arg2row]
    stc
    ret
.name:
    CHOUT SHM_MNAME                    ; a defined name, near/far corner both
    jc .out
    push si
    mov byte [cs:shm_rrok], 0
    SHOUT sh_pcmp                     ; ...a reference function's answer
    pop dx
    call shm_refarg
    jc .out
    cmp byte [sh_curtype], SH_T_TEXT  ; ...or anything that ANSWERS with text
    jne .no
    push si
    mov si, sh_sacc
    call shm_rangetext
    pop si
    ret
.no:
    clc
.out:
    ret

; =============================================================================
; THE REFERENCE FAMILY (macro plan wave 1b): OFFSET, ABSREF, RELREF, REFTEXT,
; TEXTREF, DEREF, SELECTION, CALLER - and ACTIVE.CELL, which is one too.
;
; SHEET's evaluator has no reference VALUE: an expression answers a number, a
; text, a logical or an error, and a reference is something only an argument
; parser recognises in the formula's TEXT (sh_pargref). So a function that
; answers a reference answers two things. Its VALUE is the top-left cell's,
; which is what Excel converts a reference to wherever a value is wanted - and
; here that is everywhere but one place. Its REFERENCE goes in the record
; below, and the one place is a macro function's reference argument
; (shm_mref, shm_mrangeref), which reads it back when - and only when - the
; WHOLE argument was one call to the function that wrote it:
;
;   SELECT(OFFSET(A1,1,1))        B2 - the argument is the call
;   SET.VALUE(OFFSET(A1,1,1)+1,5) the argument is an expression; its value
;                                 is a number, which names no cell - refused
;   SELECT(SUM(OFFSET(A1,0,0)))   SUM's call, not OFFSET's - refused
;
; "Whole" is decided by POSITION, not by name. shm_pmacro stamps where the
; answering call's arguments began and ended; the argument is that call when
; it ends where the call ends and everything before the call's '(' is one
; identifier. Nesting needs nothing more: OFFSET(OFFSET(A1,1,1),1,1) stamps
; the inner call, then the outer one over it, and the outer one is the
; argument.
;
; What this cannot do is hand a RANGE to a worksheet function: SUM(OFFSET(..))
; sums the top-left cell, where Excel sums the range, because SUM's arguments
; are sh_pargref's and it reads formula text. Declared, 81.85.
; =============================================================================
shm_rrok:   db 0                      ; the record below is this argument's
shm_rrnew:  db 0                      ; the handler just answered a reference
shm_rrin:   dw 0                      ; SI just past the call's '('
shm_rrout:  dw 0                      ; ...and just past its ')'
shm_rrc1:   dw 0                      ; the reference, top-left first
shm_rrr1:   dw 0
shm_rrc2:   dw 0
shm_rrr2:   dw 0

; shm_refarg - was the argument that began at DX and ends at SI exactly one
; call to a reference function? out: CF=1 AX/BX near corner, CX/DX far;
; CF=0 otherwise. SI is unchanged either way
shm_refarg:
    cmp byte [cs:shm_rrok], 0
    je .no
    cmp si, [cs:shm_rrout]            ; it ends where the argument ends...
    jne .no
    push si
    mov si, dx
    mov dx, [cs:shm_rrin]
    dec dx                            ; ...and starts, name and all, here:
    cmp si, dx                        ; its '('
    jae .nop
.id:
    mov al, [si]                      ; nothing but one identifier before it
    call shm_isname
    jnc .nop
    inc si
    cmp si, dx
    jb .id
    cmp byte [si], '('
    jne .nop
    pop si
    mov ax, [cs:shm_rrc1]
    mov bx, [cs:shm_rrr1]
    mov cx, [cs:shm_rrc2]
    mov dx, [cs:shm_rrr2]
    mov byte [sh_evalerr], 0          ; the CELL's error is not the argument's
    stc
    ret
.nop:
    pop si
.no:
    clc
    ret

; shm_isname - CF=1 when AL can be part of a function's name
shm_isname:
    cmp al, '.'
    je .y
    cmp al, '_'
    je .y
    cmp al, '0'
    jb .n
    cmp al, '9'
    jbe .y
    and al, 0xDF
    cmp al, 'A'
    jb .n
    cmp al, 'Z'
    ja .n
.y:
    stc
    ret
.n:
    clc
    ret

; shm_refret - answer the reference AX/BX .. CX/DX (either corner order):
; record it, consume the rest of the arguments, and answer the top-left
; cell's value - an empty cell is zero, as ACTIVE.CELL always answered
shm_refret:
    cmp ax, cx
    jbe .c
    xchg ax, cx
.c:
    cmp bx, dx
    jbe .r
    xchg bx, dx
.r:
    mov [cs:shm_rrc1], ax
    mov [cs:shm_rrr1], bx
    mov [cs:shm_rrc2], cx
    mov [cs:shm_rrr2], dx
    mov byte [cs:shm_rrnew], 1
    SHOUT sh_skipargs
    mov ax, [cs:shm_rrc1]
    mov bx, [cs:shm_rrr1]
    SHOUT sh_getcell2
    jc .out
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
.out:
    ret

; shm_referr - answer the error AL (unless an argument already answered one)
; and consume the rest of the arguments
shm_referr:
    cmp byte [sh_evalerr], 0
    jne .have
    mov [sh_evalerr], al
.have:
    SHOUT sh_skipargs
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    ret
shm_refbad:
    mov al, SH_ERR_VALUE
    jmp short shm_referr
shm_refnone:
    mov al, SH_ERR_REF
    jmp short shm_referr

; shm_intarg - an optional integer argument after a ','. in: AX = what an
; omitted one is worth; out: AX, SI past it; CF=1 when it is there and is
; not a number (an error, or text)
shm_intarg:
    cmp byte [si], ','
    jne .dflt
    inc si
    cmp byte [si], ','
    je .dflt
    cmp byte [si], ')'
    je .dflt
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .bad
    cmp byte [sh_curtype], SH_T_TEXT
    je .bad
    SHOUT sh_acc_toint                ; CF=1 when it did not fit
    ret
.bad:
    stc
    ret
.dflt:
    clc
    ret

; shm_boolarg - an optional logical after a ','. out: AL = 1 true, 0 false or
; omitted, SI past it
shm_boolarg:
    xor al, al
    cmp byte [si], ','
    jne .out
    inc si
    cmp byte [si], ')'
    je .out
    SHOUT sh_pcmp
    call shm_mtruth
    mov al, 0
    jnc .out
    inc al
.out:
    ret

; shm_textarg - SI at a TEXT argument: evaluate it and PARSE it in the same
; breath, before anything else can reuse sh_sacc. in: AH = 0 R1C1, 1 A1, 2
; either (shm_rangetext's own choice). out: CF=1 AX/BX .. CX/DX; CF=0 when
; it is not text or does not read as a reference, all of it
shm_textarg:
    push ax
    SHOUT sh_pcmp
    pop ax
    cmp byte [sh_evalerr], 0
    jne .no
    cmp byte [sh_curtype], SH_T_TEXT
    jne .no
    push si
    mov si, sh_sacc
    cmp ah, 1
    je .a1
    ja .any
    call shm_rangetext.dorc
    jmp short .done
.a1:
    call shm_rangetext.doa1
    jmp short .done
.any:
    call shm_rangetext
.done:
    pop si
    ret
.no:
    clc
    ret

; shm_rtcat - the DS string at SI onto DI
shm_rtcat:
    push ax
    push si
.c:
    mov al, [si]
    or al, al
    jz .e
    mov [di], al
    inc si
    inc di
    jmp short .c
.e:
    pop si
    pop ax
    ret

; shm_rtnum - AX as one part of an R1C1 reference at DI, in the form
; [cs:shm_rtform]: 0 absolute (a 0-based index, written 1-based), 2 relative
; (an offset: "[n]", or nothing at all for zero - "RC", not "R[0]C[0]", which
; is Excel's own form)
shm_rtnum:
    push ax
    push si
    cmp byte [cs:shm_rtform], 2
    jne .abs
    or ax, ax
    jz .out
    mov byte [di], '['
    inc di
    SHOUT sh_itoa
    mov si, sh_numbuf
    call shm_rtcat
    mov byte [di], ']'
    inc di
    jmp short .out
.abs:
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call shm_rtcat
.out:
    pop si
    pop ax
    ret

; shm_rtone - one cell AX col, BX row at DI, in the form [cs:shm_rtform]:
; 0 "R3C3", 1 "$C$3", 2 the relative "R[-2]C[-2]" (AX/BX are then offsets)
shm_rtone:
    push ax
    push si
    cmp byte [cs:shm_rtform], 1
    je .a1
    mov byte [di], 'R'
    inc di
    push ax
    mov ax, bx
    call shm_rtnum
    pop ax
    mov byte [di], 'C'
    inc di
    call shm_rtnum
    jmp short .out
.a1:
    mov byte [di], '$'
    inc di
    SHOUT sh_colname
    mov si, sh_colbuf
    call shm_rtcat
    mov byte [di], '$'
    inc di
    mov ax, bx
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call shm_rtcat
.out:
    pop si
    pop ax
    ret

shm_rtform: db 0                      ; shm_rtone's form, set by its caller:
                                       ; CX is the far column, so not CL

; shm_rttext - AX/BX .. CX/DX as the TEXT answer, in the form [cs:shm_rtform]
; (shm_rtone's): a range is two cells and a ':', one cell is one
shm_rttext:
    push di
    mov di, sh_sacc
    call shm_rtans
    pop di
    SHOUT sh_skipargs
    ret

; shm_rtans - shm_rttext's text written from DI (somewhere in sh_sacc) and
; answered, with the arguments left alone: GET.NAME puts its '=' first
shm_rtans:
    push di
    call shm_rtone
    cmp ax, cx
    jne .two
    cmp bx, dx
    je .one
.two:
    mov byte [di], ':'
    inc di
    mov ax, cx
    mov bx, dx
    call shm_rtone
.one:
    mov byte [di], 0
    pop di
    xor ax, ax
    SHOUT sh_acc_int                  ; the number underneath a string is zero
    mov byte [sh_curtype], SH_T_TEXT
    ret

; OFFSET(ref, rows, cols[, height[, width]]) - ref's top-left moved down rows
; and right cols, height by width (ref's own when omitted). Over the edge of
; the sheet is #REF!, and so is a height or width under one
shm_moffset:
    call shm_mrangeref
    jc .ref
    jmp shm_refbad
.ref:
    push bp
    mov bp, sp                        ; SS: these four are on the stack
    sub cx, ax                        ; ref's own size, for an omitted one
    inc cx
    sub dx, bx
    inc dx
    push ax                           ; [bp-2] col
    push bx                           ; [bp-4] row
    push dx                           ; [bp-6] height
    push cx                           ; [bp-8] width
    xor ax, ax
    call shm_intarg                   ; rows
    jc .bad
    add [bp-4], ax
    xor ax, ax
    call shm_intarg                   ; cols
    jc .bad
    add [bp-2], ax
    mov ax, [bp-6]
    call shm_intarg                   ; height
    jc .bad
    mov [bp-6], ax
    mov ax, [bp-8]
    call shm_intarg                   ; width
    jc .bad
    mov [bp-8], ax
    mov ax, [bp-2]
    mov bx, [bp-4]
    cmp word [bp-6], 1
    jl .none
    cmp word [bp-8], 1
    jl .none
    cmp ax, SH_COLS                   ; unsigned: above or left of the sheet
    jae .none                         ; wraps high and is refused with it
    cmp bx, SH_ROWS
    jae .none
    mov cx, ax
    add cx, [bp-8]
    dec cx
    cmp cx, SH_COLS
    jae .none
    mov dx, bx
    add dx, [bp-6]
    dec dx
    cmp dx, SH_ROWS
    jae .none
    add sp, 8                         ; the four above, all still there
    pop bp
    jmp shm_refret
.bad:
    add sp, 8                         ; the four above, all still there
    pop bp
    jmp shm_refbad
.none:
    add sp, 8                         ; the four above, all still there
    pop bp
    jmp shm_refnone

; ABSREF(ref_text, ref) - the R1C1 text read relative to ref's TOP-LEFT
; instead of the active cell. The text is evaluated TWICE, once to get past it
; to ref and again once ref is known, because ref's own evaluation can reuse
; sh_sacc - INPUT's idiom, and the text is nearly always a literal. It is
; parsed by shm_rangetext with the active cell swapped for ref's corner, so a
; relative part means exactly what it means everywhere else here
shm_mabsref:
    push si                           ; the text, for the second pass
    SHOUT sh_pcmp
    cmp byte [si], ','
    jne .badpop
    inc si
    call shm_mrangeref
    jnc .badpop
    mov di, si                        ; where ref ended
    pop si
    push di
    push word [sh_selcol]
    push word [sh_selrow]
    mov [sh_selcol], ax
    mov [sh_selrow], bx
    mov ah, 2
    call shm_textarg
    pop word [sh_selrow]              ; POP to memory: the flags and the four
    pop word [sh_selcol]              ; corners survive it
    pop si
    jnc .none
    jmp shm_refret
.badpop:
    pop di
    jmp shm_refbad
.none:
    jmp shm_refnone

; RELREF(ref, rel_to_ref) - ref as R1C1 text relative to rel_to_ref's
; top-left: RELREF(A1,C3) is "R[-2]C[-2]"
shm_mrelref:
    call shm_mrangeref
    jnc .bad
    push ax
    push bx
    push cx
    push dx
    cmp byte [si], ','
    jne .badpop
    inc si
    call shm_mrangeref                ; AX/BX the base
    jnc .badpop
    pop dx
    sub dx, bx
    pop cx
    sub cx, ax
    pop di
    sub di, bx
    mov bx, di
    pop di
    sub di, ax
    mov ax, di
    mov byte [cs:shm_rtform], 2
    jmp shm_rttext
.badpop:
    add sp, 8
.bad:
    jmp shm_refbad

; REFTEXT(ref[, a1]) - ref as ABSOLUTE text: "$C$3" when a1 is TRUE, "R3C3"
; when it is FALSE or omitted. Excel's names the sheet as well; this one has
; the one sheet a formula can see
shm_mreftext:
    call shm_mrangeref
    jnc .bad
    push ax
    push bx
    push cx
    push dx
    call shm_boolarg
    mov [cs:shm_rtform], al           ; 1 A1, 0 R1C1 - shm_rtone's numbering
    pop dx
    pop cx
    pop bx
    pop ax
    jmp shm_rttext
.bad:
    jmp shm_refbad

; TEXTREF(text[, a1]) - the reverse: text as A1 when a1 is TRUE, as R1C1 when
; it is FALSE or omitted - and only as that, so TEXTREF("B7",FALSE) is #REF!.
; A relative R1C1 part is relative to the active cell. Two passes over the
; text, for ABSREF's reason: a1 is evaluated between them
shm_mtextref:
    push si
    SHOUT sh_pcmp
    call shm_boolarg
    mov di, si
    pop si
    push di
    mov ah, al                        ; 1 A1, 0 R1C1 - shm_textarg's
    call shm_textarg
    pop si
    jnc .none
    jmp shm_refret
.none:
    jmp shm_refnone

; DEREF(ref) - the value of ref's top-left cell, and never the reference:
; SET.VALUE(DEREF(A1),..) writes to the cell A1 NAMES, if it names one
shm_mderef:
    call shm_mrangeref
    jnc .bad
    push ax
    push bx
    SHOUT sh_skipargs
    pop bx
    pop ax
    SHOUT sh_getcell2
    jc .out
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
.out:
    ret
.bad:
    jmp shm_refbad

; SELECTION() - the selection, all of it
shm_mselection:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    mov cx, [sh_selcol2]
    mov dx, [sh_selrow2]
    jmp shm_refret

; CALLER() - the cell whose formula called the running subroutine; #REF! in
; a macro the user started, which nothing called
shm_mcaller:
    cmp byte [cs:shm_csp], 0
    je .none
    push di
    call shm_ctop
    mov ax, [cs:di]
    mov bx, [cs:di+2]
    pop di
    mov cx, ax
    mov dx, bx
    jmp shm_refret
.none:
    jmp shm_refnone

; =============================================================================
; CONTROL (macro plan wave 2, 81.86): ECHO, ERROR, RESTART, STEP, CANCEL.KEY,
; DISABLE.INPUT, WAIT - and ALERT's type 1, which the Step dialog's answer
; path made cheap. Every setting here lasts as long as the run that made it
; (shm_mresume's start clears them all).
; =============================================================================
shm_echo:    db 1                     ; ECHO: repaint after a step that changed
shm_errmode: db 1                     ; ERROR: 0 ignore, 1 stop, 2 go to ref
shm_errcol:  dw 0
shm_errrow:  dw 0
shm_ckmode:  db 1                     ; CANCEL.KEY: 0 Esc ignored, 1 Esc
shm_ckcol:   dw 0                     ; single-steps, 2 Esc goes to ref
shm_ckrow:   dw 0
shm_escwas:  db 0                     ; Esc was down at the last look: a
                                       ; PRESS is the edge, not the level
shm_stepon:  db 0                     ; single-stepping
shm_stepgo:  db 0                     ; the dialog answered: 1 run this cell,
                                       ; 2 halt
shm_alpend:  db 0                     ; ALERT(.., 1) is waiting for its answer
shm_wtpend:  db 0                     ; WAIT is waiting, until shm_wtt
shm_wtt:     times 8 db 0

; shm_mesc - at the top of every step: was Esc pressed? The engine runs a
; whole macro inside one callback, so no key EVENT can reach it until the
; run pauses - it asks the keyboard's own state (OSAPI_KEY_DOWN) instead,
; and a WAIT's keystroke arrives as sh_macro_esc (sh_macro_gatek)
shm_mesc:
    push ax
    push bx
    mov al, KSC_ESC
    call OSAPI_KEY_DOWN               ; CF=1 down
    mov al, 0
    adc al, 0
    mov ah, [cs:shm_escwas]
    mov [cs:shm_escwas], al
    cmp byte [sh_macro_esc], 0
    jne .press
    cmp al, 1                         ; down now and up before: a press
    jne .out
    or ah, ah
    jnz .out
.press:
    mov byte [sh_macro_esc], 0
    cmp byte [cs:shm_ckmode], 0       ; CANCEL.KEY(FALSE): it cannot
    je .out
    cmp byte [cs:shm_wtpend], 0       ; a WAIT it interrupted is over
    je .nowait
    mov byte [cs:shm_wtpend], 0
    inc word [sh_macro_row]
.nowait:
    cmp byte [cs:shm_ckmode], 2
    je .goto
    mov byte [cs:shm_stepon], 1       ; Excel: Esc raises the Single Step
    mov byte [cs:shm_stepgo], 0       ; dialog - Step, Halt or Continue
    jmp short .out
.goto:
    mov ax, [cs:shm_ckcol]            ; CANCEL.KEY(TRUE, ref)
    mov [sh_macro_col], ax
    mov ax, [cs:shm_ckrow]
    mov [sh_macro_row], ax
.out:
    pop bx
    pop ax
    ret

; shm_stepmsg - the Single Step dialog's line into sh_macro_msg: "A2: =..."
; - the cell and its formula, clipped to what the alert shows
shm_stepmsg:
    push ax
    push cx
    push si
    push di
    mov di, sh_macro_msg
    mov ax, [sh_macro_col]
    SHOUT sh_colname
    mov si, sh_colbuf
    call shm_rtcat
    mov ax, [sh_macro_row]
    inc ax
    SHOUT sh_itoa
    mov si, sh_numbuf
    call shm_rtcat
    mov byte [di], ':'
    mov byte [di+1], ' '
    mov byte [di+2], '='
    add di, 3
    mov cx, di
    sub cx, sh_macro_msg
    neg cx
    add cx, OS88UI_AMAX               ; what is left of the line
    mov si, sh_macrobuf
.c:
    jcxz .e
    mov al, [si]
    or al, al
    jz .e
    mov [di], al
    inc si
    inc di
    dec cx
    jmp short .c
.e:
    mov byte [di], 0
    pop di
    pop si
    pop cx
    pop ax
    ret

; ECHO([logical]) - FALSE stops the repaint after each step that changed
; something; TRUE or omitted brings it back. The end of the run always paints
shm_mecho:
    mov byte [cs:shm_echo], 1
    call shm_boolarg0
    jnc .skip
    mov [cs:shm_echo], al
.skip:
    SHOUT sh_skipargs
    jmp shm_mtrue

; shm_boolarg0 - the FIRST argument as a logical, if there is one. out: CF=1
; AL = 1 true / 0 false; CF=0 omitted. SI past it
shm_boolarg0:
    cmp byte [si], ')'
    je .none
    cmp byte [si], ','
    je .none
    SHOUT sh_pcmp
    call shm_mtruth
    mov al, 0
    jnc .f
    inc al
.f:
    stc
    ret
.none:
    clc
    ret

; ERROR(enable[, ref]) - FALSE: a macro error is ignored and the run goes on.
; TRUE: the ordinary stop with a message, or - given ref - the run goes on
; from ref instead. Excel runs ref "whenever an error is encountered"; here
; that is a GOTO, since a call would come back to the failing cell and fail
; again
shm_merror:
    call shm_boolarg0
    jc .have
    mov al, 1                         ; omitted: TRUE
.have:
    or al, al
    jz .off
    cmp byte [si], ','
    jne .on
    inc si
    call shm_mref
    jnc .bad
    mov [cs:shm_errcol], ax
    mov [cs:shm_errrow], bx
    mov byte [cs:shm_errmode], 2
    jmp short .out
.on:
    mov byte [cs:shm_errmode], 1
    jmp short .out
.off:
    mov byte [cs:shm_errmode], 0
.out:
    SHOUT sh_skipargs
    jmp shm_mtrue
.bad:
    jmp shm_merr

; CANCEL.KEY([enable[, ref]]) - FALSE or omitted: Esc cannot interrupt the
; run. TRUE: it can - into the Single Step dialog, as Excel's Esc does, or
; given ref, by going on from ref
shm_mcancelkey:
    call shm_boolarg0
    jc .have
    xor al, al                        ; omitted: FALSE (the manual's own)
.have:
    mov byte [cs:shm_ckmode], 0
    or al, al
    jz .out
    mov byte [cs:shm_ckmode], 1
    cmp byte [si], ','
    jne .out
    inc si
    call shm_mref
    jnc .bad
    mov [cs:shm_ckcol], ax
    mov [cs:shm_ckrow], bx
    mov byte [cs:shm_ckmode], 2
.out:
    SHOUT sh_skipargs
    jmp shm_mtrue
.bad:
    jmp shm_merr

; DISABLE.INPUT(logical) - accepted, and already true of every run: while
; the engine steps, the run is one callback and no event can arrive; while it
; pauses, its dialog is modal and WAIT swallows everything but Esc
; (sh_macro_gate). Excel's reason for it - DDE - does not exist here
shm_mdisinput:
    SHOUT sh_skipargs
    jmp shm_mtrue

; RESTART([level]) - forget the return addresses above level, so that many
; RETURNs still go back and the next one ENDS the run (level 0, the
; default). Only the addresses: what the dropped frames hold stays committed
; until the run ends, since the running cell may still read its arguments
shm_mrestart:
    xor ax, ax
    call shm_intarg1
    jc .bad
    or ax, ax
    js .bad
    cmp al, [cs:shm_csp]
    jae .out
    mov [cs:shm_csp], al
    inc word [sh_pass]                ; bindings in view changed: 81.84.3
.out:
    SHOUT sh_skipargs
    jmp shm_mtrue
.bad:
    jmp shm_merr

; shm_intarg1 - the FIRST argument as an integer. in AX = what an omitted
; one is worth. out: AX; CF=1 when it is there and not a number
shm_intarg1:
    cmp byte [si], ')'
    je .dflt
    cmp byte [si], ','
    je .dflt
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .bad
    cmp byte [sh_curtype], SH_T_TEXT
    je .bad
    SHOUT sh_acc_toint
    ret
.bad:
    stc
    ret
.dflt:
    clc
    ret

; STEP() - single-step from the next cell on (the dialog: Step runs the
; cell, Halt ends the run, Continue runs on without stepping)
shm_mstepfn:
    SHOUT sh_skipargs
    mov byte [cs:shm_stepon], 1
    mov byte [cs:shm_stepgo], 0
    jmp shm_mtrue

; WAIT(serial_number) - pause until that date and time. A callback cannot
; sleep (it holds the gfx lock, and the whole desktop with it), so WAIT is a
; PAUSE: the engine returns, a half-second OSAPI_WM_TIMER brings it back to
; this same cell, and the cell looks at the clock again. The time is BANKED
; on the first evaluation - WAIT(NOW()+x) evaluated again would move its own
; target - and the second and later evaluations do not read the argument.
; On a machine with no timer (kern_small) or no clock, it does not wait
shm_mwait:
    cmp byte [cs:shm_wtpend], 0
    jne .again
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .bad
    cmp byte [sh_curtype], SH_T_TEXT
    je .bad
    push si
    push di
    mov si, sh_acc
    mov di, shm_wtt
    mov cx, 8
.bank:
    mov al, [si]
    mov [cs:di], al
    inc si
    inc di
    loop .bank
    pop di
    pop si
    mov byte [cs:shm_wtpend], 1
.again:
    SHOUT sh_skipargs
    SHOUT sh_pnow                     ; sh_acc = now; CF=1 no clock
    jc .done
    push si
    push di
    SHOUT sh_acc_load_a               ; A = now
    mov si, shm_wtt                   ; B = the target, through DS scratch
    mov di, sh_macro_tend             ; (fp_unpack_b reads DS)
    mov cx, 8
.cp:
    mov al, [cs:si]
    mov [di], al
    inc si
    inc di
    loop .cp
    mov si, sh_macro_tend
    SHOUT fp_unpack_b
    SHOUT fp_cmpab                    ; AX = -1/0/1, now against the target
    pop di
    pop si
    cmp ax, 0
    jge .done
    mov ax, 9                         ; half a second: the RTC's own grain
    SHOUT sh_macro_arm                ; is one, and Esc is heard at once
    jc .done
    dec word [sh_macro_steps]         ; a look at the clock is not a step
    mov byte [sh_macro_ctl], SH_MC_WAITT
    jmp shm_mfalse
.done:
    mov byte [cs:shm_wtpend], 0
    mov byte [sh_evalerr], 0
    jmp shm_mtrue
.bad:
    jmp shm_merr

; =============================================================================
; INFORMATION (macro plan wave 2, 81.87): GET.CELL, GET.FORMULA, GET.NAME,
; GET.DEF, GET.NOTE, NAMES, GET.DOCUMENT, GET.WINDOW, GET.WORKSPACE and
; DIRECTORY. Every one is a VALUE: it answers wherever it is evaluated.
;
; Most of the numbered tables are constants here - a SHEET document is always
; a worksheet, it has one window, no password - so the four GET.* tables are
; DATA, three bytes a row, read by one interpreter (shm_ginfo), and only the
; rows that look something up have code.
; =============================================================================
GI_NUM  equ 0                         ; the word is the number
GI_BOOL equ 1                         ; ...the logical
GI_BVAR equ 2                         ; ...a DS byte: nonzero is TRUE
GI_NA   equ 3                         ; #N/A: SHEET does not keep this
GI_STR  equ 4                         ; ...a CS string
GI_FN   equ 5                         ; ...a routine, which answers

shm_gcol:  dw 0                       ; the cell GET.CELL/GET.NOTE is about
shm_grow:  dw 0
shm_gmask: db 0
shm_gst:   dw 0                       ; GET.NOTE's start and count
shm_gcnt:  dw 0

; shm_anum - answer AX, a signed integer
shm_anum:
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    ret

; shm_abool - answer AL as a logical
shm_abool:
    or al, al
    jz .f
    jmp shm_mtrue
.f:
    jmp shm_mfalse

; shm_aerr - answer the error AL (unless one is already the answer)
shm_aerr:
    cmp byte [sh_evalerr], 0
    jne .have
    mov [sh_evalerr], al
.have:
    xor ax, ax
    jmp shm_anum
shm_ana:
    mov al, SH_ERR_NA
    jmp short shm_aerr

; shm_astr / shm_acstr - answer the NUL string at DS:BX / CS:BX as TEXT,
; clipped to what a text value holds.
;
; BX AND NOT SI, AND THAT IS THE WHOLE POINT: SI is the EVALUATOR'S PARSE
; POINTER, and every function answers with it just past its ')'. These took
; the string in SI when they were written, and each caller pointed SI at its
; answer and jumped here - so the parse resumed INSIDE THE ANSWER. It passed
; for "General" (a letter ends an expression) and failed for GET.CELL(6) of
; a formula cell: "=C3*2" read as the comparison operator, and the answer
; came back as the logical FALSE (81.87.3)
shm_acstr:
    push di
    push bx
    push cx
    mov di, sh_sacc
    mov cx, SH_STR_MAX
.c:
    mov al, [cs:bx]
    or al, al
    jz shm_astr.e
    mov [di], al
    inc bx
    inc di
    loop .c
    jmp short shm_astr.e
shm_astr:
    push di
    push bx
    push cx
    mov di, sh_sacc
    mov cx, SH_STR_MAX
.c:
    mov al, [bx]
    or al, al
    jz .e
    mov [di], al
    inc bx
    inc di
    loop .c
.e:
    mov byte [di], 0
    pop cx
    pop bx
    pop di
shm_atext:                            ; sh_sacc is already the answer
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_TEXT
    ret

; shm_ginfo - answer row AX (1-based) of the table at CS:SI, CX rows long:
; three bytes a row, a GI_* kind and a word. Past the end is #VALUE!
shm_ginfo:
    dec ax
    cmp ax, cx
    jae .bad
    mov bx, ax
    shl ax, 1
    add ax, bx
    add si, ax
    mov al, [cs:si]
    mov bx, [cs:si+1]
    cmp al, GI_NUM
    jne .n1
    mov ax, bx
    jmp shm_anum
.n1:
    cmp al, GI_BOOL
    jne .n2
    mov al, bl
    jmp shm_abool
.n2:
    cmp al, GI_BVAR
    jne .n3
    mov al, [bx]
    jmp shm_abool
.n3:
    cmp al, GI_NA
    je shm_ana
    cmp al, GI_STR
    jne .n5
    jmp shm_acstr                     ; BX is the string
.n5:
    jmp bx                            ; GI_FN
.bad:
    mov al, SH_ERR_VALUE
    jmp shm_aerr

; shm_typearg - the type_num first argument, then an optional reference
; (the active cell when it is omitted) into shm_gcol/shm_grow, and past the
; rest. out: AX = the type; CF=1 on a bad argument, already answered #VALUE!
shm_typearg:
    xor ax, ax
    call shm_intarg1
    jc .bad
    push ax
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    cmp byte [si], ','
    jne .have
    inc si
    cmp byte [si], ')'
    je .have
    call shm_mrangeref
    jnc .badpop
.have:
    mov [cs:shm_gcol], ax
    mov [cs:shm_grow], bx
    SHOUT sh_skipargs
    pop ax
    clc
    ret
.badpop:
    pop ax
.bad:
    call shm_refbad
    stc
    ret

; GET.CELL(type_num[, ref]) - 23 facts about ref's top-left cell
shm_mgetcell:
    call shm_typearg
    jc .out
    push si                           ; the parse pointer: ginfo walks the
    mov si, shm_gctab                 ; table with it
    mov cx, 23
    call shm_ginfo
    pop si
    ret
.out:
    ret
shm_gctab:
    db GI_FN
    dw shm_gc_ref                     ; 1 the reference, "$C$3"
    db GI_FN
    dw shm_gc_row                     ; 2 its row
    db GI_FN
    dw shm_gc_col                     ; 3 its column
    db GI_FN
    dw shm_gc_type                    ; 4 TYPE()
    db GI_FN
    dw shm_gc_val                     ; 5 its contents
    db GI_FN
    dw shm_gc_form                    ; 6 its formula, as text
    db GI_FN
    dw shm_gc_nf                      ; 7 its number format, as text
    db GI_FN
    dw shm_gc_align                   ; 8 alignment, 1 General .. 4 Right
    db GI_FN
    dw shm_gc_bl                      ; 9-13 left, right, top and bottom
    db GI_FN                          ; border, and the shade
    dw shm_gc_br
    db GI_FN
    dw shm_gc_bt
    db GI_FN
    dw shm_gc_bb
    db GI_FN
    dw shm_gc_bs
    db GI_FN
    dw shm_gc_lock                    ; 14 locked
    db GI_FN
    dw shm_gc_hide                    ; 15 hidden
    db GI_FN
    dw shm_gc_cw                      ; 16 column width, characters
    db GI_FN
    dw shm_gc_rh                      ; 17 row height, points
    db GI_STR
    dw shm_s_helv                     ; 18 the font - the one BIFF writes
    db GI_NUM
    dw 10                             ; 19 ...and its size
    db GI_FN
    dw shm_gc_bold                    ; 20 bold
    db GI_BOOL
    dw 0                              ; 21 italic: SHEET draws none
    db GI_FN
    dw shm_gc_under                   ; 22 underlined
    db GI_BOOL
    dw 0                              ; 23 struck out: none either
shm_s_helv: db 'Helv', 0

shm_gc_ld:                            ; AX/BX = the cell
    mov ax, [cs:shm_gcol]
    mov bx, [cs:shm_grow]
    ret
shm_gc_ref:
    call shm_gc_ld
    mov cx, ax
    mov dx, bx
    mov byte [cs:shm_rtform], 1
    push di
    mov di, sh_sacc
    call shm_rtans
    pop di
    ret
shm_gc_row:
    mov ax, [cs:shm_grow]
    inc ax
    jmp shm_anum
shm_gc_col:
    mov ax, [cs:shm_gcol]
    inc ax
    jmp shm_anum
shm_gc_type:
    call shm_gc_ld
    SHOUT sh_getcell2
    mov ax, 1                         ; empty: a number, the 0 it reads as
    jnc .have
    mov al, [sh_curtype]
    cmp byte [sh_evalerr], 0
    jne .err
    cmp al, SH_T_ERR
    je .err
    cmp al, SH_T_TEXT
    mov ax, 2
    je .have
    cmp byte [sh_curtype], SH_T_BOOL
    mov ax, 4
    je .have
    mov ax, 1
    jmp short .have
.err:
    mov byte [sh_evalerr], 0
    mov ax, 16
.have:
    jmp shm_anum
shm_gc_val:
    call shm_gc_ld
    SHOUT sh_getcell2
    jc .out
    xor ax, ax
    jmp shm_anum
.out:
    ret
shm_gc_form:
    call shm_gc_ld
    SHOUT sh_cell_totext
    mov bx, sh_clipbuf
    jmp shm_astr
shm_gc_nf:
    call shm_gc_ld
    SHOUT sh_cell_nfid
    xor ah, ah
    mov bx, ax
    shl bx, 1
    mov bx, [bx + sh_nf_codes]        ; the resident table, through DS
    jmp shm_astr
shm_gc_fmt:                           ; AL = the cell's format byte
    call shm_gc_ld
    SHOUT sh_getcell2                 ; sets sh_curfmt, empty or not
    mov al, [sh_curfmt]
    ret
shm_gc_align:
    call shm_gc_fmt
    and al, SH_FMT_ALIGN_MASK
    shr al, 1
    shr al, 1
    inc al
    xor ah, ah
    jmp shm_anum
shm_gc_bold:
    call shm_gc_fmt
    and al, SH_FMT_BOLD
    jmp shm_abool
shm_gc_under:
    call shm_gc_fmt
    and al, SH_FMT_UNDER
    jmp shm_abool
shm_gc_bl:
    mov byte [cs:shm_gmask], SH_BORD_LEFT
    jmp short shm_gc_bord
shm_gc_br:
    mov byte [cs:shm_gmask], SH_BORD_RIGHT
    jmp short shm_gc_bord
shm_gc_bt:
    mov byte [cs:shm_gmask], SH_BORD_TOP
    jmp short shm_gc_bord
shm_gc_bb:
    mov byte [cs:shm_gmask], SH_BORD_BOTTOM
    jmp short shm_gc_bord
shm_gc_bs:
    mov byte [cs:shm_gmask], SH_BORD_SHADE
    jmp short shm_gc_bord
shm_gc_hide:
    mov byte [cs:shm_gmask], SH_PROT_HIDDEN
shm_gc_bord:
    call shm_gc_ld
    SHOUT sh_bt_get                   ; AL = the border/protection byte
    and al, [cs:shm_gmask]
    jmp shm_abool
shm_gc_lock:                          ; stored INVERTED: no record is locked
    call shm_gc_ld
    SHOUT sh_bt_get
    and al, SH_PROT_UNLOCK
    xor al, SH_PROT_UNLOCK
    jmp shm_abool
shm_gc_cw:
    mov ax, [cs:shm_gcol]
    SHOUT sh_colwidth
    jmp shm_anum
shm_gc_rh:                            ; twips / 20, and 0 is the standard
    mov ax, [cs:shm_grow]
    SHOUT sh_rowtw
    or ax, ax
    jnz .have
    mov ax, SH_RH_STDTW
.have:
    SHOUT fp_i2a
    mov ax, 20
    SHOUT fp_i2b
    SHOUT fp_div
    SHOUT sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    ret

; GET.FORMULA(ref) - the top-left cell as the formula bar shows it, and a
; formula's references in R1C1, as Excel gives them: "=RC[-1]*(1+R1C1)"
shm_mgetformula:
    call shm_mrangeref
    jc .ref
    jmp shm_refbad
.ref:
    push ax
    push bx
    SHOUT sh_skipargs
    pop bx
    pop ax
    push si                           ; the parse pointer
    SHOUT sh_cell_totext              ; "=..." for a formula
    mov si, sh_clipbuf
    cmp byte [si], '='
    jne .plain
    mov [sh_rc_ccol], ax
    mov [sh_rc_crow], bx
    inc si
    CHOUT SHM_TOR1C1           ; -> sh_rwdst, [sh_rw_di] long
    mov bx, [sh_rw_di]
    mov byte [sh_rwdst + bx], 0
    mov byte [sh_clipbuf], '='
    mov si, sh_rwdst
    mov di, sh_clipbuf + 1
.cp:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .cp
.plain:
    pop si
    mov bx, sh_clipbuf
    jmp shm_astr

; shm_textname - the TEXT argument at SI, uppercased into sh_ident (a
; leading '!' - Excel's "this document" - dropped), and past the rest.
; CF=1 not text, already answered #VALUE!
shm_textname:
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT
    jne .bad
    push si
    push di
    push cx
    mov si, sh_sacc
    cmp byte [si], '!'
    jne .go
    inc si
.go:
    mov di, sh_ident
    mov cx, SH_IDENT_MAX
.c:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    mov [di], al
    or al, al
    jz .e
    inc si
    inc di
    loop .c
    mov byte [di], 0
.e:
    pop cx
    pop di
    pop si
    SHOUT sh_skipargs
    clc
    ret
.bad:
    call shm_refbad
    stc
    ret

; GET.NAME(name_text) - the name's definition as the Define Name dialog
; shows it, in R1C1: "=R1C1:R500C6". A name here is always a place
shm_mgetname:
    call shm_textname
    jc .out
    push si
    mov si, sh_ident
    SHOUT sh_name_lookup              ; AX/BX .. CX/DX
    pop si
    jnc .none
    mov byte [sh_sacc], '='
    mov byte [cs:shm_rtform], 0
    push di
    mov di, sh_sacc + 1
    call shm_rtans
    pop di
.out:
    ret
.none:
    mov al, SH_ERR_NAME
    jmp shm_aerr

; GET.DEF(def_text) - the reverse: the FIRST name whose definition is
; def_text ("=R1C1", "R1C1", or A1), in the order the names were defined
shm_mgetdef:
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT
    jne .bad
    SHOUT sh_skipargs
    push si
    mov si, sh_sacc
    cmp byte [si], '='
    jne .p
    inc si
.p:
    call shm_rangetext                ; AX/BX .. CX/DX
    jnc .nonepop
    mov [cs:shm_gcol], cx             ; the far corner, while the loop
    mov [cs:shm_grow], dx             ; needs CX and DX
    mov si, sh_names
    mov cx, [sh_nnames]
    jcxz .nonepop
.n:
    cmp ax, [si + SH_NAME_MAX + 1]
    jne .next
    cmp bx, [si + SH_NAME_MAX + 3]
    jne .next
    mov dx, [cs:shm_gcol]
    cmp dx, [si + SH_NAME_MAX + 5]
    jne .next
    mov dx, [cs:shm_grow]
    cmp dx, [si + SH_NAME_MAX + 7]
    jne .next
    mov bx, si                        ; the record starts with its name
    call shm_astr
    pop si
    ret
.next:
    add si, SH_NAME_REC
    loop .n
.nonepop:
    pop si
    mov al, SH_ERR_NAME
    jmp shm_aerr
.bad:
    jmp shm_refbad

; GET.NOTE(ref[, start[, count]]) - count characters of ref's note from
; start (1-based); the whole note when count is omitted, "" when there is
; none. A text value holds SH_STR_MAX, a note SH_NOTEMAX: the rest is cut
shm_mgetnote:
    call shm_mrangeref
    jc .ref
    jmp shm_refbad
.ref:
    mov [cs:shm_gcol], ax
    mov [cs:shm_grow], bx
    mov ax, 1
    call shm_intarg
    jc .bad
    cmp ax, 1
    jl .bad
    mov [cs:shm_gst], ax
    mov ax, SH_STR_MAX
    call shm_intarg
    jc .bad
    or ax, ax
    js .bad
    mov [cs:shm_gcnt], ax
    SHOUT sh_skipargs
    mov byte [sh_sacc], 0
    call shm_gc_ld
    SHOUT sh_nt_get                   ; AX = the note, in the text arena
    jnc .done
    push es
    push si
    push di
    push cx
    mov es, [sh_txtseg]
    mov si, ax
    mov cx, [cs:shm_gst]
.skip:
    dec cx
    jz .take
    cmp byte [es:si], 0
    je .take
    inc si
    jmp short .skip
.take:
    mov di, sh_sacc
    mov cx, [cs:shm_gcnt]
    cmp cx, SH_STR_MAX
    jbe .c
    mov cx, SH_STR_MAX
.c:
    jcxz .e
    mov al, [es:si]
    or al, al
    jz .e
    mov [di], al
    inc si
    inc di
    dec cx
    jmp short .c
.e:
    mov byte [di], 0
    pop cx
    pop di
    pop si
    pop es
.done:
    jmp shm_atext
.bad:
    jmp shm_refbad

; NAMES([doc]) - the names, as a horizontal array in Excel. SHEET has no
; array values, so it answers the array's FIRST element, which is what
; Excel shows in a single cell too (81.67's rule); #N/A when there are none
shm_mnames:
    SHOUT sh_skipargs
    cmp word [sh_nnames], 0
    je .none
    mov bx, sh_names
    jmp shm_astr
.none:
    jmp shm_ana

; GET.DOCUMENT(type_num[, name]) - the document. name is accepted and not
; read: SHEET has one document an instance
shm_mgetdoc:
    xor ax, ax
    call shm_intarg1
    jc .bad
    push ax
    SHOUT sh_skipargs
    pop ax
    push si                           ; the parse pointer: ginfo walks the
    mov si, shm_gdtab                 ; table with it
    mov cx, 26
    call shm_ginfo
    pop si
    ret
.bad:
    jmp shm_refbad
shm_gdtab:
    db GI_FN
    dw shm_gd_name                    ; 1 its name
    db GI_NA
    dw 0                              ; 2 its directory, as a path: the file
                                       ; system names a folder by CLUSTER
    db GI_NUM
    dw 1                              ; 3 a worksheet
    db GI_NA
    dw 0                              ; 4 changed since saved: not kept
    db GI_BOOL
    dw 0                              ; 5 read-only
    db GI_BOOL
    dw 0                              ; 6 password
    db GI_BVAR
    dw sh_protected                   ; 7 contents protected
    db GI_BOOL
    dw 0                              ; 8 windows protected
    db GI_FN
    dw shm_gd_r1                      ; 9-12 first and last used row and
    db GI_FN                          ; column, 0 for an empty sheet
    dw shm_gd_r2
    db GI_FN
    dw shm_gd_c1
    db GI_FN
    dw shm_gd_c2
    db GI_NUM
    dw 1                              ; 13 windows
    db GI_FN
    dw shm_gd_calc                    ; 14 1 automatic, 3 manual
    db GI_BOOL
    dw 0                              ; 15 iteration: SHEET has none
    db GI_NUM
    dw 100                            ; 16-17 ...and the dialog's defaults
    db GI_FN
    dw shm_gd_maxch
    db GI_BOOL
    dw 0                              ; 18 remote references
    db GI_BOOL
    dw 0                              ; 19 precision as displayed
    db GI_BOOL
    dw 0                              ; 20 the 1904 system
    db GI_STR
    dw shm_s_helv                     ; 21-26 the fonts, as arrays in Excel:
    db GI_NUM                         ; the first element, font 1
    dw 10
    db GI_BOOL
    dw 0
    db GI_BOOL
    dw 0
    db GI_BOOL
    dw 0
    db GI_BOOL
    dw 0

shm_gd_name:
    cmp byte [sh_name], 0
    je .none
    mov bx, sh_name
    jmp shm_astr
.none:
    jmp shm_ana
shm_gd_calc:
    ; GET.DOCUMENT(14): 1 Automatic, 2 Automatic except tables, 3 Manual -
    ; which is 81.114.8's mode plus one, exactly. This used to answer 1 or 3
    ; and had no way to say the middle one, the mode not existing yet.
    xor ah, ah
    mov al, [sh_calcmode]
    inc ax
    jmp shm_anum
shm_gd_maxch:                         ; 0.001
    mov ax, 1
    SHOUT fp_i2a
    mov ax, 1000
    SHOUT fp_i2b
    SHOUT fp_div
    SHOUT sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    ret
shm_gd_r1:
    call shm_extent
    mov ax, [cs:shm_ext_r1]
    jmp shm_anum
shm_gd_r2:
    call shm_extent
    mov ax, [cs:shm_ext_r2]
    jmp shm_anum
shm_gd_c1:
    call shm_extent
    mov ax, [cs:shm_ext_c1]
    jmp shm_anum
shm_gd_c2:
    call shm_extent
    mov ax, [cs:shm_ext_c2]
    jmp shm_anum

shm_ext_r1: dw 0
shm_ext_r2: dw 0
shm_ext_c1: dw 0
shm_ext_c2: dw 0
; shm_extent - the current sheet's used rows and columns, 1-based, into the
; four words above; all 0 for an empty sheet. Every cell record counts - a
; formatted blank is "used" in Excel as well
shm_extent:
    push ax
    push bx
    push cx
    push si
    push es
    mov word [cs:shm_ext_r1], 0xFFFF
    mov word [cs:shm_ext_c1], 0xFFFF
    mov word [cs:shm_ext_r2], 0
    mov word [cs:shm_ext_c2], 0
    mov cx, [sh_ncells]
    xor si, si
    jcxz .done
.l:
    mov es, [sh_cellseg]
    mov ax, [es:si + SH_C_ROW]
    SHOUT sh_unpackrow                ; AX the row, BX its sheet
    cmp bx, [sh_cursheet]
    jne .next
    inc ax
    cmp ax, [cs:shm_ext_r1]
    jae .r1
    mov [cs:shm_ext_r1], ax
.r1:
    cmp ax, [cs:shm_ext_r2]
    jbe .r2
    mov [cs:shm_ext_r2], ax
.r2:
    mov es, [sh_cellseg]
    mov ax, [es:si + SH_C_COL]
    inc ax
    cmp ax, [cs:shm_ext_c1]
    jae .c1
    mov [cs:shm_ext_c1], ax
.c1:
    cmp ax, [cs:shm_ext_c2]
    jbe .next
    mov [cs:shm_ext_c2], ax
.next:
    add si, SH_C_SZ
    loop .l
.done:
    cmp word [cs:shm_ext_r2], 0
    jne .out
    mov word [cs:shm_ext_r1], 0       ; empty: every one is 0
    mov word [cs:shm_ext_c1], 0
.out:
    pop es
    pop si
    pop cx
    pop bx
    pop ax
    ret

; GET.WINDOW(type_num[, name]) - the window. Positions and sizes are in
; PIXELS: the screen has no points
shm_mgetwin:
    xor ax, ax
    call shm_intarg1
    jc .bad
    push ax
    SHOUT sh_skipargs
    pop ax
    push si                           ; the parse pointer: ginfo walks the
    mov si, shm_gwtab                 ; table with it
    mov cx, 16
    call shm_ginfo
    pop si
    ret
.bad:
    jmp shm_refbad
shm_gwtab:
    db GI_FN
    dw shm_gd_name                    ; 1 the document in it
    db GI_NUM
    dw 1                              ; 2 its number
    db GI_FN
    dw shm_gw_x                       ; 3-6 x, y, width, height
    db GI_FN
    dw shm_gw_y
    db GI_FN
    dw shm_gw_w
    db GI_FN
    dw shm_gw_h
    db GI_BOOL
    dw 0                              ; 7 hidden
    db GI_BVAR
    dw sh_showformulas                ; 8 formulas displayed
    db GI_BVAR
    dw sh_gridlines                   ; 9 gridlines
    db GI_BOOL
    dw 1                              ; 10 headings
    db GI_BOOL
    dw 1                              ; 11 zero values
    db GI_NUM
    dw 0                              ; 12 gridline colour: Automatic
    db GI_FN
    dw shm_gw_c1                      ; 13-16 the edges of the (first) pane
    db GI_FN
    dw shm_gw_r1
    db GI_FN
    dw shm_gw_c2
    db GI_FN
    dw shm_gw_r2
shm_gw_x:
    mov bx, W_X
    jmp short shm_gw_rec
shm_gw_y:
    mov bx, W_Y
    jmp short shm_gw_rec
shm_gw_w:
    mov bx, W_W
    jmp short shm_gw_rec
shm_gw_h:
    mov bx, W_H
shm_gw_rec:                           ; BX = the field in the window record
    push es
    mov ax, KERNEL_SEG                ; the record is the kernel's
    mov es, ax
    add bx, [sh_ownwin]
    mov ax, [es:bx]
    pop es
    jmp shm_anum
shm_gw_c1:
    mov ax, [sh_scrollcol]
    inc ax
    jmp shm_anum
shm_gw_r1:
    mov ax, [sh_scrollrow]
    inc ax
    jmp shm_anum
shm_gw_c2:
    mov ax, [sh_scrollcol]
    add ax, [sh_vcols]
    jmp shm_anum
shm_gw_r2:
    mov ax, [sh_scrollrow]
    add ax, [sh_vrows]
    jmp shm_anum

; GET.WORKSPACE(type_num)
shm_mgetws:
    xor ax, ax
    call shm_intarg1
    jc .bad
    push ax
    SHOUT sh_skipargs
    pop ax
    push si                           ; the parse pointer: ginfo walks the
    mov si, shm_gstab                 ; table with it
    mov cx, 19
    call shm_ginfo
    pop si
    ret
.bad:
    jmp shm_refbad
shm_gstab:
    db GI_STR
    dw shm_s_env                      ; 1 the environment
    db GI_STR
    dw shm_s_ver                      ; 2 the version: the Excel SHEET is
    db GI_NUM                         ; modelled on, which is what a macro
    dw 0                              ; that asks means to test. 3 auto-
    db GI_BVAR                        ; decimal: none
    dw sh_a1style                     ; 4 R1C1
    db GI_BOOL
    dw 1                              ; 5-7 scroll bars, status bar and
    db GI_BOOL                        ; formula bar are always shown
    dw 1
    db GI_BOOL
    dw 1
    db GI_BOOL
    dw 0                              ; 8 remote requests
    db GI_NA
    dw 0                              ; 9 the alternate menu key: none
    db GI_NUM
    dw 0                              ; 10 no special mode
    db GI_NUM
    dw 0                              ; 11-12 the application window is the
    db GI_NUM                         ; screen
    dw 0
    db GI_FN
    dw shm_gs_w                       ; 13-14 the usable workspace
    db GI_FN
    dw shm_gs_h
    db GI_NUM
    dw 1                              ; 15 neither maximized nor minimized
    db GI_FN
    dw shm_gs_mem                     ; 16 free memory, KB
    db GI_NA
    dw 0                              ; 17 "available to Excel": no such sum
    db GI_FN
    dw shm_gs_fpu                     ; 18 a coprocessor, and in use
    db GI_BOOL
    dw 1                              ; 19 a mouse: the desktop needs one
shm_s_env: db 'OS/8088', 0
shm_s_ver: db '2.1', 0
shm_gs_w:
    call OSAPI_VIDEO                  ; AX = width, BX = height, CX = the
    jmp shm_anum                      ; dock's first row
shm_gs_h:
    call OSAPI_VIDEO
    mov ax, cx
    sub ax, MBAR_H
    jmp shm_anum
shm_gs_mem:
    call OSAPI_MEM_AVAIL              ; BX = total free KB
    mov ax, bx
    jmp shm_anum
shm_gs_fpu:
    mov al, [fp_hw]
    jmp shm_abool

; DIRECTORY([path_text]) - move this instance's current folder to path_text
; and answer it, or answer where it stands. THE FILE SYSTEM NAMES A FOLDER BY
; ITS CLUSTER, NOT BY A PATH, so the text is SHEET's own: the path the last
; DIRECTORY walked, kept with the cluster it arrived at, and trusted only
; while the instance still stands there (a file dialog may have moved it).
; Otherwise the root answers "B:\" and anything else #N/A. A path is walked a
; folder at a time with OSAPI_FILE_FIND and OSAPI_FILE_GOTO_QM; ".." is not
; walked (a folder does not know its parent here either), and a failed walk
; puts the instance back where it was
shm_dirtxt:  times SH_STR_MAX + 1 db 0 ; the known path, "" = none
shm_dirclu:  dw 0                     ; ...and where it was true
shm_dirdrv:  db 0
shm_dnew:    times SH_STR_MAX + 1 db 0 ; the path being walked
shm_dhere:   dw 0                     ; where the walk started, to go back
shm_dhdrv:   db 0

shm_mdirectory:
    cmp byte [si], ')'
    je .query
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT
    jne .bad
    SHOUT sh_skipargs
    call shm_dirwalk
    jnc .answer
    mov al, SH_ERR_VALUE
    jmp shm_aerr
.query:
    SHOUT sh_skipargs
.answer:
    push dx
    push bx
    call OSAPI_FILE_HERE              ; DX = the folder, BL = the drive
    cmp byte [cs:shm_dirtxt], 0
    je .root
    cmp dx, [cs:shm_dirclu]
    jne .root
    cmp bl, [cs:shm_dirdrv]
    jne .root
    pop bx
    pop dx
    mov bx, shm_dirtxt
    jmp shm_acstr
.root:
    or dx, dx
    jnz .na
    mov al, bl
    add al, 'A'
    mov [sh_sacc], al
    mov word [sh_sacc + 1], ':' + ('\' << 8)
    mov byte [sh_sacc + 3], 0
    pop bx
    pop dx
    jmp shm_atext
.na:
    pop bx
    pop dx
    jmp shm_ana
.bad:
    jmp shm_refbad

; shm_dirwalk - walk to the path in sh_sacc. CF=1 it could not be, and the
; instance is back where it started
shm_dirwalk:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    push ds
    pop es                            ; FILE_FIND fills ES:DI - ours
    call OSAPI_FILE_HERE
    mov [cs:shm_dhere], dx
    mov [cs:shm_dhdrv], bl
    mov si, sh_sacc
    mov al, [si]                      ; "X:" names the drive
    and al, 0xDF
    cmp al, 'A'
    jb .nodrive
    cmp al, 'Z'
    ja .nodrive
    cmp byte [si+1], ':'
    jne .nodrive
    sub al, 'A'
    mov bl, al
    add si, 2
.nodrive:
    mov di, shm_dnew                  ; the text starts "X:\"
    mov al, bl
    add al, 'A'
    mov [cs:di], al
    mov word [cs:di+1], ':' + ('\' << 8)
    add di, 3
    cmp byte [si], '\'
    jne .rel
    inc si
    xor dx, dx                        ; absolute: from the root
    call shm_dgoto
    jc .fail
    jmp short .comp
.rel:                                 ; relative: only from a place whose
    cmp bl, [cs:shm_dhdrv]            ; path is known
    jne .fail
    mov dx, [cs:shm_dhere]
    or dx, dx
    jz .comp                          ; the root is "X:\"
    cmp byte [cs:shm_dirtxt], 0
    je .fail
    cmp dx, [cs:shm_dirclu]
    jne .fail
    push si
    mov si, shm_dirtxt
    mov di, shm_dnew
.kc:
    mov al, [cs:si]
    mov [cs:di], al
    inc si
    inc di
    or al, al
    jnz .kc
    dec di
    pop si
.comp:                                ; one folder name at a time
    cmp byte [si], 0
    je .ok
    cmp byte [si], '\'
    jne .name
    inc si
    jmp short .comp
.name:
    push di
    mov di, sh_ident                  ; the name, uppercased
    xor cx, cx
.g:
    mov al, [si]
    or al, al
    jz .gend
    cmp al, '\'
    je .gend
    cmp al, '.'                       ; ".." - and any name starting with a
    jne .gu                           ; dot - is not walked
    or cx, cx
    jz .gbad
.gu:
    cmp al, 'a'
    jb .gs
    cmp al, 'z'
    ja .gs
    sub al, 32
.gs:
    cmp cx, 12
    jae .gbad
    mov [di], al
    inc di
    inc si
    inc cx
    jmp short .g
.gbad:
    pop di
    jmp .fail
.gend:
    mov byte [di], 0
    pop di
    call shm_dfind                    ; DX = its cluster
    jc .fail
    call shm_dgoto
    jc .fail
    cmp byte [cs:di-1], '\'           ; "X:\A" then "X:\A\B"
    je .app
    mov byte [cs:di], '\'
    inc di
.app:
    push si
    mov si, sh_ident
.ac:
    mov al, [si]
    or al, al
    jz .ae
    cmp di, shm_dnew + SH_STR_MAX
    jae .ae
    mov [cs:di], al
    inc si
    inc di
    jmp short .ac
.ae:
    pop si
    jmp .comp
.ok:
    mov byte [cs:di], 0
    mov si, shm_dnew                  ; the walk's text is the known one now
    mov di, shm_dirtxt
.kk:
    mov al, [cs:si]
    mov [cs:di], al
    inc si
    inc di
    or al, al
    jnz .kk
    mov [cs:shm_dirclu], dx
    mov [cs:shm_dirdrv], bl
    clc
    jmp short .out
.fail:
    mov dx, [cs:shm_dhere]            ; back where it was
    mov bl, [cs:shm_dhdrv]
    call shm_dgoto
    stc
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; shm_dgoto - stand the instance at DX (a folder's cluster, 0 the root) on
; drive BL. CF=1 refused. CX, SI and DI are banked: on a redirected volume
; the driver owns them (OSAPI_FILE_GOTO_Q's own warning)
shm_dgoto:
    push ax
    push cx
    push si
    push di
    call OSAPI_FILE_GOTO_QM
    pop di
    pop si
    pop cx
    pop ax
    ret

; shm_dfind - the folder named sh_ident where the instance stands. out: CF=0
; DX = its cluster; CF=1 there is none
shm_dfind:
    push ax
    push cx
    push si
    push di
    xor cx, cx
.l:
    mov di, sh_clipbuf                ; OSAPI_FIND_SZ bytes, ES = DS
    call OSAPI_FILE_FIND              ; CX = the next ordinal
    jc .no
    cmp word [sh_clipbuf + 14], OSAPI_FT_DIR
    jne .l
    mov si, sh_clipbuf
    mov di, sh_ident
.c:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    cmp al, [di]
    jne .l
    or al, al
    jz .yes
    inc si
    inc di
    jmp short .c
.yes:
    mov dx, [sh_clipbuf + 16]
    clc
    jmp short .out
.no:
    stc
.out:
    pop di
    pop si
    pop cx
    pop ax
    ret

; =============================================================================
; COMMAND EQUIVALENTS (macro plan wave 3, 81.88): the menu's own commands,
; from a macro.
;
; A command that acts at once is its MENU ITEM, fired through sh_mfire - the
; same dispatch a click reaches, so it cannot drift from the menu - and costs
; a five-byte stub. A command that takes arguments sets the state its dialog
; would have set and calls the dialog's own apply (sh_fdlg_apply, which lives
; here in the module), so the arguments reach the same code a click on OK
; does.
; =============================================================================
; the menu-fired ones: AH = the menu, AL = the item (sh_mfire's contract)
shm_x_fillr:  mov ax, (SH_MI_EDIT << 8) | SH_EI_FILLR
              jmp short shm_mfirec
shm_x_filld:  mov ax, (SH_MI_EDIT << 8) | SH_EI_FILLD
              jmp short shm_mfirec
shm_x_plink:  mov ax, (SH_MI_EDIT << 8) | SH_EI_PASTELK
              jmp short shm_mfirec
shm_x_undo:   mov ax, (SH_MI_EDIT << 8) | SH_EI_UNDO
              jmp short shm_mfirec
shm_x_just:   mov ax, (SH_MI_FORMAT << 8) | 7
              jmp short shm_mfirec
shm_x_save:   mov ax, (SH_MI_FILE << 8) | 2
              jmp short shm_mfirec
shm_x_setdb:  mov ax, (SH_MI_DATA << 8) | 4
              jmp short shm_mfirec
shm_x_setcr:  mov ax, (SH_MI_DATA << 8) | 5
              jmp short shm_mfirec
shm_x_calcd:  mov ax, (SH_MI_OPTIONS << 8) | SH_OI_CALCNOW
              jmp short shm_mfirec
shm_x_dform:  mov ax, (SH_MI_DATA << 8) | 0
shm_mfirec:
    push ax
    SHOUT sh_skipargs
    pop ax
    SHOUT sh_macro_mfire
    jmp shm_mtrue

; shm_fdk - the dialog of kind AL, as if OK were pressed on choice DX
shm_fdk:
    mov [sh_fdlg_kind], al
    mov [sh_fdlg_sel], dx
    SHOUT sh_skipargs
    push si                           ; SI IS THE PARSE POINTER, and an apply
    CHOUT SHM_FDAPPLY                ; written for a dialog owes it nothing
    pop si                            ; (81.87.3's lesson)
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; shm_boolnext - a further optional logical: CF=1 AL = 1/0 when there is
; one, CF=0 when it is omitted (",," or the end). SI past it
shm_boolnext:
    cmp byte [si], ','
    jne .none
    inc si
    cmp byte [si], ','
    je .none
    cmp byte [si], ')'
    je .none
    SHOUT sh_pcmp
    call shm_mtruth
    mov al, 0
    jnc .f
    inc al
.f:
    stc
    ret
.none:
    clc
    ret

; ALIGNMENT(type_num) - 1 General, 2 Left, 3 Center, 4 Right; 5 Fill has no
; bit in the format byte, which is full, so it is refused
shm_malign:
    xor ax, ax
    call shm_intarg1
    jc .bad
    dec ax
    cmp ax, 4
    jae .bad
    mov dx, ax
    mov al, 1
    jmp shm_fdk
.bad:
    jmp shm_merr

; FORMAT.FONT(name, size, bold, italic, underline, strike) - bold and
; underline; the face and size are SHEET's one font, and it has no italic or
; strikeout
shm_mfont:
    mov byte [cs:shm_acc8], 0         ; NOT a register: sh_pcmp is the whole
    call shm_boolarg0                 ; evaluator, and keeps none of them.
    call shm_boolnext                 ; name and size: read, and not used
    call shm_boolnext                 ; bold
    jnc .b
    or [cs:shm_acc8], al
.b:
    call shm_boolnext                 ; italic
    call shm_boolnext                 ; underline
    jnc .u
    shl al, 1
    or [cs:shm_acc8], al
.u:
    mov dl, [cs:shm_acc8]
    xor dh, dh
    mov al, 2
    jmp shm_fdk
shm_acc8: db 0

; CELL.PROTECTION(locked, hidden) - stored inverted: bit 0 is UNLOCKED
shm_mprot:
    mov byte [cs:shm_acc8], 0         ; omitted: locked, and not hidden
    call shm_boolarg0
    jnc .l
    xor al, 1
    mov [cs:shm_acc8], al
.l:
    call shm_boolnext
    jnc .h
    shl al, 1
    or [cs:shm_acc8], al
.h:
    mov dl, [cs:shm_acc8]
    xor dh, dh
    mov al, SH_FDK_PROT
    jmp shm_fdk

; CALCULATION(type_num) - 1 Automatic, 2 Automatic Except Tables, 3 Manual,
; which is Excel's own numbering and is now exactly the dialog's radio row
; plus one (81.114.8).
;
; THIS USED TO FOLD 2 INTO AUTOMATIC, on the written ground that "SHEET has
; no tables, so automatic" - true when it was written and false from
; 81.114's first stage, which is the whole hazard of a comment that reasons
; from a feature's ABSENCE. A macro asking for the one mode that exists to
; make tables affordable was silently given the mode that does not.
shm_mcalcn:
    xor ax, ax
    call shm_intarg1
    jc .bad
    dec ax                            ; 1..3 -> the radio row 0..2
    cmp ax, SH_CALC_NOWROW            ; ...and 4 is not a mode: Calculate Now
    jae .bad                          ; is CALCULATE.NOW(), its own command
    mov dx, ax
    mov al, SH_FDK_CALC
    jmp shm_fdk
.bad:
    jmp shm_merr

; PASTE.SPECIAL(paste_num[, operation_num[, skip_blanks[, transpose]]]) -
; 1 All .. 5 Notes; SHEET's Paste Special has no arithmetic, no skip and no
; transpose, so any of those is refused rather than quietly ignored
shm_mpspec:
    xor ax, ax
    call shm_intarg1
    jc .bad
    dec ax
    cmp ax, 5
    jae .bad
    push ax
    mov ax, 1
    call shm_intarg                   ; operation: 1 None only
    jc .badpop
    cmp ax, 1
    jne .badpop
    call shm_boolnext                 ; skip blanks
    jnc .s
    or al, al
    jnz .badpop
.s:
    call shm_boolnext                 ; transpose
    jnc .t
    or al, al
    jnz .badpop
.t:
    pop dx
    mov al, SH_FDK_PSPEC
    jmp shm_fdk
.badpop:
    pop ax
.bad:
    jmp shm_merr

; INSERT(shift_num) / EDIT.DELETE(shift_num) - 3 the entire row, 4 the
; entire column (omitted: the row). SHEET inserts and deletes rows and
; columns; shifting cells within one is not something it does
shm_minsert:
    mov bl, 3
    jmp short shm_mrowcol
shm_mdelete:
    mov bl, 4
shm_mrowcol:
    push bx
    mov ax, 3
    call shm_intarg1
    pop bx
    jc .bad
    sub ax, 3
    cmp ax, 2
    jae .bad
    mov dx, ax
    mov al, bl
    jmp shm_fdk
.bad:
    jmp shm_merr

; CANCEL.COPY() - the copy is forgotten
shm_mccopy:
    mov byte [sh_clip_valid], 0
    SHOUT sh_skipargs
    jmp shm_mtrue

; FORMAT.NUMBER(format_text) - one of the 21 built-in formats, by its text
; exactly as the Number dialog lists it (case aside); a code of one's own is
; not something SHEET's formats are (81.55)
shm_mfmtnum:
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT
    jne .bad
    SHOUT sh_skipargs
    push si
    xor cx, cx
.f:
    mov bx, cx
    shl bx, 1
    mov di, [bx + sh_nf_codes]
    mov si, sh_sacc
.c:
    mov al, [si]
    mov ah, [di]
    cmp al, 'a'
    jb .u1
    cmp al, 'z'
    ja .u1
    sub al, 32
.u1:
    cmp ah, 'a'
    jb .u2
    cmp ah, 'z'
    ja .u2
    sub ah, 32
.u2:
    cmp al, ah
    jne .next
    or al, al
    jz .hit
    inc si
    inc di
    jmp short .c
.next:
    inc cx
    cmp cx, SH_NF_N
    jb .f
    pop si
    jmp shm_merr0                     ; the arguments are consumed already
.hit:
    pop si
    mov al, cl
    push si
    SHOUT sh_nf_apply
    SHOUT sh_undo_drop
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; BORDER(outline, left, right, top, bottom, shade) - the Border dialog's own
; six boxes; outline is the four edges at once
shm_mborder:
    mov byte [cs:shm_acc8], 0
    call shm_boolarg0
    jnc .o
    or al, al
    jz .o
    mov byte [cs:shm_acc8], 0x1E      ; outline: left, right, top, bottom
.o:
    mov byte [cs:shm_gmask], 2        ; bits 1..5, the dialog's own layout
.l:
    call shm_boolnext
    jnc .n
    or al, al
    jz .n
    mov al, [cs:shm_gmask]
    or [cs:shm_acc8], al
.n:
    shl byte [cs:shm_gmask], 1
    cmp byte [cs:shm_gmask], 0x40
    jb .l
    mov al, [cs:shm_acc8]
    mov [sh_bdlg_sel], al
    SHOUT sh_skipargs
    push si                           ; sh_bdlg_apply leaves SI the window
    CHOUT SHM_BDAPPLY
    SHOUT sh_undo_drop
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; COLUMN.WIDTH(width[, ref]) - in characters, every column of the selection
; (or of ref); 0 is the standard width
shm_mcolw:
    xor ax, ax
    call shm_intarg1
    jc .bad
    cmp ax, SH_CW_MAXCH
    ja .bad
    mov [cs:shm_gst], ax
    mov ax, [sh_selcol]
    mov cx, [sh_selcol2]
    cmp byte [si], ','
    jne .have
    inc si
    call shm_mrangeref
    jnc .bad
.have:
    cmp ax, cx
    jbe .go
    xchg ax, cx
.go:
    mov bx, cx
    mov cl, [cs:shm_gst]
.l:
    SHOUT sh_colw_set
    inc ax
    cmp ax, bx
    jbe .l
    SHOUT sh_skipargs
    push si
    SHOUT sh_undo_drop
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; ROW.HEIGHT(height[, ref]) - in POINTS, as the dialog takes them, every row
; of the selection (or of ref); kept in twips (81.60)
shm_mrowh:
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .bad
    SHOUT sh_acc_load_a
    mov ax, 20
    SHOUT fp_i2b
    SHOUT fp_mul
    SHOUT fp_a2i                      ; AX = twips; CF=1 did not fit
    jc .bad
    or ax, ax
    jz .std
    cmp ax, SH_RH_TWMIN
    jb .bad
    cmp ax, SH_RH_TWMAX
    ja .bad
.std:
    mov [cs:shm_gst], ax
    mov ax, [sh_selrow]
    mov dx, [sh_selrow2]
    cmp byte [si], ','
    jne .have
    inc si
    call shm_mrangeref
    jnc .bad
    mov ax, bx
.have:
    cmp ax, dx
    jbe .go
    xchg ax, dx
.go:
    mov bx, dx
    mov cx, [cs:shm_gst]
    push si
.l:
    SHOUT sh_rowh_set
    jc .full
    inc ax
    cmp ax, bx
    jbe .l
.full:
    SHOUT sh_undo_drop
    pop si
    SHOUT sh_skipargs
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; DISPLAY(formula, gridline, heading, zero, color) - the Display dialog's two
; settings, set as its OK sets them (81.106: they are check boxes there now,
; not menu rows to fire); a heading, zero or colour choice SHEET does not have
; is read and not used
shm_mdisplay:
    call shm_boolarg0
    jnc .g
    mov [sh_showformulas], al
.g:
    call shm_boolnext
    jnc .done
    mov [sh_gridlines], al
.done:
    SHOUT sh_skipargs
    push si                           ; one repaint whatever changed: no
    mov si, [sh_ownwin]               ; "dirty" byte, because a byte defined
    SHOUT sh_repaint                  ; here would sit in MACRO.OVL's segment
    pop si                            ; and DS is the package's
    jmp shm_mtrue

; FREEZE.PANES(logical) - freeze at the active cell, or unfreeze; omitted
; toggles, as the menu item does
shm_mfreeze:
    call shm_boolarg0
    jnc .flip
    xor bl, bl                        ; frozen now? (after the argument:
    mov cx, [sh_freezecol]            ; the evaluator keeps no register)
    or cx, [sh_freezerow]
    jz .st
    inc bl
.st:
    cmp al, bl
    je .done
.flip:
    mov ax, (SH_MI_OPTIONS << 8) | SH_OI_FREEZE
    SHOUT sh_macro_mfire
.done:
    SHOUT sh_skipargs
    jmp shm_mtrue

; PROTECT.DOCUMENT(contents, windows, password) - contents only: SHEET has no
; window protection and no passwords
shm_mprotdoc:
    call shm_boolarg0
    jnc .flip
    mov bl, [sh_protected]
    or bl, bl
    jz .c
    mov bl, 1
.c:
    cmp al, bl
    je .done
.flip:
    mov ax, (SH_MI_OPTIONS << 8) | SH_OI_PROT
    SHOUT sh_macro_mfire
.done:
    SHOUT sh_skipargs
    jmp shm_mtrue

; PRECISION(logical) - TRUE is full precision, the only kind SHEET has;
; FALSE, "as displayed", is refused rather than pretended
shm_mprecision:
    call shm_boolarg0
    jnc .ok
    or al, al
    jz .bad
.ok:
    SHOUT sh_skipargs
    jmp shm_mtrue
.bad:
    jmp shm_merr

; --- slice 3b (81.89): Formula, Data, RUN, movement, the chart gallery ------

; shm_idk - the one-line dialog of kind AL, as if the TEXT just evaluated
; had been typed into it and OK pressed (sh_idlg_apply, the module's own)
shm_idk:
    mov [sh_idlg_kind], al
    push si
    push di
    mov si, sh_sacc
    mov di, sh_idlg_buf
    mov cx, SH_EDITMAX
.c:
    mov al, [si]
    mov [di], al
    or al, al
    jz .e
    inc si
    inc di
    loop .c
    mov byte [di], 0
.e:
    pop di
    pop si
    SHOUT sh_skipargs
    push si
    CHOUT SHM_IDAPPLY
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; shm_textfirst - the argument at SI, which must be TEXT. CF=1 it is not
shm_textfirst:
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .no
    cmp byte [sh_curtype], SH_T_TEXT
    jne .no
    clc
    ret
.no:
    stc
    ret

; FORMULA.FIND(text[, in[, at[, by[, dir]]]]) - Formula > Find: displayed
; text, a part of it, any case, forwards. Where to look, whole-cell matching
; and the order are read and not used; dir 2, BACKWARDS, is refused - SHEET's
; Find goes one way. The text is read on a SECOND pass, after the numbers,
; ABSREF's idiom (81.85.2)
shm_mffind:
    push si                           ; the text, for the second pass
    SHOUT sh_pcmp
    call shm_intarg                   ; in_num
    call shm_intarg                   ; at_num
    call shm_intarg                   ; by_num
    mov ax, 1
    call shm_intarg                   ; dir_num
    jc .badpop
    cmp ax, 1
    jne .badpop
    pop si
    call shm_textfirst
    jc .bad
    mov al, SH_ID_FIND
    jmp shm_idk
.badpop:
    pop si
.bad:
    jmp shm_merr

; FORMULA.FIND.NEXT() - the same text again, from the next cell
shm_mffnext:
    SHOUT sh_skipargs
    push si
    CHOUT SHM_FIND                     ; in CHART.OVL since 81.111
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; FORMULA.FIND.PREV() / DATA.FIND.PREV() - backwards: refused, as above
shm_mprevno:
    jmp shm_merr

; PARSE(parse_text) - Data > Parse's bracket line, as typed
; =============================================================================
; TABLE([row_input][, column_input]) - Data > Table, as a macro (81.114.11).
; Cetab 0029H, and the document gives `table-params = *2(ref / val)`, which
; is the two optional references this takes.
;
; EITHER ARGUMENT MAY BE OMITTED, and that is not a refusal: it is how a
; one-input table says which kind it is, exactly as the dialog's empty field
; does (81.114.1). Both omitted leaves nothing to substitute, and the engine
; refuses that the same way it refuses it from the dialog.
;
; THE SELECTION IS THE RECTANGLE, as it is for the command - a macro selects
; first. The engine is CHART.OVL's and this is MACRO.OVL, so it goes through
; a verb rather than a near call.
; =============================================================================
shm_mtable:
    mov word [sh_tbl_ir], SH_TBL_NONE
    mov word [sh_tbl_ic], SH_TBL_NONE
    mov word [sh_tbl_ir2], SH_TBL_NONE
    mov word [sh_tbl_ic2], SH_TBL_NONE
    cmp byte [si], ','                ; TABLE(,B1): no row input cell
    je .second
    cmp byte [si], ')'                ; TABLE(): neither, which the engine
    je .run                           ; refuses below
    call shm_mref
    jnc .bad
    mov [sh_tbl_ic], ax
    mov [sh_tbl_ir], bx
.second:
    cmp byte [si], ','
    jne .run
    inc si
    cmp byte [si], ')'                ; TABLE(A1,): no column input cell
    je .run
    call shm_mref
    jnc .bad
    mov [sh_tbl_ic2], ax
    mov [sh_tbl_ir2], bx
.run:
    SHOUT sh_skipargs
    CHOUT SHM_TBLCMD                  ; the engine, in the other module
    jc .bad                           ; not a table shape
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

shm_mparse:
    call shm_textfirst
    jc .bad
    mov al, SH_ID_PARSE
    jmp shm_idk
.bad:
    jmp shm_merr

; shm_tident - the TEXT just evaluated, uppercased into sh_ident; CF=1 it is
; empty or too long for a name
shm_tident:
    push si
    push di
    push cx
    mov si, sh_sacc
    mov di, sh_ident
    mov cx, SH_NAME_MAX + 1
.c:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    mov [di], al
    or al, al
    jz .e
    inc si
    inc di
    loop .c
    stc                               ; longer than a name holds
    jmp short .out
.e:
    cmp di, sh_ident                  ; ...or empty
    je .empty
    clc
    jmp short .out
.empty:
    stc
.out:
    pop cx
    pop di
    pop si
    ret

; DEFINE.NAME(name_text[, refers_to]) / SET.NAME(name_text, value) - a name
; here is a PLACE (81.84.3), so refers_to and value must be references: the
; selection when refers_to is omitted, and SET.NAME's value is required. The
; name is read on a second pass, after the reference, for ABSREF's reason
shm_msetname:
    mov byte [cs:shm_acc8], 1         ; SET.NAME: the reference is required
    jmp short shm_mdefnm2
shm_mdefnm:
    mov byte [cs:shm_acc8], 0
shm_mdefnm2:
    push si
    SHOUT sh_pcmp                     ; past the name
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    mov cx, [sh_selcol2]
    mov dx, [sh_selrow2]
    cmp byte [si], ','
    jne .noref
    inc si
    call shm_mrangeref
    jnc .badpop
    jmp short .have
.noref:
    cmp byte [cs:shm_acc8], 0
    jne .badpop
.have:
    mov [cs:shm_ext_r1], ax           ; banked across the name's second
    mov [cs:shm_ext_r2], bx           ; evaluation, which keeps no register
    mov [cs:shm_ext_c1], cx
    mov [cs:shm_ext_c2], dx
    mov di, si                        ; where the arguments ended
    pop si
    push di
    call shm_textfirst
    jc .badpop
    call shm_tident
    jc .badpop
    pop si
    SHOUT sh_skipargs
    push si
    mov ax, [cs:shm_ext_r1]
    mov bx, [cs:shm_ext_r2]
    mov cx, [cs:shm_ext_c1]
    mov dx, [cs:shm_ext_c2]
    mov si, sh_ident
    SHOUT sh_name_def
    pop si
    jc .full
    jmp shm_mtrue
.badpop:
    pop si
    jmp shm_merr
.full:
    jmp shm_merr0

; DELETE.NAME(name_text) - the name is gone; one not defined is an error
shm_mdelname:
    call shm_textfirst
    jc .bad
    call shm_tident
    jc .bad
    SHOUT sh_skipargs
    push si
    mov si, sh_names
    mov cx, [sh_nnames]
    jcxz .none
.n:
    push si
    mov di, sh_ident
.c:
    mov al, [si]
    cmp al, [di]
    jne .next
    or al, al
    jz .hit
    inc si
    inc di
    jmp short .c
.next:
    pop si
    add si, SH_NAME_REC
    loop .n
.none:
    pop si
    jmp shm_merr0
.hit:
    pop di                            ; DI = the record; the rest slide down
    dec cx                            ; records after it
    mov ax, cx
    mov bx, SH_NAME_REC
    mul bx
    mov cx, ax
    mov si, di
    add si, SH_NAME_REC
.mv:
    jcxz .done
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jmp short .mv
.done:
    dec word [sh_nnames]
    inc word [sh_pass]                ; a formula naming it must evaluate again
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; NOTE([add_text[, cell_ref]]) - the note on cell_ref (the active cell) is
; add_text; an empty or omitted one removes it. Excel's start_char and
; num_chars, which edit PART of a note, are read and not used
shm_mnote:
    mov byte [sh_sacc], 0
    push si                           ; the text, for the second pass
    cmp byte [si], ')'
    je .noarg
    cmp byte [si], ','
    je .noarg
    SHOUT sh_pcmp
.noarg:
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    cmp byte [si], ','
    jne .have
    inc si
    call shm_mrangeref
    jnc .badpop
.have:
    mov [cs:shm_gcol], ax
    mov [cs:shm_grow], bx
    mov di, si
    pop si
    push di
    mov byte [sh_sacc], 0
    cmp byte [si], ')'
    je .t
    cmp byte [si], ','
    je .t
    call shm_textfirst
    jc .badpop
.t:
    pop si
    SHOUT sh_skipargs
    push si
    mov ax, [cs:shm_gcol]
    mov bx, [cs:shm_grow]
    mov si, sh_sacc
    SHOUT sh_nt_set
    pop si
    jc .full
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.badpop:
    pop si
    jmp shm_merr
.full:
    jmp shm_merr0

; DATA.FIND(logical) - into Find mode, or out of it; the menu item toggles,
; so it is fired only when the mode differs
shm_mdfind:
    call shm_boolarg0
    jnc .flip
    xor bl, bl
    cmp word [sh_i_data + 2], sh_it_exitfnd  ; the relabel IS the state
    jne .st
    inc bl
.st:
    cmp al, bl
    je .done
.flip:
    mov ax, (SH_MI_DATA << 8) | 1
    SHOUT sh_macro_mfire
.done:
    SHOUT sh_skipargs
    jmp shm_mtrue

; DATA.FIND.NEXT() - the next matching record, forwards. DATA.DELETE() -
; the matching records removed, without the menu's question: a macro that
; says so has answered it
shm_mdfnext:
    mov al, SH_DBC_FIND
    jmp short shm_mdbrun
shm_mddelete:
    mov al, SH_DBC_DELETE
shm_mdbrun:
    push ax
    SHOUT sh_skipargs
    pop ax
    push si
    SHOUT sh_docmd_dbrun
    pop si
    jc .no
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.no:
    jmp shm_mfalse                    ; refused: the status line says why

; EXTRACT([unique]) - Data > Extract, the unique box as its argument
shm_mextract:
    xor dx, dx
    call shm_boolarg0
    jnc .go
    mov dl, al
.go:
    mov al, SH_FDK_EXTRACT
    jmp shm_fdk

; SORT(sort_by, key1[, order1]) - by ROWS (1) only, one key, which must lie
; inside the selection as the dialog's must (81.80); order 1 ascending, 2
; descending. A second or third key SHEET does not have: refused
shm_msort:
    xor ax, ax
    call shm_intarg1
    jc .bad
    cmp ax, 1
    jne .bad
    cmp byte [si], ','
    jne .bad
    inc si
    call shm_mrangeref                ; AX = the key's column
    jnc .bad
    mov [cs:shm_gcol], ax
    mov ax, 1
    call shm_intarg
    jc .bad
    dec ax
    cmp ax, 2
    jae .bad
    mov [cs:shm_acc8], al
    cmp byte [si], ','                ; key2: refused
    je .bad
    mov ax, [cs:shm_gcol]
    mov bx, [sh_selcol]
    mov cx, [sh_selcol2]
    cmp bx, cx
    jbe .span
    xchg bx, cx
.span:
    cmp ax, bx
    jb .bad
    cmp ax, cx
    ja .bad
    mov [sh_sort_keycol], ax
    mov al, [cs:shm_acc8]
    mov [sh_sort_desc], al
    SHOUT sh_skipargs
    push si
    CHOUT SHM_SORT
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; RUN([reference]) - run the macro at reference as a SUBROUTINE: its RETURN
; comes back here, with RUN's answer its value (81.84's call, with no
; arguments and a reference for a target rather than a name)
shm_mrun:
    cmp byte [cs:shm_cans], 0
    je .call
    mov byte [cs:shm_cans], 0
    SHOUT sh_skipargs
    mov di, shm_ans
    jmp shm_vget
.call:
    inc byte [cs:shm_ccount]
    cmp byte [cs:shm_ccount], 1
    jne .bad
    call shm_mrangeref
    jnc .bad
    mov [cs:shm_ctcol], ax
    mov [cs:shm_ctrow], bx
    mov byte [cs:shm_cnargs], 0
    mov ax, [cs:shm_pused]
    mov [cs:shm_ptent], ax
    SHOUT sh_skipargs
    mov byte [cs:shm_cpend], 1
    jmp shm_mfalse
.bad:
    jmp shm_merr

; --- movement: the window, not the selection ------------------------------
; VLINE(n) / HLINE(n) - scroll n rows / columns; VPAGE(n) / HPAGE(n) - n
; windows' worth
shm_mvline:
    mov bx, sh_scrollrow
    mov cx, 1
    jmp short shm_mscrollby
shm_mhline:
    mov bx, sh_scrollcol
    mov cx, 1
    jmp short shm_mscrollby
shm_mvpage:
    mov bx, sh_scrollrow
    mov cx, [sh_vrows]
    jmp short shm_mscrollby
shm_mhpage:
    mov bx, sh_scrollcol
    mov cx, [sh_vcols]
shm_mscrollby:
    mov [cs:shm_gcol], bx             ; which word, and by how much a step:
    mov [cs:shm_grow], cx             ; the evaluator keeps no register
    xor ax, ax
    call shm_intarg1
    jc .bad
    imul word [cs:shm_grow]           ; DX:AX, the lines
    mov bx, [cs:shm_gcol]
    add ax, [bx]
    jmp shm_mscrollto
.bad:
    jmp shm_merr

; VSCROLL(position[, row_logical]) / HSCROLL - to row (column) position when
; the second argument is TRUE, else to that FRACTION of the sheet
shm_mvscroll:
    mov word [cs:shm_gcol], sh_scrollrow
    mov word [cs:shm_grow], SH_ROWS
    jmp short shm_mscrollabs
shm_mhscroll:
    mov word [cs:shm_gcol], sh_scrollcol
    mov word [cs:shm_grow], SH_COLS
shm_mscrollabs:
    SHOUT sh_pcmp                     ; BOTH readings of the position, now:
    cmp byte [sh_evalerr], 0          ; the second argument's evaluation
    jne .bad                          ; overwrites sh_acc
    SHOUT sh_acc_toint                ; a row or column NUMBER, 1-based...
    mov [cs:shm_gst], ax
    SHOUT sh_acc_load_a               ; ...or a fraction of the sheet
    mov ax, [cs:shm_grow]
    dec ax
    SHOUT fp_i2b
    SHOUT fp_mul
    SHOUT fp_a2i
    jc .bad
    mov [cs:shm_gcnt], ax
    call shm_boolnext
    mov ax, [cs:shm_gcnt]
    jnc .have
    or al, al
    mov ax, [cs:shm_gcnt]
    jz .have
    mov ax, [cs:shm_gst]
    dec ax
.have:
    mov bx, [cs:shm_gcol]
    jmp short shm_mscrollto
.bad:
    jmp shm_merr

; shm_mscrollto - [BX] (sh_scrollrow or sh_scrollcol) becomes AX, kept on
; the sheet; the frozen panes are the painter's own business
shm_mscrollto:
    or ax, ax
    jns .lo
    xor ax, ax
.lo:
    mov cx, SH_ROWS - 1
    cmp bx, sh_scrollrow
    je .hi
    mov cx, SH_COLS - 1
.hi:
    cmp ax, cx
    jbe .set
    mov ax, cx
.set:
    mov [bx], ax
    SHOUT sh_skipargs
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; SHOW.ACTIVE.CELL() - scroll it into view
shm_mshowact:
    SHOUT sh_skipargs
    push si
    SHOUT sh_scrollto
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; SELECT.LAST.CELL() - the last used row and the last used column's cell
; (GET.DOCUMENT 10 and 12's own, 81.87)
shm_mselast:
    SHOUT sh_skipargs
    call shm_extent
    mov ax, [cs:shm_ext_c2]
    mov bx, [cs:shm_ext_r2]
    or ax, ax
    jz .empty
    dec ax
    dec bx
    jmp short shm_mselone
.empty:
    xor bx, bx                        ; an empty sheet's last cell is A1
; shm_mselone - select the one cell AX/BX, and show it
shm_mselone:
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov [sh_selrow], bx
    mov [sh_selrow2], bx
    push si
    SHOUT sh_scrollto
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; SELECT.END(direction_num) - Ctrl with an arrow: 1 left, 2 right, 3 up, 4
; down. From a cell with something next to it, to the last filled cell of
; that run; otherwise to the next filled cell, or the sheet's edge
shm_mselend:
    xor ax, ax
    call shm_intarg1
    jc .bad
    dec ax
    cmp ax, 4
    jae .bad
    mov di, ax                        ; 0 left, 1 right, 2 up, 3 down - and
    SHOUT sh_skipargs                 ; BEFORE this, which writes AL
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    call shm_step1                    ; is the NEXT cell filled?
    jc .edge                          ; the edge already: stay
    push ax
    push bx
    call shm_filled
    pop bx
    pop ax
    jnc .seek                         ; no: on to the next filled one
.run:                                 ; yes: along the run to its end
    mov [cs:shm_gcol], ax
    mov [cs:shm_grow], bx
    call shm_step1
    jc .last
    push ax
    push bx
    call shm_filled
    pop bx
    pop ax
    jc .run
.last:
    mov ax, [cs:shm_gcol]
    mov bx, [cs:shm_grow]
    jmp shm_mselone
.seek:
    push ax
    push bx
    call shm_filled
    pop bx
    pop ax
    jc .there
    call shm_step1
    jnc .seek
.there:                               ; a filled cell, or the edge itself
.edge:
    jmp shm_mselone
.bad:
    jmp shm_merr

; shm_step1 - AX/BX one cell in direction DI (0 left 1 right 2 up 3 down);
; CF=1 and AX/BX unchanged at the sheet's edge
shm_step1:
    cmp di, 1
    jb .l
    je .r
    cmp di, 3
    je .d
    or bx, bx                         ; up
    jz .edge
    dec bx
    clc
    ret
.d:
    cmp bx, SH_ROWS - 1
    jae .edge
    inc bx
    clc
    ret
.l:
    or ax, ax
    jz .edge
    dec ax
    clc
    ret
.r:
    cmp ax, SH_COLS - 1
    jae .edge
    inc ax
    clc
    ret
.edge:
    stc
    ret

; shm_filled - CF=1 when the cell AX/BX holds something
shm_filled:
    push di
    SHOUT sh_findcell                 ; which does not keep DI
    pop di
    ret

; UNLOCKED.NEXT() / UNLOCKED.PREV() - the next (previous) unlocked cell,
; row by row, wrapping round the sheet. An unlocked cell is a border-table
; record with the UNLOCK bit (81.46), and that table is SORTED by sheet, row
; and column (sh_bt_findcell's binary search), so walking it in order IS
; walking the sheet in reading order
shm_munlnext:
    mov byte [cs:shm_acc8], 0
    jmp short shm_munl
shm_munlprev:
    mov byte [cs:shm_acc8], 1
shm_munl:
    SHOUT sh_skipargs
    push si
    push es
    mov ax, [sh_cursheet]             ; the active cell, as the table keys it
    mov cl, SH_ROW_BITS
    shl ax, cl
    or ax, [sh_selrow]
    mov [cs:shm_gst], ax
    mov word [cs:shm_gcol], 0xFFFF    ; the answer: none yet
    mov word [cs:shm_ext_c1], 0xFFFF  ; the first unlocked on this sheet...
    mov word [cs:shm_ext_c2], 0xFFFF  ; ...and the last, for the wrap
    xor si, si
    mov cx, [sh_nbord]
.l:
    jcxz .done
    mov es, [sh_bordseg]
    test byte [es:si+4], SH_PROT_UNLOCK
    jz .next
    mov ax, [es:si]                   ; sheet and row
    mov bx, [es:si+2]                 ; column
    push cx
    mov dx, ax
    mov cl, SH_ROW_BITS
    shr dx, cl
    pop cx
    cmp dx, [sh_cursheet]
    jne .next
    cmp word [cs:shm_ext_c1], 0xFFFF
    jne .notfirst
    mov [cs:shm_ext_r1], ax
    mov [cs:shm_ext_c1], bx
.notfirst:
    mov [cs:shm_ext_r2], ax
    mov [cs:shm_ext_c2], bx
    cmp ax, [cs:shm_gst]              ; this record against the active cell
    jne .cmpd
    cmp bx, [sh_selcol]
.cmpd:
    je .next                          ; the active cell itself
    pushf                             ; the ORDER, kept across the test of
    cmp byte [cs:shm_acc8], 0         ; which way we are going - pushf and
    jne .prev                         ; not lahf, which writes AH, and AH is
    popf                              ; half the row being compared
    jb .next                          ; NEXT: the first one past it
    cmp word [cs:shm_gcol], 0xFFFF
    jne .next
    jmp short .take
.prev:
    popf
    jae .next                         ; PREV: the last one before it
.take:
    mov [cs:shm_grow], ax
    mov [cs:shm_gcol], bx
.next:
    add si, SH_BT_SZ
    dec cx
    jmp short .l
.done:
    pop es
    pop si
    mov ax, [cs:shm_gcol]
    mov bx, [cs:shm_grow]
    cmp ax, 0xFFFF
    jne .go
    mov ax, [cs:shm_ext_c1]           ; nothing that way: wrap round
    mov bx, [cs:shm_ext_r1]
    cmp byte [cs:shm_acc8], 0
    je .wrapped
    mov ax, [cs:shm_ext_c2]
    mov bx, [cs:shm_ext_r2]
.wrapped:
    cmp ax, 0xFFFF
    je .none
.go:
    and bx, SH_ROW_MASK               ; the row, without its sheet
    jmp shm_mselone
.none:
    jmp shm_mtrue                     ; no unlocked cell: nowhere to go

; GALLERY.AREA .. GALLERY.SCATTER(type_num, ...) - Data > Chart Gallery's
; choice, sh_gal_map's order; SHEET's gallery has one format of each type, so
; type_num is read and not used
shm_mgarea:   mov dx, 0
              jmp short shm_mgal
shm_mgbar:    mov dx, 1
              jmp short shm_mgal
shm_mgcol:    mov dx, 2
              jmp short shm_mgal
shm_mgline:   mov dx, 3
              jmp short shm_mgal
shm_mgpie:    mov dx, 4
              jmp short shm_mgal
shm_mgscat:   mov dx, 5
shm_mgal:
    mov [cs:shm_gcnt], dx             ; the evaluator keeps no register
    SHOUT sh_skipargs
    mov dx, [cs:shm_gcnt]
    mov al, SH_FDK_GAL
    mov [sh_fdlg_kind], al
    mov [sh_fdlg_sel], dx
    push si
    CHOUT SHM_FDAPPLY
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; FORMULA.GOTO(reference) - Formula > Goto: the reference selected and shown,
; which is SELECT's own work
shm_mfgoto equ shm_mselect

; --- slice 3c (81.90): File, FORMULA.FILL, DATA.SERIES ---------------------

; shm_fname - the TEXT argument at SI into sh_delname (DS), cut to an 8.3
; name; CF=1 not text or empty. The DELETE buffer, not sh_name: a name that
; turns out wrong must not have renamed the open document
shm_fname:
    call shm_textfirst
    jc .no
    push si
    push di
    push cx
    mov si, sh_sacc
    mov di, sh_delname
    mov cx, SH_FNAME_MAX
.c:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    mov [di], al
    or al, al
    jz .e
    inc si
    inc di
    loop .c
    mov byte [di], 0
.e:
    pop cx
    pop di
    pop si
    cmp byte [sh_delname], 0
    je .no
    clc
    ret
.no:
    stc
    ret

; shm_tosh_name - sh_delname becomes the document's name
shm_tosh_name:
    push si
    push di
    mov si, sh_delname
    mov di, sh_name
.c:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .c
    pop di
    pop si
    ret

; FILE.DELETE(file_text) - the file is deleted, in this instance's current
; folder (DIRECTORY's, 81.87.4); one that is not there is an error
shm_mfdelete:
    call shm_fname
    jc .bad
    SHOUT sh_skipargs
    push si
    mov si, sh_delname
    call OSAPI_FILE_DELETE            ; CF=0 AX=0, else FERR_*
    pop si
    jc .gone
    jmp shm_mtrue
.gone:
    jmp shm_merr0
.bad:
    jmp shm_merr

; NEW([type_num]) and OPEN(file_text, ...) - another document, IN THIS
; WINDOW: SHEET is one document an instance, and a macro lives in the
; document it runs in (81.88.2). So the run ENDS here - the cells it was
; running are gone - which is what Excel does when a macro closes its own
; macro sheet. 1 worksheet, 2 chart, 3 macro sheet, as File > New asks.
; A MODIFIED workbook refuses both (81.118): File > New asks Save / Discard /
; Cancel there, and a running macro cannot answer an alert
shm_mnew:
    cmp byte [sh_modified], 0
    jne .bad
    mov ax, 1
    call shm_intarg1
    jc .bad
    dec ax
    cmp ax, 3
    jae .bad
    mov [sh_fdlg_sel], ax
    mov byte [sh_fdlg_kind], SH_FDK_NEW
    SHOUT sh_skipargs
    push si
    CHOUT SHM_FDAPPLY
    pop si
    jmp short shm_mendrun
.bad:
    jmp shm_merr

shm_mopen:
    cmp byte [sh_modified], 0
    jne shm_mopen_bad
    call shm_fname
    jc shm_mopen_bad
    SHOUT sh_skipargs
    call shm_tosh_name
    push si
    CHOUT SHM_READ                   ; sh_doread's own body: we are in the
    cmp word [sh_msg], sh_m_loaded    ; module already - so its clean mark
    jne .kept                         ; too, or every addcell of the read
    mov byte [sh_modified], 0         ; leaves the file just read dirty
.kept:
    SHOUT sh_undo_drop
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop si
shm_mendrun:
    mov byte [sh_macro_ctl], SH_MC_STOP
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
shm_mopen_bad:
    jmp shm_merr

; SAVE.AS(file_text[, type_num]) - the document saved under that name, in
; that format: 1 Normal (BIFF), 2 SYLK, 3 Text, 6 CSV, 8 dBASE III, 9 DIF.
; WKS, WK1 and dBASE II SHEET does not write, and those are refused.
; Excel's password and backup arguments are read and not used
shm_mfsaveas:
    push si                           ; the name, for the second pass
    SHOUT sh_pcmp
    mov ax, 1
    call shm_intarg
    jc .badpop
    mov bx, shm_saext
.f:
    cmp byte [cs:bx], 0
    je .badpop
    cmp al, [cs:bx]
    je .have
    add bx, 3
    jmp short .f
.have:
    mov ax, [cs:bx+1]                 ; the extension's ".XXX"
    mov [cs:shm_gcnt], ax
    mov di, si
    pop si
    push di
    call shm_fname
    jc .badpop
    pop si
    SHOUT sh_skipargs
    call shm_tosh_name
    push si
    mov si, [cs:shm_gcnt]
    CHOUT SHM_SETEXT
    pop si
    mov ax, (SH_MI_FILE << 8) | 2     ; File > Save, under the new name
    SHOUT sh_macro_mfire
    jmp shm_mtrue
.badpop:
    pop si
    jmp shm_merr
shm_saext:                            ; type_num, then its extension string
    db 1
    dw sh_s_ext_biff
    db 2
    dw sh_s_ext_sylk
    db 3
    dw sh_s_ext_txt
    db 6
    dw sh_s_ext_csv
    db 8
    dw sh_s_ext_dbf
    db 9
    dw sh_s_ext_dif
    db 0

; FORMULA.FILL(formula_text, reference) - the formula into every cell of the
; reference, relative references moving as they would for each cell: the
; top-left cell gets it as FORMULA would put it there, and Fill Down then
; Fill Right carry it across, which is exactly how those two adjust
shm_mffill:
    push si                           ; the formula, for the second pass
    SHOUT sh_pcmp
    cmp byte [si], ','
    jne .badpop
    inc si
    call shm_mrangeref
    jnc .badpop
    mov [sh_selcol], ax               ; the reference IS the selection now,
    mov [sh_selrow], bx               ; which is what both fills act on
    mov [sh_selcol2], cx
    mov [sh_selrow2], dx
    pop si
    call shm_mformula                 ; FORMULA(x) - into the active cell,
    cmp byte [sh_macro_ctl], SH_MC_STOP ; its top-left, and past every
    je .out                           ; argument
    push si
    mov ax, (SH_MI_EDIT << 8) | SH_EI_FILLD
    SHOUT sh_macro_mfire
    mov ax, (SH_MI_EDIT << 8) | SH_EI_FILLR
    SHOUT sh_macro_mfire
    pop si
.out:
    ret
.badpop:
    pop si
    jmp shm_merr

; DATA.SERIES([rowcol[, type[, date[, step[, stop]]]]]) - Data > Series on
; the selection. Rows or columns come from its shape, as the dialog's do
; (81.72); type 1 linear, 2 growth, 3 date (date 1 day, 2 weekday, 3 month,
; 4 year); step 1 by default. A STOP value is 81.72's own shortfall: refused
shm_mseries:
    call shm_intarg1                  ; rowcol: derived, read and not used
    mov ax, 1
    call shm_intarg                   ; type
    jc .bad
    mov [cs:shm_gcol], ax
    mov ax, 1
    call shm_intarg                   ; date unit
    jc .bad
    mov [cs:shm_grow], ax
    mov ax, 1                         ; the step: 1 unless there is one
    SHOUT sh_acc_int
    cmp byte [si], ','
    jne .havestep
    inc si
    cmp byte [si], ','
    je .havestep
    cmp byte [si], ')'
    je .havestep
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .bad
.havestep:
    push si                           ; the step's eight bytes, banked
    push di
    mov si, sh_acc
    mov di, sh_ser_step
    mov cx, 8
.cp:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    loop .cp
    pop di
    pop si
    cmp byte [si], ','                ; stop: refused
    jne .nostop
    cmp byte [si+1], ')'
    jne .bad
.nostop:
    mov ax, [cs:shm_gcol]             ; the type, as the radio numbers it
    dec ax
    jz .lin                           ; 1 linear
    dec ax
    jz .gro                           ; 2 growth
    dec ax
    jnz .bad                          ; 3 date, by its unit
    mov ax, [cs:shm_grow]
    dec ax
    cmp ax, 4
    jae .bad
    add al, SH_SER_DAY
    jmp short .type
.gro:
    mov al, SH_SER_GRO
    jmp short .type
.lin:
    mov al, SH_SER_LIN
.type:
    mov [sh_ser_type], al
    mov ax, [sh_selcol]
    mov [sh_ser_c1], ax
    mov ax, [sh_selrow]
    mov [sh_ser_r1], ax
    mov ax, [sh_selcol2]
    mov [sh_ser_c2], ax
    mov ax, [sh_selrow2]
    mov [sh_ser_r2], ax
    SHOUT sh_skipargs
    push si
    CHOUT SHM_SERIES
    SHOUT sh_undo_drop
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; =============================================================================
; TEXT FILES (macro plan wave 4, 81.91): FOPEN, FCLOSE, FREAD, FREADLN,
; FWRITE, FWRITELN, FPOS, FSIZE.
;
; A CHANNEL IS THE WHOLE FILE, IN MEMORY. The file API is cluster-grained -
; OSAPI_FILE_READ_AT's offset and OSAPI_FILE_APPEND's file size must each be
; a cluster multiple - so reading line 3 or writing one byte cannot go to the
; disk as it is asked for. FOPEN reads the file (OSAPI_FILE_READ, which also
; expands a compressed one), every read and write works on the bytes in
; memory, and FCLOSE writes the file back whole (OSAPI_FILE_WRITE) if it
; changed.
;
; THE MEMORY IS THE TAIL OF THIS MODULE'S OWN CLAIM - between the end of
; CHART.OVL's image and CH_OVKB KB - and not a claim of its own, for two
; reasons that are both rules: SPEC.md 50.3 takes a package's claims in its
; entry proc and nowhere else, and MEM_OWNER_MAX is eight claims an owner,
; which SHEET already holds. So a file a macro opens is as big as its share of
; that tail, and a larger one is #N/A.
; =============================================================================
SHM_FCH    equ 2                      ; channels open at once
SHM_FREC   equ 24                     ; +0 name (13) +13 mode +14 dirty
                                       ; +15 open +16 base (in THIS segment)
                                       ; +18 size +20 position +22 capacity
SHM_FTAIL  equ ((shm_m2end - sh_modm0) + 15) & 0xFFF0  ; where the image
                                       ; ends, and the tail - on a PARAGRAPH,
                                       ; because a packed file expands in
                                       ; place only into a buffer whose
                                       ; offset is a multiple of 16 (20.14.2)
SHM_FEACH  equ ((SH_M2KB * 1024 - SHM_FTAIL) / SHM_FCH) & 0xFFF0
shm_fch:   times SHM_FCH * SHM_FREC db 0

; shm_fchan - the channel number argument at SI -> DI = its record. CF=1 not
; a channel that is open (the caller answers #VALUE!)
shm_fchan:
    xor ax, ax
    call shm_intarg1
    jc .no
    dec ax
    cmp ax, SHM_FCH
    jae .no
    mov bx, SHM_FREC
    mul bx
    add ax, shm_fch
    mov di, ax
    cmp byte [cs:di+15], 0            ; not open
    je .no
    clc
    ret
.no:
    stc
    ret

; FOPEN(file_text[, access_num]) - 1 read and write, 2 read only, 3 a new
; file (an existing one emptied). out: the channel number, 1..SHM_FCH, or
; #N/A when the file is not there, is too big, or no channel is free
shm_mfopen:
    push si                           ; the name, for the second pass
    SHOUT sh_pcmp
    mov ax, 1
    call shm_intarg
    jc .badpop
    dec ax
    cmp ax, 3
    jae .badpop
    mov [cs:shm_acc8], al             ; 0 rw, 1 read, 2 create
    mov di, si
    pop si
    push di
    call shm_fname                    ; -> sh_delname, uppercased
    jc .badpop
    pop si
    SHOUT sh_skipargs
    push si
    mov di, shm_fch                   ; a free channel
    xor cx, cx
.free:
    cmp byte [cs:di+15], 0
    je .got
    add di, SHM_FREC
    inc cx
    cmp cx, SHM_FCH
    jb .free
    jmp .na
.got:
    mov [cs:shm_gcnt], cx             ; its index
    push di
    mov si, sh_delname                ; the name into the record
.nm:
    mov al, [si]
    mov [cs:di], al
    inc si
    inc di
    or al, al
    jnz .nm
    pop di
    mov al, [cs:shm_acc8]
    mov [cs:di+13], al
    mov byte [cs:di+14], 0
    mov word [cs:di+20], 0
    xor ax, ax                        ; its size: 0 new, else the directory's
    cmp byte [cs:shm_acc8], 2
    je .sized
    call shm_fsize0                   ; AX = the size, CF=1 not there/too big
    jc .na
.sized:
    mov [cs:di+18], ax
    mov word [cs:di+22], SHM_FEACH    ; its share of the tail
    cmp ax, SHM_FEACH
    ja .na                            ; the file is bigger than that
    mov ax, [cs:shm_gcnt]
    mov bx, SHM_FEACH
    mul bx
    add ax, SHM_FTAIL
    mov [cs:di+16], ax                ; its base
    cmp byte [cs:shm_acc8], 2
    je .opened
    cmp word [cs:di+18], 0            ; an empty file has nothing to read
    je .opened
    push es                           ; the whole file, expanded if packed
    push di
    push cs
    pop es
    mov bx, [cs:di+16]
    mov si, sh_delname
    mov cx, SHM_FEACH
    xor dx, dx
    call OSAPI_FILE_READ
    pop di
    pop es
    jc .na
    or dx, dx                         ; what the read DELIVERED is the size:
    jnz .na                           ; FIND's under-reports a packed file
    mov [cs:di+18], ax                ; whose hint a foreign OS dropped
.opened:
    mov byte [cs:di+15], 1            ; open
    cmp byte [cs:shm_acc8], 2         ; a NEW file is marked changed, so
    jne .num                          ; FCLOSE writes it even while empty
    mov byte [cs:di+14], 1
.num:
    pop si
    mov ax, [cs:shm_gcnt]
    inc ax
    jmp shm_anum
.na:
    pop si
    jmp shm_ana
.badpop:
    pop si
    jmp shm_refbad

; shm_fsize0 - the size of the file named at [cs:DI] in this folder, from its
; directory entry (the EXPANDED size, which is what OSAPI_FILE_READ delivers).
; out: AX, CF=1 not there or 64 KB or more
shm_fsize0:
    push bx
    push cx
    push si
    push di
    push es
    push ds
    pop es
    mov bx, di
    xor cx, cx
.l:
    mov di, sh_clipbuf
    call OSAPI_FILE_FIND
    jc .no
    cmp word [sh_clipbuf + 14], OSAPI_FT_DIR
    jae .l                            ; a folder is not a file
    mov si, sh_clipbuf
    mov di, bx
.c:
    mov al, [si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    cmp al, [cs:di]
    jne .l
    or al, al
    jz .hit
    inc si
    inc di
    jmp short .c
.hit:
    cmp word [sh_clipbuf + 20], 0     ; the size's high word: 64 KB or more
    jne .no
    mov ax, [sh_clipbuf + 18]
    clc
    jmp short .out
.no:
    stc
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    ret

; FCLOSE(channel) - written back if it changed, and the memory given back.
; A write the disk REFUSES answers #N/A and leaves the channel open and
; changed: the tail is the only copy of what the macro wrote
shm_mfclose:
    call shm_fchan
    jc .bad
    SHOUT sh_skipargs
    push si
    cmp byte [cs:di+14], 0
    je .free
    call shm_fflush
    jc .na
.free:
    mov byte [cs:di+15], 0
    pop si
    jmp shm_mtrue
.na:
    pop si
    jmp shm_ana
.bad:
    jmp shm_refbad

; shm_fflush - the channel at DI written to its file, whole. CF=1 the write
; was refused, and the channel stays changed
shm_fflush:
    push es
    push di
    push cs
    pop es
    mov bx, [cs:di+16]
    mov cx, [cs:di+18]
    xor dx, dx
    mov si, sh_delname                ; the name, into DS, for the call
.nm:
    mov al, [cs:di]
    mov [si], al
    inc si
    inc di
    or al, al
    jnz .nm
    mov si, sh_delname
    call OSAPI_FILE_WRITE
    pop di
    pop es
    jc .out
    mov byte [cs:di+14], 0
.out:
    ret

; FSIZE(channel) and FPOS(channel[, position]) - positions are 1-based, as
; Excel's are: a new channel stands at 1
shm_mfsize:
    call shm_fchan
    jc .bad
    SHOUT sh_skipargs
    mov ax, [cs:di+18]
    jmp shm_anum
.bad:
    jmp shm_refbad
shm_mfpos:
    call shm_fchan
    jc .bad
    push di
    mov ax, 0xFFFF                    ; omitted: only ask
    call shm_intarg
    pop di
    jc .bad
    cmp ax, 0xFFFF
    je .ask
    dec ax
    cmp ax, [cs:di+18]                ; not past the end
    ja .bad
    mov [cs:di+20], ax
.ask:
    SHOUT sh_skipargs
    mov ax, [cs:di+20]
    inc ax
    jmp shm_anum
.bad:
    jmp shm_refbad

; FREAD(channel, num_chars) / FREADLN(channel) - text from the position on;
; FREADLN to the end of the line, its CR LF (or LF) read and not answered.
; At the end of the file, #N/A. A text value holds SH_STR_MAX
shm_mfreadln:
    mov byte [cs:shm_acc8], 1
    call shm_fchan
    jc .bad
    mov ax, SH_STR_MAX
    jmp short shm_fread
.bad:
    jmp shm_refbad
shm_mfread:
    mov byte [cs:shm_acc8], 0
    call shm_fchan
    jc .bad
    push di
    xor ax, ax
    call shm_intarg
    pop di
    jc .bad
    or ax, ax
    jz .bad
    jmp short shm_fread
.bad:
    jmp shm_refbad
shm_fread:                            ; AX = the most to read, DI = channel
    cmp ax, SH_STR_MAX
    jbe .n
    mov ax, SH_STR_MAX
.n:
    mov cx, ax
    SHOUT sh_skipargs
    mov bx, [cs:di+20]
    cmp bx, [cs:di+18]
    jae .eof
    push si
    push es
    push cs
    pop es
    add bx, [cs:di+16]                ; the byte, in this segment
    mov si, sh_sacc
.c:
    mov ax, bx
    sub ax, [cs:di+16]
    cmp ax, [cs:di+18]
    jae .e
    mov al, [es:bx]
    cmp byte [cs:shm_acc8], 0
    je .keep
    cmp al, 13
    je .eol
    cmp al, 10
    je .eol
.keep:
    mov [si], al
    inc si
    inc bx
    loop .c
    jmp short .e
.eol:
    inc bx                            ; the CR or LF itself...
    cmp al, 13
    jne .e
    mov ax, bx
    sub ax, [cs:di+16]
    cmp ax, [cs:di+18]
    jae .e
    cmp byte [es:bx], 10              ; ...and the LF of a CR LF
    jne .e
    inc bx
.e:
    mov byte [si], 0
    sub bx, [cs:di+16]                ; back to a position
    mov [cs:di+20], bx
    pop es
    pop si
    jmp shm_atext
.eof:
    jmp shm_ana

; FWRITE(channel, text) / FWRITELN(channel, text) - the text at the position,
; over what is there and on past the end; FWRITELN adds CR LF. out: the
; characters written. A read-only channel, or one its claim cannot hold, is
; refused
shm_mfwriteln:
    mov byte [cs:shm_acc8], 1
    jmp short shm_fwrite
shm_mfwrite:
    mov byte [cs:shm_acc8], 0
shm_fwrite:
    call shm_fchan
    jc .bad
    cmp byte [si], ','
    jne .bad
    inc si
    push di
    call shm_textfirst
    pop di
    jc .bad
    cmp byte [cs:di+13], 1            ; read-only
    je .bad
    SHOUT sh_skipargs
    push si
    push es
    push cs
    pop es
    mov bx, [cs:di+20]                ; a POSITION: shm_fput adds the base
    mov si, sh_sacc
    xor cx, cx
.c:
    mov al, [si]
    or al, al
    jz .text
    call shm_fput
    jc .full
    inc si
    inc cx
    jmp short .c
.text:
    cmp byte [cs:shm_acc8], 0
    je .done
    mov al, 13
    call shm_fput
    jc .full
    mov al, 10
    call shm_fput
    jc .full
    add cx, 2
.done:
    mov [cs:di+20], bx
    mov byte [cs:di+14], 1
    pop es
    pop si
    mov ax, cx
    jmp shm_anum
.full:
    pop es
    pop si
    jmp shm_ana
.bad:
    jmp shm_refbad

; shm_fput - AL at ES:BX of the channel at DI, BX on, the size following it;
; CF=1 past what the claim holds
shm_fput:
    cmp bx, [cs:di+22]                ; the channel's share of the tail
    jae .full
    push bx
    add bx, [cs:di+16]
    mov [es:bx], al
    pop bx
    inc bx
    cmp bx, [cs:di+18]
    jbe .ok
    mov [cs:di+18], bx
.ok:
    clc
    ret
.full:
    stc
    ret

; =============================================================================
; EVENTS (macro plan wave 4, 81.92): ON.KEY and ON.TIME. Each starts a run
; the way Macro > Run does - [sh_macro_col/row] and SH_MW_START through
; sh_macro_onalert - from a keystroke or from the window's timer.
; =============================================================================
shm_oncol:  dw 0                      ; ON.TIME's macro
shm_onrow:  dw 0
shm_ontt:   times 8 db 0              ; ...and when

; shm_macref - the TEXT in sh_sacc as a macro's place: a reference ("B5",
; "R2C3") or a defined name. CF=1 AX/BX its cell
shm_macref:
    push cx
    push dx
    push si
    mov si, sh_sacc
    call shm_rangetext
    jc .out
    call shm_tident                   ; ...or a name
    jc .no
    mov si, sh_ident
    SHOUT sh_name_lookup              ; AX/BX the near corner
    jmp short .out
.no:
    clc
.out:
    pop si
    pop dx
    pop cx
    ret

; shm_keycode - the key_text in sh_sacc as sh_onkey sees the key: out AX,
; AL the character (AH 0) or AH the scan code of a function key (AL 0).
; "c", "^c" (Ctrl) and "{F1}".."{F12}"; CF=1 anything else - Shift and Alt
; forms, and the named keys, are refused rather than guessed
shm_keycode:
    push bx
    push si
    mov si, sh_sacc
    xor bl, bl
    cmp byte [si], '^'
    jne .n
    inc si
    inc bl
.n:
    cmp byte [si], '{'
    je .brace
    mov al, [si]
    or al, al
    jz .bad
    cmp byte [si+1], 0
    jne .bad
    or bl, bl
    jz .plain
    and al, 0x1F                      ; Ctrl: the control code sh_onkey gets
.plain:
    xor ah, ah
    jmp short .ok
.brace:
    or bl, bl
    jnz .bad
    mov al, [si+1]
    and al, 0xDF
    cmp al, 'F'
    jne .bad
    mov al, [si+2]
    sub al, '0'
    cmp al, 9
    ja .bad
    add si, 3
    cmp byte [si], '}'
    je .one
    mov ah, 10                        ; F10..F12
    mul ah
    mov ah, [si]
    sub ah, '0'
    cmp ah, 9
    ja .bad
    add al, ah
    inc si
    cmp byte [si], '}'
    jne .bad
.one:
    cmp byte [si+1], 0
    jne .bad
    or al, al
    jz .bad
    cmp al, 12
    ja .bad
    mov ah, 0x3A
    add ah, al                        ; F1..F10: 3Bh..44h
    cmp al, 11
    jb .sc
    add ah, 0x57 - 0x3A - 11          ; F11 57h, F12 58h
.sc:
    xor al, al
.ok:
    clc
    jmp short .out
.bad:
    stc
.out:
    pop si
    pop bx
    ret

; ON.KEY(key_text[, macro_text]) - the key runs the macro, when the sheet
; has the keyboard and no run is going; "" makes it do nothing; omitted puts
; it back. SH_MKEYS bindings; one more is refused
shm_monkey:
    push si                           ; the key, for the second pass
    SHOUT sh_pcmp
    mov word [cs:shm_gcol], 0xFFFE    ; omitted: unbind
    cmp byte [si], ','
    jne .have
    inc si
    call shm_textfirst
    jc .badpop
    mov word [cs:shm_gcol], 0xFFFF    ; "": swallow the key
    cmp byte [sh_sacc], 0
    je .have
    call shm_macref
    jnc .badpop
    mov [cs:shm_gcol], ax
    mov [cs:shm_grow], bx
.have:
    mov di, si
    pop si
    push di
    call shm_textfirst
    jc .badpop
    call shm_keycode
    jc .badpop
    pop si
    push ax                           ; sh_skipargs writes AL, and AL is the
    SHOUT sh_skipargs                 ; key - F7, matched on AH, survived it
    pop ax                            ; and hid this from every Fn test
    push si
    mov si, sh_macro_keys             ; its own entry, or a free one
    mov cx, SH_MKEYS
    xor di, di
.find:
    cmp [si], ax
    je .got
    or di, di
    jnz .next
    cmp word [si], 0
    jne .next
    mov di, si                        ; the first free
.next:
    add si, SH_MKREC
    loop .find
    mov si, di
    or si, si
    jz .full
.got:
    cmp word [cs:shm_gcol], 0xFFFE
    jne .bind
    mov word [si], 0                  ; unbound
    jmp short .done
.bind:
    mov [si], ax
    mov ax, [cs:shm_gcol]
    mov [si+2], ax
    mov ax, [cs:shm_grow]
    mov [si+4], ax
.done:
    pop si
    jmp shm_mtrue
.full:
    pop si
    jmp shm_merr0
.badpop:
    pop si
    jmp shm_merr

; ON.TIME(time, macro_text[, tolerance[, insert_logical]]) - the macro runs at
; that date and time; insert FALSE cancels. ONE request: a second replaces
; the first. A time alone (under 1, "every day at"), the tolerance, and a
; machine with no clock or no timer are refused
shm_montime:
    SHOUT sh_pcmp
    cmp byte [sh_evalerr], 0
    jne .bad
    push si
    push di
    mov si, sh_acc
    mov di, shm_ontt
    mov cx, 8
.bank:
    mov al, [si]
    mov [cs:di], al
    inc si
    inc di
    loop .bank
    pop di
    pop si
    SHOUT sh_acc_toint                ; under 1: a time of day - refused
    jc .ok1
    or ax, ax
    jz .bad
.ok1:
    cmp byte [si], ','
    jne .bad
    inc si
    call shm_textfirst
    jc .bad
    call shm_macref
    jnc .bad
    mov [cs:shm_oncol], ax
    mov [cs:shm_onrow], bx
    call shm_intarg                   ; tolerance: read, not used
    call shm_boolnext                 ; insert
    jnc .ins
    or al, al
    jnz .ins
    mov byte [sh_macro_ontp], 0       ; FALSE: cancelled
    SHOUT sh_skipargs
    jmp shm_mtrue
.ins:
    SHOUT sh_skipargs
    mov byte [sh_macro_ontp], 1
    mov ax, 18                        ; a look at the clock a second
    SHOUT sh_macro_arm
    jc .notimer
    jmp shm_mtrue
.notimer:
    mov byte [sh_macro_ontp], 0
    jmp shm_ana
.bad:
    jmp shm_merr

; shm_ontime - SHM_MRESUME's SH_MW_ONTIME: the timer looked, no run going.
; CF=1: due now, and [sh_macro_col/row] is where to start
shm_ontime:
    SHOUT sh_pnow                     ; no clock: never due - dropped
    jc .drop
    push si
    SHOUT sh_acc_load_a
    mov si, shm_ontt
    mov di, sh_macro_tend
    mov cx, 8
.cp:
    mov al, [cs:si]
    mov [di], al
    inc si
    inc di
    loop .cp
    mov si, sh_macro_tend
    SHOUT fp_unpack_b
    SHOUT fp_cmpab
    pop si
    cmp ax, 0
    jl .later
    mov byte [sh_macro_ontp], 0
    mov ax, [cs:shm_oncol]
    mov [sh_macro_col], ax
    mov ax, [cs:shm_onrow]
    mov [sh_macro_row], ax
    stc
    ret
.later:
    mov ax, 18
    SHOUT sh_macro_arm
    clc
    ret
.drop:
    mov byte [sh_macro_ontp], 0
    clc
    ret

; =============================================================================
; CUSTOM MENUS (macro plan wave 4, 81.95): ADD.BAR, SHOW.BAR, DELETE.BAR,
; ADD.MENU, ADD.COMMAND, DELETE.MENU, DELETE.COMMAND, ENABLE.COMMAND,
; CHECK.COMMAND, RENAME.COMMAND.
;
; Bar 1 is SHEET's own; a custom menu added to it goes after Help. Bar 7 is
; the ONE custom bar ADD.BAR makes, holding custom menus only. The records are
; resident (sh_mcrec) because the bar is drawn and clicked there; this is
; only the bookkeeping. SHEET's own menus and commands are not edited: every
; function here refuses a built-in menu, which Excel's ENABLE.COMMAND already
; does for a built-in command.
; =============================================================================
shm_bar7:  db 0                       ; the custom bar exists
shm_n1:    db 0                       ; custom menus on bar 1...
shm_n7:    db 0                       ; ...and on bar 7
shm_mbar:  db 0                       ; ADD.MENU's bar - NOT shm_acc8, which
                                       ; shm_mcrows spends as its title flag

; shm_barent - AL = the bar (1 or 7). out: BX = its table's first CUSTOM
; entry, CX = how many; CF=1 not a bar there is
;
; CX AND NOT CL, which is what it used to say while its callers stored the
; whole WORD: CH then arrived from whatever the evaluator or a kernel
; callback had left in it, and shm_barref's copy into shm_gst is read as a
; COUNT by DELETE.MENU's shift-down. One nonzero high byte moves fifteen
; hundred bytes of this package's own data - every built-in menu's title and
; item table - six bytes down, and the bar draws as rubble
shm_barent:
    xor ch, ch
    cmp al, 1
    jne .b7
    mov bx, sh_mtab + SH_MENU_N * 6
    mov cl, [cs:shm_n1]
    clc
    ret
.b7:
    cmp al, SH_BAR_CUSTOM
    jne .no
    cmp byte [cs:shm_bar7], 0
    je .no
    mov bx, sh_mtabc
    mov cl, [cs:shm_n7]
    clc
    ret
.no:
    stc
    ret

; shm_barshow - the bar showing is re-read: its length, its titles' widths,
; and a repaint. AL = the bar to show
shm_barshow:
    push ax
    push bx
    push cx
    cmp al, SH_BAR_CUSTOM
    je .c
    mov word [sh_mtabp], sh_mtab
    mov al, [cs:shm_n1]
    xor ah, ah
    add ax, SH_MENU_N
    jmp short .set
.c:
    mov word [sh_mtabp], sh_mtabc
    mov al, [cs:shm_n7]
    xor ah, ah
.set:
    mov [sh_mcount], ax
    SHOUT sh_mtab_calc
    mov byte [sh_macro_dirty], 1
    pop cx
    pop bx
    pop ax
    ret

; shm_barnow - AL = the bar showing (1 or 7)
shm_barnow:
    mov al, 1
    cmp word [sh_mtabp], sh_mtabc
    jne .out
    mov al, SH_BAR_CUSTOM
.out:
    ret

; shm_barref - the bar_num argument, then ',' and the menu argument: its
; position on the bar (1-based) or its title. out: AL = the bar, BX = the
; menu's table ENTRY, DI = its record; CF=1 no such custom menu. SI past it
shm_barref:
    xor ax, ax
    call shm_intarg1
    jc .no
    push ax
    call shm_barent
    pop ax
    jc .no
    mov [cs:shm_acc8], al
    mov [cs:shm_gcol], bx             ; the first custom entry
    mov [cs:shm_gst], cx              ; ...and how many
    cmp byte [si], ','
    jne .no
    inc si
    SHOUT sh_pcmp
    cmp byte [sh_curtype], SH_T_TEXT
    je .byname
    SHOUT sh_acc_toint
    jc .no
    dec ax                            ; a position: past the built-in nine
    cmp byte [cs:shm_acc8], 1         ; on bar 1
    jne .pos
    sub ax, SH_MENU_N
.pos:
    cmp ax, [cs:shm_gst]
    jae .no                           ; a built-in menu, or none
    mov bx, ax
    shl bx, 1
    add bx, ax
    shl bx, 1
    add bx, [cs:shm_gcol]
    jmp short .have
.byname:
    mov bx, [cs:shm_gcol]
    mov cx, [cs:shm_gst]
    jcxz .no
.n:
    push si
    push di
    mov si, sh_sacc
    mov di, [bx]                      ; the title
    call shm_streqi
    pop di
    pop si
    je .have
    add bx, 6
    loop .n
    jmp short .no
.have:
    mov di, [bx + 2]
    sub di, SH_MC_ITEMS               ; the record
    mov al, [cs:shm_acc8]
    clc
    ret
.no:
    stc
    ret

; shm_streqi - ZF=1 when DS:SI and DS:DI are the same text, any case, a
; command's check/disabled prefix bytes skipped on DI's side
shm_streqi:
    push ax
    push si
    push di
.p:
    cmp byte [di], 3
    jae .c
    cmp byte [di], 0
    je .c
    inc di
    jmp short .p
.c:
    mov al, [si]
    mov ah, [di]
    cmp al, 'a'
    jb .u1
    cmp al, 'z'
    ja .u1
    sub al, 32
.u1:
    cmp ah, 'a'
    jb .u2
    cmp ah, 'z'
    ja .u2
    sub ah, 32
.u2:
    cmp al, ah
    jne .out
    or al, al
    jz .out
    inc si
    inc di
    jmp short .c
.out:
    pop di
    pop si
    pop ax
    ret

; shm_cmdref - after shm_barref: ',' and the command, its position (1-based)
; or its name. in DI = the record, BX = the entry. out: CX = its index, CF=1
; none such. SI past it
shm_cmdref:
    cmp byte [si], ','
    jne .no
    inc si
    push bx
    push di
    SHOUT sh_pcmp
    pop di
    pop bx
    mov cx, [bx + 4]                  ; the count
    cmp byte [sh_curtype], SH_T_TEXT
    je .byname
    push cx
    SHOUT sh_acc_toint
    pop cx
    jc .no
    or ax, ax                         ; 0: the menu itself (ENABLE, RENAME)
    jz .zero
    dec ax
    cmp ax, cx
    jae .no
    mov cx, ax
    clc
    ret
.zero:
    mov cx, 0xFFFF
    clc
    ret
.byname:
    jcxz .no
    push bx
    push si
    xor ax, ax
.n:
    mov bx, ax
    shl bx, 1
    add bx, di
    mov bx, [bx + SH_MC_ITEMS]        ; its text
    push di
    mov si, sh_sacc
    mov di, bx
    call shm_streqi
    pop di
    je .hit
    inc ax
    cmp ax, cx
    jb .n
    pop si
    pop bx
.no:
    stc
    ret
.hit:
    mov cx, ax
    pop si
    pop bx
    clc
    ret

; shm_mcitem - item CX of the record at DI: its name is the DS string at SI
; (13 characters kept), its cell AX/BX (0xFFFF: none); plain, not checked
; and not disabled
shm_mcitem:
    push ax
    push bx
    push cx
    push si
    push di
    push bx
    push ax
    mov ax, cx
    shl ax, 1
    shl ax, 1
    mov bx, di
    add bx, ax
    pop word [bx + SH_MC_CELLS]
    pop word [bx + SH_MC_CELLS + 2]
    mov ax, cx
    mov bx, SH_MCTXT
    mul bx
    mov bx, di
    add bx, SH_MC_TEXT
    add bx, ax                        ; the text
    mov ax, cx
    shl ax, 1
    add ax, di
    mov di, ax
    lea ax, [bx + 2]
    mov [di + SH_MC_ITEMS], ax        ; the pointer: the name, no prefix
    mov word [bx], 0
    add bx, 2
    mov cx, SH_MCTXT - 3
.c:
    mov al, [si]
    mov [bx], al
    or al, al
    jz .e
    inc si
    inc bx
    loop .c
    mov byte [bx], 0
.e:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; shm_mcflags - item CX of record DI: AH bit 0 checked, bit 1 disabled,
; written as the prefix bytes sh_mdrop_draw reads (SH_MENU_CHK then
; MENU_DIS), and the pointer set to the first one there is
shm_mcflags:
    push ax
    push bx
    push dx
    mov dl, ah                        ; the flags, before MUL takes AH
    mov ax, cx
    mov bx, SH_MCTXT
    push dx
    mul bx
    pop dx
    mov bx, di
    add bx, SH_MC_TEXT
    add bx, ax                        ; the text: +0 +1 prefixes, +2 name
    lea ax, [bx + 2]                  ; neither: the name itself
    test dl, 2
    jz .nodis
    mov byte [bx + 1], MENU_DIS
    dec ax
.nodis:
    test dl, 1
    jz .set
    dec ax                            ; ...and the tick in front of that
    push bx
    mov bx, ax
    mov byte [bx], SH_MENU_CHK
    pop bx
.set:
    mov bx, cx
    shl bx, 1
    add bx, di
    mov [bx + SH_MC_ITEMS], ax
    pop dx
    pop bx
    pop ax
    ret

; shm_mcstate - item CX of record DI -> AH: bit 0 checked, bit 1 disabled,
; read back from where its pointer starts
shm_mcstate:
    push bx
    push dx
    mov bx, cx
    shl bx, 1
    add bx, di
    mov bx, [bx + SH_MC_ITEMS]
    xor ah, ah
.l:
    mov dl, [bx]
    cmp dl, SH_MENU_CHK
    jne .d
    or ah, 1
    inc bx
    jmp short .l
.d:
    cmp dl, MENU_DIS
    jne .out
    or ah, 2
    inc bx
    jmp short .l
.out:
    pop dx
    pop bx
    ret

; shm_mcrows - the rows of a description range (ref at SI) into record DI
; from item CX on: each row's first cell the command's name, its second the
; macro to run - a reference or a name, as text. out: CX = the items now.
; A row past SH_MCITEMS is dropped. When AL is 1 the FIRST row is the
; menu's title instead, into the record's +2
shm_mcrows:
    mov [cs:shm_acc8], al
    mov [cs:shm_gcnt], cx
    push di
    call shm_mrangeref                ; AX/BX .. CX/DX
    pop di
    jnc .bad
    cmp bx, dx
    jbe .o
    xchg bx, dx
.o:
    mov [cs:shm_ext_c1], ax           ; the name column
    mov [cs:shm_ext_r1], bx           ; the first row
    mov [cs:shm_ext_r2], dx           ; the last
.row:
    mov bx, [cs:shm_ext_r1]
    cmp bx, [cs:shm_ext_r2]
    ja .done
    mov ax, [cs:shm_ext_c1]
    SHOUT sh_cell_totext              ; -> sh_clipbuf
    cmp byte [cs:shm_acc8], 0
    je .cmd
    mov byte [cs:shm_acc8], 0         ; the title
    push si
    push di
    mov si, sh_clipbuf
    add di, 2
    mov cx, 13
.t:
    mov al, [si]
    mov [di], al
    or al, al
    jz .te
    inc si
    inc di
    loop .t
    mov byte [di], 0
.te:
    pop di
    pop si
    jmp short .next
.cmd:
    mov cx, [cs:shm_gcnt]
    cmp cx, SH_MCITEMS
    jae .next                         ; full: the row is dropped
    push si
    push di
    mov si, sh_clipbuf                ; the name, banked where the macro's
    mov di, shm_anstxt                ; text read will not reach it
.cp:
    mov al, [si]
    mov [cs:di], al
    inc si
    inc di
    or al, al
    jnz .cp
    mov ax, [cs:shm_ext_c1]
    inc ax
    mov bx, [cs:shm_ext_r1]
    SHOUT sh_cell_totext              ; the macro column
    mov si, sh_clipbuf
    mov di, sh_sacc
.cq:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .cq
    mov ax, 0xFFFF                    ; no macro: a command that does nothing
    mov bx, ax
    cmp byte [sh_sacc], 0
    je .nomac
    call shm_macref
    jc .mac
    mov ax, 0xFFFF
    mov bx, ax
.mac:
.nomac:
    mov si, shm_anstxt                ; back into DS for shm_mcitem
    mov di, sh_clipbuf
.cr:
    mov cl, [cs:si]
    mov [di], cl
    inc si
    inc di
    or cl, cl
    jnz .cr
    pop di
    push di
    mov cx, [cs:shm_gcnt]
    mov si, sh_clipbuf
    call shm_mcitem
    inc word [cs:shm_gcnt]
    pop di
    pop si
.next:
    inc word [cs:shm_ext_r1]
    jmp .row
.done:
    mov cx, [cs:shm_gcnt]
    clc
    ret
.bad:
    stc
    ret

; ADD.BAR() - the custom bar: 7. There is one; a second is refused
shm_maddbar:
    SHOUT sh_skipargs
    cmp byte [cs:shm_bar7], 0
    jne .bad
    mov byte [cs:shm_bar7], 1
    mov byte [cs:shm_n7], 0
    mov ax, SH_BAR_CUSTOM
    jmp shm_anum
.bad:
    jmp shm_merr0

; SHOW.BAR([bar_num]) - that bar in the window; omitted, SHEET's own
shm_mshowbar:
    mov ax, 1
    call shm_intarg1
    jc .bad
    push ax
    SHOUT sh_skipargs
    pop ax
    push ax
    call shm_barent
    pop ax
    jc .bad0
    call shm_barshow
    jmp shm_mtrue
.bad:
    jmp shm_merr
.bad0:
    jmp shm_merr0

; DELETE.BAR(bar_num) - the custom bar and its menus, when it is not the one
; showing (Excel's own rule)
shm_mdelbar:
    xor ax, ax
    call shm_intarg1
    jc .bad
    cmp ax, SH_BAR_CUSTOM
    jne .bad
    SHOUT sh_skipargs
    cmp byte [cs:shm_bar7], 0
    je .bad0
    call shm_barnow
    cmp al, SH_BAR_CUSTOM
    je .bad0
    mov bx, sh_mtabc                  ; its menus' records go free
    mov cl, [cs:shm_n7]
    xor ch, ch
    jcxz .gone
.f:
    mov di, [bx + 2]
    sub di, SH_MC_ITEMS
    mov byte [di], 0
    add bx, 6
    loop .f
.gone:
    mov byte [cs:shm_bar7], 0
    mov byte [cs:shm_n7], 0
    jmp shm_mtrue
.bad:
    jmp shm_merr
.bad0:
    jmp shm_merr0

; ADD.MENU(bar_num, menu_ref) - the menu the range describes, its first row
; the title and the rest its commands, onto the bar. out: its position
shm_maddmenu:
    xor ax, ax
    call shm_intarg1
    jc .bad
    push ax
    call shm_barent                   ; BX = where its entries start, CL =
    pop ax                            ; how many
    jc .bad
    mov [cs:shm_mbar], al
    mov di, sh_mcrec                  ; a free record
    mov dx, SH_MCUST
.f:
    cmp byte [di], 0
    je .got
    add di, SH_MCREC
    dec dx
    jnz .f
    jmp .bad
.got:
    xor ch, ch
    mov ax, cx                        ; the new entry: after the others
    shl ax, 1
    add ax, cx
    shl ax, 1
    add bx, ax
    push bx
    cmp byte [si], ','
    jne .badpop
    inc si
    push ax
    mov al, [cs:shm_mbar]
    mov [di], al                      ; taken, by this bar
    pop ax
    mov byte [di + 2], 0
    mov al, 1                         ; the first row is the title
    xor cx, cx
    push di
    call shm_mcrows
    pop di
    jc .badrec
    pop bx
    lea ax, [di + 2]                  ; the entry: title, items, count
    mov [bx], ax
    lea ax, [di + SH_MC_ITEMS]
    mov [bx + 2], ax
    mov [bx + 4], cx
    SHOUT sh_skipargs
    push bx                           ; ...and it must FIT: the bar is drawn
    mov bx, sh_mtab                   ; in the window, and a title past its
    mov cl, [cs:shm_n1]               ; edge was drawn outside it and left
    add cl, SH_MENU_N + 1             ; there. Bar 1 has room for about three
    cmp byte [cs:shm_mbar], 1         ; letters after Help
    je .fit
    mov bx, sh_mtabc
    mov cl, [cs:shm_n7]
    inc cl
.fit:
    xor ch, ch
    call shm_barfits
    pop bx
    jnc .fits
    mov byte [di], 0                  ; refused: the record and the entry go
    mov word [bx], 0
    mov word [bx + 2], 0
    mov word [bx + 4], 0
    jmp shm_merr0
.fits:
    mov al, [cs:shm_mbar]             ; one more on that bar
    mov bx, shm_n1
    cmp al, 1
    je .inc
    mov bx, shm_n7
.inc:
    inc byte [cs:bx]
    mov ah, [cs:bx]                   ; its position, and the bar re-read if
    push ax                           ; it is the one showing
    call shm_barnow
    pop dx
    cmp al, dl
    jne .pos
    push dx                           ; sh_mtab_calc does not keep DX
    call shm_barshow
    pop dx
.pos:
    mov al, dh
    xor ah, ah
    cmp dl, 1
    jne .n
    add ax, SH_MENU_N
.n:
    jmp shm_anum
.badrec:
    mov byte [di], 0
.badpop:
    pop bx
.bad:
    jmp shm_merr

shm_rent:   db 0                      ; RENAME.COMMAND is renaming a TITLE...
shm_renbar: db 0                      ; ...on this bar

; shm_renfits - CF=1 when the bar in shm_renbar no longer fits its window
shm_renfits:
    push bx
    push cx
    mov bx, sh_mtab
    mov cl, [cs:shm_n1]
    add cl, SH_MENU_N
    cmp byte [cs:shm_renbar], 1
    je .go
    mov bx, sh_mtabc
    mov cl, [cs:shm_n7]
.go:
    xor ch, ch
    call shm_barfits
    pop cx
    pop bx
    ret

; shm_barfits - CF=1 when CX titles of the table at BX, each with its pads,
; are wider than the window's content
shm_barfits:
    push ax
    push bx
    push cx
    push dx
    push si
    xor dx, dx
.l:
    jcxz .done
    mov si, [bx]
    call OSAPI_FONT_WIDTH             ; AX
    add ax, SH_MPAD * 2
    add dx, ax
    add bx, 6
    dec cx
    jmp short .l
.done:
    mov ax, [sh_cw]
    cmp ax, dx                        ; CF=1: the window is narrower
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; ADD.COMMAND(bar_num, menu, command_ref) - more commands onto a custom menu
shm_maddcmd:
    call shm_barref
    jc .bad
    cmp byte [si], ','
    jne .bad
    inc si
    push bx
    mov cx, [bx + 4]
    xor al, al
    push di
    call shm_mcrows
    pop di
    pop bx
    jc .bad
    mov [bx + 4], cx
    SHOUT sh_skipargs
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; DELETE.MENU(bar_num, menu) - the menu gone, the ones after it moving up
shm_mdelmenu:
    call shm_barref
    jc .bad
    push si
    mov byte [di], 0                  ; the record is free
    mov [cs:shm_acc8], al
    mov cx, [cs:shm_gst]              ; the bar's custom entries end here
    mov ax, cx
    shl ax, 1
    add ax, cx
    shl ax, 1
    add ax, [cs:shm_gcol]
    mov di, bx
    lea si, [bx + 6]
.mv:
    cmp si, ax
    jae .mvd
    mov dx, [si]
    mov [di], dx
    add si, 2
    add di, 2
    jmp short .mv
.mvd:
    mov word [di], 0
    mov word [di + 2], 0
    mov word [di + 4], 0
    mov bx, shm_n1
    cmp byte [cs:shm_acc8], 1
    je .d
    mov bx, shm_n7
.d:
    dec byte [cs:bx]
    pop si
    SHOUT sh_skipargs
    call shm_barnow
    cmp al, [cs:shm_acc8]
    jne .done
    call shm_barshow
.done:
    jmp shm_mtrue
.bad:
    jmp shm_merr

; DELETE.COMMAND(bar_num, menu, command) - the command gone, the ones after
; it moving up: their texts, cells and pointers together, because an item's
; text slot is found by its index
shm_mdelcmd:
    call shm_barref
    jc .bad
    call shm_cmdref
    jc .bad
    cmp cx, 0xFFFF
    je .bad
    push si
    push bx
    mov dx, [bx + 4]
    dec dx                            ; the last index, once one is gone
.l:
    cmp cx, dx
    jae .last
    push cx                           ; text[i] <- text[i+1]
    mov ax, cx
    mov bx, SH_MCTXT
    push dx
    mul bx
    pop dx
    lea si, [di + SH_MC_TEXT]
    add si, ax
    mov bx, si
    add si, SH_MCTXT
    mov cx, SH_MCTXT
.t:
    mov al, [si]
    mov [bx], al
    inc si
    inc bx
    loop .t
    pop cx
    mov bx, cx                        ; ptr[i] <- ptr[i+1] - SH_MCTXT
    shl bx, 1
    add bx, di
    mov ax, [bx + SH_MC_ITEMS + 2]
    sub ax, SH_MCTXT
    mov [bx + SH_MC_ITEMS], ax
    mov bx, cx                        ; cell[i] <- cell[i+1]
    shl bx, 1
    shl bx, 1
    add bx, di
    mov ax, [bx + SH_MC_CELLS + 4]
    mov [bx + SH_MC_CELLS], ax
    mov ax, [bx + SH_MC_CELLS + 6]
    mov [bx + SH_MC_CELLS + 2], ax
    inc cx
    jmp short .l
.last:
    pop bx
    dec word [bx + 4]
    pop si
    SHOUT sh_skipargs
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr

; ENABLE.COMMAND(bar_num, menu, command, enable) / CHECK.COMMAND(bar_num,
; menu, command, check) - the command greyed or not, ticked or not; command 0
; is every command of the menu for ENABLE (Excel's "the entire menu")
shm_menablecmd:
    mov byte [cs:shm_gmask], 2
    jmp short shm_mflagcmd
shm_mcheckcmd:
    mov byte [cs:shm_gmask], 1
shm_mflagcmd:
    call shm_barref
    jc .bad
    call shm_cmdref
    jc .bad
    push bx
    push cx
    push di
    call shm_boolnext
    pop di
    pop cx
    pop bx
    jnc .bad
    xor al, 1                         ; ENABLE TRUE is NOT disabled
    cmp byte [cs:shm_gmask], 2
    je .v
    xor al, 1                         ; CHECK TRUE is checked
.v:
    mov [cs:shm_acc8], al
    SHOUT sh_skipargs
    cmp cx, 0xFFFF
    jne .one
    cmp byte [cs:shm_gmask], 2        ; 0: the whole menu - ENABLE only
    jne .bad0
    mov dx, [bx + 4]
    xor cx, cx
.all:
    cmp cx, dx
    jae .done
    call shm_mcset1
    inc cx
    jmp short .all
.one:
    call shm_mcset1
.done:
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.bad:
    jmp shm_merr
.bad0:
    jmp shm_merr0

; shm_mcset1 - item CX of record DI: its [shm_gmask] bit set if [shm_acc8]
shm_mcset1:
    push ax
    call shm_mcstate
    mov al, [cs:shm_gmask]
    not al
    and ah, al
    cmp byte [cs:shm_acc8], 0
    je .w
    or ah, [cs:shm_gmask]
.w:
    call shm_mcflags
    pop ax
    ret

; RENAME.COMMAND(bar_num, menu, command, name_text) - a new name, the state
; kept; command 0 renames the menu itself
shm_mrencmd:
    call shm_barref
    jc .bad
    call shm_cmdref
    jc .bad
    cmp byte [si], ','
    jne .bad
    inc si
    push bx
    push cx
    push di
    call shm_textfirst
    pop di
    pop cx
    pop bx
    jc .bad
    SHOUT sh_skipargs
    push si
    mov al, [cs:shm_acc8]             ; the bar, banked before the copy: that
    mov [cs:shm_renbar], al           ; byte is shared scratch
    mov byte [cs:shm_rent], 0
    lea bx, [di + 2]                  ; the title...
    cmp cx, 0xFFFF
    jne .name
    mov byte [cs:shm_rent], 1         ; ...which has to FIT (81.95.3), so the
    push si                           ; old one is banked to put back
    push di
    mov si, bx
    mov di, sh_tbuf
    mov cx, SH_MC_ITEMS - 2           ; the TITLE field, and not SH_MCTXT: an
.bk:                                  ; item's text is 16 and a title 14, and
                                       ; the two bytes past it are the first
                                       ; item's pointer
    mov al, [si]
    mov [di], al
    inc si
    inc di
    loop .bk
    pop di
    pop si
    jmp short .copy
.name:
    mov ax, cx                        ; ...or the command's name
    mov bx, SH_MCTXT
    mul bx
    lea bx, [di + SH_MC_TEXT + 2]
    add bx, ax
.copy:
    mov si, sh_sacc
    mov cx, 13
.c:
    mov al, [si]
    mov [bx], al
    or al, al
    jz .e
    inc si
    inc bx
    loop .c
    mov byte [bx], 0
.e:
    pop si
    cmp byte [cs:shm_rent], 0
    je .fits
    call shm_renfits                  ; a title past the window's edge is
    jnc .fits                         ; drawn outside it and left there
    push si
    lea bx, [di + 2]
    mov si, sh_tbuf
    mov cx, SH_MC_ITEMS - 2
.put:
    mov al, [si]
    mov [bx], al
    inc si
    inc bx
    loop .put
    pop si
    jmp shm_merr0
.fits:
    call shm_barnow                   ; a title's width changed
    call shm_barshow
    jmp shm_mtrue
.bad:
    jmp shm_merr

; =============================================================================
; DIALOG.BOX (macro plan wave 4, 81.96): a dialog a macro describes in a
; range seven columns wide - item type, x, y, width, height, text, and the
; initial value that becomes the result - whose first row is the dialog
; itself. The run PAUSES while it is up (INPUT's mechanism, 81.63) and the
; cell answers on its second evaluation: the pressed button's item number,
; counted from the second row, or FALSE for Cancel. OK first writes every
; item's result into its seventh column.
;
; Types: 1 default OK, 2 default Cancel, 3 OK, 4 Cancel, 5 text, 6 text edit,
; 7 integer edit, 8 number edit, 9 formula edit, 10 reference edit, 11 option
; group, 12 option button, 13 check box, 14 group box. The list boxes (15,
; 16) are refused, and so is a dialog with more than SHM_DBMAX items or
; SHM_DBEDITS edit boxes.
;
; Positions are Excel's dialog units: an eighth of a character across and a
; twelfth down - a pixel across and two thirds of one down, with this
; machine's 8x8 cell. The window's template, its thunks and its close are
; resident (sh_dbx_*), because the kernel calls near procs in the package.
; The edit boxes share ONE line block and ONE buffer in DS (os88line reads
; its buffer there); each box's text lives here and is swapped in to be
; drawn or typed at.
; =============================================================================
SHM_DBMAX   equ 16                    ; items after the first row
SHM_DBREC   equ 12                    ; +0 type +1 state (check: on; group:
                                       ; the button on, 1-based; edit: its
                                       ; slot) +2 x +4 y +6 w +8 h (pixels,
                                       ; from the content's origin) +10 text
SHM_DBTXT   equ 24
    times SHM_DBTXT - 24 db 0         ; sh_dbx_gtxt's literal (81.111)
    times 24 - SHM_DBTXT db 0
SHM_DBEDITS equ 4
shm_dbn:    db 0                      ; items
shm_dbpend: db 0                      ; DIALOG.BOX waits for its answer...
shm_dbans:  db 0                      ; ...which is the item, 0 for Cancel
shm_dbfoc:  db 0xFF                   ; the ITEM whose edit box has the keys
shm_dbslots: db 0                     ; edit slots given out
shm_dbdef:  db 0xFF                   ; the item Enter presses
shm_dbcol:  dw 0                      ; the range's first column and row
shm_dbrow:  dw 0
shm_dbw:    dw 0                      ; the window's size, until it opens
shm_dbh:    dw 0
shm_dbopen: db 0                      ; ...which the pause is to do
shm_dbox:   dw 0                      ; the content's origin
shm_dboy:   dw 0
shm_dbit:   times SHM_DBMAX * SHM_DBREC db 0
shm_dbtx:   times SHM_DBMAX * SHM_DBTXT db 0
shm_dbed:   times SHM_DBEDITS * SH_DBX_EDLEN db 0
shm_dbcv:   times SHM_DBEDITS * 4 db 0 ; each box's LN_CAR and LN_VIEW
shm_s_dbok: db 'OK', 0
shm_s_dbcan: db 'Cancel', 0

; shm_dbnum - the number in the cell AX col, BX row, as an integer: text,
; an error or an empty cell is 0. A logical is 1 or 0
shm_dbnum:
    push si
    push di
    push es
    SHOUT sh_findcell
    jnc .zero
    mov es, [sh_cellseg]
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    je .zero
    cmp byte [es:di+SH_C_TYPE], SH_T_ERR
    je .zero
    mov si, di
    SHOUT sh_cellval_to_acc_si
    SHOUT sh_acc_toint
    jnc .out
.zero:
    xor ax, ax
.out:
    pop es
    pop di
    pop si
    ret

; shm_dbitem - DI = item AX's record (AX 0-based)
shm_dbitem:
    push ax
    push dx
    mov dx, SHM_DBREC
    mul dx
    add ax, shm_dbit
    mov di, ax
    pop dx
    pop ax
    ret

; shm_dbslot - BX = the text of item DI's edit box (CS), and SI = its caret
; pair in shm_dbcv
shm_dbslot:
    push ax
    push dx
    mov al, [cs:di+1]
    xor ah, ah
    mov si, ax
    shl si, 1
    shl si, 1
    add si, shm_dbcv
    mov dx, SH_DBX_EDLEN
    mul dx
    add ax, shm_dbed
    mov bx, ax
    pop dx
    pop ax
    ret

; shm_db23 - AX = AX * 2 / 3: Excel's vertical dialog unit, in pixels.
; SIGNED, because the callers' sign tests come after it: an unsigned divide
; made -30 into 21,825 and no test below ever saw a negative
shm_db23:
    push dx
    push bx
    mov bx, 2
    imul bx                           ; DX:AX, so no shift can overflow
    mov bx, 3
    idiv bx
    pop bx
    pop dx
    ret

; shm_dbtext - the text of the cell AX col, BX row into CS:DI, CX bytes at
; most with the NUL. out: AX = its length
shm_dbtext:
    push si
    push di
    push cx
    SHOUT sh_cell_totext
    pop cx
    push cx
    dec cx
    xor ax, ax
    mov si, sh_clipbuf
.c:
    cmp byte [si], 0
    je .e
    push ax
    mov al, [si]
    mov [cs:di], al
    pop ax
    inc ax
    inc si
    inc di
    loop .c
.e:
    mov byte [cs:di], 0
    pop cx
    pop di
    pop si
    ret

; DIALOG.BOX(dialog_ref)
shm_mdbox:
    cmp byte [cs:shm_dbpend], 0       ; the second evaluation: the answer
    je .ask
    mov byte [cs:shm_dbpend], 0
    SHOUT sh_skipargs
    mov al, [cs:shm_dbans]
    or al, al
    jz .f
    xor ah, ah
    jmp shm_anum
.f:
    jmp shm_mfalse
.ask:
    cmp word [sh_dbx_win], 0          ; one at a time
    jne .bad
    call shm_mrangeref
    jnc .bad
    push ax                           ; sh_skipargs takes AL
    SHOUT sh_skipargs
    pop ax
    cmp bx, dx                        ; the range corners in either order
    jbe .o
    xchg bx, dx
.o:
    cmp ax, cx
    jbe .oc
    xchg ax, cx
.oc:
    sub cx, ax                        ; SEVEN columns, as Excel asks: type,
    cmp cx, 6                         ; x, y, width, height, text and the
    jb .bad0                          ; result. A narrower range would take
                                       ; an item's size from cells OUTSIDE
                                       ; it, and OK would write every result
                                       ; over them
    mov [cs:shm_dbcol], ax
    mov [cs:shm_dbrow], bx
    sub dx, bx                        ; the items: every row after the first
    jz .bad0                          ; ...and a dialog with no items has no
    cmp dx, SHM_DBMAX                 ; button either, so nothing but the
    ja .bad0                          ; close box could end it
    mov [cs:shm_dbn], dl
    mov byte [cs:shm_dbfoc], 0xFF
    mov byte [cs:shm_dbdef], 0xFF
    mov byte [cs:shm_dbans], 0
    mov byte [cs:shm_dbslots], 0
    push si
    xor cx, cx
.item:
    cmp cl, [cs:shm_dbn]
    jae .made
    call shm_dbparse
    jc .refuse
    inc cx
    jmp short .item
.refuse:
    pop si
.bad0:
    jmp shm_merr0
.made:
    cmp byte [cs:shm_dbdef], 0xFF     ; no default named: the first OK
    jne .title
    xor cx, cx
.fd:
    cmp cl, [cs:shm_dbn]
    jae .title
    mov ax, cx
    call shm_dbitem
    cmp byte [cs:di], 3
    je .fdok
    inc cx
    jmp short .fd
.fdok:
    mov [cs:shm_dbdef], cl
.title:
    mov ax, [cs:shm_dbcol]            ; the dialog's own row: its title...
    add ax, 5
    mov bx, [cs:shm_dbrow]
    SHOUT sh_cell_totext
    mov si, sh_clipbuf
    mov di, sh_macro_msg              ; ...where the template names it
    mov cx, OS88UI_AMAX
.tt:
    mov al, [si]
    mov [di], al
    or al, al
    jz .size
    inc si
    inc di
    loop .tt
    mov byte [di], 0
.size:
    mov ax, [cs:shm_dbcol]            ; ...and its size
    add ax, 3
    mov bx, [cs:shm_dbrow]
    call shm_dbnum
    cmp ax, 0                         ; ...only be ended by the close box
    jg .w
    mov ax, 320
.w:
    add ax, 2
    push ax
    mov ax, [cs:shm_dbcol]
    add ax, 4
    call shm_dbnum
    call shm_db23
    cmp ax, 0                         ; a NEGATIVE size would make a window
    jg .h                             ; no click can ever hit (wm_hit tests
    mov ax, 100                       ; x < W_X + W_W), and the run could
.h:
    add ax, TITLE_H + 2
    mov [cs:shm_dbh], ax
    pop ax
    mov [cs:shm_dbw], ax
    pop si
    mov byte [cs:shm_dbpend], 1       ; the window opens when the step
    mov byte [cs:shm_dbopen], 1       ; pauses (shm_mstep), AFTER the sheet
                                       ; is painted - a window made here was
                                       ; painted over by the pause's repaint
    mov byte [sh_macro_ctl], SH_MC_PAUSEH
    mov byte [sh_macro_wait], SH_MW_DBOX
    jmp shm_mfalse
.bad:
    jmp shm_merr

; shm_dbparse - item CX (0-based) off its row into its record. CF=1 refused
shm_dbparse:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov ax, cx
    call shm_dbitem                   ; DI = its record
    mov bx, [cs:shm_dbrow]
    add bx, cx
    inc bx                            ; BX = its row, from here to the end
    mov ax, [cs:shm_dbcol]
    call shm_dbnum
    cmp ax, 1
    jb .no
    cmp ax, 14
    ja .no                            ; 15, 16: the list boxes
    mov [cs:di], al
    mov byte [cs:di+1], 0
    cmp al, 2                         ; 1 and 2 are the DEFAULT button
    ja .notdef
    cmp byte [cs:shm_dbdef], 0xFF
    jne .notdef
    mov [cs:shm_dbdef], cl
.notdef:
    mov ax, [cs:shm_dbcol]
    inc ax
    call shm_dbnum
    mov [cs:di+2], ax
    mov ax, [cs:shm_dbcol]
    add ax, 2
    call shm_dbnum
    call shm_db23
    or ax, ax                         ; a negative y is the top, as a
    jns .yok                          ; negative size is none
    xor ax, ax
.yok:
    mov [cs:di+4], ax
    mov ax, [cs:shm_dbcol]
    add ax, 3
    call shm_dbnum
    or ax, ax                         ; a negative width or height is none,
    jns .wok                          ; so shm_dbsize gives the item its own
    xor ax, ax
.wok:
    mov [cs:di+6], ax
    mov ax, [cs:shm_dbcol]
    add ax, 4
    call shm_dbnum
    call shm_db23
    or ax, ax
    jns .hok
    xor ax, ax
.hok:
    mov [cs:di+8], ax
    mov ax, cx                        ; its text
    mov dx, SHM_DBTXT
    mul dx
    add ax, shm_dbtx
    mov [cs:di+10], ax
    push di
    mov di, ax
    mov ax, [cs:shm_dbcol]
    add ax, 5
    push cx
    mov cx, SHM_DBTXT
    call shm_dbtext
    pop cx
    pop di
    call shm_dbsize                   ; a blank width or height: its own
    mov dx, [cs:shm_dbcol]            ; DX = the initial value's column
    add dx, 6
    mov al, [cs:di]
    cmp al, 13
    je .check
    cmp al, 11
    je .group
    cmp al, 6
    jb .ok
    cmp al, 10
    ja .ok
    mov al, [cs:shm_dbslots]          ; an edit box: a slot of its own
    cmp al, SHM_DBEDITS
    jae .no
    inc byte [cs:shm_dbslots]
    mov [cs:di+1], al
    cmp byte [cs:shm_dbfoc], 0xFF     ; the first edit box has the keys
    jne .nofoc
    mov [cs:shm_dbfoc], cl
.nofoc:
    push bx
    call shm_dbslot                   ; BX its text, SI its caret pair
    mov ax, dx
    mov di, bx
    pop bx
    push cx
    mov cx, SH_DBX_EDLEN
    call shm_dbtext                   ; AX = its length...
    pop cx
    mov [cs:si], ax                   ; ...the caret at the END, as
    mov word [cs:si+2], 0             ; os88line_set would put it
    jmp short .ok
.check:
    mov ax, dx
    call shm_dbnum
    or ax, ax
    jz .ok
    mov byte [cs:di+1], 1
    jmp short .ok
.group:
    mov ax, dx
    call shm_dbnum
    or ax, ax
    jnz .gset
    inc ax                            ; blank: the first button, as Excel
.gset:
    mov [cs:di+1], al
.ok:
    clc
    jmp short .out
.no:
    stc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; shm_dbsize - item DI's blank width or height, from what it is
shm_dbsize:
    push ax
    push bx
    push si
    mov si, [cs:di+10]                ; the text's length, in pixels
    xor bx, bx
.l:
    cmp byte [cs:si+bx], 0
    je .e
    inc bx
    jmp short .l
.e:
    shl bx, 1
    shl bx, 1
    shl bx, 1
    cmp word [cs:di+6], 0
    jne .hgt
    mov ax, OS88UI_ABW                ; a button: every one the same
    cmp byte [cs:di], 4
    jbe .setw
    mov ax, bx                        ; text: its own length
    cmp byte [cs:di], 5
    je .setw
    mov ax, 160                       ; an edit box: twenty characters
    cmp byte [cs:di], 10
    jbe .setw
    lea ax, [bx+16]                   ; a check or option: the glyph too
.setw:
    mov [cs:di+6], ax
.hgt:
    cmp word [cs:di+8], 0
    jne .out
    mov ax, 15
    cmp byte [cs:di], 4
    jbe .seth
    mov ax, 8
    cmp byte [cs:di], 5
    je .seth
    mov ax, 14
.seth:
    mov [cs:di+8], ax
.out:
    pop si
    pop bx
    pop ax
    ret

; shm_dbrect - item DI's rectangle on the glass into sh_tbuf's first eight
; bytes (DS, where os88ui_btn reads one): x1 y1 x2 y2, inclusive
shm_dbrect:
    push ax
    mov ax, [cs:di+2]
    add ax, [cs:shm_dbox]
    mov [sh_tbuf], ax
    add ax, [cs:di+6]
    dec ax
    mov [sh_tbuf+4], ax
    mov ax, [cs:di+4]
    add ax, [cs:shm_dboy]
    mov [sh_tbuf+2], ax
    add ax, [cs:di+8]
    dec ax
    mov [sh_tbuf+6], ax
    pop ax
    ret

; shm_dblabel - item DI's text into sh_tbuf+8 (DS), a button's own default
; when it has none; out SI = it
shm_dblabel:
    push ax
    push bx
    push di
    mov bx, [cs:di+10]
    cmp byte [cs:bx], 0
    jne .have
    cmp byte [cs:di], 4
    ja .have
    mov bx, shm_s_dbok
    test byte [cs:di], 1              ; 1 and 3 are OK, 2 and 4 Cancel
    jnz .have
    mov bx, shm_s_dbcan
.have:
    mov di, sh_tbuf + 8
.c:
    mov al, [cs:bx]
    mov [di], al
    inc bx
    inc di
    or al, al
    jnz .c
    pop di
    pop bx
    pop ax
    mov si, sh_tbuf + 8
    ret

; shm_dbload - point the shared edit block at item DI's box: its rect, its
; text swapped into the one DS buffer, its caret, and the focus if it has it.
; out: SI = the block
shm_dbload:
    push ax
    push bx
    push cx
    push di
    call shm_dbrect
    call shm_dbslot                   ; BX its text, SI its caret pair
    push si
    mov si, sh_dbx_line
    mov ax, [sh_tbuf]
    mov [si+LN_X1], ax
    mov ax, [sh_tbuf+2]
    mov [si+LN_Y1], ax
    mov ax, [sh_tbuf+4]
    mov [si+LN_X2], ax
    mov ax, [sh_tbuf+6]
    mov [si+LN_Y2], ax
    mov word [si+LN_BUF], sh_dbx_ebuf
    mov word [si+LN_MAX], SH_DBX_EDLEN
    mov cx, di                        ; the focus: is it this item?
    sub cx, shm_dbit
    mov ax, cx
    mov cl, SHM_DBREC
    div cl
    cmp al, [cs:shm_dbfoc]
    mov byte [si+LN_FOCUS], 0
    jne .nf
    mov byte [si+LN_FOCUS], 1
.nf:
    mov di, sh_dbx_ebuf
    xor cx, cx
.c:
    mov al, [cs:bx]
    mov [di], al
    or al, al
    jz .e
    inc bx
    inc di
    inc cx
    jmp short .c
.e:
    mov [si+LN_LEN], cx
    pop bx                            ; the caret pair
    mov ax, [cs:bx]
    cmp ax, cx
    jbe .car
    mov ax, cx
.car:
    mov [si+LN_CAR], ax
    mov ax, [cs:bx+2]
    mov [si+LN_VIEW], ax
    pop di
    pop cx
    pop bx
    pop ax
    ret

; shm_dbsave - the shared block's text and caret back into item DI's box
shm_dbsave:
    push ax
    push bx
    push si
    push di
    call shm_dbslot
    mov di, sh_dbx_line
    mov ax, [di+LN_CAR]
    mov [cs:si], ax
    mov ax, [di+LN_VIEW]
    mov [cs:si+2], ax
    mov si, sh_dbx_ebuf
.c:
    mov al, [si]
    mov [cs:bx], al
    inc si
    inc bx
    or al, al
    jnz .c
    pop di
    pop si
    pop bx
    pop ax
    ret

; shm_dbgroup - item CX (an option button): AL = its place in its group,
; 1-based, and DI = the group's record; CF=1 it has no group
shm_dbgroup:
    push cx
    mov al, 1
.back:
    jcxz .none
    dec cx
    push ax
    mov ax, cx
    call shm_dbitem
    pop ax
    cmp byte [cs:di], 12
    jne .top
    inc al
    jmp short .back
.top:
    cmp byte [cs:di], 11
    jne .none
    clc
    pop cx
    ret
.none:
    stc
    pop cx
    ret

; shm_dbdraw - item CX, on the glass (the gfx lock held)
shm_dbdraw:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov ax, cx
    call shm_dbitem
    call shm_dbrect
    call shm_dblabel                  ; SI = its label, in DS
    mov al, [cs:di]
    cmp al, 4
    ja .notbtn
    xor ax, ax                        ; a button, through the paint record
    cmp cl, [cs:shm_dbdef]            ; (81.111): the default wears the ring
    jne .btn
    mov al, OS88UI_DEF
.btn:
    mov [sh_dbx_pflg], ax
    xor ax, ax                        ; ...and the pressed look is the
    cmp cl, [sh_dbx_gitem]            ; gesture record's, for the one item
    jne .up                           ; it is staged at
    mov ax, [sh_dbx_btrec + OS88UI_BT_DOWN]
.up:
    mov bx, sh_dbx_prec
    mov [bx + OS88UI_BT_DOWN], ax
    mov al, 1
    SHOUT os88ui_btn
    jmp .out
.notbtn:
    cmp al, 5
    jne .notext
.label:
    cmp byte [si], 0
    je .out
    mov cx, [sh_tbuf]
    mov dx, [sh_tbuf+2]
.run:
    mov al, CBLACK
    mov ah, CWHITE
    call OSAPI_FONT_RUN
    jmp .out
.notext:
    cmp al, 10
    ja .notedit
    call shm_dbload
    SHOUT os88line_draw
    jmp .out
.notedit:
    cmp al, 11
    je .box
    cmp al, 14
    je .box
    mov ah, OS88UI_GCHECK             ; a check box or an option button
    cmp al, 13
    je .chk
    mov ah, OS88UI_GRADIO
    push di
    push ax
    call shm_dbgroup                  ; AL its place, DI its group
    mov dl, al
    pop ax
    jc .off
    cmp dl, [cs:di+1]
    jne .off
    or ah, OS88UI_GON
.off:
    pop di
    jmp short .glyph
.chk:
    cmp byte [cs:di+1], 0
    je .glyph
    or ah, OS88UI_GON
.glyph:
    mov al, ah
    xor ah, ah
    mov cx, [sh_tbuf]
    mov dx, [sh_tbuf+2]
    SHOUT os88ui_glyph
    add cx, OS88UI_GW + 4
    add dx, 2
    cmp byte [si], 0
    jne .run
    jmp short .out
.box:
    cmp word [cs:di+6], 0             ; a group box - drawn only when it
    je .out                           ; has a size
    mov ax, [sh_tbuf]
    mov bx, [sh_tbuf+2]
    add bx, 4
    mov cx, [sh_tbuf+4]
    mov dx, [sh_tbuf+6]
    push ax
    mov al, CBLACK
    call OSAPI_SET_COLOR
    pop ax
    call OSAPI_GFX_FRAME
    cmp byte [si], 0                  ; its title, across the top edge
    je .out
    mov cx, [sh_tbuf]
    add cx, 8
    mov dx, [sh_tbuf+2]
    jmp .run
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; verb SHM2_DPAINT: the whole dialog. SI = the window, the gfx lock held
shm_dbpaint:
    push ax
    push bx
    push cx
    push dx
    mov bx, si
    call OSAPI_WM_CONTENT
    mov [cs:shm_dbox], ax
    mov [cs:shm_dboy], dx
    mov al, CBLACK
    call OSAPI_SET_COLOR
    xor cx, cx
.l:
    cmp cl, [cs:shm_dbn]
    jae .out
    call shm_dbdraw
    inc cx
    jmp short .l
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; shm_dbpress - item CX pressed: an OK writes every result and answers CX+1,
; a Cancel answers FALSE; either way the resident thunk closes the window
; and the run carries on (sh_dbx_ev)
shm_dbpress:
    push ax
    push di
    mov ax, cx
    call shm_dbitem
    mov byte [cs:shm_dbans], 0
    test byte [cs:di], 1              ; 1 and 3 are OK
    jz .done
    call shm_dbresults
    mov al, cl
    inc al
    mov [cs:shm_dbans], al
.done:
    mov byte [sh_dbx_done], 1
    pop di
    pop ax
    ret

; shm_dbresults - every item's result into its seventh column: an edit box
; its text (a number when it reads as one, for the number boxes), a check box
; TRUE or FALSE, an option group the place of the button that is on
shm_dbresults:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    xor cx, cx
.l:
    cmp cl, [cs:shm_dbn]
    jb .more
    jmp .out
.more:
    mov ax, cx
    call shm_dbitem
    mov bx, [cs:shm_dbrow]
    add bx, cx
    inc bx
    mov ax, [cs:shm_dbcol]
    add ax, 6
    mov dl, [cs:di]
    cmp dl, 13
    je .check
    cmp dl, 11
    je .group
    cmp dl, 6
    jb .next
    cmp dl, 10
    ja .next
    push bx                           ; an edit box: its text, into DS
    call shm_dbslot
    mov si, bx
    mov di, sh_rwsrc
.c:
    push ax
    mov al, [cs:si]
    mov [di], al
    pop ax
    inc si
    inc di
    cmp byte [di-1], 0
    jne .c
    pop bx
    cmp dl, 7                         ; the integer and number boxes: a
    je .num                           ; number when it is one
    cmp dl, 8
    jne .text
.num:
    push ax
    push bx
    push si
    mov si, sh_rwsrc
    SHOUT fp_atof
    jc .ntext
    cmp byte [si], 0
    jne .ntext
    SHOUT sh_acc_store
    pop si
    pop bx
    pop ax
    SHOUT sh_setvald
    jmp short .next
.ntext:
    pop si
    pop bx
    pop ax
.text:
    mov si, sh_rwsrc
    SHOUT sh_settext
    jmp short .next
.check:
    mov dl, [cs:di+1]
    SHOUT sh_setbool
    jmp short .next
.group:
    push ax
    mov al, [cs:di+1]
    xor ah, ah
    SHOUT sh_acc_int
    pop ax
    SHOUT sh_setvald
.next:
    inc cx
    jmp .l
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; shm_dbnextedit - the keys to the edit box after the focused one (Tab)
shm_dbnextedit:
    push ax
    push cx
    push di
    mov cl, [cs:shm_dbfoc]
    cmp cl, 0xFF
    je .out
    xor ch, ch
    push cx
    mov cx, [cs:shm_dbn]              ; at most every item once round
    and cx, 0xFF
    mov ah, cl
    pop cx
.l:
    inc cl
    cmp cl, [cs:shm_dbn]
    jb .t
    xor cl, cl
.t:
    push ax
    mov ax, cx
    call shm_dbitem
    pop ax
    cmp byte [cs:di], 6
    jb .n
    cmp byte [cs:di], 10
    jbe .found
.n:
    dec ah
    jnz .l
    jmp short .out
.found:
    call shm_dbfocus
.out:
    pop di
    pop cx
    pop ax
    ret

; shm_dbfocus - the keys to item CX's edit box: the old one drawn without
; its caret, the new one with it
shm_dbfocus:
    push ax
    push cx
    mov al, [cs:shm_dbfoc]
    mov [cs:shm_dbfoc], cl
    cmp al, 0xFF
    je .new
    cmp al, cl
    je .new
    push cx
    mov cl, al
    xor ch, ch
    call shm_dbdraw
    pop cx
.new:
    call shm_dbdraw
    pop cx
    pop ax
    ret

; verb SHM2_DKEY: AL = the character, AH = the scan
shm_dbkey:
    push ax
    push cx
    push si
    push di
    cmp al, 13                        ; Enter: the default button
    jne .notent
    mov cl, [cs:shm_dbdef]
    cmp cl, 0xFF
    je .out
    xor ch, ch
    call shm_dbpress
    jmp short .out
.notent:
    cmp al, 27                        ; Esc: Cancel
    jne .notesc
    mov byte [cs:shm_dbans], 0
    mov byte [sh_dbx_done], 1
    jmp short .out
.notesc:
    cmp al, 9                         ; Tab: the next edit box
    jne .notab
    call shm_dbnextedit
    jmp short .out
.notab:
    mov cl, [cs:shm_dbfoc]            ; everything else is the edit box's
    cmp cl, 0xFF
    je .out
    xor ch, ch
    push ax
    mov ax, cx
    call shm_dbitem
    pop ax
    call shm_dbload                   ; SI = the block
    SHOUT os88line_key
    jc .out
    call shm_dbsave
    SHOUT os88line_draw
.out:
    pop di
    pop si
    pop cx
    pop ax
    ret

; verb SHM2_DCLICK: CX,DX = the click, on the glass
shm_dbclick:
    push ax
    push bx
    push cx
    push si
    push di
    mov ax, cx
    xor cx, cx
.l:
    cmp cl, [cs:shm_dbn]
    jae .out
    push ax
    mov ax, cx
    call shm_dbitem
    pop ax
    call shm_dbrect
    cmp ax, [sh_tbuf]
    jl .n
    cmp ax, [sh_tbuf+4]
    jg .n
    cmp dx, [sh_tbuf+2]
    jl .n
    cmp dx, [sh_tbuf+6]
    jg .n
    mov bl, [cs:di]                   ; inside item CX
    cmp bl, 4
    ja .notbtn
    call shm_dbgrab                   ; a button fires on the RELEASE now
    jmp short .out                    ; (81.111, sh_dbx_ev arms it)
.notbtn:
    cmp bl, 13
    jne .notchk
    xor byte [cs:di+1], 1
    call shm_dbdraw
    jmp short .out
.notchk:
    cmp bl, 12
    jne .notopt
    push ax
    call shm_dbgroup                  ; AL its place, DI its group
    jc .nogrp
    mov [cs:di+1], al
    call shm_dbredio                  ; every option button, again
.nogrp:
    pop ax
    jmp short .out
.notopt:
    cmp bl, 6
    jb .n
    cmp bl, 10
    ja .n
    call shm_dbfocus                  ; an edit box: the keys, and the caret
    push cx                           ; where it was clicked
    push ax
    mov ax, cx
    call shm_dbitem
    call shm_dbload
    pop cx                            ; the click's x
    SHOUT os88line_click
    call shm_dbsave
    SHOUT os88line_draw
    pop cx
    jmp short .out
.n:
    inc cx
    jmp .l
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; shm_dbgrab - stage the gesture record at button item CX (DI = its record,
; its rect in sh_tbuf) and ask the resident thunk to arm it
shm_dbgrab:
    push ax
    push si
    push di
    mov si, sh_tbuf
    mov di, sh_dbx_btrects
    mov ax, [si]
    mov [di], ax
    mov ax, [si+2]
    mov [di+2], ax
    mov ax, [si+4]
    mov [di+4], ax
    mov ax, [si+6]
    mov [di+6], ax
    pop di
    push di
    call shm_dblabel                  ; SI = its label, in DS
    mov di, sh_dbx_gtxt
.c:
    mov al, [si]
    inc si
    mov [di], al
    inc di
    or al, al
    jnz .c
    xor ax, ax
    cmp cl, [cs:shm_dbdef]
    jne .nd
    mov al, OS88UI_DEF
.nd:
    mov [sh_dbx_gflg], ax
    mov [sh_dbx_gitem], cl
    mov byte [sh_dbx_grab], 1
    pop di
    pop si
    pop ax
    ret

; verb SHM2_DFIRE - the gesture record's button was released on (81.111)
shm_dbfire:
    push cx
    mov cl, [sh_dbx_gitem]
    cmp cl, 0xFF
    je .out
    xor ch, ch
    call shm_dbpress
.out:
    pop cx
    ret

; shm_dbredio - every option button drawn again (one moved)
shm_dbredio:
    push ax
    push cx
    push di
    xor cx, cx
.l:
    cmp cl, [cs:shm_dbn]
    jae .out
    mov ax, cx
    call shm_dbitem
    cmp byte [cs:di], 12
    jne .n
    call shm_dbdraw
.n:
    inc cx
    jmp short .l
.out:
    pop di
    pop cx
    pop ax
    ret

; shm_mstore - the answer just evaluated into the cell at AX,BX, as what it is
; - a label, a logical, an error or a number. CF=1 when the cell refused it
shm_mstore:
    push dx
    push si
    push di
    mov dl, [sh_evalerr]
    or dl, dl
    jz .noerr
    mov byte [sh_evalerr], 0          ; the ERROR is the value stored, not
    SHOUT sh_seterr                   ; the macro's own failure
    jmp short .out
.noerr:
    cmp byte [sh_curtype], SH_T_TEXT
    jne .nottext
    mov si, sh_sacc                   ; the text, out of the string register
    mov di, sh_rwsrc                  ; before anything can reuse it
    push ax
.c:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .c
    pop ax
    mov si, sh_rwsrc
    SHOUT sh_settext
    jmp short .out
.nottext:
    cmp byte [sh_curtype], SH_T_BOOL
    jne .num
    xor dl, dl
    test word [sh_acc+6], 0x7FFF
    jz .b
    inc dl
.b:
    SHOUT sh_setbool
    jmp short .out
.num:
    SHOUT sh_setvald
.out:
    pop di
    pop si
    pop dx
    ret

; shm_mtruth - the answer just evaluated, as a condition: CF=1 true. An error
; is false, and so is text, which Excel refuses as a test
shm_mtruth:
    cmp byte [sh_evalerr], 0
    jne .f
    cmp byte [sh_curtype], SH_T_TEXT
    je .f
    test word [sh_acc+6], 0x7FFF      ; zero is +0.0 or -0.0, nothing else
    jnz .t
    cmp word [sh_acc+4], 0
    jnz .t
    cmp word [sh_acc+2], 0
    jnz .t
    cmp word [sh_acc], 0
    jnz .t
.f:
    mov byte [sh_evalerr], 0
    clc
    ret
.t:
    stc
    ret

; shm_mtext - the answer just evaluated, as text, into DI (CX bytes at most)
shm_mtext:
    push ax
    push si
    push di
    SHOUT sh_str_want
    mov si, sh_sacc
.c:
    jcxz .e
    mov al, [si]
    or al, al
    jz .e
    mov [di], al
    inc si
    inc di
    dec cx
    jmp short .c
.e:
    mov byte [di], 0
    pop di
    pop si
    pop ax
    ret

; --- control ---------------------------------------------------------------
shm_mgoto:
    call shm_mref
    jc .ok
    jmp shm_merr
.ok:
    mov [sh_macro_ncol], ax
    mov [sh_macro_nrow], bx
    mov byte [sh_macro_ctl], SH_MC_GOTO
    SHOUT sh_skipargs
    jmp shm_mtrue

; RETURN([value]) - macro plan wave 1. Inside a SUBROUTINE it goes back to the
; caller with the value, which the caller's cell reads by being evaluated a
; second time (shm_mcall's answer pass, INPUT's mechanism). With no caller it
; ends the run, as it always did. HALT always ends it, every frame included.
shm_mreturn:
    cmp byte [cs:shm_csp], 0
    je shm_mhalt
    cmp byte [si], ')'
    je .noval
    SHOUT sh_pcmp
    call shm_rtype                    ; RESULT's type, or #VALUE!
    jmp short .bank
.noval:                               ; RETURN() answers TRUE, as a macro
    mov ax, 1                         ; command that did its job does
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_BOOL
.bank:
    mov di, shm_ans
    mov bx, shm_anstxt
    call shm_vput
    mov byte [sh_evalerr], 0
    SHOUT sh_skipargs
    mov byte [sh_macro_ctl], SH_MC_RET
    jmp shm_mtrue
shm_mhalt:
    SHOUT sh_skipargs
    mov byte [sh_macro_ctl], SH_MC_STOP
    jmp shm_mtrue

; FOR(counter, start, end[, step]) - the counter is a CELL (see the header).
; Everything is parsed into bss FIRST and the frame written last: the
; evaluator keeps nothing in a register across a call, DI included
shm_mfor:
    call shm_mpopself                 ; GOTO back onto a FOR restarts it
    cmp byte [sh_macro_lsp], SH_MLOOPS
    jae .bad                          ; nested deeper than the frames: stop
    call shm_mref
    jnc .bad
    mov [sh_macro_tcol], ax
    mov [sh_macro_trow], bx
    cmp byte [si], ','
    jne .bad
    inc si
    SHOUT sh_pcmp                     ; the start, into the counter
    mov ax, [sh_macro_tcol]
    mov bx, [sh_macro_trow]
    call shm_mstore
    cmp byte [si], ','
    jne .bad
    inc si
    SHOUT sh_pcmp                     ; the end
    push si
    mov si, sh_acc
    mov bx, sh_macro_tend
    SHOUT sh_trcopy
    mov ax, 1                         ; the step: 1 unless given
    SHOUT sh_acc_int
    pop si
    cmp byte [si], ','
    jne .step
    inc si
    SHOUT sh_pcmp
.step:
    push si
    mov si, sh_acc
    mov bx, sh_macro_tstep
    SHOUT sh_trcopy
    call shm_mframe                   ; DI = the frame, only now
    mov byte [di + SH_LF_KIND], 1
    mov ax, [sh_macro_tcol]
    mov [di + SH_LF_CCOL], ax
    mov ax, [sh_macro_trow]
    mov [di + SH_LF_CROW], ax
    mov si, sh_macro_tend
    lea bx, [di + SH_LF_END]
    SHOUT sh_trcopy
    mov si, sh_macro_tstep
    lea bx, [di + SH_LF_STEP]
    SHOUT sh_trcopy
    pop si
    SHOUT sh_skipargs
    inc byte [sh_macro_lsp]           ; pushed
    call shm_mtop
    call shm_mover                    ; already past the end: not even once
    jnc .in
    dec byte [sh_macro_lsp]
    call shm_mskipfrom
.in:
    jmp shm_mtrue
.bad:
    jmp shm_merr

; WHILE(test) - NEXT comes back to this cell, which tests again
shm_mwhile:
    SHOUT sh_pcmp
    call shm_mtruth
    pushf
    SHOUT sh_skipargs
    call shm_mtopself                 ; ZF: the top frame is this WHILE's
    je .have
    cmp byte [sh_macro_lsp], SH_MLOOPS
    jb .push
    popf
    jmp shm_merr                      ; nested deeper than the frames
.push:
    call shm_mframe
    mov byte [di + SH_LF_KIND], 2
    inc byte [sh_macro_lsp]
.have:
    popf
    jc .in
    dec byte [sh_macro_lsp]           ; false: out, past its NEXT
    call shm_mskipfrom
.in:
    jmp shm_mtrue

; NEXT() - the counter steps, or the WHILE tests again
shm_mnext:
    SHOUT sh_skipargs
    cmp byte [sh_macro_lsp], 0
    je .out                           ; no loop open: nothing to do
    call shm_mtop                     ; DI = the top frame
    cmp byte [di + SH_LF_KIND], 2
    je .while
    mov ax, [di + SH_LF_CCOL]         ; the counter, as the loop body left it,
    mov bx, [di + SH_LF_CROW]         ; plus the step
    SHOUT sh_getcell2
    SHOUT sh_acc_load_a
    call shm_mtop                     ; DI again: nothing keeps it across a call
    push si
    lea si, [di + SH_LF_STEP]
    SHOUT fp_unpack_b
    pop si
    SHOUT fp_add
    SHOUT sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    mov byte [sh_evalerr], 0
    call shm_mtop
    mov ax, [di + SH_LF_CCOL]
    mov bx, [di + SH_LF_CROW]
    call shm_mstore
    call shm_mtop
    call shm_mover
    jc .done                          ; past the end: out, below the NEXT
    mov ax, [di + SH_LF_COL]          ; round again, from the cell after FOR
    mov bx, [di + SH_LF_ROW]
    inc bx
    jmp short .go
.while:
    mov ax, [di + SH_LF_COL]
    mov bx, [di + SH_LF_ROW]
.go:
    mov [sh_macro_ncol], ax
    mov [sh_macro_nrow], bx
    mov byte [sh_macro_ctl], SH_MC_GOTO
    jmp short .out
.done:
    dec byte [sh_macro_lsp]
.out:
    jmp shm_mtrue

; BREAK() - out of the innermost loop, past its NEXT
shm_mbreak:
    SHOUT sh_skipargs
    cmp byte [sh_macro_lsp], 0
    je .out
    call shm_mtop
    mov ax, [di + SH_LF_COL]
    mov [sh_macro_ncol], ax
    mov ax, [di + SH_LF_ROW]
    mov [sh_macro_nrow], ax
    dec byte [sh_macro_lsp]
    mov byte [sh_macro_ctl], SH_MC_SKIP
.out:
    jmp shm_mtrue

; the loop stack - SH_MLOOPS frames of SH_LF_SZ in sh_macro_loops
shm_mtop:                             ; DI = the top frame
    push ax
    mov al, [sh_macro_lsp]
    dec al
    call shm_mfr0
    pop ax
    ret
shm_mframe:                           ; DI = the frame above the top, filled
    push ax                           ; with this cell as its home
    mov al, [sh_macro_lsp]
    call shm_mfr0
    mov ax, [sh_macro_col]
    mov [di + SH_LF_COL], ax
    mov ax, [sh_macro_row]
    mov [di + SH_LF_ROW], ax
    pop ax
    ret
shm_mfr0:                             ; AL = a frame index -> DI
    mov ah, SH_LF_SZ
    mul ah
    add ax, sh_macro_loops
    mov di, ax
    ret

; shm_mtopself - ZF=1 when there is a top frame and it belongs to THIS cell
shm_mtopself:
    push ax
    push di
    cmp byte [sh_macro_lsp], 0
    je .no
    call shm_mtop
    mov ax, [di + SH_LF_COL]
    cmp ax, [sh_macro_col]
    jne .out
    mov ax, [di + SH_LF_ROW]
    cmp ax, [sh_macro_row]
    jmp short .out
.no:
    or sp, sp                         ; ZF=0: SP is never zero
.out:
    pop di
    pop ax
    ret

; shm_mpopself - a GOTO back onto an open FOR: drop its frame, and restart
shm_mpopself:
    call shm_mtopself
    jne .out
    dec byte [sh_macro_lsp]
.out:
    ret

; shm_mover - CF=1 when the FOR at DI has run past its end: the counter's
; cell against the end, the comparison turned round for a negative step
shm_mover:
    push ax
    push bx
    push si
    mov ax, [di + SH_LF_CCOL]
    mov bx, [di + SH_LF_CROW]
    push di
    SHOUT sh_getcell2
    SHOUT sh_acc_load_a
    pop di
    lea si, [di + SH_LF_END]
    SHOUT fp_unpack_b
    SHOUT fp_cmpab                    ; AX = -1/0/1, counter against end
    test byte [di + SH_LF_STEP + 7], 0x80
    jz .up
    neg ax
.up:
    cmp ax, 1                         ; past it when counter > end (or < for
    je .over                          ; a step down)
    clc
    jmp short .out
.over:
    stc
.out:
    pop si
    pop bx
    pop ax
    ret

; shm_mskipfrom - out of the loop whose home cell is this one: on past its
; matching NEXT (shm_mnext's GOTO target is set the same way, by the engine)
shm_mskipfrom:
    push ax
    mov ax, [sh_macro_col]
    mov [sh_macro_ncol], ax
    mov ax, [sh_macro_row]
    mov [sh_macro_nrow], ax
    mov byte [sh_macro_ctl], SH_MC_SKIP
    pop ax
    ret

; --- the sheet -----------------------------------------------------------------
shm_mselect:
    call shm_mrangeref                ; AX/BX near, CX/DX far - a RANGE, not
    jc .ok                            ; shm_mref's single cell: SELECT is the
    jmp shm_merr                      ; one macro command that can select more
.ok:                                  ; than the active cell
    mov [sh_selcol], ax               ; the selection moves now; the grid is
    mov [sh_selcol2], cx              ; repainted once the step is over, never
    mov [sh_selrow], bx               ; from inside the evaluation of it. A
    mov [sh_selrow2], dx              ; ref with no far corner sets col2/row2
                                       ; to the same cell (shm_mrangeref's own
                                       ; contract), so FORMULA's own default -
                                       ; the active cell, sh_selcol/row - is
                                       ; always the range's TOP-LEFT
    SHOUT sh_scrollto
    mov byte [sh_macro_dirty], 1
    SHOUT sh_skipargs
    jmp shm_mtrue

shm_msetval:
    call shm_mref
    jnc .bad
    mov [sh_macro_tcol], ax
    mov [sh_macro_trow], bx
    cmp byte [si], ','
    jne .bad
    inc si
    SHOUT sh_pcmp
    mov ax, [sh_macro_tcol]
    mov bx, [sh_macro_trow]
    call shm_mstore
    SHOUT sh_skipargs
    jmp shm_mtrue
.bad:
    jmp shm_merr

; FORMULA(x[, ref]) - x into the active cell (or ref) AS IF TYPED: "=A1*2" is
; a formula, "12" a number, "#N/A" the error, "TRUE" the logical. The value is
; banked - its tag, its error, its eight bytes and its text - before the
; reference is parsed, which can evaluate and so overwrite all four
shm_mformula:
    SHOUT sh_pcmp
    mov al, [sh_curtype]
    mov [sh_macro_ftype], al
    mov al, [sh_evalerr]
    mov [sh_macro_ferr], al
    mov byte [sh_evalerr], 0
    push si
    mov si, sh_acc
    mov bx, sh_macro_tend
    SHOUT sh_trcopy
    cmp byte [sh_macro_ftype], SH_T_TEXT
    jne .nt
    mov si, sh_sacc                   ; typed text goes through the edit
    mov di, sh_editbuf                ; buffer, as a keystroke's would
    xor cx, cx
.c:
    mov al, [si]
    mov [di], al
    or al, al
    jz .cd
    inc si
    inc di
    inc cx
    cmp cx, SH_EDITMAX
    jb .c
    mov byte [di], 0
.cd:
    mov [sh_editlen], cl
.nt:
    pop si
    mov ax, [sh_selcol]
    mov bx, [sh_selrow]
    cmp byte [si], ','
    jne .have
    inc si
    call shm_mref
    jc .have
    jmp shm_merr
.have:
    mov [sh_macro_tcol], ax
    mov [sh_macro_trow], bx
    push si
    mov si, sh_macro_tend
    mov bx, sh_acc
    SHOUT sh_trcopy
    pop si
    mov al, [sh_macro_ftype]
    mov [sh_curtype], al
    mov al, [sh_macro_ferr]
    mov [sh_evalerr], al
    mov ax, [sh_macro_tcol]
    mov bx, [sh_macro_trow]
    cmp byte [sh_curtype], SH_T_TEXT
    je .typed
    call shm_mstore
    jmp short .done
.typed:
    cmp byte [sh_editbuf], '='        ; only a real formula can carry an R1C1
    jne .rcskip                       ; reference - a bare label goes through
                                       ; unconverted, so a label that happens
                                       ; to read "R5C3" stays exactly that
    mov [sh_rc_ccol], ax              ; the R1C1 origin is the cell the text
    mov [sh_rc_crow], bx              ; is being entered INTO (the recorder's
    push ax                           ; own convention), not the cell running
    push bx                           ; the macro - ax/bx are both already it
    mov si, sh_editbuf
    inc si                            ; sh_formula_from_r1c1 wants no leading
    CHOUT SHM_FROMR1C1         ; '=' - SYLK's ;E field has none either,
    mov byte [sh_editbuf], '='        ; and A1 text passes through unchanged
    mov si, sh_rwdst                  ; (81.7.1's own header), so this is safe
    mov di, sh_editbuf + 1            ; to run over EVERY typed formula, R1C1
    xor cx, cx                        ; or not
.rccopy:
    mov al, [si]
    or al, al
    jz .rcdone
    mov [di], al
    inc si
    inc di
    inc cx
    cmp cx, SH_EDITMAX - 1            ; sh_rw_emit already capped sh_rwdst at
    jae .rcdone                       ; SH_EDITMAX, but the leading '=' this
    jmp .rccopy                       ; loop restores needs its own byte back
.rcdone:
    mov byte [di], 0
    inc cx                            ; the leading '=' itself
    mov [sh_editlen], cl
    pop bx
    pop ax
.rcskip:
    push word [sh_selcol]             ; sh_commit enters the edit buffer into
    push word [sh_selrow]             ; the SELECTED cell, so the target is
    mov [sh_selcol], ax               ; selected for it and put back
    mov [sh_selrow], bx
    mov byte [sh_editing], 1
    SHOUT sh_commit
    mov byte [sh_editing], 0
    pop word [sh_selrow]
    pop word [sh_selcol]
.done:
    SHOUT sh_skipargs
    jmp shm_mtrue

; --- the user --------------------------------------------------------------
shm_malert:
    cmp byte [cs:shm_alpend], 0       ; 81.86: type 1's second evaluation
    jne .answer                       ; answers which button it was
    SHOUT sh_pcmp
    push di
    push cx
    mov di, sh_macro_msg
    mov cx, OS88UI_AMAX
    call shm_mtext
    pop cx
    pop di
    mov byte [sh_macro_aset], OS88UI_AOK
    mov byte [sh_macro_ctl], SH_MC_PAUSEN
    cmp byte [si], ','                ; type_num: 1 is OK and Cancel, and
    jne .show                         ; answers which; 2 and 3 are the note
    inc si                            ; and the warning, which have only OK
    SHOUT sh_pcmp                     ; here - one message box, one look
    SHOUT sh_acc_toint
    jc .show
    cmp ax, 1
    jne .show
    mov byte [sh_macro_aset], OS88UI_AOKCAN
    mov byte [sh_macro_ctl], SH_MC_PAUSEH ; the SAME cell, again, afterwards:
    mov byte [cs:shm_alpend], 1       ; INPUT's mechanism for INPUT's reason
.show:
    SHOUT sh_skipargs
    mov byte [sh_macro_wait], SH_MW_ALERT
    jmp shm_mtrue
.answer:
    mov byte [cs:shm_alpend], 0
    SHOUT sh_skipargs
    cmp byte [sh_macro_btn], 0        ; OK; Cancel and a dismissed box are
    jne .false                        ; both FALSE
    jmp shm_mtrue
.false:
    jmp shm_mfalse

; INPUT(prompt) - the second evaluation of this cell answers what was typed
shm_minput:
    mov al, [sh_macro_ansok]
    or al, al
    jz .ask
    mov byte [sh_macro_ansok], 0
    push ax                           ; sh_skipargs walks the text in AL
    SHOUT sh_skipargs
    pop ax
    cmp al, 1
    jne .cancel
    push si
    mov si, sh_macro_ans              ; a number if all of it is one
    SHOUT fp_atof
    jc .text
    cmp byte [si], 0
    jne .text
    pop si
    SHOUT sh_acc_store
    mov byte [sh_curtype], SH_T_NUM
    ret
.text:
    mov si, sh_macro_ans
    push di
    mov di, sh_sacc
.tc:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .tc
    pop di
    pop si
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_TEXT
    ret
.cancel:
    jmp shm_mfalse                    ; Cancel answers FALSE, as Excel's does
.ask:
    SHOUT sh_pcmp
    push di
    push cx
    mov di, sh_macro_msg
    mov cx, SH_MPROMPT
    call shm_mtext
    pop cx
    pop di
    SHOUT sh_skipargs
    mov byte [sh_macro_ctl], SH_MC_PAUSEH
    mov byte [sh_macro_wait], SH_MW_INPUT
    jmp shm_mfalse

shm_mmessage:
    SHOUT sh_pcmp
    call shm_mtruth
    mov word [sh_msg], 0
    jnc .off
    cmp byte [si], ','
    jne .off
    inc si
    SHOUT sh_pcmp
    push di
    push cx
    mov di, sh_macro_stmsg
    mov cx, SH_MSTMSG
    call shm_mtext
    pop cx
    pop di
    mov word [sh_msg], sh_macro_stmsg
.off:
    SHOUT sh_skipargs
    SHOUT sh_drawstatus
    jmp shm_mtrue

shm_mbeep:
    SHOUT sh_skipargs
    SHOUT sh_macro_beep
    jmp shm_mtrue

; ACTIVE.CELL() - the selected cell's value (Excel converts the reference to
; its contents wherever a value is wanted, which is everywhere here)
shm_mactcell:
    mov ax, [sh_selcol]               ; ...and, since wave 1b, a REFERENCE:
    mov bx, [sh_selrow]               ; SET.VALUE(ACTIVE.CELL(), 5) is the
    mov cx, ax                        ; active cell, as it is in Excel
    mov dx, bx
    jmp shm_refret

; --- the commands: the menu's own routines, on the selection ---------------
shm_mcopy:
    mov ax, sh_docmd_copy
    jmp short shm_mcmd
shm_mcut:
    mov ax, sh_docmd_cut
    jmp short shm_mcmd
shm_mpaste:
    mov ax, sh_docmd_paste
shm_mcmd:
    push ax
    SHOUT sh_skipargs
    pop ax
    push si
    mov si, [sh_ownwin]
    SHOUT sh_macro_cmd                ; AX = which, SI = the window
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; CLEAR([n]) - Excel's numbering (Functions and Macros, CLEAR): 1 all, 2
; formats, 3 or none the formulas - the contents - and 4 the notes, onto Edit >
; Clear's rows, which run All, Formulas, Formats. It has no notes row, so 4
; clears nothing and answers FALSE
shm_mclear:
    mov ax, 3
    cmp byte [si], ')'
    je .have
    SHOUT sh_pcmp
    SHOUT sh_acc_toint
    jnc .have
    mov ax, 3
.have:
    push ax                           ; sh_skipargs walks the text in AL
    SHOUT sh_skipargs
    pop ax
    cmp ax, 1
    je .all
    cmp ax, 2
    je .fmt
    cmp ax, 3
    jne .none
    mov ax, 1                         ; the formulas' row
    jmp short .go
.all:
    xor ax, ax
    jmp short .go
.fmt:
    mov ax, 2
.go:
    push si
    mov si, [sh_ownwin]
    SHOUT sh_macro_clear              ; AX = the row, SI = the window
    pop si
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue
.none:
    jmp shm_mfalse

shm_mcalc:
    SHOUT sh_skipargs
    SHOUT sh_recalc_all
    mov byte [sh_macro_dirty], 1
    jmp shm_mtrue

; =============================================================================
; shm_mresume - verb SHM_MRESUME: start a run ([sh_macro_wait] SH_MW_START,
; at [sh_macro_col]/[sh_macro_row]) or carry one on after its ALERT or INPUT
; =============================================================================
shm_mresume:
    push ax
    mov al, [sh_macro_wait]
    mov byte [sh_macro_wait], 0
    cmp al, SH_MW_START
    jne .notstart
.start:
    mov byte [sh_macro_running], 1
    mov word [sh_macro_steps], 0
    mov byte [sh_macro_lsp], 0
    mov byte [sh_macro_ansok], 0
    mov byte [cs:shm_csp], 0          ; macro plan wave 1: no frames, and
    mov byte [cs:shm_cans], 0         ; nothing left over from a run a HALT
    mov byte [cs:shm_sused], 0        ; or an error ended mid-call - this
    mov byte [cs:shm_bused], 0        ; state is the module's and outlives
    mov word [cs:shm_pused], 0        ; the run that wrote it
    mov byte [cs:shm_echo], 1         ; 81.86: every one of these lasts only
    mov byte [cs:shm_errmode], 1      ; as long as the run that set it -
    mov byte [cs:shm_ckmode], 1       ; Excel's own rule for ECHO and
    mov byte [cs:shm_stepon], 0       ; CANCEL.KEY, and the only safe one
    mov byte [cs:shm_stepgo], 0       ; for the rest
    mov byte [cs:shm_wtpend], 0
    mov byte [cs:shm_alpend], 0
    mov byte [cs:shm_dbpend], 0       ; 81.96: a halted run's DIALOG.BOX
    mov byte [cs:shm_dbopen], 0
    mov byte [cs:shm_escwas], 1       ; an Esc already down is not a press
    mov byte [sh_macro_esc], 0
    mov word [sh_msg], 0
    jmp short .go
.notstart:
    cmp al, SH_MW_ONTIME              ; 81.92: ON.TIME's look at the clock
    jne .notontime
    call shm_ontime
    jc .start                         ; due: a run, as Macro > Run starts one
    jmp .out
.notontime:
    cmp al, SH_MW_STEP                ; 81.86: the Single Step dialog
    jne .notstep
    mov al, [sh_macro_btn]
    mov byte [cs:shm_stepgo], 1       ; Step - and a dismissed dialog, which
    cmp al, 1                         ; is only a way to keep stepping
    jne .notstep_halt
    mov byte [cs:shm_stepgo], 2       ; Halt
.notstep_halt:
    cmp al, 2
    jne .go
    mov byte [cs:shm_stepon], 0       ; Continue: run on without stepping
    jmp short .go
.notstep:
    cmp al, SH_MW_INPUT
    jne .go
    cmp byte [sh_macro_ansok], 0      ; closed without OK: Cancel
    jne .go
    mov byte [sh_macro_ansok], 2
.go:
    cmp byte [sh_macro_running], 0
    je .out
    call shm_mstep
.out:
    pop ax
    ret

; shm_mstep - run cells until the macro ends or pauses
shm_mstep:
    push ax
    push bx
    push cx
    push si
    push di
    push es
.next:
    call shm_mesc                     ; 81.86: Esc, per CANCEL.KEY
    cmp byte [cs:shm_stepgo], 2       ; the Single Step dialog said Halt
    je .halted
    mov ax, [sh_macro_steps]
    cmp ax, SH_MACRO_MAXSTEPS
    jae .limit
    inc ax
    mov [sh_macro_steps], ax
    mov ax, [sh_macro_col]
    mov bx, [sh_macro_row]
    SHOUT sh_findcell
    jnc .stop                         ; an empty cell: the end
    mov es, [sh_cellseg]
    test byte [es:di+4], 1            ; a constant is a step that does nothing
    jz .advance
    mov si, [es:di+SH_C_FOFF]         ; the formula, out of the arena
    mov es, [sh_txtseg]
    mov di, sh_macrobuf
.cp:
    mov al, [es:si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .cp
    cmp byte [cs:shm_stepon], 0       ; 81.86: single-stepping - show this
    je .exec                          ; cell before it runs, and run it when
    cmp byte [cs:shm_stepgo], 0       ; the dialog says Step or Continue
    jne .exec
    dec word [sh_macro_steps]         ; ...it has not run yet
    call shm_stepmsg
    mov byte [sh_macro_aset], OS88UI_ASTEP
    mov byte [sh_macro_wait], SH_MW_STEP
    call shm_mpaint
    SHOUT sh_macro_alertup
    jc .noask                         ; no alert to wait on: the run stops
    jmp .out
.exec:
    mov byte [cs:shm_stepgo], 0
    mov byte [sh_macro_ctl], SH_MC_NONE
    mov byte [sh_ud_busy], 1          ; no Undo snapshot per entry: a macro is
    mov byte [sh_evalerr], 0          ; not undone, and a loop would copy the
    mov ax, [sh_evaldepth]            ; document every time round
    mov [sh_macro_exdep], ax
    mov byte [sh_macro_exec], 1
    mov byte [cs:shm_ccount], 0       ; one subroutine call to a cell
    mov byte [cs:shm_cpend], 0
    mov si, sh_macrobuf
    SHOUT sh_pcmp
    mov byte [sh_macro_exec], 0
    cmp byte [sh_macro_dirty], 0      ; a SELECT or a command: show it now
    je .ctl
    cmp byte [cs:shm_echo], 0         ; ...unless ECHO(FALSE): the end of the
    je .ctl                           ; run paints, whatever ECHO said
    call shm_mpaint
.ctl:
    mov al, [sh_macro_ctl]
    cmp al, SH_MC_STOP                ; an error or HALT ends it, call or none
    je .end
    cmp byte [cs:shm_cpend], 0        ; A PENDING CALL OUTRANKS every other
    jne .call                         ; control in the step: the calling cell
                                       ; is evaluated again after RETURN, and
                                       ; RETURN, GOTO or a loop's own control
                                       ; happens THEN, with the call answered
    cmp al, SH_MC_NONE
    je .advance
    cmp al, SH_MC_GOTO
    je .goto
    cmp al, SH_MC_STOP
    je .end
    cmp al, SH_MC_SKIP
    je .skip
    cmp al, SH_MC_RET
    je .ret
    cmp al, SH_MC_WAITT               ; 81.86: WAIT - the timer is armed
    je .waitt
    cmp al, SH_MC_PAUSEH              ; INPUT: this cell again, afterwards
    je .pause
    inc word [sh_macro_row]           ; ALERT: the next one
.pause:
    call shm_mpaint
    cmp byte [sh_macro_wait], SH_MW_ALERT
    jne .notalert
    SHOUT sh_macro_alertup
    jc .noask
    jmp .out
.notalert:
    cmp byte [sh_macro_wait], SH_MW_DBOX ; 81.96: DIALOG.BOX's own window
    jne .ask
    cmp byte [cs:shm_dbopen], 0
    je .out
    mov byte [cs:shm_dbopen], 0
    push cx
    push dx
    mov cx, [cs:shm_dbw]
    mov dx, [cs:shm_dbh]
    SHOUT sh_dbx_open
    pop dx
    pop cx
    jnc .out
    mov byte [cs:shm_dbpend], 0       ; no window to make: the run stops
    mov byte [sh_macro_wait], 0       ; ...owing nothing to a later tick
    mov word [sh_msg], sh_s_macroerr
    jmp .fin
.ask:
    mov byte [sh_macro_ansok], 0
    SHOUT sh_macro_inputup
    jnc .out
.noask:                               ; ALERT, Step or INPUT could not put its
    mov byte [sh_macro_wait], 0       ; window up (another alert or dialog,
    mov word [sh_msg], sh_s_macroerr  ; or a full table), so no answer will
    jmp .fin                          ; come: DIALOG.BOX's rule, the run stops
.goto:
    mov ax, [sh_macro_ncol]
    mov [sh_macro_col], ax
    mov ax, [sh_macro_nrow]
    mov [sh_macro_row], ax
    jmp .next
.call:                                ; macro plan wave 1: a subroutine
    mov byte [cs:shm_cpend], 0
    call shm_cpush
    jc .deep
    mov ax, [cs:shm_ctcol]
    mov [sh_macro_col], ax
    mov ax, [cs:shm_ctrow]
    mov [sh_macro_row], ax
    jmp .next
.ret:                                 ; ...and back: the CALLING cell again,
    call shm_cpop                     ; whose call site now answers RETURN's
    mov byte [cs:shm_cans], 1         ; value (shm_mcall)
    jmp .next
.deep:
    mov word [sh_msg], sh_s_mdeep
    jmp .fin
.waitt:
    mov byte [sh_macro_wait], SH_MW_WAIT
    cmp byte [sh_macro_dirty], 0
    je .out
    cmp byte [cs:shm_echo], 0
    je .out
    call shm_mpaint
    jmp .out
.halted:
    mov byte [cs:shm_stepgo], 0
    mov word [sh_msg], sh_s_macrodone
    jmp .fin
.skip:
    call shm_mskip
    jc .unmatched
    jmp .next
.advance:
    mov ax, [sh_macro_row]
    inc ax
    cmp ax, SH_ROWS
    jae .stop
    mov [sh_macro_row], ax
    jmp .next
.unmatched:
    mov word [sh_msg], sh_s_macronext
    jmp short .fin
.limit:
    mov word [sh_msg], sh_s_macrolimit
    jmp short .fin
.stop:
    mov word [sh_msg], sh_s_macrodone
    jmp short .fin
.end:
    cmp word [sh_msg], 0              ; RETURN/HALT: "done" - unless the
    jne .fin                          ; macro left a message, or failed
    mov word [sh_msg], sh_s_macrodone
.fin:
    mov byte [sh_macro_running], 0
    cmp byte [sh_macro_ontp], 0       ; 81.92: WAIT's timer took ON.TIME's
    je .fin2                          ; place - give it back
    push ax
    mov ax, 18
    SHOUT sh_macro_arm
    pop ax
.fin2:
    mov byte [sh_ud_busy], 0
    SHOUT sh_undo_drop                ; Excel cannot undo a macro either
    call shm_mpaint
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

shm_mpaint:
    push si
    mov byte [sh_macro_dirty], 0
    mov si, [sh_ownwin]
    SHOUT sh_repaint
    pop si
    ret

; shm_mskip - on past the NEXT that closes the loop at [sh_macro_ncol]/
; [sh_macro_nrow]: down its column, FOR and WHILE opening a level and NEXT
; closing one. CF=1 when the column ends first
shm_mskip:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    xor cx, cx                        ; CX = the levels opened on the way
    mov bx, [sh_macro_nrow]
.l:
    inc bx
    cmp bx, SH_ROWS
    jae .none
    mov ax, [sh_macro_ncol]
    push cx
    SHOUT sh_findcell
    pop cx
    jnc .none
    mov es, [sh_cellseg]
    test byte [es:di+4], 1
    jz .l
    mov si, [es:di+SH_C_FOFF]
    mov es, [sh_txtseg]
    mov di, sh_f_for
    call shm_mword
    je .open
    mov di, sh_f_while
    call shm_mword
    je .open
    mov di, sh_f_next
    call shm_mword
    jne .l
    jcxz .found
    dec cx
    jmp short .l
.open:
    inc cx
    jmp short .l
.found:
    mov ax, [sh_macro_ncol]
    mov [sh_macro_col], ax
    inc bx
    mov [sh_macro_row], bx
    clc
    jmp short .out
.none:
    stc
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; shm_mword - ZF=1 when ES:SI, a formula, opens with the word at DS:DI then
; '(' - in any case
shm_mword:
    push ax
    push si
    push di
.l:
    mov al, [es:si]
    cmp al, 'a'
    jb .u
    cmp al, 'z'
    ja .u
    sub al, 32
.u:
    cmp byte [di], 0
    je .end
    cmp al, [di]
    jne .out
    inc si
    inc di
    jmp short .l
.end:
    cmp al, '('
.out:
    pop di
    pop si
    pop ax
    ret
shm_m2end:                            ; 81.94: MACRO.OVL's last byte + 1 - the
                                       ; text files' buffers are its claim's tail

section SH_MODSEC                      ; 81.65: DAVERAGE...DVARP, CHART.OVL
; =============================================================================
; THE DATABASE FUNCTIONS (81.65): DAVERAGE DCOUNT DCOUNTA DMAX DMIN DPRODUCT
; DSTDEV DSTDEVP DSUM DVAR DVARP, ids SH_FID_DATABASE and up. Every one takes
; exactly three arguments - DFUNC(database, field, criteria) - and differs
; from its neighbours only in WHICH of sh_foldvalue's existing accumulators it
; reuses (sh_db_foldkind): the accumulator math is not reimplemented here, the
; family's own job is entirely about which ROWS get folded.
;
; RE-ENTRANCY IS REFUSED, not guarded. sh_db_c1..sh_cr_r2 stay live across the
; whole row-by-row, column-by-column scan - unlike sh_r1col/sh_r2col, which a
; single sh_getcell2 call banks around itself (81.52), these would need
; banking around EVERY recursable call inside a scan that makes many. A
; database or criteria cell whose own formula calls another database function
; answers #VALUE! instead (sh_db_busy), the same shape sh_stbusy already
; refuses a nested variance fold with (81.34.1) - a database argument is a
; fixed reference, not a value a formula is likely to compute cell by cell,
; so the cost of refusing this is small next to a scan that has to be careful
; everywhere instead of careful once.
;
; sh_db_foldkind - one byte per id, offset from SH_FID_DATABASE: which
; existing sh_pfid this database function folds like. DAVERAGE folds like
; AVERAGE(1), DCOUNT like COUNT(4) (numbers only), DCOUNTA like COUNTA(11)
; (anything non-blank), DSTDEV/DSTDEVP/DVAR/DVARP like their plain namesakes
; (77-80) - sh_foldvalue and sh_funcfinish read [sh_pfid] and cannot tell a
; database function called them from an ordinary fold over a range.
; =============================================================================
sh_db_foldkind: db 1, 4, 11, 3, 2, 10, 79, 80, 0, 77, 78
                ; DAVERAGE DCOUNT DCOUNTA DMAX DMIN DPRODUCT DSTDEV DSTDEVP
                ; DSUM DVAR DVARP

; in: AX = the id, SI just past '('. out: AX = the value in sh_acc, SI past
; ')'. BX CX DX DI kept, matching every other door's contract (82.16.10).
shm_pdatabase:
    push bx
    push cx
    push dx
    push di
    mov di, ax                        ; DI = the id
    cmp byte [sh_db_busy], 0
    jne .refused
    mov byte [sh_db_busy], 1
    SHOUT sh_pargref                   ; --- argument 1: the database range --
    jc .havedb1
    call shm_mname                     ; ...or a DEFINED NAME - Set Database
    jnc .badargs                       ; (81.69) is the whole reason this
    mov [sh_db_c1], ax                 ; needs to work: sh_pargref alone has
    mov [sh_db_r1], bx                 ; no name fallback of its own (that
    mov [sh_db_c2], cx                 ; lives in shm_mref's own wrapper,
    mov [sh_db_r2], dx                 ; the macro family's, not here)
    jmp .db1ok
.havedb1:
    mov ax, [sh_arg1col]
    mov [sh_db_c1], ax
    mov ax, [sh_arg1row]
    mov [sh_db_r1], ax
    mov ax, [sh_arg2col]
    mov [sh_db_c2], ax
    mov ax, [sh_arg2row]
    mov [sh_db_r2], ax
.db1ok:
    cmp byte [si], ','
    jne .badargs
    inc si
    SHOUT sh_pcmp                      ; --- argument 2: the field ----------
    call sh_dbresolve
    jnc .badargs
    mov [sh_db_fcol], ax
    cmp byte [si], ','
    jne .badargs
    inc si
    SHOUT sh_pargref                   ; --- argument 3: the criteria range -
    jc .havecr1
    call shm_mname                     ; ...or a DEFINED NAME - Set Criteria
    jnc .badargs
    mov [sh_cr_c1], ax
    mov [sh_cr_r1], bx
    mov [sh_cr_c2], cx
    mov [sh_cr_r2], dx
    jmp .cr1ok
.havecr1:
    mov ax, [sh_arg1col]
    mov [sh_cr_c1], ax
    mov ax, [sh_arg1row]
    mov [sh_cr_r1], ax
    mov ax, [sh_arg2col]
    mov [sh_cr_c2], ax
    mov ax, [sh_arg2row]
    mov [sh_cr_r2], ax
.cr1ok:
    cmp byte [si], ')'
    jne .badargs
    inc si
    ; --- pick the fold-kind and reset the accumulator, exactly as sh_pfunc's
    ; own .fold branch does for SUM/AVERAGE/... (24436) ---
    mov bx, di
    sub bx, SH_FID_DATABASE
    mov al, [cs:bx+sh_db_foldkind]
    xor ah, ah
    cmp ax, 77
    jb .novar
    cmp byte [sh_stbusy], 0
    jne .statbusy
    mov byte [sh_stbusy], 1
    mov byte [sh_db_varguard], 1
    jmp .havekind
.statbusy:
    mov byte [sh_evalerr], SH_ERR_VALUE
    mov byte [sh_db_busy], 0
    xor ax, ax
    jmp .typedonly
.novar:
    mov byte [sh_db_varguard], 0
.havekind:
    mov [sh_pfid], ax
    mov word [sh_pcnt], 0
    mov word [sh_phave], 0
    cmp ax, 10                         ; DPRODUCT folds like PRODUCT, which
    jne .zeroacc                       ; sh_pfunc's own .fold seeds at 1 - a
    mov ax, 1                          ; running product seeded with 0 can
    SHOUT fp_i2a                       ; only ever be 0
    push di
    mov di, sh_pacc
    SHOUT fp_pack_a
    pop di
    jmp .haveacc
.zeroacc:
    mov word [sh_pacc], 0
    mov word [sh_pacc+2], 0
    mov word [sh_pacc+4], 0
    mov word [sh_pacc+6], 0
.haveacc:
    mov word [sh_pacc2], 0
    mov word [sh_pacc2+2], 0
    mov word [sh_pacc2+4], 0
    mov word [sh_pacc2+6], 0
    ; --- walk the database's DATA rows, below the header ---
    mov bx, [sh_db_r1]
    inc bx
.rowloop:
    cmp bx, [sh_db_r2]
    ja .rowsdone
    push bx
    call sh_dbrowmatch                 ; CF=1 if this row matches
    pop bx
    jnc .rownext
    push bx
    mov ax, [sh_db_fcol]
    SHOUT sh_getcell2
    jnc .rowempty                      ; no such cell: sh_foldrange skips
    SHOUT sh_foldvalue                 ; these too (81.52)
.rowempty:
    pop bx
.rownext:
    inc bx
    jmp .rowloop
.rowsdone:
    SHOUT sh_funcfinish
    mov dx, ax
    cmp byte [sh_db_varguard], 0
    je .clean
    mov byte [sh_stbusy], 0
.clean:
    mov byte [sh_db_busy], 0
    mov ax, dx
    jmp .typedonly
.badargs:
    SHOUT sh_skipargs
    mov byte [sh_evalerr], SH_ERR_VALUE
    mov byte [sh_db_busy], 0
    xor ax, ax
    jmp .typedonly
.refused:
    SHOUT sh_skipargs
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
.typedonly:
    mov byte [sh_curtype], SH_T_NUM
    pop di
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_dbresolve - in: sh_curtype/sh_acc/sh_sacc hold an evaluated FIELD SPEC (a
; database's column, by name or by 1-based number); sh_db_c1/r1/c2/r2 = the
; database rectangle. out: CF=1, AX = the absolute column it names; CF=0 if
; it names nothing - a bare number outside 1..width, or a text matching no
; header cell in the database's own top row.
;
; Sets no error itself and raises none: the CALLER decides what a miss means
; - a hard #VALUE! for the function's own field argument, or (from
; sh_dbrowok) a criteria column with nothing to say, which Excel treats as no
; constraint at all rather than a broken call (81.65.2).
; -----------------------------------------------------------------------------
sh_dbresolve:
    push bx
    push cx
    push dx
    push si
    push di
    cmp byte [sh_curtype], SH_T_TEXT
    je .byname
    SHOUT sh_acc_toint
    jc .fail
    or ax, ax
    jle .fail
    mov cx, [sh_db_c2]
    sub cx, [sh_db_c1]
    inc cx                             ; CX = the database's width
    cmp ax, cx
    jg .fail
    dec ax
    add ax, [sh_db_c1]
    stc
    jmp .out
.byname:
    SHOUT sh_spush
    jnc .scanstart
    clc                                ; the string bank is full: sh_spush
    jmp .out                          ; already raised #VALUE!
.scanstart:
    mov cx, [sh_db_c1]
.scan:
    cmp cx, [sh_db_c2]
    jg .notfound
    mov ax, cx
    mov bx, [sh_db_r1]
    push cx
    SHOUT sh_getcell2
    pop cx
    jnc .nextcol
    cmp byte [sh_curtype], SH_T_TEXT
    jne .nextcol
    xor ax, ax
    SHOUT sh_sslot                     ; SI = the banked field name
    mov di, sh_sacc                    ; DI = this header cell's text
    call sh_dblkstrcmp
    or ax, ax
    jne .nextcol
    SHOUT sh_spop
    mov ax, cx
    stc
    jmp .out
.nextcol:
    inc cx
    jmp .scan
.notfound:
    SHOUT sh_spop
.fail:
    clc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_dbrowmatch - in: BX = a database DATA row; sh_db_c1/r1/c2/r2 and
; sh_cr_c1/r1/c2/r2 already set (shm_pdatabase). out: CF=1 if this row
; matches the criteria range as a whole - ANY ONE criteria row's conditions
; ALL holding (Excel's OR-of-AND-rows shape, 81.65.2). A criteria range that
; is only its own header, with no condition row beneath it at all, matches
; every database row - DSUM(db,f,A1:A1) with A1 the header alone sums the
; whole column, which is Excel's own rule too.
; -----------------------------------------------------------------------------
sh_dbrowmatch:
    push bx
    push dx
    mov [sh_db_dbrow], bx
    mov bx, [sh_cr_r1]
    cmp bx, [sh_cr_r2]
    jae .found                         ; header only: matches unconditionally
.rowloop:
    inc bx
    cmp bx, [sh_cr_r2]
    ja .nomatch                        ; every OR-arm tried, none held
    mov [sh_db_critrow], bx
    call sh_dbrowok
    jc .found
    jmp .rowloop
.found:
    stc
    jmp .out
.nomatch:
    clc
.out:
    pop dx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_dbrowok - in: sh_db_dbrow/sh_db_critrow set (sh_dbrowmatch); the criteria
; and database rectangles as above. out: CF=1 if EVERY non-blank condition in
; THIS ONE criteria row holds (AND across its columns). A blank criteria
; header, or one naming no real database field, is skipped rather than
; refused - an unrelated extra column in the criteria range must not break
; every call (81.65.2).
; -----------------------------------------------------------------------------
sh_dbrowok:
    push ax
    push bx
    push cx
    mov ax, [sh_cr_c1]
    mov [sh_db_critcol], ax
.colloop:
    mov ax, [sh_db_critcol]
    cmp ax, [sh_cr_c2]
    jg .allok
    mov bx, [sh_cr_r1]
    SHOUT sh_getcell2
    jnc .skipcol                       ; a blank header: no constraint
    call sh_dbresolve
    jnc .skipcol                       ; names no real field: ignored
    mov [sh_db_fcol2], ax
    mov ax, [sh_db_critcol]
    mov bx, [sh_db_critrow]
    SHOUT sh_getcell2
    jnc .skipcol                       ; a blank condition: no constraint
    call sh_dbtest
    jnc .failed
.skipcol:
    inc word [sh_db_critcol]
    jmp .colloop
.allok:
    stc
    jmp .out
.failed:
    clc
.out:
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbtest - in: sh_curtype/sh_curaux/sh_acc/sh_sacc hold a just-read,
; non-blank CONDITION cell; sh_db_fcol2/sh_db_dbrow name the database cell to
; test it against. out: CF=1 the database cell satisfies the condition.
;
; Banks the condition into sh_db_cond* (type, error code, the eight-byte
; value, and - through sh_spush's own stack - the text) BEFORE reading the
; database cell, which may recurse into an arbitrary evaluation the same way
; a formula cell folding a range of its own does (81.52): sh_curtype/sh_acc/
; sh_sacc are the WHOLE machine's scratch for "the value just read", shared
; by every evaluation whether it goes through a database function or not, so
; this banking is the ordinary rule here and not specific to re-entrancy.
; -----------------------------------------------------------------------------
sh_dbtest:
    push bx
    push cx
    push dx
    push si
    push di
    mov al, [sh_curtype]
    mov [sh_db_condtype], al
    mov al, [sh_curaux]
    mov [sh_db_condaux], al
    mov ax, [sh_acc]
    mov [sh_db_condval], ax
    mov ax, [sh_acc+2]
    mov [sh_db_condval+2], ax
    mov ax, [sh_acc+4]
    mov [sh_db_condval+4], ax
    mov ax, [sh_acc+6]
    mov [sh_db_condval+6], ax
    cmp byte [sh_db_condtype], SH_T_TEXT
    jne .havecond
    SHOUT sh_spush
    jnc .havecond
    clc                                ; the bank is full: #VALUE! already
    jmp .out                          ; raised; this condition cannot be read
.havecond:
    mov ax, [sh_db_fcol2]
    mov bx, [sh_db_dbrow]
    SHOUT sh_getcell2                  ; sh_db_cond* is NAMED scratch, not
                                        ; live on a call frame - nothing this
                                        ; recurses into can reach it by name
    call sh_dbcmp                      ; CF=1 = the database cell satisfies it
    jc .popmatch
    cmp byte [sh_db_condtype], SH_T_TEXT
    jne .out
    SHOUT sh_spop
    clc
    jmp .out
.popmatch:
    cmp byte [sh_db_condtype], SH_T_TEXT
    jne .matched
    SHOUT sh_spop
.matched:
    stc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_dbcmp - in: sh_db_condtype/condaux/condval (+ sh_sslot depth 0 when it is
; text) = the CONDITION; sh_curtype/sh_curaux/sh_acc/sh_sacc = the DATABASE
; cell just read. out: CF=1 the database cell satisfies the condition.
;
; A NUMBER or LOGICAL condition is exact equality against a cell of the SAME
; type - Sheet's own `=` draws the identical line (81.53), so 5 never equals
; TRUE here either. A TEXT condition with no relational prefix is a PREFIX
; match against the cell's text, case-insensitively, with `*`/`?` wildcards
; if it has any (81.65.3) - Excel's own rule for a bare label criterion. A
; TEXT condition that opens with =, <>, <=, >=, < or > compares NUMERICALLY
; when what follows the operator parses as a clean number, or as EXACT text
; otherwise; an operator followed by text that turns out not to be exactly
; the operator's own three shapes (=, <>, or a bare compare) is treated as a
; LITERAL text match including the operator characters, which will simply
; never match real data - a documented shortfall rather than a silent wrong
; answer, same as `~`-escaping a literal wildcard being absent from
; sh_dbwildmatch below.
; -----------------------------------------------------------------------------
sh_dbcmp:
    push bx
    push cx
    push dx
    push si
    push di
    mov al, [sh_db_condtype]
    cmp al, SH_T_TEXT
    je .condtext
    cmp al, SH_T_NUM
    je .condnumbool
    cmp al, SH_T_BOOL
    je .condnumbool
    clc                                ; an ERROR condition holds for nothing
    jmp .out
.condnumbool:
    cmp byte [sh_curtype], al
    jne .no
    SHOUT sh_acc_load_a                ; A = the database cell (sh_acc_load_b
    push si                            ; is not among the vectors this module
    mov si, sh_db_condval               ; has, sh_acc_load_a and fp_unpack_b
    SHOUT fp_unpack_b                  ; both are - so the condition goes into
    pop si                             ; B instead)
    SHOUT fp_cmpab
    or ax, ax
    jne .no
    jmp .yes
.condtext:
    xor ax, ax
    SHOUT sh_sslot                     ; SI = the banked condition text
    call sh_dbcrit_parse                ; SI past any operator; BX = the
                                        ; outcome mask sh_pcmp itself uses
                                        ; (1 lt, 2 eq, 4 gt), 0 = none
    or bx, bx
    jnz .withop
    cmp byte [sh_curtype], SH_T_TEXT   ; no operator: a PREFIX/wildcard match
    jne .no                           ; against the cell's OWN text, so the
                                       ; cell has to have one
    mov di, sh_sacc                    ; the database cell's own text
    call sh_dbwildmatch
    jmp .out
.withop:
    push si
    SHOUT fp_atof
    jc .textop
    cmp byte [si], 0
    jne .textop2
    add sp, 2                          ; the saved SI is not needed - the
                                        ; whole remainder parsed cleanly
    cmp byte [sh_curtype], SH_T_NUM
    jne .no
    SHOUT fp_a_to_b                    ; B = the criterion's number
    SHOUT sh_acc_load_a                ; A = the database cell's number
    SHOUT fp_cmpab                     ; the mask build below reads its flags
                                       ; DIRECTLY - nothing may come between
                                       ; this call and the first jz/jl, or it
                                       ; is testing THAT instruction's flags
                                       ; instead (this cost an `xor cx,cx`
                                       ; here once: every criterion "held" as
                                       ; equal, because xor's own ZF=1 is what
                                       ; jz then saw)
    mov cx, 2                          ; equal, until a flag says otherwise
    jz .chave
    mov cx, 1
    jl .chave
    mov cx, 4
.chave:
    test bx, cx
    jz .no
    jmp .yes
.textop2:
    add sp, 2
    jmp .textop_di
.textop:
    pop si                             ; back to just past the operator
.textop_di:
    cmp byte [sh_curtype], SH_T_TEXT   ; a literal text compare needs a TEXT
    jne .no                           ; cell - sh_sacc is stale for a number
    mov di, sh_sacc
    call sh_dblkstrcmp                 ; -1/0/1 in AX ONLY - sh_dblkstrcmp's
                                       ; own -1/1 exits are a plain MOV, which
                                       ; sets no flags at all, so testing
                                       ; jl/jz right after it (as the numeric
                                       ; branch above may, right after
                                       ; fp_cmpab, which DOES document doing
                                       ; this) would read whatever flags its
                                       ; last internal compare happened to
                                       ; leave - build the mask from AX
                                       ; instead, with or ax,ax immediately
                                       ; first
    or ax, ax
    mov cx, 2
    jz .thave
    mov cx, 1
    js .thave
    mov cx, 4
.thave:
    test bx, cx
    jz .no
.yes:
    stc
    jmp .out
.no:
    clc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    ret

; sh_dbcrit_parse - in: SI = a condition's text. out: SI past any leading
; relational operator (=, <, >, <=, >=, <>); BX = sh_pcmp's own outcome mask
; (1 lt, 2 eq, 4 gt, ORed) - 0 if the text opens with none of these six
; spellings, and SI is UNCHANGED.
sh_dbcrit_parse:
    mov al, [si]
    cmp al, '='
    jne .notEq
    inc si
    mov bx, 2
    ret
.notEq:
    cmp al, '<'
    jne .notLt
    inc si
    cmp byte [si], '='
    jne .notLtEq
    inc si
    mov bx, 3
    ret
.notLtEq:
    cmp byte [si], '>'
    jne .justLt
    inc si
    mov bx, 5
    ret
.justLt:
    mov bx, 1
    ret
.notLt:
    cmp al, '>'
    jne .none
    inc si
    cmp byte [si], '='
    jne .justGt
    inc si
    mov bx, 6
    ret
.justGt:
    mov bx, 4
    ret
.none:
    xor bx, bx
    ret

; -----------------------------------------------------------------------------
; sh_dbwildmatch - SI = a pattern (may hold `*` any-sequence and `?` any-one-
; character), DI = a subject; both compared case-insensitively. A pattern
; with NEITHER wildcard matches as a PREFIX of the subject (Excel's own rule
; for a bare label criterion); a pattern that uses one matches the WHOLE
; subject, standard glob semantics anchored at both ends. No escape for a
; literal `*` or `?` - Excel's own `~` escape is not implemented (81.65.3's
; own header names this, deliberately, rather than silently).
;
; The wildcard arm is the classic iterative backtrack: DX remembers the last
; `*` seen in the pattern (0 = none yet) and CX the subject position it may
; re-expand from, so a mismatch after a star retries one character further in
; rather than needing real recursion this assembler has no stack frames for.
; -----------------------------------------------------------------------------
sh_dbwildmatch:
    push ax
    push bx
    push cx
    push dx
    push bp
    push si
    push di
    mov bx, si
.scanwild:
    mov al, [bx]
    or al, al
    jz .nowild
    cmp al, '*'
    je .haswild
    cmp al, '?'
    je .haswild
    inc bx
    jmp .scanwild
.nowild:
.prefix:
    mov al, [si]
    or al, al
    jz .yes                            ; the whole pattern matched a prefix
    mov ah, [di]
    call sh_dblkup
    xchg al, ah
    call sh_dblkup
    xchg al, ah
    cmp al, ah
    jne .no
    inc si
    inc di
    jmp .prefix
.haswild:
    xor dx, dx
.glob:
    mov al, [si]
    or al, al
    jz .patend
    cmp al, '*'
    jne .notstar
    mov dx, si
    inc dx
    mov bp, di                         ; BP, not CX - the 8086 cannot address
                                        ; memory through CX ([cx] below is
                                        ; illegal), and BP is otherwise free
                                        ; here
    inc si
    jmp .glob
.notstar:
    mov ah, [di]
    or ah, ah
    jz .retry                          ; the subject ran out; only a star can
                                        ; still save this
    cmp al, '?'
    je .onechar
    push ax
    call sh_dblkup                     ; AL still holds the PATTERN char
    mov bl, al
    pop ax
    mov al, ah                         ; AL = the subject char now
    call sh_dblkup
    cmp al, bl
    jne .retry
.onechar:
    inc si
    inc di
    jmp .glob
.patend:
    cmp byte [di], 0
    je .yes
.retry:
    ; the classic iterative backtrack: resume the pattern right after the
    ; last star and advance the subject position it last resumed from by
    ; one. BP holds that resume position (not CX - the 8086 cannot address
    ; memory through CX at all, and [bp] without a segment override
    ; addresses SS, not DS, so every read of it below goes through DI
    ; instead). If it is already the terminator, there is no subject left
    ; to retry over, and advancing anyway would walk past the buffer into
    ; whatever memory follows it, which is what let this match "Apple"
    ; against "*an*" the first time this was tried (the subject exhausted
    ; at the wildcard's own trailing star, then kept retrying past the NUL
    ; and comparing the pattern's 'a' against stale bytes beyond sh_sacc)
    or dx, dx
    jz .no
    mov di, bp
    cmp byte [di], 0
    je .no
    mov si, dx
    inc bp
    mov di, bp
    jmp .glob
.yes:
    stc
    jmp .out
.no:
    clc
.out:
    pop di
    pop si
    pop bp
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_dblkup - AL to upper case. Preserves everything else. sh_lkup's own body
; (27166): kept local rather than vectored, one instruction not worth a door.
sh_dblkup:
    cmp al, 'a'
    jb .out
    cmp al, 'z'
    ja .out
    sub al, 32
.out:
    ret

; sh_dblkstrcmp - case-insensitive string compare, sh_lkstrcmp's own body
; (27130): AX = -1/0/1, everything else preserved. Kept local for the same
; reason sh_dblkup is - it is SHOUT's cost (a far call) on every character
; that would be paid instead, not the routine's size.
sh_dblkstrcmp:
    push bx
    push cx
    push si
    push di
.c:
    mov al, [si]
    mov bl, [di]
    call sh_dblkup
    xchg al, bl
    call sh_dblkup
    xchg al, bl
    cmp al, bl
    jb .lo
    ja .hi
    or al, al
    jz .eq
    inc si
    inc di
    jmp short .c
.eq:
    xor ax, ax
    jmp short .out
.lo:
    mov ax, -1
    jmp short .out
.hi:
    mov ax, 1
.out:
    pop di
    pop si
    pop cx
    pop bx
    ret

; =============================================================================
; DATA ▸ FIND / EXTRACT / DELETE (81.71), the criteria engine above driven
; from a MENU. Verb SHM_DBCMD; [sh_dbc_kind] picks the command and
; [sh_dbc_res] carries the answer back.
;
; THE RECTANGLES COME FROM THE TWO NAMES, not from an argument list: 81.69's
; DATABASE and CRITERIA, read through sh_name_lookup (already vectored). That
; is the whole difference from shm_pdatabase, which parses them out of the
; formula text - everything past sh_dbcmd_ranges is the identical
; sh_dbrowmatch loop.
;
; sh_db_busy IS SET HERE TOO, for the reason 81.65 sets it: sh_db_c1..sh_cr_r2
; stay live across the entire walk, and a criteria cell holding its own
; =DSUM(...) would otherwise trample them mid-scan. This is that flag's first
; writer outside shm_pdatabase.
; =============================================================================

; -----------------------------------------------------------------------------
; sh_dbcmd_ranges - fill sh_db_* and sh_cr_* from the two defined names.
; out: CF=1 both were bound; CF=0 with [sh_dbc_res] already set to say which
; one was not. Every register preserved.
; -----------------------------------------------------------------------------
sh_dbcmd_ranges:
    push ax
    push bx
    push cx
    push dx
    push si
    mov si, sh_s_dbname
    SHOUT sh_name_lookup
    jnc .nodb
    mov [sh_db_c1], ax
    mov [sh_db_r1], bx
    mov [sh_db_c2], cx
    mov [sh_db_r2], dx
    mov si, sh_s_critname
    SHOUT sh_name_lookup
    jnc .nocrit
    mov [sh_cr_c1], ax
    mov [sh_cr_r1], bx
    mov [sh_cr_c2], cx
    mov [sh_cr_r2], dx
    call sh_dbcmd_norm                 ; a name keeps both corners as the
    stc                                ; selection gave them (sh_name_def), so
    jmp .out                           ; the walks below have to be given a
.nodb:                                 ; rectangle that reads low-to-high
    mov byte [sh_dbc_res], SH_DBR_NODB
    clc
    jmp .out
.nocrit:
    mov byte [sh_dbc_res], SH_DBR_NOCRIT
    clc
.out:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_dbcmd_norm - put both rectangles the right way round. shm_pdatabase never
; had to: a formula's range argument arrives from sh_pargref already ordered.
; A NAME does not - Set Database on a selection dragged upwards binds r1 > r2,
; and every `ja`/`jg` below would then walk zero rows and report no matches,
; which reads as a broken criteria rather than a backwards drag
sh_dbcmd_norm:
    push ax
    mov ax, [sh_db_c1]
    cmp ax, [sh_db_c2]
    jle .r1
    xchg ax, [sh_db_c2]
    mov [sh_db_c1], ax
.r1:
    mov ax, [sh_db_r1]
    cmp ax, [sh_db_r2]
    jle .c2
    xchg ax, [sh_db_r2]
    mov [sh_db_r1], ax
.c2:
    mov ax, [sh_cr_c1]
    cmp ax, [sh_cr_c2]
    jle .r2
    xchg ax, [sh_cr_c2]
    mov [sh_cr_c1], ax
.r2:
    mov ax, [sh_cr_r1]
    cmp ax, [sh_cr_r2]
    jle .out
    xchg ax, [sh_cr_r2]
    mov [sh_cr_r1], ax
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; shm_dbcmd - the verb. in: [sh_dbc_kind]. out: [sh_dbc_res]; AX BX CX DX SI
; DI all clobbered, which is what a `retf` verb is allowed to do.
; -----------------------------------------------------------------------------
shm_dbcmd:
    cmp byte [sh_db_busy], 0
    je .free
    mov byte [sh_dbc_res], SH_DBR_BUSY
    ret
.free:
    call sh_dbcmd_ranges
    jnc .out                           ; sh_dbc_res already says which name
    mov byte [sh_db_busy], 1
    cmp byte [sh_dbc_kind], SH_DBC_FIND
    je .dofind
    cmp byte [sh_dbc_kind], SH_DBC_DELETE
    je .dodelete
    call sh_dbcmd_extract
    jmp .done
.dofind:
    call sh_dbcmd_find
    jmp .done
.dodelete:
    call sh_dbcmd_delete
.done:
    mov byte [sh_db_busy], 0
.out:
    ret

; -----------------------------------------------------------------------------
; sh_dbcmd_find - Data ▸ Find. The Reference Guide: "If the active cell is
; outside the database when you choose Data Find, Microsoft Excel selects the
; first record in the database that matches the criteria. If the active cell
; is inside the database ... the first record BELOW the active cell". So the
; starting row is derived from the selection, which is also what makes
; choosing Find again step to the next match.
; -----------------------------------------------------------------------------
sh_dbcmd_find:
    mov bx, [sh_db_r1]                 ; the header row; data starts below it
    mov ax, [sh_selrow]
    cmp ax, [sh_db_r1]                 ; the selection inside the database?
    jb .fromtop
    cmp ax, [sh_db_r2]
    ja .fromtop
    mov bx, ax                         ; yes: start on the row AFTER it
.fromtop:
    inc bx
.loop:
    cmp bx, [sh_db_r2]
    ja .nomore
    push bx
    call sh_dbrowmatch
    pop bx
    jc .hit
    inc bx
    jmp .loop
.hit:
    mov ax, [sh_db_c1]                 ; select the whole record, which is
    mov [sh_selcol], ax                ; what Excel's Find does - the record
    mov [sh_selrow], bx                ; and not one cell of it
    mov ax, [sh_db_c2]
    mov [sh_selcol2], ax
    mov [sh_selrow2], bx
    mov ax, [sh_db_c1]
    SHOUT sh_scrollto
    mov byte [sh_dbc_res], SH_DBR_OK
    ret
.nomore:                               ; a search that BEGAN part-way down the
    mov byte [sh_dbc_res], SH_DBR_LAST ; database found nothing FURTHER, which
    mov ax, [sh_selrow]                ; is a different sentence from "nothing
    cmp ax, [sh_db_r1]                 ; in it matches at all" - and the one
    jbe .whole                         ; Excel shows when Find walks off the
    cmp ax, [sh_db_r2]                 ; last matching record
    jbe .out
.whole:
    mov byte [sh_dbc_res], SH_DBR_NOMATCH
.out:
    ret

; -----------------------------------------------------------------------------
; sh_dbcmd_put - copy ONE field: read (AX,BX) and write it at (CX,DX) as a
; VALUE. The Reference Guide is explicit that this is what Extract does -
; "If a record contains a formula, the extract range will contain only the
; value produced by that formula and not the formula itself" - so this reads
; through sh_getcell2, which hands back the evaluated cell, and never touches
; the formula text. Preserves nothing but the rectangles in bss.
; -----------------------------------------------------------------------------
sh_dbcmd_put:
    push cx
    push dx
    SHOUT sh_getcell2
    pop dx
    pop cx
    mov ax, cx
    mov bx, dx
    jnc .blank
    cmp byte [sh_curtype], SH_T_TEXT
    je .text
    cmp byte [sh_curtype], SH_T_BOOL
    je .bool
    cmp byte [sh_curtype], SH_T_ERR
    je .err
    SHOUT sh_setvald                   ; the number is already in sh_acc
    ret
.text:
    mov si, sh_sacc
    SHOUT sh_settext
    ret
.bool:
    mov dl, [sh_curaux]
    SHOUT sh_setbool
    ret
.err:
    mov dl, [sh_curaux]
    SHOUT sh_seterr
    ret
.blank:
    SHOUT sh_clearcell
    ret

; -----------------------------------------------------------------------------
; sh_dbcmd_extract - Data ▸ Extract. The extract range is the SELECTION the
; dialog was opened on (sh_ex_*), and its FIRST ROW names the fields to take:
; "The field names you use for the extract range must be the same as the
; field names you used in the database. However, you don't have to use all
; of the database field names."
;
; Two shapes, both Excel's. A range that is ONLY its header row extracts
; downward with no limit (Excel clears "all cells below the field names to
; the bottom of the worksheet"; this clears what it wrote plus the rows it
; would have written, which is the same thing for any sheet this machine can
; hold). A range with rows beneath it takes as many records as fit and says
; so when they did not all fit.
; -----------------------------------------------------------------------------
sh_dbcmd_extract:
    call sh_dbcmd_exnorm               ; both corners the right way round
    mov ax, [sh_ex_r1]
    inc ax
    mov [sh_ex_row], ax                ; the first row of output
    call sh_dbcmd_exfields             ; does its header name ANY real field?
    jnc .nofield
    mov bx, [sh_db_r1]
    inc bx
.loop:
    cmp bx, [sh_db_r2]
    ja .done
    push bx
    call sh_dbrowmatch
    pop bx
    jnc .next
    call sh_dbcmd_exrow                ; CF=0 = the range is full
    jnc .full
.next:
    inc bx
    jmp .loop
.done:
    call sh_dbcmd_exclear              ; blank whatever the last extract left
    mov byte [sh_dbc_res], SH_DBR_OK
    ret
.full:
    mov byte [sh_dbc_res], SH_DBR_NOROOM
    ret
.nofield:
    mov byte [sh_dbc_res], SH_DBR_NOFIELD
    ret

; sh_dbcmd_exnorm - the extract range, both corners the right way round
sh_dbcmd_exnorm:
    push ax
    mov ax, [sh_ex_c1]
    cmp ax, [sh_ex_c2]
    jle .r
    xchg ax, [sh_ex_c2]
    mov [sh_ex_c1], ax
.r:
    mov ax, [sh_ex_r1]
    cmp ax, [sh_ex_r2]
    jle .out
    xchg ax, [sh_ex_r2]
    mov [sh_ex_r1], ax
.out:
    pop ax
    ret

; sh_dbcmd_exfields - out: CF=1 if at least ONE column of the extract range's
; header row names a real database field. A range naming none at all is a
; user error worth a sentence, not an empty extract that looks like "nothing
; matched"
sh_dbcmd_exfields:
    push ax
    push bx
    push cx
    mov cx, [sh_ex_c1]
.each:
    cmp cx, [sh_ex_c2]
    jg .none
    mov ax, cx
    mov bx, [sh_ex_r1]
    push cx
    SHOUT sh_getcell2
    jnc .nextcol
    call sh_dbresolve                  ; the same resolver the criteria
    jc .found                          ; headers use (81.65)
.nextcol:
    pop cx
    inc cx
    jmp .each
.found:
    pop cx
    stc
    jmp .out
.none:
    clc
.out:
    pop cx
    pop bx
    pop ax
    ret

; sh_dbcmd_exrow - copy the matching database row (sh_dbrowmatch left it in
; sh_db_dbrow) into row [sh_ex_row] of the extract range, field by field.
; out: CF=1 written, CF=0 the range had no room left. BX preserved.
;
; The columns are held in NAMED SCRATCH rather than registers: this walks two
; column spaces at once - the extract range's own (sh_ex_ec) and the database
; column each of its headers resolves to (sh_ex_dc) - across a sh_getcell2
; and a sh_dbcmd_put that both clobber freely.
sh_dbcmd_exrow:
    push ax
    push bx
    push cx
    push dx
    mov ax, [sh_ex_r2]                 ; is there a row left to write into?
    cmp ax, [sh_ex_r1]
    je .room                           ; a header-ONLY range has no bottom
    mov ax, [sh_ex_row]
    cmp ax, [sh_ex_r2]
    ja .full
.room:
    mov ax, [sh_ex_c1]
    mov [sh_ex_ec], ax
.col:
    mov ax, [sh_ex_ec]
    cmp ax, [sh_ex_c2]
    jg .rowdone
    mov bx, [sh_ex_r1]                 ; this extract column's own header...
    SHOUT sh_getcell2
    jnc .nextcol
    call sh_dbresolve                  ; ...named as a database field, by the
    jnc .nextcol                       ; identical resolver the criteria
    mov [sh_ex_dc], ax                 ; headers go through (81.65)
    mov ax, [sh_ex_dc]
    mov bx, [sh_db_dbrow]
    mov cx, [sh_ex_ec]
    mov dx, [sh_ex_row]
    call sh_dbcmd_put
.nextcol:
    inc word [sh_ex_ec]
    jmp .col
.rowdone:
    inc word [sh_ex_row]
    stc
    jmp .out
.full:
    clc
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_dbcmd_exclear - blank the rows of the extract range below what this run
; wrote. Excel: "all cells below the field names ... are cleared whether or
; not information is extracted into them", which is what stops the previous
; extract's tail being read as part of this one
sh_dbcmd_exclear:
    push ax
    push bx
    push cx
    push dx
    mov dx, [sh_ex_row]
    mov cx, [sh_ex_r2]
    cmp cx, [sh_ex_r1]
    jne .bounded
    mov cx, dx                          ; header-only: clear the rows this run
    add cx, SH_DBC_EXTAIL               ; would have used and a tail past them
.bounded:
.row:
    cmp dx, cx
    ja .out
    mov bx, [sh_ex_c1]
.col:
    cmp bx, [sh_ex_c2]
    jg .nextrow
    mov ax, bx
    push bx
    push cx
    push dx
    mov bx, dx
    SHOUT sh_clearcell
    pop dx
    pop cx
    pop bx
    inc bx
    jmp .col
.nextrow:
    inc dx
    jmp .row
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbcmd_delete - Data ▸ Delete. "When you delete records from the database,
; the other records in the database shift up to fill any gaps, but the rest of
; the worksheet is not affected ... the cells below the database do not shift
; up ten rows, as they would if you used the Edit Delete command."
;
; So this is NOT sh_rowcol_op: only the database's own rectangle moves, cell
; by cell, and a cell one column to the right of it stays exactly where it is.
; Records are carried as TEXT - sh_cell_totext out, sh_commit back - which is
; the pair Sort's own carry (81.61) and the block clipboard (81.18) already
; move a record with, so values, labels and formulas need no three cases here.
;
; Compaction runs TOP DOWN and only ever writes ABOVE where it reads, so no
; snapshot is needed: the destination row has already been read past.
; -----------------------------------------------------------------------------
sh_dbcmd_delete:
    mov ax, [sh_db_r1]
    inc ax
    mov [sh_dbc_dst], ax               ; the next surviving row's new home
    mov ax, [sh_db_r1]
    inc ax
    mov [sh_dbc_src], ax
    mov word [sh_dbc_hits], 0
.loop:
    mov bx, [sh_dbc_src]
    cmp bx, [sh_db_r2]
    ja .done
    call sh_dbrowmatch
    jc .drop
    call sh_dbcmd_moverow              ; a keeper: slide it up if it moved
    inc word [sh_dbc_dst]
    jmp .next
.drop:
    inc word [sh_dbc_hits]
.next:
    inc word [sh_dbc_src]
    jmp .loop
.done:
    cmp word [sh_dbc_hits], 0
    je .nomatch
    call sh_dbcmd_deltail              ; blank the rows nothing moved into
    call sh_dbcmd_shrink               ; ...and DATABASE now names fewer rows
    mov byte [sh_dbc_res], SH_DBR_OK
    ret
.nomatch:
    mov byte [sh_dbc_res], SH_DBR_NOMATCH
    ret

; sh_dbcmd_moverow - carry the record at [sh_dbc_src] up to [sh_dbc_dst],
; across the database's columns only. A row already in place is left alone
sh_dbcmd_moverow:
    push ax
    push bx
    push cx
    push dx
    mov ax, [sh_dbc_src]
    cmp ax, [sh_dbc_dst]
    je .out
    mov ax, [sh_db_c1]
    mov [sh_dbc_col], ax
.col:
    mov ax, [sh_dbc_col]
    cmp ax, [sh_db_c2]
    jg .out
    mov bx, [sh_dbc_src]
    SHOUT sh_cell_totext               ; -> sh_clipbuf, CX = its length
    call sh_dbcmd_totarget
    inc word [sh_dbc_col]
    jmp .col
.out:
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_dbcmd_totarget - sh_clipbuf holds the record's text; put it in
; ([sh_dbc_col], [sh_dbc_dst]). sh_commit is driven exactly the way
; sh_sort_permcol drives it: the selection IS the argument
sh_dbcmd_totarget:
    push ax
    push bx
    push cx
    push si
    push di
    mov si, sh_clipbuf
    mov di, sh_editbuf
    xor cx, cx
.copy:
    mov al, [si]
    mov [di], al
    or al, al
    jz .copied
    inc si
    inc di
    inc cx
    jmp .copy
.copied:
    mov [sh_editlen], cl
    mov ax, [sh_dbc_col]
    mov [sh_selcol], ax
    mov [sh_selcol2], ax
    mov ax, [sh_dbc_dst]
    mov [sh_selrow], ax
    mov [sh_selrow2], ax
    cmp byte [sh_editbuf], '='
    jne .commit
    mov ax, [sh_dbc_dst]               ; a formula follows its own row, the
    sub ax, [sh_dbc_src]               ; way Sort's carry makes one follow
    mov [sh_cp_rowdelta], ax
    mov word [sh_cp_coldelta], 0
    call sh_dbcmd_shiftbuf
.commit:
    mov byte [sh_editing], 1
    SHOUT sh_commit
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_dbcmd_shiftbuf - run sh_editbuf's formula body through the copy shift and
; put the answer back, '=' and length included. sh_sort_permcol's own tail
sh_dbcmd_shiftbuf:
    push ax
    push cx
    push si
    push di
    mov si, sh_editbuf
    inc si
    mov di, sh_rwsrc
.in:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .in
    mov si, sh_rwsrc
    SHOUT sh_formula_copyshift
    mov byte [sh_editbuf], '='
    mov si, sh_rwdst
    mov di, sh_editbuf + 1
    mov cx, SH_EDITMAX - 1
.out1:
    mov al, [si]
    or al, al
    jz .done
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .out1
.done:
    mov byte [di], 0
    xor cx, cx
    mov si, sh_editbuf
.len:
    cmp byte [si], 0
    je .have
    inc si
    inc cx
    jmp .len
.have:
    mov [sh_editlen], cl
    pop di
    pop si
    pop cx
    pop ax
    ret

; sh_dbcmd_deltail - the rows between the last survivor and the database's old
; bottom edge hold copies of records that moved up; blank them, across the
; database's columns only
sh_dbcmd_deltail:
    push ax
    push bx
    push cx
    mov cx, [sh_dbc_dst]
.row:
    cmp cx, [sh_db_r2]
    ja .out
    mov ax, [sh_db_c1]
.col:
    cmp ax, [sh_db_c2]
    jg .nextrow
    mov bx, cx
    push ax
    push cx
    SHOUT sh_clearcell
    pop cx
    pop ax
    inc ax
    jmp .col
.nextrow:
    inc cx
    jmp .row
.out:
    pop cx
    pop bx
    pop ax
    ret

; sh_dbcmd_shrink - DATABASE names one row fewer per deleted record, so the
; next command does not walk the blanks this one left. Excel's own database
; range shrinks the same way
sh_dbcmd_shrink:
    push ax
    push bx
    push cx
    push dx
    push si
    mov ax, [sh_dbc_dst]
    dec ax
    mov [sh_db_r2], ax
    cmp ax, [sh_db_r1]                 ; every record gone: the name keeps its
    jae .bind                          ; header row and nothing else
    mov ax, [sh_db_r1]
    mov [sh_db_r2], ax
.bind:
    mov si, sh_s_dbname
    mov ax, [sh_db_c1]
    mov bx, [sh_db_r1]
    mov cx, [sh_db_c2]
    mov dx, [sh_db_r2]
    SHOUT sh_name_def
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret


; =============================================================================
; DATA ▸ SERIES (SPEC.md 81.72) - fill the selection from its first cell.
;
; "The command fills by rows or columns. The first cell in each row or column
; to be filled must have the starting value in it." Excel's dialog carries
; FIVE controls; this asks TWO questions, which is the app's own
; ask-in-sequence idiom (81.15's Sort, File ▸ Save As) rather than a seventh
; dialog engine:
;
;   Type + Date Unit  ->  one radio column (a date unit is only ever read when
;                         the type IS Date, so the two are really one question)
;   Step Value        ->  one text field, defaulting to 1
;
; SERIES IN is DERIVED rather than asked: a selection taller than it is wide
; fills down each column, otherwise along each row, which is the answer
; Excel's own dialog preselects from the same shape. STOP VALUE is 81.72's
; documented shortfall - the selection already bounds the fill, and an early
; stop would be a third dialog for the rarer half of one control.
; =============================================================================
SH_SER_LIN   equ 0                   ; the radio index IS the type
SH_SER_GRO   equ 1
SH_SER_DAY   equ 2
SH_SER_WD    equ 3
SH_SER_MON   equ 4
SH_SER_YR    equ 5

; -----------------------------------------------------------------------------
; shm_series - verb SHM_SERIES. The range is already pinned in sh_ser_c1..r2
; and the type and step already set. Clobbers freely.
; -----------------------------------------------------------------------------
shm_series:
    call sh_ser_norm
    mov ax, [sh_ser_r2]                ; taller than wide -> down the columns
    sub ax, [sh_ser_r1]
    mov bx, [sh_ser_c2]
    sub bx, [sh_ser_c1]
    cmp ax, bx
    jb .byrow
    mov [sh_ser_n], ax                 ; --- one series per COLUMN
    mov word [sh_ser_dc], 0
    mov word [sh_ser_dr], 1
    mov ax, [sh_ser_c1]
    mov [sh_ser_i], ax
.colloop:
    mov ax, [sh_ser_i]
    cmp ax, [sh_ser_c2]
    jg .out
    mov [sh_ser_col], ax
    mov ax, [sh_ser_r1]
    mov [sh_ser_row], ax
    call sh_ser_line
    inc word [sh_ser_i]
    jmp .colloop
.byrow:
    mov [sh_ser_n], bx                 ; --- one series per ROW
    mov word [sh_ser_dc], 1
    mov word [sh_ser_dr], 0
    mov ax, [sh_ser_r1]
    mov [sh_ser_i], ax
.rowloop:
    mov ax, [sh_ser_i]
    cmp ax, [sh_ser_r2]
    jg .out
    mov [sh_ser_row], ax
    mov ax, [sh_ser_c1]
    mov [sh_ser_col], ax
    call sh_ser_line
    inc word [sh_ser_i]
    jmp .rowloop
.out:
    ret

; sh_ser_norm - the pinned range the right way round (sh_dbcmd_norm's reason:
; a selection dragged upwards or leftwards keeps the corners it was given)
sh_ser_norm:
    push ax
    mov ax, [sh_ser_c1]
    cmp ax, [sh_ser_c2]
    jle .r
    xchg ax, [sh_ser_c2]
    mov [sh_ser_c1], ax
.r:
    mov ax, [sh_ser_r1]
    cmp ax, [sh_ser_r2]
    jle .out
    xchg ax, [sh_ser_r2]
    mov [sh_ser_r1], ax
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ser_line - one series, from ([sh_ser_col],[sh_ser_row]) along
; ([sh_ser_dc],[sh_ser_dr]) for [sh_ser_n] more cells. A line whose first cell
; is not a NUMBER is skipped whole rather than refused: filling a table's
; body one column at a time is exactly the case where one of them is a label,
; and Excel leaves that column alone too.
; -----------------------------------------------------------------------------
sh_ser_line:
    push ax
    push bx
    push cx
    mov ax, [sh_ser_col]
    mov bx, [sh_ser_row]
    SHOUT sh_getcell2
    jnc .out
    cmp byte [sh_curtype], SH_T_NUM
    jne .out
    mov si, sh_acc                     ; the start value, banked out of sh_acc
    mov di, sh_ser_cur                 ; before the first sh_setvald touches it
    call sh_ser_copy8
    mov word [sh_ser_k], 0             ; ...and which term of the series this
    call sh_ser_curser                 ; is, for the calendar arms, which
    jnc .nobase                        ; cannot iterate (see sh_ser_next)
    mov [sh_ser_base], ax
.nobase:
    mov cx, [sh_ser_n]
.each:
    jcxz .out
    push cx
    mov ax, [sh_ser_dc]
    add [sh_ser_col], ax
    mov ax, [sh_ser_dr]
    add [sh_ser_row], ax
    call sh_ser_next
    mov si, sh_ser_cur
    mov di, sh_acc
    call sh_ser_copy8
    mov ax, [sh_ser_col]
    mov bx, [sh_ser_row]
    SHOUT sh_setvald
    pop cx
    dec cx
    jmp .each
.out:
    pop cx
    pop bx
    pop ax
    ret

; sh_ser_copy8 - SI -> DI, one packed double. Preserves everything
sh_ser_copy8:
    push cx
    push si
    push di
    mov cx, 8
.b:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .b
    pop di
    pop si
    pop cx
    ret

; -----------------------------------------------------------------------------
; sh_ser_next - advance [sh_ser_cur] by one term of the series.
; Linear and Date: Day are the SAME arithmetic - a serial is a number of days,
; so adding the step to it is adding days - and they are separate items only
; because the menu asks the question Excel's does.
; -----------------------------------------------------------------------------
sh_ser_next:
    push ax
    push bx
    push si
    push di
    inc word [sh_ser_k]
    cmp byte [sh_ser_type], SH_SER_GRO
    je .grow
    cmp byte [sh_ser_type], SH_SER_WD
    je .weekday
    cmp byte [sh_ser_type], SH_SER_MON
    je .cal
    cmp byte [sh_ser_type], SH_SER_YR
    je .cal
    mov si, sh_ser_cur                 ; Linear, and Date: Day
    SHOUT fp_unpack_a
    mov si, sh_ser_step
    SHOUT fp_unpack_b
    SHOUT fp_add
    jmp .store
.grow:
    mov si, sh_ser_cur
    SHOUT fp_unpack_a
    mov si, sh_ser_step
    SHOUT fp_unpack_b
    SHOUT fp_mul
.store:
    mov di, sh_ser_cur
    SHOUT fp_pack_a
    jmp .out

; --- CALENDAR arithmetic, and it is computed from the START every time -----
; NOT iteratively from the cell before it. The clamp LOSES information: 31
; January + 1 month is 28 February, and stepping again from THAT gives 28
; March where Excel gives 31. So each term is `start + k months` with the
; clamp applied fresh, which is what the gate caught as a widening drift.
.cal:
    call sh_ser_stepint                ; BX = the step, as a whole number
    mov ax, [sh_ser_k]
    imul bx                            ; DX:AX = k * step; the range bounds k,
    mov bx, ax                         ; so the high half is never wanted
    mov ax, [sh_ser_base]
    SHOUT sh_ser_to_ymd
    cmp byte [sh_ser_type], SH_SER_YR
    je .yr
    add [sh_dt_m], bx
    jmp .rebuild
.yr:
    add [sh_dt_y], bx
.rebuild:
    call sh_ser_clampday               ; 31 Jan + 1 month is 28 FEBRUARY
    SHOUT sh_ymd_to_ser
    call sh_ser_setcur
    jmp .out

.weekday:
    call sh_ser_curser
    jnc .out
    mov [sh_ser_ser], ax
    push ax
    call sh_ser_stepint
    pop ax
    or bx, bx
    jz .wdone
    jl .wback
.wfwd:
    call sh_ser_nextwd
    dec bx
    jnz .wfwd
    jmp .wdone
.wback:
    call sh_ser_prevwd
    inc bx
    jnz .wback
.wdone:
    mov ax, [sh_ser_ser]
    call sh_ser_setcur
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret

; sh_ser_nextwd / sh_ser_prevwd - [sh_ser_ser] one WEEKDAY on or back. The
; day of the week is (serial + 6) mod 7 with 0 = Sunday, which is the
; convention WEEKDAY already answers in (sh_pdate's own)
sh_ser_nextwd:
    inc word [sh_ser_ser]
    call sh_ser_dow
    cmp al, 0
    je sh_ser_nextwd
    cmp al, 6
    je sh_ser_nextwd
    ret
sh_ser_prevwd:
    dec word [sh_ser_ser]
    call sh_ser_dow
    cmp al, 0
    je sh_ser_prevwd
    cmp al, 6
    je sh_ser_prevwd
    ret
sh_ser_dow:
    push bx
    push dx
    mov ax, [sh_ser_ser]
    add ax, 6
    xor dx, dx
    mov bx, 7
    div bx
    mov ax, dx
    pop dx
    pop bx
    ret

; sh_ser_curser - [sh_ser_cur] as an unsigned date serial in AX; CF=0 when it
; is not one at all, which leaves the cell alone rather than writing a wrong
; date
sh_ser_curser:
    push si
    push di
    mov si, sh_ser_cur
    mov di, sh_acc
    call sh_ser_copy8
    SHOUT sh_acc_toudw
    jc .bad
    stc
    jmp .out
.bad:
    clc
.out:
    pop di
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_ser_clampday - sh_dt_y/m/d, with the month rolled back into 1..12 and the
; day cut to that month's own length.
;
; BOTH HALVES ARE THE FEATURE. sh_ymd_to_ser accepts a month outside 1..12 and
; a day past a month's end and ROLLS them - DATE(1990,13,1) is January 1991
; and DATE(1990,1,32) is 1 February, its own header says so - which is right
; for DATE() and wrong here: Excel's Date: Month series takes 31 January to 28
; FEBRUARY, not to 3 March. The rolling is what the first version of this did,
; and the test read it as a three-day drift.
; -----------------------------------------------------------------------------
sh_ser_clampday:
    push ax
    push bx
.high:
    cmp word [sh_dt_m], 12
    jle .low
    sub word [sh_dt_m], 12
    inc word [sh_dt_y]
    jmp .high
.low:
    cmp word [sh_dt_m], 1
    jge .clamp
    add word [sh_dt_m], 12
    dec word [sh_dt_y]
    jmp .low
.clamp:
    mov ax, [sh_dt_m]
    mov bx, [sh_dt_y]
    SHOUT sh_monlen
    cmp [sh_dt_d], ax
    jle .out
    mov [sh_dt_d], ax
.out:
    pop bx
    pop ax
    ret

; sh_ser_setcur - AX = a serial -> [sh_ser_cur]. sh_acc_fromudw, NOT fp_i2a:
; that one is signed and a serial past 32767 came back negative, which the
; gate read as every later cell repeating one wrong date
sh_ser_setcur:
    push si
    push di
    SHOUT sh_acc_fromudw
    mov si, sh_acc
    mov di, sh_ser_cur
    call sh_ser_copy8
    pop di
    pop si
    ret

; sh_ser_stepint - the step as a whole number in BX. A calendar step of 1.5
; months is not a thing, so it truncates rather than refusing
sh_ser_stepint:
    push si
    push di
    mov si, sh_ser_step
    mov di, sh_acc
    call sh_ser_copy8
    SHOUT sh_acc_toint
    jnc .ok
    xor ax, ax
.ok:
    mov bx, ax
    pop di
    pop si
    ret

; =============================================================================
; CELL (81.66): `CELL(type_of_info [, reference])`, Excel's own compatibility
; subset - nine attributes, from `Microsoft Excel Functions and Macros`
; (`LIBRARY/documentation/excel_man/` p.31-33), checked against the real text
; rather than recalled: "width" "row" "col" "protect" "address" "contents"
; "format" "prefix" "type". GET.CELL's broader set (Excel's own note: "if you
; need to use cell information in a macro") is not this app's macro language
; either, so nine is the whole of it, not a chosen subset of a longer list.
;
; reference is a single cell OR a range, using its UPPER-LEFT corner either
; way (sh_pargref's near corner, unreconciled the same way every other range
; argument in this file is - "B9:A1" is not sorted into "A1:B9" anywhere
; else here either). Omitted, it is the CURRENT SELECTION's own upper-left,
; normalized by hand rather than through sh_selrect (not among this module's
; vectors, and two comparisons are cheaper than adding one).
; =============================================================================
SH_CI_WIDTH    equ 0
SH_CI_ROW      equ 1
SH_CI_COL      equ 2
SH_CI_PROTECT  equ 3
SH_CI_ADDRESS  equ 4
SH_CI_CONTENTS equ 5
SH_CI_FORMAT   equ 6
SH_CI_PREFIX   equ 7
SH_CI_TYPE     equ 8
SH_CI_N        equ 9

sh_ci_n0: db 'width', 0
sh_ci_n1: db 'row', 0
sh_ci_n2: db 'col', 0
sh_ci_n3: db 'protect', 0
sh_ci_n4: db 'address', 0
sh_ci_n5: db 'contents', 0
sh_ci_n6: db 'format', 0
sh_ci_n7: db 'prefix', 0
sh_ci_n8: db 'type', 0
sh_ci_names: dw sh_ci_n0, sh_ci_n1, sh_ci_n2, sh_ci_n3, sh_ci_n4, sh_ci_n5
             dw sh_ci_n6, sh_ci_n7, sh_ci_n8

; the 21 short format codes CELL("format") answers, indexed exactly as
; sh_nf_codes (81.55) is - `Microsoft Excel Functions and Macros` p.32's own
; table, minus the general/currency/percent/scientific/date rows the OCR
; garbled beyond trusting: those nine (G, P0, P2, S2, D1-D4, D6-D9) survived
; the extraction intact and are the ones the codes below were checked
; against; the rest (F0, F2, ,0, ,2, C0, C0-, C2, C2-) follow the same
; documented convention every other Excel-compatible reader of this table
; agrees on
sh_ci_f0: db 'G', 0
sh_ci_f1: db 'F0', 0
sh_ci_f2: db 'F2', 0
sh_ci_f3: db ',0', 0
sh_ci_f4: db ',2', 0
sh_ci_f5: db 'C0', 0
sh_ci_f6: db 'C0-', 0
sh_ci_f7: db 'C2', 0
sh_ci_f8: db 'C2-', 0
sh_ci_f9: db 'P0', 0
sh_ci_f10: db 'P2', 0
sh_ci_f11: db 'S2', 0
sh_ci_f12: db 'D4', 0
sh_ci_f13: db 'D1', 0
sh_ci_f14: db 'D2', 0
sh_ci_f15: db 'D3', 0
sh_ci_f16: db 'D7', 0
sh_ci_f17: db 'D6', 0
sh_ci_f18: db 'D9', 0
sh_ci_f19: db 'D8', 0
sh_ci_f20: db 'D4', 0
sh_ci_fmtcodes: dw sh_ci_f0, sh_ci_f1, sh_ci_f2, sh_ci_f3, sh_ci_f4, sh_ci_f5
                dw sh_ci_f6, sh_ci_f7, sh_ci_f8, sh_ci_f9, sh_ci_f10
                dw sh_ci_f11, sh_ci_f12, sh_ci_f13, sh_ci_f14, sh_ci_f15
                dw sh_ci_f16, sh_ci_f17, sh_ci_f18, sh_ci_f19, sh_ci_f20

sh_ci_pfx_left:   db 39, 0            ; "'" - `39` because an apostrophe
                                      ; inside a NASM `db '...'` string ends
                                      ; it early, the same reason a quote
                                      ; character needs one below
sh_ci_pfx_right:  db 34, 0            ; '"'
sh_ci_pfx_center: db 94, 0            ; '^'
sh_ci_empty:      db 0                ; General's own "": sh_snull (27168)
                                      ; is the PACKAGE's, reached through
                                      ; plain DS - a local copy keeps
                                      ; .prefix's four candidate strings all
                                      ; in the SAME segment (CS)

; in: AX = the id (142, unused - CELL is the only id this door answers for),
; SI just past '('. out: AX = the value in sh_acc or its address in sh_sacc,
; SI past ')'. BX CX DX DI kept, matching every other door's contract.
shm_pcell:
    push bx
    push cx
    push dx
    push di
    SHOUT sh_pcmp                      ; --- argument 1: type_of_info -------
    cmp byte [sh_curtype], SH_T_TEXT
    jne .badargs
    push si                            ; SI is the FORMULA position -
                                       ; sh_dblkstrcmp needs it for its own
                                       ; string compare below, and every path
                                       ; out of the loop must give it back
                                       ; before touching the formula text
                                       ; again (this cost the same class of
                                       ; bug sh_pargref's own header warns
                                       ; about, once: every case answered
                                       ; #VALUE! because the comma/')' check
                                       ; right after the loop was reading
                                       ; sh_sacc instead of the formula)
    mov cx, 0
.matchloop:
    cmp cx, SH_CI_N
    jae .matchfail
    mov bx, cx
    shl bx, 1
    mov di, [cs:bx+sh_ci_names]        ; a CS-relative offset - this MODULE's
                                       ; own data, not the package's - so
                                       ; sh_ci_namecmp reads it through [cs:]
                                       ; and not sh_dblkstrcmp's plain [di]
    push cx
    mov si, sh_sacc
    call sh_ci_namecmp
    pop cx
    or ax, ax
    je .havetype
    inc cx
    jmp .matchloop
.matchfail:
    pop si                              ; balance the stack before failing
    jmp .badargs                        ; - an unrecognized type_of_info:
                                        ; #VALUE!
.havetype:
    mov [sh_ci_which], cx
    pop si                              ; the formula position, back
    cmp byte [si], ','                 ; --- argument 2: reference, optional -
    jne .noref
    inc si
    SHOUT sh_pargref
    jnc .badargs
    mov ax, [sh_arg1col]
    mov [sh_ci_col], ax
    mov ax, [sh_arg1row]
    mov [sh_ci_row], ax
    jmp .haveref
.noref:
    mov ax, [sh_selcol]                ; the current selection's own upper-
    cmp ax, [sh_selcol2]               ; left, normalized by hand (sh_selrect
    jbe .colok                         ; itself is not among this module's
    mov ax, [sh_selcol2]               ; vectors)
.colok:
    mov [sh_ci_col], ax
    mov ax, [sh_selrow]
    cmp ax, [sh_selrow2]
    jbe .rowok
    mov ax, [sh_selrow2]
.rowok:
    mov [sh_ci_row], ax
.haveref:
    cmp byte [si], ')'
    jne .badargs
    inc si
    mov cx, [sh_ci_which]
    cmp cx, SH_CI_WIDTH
    je .width
    cmp cx, SH_CI_ROW
    je .row
    cmp cx, SH_CI_COL
    je .col
    cmp cx, SH_CI_PROTECT
    je .protect
    cmp cx, SH_CI_ADDRESS
    je .address
    cmp cx, SH_CI_CONTENTS
    je .contents
    cmp cx, SH_CI_FORMAT
    je .format
    cmp cx, SH_CI_PREFIX
    je .prefix
    jmp .type                          ; SH_CI_TYPE, the last of the nine
.width:
    mov ax, [sh_ci_col]
    SHOUT sh_colwidth
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .out
.row:
    mov ax, [sh_ci_row]
    inc ax                             ; 1-based, matching ROW() (81.31) -
    SHOUT sh_acc_int                   ; sh_identcol/sh_pcellref's row is
    mov byte [sh_curtype], SH_T_NUM    ; 0-based internally
    jmp .out
.col:
    mov ax, [sh_ci_col]
    inc ax                             ; 1-based, matching COLUMN()
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .out
.protect:
    mov ax, [sh_ci_col]
    mov bx, [sh_ci_row]
    SHOUT sh_bt_get                    ; AL = the border+protection byte, 0
    test al, SH_PROT_UNLOCK            ; when no record - which is LOCKED,
    jnz .unlocked                      ; the inverted sense §81.46's own
    mov ax, 1                          ; header explains
    jmp .protectdone
.unlocked:
    xor ax, ax
.protectdone:
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .out
.address:
    mov di, sh_sacc
    mov byte [di], '$'
    inc di
    mov ax, [sh_ci_col]
    SHOUT sh_colname                   ; -> sh_colbuf, NUL-terminated
    push si
    mov si, sh_colbuf
    call sh_ci_appendstr
    pop si
    mov byte [di], '$'
    inc di
    mov ax, [sh_ci_row]
    inc ax
    SHOUT sh_itoa                      ; -> sh_numbuf, NUL-terminated
    push si
    mov si, sh_numbuf
    call sh_ci_appendstr
    pop si
    mov byte [di], 0                   ; sh_ci_appendstr's own contract is
                                       ; "not including the NUL" - the LAST
                                       ; piece has to add its own, or
                                       ; whatever sh_sacc held before (the
                                       ; type_of_info argument text itself,
                                       ; still sitting past what this
                                       ; overwrote) trails the real answer
    mov byte [sh_curtype], SH_T_TEXT
    jmp .out
.contents:
    mov ax, [sh_ci_col]
    mov bx, [sh_ci_row]
    SHOUT sh_getcell2                  ; leaves sh_curtype/sh_acc/sh_sacc as
    jmp .out                          ; the target cell's own - CELL answers
                                       ; with THAT, whatever type it is
.format:
    mov ax, [sh_ci_col]
    mov bx, [sh_ci_row]
    SHOUT sh_cell_nfid                 ; AL = the id as Format > Number has
    cmp al, SH_NF_N                    ; it: the table's id+1 less one, else
    jb .fmtid                          ; the format byte's, else General - and
    xor al, al                         ; never an index past the table
.fmtid:
    mov bl, al
    xor bh, bh
    shl bx, 1
    push si                            ; SI is the FORMULA position (past the
                                       ; closing ')' since .haveref) for the
                                       ; WHOLE REST of this call, not scratch
                                       ; - sh_ci_copy_cs needs it as ITS OWN
                                       ; source pointer, and every path out
                                       ; has to give the real one back before
                                       ; touching the formula again (the same
                                       ; class of bug the type-match loop
                                       ; had, and .address already gets right
                                       ; by banking it the same way)
    mov si, [cs:bx+sh_ci_fmtcodes]
    mov di, sh_sacc
    call sh_ci_copy_cs
    pop si
    mov byte [sh_curtype], SH_T_TEXT
    jmp .out
.prefix:
    mov ax, [sh_ci_col]
    mov bx, [sh_ci_row]
    SHOUT sh_getcell2
    mov al, [sh_curfmt]
    and al, SH_FMT_ALIGN_MASK
    push si                            ; the FORMULA position - banked before
                                       ; SI becomes scratch for the candidate
                                       ; string and sh_ci_copy_cs's own source
                                       ; pointer below (the same bug .format
                                       ; just above had)
    mov si, sh_ci_empty                ; General: the empty text - LOCAL, so
                                       ; every candidate SI below is CS-
                                       ; relative and sh_ci_copy_cs (not
                                       ; sh_snull, resident/DS-relative) is
                                       ; right for all four
    cmp al, SH_FMT_ALIGN_LEFT << SH_FMT_ALIGN_SHIFT
    jne .notleft
    mov si, sh_ci_pfx_left
    jmp .havepfx
.notleft:
    cmp al, SH_FMT_ALIGN_CENTER << SH_FMT_ALIGN_SHIFT
    jne .notcenter
    mov si, sh_ci_pfx_center
    jmp .havepfx
.notcenter:
    cmp al, SH_FMT_ALIGN_RIGHT << SH_FMT_ALIGN_SHIFT
    jne .havepfx
    mov si, sh_ci_pfx_right
.havepfx:
    mov di, sh_sacc
    call sh_ci_copy_cs
    pop si                              ; the formula position, back
    mov byte [sh_curtype], SH_T_TEXT
    jmp .out
.type:
    mov ax, [sh_ci_col]
    mov bx, [sh_ci_row]
    SHOUT sh_getcell2
    mov al, [sh_curtype]
    mov di, sh_sacc
    cmp al, SH_T_BLANK
    jne .typenotblank
    mov byte [di], 'b'
    jmp .typedone
.typenotblank:
    cmp al, SH_T_TEXT
    jne .typeisvalue
    mov byte [di], 'l'
    jmp .typedone
.typeisvalue:
    mov byte [di], 'v'
.typedone:
    mov byte [di+1], 0
    mov byte [sh_curtype], SH_T_TEXT
    jmp .out
.badargs:
    SHOUT sh_skipargs
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; sh_ci_appendstr - copy the NUL-terminated string at SI to DI (not
; including the NUL), leaving DI just past what it wrote - "append", not
; "copy", for CELL("address")'s three-piece build above.
sh_ci_appendstr:
    push ax
.l:
    mov al, [si]
    or al, al
    jz .done
    mov [di], al
    inc si
    inc di
    jmp .l
.done:
    pop ax
    ret

; sh_ci_copy_cs - CS:SI -> DS:DI, including the NUL. SI is a CS-RELATIVE
; offset into this MODULE's own data (a sh_ci_fmtcodes/sh_ci_pfx_* string) -
; plain [si] defaults to DS, the PACKAGE's segment, which is a different one
; (82.16's whole point: the module moves CS, the package keeps DS). This and
; sh_ci_namecmp below share the bug this fixed, the first time either was
; tried: every CELL(...) call answered #VALUE! - the comma/close-paren
; checks downstream of the match were reading whatever DS:[the module's own
; CS-relative offset] happened to hold, essentially random bytes relative to
; what was meant. Verified against the built file directly (`python3 -c
; "open('build/CHART.OVL','rb').read()[...]"`) before this fix, which is how
; the guess was ruled OUT rather than in - the table itself, and every
; string in it, was byte-perfect; only the READ of it was wrong
sh_ci_copy_cs:
    push ax
.l:
    mov al, [cs:si]
    mov [di], al
    or al, al
    jz .done
    inc si
    inc di
    jmp .l
.done:
    pop ax
    ret

; sh_ci_namecmp - in: DI = a CS-RELATIVE offset (a sh_ci_names entry), SI =
; DS-relative (sh_sacc, the argument text). out: AX = 0 if they match
; case-insensitively, matching sh_dblkstrcmp's own contract - which this
; cannot just call, for sh_ci_copy_cs's own reason: DI needs [cs:], SI does
; not, and sh_dblkstrcmp reads both the same way.
sh_ci_namecmp:
    push bx
    push si
    push di
.c:
    mov al, [si]
    mov bl, [cs:di]
    call sh_dblkup
    xchg al, bl
    call sh_dblkup
    xchg al, bl
    cmp al, bl
    jne .diff
    or al, al
    jz .eq
    inc si
    inc di
    jmp short .c
.eq:
    xor ax, ax
    jmp short .out
.diff:
    mov ax, 1
.out:
    pop di
    pop si
    pop bx
    ret

; =============================================================================
; THE ARRAY/MATRIX FUNCTIONS (81.67): MDETERM MINVERSE MMULT TRANSPOSE
; LINEST LOGEST TREND GROWTH. Sheet has no array-formula (Ctrl+Shift+Enter,
; multi-cell) entry at all - building one is §81.39.4's own "array formulas"
; enabler, a feature in its own right and not a prerequisite these eight
; functions have to wait on. Instead every one of them computes its REAL,
; FULL result and publishes only the array's own TOP-LEFT element as an
; ordinary value - which is exactly what Excel itself answers for any of
; these when the formula is entered as a plain cell (no CSE): TRANSPOSE
; becomes a same-cell echo, MMULT one dot product, MDETERM/MINVERSE still
; the whole determinant/inverse (there is no way to answer element (1,1) of
; an inverse without doing the whole elimination). Documented Excel
; behaviour, not an approximation of it.
;
; SH_MX_N caps every array argument at 8 rows/columns each way. sh_mx_buf
; is ONE shared elimination workspace, 8 rows by 16 (2*SH_MX_N) packed-
; double columns - wide enough for MINVERSE's augmented [A|I] and
; MDETERM's plain triangulation alike, never both at once (sh_mx_busy -
; refused, not guarded, sh_db_busy's own reason, §81.65).
;
; EVERY ROW/COLUMN LOOP INDEX BELOW IS NAMED SCRATCH (sh_mx_i/j/tr/sr), not
; a register - sh_mx_addr takes its row and column in AX/BX and returns
; through them being clobbered, so a register holding "which row am I on"
; across a call to it does not survive the call. This is not a style
; choice: an earlier draft kept i/j in registers and got the wrong element
; back once past the first row, silently, because sh_mx_addr's own output
; landed on top of the loop's own counter.
; =============================================================================
SH_MX_N equ 8
SH_MX_W equ (SH_MX_N * 2)
SH_MX_REGN equ 200                    ; the regression family's own point
                                       ; cap - LINEST/LOGEST/TREND/GROWTH are
                                       ; O(n) per point, not MDETERM's O(n^3),
                                       ; so this is a guard against a whole
                                       ; column reference rather than SH_MX_N's
                                       ; kind of limit

; sh_mx_addr - in: AX=row (0-based), BX=col (0-based). out: DI = the
; address of sh_mx_buf[row][col]. Clobbers AX, BX.
sh_mx_addr:
    push dx
    mov dx, ax
    mov ax, SH_MX_W
    mul dx
    add ax, bx
    shl ax, 1
    shl ax, 1
    shl ax, 1                          ; * 8, a packed double's width
    add ax, sh_mx_buf
    mov di, ax
    pop dx
    ret

; sh_mx_swaprows - in: AX=row1, BX=row2, CX=width (columns). Byte-swaps two
; whole rows of sh_mx_buf - no floating point involved, so no fp register
; is disturbed by a pivot swap mid-elimination.
sh_mx_swaprows:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov dx, cx                         ; width, banked
    push bx                            ; row2, banked - ax(row1) stays live
    xor bx, bx
    call sh_mx_addr                    ; di = &buf[row1][0]
    mov si, di
    pop ax                             ; ax = row2
    xor bx, bx
    call sh_mx_addr                    ; di = &buf[row2][0]
    mov cx, dx
    shl cx, 1
    shl cx, 1
    shl cx, 1                          ; cx = width * 8 bytes
.loop:
    jcxz .done
    mov al, [si]
    mov ah, [di]
    mov [si], ah
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .loop
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_mx_rowsub - in: sh_mx_tr = target row, sh_mx_sr = source row, CX =
; width (columns), sh_mx_sumy = the factor (a packed double, stashed there
; by the caller - not simultaneously used by anything else while an
; elimination is in progress). buf[tr][k] -= factor * buf[sr][k].
sh_mx_rowsub:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov dx, cx
    xor cx, cx
.loop:
    cmp cx, dx
    jae .done
    mov ax, [sh_mx_sr]
    mov bx, cx
    call sh_mx_addr                    ; di = &source[cx]
    mov si, di
    SHOUT fp_unpack_a                  ; A = source[cx]
    push si
    mov si, sh_mx_sumy
    SHOUT fp_unpack_b                  ; B = the factor
    pop si
    SHOUT fp_mul                       ; A = factor * source[cx]
    SHOUT fp_a_to_b                    ; B = that product
    mov ax, [sh_mx_tr]
    mov bx, cx
    call sh_mx_addr                    ; di = &target[cx]
    mov si, di
    SHOUT fp_unpack_a                  ; A = target[cx]
    SHOUT fp_sub                       ; A = target[cx] - factor*source[cx]
    push di
    SHOUT fp_pack_a
    pop di
    inc cx
    jmp .loop
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_mx_loadbuf - in: AX=N (square size), DX=destination column offset;
; sh_mx_r1/c1 = the source array's near corner. Loads
; buf[i][offset+j] = array[r1+i][c1+j] for i,j in 0..N-1, requiring every
; cell numeric. out: CF=1 all N*N cells loaded; CF=0 the first non-numeric
; one stopped it (the caller raises #VALUE! and abandons the call either
; way, so what is left loaded past that point does not matter).
sh_mx_loadbuf:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov [sh_mx_n], ax
    mov [sh_mx_tr], dx                 ; the column offset (sh_mx_tr/sr are
                                       ; not yet in use as row indices -
                                       ; elimination has not started)
    mov word [sh_mx_i], 0
.rloop:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .ok
    mov word [sh_mx_j], 0
.cloop:
    mov ax, [sh_mx_j]
    cmp ax, [sh_mx_n]
    jae .rnext
    mov ax, [sh_mx_c1]
    add ax, [sh_mx_j]
    mov bx, [sh_mx_r1]
    add bx, [sh_mx_i]
    SHOUT sh_getcell2
    cmp byte [sh_curtype], SH_T_NUM
    jne .bad
    mov ax, [sh_mx_i]
    mov bx, [sh_mx_tr]
    add bx, [sh_mx_j]
    call sh_mx_addr
    push si
    mov si, sh_acc
    SHOUT fp_unpack_a
    pop si
    push di
    SHOUT fp_pack_a
    pop di
    inc word [sh_mx_j]
    jmp .cloop
.rnext:
    inc word [sh_mx_i]
    jmp .rloop
.ok:
    stc
    jmp .out
.bad:
    clc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_mx_identity - in: AX=N, DX=column offset. Writes buf[i][offset+j] = 1
; if i==j else 0, for i,j in 0..N-1 - MINVERSE's own right half of [A|I].
sh_mx_identity:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov [sh_mx_n], ax
    mov [sh_mx_tr], dx
    mov word [sh_mx_i], 0
.iloop:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .idone
    mov word [sh_mx_j], 0
.jloop:
    mov ax, [sh_mx_j]
    cmp ax, [sh_mx_n]
    jae .inext
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_j]
    jne .izero
    mov ax, 1
    SHOUT fp_i2a
    jmp .ihave
.izero:
    xor ax, ax
    SHOUT fp_i2a
.ihave:
    mov ax, [sh_mx_i]
    mov bx, [sh_mx_tr]
    add bx, [sh_mx_j]
    call sh_mx_addr
    push di
    SHOUT fp_pack_a
    pop di
    inc word [sh_mx_j]
    jmp .jloop
.inext:
    inc word [sh_mx_i]
    jmp .iloop
.idone:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_mx_veckth - the k-th element of a VECTOR argument (a single row or a
; single column - LINEST/TREND's shape, not MDETERM's square). in: AX = k
; (0-based), SI -> a rect's four words r1,c1,r2,c2 (sh_mx_r1.. or
; sh_mx_r1b.. are laid out exactly that way in the equ chain, so either can
; be passed as-is). out: AX = col, BX = row - sh_getcell2's own inputs.
; Whichever of the rect's two dimensions is NOT 1 is the one k walks; the
; caller has already rejected a rect where neither is (sh_mx_regsums).
sh_mx_veckth:
    push dx
    mov dx, ax                         ; dx = k
    mov ax, [si]                       ; r1
    mov bx, [si+4]                     ; r2
    cmp ax, bx
    jne .col
    mov bx, ax                         ; single row: row stays r1...
    mov ax, [si+2]                     ; ...col = c1 + k
    add ax, dx
    jmp .out
.col:
    mov bx, ax                         ; single column: col stays c1...
    add bx, dx                         ; ...row = r1 + k
    mov ax, [si+2]
.out:
    pop dx
    ret

; sh_mx_regsums - the least-squares sums LINEST/LOGEST/TREND/GROWTH are all
; built from, one pass over the known points (81.34's variance folds are the
; precedent for "one pass, running sums" over sh_stbusy's own kind of
; reentrancy guard).
;
; in: sh_mx_r1/c1/r2/c2 = known_y's, already checked by the caller to be a
;     cell reference (sh_mx_getvec's caller does that via sh_pargref);
;     sh_mx_haveknownx = 1 and sh_mx_r1b/c1b/r2b/c2b = known_x's, or 0 to use
;     the default sequence 1,2,3,...; sh_mx_logy = 1 to fit ln(y) rather than
;     y (LOGEST/GROWTH)
; out: CF=1 with sh_mx_n/sumx/sumy/sumxy/sumx2 filled; CF=0 - known_y's or
;     known_x's is not a single row/column, their lengths disagree, a cell in
;     either is not numeric, or (sh_mx_logy) a y is not strictly positive.
sh_mx_regsums:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov ax, [sh_mx_r2]
    sub ax, [sh_mx_r1]
    inc ax                             ; ax = known_y's row count
    mov bx, [sh_mx_c2]
    sub bx, [sh_mx_c1]
    inc bx                             ; bx = known_y's column count
    cmp ax, 1
    jne .yrows
    mov cx, bx                         ; a single row: n = the column count
    jmp .ygot
.yrows:
    cmp bx, 1
    jne .bad                           ; neither dimension is 1 - not a
                                       ; vector; multiple regression is out
                                       ; of scope (SPEC.md 81.67)
    mov cx, ax                         ; a single column: n = the row count
.ygot:
    mov [sh_mx_n], cx
    cmp byte [sh_mx_haveknownx], 0
    je .havelen
    mov ax, [sh_mx_r2b]
    sub ax, [sh_mx_r1b]
    inc ax
    mov bx, [sh_mx_c2b]
    sub bx, [sh_mx_c1b]
    inc bx
    cmp ax, 1
    jne .xrows
    mov dx, bx
    jmp .xgot
.xrows:
    cmp bx, 1
    jne .bad
    mov dx, ax
.xgot:
    cmp dx, [sh_mx_n]
    jne .bad                          ; known_x's must be the same length
.havelen:
    cmp word [sh_mx_n], 1
    jb .bad
    cmp word [sh_mx_n], SH_MX_REGN
    ja .bad
    xor ax, ax
    mov [sh_mx_sumx], ax
    mov [sh_mx_sumx+2], ax
    mov [sh_mx_sumx+4], ax
    mov [sh_mx_sumx+6], ax
    mov [sh_mx_sumy], ax
    mov [sh_mx_sumy+2], ax
    mov [sh_mx_sumy+4], ax
    mov [sh_mx_sumy+6], ax
    mov [sh_mx_sumxy], ax
    mov [sh_mx_sumxy+2], ax
    mov [sh_mx_sumxy+4], ax
    mov [sh_mx_sumxy+6], ax
    mov [sh_mx_sumx2], ax
    mov [sh_mx_sumx2+2], ax
    mov [sh_mx_sumx2+4], ax
    mov [sh_mx_sumx2+6], ax
    mov word [sh_mx_i], 0
.sumloop:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .sumdone
    mov ax, [sh_mx_i]
    mov si, sh_mx_r1
    call sh_mx_veckth                  ; ax=col, bx=row of y[k]
    SHOUT sh_getcell2
    cmp byte [sh_curtype], SH_T_NUM
    jne .bad
    mov si, sh_acc
    SHOUT fp_unpack_a                  ; A = y[k]
    cmp byte [sh_mx_logy], 0
    je .havey
    SHOUT fp_ln                        ; A = ln(y[k]); CF=1 if y[k] <= 0 -
    jc .bad                            ; LOGEST/GROWTH need every y positive
.havey:
    push di
    mov di, sh_mx_t2
    SHOUT fp_pack_a                    ; t2 = the (possibly transformed) y[k]
    pop di
    cmp byte [sh_mx_haveknownx], 0
    je .defaultx
    mov ax, [sh_mx_i]
    mov si, sh_mx_r1b
    call sh_mx_veckth                  ; ax=col, bx=row of x[k]
    SHOUT sh_getcell2
    cmp byte [sh_curtype], SH_T_NUM
    jne .bad
    mov si, sh_acc
    SHOUT fp_unpack_a                  ; A = x[k]
    jmp .havex
.defaultx:
    mov ax, [sh_mx_i]
    inc ax                             ; 1-based: 1,2,3,...
    SHOUT fp_i2a
.havex:
    push di
    mov di, sh_mx_t1
    SHOUT fp_pack_a                    ; t1 = x[k]
    pop di
    mov si, sh_mx_t1
    SHOUT fp_unpack_b                  ; Sx += x[k]
    mov si, sh_mx_sumx
    SHOUT fp_unpack_a
    SHOUT fp_add
    push di
    mov di, sh_mx_sumx
    SHOUT fp_pack_a
    pop di
    mov si, sh_mx_t2
    SHOUT fp_unpack_b                  ; Sy += y[k]
    mov si, sh_mx_sumy
    SHOUT fp_unpack_a
    SHOUT fp_add
    push di
    mov di, sh_mx_sumy
    SHOUT fp_pack_a
    pop di
    mov si, sh_mx_t1
    SHOUT fp_unpack_a                  ; Sxy += x[k]*y[k]
    mov si, sh_mx_t2
    SHOUT fp_unpack_b
    SHOUT fp_mul
    SHOUT fp_a_to_b
    mov si, sh_mx_sumxy
    SHOUT fp_unpack_a
    SHOUT fp_add
    push di
    mov di, sh_mx_sumxy
    SHOUT fp_pack_a
    pop di
    mov si, sh_mx_t1
    SHOUT fp_unpack_a                  ; Sxx += x[k]*x[k]
    mov si, sh_mx_t1
    SHOUT fp_unpack_b
    SHOUT fp_mul
    SHOUT fp_a_to_b
    mov si, sh_mx_sumx2
    SHOUT fp_unpack_a
    SHOUT fp_add
    push di
    mov di, sh_mx_sumx2
    SHOUT fp_pack_a
    pop di
    inc word [sh_mx_i]
    jmp .sumloop
.sumdone:
    stc
    jmp .out
.bad:
    clc
.out:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_mx_fitline - solves the least-squares line from sh_mx_regsums's sums.
; in: sh_mx_n/sumx/sumy/sumxy/sumx2; sh_mx_const = 0 to force the line
;     through the origin (intercept 0), nonzero for the ordinary fit.
; out: CF=1 with sh_mx_slope/sh_mx_intercept filled; CF=0 the fit is
;     degenerate (a zero denominator - every known_x equal, or, forced
;     through the origin, every known_x zero) and the caller answers #NUM!,
;     MINVERSE's own singular-matrix precedent (81.67).
sh_mx_fitline:
    push ax
    push bx
    push si
    push di
    cmp byte [sh_mx_const], 0
    je .origin
    mov ax, [sh_mx_n]
    SHOUT fp_i2a                       ; A = n
    push di
    mov di, sh_mx_t1
    SHOUT fp_pack_a                    ; t1 = n, needed again below
    pop di
    mov si, sh_mx_t1
    SHOUT fp_unpack_a
    mov si, sh_mx_sumx2
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; A = n*Sxx
    push di
    mov di, sh_mx_t2
    SHOUT fp_pack_a                    ; t2 = n*Sxx
    pop di
    mov si, sh_mx_sumx
    SHOUT fp_unpack_a
    mov si, sh_mx_sumx
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; A = Sx*Sx
    SHOUT fp_a_to_b
    mov si, sh_mx_t2
    SHOUT fp_unpack_a                  ; A = n*Sxx - Sx*Sx = denom
    SHOUT fp_sub
    push di
    mov di, sh_mx_denom
    SHOUT fp_pack_a
    pop di
    mov bx, sh_mx_denom
    SHOUT fp_iszero
    jnc .havedenom
    jmp .bad
.havedenom:
    mov si, sh_mx_t1                   ; t1 still holds n
    SHOUT fp_unpack_a
    mov si, sh_mx_sumxy
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; A = n*Sxy
    push di
    mov di, sh_mx_t2
    SHOUT fp_pack_a                    ; t2 = n*Sxy
    pop di
    mov si, sh_mx_sumx
    SHOUT fp_unpack_a
    mov si, sh_mx_sumy
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; A = Sx*Sy
    SHOUT fp_a_to_b
    mov si, sh_mx_t2
    SHOUT fp_unpack_a                  ; A = n*Sxy - Sx*Sy
    SHOUT fp_sub
    mov si, sh_mx_denom
    SHOUT fp_unpack_b
    SHOUT fp_div                       ; A = slope
    push di
    mov di, sh_mx_slope
    SHOUT fp_pack_a
    pop di
    mov si, sh_mx_slope
    SHOUT fp_unpack_a
    mov si, sh_mx_sumx
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; A = slope*Sx
    SHOUT fp_a_to_b
    mov si, sh_mx_sumy
    SHOUT fp_unpack_a                  ; A = Sy - slope*Sx
    SHOUT fp_sub
    mov si, sh_mx_t1                   ; t1 still holds n
    SHOUT fp_unpack_b
    SHOUT fp_div                       ; A = intercept
    push di
    mov di, sh_mx_intercept
    SHOUT fp_pack_a
    pop di
    stc
    jmp .out
.origin:
    mov bx, sh_mx_sumx2
    SHOUT fp_iszero
    jc .bad
    mov si, sh_mx_sumxy
    SHOUT fp_unpack_a
    mov si, sh_mx_sumx2
    SHOUT fp_unpack_b
    SHOUT fp_div                       ; A = slope = Sxy / Sxx
    push di
    mov di, sh_mx_slope
    SHOUT fp_pack_a
    pop di
    SHOUT fp_azero
    push di
    mov di, sh_mx_intercept
    SHOUT fp_pack_a                    ; intercept = 0
    pop di
    stc
    jmp .out
.bad:
    clc
.out:
    pop di
    pop si
    pop bx
    pop ax
    ret

; in: AX = the id, SI just past '('. out: AX = the value in sh_acc, SI past
; ')'. BX CX DX DI kept, matching every other door's contract.
shm_pmatrix:
    push bx
    push cx
    push dx
    push di
    mov cx, ax                         ; CX = the id - DI stays free for
                                       ; sh_mx_addr's own output throughout
    cmp byte [sh_mx_busy], 0
    jne .refused
    mov byte [sh_mx_busy], 1
    cmp cx, SH_FID_TRANSPOSE
    je .dotranspose
    cmp cx, SH_FID_MMULT
    je .dommult
    cmp cx, SH_FID_MDETERM
    je .domdeterm
    cmp cx, SH_FID_MINVERSE
    je .dominverse
    cmp cx, SH_FID_LINEST
    je .dolinest
    cmp cx, SH_FID_LOGEST
    je .dologest
    cmp cx, SH_FID_TREND
    je .dotrend
    cmp cx, SH_FID_GROWTH
    je .dogrowth
    jmp .badargs                       ; unreachable - every id sh_pfunc
                                       ; routes here is one of the eight above
; --- TRANSPOSE(array) -------------------------------------------------------
.dotranspose:
    SHOUT sh_pargref
    jnc .badargs
    cmp byte [si], ')'
    jne .badargs
    inc si
    push si                            ; the FORMULA position, banked - see
                                       ; the header comment; sh_getcell2
                                       ; itself does not disturb SI, but
                                       ; every OTHER exit below does, and
                                       ; this is the one habit that is safe
                                       ; whichever branch is reached
    mov ax, [sh_arg1col]
    mov bx, [sh_arg1row]
    SHOUT sh_getcell2                  ; a transpose never moves the (1,1)
    pop si                             ; cell - whatever it holds, plain
    jmp .done_clean                    ; number or label, is the answer
; --- MMULT(array1, array2) ---------------------------------------------------
.dommult:
    SHOUT sh_pargref
    jnc .badargs
    mov ax, [sh_arg1col]
    mov [sh_mx_c1], ax
    mov ax, [sh_arg1row]
    mov [sh_mx_r1], ax
    mov ax, [sh_arg2col]
    sub ax, [sh_mx_c1]
    inc ax
    mov [sh_mx_cols], ax
    cmp byte [si], ','
    jne .badargs
    inc si
    SHOUT sh_pargref
    jnc .badargs
    mov ax, [sh_arg1col]
    mov [sh_mx_c1b], ax
    mov ax, [sh_arg1row]
    mov [sh_mx_r1b], ax
    mov ax, [sh_arg2row]
    sub ax, [sh_mx_r1b]
    inc ax
    mov [sh_mx_rows2], ax
    cmp byte [si], ')'
    jne .badargs
    inc si
    push si                            ; the FORMULA position, banked
    mov ax, [sh_mx_cols]
    cmp ax, [sh_mx_rows2]              ; the shared dimension must agree
    jne .mxbad
    cmp ax, SH_MX_N
    ja .mxbad
    mov word [sh_mx_sumx], 0           ; the running dot product
    mov word [sh_mx_sumx+2], 0
    mov word [sh_mx_sumx+4], 0
    mov word [sh_mx_sumx+6], 0
    mov word [sh_mx_i], 0
.mmloop:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_cols]
    jae .mmdone
    mov ax, [sh_mx_c1]                 ; A[r1][c1+i]
    add ax, [sh_mx_i]
    mov bx, [sh_mx_r1]
    SHOUT sh_getcell2
    cmp byte [sh_curtype], SH_T_NUM
    jne .mxbad
    mov ax, [sh_acc]
    mov [sh_mx_sumy], ax
    mov ax, [sh_acc+2]
    mov [sh_mx_sumy+2], ax
    mov ax, [sh_acc+4]
    mov [sh_mx_sumy+4], ax
    mov ax, [sh_acc+6]
    mov [sh_mx_sumy+6], ax
    mov ax, [sh_mx_c1b]                ; B[r1b+i][c1b]
    mov bx, [sh_mx_r1b]
    add bx, [sh_mx_i]
    SHOUT sh_getcell2
    cmp byte [sh_curtype], SH_T_NUM
    jne .mxbad
    push si
    mov si, sh_acc                     ; B = the just-read cell -
    SHOUT fp_unpack_b                  ; sh_acc_load_b is not among this
                                       ; module's vectors (81.66 hit the
                                       ; same gap); fp_unpack_b is
    mov si, sh_mx_sumy
    SHOUT fp_unpack_a
    pop si
    SHOUT fp_mul                       ; A = a*b
    SHOUT fp_a_to_b                    ; B = a*b
    push si
    mov si, sh_mx_sumx
    SHOUT fp_unpack_a                  ; A = running sum
    pop si
    SHOUT fp_add                       ; A = sum + a*b
    push di
    mov di, sh_mx_sumx
    SHOUT fp_pack_a
    pop di
    inc word [sh_mx_i]
    jmp .mmloop
.mmdone:
    push si
    mov si, sh_mx_sumx
    SHOUT fp_unpack_a
    pop si
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- MDETERM(array) -----------------------------------------------------------
.domdeterm:
    call sh_mx_getsquare
    jnc .badargs
    push si                            ; the FORMULA position, banked
    mov ax, [sh_mx_rows]
    cmp ax, [sh_mx_cols]
    jne .mxbad
    cmp ax, SH_MX_N
    ja .mxbad
    mov [sh_mx_n], ax
    xor dx, dx
    call sh_mx_loadbuf
    jnc .mxbad
    mov byte [sh_mx_const], 0          ; the sign, 0=+, 1=- (not
                                       ; simultaneously the `const`
                                       ; argument here - that is only the
                                       ; regression family's)
    mov word [sh_mx_j], 0
.detloop:
    mov ax, [sh_mx_j]
    cmp ax, [sh_mx_n]
    jae .detdone
    mov ax, [sh_mx_j]
    mov [sh_mx_i], ax
.findpivot:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .havepivot
    mov bx, [sh_mx_j]
    call sh_mx_addr
    mov bx, di
    SHOUT fp_iszero                    ; CF=1 the block at BX is all zero
    jnc .havepivot                     ; CF=0: nonzero, use this row
    inc word [sh_mx_i]
    jmp .findpivot
.havepivot:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .singular
    cmp ax, [sh_mx_j]
    je .noswap
    mov ax, [sh_mx_j]
    mov bx, [sh_mx_i]
    mov cx, [sh_mx_n]
    call sh_mx_swaprows
    xor byte [sh_mx_const], 1          ; a row swap flips the sign
.noswap:
    mov ax, [sh_mx_j]
    inc ax
    mov [sh_mx_i], ax
.elimloop:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .elimdone
    mov ax, [sh_mx_i]                  ; factor = buf[i][j] / buf[j][j]
    mov bx, [sh_mx_j]
    call sh_mx_addr
    mov si, di
    SHOUT fp_unpack_a
    mov ax, [sh_mx_j]
    mov bx, [sh_mx_j]
    call sh_mx_addr
    mov si, di
    SHOUT fp_unpack_b
    SHOUT fp_div
    push di
    mov di, sh_mx_sumy
    SHOUT fp_pack_a
    pop di
    mov ax, [sh_mx_i]
    mov [sh_mx_tr], ax
    mov ax, [sh_mx_j]
    mov [sh_mx_sr], ax
    mov cx, [sh_mx_n]
    call sh_mx_rowsub
    inc word [sh_mx_i]
    jmp .elimloop
.elimdone:
    inc word [sh_mx_j]
    jmp .detloop
.singular:
    xor ax, ax
    SHOUT sh_acc_int
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
.detdone:
    mov ax, 1
    SHOUT fp_i2a
    push di
    mov di, sh_mx_sumx                 ; the running product
    SHOUT fp_pack_a
    pop di
    mov word [sh_mx_j], 0
.prodloop:
    mov ax, [sh_mx_j]
    cmp ax, [sh_mx_n]
    jae .proddone
    mov bx, ax
    call sh_mx_addr
    mov si, di
    SHOUT fp_unpack_a
    push si
    mov si, sh_mx_sumx
    SHOUT fp_unpack_b
    pop si
    SHOUT fp_mul
    push di
    mov di, sh_mx_sumx
    SHOUT fp_pack_a
    pop di
    inc word [sh_mx_j]
    jmp .prodloop
.proddone:
    cmp byte [sh_mx_const], 0
    je .possign
    push si
    mov si, sh_mx_sumx
    SHOUT fp_unpack_b
    pop si
    SHOUT fp_azero                     ; A = 0
    SHOUT fp_sub                       ; A = 0 - product
    jmp .havesign
.possign:
    push si
    mov si, sh_mx_sumx
    SHOUT fp_unpack_a
    pop si
.havesign:
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- MINVERSE(array) -----------------------------------------------------------
.dominverse:
    call sh_mx_getsquare
    jnc .badargs
    push si                            ; the FORMULA position, banked
    mov ax, [sh_mx_rows]
    cmp ax, [sh_mx_cols]
    jne .mxbad
    cmp ax, SH_MX_N
    ja .mxbad
    mov [sh_mx_n], ax
    xor dx, dx
    call sh_mx_loadbuf                 ; A into buf[.][0..n-1]
    jnc .mxbad
    mov ax, [sh_mx_n]
    mov dx, [sh_mx_n]                  ; the identity into buf[.][n..2n-1]
    call sh_mx_identity
    mov word [sh_mx_j], 0
.gjloop:
    mov ax, [sh_mx_j]
    cmp ax, [sh_mx_n]
    jae .gjdone
    mov ax, [sh_mx_j]
    mov [sh_mx_i], ax
.gjfind:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .gjcheck
    mov bx, [sh_mx_j]
    call sh_mx_addr
    mov bx, di
    SHOUT fp_iszero
    jnc .gjcheck
    inc word [sh_mx_i]
    jmp .gjfind
.gjcheck:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .singular2
    cmp ax, [sh_mx_j]
    je .gjnoswap
    mov ax, [sh_mx_j]
    mov bx, [sh_mx_i]
    mov cx, [sh_mx_n]
    shl cx, 1                          ; the WHOLE augmented row
    call sh_mx_swaprows
.gjnoswap:
    mov ax, [sh_mx_j]                  ; normalize row j by its own pivot
    mov bx, [sh_mx_j]
    call sh_mx_addr
    mov si, di
    SHOUT fp_unpack_a
    push di
    mov di, sh_mx_sumy                 ; the divisor, stashed for the whole
    SHOUT fp_pack_a                    ; row
    pop di
    mov word [sh_mx_i], 0
.gjnormloop:
    mov ax, [sh_mx_n]
    shl ax, 1
    cmp word [sh_mx_i], ax
    jae .gjnormdone
    mov ax, [sh_mx_j]
    mov bx, [sh_mx_i]
    call sh_mx_addr
    mov si, di
    SHOUT fp_unpack_a
    push si
    mov si, sh_mx_sumy
    SHOUT fp_unpack_b
    pop si
    SHOUT fp_div
    push di
    SHOUT fp_pack_a
    pop di
    inc word [sh_mx_i]
    jmp .gjnormloop
.gjnormdone:
    mov word [sh_mx_i], 0              ; eliminate every OTHER row
.gjelimloop:
    mov ax, [sh_mx_i]
    cmp ax, [sh_mx_n]
    jae .gjelimdone
    cmp ax, [sh_mx_j]
    je .gjelimskip
    mov ax, [sh_mx_i]                  ; the factor is buf[i][j] itself -
    mov bx, [sh_mx_j]                  ; row j is already normalized to 1
    call sh_mx_addr                    ; there
    mov si, di
    SHOUT fp_unpack_a
    push di
    mov di, sh_mx_sumy
    SHOUT fp_pack_a
    pop di
    mov ax, [sh_mx_i]
    mov [sh_mx_tr], ax
    mov ax, [sh_mx_j]
    mov [sh_mx_sr], ax
    mov cx, [sh_mx_n]
    shl cx, 1
    call sh_mx_rowsub
.gjelimskip:
    inc word [sh_mx_i]
    jmp .gjelimloop
.gjelimdone:
    inc word [sh_mx_j]
    jmp .gjloop
.singular2:
    mov byte [sh_evalerr], SH_ERR_NUM  ; #NUM!, Excel's own answer for
    xor ax, ax                         ; MINVERSE on a singular matrix
    SHOUT sh_acc_int
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
.gjdone:
    xor ax, ax                         ; the inverse's (1,1) element is
    mov bx, [sh_mx_n]                  ; buf[0][n] - row 0 of the right
    call sh_mx_addr                    ; (identity-turned-inverse) half
    mov si, di
    SHOUT fp_unpack_a
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- LINEST(known_y's, [known_x's], [const], [stats]) -----------------------
; Simple (single-predictor) linear regression only - real LINEST's element
; (1,1) is always the slope of the LAST x-variable, and with one x-variable
; that is the whole answer a non-CSE entry could ever show anyway (81.67).
.dolinest:
    mov byte [sh_mx_logy], 0
    call .parse_yx
    jnc .badargs
    call .parse_const_stats
    jnc .badargs
    push si                            ; the FORMULA position, banked - see
                                       ; the header comment; sh_mx_regsums and
                                       ; sh_mx_fitline both reuse SI as their
                                       ; own fp-unpack pointer throughout
    call sh_mx_regsums
    jnc .mxbad
    call sh_mx_fitline
    jnc .degenerate2
    mov si, sh_mx_slope
    SHOUT fp_unpack_a
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- LOGEST(known_y's, [known_x's], [const], [stats]) -----------------------
; Fits ln(y) = ln(b) + x*ln(m) by the same sums on ln(y); element (1,1) is m,
; not ln(m) - LOGEST publishes the growth factor itself.
.dologest:
    mov byte [sh_mx_logy], 1
    call .parse_yx
    jnc .badargs
    call .parse_const_stats
    jnc .badargs
    push si
    call sh_mx_regsums
    jnc .mxbad
    call sh_mx_fitline
    jnc .degenerate2
    mov si, sh_mx_slope
    SHOUT fp_unpack_a                  ; A = ln(m)
    SHOUT fp_exp                       ; A = m
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- TREND(known_y's, [known_x's], [new_x's], [const]) ----------------------
; Fits the line, then evaluates it at new_x's[0][0] - or, if new_x's is
; omitted, at known_x's[0] (Excel's own default: the fitted value at the
; first known point).
.dotrend:
    mov byte [sh_mx_logy], 0
    call .parse_yx
    jnc .badargs
    call .parse_newx_const
    jnc .badargs
    push si
    call sh_mx_regsums
    jnc .mxbad
    call sh_mx_fitline
    jnc .degenerate2
    call .evaltarget
    mov si, sh_mx_xtarget
    SHOUT fp_unpack_a
    mov si, sh_mx_slope
    SHOUT fp_unpack_b
    SHOUT fp_mul                       ; A = slope*x
    SHOUT fp_a_to_b
    mov si, sh_mx_intercept
    SHOUT fp_unpack_a
    SHOUT fp_add                       ; A = slope*x + intercept
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- GROWTH(known_y's, [known_x's], [new_x's], [const]) ---------------------
; TREND's exponential counterpart, off the SAME ln(y) fit LOGEST uses.
.dogrowth:
    mov byte [sh_mx_logy], 1
    call .parse_yx
    jnc .badargs
    call .parse_newx_const
    jnc .badargs
    push si
    call sh_mx_regsums
    jnc .mxbad
    call sh_mx_fitline
    jnc .degenerate2
    call .evaltarget
    mov si, sh_mx_xtarget
    SHOUT fp_unpack_a
    mov si, sh_mx_slope
    SHOUT fp_unpack_b
    SHOUT fp_mul
    SHOUT fp_a_to_b
    mov si, sh_mx_intercept
    SHOUT fp_unpack_a
    SHOUT fp_add                       ; A = ln(y_pred)
    SHOUT fp_exp                       ; A = y_pred
    SHOUT sh_acc_store
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
; --- shared argument-parsing pieces, called from all four above -------------
; .parse_yx - known_y's (required) and known_x's (optional), the identical
; prefix every one of the four takes. out: CF=1 parsed, sh_mx_r1/c1/r2/c2 =
; known_y's, sh_mx_haveknownx/const/havenewx defaulted (1's own trailing args
; override const/havenewx further); CF=0 a parse error, SI wherever
; sh_pargref left it (this call's own .badargs handles that the same way
; sh_pargref's failures always are here).
.parse_yx:
    SHOUT sh_pargref
    jnc .py_fail
    mov ax, [sh_arg1col]
    mov [sh_mx_c1], ax
    mov ax, [sh_arg1row]
    mov [sh_mx_r1], ax
    mov ax, [sh_arg2col]
    mov [sh_mx_c2], ax
    mov ax, [sh_arg2row]
    mov [sh_mx_r2], ax
    mov byte [sh_mx_haveknownx], 0
    mov byte [sh_mx_havenewx], 0
    mov byte [sh_mx_const], 1
    cmp byte [si], ','
    jne .py_ok
    inc si
    SHOUT sh_pargref
    jnc .py_fail
    mov ax, [sh_arg1col]
    mov [sh_mx_c1b], ax
    mov ax, [sh_arg1row]
    mov [sh_mx_r1b], ax
    mov ax, [sh_arg2col]
    mov [sh_mx_c2b], ax
    mov ax, [sh_arg2row]
    mov [sh_mx_r2b], ax
    mov byte [sh_mx_haveknownx], 1
.py_ok:
    stc
    ret
.py_fail:
    clc
    ret
; .parse_const_stats - LINEST/LOGEST's trailing [const], [stats]. `stats` is
; parsed and discarded - it never changes element (1,1), the only element a
; non-CSE entry can ever answer (81.67's own top-left-element design).
.parse_const_stats:
    cmp byte [si], ','
    jne .pcs_close
    inc si
    call sh_pargclass
    mov bx, sh_acc
    SHOUT fp_iszero
    jc .pcs_false
    mov byte [sh_mx_const], 1
    jmp .pcs_stats
.pcs_false:
    mov byte [sh_mx_const], 0
.pcs_stats:
    cmp byte [si], ','
    jne .pcs_close
    inc si
    call sh_pargclass                  ; `stats` - discarded
.pcs_close:
    cmp byte [si], ')'
    jne .pcs_fail
    inc si
    stc
    ret
.pcs_fail:
    clc
    ret
; .parse_newx_const - TREND/GROWTH's trailing [new_x's], [const]. new_x's is
; parsed via sh_pargclass rather than sh_pargref - it can be a bare number as
; freely as a reference, and sh_pargclass already answers a reference with
; its top-left value, exactly the element this whole engine ever needs.
.parse_newx_const:
    cmp byte [si], ','
    jne .pnc_close
    inc si
    call sh_pargclass
    push si                           ; the FORMULA position, banked before
                                       ; the unpack below reuses SI
    mov si, sh_acc
    SHOUT fp_unpack_a
    pop si
    push di
    mov di, sh_mx_xtarget
    SHOUT fp_pack_a
    pop di
    mov byte [sh_mx_havenewx], 1
    cmp byte [si], ','
    jne .pnc_close
    inc si
    call sh_pargclass
    mov bx, sh_acc
    SHOUT fp_iszero
    jc .pnc_false
    mov byte [sh_mx_const], 1
    jmp .pnc_close
.pnc_false:
    mov byte [sh_mx_const], 0
.pnc_close:
    cmp byte [si], ')'
    jne .pnc_fail
    inc si
    stc
    ret
.pnc_fail:
    clc
    ret
; .evaltarget - TREND/GROWTH's x to evaluate at, when new_x's was omitted:
; known_x's[0] if that was given, else the default sequence's own first
; value, 1 - never disturbs SI, so the caller's own banked formula position
; needs no extra care around this call.
.evaltarget:
    cmp byte [sh_mx_havenewx], 0
    jne .evaldone
    cmp byte [sh_mx_haveknownx], 0
    je .evaldefault
    push si
    xor ax, ax
    mov si, sh_mx_r1b
    call sh_mx_veckth                  ; ax=col, bx=row of known_x's[0]
    SHOUT sh_getcell2
    mov si, sh_acc
    SHOUT fp_unpack_a
    pop si
    push di
    mov di, sh_mx_xtarget
    SHOUT fp_pack_a
    pop di
    jmp .evaldone
.evaldefault:
    mov ax, 1
    SHOUT fp_i2a
    push di
    mov di, sh_mx_xtarget
    SHOUT fp_pack_a
    pop di
.evaldone:
    ret
.degenerate2:                         ; sh_mx_fitline's own denominator-zero
                                       ; case - MINVERSE's #NUM! precedent
                                       ; (.singular2), not #VALUE!: the shape
                                       ; was fine, the arithmetic is not
    mov byte [sh_evalerr], SH_ERR_NUM
    xor ax, ax
    SHOUT sh_acc_int
    pop si
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
.mxbad:
    pop si                             ; the banked formula position, back -
                                       ; NOT sh_skipargs: parsing is already
                                       ; COMPLETE at every .mxbad site (a
                                       ; dimension mismatch or a non-numeric
                                       ; cell, found after the closing ')'
                                       ; was already consumed), so SI is
                                       ; already exactly where the caller
                                       ; needs it - skipping "ahead" from
                                       ; there would scan into whatever
                                       ; follows this call in the formula
                                       ; and answer #VALUE! for the wrong
                                       ; reason, or worse
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean
.badargs:
    SHOUT sh_skipargs
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .done_clean                    ; THIS call set sh_mx_busy, so it
                                       ; clears it - a bad argument list left
                                       ; every array function refused after it
.refused:
    SHOUT sh_skipargs
    mov byte [sh_evalerr], SH_ERR_VALUE
    xor ax, ax
    SHOUT sh_acc_int
    mov byte [sh_curtype], SH_T_NUM
    jmp .out                           ; the OUTER call owns the flag
.done_clean:
    mov byte [sh_mx_busy], 0
.out:
    pop di
    pop dx
    pop cx
    pop bx
    ret

; sh_mx_getsquare - parses ONE array argument (MDETERM/MINVERSE's shape)
; via sh_pargref, checks the closing ')', and fills sh_mx_c1/r1/cols/rows -
; the common prefix both share, factored out because their own bodies are
; already long. out: CF=1 parsed cleanly (SI past ')'); CF=0 a parse error
; (SI wherever sh_pargref left it - the caller's own .badargs handles this
; the same way sh_pargref's own failures always are here).
sh_mx_getsquare:
    push ax
    SHOUT sh_pargref
    jnc .out
    mov ax, [sh_arg1col]
    mov [sh_mx_c1], ax
    mov ax, [sh_arg1row]
    mov [sh_mx_r1], ax
    mov ax, [sh_arg2col]
    sub ax, [sh_mx_c1]
    inc ax
    mov [sh_mx_cols], ax
    mov ax, [sh_arg2row]
    sub ax, [sh_mx_r1]
    inc ax
    mov [sh_mx_rows], ax
    cmp byte [si], ')'
    jne .fail
    inc si
    stc
    jmp .out
.fail:
    clc
.out:
    pop ax
    ret

section .text

; sh_funcid - in: sh_ident; out: AL = the function's id, or 0xFF unknown.
; TABLE-DRIVEN as of stage 3.0d: the id IS the entry's index in sh_functab, so
; adding a function is one string and one table word. It was an unrolled
; compare chain of five lines per function, which at ten functions was merely
; verbose and at twenty-five would have been a hundred lines of boilerplate
; with a hand-written id on each - exactly the shape that drifts.
sh_funcid:
    push bx
    push cx
    push si
    push di
    xor cx, cx
    mov bx, sh_functab
.loop:
    mov di, [bx]
    or di, di
    jz .unknown                       ; the table's 0 terminator
    mov si, sh_ident
    call sh_streq
    jc .found
    inc cx
    add bx, 2
    jmp .loop
.found:
    mov ax, cx
    jmp .out
.unknown:
    mov ax, 0xFF
.out:
    pop di
    pop si
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_chktext - the operand sh_curtype describes is TEXT, and something
; arithmetic is about to happen to it: raise #VALUE!. Excel's own answer, and
; the reason it is raised HERE rather than in sh_getcell2 is that a bare `=B4`
; must still SHOW the label, and SUM must still skip it - only an operator
; makes a label a mistake.
; -----------------------------------------------------------------------------
sh_chktext:
    cmp byte [sh_curtype], SH_T_TEXT
    jne .out
    mov byte [sh_evalerr], SH_ERR_VALUE
.out:
    ret

; -----------------------------------------------------------------------------
; sh_skipargs - SI is just past an unknown function's '('; leave it just past
; the matching ')'. Counting depth rather than scanning for the first ')' is
; what keeps `=FOO(SUM(A1:A2))` from leaving a stray parenthesis behind for
; the rest of the parse to trip over.
; -----------------------------------------------------------------------------
sh_skipargs:
    push cx
    mov cx, 1
.loop:
    mov al, [si]
    or al, al
    jz .out                           ; end of the formula: unbalanced, and
    inc si                            ; sh_paren_ok already refuses those at
    cmp al, '"'                       ; entry - this is belt and braces
    je .instr
    cmp al, '('
    jne .notopen
    inc cx
    jmp .loop
.notopen:
    cmp al, ')'
    jne .loop
    dec cx
    jnz .loop
.out:
    pop cx
    ret
.instr:                               ; A QUOTED STRING IS SKIPPED WHOLE, the
    mov al, [si]                      ; rule sh_paren_ok already kept: counted,
    or al, al                         ; the ')' in =FOO("a)")+1 closed FOO
    jz .out                           ; early and left "+1 as the tail. A
    inc si                            ; doubled quote closes and reopens, which
    cmp al, '"'                       ; comes out right (81.49)
    jne .instr
    jmp .loop

; -----------------------------------------------------------------------------
; sh_str_load - in: AX = an offset in sh_txtseg; copies that NUL string into
; sh_sacc, clipped to SH_STR_MAX. Every register preserved.
; -----------------------------------------------------------------------------
; -----------------------------------------------------------------------------
; sh_txtslot - in: ES:DI = a cell record whose type is SH_T_TEXT
; out: AX = the arena offset its characters live at.
;
; A plain LABEL keeps them in SH_C_FOFF. A FORMULA whose result is text keeps
; SH_C_FOFF for its own SOURCE and the result in SH_C_VAL (81.22.1), so
; reading FOFF for both loads the formula's own text - which is what the cell
; would draw on a pass-cache hit, with no evaluation to correct it.
;
; It is a proc rather than four inline instructions because the caller needs
; it inside a push/pop pair, and a label there is a chunk boundary stkbalance
; walks into without the push - which reads as an unbalanced path.
; -----------------------------------------------------------------------------
sh_txtslot:
    mov ax, [es:di+SH_C_FOFF]
    test byte [es:di+4], 1            ; HASFORMULA
    jz .out
    mov ax, [es:di+SH_C_VAL]
.out:
    ret

sh_str_load:
    push ax
    push cx
    push si
    push di
    push es
    mov es, [sh_txtseg]
    mov si, ax
    mov di, sh_sacc
    mov cx, SH_STR_MAX
.c:
    jcxz .term
    mov al, [es:si]
    or al, al
    jz .term
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .c
.term:
    mov byte [di], 0
    pop es
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_str_store - ES:DI = a cell record whose result is TEXT; put sh_sacc into
; that cell's result slot, claiming the slot on first use (81.22.1).
; out: CF=1 if the arena had no room, in which case the cell keeps whatever it
; had. Every register preserved.
; -----------------------------------------------------------------------------
sh_str_store:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT  ; VAL IS ONLY A SLOT OFFSET IF THE
    jne .newslot                      ; CELL ALREADY HELD TEXT. On a formula
    mov ax, [es:di+SH_C_VAL]          ; that returned a number last time it is
    or ax, ax                         ; the low word of a DOUBLE, and treating
    jnz .haveslot                     ; that as an arena offset writes 64 bytes
.newslot:                             ; wherever the mantissa happens to point
    mov ax, [sh_txtlen]               ; claim one: SH_STR_MAX+1, once, for the
    mov bx, ax                        ; life of the cell - the arena never
    add bx, SH_STR_MAX + 1            ; frees, so a slot PER RECALCULATION
    cmp bx, SH_TXT_CAP                ; would empty it in seconds
    ja .noroom
    mov [sh_txtlen], bx
    mov [es:di+SH_C_VAL], ax          ; the union's first word IS the offset
    mov word [es:di+SH_C_VAL+2], 0
    mov word [es:di+SH_C_VAL+4], 0
    mov word [es:di+SH_C_VAL+6], 0
.haveslot:
    mov di, ax                        ; DI = the slot, ES = the arena
    mov es, [sh_txtseg]
    mov si, sh_sacc
    mov cx, SH_STR_MAX
.c:
    jcxz .term
    mov al, [si]
    or al, al
    jz .term
    mov [es:di], al
    inc si
    inc di
    dec cx
    jmp .c
.term:
    mov byte [es:di], 0
    clc
    jmp .out
.noroom:
    stc
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_str_cat - append the NUL string at SI to sh_sacc, clipped to SH_STR_MAX.
; -----------------------------------------------------------------------------
sh_str_cat:
    push ax
    push cx
    push si
    push di
    mov di, sh_sacc
    mov cx, SH_STR_MAX
.find:
    cmp byte [di], 0
    je .app
    inc di
    dec cx
    jnz .find
.app:
    jcxz .term
    mov al, [si]
    or al, al
    jz .term
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .app
.term:
    mov byte [di], 0
    pop di
    pop si
    pop cx
    pop ax
    ret

; sh_streq - in: SI, DI (two NUL-terminated strings); out: CF=1 equal
sh_streq:
    push ax
    push si
    push di
.loop:
    mov al, [si]
    cmp al, [di]
    jne .neq
    or al, al
    jz .eq
    inc si
    inc di
    jmp .loop
.eq:
    stc
    jmp .out
.neq:
    clc
.out:
    pop di
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_clearcell - in: AX=col, BX=row
; -----------------------------------------------------------------------------
sh_clearcell:
    call sh_removecell
    ret

; =============================================================================
; String / number utilities
; =============================================================================

; sh_colname - bijective base-26 column letters (0-based index in AX)
; out: sh_colbuf = NUL-terminated letters (up to 2 for a 256-column grid)
sh_colname:
    ; STKBALANCE-LOOP: one digit pushed a turn and the second loop pops them; the count is in CX
    push ax
    push bx
    push cx
    push dx
    inc ax
    xor cx, cx
.divloop:
    or ax, ax
    jz .popall
    dec ax
    xor dx, dx
    mov bx, 26
    div bx
    push dx
    inc cx
    jmp .divloop
.popall:
    mov bx, sh_colbuf
.popone:
    or cx, cx
    jz .term
    pop dx
    add dl, 'A'
    mov [bx], dl
    inc bx
    dec cx
    jmp .popone
.term:
    mov byte [bx], 0
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_itoa - signed AX to a NUL-terminated decimal string in sh_numbuf -
; apps/os88dec.inc's dec_s16 (SPEC.md 20.5.2), which os88chart.inc includes
sh_itoa:
    push di
    mov di, sh_numbuf
    call dec_s16
    pop di
    ret

; -----------------------------------------------------------------------------
; sh_mkblank - rebuild sh_blank (every empty cell's display text) as exactly
; [sh_cellch] spaces + NUL. Called once at startup and again whenever
; Format > Column Width... changes the preset - sh_blank can't be a fixed
; string once the cell width is a runtime value.
; -----------------------------------------------------------------------------
sh_mkblank:
    push ax
    push cx
    push di
    mov cx, [sh_cellch]
    mov di, sh_blank
.fill:
    jcxz .term
    mov byte [di], ' '
    inc di
    loop .fill
.term:
    mov byte [di], 0
    pop di
    pop cx
    pop ax
    ret

; sh_rjust - right-justify sh_numbuf into a fixed SH_CELL_CH-wide sh_tbuf
sh_rjust:
    push ax
    push cx
    push si
    push di
    mov si, sh_numbuf
    xor cx, cx
.len:
    cmp byte [si], 0
    je .havelen
    inc si
    inc cx
    jmp .len
.havelen:
    mov di, sh_tbuf
    mov ax, [sh_cellch]
    sub ax, cx
    jbe .nopad
    push cx
    mov cx, ax
.pad:
    mov byte [di], ' '
    inc di
    loop .pad
    pop cx
.nopad:
    mov si, sh_numbuf
.copy:
    jcxz .term
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .copy
.term:
    mov byte [di], 0
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_ljust - left-justify sh_numbuf into a fixed SH_CELL_CH-wide sh_tbuf
; (padding trails, mirroring sh_rjust which pads first)
; -----------------------------------------------------------------------------
sh_ljust:
    push ax
    push cx
    push si
    push di
    mov si, sh_numbuf
    xor cx, cx
.len:
    cmp byte [si], 0
    je .havelen
    inc si
    inc cx
    jmp .len
.havelen:
    mov [sh_jlen], cx
    mov di, sh_tbuf
    mov si, sh_numbuf
.copy:
    jcxz .copydone
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .copy
.copydone:
    mov ax, [sh_cellch]
    sub ax, [sh_jlen]
    jbe .term
    mov cx, ax
.pad:
    mov byte [di], ' '
    inc di
    loop .pad
.term:
    mov byte [di], 0
    pop di
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_cjust - center-justify sh_numbuf into a fixed SH_CELL_CH-wide sh_tbuf
; (the odd leftover space, if any, goes on the right)
; -----------------------------------------------------------------------------
sh_cjust:
    push ax
    push bx
    push cx
    push si
    push di
    mov si, sh_numbuf
    xor cx, cx
.len:
    cmp byte [si], 0
    je .havelen
    inc si
    inc cx
    jmp .len
.havelen:
    mov [sh_jlen], cx
    mov di, sh_tbuf
    mov ax, [sh_cellch]
    sub ax, cx
    jle .nopad
    mov bx, ax                        ; bx = total pad
    shr ax, 1                         ; ax = left pad (floor)
    mov cx, ax
    jcxz .lpdone
.lp:
    mov byte [di], ' '
    inc di
    loop .lp
.lpdone:
    sub bx, ax                        ; bx = right pad = total - left
    mov si, sh_numbuf
    mov cx, [sh_jlen]
.cp:
    jcxz .cpdone
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .cp
.cpdone:
    mov cx, bx
    jcxz .term
.rp:
    mov byte [di], ' '
    inc di
    loop .rp
    jmp .term
.nopad:
    mov si, sh_numbuf
    mov cx, [sh_jlen]
.cp2:
    jcxz .term
    mov al, [si]
    mov [di], al
    inc si
    inc di
    dec cx
    jmp .cp2
.term:
    mov byte [di], 0
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_justify - in: BL=format byte; dispatches to sh_ljust/sh_cjust/sh_rjust
; by the alignment bits (General and explicit Right both right-justify,
; since this app's cells are only ever numeric - matching how real Excel's
; own "General" alignment right-justifies a number)
; -----------------------------------------------------------------------------
sh_justify:
    push ax
    push cx
    mov al, bl
    and al, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr al, cl
    cmp al, SH_FMT_ALIGN_LEFT
    je .left
    cmp al, SH_FMT_ALIGN_CENTER
    je .center
    jmp .right
.left:
    call sh_ljust
    jmp .out
.center:
    call sh_cjust
    jmp .out
.right:
    call sh_rjust
.out:
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_justify_c - sh_justify for a LOGICAL or an ERROR value: General centres
; both (81.51). An explicit alignment means what it means for anything else.
; in: BL = the format byte
; -----------------------------------------------------------------------------
sh_justify_c:
    push ax
    push cx
    mov al, bl
    and al, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr al, cl
    cmp al, SH_FMT_ALIGN_GENERAL
    jne .explicit
    call sh_cjust
    jmp short .out
.explicit:
    call sh_justify
.out:
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_justify_t - sh_justify for a LABEL rather than a number.
;
; The one difference, and it is Excel's: General aligns a number RIGHT and a
; label LEFT. An EXPLICIT alignment means the same thing for both, so this
; only intercepts General and hands everything else straight over.
; in: BL = the format byte
; -----------------------------------------------------------------------------
sh_justify_t:
    push ax
    push cx
    mov al, bl
    and al, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr al, cl
    cmp al, SH_FMT_ALIGN_GENERAL
    jne .explicit
    call sh_ljust
    jmp .out
.explicit:
    call sh_justify
.out:
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_strlen_es - in: ES:SI = a NUL string; out: AX = its length. SI preserved.
; sh_strlen's twin for the TEXT ARENA, which is never DS.
; -----------------------------------------------------------------------------
sh_strlen_es:
    push si
    xor ax, ax
.lp:
    cmp byte [es:si], 0
    je .done
    inc si
    inc ax
    jmp short .lp
.done:
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_lpad - HOW FAR A LABEL HANGS OFF THE LEFT of its own cell, in characters.
; in: AX = its length, CX = the column's width, BL = its alignment field.
; out: AX. Zero when it fits, and zero for General or left-aligned however
; long it is - those hang off to the RIGHT instead.
;
; ONE RULE, TWO CALLERS, which is the whole reason it is a routine: the
; label's OWN cell (sh_text_to_numbuf) and every empty cell beside it
; (sh_spill) must agree about where the string starts, or the two draw
; different windows of it and the row reads as gibberish. They did, for one
; build - a centred "Centred label!!" drew "Centred" in its own cell and the
; slice from character 11 in the next, and the glass read "CentCentredel!!".
; -----------------------------------------------------------------------------
sh_lpad:
    sub ax, cx
    jbe .none                         ; it fits: nothing hangs off either side
    cmp bl, SH_FMT_ALIGN_RIGHT
    je .out                           ; right-aligned: the whole excess
    cmp bl, SH_FMT_ALIGN_CENTER
    jne .none                         ; General or left: none of it
    shr ax, 1                         ; centred: half, the odd one to the right
.out:
    ret
.none:
    xor ax, ax
    ret

; -----------------------------------------------------------------------------
; sh_text_to_numbuf - copy the label at sh_curtoff-----------------------------
; sh_text_to_numbuf - copy the label at sh_curtoff (in sh_txtseg) into
; sh_numbuf, clipped to what the cell can show, so that the justifiers - which
; all read sh_numbuf and write sh_tbuf - need to know nothing about text.
;
; The label's OWN cell is clipped here; what runs on into the empty cells to
; its right, as Excel draws it, is theirs to draw (sh_spill, 81.54). That was
; thought to need a draw order - the neighbours' occupancy before this cell
; is drawn - and it does not: each cell draws only its own slice.
; -----------------------------------------------------------------------------
sh_text_to_numbuf:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    mov es, [sh_txtseg]
    mov si, [sh_curtoff]
    ; AN OVERFLOWING LABEL SHOWS THE WINDOW ITS ALIGNMENT PUTS OVER IT, and
    ; not simply its first n characters (81.76). For General and left-aligned
    ; - which was every label before 81.76 - those are the same thing, which
    ; is why this was not needed until one could hang off to the LEFT.
    mov bl, [sh_curfmt]
    and bl, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr bl, cl
    mov cx, [sh_cellch]
    call sh_strlen_es
    call sh_lpad
    add si, ax
    mov di, sh_numbuf
    mov cx, [sh_cellch]
    cmp cx, SH_NUMBUF_MAX             ; sh_numbuf is a fixed buffer and the
    jbe .cap                          ; cell width is a RUNTIME value now
    mov cx, SH_NUMBUF_MAX             ; (stage 3.0c's Column Width), so the
.cap:                                 ; clip is against both
    jcxz .term
.copy:
    mov al, [es:si]
    or al, al
    jz .term
    mov [di], al
    inc si
    inc di
    dec cx
    jnz .copy
.term:
    mov byte [di], 0
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_spill - does a LABEL beside this empty cell run on into it? (81.54, and
; 81.76 for the two directions)
; in: AX = col, BX = row, the cell known empty. out: CF=1 with sh_tbuf holding
; this cell's slice of it and [sh_curfmt] the format to draw it in; CF=0
; otherwise.
;
; Excel draws a label wider than its column across the EMPTY cells beside it
; and stops at the first that holds anything. WHICH WAY IT RUNS IS ITS
; ALIGNMENT: a General or left-aligned label hangs off to the RIGHT, a
; right-aligned one to the LEFT, and a CENTRED one both ways at once - that
; last is geometry rather than a guess, since centring a string wider than its
; box leaves half of the excess on each side.
;
; So there are two candidates and only two, whichever way it runs: the NEAREST
; record to the left in this row and the NEAREST to the right - anything
; further is stopped by one of them. Both are one step from the insertion
; point this cell's own sh_getcell2 has already found, the table being sorted
; by (row, col): the record BEFORE it and the record AT it. The left one is
; tried first, so a cell reached from both sides takes the left label, which
; is the order Excel's own left-to-right drawing settles it in.
;
; Each cell draws its own slice and nothing else, so no draw order and no
; ranged repaint can undo another cell's.
;
; THE SLICE IS JUSTIFIED TOWARD THE LABEL, and that one rule covers every
; case: a fully covered cell holds exactly its own width either way, so it
; fills edge to edge, and a partly covered one - the last cell the text
; reaches - hugs the side the text is coming from, which is where the
; characters actually are. It is why this needs no padding arithmetic of its
; own and why a centred label's two ends come out right without a third case.
; -----------------------------------------------------------------------------
sh_spill:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    cmp byte [sh_showformulas], 0     ; formulas on show: a cell shows its
    jne .no                           ; formula, and nothing runs on
    mov dx, ax                        ; DX = this column, kept throughout
    mov ax, [sh_cursheet]             ; the packed (sheet, row) every candidate
    mov cl, SH_ROW_BITS               ; record must match
    shl ax, cl
    or ax, bx
    mov [sh_sp_key], ax
    mov ax, dx
    call sh_findcell                  ; empty by the caller's contract, so DI
    jc .no                            ; is where the record WOULD go
    mov [sh_sp_ins], di
    ; --- the record BEFORE it: a label to our left, running RIGHT ----------
    or dx, dx
    jz .tryright                      ; column A has nothing to its left
    or di, di
    jz .tryright
    sub di, SH_C_SZ
    call sh_sp_islabel
    jc .tryright
    mov al, [sh_sp_align]
    cmp al, SH_FMT_ALIGN_GENERAL
    je .haveleft
    cmp al, SH_FMT_ALIGN_LEFT
    je .haveleft
    cmp al, SH_FMT_ALIGN_CENTER
    jne .tryright
.haveleft:
    mov byte [sh_sp_dir], 0           ; the text comes from the left
    jmp short .measure
    ; --- the record AT it: a label to our right, running LEFT --------------
.tryright:
    mov di, [sh_sp_ins]
    push dx
    mov dx, [sh_ncells]
    mov ax, SH_C_SZ
    mul dx
    cmp di, ax
    pop dx
    jae .no                           ; past the last record
    call sh_sp_islabel
    jc .no
    mov al, [sh_sp_align]
    cmp al, SH_FMT_ALIGN_RIGHT
    je .haveright
    cmp al, SH_FMT_ALIGN_CENTER
    jne .no
.haveright:
    mov byte [sh_sp_dir], 1           ; ...and from the right
.measure:
    ; --- how far the text hangs off its own cell, on the LEFT side --------
    ; leftpad: 0 left/General, the whole excess right-aligned, half centred.
    mov ax, [sh_sp_lcol]
    call sh_colwidth
    mov cx, ax                        ; CX = the label column's own width
    mov si, [sh_sp_toff]
    push es
    mov es, [sh_txtseg]
    call sh_strlen_es
    pop es
    mov [sh_sp_tlen], ax
    mov bl, [sh_sp_align]
    call sh_lpad                      ; THE SAME RULE the label's own cell uses
    or ax, ax
    jnz .havepad
    cmp bl, SH_FMT_ALIGN_RIGHT        ; a leftpad of zero is either "it fits",
    je .fail                          ; so nothing runs on at all, or a label
    cmp bl, SH_FMT_ALIGN_CENTER       ; hanging off to the RIGHT - and for
    je .fail                          ; those two it can only be the first
    mov ax, [sh_sp_tlen]
    cmp ax, cx
    jbe .fail                         ; General or left, and it fits
    xor ax, ax                        ; ...or it hangs right, with no leftpad
.havepad:
    mov [sh_sp_lpad], ax
    ; --- the character index this cell's LEFT edge falls on ----------------
    ; index = leftpad + (the character distance from the label's left edge),
    ; which is +sum(widths) going right and -sum(widths) going left.
    call sh_sp_dist                   ; -> AX = the distance, signed
    add ax, [sh_sp_lpad]
    mov [sh_sp_idx], ax
    ; --- intersect [idx, idx+width) with [0, tlen) -------------------------
    mov ax, dx
    call sh_colwidth
    mov cx, ax                        ; CX = this cell's width
    mov ax, [sh_sp_idx]
    add ax, cx                        ; AX = one past this cell's last index
    cmp ax, 0
    jle .fail                         ; the whole cell is left of the text
    mov bx, [sh_sp_tlen]
    cmp ax, bx
    jle .havehi
    mov ax, bx                        ; hi = min(idx+width, tlen)
.havehi:
    mov bx, [sh_sp_idx]
    or bx, bx
    jns .havelo
    xor bx, bx                        ; lo = max(idx, 0)
.havelo:
    cmp bx, ax
    jge .fail                         ; nothing of the text lands here
    sub ax, bx                        ; AX = how many characters
    mov cx, ax
    ; --- copy them out of the text arena -----------------------------------
    mov si, [sh_sp_toff]
    add si, bx
    mov es, [sh_txtseg]
    mov di, sh_numbuf
    cmp cx, SH_NUMBUF_MAX
    jbe .copy
    mov cx, SH_NUMBUF_MAX
.copy:
    mov al, [es:si]
    or al, al
    jz .end
    mov [di], al
    inc si
    inc di
    loop .copy
.end:
    mov byte [di], 0
    cmp byte [sh_sp_dir], 0           ; JUSTIFIED TOWARD THE LABEL - the whole
    jne .rj                           ; of the rule, and the reason a partly
    call sh_ljust                     ; covered cell needs no special case
    jmp short .fmt
.rj:
    call sh_rjust
.fmt:
    mov bl, [sh_sp_fmt]               ; bold and underline are the label's...
    and bl, SH_FMT_ALIGN_CLR          ; ...but the ALIGNMENT is this slice's,
    mov al, SH_FMT_ALIGN_LEFT         ; already applied by the justify above
    cmp byte [sh_sp_dir], 0
    je .fmtal
    mov al, SH_FMT_ALIGN_RIGHT
.fmtal:
    mov cl, SH_FMT_ALIGN_SHIFT
    shl al, cl
    or bl, al
    mov [sh_curfmt], bl
    stc
    jmp short .out
.fail:
    ; A CANDIDATE THAT IS A LABEL BUT DOES NOT REACH US IS NOT AN ANSWER, and
    ; treating it as one is what the first version of this did: in a row
    ; holding a short label on the left and a centred one on the right, the
    ; short one was accepted as the left candidate, measured, found too narrow
    ; to reach - and the search stopped there, so the centred label's left half
    ; was never drawn. The left candidate is a first GUESS, not a commitment.
    cmp byte [sh_sp_dir], 0
    jne .no                           ; the right one has been tried too
    jmp .tryright
.no:
    clc
.out:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sp_islabel - is the record at DI a LABEL in the row sh_spill is asking
; about? out: CF=0 and [sh_sp_lcol]/[sh_sp_toff]/[sh_sp_fmt]/[sh_sp_align]
; filled; CF=1 if it is not one. Clobbers nothing else.
; -----------------------------------------------------------------------------
sh_sp_islabel:
    push ax
    push es
    mov es, [sh_cellseg]
    mov ax, [sh_sp_key]
    cmp [es:di], ax                   ; this row of this sheet
    jne .no
    cmp byte [es:di+SH_C_TYPE], SH_T_TEXT
    jne .no                           ; a label, or a formula's text result
    mov ax, [es:di+2]
    mov [sh_sp_lcol], ax
    mov ax, [es:di+SH_C_FOFF]         ; a label's own text...
    test byte [es:di+4], 1
    jz .haveoff
    mov ax, [es:di+SH_C_VAL]          ; ...or a formula's RESULT (81.22.1)
.haveoff:
    mov [sh_sp_toff], ax
    mov al, [es:di+SH_C_FMT]
    mov [sh_sp_fmt], al
    and al, SH_FMT_ALIGN_MASK
    push cx
    mov cl, SH_FMT_ALIGN_SHIFT
    shr al, cl
    pop cx
    mov [sh_sp_align], al
    pop es
    pop ax
    clc
    ret
.no:
    pop es
    pop ax
    stc
    ret

; -----------------------------------------------------------------------------
; sh_sp_dist - the character distance from the label's own left edge to this
; cell's, signed: positive when this cell is to the RIGHT of the label.
; in: DX = this column, [sh_sp_lcol] = the label's. out: AX. Every column's
; own width (81.56), scrolled out of view or not.
; -----------------------------------------------------------------------------
sh_sp_dist:
    push bx
    push cx
    push si
    xor cx, cx
    mov si, [sh_sp_lcol]
    cmp si, dx
    jb .rightof
.leftof:                              ; the label is at or right of us: walk
    mov si, dx                        ; OUR column up to it and negate
.lsum:
    cmp si, [sh_sp_lcol]
    jae .ldone
    mov ax, si
    call sh_colwidth
    add cx, ax
    inc si
    jmp short .lsum
.ldone:
    xor ax, ax
    sub ax, cx
    jmp short .out
.rightof:                             ; the label is left of us: walk from it
.rsum:
    cmp si, dx
    jae .rdone
    mov ax, si
    call sh_colwidth
    add cx, ax
    inc si
    jmp short .rsum
.rdone:
    mov ax, cx
.out:
    pop si
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_strlen - in: SI=NUL-terminated string; out: AX=length (SI preserved)
; -----------------------------------------------------------------------------
sh_strlen:
    push si
    xor ax, ax
.lp:
    cmp byte [si], 0
    je .done
    inc si
    inc ax
    jmp .lp
.done:
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_errname - the current cell's error, by name, into sh_numbuf. Excel's own
; spellings, because they are what a person recognises and what every book
; about spreadsheets prints. An unknown code cannot arise from this app's own
; evaluator, but a file could carry one, so it reads as #ERR rather than
; running off the end of the table.
; -----------------------------------------------------------------------------
sh_errname:
    push ax
    push bx
    push si
    push di
    mov al, [sh_curaux]
    or al, al
    jz .unknown
    cmp al, 7
    ja .unknown
    xor ah, ah
    dec ax
    shl ax, 1
    mov bx, ax
    mov si, [sh_errtab + bx]
    jmp .copy
.unknown:
    mov si, sh_s_err_unk
.copy:
    mov di, sh_numbuf
    call sh_strcpy
    pop di
    pop si
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_errcode - in: SI = a NUL-terminated error name; out: AL = its Excel
; ERROR.TYPE number, or 0 if this is not a spelling we write. The inverse of
; sh_errname, and it reads the SAME table, so the two cannot drift apart.
; -----------------------------------------------------------------------------
section SH_MODSEC                      ; 82.16.9
sh_errcode:
    push bx
    push cx
    push si
    push di
    xor cx, cx
.loop:
    cmp cx, 7
    jae .unknown
    mov bx, cx
    shl bx, 1
    mov di, [sh_errtab + bx]
    SHOUT sh_streq
    jc .found
    inc cx
    jmp .loop
.found:
    mov ax, cx
    inc ax
    jmp .out
.unknown:
    xor ax, ax
.out:
    pop di
    pop si
    pop cx
    pop bx
    ret

section .text
sh_errtab:  dw sh_s_err_null, sh_s_err_div0, sh_s_err_value, sh_s_err_ref
            dw sh_s_err_name, sh_s_err_num, sh_s_err_na
sh_s_err_null:  db '#NULL!', 0
sh_s_err_div0:  db '#DIV/0!', 0
sh_s_err_value: db '#VALUE!', 0
sh_s_err_ref:   db '#REF!', 0
sh_s_err_name:  db '#NAME?', 0
sh_s_err_num:   db '#NUM!', 0
sh_s_err_na:    db '#N/A', 0
sh_s_err_unk:   db '#ERR', 0

; =============================================================================
; NUMBER FORMAT CODES (81.55) - Excel 2.1d's twenty-one built-ins, in its own
; order (which is the BIFF built-in id, and the position a BIFF2 cell names),
; and ONE engine that draws a value by any code: the grid through a cell's
; format, TEXT() through the code it is handed. It was two: sh_numfmt knew four
; formats and TEXT() knew '$', ',', '0', '#', '.' and '%', and neither knew a
; date - DATE() and NOW() answered correctly and showed a serial number.
; =============================================================================
SH_NF_N       equ 21
sh_nf_c0:     db 'General', 0
sh_nf_c1:     db '0', 0
sh_nf_c2:     db '0.00', 0
sh_nf_c3:     db '#,##0', 0
sh_nf_c4:     db '#,##0.00', 0
sh_nf_c5:     db '$#,##0 ;($#,##0)', 0
sh_nf_c6:     db '$#,##0 ;[Red]($#,##0)', 0
sh_nf_c7:     db '$#,##0.00 ;($#,##0.00)', 0
sh_nf_c8:     db '$#,##0.00 ;[Red]($#,##0.00)', 0
sh_nf_c9:     db '0%', 0
sh_nf_c10:    db '0.00%', 0
sh_nf_c11:    db '0.00E+00', 0
sh_nf_c12:    db 'm/d/yy', 0
sh_nf_c13:    db 'd-mmm-yy', 0
sh_nf_c14:    db 'd-mmm', 0
sh_nf_c15:    db 'mmm-yy', 0
sh_nf_c16:    db 'h:mm AM/PM', 0
sh_nf_c17:    db 'h:mm:ss AM/PM', 0
sh_nf_c18:    db 'h:mm', 0
sh_nf_c19:    db 'h:mm:ss', 0
sh_nf_c20:    db 'm/d/yy h:mm', 0
sh_nf_codes:  dw sh_nf_c0, sh_nf_c1, sh_nf_c2, sh_nf_c3, sh_nf_c4, sh_nf_c5
              dw sh_nf_c6, sh_nf_c7, sh_nf_c8, sh_nf_c9, sh_nf_c10, sh_nf_c11
              dw sh_nf_c12, sh_nf_c13, sh_nf_c14, sh_nf_c15, sh_nf_c16
              dw sh_nf_c17, sh_nf_c18, sh_nf_c19, sh_nf_c20, 0
sh_nf_general: db 'GENERAL', 0
sh_nf_mon:    db 'January', 0, 'February', 0, 'March', 0, 'April', 0, 'May', 0
              db 'June', 0, 'July', 0, 'August', 0, 'September', 0
              db 'October', 0, 'November', 0, 'December', 0
sh_nf_day:    db 'Sunday', 0, 'Monday', 0, 'Tuesday', 0, 'Wednesday', 0
              db 'Thursday', 0, 'Friday', 0, 'Saturday', 0
sh_nf_c10d:   dq 10.0

; -----------------------------------------------------------------------------
; sh_fmtcode - sh_acc drawn by the format code at DS:SI, into sh_numbuf.
; sh_acc is left as it came.
;
; A code has up to three sections, ';'-separated: positive, negative, zero. A
; negative value takes the second section AS ITS MAGNITUDE - the section's own
; '(' and ')' are the sign - and with one section keeps its '-'. The section is
; copied to sh_nf_sec first, so everything after reads one NUL-ended string.
; -----------------------------------------------------------------------------
sh_fmtcode:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push word [sh_acc+6]              ; the value, put back on the way out
    push word [sh_acc+4]
    push word [sh_acc+2]
    push word [sh_acc]
    mov di, sh_nf_general
    call sh_wordeq
    jc .general
    cmp byte [si], 0
    je .general
    ; --- which section ------------------------------------------------------
    mov dl, 0                         ; DL = the section wanted
    call sh_acc_iszero
    jc .zero
    test byte [sh_acc+7], 0x80
    jz .pick
    mov dl, 1
    jmp short .pick
.zero:
    mov dl, 2
.pick:
    call sh_nf_section                ; -> sh_nf_sec; CF=1 no such section
    jnc .have
    call sh_nf_section0               ; ...then the first one, sign and all
    xor dl, dl
.have:
    cmp dl, 1
    jne .signok
    and byte [sh_acc+7], 0x7F         ; the negative section shows magnitude
.signok:
    mov si, sh_nf_sec
    call sh_nf_isdate
    jc .date
    call sh_nf_number
    jmp short .out
.date:
    call sh_nf_date
    jmp short .out
.general:
    call sh_acc_load_a
    mov di, sh_numbuf
    mov ax, 10
    call fp_ftoa
.out:
    pop word [sh_acc]
    pop word [sh_acc+2]
    pop word [sh_acc+4]
    pop word [sh_acc+6]
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_cell_nfid - in: AX = col, BX = row; out: AL = the cell's format id -
; the border table's, else the one its format byte names, else General
sh_cell_nfid:
    push bx
    push di
    push es
    push ax
    call sh_bt_getw
    mov al, ah
    pop di                             ; DI = the column, off the stack
    or al, al
    jz .byte
    dec al
    jmp short .out
.byte:
    mov ax, di
    call sh_findcell
    mov al, 0
    jnc .out
    mov es, [sh_cellseg]
    mov al, [es:di+SH_C_FMT]
    and al, SH_FMT_NUM_MASK
    push cx
    mov cl, SH_FMT_NUM_SHIFT
    shr al, cl
    pop cx
    mov bx, sh_biff_numfmt_tab
    xlat
.out:
    pop es
    pop di
    pop bx
    ret

; sh_nf_simple - AL = an id; out: CF=1 and AL = the format byte's own code
; when it is one of the four the format byte can hold
sh_nf_simple:
    push bx
    push cx
    mov bx, sh_biff_numfmt_tab
    xor cx, cx
.l:
    cmp al, [bx]
    je .yes
    inc bx
    inc cx
    cmp cx, 4
    jb .l
    clc
    jmp short .out
.yes:
    mov al, cl
    stc
.out:
    pop cx
    pop bx
    ret

; -----------------------------------------------------------------------------
; sh_nf_apply - format id AL to every cell of the selection. A cell that
; exists and wants one of the four simple formats keeps it in its format byte,
; as ever, and drops any border-table format; anything else - another format,
; or ANY format on an empty cell - goes in the border table, where it waits for
; a value (81.55). The format byte's number field is General then, so the two
; can never disagree.
; -----------------------------------------------------------------------------
sh_nf_apply:
    push ax
    push bx
    push cx
    push dx
    push si
    mov dl, al                         ; DL = the id
    mov ax, [sh_selrow]
    mov bx, [sh_selrow2]
    cmp ax, bx
    jbe .r
    xchg ax, bx
.r:
    mov [sh_nf_r1], ax
    mov [sh_nf_r2], bx
    mov cx, [sh_selcol]
    mov si, [sh_selcol2]
    cmp cx, si
    jbe .col
    xchg cx, si
.col:
    mov bx, [sh_nf_r1]
.row:
    mov ax, cx
    call sh_nf_one                     ; AX col, BX row, DL id
    inc bx
    cmp bx, [sh_nf_r2]
    jbe .row
    inc cx
    cmp cx, si
    jbe .col
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

sh_nf_one:
    push ax
    push bx
    push cx
    push di
    push es
    call sh_findcell                   ; AX, BX kept
    jnc .side                          ; no cell: the table, whatever it is
    mov cx, ax                         ; CX = the column
    mov al, dl
    call sh_nf_simple
    xchg ax, cx                        ; AX = the column, CL = its simple code
    jnc .sidefmt
    mov es, [sh_cellseg]               ; simple: the format byte...
    and byte [es:di+SH_C_FMT], SH_FMT_NUM_CLR
    push cx
    mov ch, cl
    mov cl, SH_FMT_NUM_SHIFT
    shl ch, cl
    or [es:di+SH_C_FMT], ch
    pop cx
    jmp short .drop                    ; ...and no table format beside it
.sidefmt:
    mov es, [sh_cellseg]
    and byte [es:di+SH_C_FMT], SH_FMT_NUM_CLR
.side:
    or dl, dl                          ; General on an empty cell: nothing to
    jz .drop                           ; hold - drop a table format if any
    call sh_bt_addcell
    jc .out                            ; the table is full: silent, as Border is
    mov es, [sh_bordseg]
    mov cl, dl
    inc cl
    mov [es:di+5], cl
    jmp short .out
.drop:
    call sh_bt_findcell
    jnc .out
    mov es, [sh_bordseg]
    mov byte [es:di+5], 0
    cmp byte [es:di+4], 0
    jne .out
    call sh_bt_removecell              ; nothing left in the record
.out:
    pop es
    pop di
    pop cx
    pop bx
    pop ax
    ret

; sh_nf_skipq - SI at a quote, bracket or backslash: step over what it opens.
; out: SI past it. Anything else: SI+1.
sh_nf_skipq:
    mov al, [si]
    inc si
    cmp al, '"'
    je .q
    cmp al, '['
    je .b
    cmp al, '\'
    jne .x
    cmp byte [si], 0
    je .x
    inc si
.x:
    ret
.q:
    cmp byte [si], 0
    je .x
    cmp byte [si], '"'
    je .qe
    inc si
    jmp short .q
.qe:
    inc si
    ret
.b:
    cmp byte [si], 0
    je .x
    cmp byte [si], ']'
    je .qe
    inc si
    jmp short .b

; sh_nf_section - copy section DL (0-2) of the code at SI to sh_nf_sec.
; CF=1 when the code has no such section. sh_nf_section0: section 0, always.
sh_nf_section0:
    xor dl, dl
sh_nf_section:
    push ax
    push bx
    push cx
    push si
    push di
    mov cl, dl
.find:
    or cl, cl
    jz .copy
.f1:
    mov al, [si]
    or al, al
    jz .none
    cmp al, ';'
    je .fsep
    call sh_nf_skipq
    jmp short .f1
.fsep:
    inc si
    dec cl
    jmp short .find
.copy:
    mov di, sh_nf_sec
    mov cx, SH_STR_MAX
.c1:
    mov al, [si]
    or al, al
    jz .cend
    cmp al, ';'
    je .cend
    push si
    call sh_nf_skipq                  ; a quoted ';' is text, not a separator
    mov ax, si
    pop si
.c2:
    cmp si, ax
    jae .c1
    jcxz .cend
    mov bl, [si]
    mov [di], bl
    inc si
    inc di
    dec cx
    jmp short .c2
.cend:
    mov byte [di], 0
    clc
    jmp short .out
.none:
    stc
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_nf_isdate - CF=1 when the section at SI is a DATE or TIME code: a d, y,
; h or s outside quotes, or an m with no digit placeholder anywhere
sh_nf_isdate:
    push ax
    push bx
    push si
    xor bx, bx                        ; BL = an m seen, BH = a 0 or # seen
.l:
    mov al, [si]
    or al, al
    jz .end
    cmp al, '"'
    je .sk
    cmp al, '['
    je .sk
    cmp al, '\'
    je .sk
    or al, 0x20                       ; letters to lower case
    cmp al, 'd'
    je .yes
    cmp al, 'y'
    je .yes
    cmp al, 'h'
    je .yes
    cmp al, 's'
    je .yes
    cmp al, 'm'
    jne .n1
    mov bl, 1
.n1:
    mov al, [si]
    cmp al, '0'
    je .ph
    cmp al, '#'
    jne .n2
.ph:
    mov bh, 1
.n2:
    inc si
    jmp short .l
.sk:
    call sh_nf_skipq
    jmp short .l
.end:
    or bl, bl
    jz .no
    or bh, bh
    jnz .no
.yes:
    stc
    jmp short .out
.no:
    clc
.out:
    pop si
    pop bx
    pop ax
    ret

; sh_nf_lit - one literal of the section at SI onto DS:DI: a quoted run's
; inside, a backslash's next character, a bracket's nothing ([Red] - there is
; no colour), '_x' a space, '*x' nothing; anything else itself. SI past it.
sh_nf_lit:
    push ax
    mov al, [si]
    cmp al, '"'
    je .q
    cmp al, '['
    je .skip
    cmp al, '\'
    je .esc
    cmp al, '_'
    je .under
    cmp al, '*'
    je .fill
    call sh_nf_putc
    inc si
    jmp short .out
.q:
    inc si
.q1:
    mov al, [si]
    or al, al
    jz .out
    inc si
    cmp al, '"'
    je .out
    call sh_nf_putc
    jmp short .q1
.skip:
    call sh_nf_skipq
    jmp short .out
.esc:
    inc si
    mov al, [si]
    or al, al
    jz .out
    call sh_nf_putc
    inc si
    jmp short .out
.under:
    mov al, ' '
    call sh_nf_putc
    inc si
    cmp byte [si], 0
    je .out
    inc si
    jmp short .out
.fill:
    inc si
    cmp byte [si], 0
    je .out
    inc si
.out:
    pop ax
    ret

; sh_nf_putc - AL onto DS:DI, kept inside sh_numbuf
sh_nf_putc:
    cmp di, sh_numbuf + SH_NUMBUF_MAX
    jae .full
    mov [di], al
    inc di
.full:
    mov byte [di], 0
    ret

; sh_nf_puts - the NUL string at DS:BX onto DS:DI
sh_nf_puts:
    push ax
    push bx
.l:
    mov al, [bx]
    or al, al
    jz .out
    call sh_nf_putc
    inc bx
    jmp short .l
.out:
    pop bx
    pop ax
    ret

; sh_nf_putn - AX, unsigned, as few digits as it takes; with CL=2, at least 2
sh_nf_putn:
    ; STKBALANCE-LOOP: one digit pushed a turn (and one pad zero), and the second loop pops them; the count is in CH
    push ax
    push bx
    push cx
    push dx
    mov bx, 10
    xor ch, ch
.d:
    xor dx, dx
    div bx
    push dx
    inc ch
    or ax, ax
    jnz .d
    cmp ch, cl
    jae .p
    xor dx, dx
    push dx
    inc ch
    jmp short .p
.p:
    pop ax
    add al, '0'
    call sh_nf_putc
    dec ch
    jnz .p
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_nf_run - the run of one letter (either case) at SI. out: CX = its length,
; SI past it. AL = the letter, lower case.
sh_nf_run:
    mov al, [si]
    or al, 0x20
    xor cx, cx
.l:
    mov ah, [si]
    or ah, 0x20
    cmp ah, al
    jne .out
    inc si
    inc cx
    jmp short .l
.out:
    ret

; sh_nf_name - in: AX = an index, BX = a run of NUL-ended strings; out: BX =
; the AXth of them
sh_nf_name:
    push ax
.l:
    or ax, ax
    jz .out
.s:
    cmp byte [bx], 0
    je .n
    inc bx
    jmp short .s
.n:
    inc bx
    dec ax
    jmp short .l
.out:
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_nf_date - sh_acc as a date and/or time by the section at SI -> sh_numbuf.
; m is the MONTH, except straight after an h or straight before an s, where it
; is the minute - Excel's own rule. AM/PM or A/P anywhere makes h 12-hour.
; -----------------------------------------------------------------------------
sh_nf_date:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push word [sh_acc+6]              ; THE TIME FIRST: sh_acc_toudw truncates
    push word [sh_acc+4]              ; sh_acc IN PLACE, and every time came
    push word [sh_acc+2]              ; out as midnight when it went second
    push word [sh_acc]
    call sh_dt_hms                    ; sh_dt_min, AX = the seconds
    mov [sh_nf_s], al
    mov ax, [sh_dt_min]
    xor dx, dx
    mov bx, 60
    div bx
    mov [sh_nf_h], al
    mov [sh_nf_mi], dl
    pop word [sh_acc]
    pop word [sh_acc+2]
    pop word [sh_acc+4]
    pop word [sh_acc+6]
    call sh_acc_toudw                 ; the whole days
    jnc .days
    mov di, sh_numbuf                 ; a negative date or one past 2079: the
    mov byte [di], 0                  ; one answer Excel has for it is to fill
    mov al, '#'                       ; the cell - and the grid does that for
    call sh_nf_putc                   ; anything too wide, so one is enough
    jmp .done
.days:
    push ax
    call sh_ser_to_ymd                ; -> sh_dt_y/m/d
    pop ax
    add ax, 6                         ; serial 1 is a Sunday, as in WEEKDAY
    xor dx, dx
    mov bx, 7
    div bx
    mov [sh_nf_wd], dl                ; 0 Sunday .. 6 Saturday
    mov byte [sh_nf_12], 0            ; AM/PM or A/P anywhere?
    push si
.ampm:
    mov al, [si]
    or al, al
    jz .ampmd
    or al, 0x20
    cmp al, 'a'
    jne .ampmn
    mov al, [si+1]
    cmp al, '/'
    je .ampmy
    or al, 0x20
    cmp al, 'm'
    jne .ampmn
    cmp byte [si+2], '/'
    jne .ampmn
.ampmy:
    mov byte [sh_nf_12], 1
.ampmn:
    inc si
    jmp short .ampm
.ampmd:
    pop si
    mov di, sh_numbuf
    mov byte [di], 0
    mov byte [sh_nf_lasth], 0
.tok:
    mov al, [si]
    or al, al
    jz .done
    or al, 0x20
    cmp al, 'y'
    je .yr
    cmp al, 'm'
    je .mo
    cmp al, 'd'
    je .dy
    cmp al, 'h'
    je .hr
    cmp al, 's'
    je .sc
    cmp al, 'a'
    je .ap
    call sh_nf_lit
    jmp short .tok
.yr:
    call sh_nf_run                    ; CL = the run: yy or yyyy
    jmp .yrgo
.mo:
    call sh_nf_run
    mov [sh_nf_rl], cl
    cmp byte [sh_nf_lasth], 0         ; straight after an h: the minute
    jne .mins
    push si                           ; ...or straight before an s
.mo1:
    mov al, [si]
    or al, al
    jz .mo2
    or al, 0x20
    cmp al, 's'
    je .mo3
    cmp al, 'a'
    jb .mo4
    cmp al, 'z'
    jbe .mo2                          ; any other letter first: the month
.mo4:
    inc si
    jmp short .mo1
.mo3:
    pop si
    jmp short .mins
.mo2:
    pop si
    mov al, [sh_nf_rl]
    cmp al, 3
    jb .monum
    mov ax, [sh_dt_m]
    dec ax
    mov bx, sh_nf_mon
    call sh_nf_name
    cmp byte [sh_nf_rl], 3
    jne .mofull
    mov cx, 3                         ; mmm: the first three letters
.mo5:
    mov al, [bx]
    call sh_nf_putc
    inc bx
    loop .mo5
    jmp .tokd
.mofull:
    call sh_nf_puts
    jmp .tokd
.monum:
    mov ax, [sh_dt_m]
    jmp .num12
.mins:
    xor ah, ah
    mov al, [sh_nf_mi]
    mov cl, [sh_nf_rl]
    call sh_nf_putn
    jmp .tokd
.dy:
    call sh_nf_run
    cmp cl, 3
    jb .dnum
    xor ah, ah
    mov al, [sh_nf_wd]
    mov bx, sh_nf_day
    call sh_nf_name
    cmp cl, 3
    jne .dfull
    mov cx, 3
.d5:
    mov al, [bx]
    call sh_nf_putc
    inc bx
    loop .d5
    jmp .tokd
.dfull:
    call sh_nf_puts
    jmp .tokd
.dnum:
    mov ax, [sh_dt_d]
    call sh_nf_putn
    jmp .tokd
.yrgo:
    mov ax, [sh_dt_y]
    cmp cl, 3
    jae .y4
    xor dx, dx
    mov bx, 100
    div bx
    mov ax, dx
    mov cl, 2
.y4:
    call sh_nf_putn
    jmp .tokd
.hr:
    call sh_nf_run
    xor ah, ah
    mov al, [sh_nf_h]
    cmp byte [sh_nf_12], 0
    je .h24
    xor dx, dx
    mov bx, 12
    div bx
    mov ax, dx
    or ax, ax
    jnz .h24
    mov ax, 12
.h24:
    call sh_nf_putn
    mov byte [sh_nf_lasth], 1
    jmp .tok
.sc:
    call sh_nf_run
    xor ah, ah
    mov al, [sh_nf_s]
    call sh_nf_putn
    jmp .tokd
.ap:
    mov bx, sh_nf_am
    cmp byte [sh_nf_h], 12
    jb .ap1
    mov bx, sh_nf_pm
.ap1:
    mov al, [si+1]
    cmp al, '/'
    je .apshort
    or al, 0x20
    cmp al, 'm'
    jne .aplit
    cmp byte [si+2], '/'
    jne .aplit
    call sh_nf_puts                   ; "AM" or "PM"
    add si, 5
    jmp .tokd
.apshort:
    mov al, [bx]                      ; "A" or "P"
    call sh_nf_putc
    add si, 3
    jmp .tokd
.aplit:
    call sh_nf_lit
    jmp .tok
.num12:
    call sh_nf_putn                   ; m or mm: CL is the run length, and
.tokd:                                ; sh_nf_putn pads to two for mm
    mov byte [sh_nf_lasth], 0
    jmp .tok
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

sh_nf_am:     db 'AM', 0
sh_nf_pm:     db 'PM', 0

; -----------------------------------------------------------------------------
; sh_nf_number - sh_acc by the NUMBER section at SI -> sh_numbuf.
; The digit placeholders ('0' '#' '?' and the ',' '.' among them) are one run,
; drawn as one number where the first of them stands; everything else is a
; literal kept in place. A section with no placeholder at all is only its
; literals - Excel's own reading, which is what a zero section like "nil" is.
; -----------------------------------------------------------------------------
sh_nf_number:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    ; --- pass 1: what the placeholders say ----------------------------------
    xor bx, bx                        ; BL: 2 grouping, 4 percent, 8 exponent
    xor cx, cx                        ; CH decimals, CL integer zeros
    xor dx, dx                        ; DH past the '.', DL a placeholder seen
    push si
.p1:
    mov al, [si]
    or al, al
    jz .p1end
    cmp al, '"'
    je .p1sk
    cmp al, '['
    je .p1sk
    cmp al, '\'
    je .p1sk
    cmp al, '%'
    jne .p1a
    or bl, 4
.p1a:
    cmp al, '.'
    jne .p1b
    or dl, dl
    jz .p1n                           ; a '.' before any digit is a literal
    mov dh, 1
.p1b:
    cmp al, ','
    jne .p1c
    or dl, dl
    jz .p1n
    or dh, dh
    jnz .p1n
    or bl, 2
.p1c:
    cmp al, 'E'
    je .p1e
    cmp al, 'e'
    jne .p1d
.p1e:
    or dl, dl
    jz .p1n
    mov ah, [si+1]
    cmp ah, '+'
    je .p1e2
    cmp ah, '-'
    jne .p1n
.p1e2:
    or bl, 8
    jmp short .p1end                  ; what follows is the exponent's digits
.p1d:
    cmp al, '0'
    je .p1z
    cmp al, '#'
    je .p1h
    cmp al, '?'
    jne .p1n
.p1h:
    mov dl, 1
    or dh, dh
    jz .p1n
    inc ch
    jmp short .p1n
.p1z:
    mov dl, 1
    or dh, dh
    jz .p1zi
    inc ch
    jmp short .p1n
.p1zi:
    inc cl
.p1n:
    inc si
    jmp short .p1
.p1sk:
    call sh_nf_skipq
    jmp short .p1
.p1end:
    pop si
    or dl, dl
    jnz .digits
    ; --- no placeholder: the literals are the whole answer -------------------
    mov di, sh_numbuf
    mov byte [di], 0
.lits:
    cmp byte [si], 0
    je .done
    call sh_nf_lit
    jmp short .lits
.digits:
    mov [sh_nf_fl], bl
    mov [sh_nf_cx], cx
    test bl, 4
    jz .nopct
    call sh_vpush                     ; a percent scales by a hundred
    mov ax, 100
    call sh_acc_int
    call sh_binop_pre
    call fp_mul
    call sh_acc_store
.nopct:
    test byte [sh_nf_fl], 8
    jz .fixed
    call sh_nf_sci                    ; -> sh_numbuf: mantissa E+xx
    jmp short .built
.fixed:
    call sh_acc_load_a
    mov cx, [sh_nf_cx]
    push cx
    mov cl, ch
    xor ch, ch
    call sh_numdp
    pop cx
    call sh_padzero                   ; CL = the minimum integer digits
    test byte [sh_nf_fl], 2
    jz .built
    call sh_group3
.built:
    push si                           ; the number, out of sh_numbuf's way
    mov si, sh_numbuf
    mov di, sh_nf_num
    call sh_strcpy
    pop si
    ; --- pass 2: the literals around it -------------------------------------
    mov di, sh_numbuf
    mov byte [di], 0
    mov bx, sh_nf_num
    cmp byte [bx], '-'                ; one section, negative: the sign goes
    jne .p2                           ; FIRST, before a '$' or a '('
    mov al, '-'
    call sh_nf_putc
    inc bx
.p2:
    mov al, [si]
    or al, al
    jz .done
    cmp al, '0'
    je .run
    cmp al, '#'
    je .run
    cmp al, '?'
    je .run
    cmp al, '.'
    jne .p2l
    cmp byte [si+1], '0'              ; a '.' that opens the decimals
    je .run
    cmp byte [si+1], '#'
    je .run
.p2l:
    call sh_nf_lit
    jmp short .p2
.run:
    or bx, bx                         ; the number where the first stands...
    jz .skiprun
    call sh_nf_puts
    xor bx, bx
.skiprun:                             ; ...and the rest of the run consumed
    mov al, [si]
    cmp al, '0'
    je .sr
    cmp al, '#'
    je .sr
    cmp al, '?'
    je .sr
    cmp al, '.'
    je .sr
    cmp al, ','
    je .sr
    test byte [sh_nf_fl], 8
    jz .p2
    cmp al, 'E'
    je .sre
    cmp al, 'e'
    jne .p2
.sre:
    inc si                            ; E, its sign, and the exponent's own
    cmp byte [si], 0                  ; digits: sh_nf_sci drew all of it
    je .p2
    inc si
    jmp short .skiprun
.sr:
    inc si
    jmp short .skiprun
.done:
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_nf_sci - sh_acc as MANTISSA E +/- EXPONENT, [sh_nf_cx]'s CH decimals in
; the mantissa and two digits of exponent at least -> sh_numbuf. Scaled by ten
; a step at a time rather than through a logarithm: exact for every power a
; spreadsheet holds, and never more than 330 steps for any double.
sh_nf_sci:
    push ax
    push bx
    push cx
    push si
    push di
    xor bx, bx                        ; BX = the exponent
    mov byte [sh_nf_neg], 0
    test byte [sh_acc+7], 0x80
    jz .pos
    mov byte [sh_nf_neg], 1
    and byte [sh_acc+7], 0x7F
.pos:
    call sh_acc_iszero
    jc .scaled
    mov cx, 330
.up:
    call sh_acc_load_a                ; >= 10: divide
    mov si, sh_nf_c10d
    call fp_unpack_b
    call fp_cmpab
    jl .down
    push cx
    call fp_div
    call sh_acc_store
    pop cx
    inc bx
    loop .up
    jmp short .scaled
.down:
    push cx
    mov ax, 1                         ; < 1: multiply
    call fp_i2a
    call fp_a_to_b
    call sh_acc_load_a
    call fp_cmpab
    pop cx
    jge .scaled
    push cx
    mov si, sh_nf_c10d
    call fp_unpack_b
    call fp_mul
    call sh_acc_store
    pop cx
    dec bx
    loop .down
.scaled:
    call sh_acc_load_a
    mov cx, [sh_nf_cx]
    mov cl, ch
    xor ch, ch
    call sh_numdp                     ; the mantissa, rounded...
    cmp byte [sh_numbuf], '1'         ; ...and 9.996 rounded to two places is
    jne .mant                         ; "10.00": one more step
    cmp byte [sh_numbuf+1], '0'
    jne .mant
    push bx
    call sh_acc_load_a
    mov si, sh_nf_c10d
    call fp_unpack_b
    call fp_div
    mov cx, [sh_nf_cx]
    mov cl, ch
    xor ch, ch
    call sh_numdp
    pop bx
    inc bx
.mant:
    mov di, sh_numbuf                 ; the sign in front, then E and the
    cmp byte [sh_nf_neg], 0           ; exponent at the end
    je .ms
    mov al, '-'
    call sh_ins_at
.ms:
    mov di, sh_numbuf
.end:
    cmp byte [di], 0
    je .e
    inc di
    jmp short .end
.e:
    mov al, 'E'
    call sh_nf_putc
    mov al, '+'
    or bx, bx
    jns .es
    mov al, '-'
    neg bx
.es:
    call sh_nf_putc
    mov ax, bx
    mov cl, 2
    call sh_nf_putn
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_numfmt - in: sh_acc = the value, BL = the format byte, BH = the cell's
; number format from the border table (Excel's id PLUS ONE, 0 for none: then
; the format byte's four); writes the display text into sh_numbuf, by
; sh_fmtcode and Excel's own code for that id (81.55).
; -----------------------------------------------------------------------------
; stage 4.0: the value being formatted is the DOUBLE in sh_acc, not the
; integer in AX. Its one caller is sh_drawgrid, immediately after
; sh_getcell2, which leaves sh_acc set - so the grid shows 3.5 as "3.5"
; rather than as the 3 an integer cell could hold. The currency, comma and
; percent decorations below are unchanged: they work on the digit string,
; whatever produced it.
;
; Ten significant digits, which is what fits a cell and what Excel shows in a
; General column before it starts rounding to fit.
sh_numfmt:
    push ax
    push bx
    push cx
    push si
    push di
    mov al, bh                        ; the cell's own format id, plus one...
    or al, al
    jz .byte
    dec al
    jmp short .have
.byte:
    mov al, bl                        ; ...or the four the format byte names,
    and al, SH_FMT_NUM_MASK           ; which are Excel's ids 0, 5, 3 and 9 -
    mov cl, SH_FMT_NUM_SHIFT          ; the table the BIFF writer declares
    shr al, cl                        ; them by
    mov bx, sh_biff_numfmt_tab
    xlat
.have:
    cmp al, SH_NF_N
    jb .code
    xor al, al
.code:
    mov [sh_nf_id], al
    xor ah, ah
    mov si, ax
    shl si, 1
    mov si, [sh_nf_codes + si]
    call sh_fmtcode                   ; -> sh_numbuf
    ; A NUMBER NEVER SHOWS PART OF ITSELF (81.55). It was drawn whole and the
    ; next cell painted over the rest, so 123456789 in a seven-character cell
    ; read 1234567 - a plausible number, and a wrong one. General takes fewer
    ; significant digits until it fits, which is %g's own way into scientific
    ; notation; any other format fills the cell with '#', as Excel does.
    mov si, sh_numbuf
    call sh_strlen
    cmp ax, [sh_cellch]
    jbe .out
    cmp byte [sh_nf_id], 0
    jne .hash
    mov cx, 9
.fit:
    call sh_acc_load_a
    mov di, sh_numbuf
    mov ax, cx
    call fp_ftoa
    mov si, sh_numbuf
    call sh_strlen
    cmp ax, [sh_cellch]
    jbe .out
    loop .fit
    ; fp_ftoa turns scientific only past a wide exponent, so 123456789 stays
    ; nine digits at any precision: General's last step is Excel's own, the
    ; mantissa with as many places as the cell leaves room for - 1.2E+08
    mov cx, [sh_cellch]
    sub cx, 6                         ; "d.E+08" is six without any places
    jc .hash
.sci:
    push word [sh_acc+6]              ; sh_nf_sci scales sh_acc in place
    push word [sh_acc+4]
    push word [sh_acc+2]
    push word [sh_acc]
    mov byte [sh_nf_cx], 0
    mov [sh_nf_cx+1], cl
    call sh_nf_sci
    pop word [sh_acc]
    pop word [sh_acc+2]
    pop word [sh_acc+4]
    pop word [sh_acc+6]
    mov si, sh_numbuf
    call sh_strlen
    cmp ax, [sh_cellch]
    jbe .out
    dec cx
    jns .sci
.hash:
    mov di, sh_numbuf
    mov cx, [sh_cellch]
    cmp cx, SH_NUMBUF_MAX
    jbe .h1
    mov cx, SH_NUMBUF_MAX
.h1:
    mov byte [di], '#'
    inc di
    loop .h1
    mov byte [di], 0
.out:
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_drawunderline - in: CX=cell text x (left edge, as passed to
; OSAPI_FONT_RUN), DX=cell text y (top); reads sh_numbuf (the UNPADDED
; decorated text - not sh_tbuf, which carries alignment padding) and
; [sh_curfmt] to underline exactly the text's own extent, not the whole
; cell, positioned by the same alignment the text itself used.
; -----------------------------------------------------------------------------
sh_drawunderline:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    mov [sh_ulx], cx
    mov [sh_uly], dx
    mov si, sh_numbuf
    call sh_strlen                    ; ax = text length (chars)
    mov bx, ax                        ; bx = length (chars)
    mov ax, [sh_cellch]
    sub ax, bx
    jns .padok
    xor ax, ax
.padok:                                ; ax = total pad chars
    mov dl, [sh_curfmt]
    and dl, SH_FMT_ALIGN_MASK
    mov cl, SH_FMT_ALIGN_SHIFT
    shr dl, cl                         ; dl = align code
    cmp dl, SH_FMT_ALIGN_LEFT
    je .lp0
    cmp dl, SH_FMT_ALIGN_CENTER
    je .lphalf
    mov di, ax                         ; General/Right: full pad on the left
    jmp .havelp
.lp0:
    xor di, di
    jmp .havelp
.lphalf:
    shr ax, 1
    mov di, ax
.havelp:                               ; di = left-pad chars
    shl di, 1
    shl di, 1
    shl di, 1                          ; di = left-pad pixels (*8)
    shl bx, 1
    shl bx, 1
    shl bx, 1                          ; bx = text width pixels (*8)
    mov ax, [sh_ulx]
    add ax, di                         ; ax = underline x1
    mov cx, ax
    add cx, bx
    dec cx                             ; cx = underline x2
    mov bx, [sh_uly]
    add bx, 9                          ; a couple px below the 8px glyph row
    mov dx, bx
    call OSAPI_GFX_FILL                ; AX=x1, BX=y1, CX=x2, DX=y2
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_strcpy - copy a NUL-terminated string, SI->DI, including the NUL
sh_strcpy:
    push ax
.loop:
    mov al, [si]
    mov [di], al
    inc si
    inc di
    or al, al
    jnz .loop
    pop ax
    ret

; sh_strcpy_to_di - append a NUL-terminated string at the DI cursor,
; advancing DI to the new NUL (so successive calls concatenate)
sh_strcpy_to_di:
    push ax
.loop:
    mov al, [si]
    or al, al
    jz .term
    mov [di], al
    inc si
    inc di
    jmp .loop
.term:
    mov byte [di], 0
    pop ax
    ret

; =============================================================================
; Window template, menu, strings
; =============================================================================
sh_tpl:
    dw 60, 40, 560, 380
    dw sh_ttlbuf, sh_paint, sh_onkey, sh_onclick

; The EMPTY kernel menu set (SPEC.md 12.2), same idea as apps/word/word.asm's
; wd_menus0: zero real menus, but its AM_NAME still puts 'Sheet' in the
; kernel bar. sh_mf_ret can never actually be called (there is nothing to
; pick) - it only satisfies the macro's layout.
    OS88_MENUSET sh_menus, sh_s_appname, sh_mf_ret
    OS88_MENUSET_END sh_menus
sh_mf_ret:
    ret

; sh_mtab - Sheet's own in-window menu bar (see the SH_MBAR_H section
; comment). Each entry: title string ptr, item string-ptr array, item
; count (word each, so 6 bytes/entry) - menu index 0..SH_MENU_N-1 is this
; array's own order, which sh_mfire's dispatch and sh_docmd_sortcol/
; sh_docmd_options/sh_docmd_help all key off directly.
; Stage 3.0b puts FORMULA at index 2, which is where Excel 2.1d has it -
; File Edit Formula Format Data Options Macro Window Help. Sheet's own
; multi-sheet menu stands in for Window and now sits where Window does, after
; Macro. Every index below 2 is unchanged and everything above it shifted, so
; sh_mfire's dispatch chain moved with it; nothing else in this file keys off a
; menu index (the macro language names commands, not menu positions), which is
; what made the renumber safe to do at all.
sh_mtab:
    dw sh_m_file,    sh_i_file,    5
    dw sh_m_edit,    sh_i_edit,    SH_EI_N
    dw sh_m_formula, sh_i_formula, 7
    dw sh_m_format,  sh_i_format,  8
    dw sh_m_data,    sh_i_data,    SH_DATA_N
    dw sh_m_options, sh_i_options, SH_OI_N
    dw sh_m_macro,   sh_i_macro,   SH_MAI_N
    dw sh_m_sheet,   sh_i_sheet,   SH_SHEETS
    dw sh_m_help,    sh_i_help,    1
    times SH_MCUST * 6 db 0           ; 81.95: custom menus added to this bar

; Excel 2.1d's Formula menu, in its own order: Paste Name.../Paste Function.../
; Reference/Define Name.../Note.../Goto.../Find... - all seven now. The note
; this replaced said the rest would arrive with the features behind them rather
; than as items that open nothing, and that is what happened: the list dialog
; is what Paste Name and Paste Function were waiting on, the name table is what
; Define Name needed, and Reference had nowhere to show its answer until the
; reference box existed.
sh_m_formula:    db 'Formula', 0
sh_i_formula:                             ; LABELLED like sh_i_data's and
.pname:          dw sh_it_pname           ; sh_i_file's, so a gate names the
.pfunc:          dw sh_it_pfunc           ; row it wants instead of counting
.reference:      dw sh_it_refdis          ; to it (81.114.8's rule)
.defname:        dw sh_it_defname
.note:           dw sh_it_note
.goto:           dw sh_it_goto
.find:           dw sh_it_find
sh_it_pname:     db 'Paste Name...', 0
sh_it_pfunc:     db 'Paste Function...', 0
sh_it_refdis:    db MENU_DIS, 'Reference', 0   ; 81.108: Excel's meaning -
sh_it_ref:       db 'Reference', 0     ; cycle the reference at the caret
                                       ; A1 > $A$1 > A$1 > $A1 > A1 - and so
                                       ; GREYED except while a formula is
                                       ; being entered (sh_refmark). Its old
                                       ; job, A1/R1C1, is Workspace's (81.106)
sh_it_defname:   db 'Define Name...', 0
sh_it_note:      db 'Note...', 0
sh_it_goto:      db 'Goto...', 0
sh_it_find:      db 'Find...', 0

; 81.75: the kernel menu bar's AM_NAME, and (81.103) the prefix of the window
; title, which is sh_ttl_pre + the document's name in sh_ttlbuf now. The
; PACKAGE name in OS88_HEADER is PLAN; these are what the user reads, so they
; have to agree with it - a window captioned "Sheet" launched from PLAN.O88 is
; two things answering to one name, which is the rule (73.12) this build
; exists to keep on the right side of.
sh_s_appname:  db 'Sheet', 0
sh_m_file:     db 'File', 0
sh_i_file:                                ; LABELLED like sh_i_data's, so a
.new:          dw sh_it_new                ; gate names a row instead of
.open:         dw sh_it_open               ; counting one (sheetfmt's
.save:         dw sh_it_save               ; item_index - 81.114.8's rule
.saveas:       dw sh_it_saveas             ; about a row that moves)
.fdelete:      dw sh_it_fdelete
sh_it_new:     db 'New...', 0
sh_it_open:    db 'Open...', 0
sh_it_save:    db 'Save', 0
sh_it_saveas:  db 'Save As...', 0
sh_it_fdelete: db 'Delete...', 0         ; 81.79. Excel puts it after Save As,
                                          ; which here is the END of the menu -
                                          ; so unlike 81.78's Calculate Now no
                                          ; index moves and no dispatch shifts
sh_s_delq:     db 'Delete this file?', 0  ; os88ui_ask clips at 34 characters
sh_s_deleted:  db 'Deleted.', 0
sh_s_delfail:  db 'Could not delete it.', 0
; NO PRINT ITEM. OS8088 has no print backend, so the menu entry is absent
; rather than present-and-refusing (decided 2026-09-04). Exit is absent for a
; different reason - the OS menu owns it.
;
; NO CLOSE ITEM EITHER, and it is Exit's reason with one more step (81.39.2,
; measured 2026-09-20). Excel's Close shuts one DOCUMENT window because Excel
; is MDI - Close ends a document, Exit ends the application. This app has one
; document per instance and the window's own close box already ends both, so
; a Close item would be a second name for the close box and would express no
; distinction this app HAS. It is a deliberate absence, not an outstanding
; gap: what would make it meaningful is MDI, which 81.75 records as the one
; thing the 1.8 look leaves out on purpose.
sh_s_nocopyarea: db 'Copy a cell or range first.', 0
sh_s_sheetpfx: db 'Sheet', 0
sh_s_locked:   db 'Locked cell on a protected document.', 0
sh_s_tblpart:  db 'Cannot change part of a table.', 0
sh_s_protdoc:  db 'The document is protected.', 0

; Stage 1.8/2.x: matches real Excel 2.0/2.1's own Format menu shape
; (LIBRARY/documentation/screenshots/excel/menu_format.png) -
; Number.../Alignment.../Font... open
; dialogs (sh_docmd_format's AL 0/1/2 is sh_fdlg_open's own kind number, so
; this array's first 3 entries must stay in that order). Border... is real
; (sh_bdlg_*). Row Height.../Column Width... are real too and take A TYPED
; NUMBER: SH_ID_ROWH/SH_ID_COLW through sh_idlg_open, in CHARACTERS for the
; width because that is Excel's own unit, range-checked SH_CW_MINCH..MAXCH.
;
; This said "a 3-preset radio pick ... since this app has no text-input widget
; at the app level" until 2026-09-03, and stage 3.0c had replaced both halves
; of that long before: os88line.inc gave the app a text field and
; sh_docmd_format says so in its own comment two screens up ("a typed number
; now, not the 3-preset radio pick this had to be while no text field
; existed"). Read as current it understates the app by a whole feature, and it
; did - it is where the claim "Column Width is three presets" in an assessment
; of what SHEET still lacks came from.
;
; The other half - that it applied to the WHOLE sheet - went too: 81.56 made
; the widths per column and 81.60 the heights per row, the height in POINTS
; because that is Excel's unit for it. sh_gridhit walks both now.
sh_m_format:    db 'Format', 0
; LIBRARY/documentation/screenshots/excel/menu_format_full.png:
; Number/Alignment/Font/Border/CELL PROTECTION/Row Height/Column
; Width/Justify. Cell Protection sits between
; Border and Row Height, which is not where it would have been guessed.
; 81.81: Justify is APPENDED. Excel 2.1d's Format is Number/Alignment/Font/
; Border/Cell Protection/Row Height/Column Width/Justify, so the missing item
; is the LAST one and no index below it moved - File > Delete's happy case
; again (81.79), and the opposite of what Short Menus would have been
; (dropped by the owner, 2026-09-22).
sh_i_format:    dw sh_it_fnum, sh_it_falign, sh_it_ffont, sh_it_fborder, sh_it_fprot, sh_it_frowh, sh_it_fcolw, sh_it_fjust
sh_it_fprot:     db 'Cell Protection...', 0
sh_it_fnum:      db 'Number...', 0
sh_it_falign:    db 'Alignment...', 0
sh_it_ffont:     db 'Font...', 0
sh_it_fborder:   db 'Border...', 0
sh_it_frowh:     db 'Row Height...', 0
sh_it_fcolw:     db 'Column Width...', 0
sh_it_fjust:     db 'Justify', 0    ; no ellipsis: it asks only when it has to

; Stage 2.0: the Sheet menu switches which of this instance's SH_SHEETS
; grids is active (see the multi-sheet cell-record comment above
; sh_findcell for why this lives in one instance rather than several).
; Sheet names are the fixed strings below, not user-renameable in this
; stage - simpler, and a macro's "SheetN!" reference (see sh_pident) needs
; a name it can recognize regardless of what the user might have typed.
sh_m_sheet:    db 'Sheets', 0
sh_i_sheet:                          ; one label a row, sh_i_edit's shape, so
.sheet1:       dw sh_it_sheet1       ; the row NUMBER is addressable by name
.sheet2:       dw sh_it_sheet2
.sheet3:       dw sh_it_sheet3
.sheet4:       dw sh_it_sheet4
sh_it_sheet1:  db 'Sheet1', 0
sh_it_sheet2:  db 'Sheet2', 0
sh_it_sheet3:  db 'Sheet3', 0
sh_it_sheet4:  db 'Sheet4', 0
; ...and the same four with the mark, which sh_sheetmark repoints between.
sh_it_sheet1c: db SH_MENU_CHK, 'Sheet1', 0
sh_it_sheet2c: db SH_MENU_CHK, 'Sheet2', 0
sh_it_sheet3c: db SH_MENU_CHK, 'Sheet3', 0
sh_it_sheet4c: db SH_MENU_CHK, 'Sheet4', 0
sh_sheet_plain: dw sh_it_sheet1, sh_it_sheet2, sh_it_sheet3, sh_it_sheet4
sh_sheet_chk:   dw sh_it_sheet1c, sh_it_sheet2c, sh_it_sheet3c, sh_it_sheet4c

; Stage 2.0: no generic text-prompt dialog exists in this OS (only a FILE
; picker), so "Run" starts a macro at whatever cell is CURRENTLY SELECTED,
; rather than asking for a typed/picked starting reference - see the
; Macro engine section comment for the full reasoning.
; Excel's own Macro menu is Record.../Run.../Start Recorder/Set Recorder/
; Relative Record. 81.74 adds three of the four it was missing; Start
; Recorder and Resume are that section's own documented shortfalls.
sh_m_macro:    db 'Macro', 0
; 81.107: Excel's five, in Excel's order - Start Recorder is third. Rows are
; dispatched by POSITION, so each has a name and a times pair (81.99)
sh_i_macro:
.record:   dw sh_it_recon
.run:      dw sh_it_run
.start:    dw sh_it_startdis
.setrec:   dw sh_it_setrec
.rel:      dw sh_it_relrec
.end:
%macro SH_MAIROW 2
    times ((sh_i_macro.%1 - sh_i_macro) / 2 - (%2)) db 0
    times ((%2) - (sh_i_macro.%1 - sh_i_macro) / 2) db 0
%endmacro
    SH_MAIROW record, SH_MAI_RECORD
    SH_MAIROW run, SH_MAI_RUN
    SH_MAIROW start, SH_MAI_START
    SH_MAIROW setrec, SH_MAI_SETREC
    SH_MAIROW rel, SH_MAI_REL
    SH_MAIROW end, SH_MAI_N
sh_it_startrec: db 'Start Recorder', 0     ; 81.107: live only with a recorder
sh_it_startdis: db MENU_DIS, 'Start Recorder', 0   ; range and none running
sh_it_run:     db 'Run', 0
sh_it_recon:   db 'Record...', 0     ; 81.74, relabelled while a recording is
sh_it_recoff:  db 'Stop Recorder', 0 ; live - Excel's own pair
sh_it_setrec:  db 'Set Recorder', 0
sh_it_relrec:  db 'Relative Record', 0   ; ...and this one names what choosing
sh_it_absrec:  db 'Absolute Record', 0   ; it WOULD do, as Excel's does

; Edit - "Can't Undo" is a real Excel item with no real implementation
; behind it (no undo system exists) - shown disabled (MENU_DIS) rather than
; omitted, same honesty as Format's Border/Row Height/Column Width
; placeholders. Sort Column now lives in its own Data menu (below) - it
; only had to share Edit's list while the bar was the kernel's own
; MENU_APPMAX=5 one; Sheet's own in-window bar (sh_mtab) has no such cap.
; SH_MENU_CHK is Sheet's own leading-byte convention beside the kernel's
; MENU_DIS: the item is drawn with a check in the left margin. It is 2 rather
; than 1 so the two can never be confused, and sh_mdrop_draw handles both.
sh_m_edit:     db 'Edit', 0
; READ OFF THE REAL MENU
; (LIBRARY/documentation/screenshots/excel/menu_edit_full.png, and the
; Reference Guide's own picture of it on p.117) - less Repeat since 81.99:
; Can't Undo / Can't Repeat /
; Cut / Copy / Paste / Clear... / Paste Special... / Paste Link / Delete... /
; Insert... / Fill Right / Fill Down. PASTE SPECIAL AND PASTE LINK COME
; AFTER CLEAR, not after Paste, which is where they would have gone from
; memory.
; 81.99: Repeat is GONE from this list - the owner's decision, 2026-09-22 -
; so SHEET's Edit is Excel's less its second row. Each row has a label, and
; the TIMES pairs below hold it to its SH_EI_ constant: moving a row without
; its constant, or the reverse, fails the build on that row's own line
sh_i_edit:
.undo:     dw sh_it_undo
.cut:      dw sh_it_cut
.copy:     dw sh_it_copy
.paste:    dw sh_it_paste
.clear:    dw sh_it_clear
.pastesp:  dw sh_it_pastesp
.pastelk:  dw sh_it_pastelk
.delete:   dw sh_it_delete
.insert:   dw sh_it_insert
.fillr:    dw sh_it_fillright
.filld:    dw sh_it_filldown
.end:
%macro SH_EIROW 2
    times ((sh_i_edit.%1 - sh_i_edit) / 2 - (%2)) db 0
    times ((%2) - (sh_i_edit.%1 - sh_i_edit) / 2) db 0
%endmacro
    SH_EIROW undo, SH_EI_UNDO
    SH_EIROW cut, SH_EI_CUT
    SH_EIROW copy, SH_EI_COPY
    SH_EIROW paste, SH_EI_PASTE
    SH_EIROW clear, SH_EI_CLEAR
    SH_EIROW pastesp, SH_EI_PASTESP
    SH_EIROW pastelk, SH_EI_PASTELK
    SH_EIROW delete, SH_EI_DELETE
    SH_EIROW insert, SH_EI_INSERT
    SH_EIROW fillr, SH_EI_FILLR
    SH_EIROW filld, SH_EI_FILLD
    SH_EIROW end, SH_EI_N
sh_it_undo:    db MENU_DIS, "Can't Undo", 0     ; REWRITTEN by sh_undo_label
               times 10 db 0                      ; (81.57): "Undo Paste Special"
                                                  ; and its NUL fit the slack
sh_it_pastesp: db 'Paste Special...', 0
sh_it_pastelk: db 'Paste Link', 0
sh_it_cut:     db 'Cut', 0
sh_it_copy:    db 'Copy', 0
sh_it_paste:   db 'Paste', 0
sh_it_clear:   db 'Clear...', 0
sh_it_delete:  db 'Delete...', 0
sh_it_insert:  db 'Insert...', 0
sh_it_fillright: db 'Fill Right', 0
sh_it_filldown:  db 'Fill Down', 0

; Data - real Excel 2.1 keeps Sort here, not in Edit. Chart Column.../Export
; Chart as BMP... are stage 2.x's own addition (no real-Excel Data menu
; equivalent - Excel's own charting is a whole separate document type) -
; see sh_docmd_chart's header comment for the design.
;
; 81.71 put the first six in EXCEL'S OWN ORDER (menu_data_full.png): Form,
; Find, Extract, Delete, Set Database, Set Criteria, then Sort. Sort moved
; from index 0 to 6 and the three chart items after it, which is a real cost
; paid once - the whole reason this package has a menu bar of its own is to
; look like the captures.
sh_m_data:     db 'Data', 0
; ONE LABEL A ROW, sh_i_edit's shape, so the row NUMBER is addressable by
; name - from the assembler's map by a test, and from here by a reader. Data
; > Table... going in at index 8 pushed Parse to 9 and broke three rows that
; had counted, and counting is the good case: a shifted index that lands on
; another LIVE item runs the wrong command and blames the feature.
sh_i_data:
.form:      dw sh_it_form
.dfind:     dw sh_it_dfind
.extract:   dw sh_it_extract
.del:       dw sh_it_del
.setdb:     dw sh_it_setdb
.setcrit:   dw sh_it_setcrit
.sort:      dw sh_it_sort
.series:    dw sh_it_series
.dtable:    dw sh_it_dtable                         ; 81.114, BETWEEN Series
                                                    ; and Parse - the capture
                                                    ; (menu_data_full.png) is
                                                    ; where that order comes
                                                    ; from, not from memory
.parse:     dw sh_it_parse                          ; 81.82, in Excel's place
.chart:     dw sh_it_chart
.gallery:   dw sh_it_gallery
.chartexp:  dw sh_it_chartexp
sh_it_dtable:  db 'Table...', 0
sh_it_parse:   db 'Parse...', 0
sh_it_form:    db 'Form...', 0
sh_it_dfind:   db 'Find', 0              ; 81.71, relabelled in place while a
sh_it_exitfnd: db 'Exit Find', 0         ; find is live - Excel's own item
sh_it_extract: db 'Extract...', 0
sh_it_del:     db 'Delete', 0            ; NOT sh_it_delete: that is Edit's
                                          ; own 'Delete...', which shifts
                                          ; cells rather than records
sh_it_sort:    db 'Sort...', 0
sh_it_series:  db 'Series...', 0
sh_it_chart:   db 'Chart Column...', 0
sh_it_gallery: db 'Chart Gallery...', 0
sh_it_chartexp: db 'Export Chart as BMP...', 0
sh_it_setdb:   db 'Set Database', 0
sh_it_setcrit: db 'Set Criteria', 0

; Options - Display toggles (stage 2.x). Each item's own string SWAPS
; between an On/Off pair (same relabel-by-repointing idea MENU_DIS's own
; doc shows) rather than drawing a separate checkmark glyph.
sh_m_options:  db 'Options', 0
; Real Excel's Options menu puts Protect Document... between Display... and
; Calculation...
; (LIBRARY/documentation/screenshots/excel/menu_options_full.png). Gridlines
; and Formulas are items here where Excel keeps them inside Display... - that
; divergence is 81.31's, not this one's.
; 81.106: EXCEL'S ORDER, less the three print items and Short Menus (both
; decided out): Display..., Freeze Panes, Protect Document, Calculation...,
; Calculate Now, Workspace.... Gridlines and Formulas were two relabelling
; toggles here; in Excel they are check boxes in Display..., and A1/R1C1 is
; one in Workspace..., so that is where they are. Rows are dispatched by
; POSITION, so each has a name and a times pair (81.99's care)
sh_i_options:
.display:   dw sh_it_display
.freeze:    dw sh_it_frz_off
.protect:   dw sh_it_prot_off
.calc:      dw sh_it_calc
.calcnow:   dw sh_it_calcnow
.workspace: dw sh_it_workspace
.end:
%macro SH_OIROW 2
    times ((sh_i_options.%1 - sh_i_options) / 2 - (%2)) db 0
    times ((%2) - (sh_i_options.%1 - sh_i_options) / 2) db 0
%endmacro
    SH_OIROW display, SH_OI_DISPLAY
    SH_OIROW freeze, SH_OI_FREEZE
    SH_OIROW protect, SH_OI_PROT
    SH_OIROW calc, SH_OI_CALC
    SH_OIROW calcnow, SH_OI_CALCNOW
    SH_OIROW workspace, SH_OI_WORKSPACE
    SH_OIROW end, SH_OI_N
sh_it_display:   db 'Display...', 0
sh_it_workspace: db 'Workspace...', 0
sh_it_prot_off: db 'Protect Document', 0
sh_it_prot_on:  db 'Unprotect Document', 0
sh_it_calc:     db 'Calculation...', 0
sh_it_calcnow:  db 'Calculate Now', 0    ; 81.78: Excel puts it immediately
                                          ; after Calculation...
sh_it_frz_off:  db 'Freeze Panes', 0     ; 81.70, relabelled like Protect
sh_it_frz_on:   db 'Unfreeze Panes', 0   ; Document rather than ticked; second
                                          ; since 81.106, as Excel has it
sh_s_frz_at_a1: db 'Select below or right of the split first.', 0

; Help
sh_m_help:     db 'Help', 0
sh_i_help:
.about:        dw sh_it_about               ; labelled, like sh_i_file's
sh_it_about:   db 'About Sheet...', 0
; --- the About card's lines (SPEC.md 20.5.1) ----------------------------------
; SHEET'S OWN VERSION, and it is this package's and NOT the system's: the
; About box of os8088 itself carries `os8088 1.0` (SPEC.md 14.2, a different
; number with a different meaning, and tools/os88sym.py searches the kernel
; image for that exact string). This one is named once here so that the card
; below and SPEC.md 81 cannot drift apart.
;
; 2.1 is the roadmap's, not a count of releases: SHEET is an Excel 2.1d
; imitation and the stages that carried it there are 81's (1.x the grid and
; the formats, 2.0 the macro language, 3.0 the UI, 4.x the arithmetic).
%define SH_VER '2.1'
sh_ablines:
    dw sh_ab1, sh_ab2, sh_ab3, sh_ab4, 0
sh_ab1:        db 'Sheet for os8088', 0
sh_ab2:        db 'A spreadsheet in the shape of Excel 2.1d', 0
sh_ab3:        db 'Version ', SH_VER, 0      ; the line was EMPTY, which is
                                              ; what the card uses for a gap
sh_ab4:        db 'Contributed by Koriban', 0

sh_defname:    db 'SHEET1.SLK', 0
sh_s_ready:    db 'Ready', 0
sh_s_badparen: db 'Unbalanced ( ) - kept as text.', 0
sh_s_num:      db 'NUM', 0
sh_s_calcind:  db 'CALCULATE', 0
sh_s_nw_sheet: db 'New worksheet.', 0
sh_s_nw_chart: db 'New sheet - use Data > Chart Column to chart it.', 0
sh_s_nw_macro: db 'New macro sheet - formulas shown; Macro > Run runs them.', 0
sh_s_calc_auto: db 'Calculation: Automatic', 0
sh_s_calc_auex: db 'Calculation: Automatic except Tables.', 0
sh_s_calc_man:  db 'Calculation: Manual - Calculate Now to recompute.', 0
sh_s_calc_now:  db 'Recalculated.', 0
sh_s_ju_done:   db 'Justified.', 0
sh_s_pa_done:   db 'Parsed.', 0
sh_s_pa_nobrk:  db 'Put brackets round the fields, or press Guess.', 0
sh_s_idlg_guess: db 'Guess', 0
sh_s_idlg_clear: db 'Clear', 0
sh_s_ju_notext: db 'Justify needs text or blank cells.', 0
sh_s_ju_toobig: db 'Select more rows - the text needs them.', 0
sh_s_id:       db 'ID;PWXL;N;E', 13, 10, 0
sh_s_c:        db 'C;X', 0
sh_s_y:        db ';Y', 0
sh_s_e:        db ';E', 0                  ; the expression field (stage 4.x)
sh_s_k:        db ';K', 0                  ; also the "commas are set" flag
                                            ; on an F record (stage 1.6)
sh_s_sylk_fw:  db 'F;W', 0                 ; F;W<first> <last> <width> (81.56)
sh_s_sylk_fx:  db 'F;X', 0                 ; an F (formatting) record -
sh_s_sylk_ff:  db ';F', 0                  ; stage 1.6's real SYLK support
sh_s_sylk_fs:  db ';S', 0                  ; the style field: borders, shade
sh_s_sylk_fa:  db ';A', 0                  ; a C record's comment: the note
sh_sylk_bordch: db 'LRTBS', 0              ; SH_BORD_* bit order (81.119.2)
sh_s_crlf:     db 13, 10, 0
sh_s_nn:       db 'NN;N', 0           ; SYLK's defined-name record (81.29.1)
sh_s_nne:      db ';E', 0
sh_s_colon:    db ':', 0
sh_s_r:        db 'R', 0
sh_s_cu:       db 'C', 0
sh_s_end:      db 'E', 13, 10, 0
sh_m_saved:    db 'Saved', 0
sh_s_askpre:   db 'Save changes to ', 0   ; SPEC.md 75.3's question (81.118)
sh_m_trunc:    db 'Saved - TRUNCATED; sheet too large for this format.', 0
sh_m_loaded:   db 'Loaded', 0
sh_f_sum:      db 'SUM', 0
sh_f_average:  db 'AVERAGE', 0
sh_f_min:      db 'MIN', 0
sh_f_max:      db 'MAX', 0
sh_f_count:    db 'COUNT', 0
sh_f_if:       db 'IF', 0
sh_f_not:      db 'NOT', 0
sh_f_abs:      db 'ABS', 0
sh_f_and:      db 'AND', 0
sh_f_or:       db 'OR', 0
; stage 3.0d. ORDER IS THE ID - sh_functab below indexes by position and
; sh_pfunc/sh_foldvalue/sh_pspecial switch on that number, so entries may be
; APPENDED but never reordered or removed.
sh_f_product:  db 'PRODUCT', 0
sh_f_counta:   db 'COUNTA', 0
sh_f_mod:      db 'MOD', 0
sh_f_int:      db 'INT', 0
sh_f_trunc:    db 'TRUNC', 0
sh_f_sign:     db 'SIGN', 0
sh_f_fact:     db 'FACT', 0
sh_f_sqrt:     db 'SQRT', 0
sh_f_power:    db 'POWER', 0
sh_f_round:    db 'ROUND', 0
sh_f_true:     db 'TRUE', 0
sh_f_false:    db 'FALSE', 0
sh_f_row:      db 'ROW', 0
sh_f_column:   db 'COLUMN', 0
sh_f_choose:   db 'CHOOSE', 0
; stage 4.5: the INFORMATION functions. Absent until now because an argument
; was folded to a value before the function saw it - see sh_pargclass.
sh_f_isblank:  db 'ISBLANK', 0
sh_f_isnumber: db 'ISNUMBER', 0
sh_f_istext:   db 'ISTEXT', 0
sh_f_islogicl: db 'ISLOGICAL', 0
sh_f_iserror:  db 'ISERROR', 0
sh_f_iserr:    db 'ISERR', 0
sh_f_isna:     db 'ISNA', 0
sh_f_isref:    db 'ISREF', 0
sh_f_na:       db 'NA', 0
sh_f_type:     db 'TYPE', 0
sh_f_n:        db 'N', 0
sh_f_errtype:  db 'ERROR.TYPE', 0     ; the only name here with a '.' in it,
                                       ; which is what sh_pident's .trydot is
                                       ; for
; stage 4.5: the TEXT functions - Excel 2.1's own category, less the seven
; that search and format
