                                       ; bottom of the string stack

; sh_functab - the id is the INDEX. 0 terminates.
sh_functab:
    dw sh_f_sum, sh_f_average, sh_f_min, sh_f_max, sh_f_count
    dw sh_f_if, sh_f_not, sh_f_abs, sh_f_and, sh_f_or
    dw sh_f_product, sh_f_counta, sh_f_mod, sh_f_int, sh_f_trunc
    dw sh_f_sign, sh_f_fact, sh_f_sqrt, sh_f_power, sh_f_round
    dw sh_f_true, sh_f_false, sh_f_row, sh_f_column, sh_f_choose
    dw sh_f_isblank, sh_f_isnumber, sh_f_istext, sh_f_islogicl, sh_f_iserror
    dw sh_f_iserr, sh_f_isna, sh_f_isref, sh_f_na, sh_f_type
    dw sh_f_n, sh_f_errtype
    dw sh_f_len, sh_f_left, sh_f_right, sh_f_mid, sh_f_upper
    dw sh_f_lower, sh_f_proper, sh_f_trim, sh_f_rept, sh_f_char
    dw sh_f_code, sh_f_exact, sh_f_t, sh_f_value
    dw sh_f_find, sh_f_search, sh_f_subst, sh_f_replace, sh_f_text
    dw sh_f_dollar, sh_f_fixed
    dw sh_f_date, sh_f_day, sh_f_month, sh_f_year, sh_f_weekday
    dw sh_f_time, sh_f_hour, sh_f_minute, sh_f_second, sh_f_datevalue
    dw sh_f_timevalue
    dw sh_f_rows, sh_f_columns, sh_f_areas, sh_f_index
    dw sh_f_match, sh_f_vlookup, sh_f_hlookup, sh_f_lookup
    dw sh_f_var, sh_f_varp, sh_f_stdev, sh_f_stdevp
    dw sh_f_ln, sh_f_log10, sh_f_exp, sh_f_pi, sh_f_log
    dw sh_f_sin, sh_f_cos, sh_f_tan, sh_f_asin, sh_f_acos
    dw sh_f_atan, sh_f_atan2
    dw sh_f_sln, sh_f_syd, sh_f_pmt, sh_f_pv, sh_f_fv, sh_f_npv
    dw sh_f_nper, sh_f_ddb, sh_f_ipmt, sh_f_ppmt, sh_f_rate
    dw sh_f_irr, sh_f_mirr
    dw sh_f_now                       ; 106 (81.42)
    dw sh_f_isnontext, sh_f_clean, sh_f_rand   ; 107 108 109 (81.43)
    dw sh_f_indirect                  ; 110 (81.44)
sh_functab_mac0:                      ; 81.83: the macro run's own index, so
                                      ; SH_FN_MAC0 below is DERIVED and a row
                                      ; inserted above it cannot silently
                                      ; point the Cetab flags at the wrong
                                      ; twenty functions
    dw sh_f_goto, sh_f_return, sh_f_halt, sh_f_setvalue, sh_f_select ; 111- :
    dw sh_f_formula, sh_f_alert, sh_f_message, sh_f_beep, sh_f_input  ; the
    dw sh_f_for, sh_f_while, sh_f_next, sh_f_break, sh_f_actcell     ; MACRO
    dw sh_f_copy, sh_f_cut, sh_f_paste, sh_f_clear, sh_f_calcnow     ; (81.63)
    dw sh_f_daverage, sh_f_dcount, sh_f_dcounta, sh_f_dmax, sh_f_dmin ; 131- :
    dw sh_f_dproduct, sh_f_dstdev, sh_f_dstdevp, sh_f_dsum, sh_f_dvar ; the
    dw sh_f_dvarp                                                    ; DATABASE
                                                                      ; functions (81.65)
    dw sh_f_cell                      ; 142 (81.66)
    dw sh_f_mdeterm, sh_f_minverse, sh_f_mmult, sh_f_transpose        ; 143- :
    dw sh_f_linest, sh_f_logest, sh_f_trend, sh_f_growth              ; ARRAY/
                                                                      ; MATRIX (81.67)
    dw 0
sh_functab_end:
; -----------------------------------------------------------------------------
; FOUR TABLES INDEXED BY THE SAME NUMBER, and nothing used to check they were
; the same length. sh_rpn_func indexes sh_rpn_fid and sh_rpn_fvar by the id
; sh_funcid returns, which is a position in sh_functab - so appending a
; function here and forgetting one of the other two reads whatever byte
; follows it and writes THAT as the BIFF function index. A wrong number in a
; saved file, no crash, no message. These four TIMES lines make it a build
; error instead, the same idiom OS88_BSS's literal uses; read the LINE NUMBER
; to see which table is short.
; -----------------------------------------------------------------------------
%define SH_NFUNCS ((sh_functab_end - sh_functab) / 2 - 1)
                                       ; a build without it has only the one
    times ((sh_rpn_fid_end - sh_rpn_fid) - SH_NFUNCS) db 0
    times (SH_NFUNCS - (sh_rpn_fid_end - sh_rpn_fid)) db 0
    times ((sh_rpn_fvar_end - sh_rpn_fvar) - SH_NFUNCS) db 0
    times (SH_NFUNCS - (sh_rpn_fvar_end - sh_rpn_fvar)) db 0
    times ((sh_rpn_fargc_end - sh_rpn_fargc) - SH_NFUNCS) db 0
    times (SH_NFUNCS - (sh_rpn_fargc_end - sh_rpn_fargc)) db 0
sh_s_errpfx:   db 'Err ', 0
section SH_MODSEC                      ; 82.16.9's tenant: CSV and TXT (81.40)

; =============================================================================
; CSV and TAB-DELIMITED TEXT (81.40).
;
; Excel 2.0's own open/save list (Reference Guide p.273) is .XLS/.XLC/.XLM/.XLW,
; .TXT, .CSV, .SLK, .WKS, .WK1, .DIF and .DBF - so these two are not an
; extension of the era's Excel, they are two of the nine it had and this app
; did not. They are ONE writer and ONE reader with a delimiter in [sh_sepch],
; because the only difference between them is that byte.
;
; QUOTING IS CSV'S, NOT DIF'S. A field carrying the delimiter, a quote, a CR
; or an LF is wrapped in quotes and its own quotes are doubled - the same rule
; SYLK uses for ';' (81.38.1) and the one that makes a field with a comma in it
; survive. DIF drops an embedded quote instead (see sh_dowrite_dif's .dt),
; which is right for DIF because DIF has no escape at all; CSV does.
; =============================================================================
section SH_MODSEC                      ; 82.16.9's tenant: dBASE III (81.41)

; =============================================================================
; dBASE III .DBF (81.41).
;
; Excel 2.0 listed .DBF twice in its open/save table and its Save As help says
; what for: "For transferring the database range to dBASE II" / "...dBASE III".
; dBASE was the era's database and this was the wire between them, so a 2.1d
; spreadsheet without it is missing the thing the format existed for.
;
; DBASE III ONLY (version byte 03H). dBASE II's header is a different shape and
; is not written or read here; a II file is refused by its version byte rather
; than misread.
;
; ROW 0 IS THE FIELD NAMES, which is Excel's own database-range convention -
; the range's first row names the fields. A blank header cell falls back to the
; column's letter, because a nameless field is not representable.
;
; THE HEADER'S DATE STAMP IS ZERO. dBASE III keeps YY/MM/DD of the last update
; in bytes 1..3, and THIS OS EXPOSES NO DATE TO A PACKAGE: the kernel has
; clk_year/clk_mon/clk_day and no OSAPI slot reaches them. Zero is what a tool
; that does not know writes, and it is honest; inventing a date would not be.
; (It is the same absence that stops NOW being implementable - see 81.39.)
; =============================================================================
SH_DBF_MAXF  equ 128                ; dBASE III's own field ceiling
SH_DBF_HDR   equ 32                 ; the file header, and each descriptor

sh_dowrite_dbf:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    call shm_difbbox
    mov byte [sh_trunc], 0
    call sh_dbf_scan                  ; -> nf, and per-field type/width/dec
    mov es, [sh_stgseg]
    ; --- the 32-byte file header -------------------------------------------
    xor di, di
    mov al, 0x03                      ; dBASE III, no memo file
    call sh_stgputb
    SHOUT sh_bios_ymd                 ; the last-update stamp, from the BIOS
    jc .nodate                        ; clock (81.42) - zeros if there is none
    mov ax, [sh_dt_y]
    sub ax, 1900                      ; dBASE III keeps YY, not the century
    call sh_stgputb
    mov ax, [sh_dt_m]
    call sh_stgputb
    mov ax, [sh_dt_d]
    call sh_stgputb
    jmp .datedone
.nodate:
    xor al, al
    call sh_stgputb                   ; YY
    call sh_stgputb                   ; MM
    call sh_stgputb                   ; DD
.datedone:
    mov ax, [sh_dbf_nr]
    call sh_dbf_putw                  ; record count, low word...
    xor ax, ax
    call sh_dbf_putw                  ; ...and high: 65535 records is plenty
    mov ax, [sh_dbf_nf]
    mov cl, 5
    shl ax, cl                        ; nf * 32
    add ax, SH_DBF_HDR + 1            ; + this header + the 0Dh terminator
    call sh_dbf_putw
    mov ax, [sh_dbf_rl]
    call sh_dbf_putw
    mov cx, 20                        ; 12..31 reserved
.hz:
    xor al, al
    call sh_stgputb
    loop .hz
    ; --- one 32-byte descriptor per field ----------------------------------
    mov word [sh_wcol], 0
.dloop:
    mov ax, [sh_wcol]
    cmp ax, [sh_dbf_nf]
    jae .dend
    call sh_dbf_name                  ; -> sh_numbuf, <=10 chars, uppercased
    mov cx, 11
    mov si, sh_numbuf
.dn:
    mov al, [si]
    or al, al
    jz .dnpad
    inc si
    call sh_stgputb
    dec cx
    jnz .dn
    jmp .dnend
.dnpad:
    xor al, al
    call sh_stgputb
    dec cx
    jnz .dnpad
.dnend:
    mov bx, [sh_wcol]
    mov al, [bx+sh_dbf_ty]
    call sh_stgputb                   ; the type letter
    mov cx, 4
.dr1:
    xor al, al
    call sh_stgputb
    loop .dr1
    mov bx, [sh_wcol]
    mov al, [bx+sh_dbf_w]
    call sh_stgputb                   ; length
    mov bx, [sh_wcol]
    mov al, [bx+sh_dbf_d]
    call sh_stgputb                   ; decimal count
    mov cx, 14
.dr2:
    xor al, al
    call sh_stgputb
    loop .dr2
    inc word [sh_wcol]
    jmp .dloop
.dend:
    mov al, 0x0D                      ; the descriptor terminator
    call sh_stgputb
    ; --- the records --------------------------------------------------------
    mov word [sh_wrow], 1             ; row 0 was the field names
.rloop:
    mov ax, [sh_wrow]
    cmp ax, [sh_bbrow]
    ja .footer
    mov ax, di
    add ax, [sh_dbf_rl]
    add ax, 2
    cmp ax, SH_STAGE_MAX
    ja .truncf
    mov al, ' '                       ; 20h = an ACTIVE record (2Ah = deleted)
    call sh_stgputb
    mov word [sh_wcol], 0
.floop:
    mov ax, [sh_wcol]
    cmp ax, [sh_dbf_nf]
    jae .rnext
    call sh_dbf_cellstr               ; -> sh_numbuf, this cell as text
    call sh_dbf_putfield              ; padded to its field's width
    inc word [sh_wcol]
    jmp .floop
.rnext:
    inc word [sh_wrow]
    jmp .rloop
.truncf:
    mov byte [sh_trunc], 1
.footer:
    mov al, 0x1A                      ; the end-of-file marker
    call sh_stgputb
    mov [sh_stagelen], di
    mov ax, [sh_stgseg]
    mov es, ax
    xor bx, bx
    mov cx, [sh_stagelen]
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_WRITE
    jc .werr
    mov word [sh_msg], sh_m_saved
    cmp byte [sh_trunc], 0
    je .wdone
    mov word [sh_msg], sh_m_trunc
    jmp .wdone
.werr:
    call sh_setferr
.wdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; sh_dbf_putw - AX as a little-endian word into the staging buffer.
sh_dbf_putw:
    push ax
    call sh_stgputb                   ; low byte (AL)
    mov al, ah
    call sh_stgputb
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbf_cellstr - the cell at [sh_wcol],[sh_wrow] as text in sh_numbuf.
; A blank cell gives the empty string. Preserves everything.
; -----------------------------------------------------------------------------
sh_dbf_cellstr:
    push ax
    push bx
    push cx
    push si
    push di
    push es
    mov byte [sh_numbuf], 0
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_getcell2
    jnc .out
    cmp byte [sh_curtype], SH_T_TEXT
    je .text
    cmp byte [sh_curtype], SH_T_ERR
    je .err
    cmp byte [sh_curtype], SH_T_BOOL  ; a LOGICAL goes out as its name, in
    je .bool                          ; the character column its type made
    mov si, sh_acc                    ; (81.51)
    SHOUT fp_unpack_a
    mov di, sh_numbuf
    mov ax, 10
    SHOUT fp_ftoa
    jmp .out
.bool:
    mov ax, [sh_acc+6]
    SHOUT sh_boolname
    jmp .out
.err:
    SHOUT sh_errname                  ; -> sh_numbuf
    jmp .out
.text:
    mov si, [sh_curtoff]
    mov di, sh_numbuf
    mov cx, SH_NUMBUF_MAX             ; sh_numbuf's room, never the field's:
    mov es, [sh_txtseg]               ; past it are the claims' segment words
.tc:
    mov al, [es:si]
    or al, al
    jz .tend
    inc si
    mov [di], al
    inc di
    dec cx
    jnz .tc
.tend:
    mov byte [di], 0
.out:
    pop es
    pop di
    pop si
    pop cx
    pop bx
    pop ax
    ret

; sh_dbf_slen - AL = strlen(sh_numbuf), capped at 254. Preserves the rest.
sh_dbf_slen:
    push si
    xor al, al
    mov si, sh_numbuf
.l:
    cmp byte [si], 0
    je .out
    cmp al, 254
    jae .out
    inc al
    inc si
    jmp .l
.out:
    pop si
    ret

; -----------------------------------------------------------------------------
; sh_dbf_measure - sh_numbuf holds a rendered number; fold its shape into the
; column's running maxima. A dBASE N field has ONE width and ONE decimal count
; for the whole column, so they have to be the widest any row needs.
; -----------------------------------------------------------------------------
sh_dbf_measure:
    push ax
    push cx
    push si
    mov si, sh_numbuf
    cmp byte [si], '-'
    jne .nosign
    mov byte [sh_dbf_neg], 1
    inc si
.nosign:
    xor cl, cl                        ; integer digits
.ic:
    mov al, [si]
    or al, al
    jz .fin
    cmp al, '.'
    je .dot
    inc si
    inc cl
    jmp .ic
.dot:
    inc si
    xor ch, ch                        ; decimals
.dc:
    mov al, [si]
    or al, al
    jz .fin2
    inc si
    inc ch
    jmp .dc
.fin2:
    cmp ch, [sh_dbf_md]
    jbe .fin
    mov [sh_dbf_md], ch
.fin:
    or cl, cl
    jnz .icok
    mov cl, 1                         ; ".5" still needs one integer place
.icok:
    cmp cl, [sh_dbf_mi]
    jbe .out
    mov [sh_dbf_mi], cl
.out:
    pop si
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbf_putfield - sh_numbuf into the buffer, padded to the current field's
; width. N is RIGHT-justified and C LEFT-justified, which is dBASE's own rule
; and what makes a numeric column line up in every reader.
; -----------------------------------------------------------------------------
sh_dbf_putfield:
    push ax
    push bx
    push cx
    push dx
    push si
    mov bx, [sh_wcol]
    mov dl, [bx+sh_dbf_w]             ; DL = the field width
    call sh_dbf_slen                  ; AL = the text's length
    cmp al, dl
    jbe .fits
    mov al, dl                        ; too long: keep the left of it
.fits:
    mov dh, dl
    sub dh, al                        ; DH = pad count
    mov bx, [sh_wcol]
    cmp byte [bx+sh_dbf_ty], 'N'
    jne .left
    mov cl, dh                        ; right-justify: pad first
    or cl, cl
    jz .body
.rp:
    push ax
    mov al, ' '
    call sh_stgputb
    pop ax
    dec cl
    jnz .rp
    jmp .body
.left:
    xor cl, cl
.body:
    mov cl, al
    mov si, sh_numbuf
    or cl, cl
    jz .tail
.bc:
    mov al, [si]
    inc si
    call sh_stgputb
    dec cl
    jnz .bc
.tail:
    mov bx, [sh_wcol]
    cmp byte [bx+sh_dbf_ty], 'N'
    je .done                          ; the padding already went out in front
    mov cl, dh
    or cl, cl
    jz .done
.lp:
    mov al, ' '
    call sh_stgputb
    dec cl
    jnz .lp
.done:
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbf_name - row 0 of the current column as a field name in sh_numbuf:
; uppercased and cut to 10, with the column's own letter when the header cell
; is blank, because dBASE has no nameless field.
; -----------------------------------------------------------------------------
sh_dbf_name:
    push ax
    push si
    push word [sh_wrow]
    mov word [sh_wrow], 0
    call sh_dbf_cellstr
    pop word [sh_wrow]
    cmp byte [sh_numbuf], 0
    jne .up
    mov ax, [sh_wcol]                 ; blank header: use the column letter
    mov si, sh_numbuf
    SHOUT sh_colname
.up:
    mov si, sh_numbuf
    xor ax, ax
.uc:
    mov al, [si]
    or al, al
    jz .out
    cmp al, 'a'
    jb .keep
    cmp al, 'z'
    ja .keep
    sub al, 32
    mov [si], al
.keep:
    inc si
    mov ax, si
    sub ax, sh_numbuf
    cmp ax, 10
    jb .uc
    mov byte [si], 0                  ; 10 characters is dBASE III's limit
.out:
    pop si
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbf_scan - decide every field's type, width and decimal count, and the
; record length, before a byte of header goes out. TWO PASSES ARE UNAVOIDABLE:
; the header states the record length and each field's width, and a dBASE
; field is fixed-width for the whole file, so the widest row has to be known
; first.
; -----------------------------------------------------------------------------
sh_dbf_scan:
    push ax
    push bx
    push cx
    mov ax, [sh_bbcol]
    inc ax
    cmp ax, SH_DBF_MAXF
    jbe .nfok
    mov ax, SH_DBF_MAXF               ; dBASE III's ceiling: the rest of the
    mov byte [sh_trunc], 1            ; sheet is dropped and SAID to be
.nfok:
    mov [sh_dbf_nf], ax
    mov ax, [sh_bbrow]                ; rows 1..bbrow are the records
    mov [sh_dbf_nr], ax
    mov word [sh_dbf_rl], 1           ; the deletion-flag byte
    mov word [sh_wcol], 0
.cl:
    mov ax, [sh_wcol]
    cmp ax, [sh_dbf_nf]
    jae .done
    mov byte [sh_dbf_mi], 1
    mov byte [sh_dbf_md], 0
    mov byte [sh_dbf_neg], 0
    mov byte [sh_dbf_clen], 1
    mov byte [sh_dbf_isnum], 1
    mov word [sh_wrow], 1
.rl:
    mov ax, [sh_wrow]
    cmp ax, [sh_bbrow]
    ja .colend
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_getcell2
    jnc .rnx
    cmp byte [sh_curtype], SH_T_NUM
    je .isnum
    mov byte [sh_dbf_isnum], 0
    call sh_dbf_cellstr
    call sh_dbf_slen
    cmp al, [sh_dbf_clen]
    jbe .rnx
    mov [sh_dbf_clen], al
    jmp .rnx
.isnum:
    call sh_dbf_cellstr
    call sh_dbf_measure
.rnx:
    inc word [sh_wrow]
    jmp .rl
.colend:
    mov bx, [sh_wcol]
    cmp byte [sh_dbf_isnum], 0
    je .asc
    mov byte [bx+sh_dbf_ty], 'N'
    mov al, [sh_dbf_mi]
    mov ah, [sh_dbf_md]
    or ah, ah
    jz .nodot
    inc al
    add al, ah
.nodot:
    cmp byte [sh_dbf_neg], 0
    je .noneg
    inc al
.noneg:
    cmp al, 19
    jbe .nw
    mov al, 19
.nw:
    mov [bx+sh_dbf_w], al
    mov al, [sh_dbf_md]
    mov [bx+sh_dbf_d], al
    jmp .acc
.asc:
    mov byte [bx+sh_dbf_ty], 'C'
    mov al, [sh_dbf_clen]
    mov [bx+sh_dbf_w], al
    mov byte [bx+sh_dbf_d], 0
.acc:
    mov bx, [sh_wcol]
    mov al, [bx+sh_dbf_w]
    xor ah, ah
    add [sh_dbf_rl], ax
    inc word [sh_wcol]
    jmp .cl
.done:
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_doread_dbf - read [sh_name] as dBASE III, replacing the sheet.
;
; A dBASE II file is REFUSED by its version byte rather than misread: its
; header is a different shape, and a wrong guess about a fixed-width format
; produces a sheet full of plausible rubbish instead of an error.
;
; The field names become ROW 0 and the records rows 1..n, which is the inverse
; of what the writer does and keeps a round trip through .DBF honest.
; -----------------------------------------------------------------------------
sh_doread_dbf:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov es, [sh_stgseg]
    xor bx, bx
    mov cx, SH_STAGE_MAX
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_READ
    jc .rerr
    mov [sh_sepend], ax
    cmp ax, SH_DBF_HDR + 1
    jb .badver
    mov es, [sh_stgseg]
    mov al, [es:0]
    cmp al, 0x03                      ; dBASE III without a memo file
    jne .badver
    mov ax, [es:4]
    mov [sh_dbf_nr], ax
    mov ax, [es:8]
    mov [sh_dbf_hl], ax
    mov ax, [es:10]
    mov [sh_dbf_rl], ax
    or ax, ax
    jz .badver
    mov ax, [sh_dbf_hl]
    cmp ax, SH_DBF_HDR + 1
    jb .badver
    sub ax, SH_DBF_HDR + 1
    mov cl, 5
    shr ax, cl                        ; / 32 = the field count
    or ax, ax
    jz .badver
    cmp ax, SH_DBF_MAXF
    jbe .nfok
    mov ax, SH_DBF_MAXF
.nfok:
    mov [sh_dbf_nf], ax
    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0
    mov word [sh_nbord], 0
    mov word [sh_ntbl], 0            ; 81.114.7: ...and its TABLES
    mov word [sh_nnote], 0
    SHOUT sh_colw_clear                ; ...and every column's width (81.56)
    mov word [sh_nnames], 0
    call sh_kindreset                  ; 81.97: a worksheet until a BOF says
    ; --- the descriptors: names into row 0, widths and types banked ---------
    mov word [sh_wcol], 0
    mov word [sh_wrow], 0
.dloop:
    mov ax, [sh_wcol]
    cmp ax, [sh_dbf_nf]
    jae .recs
    mov cl, 5
    shl ax, cl
    add ax, SH_DBF_HDR                ; -> this descriptor
    mov si, ax
    mov di, sh_rwsrc
    mov cx, 11
.dn:
    mov al, [es:si]
    or al, al
    jz .dnend
    cmp al, ' '
    je .dnend
    inc si
    mov [di], al
    inc di
    dec cx
    jnz .dn
.dnend:
    mov byte [di], 0
    mov ax, [sh_wcol]
    mov cl, 5
    shl ax, cl
    add ax, SH_DBF_HDR
    mov si, ax
    mov bx, [sh_wcol]
    mov al, [es:si+11]
    mov [bx+sh_dbf_ty], al            ; the type letter
    mov al, [es:si+16]
    mov [bx+sh_dbf_w], al             ; and the width
    mov ax, [sh_wcol]
    xor bx, bx                        ; row 0
    mov si, sh_rwsrc
    SHOUT sh_settext
    inc word [sh_wcol]
    jmp .dloop
    ; --- the records ---------------------------------------------------------
.recs:
    mov word [sh_wrow], 1
.rloop:
    mov ax, [sh_wrow]
    dec ax
    cmp ax, [sh_dbf_nr]
    jae .done
    cmp ax, SH_ROWS - 1
    jae .done
    mov dx, [sh_dbf_rl]
    mul dx                            ; DX:AX = (row-1) * reclen
    add ax, [sh_dbf_hl]
    mov si, ax                        ; SI -> this record
    cmp si, [sh_sepend]
    jae .done
    cmp byte [es:si], 0x2A            ; a DELETED record is skipped, which is
    je .rnext                         ; what the flag byte is for
    inc si
    mov word [sh_wcol], 0
.floop:
    mov ax, [sh_wcol]
    cmp ax, [sh_dbf_nf]
    jae .rnext
    call sh_dbf_getfield              ; SI advances by the field's width
    call sh_dbf_store
    inc word [sh_wcol]
    jmp .floop
.rnext:
    inc word [sh_wrow]
    jmp .rloop
.done:
    mov word [sh_msg], sh_m_loaded
    jmp .rdone
.badver:
    mov word [sh_msg], sh_s_dbf_bad
    jmp .rdone
.rerr:
    call sh_setferr
.rdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbf_getfield - the current field at ES:SI into sh_rwsrc, trimmed of the
; padding on BOTH sides (N is right-justified and C left-justified, so a
; reader that trimmed one end would be right for exactly half the fields).
; SI advances by the field's width. Preserves everything else.
; -----------------------------------------------------------------------------
sh_dbf_getfield:
    push ax
    push bx
    push cx
    push di
    mov bx, [sh_wcol]
    mov cl, [bx+sh_dbf_w]
    xor ch, ch
    mov di, sh_rwsrc
    jcxz .term
    push si
.lead:
    cmp byte [es:si], ' '             ; skip the leading padding
    jne .copy
    inc si
    dec cx
    jnz .lead
.copy:
    jcxz .trail
    cmp di, sh_rwsrc + SH_EDITMAX     ; the file says the width, up to 255;
    jae .trail                        ; sh_rwsrc holds 63 and the NUL, and SI
    mov al, [es:si]                   ; is re-derived from the width below
    inc si
    mov [di], al
    inc di
    dec cx
    jnz .copy
.trail:
    mov byte [di], 0
.tr:
    cmp di, sh_rwsrc                  ; and the trailing padding
    jbe .term2
    dec di
    cmp byte [di], ' '
    jne .term3
    mov byte [di], 0
    jmp .tr
.term3:
    inc di
.term2:
    mov byte [di], 0
    pop si
    mov bx, [sh_wcol]
    mov cl, [bx+sh_dbf_w]
    xor ch, ch
    add si, cx                        ; SI -> the next field, always
    jmp .out
.term:
    mov byte [di], 0
.out:
    pop di
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_dbf_store - sh_rwsrc into the cell, HONOURING THE DECLARED TYPE. A C
; field holding "007" is TEXT because dBASE said it is character data, and
; guessing from the spelling instead would silently turn a part number into
; the number 7.
; -----------------------------------------------------------------------------
sh_dbf_store:
    push ax
    push bx
    push dx
    push si
    cmp byte [sh_rwsrc], 0
    je .out
    mov bx, [sh_wcol]
    mov al, [bx+sh_dbf_ty]
    cmp al, 'N'
    je .num
    cmp al, 'F'                       ; dBASE IV's float, same shape
    je .num
    cmp al, 'L'                       ; LOGICAL: T or Y, F or N, in either
    je .logical                       ; case, and '?' for not yet known,
                                      ; which is a blank (81.51)
.text:
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    mov si, sh_rwsrc
    SHOUT sh_settext
    jmp .out
.num:
    mov si, sh_rwsrc
    SHOUT fp_atof
    jc .text                          ; a malformed N field is kept as text
    SHOUT sh_acc_store
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_setvald
    jmp short .out
.logical:
    mov al, [sh_rwsrc]
    and al, 0xDF
    mov dl, 1
    cmp al, 'T'
    je .lset
    cmp al, 'Y'
    je .lset
    dec dl
    cmp al, 'F'
    je .lset
    cmp al, 'N'
    jne .out
.lset:
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_setbool
.out:
    pop si
    pop dx
    pop bx
    pop ax
    ret

section .text

section SH_MODSEC
sh_dowrite_csv:
    mov byte [sh_sepch], ','
    jmp sh_dowrite_sep
sh_dowrite_txt:
    mov byte [sh_sepch], 9
    jmp sh_dowrite_sep

sh_dowrite_sep:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    call shm_difbbox                  ; the module's own copy (82.16.9)
    mov byte [sh_trunc], 0
    mov es, [sh_stgseg]
    xor di, di
    mov word [sh_wrow], 0
.rloop:
    mov ax, [sh_wrow]
    cmp ax, [sh_bbrow]
    ja .footer
    mov word [sh_wcol], 0
.cloop:
    mov ax, [sh_wcol]
    cmp ax, [sh_bbcol]
    ja .rnext
    mov ax, di
    add ax, SH_EDITMAX + 8            ; the widest a field can get: a label,
    cmp ax, SH_STAGE_MAX              ; its quotes, and the delimiter
    ja .truncf
    cmp word [sh_wcol], 0
    je .nosep
    mov al, [sh_sepch]
    call sh_stgputb
.nosep:
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_getcell2
    jnc .cnext                        ; an empty cell is an EMPTY FIELD, not a
    cmp byte [sh_curtype], SH_T_TEXT  ; zero - the delimiters still count it
    je .ctext
    cmp byte [sh_curtype], SH_T_ERR
    je .cerr
    cmp byte [sh_curtype], SH_T_BOOL  ; a LOGICAL goes out as its name, which
    je .cbool                         ; is how it reads back in, too (81.51)
    push si
    push di
    mov si, sh_acc                    ; a FULL DECIMAL, the lesson
    SHOUT fp_unpack_a                 ; sh_dowrite_dif learned the hard way
    mov di, sh_numbuf
    mov ax, 10
    SHOUT fp_ftoa
    pop di
    pop si
    mov si, sh_numbuf
    call sh_stgput
    jmp .cnext
.cbool:
    mov ax, [sh_acc+6]
    SHOUT sh_boolname
    jmp short .cname
.cerr:
    SHOUT sh_errname                  ; -> sh_numbuf, the error's own spelling
.cname:
    mov si, sh_numbuf
    call sh_stgput
    jmp .cnext
.ctext:
    call sh_sep_needq
    jnc .ctplain
    mov al, 34
    call sh_stgputb
    mov si, [sh_curtoff]
.ctq:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    or al, al
    jz .ctqend
    inc si
    cmp al, 34
    jne .ctq1
    call sh_stgputb                   ; an embedded quote is DOUBLED
.ctq1:
    call sh_stgputb
    jmp .ctq
.ctqend:
    mov al, 34
    call sh_stgputb
    jmp .cnext
.ctplain:
    mov si, [sh_curtoff]
.ctp:
    push es
    mov es, [sh_txtseg]
    mov al, [es:si]
    pop es
    or al, al
    jz .cnext
    inc si
    call sh_stgputb
    jmp .ctp
.cnext:
    inc word [sh_wcol]
    jmp .cloop
.rnext:
    mov si, sh_s_crlf
    call sh_stgput
    inc word [sh_wrow]
    jmp .rloop
.truncf:
    mov byte [sh_trunc], 1
.footer:
    mov [sh_stagelen], di
    mov ax, [sh_stgseg]
    mov es, ax
    xor bx, bx
    mov cx, [sh_stagelen]
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_WRITE
    jc .werr
    mov word [sh_msg], sh_m_saved
    cmp byte [sh_trunc], 0
    je .wdone
    mov word [sh_msg], sh_m_trunc
    jmp .wdone
.werr:
    call sh_setferr                   ; module-local: 82.16.9 absorbed it
.wdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sep_needq - does the current cell's label need quoting? out: CF=1 if so.
; Preserves everything else.
; -----------------------------------------------------------------------------
sh_sep_needq:
    push ax
    push si
    push es
    mov si, [sh_curtoff]
    mov es, [sh_txtseg]
.l:
    mov al, [es:si]
    or al, al
    jz .no
    inc si
    cmp al, [sh_sepch]                ; [sh_sepch] is DS-relative and DS is
    je .yes                           ; still the package - only ES moved
    cmp al, 34
    je .yes
    cmp al, 13
    je .yes
    cmp al, 10
    je .yes
    jmp .l
.yes:
    pop es
    pop si
    pop ax
    stc
    ret
.no:
    pop es
    pop si
    pop ax
    clc
    ret

; -----------------------------------------------------------------------------
; sh_doread_csv / _txt - read [sh_name], replacing the sheet.
; -----------------------------------------------------------------------------
sh_doread_csv:
    mov byte [sh_sepch], ','
    jmp sh_doread_sep
sh_doread_txt:
    mov byte [sh_sepch], 9
    jmp sh_doread_sep

sh_doread_sep:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push es
    mov es, [sh_stgseg]
    xor bx, bx
    mov cx, SH_STAGE_MAX
    xor dx, dx
    mov si, sh_name
    call OSAPI_FILE_READ
    jc .rerr
    mov word [sh_ncells], 0
    mov word [sh_txtlen], 0           ; "replacing the sheet", the same three
    mov word [sh_nbord], 0            ; sh_doread_dif clears
    mov word [sh_ntbl], 0            ; 81.114.7: ...and its TABLES
    mov word [sh_nnote], 0
    SHOUT sh_colw_clear                ; ...and every column's width (81.56)
    mov word [sh_nnames], 0
    call sh_kindreset                  ; 81.97: a worksheet until a BOF says
    mov es, [sh_stgseg]
    mov [sh_sepend], ax               ; the end, for sh_sep_field
    xor si, si
    mov word [sh_wrow], 0
.rowloop:
    cmp si, [sh_sepend]
    jae .done
    cmp word [sh_wrow], SH_ROWS
    jae .done
    mov word [sh_wcol], 0
.fieldloop:
    call sh_sep_field                 ; -> sh_rwsrc; SI at the terminator
    call sh_sep_store
    inc word [sh_wcol]
    cmp si, [sh_sepend]
    jae .done
    mov al, [es:si]
    cmp al, [sh_sepch]
    jne .eol
    inc si                            ; past the delimiter
    mov ax, [sh_wcol]
    cmp ax, SH_COLS
    jae .eol                          ; past the last column: drop the rest
    jmp .fieldloop
.eol:
    cmp si, [sh_sepend]
    jae .done
    mov al, [es:si]
    cmp al, 13
    je .eat
    cmp al, 10
    je .eat
    inc si                            ; anything else past the last column
    jmp .eol
.eat:
    inc si
    cmp si, [sh_sepend]
    jae .done
    mov al, [es:si]
    cmp al, 13
    je .eat
    cmp al, 10
    je .eat
    inc word [sh_wrow]
    jmp .rowloop
.done:
    mov word [sh_msg], sh_m_loaded
    jmp .rdone
.rerr:
    call sh_setferr                   ; module-local: 82.16.9 absorbed it
.rdone:
    pop es
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sep_field - one field at ES:SI into sh_rwsrc, NUL-terminated. SI is left
; AT the terminator (the delimiter, a CR/LF or [sh_sepend]) and never past it,
; so the caller decides what the terminator means.
; -----------------------------------------------------------------------------
sh_sep_field:
    push ax
    push cx
    push di
    mov di, sh_rwsrc
    mov cx, SH_EDITMAX
    cmp si, [sh_sepend]
    jae .end
    cmp byte [es:si], 34
    jne .plain
    inc si
.q:
    cmp si, [sh_sepend]
    jae .end
    mov al, [es:si]
    inc si
    cmp al, 34
    jne .qkeep
    cmp si, [sh_sepend]
    jae .end
    cmp byte [es:si], 34
    jne .end                          ; a lone quote CLOSES the field
    inc si                            ; a doubled one is a literal quote
.qkeep:
    jcxz .q
    mov [di], al
    inc di
    dec cx
    jmp .q
.plain:
    cmp si, [sh_sepend]
    jae .end
    mov al, [es:si]
    cmp al, [sh_sepch]
    je .end
    cmp al, 13
    je .end
    cmp al, 10
    je .end
    inc si
    jcxz .plain
    mov [di], al
    inc di
    dec cx
    jmp .plain
.end:
    mov byte [di], 0
    pop di
    pop cx
    pop ax
    ret

; -----------------------------------------------------------------------------
; sh_sep_store - sh_rwsrc into the cell at [sh_wcol],[sh_wrow].
;
; CSV HAS NO TYPE FIELD, so the field's own spelling decides. fp_atof reports
; CF=1 when there was no number there at all, and SI is left where it stopped -
; so "12abc" is TEXT rather than 12, which is the whole reason the position is
; checked and not just the carry.
; -----------------------------------------------------------------------------
sh_sep_store:
    push ax
    push bx
    push si
    cmp byte [sh_rwsrc], 0
    je .out                           ; an empty field leaves the cell blank
    mov si, sh_rwsrc
    SHOUT fp_atof
    jc .text
    cmp byte [si], 0
    jne .text
    SHOUT sh_acc_store
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    SHOUT sh_setvald
    jmp .out
.text:
    mov ax, [sh_wcol]
    mov bx, [sh_wrow]
    mov si, sh_rwsrc
    SHOUT sh_setlabel                 ; a TRUE field is the logical, as Excel
.out:                                 ; reads one (81.51)
    pop si
    pop bx
    pop ax
    ret

section .text

sh_s_ext_sylk: db '.SLK', 0
sh_s_ext_dif:  db '.DIF', 0
sh_s_ext_biff: db '.BIF', 0
sh_s_ext_csv:  db '.CSV', 0
sh_s_ext_txt:  db '.TXT', 0
sh_s_ext_dbf:  db '.DBF', 0
sh_s_ext_xls:  db '.XLS', 0          ; Excel's own name for a worksheet (81.52)
sh_s_dbf_bad:  db 'Not a dBASE III file.', 0
sh_s_biff_fontname: db 'Helv', 0     ; Excel's own historical default face
; our number-format code (General/Currency/Comma/Percent) -> the real BIFF
; built-in format id, per the OpenOffice BIFF reference: 0=General,
; 5="$"#,##0 (currency, 0dp), 3=#,##0 (comma, 0dp), 9=0% (percent, 0dp) -
; the 0-decimal-place forms, which is what this app's own formatter draws
sh_biff_numfmt_tab: db 0x00, 0x05, 0x03, 0x09
sh_s_dif_hdr1: db 'TABLE', 13, 10, '0,1', 13, 10, '""', 13, 10, 'VECTORS', 13, 10, '0,', 0
sh_s_dif_hdr2: db 13, 10, '""', 13, 10, 'TUPLES', 13, 10, '0,', 0
sh_s_dif_hdr3: db 13, 10, '""', 13, 10, 'DATA', 13, 10, '0,0', 13, 10, '""', 13, 10, 0
sh_s_dif_bot:  db '-1,0', 13, 10, 'BOT', 13, 10, 0
sh_s_dif_zc:   db '0,', 0
sh_s_dif_1c:   db '1,0', 13, 10, 0        ; stage 4.5: a STRING data item
sh_s_dif_v:    db 'V', 13, 10, 0           ; the real DIF value-indicator
                                            ; for "this numeric data is
                                            ; valid" - NOT a comment string;
                                            ; a type-0 (numeric) data item
                                            ; has no third line at all
sh_s_dif_err0: db '0,0', 13, 10, 'ERROR', 13, 10, 0 ; the ERROR indicator, on
                                                    ; a numeric item, which is
                                                    ; DIF's whole vocabulary
                                                    ; for one
sh_s_dif_na0:  db '0,0', 13, 10, 'NA', 13, 10, 0  ; a numeric item (type 0)
                                            ; whose indicator is NA - NOT
                                            ; type 1 (that's DIF's STRING
                                            ; type, whose second line must
                                            ; be a quoted string, not a
                                            ; bare keyword)
sh_s_dif_eod:  db '-1,0', 13, 10, 'EOD', 13, 10, 0

; Stage 2.0's ALERT() needs a real message box; SPEC.md 75.3's os88ui_ask is
; the project's own answer to that (a kernel-resident version was tried and
; measured too costly for every app to pay for - see SPEC.md 75.3).
; Included here, above OS88_BSS, because the
; sh_macro_msg bss field below sizes itself from OS88UI_AMAX, which this
; needs to have already defined.
%define OS88UI_ALERT
%define OS88UI_AEXTRA                ; Step/Halt/Continue and OK/Cancel (81.86)
%define OS88UI_SCROLL               ; stage 3.0a+: SPEC.md 13.10's shared
                                     ; scroll bar - OPT IN, and without it
                                     ; os88ui_sbar is simply not assembled
%define OS88UI_WHEEL                ; ...and its wheel arithmetic (13.10.8):
                                     ; the grid and the Paste list both scroll
                                     ; on it
%define OS88UI_SBDRAG               ; ...and the thumb-drag half of it
                                     ; shared scroll bar (SPEC.md 13.10.5),
                                     ; which needs W_ONCLICK/W_ONDRAG/
                                     ; W_ONMOUSEUP - Sheet already has the
                                     ; first two for range selection
%define OS88UI_ABOUT                ; ...and the standard About card (20.5.1),
%include "os88ui.inc"                ; which replaced a one-line alert here

; stage 3.0b: the one-line text field, the shared control browser.asm and
; telnet.asm already use. It gives the formula bar's content box a real caret
; and mid-string editing, replacing the append-only in-cell editor this app
; had before. MUST come after os88ui.inc (it uses its UI_* macros) and before
; OS88_BSS, which is os88ui.inc's own placement rule for the same reason.
%include "os88line.inc"

; stage 3.0b: its multi-line sibling, new in this stage and written to the same
; conventions (caller owns the block, passed in SI; no storage of its own).
; First consumer: Formula > Note..., which is Excel 2.1's cell notes and the
; first place in this app where free text can be typed at all.
section SH_MODSEC                      ; 81.102: CHART.OVL, with its only
%include "os88text.inc"                ; consumer, the Note dialog
section .text

; stage 2.x: Data > Chart Column.../Export Chart as BMP...'s shared
; rasterizer + BMP writer - see that file's own header comment for the
; CH_* constants and ch_* bss words it requires, both declared above
; stage 4.0: the software IEEE-754 double. Included before os88chart.inc for
; no reason other than tidiness - it depends on nothing but the caller's own
; scratch, declared in the bss chain below.
%include "os88fp.inc"

; apps/os88dec.inc RESIDENT, and that is a REQUIREMENT rather than a tidy-up.
; os88chart.inc includes it when nobody else has, and under CH_OVERLAY that
; puts dec_s16 in `.modc` while sh_itoa - which has TWELVE resident callers -
; calls it near. os88ovlchk names it exactly: `.text -> .modc, near: dec_s16`,
; and it is the one thing the 2026-10-14 upstream merge broke that no conflict
; marker showed, sheet.asm having merged clean. Claiming it HERE puts it in
; .text; os88chart.inc's own `%ifdef OS88DEC_INC` guard then skips its copy,
; and the module reaches it through CHFP's vector like every other resident
; routine it needs. DEC_S16 brings DEC_U16 with it (os88dec.inc's header).
%define DEC_S16
%include "os88dec.inc"

%define CH_MODC_EXT sh_modc_ext     ; 82.16.8's hook, before ch_modc is emitted
CH_OVSTAMP equ sh_modc_stamp - sh_modc0  ; ...and the build stamp ch_ovneed
CH_OVLEN   equ sh_modc_end               ; checks: where it is, and the length
%include "os88chartovl.inc"   ; the resident half of the shared
                              ; chart module: loader, shims, verbs (82.16)

%if SHM_READ != CHM_MAX + 1
  %error "SHEET's module verbs must start one past CHM_MAX - see 82.16.8"
%endif

%include "os88chart.inc"
section SH_MODSEC                      ; CHART.OVL's last byte + 1, shm_m2end's
sh_modc_end:                           ; twin: os88chart.inc is the last .modc
section .text                          ; fragment, so nothing lands after this

